INSERT INTO `ds_about_me` VALUES (1, '<p><b><span style=\"font-size: 24px;\">此处已预留空间便于后期填写展示</span></b><span style=\"font-size: 24px;\">﻿</span></p>', 'XXXX', 'XXXX');
INSERT INTO `ds_article` VALUES (187, '报纸', '站在高地瞭望', '康子湛; 朱柏妍; 洪大鹏', '解放军报', '解放军报', '国防大学;未来战争;兵棋系统;百望山;世界一流;', '百望山上，极目远眺，天高地阔。 隆冬时节，记者来到国防大学采访。一位教授讲述了一个故事：90多年前，毛泽东同志在井冈山创办红军教导队，植下了国防大学的根。井冈山上，毛泽东指着苍茫大地，问红军战士：站在黄洋界上能看多远？大家说：能看到江西和湖南。毛泽东挥手指', '2024-01-10 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2024.000052', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (188, '报纸', '神山“星火”正燎原', '王慧敏; 邢宇皓; 王斯敏; 胡晓军; 卢泽华', '光明日报', '光明日报', '农家乐;村干部;村两委;', '编者按 江西井冈山茅坪镇神山村，是一个有着光荣革命历史和鲜明时代印记的小山村。它，平凡又不平凡! 一年前，我们曾在该村蹲点调研，聆听了许许多多当年红军将士与父老乡亲之间血肉情深的感人故事，也目睹了新时代那山那水的华彩蝶变。感动，让我们捧出了那篇长篇报道《神', '2023-11-30 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.005643', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (190, '报纸', '赓续红色血脉 绽放时代光彩', '高阳', '中国组织人事报', '中国组织人事报', '井冈山精神;公务员;人民满意;主任科员;国家通用语言文字;螺蛳粉;黄洋界保卫战;', '青山碧水井冈秀，苍雾翠竹英雄魂。这里是中国革命的摇篮。 6月26日至7月10日，中央组织部以“弘扬伟大建党精神，传承党的优良传统，发挥示范带头作用”为主题，在中国井冈山干部学院举办两期全国“人民满意的公务员”培训班。来自13个中央单位、31个省（区、市）和新疆生产', '2023-07-13 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2023.001741', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (191, '报纸', '红色血脉薪火相传 千锤百炼锻造政工铁军', '赵婕', '法治日报', '法治日报', '政治部主任;司法部;司法行政工作;井冈山革命烈士陵园;司法厅;朱毛红军;红色基因;中国式现代化;习近平;薪火相传;', '井冈山，层峦叠嶂，山路蜿蜒，苍松翠竹，郁郁葱葱。 井冈山，中国革命的摇篮，在中国共产党的领导下，这里创建了中国第一个农村革命根据地，锻造出一支具有坚定理想信仰的钢铁队伍，点燃了中国革命的星星之火。 近日，司法部在位于井冈山的江西干部学院举办全国司法厅（局', '2023-06-05 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2023.002911', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (193, '报纸', '蓬勃江西，彩云长在有新天', '胡佳佳; 张慧斌; 李健; 邓逸楠', '人民法院报', '人民法院报', '南昌市;习近平总书记;人民法院;劳动争议;生态旅游;', '江西是中国革命的摇篮、人民共和国的摇篮、人民军队的摇篮和中国工人运动的策源地，孕育了伟大的井冈山精神、苏区精神和长征精神。在这片充满红色记忆的红土地，一山一水都留下了革命先烈的战斗足迹，一草一木都记载着可歌可泣的革命故事。党的十八大以来，习近平总书记两次', '2022-09-18 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2022.003380', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (194, '报纸', '在井冈山重温斗争历史汲取奋进力量', '韩萍; 徐鹏', '法治日报', '法治日报', '井冈山精神;政法机关;党的政治建设;斗争历史;政法委;', '八月的井冈山，满眼苍翠，到处焕发着勃勃生机。8月1日至14日，青海省委组织部、省委政法委在中国井冈山干部学院联合举办全省政法领导干部加强政治建设专题轮训班。政治轮训分两期进行，省直政法单位部分厅级干部，各市州委政法委书记、政法委常务副书记及政法各单位主要负责', '2022-09-13 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2022.005308', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (195, '报纸', '把感动传递给更多人', '周欢', '人民日报', '人民日报', '井冈山革命博物馆;革命文物;讲解员;余贲民;陈毅安;八角楼;铁皮箱;', '2021年3月25日，习近平总书记对革命文物工作作出重要指示强调：“革命文物承载党和人民英勇奋斗的光荣历史，记载中国革命的伟大历程和感人事迹，是党和国家的宝贵财富，是弘扬革命传统和革命文化、加强社会主义精神文明建设、激发爱国热情、振奋民族精神的生动教材。” 井冈', '2022-08-10 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.008634', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (196, '报纸', '感悟红色精神 砥砺初心使命', '张博', '中国新闻出版广电报', '中国新闻出版广电报', '井冈山精神;井冈山革命博物馆;共产党人;江西日报;红色精神;短视频;《解放军报》;井冈山革命根据地;', '历史是理解未来的钥匙。百年来，中国共产党带领中国人民走出一条从站起来到富起来，再到强起来的康庄大道，实现了从“赶上时代”到“引领时代”的伟大跨越。在百年奋斗历程中，中国共产党团结带领人民取得一个又一个胜利，以井冈山精神等为代表的革命精神发挥了重要作用。$$', '2022-01-19 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.000188', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (197, '报纸', '毛泽东诗词中的群众语言', '汪建新', '学习时报', '学习时报', '毛泽东诗词;古典诗词;武昌鱼;旧体诗词;群众语言;', '毛泽东历来重视向人民群众学习语言，向现实生活学习语言。1940年1月9日，在陕甘宁边区文化协会第一次代表大会上的讲演，即《新民主主义论》中，毛泽东指出：“一切进步的文化工作者，在抗日战争中，应有自己的文化军队，这个军队就是人民大众。革命的文化人而不接近民众，就', '2021-12-10 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002335', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (198, '报纸', '井冈山精神——跨越时空，照亮前行之路', '', '中国民族报', '中国民族报', '井冈山精神;井冈山革命根据地;', '井冈山，中国革命的摇篮。$$ 中国共产党人在创建和发展井冈山革命根据地的过程中，形成了坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利的井冈山精神。$$ 2016年春节前夕，习近平总书记来到江西，看望慰问广大干部群众和驻赣部队，首站就是井冈山。习近平总', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001151', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (199, '报纸', '用理想之光照亮奋斗之路', '江琳; 徐元锋; 孙超', '人民日报', '人民日报', '理想之光;井冈山;干部学院;党总支书记;党性教育;', '习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话中强调：“我们要用历史映照现实、远观未来，从中国共产党的百年奋斗中看清楚过去我们为什么能够成功、弄明白未来我们怎样才能继续成功，从而在新的征程上更加坚定、更加自觉地牢记初心使命、开创美好未来。”$$ 百', '2021-11-02 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011540', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (200, '报纸', '“红”出新体验 “红”出新动能', '范帆', '经济参考报', '经济参考报', '红色旅游;红色文化;红色景区;红博会;红色资源;新体验;', '2021中国红色旅游博览会10月27日-29日在革命摇篮井冈山举行，上百家文创演艺和旅游商品企业参展，共商红色旅游未来发展。$$ 记者在本届红博会上发现，国内各大红色景点不断创新红色文化呈现形式，推出红色旅游新业态，让游客有了更丰富的红色体验，既推动了红色基因传承，也', '2021-11-01 08:00:00', 'https://link.cnki.net/doi/10.28419/n.cnki.njjck.2021.005981', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (201, '报纸', '重走红色之路 探寻生态之美', '范朝慧', '中国旅游报', '中国旅游报', '井冈山革命博物馆;毛泽东;旅游点;红色旅游;研学旅行;红色摇篮;精品线路;八角楼;红色文化;黄洋界哨口;黄洋界保卫战;实景演出;讲解员;', '“久有凌云志，重上井冈山。”近日，文化和旅游部资源开发司组织多家媒体及OTA代表，组成“建党百年红色旅游百条精品线路”采风团，走进江西井冈山，沿着“井冈之路·星火燎原”精品线路，走进茅坪八角楼毛泽东故居、井冈山革命博物馆、黄洋界哨口等红色景区景点，重温红色记', '2021-10-20 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002982', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (203, '报纸', '一堂授课，一次红色洗礼', '沙子钺; 陈利', '解放军报', '解放军报', '太爷爷;雷打石;黄洋界;井冈山;', '“‘红军荟萃井冈山，主力形成在此间’。在这里，‘朱毛’携手创建中国第一块农村革命根据地，开启了中国革命的新篇章……”仲夏时节，武警江苏总队某部党史学习教育课堂上，7名井冈山籍新战士登台讲述家乡革命故事。三湾改编、黄洋界保卫战……老区传人生动讲述红色故事，带', '2021-07-26 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004745', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (204, '报纸', '井冈山下的法治“播火者”', '郑海啸; 杨璐嘉; 胡文星', '检察日报', '检察日报', '井冈山市;检察院;检察建议;公益诉讼;播火者;', '一道光，划破苍穹；一座山，辉映历史；一种精神，照耀未来。$$ 90多年前，毛泽东率领秋收起义部队来到井冈山，创立了中国共产党领导的第一个农村革命根据地——井冈山革命根据地。而后，这簇星星之火熊熊燃烧，指引着中国革命一步步走向胜利。$$ 又是一年映山红开，记者怀', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.003638', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (205, '报纸', '精神伟力跨越时空', '胡晓军; 李慧', '光明日报', '光明日报', '井冈山革命根据地;毛泽东;中华民族;群众史观;习近平总书记;中国共产党领导;马克思主义中国化;共产党人;马克思主义基本原理;中国革命道路;中国特色社会主义道路;', '位于湘赣边界罗霄山脉中段的井冈山，并不算太高，却屹立起一座中国革命史上令人景仰的丰碑。$$ 1927年10月至1930年2月，当年在此进行的革命斗争历时并不太长，却开辟出一条马克思主义基本原理同中国具体实际相结合的光辉道路。$$ 1927年10月27日，毛泽东同志率领工农革命军', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003705', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (207, '报纸', '井冈山精神：星星之火从此燎原', '张弛', '中国纪检监察报', '中国纪检监察报', '井冈山精神;红军战士;', '盛夏时节，黄洋界山头云雾弥漫。举目四望，群山起伏，层峦叠嶂。这里，就是位于湘赣边界罗霄山脉中段的井冈山。$$ 在这片红色的土地上，中国共产党人建立了第一个农村革命根据地，开辟了“农村包围城市、武装夺取政权”的革命道路，回答了“中国的红色政权为什么能够存在”', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003508', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (208, '报纸', '这道光，照亮前行之路', '赖星', '新华社;', '新华每日电讯', '井冈山精神;共产党人;秋收起义;习近平总书记;红四军;井冈山市;毛泽东;', '90多年前，井冈山茅坪八角楼。一根灯芯的微光，穿透漫漫长夜。$$ 油灯下，毛泽东同志写下《中国的红色政权为什么能够存在？》《井冈山的斗争》两篇光辉著作，成为马克思主义中国化的伟大开篇，闪耀着“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”的井冈', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005584', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (210, '报纸', '江西井冈山 “让红色火种生生不息”', '张琪彬', '中国纪检监察报', '中国纪检监察报', '井冈山;市纪委;', '盛夏时节，巍巍井冈满山翠绿。崇山峻岭间，双车道盘山公路蜿蜒伸展，火炬造型的路灯点缀两侧，串联起100多个革命旧址遗迹。7月1日，万余名党员干部、群众自发前往革命圣地，重温那段波澜壮阔、激荡人心的历史，共同庆祝中国共产党成立100周年。$$ 革命烈士陵园巍然耸立于井', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003172', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (211, '报纸', '用好用活红色资源', '孟祥夫', '人民日报', '人民日报', '红色资源;红色文化;井冈山市;红色旅游;', '红色资源的珍贵价值，不仅在于它的历史光辉，更在于它在当下依然能带给我们思考和精神滋养$$ 房顶铺着红瓦，墙上写着革命标语，红彤彤的大灯笼悬挂在门口，火炬状的路灯沿道路伸展，不时遇见身穿红军装束的体验者……走进江西省井冈山市葛田乡古田村，扑面而来的是浓浓的红', '2021-06-09 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006040', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (212, '报纸', '弘扬井冈山精神 传承红色基因', '金荣花', '中国气象局预报与网络司;', '中国气象报', '弘扬井冈山精神;红色基因;习近平总书记;', '2020年9月，组织安排我来到中国井冈山干部学院，接受政治思想教育和党性修养专题培训。井冈山是中国红色革命圣地，是以毛泽东、朱德等为代表的中国共产党人在大革命失败后，在全党积极探索中国革命道路过程中，以实事求是、敢于探索、勇于创新的革命气魄，领导创建的中国第一', '2021-02-25 08:00:00', 'https://link.cnki.net/doi/10.28122/n.cnki.ncqxb.2021.000235', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (213, '报纸', '走在红军挑粮小道上', '戴林峰', '人民日报', '人民日报', '红军;村民;小道;老区;', '巍巍罗霄，直冲云天。在山势峻拔的黄洋界脚下，江西省井冈山市源头村掩映在万顷竹林绿波中。90多年前，红军突破重重封锁，将30多万斤粮食挑上井冈山，源头村是必经隘口。如今，这里建起了红军挑粮小道景区，成为热门旅游目的地。$$ 拾级而上，擦肩而过的游客们头戴八角帽、', '2020-11-17 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2020.011389', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (215, '报纸', '井冈山随想', '柯春晖', '中国教育台;中央党校(国家行政学院)\"习近平新时代中国特色社会主义思想理论研修班\";', '学习时报', '井冈山;红军医院;秋收起义;刘仁堪;共产党人;', '脚又一次踩上井冈山坚实的土地。$$ 这是我第三次上井冈山。作为中央党校（国家行政学院）“习近平新时代中国特色社会主义思想理论研修班”（第二期）的学员，我和我的同学们根据学校的安排，在中国井冈山干部学院接受了为期一周的体验式教学。$$ 春夏之际的井冈山，阴雨', '2019-06-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OJvC4nJHEEO0rQAUUFpZfH-Mj7Ii_097IhfNbZqyPL_HAIimaTqcraFOZK4lPNSS4OybOkrvF5pMaZelbo7l6k106XJ2zIanzs3Fhd9xd6Crgljm0MARTJuvZXDl321ViQR4jsCjswEg==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (218, '报纸', '八角楼前有片“灯下红”', '何志平; 张海华; 周勇敢', '解放军报', '解放军报', '八角楼;井冈山革命烈士陵园;三湾村;三湾改编;黄洋界保卫战;红色精神;', '【写在前面】井冈山是革命的山、战斗的山，也是英雄的山、光荣的山。$$ 习主席在井冈山调研考察时充满深情地说，井冈山道路是马克思主义中国化的经典之作，从这里革命才走向成功。行程万里，不忘初心。井冈山革命理想教育要坚持下去。$$ 枫树坪下听传统，八角楼前觅灯光', '2017-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OsYpkO40PfUitWeWC8889oWx9iXwTsaHYVgAi8zHH5_2GRWGXdl00Kh5ZjmKmoel-GYywye-gAFx0rshI-7cayeGp6eslQZrj-b0KHqp2C21_EpbZTIWvLKLwMzfp3gDhqIwnhuOUnug==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (219, '报纸', '井冈山：创新发展奔小康', '', '井冈山管理局;', '中国旅游报', '井冈山;红色旅游;奔小康;景区管理;', '井冈山是中国革命摇篮，境内旅游资源十分丰富，拥有11个景区、76处景点、460多个景物景观，保存完好的革命遗址、旧址100多处，具有发展红色旅游的良好条件。近年来，井冈山依托旅游资源优势，围绕“红色最红、绿色最绿、脱贫最好”的目标，坚持“红色引领、绿色崛起”发展战', '2017-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NHgleK4qoev72sg9VnnF8A3hl5h264cd-0d0QOVLqKVMThdCM0WzcZ1piNoSlgFvEeAhlT1IDZx6p52M9fk-Z4eUDs8D9i3a1wu0swM22fH2lr-0nSlD-kdcxUBt98JQNUtEdBXsBodQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (220, '报纸', '从历史向未来出发', '赵刚', '人民法院报', '人民法院报', '助理审判员;团支部书记;最高人民法院;死刑复核;青年干警;审监庭;', '身穿红军战士服，颈系红色识别带，肩背竹篾斗笠，腿系绑腿……一队年轻的“红军战士”行进在井冈山的一条山间小径。$$ 这不是影视剧中的画面，而是最高人民法院团支部书记及青年法官培训班学员在体验“重走朱毛挑粮小道”。5月7日至11日，最高法院机关各团支部书记和青年', '2013-05-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MRD-EEtXv3U6sDKWKJusEjCULTByIsIfeOBpmWzvUnLC5gfoncHR1T32Pi6mC_MjXAxcrgea0Fv-I2Fqqj0CIG7BoXDQTu5Qn3HErZa_2Uu757pkqDSP4sfAwAEXv1DzLenKc3T2WmgQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (223, '报纸', '井冈山：公安保卫工作艰难中起步', '周琼 ; 肖海员', '人民公安报', '人民公安报', '公安保卫工作;井冈山;国民党军;', '对于国人而言，这是一座特别的山。成长从这里开始，辉煌从这里启程。$$ 对于人民警察而言，这是一座更特别的山。当他们的责任里多了“守护”二字，他们与这座山的关系便不再只是回溯、瞻仰。力量在这里汲取，传承在这里展现。$$ 结束与开始之间$$ 2010', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PQrwPaRW5kefqhA6lr-jyC4Ckbj-ajETtHsjUaXsPQwb2SMYfBf6CQ7ZPFdzIotqUf3w9pgaFqA0-j75p6JlkbJ6zTCOC_aDAXH-BacQrEAh3BtebPfvncMvdkOXFYgYkGnS5BVggB7A==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (226, '报纸', '巍巍井冈展新姿', '梁睿 ; 赖永峰', '经济日报', '经济日报', '井冈山革命斗争;井冈山市;塑料光纤;', '又是一年杜鹃花开。在中国共产党成立90周年前夕，记者怀着崇敬的心情再次来到绵亘五百里的巍巍井冈山，重忆党在创建初期极端艰苦的环境下领导武装斗争的烽火岁月，采访井冈山在经济社会发展这一新战场上取得的新成就。$$ 井冈山上党旗红$$ 忆往昔峥嵘岁月稠。1927年，', '2011-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MGWoyHPhiOUYBhTnMO2-ujwo8JQSHAqbpYrNpbb8zJJElOgNBVoZwb6f7KPT1pwN-P71cxBCJVnSEehORuVDILrZ8MK55V9i5lB39twpHV1_uW4ZXPWQfQuSUwlVc9zthr17XvkuzjVw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (227, '报纸', '凤舞九天庆十年 和谐发展新井冈', '', '中国经济时报', '中国经济时报', '井冈山市;工业总产值;工业强市;旅游兴市;旅游工艺品;有机大米;新城区;日用瓷;', '岁月镌刻韶华，人间彪炳伟业。２０００年５月，在新千年浓浓喜庆的氛围中，经国务院批准，由原井冈山市与原宁冈县合并组建的新井冈山市正式成立，井冈山发展史上浓墨重彩的一页由此掀开。$$ 弹指一挥间，新井冈山市走过了１０个年头。然而，这１０年却记录着井冈儿女艰苦', '2010-11-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PfxBS3H4faigHPKwWh3QY-EqfmJTJOjXEtiiCMsZwFx9vAhFEIFeuuv42wryu8ktXRN0ldSYcYf05QoRKuwc7XiuxzXdlCzEWObde5vQnKI2wZik5I7GvKSukhSmJmKeZABQlNUUnsOA==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (228, '报纸', '“井冈山精神永放光芒!”', '罗书臻 ; 姚晨奕', '人民法院报', '人民法院报', '井冈山精神;井冈山斗争时期;高级人民法院;三个至上;革命传统教育;王胜俊;', '夏日的革命圣地井冈山，山峦叠嶂，树木苍翠，生机勃勃。$$ 8月上旬，全国大法官审判管理专题研讨班在井冈山举办，会议期间，组织大法官们进行了一系列革命传统教育活动，缅怀革命先烈，瞻仰革命旧址，听取有关井冈山精神的报告，接受了一次难忘的革命传统教育。$$', '2010-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NoaUOJYpjD8U45fCZbj3yQUjOsBVN3hlSkL7Vjr_QxQQnIt3h4UPbBkKnuh_4uKBn0l0uPNVt7KWN2zqri9ResYe9kHGvC3Ah8bFow5Vy6cytghU_vOzq0oNjMIB7d3kF68r6GoQcdXQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (229, '报纸', '让忠诚融入共和国检察官的血脉', '肖玮 ; 徐盈雁; 欧阳晶', '检察日报', '检察日报', '检察官;检察长;中国特色社会主义事业;建设者;最高人民检察院;中国特色社会主义检察制度;检察职业道德;共和国;', '革命圣地井冈山，群山巍峨，林海苍茫。 $$ 7月下旬，最高人民检察院在这里召开全国检察长座谈会暨全国检察机关第二次民事行政检察工作会议，并围绕大力弘扬井冈山精神举行了一系列革命传统教育活动，让参加会议的全体代表感受到了浓浓的红色氛围，进一步坚定了理想信', '2010-07-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PGCLiil7b9vzVRoQ2xEBFBTz9vIhuXTvQ-eqkdtetgh6p84JTsChZaK5zFyub45j4m3J0r7GUQfk3t8C9DqcvOqyw5TUhwQA_snM2oCMzh8e3Lp4-RmCww2YLbC99SRIQUUEdfKboCSw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (231, '报纸', '昔日红色摇篮 今日生态井冈', '', '中国经济时报', '中国经济时报', '井冈山斗争;新城区;井冈山市;拿山乡;', '巍巍井冈，令人神往。井冈山在中国是一个家喻户晓的地方，是中国红色革命的摇篮。老一辈无产阶级革命家在这里创建了革命根据地，走出了“农村包围城市”的第一步，掀开了中国近代史的崭新一页。$$  “山下旌旗在望，山头鼓角相闻。敌军围困万千重，我自岿然不动。早已', '2010-05-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MahwFCdpZpElO-JRIOq4CYrVQXNQJiqPEwoN8ZZYXemnQr8xArRAdn_kCNyYkl2LHL4ckK1zi4eoXCgA7dJwiJBiv06xmum_KU_cuf2dFtJFuUvIa5J-sTbjgqcRPuY-hrQe6aXyEwQw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (232, '报纸', '井冈山将建全国青少年革命传统教育基地', '梅柏林', '中国旅游报', '中国旅游报', '革命传统教育基地;井冈山;', '本报讯（驻江西记者 梅柏林）记者日前从井冈山管理局获悉，为进一步加强全国青少年革命传统教育，中共中央组织部与共青团中央决定在革命摇篮井冈山建设一个全国青少年井冈山革命传统教育基地，通过短期集中学习的形式，让全国的青少年分批来井冈山学习优良革命传统，帮助青少', '2010-01-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PNhpxM7WOK8ejADRqg2ek1Y9NEt2JZy7z7G51nweyaX7O-N-j3kNMbONn-Kp_l9Jtg9esun8w9X69xl7Rdcf6lbAWmWvBdEQPohZcmlDDb2NOs4rGMn8163oTPtzMM5SQudPTt4Jz6rw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (233, '报纸', '井冈山 红色旅游新年开门红', '任江华', '人民日报', '人民日报', '红色旅游;井冈山;革命传统教育;', '本报南昌1月2日电 （记者任江华）节日的井冈山，寒意料峭，但挡不住来自全国各地近5000名游客的脚步，他们在这里唱红军歌、走红军路、读红军书、吃红军餐、看红色景点、观红色经典晚会、住红军小屋、听红色故事……接受革命传统教育和爱国主义教育。$$ 黄洋界哨口，', '2010-01-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N_YgMM5i3MjWXeKE10Lq3NFFRTyibGALu7bj3B5VoI9LfGhIuDVayltaIzJdEQd7sOH9NPaFiht7lPI5XiCvBhOBa0y9Adj3uooeJ46e4WjWO4nZCmGVpn7WVi2b4R9tAxBn7YjL0YqQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (234, '报纸', '慰先辈英魂 塑清明正气', '张飞', '人民公安报', '人民公安报', '井冈山革命博物馆;公安厅;公安机关;公安队伍;政法委;', '“只有依靠对崇高理想的矢志不渝、对党和人民的无比忠诚和对革命事业的锲而不舍，公安队伍才能够成为一支靠得住、过得硬的队伍。这也是历史的一再证明。”11月1日至11月3日召开的全国公安厅局长座谈会上，用井冈山精神锻造公安队伍，成为与会代表们的共识。 $$ 11月3', '2009-11-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NiwswEe4Z5RmsAMSDtSNm2kEXwGJKXbI2G5TkwNxtC0AmDevIqmt6lTsL5ke7frqtqRwW6h__EW2th3s5LXPVkBVcFe5aPQS8RAagDR8mWl7DtLPJSxBiZhipL3uVyXF7Wo8o-JInqJA==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (235, '报纸', '苍茫林海满眼绿 巍巍井冈别样红', '顾阳; 赖永峰', '经济日报', '经济日报', '井冈山管理局;塑料光纤;井冈山市;旅游产品开发;红色旅游;客家村落;新型工业化道路;旅游产业;森林覆盖率;', '如果用一句最简洁的话来概括井冈山，“历史红、山林好”则再恰当不过了。$$ 这个位于湘赣边界、罗霄山脉中段的高大山麓，不仅见证了一段惊天动地的历史，被誉为“中国革命的摇篮”，而且还有着秀美绝伦的自然生态资源———这里有迄今地球上同纬度保持最完好的7200多公', '2009-11-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pitr_zSIxWwIkNiaVSInH8Xdj2Bznw20JdqzDIjmb9Fcnqmo4-DwG_SwemHovsmXCbCbH19PNKfIKbQP_a9CZheJBTpddl4MOMw8iqCTzIWxRKWj0L5z5dBdU9i-8ZkdPVwIYHM4ZLvQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (237, '报纸', '“三贴近与井冈山精神一脉相承”', '周宁; 璩静', '新华每日电讯', '新华每日电讯', '井冈山精神;井冈山斗争;一脉相承;《十送红军》;三贴近;', '如黛“青山”围就一方宽大的舞台。80多年前的烽烟已然消散，80多年后的大地生机盎然。$$ 曲曲荡气回肠的红色旋律、段段历久弥新的红色记忆，展现着幅幅井冈山斗争波澜壮阔的历史画卷。$$ 22日晚，参加“中央新闻单位名编辑名记者江西老区行”活动的100名采编骨干在', '2009-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Mrxncjl7RtNkHKJAS6iuYF6mAhYAyLZerpSnTb4ROG3Me0QkgafWy2tvckilXKqtNG9qYu2iQdzTXmgdsABdsQprcqXbzzasi0RyWONyzs1OXhrwYFvfL_MCgUAjAc1BzQ3AxfjILFlg==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (238, '报纸', '让井冈山精神在大学永放光华', '谭浩; 温红彦', '新华社;', '人民日报', '井冈山精神;高校党的建设;', '□他们是一批特殊的学员，既是“大知识分子中的领导干部”，又是“领导干部中的大知识分子”。而在这里，他们像小学生一样认真$$ □一次井冈行，一生井冈情。在学员们心中，八角楼的灯光依然，这缕光芒不仅照亮了参加培训的高校党委书记、校长们的心，更让人们有理由', '2009-08-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NHir1dLzcmObExS-hxmkqvLdin44_yy3rgvvgpBY8TKDIPqxMLUDU8rgyHDFjWrSlrkkVBplwm51A9GfBcAT_laR0jyH5nnvEDveB6VZSTXzflRARBR4HECLPCBWf6v4k5Vqzcc4Nbjw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (239, '报纸', '坚定信念闯新路', '任江华', '人民日报', '人民日报', '井冈山斗争;坚定信念;井冈山革命根据地;中国井冈山干部学院;井冈山革命博物馆;红色旅游;', '夏日，江西井冈山革命博物馆游人如织。$$ 展厅里，人们凝神观看，驻足沉思。“实物、文献、图片以及声、光、电的陈列表现形式，加深了我们对井冈山革命斗争史的了解，对井冈山精神内涵的理解。”广东游客吕先生连称“不虚此行”。$$ “井冈山斗争培育了以坚定', '2009-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OKVxcspJoGcnNdIO22xr9wBGQ1lusQNEtoWPFXdhx10LJlyCLcPL-rqWg2--MB5GFV_lfWpgI30071dm6EJx36R6vwhuJLi_SIOi-J_odda0ZI8u9Bj0lItJxi4-KG-pfbyjHZRRnNpw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (240, '报纸', '井冈山“三项工程”助推廉政建设', '颜芳明', '中国纪检监察报', '中国纪检监察报', '廉洁自律;三项工程;井冈山;', '本报讯 江西省井冈山市近年来全面实施“革命传统教育工程”、“廉洁自律工程”、“干部素质工程”，扎实推动党风廉政建设。$$  在实施“革命传统教育工程”过程中，该市各级党政组织传承井冈山精神，充分挖掘红色文化资源，将井冈山革命博物馆、行洲红军标语群、', '2009-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4ORDo8oH9ita1Fg2sScaY5XSMMqf4-WtvVayYpvb956X4XVuoYFXGD_ywu09zwTTB_HgwaQMDHHypi4BwSMZOKwLfw2ECMaHT2RUNg-PE7xWB3M2xEZyvCUmHNYGupxjXeROORE3zakhg==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (243, '报纸', '请到美丽吉安来', '魏晓霞; 班若川', '中国旅游报', '中国旅游报', '吉安市;井冈山;红色旅游;旅游业;', '“提到井冈山，几乎家喻户晓，而井冈山就坐落在江西省吉安市境内。”吉安市市长王萍用最简洁的语言，说出了吉安的非比寻常。$$ 位于江西省中部、有着2000多年历史的吉安，因红色而辉煌：波澜壮阔的井冈山革命斗争，给这片红土地留下了丰富的红色遗存———三湾改编旧', '2009-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MDIf_iixhtDD2zR7Nft0P5EWCyAX-gUJOf8B0VJX_G_imhE_yVOg_FQR0vjZTKjzp6inw1atiT7aXo08--E9LjUxIq77QLl5aVXeSUBTGBifha4XmZp3KdwHsh10KYHTGdcd7w2T9rwQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (244, '报纸', '圣地洗礼铸军魂', '王继荣 ; 刘泉', '科技日报', '科技日报', '红军医院;三湾改编;总医院;参观见学;党指挥枪;当代革命军人核心价值观;井冈山;', '井冈山，中国革命的摇篮，她如一颗熠熠生辉的明珠，镶嵌在湘赣边界罗霄山脉中段，以她独特的魅力吸引着世人的目光。4月27日至29日，解放军总医院参观见学团，在总后勤部副部长兼解放军总医院院长秦银河的率领下，踏上了这片神奇的土地。缅怀先烈、寻访旧址、服务老区人民，一', '2009-05-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OrHTQceXDh3N0uzvjVXKab6ytyqJ59_vNe-hLXE2vuLBsbO0Acf6G3ioknbjsQvRSY4L7JmB6JhtIpQmMVJc_7PQS9hEdH3MuOEN_YnDQ8rdEpE0wRMNXbGYoCQAd9VQEMD1rxys1a1g==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (245, '报纸', '追寻传统之根 筑牢思想之魂', '王梦义 ; 代烽', '解放军报', '解放军报', '当代革命军人核心价值观;党代表;', '本报讯　王梦义、记者代烽报道：4月上旬，为期15天的南京军区新任党支部书记培训结束。460名新任“党代表”通过井冈山寻根之旅，向军区全体党支部书记发出倡议：做党的创新理论的坚定信仰者、政治工作“生命线”的忠实守护者、当代革命军人核心价值观的自觉实践者，让井冈山', '2009-04-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PqdIsdqRNxxC_YQ47KeXyzlHGF0MHxFXlTdR9DuiOX0Fku94NuhFN3XV6YE0jao_4Q1750Jqj-L0y_Qs9DriE9wWpTMJmchHTdTrPjA2QSHHFMkxl06ql5LXuZbyDimHL-CoWH_i-IIQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (246, '报纸', '巍巍井冈情意浓', '孙承斌', '人民日报', '人民日报', '胡锦涛;黄洋界保卫战;井冈山革命斗争;劳动模范;吴建中;中共中央书记处书记;', '中华民族传统节日春节到来之际，革命圣地井冈山到处张灯结彩，洋溢着喜庆祥和的气氛。$$ １月２４日至２５日，农历腊月二十九和除夕，中共中央总书记、国家主席、中央军委主席胡锦涛在江西省委书记苏荣和省长吴新雄等陪同下来到井冈山市，亲切看望慰问革命老区干部群', '2009-01-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MCQReKxmK2IRAlhHNktPZPk96cevitUfVR3WujPXnQP-M-HsLnnnA9zn_GgKqCkgGU1mFb7zVJqBD4MXbQvV6n9xolUPdCr2lnTxMFEdafa3FIZu99tsndMvAs9TE8RNm9_OqMRXDK0A==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (247, '报纸', '除夕访井冈,胡锦涛同村民一道磨豆腐', '孙承斌', '新华社;', '新华每日电讯', '胡锦涛;吴建中;黄洋界保卫战;', '中华民族传统节日春节到来之际，革命圣地井冈山到处张灯结彩，洋溢着喜庆祥和的气氛。 $$ 1月24日至25日，农历腊月二十九和除夕，中共中央总书记、国家主席、中央军委主席胡锦涛在江西省委书记苏荣和省长吴新雄等陪同下来到井冈山市，亲切看望慰问革命老区干部群众，', '2009-01-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OvNjN7XA01VcKOe5jTH4F7_fkWth7PtqFD2oPZ26QGn8uRtBr7Y7VXxJD4N0p4qJ7LG862n9r985M8xaQ8lTM55nHwf5vqm_p_AxeSbP7ub8a1cEy-B6Lew2or0PVDbFd7eLfdCJZGjQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (249, '报纸', '坚定信念育英才', '李章军', '人民日报', '人民日报', '坚定信念;体验式教学;中国井冈山干部学院;黄洋界;井冈山;', '“山下旌旗在望，山头鼓角相闻……”$$井冈山黄洋界。跨越革命风雨、激情岁月，６月初，中国井冈山干部学院学员、５０多名来自全国各高校的思想政治课骨干教师，满怀激情地朗诵着毛泽东经典诗词《西江月·井冈山》。$$半个多世纪前，这里孕育了中国革命成功', '2007-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OObrhJFVquw6yYnDskQN3M_1IymjLJxq6orbfkDNr8LOJUzR5PCkBkxSJhZ-98yQ9Dp0pe4v2KLMGOXvjM_3jsZzdZXpRYEzP1GPUkiYM6bIJ5GkvExA0CPdTp4_ONg20QQEy04WKIcQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (250, '报纸', '井冈山红色旧址成荣辱观教育大课堂', '颜芳明; 刘斐', '中国纪检监察报', '中国纪检监察报', '井冈山;知荣明耻;革命旧址;大课堂;', '本报讯　日前，江西省井冈 山市又迎来了一批“缅怀先烈、 知荣明耻”实践团成员。成员 们怀着无比崇敬的心情参观了 井冈山革命历史博物馆、茨坪 革命旧址、小井红军医院、北 山烈士陵园，并重温入党誓词， 深刻领会“坚定信念、艰苦奋 斗、', '2006-12-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4ONUhxKEqqwFmBGmclA7cbrt-Qnsy8kk4sMu5pB8na_DhSOdabJcSc5vODTy7lYtYeHThiIeFMakz3eV_gJb8q2JHnjQHm6PrYyDw1XE7ohXYWhJvmoHo0KKEQpVdOH53TSi6w9a57NdQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (251, '报纸', '井冈山反腐倡廉教育突出“红色经典”', '颜芳明', '中国纪检监察报', '中国纪检监察报', '反腐倡廉教育;井冈山;廉政教育;“红色经典”;', '本报讯　“红米饭，南瓜 汤，秋茄子，味道香……”每当 夜幕降临，江西省井冈山市天 街音乐喷泉如约开启，一曲曲 井冈山斗争时期的优美旋律 悠然响起，让全市干部群众和 游客不知不觉受到了教育和 熏陶。这是井冈山市充分利用', '2006-10-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NYS_dL9_7rVoSUq6Al7oFfS69z71X9L1gzKM4_h1Jx3rDhFARpLtV76x4HxOqgkl7V23z3Qa2Odcd44HIbTt97ZRJZhPFfgDdP-_sGIAvAezBKj_nUpZtsGBRic4mJXixoGkk5dGsOrw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (252, '报纸', '红绿交映井冈山', '陈宜萍; 范传新; 龙友谢', '金融时报', '金融时报', '井冈山市;五指峰;', '41岁的李来清既是人民银行井冈山支行的行员,同时也拥有井冈山旅游局正式颁发的导游证。因为这导游的身份，最近几年她比别人都忙，在做好本职工作的同时，好学的她博览群书，融会贯通大量与井冈山有关的史料，经常陪同来井冈山游览的各级领导，周末很少在家。$$ 而26岁', '2006-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ol6P6rydWXuaHa-5AwOzLmmDrVajuKJUzjt_F59Pe7Mt9_yQH7gWgnAYMPmQ6z8E6tr8cIkY2tPq1plCPZZTN7AEdf7dtvNWEOWt1G-QwSYh1WXHfgjXfqO3dhsgIss7Vsn0Wa3HOiaA==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (253, '报纸', '何挺颖', '', '人民日报', '人民日报', '井冈山革命根据地;毛泽东;黄洋界保卫战;党代表;', '何挺颖，１９０５年５月出生于陕西省南郑县。１９２４年，何挺颖进入上海大同大学，１９２５年５月参加五卅运动，６月加入中国共产主义青年团，随后转入上海大学社会学系学习，同年冬转为中国共产党党员。 １９２６年夏，何挺颖受党组织派遣到北伐军部队任团指导员，', '2006-05-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MDAWf_7I5vIPc1HH5sy7W8PmBtZwjRtmHq__Xxa-FJ-C6ihNHa9A1ydS-Jjl_SGi4oOkqhaSzNi2SY7r5qa5XlwnuK5bKMpX9QMz0jhDiXsg7_pzQ0DrixOhRHiOL6AHYRb-UNUIN0HA==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (254, '报纸', '井冈山精神激励官兵爱岗敬业', '戴庆明; 李凌志', '解放军报', '解放军报', '弘扬井冈山精神;爱岗敬业;精神激励;', '本报讯 戴庆明、特约通讯员李凌志报道：4月10日,武警江西总队吉安市支队进行了一场别开生面的社会主义荣辱观教育课。500张反映井冈山精神的传统教育照片被搬进课堂,作为开展荣辱观教育的鲜活教材。该支队充分利用驻地革命传统教育资源,激励官兵树立正确的荣辱观,取得可喜成效', '2006-04-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MhXQ8ffIbo3-sNFh7wOg-uOy0TkM1lfCfRligwrDTVPL_7BTiL0bfYNRSCfG1OUS6mGFvdL_QD2tjlD-kxFHpgdC9hNI8jJvl9S4KRkaLwSHZaNNOBspJbwQAM_CdIelS4lJLEIf4msw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (255, '报纸', '王良', '', '人民日报', '人民日报', '张辉瓒;国民党军;', '王良是中国工农红军建军初期的著名将领。原名王化赅,字傅良。1905年生,四川綦江人。1924年考入上海持志大学学习,开始接触马克思主义。1926年到广州入黄埔军校第5期学习,他先学步科,后学骑科,成绩优异。1927年加入中国共产党。 蒋介石发动四一二反革命政变后,王良所在的武', '2006-04-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OIaK8xOQX0QrhHJpncpXZN18Pf3WJq_ega6XUIZaOuW90KIVFtQj8ViXC_jyaWJomePSelrqeeQ2p-rvDquNLO8cOXHC49kWKFKGlhN4gYcpQjGGvp5Xn77neMRBXUYGAM1SD8_S7nEw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (256, '报纸', '李灿', '', '人民日报', '人民日报', '彭德怀;中国工农红军;鄂东南;', '李灿是中国工农红军高级指挥员。原名李文彬，1901年生，湖南宜章人。1918年入湘军第2师6团1营2连当兵，编在彭德怀任班长的第2班。在军中，他教彭德怀识字，彭德怀教他操练，两人结成至交。后又与营部文书黄公略相识。由于志同道合，感情融洽，遂成好友。他们目睹军阀部队的腐', '2006-03-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N95hPXe7NZGpIhijUqnwFN5SSlFfFxkgqAahLb_i4SphaoaUVet0MAm0C8aBGwKrNrh8bM_pC6FpRkgHNXZ_-_CD_Vtyi-bH1JBM_0fYKfNe9mPzcJ4sDoL5lDqh-Bm2bzEfl2mxVbOg==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (257, '报纸', '曾士峨', '', '人民日报', '人民日报', '曾士峨;国民革命军;', '曾士峨，1904年生，湖南益阳人。1923年入益阳信义大学，开始接受进步思想。1924年到长沙，参加反帝爱国学生运动。1925年入黄埔军校长沙三分校学习。同年6月加入中国共产主义青年团。1926年入国民革命军第8军独立1师学生队，同年转入中国共产党。参加了北伐战争，在国民革命军', '2006-02-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PK4AxBx64FbyX8ARwo1KdnZCq1YN6uQNLDCZBOojdxbpyvoORUOWOyxtPeN3Ka6xIMGXsDlCNNUqCLGd7wU_ykrfaf5CC4vie9Sli_4iZQKvh4Hco8KzJQM_YcbC_lpB9Z0Db_kPvHJQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (258, '报纸', '井冈山红色旅游文化节好戏连台', '陈奇志; 赵书军; 李少豪', '江西记者站;', '中国旅游报', '井冈山;红色旅游文化;旅行社;', '为了使“红色摇篮、绿色宝库”井冈山红色旅游品牌唱响中华，走向世界，从9月中旬开始，由江西省旅游局，吉安市委、市政府，井冈山市委、市政府联合举办的“2005中国井冈山红色旅游文化节”相继粉墨登场，“旅游活动周”、“新闻发布会”、“万人火炬传递”、“大型综艺节目”', '2005-09-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PhSuX3o7oWZPwkTqpr4HXTtm_jYeu0BiobwvL0WFrY5-Wy-zfPgesVLerOAmRiOBdFtXW8hn9z_W_QjU2sPHQ8McsVBIGUdosQaCmbBJWwLFQbpwUNtaeRaANG0o_5JbG-7l2_7Tn7Gg==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (259, '报纸', '井冈山：从革命“火种”到幸福“火焰”', '范建', '科技日报', '科技日报', '洗手间;沼气池;生态家园富民计划;井冈山;', '“七一”前夕，我们沿着当年红军在井冈山会师的路线，感受难忘的井冈精神。攀上黄洋界，在朱德总司令挑粮走过的小路上，我们看到一种用松枝做燃料的“火把”。当地人叫做“松明子”。“松明子”伴随红军翻山越岭；乡亲们也打着“火把”迎送红军。“松明子”，照亮了红军和老', '2005-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M8TMaRGxQlwHVChlTB4_I3PvmatNkhk4cdnrBec-GZYQ5xuQpZ5Gy9jQ4paYV2Te4Pl4lM5yZZXKxrlZFSQs71mnolfI60alB1EzkJIdM9xGBCpLiVtJCrNtsM24hWe-DybjLQTiIaHg==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (260, '报纸', '武警江西吉安支队用“井冈山精神”深化“四个教育”', '舒春平; 戴庆明', '人民公安报', '人民公安报', '井冈山精神;革命传统;江西吉安;四个教育;', '本报讯：驻守在井冈山革命 老区的武警江西总队吉安市支 队，充分利用驻地革命传统教育 资源，把“井冈山精神”寓于“四个 教育”中，连续十年开展“学习红 军优良传统，争做合格忠诚卫士” 活动，涌现出一大批履职尽责的 高素质官兵。$$', '2004-12-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NoMqHwrtUZai8a2YM1LwHUrImK5TN2jrf33OLpovH5zAOM4KacsJm08FMr-o_y7yAZ7G-JWs_VHVr370BkosHIsydbx2q6sDQU39cjisoc8vSgrK8roFSfkMsYaHikJ4_3ZS71jMe5uA==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (261, '报纸', '井冈山打造“六个一”工程', '梅毅; 陈奇志', '中国旅游报', '中国旅游报', '井冈山;“六个一”工程;红色旅游;', '本报讯(江西记者站 梅毅 陈奇志)今年“十一”黄金周，恰逢国庆55周年，革命圣地井冈山掀起了红色旅游的浪潮。据统计，10月1日—5日全市共接待来山游客9.07万人次，与去年同期相比增长216.03%；实现旅游收入4552.51万元，与去年同期相比增长175.8%，实现旅游接待创历史新高，', '2004-10-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OHGivIoBSKflv66p-ZHIknThZiD2FhzYtOpEX25AWMRK511XS4te4yqOZE3dXrB-feZWzOD_jb_Q9bsYT2EuSDyiRi0-JoxQSlT-4t-D1pRmmN9Iv_4rU_7pzCokIMcDjzm0r2sjZtJg==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (262, '报纸', '精神的力量', '胡晓军', '光明日报', '光明日报', '井冈山市;', '主峰海拔1586米。它并不算太高，却屹立起了一座中国革命史上令人仰止的丰碑。 $$ 1927年10月至1930年2月。当年在此进行的革命斗争历时并不算太长，却开辟出了一条马克思主义与中国革命实践相结合的光辉道路。 $$ 巍巍井冈山，连着中国共产党璀璨的历史。77年过去，它正', '2004-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NfVcCchyWb7fZYIj2SHc8F3v2bQd3gMewomn8HMwfz2lTuQJxEajlngKLeC4maqpgT5fdR2HE0WJQoYk7pv4q8DUhEIEiIlFRVOEecfC4OPgBasWXWttYjvSakuhJjyarBUuY3WcUPuA==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (263, '报纸', '井冈山的红与绿', '', '人民日报', '人民日报', '井冈山市;农村革命根据地;革命老区;', '编者的话$$ 井冈山是中国革命的摇篮。77年前，毛泽东等老一辈无产阶级革命家在这里创立了第一个农村革命根据地，如火如荼的斗争岁月锤炼出宝贵的井冈山精神。如今，经过几代建设者的艰苦奋斗，井冈山已由过去的贫瘠山区建设成为革命传统和爱国主义教育基地、国家级重点风', '2004-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PAuz6oL8CTcTcwfMj-j11kOv04TZABvpnT8kaQJfcXoo8JX6JPG-_V-cZLAC44ie8zz09eHwpq_7MjN0itP4uewIBaT7sN_Gw2o6QKFpaGkbSVC3BDHC7w5fBBr-sFSTJ0oPfgHqKRow==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (264, '报纸', '革命摇篮今亦红', '胡晓军', '光明日报', '光明日报', '井冈山市;革命摇篮;', '盛夏时节驱车上井冈，苍山层林给人带来一片沁人心脾的清凉意境；在山上造访各处革命旧址，所见所闻又让人产生一种激昂向上的炽热情怀。 $$ 有“中国革命摇篮”之称的井冈山，在爱国主义旗帜下，在革命传统教育中，焕发着火红的风采。 $$在红色课堂里成长 $$ 茨坪毛泽东', '2004-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MwQ94pJgOr3Wpfy5K8vhJlYRH9VlbUAW_aU8q8JKSOmhMZoAqItUO5T6cFVahErYG2YbnRoOL-wMb7Jq6oI2jbJwJujeDyV4S3wfKYbWXyJlF_piQliIYptxucaurqXWA4vuUBKjt0mA==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (265, '报纸', '一生的红色记忆', '蔡洁璐; 王绍雄', '光明日报', '光明日报', '井冈山;', '这是一群活跃在井冈山红色土地上的浙江学子。从1月14日到1月23日，短短10天时间里，23名浙江师范大学的学生以“三个代表”重要思想为指导，追寻着红军的足迹，走进老区，走进农村，开展了一系列社会实践活动。$$ 重温井冈山精神$$ 实践队怀着对革命志士的敬仰之情参', '2004-02-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PrnbdUfvl5eGa6zLpF1BhJSHun16R6AgeQB5wy14fIOOyMe1j3YC57gBJ8kdEySxsJRhNvBGiuN5rZGbWdTTSoQXJNtN9qmEucMO3jIxM0lWxyIN_4aggoQ1O_a0dbG0l86DDERGN2vA==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (266, '报纸', '井冈山精神铸警魂', '刘志刚', '人民公安报', '人民公安报', '井冈山精神;消防大队;', '巍巍井冈山是中国革命的摇篮，孕育了 伟大的井冈山精神。江西省井冈山市公安消 防大队全体官兵，始终坚持和发扬井冈山精 神，以实际行动诠释“三个代表”重要思想， 一心为民，无私奉献，为党旗增辉，为警徽添 彩。建队32年来，他们49次受到省级以上', '2004-01-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NnHhTN6X8VILI4Wi4Q-Ssy4QW2LIYTKrArOTkk4jQP_mIW1E82vtgQKCzbP64fUua6dI6FrW71rjIHDuqynbOjh5eOfo76GymJgjrxxalMu9g12sio17yQoLpYFmlcIMih2qYWUkEfhQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (267, '报纸', '井冈山：“红色旅游”火起来', '余清楚', '人民日报', '人民日报', '井冈山;黄洋界保卫战;红色遗址;', '本报南昌6月20日电　记者余清楚报道：“七一”来临之际，革命圣地井冈山游人如织，迎来了新的旅游旺季。$$ 井冈山保存有黄洋界、八角楼等100多处革命旧居旧址，其中21处为全国重点文物保护单位。为将这一丰富的红色资源转化为旅游资源，该市加大红色遗址修缮力度，将遗址', '2003-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OytEP_RJAgxbdqdQgpdJIs7l-aypJJU0I1b-KR4czWTEE8RNIBsWomW6qrZ7rPCeS4XlSgu3yJGceDmUSbkoGZPkw7zitNRMDnoRvLSU0zSGyZp8lpPEKZ16q21IXK9Xx7INZ-rF72qA==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (268, '报纸', '为了让红旗永远飘扬', '龙小毛', '人民法院报', '人民法院报', '最高人民法院;井冈山革命斗争;', '一曲艰苦奋斗之歌$$ １９６５年５月重上井冈山的毛主席激动而又长时间地对随行人员讲述当年井冈山的艰苦战斗、生活情景，并着重强调，“要更好地建设社会主义中国、更好地建设社会主义的井冈山”，“艰苦奋斗的精神不要丢了，井冈山的革命精神不要丢了”。$$ １９９', '2003-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Mrvh66QKT1-RsU6ieVwTwCxgJ7P-D3WrFobrTwb5c8FDDVyp_CZiFZcO0-XbFCGfVW9ti-30x8tRh2Ga_rglPbmfuTe_sJ-lQj4v3PJ83VgmlwDC-wvn9jrs2nMiX1bjpIZE2P-jKfFQ==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (269, '报纸', '党的光辉照军营', '丁海明', '解放军报', '解放军报', '十六大报告;酥油灯;井冈山;江泽民同志;', '一座座军营红旗飘飘，一个个哨所挂起红灯，一队队官兵唱起了歌儿。十六大报告，像浩荡的春风，吹遍军营，吹进官兵的心中。 $$ 从乌苏里江畔到帕米尔高原，从北疆国门到南沙岛礁，从浩瀚碧海到长天云霄……戍边卫国的将士们心潮澎湃，以满腔的政治热情认真学习十六大报告', '2002-11-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MAIAVs1Bl-aSM1OxAPhZDiq-50C1EaN4OIvpe8OUEUazuDg89qpxs9192Ki6uLDVLljTBWaFK8VYvwAP5yi1bMxsvHG83fvsNjdX9Dm_t4iL3DaFmOXDAyvXjU9-iYi7GwqziSPExgVw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (272, '报纸', '八角楼前讲传统 三湾村里话军魂', '万海林; 彭卫平', '解放军报', '解放军报', '八角楼;三湾村;三湾改编;', '本报讯：万海林、特约通讯员彭卫平报道：地处革命摇篮 井冈山的江西省吉安军分区，在理想信念教育中，以井冈山 为课堂，以井冈山斗争史为教材，引导官兵走进历史，面向未 来，深刻认识“三湾改编”确立的党对军队绝对领导制度是我军', '2001-05-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PQ6RZPE7wg1t6liNRv7DONuMSPcg9k7RNg0S7ZOyWTutpuaPrcjJjw4NFdghFT9yUEmAZTAm_o17ATbw82YPcA7ObOlJGj86uvbu-61v6JpTItrRvKuE0YRU4uzh8Vpvy_NtRnmGVWsw==&uniplatform=NZKPT&language=CHS', '黄洋界_screened');
INSERT INTO `ds_article` VALUES (273, '报纸', '神山“星火”正燎原', '王慧敏; 邢宇皓; 王斯敏; 胡晓军; 卢泽华', '光明日报', '光明日报', '农家乐;村干部;村两委;', '编者按 江西井冈山茅坪镇神山村，是一个有着光荣革命历史和鲜明时代印记的小山村。它，平凡又不平凡! 一年前，我们曾在该村蹲点调研，聆听了许许多多当年红军将士与父老乡亲之间血肉情深的感人故事，也目睹了新时代那山那水的华彩蝶变。感动，让我们捧出了那篇长篇报道《神', '2023-11-30 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.005643', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (274, '报纸', '激发新动能 当好红土圣地守护者', '王莉莉; 曾芳洲; 肖玮; 梅琴; 刘玮', '人民公安报', '人民公安报', '公安局;井冈山市;井冈山精神;派出所;守护者;', '品牌名称：“三红三心”励警教育体系 核心理念：筑牢红色信仰，永葆忠诚之心；传承红色基因，筑牢敬仰之心；磨砺红色力量，激发担当之心 秋高气爽，巍巍井冈山层林尽染。井冈山是中国革命的摇篮。跨越时空的井冈山精神，传承着中国共产党人的初心和使命。近年来，江西省井', '2023-10-18 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2023.005625', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (275, '报纸', '传承红色基因 助力赣鄱发展', '王欢; 王磊', '人民政协报', '人民政协报', '红色基因;井冈山革命烈士陵园;习近平总书记;吉安市;白鹭洲书院;', '传承红色基因，心系赣鄱发展。近日，30多位十三届江西省政协港澳委员和特邀海外侨胞、台胞代表，齐聚江西省吉安市开展返赣视察。 在井冈山革命烈士陵园、革命博物馆体悟“红”的厚重，在神山村、植物园体会“绿”的蓬勃；在吉州窑、白鹭洲书院感悟“古”的悠久，在经济技术', '2023-10-10 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2023.005814', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (276, '报纸', '向星星之火指引的方向前行', '李春薇; 刘荣松; 欧阳璐', '检察日报', '检察日报', '检察院;检察干警;井冈山市;检察长;', '井冈山八角楼上，历经90余载，那盏每当夜幕降临便会亮起的清油灯还在。前来瞻仰的人见此情景，便能忆起“星星之火，可以燎原”的伟大革命历程。 八角楼上的灯光照亮的不仅是中国革命道路，还有共产党人百年不变的初心与理想信仰。 2016年2月，习近平总书记在江西考察时指出', '2023-08-06 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2023.003166', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (278, '报纸', '井冈山创新融合引客来', '周晨', '中国旅游报', '中国旅游报', '井冈山;井冈山管理局;管理处;红色旅游;', '暑期到来，“中国革命摇篮”井冈山红色旅游迎来热潮。作为首批全国红色旅游融合发展试点单位，井冈山依托丰富红色资源，以融合发展为路径，通过融合新业态、搭建新场景、推出新玩法聚客引流。 走进“元宇宙·境界井冈山”体验馆，戴上VR眼镜便能全景式体验那段激情燃烧的岁', '2023-06-29 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2023.001474', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (279, '报纸', '“接过这副担子是件幸福的事”', '王群学; 黄毅华; 龙礼彬', '中国国防报', '中国国防报', '井冈山革命博物馆;井冈山精神;讲解员;', '秋日井冈，丹桂飘香。 在江西省井冈山市茨坪革命旧址群，游客们常能看到一名身材挺拔的年轻人，背着扩音器穿梭于一排排干打垒土坯房之间，自信而从容地讲解着井冈山的红色故事。 他叫毛浩夫，是井冈山革命博物馆专职讲解员。本期“视点”，我们一起了解他的故事。 “就像', '2022-10-11 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2022.001858', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (280, '报纸', '在井冈山重温斗争历史汲取奋进力量', '韩萍; 徐鹏', '法治日报', '法治日报', '井冈山精神;政法机关;党的政治建设;斗争历史;政法委;', '八月的井冈山，满眼苍翠，到处焕发着勃勃生机。8月1日至14日，青海省委组织部、省委政法委在中国井冈山干部学院联合举办全省政法领导干部加强政治建设专题轮训班。政治轮训分两期进行，省直政法单位部分厅级干部，各市州委政法委书记、政法委常务副书记及政法各单位主要负责', '2022-09-13 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2022.005308', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (281, '报纸', '告慰红军好阿哥，拿山今已换新颜', '王斯敏; 李晓; 胡晓军', '光明日报', '光明日报', '井冈山;客家山歌;根据地;《十送红军》;送别歌;', '“三送（里格）红军，（介支个）到拿山，山上（里格）苞谷，（介支个）金灿灿。苞谷种子，（介支个）红军种，苞谷棒棒，咱们穷人掰。紧紧拉着红军手，红军啊，撒下的种子（介支个）红了天……” 十里相送，送别红军。送到下了山、过了坡，送到江之畔、大道旁，送出了泪花花', '2022-08-12 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.003778', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (282, '报纸', '把感动传递给更多人', '周欢', '人民日报', '人民日报', '井冈山革命博物馆;革命文物;讲解员;余贲民;陈毅安;八角楼;铁皮箱;', '2021年3月25日，习近平总书记对革命文物工作作出重要指示强调：“革命文物承载党和人民英勇奋斗的光荣历史，记载中国革命的伟大历程和感人事迹，是党和国家的宝贵财富，是弘扬革命传统和革命文化、加强社会主义精神文明建设、激发爱国热情、振奋民族精神的生动教材。” 井冈', '2022-08-10 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.008634', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (285, '报纸', '“三大纪律八项注意”的由来', '刘小花', '解放军报', '解放军报', '三大纪律八项注意;工农革命军;士兵委员会;', '在井冈山革命博物馆，收藏着一份《三大纪律八个注意说明》油印宣传册。全册共7页，落款为“中国共产党永新县委印”，时间为“12月17日”。这本小册子对“三大纪律八个注意”逐条做了解释，是红军纪律教育所使用的宣传教材。 这份《三大纪律八个注意说明》宣传册与“三大纪律', '2022-06-26 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.006613', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (287, '报纸', '依法保护运用 让红色资源“活”起来', '王丹', '人民日报', '人民日报', '革命文物;责任人;文物保护;红色文化;“活”起来;红色基因;遗址群;红色资源;', '初春的薄雾下，江西省安福县钱山乡虎龙坪战斗遗址群规整肃穆。 “虎龙坪战斗遗址群进行了重新规划和保护，这是对烈士的告慰!”近日，井冈山革命博物馆原馆长肖邮华再次来到钱山，看到钱山英烈墙已经建起，通往无名英雄墓地的步道阶梯也已铺好，感慨万分。 为加强对革命文物', '2022-03-17 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.002704', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (288, '报纸', '一口米缸映照严明纪律', '王帅', '人民日报', '人民日报', '井冈山;人民军队;', '在江西井冈山革命博物馆，一口棕黄色的陶质米缸静静伫立。鼓腹、曲颈、圆口、竖条纹的米缸，历经90多年的岁月洗礼已然陈旧斑驳，表面还有一条狭长的裂痕。这口农家米缸虽然看似寻常，却是中国共产党领导的人民军队遵守群众纪律、维护群众利益的有力见证。 越是艰苦条件下的', '2022-02-14 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.001551', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (289, '报纸', '感悟红色精神 砥砺初心使命', '张博', '中国新闻出版广电报', '中国新闻出版广电报', '井冈山精神;井冈山革命博物馆;共产党人;江西日报;红色精神;短视频;《解放军报》;井冈山革命根据地;', '历史是理解未来的钥匙。百年来，中国共产党带领中国人民走出一条从站起来到富起来，再到强起来的康庄大道，实现了从“赶上时代”到“引领时代”的伟大跨越。在百年奋斗历程中，中国共产党团结带领人民取得一个又一个胜利，以井冈山精神等为代表的革命精神发挥了重要作用。$$', '2022-01-19 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.000188', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (290, '报纸', '法治精神从这里始发', '董凡超', '法治日报', '法治日报', '法治精神;情景剧;《井冈山》;政法队伍;江西省;女子监狱;《井冈山土地法》;', '三湾改写新军制，一法分完旧地疆!$$ 星火燎原传赤色，工农革命聚戎装!$$ ……$$ 9月30日，在江西省女子监狱办公区的一隅，干警们正在精心排练着原创诗词朗诵情景剧《井冈山》，铿锵有力的诵读声传向远方。$$ 当天，《法治日报》记者跟随第二批政法队伍教育整顿调研采访团', '2021-11-01 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2021.006143', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (291, '报纸', '重走红色之路 探寻生态之美', '范朝慧', '中国旅游报', '中国旅游报', '井冈山革命博物馆;毛泽东;旅游点;红色旅游;研学旅行;红色摇篮;精品线路;八角楼;红色文化;黄洋界哨口;黄洋界保卫战;实景演出;讲解员;', '“久有凌云志，重上井冈山。”近日，文化和旅游部资源开发司组织多家媒体及OTA代表，组成“建党百年红色旅游百条精品线路”采风团，走进江西井冈山，沿着“井冈之路·星火燎原”精品线路，走进茅坪八角楼毛泽东故居、井冈山革命博物馆、黄洋界哨口等红色景区景点，重温红色记', '2021-10-20 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002982', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (292, '报纸', '“红色摇篮”来了一群找答案的人', '程迪', '新华每日电讯', '新华每日电讯', '红色摇篮;', '国庆假期夜间，南昌八一起义纪念馆内，江西首部革命旧址沉浸式实景剧《那年八一》正上演，通过声光电技术，将在场观众带入那年烽火硝烟中。有的观众换上军装，成为剧中角色，感受场景变化；有的观众与演员直接搭戏，参与剧情发展。$$ 南昌被誉为“军旗升起的地方”，人民军', '2021-10-06 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007703', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (294, '报纸', '击鼓催征启新程 奋楫扬帆再出发', '李洁琼', '中华工商时报', '中华工商时报', '理想信念教育;习近平总书记;党史学习;民营企业家;主题活动;“七一”重要讲话;', '百年峥嵘岁月，百年砥砺奋进；矢志践行初心使命，奋力开创光辉未来。习近平总书记“七一”重要讲话深情回望中国共产党团结带领中国人民开辟伟大道路、创造伟大事业、取得伟大成就、实现伟大梦想，吹响了向全面建成社会主义现代化强国迈进的动员令、冲锋号。$$ 为推动党史学', '2021-08-06 08:00:00', 'https://link.cnki.net/doi/10.38311/n.cnki.nzhgs.2021.003733', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (295, '报纸', '井冈翠竹依然挺拔', '刘发为', '人民日报海外版', '人民日报海外版', '井冈山国家级自然保护区;井冈山精神;红色旅游;', '“今年是建党百年，来井冈山的客人格外多。”一见面，井冈山国家级自然保护区大井林场副场长邹秋平就热情地对记者说，“井冈山精神是跨越时空的。”$$ 井冈山地处湘鄂交界的罗霄山脉中段。下了高速要上井冈山时，记者看到一座巨大的红旗雕塑。当地人说，这面红旗，既表明中', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002294', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (296, '报纸', '井冈山：用好红色资源 走出发展新路', '罗嗣尧; 周晨', '中国旅游报', '中国旅游报', '井冈山;井冈山革命博物馆;红色资源;', '1927年10月，毛泽东同志率领秋收起义部队走上井冈山，开始工农武装割据斗争。在这里，中国共产党人开辟了“农村包围城市、武装夺取政权”的中国革命道路，孕育了“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”的井冈山精神。$$ 如今，井冈山结合新的时代', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002146', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (297, '报纸', '井冈山精神跨越时空闪耀光芒', '赖永峰; 刘兴', '经济日报', '经济日报', '井冈山精神;井冈山革命博物馆;习近平总书记;', '中国共产党始终把共产主义远大理想写在旗帜上，将马克思主义作为根本指导思想，并将其与中国具体实际相结合，引领革命向着胜利方向前进。井冈山斗争就是在这一理想信念引领下进行艰苦卓绝奋斗的光辉实践。$$ “井冈山是中国革命的摇篮。井冈山时期留给我们最为宝贵的财富，', '2021-07-24 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005541', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (298, '报纸', '井冈山下的法治“播火者”', '郑海啸; 杨璐嘉; 胡文星', '检察日报', '检察日报', '井冈山市;检察院;检察建议;公益诉讼;播火者;', '一道光，划破苍穹；一座山，辉映历史；一种精神，照耀未来。$$ 90多年前，毛泽东率领秋收起义部队来到井冈山，创立了中国共产党领导的第一个农村革命根据地——井冈山革命根据地。而后，这簇星星之火熊熊燃烧，指引着中国革命一步步走向胜利。$$ 又是一年映山红开，记者怀', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.003638', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (299, '报纸', '精神伟力跨越时空', '胡晓军; 李慧', '光明日报', '光明日报', '井冈山革命根据地;毛泽东;中华民族;群众史观;习近平总书记;中国共产党领导;马克思主义中国化;共产党人;马克思主义基本原理;中国革命道路;中国特色社会主义道路;', '位于湘赣边界罗霄山脉中段的井冈山，并不算太高，却屹立起一座中国革命史上令人景仰的丰碑。$$ 1927年10月至1930年2月，当年在此进行的革命斗争历时并不太长，却开辟出一条马克思主义基本原理同中国具体实际相结合的光辉道路。$$ 1927年10月27日，毛泽东同志率领工农革命军', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003705', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (300, '报纸', '井冈山：“挑水人”挑起使命担当', '温婷婷; 王子鹏; 张斌', '中国水利报', '中国水利报', '井冈山;水利局;井冈山市;城乡供水;', '在井冈山革命博物馆陈列柜中，两只破旧的水桶格外引人注目，这是当年毛泽东同志帮房东周香姬挑水用的水桶。$$ 1928年5月，毛泽东来到江西省吉安市永新县塘边村考察，住在贫农周香姬家中。周大娘唯一的儿子参加红军去了前线，平时的家务活、农活全都压在她和儿媳的肩上。毛泽', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2021.001193', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (302, '报纸', '井冈山精神具有不可磨灭的生命力和时代价值', '刘旭; 姚鹏', '中国妇女报;', '中国妇女报', '井冈山精神;时代价值;社会主义核心价值观教育;', '“井冈山精神源远流长，博大精深，是一个蕴涵丰富的巨大精神宝库。”井冈山革命博物馆党总支副书记、副馆长、研究馆员林道喜在接受中国妇女报全媒体记者采访时如是说。他还表示，井冈山精神是以毛泽东为代表的中国共产党人把马克思列宁主义基本原理与中国革命的具体实践相结', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.002212', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (304, '报纸', '信念的力量指引胜利', '周玮; 高皓亮; 赖星', '新华社;', '新华每日电讯', '井冈山革命博物馆;井冈山精神;井冈山革命根据地;共产党人;习近平总书记;', '井冈山八角楼前，一棵在石下萌芽扎根的枫树竟把石头撑开，历经90余载风雨依然高大挺拔。$$ 中国共产党历史展览馆里，一盏红军在井冈山使用的油灯，映照中国共产党人百年不变的初心与信念。$$ 循着百年大党的精神之源，让我们聚焦中国共产党精神谱系中这个重要的红色坐标—', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005327', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (305, '报纸', '以实现中华民族伟大复兴为己任', '陈凤莉; 刘世昕; 张文凌; 潘志贤; 任明超; 王磊; 陈卓琼; 王豪; 邓智勇; 陈慧琦', '中青报;中青网;', '中国青年报', '中华民族伟大复兴;团支部书记;', '连日来，习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话，在广大团干部和团员青年中引起热烈反响，大家纷纷表示，要坚定不移听党话、感党恩、跟党走，不忘初心，勇于担当，为实现中华民族伟大复兴贡献青春力量。$$ 北京二七纪念馆志愿党史宣讲员、北京大学学生石', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.002574', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (307, '报纸', '江西井冈山 “让红色火种生生不息”', '张琪彬', '中国纪检监察报', '中国纪检监察报', '井冈山;市纪委;', '盛夏时节，巍巍井冈满山翠绿。崇山峻岭间，双车道盘山公路蜿蜒伸展，火炬造型的路灯点缀两侧，串联起100多个革命旧址遗迹。7月1日，万余名党员干部、群众自发前往革命圣地，重温那段波澜壮阔、激荡人心的历史，共同庆祝中国共产党成立100周年。$$ 革命烈士陵园巍然耸立于井', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003172', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (308, '报纸', '守正创新永葆优势', '钱宗阳', '解放军报', '解放军报', '政治建军;共产党;人民军队;古田会议;政治整训;思想建党;守正创新;', '坚持从思想上政治上建设部队，是我军建设的一条基本原则，是能打仗、打胜仗的政治保证。过去我们是这么做的，现在也必须这么做。$$ ——习近平$$ 站在历史与现实的交汇点上，眺望中国共产党在“第一个百年”的漫漫征途，有一条原则熠熠生辉——思想建党、政治建军。$$ 100', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004164', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (310, '报纸', '红色故事是最生动的教材', '张天培', '人民日报', '人民日报', '井冈山革命博物馆;红色精神;红色基因;井冈山精神;习近平总书记;', '在参与中传承、在传承中发扬，信仰之火就能熊熊不息，红色基因就能融入血脉$$ 在井冈山革命博物馆，一根灯芯的故事被反复提及。这是一根陈旧油灯里的灯芯，在罗霄山脉中段的八角楼里闪耀火光。就是在这豆大的火苗、微弱的光亮下，毛泽东同志思考着适合中国革命发展的道路。', '2021-03-29 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.003164', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (311, '报纸', '一位农民的入党宣誓书', '尹龙乔丹; 刘兴', '井冈山革命博物馆;', '经济日报', '入党宣誓;入党誓词;', '在井冈山革命博物馆展陈的众多藏品中，有一份特别的入党宣誓书。这份写在布条上的宣誓书，展现了一位普通农民灵魂深处坚定的革命信念和对党的忠诚。 那是1931年1月25日寒冷的深夜，一座简陋的榨油坊内，永新县东南特区党委工作人员郑重地把党旗挂在墙壁上，这一刻成为贺页朵', '2021-01-25 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.000934', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (312, '报纸', '第一面军旗的诞生', '颜芳明; 罗芹; 刘清', '江西省井冈山市纪委监委;', '中国纪检监察报', '杨立三;陈树华;工农革命军第一军第一师;何长工;', '在江西井冈山革命博物馆里，珍藏着一面红色旗帜，旗帜左面写有“工农革命军第一军第一师”字样，旗帜的中央缝着一个金黄色的大五角星，五角星内绣着镰刀和斧头图案，这是中国共产党人民军队的第一面军旗。历经岁月的洗礼，旗帜略显褪色，但却依然清晰夺目。它是光明与希望的', '2019-07-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MXXqt7YaN5aPVMM8uU_64lNmSitJevqTv6p-27VSx8SRk83SLSkCtWHDwqFtB0karEJpmjKFpBSCi8yGedzB64DnY7FQX1coQNPLParFgzuP1iQoJj821ZMwioEL898Yscdf9164e4tw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (314, '报纸', '年轻一代在传承与创新路上续写精彩', '张文燕; 朱永康', '中华工商时报', '中华工商时报', '年轻一代;全国工商联;企业家精神;实事求是闯新路;理想信念教育;井冈山;民营企业家;', '编者按：3月27-29日，全国工商联在江西省井冈山市举办年轻一代民营企业家理想信念教育活动。来自全国32个省区市的120余位青年企业家在3天的时间里瞻仰井冈山革命烈士陵园，参观井冈山革命博物馆和井冈山金融博物馆，在小井红军医院接受现场教学，并围绕践行井冈山精神进行座', '2019-04-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NB-DPuF70p3A8lT-j9_KrPHC_X_XW2gyoSH5SsD1VE_gm3ogvASqgGnDqVm2UNzxEPJArs6UjPqz_Vmydq-uju84vh5kVvc5pfxN2fo7u8-BcOz-fy1wv-zdI4B4n-mYiU58iPGOqFyg==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (315, '报纸', '井冈山：创新发展奔小康', '', '井冈山管理局;', '中国旅游报', '井冈山;红色旅游;奔小康;景区管理;', '井冈山是中国革命摇篮，境内旅游资源十分丰富，拥有11个景区、76处景点、460多个景物景观，保存完好的革命遗址、旧址100多处，具有发展红色旅游的良好条件。近年来，井冈山依托旅游资源优势，围绕“红色最红、绿色最绿、脱贫最好”的目标，坚持“红色引领、绿色崛起”发展战', '2017-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PEzzVOpcrD0Z83aj_F0c_4pQDzHOldAv5_PPJkWL4QG4vBzt2RnzTV-tBO0ZrpMej1pqEqCdyEyn9b7gHA9T_Ui2mzoMoSgScfdkJNKV-jvNGYuknXHUzs7S4Jb9mp4be9hX3WeTPRRg==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (316, '报纸', '燎原星火在这里点燃', '孟维伟; 曹蕾; 罗珺', '中国纪检监察报', '中国纪检监察报', '井冈山革命博物馆;湘赣边界;井冈山革命根据地;工农武装割据;', '6月28日，江西井冈山茅坪八角楼。青油灯静静地放在桌上。$$ “八角楼的灯光，比天上的北斗星还要明亮。”讲解员黄俊峰正在向游客们讲述那段艰难而光辉的岁月，“正是在这盏如豆的小小青油灯下，毛泽东挥笔写下《中国的红色政权为什么能够存在》《井冈山的斗争》两篇光辉著', '2016-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MQFu65hmuBvQzBv0obZaanvz1YfUbjWTt6iaxA9VOT3WWV6ujsFSQf8O8lCw6JqZOGKwKzw-2VsSRv9DD_nsZQ9VTMA34xUyjCsutozE2L2d9mUauZ60CDZC0dG1VF0i9SPvWdsWfPGg==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (319, '报纸', '井冈山：公安保卫工作艰难中起步', '周琼 ; 肖海员', '人民公安报', '人民公安报', '公安保卫工作;井冈山;国民党军;', '对于国人而言，这是一座特别的山。成长从这里开始，辉煌从这里启程。$$ 对于人民警察而言，这是一座更特别的山。当他们的责任里多了“守护”二字，他们与这座山的关系便不再只是回溯、瞻仰。力量在这里汲取，传承在这里展现。$$ 结束与开始之间$$ 2010', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OJKHYNDNMJFjKGQnili8_JT6364Lu5lna0qy8nZSEB97YT3QZNQbPcZWp8D8QMyNCj4puHB6l63w31b1RNWCSchmd1beVS2zSVRQt5PVCNjBbgTzB_6ZDyE8QnOTtw12-f9w6YKASmmA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (321, '报纸', '星星之火映天红', '李兴文; 杜宇', '人民日报', '人民日报', '井冈山革命根据地;红四军;湘赣边界;黄洋界保卫战;工农武装割据;秋收起义;', '新华社江西井冈山５月１４日电　（记者李兴文、杜宇）历经风雨洗礼，今日井冈山茅坪的八角楼显得格外凝重，那盏斑驳的油灯依然临窗摆放，砚台似乎还散发着昨日的墨香，一个伏案疾书的身影仿佛穿越时光，出现在我们眼前。$$ ８０多年前，毛泽东总结井冈山革命根据地斗', '2011-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OVkedRtejqqgWMRY0oUx9MCsj54xwZFsC6eGdoKWvq1wEt7TJzgblRfPptZys3fMBhBCJGjJ0b1b5vuIaK69ooq0dyB8zSYOuzAnINOolhZ2JKjXBFFwAVzpP5eTSBwjdPKAWpk_8xIw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (322, '报纸', '踏访井冈山——中国革命的摇篮', '张晓祺 ; 代烽 ; 徐政武', '解放军报', '解放军报', '井冈山斗争;工农革命军;毛泽东;井冈山革命博物馆;中国革命;', '也许，世界上还没有哪座山，像它这样与一个民族、一个国家、一个政党、一支军队有着如此密切的联系。$$ 井冈山，中国革命的摇篮。5月12日，冒着霏霏细雨，“红色足迹万里行”前方报道组来到井冈山，追寻留在这里的红色印记。$$ 重温一段历史——$$ 中国要有自己的马', '2011-05-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NM2fpIQej3ZiCcI5-I07JL2dtiDqfqmLYJ4UUh7xp1BimMmihJlITCYcQei8weCBQkDzkUOBpFy0oIFf7G1tcmuU7wdWRTuthyvVc8c8el8zagDpNI_Qv17BWo7bJsPtHalxuZjzMJdA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (323, '报纸', '《井冈山土地法》', '李兴文; 徐硙', '新华每日电讯', '新华每日电讯', '井冈山土地法;《井冈山土地法》;湘赣边界;', '新华社江西井冈山5月10日专电(记者李兴文　徐硙)“土地税由县苏维埃政府征收”,“以人口为标准,男女老幼平均分配”……这是《井冈山土地法》中的具体内容。这部于1928年12月颁布的土地法是中国共产党领导下的第一部具有法律效应的、成文的土地法。$$ 1927年10月,毛泽', '2011-05-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OuJmu1eBPaXQeUMydv8B5UuSnhHHLHEnbqhPvKBHRN_fdu_lfDCT90YrtwDKmALBIx1Cplr2C8i4Vbv2QGW_KGP0R2Hk-CYIOxOqJWFn6m3WGR6NpMZn_R_Wad44HiEcnhInJXYALNAg==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (324, '报纸', '沿着先辈足迹', '卞民德; 吴建群', '人民日报', '人民日报', '井冈山;', '本报井冈山5月8日电 （记者卞民德、吴建群）沿着当年毛泽东率领秋收起义部队上井冈的道路，“追寻”活动赴赣闽小分队的学生经萍乡、莲花、永新，到达井冈山。$$ 今天上午，同学们来到井冈山革命烈士陵园，向井冈山斗争时期死难的烈士敬献花圈。接着，同学们走上当年', '2011-05-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MgCnx8sNgSGbO6dLXNLg29Cx6-N_TR5nHBqwmO7DkW0q-K5kdpgRrpvUaOLrSpZLlQPa4XARa_EUFNOJf48j2lem7G63Ly_TsNZwR-Nz3Vi2eBM2RvFLu88j-3kEJCXopYD858QmF7mA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (325, '报纸', '巍巍井冈展新姿', '梁睿 ; 赖永峰', '经济日报', '经济日报', '井冈山革命斗争;井冈山市;塑料光纤;', '又是一年杜鹃花开。在中国共产党成立90周年前夕，记者怀着崇敬的心情再次来到绵亘五百里的巍巍井冈山，重忆党在创建初期极端艰苦的环境下领导武装斗争的烽火岁月，采访井冈山在经济社会发展这一新战场上取得的新成就。$$ 井冈山上党旗红$$ 忆往昔峥嵘岁月稠。1927年，', '2011-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OSdAssDibb495LAPJ3exJ4QJqBa0LGLYXY0WQk2DfG4tHZ4ctXMVMT8lp9HM8not1SuF1LbCWmahAS8_QXroHm3qSjLxiyj3oGVrhkqliXs-cuNMRqzMZh4ZrAB54uTCjj2xslbCq9xw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (327, '报纸', '“井冈山精神永放光芒!”', '罗书臻 ; 姚晨奕', '人民法院报', '人民法院报', '井冈山精神;井冈山斗争时期;高级人民法院;三个至上;革命传统教育;王胜俊;', '夏日的革命圣地井冈山，山峦叠嶂，树木苍翠，生机勃勃。$$ 8月上旬，全国大法官审判管理专题研讨班在井冈山举办，会议期间，组织大法官们进行了一系列革命传统教育活动，缅怀革命先烈，瞻仰革命旧址，听取有关井冈山精神的报告，接受了一次难忘的革命传统教育。$$', '2010-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NeTFde_x2DOJYVeLMD-5wQIZ8RmZGL0gJHSFIxI4n_iqSV1jvz4HGN4KT39OcQPamU9lgCpMJ7dvnq70ErUeJMJ-QjwXWitWO9dVHEUwdboMey4p261hfhfZ-fTwRZZvTwoqWAuNmuvA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (328, '报纸', '井冈山革命博物馆', '', '中国纪检监察报', '中国纪检监察报', '井冈山革命博物馆;老一辈无产阶级革命家;教育示范基地;', '井冈山革命博物馆是为纪念毛泽东等老一辈无产阶级革命家创建的第一个农村革命根据地——井冈山革命根据地而建的革命史类博物馆，于1959年10月竣工开放。馆藏文物、历史图片和文献资料3万余件；珍藏党和国家领导人、著名书画家及社会各界知名人士的墨宝珍迹数百幅；保存毛泽东', '2010-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OXO9yGXLVTeML6qmWKXcpbFEa7LDerMBH34c35m_BJBCudDs0QXOk9pf__SllMx_xBm-qu456MxGjHyYLGO0yd29M2DEpHRbx5o1A9jg0XSPLwfxplGp25pRHzqwTB34w7GNnj1_kBew==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (329, '报纸', '让忠诚融入共和国检察官的血脉', '肖玮 ; 徐盈雁; 欧阳晶', '检察日报', '检察日报', '检察官;检察长;中国特色社会主义事业;建设者;最高人民检察院;中国特色社会主义检察制度;检察职业道德;共和国;', '革命圣地井冈山，群山巍峨，林海苍茫。 $$ 7月下旬，最高人民检察院在这里召开全国检察长座谈会暨全国检察机关第二次民事行政检察工作会议，并围绕大力弘扬井冈山精神举行了一系列革命传统教育活动，让参加会议的全体代表感受到了浓浓的红色氛围，进一步坚定了理想信', '2010-07-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P6rHmKSpq3ZPPM4kEEiflJGiM55s9aEkZQ5AuOE_b4A22m5nrahWFp1S28DYL2i57hpM8-KTxjoCRPxRp_isieDu7JxwHv6_jihc9m68Xa6XMaQxrtt-s8pAM9l_Ff7o1Q29JrO986AA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (330, '报纸', '绵绵细雨祭先烈', '张鹏; 唐先武', '科技日报', '科技日报', '井冈山市;红军烈士墓;吴孟超;', '细雨是初春的标志。清明之际，细雨绵绵。早春里的井冈，层林染翠；清明前的茨萍，杜鹃吐芳。$$ 3月31日，第二军医大学东方肝胆外科医院院长吴孟超院士率领医院40多名党支部书记和专家教授，千里奔赴井冈山，追寻红军足迹、传承井冈精神，祭奠革命先烈、反哺老区人民。', '2010-04-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P1fgw53ZaB4aDfMB9pbqTT4LZeKjvwsOT9LxUv_8OcHT0rHJTOSjgXKJvlhXQ90uM29SRXE60ckQVu_UEqR-_gIrXsID9axK1ee2zLYuv6eCiKRuZvF7mqE5EHe5F78MGQVaXScApUTA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (332, '报纸', '井冈山将建全国青少年革命传统教育基地', '梅柏林', '中国旅游报', '中国旅游报', '革命传统教育基地;井冈山;', '本报讯（驻江西记者 梅柏林）记者日前从井冈山管理局获悉，为进一步加强全国青少年革命传统教育，中共中央组织部与共青团中央决定在革命摇篮井冈山建设一个全国青少年井冈山革命传统教育基地，通过短期集中学习的形式，让全国的青少年分批来井冈山学习优良革命传统，帮助青少', '2010-01-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NP66-j0FARDIt-l9EgUJEhJtfBVgCgvlzOVPrcJmfIstTai0wN1B9m0Fvogsc7iqlTh66brnf8EjOIOkLMMOh2lTC6LxhHpHTg7Y0uktuQaXr-uqkWVaNCqRVbB5U8_-uUtZk2yvQceg==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (333, '报纸', '井冈山 红色旅游新年开门红', '任江华', '人民日报', '人民日报', '红色旅游;井冈山;革命传统教育;', '本报南昌1月2日电 （记者任江华）节日的井冈山，寒意料峭，但挡不住来自全国各地近5000名游客的脚步，他们在这里唱红军歌、走红军路、读红军书、吃红军餐、看红色景点、观红色经典晚会、住红军小屋、听红色故事……接受革命传统教育和爱国主义教育。$$ 黄洋界哨口，', '2010-01-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ou8AcMUa533swuZYunzamNoPnkC3rtnV29Riue2dmxAuYv4akZgMsispwNUwNuNogYttmyNGJ68SpyZU-xOHKVSlj-NhKbBmf7X_Pmh-E1-Rwm-T-JwQao8aujrJX8RF4nJD0V2V0Dmw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (337, '报纸', '慰先辈英魂 塑清明正气', '张飞', '人民公安报', '人民公安报', '井冈山革命博物馆;公安厅;公安机关;公安队伍;政法委;', '“只有依靠对崇高理想的矢志不渝、对党和人民的无比忠诚和对革命事业的锲而不舍，公安队伍才能够成为一支靠得住、过得硬的队伍。这也是历史的一再证明。”11月1日至11月3日召开的全国公安厅局长座谈会上，用井冈山精神锻造公安队伍，成为与会代表们的共识。 $$ 11月3', '2009-11-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OiVWd9VNyCtNd0GcfC1OacLM5yrXjBauPeIv3rKeIZR7iRlJN9-3yTio4XaX4tHAtLd3XAOFVp4EDzjDzlcUAieZxQRwLjpCDGGbbb_3M9KjTrKeW5nzqZiK2344Kc9Wl0L1572cc9jA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (338, '报纸', '用红色资源对国防生进行主题教育', '刘国党; 罗词礼; 徐政武', '中国国防报', '中国国防报', '国防生;红色资源;主题教育;', '本报讯 刘国党、罗词礼、特约记者徐政武报道：11月上旬，南京军区驻华东交通大学选培办先后组织600余名国防生来到英雄城南昌和革命圣地井冈山，开展重温入党誓言、野营拉练等活动。近年来，该校选培办把红色资源作为培养国防生核心价值观的生动教材，引导国防生从中汲取养分', '2009-11-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OBvuLAUPdrCtIzv0hgCIgnQH_5YczOeg-TsgEd6Bk_xpM2eYcOOqd9WLYSYmxsFmt9dnTC0P8zNbugP5Q93mPxJNDMkwc1e1qk1Eft4ReDUXmVaHiwG3xQmgpGWuDavERqNuhy0JtuwQ==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (339, '报纸', '高度重视革命遗址遗迹保护利用', '余孝忠', '人民日报海外版', '人民日报海外版', '革命遗址;革命传统教育;保护利用;', '据新华社南昌１１月６日电　（记者 余孝忠）中共中央政治局委员、中央书记处书记、中宣部部长刘云山近日在江西调研时强调，遍布全国各地的革命遗址遗迹，蕴藏着十分丰富的精神内涵，凝结着我们党的光荣传统和伟大民族精神，始终是我们百折不挠、勇往直前的精神动力。要十分珍', '2009-11-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MbWp6X3yq1biU9tCbpZ3ESH7JOp4uiohCG54bshuAa13uIzCKHWhCp9Lelk_LhCTM5LZ4_Inezidv2Nq6WpE_3kHQ_YuPS2RxiDpdy80GxoFSgJqOOznFhU3oONrM40l4RlXGszj1LvQ==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (340, '报纸', '凝聚起建设中国特色社会主义的强大力量', '余孝忠', '新华每日电讯', '新华每日电讯', '建设中国特色社会主义;革命传统教育;', '新华社南昌11月6日电(记者余孝忠)中共中央政治局委员、中央书记处书记、中宣部部长刘云山近日在江西调研时强调，遍布全国各地的革命遗址遗迹，蕴藏着十分丰富的精神内涵，凝结着我们党的光荣传统和伟大民族精神，始终是我们百折不挠、勇往直前的精神动力。要十分珍惜并不断发', '2009-11-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MlVvU_gbHie6X01K_hA_Q6JMH1dzB6wUX40-tT7X4Tw23cHtr887Cb2qNsktG0V-mJXPT-di9WG3dRJUNuGjr3j6m-KRz9IbSVyZj0ExHAEv5bg3gITvA0wy5AaxoY9YCGLyBInSAvpQ==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (341, '报纸', '“三贴近与井冈山精神一脉相承”', '周宁; 璩静', '新华每日电讯', '新华每日电讯', '井冈山精神;井冈山斗争;一脉相承;《十送红军》;三贴近;', '如黛“青山”围就一方宽大的舞台。80多年前的烽烟已然消散，80多年后的大地生机盎然。$$ 曲曲荡气回肠的红色旋律、段段历久弥新的红色记忆，展现着幅幅井冈山斗争波澜壮阔的历史画卷。$$ 22日晚，参加“中央新闻单位名编辑名记者江西老区行”活动的100名采编骨干在', '2009-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pp4m2WDfF8T_moTbuAqDXpyhLrWW40rI0788T2Gs_1kdkAGQeRxzRsfo9TJbKuFFXs61KIWgFm4xgfXseUsxDSYOqgO2alyGuLLicXgJDhcD2VJ2wBZL4g4Fojjr8KC6qcNRcUMqiJrA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (342, '报纸', '坚定信念闯新路', '任江华', '人民日报', '人民日报', '井冈山斗争;坚定信念;井冈山革命根据地;中国井冈山干部学院;井冈山革命博物馆;红色旅游;', '夏日，江西井冈山革命博物馆游人如织。$$ 展厅里，人们凝神观看，驻足沉思。“实物、文献、图片以及声、光、电的陈列表现形式，加深了我们对井冈山革命斗争史的了解，对井冈山精神内涵的理解。”广东游客吕先生连称“不虚此行”。$$ “井冈山斗争培育了以坚定', '2009-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OdYs4HRW4TRgU7xMshfZwXrV28C1xbPz5RW6-RPNF4QQJ---w7LTKyIgDYPjOfGRlE37fZ2nnv_6b6rJ4pKLKtJ25gj-a3u0PNy3Hxu2LyKU_Wflt_akRdpnPVIh17vYcI-AXq-Ej-Xw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (343, '报纸', '井冈山“三项工程”助推廉政建设', '颜芳明', '中国纪检监察报', '中国纪检监察报', '廉洁自律;三项工程;井冈山;', '本报讯 江西省井冈山市近年来全面实施“革命传统教育工程”、“廉洁自律工程”、“干部素质工程”，扎实推动党风廉政建设。$$  在实施“革命传统教育工程”过程中，该市各级党政组织传承井冈山精神，充分挖掘红色文化资源，将井冈山革命博物馆、行洲红军标语群、', '2009-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OxnxNpKLnvWgB-D8a6f0EdTba2KT3zT7TtI-qZ0XJkaxsdk4Uc2zl8KhrDC_M2FSR1dG228ow3uyhn0HN6lFoTqm7G0X8HO-vNopeRhmjfxCU5tMk3p4jHCK1X1-CuO_mdKP63x60Xng==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (344, '报纸', '金融危机时,胡锦涛为何来到井冈山', '刘菁; 周伟; 张辛欣', '新华每日电讯', '新华每日电讯', '井冈山斗争;胡锦涛;井冈山革命博物馆;秋收起义;湘赣边界;', '新华社南昌7月5日电(记者刘菁、周伟、张辛欣)一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。 $$ 再上井冈山，重走井冈路', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MjQHHnG0XEJunaZVHBa6oXhCbNWjQYaZ6XKvHJnGQcUKrE7QmF1B2Qd2-HXgL09GVry4PovY3YbeWKrSz6Dt0z8dwmrq_dR6akG0l3yFbhQR8wQOTPx1gOUfVKCOzRI2Vr3l65pcf0GQ==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (345, '报纸', '道路·信念·核心', '刘菁; 周伟; 张辛欣', '新华社;', '中国青年报', '井冈山斗争;井冈山革命博物馆;南昌起义;秋收起义;湘赣边界;武装夺取政权;农村包围城市;工农革命军;共产党人;科学发展观;', '一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。$$ 再上井冈山，重走井冈路，抚今追昔，我们敬仰这片红土地，自豪60年新中国。', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MPkzlYP6jeG1MjNGWGCku4I1CHezXOAO60xa1OGXqvyzoDrSei9Bbb9TzdGrkhwjLrFPAypJtddLjr449GS6c8VxPcM1q7uViadFeTz10VWHahpWYbM8UJGNVzCgEXsRiTIFmxMri6Ug==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (348, '报纸', '请到美丽吉安来', '魏晓霞; 班若川', '中国旅游报', '中国旅游报', '吉安市;井冈山;红色旅游;旅游业;', '“提到井冈山，几乎家喻户晓，而井冈山就坐落在江西省吉安市境内。”吉安市市长王萍用最简洁的语言，说出了吉安的非比寻常。$$ 位于江西省中部、有着2000多年历史的吉安，因红色而辉煌：波澜壮阔的井冈山革命斗争，给这片红土地留下了丰富的红色遗存———三湾改编旧', '2009-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O-DUg0acUaQEyx2UwA2HEeTWO393rgfFNROF-K-g_6Y6mWer_jWfuDjMixtOwpOzX4RYPMo1PbKcRXcu90Aj8Af_4zOnwyDKL5CZwi6vyRtEZcGpiss0JiyyFFBLhsO7JBzrz2IsBG6g==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (349, '报纸', '红色文化的魅力效应', '廖国良', '经济日报', '经济日报', '红色文化;价值功能;井冈山革命博物馆;红色旅游;', '江西，是一块神奇而炽热的土地，这块土地创造了无数个中国革命里程碑式的红色标记。$$ 这块红土地上，有11个国家级爱国主义教育示范基地和58个省级爱国主义教育示范基地，它们在新时代展现出独具魅力的风采。$$ 这块红土地上，百花齐放的红色文化的繁荣，方兴未艾', '2009-04-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MmdxVJk0S8bOrUvbO389n5kUU-egSJa_84MAj1iVdsmtojgs1Lcv94T56CaZDjRTV3d1XArnUffSVyCId7EhVNCEV5pNehz1g59uaN5EdfQRtddUi177hDSH3nQKr8uR8EBhHXPnOc7Q==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (350, '报纸', '巍巍井冈情意浓', '孙承斌', '人民日报', '人民日报', '胡锦涛;黄洋界保卫战;井冈山革命斗争;劳动模范;吴建中;中共中央书记处书记;', '中华民族传统节日春节到来之际，革命圣地井冈山到处张灯结彩，洋溢着喜庆祥和的气氛。$$ １月２４日至２５日，农历腊月二十九和除夕，中共中央总书记、国家主席、中央军委主席胡锦涛在江西省委书记苏荣和省长吴新雄等陪同下来到井冈山市，亲切看望慰问革命老区干部群', '2009-01-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NKMMiCe1oIagOnL49yjHK6Wu6If45Y8E5eY0lflECmgFk6D6CxIZdlS-iHqcqeMFTdv4uq0TA3GnRHvJ4Qib3tSIlP9LpwzxkwIS-D-3-proNpUe_ViHC2BrhLie_AX5IYIPGfih7TVA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (351, '报纸', '除夕访井冈,胡锦涛同村民一道磨豆腐', '孙承斌', '新华社;', '新华每日电讯', '胡锦涛;吴建中;黄洋界保卫战;', '中华民族传统节日春节到来之际，革命圣地井冈山到处张灯结彩，洋溢着喜庆祥和的气氛。 $$ 1月24日至25日，农历腊月二十九和除夕，中共中央总书记、国家主席、中央军委主席胡锦涛在江西省委书记苏荣和省长吴新雄等陪同下来到井冈山市，亲切看望慰问革命老区干部群众，', '2009-01-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MUOJ2F5HfZaYHtEb1jSuIuYGmlOR8M8qGTWKuz6al0XqF4qFY8ZR64-LbJ663AIAyYwxlEgxCTf-ZuBp3Cj7db1ssUN0bzWS0JdKGQld7C4-sDM0Io0tlG6EtMiN8eJ9wnbmcfA5gO3g==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (352, '报纸', '全国检察机关先进工作者在井冈山休假', '周文英', '检察日报', '检察日报', '检察机关;井冈山;休假团;', '本报并冈山9月22日电(记者周文英) 9月21日，最高人民检察院副检察长孙谦在国家检察官学院井冈山分院看望了全国检察机关第十一期先进工作者休假团成员，向大家表示亲切的问候。$$ 此次全国检察机关先进工作者休假团成员共16人。他们之中既有屡建功勋的老模范，也有朝气', '2008-09-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4McekQ372gRRu-csGlvh8FG_NCbN4oD4QI9nsb9icU3dwMyPrB24WzR9JIYFvoCBlpvRlhQHPyufUtLiYHpmNqhO9apkDhlZoOK3WXCmMZL57UyQdJkHWsQt1uODyAif9ig_jptT0bWLQ==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (353, '报纸', '健全管理机构制度 确保免费开放有序', '廖国良', '经济日报', '经济日报', '免费开放;井冈山革命博物馆;接待工作;', '本报讯 记者廖国良报道：江西省为加强公共文化服务体系建设和公民思想道德建设，从2007年11月5日起将井冈山革命博物馆等6个全国爱国主义教育示范基地首批对全社会免费开放。井冈山革命博物馆免费开放后观众人数激增，仅头3个月，就接待观众20余万人次，同比增长近40%。$$', '2008-03-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OddY-alHn-12GS6BU_BHfeidU4xBm05goBbmm7M5aqfMgTh18I2Dcz0-xycvIL2NiEdMS9wFFSkSfRG4wwJAvO2nz-eVLwMxYSbuno2HRL1Enuw9jrQUQjLWPyZ8o8w26dAX6vXONxaw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (354, '报纸', '春雷交响', '卜金宝', '解放军报', '解放军报', '农民运动;教育示范基地;《湖南农民运动考察报告》;毛泽东;', '去年10月，在井冈山革命根据地创建80周年之际，全国爱国主义教育示范基地——井冈山革命博物馆以全新面貌亮相。走进展厅，一幅2.1米×2.65米的大型油画跃入眼帘，犹如一团跳动的火焰，吸引着观赏者的目光。这幅名为《春雷交响1927·好得很》的巨幅油画，构思缜密，气势恢宏，', '2008-01-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N_UzNubqZKhJ012c_QD76c4DQ7VxIuvzftoAyG2QZnY9cr9GOlOQ4xYeinzu8SI0d_R7JQ57kEstEcbMOX0KUaJ0orcygHimQjpzpiP68Tasc9P4kppepurUq9SPG8eK1fJUWBsJxGKw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (355, '报纸', '红色经典引发示范效应', '胡晓军; 王惠民', '光明日报', '光明日报', '免费开放;爱国主义教育基地;教育示范基地;江西革命烈士纪念堂;示范效应;安源路矿工人运动纪念馆;井冈山革命博物馆;革命传统教育;红色经典;', '这是一片神奇的土地。在16.69万平方公里的土地上,青山绿水之间,散 布着一个个红色经典的称号与地名:中国工人运动的策源地——安源,中国革命的摇篮——井冈山,军旗升起的地方——南昌,中华苏维埃的“红都”——瑞金,红军长征出发地——于都…… $$红色的江西大地上,有11个', '2007-11-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PYzps75F0sAwAi_zSkWMD-7XpyN_CHDD9vWVAvau8ngXYaAzLf_8AaacHeOqJS8ABqeoAOVTHrSDbsdCtMgOz_Eda1sw-_K-eX-bjFPIu5vTlqcVOcnlFLIdxONyzRL9Zx24lvApTFWA==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (356, '报纸', '江西免费开放六个爱国主义教育示范基地', '廖国良; 杨颖; 张雪', '经济日报', '经济日报', '教育示范基地;江西省;爱国主义;免费开放;', '本报讯 从11月5日起，江西省向全社会免费开放6个全国爱国主义教育示范基地。这6个示范基地是井冈山革命博物馆、方志敏纪念馆、于都县革命烈士纪念馆及中央红军长征第一渡纪念碑园、安源路矿工人运动纪念馆、江西革命烈士纪念堂和永新三湾改编旧址。预计2008年1月底前，江', '2007-11-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PyBXvNlNNM1tVkmcAA80eN59nomTgL2UCo8groO7N2avR5bB5Q0omnHbtb-njdJvqZfXxMKMmc5_Ew4sZHXoLRUinTINXkR6cF1epk_Or5AylX5QmeAMSXfl9eAmtMoGW3awZToHQ0Tw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (357, '报纸', '教育部举行井冈山精神报告会', '张贵勇', '中国教育报', '中国教育报', '井冈山精神;报告会;先进性教育活动;教育部;', '本报北京3月2日讯(记者　张贵勇)教育部今天举行井冈山精神报告会。井冈山革命博物馆原馆长毛秉华作了题为《弘扬井冈山精神，加强党的执政能力建设》的报告。教育部党组副书记、副部长张保庆主持会议并讲话。 $$ 报告会上，毛秉华回顾了井冈山革命斗争的历史，介绍了许多鲜', '2005-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OWsswfNVWW6MOiJjsDqvZMCtqtZwCWQqhnzWOSo-Zorl11vUNJ4pYPPIr6hr7G4RFrf42o14eRTdAJr-5n48Qq6SjhsxvK-QdOSHj3XuRDkNX39LQNktu-yVXoiSyQc9O2iJ-BVT8B3g==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (358, '报纸', '一生的红色记忆', '蔡洁璐; 王绍雄', '光明日报', '光明日报', '井冈山;', '这是一群活跃在井冈山红色土地上的浙江学子。从1月14日到1月23日，短短10天时间里，23名浙江师范大学的学生以“三个代表”重要思想为指导，追寻着红军的足迹，走进老区，走进农村，开展了一系列社会实践活动。$$ 重温井冈山精神$$ 实践队怀着对革命志士的敬仰之情参', '2004-02-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PbPnAB0CaCN_hgtKqSYC8gwmTTIys3BUWYn_9Rw9mkjvYJLr3-D4oOFl_JuRFvx3SdUmt9GM0aBoFT3vxn40ZCtGLgbp-CQSNkLPoMKhPKJgLv99FQ_uAQE705SuxrafLPK1uzNPgwuw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (359, '报纸', '丹青难写是精神', '刘文兰; 刘福明; 邝小明', '光明日报', '光明日报', '井冈山革命斗争;井冈山市;革命根据地;', '巍巍井冈山，殷殷挚爱情。一位满头银丝的老人，坚持34年如一日，马不停蹄，义务宣讲井冈山精神；行程万里，只身一人足迹踏遍湘赣两省边界各县农村；无私奉献，数十万元讲课费分文不取，反倒自己拿出10095元捐赠社会公益事业。他，就是今年全国“五一”劳动奖章获得者毛秉华', '2003-05-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P_YnOIkdmuSRuP3f6eEqQA5kxlE9luQjqYi0_Rff9Uihe_m1PTcTKsFvaHKq8t0B1hTOJFbyheh0txS4jZBSl7MFcPuKewhyRLg5tX5HucnP8Ng4WEvtFFB6pRzhcu-h-WKrAnEPjunw==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (360, '报纸', '井冈山“寻根”', '王握文; 曾砥平', '科技日报', '科技日报', '井冈山;革命传统;博士生;', '本报讯：通讯员王握文 曾砥平报道：今年 开学伊始，国防科技大学2000级166名博士研 究生走宁冈，访永新，上井冈，在中国革命的发 源地开始了入校后的第一课，接受革命传统教 育。$$  今年考', '2000-10-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N6Rrx9Dkv4kuh5Al1Se3klE6FMjat1asYEgogZvvUH8XrZ1SM1uQXCWWNNpmXsK19742J_f3PfUJalrHl8h1wcPg3wxMW8oklUjX7Mp1AxYLEidqjPeCNYtt4TzAJL_CMERrno0Vio0A==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (361, '报纸', '博士生第一课：井冈山上“寻根”励志', '唐湘岳; 王握文', '光明日报', '光明日报', '博士生;井冈山;第一课;', '本报讯（记者唐湘岳 通讯员王 握文） 国庆前夕，国防科技大学2000 级166名博士研究生走宁冈，访永新， 上井冈，在中国革命的发源地开始了 他们入校后的第一课──井冈山革命 传统教育。这是该校为打牢高层次人 才思想基础而坚持了多年的做法', '2000-10-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M0XmsnuEEXq_Asf4nY-h_iFIS6r6-S7jJ87PCiXJs2aPYLh_aFyxx-0eA6ClK-Bs3O5XO0lh7MNh98iwz1EBrmrEreYiS2siicy6wwzbLhDBN0CeOU75PHfHM6vlgkIOoTmffhpYwFTg==&uniplatform=NZKPT&language=CHS', '井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (362, '报纸', '“红色旅游+”助推湖南浏阳高质量发展', '张玲', '中国文化报', '中国文化报', '红色文化旅游;高质量;浏阳市;红色资源;红色旅游;文家市镇;秋收起义;湖南浏阳;', '2022年，湖南浏阳接待游客3048万人次，旅游总收入322亿元。“作为浏阳旅游重要的组成部分，红色文旅对浏阳高质量发展作出了重大贡献。”浏阳市文化旅游广电体育局党组书记、局长陈刚说，近年来，浏阳深入挖掘红色文化，全力激活红色资源，生动讲好红色故事，红色文化旅游发展', '2023-10-21 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2023.002632', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (364, '报纸', '周恩来亲笔修改《八一起义》说明稿', '刘小花', '解放军报', '解放军报', '八一起义;前敌委员会;连环画;周恩来;《八一起义》;', '在南昌八一起义纪念馆，珍藏着一份周恩来亲自修改过的《八一起义》说明稿（复制件）。这份《八一起义》说明稿为16开方格信纸，一共5张。原稿由时任南昌八一起义纪念馆副馆长杜南用蓝色钢笔书写，红色字迹为当年编辑所改，黑色毛笔小楷字为周恩来修改字迹。说明稿中，周恩来修', '2022-07-24 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.003870', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (365, '报纸', '中国共产党现存最早的入党誓词', '', '学习时报', '学习时报', '入党誓词;毛泽东;中国共产党;入党宣誓;', '入党誓词是中国共产党党员的宣誓书，是每名党员加入中国共产党时对自己作出的严格要求，对党作出的自我保证，对人民作出的庄严承诺。在不同的历史时期，中国共产党的入党誓词内容不同。$$ 在中国共产党历史展览馆，陈列着中国共产党现存最早的入党誓词，这就是江西永新农民', '2021-12-10 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002333', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (366, '报纸', '井冈山精神——跨越时空，照亮前行之路', '', '中国民族报', '中国民族报', '井冈山精神;井冈山革命根据地;', '井冈山，中国革命的摇篮。$$ 中国共产党人在创建和发展井冈山革命根据地的过程中，形成了坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利的井冈山精神。$$ 2016年春节前夕，习近平总书记来到江西，看望慰问广大干部群众和驻赣部队，首站就是井冈山。习近平总', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001151', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (369, '报纸', '百年风华熔铸党指挥枪', '刘小兵', '光明日报', '光明日报', '人民军队;习近平;听党指挥;党对军队绝对领导;军队建设思想;党组织;解放战争;党指挥枪;', '历史长河波澜壮阔，百年历程栉风沐雨。$$ 1921年7月，开天辟地大事变，中国有了共产党。1927年8月，南昌城头炮声隆，人民军队诞生了。从此，党旗所指，军旗所向。在中国共产党的领导下，人民军队一路披荆斩棘，历经硝烟战火，克服一个又一个困难，战胜一个又一个强敌，夺取', '2021-08-01 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003901', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (370, '报纸', '铭记光辉历史 续写强军新篇', '李学勇; 黎云; 张汨汨', '新华社;', '人民日报', '人民军队;根本宗旨;全心全意为人民服务;军队建设思想;党对军队绝对领导;习近平;中国共产党成立;', '百年党史波澜壮阔，强军征程一路向前。历史，是最好的教科书。$$ 这是一支中国共产党亲手缔造的队伍。这是一支值得党和人民信赖的武装。$$ 人民军队一路走来，为党和人民建立了不朽功勋，是保卫红色江山、维护民族尊严的坚强柱石，是维护地区和世界和平的强大力量。进入新', '2021-08-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007993', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (372, '报纸', '井冈山：用好红色资源 走出发展新路', '罗嗣尧; 周晨', '中国旅游报', '中国旅游报', '井冈山;井冈山革命博物馆;红色资源;', '1927年10月，毛泽东同志率领秋收起义部队走上井冈山，开始工农武装割据斗争。在这里，中国共产党人开辟了“农村包围城市、武装夺取政权”的中国革命道路，孕育了“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”的井冈山精神。$$ 如今，井冈山结合新的时代', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002146', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (374, '报纸', '这道光，照亮前行之路', '赖星', '新华社;', '新华每日电讯', '井冈山精神;共产党人;秋收起义;习近平总书记;红四军;井冈山市;毛泽东;', '90多年前，井冈山茅坪八角楼。一根灯芯的微光，穿透漫漫长夜。$$ 油灯下，毛泽东同志写下《中国的红色政权为什么能够存在？》《井冈山的斗争》两篇光辉著作，成为马克思主义中国化的伟大开篇，闪耀着“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”的井冈', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005584', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (377, '报纸', '坚持人民至上 彰显初心使命', '王向明', '中国人民大学习近平新时代中国特色社会主义思想研究院;', '解放军报', '人民至上;', '内容提要$$ 中国共产党根基在人民、血脉在人民。坚持人民至上是对中国共产党全体党员的根本要求。世界上没有任何一个政党能够像中国共产党那样，公开地要求每一个党员，都必须公而忘私，能够为了人民的利益不惜牺牲自己的一切。$$ 习近平主席在参加十三届全国人大三次会议', '2020-07-03 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2020.003441', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (378, '报纸', '第一面军旗的诞生', '颜芳明; 罗芹; 刘清', '江西省井冈山市纪委监委;', '中国纪检监察报', '杨立三;陈树华;工农革命军第一军第一师;何长工;', '在江西井冈山革命博物馆里，珍藏着一面红色旗帜，旗帜左面写有“工农革命军第一军第一师”字样，旗帜的中央缝着一个金黄色的大五角星，五角星内绣着镰刀和斧头图案，这是中国共产党人民军队的第一面军旗。历经岁月的洗礼，旗帜略显褪色，但却依然清晰夺目。它是光明与希望的', '2019-07-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NMrF6Ixudw43o1b3guYokBJTOTGPO1qI_CDeEEmP6AmCZmscZTODpUtAWWWI2yfXJzGkeNHpT_d5FZbHICpeQK-p_iSpedEeG4G_z-RS56pJuHh0YFedhb5lU0FVrujEpUhf4dRgKcfg==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (379, '报纸', '革命摇篮井冈山：星星之火 点亮初心', '黄欢', '中国组织人事报', '中国组织人事报', '井冈山;湘赣边界特委;井冈山革命博物馆;王尔琢;中国的红色政权为什么能够存在;秋收起义;革命摇篮;', '仲夏的井冈山，雨水连绵，万木苍翠，处处充满了红色记忆。$$ 这里的山间小路，走出了通往民族复兴的革命大道。这里的八角楼灯光，照亮了中国人民的奋斗征程。$$ 行程万里，不忘初心。$$ 沿着革命先辈的足迹，触摸历史时空，井冈山，革命的摇篮，她的光辉历程，皆承载着', '2019-07-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MfulqI0mSApA85BoatysTt2rjfXbazdG9qCwg4_J9tJmj8e5_mSG7GbT-zID8H48_u6bUmK3iuJeTqEGazNjcGocfAIB9bSXfPyr7-OD_gt48W0K8arEg8CFf648SAic_vFT0rHqYMZw==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (380, '报纸', '井冈山随想', '柯春晖', '中国教育台;中央党校(国家行政学院)\"习近平新时代中国特色社会主义思想理论研修班\";', '学习时报', '井冈山;红军医院;秋收起义;刘仁堪;共产党人;', '脚又一次踩上井冈山坚实的土地。$$ 这是我第三次上井冈山。作为中央党校（国家行政学院）“习近平新时代中国特色社会主义思想理论研修班”（第二期）的学员，我和我的同学们根据学校的安排，在中国井冈山干部学院接受了为期一周的体验式教学。$$ 春夏之际的井冈山，阴雨', '2019-06-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OGwZk-rPdzG8mfjJtR8XIRkb_1vfXLc0MTtRouVCSroN1zruGCJHg0flw2jdl51ryqAthBZYEQL-hGYCw6HKnJlG6kLYDP7SSymwGp8AY3iqp9Z13hz0GlpaEgdcwek9FPuM6X8q_LOg==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (385, '报纸', '人民军队建设史上的重要里程碑', '', '总政治部办公厅编研局;', '解放军报', '红四军;毛泽东;军队建设史;“九月来信”;古田会议精神;', '古田会议，即中国共产党红军第四军第九次代表大会，于1929年12月28日至29日在福建上杭古田镇溪背村曙光小学（原廖氏宗祠）召开。这次会议虽然只是红四军一次党内会议，但由于它系统地、创造性地回答和解决了当时党和军队建设面临的一系列根本性方向性全局性问题，因而不仅对', '2014-10-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OcLStCWhfgFmhaLwcmF3BWsyajvMNbqdHYluCNkcRnFQNpzSgTVTkYN9bEffMjcoPCAIZ3s5cMYxu0cANxQ0VPcLF-lXEny55DMdoaAZ-X-rmcslnZ9AcKRWdqZ5qcqFfVNU4D6ah9Lw==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (386, '报纸', '坚守信念的高地', '周舒艺', '人民日报', '人民日报', '支部建在连上;党对军队的绝对领导;井冈山会师;秋收起义;', '由广州军区政治部与湖南省委宣传部联合推出的大型话剧《支部建在连上》最近在湖南长沙公演，获得好评。《支部建在连上》反映了红军建军之初艰难曲折的探索过程，形象生动地讲述了“党指挥枪”的思想是怎样在革命斗争的残酷现实中逐渐成熟，又是怎样在革命军队中贯彻下去的。', '2012-11-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OrZS9KFqApMgoAZ5v7JSxGkyEUPIs0mgkGRQZfn6JOVBLDCl1qcl43YiV5na1Z8RKr0Ciniu43nT3OfK_wpZTLgSxvI4H_5bZqAOUBPBp9kMwstLpkxONc_WcwYsSQup5PFoVBH5I9Ew==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (387, '报纸', '激情澎湃的军魂颂歌', '严德勇; 李华敏 ; 田利阳', '解放军报', '解放军报', '支部建在连上;余洒度;历史题材;武装割据;党指挥枪;戏剧冲突;秋收起义;思想建党;三道桥;四个伟大;三湾改编;', '金秋十月，秋高气爽。广州和长沙两地，同时被一部名叫《支部建在连上》的大型革命历史题材话剧点燃“红色激情”。$$ 这部向党的十八大献礼的剧目，取材于秋收起义部队攻打浏阳失败后，从1927年9月文家市转兵，到1928年4月井冈山朱毛会师那一段艰苦卓绝的斗争历史。话剧以', '2012-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NNJjUjHpyg_Qn9kGcFI35MjHDsiCWgLRHIg6Q3gf21CIdEO20zeMNodhhc04fNX1vAnh15_OohkXd7lPnQ8__40RFdr8wvt-GjM-M9qEfSEgzPMMMqj2UWFcD_bMivJgTJynny0ceXEg==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (392, '报纸', '砍头不要紧 只要主义真 夏明翰', '', '人民日报', '人民日报', '夏明翰;秋收起义;何叔衡;', '据新华社北京３月１７日电 “砍头不要紧，只要主义真。杀了夏明翰，还有后来人！”这是１９２８年３月２０日夏明翰在被国民党新军阀杀害前，写下的大义凛然的就义诗。$$ 夏明翰，字桂根，祖籍湖南衡山县，１９００年农历八月生于湖北秭归。１９１７年春，出身名门望族', '2011-03-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M4IV0p0_vqeCDXA_yFjl5GtGkU2v8AIGF7-GOfUBAOLZati4iK-guDbnx1ZpPPIRCAAdLlS2OPHmPbU5aVrgTdAEEdOijrVKJEOTjou5T3LTsChzGACHDv5puSzO9zKTRY5MsDgVVJLQ==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (393, '报纸', '红土地上走出的优秀儿子', '梅克保', '中共湖南省委;', '人民日报', '宋任穷;浏阳县;秋收起义;', '今天，我们怀着无比崇敬的心情，参加纪念宋任穷同志诞辰100周年座谈会，缅怀他的历史功绩，学习他的品德风范。在此，我谨代表中共湖南省委和6800万家乡人民向他表示深切的怀念！ 宋任穷同志是湖南这块红色土地上走出来的优秀儿子。1909年7月11日，他出生于浏阳县一个贫苦农', '2009-07-11 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2009.002376', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (394, '报纸', '金融危机时,胡锦涛为何来到井冈山', '刘菁; 周伟; 张辛欣', '新华每日电讯', '新华每日电讯', '井冈山斗争;胡锦涛;井冈山革命博物馆;秋收起义;湘赣边界;', '新华社南昌7月5日电(记者刘菁、周伟、张辛欣)一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。 $$ 再上井冈山，重走井冈路', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Otp4JuyhciMBt4k1zI18CIledfYapx1hxywCLH1h2ljTQ8aVLJAea9FYG7lD0FlcmSknVbKnYzIJnpihFHyYFCISYjPqdP0-GidqCxsxTu8rVEr6ehO4XHDt5HETd6QGJ_kn73g5P9zg==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (395, '报纸', '道路·信念·核心', '刘菁; 周伟; 张辛欣', '新华社;', '中国青年报', '井冈山斗争;井冈山革命博物馆;南昌起义;秋收起义;湘赣边界;武装夺取政权;农村包围城市;工农革命军;共产党人;科学发展观;', '一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。$$ 再上井冈山，重走井冈路，抚今追昔，我们敬仰这片红土地，自豪60年新中国。', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OfKu_0BSjIOYJwtQVlmCkJwVF6_sQJoxHzdyKY7PC9BbLWlbhI_UVMAnkh52kNaiA0AFO43tcS9WpkaWAlHU83bjDS_jBx40EqlMfrpwsSo3SGjRXUIEuiyAOv7dSzBkanRiS3VhJYqg==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (397, '报纸', '“三月扑城”惊天地', '方强', '人民日报', '人民日报', '义勇军;湖南省;县委书记;秋收暴动;余贲民;', '今年3月16日，是著名的平江“三月扑城”80周年，也是发动、组织这次20万农军扑城的总指挥——时任中共湖南省委委员兼平江县委书记、我党早期宣传教育家毛简青烈士诞辰118周年。$$平江“三月扑城”发动之广泛，规模之宏大，意义之深远，在中国革命史上甚为罕见。我作', '2008-04-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MSbJUh39i_x4WrqD63kE65F5OhR0IVThi5AfqaZ4_r4et3agl_dLSFTOuQPN5_CNRHP6a2zoI2YkY_cNLfhhtYZg3mUlXjVZtDdLdVvElC254G57UVM7MVy9gYHta7zYzcu-Vi9QLKCQ==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (399, '报纸', '江西纪念“八一”文化活动精彩纷呈', '柯中华', '中国文化报', '中国文化报', '文化活动;秋收起义;', '本报讯 为纪念八一起义、秋收起义、井冈山革命根据地创建80周年暨中国人民解放军建军80周年，江西各地纷纷组织各种文化活动迎接“八一”的到来。$$ 由江西省政府、国家广电总局、国家旅游局共同举办的第三届红色旅游博览会将于8月1日在南昌开幕。南昌八一起义纪念馆', '2007-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Nt9FRZct9G8XlhJwBrnn_f3H0vqvHduASroBbfjBA5T184vOky6VFgtNa9JZEkvttdsA3EV9Ep69U9A10mlP5Y0nZTZeArHLysLV_VXVOqawWJF3KuWf-encXo5C4TGiYa2NyA_fFw1g==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (400, '报纸', '重大革命历史题材电视连续剧《井冈山》隆重推出', '毛东红', '中国纪检监察报', '中国纪检监察报', '重大革命历史题材;电视连续剧;《井冈山》;', '本报讯(记者　毛东红)为庆 祝中国人民解放军建军80周年， 弘扬井冈山革命传统和优良作 风，由中央电视台、解放军总政治 部宣传部、江西省委宣传部、南京 军区政治部和中央纪委宣教室联 合出品，中央电视台文艺中心影 视部、南京军区政治部前', '2007-07-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MjGCWMZ_YC3uOUylSLGEbouEM52GfTQRTTBqvKpI6omY2y2J1WA2LrdDLKXg7pCrBWTAPy2Q9kRAI5CspnGKNS-Z8dSm7q7J_krcle0w5EYFlFv1IkBMD1DIBSjQpg5uVU9QMNUsCgTQ==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (403, '报纸', '铁军精神', '杨连元', '工人日报', '工人日报', '铁军精神;红军师;叶挺独立团;秋收起义;', '“北伐中诞生，井冈山成长，我们是共产党的第一支武装。长征路上打先锋，抗日战场敌胆丧。从东北到海南，历经千百仗，英雄部队百炼成钢……”聆听这曲雄浑酣畅、铿锵顿挫的《铁军之歌》，读者的眼前也会闪现出那烽火连天、枪林弹雨的历史画面吧。$$ 这就是济南军区某', '2007-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OwuIT1T1uns1zSaGaxeIxRiKolbx2Oe9AOcOfE-RQ6iI4bckcKa_qI_Z_0iHZe6TdD-5utcsEG129RHwIr0_YAGeP0nEzjE-rUq0YWJ14mVp2Lk6R45mMH1jtS5YBDo9tN5qvP1Yy1Bw==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (406, '报纸', '萍乡：体味红色热土的味道', '吕娜', '中国水利报', '中国水利报', '秋收起义;安源路矿;湘赣边界;水务局;纪念碑;工人运动;', '$T这里是一方神奇而火红的土地，这里曾迸发出火热的革命热情：辛亥革命的预演──萍浏醴起义在这里发生， 中国工人运动的典范──安源路矿工人大罢工在这里兴起……这里就是江西省萍乡。11月，我们踏上这方热土，呼 吸这里的空气，感受这里辉煌的过去和变化的今天。$', '2006-12-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N-38vpS962ThersyTj-WSWL8Xgtl2JJkqlHdibOX-3Zfsnzx4miB3j67uCr4SU9pAI1FyiI93_Ra51wTlVskJdT8AXTtmTcv_gNTqLd-9FYtgDgHATsmAl3G4Qr3OUItLpQrZur7ffjA==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (407, '报纸', '井冈山会师(上)', '', '人民日报', '人民日报', '井冈山会师;毛泽东;南昌起义军;湘南特委;工农革命军;', '１９２８年４月下旬，朱德、陈毅率领由南昌起义部队余部和湘南农军组成的工农革命军，与毛泽东率领的湘赣边界秋收起义后组成的工农革命军在井冈山胜利会师。为了纪念这次具有伟大历史意义的会师，朱德曾赋诗道：“红军荟萃井冈山，主力形成在此间。领导有方在百炼，人民专政', '2006-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OflUcdhbdnDqQAdI0imMpXT5hp8mj-pnh3Wow5c2m8hGVZEjPRktMYxamytqm-U-QPYh7kUo3lE1OWzWEjdhHg77VoVTGmIZeQ3nEN6uIkENS07W0VE4sj5QcMRIqAT-utZgpaRV93bA==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (408, '报纸', '三湾改编 “支部建在连上”', '', '人民日报', '人民日报', '三湾改编;支部建在连上;湘赣边界秋收起义;', '三湾，是江西永新县的一个万木苍翠、群山环抱的小山村。湘赣边界秋收起义后，毛泽东率部向罗霄山脉中段转移，１９２７年９月２９日到达这里。在进村的当晚，毛泽东在“泰和祥”杂货铺召开中共前敌委员会扩大会议，讨论部队现状及其解决的措施，决定对部队实行整顿和改编，这', '2006-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MaIv2PM2qqQhjkYaTjH-f1a_IlazbJa1waGgnlfpf2UUadUrIgNCfrt6zihXC4kokpgKrscnebb44jlOBPQuy6Fefo13ni9J_PCiyTVn43Tl2bU-FKo58HMDlMoe-U4FAVEcUGaDrm7Q==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (409, '报纸', '湘赣边界秋收起义(下)', '', '人民日报', '人民日报', '湘赣边界秋收起义;国民党军;文家市;东门市;工农革命军;', '１９２７年９月１１日，工农革命军第１师按照预定计划，举行湘赣边界秋收起义。$$ 根据中共湖南省委的部署，长沙的铁路工人和部分农民，于９月９日开始分头破坏长沙至岳阳和长沙至株洲段的铁路，一度中断了敌方的铁路运输。$$ 起义开始后，第１团由修水、渣津', '2006-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MU27MX-WIqsLKTOguEw3jCZG1DHPfxfcjpVRNJkj-gMkBlo1c61ZZDukoKB58jZNTUw2hsd9S-gHwZBchU1pdwXH8NcuNiU9pu5TiGEVFJ1UfuYhd7H5Wc8iULgFUSfu5zvoqhZaUrCg==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (410, '报纸', '潘心元', '', '人民日报', '人民日报', '潘心元;秋收起义;马日事变;', '1927年5月21日，国民党反动军官许克祥叛变革命，发动“马日事变”，湖南笼罩在白色恐怖之中。潘心元对妻子说：“我的头是钢铸铁浇的，对革命是至死不移的。”“革命不成功，我是誓不罢休的。”$$ 潘心元，又名潘心源，1903年1月生，湖南浏阳人，1920年考入长沙岳云中', '2006-03-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PtRtUk2Bn_u2ayCR7tnyyTr8CMQ_3JFQMeWpf22EI7ZCVK6PhX5Sfth5CtdEgNS79XIyL4jXdXlYRkXps6EgVuFziAGRa6UhRT4Mwl7ar-SPaNdc6WJah6iAKMsccM9gtAZt0D69gYkg==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (414, '报纸', '毛泽东与建军及“八一”纪念日', '李南俊', '人民政协报', '人民政协报', '毛泽东;秋收起义;南昌起义;', '（一）$$  众所周知，中国共产党领 导的军队诞生于1927年8 月1日的南昌起义，即这天根 据中共中央决定，周恩来、贺 龙、叶挺、朱德、刘伯承等领导 的国民革命军约两万多人在', '2002-07-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NlTsUl6b2QNcD1F17xD0J1PhyumxTrqcfOVSOG03h4ArekqiHX7wFXzBu3wqS5JSPj1hdatzQmYlE_hcLFCbLv6PAGIdYa80kFifWLHjaPd04yKyycEbuLIxTCwsV8Cozs0hWS1Z9hiQ==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (415, '报纸', '夏明翰：砍头不要紧 只要主义真', '赵明亮', '新华每日电讯', '新华每日电讯', '夏明翰;李维汉;秋收起义;', '“砍头不要紧，只要主义真。杀了 夏明翰，还有后来人！”$$  只要读过这首“砍头诗”，便很难 忘记夏明翰。$$  1928年3月20日清晨，汉口余记 里刑场，反动桂系军阀即将在这里杀害', '2001-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NaiVUGAOr_wgem5fKXWzoVelt4uW_F4CgAjMDou8xbWx7v7HFuIkljWBM2zzC4OJnGgrYJo9Su6S5u2S7ndb64MDojBNMj_sego9qEQ8bYL2WDBenLN7ulcbuU2az6xszzyD0MSWTdsw==&uniplatform=NZKPT&language=CHS', '秋收起义_screened');
INSERT INTO `ds_article` VALUES (416, '报纸', '不忘初心 接续奋斗', '周围围; 刘明珠; 杨儒宇', '中青报;中青网;', '中国青年报', '烈士陵园;主题网络;清明祭;退役军人;话题传播;人民英雄纪念碑;纪念园;', '“我将爱你所爱，愿你所愿，这盛世每一天……”4月5日，厦门六中合唱团为2023年“清明祭英烈”主题网络传播活动演唱的《如愿》视频引发全网刷屏。从清晨到夜晚，在全国线下17处烈士纪念设施及红色教育基地，少先队员、共青团员、退役军人、市民等很多人自发前去祭扫，为英烈', '2023-04-07 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2023.001134', '王佐_screened');
INSERT INTO `ds_article` VALUES (417, '报纸', '以红色名村建设赋能乡村振兴', '易刚', '江西省莲花县委;', '中国组织人事报', '村干部;“三化”建设;基层党建;', '习近平总书记多次强调，红色资源是最宝贵的精神财富，要用好红色资源，赓续红色血脉。江西省莲花县是井冈山斗争时期的“全红县”，是秋收起义的策源地和引兵井冈的决策地，是中共湘赣省委、省苏维埃政府的诞生地。近年来，坚持以党建为引领，深入挖掘红色资源，因村制宜、逐', '2022-01-07 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2022.000060', '王佐_screened');
INSERT INTO `ds_article` VALUES (418, '报纸', '井冈山：公安保卫工作艰难中起步', '周琼 ; 肖海员', '人民公安报', '人民公安报', '公安保卫工作;井冈山;国民党军;', '对于国人而言，这是一座特别的山。成长从这里开始，辉煌从这里启程。$$ 对于人民警察而言，这是一座更特别的山。当他们的责任里多了“守护”二字，他们与这座山的关系便不再只是回溯、瞻仰。力量在这里汲取，传承在这里展现。$$ 结束与开始之间$$ 2010', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NerVgG04x3jpBk3aov_lfrhHS3We9LlHuTB7C4u-xLhbug9FEq22mp-nY9rNaO1rpqvEYhfSx76LOCiB2qcFP6H0hWV7nmDoh9Y1tFP5dKoYetLPqxvpHBvcFLkg4PBsdVYliyOAa8LQ==&uniplatform=NZKPT&language=CHS', '王佐_screened');
INSERT INTO `ds_article` VALUES (420, '报纸', '踏访井冈山——中国革命的摇篮', '张晓祺 ; 代烽 ; 徐政武', '解放军报', '解放军报', '井冈山斗争;工农革命军;毛泽东;井冈山革命博物馆;中国革命;', '也许，世界上还没有哪座山，像它这样与一个民族、一个国家、一个政党、一支军队有着如此密切的联系。$$ 井冈山，中国革命的摇篮。5月12日，冒着霏霏细雨，“红色足迹万里行”前方报道组来到井冈山，追寻留在这里的红色印记。$$ 重温一段历史——$$ 中国要有自己的马', '2011-05-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MO5B1CMoKw5f7VhmB3-JW1GxOUNFBG9RVeTZ_xnUdOnThBFTk8F7TGKcL8Zbvii1Au5nmiYtrV3H38FV2rhpaWeD1ltiecqFhDx4Uy17jUfdsiGRjI5uRrzoSFAAw09oiHdt7ZYChv0g==&uniplatform=NZKPT&language=CHS', '王佐_screened');
INSERT INTO `ds_article` VALUES (422, '报纸', '“井冈山精神永放光芒!”', '罗书臻 ; 姚晨奕', '人民法院报', '人民法院报', '井冈山精神;井冈山斗争时期;高级人民法院;三个至上;革命传统教育;王胜俊;', '夏日的革命圣地井冈山，山峦叠嶂，树木苍翠，生机勃勃。$$ 8月上旬，全国大法官审判管理专题研讨班在井冈山举办，会议期间，组织大法官们进行了一系列革命传统教育活动，缅怀革命先烈，瞻仰革命旧址，听取有关井冈山精神的报告，接受了一次难忘的革命传统教育。$$', '2010-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NdW-rjrIqyPcM1W8VCXnVr5t2yQ6k6KjjHPEf_deSu-593lG6n-01JvJR__bcpJF-rcf6zsrYdckKxZ4W_7vBNIESw602OU92yyry2QEOJOMQIZfqny--q3NX5Dio9ClOmwphLcieyvA==&uniplatform=NZKPT&language=CHS', '王佐_screened');
INSERT INTO `ds_article` VALUES (423, '报纸', '让忠诚融入共和国检察官的血脉', '肖玮 ; 徐盈雁; 欧阳晶', '检察日报', '检察日报', '检察官;检察长;中国特色社会主义事业;建设者;最高人民检察院;中国特色社会主义检察制度;检察职业道德;共和国;', '革命圣地井冈山，群山巍峨，林海苍茫。 $$ 7月下旬，最高人民检察院在这里召开全国检察长座谈会暨全国检察机关第二次民事行政检察工作会议，并围绕大力弘扬井冈山精神举行了一系列革命传统教育活动，让参加会议的全体代表感受到了浓浓的红色氛围，进一步坚定了理想信', '2010-07-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MDVszKfN65EtGYDXCZT5Q232JQTObGry-FnEUIGkCx4GXhE5K3_lQzpo5f5FDsB8LuSzjF8ivrK37-MTCiCD9F4EwChfcGUwNs97xsDJuoj_WuDtU63oxSfyM0qYVLEQ2jq3i-bT7J3g==&uniplatform=NZKPT&language=CHS', '王佐_screened');
INSERT INTO `ds_article` VALUES (425, '报纸', '绵绵细雨祭先烈', '张鹏; 唐先武', '科技日报', '科技日报', '井冈山市;红军烈士墓;吴孟超;', '细雨是初春的标志。清明之际，细雨绵绵。早春里的井冈，层林染翠；清明前的茨萍，杜鹃吐芳。$$ 3月31日，第二军医大学东方肝胆外科医院院长吴孟超院士率领医院40多名党支部书记和专家教授，千里奔赴井冈山，追寻红军足迹、传承井冈精神，祭奠革命先烈、反哺老区人民。', '2010-04-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MqR7Euh_jdQJgsd8BsdkDNx8iYd4qu6328mLgTIG1QFMQftbOoxZVDamn9n5EVx6L4V7r147saApmdMQPAoLREVCqwn6pGutj3edrcTXClVya0eTkDTODqfkzhIIAanxm5eqWXs8Rl_Q==&uniplatform=NZKPT&language=CHS', '王佐_screened');
INSERT INTO `ds_article` VALUES (426, '报纸', '井冈山会师(上)', '', '人民日报', '人民日报', '井冈山会师;毛泽东;南昌起义军;湘南特委;工农革命军;', '１９２８年４月下旬，朱德、陈毅率领由南昌起义部队余部和湘南农军组成的工农革命军，与毛泽东率领的湘赣边界秋收起义后组成的工农革命军在井冈山胜利会师。为了纪念这次具有伟大历史意义的会师，朱德曾赋诗道：“红军荟萃井冈山，主力形成在此间。领导有方在百炼，人民专政', '2006-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MqpNomdUnnchVFXXck9Kf8wwI_33-My1IMR7h3klYYwd2X-L_iTCWFl2A_iVO7f1PJFZIKylyd2-qI6kbzc5XqU_gj1Ba_Xo9eUxnfX9IMKQEx027yK2qQtJrnOu1Cn81NYtBXXs6gAg==&uniplatform=NZKPT&language=CHS', '王佐_screened');
INSERT INTO `ds_article` VALUES (427, '报纸', '湘赣边界秋收起义(下)', '', '人民日报', '人民日报', '湘赣边界秋收起义;国民党军;文家市;东门市;工农革命军;', '１９２７年９月１１日，工农革命军第１师按照预定计划，举行湘赣边界秋收起义。$$ 根据中共湖南省委的部署，长沙的铁路工人和部分农民，于９月９日开始分头破坏长沙至岳阳和长沙至株洲段的铁路，一度中断了敌方的铁路运输。$$ 起义开始后，第１团由修水、渣津', '2006-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MWLB2maZ_bcltmVKqlzs6QI-LPYek1-Q9gzYWBbSok6uhD6bpkO7JwPooYjJh6khaoc5sHPVaBN0yGyNwBMUFwa5J17u37A3HEtDEG5R702MTzppLEBFVi8oCEeiJ1ChWI4Wz82WdAOQ==&uniplatform=NZKPT&language=CHS', '王佐_screened');
INSERT INTO `ds_article` VALUES (428, '报纸', '激发新动能 当好红土圣地守护者', '王莉莉; 曾芳洲; 肖玮; 梅琴; 刘玮', '人民公安报', '人民公安报', '公安局;井冈山市;井冈山精神;派出所;守护者;', '品牌名称：“三红三心”励警教育体系 核心理念：筑牢红色信仰，永葆忠诚之心；传承红色基因，筑牢敬仰之心；磨砺红色力量，激发担当之心 秋高气爽，巍巍井冈山层林尽染。井冈山是中国革命的摇篮。跨越时空的井冈山精神，传承着中国共产党人的初心和使命。近年来，江西省井', '2023-10-18 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2023.005625', '茨坪_screened');
INSERT INTO `ds_article` VALUES (429, '报纸', '传承红色基因 助力赣鄱发展', '王欢; 王磊', '人民政协报', '人民政协报', '红色基因;井冈山革命烈士陵园;习近平总书记;吉安市;白鹭洲书院;', '传承红色基因，心系赣鄱发展。近日，30多位十三届江西省政协港澳委员和特邀海外侨胞、台胞代表，齐聚江西省吉安市开展返赣视察。 在井冈山革命烈士陵园、革命博物馆体悟“红”的厚重，在神山村、植物园体会“绿”的蓬勃；在吉州窑、白鹭洲书院感悟“古”的悠久，在经济技术', '2023-10-10 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2023.005814', '茨坪_screened');
INSERT INTO `ds_article` VALUES (430, '报纸', '踏上红土地 播下健康火种', '吴倩; 胡曦; 周翔', '健康报', '健康报', '罗庆锋;报告单;革命老区;主任医师;井冈山市;体检报告;', '红色是井冈山革命老区的底色，中国革命的星星之火从这里燎原，燃遍大江南北。6月25日，在全国上下纷纷深入开展主题教育、“七一”即将来临之际，由国家卫生健康委宣传司组织的“中国好医生、中国好护士”志愿服务总队带着健康火种来到江西省吉安市井冈山市开展“名医走基层志', '2023-06-29 08:00:00', 'https://link.cnki.net/doi/10.28415/n.cnki.njika.2023.002032', '茨坪_screened');
INSERT INTO `ds_article` VALUES (431, '报纸', '红色血脉薪火相传 千锤百炼锻造政工铁军', '赵婕', '法治日报', '法治日报', '政治部主任;司法部;司法行政工作;井冈山革命烈士陵园;司法厅;朱毛红军;红色基因;中国式现代化;习近平;薪火相传;', '井冈山，层峦叠嶂，山路蜿蜒，苍松翠竹，郁郁葱葱。 井冈山，中国革命的摇篮，在中国共产党的领导下，这里创建了中国第一个农村革命根据地，锻造出一支具有坚定理想信仰的钢铁队伍，点燃了中国革命的星星之火。 近日，司法部在位于井冈山的江西干部学院举办全国司法厅（局', '2023-06-05 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2023.002911', '茨坪_screened');
INSERT INTO `ds_article` VALUES (432, '报纸', '江西井冈山 打破时空限制 红色历史“破壁出圈”', '彭澳丽', '中国文化报', '中国文化报', '红色旅游;井冈山;井冈山红色文化;旅游业;风景旅游区;笔架山;时空限制;', '“夜半三更哟盼天明，寒冬腊月哟盼春风；若要盼得哟红军来，岭上开遍哟映山红。”2022年4月，江西井冈山第十三届杜鹃花节首次将展览搬到线上，以“云游”形式展示井冈山的红色旅游、绿色生态和风土人情，让游客打破时空限制，让井冈山旅游“破壁出圈”。 日前，文化和旅游部', '2023-02-04 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2023.000331', '茨坪_screened');
INSERT INTO `ds_article` VALUES (433, '报纸', '井冈山：打造群众满意的“平安高地”', '陈希; 肖玮; 胡智强', '人民公安报', '人民公安报', '井冈山市;公安局;群众满意;', '近年来，江西省井冈山市公安局持续加强平安建设，公众安全感和满意度持续领跑全省。“这得益于我们大力弘扬井冈山精神。”井冈山管理局党工委委员、井冈山市委常委、公安局局长吕建安如是说。 坚持红色传承 锻造先锋警队 “在烈士陵园里，有井冈山斗争时期牺牲的48000多名', '2023-01-28 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2023.000362', '茨坪_screened');
INSERT INTO `ds_article` VALUES (434, '报纸', '“接过这副担子是件幸福的事”', '王群学; 黄毅华; 龙礼彬', '中国国防报', '中国国防报', '井冈山革命博物馆;井冈山精神;讲解员;', '秋日井冈，丹桂飘香。 在江西省井冈山市茨坪革命旧址群，游客们常能看到一名身材挺拔的年轻人，背着扩音器穿梭于一排排干打垒土坯房之间，自信而从容地讲解着井冈山的红色故事。 他叫毛浩夫，是井冈山革命博物馆专职讲解员。本期“视点”，我们一起了解他的故事。 “就像', '2022-10-11 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2022.001858', '茨坪_screened');
INSERT INTO `ds_article` VALUES (435, '报纸', '蓬勃江西，彩云长在有新天', '胡佳佳; 张慧斌; 李健; 邓逸楠', '人民法院报', '人民法院报', '南昌市;习近平总书记;人民法院;劳动争议;生态旅游;', '江西是中国革命的摇篮、人民共和国的摇篮、人民军队的摇篮和中国工人运动的策源地，孕育了伟大的井冈山精神、苏区精神和长征精神。在这片充满红色记忆的红土地，一山一水都留下了革命先烈的战斗足迹，一草一木都记载着可歌可泣的革命故事。党的十八大以来，习近平总书记两次', '2022-09-18 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2022.003380', '茨坪_screened');
INSERT INTO `ds_article` VALUES (436, '报纸', '吉安：赓续红色血脉 当好红军传人', '陈希; 曾芳洲; 欧阳长春', '人民公安报', '人民公安报', '吉安市公安局;革命老区;人民警察;公安机关;井冈山精神;红色基因;', '开栏的话 一切向前走，都不能忘记走过的路。革命老区是新中国的摇篮。无数革命先辈在老区用鲜血和生命，铺就了一条通往今天幸福生活的道路，留下了一大笔可贵的精神财富。 奋进新征程，建功新时代。为迎接党的二十大胜利召开，本报自即日起，开设“革命老区公安行”专栏，', '2022-06-05 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2022.002795', '茨坪_screened');
INSERT INTO `ds_article` VALUES (437, '报纸', '井冈山市公安局茨坪派出所：红土圣地的“红军传人”', '陈希; 肖玮', '人民公安报', '人民公安报', '派出所;公安局;井冈山市;', '“我在井冈山长大，要用一生守护她。” “我的老外公在井冈山斗争中英勇牺牲，我是烈士后代，要做红军传人。” 五百里井冈青山莽莽，驻守在这里的江西省井冈山市公安局茨坪派出所延绵百年红色血脉、传承井冈山精神，发扬党的光荣传统，一颗红心忠诚向党、一腔热情服务群众', '2022-05-30 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2022.002714', '茨坪_screened');
INSERT INTO `ds_article` VALUES (438, '报纸', '永远做党和人民的忠诚卫士', '张天培', '人民日报', '人民日报', '公安局;刑侦大队;派出所;刑侦支队;安保任务;人民警察;', '英雄是一个民族最闪亮的坐标。 忠诚党和人民事业，牢记使命、忠实履职，顽强拼搏、无私奉献，党的十九大以来，公安队伍涌现出了一大批英雄模范。他们在打击犯罪、保护人民的关键时刻挺身而出、冲锋在前；在重大安保任务面前不怕疲劳、连续奋战；在平凡工作岗位上默默耕耘、', '2022-05-26 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.005436', '茨坪_screened');
INSERT INTO `ds_article` VALUES (440, '报纸', '讲红色故事 品红色文化', '周晨', '中国旅游报', '中国旅游报', '红色旅游;井冈山;红博会;红色文化;主题展览;红色基因;红色景区;党史学习;', '10月26日至29日，由江西、湖南两省政府主办的2021中国红色旅游博览会（以下简称“红博会”）在井冈山举办。全国400多家重点红色景区、文化和旅游企业代表齐聚革命圣地，共同追寻永不磨灭、历久弥新的红色记忆，推动红色旅游产业高质量发展。$$ 出新出奇出彩$$ 本届红博会主', '2021-11-05 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.003158', '茨坪_screened');
INSERT INTO `ds_article` VALUES (441, '报纸', '用理想之光照亮奋斗之路', '江琳; 徐元锋; 孙超', '人民日报', '人民日报', '理想之光;井冈山;干部学院;党总支书记;党性教育;', '习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话中强调：“我们要用历史映照现实、远观未来，从中国共产党的百年奋斗中看清楚过去我们为什么能够成功、弄明白未来我们怎样才能继续成功，从而在新的征程上更加坚定、更加自觉地牢记初心使命、开创美好未来。”$$ 百', '2021-11-02 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011540', '茨坪_screened');
INSERT INTO `ds_article` VALUES (442, '报纸', '井冈山：打造红土地旅游服务新样板', '胡佳佳; 张慧斌; 汪启链', '人民法院报', '人民法院报', '井冈山精神;旅游纠纷;生态旅游;红土地;', '上个世纪20年代末，在井冈山这片红土地上，以毛泽东、朱德等为代表的中国共产党人，创建了中国第一个农村革命根据地，开辟了“农村包围城市、武装夺取政权”的中国革命道路。井冈山斗争的伟大实践，对中国革命道路的探索和抉择、对中国共产党和人民军队的成长都具有关键意义', '2021-09-22 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.004432', '茨坪_screened');
INSERT INTO `ds_article` VALUES (443, '报纸', '铭记光辉历史 续写强军新篇', '李学勇; 黎云; 张汨汨', '新华社;', '人民日报', '人民军队;根本宗旨;全心全意为人民服务;军队建设思想;党对军队绝对领导;习近平;中国共产党成立;', '百年党史波澜壮阔，强军征程一路向前。历史，是最好的教科书。$$ 这是一支中国共产党亲手缔造的队伍。这是一支值得党和人民信赖的武装。$$ 人民军队一路走来，为党和人民建立了不朽功勋，是保卫红色江山、维护民族尊严的坚强柱石，是维护地区和世界和平的强大力量。进入新', '2021-08-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007993', '茨坪_screened');
INSERT INTO `ds_article` VALUES (444, '报纸', '井冈山：“挑水人”挑起使命担当', '温婷婷; 王子鹏; 张斌', '中国水利报', '中国水利报', '井冈山;水利局;井冈山市;城乡供水;', '在井冈山革命博物馆陈列柜中，两只破旧的水桶格外引人注目，这是当年毛泽东同志帮房东周香姬挑水用的水桶。$$ 1928年5月，毛泽东来到江西省吉安市永新县塘边村考察，住在贫农周香姬家中。周大娘唯一的儿子参加红军去了前线，平时的家务活、农活全都压在她和儿媳的肩上。毛泽', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2021.001193', '茨坪_screened');
INSERT INTO `ds_article` VALUES (447, '报纸', '信念的力量指引胜利', '周玮; 高皓亮; 赖星', '新华社;', '新华每日电讯', '井冈山革命博物馆;井冈山精神;井冈山革命根据地;共产党人;习近平总书记;', '井冈山八角楼前，一棵在石下萌芽扎根的枫树竟把石头撑开，历经90余载风雨依然高大挺拔。$$ 中国共产党历史展览馆里，一盏红军在井冈山使用的油灯，映照中国共产党人百年不变的初心与信念。$$ 循着百年大党的精神之源，让我们聚焦中国共产党精神谱系中这个重要的红色坐标—', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005327', '茨坪_screened');
INSERT INTO `ds_article` VALUES (448, '报纸', '江西井冈山 “让红色火种生生不息”', '张琪彬', '中国纪检监察报', '中国纪检监察报', '井冈山;市纪委;', '盛夏时节，巍巍井冈满山翠绿。崇山峻岭间，双车道盘山公路蜿蜒伸展，火炬造型的路灯点缀两侧，串联起100多个革命旧址遗迹。7月1日，万余名党员干部、群众自发前往革命圣地，重温那段波澜壮阔、激荡人心的历史，共同庆祝中国共产党成立100周年。$$ 革命烈士陵园巍然耸立于井', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003172', '茨坪_screened');
INSERT INTO `ds_article` VALUES (452, '报纸', '井冈山：创新发展奔小康', '', '井冈山管理局;', '中国旅游报', '井冈山;红色旅游;奔小康;景区管理;', '井冈山是中国革命摇篮，境内旅游资源十分丰富，拥有11个景区、76处景点、460多个景物景观，保存完好的革命遗址、旧址100多处，具有发展红色旅游的良好条件。近年来，井冈山依托旅游资源优势，围绕“红色最红、绿色最绿、脱贫最好”的目标，坚持“红色引领、绿色崛起”发展战', '2017-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OGDujC0ghgztvrGzOzjcn8DXGFywyJnEnzmjRCDnbAoQjGQUpk_aDhn6U6J5GEBO64pFqCxBmb2EqaJBp11zJI1TWz8yL8AJfM-svgBvgYBLxOvczN_K1Wo7TjhGbrQn4HysX67iUubA==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (453, '报纸', '燎原星火在这里点燃', '孟维伟; 曹蕾; 罗珺', '中国纪检监察报', '中国纪检监察报', '井冈山革命博物馆;湘赣边界;井冈山革命根据地;工农武装割据;', '6月28日，江西井冈山茅坪八角楼。青油灯静静地放在桌上。$$ “八角楼的灯光，比天上的北斗星还要明亮。”讲解员黄俊峰正在向游客们讲述那段艰难而光辉的岁月，“正是在这盏如豆的小小青油灯下，毛泽东挥笔写下《中国的红色政权为什么能够存在》《井冈山的斗争》两篇光辉著', '2016-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MxgQ1MYHiE_z3PWltJ6S5ThNaVmu9dkldDsFvXYYvNCmF5l3Iv4xWQTgA4QBslt6ml7InsJbj3EZy5TtuATRM1R-hmL9ZecP5JTtZRL7gHeOPpBTv_sJoPCrPzBgCS6YwKsyyqHa4ORQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (454, '报纸', '从历史向未来出发', '赵刚', '人民法院报', '人民法院报', '助理审判员;团支部书记;最高人民法院;死刑复核;青年干警;审监庭;', '身穿红军战士服，颈系红色识别带，肩背竹篾斗笠，腿系绑腿……一队年轻的“红军战士”行进在井冈山的一条山间小径。$$ 这不是影视剧中的画面，而是最高人民法院团支部书记及青年法官培训班学员在体验“重走朱毛挑粮小道”。5月7日至11日，最高法院机关各团支部书记和青年', '2013-05-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PapDOZCocXF15Hd6s_llbnIKKJBhKqtaIv4bStGVvbeL1FCkyuAxvqPqppsAGHju_wBCgKh1b0-SWVuQJAAzIlW3qlmHlZTJGLDDSxNcHCYVIGuqEwi9zzHUK98X1mmMDhBsu7lOuu2A==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (455, '报纸', '激情澎湃的军魂颂歌', '严德勇; 李华敏 ; 田利阳', '解放军报', '解放军报', '支部建在连上;余洒度;历史题材;武装割据;党指挥枪;戏剧冲突;秋收起义;思想建党;三道桥;四个伟大;三湾改编;', '金秋十月，秋高气爽。广州和长沙两地，同时被一部名叫《支部建在连上》的大型革命历史题材话剧点燃“红色激情”。$$ 这部向党的十八大献礼的剧目，取材于秋收起义部队攻打浏阳失败后，从1927年9月文家市转兵，到1928年4月井冈山朱毛会师那一段艰苦卓绝的斗争历史。话剧以', '2012-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pq6K-hLEGFxGlLjpertlbjh944KetcQ8ZZ5UCfI5qRGItt65-HBrNlvhNLDSOVq3KEqOlEEdhOKp9FgX8MOr6Wpjx0fZTgqsFOTNyaMRkzm9cZ7_vbFt5z945GyiK_YXZtLNnDwwxsPg==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (457, '报纸', '井冈山：公安保卫工作艰难中起步', '周琼 ; 肖海员', '人民公安报', '人民公安报', '公安保卫工作;井冈山;国民党军;', '对于国人而言，这是一座特别的山。成长从这里开始，辉煌从这里启程。$$ 对于人民警察而言，这是一座更特别的山。当他们的责任里多了“守护”二字，他们与这座山的关系便不再只是回溯、瞻仰。力量在这里汲取，传承在这里展现。$$ 结束与开始之间$$ 2010', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ow-HemjghNIyMneYUII9c7c6gjRBVYWm6oi2VNVChGR2EP0Y9xiyOpv672mxFFRrBkwPkMVI9bZ0wX2W4hsvQ--CaH2dJXtgLis8C9o_XDF8ytM8dJQQ_17MgLWLLyNRhzu74EJoZbSg==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (458, '报纸', '星星之火映天红', '李兴文; 杜宇', '人民日报', '人民日报', '井冈山革命根据地;红四军;湘赣边界;黄洋界保卫战;工农武装割据;秋收起义;', '新华社江西井冈山５月１４日电　（记者李兴文、杜宇）历经风雨洗礼，今日井冈山茅坪的八角楼显得格外凝重，那盏斑驳的油灯依然临窗摆放，砚台似乎还散发着昨日的墨香，一个伏案疾书的身影仿佛穿越时光，出现在我们眼前。$$ ８０多年前，毛泽东总结井冈山革命根据地斗', '2011-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MavOtZ_wB06Kzq1efqtera7Vc5u54sNzH2p5P9k3CEXInsAdMLxUk01VzT7tgwqa47axVFK9bl-nEEg0OOI3kO-82K8uz_f0l1oKHSR794rzKChcXqR2vH-L3F2n_mhL_k43SJlNhTbg==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (459, '报纸', '巍巍井冈展新姿', '梁睿 ; 赖永峰', '经济日报', '经济日报', '井冈山革命斗争;井冈山市;塑料光纤;', '又是一年杜鹃花开。在中国共产党成立90周年前夕，记者怀着崇敬的心情再次来到绵亘五百里的巍巍井冈山，重忆党在创建初期极端艰苦的环境下领导武装斗争的烽火岁月，采访井冈山在经济社会发展这一新战场上取得的新成就。$$ 井冈山上党旗红$$ 忆往昔峥嵘岁月稠。1927年，', '2011-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MVQ7zJpbh9FZzMFSOQxewC0FZq_HgPFwM-BnNzqH8USoCJ_2ELrxlpvIYUphcp4kboRIzjwbVQZTQJUiLGhFVe9ZfpeORjBJVzcb_540kmIORG8hY-J__20HOP4vralK5bqRLhyjgsdg==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (460, '报纸', '凤舞九天庆十年 和谐发展新井冈', '', '中国经济时报', '中国经济时报', '井冈山市;工业总产值;工业强市;旅游兴市;旅游工艺品;有机大米;新城区;日用瓷;', '岁月镌刻韶华，人间彪炳伟业。２０００年５月，在新千年浓浓喜庆的氛围中，经国务院批准，由原井冈山市与原宁冈县合并组建的新井冈山市正式成立，井冈山发展史上浓墨重彩的一页由此掀开。$$ 弹指一挥间，新井冈山市走过了１０个年头。然而，这１０年却记录着井冈儿女艰苦', '2010-11-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ns9ZNluQrTq3kZwQrjH_ooQJncrOiy_HK89pFatijP9xn6I2i_IreI8ZHO1GND0QqHqP3DGbzw6Y3FaBPjqh8uR7usNuOiL3AcoxXPbFvu1i2pH76Jx5YLJc0_WKXu93AyUarrm6qoag==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (461, '报纸', '井冈翠竹映笑脸', '宁新路', '中国财经报', '中国财经报', '井冈山革命斗争;水泥路;革命老区;', '车子还没进茅坪，茅坪乡乡长谢建文就早已在进村的山口处等候了。他说在此等候有两层意思：一来感谢中央财政革命老区转移支付资金为茅坪发展送来了及时雨，表达茅坪人的热情；二来让各位下车步行进村，看一看茅坪村里村外的新变化。$$ 茅坪，在井冈山革命斗争时期，曾是红', '2010-11-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OcDwkOdTyXgtaRqqEiZHzvC8Pz7MNAKp7qWCg7tkBnx3zNtIrR8akTcqp5wKnBcOn_5vNgKlBlHTuFuX1-zvWDLaGOISA6xqe0QG_Z9j8BLJCNTEXsbrhmr-qKmhmScz74RmxsNoKxDg==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (462, '报纸', '井冈山革命博物馆', '', '中国纪检监察报', '中国纪检监察报', '井冈山革命博物馆;老一辈无产阶级革命家;教育示范基地;', '井冈山革命博物馆是为纪念毛泽东等老一辈无产阶级革命家创建的第一个农村革命根据地——井冈山革命根据地而建的革命史类博物馆，于1959年10月竣工开放。馆藏文物、历史图片和文献资料3万余件；珍藏党和国家领导人、著名书画家及社会各界知名人士的墨宝珍迹数百幅；保存毛泽东', '2010-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MEFSek2GiqA6Mn2pkxaVGDSDNzmwt1MGVTCV1RMAA4C-t8ZBVl-bnvdUcDNz4hkoWz-4RwGlCywkwfEQPzlLvBxvVVKF-mwy1MhV0wcKRUAc15PZmurm13q15-ii50qRuyEaqxbSKA6w==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (463, '报纸', '让忠诚融入共和国检察官的血脉', '肖玮 ; 徐盈雁; 欧阳晶', '检察日报', '检察日报', '检察官;检察长;中国特色社会主义事业;建设者;最高人民检察院;中国特色社会主义检察制度;检察职业道德;共和国;', '革命圣地井冈山，群山巍峨，林海苍茫。 $$ 7月下旬，最高人民检察院在这里召开全国检察长座谈会暨全国检察机关第二次民事行政检察工作会议，并围绕大力弘扬井冈山精神举行了一系列革命传统教育活动，让参加会议的全体代表感受到了浓浓的红色氛围，进一步坚定了理想信', '2010-07-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ov4upM41wPXh3lhMurQJSG3_NhqFfvxCfAEf4TPeyqsqCICVw1Be1KPXR5FaNRJiMykBQhpJCk4b2F_c4UBjZNd6ZDgmmqs2sHxCLt_MQlOmL9xEWFcabKf2qdwkgjI54sTmfhq2vIJg==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (464, '报纸', '把12315作为一项民心工程来抓', '陈建国; 张石林 ; 朱海', '中国消费者报', '中国消费者报', '井冈山市;消费者;消费维权;民心工程;工商局局长;', '江西井冈山是全国首批5A级重点旅游景区，也是全国革命传统教育的重要基地，每年吸引着数百万海内外游客前来参观游览。为了适应井冈山地区旅游形势的发展，切实维护广大游客的合法消费权益，10年来，井冈山市工商局采取多项举措，大力开展12315消费维权工作，把12315服务平台', '2010-07-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OkzULlO1FT9oi8os0wY9bH6YacdZ0ORVkQ7Vr_wZ_AWHA2oVjg73I2jzhJ7oyoZbsPvSMCGheaixYp3yIm47Z_IzNT_3zYM3x_5tjTToNy3oAoa6xZXZi2jF3gUynvkPJXf14FcGvw4w==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (466, '报纸', '昔日红色摇篮 今日生态井冈', '', '中国经济时报', '中国经济时报', '井冈山斗争;新城区;井冈山市;拿山乡;', '巍巍井冈，令人神往。井冈山在中国是一个家喻户晓的地方，是中国红色革命的摇篮。老一辈无产阶级革命家在这里创建了革命根据地，走出了“农村包围城市”的第一步，掀开了中国近代史的崭新一页。$$  “山下旌旗在望，山头鼓角相闻。敌军围困万千重，我自岿然不动。早已', '2010-05-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PNrS26OktBiBfecIJGToAstEnRJilufso2b6Z4SwYllFNrMk67Jh0N5XXNJurdX-PEbrzDQEhVm_JIVqRtlARhjBjSPHxFRMWTf97tY6A0UnHL_lQVtiH9TLlZWDhRJJrYSA8rmDVLXQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (468, '报纸', '井冈山 红色旅游新年开门红', '任江华', '人民日报', '人民日报', '红色旅游;井冈山;革命传统教育;', '本报南昌1月2日电 （记者任江华）节日的井冈山，寒意料峭，但挡不住来自全国各地近5000名游客的脚步，他们在这里唱红军歌、走红军路、读红军书、吃红军餐、看红色景点、观红色经典晚会、住红军小屋、听红色故事……接受革命传统教育和爱国主义教育。$$ 黄洋界哨口，', '2010-01-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M_MJZfd4PvP93V86kWP0Hbc-AsyH9McnT3lPNdE59Vnrz-xbE5hRIrYoHpp7xqF5C6vDQSLzGv53ognCpQ3aAZKccmztJRQ4zl4fCG4-JZKiZ8LVueeyQQPt2qgUgQHDSLO5Vwn03niQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (470, '报纸', '苍茫林海满眼绿 巍巍井冈别样红', '顾阳; 赖永峰', '经济日报', '经济日报', '井冈山管理局;塑料光纤;井冈山市;旅游产品开发;红色旅游;客家村落;新型工业化道路;旅游产业;森林覆盖率;', '如果用一句最简洁的话来概括井冈山，“历史红、山林好”则再恰当不过了。$$ 这个位于湘赣边界、罗霄山脉中段的高大山麓，不仅见证了一段惊天动地的历史，被誉为“中国革命的摇篮”，而且还有着秀美绝伦的自然生态资源———这里有迄今地球上同纬度保持最完好的7200多公', '2009-11-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PB6gGmoJ47t4nY3YC0RV5bAG7ef-CkZ2MSXvfwXheDxa-UJjkV_Ri352HDxjT-eMCSVt4wz1-8Fk_TsAlWjr2oa8vSEGeakWHkfxdZhr9J1Vli9ntRGFcH226Y896JQC9QMjj7OdzyOw==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (472, '报纸', '“红色管理”学习坚守信念', '高初建', '中华工商时报', '中华工商时报', '民营企业家;井冈山;建设者;', '由华商学院主办的“首届中国民营企业家学习运用毛泽东管理哲学特训班”日前在革命老区井冈山举行。来自全国各地的６０余位民营企业家参加了这次特训，国家行政干部管理学院、中国人民解放军军事科学院、国防大学、总参等权威院校和机构的学者专家，为民营企业家们进行了专题', '2009-07-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OzVogiO06Qxmw5U5DWR5ktfqQhJoj5fulwYYjJY7s7_na5HIOUV37uWuv4J9hNCycaEVK6TyVojQIni0JlXsOkJ1LfpSPRtCNGrx4ywX66_Gn_A5EVhHLGKRnpDZ-p61iA69jziv2p2Q==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (473, '报纸', '坚定信念闯新路', '任江华', '人民日报', '人民日报', '井冈山斗争;坚定信念;井冈山革命根据地;中国井冈山干部学院;井冈山革命博物馆;红色旅游;', '夏日，江西井冈山革命博物馆游人如织。$$ 展厅里，人们凝神观看，驻足沉思。“实物、文献、图片以及声、光、电的陈列表现形式，加深了我们对井冈山革命斗争史的了解，对井冈山精神内涵的理解。”广东游客吕先生连称“不虚此行”。$$ “井冈山斗争培育了以坚定', '2009-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OWvSyKQnsDaqdUDz-oB-XQYHmirvkAIGInH-4Pxl2WOjHpNNSpFVwLvjocKw2O0NBU4XIr3PBvB3HetOQdvLCl_UU1rSemjH0mzRHobUfVXzq-_0Ek3B1Lf_EVvJVbfQJVLocUKlUIVA==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (474, '报纸', '请到美丽吉安来', '魏晓霞; 班若川', '中国旅游报', '中国旅游报', '吉安市;井冈山;红色旅游;旅游业;', '“提到井冈山，几乎家喻户晓，而井冈山就坐落在江西省吉安市境内。”吉安市市长王萍用最简洁的语言，说出了吉安的非比寻常。$$ 位于江西省中部、有着2000多年历史的吉安，因红色而辉煌：波澜壮阔的井冈山革命斗争，给这片红土地留下了丰富的红色遗存———三湾改编旧', '2009-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MrYryuX0jg9qdxrVIfgmHex5TAP5joYvtXel-mJCkb1ueXTSD08y-3OwXfB_cqIAquTaiB-wmXER8B7j9MDyg3rb6uYCtHJ3yoWv5LU3w3jx5XIH7qIOQuWhYH5YG7vQDPO0BlCm466Q==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (475, '报纸', '圣地洗礼铸军魂', '王继荣 ; 刘泉', '科技日报', '科技日报', '红军医院;三湾改编;总医院;参观见学;党指挥枪;当代革命军人核心价值观;井冈山;', '井冈山，中国革命的摇篮，她如一颗熠熠生辉的明珠，镶嵌在湘赣边界罗霄山脉中段，以她独特的魅力吸引着世人的目光。4月27日至29日，解放军总医院参观见学团，在总后勤部副部长兼解放军总医院院长秦银河的率领下，踏上了这片神奇的土地。缅怀先烈、寻访旧址、服务老区人民，一', '2009-05-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M1KmoSJ9w39-b7ttD250l-4POuWi8vu9iV5lu6OqBlBcnJ2p7f-yABe1y4JoSY2GrITEhdATWtjl99o82JZpreksZOVnMsXAMYV_bgmcqZTS-C1N-IjH8sTMWsTo7scCwHeaIyJ-eRdg==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (476, '报纸', '追寻传统之根 筑牢思想之魂', '王梦义 ; 代烽', '解放军报', '解放军报', '当代革命军人核心价值观;党代表;', '本报讯　王梦义、记者代烽报道：4月上旬，为期15天的南京军区新任党支部书记培训结束。460名新任“党代表”通过井冈山寻根之旅，向军区全体党支部书记发出倡议：做党的创新理论的坚定信仰者、政治工作“生命线”的忠实守护者、当代革命军人核心价值观的自觉实践者，让井冈山', '2009-04-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MSgxqPMmwibbgnH9mV01_73dBRd_u_zg0VPkXA4gNRKst0PHNh5TuAnYAs5DatfpM-vHj3fIy732W8XwqlwqbmoBTgUG-obvL1UDYP-sHcUtS0yGTuvWsfYihl7hLkZ6U7Dw7HOGuFsA==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (477, '报纸', '巍巍井冈情意浓', '孙承斌', '人民日报', '人民日报', '胡锦涛;黄洋界保卫战;井冈山革命斗争;劳动模范;吴建中;中共中央书记处书记;', '中华民族传统节日春节到来之际，革命圣地井冈山到处张灯结彩，洋溢着喜庆祥和的气氛。$$ １月２４日至２５日，农历腊月二十九和除夕，中共中央总书记、国家主席、中央军委主席胡锦涛在江西省委书记苏荣和省长吴新雄等陪同下来到井冈山市，亲切看望慰问革命老区干部群', '2009-01-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NjobYVKlXMVO9XBGZFpnyDKt8GZ4vwkliIXZ0pmsYz9OyFt9oZzngCeFPMU-OmDV2XUYzlrnmGCweFGFVxUPTxIxCqMtw8Wa343I_Spga5LfGVqB5E5YehE2IUn9LaWIkke2L5u8CVOQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (478, '报纸', '除夕访井冈,胡锦涛同村民一道磨豆腐', '孙承斌', '新华社;', '新华每日电讯', '胡锦涛;吴建中;黄洋界保卫战;', '中华民族传统节日春节到来之际，革命圣地井冈山到处张灯结彩，洋溢着喜庆祥和的气氛。 $$ 1月24日至25日，农历腊月二十九和除夕，中共中央总书记、国家主席、中央军委主席胡锦涛在江西省委书记苏荣和省长吴新雄等陪同下来到井冈山市，亲切看望慰问革命老区干部群众，', '2009-01-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PGxZFSdnOSKw4vW-7PopO_cYsDb_s0psu11OtrzvBoyvH8TT27TnkoiCKCFVZVixvru0Yv9NAbAY5qRXeRujOISAfbwQi1Q4PZtlimlQ15NED9AYscOBAo4F4IxrvDcv3_voAQq7YXfg==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (480, '报纸', '闪耀红色与绿色的井冈山', '郭海; 张遥', '中国经济时报', '中国经济时报', '井冈山;客家文化;笔架山;客家人;休闲度假;', '这是一片神奇的土地,这是一个令人无法忘怀的地方,这是一座高度没有极限的山岳。这就是传统的红色旅游胜地井冈山。$$  红色旅游,一直以来都是井冈山特色旅游文化的代名词。然而,井冈山不止有红色的历史、红色的文化,更有青山绿水的环境和多姿多彩传统而神秘的独特文化。', '2008-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P2OR4fLy2AupNxsMGHH7vJoTjrwMr6VMHcxcDyEL1qiRxpmyND-tnUpmBR6exLRqVhjCI5VzjZPYsOXWqKN7Wxk_opjR12yWb83JrQpFCRV9UFmItr_WRXdueebLkdHES3LyrirU-P1w==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (481, '报纸', '“真像当年的红军工作队”', '王余根; 徐政武; 周木栋', '光明日报', '光明日报', '民兵应急分队;人武部干部;工作队;', '巍巍井冈,曾是中国革命的摇篮。 $$而今走进井冈山这片红土地,听到最多的,是井冈山市人民武装部官兵在完成多样化任务中续写服务人民的佳话。看着他们走村入户帮助贫困农户奔小康,老区群众由衷赞誉:“真像当年的红军工作队。”$$ 16项重大工程建设勇当“主力军” $$', '2008-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P4KAkSrmVFeqgVpARRsNEwg0AHAEdFDg-razXFOfCUjE0_8w7MpDXOfj90ka-dUwmdpUAlKbu7IKHUYJvK8OcUEIn-j0C_tPi28RLQF4P97ubt9th40pEUGe-hci8AmYAUNlALIW4GcQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (482, '报纸', '井冈山红色旧址成荣辱观教育大课堂', '颜芳明; 刘斐', '中国纪检监察报', '中国纪检监察报', '井冈山;知荣明耻;革命旧址;大课堂;', '本报讯　日前，江西省井冈 山市又迎来了一批“缅怀先烈、 知荣明耻”实践团成员。成员 们怀着无比崇敬的心情参观了 井冈山革命历史博物馆、茨坪 革命旧址、小井红军医院、北 山烈士陵园，并重温入党誓词， 深刻领会“坚定信念、艰苦奋 斗、', '2006-12-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NjdK90UzPNY3lUk1yXKlJeYh1ChOFNn4HGepdkRY_brT7RLyMAcr78LTKfQ-E-CHnCqahm4YCjD5CX7i2mNDj9HL_2yV9yMaM3065dykVCX1ehTfCjXSzl80Mzcla_hTAhR_VYbBFmiQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (483, '报纸', '湘赣边界秋收起义(下)', '', '人民日报', '人民日报', '湘赣边界秋收起义;国民党军;文家市;东门市;工农革命军;', '１９２７年９月１１日，工农革命军第１师按照预定计划，举行湘赣边界秋收起义。$$ 根据中共湖南省委的部署，长沙的铁路工人和部分农民，于９月９日开始分头破坏长沙至岳阳和长沙至株洲段的铁路，一度中断了敌方的铁路运输。$$ 起义开始后，第１团由修水、渣津', '2006-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OW_f_crNZKXxOstuf6tSzFTu0AmzTNr5yOKoJhw4QyddCfGnc6wrAKlK13plpHdAiRQlrwI0G0OJi-oKzU8TIOFexaXDwdJ-QFLFpdye_HZ7L4x74GpkxFdfkRj42O2r938h9US1qhwQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (484, '报纸', '翠色井冈今又新', '刘建林', '人民日报', '人民日报', '井冈山管理局;', '井冈山，中国革命的摇篮。$$ １９２７年１０月，毛泽东率领湘赣边界秋收起义部队在这里创建了我党第一个农村革命根据地。如火如荼的斗争岁月锤炼出宝贵的井冈山精神：“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”。$$ 如今，经过几代建设者的不懈', '2006-06-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MQ7EcZoOIS3HgBeguRXpCsQeLEx_mtIomcnnikbyug3vl3IIHK6SQfCBqQdTR6asOVHLap0LU6G2XBdWfJ7UZISRnYtcBlV_CEBKjQo3Pu1cm7_dAKfdPbiMrAd1qOx1vY4g1EuxGPTg==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (485, '报纸', '弘扬井冈山精神 建设一流气象事业', '喻迎春; 汪慧娟; 邓志华', '中国气象报', '中国气象报', '井冈山精神;气象服务;气象局;秦大河;', '本报讯 10月18日下午，在井冈山 干部学院学习的中国气象局秦大河局长 利用学习间隙，在江西省气象局陈双溪局 长的陪同下，专程来到井冈山市气象局视 察工作，看望慰问基层气象干部职工，殷 切寄语气象工作者要大力弘扬井冈山精 神，继承发扬', '2005-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MVWs3Cu7XgwW8yE7cuTgChjhh1NB2qW5X57cioFiGrrlsDxMNIRIWnssPOhaB6L39MylsKQnyIt98lLS0UM5-zx376nK0cC9anEm2Nd9dDtm9wey0NRI_BS6ulZT-B8mfju9mx71NrzA==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (486, '报纸', '井冈山再掀红色旅游浪潮', '史延廷; 梅柏林', '江西记者站;', '中国旅游报', '红色旅游;井冈山;红色旅游文化;', '本报讯（记者 史延廷 江西记者站 梅柏林）10月15日至16日，2005中国 井冈山红色旅游文化节在茨坪体育场隆 重举行。江西省委副书记、常务副省长 吴新雄，副省长孙刚，全国红色旅游工 作协调小组办公室史学健和吉安市四套 班子的领导出席了10月1', '2005-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4ODAFl6s0jpKDLoi1LWUp3NkKdbfv4yCHmiYwdCtlaK_976qGSkZiGxLBHfbEqhakwDrhRA0oGtOAGZnMpss0jK-RZUrMz6qSC8zXnbeX6_stskiWGBjWL_LRL3KV95DnbjckvsygXb6A==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (487, '报纸', '共同推进红色旅游事业发展', '赵垒', '中国旅游报', '中国旅游报', '红色旅游;旅游业;开发性金融;国家旅游局;国家开发银行;', '本报讯(记者　赵垒)3月11日，国家旅游局和国家开发银行在北京签订《开发性金融合作协议》，双方将以红色旅游的开发建设为先导，实行长期战略合作。这项合作旨在贯彻落实党中央和国务院批准、中共中央办公厅和国务院办公厅印发的《2004—2010年全国红色旅游发展规划纲要》的精', '2005-03-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P_rU1EAKqFIOQzutLkjeJqTBESp5QQD2ssJj7PFgTnaAZtt1b6atGGW9G18bSiYfq6kgdg728iyB9g1yBVchEnUTrkpvM7mTm5gejdogIeHEdTuLREi-6Je2vAitoKos2LEm4gEL4EBA==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (488, '报纸', '红土地崛起“绿色路”', '', '中国经济导报', '中国经济导报', '井冈山市;施工单位;压覆矿产;交通厅;环保理念;土石方施工;征地拆迁;', '$T巍巍井冈山，方圆500里，雄踞湘赣间。$$  这里是中国革命的摇篮，先辈们在此点燃了中国革 命的星星之火，使这里成为传承革命历史的圣地；这里又 是著名的风景名胜区，山高林密，物种丰饶，风光绮丽。$$  为了进一步提升井冈山的政治和旅游资源优势，', '2005-03-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OVc6LWnFE2W0mR_x0QrUChVaYnuzOH491CdMiweUssRL4TqaxwP5sEBBN7nxprQ5WW3-IuFf10lilrPQ_MgDY5iPj6xq5FoIccHTcyQHlVm1pJv4c_z601TsDkWZrcAprlOQPzeEIlHw==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (489, '报纸', '打造品牌推动红色旅游', '陈东有', '江西省委宣传部;', '光明日报', '红色旅游;紧密结合;旅游总收入;红色旅游景区;打造品牌;', '江西在革命战争年代，无数革命先辈和英烈用鲜血和生命谱写了一部气壮山河的英雄史诗，为后人留下了一大笔永远值得学习和传承的伟大精神，也为江西发展红色旅游提供了得天独厚的资源条件。省委、省政府先后于2001年和2002年下发了两个一号文件，明确将旅游业特别是红色旅游作', '2005-02-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PnD89hqN3KTIUUebwM5n_oy3N1BX5-rlDPMiuwzE-jfVRn6eAWae8EM1I0PmxXbhR0lQmCIIVMC4y0mkih37i81OvHj0tDl-pEc86kl_HFuNsIuowGR2SDIsTXCicX4ZQU03R_Ib9K8A==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (490, '报纸', '江西联通为井冈山旅游业护航', '周海华', '人民邮电', '人民邮电', '井冈山地区;旅游业;', '本报讯 近两年来，江西吉安联通克服井冈山地区地势险峻等困难，全力打造精品网络，让到井冈山的参观者和游客享受联通精品网络带来的通信便利。$$井冈山不仅是中国革命的摇篮，也是全国重点风景名胜区，来自海内外的游客和参观者络绎不绝。为了给远道而来的参观者和游客提供优', '2004-09-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NRSHL29KQH9ZRM5grRmEpt4JbEPx9AKvZDCVaNy1O3Y6dZNEFfCfxjk6mRbK7ZT-g4gv1KSxYyz5LlXnvVg0CnbZ-vrL54QsGAWZj_2UQYtMWqXFb5a2W3YL0empLAHl8VgHVFicus1w==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (491, '报纸', '精神的力量', '胡晓军', '光明日报', '光明日报', '井冈山市;', '主峰海拔1586米。它并不算太高，却屹立起了一座中国革命史上令人仰止的丰碑。 $$ 1927年10月至1930年2月。当年在此进行的革命斗争历时并不算太长，却开辟出了一条马克思主义与中国革命实践相结合的光辉道路。 $$ 巍巍井冈山，连着中国共产党璀璨的历史。77年过去，它正', '2004-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PdZRDEZldnSxl4vMhyQXNaFKJ6g_-FZLm9i2sO2Rw79-PZPcyW7jVsIugHp4BaK8md9nh_TXirzkdSrL1DL1ZsrQvs4-LuwBXIgBHgpI0E63HoIm8PsJqCjAybgOnJYt0zsKZfBHzLqQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (492, '报纸', '革命摇篮今亦红', '胡晓军', '光明日报', '光明日报', '井冈山市;革命摇篮;', '盛夏时节驱车上井冈，苍山层林给人带来一片沁人心脾的清凉意境；在山上造访各处革命旧址，所见所闻又让人产生一种激昂向上的炽热情怀。 $$ 有“中国革命摇篮”之称的井冈山，在爱国主义旗帜下，在革命传统教育中，焕发着火红的风采。 $$在红色课堂里成长 $$ 茨坪毛泽东', '2004-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OnjSRADrpLvPVpqPlYNbyDo-hRvKMGuIbW0hn8eZO589isqTv-n6F23A8OynarEJOkuHgDNX-9cRD3OqXeknDXD9CUrj9auhDFPDT-TjDWG9TYL761fCBdrA6qSK_qYUZ03TtoXoPPHQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (493, '报纸', '为了让红旗永远飘扬', '龙小毛', '人民法院报', '人民法院报', '最高人民法院;井冈山革命斗争;', '一曲艰苦奋斗之歌$$ １９６５年５月重上井冈山的毛主席激动而又长时间地对随行人员讲述当年井冈山的艰苦战斗、生活情景，并着重强调，“要更好地建设社会主义中国、更好地建设社会主义的井冈山”，“艰苦奋斗的精神不要丢了，井冈山的革命精神不要丢了”。$$ １９９', '2003-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M0u7IXOBy0fks-SZ9SOSR8g6xGxwxjuXVQQFVXydDF5Z3IGJYiSKrvJU8hMQ_sRlIbuAS4fsYOTic9uwbrQUTZHtDaPNQ3YQ7x3yJOjIWwzkOQ6g7T-vmtp6EqKZQZxon8EqsY27AzSA==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (494, '报纸', '弘扬革命传统　再创井冈辉煌', '王谨', '人民日报', '人民日报', '优势转化;井冈山;吉安市;', '带着井冈山儿女的美好祝愿，当选为中共十六大代表的吕滨即将进京出席党的盛会。盛会前夕，记者在井冈山茨坪采访了中共江西省吉安市委书记吕滨。$$ “能当选为党的十六大代表，是吉安老区党员对我的信任”。吕滨说，吉安人民正以加快发展的实际行动，向党的十六大献礼。', '2002-11-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MhSQvgp7O98qJmfK4zSuHcVpbpro7KU-QKG4YgjnkS4TXvlHF5ju-ov5q-abBgZkOpaMn1yyhT7jrgjnZPTwYP3q2YPQt_DNr25yq1v0HHil4Olnu9XWNS2xyibosFb_WNWLeWaeyhYQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (495, '报纸', '井冈精神是恒久的动力', '周文英', '检察日报', '检察日报', '井冈山市;政工科;', '站在井冈山茨坪，白日 看天特别近，因为这里的修 竹茂林澄净了大气。记者 想，晚上若是在这看星星一 定也很亮。但记者在井冈山 的那个夜晚，下起了瓢泼大 雨，没有星星可看。$$', '2001-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N65X0HKMiLmglX-uBJ-QyLUgfxJRCZiDtHc_qVzHV0SZft7qhj4_zNHsUq5BZE6i65VtfS5Y7WVBlR3ksWBtgozfUEmgNHJCKLUQ6Y46qDBzHiTHEQFuovoPmgXPYqTBDdaQfVwJkmpQ==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (498, '报纸', '追寻先辈学习成才之路', '何鸣鸿; 周猛', '解放军报', '解放军报', '井冈山;毛主席;', '本报井冈山5月9日电：记者何鸣鸿、周猛报道：两天来， 在这里缅怀革命先烈、学习光荣传统的第二届全军十大学习成 才标兵有个意外“发现”：我军官兵学习成才的历程与我军发展 壮大的历史一样漫长，起点就在井冈山。$$  1927年，', '2001-05-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NySRgb-Dl0lclESbY51wYavJVOEnZblMF_WBj_3IUb59iQ-clYI2MFKCEOSqjfUEViE845VhdkXvik07IEgvGg5F_3HB93Q3INDOcB60bQsejZUIlR9liL-h_XP645f_SiFARvhG1wRw==&uniplatform=NZKPT&language=CHS', '茨坪_screened');
INSERT INTO `ds_article` VALUES (502, '报纸', '依法保护运用 让红色资源“活”起来', '王丹', '人民日报', '人民日报', '革命文物;责任人;文物保护;红色文化;“活”起来;红色基因;遗址群;红色资源;', '初春的薄雾下，江西省安福县钱山乡虎龙坪战斗遗址群规整肃穆。 “虎龙坪战斗遗址群进行了重新规划和保护，这是对烈士的告慰!”近日，井冈山革命博物馆原馆长肖邮华再次来到钱山，看到钱山英烈墙已经建起，通往无名英雄墓地的步道阶梯也已铺好，感慨万分。 为加强对革命文物', '2022-03-17 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.002704', '反围剿_screened');
INSERT INTO `ds_article` VALUES (514, '报纸', '以实现中华民族伟大复兴为己任', '陈凤莉; 刘世昕; 张文凌; 潘志贤; 任明超; 王磊; 陈卓琼; 王豪; 邓智勇; 陈慧琦', '中青报;中青网;', '中国青年报', '中华民族伟大复兴;团支部书记;', '连日来，习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话，在广大团干部和团员青年中引起热烈反响，大家纷纷表示，要坚定不移听党话、感党恩、跟党走，不忘初心，勇于担当，为实现中华民族伟大复兴贡献青春力量。$$ 北京二七纪念馆志愿党史宣讲员、北京大学学生石', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.002574', '反围剿_screened');
INSERT INTO `ds_article` VALUES (518, '报纸', '年轻一代在传承与创新路上续写精彩', '张文燕; 朱永康', '中华工商时报', '中华工商时报', '年轻一代;全国工商联;企业家精神;实事求是闯新路;理想信念教育;井冈山;民营企业家;', '编者按：3月27-29日，全国工商联在江西省井冈山市举办年轻一代民营企业家理想信念教育活动。来自全国32个省区市的120余位青年企业家在3天的时间里瞻仰井冈山革命烈士陵园，参观井冈山革命博物馆和井冈山金融博物馆，在小井红军医院接受现场教学，并围绕践行井冈山精神进行座', '2019-04-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NwIEbVc9VrtP5lOhzgyYzVwFVEJOhwlj84pZtklCcR95EOqBG8Xzg8_qfeH-REC5uOiBYaWDvDgoUtBnAWMYQWO0Frj_Bvoeo7jx9J9f2zLDCmDLWO1G_5Y-P1NjlmqfD1L6LWPAJfsw==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (523, '报纸', '学思践悟 坚定信念', '李明征', '中央党校中青一班;国务院法制办政府法制研究中心;', '学习时报', '马克思主义中国化;中国特色社会主义事业;坚定信念;共产党人;社会主义革命;', '重读马克思、恩格斯、毛泽东的经典著作，学习马克思主义的理论精髓，能使人心明眼亮、信念坚定，能使人脚踏中国的大地，为中国特色社会主义事业和中华民族的伟大复兴奋进前行。$$ 马克思主义在中国落地生根是历史的必然选择$$ 马克思主义好比一粒种子，能在中国生根发芽', '2016-11-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P44DrEQKgq4NE_avqltE_XC2ge-zhX5q0xKF5-UrXZGSB7haI1_IHFIbJgxRtPDr5z0HZHD_5l_RjrdcUkKxa4w-sYyjm4q2JyfJzom6PvJUahzwlmxdJRGdDhNNNeX5Zbtbrz7OXcSw==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (526, '报纸', '革命家的真性情和大情怀', '陈先义', '解放军报社文艺部;', '光明日报', '彭德怀元帅;革命家;重大革命历史题材;红五军;井冈山;真性情;红四军;', '近日在中央电视台热播的电视剧《彭德怀元帅》首次将彭德怀的一生经历搬上荧屏，首播当日就获得全国上星频道电视剧收视率第一名的骄人成绩，使重大革命历史题材创作如何获得更多观众青睐的话题成为舆论热点。时下人们精神境界不断提升，对重大革命历史题材的需求与日俱增。从', '2016-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MsrgHIjYk0wnIz7Olp3kHYgES4k22zTazss9v53TmfEHvAHuXmsU6Vj1jAPdqIFlKn9pQDXaMD78Ziri-CB3cXHcgi8q7DWwTsam_ocnkPPhjw6SjF9DGF4pTY1dDDg8Q0lpCc1vHkrg==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (538, '报纸', '陕北红军和苏区主要创建人之一 刘志丹', '', '人民日报', '人民日报', '刘志丹;革命军事委员会;陕北红军;陕甘边苏区;', '新华社西安４月１３日电 今年４月１４日是陕北红军和苏区主要创建人之一、中国工农红军高级将领刘志丹逝世７５周年纪念日。刘志丹逝世7周年时，毛泽东曾亲笔题词：“群众领袖，人民英雄”。$$ 刘志丹，１９０３年生于陕西保安（今志丹）县。１９２１年考入陕北联合县', '2011-04-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MZ5tF42s65lB11ca95NophcyqmpaGRiKExkvlGmJ2geVl2Ts9a-U64JUT7DbmrO9V2HibEjCr_ke2CZyWDhgv_gH2A3s14GQw9nzyeV8fxm0XKCSc9L9rsHb18j0AueOF0gO741CWu5w==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (542, '报纸', '不寻常的红色寻根之旅', '梁申虎 ; 李光辉 ; 傅开强', '解放军报', '解放军报', '大瑶山;枫树坪;黄土铺;支部建在连上;历史担当;', '初秋时节，济南军区某摩托化步兵师奉命挥师南下，挺进西南某演兵场。$$ 这是一支有着光荣传统的英雄部队：师机关和部分部队曾参加了秋收起义、创建井冈山革命根据地、五次反围剿、二万五千里长征，解放战争时期打出了“猛虎师”的威名。$$ 此次远程机动演练，该师官兵', '2009-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P7a_qYCNyCwByFrDAAB36vfUJk_-vVzx-RaQbwblTauUVxy62cgbQpGWM-uhAUEXfeqkXba1cyX7-xQmUsUOoAEwDV_a9wknoxq7t1GoJVxlpY-MZgg7I8qgSzRYV-xC51_hzD16lNvA==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (546, '报纸', '用生命诠释军人的忠诚', '孟斌; 杨继龙; 杨连元', '工人日报', '工人日报', '第一个;党员突击队;胥家镇;炮兵指挥;地震灾区;', '连日来，在汶川地震灾区，上万名群众哀悼抗震英雄武文斌的场面真是让人刻骨铭心。$$ 花圈摆满了都江堰胥家镇中心小学操场，吊唁的人们呈一字长蛇阵，老百姓说：“他是为了灾区群众而活活累死的！”$$铁心为民，恨不得长出千双手$$ 5月12日下午，汶川发生大', '2008-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NmgU0jidJMbYgqIKIEdQo6AYJinHx0C9ihnB1_jGcQRsRcBCooUPqXR0Sd9zPKh4MiD9Pmf5wmE9O5-CSI4LtEYNPF1dkCzSJojEbeIRVONOWKPLI9vUnf0zELvWKM3JiIS9MmBfemEQ==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (548, '报纸', '江西吉安青原区：东井冈如何“红”起来', '郭海; 陈佳丽', '中国经济时报', '中国经济时报', '青原区;东固革命根据地;中国经济时报;江西吉安;第二次国内革命战争时期;红色旅游;', '江西省吉安市青原区，是一块富有光荣革命传统的红土地。在第二次国内革命战争时期，享有“东井冈”之誉的东固革命根据地就创建在这里，也是第一、二次反“围剿”的旧战场。这块红色的土地如何能“红”起来呢？这成了青原领导班子一直在探索的问题。近年来，他们立足本地革命', '2007-10-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NXpwNyJ3KWx8xG0wStMOd63ezvYgsLPi_vbMX6WRTZB248Ct02MleVN8aFRn8euCo3UuGOwQQhXqE0Kv-3oHLSjJJIsVp6IQwYy1byR19TbTbuhOii7GMuzBM6jcSln1q5jjURB3_VkQ==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (549, '报纸', '坚定信念育英才', '李章军', '人民日报', '人民日报', '坚定信念;体验式教学;中国井冈山干部学院;黄洋界;井冈山;', '“山下旌旗在望，山头鼓角相闻……”$$井冈山黄洋界。跨越革命风雨、激情岁月，６月初，中国井冈山干部学院学员、５０多名来自全国各高校的思想政治课骨干教师，满怀激情地朗诵着毛泽东经典诗词《西江月·井冈山》。$$半个多世纪前，这里孕育了中国革命成功', '2007-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Py9pMIR7C-Sq4brjA1Kp6wp28_qdvErB1wyGcqJjnWwlSWirnuLmjzb9ZLJIHwtySmM6lpOzP6euBHXm4xlBUaxP2wxtqo6arQ4b4TQVzGiMnpppZdI5NHYpS62Sf4xIt6yONPPSL73w==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (550, '报纸', '江西吉安县筹资1500余万元兴建“将军公园”', '肖晓林', '人民政协报', '人民政协报', '吉安县;红色旅游;主题雕塑;', '本报讯全国著名的将军县——江西省吉安县积极落实政协提案，筹资1500余万元兴建的“将军公园”，已于“八一”建军节期间正式对外开放。新建成的“将军公园”成为京九铁路沿线的又一红色旅游亮点。$$吉安县是井冈山革命根据地的重要组成部分，赣西南革命斗争的中心', '2007-08-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PAJTFkJKGOZugrrQZnzQUfPmWtN7WkazunSc4hR5O91rb76rCgdokHf2CO16VLWWESlIs_Hfb5bvbQiAhVr_vFxMzHvlmRQ86Oa2YxWGDxqVQIsMMmp14AJrfpK1YFNChwXTEKlib2mA==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (553, '报纸', '江西吉安县兴建“将军园”', '肖晓林', '光明日报', '光明日报', '吉安县;主题雕塑;红色旅游;井冈山革命根据地;', '本报讯　全国著名的将军县——江西吉安县兴建的“将军园”将于今年“八一”前夕正式对外开放。 $$ 吉安县是井冈山革命根据地的重要组成部分，赣西南革命斗争的中心，第一、第二次反围剿的主战场。吉安县诞生了余秋里、肖望东等46位共和国开国将军，其中，中将13名，少', '2007-03-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PoCka6RZF5lsOgdJqm4Zraj833ZRc13qaEp3kKB268M-n15OHqj2mrzdkD7dzkbgQcGHzb0vKNB-lKufod_9EIC2kCGsRGXC7oBzBafn1NbdcRsAidmsl3C8-PlQ0FWfV8sNffeSGyOA==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (556, '报纸', '游击战争“十六字诀”', '', '人民日报', '人民日报', '游击战争;中国工农革命军;前敌委员会;十六字诀;', '１９３０年１２月，在中央苏区第一次反“围剿”期间，中共红一方面军总前委在宁都县小布召开苏区军民歼敌誓师大会，会场两边贴着：“敌进我退，敌驻我扰，敌疲我打，敌退我追，游击战里操胜算；大步进退，诱敌深入，集中兵力，各个击破，运动战中歼敌人”的巨副对联，生动地', '2006-08-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PSAlmY0fXbGiMSfbJA9dA67QfdnXDdgdozjsDI-y0AKQ7lUGp6a7uzGH6PlWiwar_-4Df4FY3P9RlEmMkooaTqxXkerG6ybd1J_fSmoWYfolDsLXDjX2jOsm-9uaa9DjR5KT5cVnqosA==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (557, '报纸', '王良', '', '人民日报', '人民日报', '张辉瓒;国民党军;', '王良是中国工农红军建军初期的著名将领。原名王化赅,字傅良。1905年生,四川綦江人。1924年考入上海持志大学学习,开始接触马克思主义。1926年到广州入黄埔军校第5期学习,他先学步科,后学骑科,成绩优异。1927年加入中国共产党。 蒋介石发动四一二反革命政变后,王良所在的武', '2006-04-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PcUd7fM_SZFjwRF80KiEjyaZmTcW2bKMqz6Q2h7J4HHtmA6SGUJ9IJS6sHEI-f1jX80aN1a0wQhHy8wrDMdi873bmTY7gptFwJQ1jYhmurCCSjMCQDAFL4slzVo6XC66fVl-6ss3Yt5Q==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (560, '报纸', '贺昌', '', '人民日报', '人民日报', '中央苏区;中国工农红军;', '南方三年游击战争的主要领导人陈毅在《哭阮啸仙、贺昌同志》一诗中沉痛地写道：“环顾同志中，阮贺足称贤。阮誉传岭表，贺名播幽燕，审计呕心血，主政见威严。哀哉同突围，独我得生全。”表达了他对贺昌等同志的敬佩与怀念。$$ 贺昌是中国工农红军高级指挥员。1906年', '2006-03-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O6MVd3fy2O5CXjLiNdnsWFp8CUr8Ob1hRtxFwRqCo5-y2QSHigFsdkcAf8sSnCiqrGCrhQnYm6hSPfuoaqZDEs59Bd3PQgFo_UuWZ8bOZP1uV9xL6PDygkeWFBO8cY0Nr7QoBI7pqRHA==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (561, '报纸', '梁鸿钧', '', '人民日报', '人民日报', '梁鸿钧;国民党顽固派;', '梁鸿钧，1905年生，湖南湘潭人。因家境贫寒，少年时逃荒到广西钦州做工。1921年在广东军阀邓本殷部当兵。1925年冬离开原先部队，加入国民革命军第4军，后参加北伐战争。1927年随部参加南昌起义。起义部队南下广东失利后，随朱德、陈毅转战于闽粤赣湘边，上了井冈山。1928年冬', '2006-03-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OBqFpsHpjo9zoQvzPwdZirZHf0x32g69wRA1EQSj9kxiIunLspxcI5jJIlqPOchOX-GQZFjB-RkqUdwI2fY6KcvuukJOp-JO8nG4YDquUM6PC-cf5HNkwekIzIOPBR_riwFYkiPqRHMg==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (562, '报纸', '曾士峨', '', '人民日报', '人民日报', '曾士峨;国民革命军;', '曾士峨，1904年生，湖南益阳人。1923年入益阳信义大学，开始接受进步思想。1924年到长沙，参加反帝爱国学生运动。1925年入黄埔军校长沙三分校学习。同年6月加入中国共产主义青年团。1926年入国民革命军第8军独立1师学生队，同年转入中国共产党。参加了北伐战争，在国民革命军', '2006-02-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PDkB5KNA7E-XKyC_e3C2PGUO0Uij5gS3zV4CfmphU2yRsNfwy_TkMLbXAREQVkL3Is89ckwwNYUGIrcqYW4o6gDhfb4LANUlPHLHCGNhW0YROTUYha7iKZAFIh_cw_uMHrE4ouw85zxw==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (563, '报纸', '朱云卿', '', '人民日报', '人民日报', '朱云卿;红四军;第一次反“围剿”;', '朱云卿，1907年出生于广东省梅州，1921年随叔父到印度尼西亚打工，1924年回广州，考入黄埔军校第三期，参加军校进步组织“青年军人联合会”。1925年10月，朱云卿参加讨伐反动军阀陈炯明的第二次东征，在战斗中机智英勇，受到周恩来的赞赏，同年加入中国共产党。$$ 192', '2006-02-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OOVx3XEF1nr3PKyhfapHrSsan9v2Bi1D0ZwxjfMvWgVnN3YwphqsXeJihaxHPYszIZwSX61cr4aUEc_0ogZlFmCpQJ3XYv7yPHYGsX_nBKUDA9gvZOkPDIbaQfVXVp9trFSxD5anwpKQ==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (565, '报纸', '王麓水', '', '人民日报', '人民日报', '王麓水;抗日根据地;', '王麓水是八路军高级指挥员。1913年生，江西萍乡人。1926年加入中国共产主义青年团，在家乡参加农民运动，积极完成党指派的革命工作。1928年，萍乡党组织奉命把从井冈山送来的一大批黄金送交安源市委，用于到长沙购买药品。王麓水自告奋勇，装扮成卖米的商贩，巧妙地越过国民', '2005-11-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MnriEcF1fHlxQamWvYCUo9R4ULosw_P3zTVNFWEzSaHqMIwO4810gA4lxj0isPySj28V300xV8OO4ykHOecR06VNx1sVLuXk9odOuf_BqrRr0qG_wD8faEJSEgqZAIzdN5GTLoAeT5hw==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (566, '报纸', '粟裕', '', '人民日报', '人民日报', '抗日根据地;', '1984年1月25日，粟裕在中顾委举行的春节茶话会的书面发言中坚定地说：“共产党人的气概，从来都是知难而进的。”“我对于马列主义、毛泽东思想的伟大真理，对于中国革命和建设的光辉前途，对于共产主义事业的美好未来，是满怀必胜的信念的。”$$ 粟裕是中国人民解放', '2005-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NpC9eKeimzQsoKGAI-9a_flhXFd0v6rlt3sI-RmOcHtIPbuOtPJCSGHwY8JFlib8kGXWhwA1UgvPjf2HXiySffxUGqKTZag-A8GAQFWWDXpc_x4zol8SZUL_9nOwC8fzp1BohcmSLoPA==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (567, '报纸', '周子昆', '', '人民日报', '人民日报', '周子昆;新四军;中央苏区;', '周子昆是中国工农红军和新四军高级指挥员。1901年生，祖籍湖南，出生于广西桂林。早年曾参加五四运动。后入桂军刘震寰部当兵。1925年6月投身革命，入孙中山的建国陆海军大元帅府铁甲车队，任班长，同年10月加入中国共产党。11月被编入叶挺独立团，任排长。1926年随军北伐，参', '2005-06-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P0DowKT0SiPkGs_pGwxPrApMpdpyY7NgLgOgAX8LlmnLSSTWSHX1btT_1wKjPcIX9BxBNQ5RnOsU_c1D8mFN82Rwc0PD4HQNkZQNwjuPzMljz-ZyYOp3sIPAArPwhrLaT_-cnLuxI7_w==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (568, '报纸', '一生的红色记忆', '蔡洁璐; 王绍雄', '光明日报', '光明日报', '井冈山;', '这是一群活跃在井冈山红色土地上的浙江学子。从1月14日到1月23日，短短10天时间里，23名浙江师范大学的学生以“三个代表”重要思想为指导，追寻着红军的足迹，走进老区，走进农村，开展了一系列社会实践活动。$$ 重温井冈山精神$$ 实践队怀着对革命志士的敬仰之情参', '2004-02-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pk-lDnUG2pNQU8hsXuuJFRoq9GGF7hiTtJdeVDLG2FYUaBUroJhXakHr-QdovaefibYQV-TozRVrj1sJsAavl7pq_Xje70u53KKTbSbMDA8y5dxFn9mhZmcNLpe0bV22X4TKJHLRw4eA==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (570, '报纸', '红旗还能打多久？', '', '中华工商时报', '中华工商时报', '世界投资报告;', '早在井冈山时期，年轻的红军将领林彪面对第四次反围剿的失败产生了悲观失望的情绪，发出了“红旗还能打多久？”的疑问，毛委员的回答就是那篇著名的“星星之火，可以燎原”。$$ 现在中国股市的上上下下也弥漫着一股悲观失望的情绪，边缘化的讨论就是这种情绪的反映，只', '2003-09-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MqubHXj_u_l2aokBiGgj9WuE9gKLeikBoYjfb9ntshQuwH-58xSMNVAEYlUYPw6p5HlKIKSkV1J9bi1s6Tm5hjQeHDdzZ0fqQlKI7PIyBQdjpUwTbwrByqZEyg06wQv9HU4PqE8I5wsQ==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (573, '报纸', '毛泽东与建军及“八一”纪念日', '李南俊', '人民政协报', '人民政协报', '毛泽东;秋收起义;南昌起义;', '（一）$$  众所周知，中国共产党领 导的军队诞生于1927年8 月1日的南昌起义，即这天根 据中共中央决定，周恩来、贺 龙、叶挺、朱德、刘伯承等领导 的国民革命军约两万多人在', '2002-07-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PA4HzmuI3hXZXWswfzW7_-8r1beZUiv__KN7miblTYf-qC0V_zleDFAw74div4DVTe408pi9kInCAtqa_kgKxKuDM78cvQdgIvtbN3UPNMZjg4MmERepjngHMStnU2KBay33fcQnOHeQ==&uniplatform=NZKPT&language=CHS', '反围剿_screened');
INSERT INTO `ds_article` VALUES (578, '报纸', '送别“老阿姨”龚全珍', '赖星', '新华每日电讯', '新华每日电讯', '老阿姨;甘祖昌;悼念厅;莲花县;殡仪馆;', '9月7日，江西省萍乡市莲花县。人们或是手持菊花，或是举着悼念横幅，从清晨就站在县殡仪馆至甘祖昌将军墓的沿途，等待送别“老阿姨”龚全珍。 67年前，龚全珍跟随丈夫甘祖昌从新疆回到他的故乡莲花县，共同谱写了“并蒂莲花初心红”的佳话——甘祖昌不当将军当农民，扎根乡', '2023-09-08 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.005500', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (579, '报纸', '“言传身教就是给子女的传家宝”', '郑少忠; 朱磊; 周欢', '人民日报', '人民日报', '甘祖昌;莲花县;', '9月2日16时16分，开国少将甘祖昌的夫人、第四届全国道德模范、全国优秀共产党员龚全珍同志逝世，享年100岁。 从66年前毅然随夫返乡务农，到成为全国道德模范、全国优秀共产党员、最美奋斗者，龚全珍从未忘记过她和丈夫甘祖昌的信念：“每天都认认真真全心全意为人民服务。”', '2023-09-06 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.009069', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (580, '报纸', '“老阿姨”走了，留下无尽的精神力量', '刘旭; 林涵', '中国妇女报;', '中国妇女报', '老阿姨;精神力量;中国妇女报;', '被习近平总书记尊称为“老阿姨”的龚全珍走了。 2023年9月2日16时16分，全国三八红旗手标兵、第四届全国道德模范、全国优秀共产党员、“最美奋斗者”称号获得者龚全珍，因病医治无效，溘然长逝，享年100岁。 讣告刷屏网络，无数人心痛落泪。在江西，各界干部群众深切缅怀“', '2023-09-04 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2023.002521', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (581, '报纸', '在推动中部地区崛起上勇争先', '郑少忠; 朱磊; 王丹', '人民日报', '人民日报', '江西省;富硒蔬菜;产业园;习近平总书记;中部地区崛起;产业链;红色基因;', '巍巍井冈山，滔滔赣江水。满山的杜鹃红了，遍野的秧苗泛着青绿，赣鄱大地生机盎然。 党的十八大以来，习近平总书记两次赴江西考察调研，参加十二届全国人大三次会议江西代表团审议，对江西提出“努力在加快革命老区高质量发展上作示范、在推动中部地区崛起上勇争先”的殷切', '2022-06-08 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.005987', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (582, '报纸', '谱写璀璨的奋斗篇章', '杨昊', '人民日报', '人民日报', '麻风病;奋斗者;建档立卡;吉根乡;讲解员;抗抑郁;', '近日，中宣部、全国妇联评选出10名“最美巾帼奋斗者”。她们是中国女性的先进代表，向社会传递了爱党报国、信念坚定的政治品格，展现了自尊、自信、自立、自强的巾帼风采，在新时代的广阔舞台上绽放芳华，谱写了璀璨的奋斗篇章。 助力乡村振兴：“把学会的知识为祖国和人民', '2022-03-07 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.002389', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (587, '报纸', '感悟思想魅力 汲取前进力量', '李小豹', '江西省萍乡市委;', '中国组织人事报', '习近平总书记;中国特色社会主义;全面从严治党;', '以革命先烈先辈为镜，更加坚定自觉把革命老区信念坚定、对党忠诚的红色基因代代相传，坚持不懈把习近平新时代中国特色社会主义思想深化为永恒的价值认同、稳定的情感归属，真正将理想信念植入灵魂、融入血脉$$ 面对艰难险阻，唯有始终保持“乱云飞渡仍从容”的战略定力，坚', '2020-08-26 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2020.002540', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (588, '报纸', '凝聚民族复兴的精神伟力', '罗争光; 熊丰; 王思北', '人民日报', '人民日报', '习近平总书记;民族复兴;社会主义思想道德建设;崇德向善;模范人物;', '伟大时代呼唤伟大精神，崇高事业需要榜样引领。$$ 党的十八大以来，以习近平同志为核心的党中央高度重视社会主义精神文明建设特别是思想道德建设，对加强立德树人、以文化人等各项工作作出一系列重要指示，对表彰道德模范、开展学习宣传道德模范活动等提出明确要求，推动社', '2019-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NdW9yGDC69rSmjN0Ks18tnxsKNXKKhLHe3U1tHIyapKi1nuJR1J27EsSZZ2XpJHNJ14Dsgjgi964WBkA1M2aB5BqEajs9JG3j8YMTdeV5ZovQsvRHqZ4Qpi_QfrTee67_jwMtwKt7wyg==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (589, '报纸', '初心照亮征程 奋进成就梦想', '李自强', '中国纪检监察报', '中国纪检监察报', '甘祖昌;共产党人;吴金印;', '一个人，如果没有远大的理想，就会碌碌无为；一个政党，如果忘记为之奋斗的初心，就会迷失前进的方向。$$ 中国共产党人是理想主义者，始终不忘初心，沿着理想信仰指引的方向奋勇拼搏；中国共产党人也是现实主义者，始终直面时代，不断克服艰难险阻成就辉煌。我们所处的时代', '2019-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PO8MJyvg0pOcpO18YpkamXrW6DtanQ7rSvwPodXtbRw2D8oVSnIpVNq9ZPJ8BoytnTGGKsGXYCW4bPicUXtkiyPa2JvAcoEC0Cta7xmUEPTtzZxmsi646qxl752TkxAM3EJVNqV0xLjA==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (590, '报纸', '这个瞬间何以感动国人', '', '光明日报', '光明日报', '习近平总书记;全国文明城市;未成年人思想道德建设;', '11月17日，新闻联播的一个镜头刷屏网络和微信朋友圈。这天上午，习近平总书记在人民大会堂亲切会见新一届的全国文明城市、文明村镇、文明单位、文明校园，未成年人思想道德建设先进工作代表和全国道德模范代表，当看到93岁的中船重工719研究所名誉所长黄旭华、82岁的贵州省遵', '2017-11-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P8zyiQ_tmz3w3WOqD7Mqo3de6BrYfyHJHybtyUGMZ8hH-1XgR1839dBbBI04dp3fzySKeSaAOODaOUv1CeftowyubD1pLeVfHN4VU8HxNEeU5edL8tZPeyVSxUY6fVIV05M-7U6pU-qw==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (591, '报纸', '传承信仰的力量', '胡军', '江西省上饶市委组织部;', '中国组织人事报', '对党忠诚;榜样学习;', '共产党员是什么样子，共产党人有什么特质，近日播出的专题节目《榜样》，生动诠释了优秀共产党员的风采，不仅让人们看到了合格党员的标杆，更从榜样身上感受到了信仰的力量。$$ 信仰来自对党忠诚。从开国将军甘祖昌夫人龚全珍的初心，到当代军人刘锐的忠诚；从87岁高龄“行', '2017-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OueGCtJL1jURrWi4ftIkEGQWG1KKRRKuy6ZELYcKpLA3Av-4kVNnrpxygoAacOQbPth8IjKbUvaf6f7S31t4DytVgl2cPQf8cp2lAVJ8EpJH1nbTo5_sKNGz0dwcOoMne-qyEghb0r7w==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (592, '报纸', '我们的“老阿姨”，我们奋斗的力量', '李小豹', '江西省萍乡市委;', '人民日报', '习近平总书记;', '每次品读《本色》，我总能感受到一股力量始终在推动我和我们这座城市发展前行，激励我们去攻克一个个困难、实现一个个突破$$ 2013年5月28日人民日报刊登了长篇通讯《本色——甘祖昌将军夫人龚全珍的故事》。我一直把这张报纸压在办公桌玻璃板下，当作引领我思想和行动的宝', '2016-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PURmzZ51peWVd3BlK6HABs-gT5Kd0Pl4_Svq2141hm74-NxFGxWwS9nw_fEJ5ICU1KkdEa_NzvfQKKkC9M_xdjev1xdvqzD6XDKpt8YOxRi0BZHlOpVf18_z_lMVhK2muTGsP1B8uO7A==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (593, '报纸', '党员身份是一辈子的坚守', '张磊', '中国纪检监察报', '中国纪检监察报', '党员身份;党章意识;', '党员身份不是一阵子的坚持，而是一辈子的坚守。每一名党员都应以一生的忠诚和执着，传承共产党人大公无私、艰苦奋斗的优良作风，演绎清正廉洁、奋楫争先的时代强音。$$ 日前，有媒体刊发人物通讯《印在139级台阶上的足迹》，讲述了湘潭大学原纪委书记曾子其退休19年坚持做', '2015-06-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Nuu3XF3baaLA3EDeiC92GQSmV94OsAE-bhxxn_8uOH7A54JUGGJovyYS1PdvJXR9DXAG2c0dqL3w91NleBegKuJRyxuQ4cKciHBtkwmoWuaPHVSJHZ2d3sSTSV_8e7-co1xUCAOHxhXQ==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (595, '报纸', '伟大时代呼唤伟大精神', '胡晓军', '光明日报', '光明日报', '共产党人;人生哲学;伟大精神;甘祖昌;政治本色;共产主义;无私奉献;知识女性;党性修养;利益观;淡泊名利;时代呼唤;', '本期主题$$ 在全党上下深入开展群众路线教育实践活动的日子里，有一位耄耋老人的先进事迹感动着人们，她就是已故开国将军甘祖昌的夫人龚全珍。半个多世纪里，龚全珍以平凡而朴实的言行，忠实地诠释了共产党人对理想的追求、对信仰的坚守和对事业的执著。今年九月，习近平', '2013-12-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N72sUGrf-5_b3lQYXD7uF-AthHGFqgkLMSwBziRuTYTAP7oXVh_6_A5FyAZq9-xXUr9X1okuI-SyKzIauNFUo_RsMq2WcdXcoTuOZb5-eDtCgAW7tcjpv1dvYENjcGCy8VpjnjJiL_ew==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (596, '报纸', '龚全珍同志先进事迹报告会报告摘编', '', '中国妇女报', '中国妇女报', '甘祖昌;永不掉队;先进事迹报告会;', '龚全珍的三次选择$$ 报告人：中共莲花县委书记 夏兴$$ 在龚老普通而不平凡的历程中，对我教育最深的，是她人生里的3次选择。$$ 龚老的第一次选择是，跟定共产党，参加解放军。$$ 1923年，龚老出生在山东烟台一个工人家庭。14岁那年，日本侵略者入侵山东，她的三', '2013-11-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O1Xx8GU058RwBWRrSaA6ttQIQQdVpkkAfcaIjwAYTmhp69B-2ZCXkxjKAFOPy4IQSckqtjhVmyqXku6tpnC_K2jSixORLQb-uAC7y99rDjUFv7Tj3Bx6jI7cxoEnEJIRz4p6IEqxfG0Q==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (597, '报纸', '一位永葆本色的共产党员', '', '光明日报', '光明日报', '共产党员;物质生活;甘祖昌;', '编者按$$ 她是将军夫人，却始终甘做一名普通的教师，一辈子坚守信仰，一辈子热心教育。她已过耄耋之年，但一颗为民的赤诚之心，却依然年轻……11月6日，由中组部、中宣部、全国妇联、中共江西省委共同主办的全国道德模范龚全珍同志先进事迹报告会在人民大会堂举行。报告团', '2013-11-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NYgQfZM02MPxUa6orUdeH2N8eUQ6F2oWrRayejuqNGPMWRbwdQI2ETYUi6bS2sCiyguh9T-1Ihomjv7l0o9oh60M5g39TLRzSmXCA3Rgi4hAesNy747X3mpKvGArKK78mkSyokI42e-w==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (598, '报纸', '“三个尊重”倡导良好风尚', '', '人民日报', '人民日报', '习近平总书记;', '“我再次向龚老前辈表示致敬！”9月26日，习近平总书记在接见全国道德模范时，饱含真情地介绍老将军甘祖昌的夫人龚全珍老人，深情回忆起这位江西老红军、新中国的开国将军回家当农民的故事，高度赞扬年逾90的龚全珍同志始终保持这种艰苦奋斗精神，强调要把这种精神一代一代传', '2013-09-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pzm061lHXQUOfLzMgNFw42h8SIJBOdj8obpPZBPlmeLU-lCBI23soyVrKR6YtyHhYyUVIaA7ek6jRnyjlV4EC7DqUTmZE2KT-fgfgtZ27XFmLKy8_RZEDfIuckrxVB527LHn5egjoS0Q==&uniplatform=NZKPT&language=CHS', '龚全珍_screened');
INSERT INTO `ds_article` VALUES (601, '报纸', '英勇奋战 屡建战功 卢德铭', '', '人民日报', '人民日报', '卢德铭;毛泽东;', '据新华社北京３月２日电 １９２７年９月２５日，毛泽东率领的秋收起义军在向井冈山进军途经江西萍乡芦溪县时遭到国民党军伏击，总指挥卢德铭在战斗中英勇牺牲。得知这一噩耗后，毛泽东痛心疾呼：“还我卢德铭！”$$ 卢德铭，又名继雄，字邦鼎，号又新。１９０５年生', '2011-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M6-QBJEPlJWwC-PYTJ5sgIj1ne3R4ESANqY1gA5x8Ka5N9KO2tesafX5rs_ZCTC-a26Xfs7WGrPeh0knh_b31rMIdWeJcIPN175d619YsOzMEnzKGzOuxhXhhQ_QHGlZQPKzx4s00htA==&uniplatform=NZKPT&language=CHS', '何挺颖_screened');
INSERT INTO `ds_article` VALUES (602, '报纸', '井冈山会师(上)', '', '人民日报', '人民日报', '井冈山会师;毛泽东;南昌起义军;湘南特委;工农革命军;', '１９２８年４月下旬，朱德、陈毅率领由南昌起义部队余部和湘南农军组成的工农革命军，与毛泽东率领的湘赣边界秋收起义后组成的工农革命军在井冈山胜利会师。为了纪念这次具有伟大历史意义的会师，朱德曾赋诗道：“红军荟萃井冈山，主力形成在此间。领导有方在百炼，人民专政', '2006-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OLnT_35AFDK893zm2q_m3qo6gHDHw0_yvAYifGRpuBqHTjl7KPPD3eVY40NitF5-tJStr6Pbd1LpdSjc311BWfxW-fgbnYpKC3Z59gaiM7JKFnPEU7xI3hiV1xUahILH3FtWwNjdT6rw==&uniplatform=NZKPT&language=CHS', '何挺颖_screened');
INSERT INTO `ds_article` VALUES (604, '报纸', '朱云卿', '', '人民日报', '人民日报', '朱云卿;红四军;第一次反“围剿”;', '朱云卿，1907年出生于广东省梅州，1921年随叔父到印度尼西亚打工，1924年回广州，考入黄埔军校第三期，参加军校进步组织“青年军人联合会”。1925年10月，朱云卿参加讨伐反动军阀陈炯明的第二次东征，在战斗中机智英勇，受到周恩来的赞赏，同年加入中国共产党。$$ 192', '2006-02-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MSjsEzE3fq0OC_xv5fQf39TFAyZ4uzrAq5OW5UasB--dcZy5ZjFZVbwcgV9W5TTuiA_TSAyp_Ga8niSEpgznQhLXqdJVsVVOo-teYXGrLMDhpgzQg6ZFLgjTDigI-zDufymlJprhF1Ug==&uniplatform=NZKPT&language=CHS', '何挺颖_screened');
INSERT INTO `ds_article` VALUES (605, '报纸', '一路奋进 一路转型', '贺逸舒; 陶然', '解放军报', '解放军报', '红一连;开辟通路;新装备;', '你人生中最重要的台词是什么？相信每个人都有自己的答案。 胡贯蕾的答案是：“我是红一连第49任连长。” 每当这句话脱口而出，胡贯蕾总能感受到一种自信的力量。 今年，红一连组建95周年，胡贯蕾担任红一连连长第3年。从刚上任时的手忙脚乱，到如今的游刃有余，胡贯蕾越来', '2022-08-25 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.004620', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (606, '报纸', '走进精神之源 补足精神之钙', '陈妙然', '中国新闻出版广电报', '中国新闻出版广电报', '《光明日报》;中共一大;中国共产党成立;习近平总书记;共产党人;坚持真理;千秋伟业;', '在庆祝中国共产党成立100周年大会上，习近平总书记话语铿锵：“一百年前，中国共产党的先驱们创建了中国共产党，形成了坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民的伟大建党精神，这是中国共产党的精神之源。”首次提出并深刻诠释了“', '2022-01-18 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.000169', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (607, '报纸', '中国共产党现存最早的入党誓词', '', '学习时报', '学习时报', '入党誓词;毛泽东;中国共产党;入党宣誓;', '入党誓词是中国共产党党员的宣誓书，是每名党员加入中国共产党时对自己作出的严格要求，对党作出的自我保证，对人民作出的庄严承诺。在不同的历史时期，中国共产党的入党誓词内容不同。$$ 在中国共产党历史展览馆，陈列着中国共产党现存最早的入党誓词，这就是江西永新农民', '2021-12-10 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002333', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (609, '报纸', '对党忠诚 高举旗帜阔步前行', '付静', '人民公安报', '人民公安报', '公安队伍;公安民警;高举旗帜;', '历史，总在一个个重要时间节点中被标注，又在一个个里程碑中启航。$$ 2021年7月1日，中国共产党百年华诞，是时间的刻度，更是奋进的标尺。$$ 百年的波澜壮阔与令世界瞩目的伟大成就，给出了“没有中国共产党，就没有新中国，就没有中国特色社会主义”的“历史答案”，揭示', '2021-08-09 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.004390', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (610, '报纸', '井冈山精神跨越时空闪耀光芒', '赖永峰; 刘兴', '经济日报', '经济日报', '井冈山精神;井冈山革命博物馆;习近平总书记;', '中国共产党始终把共产主义远大理想写在旗帜上，将马克思主义作为根本指导思想，并将其与中国具体实际相结合，引领革命向着胜利方向前进。井冈山斗争就是在这一理想信念引领下进行艰苦卓绝奋斗的光辉实践。$$ “井冈山是中国革命的摇篮。井冈山时期留给我们最为宝贵的财富，', '2021-07-24 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005541', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (611, '报纸', '井冈山精神：星星之火从此燎原', '张弛', '中国纪检监察报', '中国纪检监察报', '井冈山精神;红军战士;', '盛夏时节，黄洋界山头云雾弥漫。举目四望，群山起伏，层峦叠嶂。这里，就是位于湘赣边界罗霄山脉中段的井冈山。$$ 在这片红色的土地上，中国共产党人建立了第一个农村革命根据地，开辟了“农村包围城市、武装夺取政权”的革命道路，回答了“中国的红色政权为什么能够存在”', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003508', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (613, '报纸', '特色文化创演燃旺精神火炬', '吴浩宇; 牛涛; 钱晓虎', '解放军报', '解放军报', '党史学习;特色文化;', '“在掩护第11纵队医院后撤任务中，我连官兵英勇阻击了敌人40多个小时的轮番进攻……”前不久，在海军陆战队某旅“一等功臣连”俱乐部里，一场党史情景短剧上演，反映的是该连前身部队在淮海战役中的战斗事迹。$$ “情景剧生动再现当年战史，官兵更容易接受和理解。”该连所', '2021-07-13 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004438', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (614, '报纸', '信念的力量指引胜利', '周玮; 高皓亮; 赖星', '新华社;', '新华每日电讯', '井冈山革命博物馆;井冈山精神;井冈山革命根据地;共产党人;习近平总书记;', '井冈山八角楼前，一棵在石下萌芽扎根的枫树竟把石头撑开，历经90余载风雨依然高大挺拔。$$ 中国共产党历史展览馆里，一盏红军在井冈山使用的油灯，映照中国共产党人百年不变的初心与信念。$$ 循着百年大党的精神之源，让我们聚焦中国共产党精神谱系中这个重要的红色坐标—', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005327', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (615, '报纸', '藏在红布里的誓词', '', '中国纪检监察报', '中国纪检监察报', '入党誓词;永新县;', '“牺牲个人，言首纟必蜜（严守秘密），阶级斗争，努力革命，伏（服）从党其（纪），永不叛党。”这份有错别字的入党誓词，出自一位普通农民贺页朵之手。如今再看这份泛黄的入党誓词，我们看到的是一张勇敢无畏的面孔、一颗对党的赤诚之心、一份一以贯之的信仰。$$ 90年前的', '2021-05-04 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.002096', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (616, '报纸', '从党史中汲取干事创业养分', '何雪雪', '北京市纪委监委驻市文化和旅游局纪检监察组;', '中国纪检监察报', '干事创业;纪检监察干部;', '学习党史，读到毛泽东只点一根灯芯，在昏暗的灯光下写出《中国的红色政权为什么能够存在？》等光辉著作时，我深受触动，不禁感慨，学史明理、学史增信、学史崇德、学史力行，只有不断从党史中汲取养分，转化为干好工作的内生动力，才能知责于心、担责于身、履责于行。$$ 我', '2021-04-20 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.001819', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (618, '报纸', '一位农民的入党宣誓书', '尹龙乔丹; 刘兴', '井冈山革命博物馆;', '经济日报', '入党宣誓;入党誓词;', '在井冈山革命博物馆展陈的众多藏品中，有一份特别的入党宣誓书。这份写在布条上的宣誓书，展现了一位普通农民灵魂深处坚定的革命信念和对党的忠诚。 那是1931年1月25日寒冷的深夜，一座简陋的榨油坊内，永新县东南特区党委工作人员郑重地把党旗挂在墙壁上，这一刻成为贺页朵', '2021-01-25 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.000934', '贺页朵_screened');
INSERT INTO `ds_article` VALUES (621, '报纸', '讲好红色故事 迸发时代活力', '吴艳丽; 马苏薇', '人民日报', '人民日报', '壁画创作;红色精神;建筑空间;中共一大;艺术创作;艺术表达;城市更新;创作者;艺术语言;', '在献礼建党百年的艺术创作中，红色壁画是一个亮点。近年来，从城市到乡村，从馆内到室外，越来越多的红色壁画涌入大众视野，以厚重的文化内涵、精湛的艺术语言，向人们生动讲述红色故事、彰显红色精神。红色壁画如何以新面貌点亮公共空间？一些新老作品，提供了有益的启示。$', '2021-09-26 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.010216', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (624, '报纸', '开辟革命新道路', '高中华', '中央党校(国家行政学院)习近平新时代中国特色社会主义思想研究中心;中共党史教研部;', '解放军报', '毛泽东;新道路;八七会议;', '1927年大革命失败后，神州大地陷入一片白色恐怖。新生的中国共产党遭受成立后从未遇到过的严峻考验，中国革命处于命悬一线的紧要关头。$$ 死亡和屠刀吓不倒真正的信仰者，腥风血雨只能让共产党人更加笃定信念、冲破暗夜、勇毅向前。$$ 面对严酷斗争和血的教训，我们党认识', '2021-04-13 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.002293', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (625, '报纸', '朱德的手电筒', '张少华', '福建省平和县纪委监委;', '中国纪检监察报', '南昌起义军;手电筒;国民党反动派;三河坝;', '福建省平和县秀峰乡福塘村村民朱林生家里珍藏着一把锈迹斑驳的手电筒。手电筒为铝制外壳，柄长31厘米，头部直径8厘米，尾部直径5厘米，可容三只干电池，这是伟大的马克思主义者，无产阶级革命家、政治家和军事家，中国共产党、中国人民解放军和中华人民共和国的主要缔造者和', '2018-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MCFDTZ1hneeLfK9ErvShLUN8Mw8xaxCEFnCVjQQwZGYgK0DgBYbDUsQmXlK_enTlRzW30CQjKR0tTr8hQeAj6oVRWqDWg_cNscJZiOxk6-wmRx3AxQ5uV_-fMP9sUxtRycPyYFjmk8Uw==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (627, '报纸', '人民军队建设史上的重要里程碑', '', '总政治部办公厅编研局;', '解放军报', '红四军;毛泽东;军队建设史;“九月来信”;古田会议精神;', '古田会议，即中国共产党红军第四军第九次代表大会，于1929年12月28日至29日在福建上杭古田镇溪背村曙光小学（原廖氏宗祠）召开。这次会议虽然只是红四军一次党内会议，但由于它系统地、创造性地回答和解决了当时党和军队建设面临的一系列根本性方向性全局性问题，因而不仅对', '2014-10-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PV7_l4wrp26dyfDYIiJ2OWLFNc6kWuKdrqqebAfH7g52Jp9x9DMPQAt9GPjCn9-A2w6ecX6BnkN3-MELzuw_66LfOcJFomAywwkuzoBRC_27YV3oVTlOwe_QZbf4f6o_ZJHY2JDD0PsA==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (628, '报纸', '坚守信念的高地', '周舒艺', '人民日报', '人民日报', '支部建在连上;党对军队的绝对领导;井冈山会师;秋收起义;', '由广州军区政治部与湖南省委宣传部联合推出的大型话剧《支部建在连上》最近在湖南长沙公演，获得好评。《支部建在连上》反映了红军建军之初艰难曲折的探索过程，形象生动地讲述了“党指挥枪”的思想是怎样在革命斗争的残酷现实中逐渐成熟，又是怎样在革命军队中贯彻下去的。', '2012-11-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4ML3v5KFe13ss3QEuJCfzHEr1mSp_nvM3X8n7Yde-Pq7dJn9_63pShAn-Q5iJmka0qOacKXV6yASaq3ElixHyJ2bDxJVhCZVDs02QWxsNUJy6FPAsj55G0VRVCFdSVjYDNkZUbmmTZbdw==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (631, '报纸', '解密“红色大馆”', '刘中刚 ; 贺云清; 宋歆', '解放军报', '解放军报', '文物藏品;军事博物馆;加固改造工程;主题展览;中国共产党领导;灾后恢复重建;南昌起义;书画创作;人民军队;革命传统教育;叶剑英;', '毛泽东主席题写馆名，周恩来、刘少奇、朱德、邓小平、陈毅、罗荣桓、叶剑英等老一辈无产阶级革命家捐赠珍贵文物……这里永久珍藏着我党我军的血脉，珍藏着人民军队的根、人民军队的魂。在建党90周年之际，记者对话中国人民革命军事博物馆馆长陈士富、政委孔令义——$$ 火', '2011-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Owl8u70khcjKnpNaoXposGA3k9qYGlrp3Gf72mO1V5OMzBR7wg5UBDrvEVcL6lMliyt07TvM4419KqCMTMUv5rguTZgzdIiglNP8eq-8Lpr1IJ-Ivr2YzfBs41cHfbDWwua6vEo8KrzQ==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (635, '报纸', '抓机遇 保增长 调结构 上水平', '陈忠定', '人民邮电', '人民邮电', '中国联通;移动业务;上水平;科学发展观;', '本报讯 中国联通2009年年中工作会议于7月15日至18日在革命圣地江西井冈山召开。会议在总结2009年上半年主要工作的基础上，分析了企业发展目前面临的内外部形势，安排部署了下半年任务，动员各级企业和全体员工学习井冈山精神，以科学发展观为指导，抓机遇，保增长，调结构，', '2009-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Nb3t9Gip98j6cBRGemTwl48NaqRKtGrsE4d8mnLizfg8MlRDe_Ql0Q64WLt0SgyJjahKVObehBDcixLr8jHfuFf8W2byLHdSbz1KINplKGA680D_LR5w_g6scMs0XOslZ1ZC5hZ_dadQ==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (638, '报纸', '杨柳新翻再现“井冈山革命斗争”', '', '中国文化报', '中国文化报', '井冈山革命斗争;刘大为;井冈山时期;', '为了深入实地考察生活，更好地再现“井冈山革命斗争”的伟大历史瞬间，刘大为和苗再新专程跑了几趟井冈山。$$ 他们找到井冈山博物馆的馆长谈了一晚上，了解当时的历史背景，包括服装、旗帜、时间、地点等种种状况；参观井冈山博物馆、会师博物馆等等，随后又到井冈山', '2008-12-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ny83YMoS8TujW7xy2p8PYyWOYbHiOYHoySP1t-6nTwXPlqGKk57iHwWTjuoROlwXcNgrh_UG7DkWI9bXvIqnK1vre5x03783HSX5OeWIi6xJE5nhQsJruCViXL48UcGDY-DZiMEv6mJA==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (640, '报纸', '重大革命历史题材电视连续剧《井冈山》隆重推出', '毛东红', '中国纪检监察报', '中国纪检监察报', '重大革命历史题材;电视连续剧;《井冈山》;', '本报讯(记者　毛东红)为庆 祝中国人民解放军建军80周年， 弘扬井冈山革命传统和优良作 风，由中央电视台、解放军总政治 部宣传部、江西省委宣传部、南京 军区政治部和中央纪委宣教室联 合出品，中央电视台文艺中心影 视部、南京军区政治部前', '2007-07-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PFjLHnsnhMhIdZ4hQv4s1-wJsNKolXyLP_FjNeI9l0vWg3y3byLI7Jo099Cu5Kh61afERRpGcngsAu3tJbZAaKvd_MzsrRQ7WbIHOQSog7HzHo9u7aF5s3NDebL4ddVl5i3wCJTFyQ0A==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (641, '报纸', '井冈山红色旧址成荣辱观教育大课堂', '颜芳明; 刘斐', '中国纪检监察报', '中国纪检监察报', '井冈山;知荣明耻;革命旧址;大课堂;', '本报讯　日前，江西省井冈 山市又迎来了一批“缅怀先烈、 知荣明耻”实践团成员。成员 们怀着无比崇敬的心情参观了 井冈山革命历史博物馆、茨坪 革命旧址、小井红军医院、北 山烈士陵园，并重温入党誓词， 深刻领会“坚定信念、艰苦奋 斗、', '2006-12-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OCtgnn0csojV660Rrh1Yn74NfYxi9XcPwc9JIn6_HyQBDR0C6PcpePuwMYljWbhyI5o1rJsKkGjrvYks0ifSyZhCADd3iG-gxew1YMbF3Pgso6F7vybC1eu6DdzCTcP85Iv3jTEAFu7Q==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (642, '报纸', '井冈山会师(下)', '', '人民日报', '人民日报', '平江起义;彭德怀;滕代远;井冈山会师;黄公略;', '１９２８年１２月，彭德怀、滕代远率领在平江起义中创建的红５军主力８００多人，突破敌人的围追堵截，来到井冈山同红４军会合。井冈山又多了一支革命劲旅。$$ １９２７年大革命失败后，湖南省平江地区的工农群众在中国共产党的领导下举行过几次暴动，并组织了游击队开展', '2006-08-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PEyQxl5wK7QZhOppvwbyFJ-mJPyZEVfL4Rr8ntz_YvYMvFdmwovrbcOgroHLIOU5lew0tChU7C39tqqmJbNMMX91u_mNIubmwWAX6e_3YJl_DT3Davmz4fQDXLJU2U5KW48CO1q4Qomw==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (643, '报纸', '井冈山会师(上)', '', '人民日报', '人民日报', '井冈山会师;毛泽东;南昌起义军;湘南特委;工农革命军;', '１９２８年４月下旬，朱德、陈毅率领由南昌起义部队余部和湘南农军组成的工农革命军，与毛泽东率领的湘赣边界秋收起义后组成的工农革命军在井冈山胜利会师。为了纪念这次具有伟大历史意义的会师，朱德曾赋诗道：“红军荟萃井冈山，主力形成在此间。领导有方在百炼，人民专政', '2006-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NulVOeElX7v7Mv0KjqBAen927x0ifXk1LFFjIWLQyzBl9VHlEabL3fp3BAD3dsJL3SHyB6yD1kovrZopsddfQ_J0AKOx_mW4Md8dNS9zA0CN6IU3CabsrcJ-JK01k-lxgdsIvmRwFdYg==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (644, '报纸', '井冈山：从革命“火种”到幸福“火焰”', '范建', '科技日报', '科技日报', '洗手间;沼气池;生态家园富民计划;井冈山;', '“七一”前夕，我们沿着当年红军在井冈山会师的路线，感受难忘的井冈精神。攀上黄洋界，在朱德总司令挑粮走过的小路上，我们看到一种用松枝做燃料的“火把”。当地人叫做“松明子”。“松明子”伴随红军翻山越岭；乡亲们也打着“火把”迎送红军。“松明子”，照亮了红军和老', '2005-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MVYQiDCBzsGPydmXmsyBE7tVY5kJ5TUUUUm3u0LCzqiM2SM_gXjR6nQ-uoO2iAl23I96Yo7DgyxDUa2fG-LiHvJsPdiOz_l5qBr8rF_P5i4o5tAmgwsXyFaq7zIed3N2ZvOmgEDmrqJw==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (645, '报纸', '千场免费电影送老区', '叶辉; 严红枫; 杨振华', '光明日报', '光明日报', '横店集团;影视产业;井冈山市;', '本报浙江横店7月14日电　浙江横店影视产业实验区“千场免费电影送老区活动”近日首战告捷，在7月1日起的一周里，放映队为革命老区井冈山市的中小学生放映电影30多场，观众达数万人次。受到老区中小学生的热烈欢迎。$$ 浙江横店影视产业实验区于今年4月挂牌，这是目前', '2004-07-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NSAWJXd3YhbQske-7BkcdDYz6juebpKrc0umvmYWujisDFEcpf-ytlc1qPXwdlleQECcsjnXz_SBLqJE2DiE4g6eDq8eN2sNEai-sSQiyef9MxGpfbuoW0n_x7gTeJud1y2PI20VTIbg==&uniplatform=NZKPT&language=CHS', '井冈山会师_screened');
INSERT INTO `ds_article` VALUES (647, '报纸', '把青春热血融入时代洪流', '解辛平', '解放军报', '解放军报', '中国青年;青年官兵;时代洪流;', '（一） 历史，如同一条奔腾不息的长河。 去年，我们刚刚庆祝中国共产党成立100周年。今年，我们又迎来中国人民解放军建军95周年、中国共产主义青年团成立100周年。 百年大党，风华正茂。我们这支由党缔造、绝对领导的人民军队，不也正是一个青春的方阵吗？ 人民军队，永', '2022-05-05 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.002343', '卢德铭_screened');
INSERT INTO `ds_article` VALUES (648, '报纸', '井冈山精神——跨越时空，照亮前行之路', '', '中国民族报', '中国民族报', '井冈山精神;井冈山革命根据地;', '井冈山，中国革命的摇篮。$$ 中国共产党人在创建和发展井冈山革命根据地的过程中，形成了坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利的井冈山精神。$$ 2016年春节前夕，习近平总书记来到江西，看望慰问广大干部群众和驻赣部队，首站就是井冈山。习近平总', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001151', '卢德铭_screened');
INSERT INTO `ds_article` VALUES (649, '报纸', '这道光，照亮前行之路', '赖星', '新华社;', '新华每日电讯', '井冈山精神;共产党人;秋收起义;习近平总书记;红四军;井冈山市;毛泽东;', '90多年前，井冈山茅坪八角楼。一根灯芯的微光，穿透漫漫长夜。$$ 油灯下，毛泽东同志写下《中国的红色政权为什么能够存在？》《井冈山的斗争》两篇光辉著作，成为马克思主义中国化的伟大开篇，闪耀着“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”的井冈', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005584', '卢德铭_screened');
INSERT INTO `ds_article` VALUES (651, '报纸', '弘扬井冈山精神 传承红色基因', '金荣花', '中国气象局预报与网络司;', '中国气象报', '弘扬井冈山精神;红色基因;习近平总书记;', '2020年9月，组织安排我来到中国井冈山干部学院，接受政治思想教育和党性修养专题培训。井冈山是中国红色革命圣地，是以毛泽东、朱德等为代表的中国共产党人在大革命失败后，在全党积极探索中国革命道路过程中，以实事求是、敢于探索、勇于创新的革命气魄，领导创建的中国第一', '2021-02-25 08:00:00', 'https://link.cnki.net/doi/10.28122/n.cnki.ncqxb.2021.000235', '卢德铭_screened');
INSERT INTO `ds_article` VALUES (652, '报纸', '英勇奋战 屡建战功 卢德铭', '', '人民日报', '人民日报', '卢德铭;毛泽东;', '据新华社北京３月２日电 １９２７年９月２５日，毛泽东率领的秋收起义军在向井冈山进军途经江西萍乡芦溪县时遭到国民党军伏击，总指挥卢德铭在战斗中英勇牺牲。得知这一噩耗后，毛泽东痛心疾呼：“还我卢德铭！”$$ 卢德铭，又名继雄，字邦鼎，号又新。１９０５年生', '2011-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OFP1x6r_UPwf9T0-AsAnCst3xwiaEP4ab7rnendtF0LFqzdLZQAVe5ZglQ7VKoLWLKsrU8FWFB2LH_u1iij0FNL1olI8PpyL9Q1kaF7yspdh6mpzuVnF5qvgguxQDa2uVaWsdzOkfXPA==&uniplatform=NZKPT&language=CHS', '卢德铭_screened');
INSERT INTO `ds_article` VALUES (654, '报纸', '湘赣边界秋收起义(下)', '', '人民日报', '人民日报', '湘赣边界秋收起义;国民党军;文家市;东门市;工农革命军;', '１９２７年９月１１日，工农革命军第１师按照预定计划，举行湘赣边界秋收起义。$$ 根据中共湖南省委的部署，长沙的铁路工人和部分农民，于９月９日开始分头破坏长沙至岳阳和长沙至株洲段的铁路，一度中断了敌方的铁路运输。$$ 起义开始后，第１团由修水、渣津', '2006-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N3MQkUjnEfVMOWgCdcQDV2K3PAOgIaNa5J6eExH-G3uexqsd2mX65BGpq_eiTPvfbYsvUNLYv8F6PnGBQHP5NgAC1ZNBjIZgcCMncTFLOUEBq8K8YfBjNEcUxJp5C3z678r3cV2YVeTQ==&uniplatform=NZKPT&language=CHS', '卢德铭_screened');
INSERT INTO `ds_article` VALUES (655, '报纸', '何挺颖', '', '人民日报', '人民日报', '井冈山革命根据地;毛泽东;黄洋界保卫战;党代表;', '何挺颖，１９０５年５月出生于陕西省南郑县。１９２４年，何挺颖进入上海大同大学，１９２５年５月参加五卅运动，６月加入中国共产主义青年团，随后转入上海大学社会学系学习，同年冬转为中国共产党党员。 １９２６年夏，何挺颖受党组织派遣到北伐军部队任团指导员，', '2006-05-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OR0xanUr6J0xsDaaSTzO4A65ZBzf214xo3rMWBMTR0cJyWpiQr1Dt3OlmjLOkCahvH2kFBrhciKBkuhndFh4rFH6tMuOnZ8hgrMeSkK4cCgBXBc9K5zDcVY0pZWTk8FZx2B5FXvQWyQw==&uniplatform=NZKPT&language=CHS', '卢德铭_screened');
INSERT INTO `ds_article` VALUES (657, '报纸', '“红色故事”激发职工建功热情', '曾思云; 胡青松', '工人日报', '工人日报', '红色基因;吉安市;', '“我聆听了吉安工运先驱梁一清烈士的故事，深切感受吉安工运的辉煌过往，收获良多。”近日，参观完中华全国总工会苏区中央执行局和二七会议旧址后，江西省吉安市总工会年轻干部邓淑敏慨叹。 吉安是革命老区，拥有丰富的红色资源和工运资源，如何运用好这些红色资源“富矿”', '2023-10-30 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2023.005214', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (658, '报纸', '“接过这副担子是件幸福的事”', '王群学; 黄毅华; 龙礼彬', '中国国防报', '中国国防报', '井冈山革命博物馆;井冈山精神;讲解员;', '秋日井冈，丹桂飘香。 在江西省井冈山市茨坪革命旧址群，游客们常能看到一名身材挺拔的年轻人，背着扩音器穿梭于一排排干打垒土坯房之间，自信而从容地讲解着井冈山的红色故事。 他叫毛浩夫，是井冈山革命博物馆专职讲解员。本期“视点”，我们一起了解他的故事。 “就像', '2022-10-11 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2022.001858', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (659, '报纸', '井冈山上的红色“接棒人”', '赖星', '新华每日电讯', '新华每日电讯', '井冈山精神;', '手持“小蜜蜂”扩音器，笔挺地站在一排排革命旧居旧址旁，介绍井冈山的红色历史……近6年来，毛浩夫已面向海内外游客、学员宣讲了4000余场。 很难想象，这是一名国际金融与贸易专业毕业的“海归”青年。2015年从英国留学归来后，毛浩夫曾在江西省会南昌工作过。在爷爷毛秉华', '2022-04-27 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.003320', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (661, '报纸', '井冈翠竹依然挺拔', '刘发为', '人民日报海外版', '人民日报海外版', '井冈山国家级自然保护区;井冈山精神;红色旅游;', '“今年是建党百年，来井冈山的客人格外多。”一见面，井冈山国家级自然保护区大井林场副场长邹秋平就热情地对记者说，“井冈山精神是跨越时空的。”$$ 井冈山地处湘鄂交界的罗霄山脉中段。下了高速要上井冈山时，记者看到一座巨大的红旗雕塑。当地人说，这面红旗，既表明中', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002294', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (662, '报纸', '井冈山精神：星星之火从此燎原', '张弛', '中国纪检监察报', '中国纪检监察报', '井冈山精神;红军战士;', '盛夏时节，黄洋界山头云雾弥漫。举目四望，群山起伏，层峦叠嶂。这里，就是位于湘赣边界罗霄山脉中段的井冈山。$$ 在这片红色的土地上，中国共产党人建立了第一个农村革命根据地，开辟了“农村包围城市、武装夺取政权”的革命道路，回答了“中国的红色政权为什么能够存在”', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003508', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (663, '报纸', '红色故事是最生动的教材', '张天培', '人民日报', '人民日报', '井冈山革命博物馆;红色精神;红色基因;井冈山精神;习近平总书记;', '在参与中传承、在传承中发扬，信仰之火就能熊熊不息，红色基因就能融入血脉$$ 在井冈山革命博物馆，一根灯芯的故事被反复提及。这是一根陈旧油灯里的灯芯，在罗霄山脉中段的八角楼里闪耀火光。就是在这豆大的火苗、微弱的光亮下，毛泽东同志思考着适合中国革命发展的道路。', '2021-03-29 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.003164', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (664, '报纸', '精神火种永不灭', '刘明中', '中国财经报', '中国财经报', '井冈山;工作室;', '在井冈山采访，虽然只有不到一周的时间，却给记者留下了难以磨灭的印象。$$ 记者一行采访石金龙的时候，他讲述的曾志晚年的故事，让每个在场的人的心灵都受到了巨大的震撼。不忘初心，牢记使命，曾志身上体现出来的井冈山精神，其精神实质就是这八个字，这就是“革命理想高', '2019-10-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PCyWBZIFxp1YDLBAmznL7s6F5zutc5e5G8lu_OPTURjKBU_gJIHSSF3ZF43qWEVmoYoNdpyVbVSpNnLzCbiX_4JXx4FwaOjVdfygC7EhO5RIKTmdq0zeoCs2fOuYBgqczrcddkHhcNow==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (665, '报纸', '凝聚民族复兴的精神伟力', '罗争光; 熊丰; 王思北', '人民日报', '人民日报', '习近平总书记;民族复兴;社会主义思想道德建设;崇德向善;模范人物;', '伟大时代呼唤伟大精神，崇高事业需要榜样引领。$$ 党的十八大以来，以习近平同志为核心的党中央高度重视社会主义精神文明建设特别是思想道德建设，对加强立德树人、以文化人等各项工作作出一系列重要指示，对表彰道德模范、开展学习宣传道德模范活动等提出明确要求，推动社', '2019-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4POIBSQ_Y8FRfmAhqd9LX-XCF7O19P7mztKwrBq7YNlkeeXbc8C9NrTT6oJfPvGn3ggnsWud7SMgAyin9ZExIo56jern-XlyGg4vctIy7sDMnqHyoeJW0fMuMpQlJ4s2BYokzTR40wMeg==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (666, '报纸', '燎原星火在这里点燃', '孟维伟; 曹蕾; 罗珺', '中国纪检监察报', '中国纪检监察报', '井冈山革命博物馆;湘赣边界;井冈山革命根据地;工农武装割据;', '6月28日，江西井冈山茅坪八角楼。青油灯静静地放在桌上。$$ “八角楼的灯光，比天上的北斗星还要明亮。”讲解员黄俊峰正在向游客们讲述那段艰难而光辉的岁月，“正是在这盏如豆的小小青油灯下，毛泽东挥笔写下《中国的红色政权为什么能够存在》《井冈山的斗争》两篇光辉著', '2016-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ov9M7ygTBf4bXS2Icc_IHvWE__0fAs0cPad8-YC4lH7egw1BCDQkKNtBlVufIMwx571D2YTgDu4ynHFqpDBqAlCWSElN7mOEtM7p8n_WvD2PcMdDfRYwyB5H-uP5pNxnRCBXSUtg_6xA==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (669, '报纸', '踏访井冈山——中国革命的摇篮', '张晓祺 ; 代烽 ; 徐政武', '解放军报', '解放军报', '井冈山斗争;工农革命军;毛泽东;井冈山革命博物馆;中国革命;', '也许，世界上还没有哪座山，像它这样与一个民族、一个国家、一个政党、一支军队有着如此密切的联系。$$ 井冈山，中国革命的摇篮。5月12日，冒着霏霏细雨，“红色足迹万里行”前方报道组来到井冈山，追寻留在这里的红色印记。$$ 重温一段历史——$$ 中国要有自己的马', '2011-05-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pc4GRA2IX-aQpAEVHO_-eNpqvwcRL5fYCYwGmWS5rplN5mDWW0ItsWdF4u7GAnUmYih829Wt63FQuhnPTf0r_6PJQqZIYDlrZFRRfYb7WOmni58Gis_1EFBf_HEfDGoCET3DUJJdu-RA==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (670, '报纸', '让忠诚融入共和国检察官的血脉', '肖玮 ; 徐盈雁; 欧阳晶', '检察日报', '检察日报', '检察官;检察长;中国特色社会主义事业;建设者;最高人民检察院;中国特色社会主义检察制度;检察职业道德;共和国;', '革命圣地井冈山，群山巍峨，林海苍茫。 $$ 7月下旬，最高人民检察院在这里召开全国检察长座谈会暨全国检察机关第二次民事行政检察工作会议，并围绕大力弘扬井冈山精神举行了一系列革命传统教育活动，让参加会议的全体代表感受到了浓浓的红色氛围，进一步坚定了理想信', '2010-07-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PkbPKseRyUBFhDWFqAWAmcS0fcm5jFneDkv5QwX-jyHetUpOIMk8nJ942Rp8ePEKfbKD-iVFmpgeKkZg2TMGRBTs-hMPxyYEUoDnMoO-Ey96PdZ96_GSaH4-xmNelAnl7V9kHPzSHB0Q==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (671, '报纸', '绵绵细雨祭先烈', '张鹏; 唐先武', '科技日报', '科技日报', '井冈山市;红军烈士墓;吴孟超;', '细雨是初春的标志。清明之际，细雨绵绵。早春里的井冈，层林染翠；清明前的茨萍，杜鹃吐芳。$$ 3月31日，第二军医大学东方肝胆外科医院院长吴孟超院士率领医院40多名党支部书记和专家教授，千里奔赴井冈山，追寻红军足迹、传承井冈精神，祭奠革命先烈、反哺老区人民。', '2010-04-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PVLKfrRtd_j9AmG-rPscstJFwxdIEmdwx_rT6mflddkh9HCyjZRl3PvvwbVIqelgCbWpNoWXzonszuYIYf4JM7ZmCCgooowG3fKmHvk2DQ20IGdKIowvNRjc28vqs8v-ztmh8CG3E6UQ==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (672, '报纸', '坚定信念闯新路', '任江华', '人民日报', '人民日报', '井冈山斗争;坚定信念;井冈山革命根据地;中国井冈山干部学院;井冈山革命博物馆;红色旅游;', '夏日，江西井冈山革命博物馆游人如织。$$ 展厅里，人们凝神观看，驻足沉思。“实物、文献、图片以及声、光、电的陈列表现形式，加深了我们对井冈山革命斗争史的了解，对井冈山精神内涵的理解。”广东游客吕先生连称“不虚此行”。$$ “井冈山斗争培育了以坚定', '2009-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PGLJwJ64tuI0z_-1S3K688ey8Bl64O7oXVN0VoWc8Qq-M5pBFOLLd-sniz7rvsitg_lxBWV_QikVpnOS5Rqf8AGkNHGxDk1ud-x3JeqVKyErsyAyUv3rrC5J6TR5G4Wi-u5pKdn9ka8A==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (673, '报纸', '金融危机时,胡锦涛为何来到井冈山', '刘菁; 周伟; 张辛欣', '新华每日电讯', '新华每日电讯', '井冈山斗争;胡锦涛;井冈山革命博物馆;秋收起义;湘赣边界;', '新华社南昌7月5日电(记者刘菁、周伟、张辛欣)一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。 $$ 再上井冈山，重走井冈路', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MmGEI_MiU05AQGMtZK3QEaVFfjfR_gAnCq01R0iOeFXbSmJAFR1eFrQZ86WabqLzzazuQl4VMHZOa6zPZVqMUroD9T1hhzxwPIVp7ASrbxepzdmtEi4evZHjM18Q2gmM7j3HTPIommbQ==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (674, '报纸', '道路·信念·核心', '刘菁; 周伟; 张辛欣', '新华社;', '中国青年报', '井冈山斗争;井冈山革命博物馆;南昌起义;秋收起义;湘赣边界;武装夺取政权;农村包围城市;工农革命军;共产党人;科学发展观;', '一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。$$ 再上井冈山，重走井冈路，抚今追昔，我们敬仰这片红土地，自豪60年新中国。', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ohds1O1rjXF1KsNdayJY2a0TX7bBilukU7NQXEpad7GL7G1N0Q20LPHSmPKj0ngk7Cs1IiGK0uCe-MOZ3_8CoBZ_jGrLCSEN0RoRtCQBWO6AhKGZJ5zM2tvnOamEt_zPWxd1IdRNLZQg==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (675, '报纸', '教育部举行井冈山精神报告会', '张贵勇', '中国教育报', '中国教育报', '井冈山精神;报告会;先进性教育活动;教育部;', '本报北京3月2日讯(记者　张贵勇)教育部今天举行井冈山精神报告会。井冈山革命博物馆原馆长毛秉华作了题为《弘扬井冈山精神，加强党的执政能力建设》的报告。教育部党组副书记、副部长张保庆主持会议并讲话。 $$ 报告会上，毛秉华回顾了井冈山革命斗争的历史，介绍了许多鲜', '2005-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NIaO7u1JuTOJGkz4sZU-mseKaIYNeKsmR_jmKGHJ2c7yIhQxiGqRRlklPpn_fWPebW8_V6vnJrbSfIXvFCdOmDC44raAlnRFsyR6ehQP-9phtU6jpFmCl_FOljI_D68UHfuCnbcyppnw==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (676, '报纸', '精神的力量', '胡晓军', '光明日报', '光明日报', '井冈山市;', '主峰海拔1586米。它并不算太高，却屹立起了一座中国革命史上令人仰止的丰碑。 $$ 1927年10月至1930年2月。当年在此进行的革命斗争历时并不算太长，却开辟出了一条马克思主义与中国革命实践相结合的光辉道路。 $$ 巍巍井冈山，连着中国共产党璀璨的历史。77年过去，它正', '2004-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OWjmuL79cvuN7NZ50TQZ17StkukxiUwz0s48A4chcq8g1pNMKWsvxqgJPe3kzGuAm3GyVdk8C9C6bYll1StNUwjYZDVMb3YSpuZ-P1Ga0yUTjZKf-FsWKhzekVOphuo-XZrW8ykRbt_g==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (677, '报纸', '革命摇篮今亦红', '胡晓军', '光明日报', '光明日报', '井冈山市;革命摇篮;', '盛夏时节驱车上井冈，苍山层林给人带来一片沁人心脾的清凉意境；在山上造访各处革命旧址，所见所闻又让人产生一种激昂向上的炽热情怀。 $$ 有“中国革命摇篮”之称的井冈山，在爱国主义旗帜下，在革命传统教育中，焕发着火红的风采。 $$在红色课堂里成长 $$ 茨坪毛泽东', '2004-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P4gzeluigbprHcmgsvUfeZAoaU6n5GGcut_2AZhVqGz8vIqSGN6rqWIgniDi5XrHdaB_no-dRKJIXlQ5LMoc-M27Mv0Q9QhzPRlNxF9vGpk7U1fHBpSFYWtTtKs6MKkr0LIDWlHrkH4Q==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (678, '报纸', '井冈山精神首场报告会在国防大学举行', '王海磬; 王光荣', '光明日报', '光明日报', '国防大学;井冈山;报告会;', '本报北京11月13日电　今天下午，由中共江西省委宣传部、江西省文化厅、吉安市委市政府、井冈山市委市政府联合举办的井冈山精神首场报告会在国防大学举行。国防大学校长裴怀亮、政委赵可铭出席报告会。$$ 井冈山与国防大学有着特殊渊源。诞生于井冈山龙江书院的红军教导', '2003-11-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Oj14RdH-35Gb6rgeVrAEMn-Z5WLEvIG18KgkyQdIihtbmKrV6bt55diKgT_XiOolzETr5q-evBQpeKQE02uPHO0Xgdvtx6IuYYKX0P-ZYA5l_GFUDR9cOUMAr8aSh83vORXjso7f9WVg==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (679, '报纸', '丹青难写是精神', '刘文兰; 刘福明; 邝小明', '光明日报', '光明日报', '井冈山革命斗争;井冈山市;革命根据地;', '巍巍井冈山，殷殷挚爱情。一位满头银丝的老人，坚持34年如一日，马不停蹄，义务宣讲井冈山精神；行程万里，只身一人足迹踏遍湘赣两省边界各县农村；无私奉献，数十万元讲课费分文不取，反倒自己拿出10095元捐赠社会公益事业。他，就是今年全国“五一”劳动奖章获得者毛秉华', '2003-05-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MUofoKRmSzAI84LprfIFYfh1PYpAhxbIqLwmJXq5_KZSvjuyc_0QHLCbkudrsi9rHeHS9SR6YQKbGGxKuhPNUmExSb0q-XV4DoVnOQS5e8hHvRs7G9Wqh_MdfYw0oGJtpJzmj_Xce72w==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (680, '报纸', '为了让红旗永远飘扬', '龙小毛', '人民法院报', '人民法院报', '最高人民法院;井冈山革命斗争;', '一曲艰苦奋斗之歌$$ １９６５年５月重上井冈山的毛主席激动而又长时间地对随行人员讲述当年井冈山的艰苦战斗、生活情景，并着重强调，“要更好地建设社会主义中国、更好地建设社会主义的井冈山”，“艰苦奋斗的精神不要丢了，井冈山的革命精神不要丢了”。$$ １９９', '2003-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MXTYsOkahwYAUERkC4iw--r9Ays-nXGtGjdLta8X2BaceM-1VaYCIqvhv1G7IGKJWom5D2v1ddn7I3F6GtgNSVgoWuU93YAuEuGpTdTx4B9XUQ6l5K8g12MdexxpJ-UwWjaPut0amZkQ==&uniplatform=NZKPT&language=CHS', '毛秉华_screened');
INSERT INTO `ds_article` VALUES (683, '报纸', '让大地赋我们无穷力量', '关铭闻; 王慧敏; 赵建国; 邢宇皓; 户华为; 王国平; 王琎; 彭景晖; 杨舒', '光明日报', '光明日报', '习近平总书记;社会主义;生态保护;黄河流域;调查研究局;毛泽东;中国特色社会主义道路;长江经济带;中国共产党;治国理政;', '一棵大树如何才能枝繁叶茂？唯有舒展根须不断向大地汲取营养；一条江河如何才能奔流不息？唯有敞开胸襟吸纳每一颗雨滴；一个大党如何才能永葆青春？唯有扑下身子融入人民。 春三月，中共中央办公厅印发了《关于在全党大兴调查研究的工作方案》。伴着和煦惠风，千百万党员干', '2023-04-21 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.001845', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (687, '报纸', '感悟红色精神 砥砺初心使命', '张博', '中国新闻出版广电报', '中国新闻出版广电报', '井冈山精神;井冈山革命博物馆;共产党人;江西日报;红色精神;短视频;《解放军报》;井冈山革命根据地;', '历史是理解未来的钥匙。百年来，中国共产党带领中国人民走出一条从站起来到富起来，再到强起来的康庄大道，实现了从“赶上时代”到“引领时代”的伟大跨越。在百年奋斗历程中，中国共产党团结带领人民取得一个又一个胜利，以井冈山精神等为代表的革命精神发挥了重要作用。$$', '2022-01-19 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.000188', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (688, '报纸', '牢记中国共产党是什么要干什么这个根本问题', '贾珍珍; 卢潇; 刘杨钺', '国防科技大学党的创新理论研究中心;', '解放军报', '人民至上;中国共产党人;根本问题;共产党;', '不忘初心，方得始终。党的十九届六中全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》强调，全党要牢记中国共产党是什么、要干什么这个根本问题，把握历史发展大势，坚定理想信念，牢记初心使命，始终谦虚谨慎、不骄不躁、艰苦奋斗。“是什么、要干什么', '2021-12-15 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007722', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (690, '报纸', '井冈山精神——跨越时空，照亮前行之路', '', '中国民族报', '中国民族报', '井冈山精神;井冈山革命根据地;', '井冈山，中国革命的摇篮。$$ 中国共产党人在创建和发展井冈山革命根据地的过程中，形成了坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利的井冈山精神。$$ 2016年春节前夕，习近平总书记来到江西，看望慰问广大干部群众和驻赣部队，首站就是井冈山。习近平总', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001151', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (694, '报纸', '坚持实事求是 增强党性原则', '徐隽', '人民日报', '人民日报', '中央党校;党性原则;国家行政学院;', '出入中央党校（国家行政学院）大门时，都会看到花岗岩上镌刻的4个大字——“实事求是”，这是毛泽东同志为中央党校题写的校训。党的领导干部在中央党校（国家行政学院）学什么？首先要学的就是实事求是。$$ 习近平总书记在2021年秋季学期中央党校（国家行政学院）中青年干部', '2021-11-02 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011541', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (695, '报纸', '从井冈山精神中汲取奋进力量', '王少玄', '江西省吉安市委;', '学习时报', '井冈山精神;共产党人;井冈山革命根据地;', '一座山，辉映历史；一种精神，照耀未来。习近平总书记指出，“井冈山是革命的山、战斗的山，也是英雄的山、光荣的山”。这里见证了中国共产党人开辟农村包围城市、武装夺取政权道路的伟大实践，淬炼了党与群众同甘共苦、血脉相连的优良作风，锻造了伟大的井冈山精神。井冈山', '2021-10-04 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001832', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (696, '报纸', '井冈山：打造红土地旅游服务新样板', '胡佳佳; 张慧斌; 汪启链', '人民法院报', '人民法院报', '井冈山精神;旅游纠纷;生态旅游;红土地;', '上个世纪20年代末，在井冈山这片红土地上，以毛泽东、朱德等为代表的中国共产党人，创建了中国第一个农村革命根据地，开辟了“农村包围城市、武装夺取政权”的中国革命道路。井冈山斗争的伟大实践，对中国革命道路的探索和抉择、对中国共产党和人民军队的成长都具有关键意义', '2021-09-22 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.004432', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (699, '报纸', '井冈翠竹依然挺拔', '刘发为', '人民日报海外版', '人民日报海外版', '井冈山国家级自然保护区;井冈山精神;红色旅游;', '“今年是建党百年，来井冈山的客人格外多。”一见面，井冈山国家级自然保护区大井林场副场长邹秋平就热情地对记者说，“井冈山精神是跨越时空的。”$$ 井冈山地处湘鄂交界的罗霄山脉中段。下了高速要上井冈山时，记者看到一座巨大的红旗雕塑。当地人说，这面红旗，既表明中', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002294', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (700, '报纸', '井冈山：用好红色资源 走出发展新路', '罗嗣尧; 周晨', '中国旅游报', '中国旅游报', '井冈山;井冈山革命博物馆;红色资源;', '1927年10月，毛泽东同志率领秋收起义部队走上井冈山，开始工农武装割据斗争。在这里，中国共产党人开辟了“农村包围城市、武装夺取政权”的中国革命道路，孕育了“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”的井冈山精神。$$ 如今，井冈山结合新的时代', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002146', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (703, '报纸', '井冈山精神跨越时空闪耀光芒', '赖永峰; 刘兴', '经济日报', '经济日报', '井冈山精神;井冈山革命博物馆;习近平总书记;', '中国共产党始终把共产主义远大理想写在旗帜上，将马克思主义作为根本指导思想，并将其与中国具体实际相结合，引领革命向着胜利方向前进。井冈山斗争就是在这一理想信念引领下进行艰苦卓绝奋斗的光辉实践。$$ “井冈山是中国革命的摇篮。井冈山时期留给我们最为宝贵的财富，', '2021-07-24 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005541', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (704, '报纸', '精神伟力跨越时空', '胡晓军; 李慧', '光明日报', '光明日报', '井冈山革命根据地;毛泽东;中华民族;群众史观;习近平总书记;中国共产党领导;马克思主义中国化;共产党人;马克思主义基本原理;中国革命道路;中国特色社会主义道路;', '位于湘赣边界罗霄山脉中段的井冈山，并不算太高，却屹立起一座中国革命史上令人景仰的丰碑。$$ 1927年10月至1930年2月，当年在此进行的革命斗争历时并不太长，却开辟出一条马克思主义基本原理同中国具体实际相结合的光辉道路。$$ 1927年10月27日，毛泽东同志率领工农革命军', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003705', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (705, '报纸', '井冈山精神：星星之火从此燎原', '张弛', '中国纪检监察报', '中国纪检监察报', '井冈山精神;红军战士;', '盛夏时节，黄洋界山头云雾弥漫。举目四望，群山起伏，层峦叠嶂。这里，就是位于湘赣边界罗霄山脉中段的井冈山。$$ 在这片红色的土地上，中国共产党人建立了第一个农村革命根据地，开辟了“农村包围城市、武装夺取政权”的革命道路，回答了“中国的红色政权为什么能够存在”', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003508', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (706, '报纸', '这道光，照亮前行之路', '赖星', '新华社;', '新华每日电讯', '井冈山精神;共产党人;秋收起义;习近平总书记;红四军;井冈山市;毛泽东;', '90多年前，井冈山茅坪八角楼。一根灯芯的微光，穿透漫漫长夜。$$ 油灯下，毛泽东同志写下《中国的红色政权为什么能够存在？》《井冈山的斗争》两篇光辉著作，成为马克思主义中国化的伟大开篇，闪耀着“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”的井冈', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005584', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (709, '报纸', '信念的力量指引胜利', '周玮; 高皓亮; 赖星', '新华社;', '新华每日电讯', '井冈山革命博物馆;井冈山精神;井冈山革命根据地;共产党人;习近平总书记;', '井冈山八角楼前，一棵在石下萌芽扎根的枫树竟把石头撑开，历经90余载风雨依然高大挺拔。$$ 中国共产党历史展览馆里，一盏红军在井冈山使用的油灯，映照中国共产党人百年不变的初心与信念。$$ 循着百年大党的精神之源，让我们聚焦中国共产党精神谱系中这个重要的红色坐标—', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005327', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (712, '报纸', '星火映井冈 理想耀中国', '黎隆武', '江西省委宣传部;省新闻出版局(省版权局);', '中国新闻出版广电报', '弘扬井冈山精神;习近平总书记;', '井冈山是中国革命的摇篮，井冈山精神是中国共产党在开辟中国革命新道路过程中形成的伟大革命精神。习近平总书记2016年2月在江西考察时指出，要结合新的时代条件，坚持坚定执着追理想、实事求是闯新路、艰苦奋斗攻难关、依靠群众求胜利，让井冈山精神放射出新的时代光芒。$$', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.002501', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (714, '报纸', '百年风华：读懂你的样子', '钟华论', '新华每日电讯', '新华每日电讯', '全面从严治党;中国共产党历史;共产党人;人民幸福;中国特色社会主义;习近平总书记;人类命运共同体;陈乔年;陈延年;奋斗者;', '一群年轻人的身影，定格于上海石库门。$$ 谁能想到，就是这群平均年龄只有28岁的青年，冲破沉沉黑夜，点燃革命星火，掀起了气壮山河的惊雷巨澜。$$ 一叶红船，静静停泊在浙江嘉兴南湖。$$ 谁能想到，一个马克思主义政党就是从这里起航，穿越重重关山，奋进漫漫征途，书写', '2021-06-28 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005124', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (715, '报纸', '开辟革命新道路', '高中华', '中央党校(国家行政学院)习近平新时代中国特色社会主义思想研究中心;中共党史教研部;', '解放军报', '毛泽东;新道路;八七会议;', '1927年大革命失败后，神州大地陷入一片白色恐怖。新生的中国共产党遭受成立后从未遇到过的严峻考验，中国革命处于命悬一线的紧要关头。$$ 死亡和屠刀吓不倒真正的信仰者，腥风血雨只能让共产党人更加笃定信念、冲破暗夜、勇毅向前。$$ 面对严酷斗争和血的教训，我们党认识', '2021-04-13 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.002293', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (716, '报纸', '弘扬井冈山精神 传承红色基因', '金荣花', '中国气象局预报与网络司;', '中国气象报', '弘扬井冈山精神;红色基因;习近平总书记;', '2020年9月，组织安排我来到中国井冈山干部学院，接受政治思想教育和党性修养专题培训。井冈山是中国红色革命圣地，是以毛泽东、朱德等为代表的中国共产党人在大革命失败后，在全党积极探索中国革命道路过程中，以实事求是、敢于探索、勇于创新的革命气魄，领导创建的中国第一', '2021-02-25 08:00:00', 'https://link.cnki.net/doi/10.28122/n.cnki.ncqxb.2021.000235', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (718, '报纸', '弘扬跨越时空的井冈山精神', '李镇发', '江西省南昌市委;组织部;', '中国组织人事报', '井冈山精神;井冈山斗争时期;实事求是闯新路;共产党人;全面建成小康社会;', '那是一段成就中国革命伟业的峥嵘岁月，那是无数革命忠魂铸就的伟大精神。井冈山从此成为中国革命的摇篮，成为共产党人永远的精神家园……$$ 一$$ 90多年前，以毛泽东、朱德为杰出代表的中国共产党人在井冈山开创了中国第一个农村革命根据地，点燃了“工农武装割据”的星星', '2020-01-15 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2020.000151', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (719, '报纸', '永远的井冈山', '彭勃', '中央党校(国家行政学院)\"习近平新时代中国特色社会主义思想\"理论研修班;江西省委党史研究室;', '学习时报', '井冈山;红色基因;精神传承;', '井冈山，中华儿女心向往的革命摇篮。“好高的井冈山哟，杜鹃花最艳，点燃了星星之火哟，美丽了母亲的容颜，小溪里流淌的故事是先辈的呼唤，大山里播种的信念是不朽的诗篇。”$$ 开天辟地第一回，人民有了子弟兵。以毛泽东、朱德为主要代表的中国共产党人，点燃了中国革命的', '2018-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OTL0h5SSIa6EYkSNmDU5Hxr0Lk-sczIAHRfo9IAcgX7sIpKPh_t95-VtgfGMHh5vMwIhqECf4tTJU9SVpw6h36uGdNp5RB1o-8OYm6Hfypr_hkkCx2Trg1as88A69Udx2R-gO6RoS9cA==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (720, '报纸', '把中华民族复兴伟业不断推向前进', '鹿心社', '中共江西省委;', '人民日报', '南昌起义;中华民族复兴;大革命失败;国民党反动派;', '习近平同志在庆祝中国人民解放军建军90周年大会上的重要讲话，回顾了人民军队发展壮大的光辉历程，总结了人民军队从胜利走向胜利的历史经验，提出了把人民军队建设成为世界一流军队必须牢牢把握的根本要求。作为人民军队军旗升起的地方，我们要深入学习贯彻习近平同志的重要', '2017-08-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MvZnMHnC5X2xXGh2wDDlaA4nYrE4ciTTJ1RnNkdQDHA-mavYVnSC_9kwhwZx5RKDP8daPdwueh7n3elqpH4TTsyJPk6WetAdCEIXKLjrJb83Km5_KcTAPPYLJjIKjWw3XbLi6DEu7Kyg==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (723, '报纸', '不忘初心好扬帆', '鹿心社', '中共江西省委;', '人民日报', '共产党人;奋斗精神;毛泽东;习近平同志;井冈山斗争时期;共产主义理想信念;', '“面向未来，面对挑战，全党同志一定要不忘初心、继续前进。”在庆祝中国共产党成立95周年大会上，习近平同志发表了重要讲话，强调“不忘初心、继续前进”。这篇重要讲话气势恢宏、意蕴深远，具有强烈的历史纵深感和现实针对性，体现了共产党人的本色初衷和使命担当，是实现', '2016-08-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PY6syD4qb4fIGMeAHJXJUNMW7QQS-_mz6UqqqMSo2JMMqSkWdFJhdTygql_hPEBG6To1ovmefzUVxnqQTg8r4Ed7x1e3LRBXr0Wotm8ImCC4ha6jLwhrUoatCtDYzq_BFbG4WsVTtRJQ==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (725, '报纸', '燎原星火在这里点燃', '孟维伟; 曹蕾; 罗珺', '中国纪检监察报', '中国纪检监察报', '井冈山革命博物馆;湘赣边界;井冈山革命根据地;工农武装割据;', '6月28日，江西井冈山茅坪八角楼。青油灯静静地放在桌上。$$ “八角楼的灯光，比天上的北斗星还要明亮。”讲解员黄俊峰正在向游客们讲述那段艰难而光辉的岁月，“正是在这盏如豆的小小青油灯下，毛泽东挥笔写下《中国的红色政权为什么能够存在》《井冈山的斗争》两篇光辉著', '2016-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MzG98AQssM3yJQNPgQvn8_bRBgfHYGS07VNdS-MR2Vk-KkwLrc3Taee2WvqAILk1Ri8YoM4QJolnCCkkzNEgsBoQPFnSxThCm5ilCbtX5I6fKfvE0sPk472cGsGCgRswJyrK3Os3GMxA==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (726, '报纸', '井冈山，心中永远的圣地', '江东洲', '广西青联;科技日报广西记者站;科技日报海南记者站;', '科技日报', '井冈山;毛泽东;马克思主义与中国革命;习近平总书记;实现中国梦;老一辈无产阶级革命家;全面建成小康社会;党的作风建设;武装夺取政权;严以修身;严以用权;中华民族伟大复兴;井冈山革命根据地;群众路线;严以律己;大革命失败;', '井冈山是中国革命的摇篮，在这块红色土地上，以毛泽东同志为代表的中国共产党人，点燃了中国革命的星星之火，不仅为中国革命开辟了一条成功之路，而且培育出了凝聚中华民族之魂的井冈山精神，在革命、建设以及改革开放新时期激励着全国人民不断奋勇前进。习近平总书记在参加', '2015-11-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MyRvOywSqLTpX-p3IAp1u0DfqcJUzVB5qGHR0w7xhs-IQyF45rseAJk4vjyQK6GOWUKWSGBUUbzQeFeH9-Op-5OCfhZY4vBB2UGJGWGZ8Du_z8vU4_IpsnR3t_OqJeQ1_gXzA-4Swzjw==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (728, '报纸', '农村包围城市、武装夺取政权思想是如何提出的？', '户华为', '光明日报', '光明日报', '农村包围城市;武装夺取政权;井冈山根据地;', '大革命失败后，中国红色政权和革命力量处在强大的白色政权的包围之中。1928年5月，在湘赣边界党的第一次代表大会上，毛泽东总结建立井冈山根据地的经验，提出深入土地革命，加强根据地政权建设、军队建设和党组织建设的任务，初步回答了这个问题。当年10月，湘赣边界党的第二', '2012-09-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PVl57MagulKsMIFUHrWaAkZIr-RKmLgBGUGBkaaPykbGs7YsuwOmbR0Rrc5KErs8wZgQd3XeDbe8Sp4Rccv5BEC-54xo4pX3rv4z2bPjvF-p7FISTTW5f75xVvp5gMLTzE-Bz68dYDDg==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (733, '报纸', '传承井冈精神铭记社会责任', '高初建', '中华工商时报', '中华工商时报', '非公有制经济人士;井冈山斗争;社会责任;', '在中国共产党建党90周年纪念日前夕，中央统战部、中国光彩事业促进会组织了以“感恩革命老区、传承井冈精神”为主题的井冈行活动。通过组织非公有制经济人士开展革命传统教育，引导非公有制经济人士进一步增强感恩党、感恩国家、感恩人民的意识，激励他们更加自觉地履行社会', '2011-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MblhEAHoCMv3ABiNJDehVULieBe66EtDQ9MfWGI1W62bX7sMqx4QsALC1JAUwmtXqdEyccJEKR0bP4JiJ2tQfhAU64Ue3-CZK8FXvS20c6CB07Om72lietp3nBx2J6-pFHAkG-XCs9dA==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (735, '报纸', '星星之火映天红', '李兴文; 杜宇', '人民日报', '人民日报', '井冈山革命根据地;红四军;湘赣边界;黄洋界保卫战;工农武装割据;秋收起义;', '新华社江西井冈山５月１４日电　（记者李兴文、杜宇）历经风雨洗礼，今日井冈山茅坪的八角楼显得格外凝重，那盏斑驳的油灯依然临窗摆放，砚台似乎还散发着昨日的墨香，一个伏案疾书的身影仿佛穿越时光，出现在我们眼前。$$ ８０多年前，毛泽东总结井冈山革命根据地斗', '2011-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OxuT92O5JgnBq0-CwNfpvz8hRp9xDyPSKyxv0bfyJ1sK8iowxrVz-mel0vITnWBAA5q9HrI94jU-RmpGZdzTNV6uCzxKzzjSTKJPD_-Xb2CMvkvNbJxm0EeL390QcwAnAwTGhRck3EGg==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (736, '报纸', '踏访井冈山——中国革命的摇篮', '张晓祺 ; 代烽 ; 徐政武', '解放军报', '解放军报', '井冈山斗争;工农革命军;毛泽东;井冈山革命博物馆;中国革命;', '也许，世界上还没有哪座山，像它这样与一个民族、一个国家、一个政党、一支军队有着如此密切的联系。$$ 井冈山，中国革命的摇篮。5月12日，冒着霏霏细雨，“红色足迹万里行”前方报道组来到井冈山，追寻留在这里的红色印记。$$ 重温一段历史——$$ 中国要有自己的马', '2011-05-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NT_w1wv-Mjazez-cJ_i4i6RhCGb0iG7qFGng174VbldPYWijBEeJw1RZm44ZNiAO7ZXD80h_cBuplcnWaW2rlgg9Ojf4_dxZkI48eb-GQ1o3NYSSB6744gE-mXnU75cc9v2juAqNf1iQ==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (737, '报纸', '巍巍井冈展新姿', '梁睿 ; 赖永峰', '经济日报', '经济日报', '井冈山革命斗争;井冈山市;塑料光纤;', '又是一年杜鹃花开。在中国共产党成立90周年前夕，记者怀着崇敬的心情再次来到绵亘五百里的巍巍井冈山，重忆党在创建初期极端艰苦的环境下领导武装斗争的烽火岁月，采访井冈山在经济社会发展这一新战场上取得的新成就。$$ 井冈山上党旗红$$ 忆往昔峥嵘岁月稠。1927年，', '2011-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PFWBhkOhDIjiqmoMeI5eFyXQlKvzsiSBVekcNgLE8dPBf2u0iRlfmxQlanw74NuIeHcH2S3P8Yw0J2VepT0I1cFDYYQDDQCMSMP9XK-U9Xk60pANqV7UfGi6If01nfSC5tdCMl7lgkYg==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (738, '报纸', '大力弘扬井冈山精神 谱写人民司法事业新篇章', '', '人民法院报', '人民法院报', '弘扬井冈山精神;三项重点工作;', '全国大法官审判管理专题研讨班在革命圣地井冈山举行。这既是一次围绕三项重点工作深入研究加强人民法院审判管理工作的专题研讨会，又是一次大力弘扬井冈山精神的学习会、教育会、现场会，集中体现出专题研讨与接受革命传统教育相结合的鲜明特点。会议期间，大法官们专程瞻仰', '2010-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NFwZ4VTIIYczVuESiUTsi7JjoxaXYP2MHUCnYEuimI9LyW2a2vVuOBePnvdbHUAsXzUYbV4spsops3g8BBoSgEonJeXzETzf8nSswzAuqIER-yStHsxNr8eAlxLGJPX_pdvdzPym_LDw==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (739, '报纸', '井冈山革命博物馆', '', '中国纪检监察报', '中国纪检监察报', '井冈山革命博物馆;老一辈无产阶级革命家;教育示范基地;', '井冈山革命博物馆是为纪念毛泽东等老一辈无产阶级革命家创建的第一个农村革命根据地——井冈山革命根据地而建的革命史类博物馆，于1959年10月竣工开放。馆藏文物、历史图片和文献资料3万余件；珍藏党和国家领导人、著名书画家及社会各界知名人士的墨宝珍迹数百幅；保存毛泽东', '2010-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P7r-CcobN4zaWqn0E6BOqPT4dFm1tjwqU4nLqx3SJGFTnxZDUKKTfS7oTbwI2rZQo5UIFsoKmhxwY61P6AVj4VIu2fnn0tK-6lfB3trBTuUPFOzm49ibamOVoLG_DWDcRQExZJE4o4AA==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (740, '报纸', '坚定信念闯新路', '任江华', '人民日报', '人民日报', '井冈山斗争;坚定信念;井冈山革命根据地;中国井冈山干部学院;井冈山革命博物馆;红色旅游;', '夏日，江西井冈山革命博物馆游人如织。$$ 展厅里，人们凝神观看，驻足沉思。“实物、文献、图片以及声、光、电的陈列表现形式，加深了我们对井冈山革命斗争史的了解，对井冈山精神内涵的理解。”广东游客吕先生连称“不虚此行”。$$ “井冈山斗争培育了以坚定', '2009-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N6Ot6-B9hf6u5D_h5NlFJySRYoWl_XEi3XmwWk9QzXoO3y2jI6zJVQ-jsnYi-kmoUPp3mH41NpnRQE_7lIo7Z1uoARyUNCs0Wq7dmgUs7IJ2ppV8feaKKJ7KidFCwJyvPfvxPRm7Ia1A==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (741, '报纸', '金融危机时,胡锦涛为何来到井冈山', '刘菁; 周伟; 张辛欣', '新华每日电讯', '新华每日电讯', '井冈山斗争;胡锦涛;井冈山革命博物馆;秋收起义;湘赣边界;', '新华社南昌7月5日电(记者刘菁、周伟、张辛欣)一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。 $$ 再上井冈山，重走井冈路', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NCW80DmUKLNx8AJSBmuufSNqB8hHtdwBu_tUFDS0JkWW2Lrs4fNRFKofb6k3NNj86fXg2a2tABtKu-skCB2weT3FzHEvU_GeEWularUJ301RwqYxRw6C5divhwMmdM0NDeFBOrhdyY1w==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (742, '报纸', '道路·信念·核心', '刘菁; 周伟; 张辛欣', '新华社;', '中国青年报', '井冈山斗争;井冈山革命博物馆;南昌起义;秋收起义;湘赣边界;武装夺取政权;农村包围城市;工农革命军;共产党人;科学发展观;', '一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。$$ 再上井冈山，重走井冈路，抚今追昔，我们敬仰这片红土地，自豪60年新中国。', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P1Ysfmi1R_ihIlfyuqCX9ZbiKu_AobhLHa6a6Wwr5SvLPnn7AsS7je_3ezfGwuMcLtxC4DY7oWsM7YRjy8T6Zhl2CE1OiauVuPmtU4zNdkzZQLFlqAdGU-0Y1n5vv2mjCksGNn-bMFPQ==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (743, '报纸', '请到美丽吉安来', '魏晓霞; 班若川', '中国旅游报', '中国旅游报', '吉安市;井冈山;红色旅游;旅游业;', '“提到井冈山，几乎家喻户晓，而井冈山就坐落在江西省吉安市境内。”吉安市市长王萍用最简洁的语言，说出了吉安的非比寻常。$$ 位于江西省中部、有着2000多年历史的吉安，因红色而辉煌：波澜壮阔的井冈山革命斗争，给这片红土地留下了丰富的红色遗存———三湾改编旧', '2009-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NlDwPQ1VHxTR7PX_u4Rou0iZOL1mkamfeSqV1UalHh030dju-vgPNT5mNqkiLofY7Ctl07fPQx1fJagXIRLl_251YunBkGw3JqimKItYbokZ05m17fCqQchc9ZamqL3PoPqIKkjcLsuA==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (744, '报纸', '闪耀红色与绿色的井冈山', '郭海; 张遥', '中国经济时报', '中国经济时报', '井冈山;客家文化;笔架山;客家人;休闲度假;', '这是一片神奇的土地,这是一个令人无法忘怀的地方,这是一座高度没有极限的山岳。这就是传统的红色旅游胜地井冈山。$$  红色旅游,一直以来都是井冈山特色旅游文化的代名词。然而,井冈山不止有红色的历史、红色的文化,更有青山绿水的环境和多姿多彩传统而神秘的独特文化。', '2008-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MfvBJ4yFeRiBFVSiRe8lIFsHjR6KOUA9XmiFXc3CplI7REqfJyq2K8_CSIJJ9DIhb1-az3gc-7qp_AomddQeZvMf21J1nSZnsQu5xa0GKsh4DrPX5Og1xXce0qELykcSg3OeYvBP0Ujw==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (745, '报纸', '在纪念井冈山革命根据地创建80周年大会上的讲话', '李长春', '人民日报', '人民日报', '井冈山革命根据地;光荣革命;科学发展观;全面建设小康社会;中国特色社会主义道路;', '同志们、朋友们：$$今天，我们在这里隆重集会，纪念井冈山革命根据地创建80周年。我代表党中央、国务院，向大会的召开表示热烈的祝贺！向所有参加过井冈山革命斗争的老红军、老同志，向在井冈山革命斗争中作出巨大贡献的井冈山老区人民致以诚挚的问候和崇高的敬意！$', '2007-10-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OwlgzWBG8kCH1W9nvmsbJ9wUWfGugdFIwPg9pOs3oA8Lf3yBVOco2xymN17wzMC546-bm-dnNU7t4IByiI2kE5rddAS-3P8tF6AVY2YieONAcTpvHvGb4s8K_MRDpuEm_X0OAk_Yo7gA==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (746, '报纸', '大力弘扬井冈山精神', '李文彩', '江西吉安市委;江西省委宣传部;', '光明日报', '弘扬井冈山精神;共产党人;毛泽东;井冈山斗争;马克思主义基本原理;工农红军;井冈山革命根据地;党对军队的绝对领导;共产主义理想;加强党的建设;', '井冈山精神，是以毛泽东为代表的中国共产党人把马克思主义基本原理与中国革命的具体实践相结合而培育的一种伟大革命精神。井冈山精神，集中体现了我党、我军的性质和宗旨，深刻反映了中国共产党人的崇高思想和高尚情操。在新的历史条件下，大力弘扬井冈山精神，必将激励全党', '2007-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MMGyiFq9NSUipzEzhYwdDSkr_682GPek1Quxz6mZ7kBul3PTbeKKW4yxEr20l7xcYjY8pvP2z5sswxEqYGvTlM3-XJX-nxm-6XvlHdmC8RvVEjjyAFJ-2kWyaE6Tl8im5jo2rh-4f80w==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (747, '报纸', '坚定信念育英才', '李章军', '人民日报', '人民日报', '坚定信念;体验式教学;中国井冈山干部学院;黄洋界;井冈山;', '“山下旌旗在望，山头鼓角相闻……”$$井冈山黄洋界。跨越革命风雨、激情岁月，６月初，中国井冈山干部学院学员、５０多名来自全国各高校的思想政治课骨干教师，满怀激情地朗诵着毛泽东经典诗词《西江月·井冈山》。$$半个多世纪前，这里孕育了中国革命成功', '2007-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N4bPg9FnL7-_SrlLlACd3Nqqu2CoAQnwg-vnnUZHQ9c_FmzeOdedBDhXpPdrzoR2Rf8o_bhrR0v-QCHz0444_d6pb6xCFWBMba2_vB6bkP7UCucvIvmkRkolt8ewwm9bSeQybSXVlSCg==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (748, '报纸', '毛泽东思想的形成与发展', '', '人民日报', '人民日报', '毛泽东思想;马克思列宁主义;共产党人;形成与发展;', '毛泽东思想是马克思列宁主义的基本理论与中国革命具体实践相结合的产物，是马克思主义中国化的第一个重大理论成果。$$中国共产党自成立起，就以马克思列宁主义为指导，开始了全新的中国革命。以毛泽东为主要代表的中国共产党人，根据马克思列宁主义的基本理论，把中', '2007-06-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MvG3Rn99KwlflF5IErFko8ZDulamN0FJIbRJjIUUz4vn5VVlYTg4-AFdSo5co1R4TigR1ufc94cVxuYC-tOQiptAXqd1yT9BYJFjv59PKSW3YCHGScioFSdGQlXFC6UN6a89cmAQyCBA==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (749, '报纸', '毛泽东思想的形成与发展', '', '中国青年报', '中国青年报', '毛泽东思想;马克思列宁主义;共产党人;形成与发展;', '毛泽东思想是马克思列宁主义的基本理论与中国革命具体实践相结合的产物，是马克思主义中国化的第一个重大理论成果。$$ 中国共产党自成立起，就以马克思列宁主义为指导，开始了全新的中国革命。以毛泽东为主要代表的中国共产党人，根据马克思列宁主义的基本理论，把中国革命', '2007-06-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NRB1vIejJwbSg_wrxPw5I2vh56S_WcfL9ISFL2q6a7MesS0J1qfK_8xP6TbA9dj3bq5rzAsXmmYA9ls_-LULjMTa8dQrcdMq23zgFTTFGSilDH4trnnWFahel17MCB-7odBJi0a-WNYg==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (751, '报纸', '农村包围城市、武装夺取政权思想的提出（下）', '', '人民日报', '人民日报', '农村包围城市;武装夺取政权;中央革命根据地;', '在井冈山等农村根据地建立、发展的同时，党领导的上百次以夺取城市为目标的武装起义相继失败，党在城市的工作始终处于困难境地。但是，这一时期，党领导的以土地革命为中心内容的农村游击战争却已广泛发展起来。到１９３０年上半年，全国红军已发展到十几个军，约７万人，在', '2006-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MlPgFynHGYzmpTXsYgYMzn9M00pQtbnDqXvuEXHV8UaynsuUO_6eXJgYmutyxSPuupcQXbwZDfsJ1vo1mya5bPCH8E6zFTJ0sCchtnBZyfGcow4XeFYqVIYoijUe_yTDMyGvF68gK-VA==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (752, '报纸', '农村包围城市、武装夺取政权思想的提出(上)', '', '人民日报', '人民日报', '农村包围城市;毛泽东;红色政权;武装夺取政权;', '大革命失败后，以毛泽东为代表的中国共产党人，高举起土地革命和武装反抗国民党反动统治的旗帜，肩负起独立领导中国民主革命的重任，实行武装斗争，经过创建、发展红军和农村革命根据地的实践，提出了农村包围城市、武装夺取政权的思想，逐步找到了一条适合中国特点的民主革', '2006-11-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OvFhTy6-rtZAz1GayrWGkOee39oNE3gcKbrgWx4-lnNnL_zzyNZf6miFbwhx9jzMTE_uCAdqs4iX5GrhtlEEn1Vzc6HCVwne-EWZWfU1MWKaqVw8s6Y9M3ZgPkwRNWamZomBhCkMTYFg==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (753, '报纸', '红绿交映井冈山', '陈宜萍; 范传新; 龙友谢', '金融时报', '金融时报', '井冈山市;五指峰;', '41岁的李来清既是人民银行井冈山支行的行员,同时也拥有井冈山旅游局正式颁发的导游证。因为这导游的身份，最近几年她比别人都忙，在做好本职工作的同时，好学的她博览群书，融会贯通大量与井冈山有关的史料，经常陪同来井冈山游览的各级领导，周末很少在家。$$ 而26岁', '2006-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NLwgD93w6gRnbZlcsnEYj6VRtDiaDlGSiQGDY5EmwrDcg-rxsuKeuwzutsKc1Pkf1I_g6Fu9-8aXPkHlE0-YPqP8iZKo3Qx-DyyI99QuOYo3bofUAqwk6iIHUVlosY1p8MLUZmcaJSwg==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (754, '报纸', '精神的力量', '胡晓军', '光明日报', '光明日报', '井冈山市;', '主峰海拔1586米。它并不算太高，却屹立起了一座中国革命史上令人仰止的丰碑。 $$ 1927年10月至1930年2月。当年在此进行的革命斗争历时并不算太长，却开辟出了一条马克思主义与中国革命实践相结合的光辉道路。 $$ 巍巍井冈山，连着中国共产党璀璨的历史。77年过去，它正', '2004-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NOr5hcHzpLUNEEDxuHnLH0oO-gmpmiwhx_YR89-byDIyYcBMFsw9O7xMxRDnGg32cEYs5Ay9BFihX9jesiSvLRyMCf4aTwJAB2LQVTRES2NwVet2ECl6bGQBshxRX3s3X57jY8DiZejQ==&uniplatform=NZKPT&language=CHS', '农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (757, '报纸', '心永远与农民在一起', '仲农平', '农民日报', '农民日报', '习近平总书记;农民群众;中国式现代化;农耕文明;文化自信;中华优秀传统文化;', '2024年2月1日，天津市西青区第六埠村村民杜洪刚家里迎来了一位特别的客人。上午，习近平总书记一下列车就来到去年海河特大洪水受灾的第六埠村，看灾后重建情况，同村民们一笔一笔算灾情损失和灾后生产发展、就业增收账。 这些年来，每到春节前夕，习近平总书记总会以各种方', '2024-02-05 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2024.000629', '神山村_screened');
INSERT INTO `ds_article` VALUES (758, '报纸', '神山“星火”正燎原', '王慧敏; 邢宇皓; 王斯敏; 胡晓军; 卢泽华', '光明日报', '光明日报', '农家乐;村干部;村两委;', '编者按 江西井冈山茅坪镇神山村，是一个有着光荣革命历史和鲜明时代印记的小山村。它，平凡又不平凡! 一年前，我们曾在该村蹲点调研，聆听了许许多多当年红军将士与父老乡亲之间血肉情深的感人故事，也目睹了新时代那山那水的华彩蝶变。感动，让我们捧出了那篇长篇报道《神', '2023-11-30 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.005643', '神山村_screened');
INSERT INTO `ds_article` VALUES (759, '报纸', '激发新动能 当好红土圣地守护者', '王莉莉; 曾芳洲; 肖玮; 梅琴; 刘玮', '人民公安报', '人民公安报', '公安局;井冈山市;井冈山精神;派出所;守护者;', '品牌名称：“三红三心”励警教育体系 核心理念：筑牢红色信仰，永葆忠诚之心；传承红色基因，筑牢敬仰之心；磨砺红色力量，激发担当之心 秋高气爽，巍巍井冈山层林尽染。井冈山是中国革命的摇篮。跨越时空的井冈山精神，传承着中国共产党人的初心和使命。近年来，江西省井', '2023-10-18 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2023.005625', '神山村_screened');
INSERT INTO `ds_article` VALUES (760, '报纸', '传承红色基因 助力赣鄱发展', '王欢; 王磊', '人民政协报', '人民政协报', '红色基因;井冈山革命烈士陵园;习近平总书记;吉安市;白鹭洲书院;', '传承红色基因，心系赣鄱发展。近日，30多位十三届江西省政协港澳委员和特邀海外侨胞、台胞代表，齐聚江西省吉安市开展返赣视察。 在井冈山革命烈士陵园、革命博物馆体悟“红”的厚重，在神山村、植物园体会“绿”的蓬勃；在吉州窑、白鹭洲书院感悟“古”的悠久，在经济技术', '2023-10-10 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2023.005814', '神山村_screened');
INSERT INTO `ds_article` VALUES (761, '报纸', '向星星之火指引的方向前行', '李春薇; 刘荣松; 欧阳璐', '检察日报', '检察日报', '检察院;检察干警;井冈山市;检察长;', '井冈山八角楼上，历经90余载，那盏每当夜幕降临便会亮起的清油灯还在。前来瞻仰的人见此情景，便能忆起“星星之火，可以燎原”的伟大革命历程。 八角楼上的灯光照亮的不仅是中国革命道路，还有共产党人百年不变的初心与理想信仰。 2016年2月，习近平总书记在江西考察时指出', '2023-08-06 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2023.003166', '神山村_screened');
INSERT INTO `ds_article` VALUES (762, '报纸', '踏上红土地 播下健康火种', '吴倩; 胡曦; 周翔', '健康报', '健康报', '罗庆锋;报告单;革命老区;主任医师;井冈山市;体检报告;', '红色是井冈山革命老区的底色，中国革命的星星之火从这里燎原，燃遍大江南北。6月25日，在全国上下纷纷深入开展主题教育、“七一”即将来临之际，由国家卫生健康委宣传司组织的“中国好医生、中国好护士”志愿服务总队带着健康火种来到江西省吉安市井冈山市开展“名医走基层志', '2023-06-29 08:00:00', 'https://link.cnki.net/doi/10.28415/n.cnki.njika.2023.002032', '神山村_screened');
INSERT INTO `ds_article` VALUES (763, '报纸', '江西赣州三百多场活动引起共情共振', '刘旭', '中国妇女报;', '中国妇女报', '赣州市;百姓家;习近平总书记;江西赣州;', '翻开《习近平走进百姓家》165页，面向安远县第二中学师生，赣州市三八红旗手欧阳云花绘声绘色讲起了习近平总书记来到井冈山神山村，走进红军烈士后代左秀发一家的故事。 听到村民用“糍粑越打越黏，日子越过越甜”来描述这些年的变化，现场师生们感同身受，不由自主地鼓起了', '2023-06-21 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2023.001824', '神山村_screened');
INSERT INTO `ds_article` VALUES (764, '报纸', '总书记同劳动人民在一起', '胡果; 吴秋余; 王观; 刘诗瑶', '人民日报', '人民日报', '劳动创造;劳动者;共同富裕;中华民族;中国梦;劳模精神;劳动精神;习近平总书记;中国式现代化;', '劳动，一切幸福的源泉，一切成功的必经之路。 人世间的美好梦想，只有通过诚实劳动才能实现； 发展中的各种难题，只有通过诚实劳动才能破解； 生命里的一切辉煌，只有通过诚实劳动才能铸就。 人民创造历史，劳动开创未来。 “我们的根扎在劳动人民之中。”党的十八大以', '2023-04-30 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.004590', '神山村_screened');
INSERT INTO `ds_article` VALUES (765, '报纸', '江西不断拓宽农民增收致富渠道', '郑少忠; 朱磊', '人民日报', '人民日报', '增收致富;马家柚;专业合作社;油茶产业;', '雨后的神山村，薄雾轻笼，水声潺潺，绿竹苍翠欲滴，全国人大代表、江西井冈山市茅坪镇神山村村民左香云正聚精会神地打磨手中的竹筒。不久前，他给村民们做了一次全国两会精神宣讲。 习近平总书记在参加十四届全国人大一次会议江苏代表团审议时强调，要把产业振兴作为乡村振', '2023-04-21 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.004100', '神山村_screened');
INSERT INTO `ds_article` VALUES (766, '报纸', '让大地赋我们无穷力量', '关铭闻; 王慧敏; 赵建国; 邢宇皓; 户华为; 王国平; 王琎; 彭景晖; 杨舒', '光明日报', '光明日报', '习近平总书记;社会主义;生态保护;黄河流域;调查研究局;毛泽东;中国特色社会主义道路;长江经济带;中国共产党;治国理政;', '一棵大树如何才能枝繁叶茂？唯有舒展根须不断向大地汲取营养；一条江河如何才能奔流不息？唯有敞开胸襟吸纳每一颗雨滴；一个大党如何才能永葆青春？唯有扑下身子融入人民。 春三月，中共中央办公厅印发了《关于在全党大兴调查研究的工作方案》。伴着和煦惠风，千百万党员干', '2023-04-21 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.001845', '神山村_screened');
INSERT INTO `ds_article` VALUES (767, '报纸', '向着强国建设、民族复兴的宏伟目标奋进', '', '新华社;', '人民日报', '民族复兴;习近平总书记;全面从严治党;', '中共中央总书记、国家主席、中央军委主席习近平13日在十四届全国人大一次会议闭幕会上的重要讲话，在社会各界引发强烈反响。广大代表委员和干部群众表示，新征程上，要更加紧密地团结在以习近平同志为核心的党中央周围，以坚定的信心奋发进取，以实干的行动干事创业，向着强', '2023-03-15 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.002657', '神山村_screened');
INSERT INTO `ds_article` VALUES (768, '报纸', '向着强国建设、民族复兴的宏伟目标奋进', '', '新华社;', '新华每日电讯', '民族复兴;习近平总书记;全面从严治党;', '中共中央总书记、国家主席、中央军委主席习近平13日在十四届全国人大一次会议闭幕会上的重要讲话，在社会各界引发强烈反响。广大代表委员和干部群众表示，新征程上，要更加紧密地团结在以习近平同志为核心的党中央周围，以坚定的信心奋发进取，以实干的行动干事创业，向着强', '2023-03-15 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.001545', '神山村_screened');
INSERT INTO `ds_article` VALUES (770, '报纸', '坚持人民至上的价值追求', '仲音', '人民日报', '人民日报', '人民至上;价值追求;习近平总书记;', '“我将无我，不负人民”，是不变的初心，更是坚定的行动。近日，一段记录习近平总书记十年来躬身力行、深入群众之中的短视频让人感动至深。顶风雪、冒酷暑，踏泥泞、翻山沟，从黄土高坡到青藏高原，从太行山区到乌蒙山区，从零下几十摄氏度到海拔数千米，习近平总书记风雨兼', '2022-10-16 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.011834', '神山村_screened');
INSERT INTO `ds_article` VALUES (772, '报纸', '充分发挥党总揽全局、协调各方的领导核心作用', '孟祥夫', '人民日报', '人民日报', '领导核心作用;总揽全局;习近平总书记;党中央;中国特色社会主义制度;', '“没有共产党就没有新中国，共产党辛劳为民族，共产党他一心救中国……”这首谱写于革命战争年代的歌曲，被一代代中华儿女传唱着，迎来新中国，走进新时期，跨入新时代。历史和现实都告诉我们，没有中国共产党，就没有新中国，就没有中国特色社会主义。 党的十九届六中全会', '2022-08-16 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.008843', '神山村_screened');
INSERT INTO `ds_article` VALUES (773, '报纸', '不负人民 人民不负', '', '光明日报', '光明日报', '建党初期;习近平总书记;共产党;', '共产党人打江山、守江山，到底是为了什么？是为了人民! 只有为人民谋福祉，只有与人民同甘苦，才能赢得民心，才能从胜利走向胜利。神山村近百年的发展历程，就是明证! 历史回望，在那血雨腥风的年代，我们之所以能在重重包围中打拼出一个红彤彤的井冈山革命根据地，靠的是', '2022-07-21 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.003389', '神山村_screened');
INSERT INTO `ds_article` VALUES (774, '报纸', '为老区创新发展贡献检察力量', '刘荣松; 欧阳晶', '检察日报', '检察日报', '检察院;贫困户;吉安市;', '盛夏时节，江西吉安草木葱茏、天高云淡、禾香鱼肥，丰沃的庐陵大地处处生机勃勃，一幅革命老区高质量发展的美丽画卷正徐徐展开。 作为吉安市管辖范围的一部分，曾经的井冈山革命老区已展现新颜。6年前，习近平总书记来到井冈山市考察，走进井冈山市茅坪乡神山村，对脱贫攻坚', '2022-07-11 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2022.003063', '神山村_screened');
INSERT INTO `ds_article` VALUES (775, '报纸', '发挥基层党组织引领作用，打造新时代乡村振兴新样板', '朱磊; 王丹', '人民日报', '人民日报', '基层党组织;村党组织;井冈山市;战斗堡垒作用;引领作用;', '党的基层组织是确保党的路线方针政策和决策部署贯彻落实的基础，是群众的“主心骨”。 2016年2月2日，在江西井冈山市茅坪乡（现为茅坪镇）神山村红军烈士后代左秀发家中，习近平总书记对一家人立足本地资源、依靠竹木加工增收脱贫的做法给予肯定。在村党支部，总书记看规划', '2022-06-08 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.005984', '神山村_screened');
INSERT INTO `ds_article` VALUES (776, '报纸', '在推动中部地区崛起上勇争先', '郑少忠; 朱磊; 王丹', '人民日报', '人民日报', '江西省;富硒蔬菜;产业园;习近平总书记;中部地区崛起;产业链;红色基因;', '巍巍井冈山，滔滔赣江水。满山的杜鹃红了，遍野的秧苗泛着青绿，赣鄱大地生机盎然。 党的十八大以来，习近平总书记两次赴江西考察调研，参加十二届全国人大三次会议江西代表团审议，对江西提出“努力在加快革命老区高质量发展上作示范、在推动中部地区崛起上勇争先”的殷切', '2022-06-08 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.005987', '神山村_screened');
INSERT INTO `ds_article` VALUES (777, '报纸', '吉安：赓续红色血脉 当好红军传人', '陈希; 曾芳洲; 欧阳长春', '人民公安报', '人民公安报', '吉安市公安局;革命老区;人民警察;公安机关;井冈山精神;红色基因;', '开栏的话 一切向前走，都不能忘记走过的路。革命老区是新中国的摇篮。无数革命先辈在老区用鲜血和生命，铺就了一条通往今天幸福生活的道路，留下了一大笔可贵的精神财富。 奋进新征程，建功新时代。为迎接党的二十大胜利召开，本报自即日起，开设“革命老区公安行”专栏，', '2022-06-05 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2022.002795', '神山村_screened');
INSERT INTO `ds_article` VALUES (779, '报纸', '“总书记，乡亲们非常想念您!”', '林晖; 熊争艳; 屈婷; 杨玉华; 何宗渝; 孙奕; 施雨岑; 孙少龙; 王鹏; 徐壮', '人民日报', '人民日报', '全面从严治党;人大代表;', '早春时节，近5000名代表委员汇集首都北京，共赴一场春天的盛会。来自天南海北、身处各行各业，他们带来人民群众最真诚的嘱托和期盼。 这些年来，习近平总书记带领亿万人民战贫、抗疫、反腐、铸魂……气吞山河的史诗画卷中，记录下一处处乡村的旧貌新颜，一个个群体的命运转', '2022-03-10 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.002462', '神山村_screened');
INSERT INTO `ds_article` VALUES (780, '报纸', '脱贫户的生活更上一层楼', '陈有连; 倪赣军; 左小煌; 莫志超', '农民日报;中国农网;', '农民日报', '脱贫户;合作社;吉安市;吉水县;', '临近中午，彭夏英便开始忙活晚饭，晚上有7桌客人要来她家做客。2016年春节前夕，在江西看望慰问广大干部群众的习近平总书记来到井冈山上的神山村，走进贫困户彭夏英和丈夫张成德家中，算收入、问需求。总书记的到来让彭夏英一家的生活大变样，也给吉安市的脱贫攻坚和后续巩固', '2022-03-04 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2022.000804', '神山村_screened');
INSERT INTO `ds_article` VALUES (781, '报纸', '星火再燎原', '郭强; 熊家林; 郭杰文', '新华每日电讯', '新华每日电讯', '井冈山;山乡巨变;柏露乡;东上乡;', '新华社南昌2月23日电（记者郭强、熊家林、郭杰文）江西井冈山，中国革命的星火从这里燃遍大江南北，脱贫攻坚战胜利的星火从这里席卷神州大地。 2017年2月，井冈山在全国率先脱贫，成为我国贫困退出机制建立后首个“摘帽”的贫困县。井冈山农村居民人均可支配收入已从2017年', '2022-02-24 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.001407', '神山村_screened');
INSERT INTO `ds_article` VALUES (782, '报纸', '丹心如一为人民', '张旭东; 赵超; 吴晶; 林晖; 朱基钗; 刘敏', '新华社;', '新华每日电讯', '习近平总书记;人民幸福;', '岁月流转，真情永恒。$$ 虎年春节即将到来之际，习近平总书记再次来到人民中间，给千家万户送去新春的美好祝福。这是党的十八大以来，习近平总书记第十个年头在春节前看望慰问基层干部群众。$$ “我无论多忙，都要抽时间到乡亲们中走一走看一看。”$$ 走过一条条崎岖不平', '2022-01-31 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.000909', '神山村_screened');
INSERT INTO `ds_article` VALUES (783, '报纸', '丹心如一为人民', '张旭东; 赵超; 吴晶; 林晖; 朱基钗; 刘敏', '人民日报', '人民日报', '习近平总书记;全面从严治党;姜德明;对口帮扶;中央政治局常委;人民幸福;', '岁月流转，真情永恒。$$ 虎年春节即将到来之际，习近平总书记再次来到人民中间，给千家万户送去新春的美好祝福。这是党的十八大以来，习近平总书记第十个年头在春节前看望慰问基层干部群众。$$ “我无论多忙，都要抽时间到乡亲们中走一走看一看。”$$ 走过一条条崎岖不平', '2022-01-31 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.001071', '神山村_screened');
INSERT INTO `ds_article` VALUES (785, '报纸', '感悟红色精神 砥砺初心使命', '张博', '中国新闻出版广电报', '中国新闻出版广电报', '井冈山精神;井冈山革命博物馆;共产党人;江西日报;红色精神;短视频;《解放军报》;井冈山革命根据地;', '历史是理解未来的钥匙。百年来，中国共产党带领中国人民走出一条从站起来到富起来，再到强起来的康庄大道，实现了从“赶上时代”到“引领时代”的伟大跨越。在百年奋斗历程中，中国共产党团结带领人民取得一个又一个胜利，以井冈山精神等为代表的革命精神发挥了重要作用。$$', '2022-01-19 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.000188', '神山村_screened');
INSERT INTO `ds_article` VALUES (786, '报纸', '“我们的日子一天比一天好”', '廖文根; 姜洁; 易舒冉; 杨颜菲', '人民日报', '人民日报', '翻身不忘共产党;', '我们国家是人民当家作主，包括我在内，所有领导干部都是人民勤务员。$$ 我们党是全心全意为人民服务的党，将继续大力支持老区发展，让乡亲们日子越过越好。$$ ——习近平$$ 江西吉安井冈山市茅坪镇神山村位于罗霄山脉深处，云雾环绕。村里竖着一块牌子，上面写着：“神山', '2022-01-11 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.000285', '神山村_screened');
INSERT INTO `ds_article` VALUES (787, '报纸', '井冈山精神——跨越时空，照亮前行之路', '', '中国民族报', '中国民族报', '井冈山精神;井冈山革命根据地;', '井冈山，中国革命的摇篮。$$ 中国共产党人在创建和发展井冈山革命根据地的过程中，形成了坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利的井冈山精神。$$ 2016年春节前夕，习近平总书记来到江西，看望慰问广大干部群众和驻赣部队，首站就是井冈山。习近平总', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001151', '神山村_screened');
INSERT INTO `ds_article` VALUES (790, '报纸', '井冈山：用好红色资源 走出发展新路', '罗嗣尧; 周晨', '中国旅游报', '中国旅游报', '井冈山;井冈山革命博物馆;红色资源;', '1927年10月，毛泽东同志率领秋收起义部队走上井冈山，开始工农武装割据斗争。在这里，中国共产党人开辟了“农村包围城市、武装夺取政权”的中国革命道路，孕育了“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”的井冈山精神。$$ 如今，井冈山结合新的时代', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002146', '神山村_screened');
INSERT INTO `ds_article` VALUES (791, '报纸', '井冈山精神放射新的时代光芒', '卢翔', '工人日报', '工人日报', '井冈山精神;井冈山革命烈士陵园;讲解员;', '一座山，辉映历史；一种精神，照耀未来。$$ 井冈山是中国革命摇篮。90年前，以毛泽东、朱德为代表的中国共产党人在这里创建了第一块农村革命根据地，开展了艰苦卓绝的井冈山斗争，开辟了中国特色的革命道路。$$ 井冈山斗争孕育了伟大的井冈山精神。“坚定信念、艰苦奋斗，', '2021-07-25 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2021.003468', '神山村_screened');
INSERT INTO `ds_article` VALUES (792, '报纸', '井冈山精神跨越时空闪耀光芒', '赖永峰; 刘兴', '经济日报', '经济日报', '井冈山精神;井冈山革命博物馆;习近平总书记;', '中国共产党始终把共产主义远大理想写在旗帜上，将马克思主义作为根本指导思想，并将其与中国具体实际相结合，引领革命向着胜利方向前进。井冈山斗争就是在这一理想信念引领下进行艰苦卓绝奋斗的光辉实践。$$ “井冈山是中国革命的摇篮。井冈山时期留给我们最为宝贵的财富，', '2021-07-24 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005541', '神山村_screened');
INSERT INTO `ds_article` VALUES (793, '报纸', '井冈山下的法治“播火者”', '郑海啸; 杨璐嘉; 胡文星', '检察日报', '检察日报', '井冈山市;检察院;检察建议;公益诉讼;播火者;', '一道光，划破苍穹；一座山，辉映历史；一种精神，照耀未来。$$ 90多年前，毛泽东率领秋收起义部队来到井冈山，创立了中国共产党领导的第一个农村革命根据地——井冈山革命根据地。而后，这簇星星之火熊熊燃烧，指引着中国革命一步步走向胜利。$$ 又是一年映山红开，记者怀', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.003638', '神山村_screened');
INSERT INTO `ds_article` VALUES (794, '报纸', '井冈山：“挑水人”挑起使命担当', '温婷婷; 王子鹏; 张斌', '中国水利报', '中国水利报', '井冈山;水利局;井冈山市;城乡供水;', '在井冈山革命博物馆陈列柜中，两只破旧的水桶格外引人注目，这是当年毛泽东同志帮房东周香姬挑水用的水桶。$$ 1928年5月，毛泽东来到江西省吉安市永新县塘边村考察，住在贫农周香姬家中。周大娘唯一的儿子参加红军去了前线，平时的家务活、农活全都压在她和儿媳的肩上。毛泽', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2021.001193', '神山村_screened');
INSERT INTO `ds_article` VALUES (795, '报纸', '牢记嘱托 幸福产业助力老区振兴发展', '任丽; 周晨; 王文华; 李志刚', '中国旅游报', '中国旅游报', '老区;幸福;产业;助力;', '习近平总书记在庆祝中国共产党成立100周年大会上指出，我们深切怀念为中国革命、建设、改革，为中国共产党建立、巩固、发展作出重大贡献的老一辈革命家，深切怀念为建立、捍卫、建设新中国英勇牺牲的革命先烈，深切怀念为改革开放和社会主义现代化建设英勇献身的革命烈士，深', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.001990', '神山村_screened');
INSERT INTO `ds_article` VALUES (796, '报纸', '信念的力量指引胜利', '周玮; 高皓亮; 赖星', '新华社;', '新华每日电讯', '井冈山革命博物馆;井冈山精神;井冈山革命根据地;共产党人;习近平总书记;', '井冈山八角楼前，一棵在石下萌芽扎根的枫树竟把石头撑开，历经90余载风雨依然高大挺拔。$$ 中国共产党历史展览馆里，一盏红军在井冈山使用的油灯，映照中国共产党人百年不变的初心与信念。$$ 循着百年大党的精神之源，让我们聚焦中国共产党精神谱系中这个重要的红色坐标—', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005327', '神山村_screened');
INSERT INTO `ds_article` VALUES (797, '报纸', '恢宏史诗耀千秋', '邬焕庆; 赵超; 熊争艳; 王鹏; 黄垚; 戴小河', '新华社;', '新华每日电讯', '习近平总书记;第一个;全面建成小康社会;中国共产党;奋斗目标;家庭医生;', '“经过全党全国各族人民持续奋斗，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会，历史性地解决了绝对贫困问题，正在意气风发向着全面建成社会主义现代化强国的第二个百年奋斗目标迈进。”$$ 7月1日，习近平总书记在庆祝中国共产党成立100周年大会上的庄严', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005328', '神山村_screened');
INSERT INTO `ds_article` VALUES (798, '报纸', '热情讴歌百年伟业 坚定信念再创辉煌', '', '人民日报', '人民日报', '党史学习;习近平总书记;坚定信念;百年华诞;创业史;南华西街道;井冈山市;奋斗目标;汉正街;再创辉煌;', '7月1日，巍巍井冈，天朗气清。位于黄洋界脚下的江西井冈山市茅坪镇神山村格外热闹，乡亲们围坐在村部办公楼里，集中收看庆祝中国共产党成立100周年大会直播。$$ “在这里，我代表党和人民庄严宣告，经过全党全国各族人民持续奋斗，我们实现了第一个百年奋斗目标，在中华大地', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006859', '神山村_screened');
INSERT INTO `ds_article` VALUES (800, '报纸', '四十年后再出发', '', '农民日报', '农民日报', '农民工;四十年;大包干;“剪刀差”;乡镇企业;', '一$$ 1978年，新年的第一缕晨曦像往常一样唤醒中国，即使最大胆的预言家也不敢想象，在这一年接近尾声的时候，看上去那么坚不可摧的幕布，会被撕开一个口子；并从这个口子开始，以摧枯拉朽的态势在中国大地上熊熊燃烧起来。$$ 一个改变亿万中国人命运的大时代开始了。$$', '2018-12-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PgpCV9bTad6KMuETfyOZWzeWMRG0MLHJc2WdBlmcXGncxhk-rF_ebSAR_qIQ80GWhKkASyvJwc8yNfd74G2S8snBrbrSPyrVX8nS8IAuB454k8hWoLqyYeIIwi9FvYFjfDx_gQbHSTHg==&uniplatform=NZKPT&language=CHS', '神山村_screened');
INSERT INTO `ds_article` VALUES (801, '报纸', '新时代，携手书写新答卷', '沈刚', '工人日报', '工人日报', '高质量发展;供给侧结构性改革;国内生产总值;稳中有进;中央经济工作会议;习近平总书记;减少贫困;', '时序更替，早春时节的中国，即将进入两会时间。国家的宏伟愿景，人民的幸福期盼，再次交汇在祖国的心脏。$$ 全球的目光，热切地投向这里。因为，随着软硬实力的稳步增长，中国为发展中国家拓展了走向现代化的途径，也为促进全球治理体系变革贡献了中国智慧和中国主张。$$', '2018-03-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OS4vrNpu1UxwOyMUNjM_KYhYHK5Z-JWTlr-5HUmsGR5_QKix5a48pmGtDR--BOTGTKe0m3CfJElEqdcvamxJgIrnsdnc5EPyBExOBVWFFy6QFFGAMS62_iwSbMHOSaiyIfxEYkSbSPdA==&uniplatform=NZKPT&language=CHS', '神山村_screened');
INSERT INTO `ds_article` VALUES (802, '报纸', '实践创新不忘初心', '', '人民日报', '人民日报', '发展理念;以人民为中心;社会主义中国;习近平总书记;', '砥砺奋进的征途上，“以人民为中心”的发展理念贯穿始终，照见的正是共产党人的初心$$ “你呀，不错嘞，好书记啊！”$$ 2016年春节前夕，江西井冈山市神山村。年过七旬的老支书彭水生，向习近平总书记竖起大拇指。$$ 质朴的点赞，是人民群众对共产党发自内心的认同、发', '2017-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Op3c_zHCbPRXAD8iggBpQyEeGWLCztVJwYxQPNcapsekL_0J9aRxePWGa8RHPobYMg2s3MDZ8nwEt24TcI5H0zUJiX0PpMyVYO74yZg8OJIzv-MZVdwYhCDNrni3ZH30u3Ynp5rR4yHQ==&uniplatform=NZKPT&language=CHS', '神山村_screened');
INSERT INTO `ds_article` VALUES (803, '报纸', '乘风破浪正当时 定将改革进行到底', '刘冬林', '团北京市委组织部;', '中国青年报', '时时刻刻;公租房;', '最近，同事之间看得最多、聊得最多的就是《将改革进行到底》专题片。大家被纪录片的恢弘、诚恳所震撼，更为十八大以来的改革进展所折服。$$ “你呀，不错嘞!”$$ 这是《将改革进行到底》第一集和第十集都有的亲切一幕，井冈山市茅坪乡神山村的彭水生老人握住习近平总书记', '2017-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O_K_PB5EXo5qG-n15gj7-yA6Vt3ZWVd4AZmzbS_C2GPjOu9gRF4nroeFqDH1kQbIs_IS8naE14j0-qY7xxJkJLPpJ0vUBsByNouIOCdHEtXnb4VK41kUbKIQ2n33HK-NhOrjYGYb2W6A==&uniplatform=NZKPT&language=CHS', '神山村_screened');
INSERT INTO `ds_article` VALUES (804, '报纸', '井冈山：创新发展奔小康', '', '井冈山管理局;', '中国旅游报', '井冈山;红色旅游;奔小康;景区管理;', '井冈山是中国革命摇篮，境内旅游资源十分丰富，拥有11个景区、76处景点、460多个景物景观，保存完好的革命遗址、旧址100多处，具有发展红色旅游的良好条件。近年来，井冈山依托旅游资源优势，围绕“红色最红、绿色最绿、脱贫最好”的目标，坚持“红色引领、绿色崛起”发展战', '2017-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OXb3ToPEdx1NcfA6a3hwEEyk_M43Hg9Oye291C4ISBm_54hjv0JyZReiSl8MZI5C4uLsliJVsDRwoj3DKAxlYcgruUH5NiBdwtLN35HfJ635hVMIxEY2SdLM7FXOPIlY73Q67yrOM7jg==&uniplatform=NZKPT&language=CHS', '神山村_screened');
INSERT INTO `ds_article` VALUES (805, '报纸', '精准发力打好脱贫攻坚战', '', '人民日报', '人民日报', '攻坚战;精准发力;精准扶贫;', '“井冈山要在脱贫攻坚中作示范、带好头”。江西井冈山市牢记习近平总书记的嘱托，奋力向贫困宣战。如今，这个革命老区的脱贫摘帽，为全国上下齐心协力打好脱贫攻坚战注入了更大信心。$$ 在主持中共中央政治局第三十九次集体学习时，习近平总书记强调，“农村贫困人口如期脱', '2017-02-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PH6tFj6MPs6cH-4ywqMjMSR60Qu5LAD5nIrl5zeJPoE88cLVL-dD3yF3kWDL3yPGniffzwzzn9BG0mtHHspJEZyVcg65kpA9tAE1jzSm9jKi8R7eWSOz53T-L9ha8wjulLUKVGnf9zpw==&uniplatform=NZKPT&language=CHS', '神山村_screened');
INSERT INTO `ds_article` VALUES (807, '报纸', '英勇奋战 屡建战功 卢德铭', '', '人民日报', '人民日报', '卢德铭;毛泽东;', '据新华社北京３月２日电 １９２７年９月２５日，毛泽东率领的秋收起义军在向井冈山进军途经江西萍乡芦溪县时遭到国民党军伏击，总指挥卢德铭在战斗中英勇牺牲。得知这一噩耗后，毛泽东痛心疾呼：“还我卢德铭！”$$ 卢德铭，又名继雄，字邦鼎，号又新。１９０５年生', '2011-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Mi6PFahImHmUKeFVDlC86xHV3wfsYEc2rE3mtz-YangZtCPDpiSA4_LmTrvZF95w5lWBE7wd4cE1jKSaIt6hqaPeYkljotCgdYalvdTIN6nxvJlR7OdvuIQkZYr6p5bYN9NssWL03vfw==&uniplatform=NZKPT&language=CHS', '宛希先_screened');
INSERT INTO `ds_article` VALUES (808, '报纸', '宛希先', '', '人民日报', '人民日报', '宛希先;湘赣边界特委;党代表;', '宛希先，1906年生，湖北黄梅人。1924年在黄梅八角亭高等小学读书时，在堂兄宛希俨和黄梅县进步知识青年的影响下，接受革命思想，参加革命活动。1925年加入中国共产党。1926年秋到武汉，入国民革命军第二方面军总指挥部警卫团5连当兵，后任连长。1927年9月参加湘赣边界秋收起', '2006-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OhTLXxKD799H90SW1KOUe0QS1lUp0-zQjQW1z73Fhg6vyrg74Hoj7OzHtrylXCWrFIKafiaWdZE82q76orsPnoR4RWZx3nWlMLBzsPlEXnZ_swIPHEWAgIpgTdLB0xti9AJzBZYZpAxQ==&uniplatform=NZKPT&language=CHS', '宛希先_screened');
INSERT INTO `ds_article` VALUES (810, '报纸', '支部建在连上，更要强在连上', '张磊峰; 邓栋之; 尚宗昌', '解放军报', '解放军报', '支部建在连上;战斗堡垒;组织生活;雷达站;战区空军;', '1927年，毛主席领导的“三湾改编”，将党的支部建在连上，从政治上组织上保证了党对军队的绝对领导，对人民军队产生了深远影响。 进入新时代，习主席对基层党组织建设高度重视，一以贯之强调“扭住党的组织抓基层”，对基层党组织的地位作用、职责功能、发力重点、队伍建设', '2023-11-06 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2023.003399', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (811, '报纸', '“红色故事”激发职工建功热情', '曾思云; 胡青松', '工人日报', '工人日报', '红色基因;吉安市;', '“我聆听了吉安工运先驱梁一清烈士的故事，深切感受吉安工运的辉煌过往，收获良多。”近日，参观完中华全国总工会苏区中央执行局和二七会议旧址后，江西省吉安市总工会年轻干部邓淑敏慨叹。 吉安是革命老区，拥有丰富的红色资源和工运资源，如何运用好这些红色资源“富矿”', '2023-10-30 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2023.005214', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (815, '报纸', '为实现中华民族伟大复兴提供战略支撑', '李学勇; 黄明; 梅常伟', '人民日报', '人民日报', '中华民族伟大复兴;人民军队;党对军队绝对领导;中央军委;习近平;战略支撑;军委主席;时代使命;政治建军;党中央;世界一流;社会主义制度;强军目标;武警部队;强军之路;', '中华民族走出苦难、中国人民实现解放，有赖于一支英雄的人民军队。 中华民族实现伟大复兴，中国人民实现更加美好生活，必须加快把人民军队建设成为世界一流军队。 中共中央总书记、国家主席、中央军委主席习近平在庆祝中国人民解放军建军90周年阅兵时发表重要讲话指出：“', '2022-08-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.008204', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (816, '报纸', '运用好红色资源 传播好红色文化', '李兴文; 姚子云; 袁慧晶; 贾伊宁', '新华每日电讯', '新华每日电讯', '红色文化;红色资源;动漫创作;红色题材;三湾改编;《闪闪的红星》;鲁迅美术学院;', '新华社北京6月30日电(记者李兴文、姚子云、袁慧晶、贾伊宁)“到那时，到处都是活跃跃的创造，到处都是日新月异的进步……”在江西弋阳县的方志敏纪念馆前，时常响起《可爱的中国》的诵读声。青年学生们在这里献上鲜花，诵读烈士笔下的绝唱，感怀那段烽火硝烟岁月中对祖国的热', '2022-07-01 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.004929', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (817, '报纸', '抱团发展 老区振兴取得“乘数效应”', '苏晓洲; 刘良恒; 赖星; 崔璐', '经济参考报', '经济参考报', '湘东区;区域合作;上栗县;示范区建设;乘数效应;交界地区;烟花爆竹;省际通道;长株潭地区;萍乡市;', '一句“老表”，道出湘赣地缘人缘血脉亲情。在大革命时期，老一辈无产阶级革命家扎根湘赣边界，与当地人民并肩作战，为新中国的建立铸就不朽功勋。百年党史上，湘赣边革命老区走出了180多位开国将军，在革命战争中牺牲的烈士多达30万人，秋收起义、三湾改编等重大历史事件在这', '2022-05-10 08:00:00', 'https://link.cnki.net/doi/10.28419/n.cnki.njjck.2022.002185', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (818, '报纸', '红色是鲜亮的底色', '朱磊', '人民日报', '人民日报', '红色资源;红色基因;', '安源路矿，掀起工人运动的高潮；秋收起义，第一次亮出中国共产党的旗帜；井冈山，革命摇篮孕育燎原的“星星之火”；桂东沙田，“第一军规”历久弥新……湘赣边革命老区的土地上，有许多难以忘却的红色记忆。 行走湘赣边，红色资源在焕发活力。老区人民捐出祖屋，做宣教基地', '2022-04-27 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.004420', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (820, '报纸', '军旗永跟党旗走', '安普忠', '解放军报', '解放军报', '全军官兵;人民军队;听党指挥;党对军队绝对领导;习近平;优良传统;', '“只有中国共产党领导的人民军队，才能创造这个奇迹。”正在全国热映的电影《长津湖之水门桥》背后的真实历史，成为参加全国两会的军队代表委员们热议的话题。 铁心向党、至死不渝，英雄用生命捍卫的，是人民军队坚决听党指挥的赤胆忠心，是人民军队对党绝对忠诚的优良传统', '2022-03-06 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.001193', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (821, '报纸', '从百年党史中汲取奋斗强军力量', '丁增义; 张汨汨', '新华社;', '人民日报', '党史学习;习近平;政治整训;', '党的历史是最生动、最有说服力的教科书。$$ 在中国共产党百年华诞的重大历史时刻，以习近平同志为核心的党中央立足百年党史新起点、着眼开创事业发展新局面，作出在全党开展党史学习教育的重大战略决策。$$ 一年来，全军坚持用习近平新时代中国特色社会主义思想特别是习近', '2022-01-10 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.000255', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (822, '报纸', '党指挥枪 无往而不胜', '陈东恒', '学习时报', '学习时报', '人民军队;中国特色社会主义;习近平;科学论断;党指挥枪;党组织;新中国成立初期;全心全意为人民服务;古田会议;党的组织建设;党中央;马克思主义;', '立足建党百年历史当口，回望我军从无到有、由小变大、自弱向强的来程去路，从根本上深切把握党对人民军队政治、思想和组织领导的历史必然性、科学真理性，更加坚定自觉坚持党对军队绝对领导的根本原则制度，更加坚定自觉团结在以习近平同志为核心的党中央周围，把强军事业推', '2022-01-03 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2022.000014', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (824, '报纸', '北科大：修炼推优“内功”为党育人', '王姗姗; 杨凤琦', '中青报;中青网;', '中国青年报', '推优工作;团组织;第二课堂;成绩单;团支部书记;入党积极分子;北科大;', '“马克思主义是信仰，加入中国共产党是我的追求。人需要有理想、有梦想，更需要有信仰，这样我们才能即使身在井隅，却心向阳光。”近日，北京科技大学大二学生彭子颖在团支部推优大会上表达了入党志愿。$$ 在北科大，这样的推优大会时常召开，每一名追求进步的共青团员都要', '2021-12-16 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.004431', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (825, '报纸', '重温百年党史 担当时代重任', '杨宝光', '中青报;中青网;', '中国青年报', '文艺工作者;文化自信;', '连日来，新兴领域青年通过网络、电视、报纸、广播等渠道，认真学习党的十九届六中全会精神并展开了热烈讨论。$$ 回顾党百年奋斗的壮阔历程，铭记重大成就，承先辈志、铸爱国魂$$ 天津网络作家、第十七期青社学堂学员猫冬说，今年有机会参加了团中央在井冈山举办的“青社学', '2021-12-13 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.004387', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (826, '报纸', '中国共产党现存最早的入党誓词', '', '学习时报', '学习时报', '入党誓词;毛泽东;中国共产党;入党宣誓;', '入党誓词是中国共产党党员的宣誓书，是每名党员加入中国共产党时对自己作出的严格要求，对党作出的自我保证，对人民作出的庄严承诺。在不同的历史时期，中国共产党的入党誓词内容不同。$$ 在中国共产党历史展览馆，陈列着中国共产党现存最早的入党誓词，这就是江西永新农民', '2021-12-10 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002333', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (828, '报纸', '加快国防和军队现代化', '', '解放军报', '解放军报', '人民军队;绝对领导;中华民族;军队现代化;军队现代化建设;', '强国必须强军，军强才能国安。党的十九届六中全会全面回顾党领导人民军队从小到大、从弱到强、从胜利走向胜利的光辉历程，深刻阐述了新时代以来国防和军队建设取得的历史性成就、发生的历史性变革，并对加快国防和军队现代化作出战略擘画，为实现党在新时代的强军目标、把人', '2021-11-20 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007235', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (829, '报纸', '支部建在连上 正气充盈心间', '', '解放军报', '解放军报', '李延年;基层政治干部;支部建在连上;', '编者按 近日，电视剧《功勋·能文能武李延年》受到观众广泛好评。李延年的形象为什么能够得到观众充分认同？因为他展示出我军基层政治干部应有的样子，更道出我军无往不胜的根本原因——支部建在连上，正气充盈心间。如何赓续我军优良传统、做新时代“李延年式”政治干部？', '2021-11-16 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.008094', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (830, '报纸', '井冈山精神——跨越时空，照亮前行之路', '', '中国民族报', '中国民族报', '井冈山精神;井冈山革命根据地;', '井冈山，中国革命的摇篮。$$ 中国共产党人在创建和发展井冈山革命根据地的过程中，形成了坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利的井冈山精神。$$ 2016年春节前夕，习近平总书记来到江西，看望慰问广大干部群众和驻赣部队，首站就是井冈山。习近平总', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001151', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (831, '报纸', '军魂：我军无往不胜之源', '刘正斌', '国防大学习近平新时代中国特色社会主义思想研究中心;', '解放军报', '李延年;政治建军;革命军人;党组织;战斗力;', '近日，电视剧《功勋·能文能武李延年》热播，在全社会引起热烈反响，引发了人们对战场真正需要什么样的政治干部的深度思考。李延年是我党我军培养的众多优秀政治干部的缩影，透过这位英雄人物能文能武的高大形象，我们再次深刻认识到，坚持党对军队的绝对领导，矢志不渝听党', '2021-11-08 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007014', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (832, '报纸', '新时代，我们呼唤更多的“李延年”', '韩国贤; 柴华', '解放军报', '解放军报', '李延年;共和国;政治干部;江永红;', '李延年表情严肃，眼神里，透着军人的刚毅。$$ 这是在已公开的多数照片里，他留给人们的印象。$$ 记者看到的一张合影里，他笑容可掬。合影的对象，是解放军报原副总编辑、军旅作家江永红。合影的时间，是2019年12月24日。$$ 那是一次长达10天、相谈甚欢的采访结束后，战友', '2021-11-06 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006994', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (833, '报纸', '铁心向党代代相传', '费士廷; 韩成; 胡瑞智', '解放军报', '解放军报', '杨根思连;党组织;红一连;听党指挥;集团军;', '国庆假期，电影《长津湖》燃爆全国院线。志愿军将士不畏强敌、不惧生死的英雄风骨撼人心魄，感动亿万观众。$$ “我们的身后就是祖国，为了祖国人民的和平，我们不能后退一步!”志愿军将士的英雄壮举，源于革命军人对党和人民的无限忠诚。$$ “坚持党指挥枪、建设自己的人民', '2021-11-05 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006967', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (834, '报纸', '从伟大建党精神中汲取力量', '郭亚利', '贵州省桐梓县委;组织部;', '中国组织人事报', '村党组织;', '习近平总书记在庆祝中国共产党成立100周年大会上科学总结了“坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民”的伟大建党精神。党员干部要从伟大建党精神中汲取力量，补足精神之钙、把稳思想之舵，筑牢共产党人爱党爱国、爱民重民、爱岗敬', '2021-10-15 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.003223', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (840, '报纸', '开辟主题电影新型表达方式', '杨雯; 沈舒雅', '中国新闻出版广电报', '中国新闻出版广电报', '毛泽东;李大钊;焦裕禄;革命者;表达方式;', '建党百年献礼影片集中涌现，且题材丰富、类型多样、风格各异，其中有展现革命峥嵘岁月的《1921》《红船》，有致敬英雄先烈的《革命者》，有反映重大革命事件的《三湾改编》，有讴歌优秀共产党员感人事迹的《守岛人》《我的父亲焦裕禄》以及《柳青》，有致敬伟大抗疫英雄的《', '2021-08-11 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.003195', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (841, '报纸', '百年风华熔铸党指挥枪', '刘小兵', '光明日报', '光明日报', '人民军队;习近平;听党指挥;党对军队绝对领导;军队建设思想;党组织;解放战争;党指挥枪;', '历史长河波澜壮阔，百年历程栉风沐雨。$$ 1921年7月，开天辟地大事变，中国有了共产党。1927年8月，南昌城头炮声隆，人民军队诞生了。从此，党旗所指，军旗所向。在中国共产党的领导下，人民军队一路披荆斩棘，历经硝烟战火，克服一个又一个困难，战胜一个又一个强敌，夺取', '2021-08-01 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003901', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (842, '报纸', '铭记光辉历史 续写强军新篇', '李学勇; 黎云; 张汨汨', '新华社;', '人民日报', '人民军队;根本宗旨;全心全意为人民服务;军队建设思想;党对军队绝对领导;习近平;中国共产党成立;', '百年党史波澜壮阔，强军征程一路向前。历史，是最好的教科书。$$ 这是一支中国共产党亲手缔造的队伍。这是一支值得党和人民信赖的武装。$$ 人民军队一路走来，为党和人民建立了不朽功勋，是保卫红色江山、维护民族尊严的坚强柱石，是维护地区和世界和平的强大力量。进入新', '2021-08-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007993', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (844, '报纸', '铁心向党的红色传人', '李龙伊', '人民日报', '人民日报', '红一连;连队党支部;听党指挥;', '三秦之地，华山脚下，驻守着一支战功卓著、声名赫赫的英雄连队。$$ 走进这支连队的连史馆，一件件展品、一幅幅照片，铭刻着这支连队的厚重历史：“百战百胜”“英勇连”等一面面战旗，展示着连队取得的辉煌成绩；参与“三湾改编”、警卫遵义会议等历史事件，昭示着连队铁心', '2021-07-27 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007781', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (847, '报纸', '一堂授课，一次红色洗礼', '沙子钺; 陈利', '解放军报', '解放军报', '太爷爷;雷打石;黄洋界;井冈山;', '“‘红军荟萃井冈山，主力形成在此间’。在这里，‘朱毛’携手创建中国第一块农村革命根据地，开启了中国革命的新篇章……”仲夏时节，武警江苏总队某部党史学习教育课堂上，7名井冈山籍新战士登台讲述家乡革命故事。三湾改编、黄洋界保卫战……老区传人生动讲述红色故事，带', '2021-07-26 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004745', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (848, '报纸', '井冈山精神跨越时空闪耀光芒', '赖永峰; 刘兴', '经济日报', '经济日报', '井冈山精神;井冈山革命博物馆;习近平总书记;', '中国共产党始终把共产主义远大理想写在旗帜上，将马克思主义作为根本指导思想，并将其与中国具体实际相结合，引领革命向着胜利方向前进。井冈山斗争就是在这一理想信念引领下进行艰苦卓绝奋斗的光辉实践。$$ “井冈山是中国革命的摇篮。井冈山时期留给我们最为宝贵的财富，', '2021-07-24 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005541', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (849, '报纸', '《三湾改编》：信仰生生不息 薪火代代相传', '杨雯', '中国新闻出版广电报', '中国新闻出版广电报', '三湾改编;《三湾改编》;历史题材;', '7月19日，由八一电影制片厂一级导演杨虎执导、演员侯京健主演的重大革命历史题材影片《三湾改编》全国上映。$$ 在历史长河中，“三湾改编”不仅是一次部队的整顿与改编，更是一次从根本上建立党对军队的绝对领导，重建部队军事、政治、组织纪律，创立党内民主和党内政治生活', '2021-07-21 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.002879', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (850, '报纸', '历久弥新的宝贵经验', '姜洁; 孟祥夫; 杨昊', '人民日报', '人民日报', '全面从严治党;党中央;宝贵经验;思想建党;政治建军;走向胜利;马克思主义基本原理;中国共产党;习近平;张子善;毛泽东思想;', '习近平总书记在庆祝中国共产党成立100周年大会上指出，我们要用历史映照现实、远观未来，从中国共产党的百年奋斗中看清楚过去我们为什么能够成功、弄明白未来我们怎样才能继续成功，从而在新的征程上更加坚定、更加自觉地牢记初心使命、开创美好未来。$$ 百年征程，党领导人', '2021-07-11 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007108', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (851, '报纸', '在强军新征程中弘扬伟大建党精神', '陈东恒; 赵卓; 翟婵', '军事科学院军队政治工作研究院;', '光明日报', '绝对领导;人民军队;', '习近平总书记在庆祝中国共产党成立100周年大会上，首次提出并深刻阐述伟大建党精神的深刻内涵、历史意义、时代价值和实践要求，对于激励全军官兵向着实现党在新时代的强军目标迈进，不断把新时代强军事业推向前进，意义重大而深远。我们要深入贯彻落实习近平总书记重要指示要', '2021-07-11 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.006611', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (852, '报纸', '新征程上，必须加快国防和军队现代化', '', '人民日报', '人民日报', '人民军队;世界一流;中华民族;军队现代化;习近平总书记;强军之路;党对军队绝对领导;', '“强国必须强军，军强才能国安。”在庆祝中国共产党成立100周年大会上，习近平总书记指出“人民军队为党和人民建立了不朽功勋，是保卫红色江山、维护民族尊严的坚强柱石，也是维护地区和世界和平的强大力量”，强调“以史为鉴、开创未来，必须加快国防和军队现代化”。$$ 19', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007138', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (853, '报纸', '奋进新征程 书写报国新篇章', '孙亚慧', '人民日报海外版', '人民日报海外版', '习近平总书记;中国共产党成立;庆祝大会;欧美同学会;段燕文;中国特色社会主义;奋斗目标;共产党员;', '连日来，习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话，在留学归国人员群体中引发热烈反响。大家纷纷表示，要在中国共产党的坚强领导下，将自己的爱国情、强国志、报国行与国家发展所需相融，为中华民族伟大复兴贡献力量。$$ 汲取力量 赓续红色血脉$$ 欧美同', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002064', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (854, '报纸', '从人民军队历史功勋感悟党的伟大领导力', '王强; 刘铭', '国防大学习近平新时代中国特色社会主义思想研究中心;', '解放军报', '人民军队;领导力;军队建设思想;历史功勋;', '习主席在庆祝中国共产党成立100周年大会上的重要讲话中指出：“坚持党指挥枪、建设自己的人民军队，是党在血与火的斗争中得出的颠扑不破的真理。”90多年前，南昌城头一声枪响，一支由无产阶级领导的新型人民军队由此诞生。从此，我军高举着党的旗帜，夺取土地革命战争、抗日', '2021-07-08 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004341', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (856, '报纸', '坚定不移听党指挥 勠力奋斗强国强军', '梅常伟', '人民日报', '人民日报', '听党指挥;军队现代化;政治建军;强军之路;党对军队绝对领导;', '“强国必须强军，军强才能国安”“把人民军队建设成为世界一流军队，以更强大的能力、更可靠的手段捍卫国家主权、安全、发展利益”……7月1日，庆祝中国共产党成立100周年大会在北京天安门广场隆重举行，中共中央总书记、国家主席、中央军委主席习近平发表重要讲话。$$ 连日', '2021-07-08 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007014', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (857, '报纸', '江西省永新县三湾乡三湾村：枫树坪的守望与见证', '朱一鸣; 刘自艰', '农民日报;中国农网;', '农民日报', '水冲式;三湾乡;三湾改编;永新县;枫树坪;讲解员;江西省;', '“我毛泽东干革命，图的是天下劳苦大众得解放。愿意跟我走的，此行前去，山高水长，任重道远……”位于三湾村枫树坪饱经沧桑的红枫古樟，见证了一代伟人震撼人心的气魄与胸襟。$$ 1927年9月，秋收起义后，毛泽东率领中国工农革命军第一军第一师向罗霄山脉中段的井冈山转移。', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2021.003071', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (859, '报纸', '奋斗强军 我们都是追梦人', '钱宗阳', '解放军报', '解放军报', '强军目标;红一连;天文点;人民军队;标兵单位;追梦人;', '百年征程，这是一个载入史册的时刻——$$ 2013年3月11日，习主席在十二届全国人大一次会议解放军代表团全体会议上，鲜明提出“建设一支听党指挥、能打胜仗、作风优良的人民军队”的强军目标。$$ 强军路上，这是一份催人奋进的荣光——$$ 2014年底，全军首次评比表彰“全军', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004153', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (862, '报纸', '三湾改编：一支新型人民军队从这里诞生', '朱一鸣; 刘自艰', '农民日报;中国农网;', '农民日报', '三湾改编;人民军队;', '“这几棵树是三湾改编的历史见证物，也可以说是三湾改编的标志，当年毛泽东同志就是在这个位置给部队动员讲话。”三湾村村民刘新宝指着树下的半身铜像讲道。$$ 1927年9月，毛泽东领导的湘赣边界秋收起义遭重挫后，他决定剩余部队向井冈山地区转移。29日上午，部队翻越了大山', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2021.003074', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (865, '报纸', '恰是百年风华 强军征途如虹', '董永在', '习近平强军思想研究中心;', '中国国防报', '人民军队;世界一流;党对军队绝对领导;奋斗目标;', '毛泽东同志指出：“从马克思主义关于国家学说的观点看来，军队是国家政权的主要成分。谁想夺取国家政权，并想保持它，谁就应有强大的军队。”无论是革命战争年代，还是和平建设时期，我们党都始终致力于建设一支强大的人民军队，为实现中华民族从站起来、富起来到强起来提供', '2021-06-23 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2021.001397', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (866, '报纸', '让井冈山精神放射新的时代光芒', '王少玄', '江西省吉安市委;', '中国组织人事报', '井冈山精神;党史学习;革命老区;习近平总书记;', '从中国共产党的发展历程中汲取精神营养，让初心永不蒙尘褪色，让信仰永远保质保鲜，始终做到信仰如山$$ 前进道路从无坦途，只有思想破冰，才会有行动突围。抓发展要像干革命一样，抓住有利时机，吹响前进号角$$ 历史是最好的教科书，党史是最好的营养剂。习近平总书记强调', '2021-06-07 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.001920', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (867, '报纸', '藏在红布里的誓词', '', '中国纪检监察报', '中国纪检监察报', '入党誓词;永新县;', '“牺牲个人，言首纟必蜜（严守秘密），阶级斗争，努力革命，伏（服）从党其（纪），永不叛党。”这份有错别字的入党誓词，出自一位普通农民贺页朵之手。如今再看这份泛黄的入党誓词，我们看到的是一张勇敢无畏的面孔、一颗对党的赤诚之心、一份一以贯之的信仰。$$ 90年前的', '2021-05-04 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.002096', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (868, '报纸', '开辟革命新道路', '高中华', '中央党校(国家行政学院)习近平新时代中国特色社会主义思想研究中心;中共党史教研部;', '解放军报', '毛泽东;新道路;八七会议;', '1927年大革命失败后，神州大地陷入一片白色恐怖。新生的中国共产党遭受成立后从未遇到过的严峻考验，中国革命处于命悬一线的紧要关头。$$ 死亡和屠刀吓不倒真正的信仰者，腥风血雨只能让共产党人更加笃定信念、冲破暗夜、勇毅向前。$$ 面对严酷斗争和血的教训，我们党认识', '2021-04-13 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.002293', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (869, '报纸', '争当光荣传统和优良作风的忠实传人', '李晓辉', '军事科学院习近平强军思想研究中心;', '中国国防报', '光荣传统;优良作风;党对军队绝对领导;人民军队;优良传统;', '党领导人民军队近百年的不凡岁月，孕育形成了超越时空、震古烁今的光荣传统和优良作风，成为我军由小到大、由弱到强的精神血脉和强大优势。习主席强调：“不论过去、现在还是将来，党的光荣传统和优良作风都是激励我们不畏艰难、勇往直前的宝贵精神财富。”这一重要论述深刻', '2021-04-07 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2021.000750', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (870, '报纸', '坚持党对人民军队的绝对领导', '', '解放军报', '解放军报', '绝对领导;人民军队;军委主席;', '党对军队绝对领导是中国特色社会主义的本质特征，是党和国家的重要政治优势，是人民军队的建军之本、强军之魂。党对军队绝对领导的根本原则和制度，发端于南昌起义，奠基于三湾改编，定型于古田会议，丰富发展于党领导人民军队革命、建设和改革的伟大实践。军队党的建设的首', '2020-09-12 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2020.004930', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (871, '报纸', '抗疫战场书写绝对忠诚', '高宁', '国防大学习近平新时代中国特色社会主义思想研究中心;', '解放军报', '红色基因;人民军队;听党指挥;', '强军文化蕴含着我军在长期战斗、训练和生活中凝练形成的精神血脉，沉淀着人民军队最深层的精神追求。其中，绝对忠诚是强军文化极为鲜明的精神品格，是人民军队区别于其他军队的独特精神标识。在抗击新冠肺炎疫情的特殊战场上，新时代革命军人再次以实际行动生动阐释了忠诚品', '2020-05-14 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2020.002461', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (872, '报纸', '确保人民军队绝对忠诚于党和人民', '', '人民日报', '人民日报', '人民军队;绝对领导;中国特色社会主义;党中央;国防和军队建设;忠诚于党;', '党对军队绝对领导的根本原则和制度，是人民军队完全区别于一切旧军队的政治特质和根本优势$$ 人民军队政治生态重塑、组织形态重塑、力量体系重塑、作风形象重塑，有力保障国家主权、安全、发展利益$$ 强大的人民军队，是国力强盛的保障。15个徒步方队步伐铿锵、锐不可当，3', '2019-11-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NbT6iICD9OEm8shhYvSCs0lHPkVK0TDFYI8uFIot_kcQDOpeUlw0U5fuHkixuy_l7PL-4eH-HhBRFN09eDa-HOey2lhebDdvj6ZSRMZ7U2g5NXMz30mFcl9DtVpQ8j7bFnDCF6mWuE8g==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (873, '报纸', '从定型到重塑：政治建军的时代篇章', '张明仓', '习近平强军思想研究中心;', '解放军报', '政治建军;思想建党;政治本色;人民军队;古田会议精神;', '90年前的古田会议和5年前的古田全军政治工作会议，创造性地回答了事关我军兴衰存亡的一系列重大问题，在紧要历史关头引领我军实现浴火重生、凤凰涅槃，在不同时期矗立起我军建设发展的不朽丰碑。$$ 迈入新征程，奋进新时代，需要从历史和传统中汲取前行的力量。站在新的历史', '2019-11-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P00HEOLS08ThVqiQDXTgApDUaT6U83O6-6Dz1oM3d_5mJ4IeznbTMZWSBk8S1RldRxzIE_tq2C_MzxFZedi0Yhx44S24s6ZbwyS1B8Fy04PTd3PSmybiFgDkbS9ovNuGapaVFg0apGnA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (875, '报纸', '井冈山随想', '柯春晖', '中国教育台;中央党校(国家行政学院)\"习近平新时代中国特色社会主义思想理论研修班\";', '学习时报', '井冈山;红军医院;秋收起义;刘仁堪;共产党人;', '脚又一次踩上井冈山坚实的土地。$$ 这是我第三次上井冈山。作为中央党校（国家行政学院）“习近平新时代中国特色社会主义思想理论研修班”（第二期）的学员，我和我的同学们根据学校的安排，在中国井冈山干部学院接受了为期一周的体验式教学。$$ 春夏之际的井冈山，阴雨', '2019-06-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MzpftSVb2hST6T3idjdyfi5rVe-WZBiY6OFiSc-WpVfpdgDG2c4z8a_S3bTkHxOk8Du1x1ddMch8NtjazuKQ1x4kvPUcz_h2SdQHkchdTjK7SfgTgchF2hETQ_lztDUqtr0Qwo9MXNXw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (876, '报纸', '以高度的政治责任感和历史使命感投身改革', '黄少楼', '广西壮族自治区北海市公安边防支队;', '人民公安报', '公安边防部队;习主席;历史使命感;政治责任感;', '习近平总书记强调指出，改革开放是决定当代中国命运的关键一招。当前，公安现役部队改革进入实质性的关键时期。改革既考验忠诚，也考量素质，更拷问能力。公安边防部队必须以高度的政治责任感和历史使命感，因势而谋、乘势而上，增强投身改革的自信、自强、自觉、自律，坚定', '2018-07-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Npp6BtIvOyw70siF8-BehqLmpwVlJ70FfDO0_6J_pWfZw7eVoEU_RdG3TMCp8cPTPrKeGscOOTfvFZ-gufNbp9hbF0CqgQ9wZ_b1AkLWDk1pMipNYmo4X6JnGL9_z1158-R8BjnoHCgQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (877, '报纸', '忠诚的底色是红色', '', '解放军报', '解放军报', '红色基因;红一连;急难险重任务;', '是什么力量，让一个连队走过91年岁月依然充满活力？是什么力量，让一支队伍历经91年风雨始终坚强过硬？一茬茬“红一连”官兵用行动作答：是红色基因这一本色的力量。$$ 1927年9月，“三湾改编”开创了我军“支部建在连上”的光辉历史，也成就了“红一连”的不朽英名。血脉', '2018-07-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MqxL9lbGjVXk0bcaKJeJv6tjIEl2x7R4i6OOt_8gTdrm5RJh48myg5q69u-V38MXzMSMUjypWwESMY9pgOYmuHba0pYbzsKoaR973OKOgY44042mFrFBsnAgnqfgPRUZxy4Phy-GGK2g==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (881, '报纸', '八角楼前有片“灯下红”', '何志平; 张海华; 周勇敢', '解放军报', '解放军报', '八角楼;井冈山革命烈士陵园;三湾村;三湾改编;黄洋界保卫战;红色精神;', '【写在前面】井冈山是革命的山、战斗的山，也是英雄的山、光荣的山。$$ 习主席在井冈山调研考察时充满深情地说，井冈山道路是马克思主义中国化的经典之作，从这里革命才走向成功。行程万里，不忘初心。井冈山革命理想教育要坚持下去。$$ 枫树坪下听传统，八角楼前觅灯光', '2017-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M-d6faVyWKHc6Y9JesS0nGRPtZhLC6i_kszrlUPEWRKTHdf12GvI75lVgzhqiJE63ZAdh96zdtAkMTVK3eALnFPaS1gAdjfFkXdy2hdgKz_heVvrxGD_I0sQgVtIQDrJ_9IrWyhvSkUw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (882, '报纸', '传统的火种 不灭的火焰', '刘建伟', '解放军报', '解放军报', '红色基因;优良传统;', '如果要问，在我军建设发展史上，是什么真正融入了官兵血脉？那就是代代传承的红色基因。$$ 在某部“红八连”，无论翻开哪个战士笔记本的扉页，都会看到这样一行字：“党的声音就是母亲的话语。”$$ 这句话来自于长征路上最艰难的时刻。当时，连队第三任指导员韩光荣把他', '2017-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4On9BlQiHyGV9gSXEOKMlARBKGzJdU7_-e4TJZqqIvsL3ocgT_YU2EqHI1fzrnunhfWFubTQtOwvGSsHX2Jm8UAkXoXlWixq_8qjt9dmMKKkZ0qTRX__S-y9zCk1SMQuVFYjJdS-BuxRg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (884, '报纸', '开新图强，担起强军重任', '', '解放军报', '解放军报', '重任;官兵;', '革弊是为了鼎新，破障是为了前行。全面彻底肃清郭伯雄、徐才厚案件流毒影响，根本目的是以新的精神风貌开新图强，引导官兵把意志和力量凝聚到实现强军目标、建设世界一流军队上来。$$ 回顾历史，每逢关键时期和重要关口，我党我军都要正本清源、固本培元，以适应新的斗争、', '2016-07-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OnYsEwlp2gVunldo8rcqBvaRQW6lb3j-zUyv50OUurZsuCVryZwP4gGxPBgYqWKotTrUShmjVluegIDK0fbl6PXXImHSlaV1jPjzglscthK59ezuLJa9utp1JVL4l_pS4Gemg4YFiD9g==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (885, '报纸', '燎原星火在这里点燃', '孟维伟; 曹蕾; 罗珺', '中国纪检监察报', '中国纪检监察报', '井冈山革命博物馆;湘赣边界;井冈山革命根据地;工农武装割据;', '6月28日，江西井冈山茅坪八角楼。青油灯静静地放在桌上。$$ “八角楼的灯光，比天上的北斗星还要明亮。”讲解员黄俊峰正在向游客们讲述那段艰难而光辉的岁月，“正是在这盏如豆的小小青油灯下，毛泽东挥笔写下《中国的红色政权为什么能够存在》《井冈山的斗争》两篇光辉著', '2016-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NzrSON3MGixZRcc9Ank_nKxDt82tPoPZULmJXk8HZpMa8S6ghTg_BWdzx-JJ3p0hX14usSajxuMas2ZjOrE1vTPuCK45h1M-AD0LaquFY6xhNW9d7enKE3EoiadqvFP8S0fTKaJHGAFA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (887, '报纸', '怎么改都不能改丢“基因”', '', '解放军报', '解放军报', '国防和军队改革;听党指挥;人民军队;', '改革开放之初，“总设计师”邓小平同志曾强调，坚持共产党领导“这个原则是不能动摇的”，“老祖宗不能丢啊”。深化国防和军队改革，改掉的是陈规和弊端，需要牢牢守住的是党的领导这个“根”。不论怎么改，“基因”不能丢。$$ 事实上，行进在改革之路上的人民军队，已经用', '2016-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O85LeBn2S2aRkswXtbdbTJNOLUjOqMGrGkc-SFilmuoCwaI_1Z9SJ8sntXsLmV52gWTcl4XQnY4hLEC-vZl-PW7YfHJeaoziamaRUgbBDnz7r_NhJkRYL9wjn7g3CamWmL9RlgYWwntA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (889, '报纸', '交出时代大考的合格答卷', '', '解放军报', '解放军报', '国防和军队改革;中央军委;军队组织形态;世界新军事革命;改革强军;革命性变革;习主席;军事变革;强军之路;人民军队;', '“深化国防和军队改革正面临一个难得的机会窗口，一定要把握好。这是我们回避不了的一场大考，军队一定要向党和人民、向历史交出一份合格答卷。”$$  ——习近平$$  （一）$$  “物不因不生，不革不成”。$$  一个国家、一个民族、一支军队的发展强', '2015-11-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OMJRYlJ-ImzJQ7BV1iC9IOstMoMebYlX5JnPJ0wrzGORUOkRdqpg0QdKLYex4WWbxqMG44_QYq7WFbrvhwcW4PNld_nksbhmzkiNSCRIyDtYZrpOr_z5jwWbBh42P1wXHRUSXACMB7uQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (890, '报纸', '坚持扭住党的组织抓基层', '', '解放军报', '解放军报', '党的组织;基层党组织;支部建在连上;', '基层党组织是党在基层的“神经末梢”，担负着掌握和建设部队的重要责任。基层组织坚强有力，部队建设才能根深叶茂。贯彻落实新修订的《军队基层建设纲要》，推动基层建设全面进步、全面过硬，关键要把基层党组织建坚强。$$ “支部建在连上”是我军的优良传统，也是党领导', '2015-04-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N16hxeSPbgf6F8a43KPv62ECPXyy9SME6nXfvXN-bdilL8qizIPnQ6C03mVY3aVE6v2CCN3YCj-LvXk-PHzRHDliSWS2dIT9jna2-aPAj3uyBQ8nlUe7mGEUS6JR1dytIDU3bix5SVOQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (891, '报纸', '抡起革弊鼎新的开山斧', '辛士红', '解放军报', '解放军报', '徐才厚;', '如果讳疾忌医，遮遮掩掩，听任污泥浊水泛滥，放纵“老虎”“苍蝇”横行，“军队就不成为军队，更谈不上能打仗、打胜仗了，甚至还会有变质变色的危险！”$$ 清障除碍，需要一把开山利斧；革弊鼎新，需要一种“蛮拼的”精神。$$ 在全军团以上党委机关开展的“三严三实”', '2015-01-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MwE2g9yubnRuw9W5cWYRVvIBjNQHdK4rFUSf0e7c7M97vBArvTzQ6XnsmROeltSymOI-ANodB2kp5U53-Ks9pEP7YgDvi4fOZzMr67Dnd1Qjf3WdONr_sPWVPlIXfLeM37g4ZTL5TapQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (892, '报纸', '敢于同错误思想作斗争', '', '解放军报', '解放军报', '错误思想;古田会议;战斗性;', '开展积极健康的思想斗争，是除尘去垢、排毒祛邪的有力武器。古田会议及其决议，就是同各种错误思想作斗争的产物。$$ 古田会议召开前，只有两岁的红军，虽然经过“三湾改编”，但依旧没有完全消除旧式军队的影响，还不是一支完全成型的无产阶级人民军队，还存在着单纯军事', '2014-10-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MXdjXYuhqf9_ostCAjXpbEcXQLGIDbBS9hTDq5KF3l-pBDBYWaQxZ-VL4AfLz4FEFH-AkNECwXJgDYPfEms4ezJ6iMGkM6NnBbcnkV6r2beEhKap0PH03JbXf3zdFRR0fShQBwOa_T3A==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (893, '报纸', '官兵一致：开启胜利之门的钥匙', '胡君华; 刘建伟; 严德勇; 刘一伟', '解放军报', '解放军报', '国民党军队;古田会议;《古田会议决议》;张赤男;官兵关系;', '红军诞生之初，还打着农民和旧军队的鲜明印记。当年，有着不少从旧军阀里过来的“五皮”干部：脚穿皮鞋，手戴皮套，腰系皮带，肩挎皮包，手握皮鞭。$$ 1927年9月，毛泽东针对个别“五皮”干部用皮鞭打红军战士的现象，在“三湾改编”中提出：支部建在连上，设立士兵委员会', '2014-10-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Mh4Yg_hNUwJ_GaS5iS0HOKdC4HTOw2g6fJsfm9iBqz7WaK0D0GN02G1Iwv-CBrJdkWRQIjOXBZm3Yz23Q3XOirXRJkxe5gJuRXHiNirzLcsLILqDbaV617n5dmr_DRdDkwU4ZhAS2ReQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (895, '报纸', '人民军队建设史上的重要里程碑', '', '总政治部办公厅编研局;', '解放军报', '红四军;毛泽东;军队建设史;“九月来信”;古田会议精神;', '古田会议，即中国共产党红军第四军第九次代表大会，于1929年12月28日至29日在福建上杭古田镇溪背村曙光小学（原廖氏宗祠）召开。这次会议虽然只是红四军一次党内会议，但由于它系统地、创造性地回答和解决了当时党和军队建设面临的一系列根本性方向性全局性问题，因而不仅对', '2014-10-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MNoY54PM75aMYEPdYilBbE1nCvg7stxte9Ae3qgOKov7qFBrzKzbzdY8WQbogNn0KZ-733BrbXML1X5ODKz79rGCxV-WRCw2GNVyURsPmAYxVnxwLOYeUugcB0ANeqFP1JquxB71LBnw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (896, '报纸', '把听党指挥作为根本要求和首要任务', '马家利', '江西省军区;', '人民日报', '听党指挥;首要任务;', '习近平同志在接见全军党建工作会议代表时强调，“军队党的建设的首要任务是确保党对军队的绝对领导，这也是对军队党的建设的根本要求”。党对军队的绝对领导，是我军的军魂和命根子。今天加强军队党的建设，必须永远牢记这条经过血雨腥风洗礼、残酷斗争检验的历史经验，把听', '2014-01-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NrVQKRWABvc1De2rCxV2MB8IZbLsRxss_8ScVAtdngw3D7TH80wvbqmg3wXONAabOtXZjFaw77ZdUyWZRyM8jDxQJy2Rarl0ZbyVdvm5K79eJT1psI11IBhSnC31Zfi54p5pTv3EDMzw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (897, '报纸', '我军优良传统鲜明而生动的体现', '周明贵', '南京军区联勤部;', '解放军报', '优良传统;人民军队;听党指挥;', '习主席提出的“听党指挥、能打胜仗、作风优良”的强军目标，鲜明而生动地体现了我军优良传统，具有传承性，体现时代性，富有创新性。$$ 听党指挥是强军之魂，也是人民军队优良传统之精髓。我军是党一手缔造的，从诞生之日起就和党紧紧联系在一起。我军发展壮大的历史，就', '2013-04-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M3L0aLfbXd23PyQt2Q_mS-xPFiGEmnb4F8u2KDOjddm6d9Dm0hO3BrIeMZESpv_YaW5hggNpLuJmjIUo-HE3E8uGAbHF5IojhDQiFC26yFrKa_mYc1w4xTRQKOK9pk3VZ5a827Uycjgg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (898, '报纸', '激情澎湃的军魂颂歌', '严德勇; 李华敏 ; 田利阳', '解放军报', '解放军报', '支部建在连上;余洒度;历史题材;武装割据;党指挥枪;戏剧冲突;秋收起义;思想建党;三道桥;四个伟大;三湾改编;', '金秋十月，秋高气爽。广州和长沙两地，同时被一部名叫《支部建在连上》的大型革命历史题材话剧点燃“红色激情”。$$ 这部向党的十八大献礼的剧目，取材于秋收起义部队攻打浏阳失败后，从1927年9月文家市转兵，到1928年4月井冈山朱毛会师那一段艰苦卓绝的斗争历史。话剧以', '2012-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NxnP0gdi9N1wezWv6kWs6X15adBXRayzljGfA3GQ_L8rldjKRBc2NHvyQQxLH20uvRVveHjUzLp13nsPvw-pC_viEi_HFgh1MDG3ksQrFipMsZly8sbNTnzSTiCzV0Hl4c7yvRUnRfkQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (899, '报纸', '打牢执政为民的坚实根基', '', '人民日报', '人民日报', '执政为民;党的宗旨;', '为谁谋利、替谁掌权，这是任何一个执政党都必须回答的问题。作为以“全心全意为人民服务”为根本宗旨的马克思主义政党，90年来的发展历程告诉我们，来自人民、植根人民、服务人民，是中国共产党始终立于不败之地的根本。也正因此，如何不断增强为人民谋利益的能力，更好地服', '2012-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MN9SZzJaB1cx_xWasquRI7wT7czEMrF2qu6KshK_vpzMyKYl4hb-iXFtmIT4f0Ml-SXWjDOLNcB9E-oDDHUGP3u06xzQDbCMvadeTiL6FDTslRdcALZzDhwtCEbX0Wzbsc6KKlh2nw2Q==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (902, '报纸', '党指挥枪：军旗跟着党旗走', '甄澄', '光明日报', '光明日报', '党指挥枪;人民军队;党对军队的绝对领导;', '人民军队，永远要以党的旗帜为旗帜、以党的任务为任务。“党指挥枪”，永远是人民军队的建军之魂、立军之本。坚持党对军队绝对领导，就能保证枪杆子始终掌握在忠于党的可靠的人手里，保证军队始终置于党的绝对领导之下，军权牢牢掌握在党和人民手中。$$ “党指挥枪”', '2011-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Nxf0-uOaTVGjmQfDYDGFbf2piYsZPnCUv9Tn96UKWaFxKOP0TXw2gVdMc4f5mZf-ZYXmZLD4-7u5Dyaju8690xzwgqZS_JfYLcK77Cn5YDSdhTxFfi-YyTHwEAanJO2byhDmTLGZ2S9Q==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (903, '报纸', '“寻根之旅”震撼心灵', '周奔 ; 李华敏', '解放军报', '解放军报', '党史军史教育;毛主席;', '本报讯 记者周奔、特约记者李华敏报道：誓言声声表忠诚，红星闪闪心向党。6月10日，在毛主席组织“水口连队建党”旧址湖南炎陵水口镇叶家祠前，广州军区百余名将校军官在军区司令员徐粉林、政委张阳的带领下，庄严地举起右手，重温入党誓词。$$ “开展这次活动，是我们发', '2011-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Maan7FAMZmv9dUPFNbsX9EfEO-vOsPs2hBdrJZabLryvmehI_jb1NfOSnK6ieVkLDuE5sX4bvM-gNTFUpb5rKO-uTV0JEMrSa__G65bnvmenWycZBMBdJGy0rgVdrnMKz3qwBzzhElqQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (907, '报纸', '军魂在这里铸就', '王振江 ; 杨清刚 ; 陈小军', '解放军报', '解放军报', '红四军;“九月来信”;古田会议;《古田会议决议》;', '究竟是一座怎样的院落，能在中国革命史上留下绵延不绝的历史回响？究竟是一份怎样的决议，能凝聚成长盛不衰的精神力量？$$ 今天，我们怀着崇敬之情前往古田，踏访我军建军史上形成军魂的源头。$$ 陈毅认识到问题的严重性$$ 这座始建于1848年黛瓦白墙的古朴建筑，称', '2011-05-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O3TlYRayC_YgVkCfXBwBHyyvgLB-h3Ft0DSBrzW8ere65IuBQn7uHDsAd8YHpg_4q1ixhCH2822Y6opRc7WrdX_t_SbGnNm2S4C2xT3pLTZLXSXbxlJ8aSLhQpPG94L9dqU-wbWEAs2Q==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (908, '报纸', '惊天动地铸雄师', '胡锦武', '人民日报', '人民日报', '秋收起义;前敌委员会;中国共产党领导;南昌城;南昌起义;三湾改编;武装起义;国民党反动派;人民军队;武装斗争;大革命失败;共产党人;', '新华社南昌５月１２日电 （记者胡锦武）８４年前的８月１日凌晨，中国共产党人用南昌城中的稠密枪声，向世界发出了独立领导中国革命的宣言。$$ １９２７年８月１日发生的一切，已成为人民军队历史上的永恒。$$ 由陈毅元帅手书馆名的八一起义纪念馆，坐落在南', '2011-05-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PM2JDkLT30LF21X2XvNLvhdT0VXYPC5rPABoqoknbgm2bkh-cPx4vnbqD1n-0MZ7EHRrXEGmk4KY1jL2209kboXBROe5WwipI94Jw5R2mdZfKqLiuDu1L9BiMtS-QitnMwTyL-WqzCnQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (909, '报纸', '踏访井冈山——中国革命的摇篮', '张晓祺 ; 代烽 ; 徐政武', '解放军报', '解放军报', '井冈山斗争;工农革命军;毛泽东;井冈山革命博物馆;中国革命;', '也许，世界上还没有哪座山，像它这样与一个民族、一个国家、一个政党、一支军队有着如此密切的联系。$$ 井冈山，中国革命的摇篮。5月12日，冒着霏霏细雨，“红色足迹万里行”前方报道组来到井冈山，追寻留在这里的红色印记。$$ 重温一段历史——$$ 中国要有自己的马', '2011-05-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M1jakcLz2k0uV3g8mPTauIlZIWLh5IyEhuvnf1q4T1Fwrws_ed5jjGmjl6JF5YA3evi2UiloZJYhtex8BKXF4j7xbDlfpyrodm19IAIeS4nba3HTkiBVo-sFoCV-757OIfwe9n1g8LyA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (910, '报纸', '运用“时尚元素”传承红色基因', '王卫东; 傅开强', '解放军报', '解放军报', '红色基因;三湾村;时尚元素;', '“小竹板，响连天，咱来说说‘红一连’；秋收起义这一天，从此有了咱一连；部队来到三湾村，日出朝霞红烂漫；毛委员来到‘红一连’，亲自来把支部建……”$$ 今天上午，伴着清脆的快板声，一堂别开生面的党史课正在济南军区某团“红一连”学习室进行。$$ 表演快板的不', '2011-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MBBD2WjALd0E_PbGEY-vUWAUJ13n6LlBVbK8NYSDxVhrlqg081jbhjDMcgTpLWVRDkvqMjiGViiVrHNaS6id0S-chikNTYVe2W07QCPnkmWPq1PUMr6agosM2UOacKohVXWzx47k9Idg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (911, '报纸', '今天,我们怎么学党史', '张晓祺 ; 马杰; 尚春雅', '解放军报', '解放军报', '批评和自我批评;党史学习;共产党员;', '几回回梦里回延安，双手搂定宝塔山……4月上旬，总装某基地组织团以上领导干部，走进革命圣地延安，访旧址、寻故迹，学传统、话使命。$$ “这样的现地教学活动，只是我们多形式多角度学深学好党史的一个缩影。”基地政委赵传祥介绍，“中国共产党的历史，堪称思想的宝库，', '2011-04-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NH70_KgHSWACL-c4w0AEvHRxKrEOQmG9BqiHVKabEDFlcKVivDjCD89MFlaEdDR8HB4U546Tfsbq5ifwPOchMJvUOQm6StXws6aGqsfbxSINdNVI8GGYoA7KynhmZrnewuRl-D_v1QPw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (912, '报纸', '强化军魂意识 坚定理想信念', '', '解放军报', '解放军报', '地方大学生干部;当代革命军人;时事直通车;理想信念;省军区;党对军队的绝对领导;集团军;时事政策教育;红色博客;第二炮兵;水警区;三湾改编;', '在纪念建党90周年之际，如何进一步在当代革命军人中强化军魂意识，引导官兵坚定理想信念，始终信党爱党跟党走，是摆在我们面前的一个重要课题。$$ 今天，我们向读者介绍6个单位深化主题教育、强化军魂意识的经验做法。他们的经验有两个共同点，其一是“回头看”，也就是扭', '2011-04-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OBUIOLhkquNoXuAsy4uJFmG6o1aySfmMvM8H0koo248xUJUHnhlIT-3pstU3vo1hBWEq3kddWkbUVQSyyf5ZeD_205xpxrQQ7fvtFsofchr-UW09-DusadaZIRsmEzTydnMKitJPmsWA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (913, '报纸', '铁心跟党走 誓言变行动', '周奔 ; 邵敏 ; 罗正然', '解放军报', '解放军报', '周素园;光荣传统;当代革命军人核心价值观;听党指挥;党的创新理论;事物本质;', '编者按 忠诚于党是人民军队最根本的政治要求，是当代革命军人核心价值观的灵魂。南京军区某机步师在深化主题教育活动中，充分利用纪念建党90周年这一有利契机，充分发挥党史军史和部队光荣传统教育资源作用，引导官兵强化军魂意识，收到良好效果。他们的成功实践启示我们，只', '2011-03-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MpKk59bVv30F5zuKcPapApnEi7yJBVndDzrM3hGJdYrENd051txY6HLSdFq6BVciOsdnZM7b4DEByEYkPkPaRtlQFQQieZUs-FR1K_P1Ov5hbBXXnudzvUYiuUKL9eZNT5p2mh8NGyJw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (915, '报纸', '今日“铁军”怎样铸魂', '欧灿 ; 梁申虎; 李光辉', '解放军报', '解放军报', '集团军;叶挺独立团;团政委;红一连;红色基因;', '剑有剑气，军有军魂。坚持党对军队的绝对领导，是我军永远不变的军魂。新形势下，如何应对新情况新挑战，打牢部队高举旗帜、听党指挥、履行使命的思想政治基础，进一步强化军魂意识，筑牢思想防线？济南军区某集团军作出了有益的探索。 $$ 1 红菜盘的故事年代久远，如何找', '2011-03-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NXIy4KepylzD4gem-DHnpMaetn32tYLJvW3ShFzcQCxStN1fnb0Kelf9b7POVSbTlTV_Q3YTbstAABq2npnVCAsLAyHtapMrsuWky7BHVwQ6uPTswIAm3dt4CrxVB_Uw16Y3Ta5xKMxQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (916, '报纸', '永新三湾红枫树“情牵”嘉兴南湖红船', '刘志宏 ; 贺志英 ; 贺振飞', '中国旅游报', '中国旅游报', '南湖红船;', '本报讯 (刘志宏 贺志英 贺振飞) 近日，江西省永新县石桥镇与浙江省嘉兴市嘉善县罗星街道达成在永新县开发区投资兴建永新罗星工业园投资意向协议。这是今年10月，嘉兴市委党校第22期中青班在井冈山学习培训期间，与同在此学习的石桥镇领导干部在培训之余，互商发展大计，携手', '2010-11-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NjKbnkxBAcapfFdDtegj8raZ6wAIZ38osHJJx5d3LZuH3gd5oXXHRZPV262CmWRV_I_00-ZIPbWnxYJ9XT3XEI7z-F7Ws1QpLCU5-qgpMYuLJUHTH3PSm9IvLc0tzqixAjHn24P1xt4A==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (918, '报纸', '“军史宝库”的开掘者', '王雁翔; 李华敏 ; 张科进', '解放军报', '解放军报', '广州军区;编研人员;军史资料;三支两军;', '人物小传：彭新云，1949年11月出生，1966年8月入伍，1974年毕业于北京大学历史系，1986年开始从事军史编研工作，退休后继续在军史编研岗位上耕耘，主编、参编和组织编写中国人民解放军历史资料丛书《土地革命战争时期各地武装起义》、《解放战争战略追击》、《剿匪斗争》分册', '2010-07-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Mrusagd2TQffruyw2cejCOXdNxb2txvdf55JL2pFjrwf0FQn0SPU3a5lfRmvH3Lt2WDVYItQaEQizj5eY9jY6BfUDdtQLxR0WUqjbWbrQ47esA8-_Em1-tQiD1fzpaPMz7B9G73zZjLw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (919, '报纸', '正确把握军队思想政治建设的时代课题', '', '解放军报', '解放军报', '军队思想政治建设;“三个确保”;新世纪新阶段;时代课题;古田会议精神;正确把握;', '历史总是在回答时代课题中前进的。$$ 80年前的1929年12月，在闽西群山环抱的一个小村庄，诞生了我军历史上第一个具有划时代意义的纲领性文献——《中国共产党红军第四军第九次代表大会决议案》。从此，古田成为中国革命的圣地，古田会议成为人民军队建设史上的丰碑。$$', '2009-12-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P6g1x27geglcfwsOX2gq68lbM3sEDoRCdb16r8wP_9iEzpskN8ZXMLhQyLX6Sp5OunTBWB6uppBQVfshZqNOS4iEhsQdVVQBPNLe-O0zbwyolP-sHnhhv47d2Smrti_jVVIbEOrdt5pQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (921, '报纸', '不寻常的红色寻根之旅', '梁申虎 ; 李光辉 ; 傅开强', '解放军报', '解放军报', '大瑶山;枫树坪;黄土铺;支部建在连上;历史担当;', '初秋时节，济南军区某摩托化步兵师奉命挥师南下，挺进西南某演兵场。$$ 这是一支有着光荣传统的英雄部队：师机关和部分部队曾参加了秋收起义、创建井冈山革命根据地、五次反围剿、二万五千里长征，解放战争时期打出了“猛虎师”的威名。$$ 此次远程机动演练，该师官兵', '2009-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Mu2B4SXMe0B8AmG5KuCbWQ9FMXwaTI75FDZ2RphTYtNjNQOiBRGLBlu_iPi-_XXZsa4-L9chLkZrrEh1iQEAXr5tzNhrsWe7hidmkobdTsBjFTG8sMlQPVt3xBB6I9shuugH8EJB1usw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (923, '报纸', '“三贴近与井冈山精神一脉相承”', '周宁; 璩静', '新华每日电讯', '新华每日电讯', '井冈山精神;井冈山斗争;一脉相承;《十送红军》;三贴近;', '如黛“青山”围就一方宽大的舞台。80多年前的烽烟已然消散，80多年后的大地生机盎然。$$ 曲曲荡气回肠的红色旋律、段段历久弥新的红色记忆，展现着幅幅井冈山斗争波澜壮阔的历史画卷。$$ 22日晚，参加“中央新闻单位名编辑名记者江西老区行”活动的100名采编骨干在', '2009-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PaOUDwLuILs_QVQUMvdw2Lh-rFGHq1pd5XEu2H-M2iGMt1woIyffgurihKlwAHsj6q0p73HeGlUa540gASLJ6AOPGFaWaTwlCRWuXjNvtSpXaBaTMbc8irywcxWUEAm4VklQwfjIxFfg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (924, '报纸', '“红色管理”学习坚守信念', '高初建', '中华工商时报', '中华工商时报', '民营企业家;井冈山;建设者;', '由华商学院主办的“首届中国民营企业家学习运用毛泽东管理哲学特训班”日前在革命老区井冈山举行。来自全国各地的６０余位民营企业家参加了这次特训，国家行政干部管理学院、中国人民解放军军事科学院、国防大学、总参等权威院校和机构的学者专家，为民营企业家们进行了专题', '2009-07-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O1CGW4FLdwdTq8BOQNPe9aJ8YfOBAn0oTJDQUh6iCmFo2_90p52R_j3YkS3QYjEhAqlmYN8G828Nj2E7OuCvNkiwd0dyIm0aIA_-FAusrDzm334wFJ3VCczLZ1aSTYb9Mf99u5kz5k6g==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (925, '报纸', '“三湾传人”的红色基因密码', '赛宗宝; 黄超 ; 魏国 ; 梁申虎', '解放军报', '解放军报', '党支部;红一连;新装备训练;基因密码;', '著名作家陈忠实在济南军区某团“红一连”体验生活时，有过这样一段评语：在光荣传统与现代文明的交融激荡中，“三湾改编”以来形成的“军魂文化”，已化作一种兵之味、士之气、连之风、军之魂。 $$ 仲夏，记者来到“红一连”，探寻赋予“红一连”党支部强劲传承力的神', '2009-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ndt6v765Eu4WuGcAqE7-dYiEs_f-Z-jUYiLfzV__4DKUCUj09e_vyqazIbhRHQxGFz_wRmDiaa4MadialBuPhOzuHta8OSl-tCC9Mhzt_lDxiLl_y-DP5YjfdXzcff5q5_-BlGPldTgQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (926, '报纸', '红色堡垒 绿色方阵', '王会甫; 戴丹华; 侯静', '科技日报', '科技日报', '红一连;党支部;科学发展观理论;支部建在连上;', '战争年代，“红一连”先后参加300余次著名战役、战斗，屡建奇功，被授予“英勇连”“百战百胜连”等荣誉称号。和平年代，“红一连”出色完成了1998年长江抗洪、国庆50周年大阅兵等重大任务。1991年以来，先后5次被总政表彰为“先进基层党组织”，被中央组织部表彰为“全国先', '2009-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MneLNV519-_QmVSh7uGAbRCr39m_rMVJm7r1lzJc0w-8Oop_0L7k43YfMBIpFZ6d5eJTNKydDQEi0PV1O-SWORbQtNGsVtXcgHoJK_EFVLt_WY4mlpub64rJZVvAM6qy0bZS024GNjKA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (927, '报纸', '屡建奇功的“战斗堡垒”', '李争平', '经济日报', '经济日报', '战斗堡垒;复杂电磁环境;红一连;党支部书记;', '这是一支从秋收起义的血火中走来的英雄连队。在著名的“三湾改编”中，它成立了我军第一个连队党支部。从此，“支部建在连上”，成为人民军队攻坚克难、无往不胜的根本保证。82年风雨征程，在党支部的坚强领导下，“红一连”屡建奇功，被授予“英勇连”、“百战百胜连”等荣', '2009-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Mil1HSv16FAcPP_BsD4JII0xODrKGV5e2eFOxIjtcog544ZqKOMjsacdXPpStMD2bTTLK_onkUCRCVPNOpXWmHJxN2unXlU0l0YFC93b_HjqsM8IrA7Jw41dGMHJiClvcfGTAjlp1yRQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (928, '报纸', '神奇的“永动机”', '刘声东; 孟斌; 李光辉', '解放军报', '解放军报', '红一连;支部建在连上;党员汇报制度;党支部;基层党组织;永动机;', '这是一面“领跑者”的旗帜。$$ 它从“三湾改编”走来，1927年9月29日，毛泽东同志亲自到这个连队发展了6名党员，并成立了连队党支部，“红一连”由此成为实行“支部建在连上”的第一个连队。82年风雨兼程，“红一连”党支部在人民军队阔步前进的征途上，始终保持着开路', '2009-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ode-laz0z2Pbd5fsui0VlcNQgoJhWQOoxv6YNKHIhQ_2x0NpED8yrBALfp4lwUzZoV-mPGCqAj_9sJgaKMP5AU-WyH5dSzQxzwps9cUtOELZEmuDAZDmphLusteU0tJD7Yziqio3JzEA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (930, '报纸', '红土地上走出的优秀儿子', '梅克保', '中共湖南省委;', '人民日报', '宋任穷;浏阳县;秋收起义;', '今天，我们怀着无比崇敬的心情，参加纪念宋任穷同志诞辰100周年座谈会，缅怀他的历史功绩，学习他的品德风范。在此，我谨代表中共湖南省委和6800万家乡人民向他表示深切的怀念！ 宋任穷同志是湖南这块红色土地上走出来的优秀儿子。1909年7月11日，他出生于浏阳县一个贫苦农', '2009-07-11 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2009.002376', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (931, '报纸', '金融危机时,胡锦涛为何来到井冈山', '刘菁; 周伟; 张辛欣', '新华每日电讯', '新华每日电讯', '井冈山斗争;胡锦涛;井冈山革命博物馆;秋收起义;湘赣边界;', '新华社南昌7月5日电(记者刘菁、周伟、张辛欣)一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。 $$ 再上井冈山，重走井冈路', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MomqyAJ_VET3Ga7W6122pL9bTDKipVMu2CULufRSjofljEinUj4t4AHhrJoQbrEQZmbL2I8W-bs5eeLgDrc9KRjiTLm2NPOO6gPylqVh6G37wyJS46dWA5vamveWLo5aYh5Fh7a3qSOw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (932, '报纸', '道路·信念·核心', '刘菁; 周伟; 张辛欣', '新华社;', '中国青年报', '井冈山斗争;井冈山革命博物馆;南昌起义;秋收起义;湘赣边界;武装夺取政权;农村包围城市;工农革命军;共产党人;科学发展观;', '一条路，自井冈山延伸，蜿蜒曲折，在伟大理想和坚定信念的指引下，一步步走向胜利；一条路，在井冈山创建，前无古人，在解放思想、实事求是的探索中，走向农村包围城市，走向中国特色社会主义。$$ 再上井冈山，重走井冈路，抚今追昔，我们敬仰这片红土地，自豪60年新中国。', '2009-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PVIyDO3qH_kNF1_81gF8HLUbOPmW12OI_dGIDvYwsQDsI3A7GV4B28CWDlLxFiont72rcWHjCGlu3A9mls4HZcd_kGzwe7xj_nk3fWFWSf5QO8VpSytYgq_MlWwFudEn6PXMAW209yfg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (935, '报纸', '请到美丽吉安来', '魏晓霞; 班若川', '中国旅游报', '中国旅游报', '吉安市;井冈山;红色旅游;旅游业;', '“提到井冈山，几乎家喻户晓，而井冈山就坐落在江西省吉安市境内。”吉安市市长王萍用最简洁的语言，说出了吉安的非比寻常。$$ 位于江西省中部、有着2000多年历史的吉安，因红色而辉煌：波澜壮阔的井冈山革命斗争，给这片红土地留下了丰富的红色遗存———三湾改编旧', '2009-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PD5ziqAjpXvkhMB2VYgItfm9W1unrBdqb4ZBvQTepinxxwm1SrWJwxDPtySD6gWCpWvtv8c_vszi9YweH7gGXghNEjRwjYSrDSRYRCh4aVQfMe6U_LH3Q7qidWTrv-TW3-Srt1JddA2A==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (936, '报纸', '圣地洗礼铸军魂', '王继荣 ; 刘泉', '科技日报', '科技日报', '红军医院;三湾改编;总医院;参观见学;党指挥枪;当代革命军人核心价值观;井冈山;', '井冈山，中国革命的摇篮，她如一颗熠熠生辉的明珠，镶嵌在湘赣边界罗霄山脉中段，以她独特的魅力吸引着世人的目光。4月27日至29日，解放军总医院参观见学团，在总后勤部副部长兼解放军总医院院长秦银河的率领下，踏上了这片神奇的土地。缅怀先烈、寻访旧址、服务老区人民，一', '2009-05-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PF1SXRv7Bic1qnlqnxxHaMN9ZAVGxY3i8t3hpuetANdTYsh-a82n6trdZZ7YxgQEbteyN_lwbNg113vD2S7ShFtzeIqEYAX19FtqYh94leJ3d2kYx-YyesnOpfaQX5evynn7AysvU1NA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (937, '报纸', '老区遍撒科技情', '寇勇', '科技日报', '科技日报', '科技扶贫;井冈山;科技示范户;', '井冈山，曾经书写了中国革命的壮丽诗篇，老一辈革命家在这里点燃的星星之火，成就了安邦定国的伟大事业。 $$ 1989年，科技部扶贫团踏上这片红土地；如今，20年过去，科技的雨露遍撒井冈，漫山遍野的井冈杜鹃，辉映着老区人民告别贫穷的科技之旅…… $$ 科技扶', '2009-04-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ps5IQpJLrC7M_lqkcsuwpmKloiglvmlMuJ8Es1kCUDOT3iAiKncWBWJSRUUeyu-96_InXnAjwGXJ162FH01Qra3yksYtaFobUYhA4Azpea2BT2Yai1bPdsZvndMsZcsEvoMj3itZJKAg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (938, '报纸', '追寻传统之根 筑牢思想之魂', '王梦义 ; 代烽', '解放军报', '解放军报', '当代革命军人核心价值观;党代表;', '本报讯　王梦义、记者代烽报道：4月上旬，为期15天的南京军区新任党支部书记培训结束。460名新任“党代表”通过井冈山寻根之旅，向军区全体党支部书记发出倡议：做党的创新理论的坚定信仰者、政治工作“生命线”的忠实守护者、当代革命军人核心价值观的自觉实践者，让井冈山', '2009-04-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PpuKNPx8C7QEDjMcQBDdWX1XLM9SyC8JVekr0aTz9g5Lw2BfxKSmdMWakJpv2g-z4AlJuuhZIEhdxIWmVx-A6-_l84MFRY9FPapMbNpYJMLbNiAkZec2_Cv4rwwhlwUTXIOI-UoqfyBw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (939, '报纸', '永新廉政文化建设主打“红色牌”', '肖慧祥', '中国纪检监察报', '中国纪检监察报', '廉政文化建设;红色资源;', '本报讯　近年来，江西省 永新县充分利用红色资源推动 廉政文化建设，把廉政文化融 人红色文化，努力打造党风廉 政教育新亮点。$$  该县是我军实施“三湾改 编”的红色故土，是全国五大 将军县之一，境内红色资源丰 富，现有革命遗址470多', '2008-08-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OU0YjdTihK6vCvtjqwlbsDNAiosTBN47XYDigFr4vXnfbX-yYFBdtNLPlB8br5jiJzFX4Vmv2PyNAf0BI8Q7Aao6A4ZGQ5S33b4ebUGglRR86kduVxGekfY-Jop0-PYIhyFTaYBVJV4w==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (940, '报纸', '肩负起中华民族的重托', '李殿仁; 中将', '国防大学;', '光明日报', '国防大学;联合作战指挥人才;军队院校;中华民族;', '编者按 与我军同步成长壮大的国防大学，今年迎来建校80周年校庆。为总结、反映国防大学在办学治校、教学科研方面的经验和成果，军事版从本期起陆续刊发国防大 $$学一批专家学者的文章，敬请留意。 $$毛泽东曾为抗大规定了“三句话八个字”的教育方针和校风，即', '2007-12-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PWvSm8ZBrBpPlpUjwQrJllSDin5WWAg_HV_CU0_669I6GLXo9nwJLNEvPAXE6JIqp_Rt6zmzJVEpPx-ASX4HCGISNrs4cLJYfk_GRSWDjVbc7vT4CzjQszcPe38MuykZhdGvcApIxxeQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (941, '报纸', '红色经典引发示范效应', '胡晓军; 王惠民', '光明日报', '光明日报', '免费开放;爱国主义教育基地;教育示范基地;江西革命烈士纪念堂;示范效应;安源路矿工人运动纪念馆;井冈山革命博物馆;革命传统教育;红色经典;', '这是一片神奇的土地。在16.69万平方公里的土地上,青山绿水之间,散 布着一个个红色经典的称号与地名:中国工人运动的策源地——安源,中国革命的摇篮——井冈山,军旗升起的地方——南昌,中华苏维埃的“红都”——瑞金,红军长征出发地——于都…… $$红色的江西大地上,有11个', '2007-11-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OQsJ6zGvoRffTMujTywVXKSEc5ogRmed6SJrmX9YBRebq7miE3oAVfotkCb7lD9YrtZCz7vsZuTDIlrfLCWZjwN0m65AryySw3ln_KQRRw0i25S066vtia1GVJdN8Gyo81CbRsbHkdkQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (942, '报纸', '江西免费开放六个爱国主义教育示范基地', '廖国良; 杨颖; 张雪', '经济日报', '经济日报', '教育示范基地;江西省;爱国主义;免费开放;', '本报讯 从11月5日起，江西省向全社会免费开放6个全国爱国主义教育示范基地。这6个示范基地是井冈山革命博物馆、方志敏纪念馆、于都县革命烈士纪念馆及中央红军长征第一渡纪念碑园、安源路矿工人运动纪念馆、江西革命烈士纪念堂和永新三湾改编旧址。预计2008年1月底前，江', '2007-11-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MqiRF-3wEwpyWlIkaJgWcXWiv-LmSp7i9KVSP1GwvXwGoPI6W_tQzEHwXhqmU0yxey0n6lZ6vZDPiTtRhzcF1WVwu0bspuWMqJ1FGUeYAA3HiIJGVcfYMPItLCUbTkdof4Irv564liIw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (943, '报纸', '大力弘扬井冈山精神', '李文彩', '江西吉安市委;江西省委宣传部;', '光明日报', '弘扬井冈山精神;共产党人;毛泽东;井冈山斗争;马克思主义基本原理;工农红军;井冈山革命根据地;党对军队的绝对领导;共产主义理想;加强党的建设;', '井冈山精神，是以毛泽东为代表的中国共产党人把马克思主义基本原理与中国革命的具体实践相结合而培育的一种伟大革命精神。井冈山精神，集中体现了我党、我军的性质和宗旨，深刻反映了中国共产党人的崇高思想和高尚情操。在新的历史条件下，大力弘扬井冈山精神，必将激励全党', '2007-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NnK0-a_l5BO-wGGRuOwcDC-j99_H7MrO0RRRzarH4jhcYI78AVhgqyaz5wDvqMKypKPnQWOvJJ6CjOD8F1wQeV8u9DhbRe3nmLgu6LuOSEDs2efBSr_ZmbAzSzUWE2k9HUjcvLonHR-g==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (944, '报纸', '坚定信念育英才', '李章军', '人民日报', '人民日报', '坚定信念;体验式教学;中国井冈山干部学院;黄洋界;井冈山;', '“山下旌旗在望，山头鼓角相闻……”$$井冈山黄洋界。跨越革命风雨、激情岁月，６月初，中国井冈山干部学院学员、５０多名来自全国各高校的思想政治课骨干教师，满怀激情地朗诵着毛泽东经典诗词《西江月·井冈山》。$$半个多世纪前，这里孕育了中国革命成功', '2007-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PtgIg8Z1YlQ3Mt9IxfUvNUXljkJpjwO1gr0DsiNXjyLjn1rxgCD8vx4CnazK2mKfTmffL4sc2hfiNMiX3-DH0ZG8WHH3g5TA5dgqdrwItQkI_28oxxeYCoopuSt8CTNBioVQ9_dEDf5A==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (945, '报纸', '中国人民解放军的军魂', '', '人民日报', '人民日报', '中国人民解放军;共产党;绝对领导;中央军委;中共中央;', '坚持中国共产党对中国人民解放军的绝对领导，是中国人民解放军建军的根本原则和永远不变的军魂。$$中国人民解放军是中国共产党缔造和领导的无产阶级的新型人民军队，是执行革命的政治任务的武装集团，是为实现党的纲领、路线服务的。党对军队实施绝对领导这一根本原', '2007-08-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MnISFr59lwU9iIZ2JpDcDdbEzDPEG7tp-j70vfnK9tuPIZfIZN3R7jN1PlrMRauRs_BO5KfdW1d3ZxG_6-JZMWSs449R0mG9KDuDCDD1R7nXeo36qfGsEt8Cvmtbx7Am-kyiJSTiuSfQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (946, '报纸', '发扬优良传统 履行神圣使命', '', '学习时报', '学习时报', '国防和军队建设;历史使命;科学发展观;优良传统;军事斗争准备;中国特色军事变革;党对军队的绝对领导;新世纪新阶段;听党指挥;神圣使命;', '今年是中国人民解放军诞生80周年。80年来，这支伟大的人民军队，在中国共产党领导下，为民族独立解放、国家繁荣富强，为世界和平发展，前赴后继、英勇奋斗，创造了彪炳千秋的辉煌业绩。 $$（一）$$我军从诞生之日起，就聚集在党的旗帜下，坚定地同中国人民站在一起，', '2007-07-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MSfwqsBdkasAqe4n8Q-Lfl2MyV8pLt9tSJQr61rsLvNJwUoyhRZtU1UjAZAH1KVyc7o4emdbOOGcGSq4-CrZZqhYO6o5nMWL2cGUDr51YIIh7PBuvO8VTMm0fMuZAaKe85j1IY3t2Nog==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (947, '报纸', '井冈山红色旧址成荣辱观教育大课堂', '颜芳明; 刘斐', '中国纪检监察报', '中国纪检监察报', '井冈山;知荣明耻;革命旧址;大课堂;', '本报讯　日前，江西省井冈 山市又迎来了一批“缅怀先烈、 知荣明耻”实践团成员。成员 们怀着无比崇敬的心情参观了 井冈山革命历史博物馆、茨坪 革命旧址、小井红军医院、北 山烈士陵园，并重温入党誓词， 深刻领会“坚定信念、艰苦奋 斗、', '2006-12-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PY07bwLUcPKT2h1YJp-kKw8HTbDhrV04Oz6kDjeiZ5hdJHQAGQl2wAHhWeacl4RMiAABpEcHt-HAPLUgyqITPxcHFOdcXdMvYtY0UgEeEBJVNxxDNikJQ7U52La8avlDG0uhdIMEqhKQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (948, '报纸', '党旗飘扬在心中', '曹红艳; 张乡林; 黄健', '经济日报', '经济日报', '支部建在连上;红一连;', '走进济南军区某红军团“红一连”，连队的厚重历史和辉煌荣誉让人震撼————$$ 1927年9月29日走上井冈山之前的三湾改编中，毛泽东同志亲自发展了6名党员，并创立了全军第一个连队党支部，我军“支部建在连上”的历史由此开创。在革命战争年代，连队先后参加300余次战', '2006-09-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N9DnXqvtkIWB0PHINuhgkkvzg5UNYxtr8L85xvULIJ5YRcOFpP_UWAviUaSGuvaMOPXxR0mb7Uc_HtVRcYpmBYFWGXn1BT2WSg3vPKbEypNX0isKrUVQqmkhAIIRX46CF_rwtb431nQQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (949, '报纸', '三湾改编 “支部建在连上”', '', '人民日报', '人民日报', '三湾改编;支部建在连上;湘赣边界秋收起义;', '三湾，是江西永新县的一个万木苍翠、群山环抱的小山村。湘赣边界秋收起义后，毛泽东率部向罗霄山脉中段转移，１９２７年９月２９日到达这里。在进村的当晚，毛泽东在“泰和祥”杂货铺召开中共前敌委员会扩大会议，讨论部队现状及其解决的措施，决定对部队实行整顿和改编，这', '2006-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PGEnyAINxxKbHBu-UbDEBi4UrdYKZ-bua9PhTRE24LJw3h8Gg3axoVVYfnTfTJYue3GAAOy944vKnS9L69dyi4ovg5fWGYo9hdP5Klczq96il9-KXcV4ulbRLU1Wpv4XBz_sUDubJbOQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (950, '报纸', '红一连：战旗永随党旗飘', '张乡林; 唐金江; 黄健; 唐先武', '科技日报', '科技日报', '红一连;支部建设;', '把军魂融入官兵灵魂，“红一连”党支部在不同时期、不同关口，教育引导的方法各不相同。他们认为，党的创新理论是时代精神的最高体现，与我党我军的优良传统是一脉相承、与时俱进的。新兵入伍，党支部首先把他们带到荣誉室，学传统，讲战例，特别要求人人熟知“支部建在连上', '2006-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PSVqMNeCvQdErOMupYA9gerhOdFuGzK-_zWl1dLm-hf_hM3979xUr-AZmz_VzBD00Xv8IMPzPChjR-6RVnBbnB3itbnWGOK5ocTpmXi-w2Pab4JDsgYZCnBAI7z55aC69DCN6KZzj9Rw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (951, '报纸', '湘赣边界秋收起义(下)', '', '人民日报', '人民日报', '湘赣边界秋收起义;国民党军;文家市;东门市;工农革命军;', '１９２７年９月１１日，工农革命军第１师按照预定计划，举行湘赣边界秋收起义。$$ 根据中共湖南省委的部署，长沙的铁路工人和部分农民，于９月９日开始分头破坏长沙至岳阳和长沙至株洲段的铁路，一度中断了敌方的铁路运输。$$ 起义开始后，第１团由修水、渣津', '2006-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OoIptmqYvbEa0BSSb0130ySwqWUKJokapc4vfNToD2VePzWZ1vz-7N0MGXdBep44r_wQVpiPgEDFXeOjRnRq68Sz4EKUGF0EBnuA7QBXbZWL8qNom_Wx1x4LoARJrFD7sLv2kxr3ZKZw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (952, '报纸', '战旗永随党旗飘', '张乡林; 黄健; 费士廷', '解放军报', '解放军报', '红一连;党支部;战斗堡垒;支部建在连上;', '这是一支从秋收起义的硝烟中走来的英雄连队。79年风雨征程，一部“红一连”的连史，见证了我军在党的坚强领导下发展壮大的历程。 $$ 1927年9月29日，在著名的“三湾改编”中，毛泽东同志亲自在该连发展了6名党员并创立了全军第一个连队党支部，我军“支部建在连上”的', '2006-07-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MneRBZET-Q-vPxWRyPh8wbQ16xgGPuKGObNE-lqp6a0JLWt037rpnzvH9hnPrs0xFP8c1zTbjp_zmObKJBc-3AmtdNVQ5ePzX-OkE32dBMvhyd21TsuPkAg0tQXx4TIY6T7ggh5Sz69A==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (953, '报纸', '何挺颖', '', '人民日报', '人民日报', '井冈山革命根据地;毛泽东;黄洋界保卫战;党代表;', '何挺颖，１９０５年５月出生于陕西省南郑县。１９２４年，何挺颖进入上海大同大学，１９２５年５月参加五卅运动，６月加入中国共产主义青年团，随后转入上海大学社会学系学习，同年冬转为中国共产党党员。 １９２６年夏，何挺颖受党组织派遣到北伐军部队任团指导员，', '2006-05-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OozvNmhAGJctqMlDSycc2vc4RmA2eEQVWaD_4WHTwPh0eZqAf0g-4w5erQ9wWLPKY8IsrD9-d6PH9gJ73YkBoHF6I4_Ae4XC1ZSY5V2iKr0M_1q9Al6k9Rk1o99Tc_GTcPNXa-3W5fpQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (954, '报纸', '井冈山精神激励官兵爱岗敬业', '戴庆明; 李凌志', '解放军报', '解放军报', '弘扬井冈山精神;爱岗敬业;精神激励;', '本报讯 戴庆明、特约通讯员李凌志报道：4月10日,武警江西总队吉安市支队进行了一场别开生面的社会主义荣辱观教育课。500张反映井冈山精神的传统教育照片被搬进课堂,作为开展荣辱观教育的鲜活教材。该支队充分利用驻地革命传统教育资源,激励官兵树立正确的荣辱观,取得可喜成效', '2006-04-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MI_CuY4Et1GVPrZpYBcb0tbOu_2h5VMHlisSYT2s6ENGnuBL2NGv02KnsbkRR4XZ9TPu_pItTFVBfP5b0hhFsUmq0nfOnBnL9wETjRRupuia8EtsEIXGrvqH9hRWwgVhGCM30UAAmfHQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (955, '报纸', '宛希先', '', '人民日报', '人民日报', '宛希先;湘赣边界特委;党代表;', '宛希先，1906年生，湖北黄梅人。1924年在黄梅八角亭高等小学读书时，在堂兄宛希俨和黄梅县进步知识青年的影响下，接受革命思想，参加革命活动。1925年加入中国共产党。1926年秋到武汉，入国民革命军第二方面军总指挥部警卫团5连当兵，后任连长。1927年9月参加湘赣边界秋收起', '2006-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NlKHBgaN_AuduqpN8_fLMxXavWw4uDsU477nk2XRAEERKcRtRMcbvrTDVSs4WvuNVmg770rvU9A2uWpbNa14Xl9HmW3Tgg-ccyTN7ERWU50SlPiP4rZZiftOGXFVXZxn9w8hNw1jYTiw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (956, '报纸', '曾士峨', '', '人民日报', '人民日报', '曾士峨;国民革命军;', '曾士峨，1904年生，湖南益阳人。1923年入益阳信义大学，开始接受进步思想。1924年到长沙，参加反帝爱国学生运动。1925年入黄埔军校长沙三分校学习。同年6月加入中国共产主义青年团。1926年入国民革命军第8军独立1师学生队，同年转入中国共产党。参加了北伐战争，在国民革命军', '2006-02-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NYnP-xqQa63UvSssP7IaWhfnjsRXJC68MyCUs7EJwjfmLQLgDwEMF6wqCZpI8Wn9JkOkHxXCiGsXJ3DF1NTOY-GiVIZaI4TX4RZ-h_1RtligjSpwoBqaAPttctlh4xAWmR3QRX8Qp85Q==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (957, '报纸', '永新“旅游改编”见成效', '李少豪', '中国旅游报', '中国旅游报', '红色旅游品牌;旅游线路;', '江西永新县是著名的“三湾改编”和“龙源口大捷”发生地，为全国第四大将军县，也是贺子珍、许和子的故乡。全县现存革命旧址、遗迹470多处，其中国家级文物保护单位7处。2004年，永新县被国家列入《全国红色旅游经典景区名录》和《全国红色旅游精品线路名录》。除“红色”外', '2005-12-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N18DQhVyj_mlXxiWrKI3tvqBdZnu_slLt6X1nS9Z5373R9LWk_mxoGUYoGZ9PPDCaJhqPPzlMN6TwMu8VU92sYqCxQGD0_sl-M5wD1qLaXaHyuhO1nIRxJREz1sttLmEo6bavlE3yEBQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (958, '报纸', '谭政', '', '人民日报', '人民日报', '政治部主任;八路军;', '谭政是杰出军事家，中国人民解放军卓越的政治工作领导人。1906年生，湖南湘乡人。1927年3月加入国民革命军。9月参加毛泽东领导的湘赣边界秋收起义和三湾改编。10月加入中国共产党。后任中国工农红军纵队队委秘书、军委秘书长、军政治部主任、师政治委员、军团政治部组织部部', '2005-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OceeqR_7cY26qLv7ghsNgmrQz2rJb3B8QD-OvoS9IbE-_BPtM-XEND61ArIsznr_KGCZHemvgoXw9rU_CNFVYR96N-FskLHOWxKxPt3KxwMEm7oL8ihh41u1G180Pn-hPIOhZBDxctCQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (959, '报纸', '把政治信念化作实际行动', '丁海明; 王士彬', '解放军报', '解放军报', '实际行动;政治信念;高举旗帜;', '3月的京西宾馆春意盎然。解放军代表团分组讨论的各个会场里气氛热烈。高举邓小平理论和“三个代表”重要思想伟大旗帜，坚决听从党中央、中央军委和胡主席指挥，把这一坚定的政治信念化作实际行动，是军队代表们的重要话题。 $$ 坚定信仰不动摇 $$ 新春伊始，从高级领率', '2005-03-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O9ICClWG8gkF9KKHfUmKQQjRhgPteyTZZ5xSt4K0NT_IzDlXYRVDUdvLZRNuAI1DAEp86IzEg3zsL_s1DGUqqAMzVrPln0KS1yB8no8FzxfsTAKm4Va6U78AX-IYDI3VrDLfTTQOnDfA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (960, '报纸', '江西法官走进“红色大课堂”', '郭兵; 周迎飚', '人民法院报', '人民法院报', '保持共产党员先进性教育活动;大课堂;', '江南春早花绽红。今春以来，赣鄱大地的法官和其他工作人员，纷纷举旗列队，蓬勃走向当地的“红色课堂”——读红色书籍，游红色圣地，看红色展览，听红色报告，唱红色歌谣，再次接受革命传统教育，营造保持共产党员先进性教育活动的浓厚氛围。 $$ 江西高院党组书记、院长康', '2005-03-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MtbPN5ImtT1rECu4gOJQ_WG0LmGL20_3k8yfxpFYYTsdrrSYkJSlEUwFaP2GHczbs9gqQA9NS9NyzCHaR1hCdraevCtmG-T1KxZdYocUORDKtSGpv4YyYRaN28k6mHdKIzLivvpVwu_g==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (961, '报纸', '武警江西吉安支队用“井冈山精神”深化“四个教育”', '舒春平; 戴庆明', '人民公安报', '人民公安报', '井冈山精神;革命传统;江西吉安;四个教育;', '本报讯：驻守在井冈山革命 老区的武警江西总队吉安市支 队，充分利用驻地革命传统教育 资源，把“井冈山精神”寓于“四个 教育”中，连续十年开展“学习红 军优良传统，争做合格忠诚卫士” 活动，涌现出一大批履职尽责的 高素质官兵。$$', '2004-12-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MU4YH2_kK9HSicfR9C2aEpSxmTT2bFOZhyrrpLaYND7oOvNaFrtdYhxQ7bZYpsPVIBvcoNOifaKd0SUoFVdNLRpNNQERdrj13Cdb8woqS3kknzRWfmBq12GqHi3t3QJEKBc977UCZ8bg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (962, '报纸', '吉安军分区千余民兵上井冈培育革命战斗意志', '谢启恩; 徐政武', '解放军报', '解放军报', '军分区;战斗意志;', '本报讯　谢启恩、特约通讯员徐政武报道：5月下旬，江西省吉安军分区组织千余民兵登上井冈山现地学传统。这是该军分区以红色资源为教材加强新形势下民兵思想政治建设、促进民兵工作政治落实的具体举措。 $$ 吉安军分区党委坚持用强有力的思想政治工作，促进民兵工作政治落', '2004-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O4_Ejn8etkPVGV80dzd8hFs8dVdGXiA3VwaZLQzJPu9fb9dqAkwIhWnIOCjZ6NR2wq3hMGjg4MPxADhOoYJPMe8G3he5YW4vHprfZ37wt4h9LlcydUg5oqo96KbkJwzEID4iAofzTBvg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (968, '报纸', '始终不渝坚持党对军队绝对领导', '郭嘉', '人民日报', '人民日报', '支部建在连上;党对军队的绝对领导;军队建设史;党对军队绝对领导;', '建军之魂 胜利之本 ──人民军队永远忠于党$$  记者：党的三代领导核心特别强调“党指 挥枪”，为什么说坚持党对军队的绝对领导，是 我军政治上永远合格的根本保证？$$  杨春长（以下简称杨）：党对军队的绝对领 导，是我军永远不变的军', '2001-07-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P47p9pHtCgNP7i7SnS2L_azKF3p3XcaqEvSjmwm5-YONXTeB_YPYtCLwJIVY3fEEi6EK1kcrh2N42hM_GgH9szx1U27nsx4bMHy88mSD4tf2Lvf_vKxUZWo9KggwdhHdHSiz_0vZuUaA==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (969, '报纸', '追寻先辈学习成才之路', '何鸣鸿; 周猛', '解放军报', '解放军报', '井冈山;毛主席;', '本报井冈山5月9日电：记者何鸣鸿、周猛报道：两天来， 在这里缅怀革命先烈、学习光荣传统的第二届全军十大学习成 才标兵有个意外“发现”：我军官兵学习成才的历程与我军发展 壮大的历史一样漫长，起点就在井冈山。$$  1927年，', '2001-05-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NqaGNEUgwF-aoyyPoKOlsmgca7Jz_VoCoDw7LO8ddF012taZ3PZWF94Cssbf5o4uWshLQJ1vnm3BtcSLedkB2OHK7mKcIIpRCfKqlc_3VpzrIuAFEpi74WW1gtPU-2V6vR-M-my3p4qw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (970, '报纸', '八角楼前讲传统 三湾村里话军魂', '万海林; 彭卫平', '解放军报', '解放军报', '八角楼;三湾村;三湾改编;', '本报讯：万海林、特约通讯员彭卫平报道：地处革命摇篮 井冈山的江西省吉安军分区，在理想信念教育中，以井冈山 为课堂，以井冈山斗争史为教材，引导官兵走进历史，面向未 来，深刻认识“三湾改编”确立的党对军队绝对领导制度是我军', '2001-05-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4ONQSaMPtdhudfSjhSx1RyYz082O7HCol1hDQeABifYKEPcELTAeMAE3R_WquCWoAgNJFtH7KInw0BD3MBtXC6hU1jmpzZxEeliYkkpeWIhhINfF1aW6LJIP8Lsaim8WUOcNOtytI69SQ==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (971, '报纸', '士兵做主人 基层建设兴', '暴玉怀; 孙继炼; 丁海明', '解放军报', '解放军报', '三大民主;基层建设;', '1927年9月，毛泽东在江西省永新县三湾对秋收起义后 的部队进行了著名的“三湾改编”，创立了我军政治、经济、军 事“三大民主”。如今，它已经伴随我军走过了73年的风雨历 程。随着时代发展、社会进步和形势变化，“三大民主”的优良 传统在部队如何继承', '2001-01-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M_3vZl59vQ9rJPS4-n6YSnoskxgT8mF0Dkytq1pGfK5JxhXF3ke2kL3GKKuH1WpACn7IZyhkz4HcbxcC8gpeC2Fz2um_KBem08PwVIoEAOtc_rtjX2VZtD6tyPxBR3s4RtVWrx4ee5Uw==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (972, '报纸', '井冈山“寻根”', '王握文; 曾砥平', '科技日报', '科技日报', '井冈山;革命传统;博士生;', '本报讯：通讯员王握文 曾砥平报道：今年 开学伊始，国防科技大学2000级166名博士研 究生走宁冈，访永新，上井冈，在中国革命的发 源地开始了入校后的第一课，接受革命传统教 育。$$  今年考', '2000-10-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O4_EqPnCcLwNT729A4fPLlxUmjKklv7Aad3O8CW5jhLt3YQDAEgZ45Aewt-4v0CDtr5zeJnRkS3sYuoqfb_zm4k4En0NsupC40yMLQUNez6kksnRcH51gKQZCz4FetN4zSQlbem7tlGg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (973, '报纸', '博士生第一课：井冈山上“寻根”励志', '唐湘岳; 王握文', '光明日报', '光明日报', '博士生;井冈山;第一课;', '本报讯（记者唐湘岳 通讯员王 握文） 国庆前夕，国防科技大学2000 级166名博士研究生走宁冈，访永新， 上井冈，在中国革命的发源地开始了 他们入校后的第一课──井冈山革命 传统教育。这是该校为打牢高层次人 才思想基础而坚持了多年的做法', '2000-10-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N4HFSK8HHLsMX825v_FKirtzGLuvZKEEHirq8Y4mE3ju9udmUWfjuu2fHYATIrJ69NxGB4vamxOQoB6-ZkS0Swu_UnVpauKfPHbV-0JGEodAcli8AWhLlPHegQrT6A-Q5OCg77lQqQkg==&uniplatform=NZKPT&language=CHS', '三湾改编_screened');
INSERT INTO `ds_article` VALUES (974, '报纸', '井冈山精神——跨越时空，照亮前行之路', '', '中国民族报', '中国民族报', '井冈山精神;井冈山革命根据地;', '井冈山，中国革命的摇篮。$$ 中国共产党人在创建和发展井冈山革命根据地的过程中，形成了坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利的井冈山精神。$$ 2016年春节前夕，习近平总书记来到江西，看望慰问广大干部群众和驻赣部队，首站就是井冈山。习近平总', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001151', '张子清_screened');
INSERT INTO `ds_article` VALUES (975, '报纸', '这道光，照亮前行之路', '赖星', '新华社;', '新华每日电讯', '井冈山精神;共产党人;秋收起义;习近平总书记;红四军;井冈山市;毛泽东;', '90多年前，井冈山茅坪八角楼。一根灯芯的微光，穿透漫漫长夜。$$ 油灯下，毛泽东同志写下《中国的红色政权为什么能够存在？》《井冈山的斗争》两篇光辉著作，成为马克思主义中国化的伟大开篇，闪耀着“坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利”的井冈', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005584', '张子清_screened');
INSERT INTO `ds_article` VALUES (977, '报纸', '弘扬革命精神的“传家宝”', '王子潇', '人民日报', '人民日报', '革命精神;红色文物;', '一件件红色文物，用最沉静的姿态，讲述着最动人的故事，它们是弘扬革命精神的“传家宝”，也是教育后来人的生动教材 走进贵州遵义四渡赤水纪念馆，一件件陈列的红色文物，重现了那段烽火燃烧的岁月，让参观者内心受到震撼。一个用篾条绑着的陶坛和两枚铜钱，作为一套组合文', '2021-07-20 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.013803', '张子清_screened');
INSERT INTO `ds_article` VALUES (982, '报纸', '井冈山会师(上)', '', '人民日报', '人民日报', '井冈山会师;毛泽东;南昌起义军;湘南特委;工农革命军;', '１９２８年４月下旬，朱德、陈毅率领由南昌起义部队余部和湘南农军组成的工农革命军，与毛泽东率领的湘赣边界秋收起义后组成的工农革命军在井冈山胜利会师。为了纪念这次具有伟大历史意义的会师，朱德曾赋诗道：“红军荟萃井冈山，主力形成在此间。领导有方在百炼，人民专政', '2006-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MPPJ1qXYwr1G2HngYgS8xcAhx3kWFsld8pvCE45tLvej2kWG5dnOjBTmG1pLZDwP4aHmVLUA-Uu-KOzDNsScMqPITGNDH_MTGVtvnaGPoksu-jiPdY2p8jy8LnYvHVZTqfVaOliXQE5w==&uniplatform=NZKPT&language=CHS', '张子清_screened');
INSERT INTO `ds_article` VALUES (983, '报纸', '何挺颖', '', '人民日报', '人民日报', '井冈山革命根据地;毛泽东;黄洋界保卫战;党代表;', '何挺颖，１９０５年５月出生于陕西省南郑县。１９２４年，何挺颖进入上海大同大学，１９２５年５月参加五卅运动，６月加入中国共产主义青年团，随后转入上海大学社会学系学习，同年冬转为中国共产党党员。 １９２６年夏，何挺颖受党组织派遣到北伐军部队任团指导员，', '2006-05-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NBBZ1XAV0XzAvT_aEgtyT5UZPv8sLvM_9TV4q0gpHDPF5mzAZR43pBnE0JfMBakQihL6XD9bH6a-ML7ojwc4aUDd7T9eQmuNeOmRLy6odBf6AZFsxiqa2VS5GNdoOOJ_t5SVZ7btppaw==&uniplatform=NZKPT&language=CHS', '张子清_screened');
INSERT INTO `ds_article` VALUES (986, '报纸', '重走红色之路 探寻生态之美', '范朝慧', '中国旅游报', '中国旅游报', '井冈山革命博物馆;毛泽东;旅游点;红色旅游;研学旅行;红色摇篮;精品线路;八角楼;红色文化;黄洋界哨口;黄洋界保卫战;实景演出;讲解员;', '“久有凌云志，重上井冈山。”近日，文化和旅游部资源开发司组织多家媒体及OTA代表，组成“建党百年红色旅游百条精品线路”采风团，走进江西井冈山，沿着“井冈之路·星火燎原”精品线路，走进茅坪八角楼毛泽东故居、井冈山革命博物馆、黄洋界哨口等红色景区景点，重温红色记', '2021-10-20 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002982', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (989, '报纸', '把中华民族复兴伟业不断推向前进', '鹿心社', '中共江西省委;', '人民日报', '南昌起义;中华民族复兴;大革命失败;国民党反动派;', '习近平同志在庆祝中国人民解放军建军90周年大会上的重要讲话，回顾了人民军队发展壮大的光辉历程，总结了人民军队从胜利走向胜利的历史经验，提出了把人民军队建设成为世界一流军队必须牢牢把握的根本要求。作为人民军队军旗升起的地方，我们要深入学习贯彻习近平同志的重要', '2017-08-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pl-K4edQNcz1x2Lf9FlyyrVMHp09jl5zFG5esnurlPd83-PbnHkq8nLHkNgM_MmTSOi25fd6HfzgfJOkJC_trG_Th8tJ7bhbSdVvf8_J09Hd4CmBlAHjHjL7ulipyoYYcUZIYeKsJOBQ==&uniplatform=NZKPT&language=CHS', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (990, '报纸', '燎原星火在这里点燃', '孟维伟; 曹蕾; 罗珺', '中国纪检监察报', '中国纪检监察报', '井冈山革命博物馆;湘赣边界;井冈山革命根据地;工农武装割据;', '6月28日，江西井冈山茅坪八角楼。青油灯静静地放在桌上。$$ “八角楼的灯光，比天上的北斗星还要明亮。”讲解员黄俊峰正在向游客们讲述那段艰难而光辉的岁月，“正是在这盏如豆的小小青油灯下，毛泽东挥笔写下《中国的红色政权为什么能够存在》《井冈山的斗争》两篇光辉著', '2016-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NpRDTh3ZkzoqtkYw4ST-0-Gla1erKNb_-94DY9PmhlxeXjh_cQ4HdTbm6awu8efKk937awOTV4D6x41mLjIGrJnfxxkOSsgxC4tPXMyoNGGj5xgX_SSEvgmq1c6qGfdRpTeAHQlNv1Yw==&uniplatform=NZKPT&language=CHS', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (991, '报纸', '激情澎湃的军魂颂歌', '严德勇; 李华敏 ; 田利阳', '解放军报', '解放军报', '支部建在连上;余洒度;历史题材;武装割据;党指挥枪;戏剧冲突;秋收起义;思想建党;三道桥;四个伟大;三湾改编;', '金秋十月，秋高气爽。广州和长沙两地，同时被一部名叫《支部建在连上》的大型革命历史题材话剧点燃“红色激情”。$$ 这部向党的十八大献礼的剧目，取材于秋收起义部队攻打浏阳失败后，从1927年9月文家市转兵，到1928年4月井冈山朱毛会师那一段艰苦卓绝的斗争历史。话剧以', '2012-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O2wuVeoW4ANflFItgPiv4sUntBj-Ef665HQFy4_JKN47OpbyE5kFTN_hLtNUuR2zLrwJ3A6cYxvOr2_rgHA-L4Z77ibUZnRfkp-aZGv1d2GiGltJuuxdyE7uOVxwirMcmrsD2eU0S6tA==&uniplatform=NZKPT&language=CHS', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (994, '报纸', '彭儒同志遗体送别仪式在京举行', '钟纪闻 ; 尹健 ; 瞿芃', '中国纪检监察报', '中国纪检监察报', '中央纪委;监察部;', '中国共产党的优秀党员，久经考验的忠诚的共产主义战士，我党纪律检查战线的优秀领导干部，中央纪委原专职委员彭儒同志（部长级医疗待遇）遗体送别仪式，１０月１３日上午在北京八宝山革命公墓举行。贺国强、曾庆红、何勇参加了送别仪式。 $$ 彭儒同志因病医治无效，于', '2010-10-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N-irJ66bIVt48yne9nS-xApCKECK8tqMNAm-3qz_1yxtxnAJu83IXSsXjbWSZooDY_TY_TWxKKW0BblDBCUIa6H2wEv5kSY3-GuE_E5R72fWaiPOC9lrvuV98BKHy4-4p-GAMa71ny5Q==&uniplatform=NZKPT&language=CHS', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (998, '报纸', '请到美丽吉安来', '魏晓霞; 班若川', '中国旅游报', '中国旅游报', '吉安市;井冈山;红色旅游;旅游业;', '“提到井冈山，几乎家喻户晓，而井冈山就坐落在江西省吉安市境内。”吉安市市长王萍用最简洁的语言，说出了吉安的非比寻常。$$ 位于江西省中部、有着2000多年历史的吉安，因红色而辉煌：波澜壮阔的井冈山革命斗争，给这片红土地留下了丰富的红色遗存———三湾改编旧', '2009-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PBRKDigE_gEIYE2R-4QyzQc--VC78542SKGhzRKWv3Lf6WyYHg34eIjdZ7ySpz5qje0MSS2fXeUXOsU-QFm8p6E0fz176CJx9W2oOV5zvQwdtNbXUlAgfn2eBo2znVRt-twrrWq8AANg==&uniplatform=NZKPT&language=CHS', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (999, '报纸', '杨柳新翻再现“井冈山革命斗争”', '', '中国文化报', '中国文化报', '井冈山革命斗争;刘大为;井冈山时期;', '为了深入实地考察生活，更好地再现“井冈山革命斗争”的伟大历史瞬间，刘大为和苗再新专程跑了几趟井冈山。$$ 他们找到井冈山博物馆的馆长谈了一晚上，了解当时的历史背景，包括服装、旗帜、时间、地点等种种状况；参观井冈山博物馆、会师博物馆等等，随后又到井冈山', '2008-12-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M75z_uJ9LrPnm5esDpdydIu4Cj_eOX6cj1t0z8dX3MgV1ThAljfEjD-1VFgcg1L0-zWis_1ruCV5Zfi2IUxsPZY1v8zXedDIe5MKht2KYh8LACBbWmcXWxaGfgwTdeAVEtpFpUpZJGPg==&uniplatform=NZKPT&language=CHS', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (1000, '报纸', '闪耀红色与绿色的井冈山', '郭海; 张遥', '中国经济时报', '中国经济时报', '井冈山;客家文化;笔架山;客家人;休闲度假;', '这是一片神奇的土地,这是一个令人无法忘怀的地方,这是一座高度没有极限的山岳。这就是传统的红色旅游胜地井冈山。$$  红色旅游,一直以来都是井冈山特色旅游文化的代名词。然而,井冈山不止有红色的历史、红色的文化,更有青山绿水的环境和多姿多彩传统而神秘的独特文化。', '2008-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MRzeLRj6TnvuzQMTdm9J9DEq1x1eOp5P-2o72A2odDrad-RC4KL0mU_esMCOG5jd2V_B4r4q55EmExh6ZVkpF4YU0GbnerPBQcMg5uYDxqS0Z476I6axPewpfzvGdW05vhFEL5i00KjA==&uniplatform=NZKPT&language=CHS', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (1001, '报纸', '武警江西吉安支队用“井冈山精神”深化“四个教育”', '舒春平; 戴庆明', '人民公安报', '人民公安报', '井冈山精神;革命传统;江西吉安;四个教育;', '本报讯：驻守在井冈山革命 老区的武警江西总队吉安市支 队，充分利用驻地革命传统教育 资源，把“井冈山精神”寓于“四个 教育”中，连续十年开展“学习红 军优良传统，争做合格忠诚卫士” 活动，涌现出一大批履职尽责的 高素质官兵。$$', '2004-12-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MJWKxKsSY9JHkU5gSBvPuxDY_bAx2i83kdvY5HH5VpPEKf6hSa7kMI3DM2JMAd4B6PXQbNhdbFZ2a-IquRAZuiq-ej-YeJbWbfrqt5KChklnV7w1_aTArC3utWy3kmssPNnicmfH0zbg==&uniplatform=NZKPT&language=CHS', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (1002, '报纸', '千场免费电影送老区', '叶辉; 严红枫; 杨振华', '光明日报', '光明日报', '横店集团;影视产业;井冈山市;', '本报浙江横店7月14日电　浙江横店影视产业实验区“千场免费电影送老区活动”近日首战告捷，在7月1日起的一周里，放映队为革命老区井冈山市的中小学生放映电影30多场，观众达数万人次。受到老区中小学生的热烈欢迎。$$ 浙江横店影视产业实验区于今年4月挂牌，这是目前', '2004-07-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NWcfYryKYfVJIadf95Q-3V6Ey3wnyJA2NccwF8o-WCIwB9QhoCY78uHfZOfh_8UPtgeorjiEgFMxNJzc9_rI_StEy9mkYD_nxoKoG8hZBodgWePz_xvt09KQwH6jp-dO_-PPqfM70WIg==&uniplatform=NZKPT&language=CHS', '朱毛会师_screened');
INSERT INTO `ds_article` VALUES (1007, '报纸', '井冈山精神——跨越时空，照亮前行之路', '', '中国民族报', '中国民族报', '井冈山精神;井冈山革命根据地;', '井冈山，中国革命的摇篮。$$ 中国共产党人在创建和发展井冈山革命根据地的过程中，形成了坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利的井冈山精神。$$ 2016年春节前夕，习近平总书记来到江西，看望慰问广大干部群众和驻赣部队，首站就是井冈山。习近平总', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001151', '王尔琢');
INSERT INTO `ds_article` VALUES (1012, '报纸', '《你的样子》为百年中国共产党画像', '王若辰', '新华每日电讯', '新华每日电讯', '人物故事;政论片;《你的样子》;共产党;百年中国;', '“新华社推出的这部片子，用全新方式讲述中国共产党砥砺奋进的百年历史，以感天动地的故事、新颖独特的视角，回答历史之问。”党史专家如是说。$$ 这是什么片子？——“七一”前夕，由新华社音视频部摄制的建党百年五集大型政论片《你的样子》重磅推出。$$ 讲述方式新在何', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005206', '王尔琢');
INSERT INTO `ds_article` VALUES (1013, '报纸', '今日之中国，正如您所愿', '钟轩理', '新华每日电讯', '新华每日电讯', '人民幸福;民族独立;中国共产党领导;中国特色社会主义道路;中华民族;民族复兴;', '魂断最是春来日，一起弹泪过清明。$$ 又是一年清明时节。在这个慎终追远、思古怀今的特殊时刻，最不能忘记的是那些为民族独立和解放、为国家繁荣和富强、为人民幸福和安康抛头颅、洒热血的革命先辈和人民英雄。一百年来，在中国共产党领导的实现中华民族伟大复兴的历史进程', '2021-04-04 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.002703', '王尔琢');
INSERT INTO `ds_article` VALUES (1014, '报纸', '王尔琢：革命不成功立誓不回家', '张嘉升', '学习时报', '学习时报', '王尔琢;工农革命军;实业救国;', '“儿何尝不眷恋着家庭的亲密，但烈士殷红的血迹燃起了儿的满腔怒火，乱葬岗上孤儿寡母的哭声斩断了儿的万缕归思。为了让千千万万的母亲和孩子能过上好日子，为了让白发苍苍的老人皆可享乐天年，儿已以身许国，革命不成功立誓不回家。”这是王尔琢写给远在湖南老家的父母的一', '2019-12-02 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2019.000115', '王尔琢');
INSERT INTO `ds_article` VALUES (1016, '报纸', '追寻中华民族伟大复兴之路', '肖怀远', '天津市人大常委会;', '人民日报', '中华民族伟大复兴;中国共产党;毛泽东;农村包围城市;共产党人;武装夺取政权;', '经过创作团队3年多的不懈努力，在中国共产党建党纪念日前夕，在继《解放》、《辛亥革命》之后，我们把与著名作家王朝柱合作的第三部革命历史题材电视剧《寻路》奉献给全国观众，心里感到十分欣慰。$$ 《寻路》秉持严肃认真的创作态度，严格尊重历史真实，以广阔的视角、宏', '2013-06-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB43_O-Fx-vXfxfCoGq_mmkghPJcXj7ho92Y6sf2RicPE_S91XXu2pVYns0BRu2WWKYQ5a-EGfD0iR2SG5aWYuXkmQ7vjgvwq5Eps66qej3er9RgaBSwgnMK6-9JV6rn_NkWh6kh19y4Llvxnum-rwDY9Jf48ssmb7bZOOyoubJ6JQGsLMziJYiD&uniplatform=NZKPT&language=CHS', '王尔琢');
INSERT INTO `ds_article` VALUES (1018, '报纸', '何祥美：中国士兵的多彩人生', '丁广阳; 王余根 ; 程永亮; 杨清刚', '解放军报', '解放军报', '狙击手;王尔琢;先天条件;心路历程;', '编者按$$　　10年军旅生涯，10年艰苦磨砺，成长为陆地、海上、空中驰骋的“三栖精兵”，何祥美的精武之路并非一帆风顺。“当兵就当能打赢的兵”，何祥美在生与死、得与失、苦与乐等方面的选择，生动诠释了一名士兵践行当代革命军人核心价值观的丰富内涵。他成长的心路历程告', '2010-01-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB5x1YOWh2cW3Tpts7SsqVLNig56ov75QfRkMFT2SE7b3v618DX85QQeCkUBOH-w1Wj0oVGmLyhwXNSK2683QDYcL1hqB5x5iaTqCgquIVyVJCglHRL_No05ihrktHlGFSPi-XnZ6cuJb9ncIpmQNu0m2Xns7r6wvkQFnmeOn2x6NA==&uniplatform=NZKPT&language=CHS', '王尔琢');
INSERT INTO `ds_article` VALUES (1019, '报纸', '何祥美：中国士兵的时代形象', '代烽; 丁广阳; 胡伟; 陈云', '解放军报', '解放军报', '狙击手;狙击步枪;当代革命军人核心价值观;扁平空间;新型装备;橡皮舟;粘液质;上合组织;战备物资;', '新闻链接：2008年9月，本报曾报道了“三栖精兵”何祥美的先进事迹，展示了一名中国当代士兵的精武风采。此后，南京军区党委作出向何祥美学习的决定，南京军区部队广泛开展了“当兵就当能打仗的兵”学习讨论活动，持续掀起了练兵热潮。此后，何祥美先后获“中国青年五四奖章”', '2010-01-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB4ZhicgatrUUydTPsx08ko1MTq_BRLGkeqE1ELqwX8XEtyb3CFtTtigZUA8sZRqvmjIc32_JYhgQxPgZQqs_afHwRLn1KHLZjhWyYRLyoz9d4d_R35bpNn2vOJWD33QozLSSexUhj_Kd7uCIQJLceI5KCUeFQBSfAKypyr7-mkEdw==&uniplatform=NZKPT&language=CHS', '王尔琢');
INSERT INTO `ds_article` VALUES (1022, '报纸', '跨越时空的井冈山精神放射新的时代光芒', '刘旭; 姚鹏', '中国妇女报;', '中国妇女报', '井冈山精神;井冈山革命根据地;红军战士;毛泽东;', '在江西省泰井高速公路连接线进入井冈山的路口处，一座大型雕塑“井冈红旗”巍然矗立。雕塑高19.27米，跨度27米，寓意井冈山革命根据地创建于1927年。如今前往井冈山的人们往往会在这里驻足，大家也多是从这里开启对中国革命摇篮井冈山的全新体验。$$ 雄伟壮美的“井冈红旗”', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.002211', '五龙江_screened,黄洋界_screened,井冈山革命博物馆_screened,茨坪_screened,井冈山会师_screened');
INSERT INTO `ds_article` VALUES (1023, '报纸', '优秀指挥员王尔琢', '', '人民日报', '人民日报', '王尔琢;国民党军;龙源口;指挥员;', '新华社北京３月１日电 １９２８年１０月中旬，在为中国工农红军优秀指挥员王尔琢举行的追悼会上，毛泽东、朱德高度评价了王尔琢为革命所作的贡献。会场上悬挂着由毛泽东拟稿、陈毅书写的挽联：“一哭尔琢，二哭尔琢，尔琢今已矣！留却重任谁承受？生为阶级，死为阶级，阶级', '2011-03-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Np2qB-FqVVMf1C5BgrjITjKMSXbFfTtYA1eFO7_QpCo89s_SOKYmbjFPQsLFqff9lPYuiJb6PKHjntpSvrhscp4P8ec9kBP3aMhF9Jtc2Zv08hILX7tCWNbv2cssoBSFEXzadIuXPAvg==&uniplatform=NZKPT&language=CHS', '五龙江_screened,朱毛会师_screened,王尔琢');
INSERT INTO `ds_article` VALUES (1024, '报纸', '红六军团由湘赣苏区突围西征', '', '人民日报', '人民日报', '国民党军;湘赣苏区;', '１９３４年夏，湘赣苏区反“围剿”失利，苏区日益缩小。７月２３日，中共中央和中央革命军事委员会命令红６军团撤离湘赣苏区，到湖南省中部发展游击战争，并同红３军（由红２军团改编）取得联系，配合中央红军的战略行动。据此，中共湘赣省委和湘赣军区成立了以任弼时为主席', '2006-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MlyVnD5pbBB8OUMm-a_v62TDc9FhsEC2oHrjDcXpYe7VyDLwd4POtMjZWD9Q67yZKs1rYODjRljbyI92tM7x7_zERn1_wsLk_JJ4AEntyQOhk0Ab7gU3rvBuW_DtG7e1cO8RDWjnNN1Q==&uniplatform=NZKPT&language=CHS', '五龙江_screened');
INSERT INTO `ds_article` VALUES (1025, '报纸', '风雨五十载 山花开更艳', '张敏; 周伟', '新华每日电讯', '新华每日电讯', '大汾镇;', '井冈山脚下的遂川 是个贫困县。在这个县 的大汾镇，活跃着一支 已有50年历史的农民 剧团。$$  邹德安现在是农民 剧团的团长，也是大汾 镇的党委书记。在大汾', '2000-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PIz6wCitMw497Y-Lp7QupijVzd-ioqqrKsI7GAljyH8Nq65bycz97Ay_uUyQI2nPvLsHku31VmEOn6VesSp3cW9Y4Sm0Kjs83kP29i1OBAak2NWn0rIDbhel_nYCDv8QizYlOAB-y3NA==&uniplatform=NZKPT&language=CHS', '五龙江_screened');
INSERT INTO `ds_article` VALUES (1026, '报纸', '永不磨灭的“长征印记”', '兰善喜; 郭冬明; 危乔巧; 马宇辰', '解放军报', '解放军报', NULL, '金秋十月，江西于都。中央红军长征集结出发地纪念园内，一场以“伟大的出发·永远的长征”为主题的中央红军长征出发历史展开展。一张张图片、一段段史料、一件件文物，将参观者带回90年前的于都河畔。 1934年10月，中央红军8.6万余名将士，星夜渡过于都河坚毅出征，在中华大', '2024-10-16 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2024.002352', '项英');
INSERT INTO `ds_article` VALUES (1027, '报纸', '“古武汉的源头，新武汉的荟萃”', '吴植; 胡诚; 连迅; 张潘', '新华每日电讯', '新华每日电讯', NULL, '提起武汉，许多人自然想到武汉三镇：汉口、汉阳和武昌。汉江汇入长江，在地理意义上将武汉一分为三。然而，“武汉”作为三镇的合称，上世纪20年代才出现。此前，武汉地区一直或多或少与“江夏”这个名字有关，其历史可追溯到西汉时期设立的江夏郡。 如今，江夏是武汉南部的', '2024-06-28 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2024.004885', '项英');
INSERT INTO `ds_article` VALUES (1028, '报纸', '一把见证革命历程的手枪', '李卫玉', '中国国防报', '中国国防报', NULL, '赖传珠使用过的左轮手枪，现收藏于南昌新四军军部旧址陈列馆。 在南昌新四军军部旧址陈列馆里，珍藏着一把左轮手枪。这把手枪长21厘米、宽17厘米，见证了新四军军部参谋处长赖传珠的革命历程。如今，参观者通过这把手枪学习新四军的光荣历史，感受新四军将士为了民族解放殊', '2024-01-04 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2024.000437', '项英');
INSERT INTO `ds_article` VALUES (1029, '报纸', '干群合力干 振兴步子快', '孟祥夫', '人民日报', '人民日报', NULL, '秋雨过后，碧空如洗。“吱呀”一声，河北滦平县五道营子满族乡五道营子村村部的大铁门开了。早上7点刚过，村党支部书记、村委会主任吴克东就来到了村部。 孟营子自然村村民代表孟钧莱一脚跨了进来：“老吴，我们需要安装变压器，另外北长垅原有的管灌不能用了，要换成喷灌管', '2023-10-17 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.010311', '项英');
INSERT INTO `ds_article` VALUES (1030, '报纸', '信仰铸忠魂', '易舜', '中国纪检监察报', '中国纪检监察报', NULL, '春回大地，万物复苏，作为湖北省武汉革命博物馆今年推出的首个新展，“信仰铸忠魂——中国共产党首届中央监察委员会成员专题展”最近在中国共产党纪律建设历史陈列馆正式开放，吸引包括纪检监察干部在内的众多党员干部前来参观，从中汲取奋斗的力量。 1 首届中央监察委员会', '2023-02-13 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.000462', '项英');
INSERT INTO `ds_article` VALUES (1038, '报纸', '立足新起点 奋斗新征程', '沈良坤; 刘帆; 徐文标; 李凯', '中国应急管理报', '中国应急管理报', NULL, '连日来，应急管理系统把学习宣传贯彻习近平总书记“七一”重要讲话精神作为一项重大政治任务，通过邀请“七一勋章”获得者上党课等方式，引导广大干部职工深刻领会和把握重要讲话的重大意义、丰富内涵、核心要义、实践要求，切实把思想和行动统一到重要讲话精神上来。请', '2021-07-21 08:00:00', 'https://link.cnki.net/doi/10.28046/n.cnki.ncaqs.2021.002505', '项英');
INSERT INTO `ds_article` VALUES (1039, '报纸', '再现隐蔽战线上的“八年抗战”', '袁一雪', '中国科学报', '中国科学报', NULL, '《剑吼西风：中央特科纪事》（以下简称《剑吼西风》）出自中共党史专家、中共隐蔽战线史学者叶孝慎之手。在接受《中国科学报》采访时，叶孝慎表示：“这是一本说‘不’的书。也许有人会认为这是我的自大，但我还是要说，我对大多在我之前以五花八门名义来解读中央特科的语言', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2021.002167', '项英');
INSERT INTO `ds_article` VALUES (1042, '报纸', '第二集 共赴国难', '', '光明日报', '光明日报', NULL, '1931年九一八事变后，日本帝国主义加快了侵略中国的步伐。日本军方制订了《1935年度对华作战计划》、1936年日本政府制订了《国防方针》和《用兵纲领》、日本中国驻屯军司令部制订了《1936年度华北占领地区统治计划书》，这些机密文件显示其早就确定了侵占全中国的', '2015-08-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB6ufAhzLXwgwXEUH_QqzD6MpCI2XwLphFeILksiMQugNleZbJ0wIIcHUKbFdNJk1tjpr_SqbR5ZfRwyhtO77ExVikJEzWgIPs5LgzqooFxzpYTv9AdRr4SsBaT0m31ePSGeRnCjMRJd8jODtra-y5mFlrC4ovKMuB4a_Z3jUW4pXxxOl9YXXgtH&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1044, '报纸', '既要经济发展 又要青山绿水', '何伟', '经济日报', '经济日报', NULL, '编者按“绿树村边合，青山郭外斜。”一个个乡村如璀璨明珠镶嵌在皖南大地上。安徽省宣城市大力实施生态文明村建设和城乡一体化发展战略，全力推进美好乡村建设；与此同时，宣城经济保持高速发展，2012年实现地区生产总值757.5亿元，同比增长12.6%，主要经济指标增幅均位于安', '2013-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB7EM_LU_6j4oV3HXBUZqR2i9MRyTftl1yEKBK2W1E_G5k7y20ZhSQfV16BxDvO1ENib35oTPE_HFhY5qCgoffIj2HhaAgas89jM5uEcf5GuTTkkPFqdPjjjDAanVW-QHa9O9tCKosvt5_Fi72JHTJ580DPLDavTKoMePBKaRpa-tNtgDYd60xau&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1046, '报纸', '宪法：九鼎重器 百炼乃成', '白龙', '人民日报', '人民日报', NULL, '宪法，是治国安邦总章程，是公民权利的宣言书。中国共产党人的宪法追求和宪法实践，从革命根据地时期贯穿到当代，不乏坎坷曲折，勾画出几代人的不懈努力。　　　54宪法　开创新篇　　　1953年1月13日，中央人民政府委员会举行第二十次会议，正式作出《关于召开全国人', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB5x5cSBaNkeNAn878UliIzHKltoqrOrCrGI9e7cst4pXESVQrNdH0FDR57VC7COrJ2fUeuuB9HeE0gwSVK0VlMe8ag1DiEHTMJru3DzRoU28DG7NGYTBTP_YUs5Pi7i-jBcfEgTQt1ShJ8tS7SeEZvNNHol0JElPIrO42nJUxS26Z6Sih-TN9TG&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1048, '报纸', '寂静的辅德里', '欧阳浩', '解放军报', '解放军报', NULL, '开车走上海延安路高架桥，在经过老成都北路时，原本平直的道路突然绕行了一个小弯。向外俯看，能看到一处典型的石库门建筑。这就是位于上海原南成都路辅德里625号的中共二大会址纪念馆。　1922年7月16日至23日，中国共产党第二次全国代表大会就在这里举行。虽然距离党的', '2011-05-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB7nAtODK15wTYQqvjNByjAs9P9ccCbyiojqDaX4giiDTGFCd1Pn9XEsC9Sp01S8ef5RVG2S-TD1P6SCfVZjRXXzUuteGwBQhbJTnHLa7c9grtYnfacafISgHZ9tZjRyx3P48lQWHgOu4wEFeSQXNlfoQGPjLSA6hbCd1oKlpbFd5bysq3JMIMWB&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1050, '报纸', '“二七烈士”林祥谦', '', '人民日报', '人民日报', NULL, '新华社北京２月１４日电 在湖北汉口江岸车站，矗立着一尊昂首挺立的红色花岗岩雕像，雕像基座正面镌刻着“林祥谦烈士”５个金色大字。他就是１９２３年在“二七大罢工”中担任京汉铁路总工会江岸分会委员长的林祥谦，这里就是他当年英勇牺牲的地方。　　　林祥谦，１８', '2011-02-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB6epjb6oqWAu01imi_-stHwQfrSGMZcIkqEG2NcaAp_dW1QeLuN0Mmdn0ijC6HxSEPsktQbuU_H3uwpZPjVeunq7ERxYn4rN0ntntwQTT-WeFJ2s4IlFMQW2cLp7LiFD8L6PlTfP0PFb8db8i98ZcXsV_QXOVW5AkqQbMTzaCbQ5ugTOx1-vsmQ&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1053, '报纸', '项怀诚的三部曲:收钱、分钱、赚钱', '李一硕 ; 骆伟琼', '中国会计报', '中国会计报', NULL, '提起财政部原部长项怀诚，你会想到什么?他幼年时有数字恐惧症，但一堂课能写两篇作文，自己一篇，替同桌再写一篇。他有个名扬世界的表叔，中国两弹一星元勋杨嘉墀，那是他最初的偶像。他的第一份工作是研究俄汉机器翻译，成天对着一个有两三个房间那么大的家伙干瞪', '2010-04-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB6LvLyIhrdXZpPp2Cg2vYL0BKT8yHblBgHZTxh_A6_HYldLnuiq9M1mbiEJpOME-KOLFjqzCz0hT5-hKzDL6W_wjJGivN58emN3oG75EzUcbD9m9Hu0eLONu6mD3oanWIHiCMHAhhlNoJfrsHJ-klOl9GkxMenXDLggyhqSqjh1Tg==&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1055, '报纸', '美16家情报机构锁定中国', '章名岂', '中国国防报', '中国国防报', NULL, '据美国《华盛顿时报》专栏《五角圈内》(暗指五角大楼)报道，日前，美军太平洋总部司令基廷在香港表示，尽管美情报部门已经将中国军力作为情报搜集的重点，但是他依然对缺乏有关中国军力的战略性情报感到十分担忧。分析人士指出，近年来，随着中国综合国力的快速增', '2009-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB6RM8cZWkXpZxRiKXCytc05EZuqyJqCxYbdzkYYKNGkc65EoyGmhcja3tRP4s1Cu6iGLiqjs0zi3ZWqeIPWKqYx1C3LR-mnclXnGF5IjslIjFpDxhc4IlFsl8euudNQnc29TYxRqQYxL2ArMOws-G9KJH8rXpIDY8HJTkygPqgwsA==&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1062, '报纸', '京汉铁路工人大罢工', '', '人民日报', '人民日报', NULL, '党的二大之后，党成立了领导工人运动的中国劳动组合书记部。从１９２２年１月到１９２３年２月，掀起了中国工人运动的第一个高潮。在持续１３个月的时间里，全国发生大小罢工１００余次，参加人数达到了３０万以上。其中，京汉铁路工人大罢工上演了最为壮烈的一幕。　　', '2006-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB7ynDEXw6swCLVjw0r0YhpzrH7lMtKyRk4CMZ_2CXHF8WDGgtrlRtOPrWGXl96oojaqE6ZcZko02RlhYIvWC6wJghLa_xrQCyTLt78OF-2P-nYb0Irr3IigCg9g-rQBAC1VIJC_uVWKVTmghF4r3HmMDFiKISvmSQ-YG9XJLvC34w==&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1063, '报纸', '党的五大', '', '人民日报', '人民日报', NULL, '１９２７年蒋介石发动“四一二”反革命政变，大肆屠杀共产党人和革命群众，大革命遭到了局部的严重失败。此后，全国形成了三个政权，即原来的北洋军阀政府，上海、南京的蒋介石反革命政权和武汉国民政府。面对错综复杂的矛盾和尖锐激烈的斗争，需要中国共产党对形势有清醒的', '2006-05-26 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2006.018164', '项英,项英');
INSERT INTO `ds_article` VALUES (1065, '报纸', '毛泽东税收思想初探', '', '中国财经报', '中国财经报', NULL, '编者按：毛泽东是中国也是世界历史上一位伟大的革命 者。他不仅是一位杰出的政治家、军事家、思想家，同时 在经济、财政、税收理论方面也有着许多重大建树。本 文对毛泽东早期，即第一、二次国内革命战争时期的税 收思想作了初步探讨，使读者', '2004-02-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB7kXs5V4iYa3Lh7pcxpSO5QbbbrIy2lOPcI0On1s0NjehNYxWUdeRWz0vMH3GPb9V5ttNrirr54VQQ2DVtAAG1qOyl9WQudjUH8XUSC-2VMQ2bWA5fzcSzzu5PsZTXDtS0tvLFQEjutI620KIrZvTs39AKfgm4MqHv5SKU0CdpPFQ==&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1067, '报纸', '《新四军》亮相荧屏', '倪敏', '中国消费者报', '中国消费者报', NULL, '近日，26集电视连续剧《新四军》 将在中央电视台一套黄金时段隆重开 播，这部安徽省委宣传部、中央电视台 影视部、安徽电视台联合摄制的重点 剧目，是我国第一部全景式展现新四 军波澜壮阔战斗历程的电视剧，完整、 生动地再现了叶挺、项英、', '2003-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB4awTDRI_IMovvnRrH47f_DBo9yy9kUjWrHLFJJSoUArFTzk0npgXPZtdAZg6ZqqSQfApqC4tOZ_Z_I-mySdPCqoAB4gW7oSQruDSnoKpGLzHGyhv_E-IjBm2dnLxN1eNlpjMjUAN8L0yA5vYlj4SSD0VOFIJs6Lx6Z8QimUEzJUQ==&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1068, '报纸', '毛泽东的生日', '李南俊', '人民政协报', '人民政协报', NULL, '凡在旧社会出生的人，一般 都以农历来记自己的生日。毛泽 东的生日，《韶山四修族谱》卷十 五记载：“清光绪十九年癸已十 一月十九辰时生”。新中国成立 后，叶子龙等毛泽东身边的工作 人员，将公历与农历对照，核定 毛泽东生日为公历189', '2002-12-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB6e8nZdvyWuuON84wj6Z1tas5v-Lyj-mqlLx4ZuTtaibZZkKXYwFEYGhsGZnmdpHf-4ixF2fPTKO3MXn5khHZ98vHSIJTTuI4BBPctKPlowJLefIqZdKa1lW4K91419EP4-5ynlEn3gRZXYemURkM68xcU2UJCjiyQ-oKyHVCZH9w==&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1071, '报纸', '阅尽沧桑志凌云', '曲志红; 沈路涛; 李术峰', '新华社;', '新华每日电讯', NULL, '80年征程浓缩在5300平 方米的长廊中──血火的战 争、曲折的探索、辉煌的成 就……中国共产党追求真理、 艰苦奋斗的史页让我们历历阅 尽；80年征程呈现在1500多', '2001-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB7EHdeltmR8pMpSG6mDVpgwT7TsaGZb2zWTZVQz9N3DkAEjMUGW4sOw0jYrll6YR_MnNoCKcn9Hu4hT0xwHejLngvoNf83Cm6zRVKUBb9dSohcWBxtsSYt8Es1GpUZ4a1h7I_U7x5n9-x9gex0y6-q7lsL6iyVLZQgVEW7-MvjvRQ==&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1072, '报纸', '抚今追昔读云岭', '蔡小伟', '人民日报', '人民日报', NULL, '安徽省泾县的云岭是新四军军部旧址，是中国 近代革命史上的重要遗迹之一。6月初的一天，记者随众多的景仰者，来到这一 被青山绿水环抱着的全国爱国主义教育基地。阳光穿透晨雾，洒在皖南的山山水水。新四军军 部旧址纪念馆1万平方米', '2001-06-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=i_LPdPvRpB65tbI2XuP4XRR8QU88nbpDG0n5vTvS4HG-SIPS4Uu4nVI9NY8id6vTRjPV_HSGEUyDwFf8ugXuADopsCrxw2d3_F05dNWakknVQYHTWUoT7KT8vZ0B4RDgxV__3AKk8S48wDgLr3KZRf5NUP1oIgWd7u_AGb4WCb8tdmnL1UQbdQ==&uniplatform=NZKPT&language=CHS', '项英');
INSERT INTO `ds_article` VALUES (1075, '报纸', '赣鄱巾帼心向党 团结奋进新征程', '', '中国妇女报', '中国妇女报', '妇联组织;妇女儿童权益;维权工作;“两纲”;家庭教育指导;全面从严治党;全国妇联;江西省;中国式现代化;习近平总书记;', '江西是一片充满红色记忆的红土地，一山一水都留下了革命先烈的战斗足迹，一草一木都记载着可歌可泣的信仰故事。 作为党开展妇女工作起步的地方，无论过去、现在还是将来，无论时代怎样变迁，伟大的井冈山精神、苏区精神和长征精神永远是弥足珍贵的精神财富，始终激励着赣鄱', '2023-09-11 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2023.002591', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1077, '报纸', '以法之名护英烈', '瞿芃', '中国纪检监察报', '中国纪检监察报', '烈士褒扬;烈士事迹;以法之名;民事公益诉讼;保护法;爱国主义精神;', '“五一”前夕的福建龙岩天气多变，在被誉为“中国工农红军长征第一村”的长汀县中复村，60岁的讲解员钟鸣仍旧保持着每天12场次的工作节奏。 “1934年秋，中央红九军团在这里与国民党军队展开了7天7夜的松毛岭阻击战。当年9月30日，红九军团在观寿公祠举行誓师大会，开始了二', '2023-04-29 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.001621', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1086, '报纸', '一路风景一路课堂一路希望', '罗双奇; 孙绍建', '中国国防报', '中国国防报', '红军烈士陵园;川陕革命根据地;王坪村;隧道洞门;', '“高速通了，从通江县城到沙溪镇王坪村川陕革命根据地红军烈士陵园车程由90分钟缩短至20分钟。今年参观人次至少增加三至五成。”看着纷至沓来的参观者，川陕苏区纪念馆副馆长李坤容满脸欣然。 “路通了，村里的农副产品不愁运不出去，24家农家乐、民宿、商店生意也更好了，', '2022-04-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MiJOPyMjuIfBEjMlzRXVcs-IRJc23bh87oNbtEw_yfGrsCJ2d_BXOhz2KPOEndF5MkR3JINbxuBLqQxjYUpp66ydUic9YaVb1KtE_umKHN6s099MgQblxdbMwaC7ervc0qXkvyi2ohZQ==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1116, '报纸', '传承发扬革命先驱梁柏台的崇高精神 扎实走好新时代人民检察事业新的长征路', '张军', '最高人民检察院;', '检察日报', '梁柏台;人民检察事业;司法检察;革命先驱;传承发扬;长征路;', '梁柏台同志1899年9月生于浙江省新昌县，1920年加入社会主义青年团，1922年底在莫斯科东方大学转为中国共产党党员。1924年毕业后，长期在苏联远东地区从事华工革命运动。1931年秘密回国参加国内革命斗争。毛泽东同志任主席的中华苏维埃共和国临时中央政府成立后，梁柏台同志一', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.003745', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1121, '报纸', '在新的历史时期继续弘扬伟大的苏区精神', '罗雪梅', '江西省赣州市委党校;', '中国妇女报', '苏区精神;历史时期;治党治国;', '经历大革命惨痛失败后，中国共产党人在严酷的形势下，进行了创建根据地、开展苏维埃革命的伟大斗争，并建立了中国历史上第一个全国性的工农民主政权——中华苏维埃共和国临时中央政府,谱写了中国共产党领导的革命根据地建设和红色政权建设的新篇章。苏区时期是党建设红色', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.001837', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1124, '报纸', '赓续苏区干部好作风', '刘宗炎; 郭冬明', '解放军报', '解放军报', '军分区;苏区干部好作风;兴国县;', '盛夏时节，在江西省兴国县长冈乡长冈村广场一侧的工地上，搅拌机轰鸣，工人们忙碌，一片热火朝天的景象。“这是军分区今年助力长冈村‘红色名村’建设，正在修建的集党建培训、党性教育等功能于一体的‘政治生活馆’，下一步还将配套完善党建广场、党建长廊，打造村级党', '2021-07-26 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004751', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1129, '报纸', '管好河湖 造福人民', '吴頔', '中国水利报', '中国水利报', '幸福河;水利部;河湖管理;河长制;水利委员会;', '江河湖泊是生命的源泉、民族的血脉、文明的摇篮。管理好河湖，正是百年来中国共产党为人民谋幸福、为民族谋复兴的重要使命和伟大实践。“一切水利、江河湖溪、森林牧场、大山林，由苏维埃管理。”这是1931年中华苏维埃第一次全国代表大会通过的《中华苏维埃共和国土地法', '2021-07-14 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2021.001142', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1133, '报纸', '湘南特别法庭：审判土豪劣绅 捍卫红色政权', '盖峰', '人民法院报', '人民法院报', '宜章县;特别法庭;红色政权;苏维埃政府;', '点睛1924年1月，国共合作的实现，不仅促进了工人运动的高涨，也推动了农民运动的开展。海陆丰农民运动带起了全国农民运动的旋风。1926年7月，北伐战争胜利进军，进一步推动了全国农民运动的蓬勃发展，中央农委决定以湖南、湖北、江西、河南四省农民运动为重点，同时在陕', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003027', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1143, '报纸', '一面青砖墙，浓浓鱼水情', '马原', '人民日报', '人民日报', '人民至上;鄂豫皖苏区;', '坚持人民至上、紧紧依靠人民、不断造福人民、牢牢植根人民，党才能不断发展壮大；始终与人民心心相印、同甘共苦、团结奋斗，党才能永葆生机活力在河南新县鄂豫皖苏区首府革命博物馆，有一面青砖墙，墙上刻着《中华苏维埃共和国土地法》，现为国家一级文物。由于年代久远', '2021-06-24 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006653', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1150, '报纸', '毛泽民：坚贞不屈的“红色大管家”', '帅才', '人民日报', '人民日报', '毛泽民;陈潭秋;大管家;', '新华社电 （记者帅才）在韶山冲景区，游人如织，走进毛泽东同志故居，游客们认真倾听讲解员讲述当年那段故事——毛泽东坐在灶屋里的火塘边，给大弟弟毛泽民、小弟弟毛泽覃以及堂妹毛泽建讲述革命道理。在韶山，毛泽民等烈士的故事广为人知。毛泽民，1896年生，湖南湘潭', '2019-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MfpCM-xgn75OWIMZuqOxZZeOUd23QSATFhqjEknrmNJZIeZ2pxlLqhTP7sxPlJxM49ORyU_GY5hlhdv3tDt-vdvUf4tsPMcCcfK1NT8BrkN1r6MxWig1fR95EnWL3LIdl7dLrdmdE2cw==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1159, '报纸', '夜访群众 写就《才溪乡调查》', '马跃华; 林斯乾', '光明日报', '光明日报', '才溪乡;毛泽东;《才溪乡调查》;', '来到毛泽东才溪乡调查纪念馆，纪念馆前的几个红色大字夺人眼球——“没有调查就没有发言权”。站在毛泽东的蜡像前，毛泽东才溪乡调查纪念馆馆长陈春连介绍说，1930年5月，毛泽东为了反对当时红军中存在的教条主义思想，专门写了《反对本本主义》一文，提出“没有调查，', '2014-06-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M-zsir2Iydqwj1qgwchmpjQSzb8dZnwuIYMLrfyl2rKW4aWdCdrP1esfK3HcmkO1reJnFVhz1pNMhSapeZz74S5j_i4N4rZ8-q8b3cKACG3paMMvyE_E_i7G0akwmpBxSdOdJqnpfukg==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1160, '报纸', '加快出台《川陕革命老区发展振兴规划》', '王菲', '全国人大;', '人民政协报', '川陕革命老区;《川陕革命老区发展振兴规划》;川陕苏区;', '川陕革命老区（原川陕苏区）是中华苏维埃共和国的第二大区域，革命年代共有20多万人参加红军，牺牲的在册革命烈士达9万多人，对中国革命胜利作出了重大贡献。近年来，川陕革命老区经济社会得到了较快发展，但由于地域条件限制、发展基础薄弱等原因，与全国平均水平相比，该地', '2014-04-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MHEKdg9NvaGbYRMd3aXg_3oeCKea_M8zSQYydCxK1HOtyry4BFAKlrMiIvFCGPQ8mQpgqyez1sOaOC-VvfR-_WCyMziF9LPPFM6N7L7Ze34ctg73Tj5ELe56ThpTtwpxm1F_mqzwIPZg==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1175, '报纸', '不应被遗忘的川陕苏维埃工农银行', '杨洋 ; 别凌 ; 周杨 ; 夏翰', '金融时报', '金融时报', '川陕苏区;川陕革命根据地;', '“那批机器就埋藏在太阳落山的地方。”在过去70多年时间中，不断有人按照这条线索去寻找传说中的川陕省苏维埃政府工农银行制造货币的机器，却一次次无功而返，但是82岁的程自珍却从不怀疑这则传言的真实性。1932年10月，中国工农红军第四方面军撤离鄂豫皖苏区，转', '2011-06-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OKMS8gS9Odk8vI3j_TYMgV1lUI5wIxC-IizLM1Dl_UrKV4qgk6PsgPdNE9y78hbW51f_OvDoMgVXtF8MlN46J3QiTX3ZnaKxZGgxpOprT4jvq51YNA1NI1gvqAUxemwEQNOvgAALrQjA==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1178, '报纸', '为人民司法 须立足本职', '王敬波', '中国政法大学法治政府研究院;', '人民日报', '司法;法官;法律工作者;法院;', '人民性是中国特色社会主义司法制度的本质属性，为人民司法是中国司法制度的优良传统，从江西苏区成立中华苏维埃共和国临时最高法庭，到新中国最高人民法院成立；从提倡马锡五审判方式，到当前全国各级人民法院广泛开展的“人民法官为人民”活动，为人民司法的优良传统不断发', '2011-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PUUvVzyzKhpHByNiV9UtU6Z4vr_YX353sE82_qK9HyiSG6BVvRclZTsZ72mEOFQ7Vb-PVOyxJXX-syxKaTPcIH4uxC6ECo5hyjeHVG413q9OS1PAOaOME9qBGK7ftpkV1y42WdWlZzTg==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1183, '报纸', '红军高级指挥员 段德昌', '', '人民日报', '人民日报', '段德昌;指挥员;', '据新华社北京５月２日电　段德昌是中国工农红军高级指挥员、军事家。１９０４年８月出生于湖南南洲（今南县）九都山九屋厂。１９２２年入长沙雅各中学读书，参与组织马克思主义学习小组，进行爱国学生运动。１９２４年和何长工一起在华容创办新华中学，传播进步思想。１９２', '2011-05-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PXhhDbPSzXJsInD2eqofRZuTLVV3dVPRbI7UR10MXyK-i8qd2NRhyYS4JZBllgF1IbKb6GGtC4mpOaH6fuUdV5g7pb6P865cei2ubTGAotnoQtCVhqFQlgoP1VKAIKeAOs0-kj7WqU6Q==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1186, '报纸', '坚持群众路线 满足司法需求', '张忠厚', '江西省高级人民法院;', '人民法院报', '司法需求;', '江西是革命老区，是共和国的摇篮，是人民司法的发祥地。早在中央苏区时期，我党就在江西建立了中国革命史上最早的人民司法审判机关——中华苏维埃共和国最高法院和最高法庭，开展了具有工农民主性质，维护广大工农兵劳苦群众利益，保障新生红色革命政权的人民司法审判工作。', '2011-04-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PTn26E3VX-_gmCjJJXtIJQCgSXXTkMPHTJiFr3XlTWEE5MTMEytvW_8go7dverVjI1_9w8zxypziEkGQxJjpYJUT_2JYcmwHOYCcYLgp9Qsjzg8zJmvyTSKr-lPFQhoCC094BCnctaWA==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1188, '报纸', '生是为中国 死是为中国 刘伯坚', '', '人民日报', '人民日报', '刘伯坚;冯玉祥;中革军委;', '据新华社北京３月２０日电　刘伯坚，１８９５年１月生于四川省平昌县，早年曾就读于川东高等师范学校、成都高等师范学堂。１９２０年赴欧洲勤工俭学，先后在法国、比利时一边做工一边学习。这期间，他阅读了大量马克思主义经典著作，认真研究俄国十月革命经验。１', '2011-03-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O1TT2UBgHtCaH8LSRGvZnDFEY7ApmzZIzVGJ7LxYGMs7BqmDShOuIz7KRKpojgiVSOx8wywaxom_VZKZBJGoVzPlduBBkfVcp2bF8KzQopqJIsCywiHLSbdfM3tjktseTnceCo8s1JXw==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1190, '报纸', '中国共产党的创始人之一何叔衡', '', '人民日报', '人民日报', '何叔衡;中国共产党;中央革命根据地;创始人;', '新华社北京２月２３日电 今年２月２４日，是革命长者何叔衡壮烈牺牲７６周年纪念日。何叔衡，１８７６年出生，湖南省宁乡县人。１９０２年考中秀才。县衙请他去担任主管钱粮的官吏，他激愤于衙门腐败，甘愿在家种田、教私塾，乡里人称“穷秀才”。１９１３年考入湖南省', '2011-02-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OJc12yilQt84OWiGvR7NUyUruEpJmYd4HD4fSfDBCLYV3fjyNMrK23t4FFqk_jNc3IMPhdiljv5M60HZ8dGKHfCO_0DsDynom0PpGLA-2zWvTn0sD2VlmtzAIgNtTLrI3o_4oj4vqy4g==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1194, '报纸', '科技的繁荣需要灵魂的支持', '寇勇', '科技日报', '科技日报', '学术不端行为;杜祥琬;', '本报赣州3月28日电 （记者寇勇）“科技的繁荣需要灵魂的支持，这个灵魂就是科学精神、科学道德和良好的学风！”在今天举办的“弘扬苏区精神、倡导科学道德”论坛上，中国工程院副院长杜祥琬院士的话掷地有声，引起了与会者的强烈共鸣。本次论坛由中国科协会同江西', '2010-03-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NeISG8WTOIN1ZEy3d2w8N2CnLY59yR2Mg8Y8Cr9W4J0rFR_EeWFbeZ6KMKNrClHTv51UurqC-xoAY5JSukWVgSby1OxDxmr_8811omiabmeX2BzGpoi7O3CrFiXbAl14FsGP4qmWUQNw==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1197, '报纸', '赣州法院:老区司法传统在这里光大', '陈文春; 肖建国', '人民法院报', '人民法院报', '司法传统;', '阅读提示 赣州是人民司法的发祥地。早在1932年，中央苏区就在赣南先后成立了中华苏维埃共和国临时最高法庭、最高法院。如今，人民司法优良传统在赣南老区不断传承和发扬光大。近年来，赣州市两级法院确立“队伍素质高，保障水平高；先进模范多，调研成果多；涉诉信', '2009-08-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OGDjMV0utGPTnPWiPRKVU_QRmqtKWPGDk__9LKJhLse-W-yBMNbCdmOmEiN4SPSvbKZxa4-c0h7kOnUVQSwkjEKupG2UZGlut3n_vTglnJyUTF7Lm9a-KIzC1hpCadlA97QE1kDJqyqQ==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1202, '报纸', '永远的雕像', '孙继炼 ; 宋歆 ; 赵伍芳; 谭建军', '解放军报', '解放军报', '湘鄂川黔革命根据地;永顺县;红二、六军团;湘西攻势;', '湖南省湘西自治州永顺县，伏垣于延绵不绝的武陵山脉深处，是土家族的发源地以及历史上土家王朝——老司城的所在地。其人口绝大部分是土家族后裔，有着独特的“巴人文化”。 战争年代，这里一望无际的高山密林，是红军打游击、建根据地的上佳之处。第二次国内革命战', '2009-04-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OIAEfm2PZHBQ8tcRmWVmWVmZI01Qryi3bQHRG1YpjoIFpNjk4rosOnR-7UJlKHjh0g_poRdRIScKTYdT5BulWx8BC5jeBgdzwEVOGoHT246HpMNY153vPLpsdYcF1bLIIGL5ayujH1gw==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1204, '报纸', '“八一”建军节的确定(上)', '', '人民日报', '人民日报', '中国工农红军;中央革命军事委员会;中华苏维埃共和国临时中央政府;', '１９３３年６月，中共中央、中央革命军事委员会向中华苏维埃共和国临时中央政府建议，以南昌起义日——８月１日为中国工农红军成立纪念日，每年的８月１日开展纪念活动。中央政府同意这一建议，并决定在红军成立纪念日期间，开展拥军优属活动。$$６月３０日，中央革', '2007-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O9gzYaq46pO3PGgdL_4fBWmquLY48CJbr9wKjWcV6paRvQJkKmbTx-0uC4yHUKZK4iAdNA2FTWRVlqnfJ7YoCYwfv7GDiolNzLCIdycLbWnRald9I0Y349odwIWsx0SFoloXqURX-eSg==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1207, '报纸', '阮啸仙与人民审计制度的建立', '', '人民日报', '人民日报', '审计制度;阮啸仙;临时中央政府;', '中国共产党领导下的人民政府审计制度，始建于第二次国内革命战争时期。１９３１年１１月，中华苏维埃共和国正式成立后，临时中央政府（人民委员会）注意到革命根据地没有明确统一的财政经济政策，地方各级苏维埃政府和各部队缺乏财政统一观念，普遍没有建立预算、决算制度，', '2007-02-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MuqTEVLOxj-mridwPhh-ofmJk8puW7nsVgVU7bGyJ8vHM80oBb1CMpiOIJ8qpmYSZIfPeLaMA1I0q-fZmqm-ar9iLsv4OQDPXNs64xLKHsIberkb_Zx3D_qpoaQLUdv2fOAu8g2dE91g==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1221, '报纸', '巍巍宝塔作证', '雷和平; 严李锁', '金融时报', '金融时报', '延安市;陕甘宁边区银行;中华苏维埃共和国国家银行;金融工作者;', '“七一”前的一个早晨，记者来到了延安市场沟。 这里已经是高楼林立、车水马龙。历经60多年的风霜雨雪，气势宏伟的陕甘宁边区银行大楼仍然在这里屹立着，像一座无言的丰碑，默默地向人们展示着以往的辉煌。 1935年11月下旬，随中央红军长征到达陕北的中', '2006-07-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O7JxzGnCK0QT_IjI5nwYEOEdb18irF2x7GobBxVne0xJOfEDAanLAOa4Je0Tel29uZLZ7bM7MOHhmXG8gAzrxjrL2QuVnnNibEMpkv2LozeHY9pc3PbjkaKUfNL1jSHMZg4Oe4F_QkYQ==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1226, '报纸', '张正坤', '', '人民日报', '人民日报', '红军大学;中央苏区;', '张正坤,1898年出生于湖南省浏阳县。1926年10月加入中国共产党。1927年马日事变后,参加十万农军围攻长沙的战斗,1929年冬参加党领导的游击队,1930年任游击队浏北第一支队支队长,后任浏阳赤卫军特务连连长。1931年3月,任湘鄂赣红军独立第一师三营营长。1933年初,任红十八军一五', '2006-04-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OBJuszIsSvTpGFpbuJhNodw6mpx5tjTQOSzfOj4c5WzDBQbV5T9YiHtZat_sn6D7GLhGFgrTritqWIti8VISaeNEK7NX3c2yC8I1K2IDZNdxmeHutYOjqeuQpA_Ee0IDCiRbKbVls5ig==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1227, '报纸', '邓萍', '', '人民日报', '人民日报', '平江起义;中央苏区;彭德怀;', '长期与邓萍一起战斗过的彭德怀曾深情地追忆道：“从平江起义到井冈山斗争,从江西苏区转战到长征途中,直到他牺牲前,我们一直在一起工作,互相配合得很好。邓萍对党和人民的革命事业忠心耿耿,作战指挥沉着果断、英勇顽强,是一个很有才干的优秀军事干部。”并强调说：“邓萍这个', '2006-03-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P36QOntDvuzpqvq2I4oHxbQLoxo-UNELA15_oRKdI0d3znSBzczT-L1VV4FHJYmEXc1Up7OKOAao8JEPgghREHUHgRKy2re61Tb0c2kaicUhlVh4V572kXMIGZDRz1gS4jPSqeTgEHQQ==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1228, '报纸', '陈寿昌', '', '人民日报', '人民日报', '陈寿昌;中央革命根据地;工人运动;', '陈寿昌，1906年10月出生于浙江镇海。1922年，陈寿昌离开家乡先后来到武汉、郑州，进入郑州电报局做工。1923年二七大罢工开始后，陈寿昌积极参加组织郑州电报局职工声援铁路工人的斗争。二七惨案后，工人运动转入低潮，陈寿昌从郑州转到武汉电报局从事工人运动，坚持革命斗争', '2006-03-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NEEVQmhI7ZLLyw4nmtRq996sNgPAsaRBeoPdhfthOQt1voNLPaUPDv6IP9Kde6CRTjGZYzqgMRPtdwld8CNa9R-E6DgcVQ-64CyWCKGR2WrNB5-YVGEgvRddFnbSkdz1bg8czpbmfImQ==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1229, '报纸', '郭滴人', '', '人民日报', '人民日报', '郭滴人;龙岩县;', '郭滴人是闽西红军和苏区创建人。1907年生，福建龙岩人。1923年入厦门集美学校读书，参加过进步学生运动。1926年春赴广州，入毛泽东主办的第六届农民运动讲习所学习，6月加入中国共产党。同年9月结业后，随北伐东路军回到龙岩，秘密建立中共基层组织，先后任中共龙岩县党总支', '2006-02-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Me37PLqa39m27yrHeeb1eDIMwxepjvKyywCqO2h5hMZ-7f-69P7LedXlOY8pPh-lNyFr_W7Vry5l-uynOTYZQhp4Ir2M1YAmuKRzGQ_dkfBkO74W5p25UIGX6owXY5c06tKESoUSWtsg==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1235, '报纸', '我国工人运动的著名领袖之一邓发', '', '人民日报', '人民日报', '工人运动;', '邓发是我国工人运动的著名领袖之一。1906年生，广东省云浮县人。由于家境贫寒，早年到香港做工。受苏兆征的影响，参加了海员工会和洋务工会。1922年参加香港海员大罢工，1925年参加省港大罢工，任工人纠察队队长。同年10月加入中国共产党。后参加北伐战争。1927年春任中共广', '2005-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NHpxEdfAkB3Gu8yUFwqtCsAiJpr9QEhQMXaA0AWV9KaIFJ3Sac8MqqSglxzrml0S_Ejo5Etayj2R_WAyevO5ICiZmQa3JoOcDJO6MLrSA7CHQdQ45BCvQgjJ_wzRUBb0BUat2-_AMWqw==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1236, '报纸', '赣州中院：秉承传统 拥抱现代', '周迎飚; 郭复彬; 徐俊', '人民法院报', '人民法院报', '破产案件;', '“苏区干部好作风……”７０多年前，这首赣南山歌在中华苏维埃共和国的土地上广为传唱。着草鞋、走山路、访民众，苏区审判干部亲民、爱民的司法作风，深受百姓的欢迎和拥护，在共和国的审判史上书写了浓墨重彩的篇章。２００１年４月，最高人民法院院长肖扬踏上这片红', '2004-08-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MTs9xLyx4U0SBMkNp6VW8G6DWkMVzOHLwnQkbhztmyKVld-qfIZIy8R0jXgWvRN6CnWGZJBt4RNHwvROCB07a_DSFi7qK6D7HHhln_oeIh0dwPFVrUlHrh-s-oRsxo1XyUJgqWaFXz8Q==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1237, '报纸', '红色金融 走过风雨到辉煌', '雷和平; 雷国伟; 孙炜; 高延春', '金融时报', '金融时报', '陕甘宁边区银行;红色金融;中华苏维埃共和国国家银行;', '在一个七月流火的日子，记者来到了延安市场沟。历经63年的风霜雨雪，气势宏伟的陕甘宁边区银行大楼仍然屹立在这里，像一座无言的丰碑，默默地向人们展示着以往的辉煌。在中国现代金融史上，陕甘宁边区银行有着极其特殊的地位。她是中华苏维埃共和国国家银行的直接继承', '2004-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M5asHg-rDJpD4l0U_zrIrDMQwjADvNG3mu9P0Gbmad5vDIljmPVZD0syyLCaB521W6W2mDPQun2UO_9_S6ObMfWYreU3GXhfwu3qabadAkuNnQfaMwFkQ6FvXESiO8A77zueiutifWPw==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1250, '报纸', '永远与人民同呼吸共命运', '翟伟', '新华每日电讯', '新华每日电讯', '中央革命根据地;党的优良传统;中央党史研究室;中华苏维埃共和国;', '据新华社北京10月24日电（记 者翟伟）纪念中央革命根据地创建暨 中华苏维埃共和国临时中央政府成立 70周年座谈会今天在北京举行。中 共中央政治局常委、国家副主席、 中央军委副主席胡锦涛出席', '2001-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OnpDXGtE-JHK0HCHhJmLVbjDMCxVMGhILfCSM2-Z9eVLAaXzwXDnbGtJyHRguhXDIH1Fb_G7Q38N82lyN0BJ72f8fNwiD9mq8c-QPvH5wf3XsqjN4sGEBwkimKo-WtiwKCZ4j59UC99g==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1257, '报纸', '吉安发现中央苏区邮袋', '邹晓明; 蔡厚正', '新华每日电讯', '新华每日电讯', '中央苏区;中华苏维埃共和国;', '新华社南昌8月15日电（邹晓明 蔡厚正）一只印有 “中华苏维埃共和国中央邮政总局”印章和其他“赤色邮 政”标志的邮袋，最近在江西吉安市被发现。 这只邮袋通体呈纺锤形，系用苎麻织成的白色夏布布质。', '2000-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MaMxmduApzMFJl0Ja9YAnbZ5YfwKBnxi7n53SGw9QzTygKTCRRsOGyv0QbJ-eugwirmGj3wEMf5eABibiW1XlD7cXqTm4B8_hsPl9PQpEfbKz1LJFFchsKSn5DDAS4yDWj-mhXMrUaag==&uniplatform=NZKPT&language=CHS', '苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1258, '报纸', '长篇报告文学《赣红谣》用“情”给出答案', '孙海悦', '中国新闻出版广电报', '中国新闻出版广电报', '长篇报告文学;中央苏区文化;江西高校出版社;《赣红谣》;', '追忆红色苏区历史文化、描摹绿色乡村振兴图景，江西高校出版社长篇报告文学《赣红谣》展现中国共产党领导下赣南原中央苏区乡村振兴成果，擦亮了赣南原中央苏区文化名片。 作者深入赣南十八县走访 长篇报告文学《赣红谣》是中国作家协会会员凌翼“新时代革命老区长篇报告文', '2024-01-17 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2024.000119', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1261, '报纸', '文物“活”起来 红色“亮”起来', '潘聪; 刘航; 郭冬明', '解放军报', '解放军报', '革命文物;革命旧址;井冈山革命博物馆;文物保护;“活”起来;', '暑期来临，江西各地迎来红色旅游热潮。长征出发地于都，“共和国的摇篮”瑞金，“工人运动的摇篮”萍乡……广大游客通过参观博物馆里的文物、广袤大地上的旧址，了解革命历史、传承红色基因。 革命文物承载党和人民英勇奋斗的光荣历史，记载中国革命的伟大历程和感人事迹，', '2023-07-19 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2023.002606', '瑞金_screened,黄洋界_screened,井冈山革命博物馆_screened,秋收起义_screened,反围剿_screened,井冈山会师_screened,朱毛会师_screened');
INSERT INTO `ds_article` VALUES (1263, '报纸', '红土地高质量发展春潮涌', '张毅; 郑少忠; 刘维涛', '人民日报', '人民日报', '革命老区;赣州市;国际陆港;', '赣南，重峦叠嶂，满目葱茏，岭上开遍映山红。 红军长征出发地，江西赣州于都县，新落成的长征大剧院内，《长征第一渡》演出震撼人心。80多年前，飘扬的红旗，正是从这里出发，在大地上走出一条“红飘带”。 对这片英雄的土地，习近平总书记念兹在兹。2019年5月22日，在听取', '2023-05-09 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.004760', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1264, '报纸', '让红色基因“根”和“魂”代代相传', '朱宁宁', '法治日报', '法治日报', '红色基因;红色文化资源;红色旅游;红色资源;', '鉴往事，知来者。 4月6日，江西省于都县，蒙蒙细雨中，《法治日报》记者跟随全国人大常委会法工委英雄烈士保护法调研组一行来到位于于都河畔的中央红军长征出发纪念碑前。 不远处的渡口，正是八十九年前中央红军长征集结出发地。在于都人民的紧密配合下，86000多名红军将士', '2023-04-18 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2023.001986', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1268, '报纸', '福建长汀 “红色小上海” 再续传奇华章', '刘凡; 廖连明; 薛梦芳', '金融时报', '金融时报', '长汀县;水土流失治理;小上海;福建长汀;生态文明建设;闽西工农银行;绿水青山;湿地公园;林下经济;贷款余额;农信联社;习近平;生态旅游;', '福建长汀县史称汀州，是红军的故乡、红军长征出发地和原中央苏区的经济中心。1929年，红军打响入闽第一枪，解放了长汀城，揭开创建中央苏区的序幕。中共福建省委、省苏维埃政府、省军区先后在长汀成立，长汀成为福建苏区的政治、军事、经济中心，被誉为“红色小上海”。当年', '2022-09-13 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2022.005168', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1269, '报纸', '红色热土唱响鱼水欢歌', '刘宗炎; 付艳; 郭冬明', '中国国防报', '中国国防报', '红军精神;军分区;红色基因;赣州市委;退役军人;军转干部;赣南苏区;', '鱼水情深同大海，军民义重若长城。 江西赣州，是一方红色热土。这里是苏区精神的孕育和形成地，也是长征精神的发源地。战争年代，母送子、妻送郎、父子争相上战场的拥军支前故事催人泪下；和平时期，赣州军民赓续红色血脉，携手共画军政军民团结同心圆，让双拥之花在红土地', '2022-09-08 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2022.001679', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1271, '报纸', '寻找党章守护者张人亚', '顾小立', '新华每日电讯', '新华每日电讯', '共产党;中华苏维埃共和国;守护者;', '一种什么样的觉悟，让一位不到30岁的年轻人，遇到危险时首先想到的是党的文件的安全？ 一种什么样的信念，让一位老父亲几十年如一日保管好儿子托付的物品，甚至不惜编造“儿已亡故”的谎言？ 一种什么样的执着，让一个家族四代人用跨越大半个世纪的“接力”，走过大半个中', '2022-07-29 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.005709', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1272, '报纸', '盘活红绿资源 推动老区振兴', '叶辉圣; 周晨', '中国旅游报', '中国旅游报', '旅游点;主题公园;红色资源;长征精神;纪念园;红色旅游;赣南采茶戏;红色文化;苏区干部好作风;乡村旅游;', '“七一”前后，革命老区江西赣州客流明显增加，无论是红色景区景点，还是主题乐园、乡村旅游点等都实现了客流回升。赣州是原中央苏区，是长征出发地之一，拥有众多的革命遗址遗迹；赣州也是千里赣江源头、纵贯大湾区全境的东江源头，山水资源丰富，生态环境优越。 《国务院', '2022-07-05 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.001762', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1273, '报纸', '各地常态化开展党史学习教育', '', '经济日报', '经济日报', '党史学习;长效化;常态化;北大红楼;', '江西 红色基因代代传 本报记者 赖永峰 刘兴 七一前后，江西瑞金市“共和国摇篮”国家5A级景区人潮涌动，该市精心策划推出的“共和国寻根”“新长征溯源”“寻根红色中华、感受苏区振兴”等精品研学线路，连日来吸引了12万余名游客走进红色景区开展红色教育。“我们把革命遗', '2022-07-03 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2022.003927', '瑞金_screened,井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (1276, '报纸', '红井汩汩幸福来', '刘云', '农民日报;中国农网;', '农民日报', '沙洲坝镇;村集体;党总支;就业增收;全村党员;瑞金市;人才储备库;村“两委”;革命老区;', '盛夏时节，江西省瑞金市沙洲坝镇沙洲坝村古樟成荫，蝉声响动。沿着村里鹅卵石铺成的小路一直向前走，一口老井呈现眼前。井边，身着红军军装的讲解员在几名游客的簇拥中，将这口老井的故事娓娓道来—— “1933年，毛主席在江西领导革命的时候，在沙洲坝住过。见乡亲们吃水难', '2022-07-01 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2022.002428', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1277, '报纸', '真情润红土 携手促振兴', '胡晓军', '光明日报', '光明日报', '振兴发展;国家发改委;对口支援;赣南苏区;中央苏区;革命老区;', '编者按 今年是赣南等原中央苏区振兴发展战略实施十周年。十年来，在以习近平同志为核心的党中央关心关怀下，赣南等原中央苏区经济社会发展成就喜人—综合实力显著增强、产业发展量质齐升、城乡面貌日新月异、人民生活更加幸福…… 十年里，对口支援赣南等原中央苏区的中央', '2022-06-28 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.003008', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1278, '报纸', '江西：再出发，新征程上“赣”劲足', '陈希; 曾芳洲', '人民公安报', '人民公安报', '公安局;网上办事;习近平总书记;公安厅;富硒水稻;梓山镇;', '火红五月，赣鄱大地草木葱茏。晨曦下，于都河畔巍然耸立的中央红军长征出发纪念碑，形如双帆、迎风欲发。 “重整行装再出发!”遵循习近平总书记指引的方向，江西公安机关大力弘扬井冈山精神、苏区精神、长征精神，以感恩之心、担当之责，笃定前行、护航发展。如今，江西这片', '2022-06-17 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2022.003158', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1281, '报纸', '江西瑞金中央革命根据地纪念馆：让革命薪火生生不息', '王竹青; 刘俊林; 苏春生', '中国文化报', '中国文化报', '江西瑞金;中央革命根据地;', '江西瑞金中央革命根据地纪念馆管辖境内革命旧址120多处，是首批全国爱国主义教育示范基地、国家一级博物馆、全国红色旅游经典景区。近年来，该纪念馆充分发挥红色资源优势，树立践行融合创新发展理念，让革命文物融入红色旅游、融入百姓生活。2021年，瑞金中央革命根据地纪念', '2022-05-06 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.001247', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1283, '报纸', '对话《中央苏区青年运动史》修订编委会', '陈卓琼; 周围围', '中青报;中青网;', '中国青年报', '中央苏区;青年运动史;《中央苏区青年运动史》;编委会;', '中青报·中青网记者：为什么修订《中央苏区青年运动史》？请问编委会何时启动了《中央苏区青年运动史》重修编撰工作？对比2009年出的第一版，修订版主要对哪些内容进行了修订（增减）？ 编委会：《中央苏区青年运动史》原书于2009年出版，受历史条件所限，原书存在部分史料', '2022-04-28 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.001530', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1287, '报纸', '赣州：“苏区红+警察蓝”淬炼红土铁军', '陈希; 曾芳洲; 黄传钢', '人民公安报', '人民公安报', '赣州市;公安局;', '寒冬冷雨，在疫情防控卡点、在乡村、在路面、在企业园区，一道道“警察蓝”成为赣南大地的平安色。江西省赣州市公安局弘扬苏区好作风，以“苏区红”滋养公安职业“警察蓝”。“我们以党建带队建，以党务促警务，通过‘苏区红+警察蓝’双色融合育警机制，努力探索和实践新时代', '2022-01-24 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2022.000453', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1288, '报纸', '山高水长沂蒙红', '赵秋丽; 李志臣; 王珊珊', '光明日报', '光明日报', '沂蒙精神;临沂市;支部书记;山高水长;', '电影《长津湖》上映后，《沂蒙山小调》的优美旋律在电影院里一次次响起，也唱响了军民“水乳交融、生死与共”铸就的沂蒙精神。$$ 五千年沂河吟唱着历史长歌，八百里蒙山绵延着红色血脉。2013年11月，习近平总书记在山东临沂考察时指出：“沂蒙精神与延安精神、井冈山精神、', '2022-01-12 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.000179', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1289, '报纸', '“点绿成金”的江西经验', '马梅若', '金融时报', '金融时报', '金融业;试验区;碳中和;绿色金融;', '近百年前，江西这片土地曾上演过“敢叫日月换新天”的革命斗争——党领导下的人民军队在南昌诞生，全国第一块农村革命根据地在井冈山创建，工农民主专政的新型政权——中华苏维埃共和国在瑞金成立，“四破铁围奇中奇”在江西苏区演绎。革命星星之火自此燎原。$$ 如今，这里', '2021-12-30 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.006902', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1293, '报纸', '苏维埃政权的改造与苏区法制的变革', '张晓明', '九江学院法学院;', '人民法院报', '苏维埃政权;中国共产党;政权建设;', '毛泽东同志创建了井冈山革命根据地，为中国革命开辟了一条农村包围城市、武装夺取政权的新道路。地方苏维埃政权，是在各级党组织的领导下，广大工农群众进行革命暴动、推翻地主豪绅的反动统治而建立起来的。当然，中国苏维埃运动在模仿苏联模式的同时，也在推动用马克思主义', '2021-12-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NxF9GCtoa5dH9MtUJWhjiqlQg66Ze8dYHHDkuAjEmHIgaWsfvciSfue0PVTjAblzx7BCh-PdURZVGWb8vs2Heu-1sCxRIwwpnTB9tc2KPVzeSf1owl9kA1vG_ORCNLA6APAYwAMyRGBA==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1296, '报纸', '“水利是农业的命脉”暨中央苏区水利史学习研讨会在江西瑞金召开', '张元一; 谢元鉴', '中国水利报', '中国水利报', '中央苏区;水利史;研讨会;江西瑞金;', '本报讯（记者 张元一 通讯员 谢元鉴）11月27日至28日，“水利是农业的命脉”暨中央苏区水利史学习研讨会在江西省瑞金市举办。研讨会旨在贯彻落实习近平总书记“传承红色基因，赓续共产党人精神血脉”重要指示精神，持续推进党史学习教育，深入挖掘中央苏区水利文化，落实党和', '2021-12-01 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2021.001983', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1302, '报纸', '讲好红色故事 传承长征精神', '', '人民日报', '人民日报', '长征精神;贵州省;长征故事;红军长征;', '习近平总书记强调，不论我们的事业发展到哪一步，不论我们取得了多大成就，我们都要大力弘扬伟大长征精神，在新的长征路上继续奋勇前进。$$ 今年是红军长征胜利85周年。通过长征国家文化公园建设，整合长征沿线具有突出意义、重要影响、重大主题的文物和文化资源，对于充分', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011902', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1310, '报纸', '镌刻在石碑上的23179个名字', '杨悦; 郭冬明', '解放军报', '解放军报', '李才莲;兴国县;', '青山环绕的陵园，树木整齐排列，每一棵都如一位笔直挺立的卫士，守候在一块大理石墓碑旁。步入其中时，能看到斜坡上镶嵌着几个红色的大字——“中华烈士第一县”。$$ 紧跟着这几个大字，是数字“23179”，沉重而醒目。$$ 江西兴国县散葬烈士墓园，许多从老区走向革命之路、', '2021-11-08 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007008', '瑞金_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1314, '报纸', '梁柏台与中央苏区时期的劳动感化院', '薛永毅', '西安交通大学法学院;', '人民法院报', '劳动感化院;看守所;梁柏台;监狱制度;中央苏区时期;', '在中国共产党百年法治历史的坐标体系中，梁柏台无疑是一个绕不过去的关键人物：中国共产党早期的“红色法律专家”、《中华苏维埃共和国宪法大纲》的执笔人、人民法制和人民司法的开拓者和奠基人。在梁柏台短暂而辉煌的法制人生中，由他倡导并推动建立的以感化教育和劳动改造', '2021-11-05 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.004957', '瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1316, '报纸', '儒雅与壮烈：怀念瞿秋白', '涂洪长; 董建国', '新华每日电讯', '新华每日电讯', '瞿秋白;瞿秋白纪念馆;觅渡桥;', '这是一个革命者留给世界最后的形象：双手后置于背，目光平视于前，嘴角带着一丝从容的微笑。生命的尽头，对于他来说，只是“伟大的”休息。$$ 这是一个“才子”、“文人”脑海中最后的世界：“一切新的，斗争的，勇敢的都在前进。那么好的花朵，果子，那么清秀的山和水，那', '2021-10-29 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008346', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1319, '报纸', '清末民初江西是否铸造过银元？', '曹军新', '金融时报', '金融时报', '军政府;光绪元宝;清末民初;', '自1928年到1935年，中国共产党分别在井冈山、湘鄂西、鄂西北、湘鄂赣、鄂豫皖和江西瑞金建立了红色工农政权，曾短暂铸造和流通过多款式银元及银辅币，基本形成了江西苏区铸行过银币的共识。除此之外，江西在清末及民国初期究竟有没有铸造或代铸过银元的问题，在泉界和学界有', '2021-10-08 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.005189', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1321, '报纸', '让苏区精神绽放新时代光芒', '吴忠琼', '江西省委;赣州市委;', '学习时报', '苏区精神;新时代;苏区干部;苏区时期;', '苏区时期，在革命根据地的创建和发展中，在建立红色政权、探索革命道路的实践中，无数革命先辈用鲜血和生命铸就了苏区精神。苏区精神是中国共产党人革命精神链条中的重要一环，既蕴含了中国共产党人革命精神的共性，又显示了苏区时期的特色和个性，在党的精神宝库中占据重要', '2021-09-27 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001794', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1324, '报纸', '续红色家谱 让精神永存', '艾立民', '中国书刊发行业协会;', '中国新闻出版广电报', '出版工作者;中央印刷厂;新闻出版工作;出版界;', '瑞金，曾是中华苏维埃共和国临时中央政府的首都，也是举世闻名的中国工农红军二万五千里长征的出发地之一，因其特殊的历史地位享有“红色故都”“共和国的摇篮”的称誉。今天党中央和共和国的各部委几乎都可以在这儿找到他们的“根”。党的新闻出版管理机构——中华苏维埃中', '2021-09-14 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.003755', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1325, '报纸', '从《红星》报看早期军报如何宣传动员', '徐鹏; 贺敏', '学习时报', '学习时报', '《红星》;红军建设;宣传动员;', '《红星》报是中华苏维埃共和国中央革命军事委员会的机关报，也是党中央直接领导的全面指导红军建设的第一份军报。它于1931年12月11日在瑞金创刊，到1935年8月中央红军主力进入川陕甘地区终止出刊。在近4年的军事宣传实践中，《红星》报聚焦报道重大军事斗争，重视思想政治建', '2021-09-13 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001702', '瑞金_screened,苏维埃共和国_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (1326, '报纸', '走近红色资源的平凡守护者', '韩刚; 乔志强; 郭冬明', '解放军报', '解放军报', '红色资源;湘鄂赣革命根据地;红色基因;红色文物;守护者;', '写在前面$$ 江西是一片充满红色记忆的红土地，处处传颂着革命先烈可歌可泣的英雄故事。为讲好党的故事、革命的故事、根据地的故事、英雄和烈士的故事，近年来，江西军地充分调动社会各界参与保护红色资源的热情，引导民间力量参与红色资源的保护利用，让更多的红色资源成为', '2021-09-11 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.005922', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1328, '报纸', '中央苏区时期罗荣桓与扩红运动', '孙建猛', '湘潭大学马克思主义学院;', '团结报', '扩红运动;罗荣桓;中央苏区时期;', '中央苏区时期，罗荣桓在扩红运动中担任了一系列重要领导职务，为扩红运动的顺利开展奉献了大量的精力与智慧。在担任江西省军区政治部主任期间，罗荣桓亲赴一线领导扩红工作。在担任总政治部武装动员部部长期间，罗荣桓高度重视少先队和赤卫军的作用，并对其野营训练工作进行', '2021-08-05 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001588', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1332, '报纸', '江西：红色摇篮新奋斗', '赵珊', '人民日报海外版', '人民日报海外版', '红色摇篮;红色旅游;精品线路;秋收起义;油菜花;脐橙产业;鄱阳湖;', '江西是一片充满红色记忆的土地，红色是江西最亮的品牌，同时，江西又是全国最绿的省份之一，绿色是江西最大的优势。走进江西，处处是景，处处如画，红与绿相得益彰，交相辉映。$$ “建党百年红色旅游百条精品线路”中，江西共有5条红色精品线路入选，“井冈之路·星火燎原”', '2021-07-30 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002327', '瑞金_screened,秋收起义_screened');
INSERT INTO `ds_article` VALUES (1340, '报纸', '“我们都是苏区精神的传人”', '陈典宏; 黄海', '解放军报', '解放军报', '连队官兵;苏区精神;鄂豫皖苏区;红色文物;中央革命根据地;', '屏幕的这一边，是苏区精神的传播者——江西瑞金中央革命根据地纪念馆的工作人员。$$ 屏幕的另一边，是苏区精神的传承人——从鄂豫皖苏区走出的红军连队。$$ 盛夏七月，战炮轰鸣，野外驻训场一片火热。训练间隙，第74集团军某旅“红三连”一场别开生面的“追根溯源，连线红', '2021-07-26 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004752', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1344, '报纸', '赣州将红色旧址打造成法宣重要平台', '黄辉', '法治日报', '法治日报', '中华苏维埃共和国;司法人民委员部;司法行政工作;梁柏台;中央苏区;', '七月的赣南，山明水净，岁月凝香。$$ 在江西省赣州市瑞金沙洲坝红井景区核心区域，一幢幢黛瓦黄墙的庭院格外引人注目，中华苏维埃共和国司法人民委员部旧址便坐落其中。$$ 近年来，赣州市充分利用革命旧址优势，通过开展诵读红色家书及《八子参军》《信念的力量》红色故事', '2021-07-19 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2021.004011', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1345, '报纸', '正本清源铸铁军 今朝警营别样红', '谢俊思', '人民公安报', '人民公安报', '公安队伍;赣州市;教育整顿;公安局;公安机关;', '“踏遍青山人未老，风景这边独好。”1934年夏，毛泽东在赣南会昌写下《清平乐·会昌》。$$ 最近，记者在江西赣州走访市、县两级公安机关、基层派出所，深入企业、社区、街头、村落，采访第一批公安队伍教育整顿进展情况，时刻感到赣州公安队伍正进行着一次深刻的精神洗礼、', '2021-07-16 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003939', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1346, '报纸', '江西再探新路 让绿水青山“有价有市”', '马梅若; 廖斌; 谢文君', '金融时报', '金融时报', '林权抵押贷款;生态产品;绿水青山;抚州市;林地使用权;公益林;《金融时报》;天然商品林;', '遥想当年，中国共产党人凭借非凡的智慧、豪迈的斗志，在江西大地掀起了一场波澜壮阔的革命斗争：中国工人运动的策源地在安源形成，党领导下的人民军队在南昌诞生，全国第一块农村革命根据地在井冈山创建，工农民主专政的新型政权——中华苏维埃共和国在瑞金成立，“四破铁围', '2021-07-15 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.003591', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1347, '报纸', '革命老区的“红色旅游饭”端得稳前景阔', '崔立勇', '中国经济导报;', '中国经济导报', '红色旅游;龙岩市;长汀县;革命老区;', '“1934年9月，浴血奋战了七天七夜的红九军团将士在观寿公祠前举行誓师大会，告别乡亲，开始长征……”2021年的端午节，在福建省龙岩市长汀县南山镇，讲解员手指纪念石碑，向来自全国的游客讲述87年前中复村的革命故事。$$ 近年来，红色旅游的规模和热度不断攀升。人们游历红', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28095/n.cnki.ncjjd.2021.001658', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1349, '报纸', '数字化“扮靓”红色热土', '叶曜坤', '人民邮电', '人民邮电', '江西省;工业互联网;井冈山精神;', '习近平总书记指出：“井冈山是中国革命的摇篮。井冈山时期留给我们最为宝贵的财富，就是跨越时空的井冈山精神。今天，我们要结合新的时代条件，坚持坚定执着追理想、实事求是闯新路、艰苦奋斗攻难关、依靠群众求胜利，让井冈山精神放射出新的时代光芒。”$$ 井冈山位于湘赣', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28659/n.cnki.nrmyd.2021.002057', '瑞金_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1350, '报纸', '红色基因的检察传承', '邱春艳', '检察日报', '检察日报', '党中央;绝对领导;人民委员部;红色基因;人民检察事业;基层检察院;人民检察制度;', '你见过夏夜的长安街吗？$$ 每当夜幕降临，长安街华灯高照，远远望去，如一条珍珠串起的长龙，钻石镶嵌的玉带，构成一幅绝美的“盛世长安图”。如果将目光从长安街延展开去，可以看到，如今的中华大地，“到处都是活跃跃的创造，到处都是日新月异的进步”。这“可爱的中国”', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.003287', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1354, '报纸', '何叔衡：人民政权的第一任“首席大法官”', '黄慕泽', '人民法院报', '人民法院报', '何叔衡;毛泽东;共产党;瑞金县;苏维埃;首席大法官;临时最高法庭;', '1932年2月，中华苏维埃共和国临时最高法庭于江西瑞金成立，何叔衡任主席。而后，中华苏维埃共和国最高法院于1934年2月正式成立。$$ 如今，在中华苏维埃共和国最高法院旧址院内，立着一个造型生动的人物铜像。双方村民握手言和的形象背后，是何叔衡化解两村“争水”的故事。$', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003060', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1355, '报纸', '梁柏台：开创红色司法多个“第一”', '黄慕泽', '人民法院报', '人民法院报', '梁柏台;苏维埃;裁判部;', '“以身付诸国，竭力以担国事，以保国家，不以私而忘公”，这是梁柏台烈士之志——做一个以身许国的大丈夫。在位于江西省瑞金市的红军烈士纪念塔和中华苏维埃共和国最高法院旧址，记者注视着梁柏台的名字，探寻这位红色法学家对革命法律研究和司法工作的伟大贡献。$$ 梁柏台(', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003062', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1360, '报纸', '赣南苏区：翻开振兴发展新篇章', '程晖', '中国经济导报;', '中国经济导报', '赣南苏区;振兴发展;新篇章;中国经济导报;革命老区;中央苏区;', '2012年6月28日，《国务院关于支持赣南等原中央苏区振兴发展的若干意见》正式出台，翻开了赣南革命老区发展新篇章。$$ 支持原中央苏区振兴发展迈出坚实步伐$$ 赣南是原中央苏区的主体和核心区域，被誉为“红都圣地”，革命先辈们在这片红色土地上进行了治国安邦的伟大实践。', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28095/n.cnki.ncjjd.2021.001583', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1361, '报纸', '打造革命文物保护利用的“江西样板”', '惠梦; 廖乐逵; 章凯', '中国财经报', '中国财经报', '文物保护;财政厅;革命文物;红色旅游;红色文化;', '近年来，江西主动对接国家支持革命老区振兴发展的战略部署，实施“赣南等原中央苏区革命遗址保护利用工程”，持续推进红色文化基因传承，大力发展红色旅游，形成了全国革命文物保护利用的“江西经验”。$$ 江西是中国革命的摇篮。在战火硝烟的年代，老一辈无产阶级革命家在', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28053/n.cnki.nccjb.2021.001833', '瑞金_screened,茨坪_screened');
INSERT INTO `ds_article` VALUES (1363, '报纸', '红井映初心 碧水润红都', '石珊珊; 盛晓晓; 欧阳兴', '中国水利报', '中国水利报', '农村饮水安全工程;瑞金市;供水公司;供水能力;', '“吃水不忘挖井人，时刻想念毛主席”，这块写进小学课本的石碑，就立在江西省瑞金市沙洲坝村。$$ 中央苏区时期，毛泽东主席发现沙洲坝村群众喝的是又脏又臭的池塘水，便带领军民选址挖井，奋战十几天，挖出一口直径0.85米、深约5米的水井。毛主席还亲自下井底铺沙石、垫木炭', '2021-06-18 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2021.000980', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1365, '报纸', '革命老区振兴发展为什么如此重要', '童章舜', '国家发展和改革委员会地区振兴司;', '学习时报', '革命老区;社会主义现代化建设;中央苏区;', '革命老区是党和人民军队的根，是中国人民选择中国共产党的历史见证。党中央、国务院高度重视革命老区振兴发展工作，党的十八大以来，习近平总书记多次对革命老区振兴发展发表重要讲话，作出重要指示批示，站在时代和全局高度，指明了做好革命老区振兴工作的重大意义和目标要', '2021-05-31 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.000944', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1366, '报纸', '激发奋进新征程的磅礴力量', '王成兵', '江西省赣州市委;组织部;', '中国组织人事报', '党史学习;党性教育;红色基因;红色教育;红色资源;基层党建;赣南苏区;习近平总书记;长征精神;', '习近平总书记强调，要把红色资源利用好、把红色传统发扬好、把红色基因传承好。赣南苏区是原中央苏区核心区、共和国摇篮，是苏区精神、长征精神和苏区干部好作风的主要发源地。要用好丰富的红色资源，教育引导广大党员干部牢记初心使命，激发奋进新征程、走好新长征的磅礴力', '2021-04-28 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.001490', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1371, '报纸', '“胜利歌”前热泪流', '杨耀燕; 刘兴; 刘珊伊', '瑞金中央革命根据地纪念馆;', '经济日报', '胜利原因;袁国平;反“围剿”;', '有一次，我接待了一批特殊的团队。刚开始，我以为是一般游客。当我讲到国家一级文物《三期革命战争胜利歌》时，有一位老人用颤抖的双手隔着展柜轻轻抚拭着这件文物，激动地说：“这是我父亲创作的!原来这个团队的游客都是红军后代，他们追随着父辈的足迹来到瑞金，来看看父辈', '2021-01-26 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.000962', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1372, '报纸', '一心一意是三明', '王国平', '光明日报', '光明日报', '三明市;万寿岩;格氏栲;', '三元、明溪，都是地名，各取一字，就是“三明”。$$ 按说这只是个物理行为，哪知道引起的是化学反应。$$ 三明地处闽西和闽西北，是老区、山区，也是苏区，区位优势不是很明显，资源禀赋也不是有多么突出，曾经在整个城市序列里多少有点“不太起眼”。$$ 问题是，人不可貌', '2020-12-16 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2020.006663', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1373, '报纸', '在新时代继承和发展“马锡五审判方式”', '郑重', '上海市青浦区人民法院;', '人民法院报', '马锡五审判方式;继承和发展;司法为民;', '诞生于陕甘宁边区的马锡五审判方式是党领导的人民司法审判理念、方法、经验的总结，是我国革命根据地时期法制建设的典型代表。马锡五审判方式根植于中国共产党领导下的人民司法伟大实践，是全心全意为人民服务根本宗旨的生动诠释，在人民司法发展史上写下了光辉篇章。马锡五', '2020-01-10 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2020.000136', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1376, '报纸', '孕育于中央苏区的人民司法红色基因', '徐英荣', '江西省高级人民法院;', '人民法院报', '中央苏区;反革命案件;红色基因;', '习近平总书记曾多次强调，要把红色资源利用好，把红色传统发扬好，把红色基因传承好。中央苏区孕育出的人民司法红色基因，凝结了司法先驱的理想追求，昭示着司法文化的传承创新，彰显出人民司法的优秀品质，是人民法院发展史上宝贵的精神财富。$$ 中华苏维埃共和国成立后，', '2019-09-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P9pMsVu8qVBt1oWQZAJQbXdim_FS2gD6SsdAfF-uQdNK7LV3HVGN9y16shaItrIViUB7ji_RnqDVfiOheA3QtQ4XoDA3Mx5dXYY_eJUkXPNAe8sORhsVvyUMPJjsfkd4Ru8Y_1fjMRlw==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1377, '报纸', '水壶背后的故事', '杨特团', '福建省漳州市纪委监委;', '中国纪检监察报', '漳州战役;中央红军;南靖县;', '在福建省南靖县内洞村的“漳州战役南靖决战纪念室”里，收藏着一只军用水壶。水壶不大，表面掉漆严重，显得十分陈旧。这只水壶背后有着怎样的故事呢？$$ 时间追溯到1932年春，苏区中央红军为了粉碎国民党的经济封锁、向外发展，毛泽东提出攻打漳州策略。漳州是通向“海口”', '2019-08-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OTJdY73m3NzC1JaLRJidlMaA0cqbIm2d-HWlL7uDxmDDhS02V12B0eEyJhewVz0QBh22Y9BlgG6RNiuL16rj5bXQ8rdkc0w2bc3zFneOjaysJnK9dYncu4Za6ytwM0lApuwhaIZHfaJA==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1378, '报纸', '缅怀先辈伟绩 弘扬长征精神', '王光鑫', '学习时报', '学习时报', '长征精神;纪念碑;红军长征;中央苏区第五次反“围剿”;中央红军;城东门;于都县;', '5月20日，习近平总书记来到江西省于都县，瞻仰中央红军长征出发纪念碑，察看中央红军长征出发地旧址原于都县城东门渡口，参观中央红军长征出发纪念馆。在纪念碑前，他向革命先烈敬献花篮并三鞠躬。他强调，我们不能忘记党的初心和使命，不能忘记革命理想和革命宗旨，要继续高', '2019-05-24 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2019.001523', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1379, '报纸', '陈潭秋：中共一大代表、党的创始人之一', '徐海波', '人民日报', '人民日报', '陈潭秋;中共一大;中央苏区;创始人;', '新华社电 （记者徐海波）春节期间，湖北省黄冈市黄州区陈策楼镇陈策楼村，一派祥和气氛。中共一大代表、党的创始人之一的陈潭秋烈士的故居就位于村湾中央。不少外地游人和返乡游子特意来到这里，敬献鲜花，缅怀先烈。$$ 陈潭秋，1896年生，湖北黄冈人。青年时代积极参加五', '2019-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MzcNcdUbBQNRWqeziY7VtsuuOMlLL_sho4hJGhxC3g_nzgC7hNW_cxza2mQzXZBNtQ1Iho4M4ZzSIvBePLrdVDWq6zWoLy9KxOftaVxkr8VZ-9AZJCe1MeLc6MvDOY4QWeqvZ9x6T1oA==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1381, '报纸', '周恩来与八一建军节庆典', '戴和杰; 何剑芳', '江西省南昌市纪委监委;', '中国纪检监察报', '八一建军节;红一方面军;中国工农红军;周恩来;', '1933年8月1日，盛大阅兵典礼在中央苏区首府江西瑞金举行，这是中国工农红军第一次庆祝自己的建军节，此次阅兵开创了人民军队建军节阅兵之先河。为了举办好这次庆典，时任红军总政委兼第一方面军总政委的周恩来，付出了大量心血，在八一建军节历史上挥写了浓墨重彩的一笔。$$', '2018-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Oz-L-t7Yod3VbP_HLXv9McHgGlNR7zewcg6CjOxbSMDhcgq6xBGX0Kg2H_iaP1DZGrq3PO-LevTzyxXPvHsxYyQb6BlAiIi5_FEgkEbmyYvb6mpOhXwi-wDjYSqZ0b3-K4WqsV6MVQRg==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened,项英,反围剿_screened');
INSERT INTO `ds_article` VALUES (1382, '报纸', '自媒体侵犯名誉权的认定', '危先平; 危雅芸', '江西省瑞金市人民法院;', '人民法院报', '名誉权;注意义务;侮辱他人;名誉侵权;', '【案情】$$ 记者杨某明经采访获知红军女战士张某某（2013年去世）义务为红军烈士毛某某守墓七十年的事迹后，于2014年3月31日在《江西日报》发表了《老红军母子接力80年守护毛某某墓》的报道。$$ 原为某中央革命根据地历史博物馆馆长的邹某某，查阅相关资料后发现张某某前', '2018-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NzfGw1vMmGCGkZasdKbOE2bb_79bCvpftvXfZnb0HyI7c0yASj22MVIXHfD0wfrrvKzzidjlZV0V6hxd1IwyWtfs8z7d2FuBIahQKp15WSwFRoPgTAZjI-PBvHDS1K-qHkOJYsdrvktg==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1383, '报纸', '用红色基因打造过硬队伍', '钟铮', '公安局;', '人民公安报', '红色基因;革命传统教育;', '多年来，江西瑞金公安采取多种形式，充分利用红色资源，加强革命传统教育，不断提升队伍建设整体水平，先后涌现出了一大批优秀基层单位和先进个人，人民群众的安全感、满意度不断提升，树立了公安队伍的良好形象。$$ 开展红色教育，大力弘扬苏区精神。瑞金市公安局紧紧围绕', '2018-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NhwUXynerAsuMp5Zc6uX4_8GX__o71SCaGzIAS5HGxx3689n4hNJ5Byj3gNG1kWX79f4NaEMDf5b20zKi0F5mgQ94LNP0KRJMyyNe7KutdyGost8OaE4djOUZPS7UkFFoWZ4OF83MbGw==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1384, '报纸', '雄关漫道真如铁，而今迈步从头越', '', '中国青年报', '中国青年报', '中央团校;党中央;青年群众工作;泽东青年干部学校;团干部培训;', '烽火创办、辗转壮大、曲折前进、沐浴春晖、承载重望、规范建设、提升层次、转型发展……从列宁团校到战时青年训练班，从泽东青年干部学校到中央团校，一路慷慨壮曲、一路激越雄歌，十万颗青春赤胆在这里潜心磨砺，十万名青年干部在这里淬炼成钢!$$ 2017年11月20日，党的十', '2018-04-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M4eoguQU6WmSbQgJEf7URvNtqBS3ust2ttePwCVlZfmsbwFocalAZlYF-9NnuSV_TjxfqdFGX1F35S67qXNoqlbWLrpNCkEUKsTYVCBbaThGgC2d-TpJNyZOyVQpjocGadL_r1BQVYLw==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1389, '报纸', '抗大的魅力究竟在哪', '杨彩霞', '学习时报', '学习时报', '毛泽东;抗大精神;红军大学;红军长征;', '编者按$$ 办学9年多，培养10多万英才，在条件极其简陋的“窑洞大学”里，抗大书写了我党我军教育史上的奇迹。不忘初心，继续前进，在抗大建校80周年之际，本报特约请资深专家和相关人士，对抗大建校史、抗大精神的现实意义、献身国防教育事业和建设世界一流军队等问题进行', '2016-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Nrnb0dGHqEMwZuuLH7C4rUldC5d_pzrJbbs0wR5FZNwXRxWhzKW7zBh1JAHGMqdTZzatbhQOmoYVQeAVrwsgWQl94sZq9pUwU6OYQmyWW5VxkpdPw6pwZ_eY4XjwX2TtE0tU1GVFJjSg==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1391, '报纸', '依法办事 依法执政 依法治国', '张向阳', '最高人民法院应用法学研究所;', '人民法院报', '依法治国;依法办事;依法执政;华北人民政府;最高人民法院;人民法院组织法;', '今年是董老诞辰一百三十周年。回忆起在董老身边工作的日子，我深切地怀念他。董老永远活在我的心中。$$ 晚清秀才·旧民主主义者·共产党人$$ 董老是湖北黄安县（今红安）人。父亲和四叔都是当地有名的秀才，从事师塾教育。董老5岁以前，父亲教他读《三字经》《百家姓》。', '2016-06-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Oc5ozwf_cilPM33ryAOpTYLM8EwKm9p2ktkaBhfXFfbtJKmrvGMYPRa29D9qYhAyGE4CxQlHPCexSOnGeCulAJLZke3DwufgEkDxBc3jvn_50rRoxjsipqw-yWPoOdg1zVK_s09oKcyA==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1392, '报纸', '传承红色基因 滋养精神家园', '姚亚平', '中共江西省委;宣传部;', '人民日报', '红色基因;红色资源;江西省;红色文化;社会主义核心价值观;八一精神;', '习近平同志强调：“牢固的核心价值观，都有其固有的根本。抛弃传统、丢掉根本，就等于割断了自己的精神命脉。”对于社会主义核心价值观来说，我们党的红色基因就是不能抛弃的传统、不能丢掉的根本。在我们党带领人民进行革命和建设的进程中，形成了许多伟大的革命精神，留下', '2015-02-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Op55G8tTsM7SxULzTkVvYePI6autj6hhUY6UEOWaKzy-Gd05rux0UlJWPh4Dnduq-XMsVDEpVr0hVa_DVd9Cj_FfxEH-EKZHqaybHvlhFtbk9tL3Sa1oLl1bJPtVHKduD_FdaAoXsD2Q==&uniplatform=NZKPT&language=CHS', '瑞金_screened,井冈山革命博物馆_screened,龚全珍_screened');
INSERT INTO `ds_article` VALUES (1396, '报纸', '井冈山告诉我们的四句话', '常书铭', '山西省水利厅;', '学习时报', '井冈山;共产党人;群众利益无小事;革命理想;', '7月1日至6日，我们怀着无比崇敬的心情，在中国革命的摇篮——井冈山进行了实打实的感受式、体验式、情境式学习，从中得到教育、受到启发、获得力量。我们共同的感觉，这是一次信仰坚定之旅、精神寻根之旅、心灵净化之旅，以独特的教学模式，让我们心灵受到震撼、灵魂得到升华', '2013-11-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NOs7KuG5AuoagvONlmgHLEFAaFJQWdM0j8yj9bcZ2_FP8yx4gGRViBwdSsAxYSIdzPRl3eK5oFuKtUtArUiJNvW-ZaKtW6oReDflfKMIcaU4ROGt6UGxZdbOzvz7FaM7mFLUOVLs32Iw==&uniplatform=NZKPT&language=CHS', '瑞金_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1397, '报纸', '“八一”建军节是如何确定的？', '户华为', '光明日报', '光明日报', '中国工农红军;中央革命军事委员会;中华苏维埃共和国临时中央政府;', '1933年6月，中共中央、中央革命军事委员会向中华苏维埃共和国临时中央政府建议，以南昌起义日——8月1日为中国工农红军成立纪念日，每年的8月1日开展纪念活动。中央同意这一建议，并决定在红军成立纪念日期间，开展拥军优属活动。随后，中央革命军事委员会发布《关于决定“八', '2012-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M3n1ZGrQBOO6AcDttlcOt5sHQ1Q5vLw-irOB98zj5ZpvsRp3mSRE61U01N2KN_-rafP2j2SpFGZYP37-NhqCetZ-OjZQD76SMvIRZpSiyf0NLvQqI2FL6irXlnt0jk4TywuAV093zTjw==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1400, '报纸', '督赣十年熊式辉', '谭洪安; 熊学慧', '中国经营报', '中国经营报', '熊式辉;抗战期间;省营工业;', '1931年12月15日，一纸来自南京的委任状，把年方38岁的海陆空军总司令南昌行营参谋长熊式辉，推上了江西省主席之位。同一天，国民党中央常委会在南京举行临时会议，面对胡汉民、汪精卫两大党内反对派“逼宫”的国民政府主席兼军事委员会委员长蒋介石，向全国发表通电，宣布“', '2012-05-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MP3h2vb2rWtU0fKDzd34ab1DvOQYvwDC-IMPZUt9Tw3Jj7vEho-Ys_qDINg7qZqZ48l6KOq6A4ajePOPzwgscdQYZRjLE6bnMVagkdtDhZBpgOTJonPxOzrWkrvW6pAV3A0O7rr_7ezg==&uniplatform=NZKPT&language=CHS', '瑞金_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1401, '报纸', '继承光荣传统 建设美好红都', '钟炳明', '中共江西省赣州市委;瑞金市委;', '人民日报', '共产党人;中华苏维埃共和国;中央革命根据地;', '今年是中央革命根据地创建暨中华苏维埃共和国成立80周年。80年前，以毛泽东同志为代表的中国共产党人在以江西瑞金为中心的赣南、闽西大地上，进行了艰苦卓绝、波澜壮阔的革命斗争，开辟了中央革命根据地，创建了中华苏维埃共和国。作为中华苏维埃共和国临时中央政府所在地，', '2011-11-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OCPt1gUS9lIWhQGdbFcefKw8N5U6p1mQYphoYf-ek8RG01EVULbUhzGf9KTpZDpDpZCrtBBQDPpJ1WYV4fn1eIcvSW98hj3KxTYBAe71pSe7svtbBefGi8TboL4aj0Vh2SaYxNoHGn7g==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1403, '报纸', '中央苏区党风廉政建设基本经验研究', '汪毓华', '江西省纪委;省监察厅;', '中国纪检监察报', '党风廉政建设;中央苏区;反腐败斗争;经验研究;', '1931年11月，中华苏维埃第一次全国代表大会召开，宣告成立中华苏维埃共和国，江西瑞金成为红色首都。在中央苏区时期，我们党开始了治国理政的伟大探索和成功实践。为杜绝腐败现象的发生，采取了一系列重要举措，开创了为政清廉的一代新风，其经验对当今时代仍然有着重要而现', '2011-09-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NCTUemQjkt0gUopi6ii5Tr5YXOC52i_yCB4Dv5gXWsKoqFxtDpDm6ZTlp2fBmzPkFOG24OuUyM_uuHt7YndOnWgpnOfsZp8D8voTKnHMLdmDaF_hQQrgXSsNhSgLu69aHKfobx02T5Ig==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1404, '报纸', '诉讼联络员让司法服务无限延伸', '姚晨奕 ; 陈文春 ; 肖建国 ; 曾照旭', '人民法院报', '人民法院报', '联络员;联络员制度;网络体系;司法服务;人民法庭;', '江西赣州是全国著名的革命老区，瑞金市及周边几个县是第二次国内革命战争时期的中央革命根据地和中华苏维埃共和国临时政府所在地；赣州也是人民司法的发源地，苏区审判时期形成的依靠群众、服务群众的优良司法传统如今在这里更加发扬光大。诉讼联络员制度，便是赣州市两级法', '2011-09-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OcP1rIaxAWVh5tLLjTGyVmOzVQUR3Nou8lkGe5Cat_yz9jJBJSjFuijER-Wwa1jdyzwfudCLPf7LEqX3gbEsYRbDk8q96z6qPdPfzhOXtU110pgeS8_1As3uD1jDJEt09CYoWqz-ucVQ==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1408, '报纸', '标本兼治反腐败', '姜洁', '人民日报', '人民日报', '反腐败;标本兼治;中央苏区;', '一个国家，腐败不除，无以立国；一个政党，腐败不除，无以立本。$$ “共产党是为劳苦大众谋福祉，他们不拿群众一针一线！”从建党初期，苏维埃政府到革命根据地、到解放区，共产党所到之处，都建立了与国民党的腐败政府形成鲜明对照的廉洁政府。这极大地争取了民心，', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Nb7wIOzKf3mhys4TZVdfWnsR6PWj9dSqJhaEsI4taMDdPWKBAC-MzRwjXuo_5RV1_QohyPpU3Y5UxxiOrohpXu3Wittbh6yfLAEYkUrePR4puTzgW3rrYOOxir4nDMLGiNxHbMTOcb_w==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1409, '报纸', '发扬苏区工运传统 做好新时期工会工作', '姚亚平', '江西省人大常委会;省总工会;', '工人日报', '工会工作;工会组织;江西苏区;工人夜校;', '1934年1月，毛泽东在第二次全国苏维埃代表大会的报告中总结苏区工会的成绩与经验时指出：苏区工会是组织坚强的阶级工会，是苏维埃政权的柱石，是保护工人利益的堡垒，是广大工人群众学习共产主义的学校。全总苏区中央执行局在瑞金艰苦卓越的工作业绩，为夺取新民主主义革命胜', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PdYhPXlCxRVsdplI3R1abhYiWfTVgXq53Bz4QSH9YnEU95ygtIfgR6h5X1hkuwmrXUdASu_2GL34RKfkqVJhsZzVQxbzsaa70BqPaFUZ_-LGEhaGBOW4d3Ndx9-kba1enzkh69pVrciQ==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1410, '报纸', '冲破黑暗的“黎明之声”', '', '新华社;', '新华每日电讯', '延安新华广播电台;国统区;陕北新华广播电台;', '1940年12月30日,一个平凡却又特殊的日子。$$ 这一天,1931年成立于江西瑞金中央苏区的新华通讯社,创办了延安新华广播电台。$$ 在战火纷飞的岁月,新华社的口语广播冲破敌人的重重封锁,将中国共产党和解放区的声音传播到国内外,鼓舞和激励亿万人民为民族独立、人', '2011-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P3Ja8QDYlEYDdqyQByUolnioixjuOLJhxF3GUVP0FOV2N_Z9AO2PPZtInrxQOiJyuJkdG0dr5qQxwX0_-bI0j-u3Vb6M6u7yUhsTqqcRvp7FSDJM4H5jJXTwnqbCPAKdQkxavIgfrlTQ==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1420, '报纸', '瑞金,你应该知道的几个第一', '杨清刚 ; 唐芳茂', '解放军报', '解放军报', '八一建军节;中央革命军事委员会;中华苏维埃共和国临时中央政府;中国工农红军;', '第一次设立国家军委$$ 为便于各地的红军在统一的战略意图下配合行动，在中华苏维埃共和国临时中央政府刚刚诞生后，就于1931年11月25日成立了中华苏维埃共和国中央革命军事委员会（简称中革军委）。$$ 这是中共执政（局部）后首次设立国家军委。中革军委是政府系统的最', '2011-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M8IKOgGZkln01tRKgU1ecTFdigGmuE3K6ZR_mFZ0f1gDxOgZlsge0cAFtyAoh1nMFeVnBbsUMcbAgTi-nUWVWOf2JMt-w1fTw7e9bJ3AAbZCa0ILfH8eodXtqtvLsXarwtw5_xnP90Rw==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1423, '报纸', '红军优秀指挥员毛泽覃', '', '人民日报', '人民日报', '毛泽覃;指挥员;', '据新华社北京４月２５日电 毛泽覃，１９０５年９月生，湖南省湘潭县韶山冲人。１９１８年，随长兄毛泽东到长沙，进入湖南第一师范附属小学学习，同年参加新民学会。１９２１年７月，他加入中国社会主义青年团。１９２２年初，进入长沙协均中学读书，他组织青年阅读进步书刊', '2011-04-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O9DNIsLez5UNRFwrN6MUdcngCXyOhxrH__Ri7v0wjZ2nKRgN8D-THNIcjCSXuLY_lglRHCDXoJS_bRtWgYqRsPj4ZX-lUSgga_CHHU8qCU51CDDhaYTYvibFo3_mkkI_NgVP_v27Anpg==&uniplatform=NZKPT&language=CHS', '瑞金_screened,反围剿_screened,井冈山会师_screened');
INSERT INTO `ds_article` VALUES (1424, '报纸', '弘扬好作风 真功在平时', '刘建林; 卞民德', '人民日报', '人民日报', '创先争优活动;江西省;入党积极分子;基层党组织;', '创先争优活动开展一年来，江西省委坚持围绕中心、服务大局，把抗洪抢险、灾后重建、完成和超额完成“十一五”规划目标任务、精心谋划“十二五”规划，促进经济社会又好又快发展作为创先争优的最大实践。$$ 全省9.4万个基层党组织、近百万共产党员，继承和弘扬苏区干部', '2011-04-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ogwoxwwsvet2zIFQm9uLrD720Bbgtw8hK1UMrrR-jh7KEWCwYBHjyAMX0-ZQ0Oa72bii4fbGEfbrEuX9Q_jw92ErLTYmpO4-9Ge7Dctlv874HtgtrgG3wcaxW_QvZ7Vk2VhvcB-uiA9g==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1426, '报纸', '“红色”龙头牵引文化建设快车平稳飞驰', '', '人民法院报', '人民法院报', '江西省;廉政教育;', '昔日的赣南，是一方积淀厚重的土地，80多年前，这里诞生了中华苏维埃共和国和共和国临时最高法庭、最高法院，老一辈苏区司法工作者用他们的实践，锻造了人民司法优良传统；今天的赣南，又是一片生机盎然的沃野，赣州法院以弘扬人民司法光荣传统为龙头，牵引文化建设的快车，', '2011-01-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PyTz9IuqoMaO8IDNBRv4N97ezxDtUlOfdgwhwCAAficF6-5BGHzdWdPXyr0p_jtJKUy42UPjzOCRQWFnAuQhmBs6cpuJj-o0wYV6eDm2rdr_sJPDQRdpfgoWzA8JyMI_cUXqa5Tt7Fhg==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1427, '报纸', '中央红军兵工厂迁建奠基仪式举行', '单伟; 张晓祺', '解放军报', '解放军报', '中央红军;总装备部;', '本报瑞金11月23日电 单伟、记者张晓祺报道：“红色故都”再添“红色遗址”。今天上午，中央红军兵工厂迁建奠基仪式在江西瑞金举行，数百名老区群众怀着对人民军队的深厚感情，赶来参加奠基仪式。$$ 作为瑞金时期中央苏区最大的兵工厂，中央红军兵工厂是中国共产党和人民军', '2010-11-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O1vDJZxnisb6oe6kgg3ZDtMjLGF4eFZxLF04x7R2nXXm7QSONqGt0qI5VgpSkqemdJ5j4JU1BJxX589iOYd34YCx7o767ZwQgMFzJgDvhGMrhAaDLJ_ApfbxT7rD9JAmQqB-9zrv9_Cw==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1428, '报纸', '中央苏区红色旅游联盟共拓市场', '梅柏林; 汪平; 李金枝', '中国旅游报', '中国旅游报', '红色旅游;中央苏区;', '本报讯（驻江西记者 梅柏林 驻福建记者 汪平 通讯员 李金枝）中央苏区红色旅游联盟第二次联席会议日前在江西省瑞金市沙洲坝召开。来自闽粤赣3省7市34个中央苏区县（市）的代表签署了《中央苏区红色旅游联盟2011年市场推广合作框架协议》，并就发挥联合优势，拓展客源市场、', '2010-11-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MHt2Ac3ovknpYw24EEcvmna3QWKiW54Av_6QURWuAkXE6ytlgsK1OLhiUCb0hnbhr-wGAVkEzsV63x5bX7_pY8iAnH04kNSOIRuEj2TXorE_19oZobajKPEY-6FcH1Vhf1H5pF-R6ivA==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1430, '报纸', '用井冈山精神筑守法律家园', '姚晨奕 ; 占飞鹏', '人民法院报', '人民法院报', '井冈山精神;优良传统;重要讲话精神;王胜俊;', '9月1日至3日在井冈山举行的江西全省三级法院院长会议上，与会代表就如何贯彻落实王胜俊院长不久前视察江西法院时的重要讲话精神，进行了热烈的讨论，大家一致表示，一定要大力弘扬井冈山精神和苏区优良传统，以此筑牢全省法院干警能动司法践行“司法为民”理念的思想根基，加', '2010-09-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M1e-7OHQD-x2WXz31H9NdCYDPp6BdDMYMEwkEUdvdhTfduH-PImLWwSLilIXVQxyfXj9GEhDyIcq1QrfWhe7iiep5s6DJCGxr0SBjmNsMiR5cd_zWXfjYKW6PSPf9zdZa_iwaWMr_Tug==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1434, '报纸', '中华全国总工会苏区中央执行局旧址揭牌仪式在瑞金举行', '赵翔', '工人日报', '工人日报', '中华全国总工会;倪健民;执行局;', '本报瑞金5月24日电 （记者赵翔）今天上午，中华全国总工会苏区中央执行局旧址揭牌仪式在江西瑞金市隆重举行。中共中央政治局委员、全国人大常委会副委员长、中华全国总工会主席王兆国致信祝贺。$$ 中华全国总工会副主席、书记处书记倪健民出席揭牌仪式并讲话。$$ 倪健', '2010-05-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OHd3xQWF2F2ExaGszHsWJpadLJ-rTHtzQhkkrntstx6mMomjC328yAjH_xKy4slNdsy5-nc0ZmW3EO0nM-Q8rpc6TwexuTIDEFT02NQHDvHX5uZ9MzVO3nfiLkFOicJblD_-mAgE_CeA==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1436, '报纸', '井冈山增设《井冈山红色邮政史》展览', '尚静芳; 梅柏林', '中国旅游报', '中国旅游报', '井冈山;井冈山革命博物馆;《井冈山红色邮政史》;', '本报讯（尚静芳 驻江西记者 梅柏林）日前，《井冈山红色邮政史》展览在茨坪毛泽东同志旧居正式对外开展。展览以珍贵的历史图片和文物反映了从当年中央红军在井冈山组建第一个红色交通站、委任第一位红色交通员邓贞谦开始，红色邮政历经井冈山、瑞金和延安、西柏坡、北京等时', '2010-03-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PzkBP5-si6UsGoXS4q1oN3__7mKTBZsRyPaIqkNnDJGjIk8vag1uXJpjgSp3mjtX4qwhe1Hponb0ldTtfrxl6QFqsswwQkEKVrdtfPTeOIRCaY96kzMHI09ST7YNZ0A2zrytBKI6u4OQ==&uniplatform=NZKPT&language=CHS', '瑞金_screened,井冈山革命博物馆_screened,茨坪_screened');
INSERT INTO `ds_article` VALUES (1441, '报纸', '第三次全国苏区精神研讨会暨第六次红都瑞金爱国主义教育基地联席会在京举行', '刘声东; 邹维荣', '解放军报', '解放军报', '爱国主义教育基地;研讨会;', '本报北京12月12日电 记者刘声东、邹维荣报道：第三次全国苏区精神研讨会暨第六次红都瑞金爱国主义教育基地联席会11日在北京召开。$$ 会议就苏区精神的形成、传承与发展等进行了广泛的学术交流。通过一天的研讨，第三次全国苏区精神研讨会达成四方面的共识：进一步加深了对', '2009-12-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NSj3BPHVNk1rU9_9HM14jOR4kigvRfFRNLn-cP0RxwAJK4dqYkDwJnVVD9xDGK1sgmSyKyEUTEmKduQ1Y6Dpf5N93qPmgl6knv6YhI27j05wzWqE8DgnM3dd6vFub609aGieGcBh_60w==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1450, '报纸', '中国工运史上的丰碑', '赵翔; 刘丰', '工人日报', '工人日报', '中华全国总工会;工运史;工会系统;执行局;枣子排;革命传统教育基地;', '今年是中国共产党建党88周年和中华人民共和国建国60周年庆典。日前，记者随同江西省瑞金市总工会干部，瞻仰了中华全国总工会苏区中央执行局旧址，接受了一次生动而又深刻的革命传统教育。$$ 瑞金城西7公里处的沙洲坝镇枣子排村，有一条长500米、宽3米的水泥路，路的尽头就', '2009-07-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PjIg4qjc111zB39kvbWOpRJj8O_uqDYrwJbQcpUKX09rKi5KPkj13rdtigfL5OEdgOKhcNrN86qoDXC4D2bweOt7aEcK46teL0byIVR6CKM5fZrcviWcJ-CbICo7nB9_ybJOA0PZMjXQ==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1452, '报纸', '寻根之旅润军魂', '刘德茂 ; 褚振江', '解放军报', '解放军报', '井冈山斗争;参观见学;国防大学;', '盛夏的南方山区，层峦滴翠，满目芳菲。怀着一种对革命老区永恒和神圣的景仰，国防大学前不久组织师以上单位党委支部书记轮训班赴赣南闽西地区，开展了一次别开生面的见学活动，寻根之旅让将校们获益匪浅。$$ 精神家园汲取养分 $$ 82年前，朱毛红军先后挺进罗霄山脉', '2009-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PjxK9QneXuMeJBZnducBVk4sVsDmVJsq3ft7L_UnWdupmwQx8P6t5glbHTzRIAu4vvQ2VIOIKWQLTL1ZaucSVcu0R4_Zlj4boaDdaVMxhLVwmQqZwBoUQCptJibPCffFk7qkQSqAs9rw==&uniplatform=NZKPT&language=CHS', '瑞金_screened,黄洋界_screened,井冈山革命博物馆_screened,井冈山会师_screened,三湾改编_screened,张子清_screened,朱毛会师_screened');
INSERT INTO `ds_article` VALUES (1454, '报纸', '努力推动红色旅游又好又快发展', '潘惠珍; 吴健芳', '中国旅游报', '中国旅游报', '红色旅游;古田会议会址;福建省旅游局;又好又快发展;', '本报讯（潘惠珍吴健芳）在深入开展学习实践科学发展观活动中，福建省旅游局日前组织机关各部门负责人深入古田老区调研，提出要进一步发扬古田会议精神，努力推动全省红色旅游工作又好又快发展。$$ 在调研座谈会上，福建省旅游局局长郭恒明强调，打造红色旅游精品是当', '2008-11-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MqkHL6wUQuiElxYDqgd4VJnkuZPblqJ-8rIxOiblBqxq_wGgam47_zx5nUHri5k8C1-LHr89Ysly9zcJ4HGBJfXMfyvEl9m_eUWa8_UEAXtIWMl6J8tfZUv7UmkyY4tbRrylKMjUy05w==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1456, '报纸', '“八一”建军节的确定(下)', '', '人民日报', '人民日报', '红星奖章;中革军委;王稼祥;国民党军;', '１９３３年８月１日，中央革命军事委员会在瑞金举行阅兵、宣誓、授章、授旗仪式，纪念“八一”节。为防止遭受到国民党军的空袭，活动于１７时到１９时３０分进行。参加这次活动的有中共临时中央、苏维埃中央政府、中革军委领导和机关部门领导及代表，青年团中央和全国总工会', '2007-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PzSCtPvdshCZeNfluUCmGfz5jg9xl-UUvr-zKimHamnfh-xrrr8cDWPnyOsL0a_6CpTlpP9DRhdhb4AtH6oToOp7cPYhGRNZ1H4Z2fI9EKQNBMOIIB5F8EpSktgFi6s4qOknxH71w0Gw==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1457, '报纸', '吴官正何勇为中央纪委监察部旧址建成揭幕发贺信', '钟继轩', '中国纪检监察报', '中国纪检监察报', '中央纪委;监察部;反腐败斗争;吴官正;', '本报讯　在中国共产党建党 86周年前夕，广大纪检监察干部 期盼已久的中央纪委监察部旧址 在江西省瑞金市建成并举行揭幕 仪式。中共中央政治局常委、中 央纪委书记吴官正，中共中央书 记处书记、中央纪委副书记何勇 对旧址重建非常重视，分别', '2007-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O_zLMO6RuoZkmOc-VuaEOdIsPpFT3jtkaG7ReX-2WQD4rLTQJDhKJLxdTrrh3b8siUgl3TYC2hu3xVuXk7Mzho5Mk1aDqsh1ATzhAiFwTkcirl1LGfmaHxO77isEn59R60lbr5YR3MVg==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1459, '报纸', '送您一颗“小太阳”', '冯义军; 李洪明', '中国电力报', '中国电力报', '江西省电力公司;大柏地;瑞金市;国家电网公司;供电所所长;', '“等到革命胜利后，我们送大家一颗小太阳”，这是当年毛泽东在江西苏区看到老百姓过着没有电的生活时，对当地的老百姓说过的一句话。$$２００６年５月１３日，国家电网公司在江西南昌市安义县罗丰村举行了户户通电工程启动仪式，正式拉开了国家电网公司实施农村户户通电', '2007-06-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M0rhcaxOWCmULlJizeZaIbi-GymNN7DmDyYqsw8PqEnAWOr_8D1H9K1qbUWYj1aYM_viI7hPhJ5bLI26LizuBLQ2pr-501mysfJI8ugePbv7bmSvNOhu7G9opZUBgKKSkAYZ4MAgSzpg==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1462, '报纸', '南方八省红军坚持三年游击战争', '', '人民日报', '人民日报', '游击队;国民党军;三年游击战争;地方武装;中央苏区;', '１９３４年１０月，中央红军主力开始长征时，中共中央决定留下红军第２４师及地方武装共１.６万余人和部分党政工作人员，在中央苏区及其邻近地区坚持斗争。成立苏区中央分局、中华苏维埃共和国中央政府办事处、中央军区，项英任分局书记、军区司令员兼政治委员，陈毅任中央政', '2006-11-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ot6hhQePHp3Hl2PHexsHKv7e8LDLc-JsX2X-8rnB70WeQy0DMAmKjVbuS61DpZxvB5G6_t9qthZovU4CKCbQZEk8C2IJFztqMWUGMQPWTiAPFhOgyJRO4eJhCXMvnk9ljWsx0YzNcwnQ==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1463, '报纸', '让农民的心热乎起来', '顾仲阳', '人民日报', '人民日报', '新安村;扶贫办主任;无籽西瓜;人均纯收入;太空莲;整村推进;', '广昌，有一张著名的“历史名片”，它曾是中央苏区的北大门，“红都”瑞金的重要屏障。１９３４年４月，红军在第五次反“围剿”中失利，中央红军就是在这里，做出了战略转移的部署。$$ 地处广昌南部的新安村，长期以来，贫困一度是它的另一张“名片”。村民吃的是达不', '2006-11-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OMhvcI1Be8BOliXNl0qxWR0TEDTR5_147axBrXRUYTFFYynPzLDMUtCDwBjfhpjlNbHHeWKyDyfkhzSLFQZ8VVUWT4Cz-sO1QXif-OiAE_19HHNhQZpP6bStfvlGDP2iHs1VTd-YpHqw==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1469, '报纸', '兴国：模范县的红色梦想', '冯洁; 吉玛', '中国经济导报', '中国经济导报', '旅游产业;模范县;红色旅游;江西省;工业园区;旅游线路;长冈乡;劳动密集型企业;中央红军;井冈山;', '“哎呀嘞，苏区干部好作风，自带干粮 去办公。日着草鞋干革命，夜打灯笼访贫 农。”记者听到这首著名的中央苏区时期的 山歌《苏区干部好作风》，是在兴国的革命 烈士纪念馆。23岁讲解员清亮的歌声，让 人觉得兴国不愧“山歌之乡”的盛名。$$', '2006-09-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OpMCC36dEs4XAFngu-tNjR9lPTj8nHZTU8QqGe_fwSPsc2Atvv0N8K4KF_KNXh1Lha0F-6Asdv3uutCfdh0n33D6TB8Gb9bnGDwE-FK0cw_sgYXiGXLekPLXW84XslVpILWLaArpBcrg==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1474, '报纸', '中央苏区第二次反“围剿”', '', '人民日报', '人民日报', '中央苏区第二次反“围剿”;国民党军;红一方面军;', '中央苏区第二次反“围剿”取得重大胜利后，毛泽东兴奋地填词《渔家傲·反第二次大“围剿”》：“白云山头云欲立，白云山下呼声急，枯木朽株齐努力。枪林逼，飞将军自重霄入。七百里驱十五日，赣水苍茫闽山碧，横扫千军如卷席。有人泣，为营步步嗟何及！” $$ １９３１', '2006-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P3L5_-TPR9CwkwY9udXW28j6NTwhIeSIw0lfm9KPs5Pms-HqeB-Au_8BhOKQ4suayU8A8nV0aiMBE6zFsfFOdChTeoIZXWgJo7m7sERujDWLpPoKubsOWWbHm2iAiLpNUnlQ68eBtBGg==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1477, '报纸', '于都：30万人保守一个天大的秘密', '余孝忠; 陈春园', '新华每日电讯', '新华每日电讯', '中央红军;暗示性;游击战争;', '新华社南昌8月5日电(记者余孝忠、陈春园)8万多红军主力在一个县城内外集结、休整了长达10天时间，之后安全顺利地跨过“长征第一渡”，国民党谍报部门却对此一无所知。72年前，30万于都人民共同保守着一个天大的秘密，被今天的党史研究者赞为奇迹。 $$ 据当地史料记载', '2006-08-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OHi3B09ySY50V9Je4aCQ1NwLiYpLeOz8OUV8QIsea0wB02t8iKcvDdJuRlM-qFtkojoIsoVVFIkwTOyODKfhXF1rMARllrGzDb18BVJIsNd09N7LEjIxEMu4DGSmxXxLdROu_9erwc0A==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1480, '报纸', '新农村看电', '李洪明; 郭奕明', '中国电力报', '中国电力报', '新农村建设;示范点建设;供电部门;', '打开中华人民共和国地图，有两个地 方采用了“红五星”标志，一个是首都非 京，另一个就是“红色故都”赣州市的瑞 金。作为革命老区和我国中部一个以农业 为主、农村人口占多数的经济欠发达地 区，赣州市近一年多来的社会主义新农村 建设为世人瞩目', '2006-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PV2DJ9W1omAREk1FVlv0BGBvqxQdiQTpXusWOZm_HiPrHnAVy9l8qKcuR2ar3m75mmwzMq1dO59pIbydPurQUM8vWTSe0lA1aSkwnhjUlcCdqdhDfjveztyzGVp7GEaDT8C3iuazzHbA==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1481, '报纸', '中华苏维埃妇女生活改善委员会旧址揭幕', '张清林', '中国妇女报', '中国妇女报', '妇女生活改善委员会;中华苏维埃;', '4月17日,“红都”瑞金歌声嘹亮,彩旗飞舞,中华苏维埃共和国妇女生活改善委员会旧址揭幕仪式在这里隆重举行,全国妇联副主席、书记处书记陈秀榕,全国妇联书记处书记甄砚等领导为旧址揭幕。 1932年4月,中华苏维埃共和国妇女生活改善委员会在当时的中华苏维埃共和国临时中央政', '2006-04-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4McwfZY3BmUauelvioRMCYQBA0GrXGlJzV2kK4wqVC5L25Rkl-lehEPYMx6eJ1o9ni6rOa59DLQR91E2mSM8w56JEbq5DuFbbM9DHVC7h63ekkLV3RVOwmCvs0CkAKsszkZOIwrNTFS6w==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1483, '报纸', '周桂生', '', '人民日报', '人民日报', '周桂生;游击战争;', '周桂生,1906年生,湖南平江人。出身于贫苦的农民家庭,曾给地主当长工。1926年7月在家乡参加中共平江县委领导的暗探队,为北伐部队搜集情报,同年9月加入乡农民协会。1928年3月参加平江农民扑城暴动,他自告奋勇参加敢死队,用炸药包炸毁敌军火力点,为扑城农军打开了一条通道。4月', '2006-03-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PlkDr0HjOhAsZwPssFum3Ndq-3WfOhoOB5HrxRjYeEJ2j2OntmVVGG1lGajEs-sxJO-Qh1QVdP8oUoiOclk25xf8m98fCxoKa7GocrKhdcSGuMJoeeKJqdeQTrZ-XlEraKgWihGDME0g==&uniplatform=NZKPT&language=CHS', '瑞金_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1486, '报纸', '梁柏台', '', '人民日报', '人民日报', '梁柏台;中华苏维埃共和国临时中央政府;革命法庭;', '梁柏台，1899年9月生于浙江省新昌县，1918年考入浙江省立第一师范学校预科，1920年冬加入中国社会主义青年团，成为我国最早的青年团员之一。1921年，梁柏台和刘少奇、任弼时、肖劲光等人先后赴苏联，1922年进入莫斯科东方大学，同年底转为中国共产党党员。1924年毕业后，长期', '2006-01-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MiwJ8Y_alKWPhdADksh3r_9Q5BWRddco_uBgoAizb0l9fLDMY2mgJyLrdO0oTJfJiqD9Lnh3GMXVZ7y1VGOSDbuRiAJv948sugXRq8LfNGTE1CG4pTQAt33dXT_Etz4fc5evqi6FIdSg==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1491, '报纸', '湘鄂西苏区创建人 周逸群', '', '人民日报', '人民日报', '湘鄂西苏区;周逸群;创建人;', '周逸群是湘鄂西红军和苏区创建人，毕生为党工作，矢志不渝。他说：“只要我一天活着，我就一天不停止党的工作。”“我们共产党员，要像铁一样硬，钢一样强。”$$ 周逸群，1896年生，贵州铜仁县人。1919年赴日本留学。曾参加反对帝国主义、北洋军阀的爱国活动。1923年回国', '2005-03-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NZWxywNLHyrT-6ES6GqnmBEBNpzYImBW47NMz_cGZhmmDFJ5u191FADhGR1iidC5DJUdXjzaCDPB8c_LSVlOUHcG5CiYKJmlti-Im4610jomL_RD6vj1cq__ZVpKCRvgljK8R1EMIkkA==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1492, '报纸', '走近苏区', '', '本报采访组;', '中国财经报', '红军长征;李卫民;井冈山;', '$T“今日长征路”日记①$E$$ $T2004年7月25日，小雨。南昌──赣州$E$$ $F编者按$E  $T今年是红军开始二万五千里长征70周年。由于地理、历史、 文化等多方面的原因，红军当年途经之处，今天仍然是我国经济 较为落后的地方。当前，党中央、国务院高度重', '2004-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PCjWwUMmwGosrYZfF1G04bIPpHtDxXVw8MTMy4Yudz6NIcwO4wYKzObm07zDMn_fnvLC3H71TRBU7aKUi6JgsKC3HX6YuEIpGgmTxPxGhptuRpQDyZZa6xPxGwGwlyDfu8As3j2lKZLw==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1496, '报纸', '赣鄱涌廉潮', '景延安', '中国纪检监察报', '中国纪检监察报', '纪检监察机关;反腐败斗争;党风廉政;拒腐防变;', '春天的赣鄱大地，一派生 机盎然。$$  上井冈、下瑞金，记者在 江西采访时，经常能听到这样 一些催人奋进的话语：“江西 在中部地区崛起”、“富民兴 赣”、“建设美好江西”。$$  人心思进求发展，红色江 西正崛起。$$  同样', '2004-04-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MgdTebW0IEbGxK3uwU-nhfqVXY-Vf2nuqXtyvXfxVjbYISbx5oRi9oWv37cDPOW5jBLWSEOAidf4A0b73toMoGwPCtZxfxOoAIwxvpHTEuZ0LpDB_Q13Z-cerx1KxnAdF06ZsWIxR9xA==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1498, '报纸', '电影《心动岁月》感动红都人民', '苏丽萍', '光明日报', '光明日报', '《心动岁月》;', '本报瑞金3月31日电　作为纪念红军长征70周年系列活动的一个重头戏，电影《心动岁月》今日在江西瑞金首映。这部描述红军女战士英子长征途中坎坷经历的影片，深深打动了苏区人民，将人们的思绪带回到70年前的峥嵘岁月中。$$ 瑞金是红军两万五千里长征的出发地，瑞金人民', '2004-04-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NkHL_1K4Ys35T2sdJQn-GKHiOduJ0_DNAZ9gct8hDaSingBVa3Blhb9q41pnHcYk3xexOkDA-9E3H8OhSjSwAi6jMgXjhjM8KAgBCr7-1U39KvoUGaihy-ysXzfQJJNljrjVN1S0lp7g==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1500, '报纸', '赣南唱响新山歌', '庄殿君; 邬焕庆; 胡晓军; 蒋升阳', '“三个代表”在基层采访团;', '光明日报', '社区居民;', '在江西，人们把赣州市所辖18个县、市、区习惯地通称为“赣南”。赣南是著名革命老区，有着优良革命传统。赣南人爱把他们的所感所想化成脱口而出的山歌，一唱抒胸臆。$$ 金秋的9月，赣南的山水间山歌的旋律依旧婉转。但在这块红色的热土，人们却从许多新山歌中聆听出由古', '2003-09-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NChnw-5GhAP9-RQIqW5zuyYJTYpOagc6vaKjY7IWbeZiDgDABpVuXXn5Zjy_EP9TrPvt46DMLKi2t7gK3f8iwhKY4Tg_FFyQj9Ul4AOLxJHPzmuAllH8R9Ool3iYlwLV_ubjGXe8mokA==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1504, '报纸', '瑞金法院查明我国早期人民陪审员罗梓铭烈士生平', '严帆; 瑞法警', '人民法院报', '人民法院报', '罗梓铭;人民陪审员;', '本报讯 最高法院院长肖扬在江西省瑞金参观苏区最高法院旧址时，曾对苏区判决书上“陪审员罗梓铭”的落款很重视，专门询问其生平历史，指示瑞金法院要认真调查研究。时隔两年后，瑞金市法院经过一系列的调查考证之后，终于查实罗梓铭的真实身份和生平。$$ 今年１１月', '2002-12-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MnbrvmH6gmlmS0J2W46WlCeTJ3Y_NR3TIzhL2nmRbWKZYi-gCc2NdSoTTn5I5fT4jBcnAZHoRsBJ6Ev9Z14STDd6jbl-CzF1j2L9ikdfL_xnplr142lu9Tfq3PjH_zJ8uvfQszZsIRdw==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1507, '报纸', '中华苏维埃共和国山林水利局旧址修复工程动工', '邓浩亭', '中国水利报', '中国水利报', '中华苏维埃共和国;水利局;人民委员部;修复工程;', '本报讯　5月18日，中华苏维埃共和国土地人民委员部山林水利局旧址修复工程在江西瑞金破土，它将成为全国水利系统职工接受革命传统教育的基地。$$ 中华苏维埃共和国土地人民委员部山林水利局是主管苏区水利工作的专门机构，即中华人民共和国水利部的前身。它成立于1931', '2002-06-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OBl0b-JquJwA0muhKs63hJhg5ZtXcgEbmcQ4qPZRCk5Q_eoiePir_4_wSMgLCtvSkaUibwuHyR888csclYeNeRMWFBHLbly5HrEeC7fhVTpfQJmgl2bHZWCh8P3uWFxFbs0AcZ1DPbpQ==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1508, '报纸', '江西隆重纪念创建中央苏区红色政权七十周年', '刘文杰', '人民日报', '人民日报', '红色政权;中央苏区;中华苏维埃共和国;', '新华社南昌11月7日电（记者刘文 杰）江西省今天在瑞金市隆重举行中央革 命根据地创建暨中华苏维埃共和国临时中 央政府成立70周年纪念大会。江西省委书 记孟建柱、省长黄智权及中央各部委代表 近千人参加了纪念大会。$$  1929年1月，毛泽东', '2001-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MGxojrlu-vUlqcqMuQRULKmPbjAQ8nneixE0TEL4gPwhm3y862BTDZ5E_w0r4pn2YYrCbu5rNHmK9p8UaViNpLF5Uh4XRdLlkNFL_DotQRKaDdiOBNCEH_PBUJes5-CpZgWc5oU1kung==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1512, '报纸', '瑞金发现苏区《居住证》', '邓华; 胡晓军', '光明日报', '光明日报', '居住证;《居住证》;', '本报讯（通讯员邓华记者胡晓军）一张中华苏维埃共和 国时期的《居住证》日前在江西省瑞金市被发现。$$  《居住证》用毛边纸石印楷体印刷，通高19厘米，宽12厘 米。印有“江西省××县××区××村字第××号居住证”， 含“家长', '2001-07-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M2m_NkcXbuAvDKHjW0CwTfF8wOgSEHJQviaTUv7o5NSm5mvedYfLL4Qts51Q9gWUXkcufnzLpLC21hvlN6SN3oFGjoy7qugv8MoidERer8guyuZmTg-nP0ncbEuDSWga-9LV2dvneqww==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1515, '报纸', '弘扬光荣传统 坚定理想信念', '', '人民公安报', '人民公安报', '国家政治保卫局;政治保卫;严打整治斗争;理想信念;红色政权;中华苏维埃共和国;', '同志们：$$  在纪念中国共产党成立80周年 这一重要历史时刻，今天，我们在这 里隆重举行中华苏维埃共和国国家 政治保卫局旧址揭幕仪式。作为现任 公安部部长，我的心情十分激动！$$  1921年7月，中国共产党在上 海诞生，这是中国历', '2001-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pq25yBVW6ZJW8KJxy2JA4YDxfNDs-6FCpO8Cx3Pn_-WT17BPjUuh80nBsehrVygS1VREmJNdELSqHFZNZ3CwgcZ09Fp00RGLtE3fq30AIL1r0wIh6umtBnQMbOnVcdEpWMXSbaV5daPQ==&uniplatform=NZKPT&language=CHS', '瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1517, '报纸', '井冈山第一支部', '文洪英; 肖况', '农民日报', '农民日报', '井冈山;支部书记;毛泽覃;农村党支部;井冈山根据地;', '这是一个不应该被忘却的名字——乔林。 $$ 乔林是一个小山村的名字。 $$ 上了井冈山，由茨坪经黄洋界西行十余公里，一条弯弯曲曲的大山沟，便是乔林的地盘。像它的名字一样，这里漫山遍野都是高大茂密的林木。在大如房屋的石头旮旯里，散落着星星点点的田地。这里', '2001-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PmLBAVz9DLIEdSXBYjP-V8mkSfBTBv7ysVTRLwpPLcBCMdZNzcxheHzdBtAlcI-ucL1skW8Bt3_5XbMNu4x7dwZcsmOS5FJLqtoePdZz7-rQhoG90QX8o0MGPLmh2OUwe_BghaP-TEGQ==&uniplatform=NZKPT&language=CHS', '瑞金_screened,黄洋界_screened,茨坪_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1520, '报纸', '瑞金发现苏区党的机关报《斗争》', '曾海林; 瑞宣', '新华每日电讯', '新华每日电讯', '机关报;《斗争》;', '新华社南昌4月16日电（曾海林 瑞宣） 瑞金市象湖镇一个体户近日在废旧书籍中意外 地发现了一份珍贵的苏区革命历史文物── 中共苏区中央局创办的《斗争》刊物。$$  经当地党史专家鉴定，此期刊物出版于', '2001-04-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N1bHMmFR9PjL3mw7XkQ-tCKry2vcZ8Jzje8FMRkkq6lID6T3lIBbf15eJpjhA8yP2zUSM_rbGRfENK-vZ1wqjRB4stkWtUHiJH5Ba3nO8gWgiLg6HsMeEGb7VZbFuUILY7mpUePRBZgA==&uniplatform=NZKPT&language=CHS', '瑞金_screened');
INSERT INTO `ds_article` VALUES (1521, '报纸', '多彩永定 旅游带动乡村振兴', '刘圆圆', '人民政协报', '人民政协报', '客家文化;红色文化;土特产;', '福建省龙岩市永定区是著名的土楼之乡，2008年，福建土楼被列入《世界遗产名录》，藏在山林中的土楼渐渐被世人熟知；永定又是红色沃土，土地革命时期一条中央红色秘密交通线，被誉为“中华苏维埃的血脉”……近日，“点亮灵山秀水 共享美好生活”2023文化和旅游助力乡村振兴采', '2024-01-12 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2024.000245', '土地革命战争_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1523, '报纸', '千年犹江元造化 红色沃土踏新途', '季为民; 石健', '中国经营报', '中国经营报', '上犹县东山镇;定点帮扶;挂职干部;中国社会科学院;农村留守儿童;革命老区;乡村旅游;', '编者按/千年来，东坡吟咏、阳明教化，上犹因中华优秀传统文化而扬名。百年来，厚植红色、扎根老区，上犹因优秀革命老区文化而夺目。十年来，脱贫攻坚、乡村振兴，上犹因社会主义先进文化而发展。“三个文化”，即中华优秀传统文化、革命文化和社会主义先进文化。党的十八大以', '2023-07-10 08:00:00', 'https://link.cnki.net/doi/10.38300/n.cnki.nzgjy.2023.001482', '土地革命战争_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1524, '报纸', '相互融通 推陈出新：革命根据地史研究的总结与展望', '赵凡', '光明日报', '光明日报', '革命根据地;全球史;华北解放区;中国共产党领导;苏区时期;相互融通;', '编者按 从百年党史演进脉络来看，创建革命根据地、开展工农武装割据斗争，是中国共产党在第一次大革命失败后面对严峻形势作出的具有重大战略意义的历史抉择。在土地革命、抗日战争、解放战争等不同历史时期，党的根据地建设随具体革命实践而不断变化，在百年党史中意义重大', '2023-03-15 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.001255', '土地革命战争_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1526, '报纸', '走出新时代振兴发展新路', '高炳; 王永战', '人民日报', '人民日报', '革命老区;绿水青山;', '初夏时节的川陕革命老区，崇山峻岭间草木葳蕤。四川省巴中市通江县，川陕革命根据地红军烈士陵园里，不少人在瞻仰先烈。 “作为土地革命战争时期第二大苏区，川陕根据地背靠巴山南麓，俯瞰川东盆地，地势险要，兵强马壮，被毛泽东同志盛赞‘是扬子江南北两岸和中国南北两部', '2022-05-27 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.005458', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1527, '报纸', '绘就幸福民生新画卷', '赵青', '中国组织人事报', '中国组织人事报', '企业招工;技能提升;社保工作;巴中市;创业培训;', '清明时节，位于四川省巴中市通江县王坪村的川陕革命根据地红军烈士陵园迎来了一批批祭扫者。青山埋忠骨，松柏寄英魂，二万五千余名红军烈士安眠于此。土地革命战争时期，巴中作为川陕苏区的核心区域和首府所在地，为中国革命胜利作出了重要贡献和巨大牺牲。受资源禀赋、交通', '2022-05-10 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2022.001278', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1528, '报纸', '走好富民乡村振兴路', '叶小钟', '工人日报', '工人日报', '茶叶种植;雁南飞茶田;大埔县;振兴路;纪念园;', '1927年10月，三河坝战役在广东梅州打响；土地革命战争时期，在中国共产党的坚强领导下，梅州建立了东江苏维埃政府，成立了红十一军，开辟了著名的中央红色交通线…… 如今，梅州以苏区精神激发发展动力，利用政策红利盘活生态和文化资源，走好富民乡村振兴之路。 道路通畅', '2022-04-20 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2022.001779', '土地革命战争_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1529, '报纸', '赣闽粤原中央苏区：革命圣地的“变”与“进”', '龙跃梅; 谢开飞; 魏依晨', '科技日报', '科技日报', '中央苏区;福建三明;广东梅州;革命圣地;', '江西井冈山，神山村一步步蜕变，成了充满生机活力的村庄；福建三明，正全力向“中国稻种基地”进发；广东梅州，村民在家门口实现了就业创业…… 赣闽粤原中央苏区，是土地革命战争时期中国共产党创建的最大最重要的革命根据地，是人民共和国的摇篮和苏区精神的主要发源地，', '2022-04-18 08:00:00', 'https://link.cnki.net/doi/10.28502/n.cnki.nkjrb.2022.004665', '土地革命战争_screened,神山村_screened');
INSERT INTO `ds_article` VALUES (1534, '报纸', '弘扬大别山精神，把伟大事业奋力推向前进', '', '人民日报', '人民日报', '大别山精神;鄂豫皖苏区;', '了解历史，才能看得远；永葆初心，才能走得远。2019年9月，习近平总书记在河南考察时强调，“鄂豫皖苏区根据地是我们党的重要建党基地，焦裕禄精神、红旗渠精神、大别山精神等都是我们党的宝贵精神财富”，勉励广大党员、干部“在接受红色教育中守初心、担使命，把革命先烈为', '2021-11-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011599', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1537, '报纸', '不怕牺牲 依靠群众', '刘开雄', '新华社;', '新华每日电讯', '陕甘边革命根据地;依靠群众;照金精神;陕甘革命根据地;红二十六军;土地革命战争;陈家坡会议;刘志丹;王泰吉;谢子长;习近平总书记;', '20世纪30年代初，刘志丹、谢子长、习仲勋等老一辈革命家在极其艰难困苦的情况下，组建了中国工农红军第二十六军，成立了陕甘边特委和陕甘边革命委员会，创建了以照金为中心的陕甘边革命根据地。这是中国共产党在西北地区建立的第一个山区革命根据地，在革命和战斗的实践中铸', '2021-10-28 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008275', '土地革命战争_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1538, '报纸', '照金精神，写下光辉一页', '王乐文; 高炳', '人民日报', '人民日报', '照金精神;陕甘边革命根据地;中国工农红军;', '以照金为中心的陕甘边革命根据地，在中国革命史上写下了光辉的一页。要加强对革命根据地历史的研究，总结历史经验，更好发扬革命精神和优良作风。$$ ——摘自习近平总书记2015年2月14日在陕西考察时的重要讲话$$ 深秋时节，走进陕西省铜川市耀州区，穿行在革命老区照金镇的', '2021-10-27 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011293', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1539, '报纸', '坚持群众路线 传承照金精神', '青平', '中国青年报', '中国青年报', '照金精神;中国共产党人;陕甘边革命根据地;', '照金位于陕西耀县（今铜川市耀州区）西北部，上世纪30年代初，刘志丹、谢子长、习仲勋等革命领导人在这里发动群众打土豪、分粮分地，开展了一系列艰苦卓绝的武装斗争。他们最终以照金为中心创建了陕甘边革命根据地，这是中国共产党在极端艰苦条件下创建的西北地区第一个山区', '2021-10-25 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.003802', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1546, '报纸', '重庆城口革命法庭：巴山之巅上的红色司法足迹', '覃辉', '重庆市第二中级人民法院;', '人民法院报', '苏维埃革命;城口县;', '位于重庆最北端的城口县，居巴山之巅，据渝川陕三省门户，俯瞰巴蜀、控扼陕鄂。90年前的土地革命战争时期，我党无数革命先烈在此秦巴山区最高之地，创建了重庆市唯一成建制的革命老区，造就了城口县在重庆市的“三个第一”，第一个迎来中国工农红军主力部队的县、第一个被地', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.002939', '土地革命战争_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1549, '报纸', '传奇红安', '', '中国建设报', '中国建设报', '纪念园;七里坪镇;李先念故居;鄂豫皖苏区;红色旅游;革命传统教育基地;湖北省;黄麻起义;经典景区;全域旅游;大别山;红安绣活;', '红安,原名黄安,位于湖北省东北部、大别山南麓,是全国著名的老区县,也是住房和城乡建设部的定点帮扶县。$$ 这里打响了鄂豫皖地区武装反抗国民党反动统治的第一枪,诞生了 200多位共和国将军,更有红安14万英雄儿女为革命献出了宝贵生命。红安被誉为“中国第一将军县”。$$ 红', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.38299/n.cnki.nzgjs.2021.001635', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1550, '报纸', '传承弘扬大别山精神', '', '团结报', '团结报', '大别山精神;党的纪律建设;古田会议;毛泽东;中国共产党革命精神;无产阶级政党;马克思列宁主义;鄂豫皖革命根据地;传承弘扬;', '【编者按】$$ 从中国共产党诞生到1949年中华人民共和国成立，大别山“28年红旗不倒”，创造了中国革命历史的辉煌篇章，留下了丰厚的革命历史遗产。2019年9月，习近平总书记考察河南，提出鄂豫皖苏区根据地是我们党的重要建党基地，大别山精神是我们党的宝贵精神财富的重要论', '2021-04-29 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.000916', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1553, '报纸', '赣粤边游击区的女英雄', '何剑芳; 戴和杰', '江西省南昌市纪委监委;', '中国纪检监察报', '游击区;国民党军;女英雄;', '由苏区中央分局书记项英、中央政府办事处主任陈毅等领导的南方三年游击战争，是土地革命战争史上的光辉一页。它在主力红军长征后极其艰苦的条件下，树起了一面鲜红的战斗旗帜，牵制和消耗了国民党军的有生力量，保存了革命火种，发展了武装力量，锻造培育了大批骨干。$$ 赣', '2019-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MVEpgLh2DldClQkt3qNIXaNMmIngoPRWQloHy4D9gEKn6Rx1RviQ87TO75YIBWGNew4PEewmtNUh-NKBrcUx9DV6M_3Z0cb44ipp2rKTmv_zHj5H4slx9JkiH2LGRjdN0Cx_SkPSfOEw==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1554, '报纸', '南梁精神与群众领袖的人格魅力', '欧阳坚', '甘肃省政协;', '学习时报', '群众领袖;根据地;习仲勋;南梁精神;刘志丹;人格魅力;', '南梁精神是中华民族精神的重要组成部分。南梁精神的形成和发展，处处闪耀着群众领袖的革命风范、高尚品德和人格魅力。刘志丹、谢子长、习仲勋是南梁革命根据地人民群众爱戴和敬仰的群众领袖，南梁精神中闪烁着他们智慧的光芒和高尚的人格魅力。$$ 南梁精神是土地革命战争时', '2018-09-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MnTkbzcsq0MtMqzLDx-FQ4tD-lpkNaZm_vT2nlP5rfdCiwJ9TPe48RnkJQWO8udd2CXYTZe83uMzxgoaeHxAaNXXWMQp9OWtPRg92f0kXJLolpZZGgFFE7WkDXdlWa2JuKJPqAWkA99w==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1555, '报纸', '革命老区红色文化建设的启示', '隋云鹏', '山东省文化厅;', '中国文化报', '红色文化;马克思主义;', '党的十九大报告指出：“中国特色社会主义文化，源自于中华民族五千多年文明历史所孕育的中华优秀传统文化，熔铸于党领导人民在革命、建设、改革中创造的革命文化和社会主义先进文化，植根于中国特色社会主义伟大实践。”革命老区创造的革命文化对当前文化建设具有极其重要的', '2018-03-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OsAkQtB3zO_KyXIOH8nnqWy_BLs7nHJjBLEXaC_Ym-FLKyltb9FTgT1S_fkBq5O9jeVAEJdmGNJUvO5Y2V0BuUod6fkgma-7ulXemcmxYissZRC4BrqokpXm1QVSebRBTCbeq7G1KZHQ==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1557, '报纸', '道路自信在探索中诞生', '肖居孝', '中国井冈山干部学院办公厅;', '经济日报', '中央苏区;中国共产党;共产党人;秋收起义;中华苏维埃共和国;武装暴动;大革命失败;土地革命;武装起义;', '道路问题是关系党的事业兴衰成败第一位的问题，道路就是党的生命$$ 在中国共产党95年波澜壮阔的革命历程中，从开创井冈山革命根据地，到创建中央苏区，以毛泽东为代表的中国共产党人，谱写了中国共产党苦难辉煌革命战争史诗的绚丽篇章，奠定了中国共产党人道路自信的坚实基', '2016-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M9f0Fy312TG9RG4N_eVBumfdgYV_ZdTKxQ2ENnib7weVY4CHRa4Qyr0X7jiPBesCFyCkCT-qDD7nw0KT9P_e2qgqZLwiGdmfB1F474zbnWV21NuKBA-c9Wr-KoxL-GlO0Cx9fMR3WuuA==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened,瑞金_screened,苏维埃共和国_screened,秋收起义_screened,反围剿_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1561, '报纸', '坚持群众观点 弘扬求实精神', '尤权', '福建省委;', '中国纪检监察报', '才溪乡;毛泽东;求实精神;', '才溪乡调查是毛泽东同志在土地革命战争时期，革命形势十分严峻的背景下开展的一次著名的农村调查。当年的中央苏区模范乡才溪，毛泽东同志总共去了三次。1933年11月是第三次，那次调查耗时十多天，形成了《才溪乡调查》这一经典篇目，系统总结了才溪乡政权建设、扩大红军、经', '2013-10-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pf5pTEdO43s9_IhN-gMacnSaowl2WwrfiJnFrCfXMyPo71am9y-ben-ljxggPcM5UPslhVmJvrcTmpfpBptYNo2fnBqy6BJdJ10lDznbXS7fJnGCC9yAGDOHRM6_82OINyDvhmaAdXXw==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1562, '报纸', '弘扬深入基层调查研究的优良传统', '尤权', '中共福建省委;', '人民日报', '才溪乡;毛泽东;密切联系群众;优良传统;群众路线;', '习近平同志在河北调研指导工作时指出：“历史是最好的教科书。对我们共产党人来说，中国革命历史是最好的营养剂。多重温这些伟大历史，心中就会增加很多正能量。”今年是毛泽东同志开展才溪乡调查80周年。为纪念这一重要事件，福建省委召开专题座谈会，重温党的光辉历史，研', '2013-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ny5hFHJmlOXpyi_1kKk45jwQxt-xVtzpqLdW38NhuuUlm2weP9jn_jIxDnvGKZQ4S8b8z1jIHteMGmvLUmK36tW8YwWw28r9DmUWZPKU-vIjk0OD5Y1K2nJXuFyLsFz-taZKayhzD6bw==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1564, '报纸', '共和国不会忘记', '余孝忠 ; 陈建华 ; 林艳兴', '新华每日电讯', '新华每日电讯', '共和国不会忘记;原中央苏区;李建平;振兴发展;', '《国务院关于支持赣南等原中央苏区振兴发展的若干意见》,在中国共产党成立91周年前夕正式出台。$$ 沐浴着共和国的阳光,有着光荣革命历史传统的918万赣南苏区人民,再一次迎来历史性时刻。$$ 巨大的牺牲奉献:赣南人民土地革命时期的主题$$ 连日来,一部根据革', '2012-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MJpOcKQeZFUXpg1zcgEF70M3wnqZLOb3m-38dmD2Y2ZWXV4IM1NrUABb1GUbXqDPcMrA30p5jQuTlfZEXKoFTBzUVOnS1k2aSiu5dhax6wISdcN_sP06BvrkYxA9CSC1kL-g391eeykg==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1569, '报纸', '从第一个连党支部到强大的人民军队', '陆培法', '人民日报海外版', '人民日报海外版', '第一个;绝对领导;毛泽东;党支部;三湾改编;秋收起义;', '1927年秋天，毛泽东同志在江西永新县三湾村发展了６名党员并创立了全军第一个连队党支部，我军“支部建在连上”的历史由此开创。$$ 毛泽东亲手建立全军第一个连队党支部$$ 1975年10月1日，毛泽东向身边工作人员讲了一段故事。$$ 八一南昌起义之后，中国', '2011-05-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PDSKVZoepN1Yg9OaxUwi5WHpfjpLqj4g7nxWj5spSFC_iMqzypnCbMAr06rIGGvyEpl8wVfg8V-fkzvt0NdWi8qvY2chjlEXaNX5hjJWJfT3B_lhbWKw9v3f8UdgUZ8PlXcWmJU-L4Rg==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened,秋收起义_screened,农村包围城市、武装夺取政权_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (1574, '报纸', '红都瑞金的原则和精神是永存的', '郭兵', '江西省高级人民法院;', '人民法院报', '中国共产党;共产党人;毛泽东思想;马克思主义;中央苏区;中华苏维埃共和国;', '以瑞金为红都的中华苏维埃共和国，是中华人民共和国的雏形和基石，是建立人民民主政权的伟大尝试。是中国共产党精英荟萃之地，是中华民族大批有识之士和杰出人才的集散地。是毛泽东思想的主要发祥地。充分体现了新民主主义国家政权的特点。$$ 马克思、恩格斯指出，一切', '2010-04-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MWdMjR2ITpytOdNMB9qn1elrOovVFeJCVLl-W3TtTRvgxWkZeKtuiMmV6UZ7DxLeI6k8PABHqeOMZr4sV0z__EqJAO5RBzlcnPdzfIqvo-5iF6ern3BOakVQrdLbfJVfBfIh_VMhbwMw==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1575, '报纸', '碧血三河铸丰碑', '段琦; 周建明; 杨小刚', '解放军报', '解放军报', '三河坝;井冈山会师;大埔县;纪念碑;重点文物保护单位;', '三江涛壮，枪声激越，“八一”起义军在三河坝英勇抗击国民党反动派，在建军史上写下了光辉的一页；$$ 赤帜高扬，星火燎原，土地革命战争时期，老区儿女点燃革命烽火，不少村镇相继成立苏维埃政权；$$ 红星高照，山水迢递，途经青溪的红色交通线，曾经输送过大批革命精', '2009-11-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M50RlrU7NZxlxU6wG7sP52Pszt_vlQ8La58d_1mvMEdU7IIpJfu56TAcJgXvjwR1QG2TIr52QHuRCQ88C3_FnVyXB9cLmVITv7M5j17dJBDSMtKrNhpL7gT5qsIGEYnbWwgZ9vUlYipQ==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened,瑞金_screened,井冈山会师_screened');
INSERT INTO `ds_article` VALUES (1578, '报纸', '“模范兴国”续新篇', '代烽; 徐政武; 肖力民', '解放军报', '解放军报', '长冈乡;中国工农红军;兴国县;土地革命战争时期;', '江西兴国县，建县于三国，始称平阳县，宋太平兴国七年以年号得名至今，已有1700多年的历史。兴国的广为人知还是源自那段革命岁月：土地革命战争时期，只有23万人口的兴国县，参军参战的就达8万余人，5万多人牺牲，仅有名有姓的烈士就达23179名。二万五千里长征路上，平均每一', '2009-07-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PVvhVbbTwUrtzH1reLadkDYncl05NMBL2uepDrFCLnUxxMyDXMy2_m7XRGwEqNqokP4AB7XsdCse2-nsNQLQW_2MPdjok2kox1T5mfmALZv9Dt_nkLGsr3DnvObiuSfVwEyZvkKnu_2A==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1581, '报纸', '福建“三下乡”为农民送“精神年货”', '高建进', '光明日报', '光明日报', '“三下乡”;嵩溪镇;农民工;', '本报清流1月20日电　18日是农历小年,福建清流县嵩溪镇的群众过了个红红火火的“文化年”。该省2009年文化科技卫生“三下乡”活动日前在这里启动,近万名从四面八方赶来的乡亲们兴高采烈地挑选着自己急需的“精神年货”。 $$ 清流县是最早的土地革命战争时期21个苏区县之一', '2009-01-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MJmS0NfTpGCuqEfJqqlD4FhZXoMNKdhJ_PLc06rJAdbOG42Ycgt3YUoztThg4V6j1qL90EbMFA3T1IxpxS8rRvBru7CWGzTlDc95JOZMP49mQ3tLXGzT0Px2azaP7MT4_fWMIxXNTpRg==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1584, '报纸', '红四方面军发起四次进攻战役（上）', '', '人民日报', '人民日报', '红四方面军;国民党军;黄安战役;鄂豫皖苏区;', '红四方面军是土地革命战争时期，中国共产党领导的工农红军主力之一。１９３１年１１月７日，由鄂豫皖苏区的第４、第２５军在湖北省黄安县七里坪合编组成，徐向前任总指挥，陈昌浩任政治委员，全军近３万人。 $$ １９３１年９月，蒋介石在对中央苏区的第三次“围剿”失', '2006-08-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P_YBomPYnqQ9oDEC_YmEGjg8gRffHBD-98Rhm_fNRDx4Ng0k_lvtAZgmbPS4O1pPisJsdr80c1PmCm3ZgvmX9_4--zP9kpGvfJ1YwQc9CohoeEPskK_zJSdb27oGrWYwEcVvSYl3aKOw==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1585, '报纸', '红军的故乡 将军的摇篮 发展的沃土 和谐的家园', '', '农民日报', '农民日报', '鄂豫皖苏区;信阳市;红四方面军;红二十五军;', '扼两淮而控江汉，$$ 襟荆楚而屏中原；$$ 东西经济交融，南北文化荟萃。$$ 在中华人民共和国的版图上，豫鄂皖交界，江淮之间，有一片古老而又年轻的土地，它山水相伴，红绿相宜，这就是有“北国江南，江南北国”、“红军故乡，将军摇篮”之称的河南省信', '2006-01-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MUrTZddDXBCsTcBernn8bDXvgjNuJpxnNZTR-Ga4RPrMB791XYqNctKoNbOJvpCCXaNMDSttCOwPDiwyFP-LOsNQur3UGmSSmGWIPs3b0z0ZlVEtmd7Qm-EIJIPMrdEHtFh1IefngqYQ==&uniplatform=NZKPT&language=CHS', '土地革命战争_screened');
INSERT INTO `ds_article` VALUES (1592, '报纸', '弋阳：“红色+”机制唱响基层治理新乐章', '胡佳佳; 周军', '人民法院报', '人民法院报', '红色资源;家事调解;人民调解员;基层治理;司法为民;方志敏精神;巡回审判;', '江西弋阳，这片红色沃土，有名有姓的烈士就达9288名。闽浙皖赣苏区时期，以方志敏为代表的革命先烈，在这片红土地上创造了丰富的实践经验，为基层社会治理留下了宝贵财富。弋阳县人民法院利用得天独厚的红色资源，大力弘扬方志敏精神，通过构建“红色+”工作新机制，推动社会', '2023-09-04 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2023.002385', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1593, '报纸', '红色薪火汇聚精神星河', '吴思亮; 谢永平; 郭冬明', '解放军报', '解放军报', '省军区;红色资源;红色基因;', '江西，一片红色的热土，人民军队在这里创建，万里长征从这里出发。 “在党的二十大召开之年参军入伍，对我来说意义非凡。”在江西遂川县兵役服务站，革命后代邓鸿鹏说，他的太爷爷在井冈山革命斗争时期加入红军，他的爷爷也在新中国成立后光荣参军。最好的传承，就是沿着先', '2022-09-19 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.005076', '方志敏_screened,黄洋界_screened');
INSERT INTO `ds_article` VALUES (1594, '报纸', '挖掘红色资源培根铸魂', '瞿芃; 文子玉', '中国纪检监察报', '中国纪检监察报', '廉洁文化;纪检监察机关;红色资源;警示教育;江西省;赵醒侬;井冈山革命博物馆;', '“五一”假期，江西省井冈山市厦坪镇政府办公室主任周华睿头一件事就是参观井冈山革命博物馆。 “我是土生土长的井冈山人，从小听红色歌谣、革命故事长大，每次来这里都有新的收获。”周华睿告诉记者，利用休息时间参观井冈山革命博物馆、瞻仰北山革命烈士陵园，已成为他和', '2022-05-08 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.001873', '方志敏_screened,井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (1595, '报纸', '革命老区南平为什么能“红旗不倒”', '王盛泽', '福建省委党史方志办;', '学习时报', '革命根据地;党组织;陈昭礼;苏维埃模范省;方志敏;八七会议;农民暴动;福建省;革命老区;', '南平是福建省最早建党、最早举起武装斗争旗帜的地方之一，是“红旗不倒”的地方。南平俗称闽北，是一块红色圣地，这里书写了波澜壮阔的革命历史画卷，为中国革命的胜利作出了重大贡献。$$ 福建省最早建党、最早举起武装斗争旗帜的地方之一$$ 在五四运动的影响下，闽北的有', '2021-11-19 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002190', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1601, '报纸', '赓续老区精神 点燃新时代“星星之火”', '青平', '中国青年报', '中国青年报', '老区精神;革命老区;习近平总书记;方志敏;共产党人;求真务实;', '革命老区是党和人民军队的根，是中国人民选择中国共产党的历史见证。在中国革命的不同时期，老区人民为壮大革命力量、取得革命胜利付出了巨大牺牲，作出了重大贡献。老区人民对党无限忠诚、无比热爱。没有老区人民的棉袄、布鞋，就没有“打过长江去，解放全中国”的伟大胜利', '2021-11-08 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.003992', '方志敏_screened,瑞金_screened,苏维埃共和国_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1604, '报纸', '赣鄱大地的红色图谱', '李百灵', '中国文化报', '中国文化报', '美术创作;江西省;革命老区;方志敏;', '赣鄱大地处处镌刻着红色记忆：人民军队在这里创建，革命道路在这里开辟，万里长征从这里起步，工人运动奇迹在这里书写，伟大而不朽的井冈山精神、苏区精神、长征精神在这里铸就。江西这片红土圣地，到处红旗漫卷、红星闪闪、红歌嘹亮，红色故事口口相传。8月12日，由江西省文', '2021-08-22 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.002576', '方志敏_screened,井冈山会师_screened');
INSERT INTO `ds_article` VALUES (1605, '报纸', '永不熄灭的红色火种', '刘雪薇; 杨刚; 郭冬明', '中国国防报', '中国国防报', '三年游击战争;游击区;长岭会议;游击队;', '仲夏时节，一座庄重大气的红色新地标——南方红军三年游击战争纪念馆在江西省大余县开馆。这是全国首座、全面展示南方8省15个游击区三年游击战争光荣历史的红色基因库，是长征国家文化公园的重要组成部分。$$ 1934年10月，中央红军主力长征后，中共中央决定成立以项英为书记', '2021-08-19 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2021.001869', '方志敏_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1606, '报纸', '彭干臣：革命政权的第一位公安局长', '杨形涛', '人民公安报', '人民公安报', '彭干臣;第一位;革命政权;公安局长;', '1927年8月1日，南昌起义打响了中国共产党武装反抗国民党的第一枪，也打响了中国共产党建立建设警察队伍的第一枪。南昌起义中，中国共产党不仅接管了历史上的第一个公安局，也诞生了历史上的第一位公安局长——彭干臣。彭干臣，1899年出生于安徽省英山县（今属湖北省），1919', '2021-08-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OAu4RXCkWb-Uh2NhhyKcFqi9_ZAklttKBAYuQDYTi-3l4rKpGPRob748TNyfJoVe24QDH_d7CP4WV7s9WSjr1aSlI0BTN5WPu5g0Wz7CA78Cmd71ZgTlo7chc0Vc0jCQruNrVpu3DPMA==&uniplatform=NZKPT&language=CHS', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1609, '报纸', '苏区精神要永远铭记、世代传承', '', '人民日报', '人民日报', '苏区精神;共产党人;中华苏维埃共和国;红色政权;世代传承;', '老区、苏区的红土地孕育了革命，为中国人民的解放事业作出了巨大贡献。在革命根据地的创建和发展中，在建立红色政权、探索革命道路的实践中，无数革命先辈用鲜血和生命铸就了以坚定信念、求真务实、一心为民、清正廉洁、艰苦奋斗、争创一流、无私奉献等为主要内涵的苏区精神', '2021-07-26 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007711', '方志敏_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1611, '报纸', '精神之源 精神标识', '张晓松; 胡浩; 史竞男; 丁小溪; 高蕾; 王子铭; 刘硕', '新华社;', '新华每日电讯', '精神谱系;中国共产党成立;共产党人;人民幸福;', '编者按：在庆祝中国共产党成立100周年大会上，习近平总书记深刻指出：“一百年前，中国共产党的先驱们创建了中国共产党，形成了坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民的伟大建党精神，这是中国共产党的精神之源。”一百年来，中国', '2021-07-20 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.010217', '方志敏_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1612, '报纸', '江西：中部崛起勇争先', '廖斌; 谢文君', '金融时报', '金融时报', '生态文明;中部崛起;试验区建设;', '江西这片红色圣土浸染着无数革命烈士鲜血，孕育了伟大的井冈山精神、苏区精神、长征精神，承载着中国共产党人的初心使命。军旗在南昌升起，星星之火从井冈山燎原，共和国的伟大预演在瑞金启幕，二万五千里长征自于都出发，中国革命从这里走向胜利。$$ 2019年5月，习近平总书', '2021-06-29 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.003218', '方志敏_screened,瑞金_screened,神山村_screened');
INSERT INTO `ds_article` VALUES (1613, '报纸', '对党忠诚要做到九死而不悔', '毛强', '学习时报', '学习时报', '九死;党员;刘启;不悔;', '第五次反“围剿”失利后，红军开始长征。江西省苏维埃政府主席刘启耀奉命留守苏区打游击，并保管党组织活动经费，其中包括13根金条和大量银元首饰等。1935年，刘启耀在一场血战中率部突围，负伤后死里逃生，与上级失去联系。为了寻找组织，刘启耀背着金条等乞讨数年，历经千', '2021-06-21 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001090', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1615, '报纸', '可爱的中国 如您所愿', '赵美宁', '中国纪检监察报', '中国纪检监察报', '方志敏;革命根据地;共产党人;', '8月21日，是方志敏烈士诞辰120周年纪念日，为缅怀英烈，寻根溯源，更好地继承老一辈共产党人的初心和风范，记者采访了方志敏的长孙方华清，从其叙述中，我们能够感受到方志敏这位无产阶级革命家、政治家、军事家的一腔爱国之情。$$ 在采访中，方华清说，现在全党正在深入开', '2019-08-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NORS9MEVHptxXb-9CnS7q64DCPuN6qej16mGzpA4WLiMfNTSdYaOEK2rkiK699IefI3lCnFr6oaSyq33qzgpJ8wojlEwgi4qz9L9R9pOLMO8fYi1HbEUdeAAEOnYM3qTjpW54Ldb7u0Q==&uniplatform=NZKPT&language=CHS', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1616, '报纸', '铭记党史 不忘初心', '严琛', '安徽省宣城市委;组织部;', '学习时报', '方志敏;共产党人;全心全意为人民服务;', '习近平总书记指出，历史是最好的教科书，对中国共产党人来说，中国革命历史是最好的营养剂，党史是党执政兴国的根基与血脉。我们党95年的奋斗历程，是党的几代领导集体和各个时期党员干部进行革命、建设、改革事业的历史积淀，其中蕴含的最珍贵的智慧和力量就是中国共产党人', '2016-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NooXkwnbQyZju4lARxFIoJ6dKCfhmBqJqSw3d3palVR6mmcaE8HlNEoof8ztpUSSm8yDhdwUuuz_7GSDYqreHo3Je6Z59ms-wSYwg94bT7CZ_jR_prGNAkQvdfv7zxHDJ-oBid7ebpQQ==&uniplatform=NZKPT&language=CHS', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1617, '报纸', '弘扬方志敏精神', '马承祖', '江西省上饶市委;', '学习时报', '方志敏精神;共产党人;为人民谋利益;', '方志敏精神是指以方志敏同志为主要代表的中国共产党人，在带领赣东北地区的革命群众举行武装起义、开展土地革命、建立红色政权、创建赣东北和闽浙赣革命根据地实践过程中形成的革命精神。其内涵实质主要表现为爱国、创造、清贫、奉献的有机统一。今天，学习和弘扬方志敏精神', '2016-07-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MkxC_-pLSfaXVV9RVCdby0gMNcQLKWzB6RrsD5oebG9Qds5Gnpm2uLnTEIaKQd6WiK4JQdK6ppaIsS6WrwopI6yIraLSpNQGOHp1KVYrmwwzc_TPEcOuLGAQS1iptsRD6q7wlKFWDTHA==&uniplatform=NZKPT&language=CHS', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1620, '报纸', '方志敏精神的魅力来自何处', '董仚生', '中共江西上饶市委;', '光明日报', '方志敏精神;中央苏区;', '在迎接党的十八大召开之际,我们怀着感恩之心缅怀那些为国家兴亡、民族自强献出宝贵生命的革命先烈们。1935年8月6日,年仅36岁的方志敏英勇就义,他可歌可泣的事迹感人至深,他可赞可叹的信念让人敬佩——$$ 这些年来，我市坚持每年都召开方志敏及方志敏精神研讨会，举行纪念', '2012-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Mw82OYQSxduUHH-VKudXcNgCnu5-OJvDcB63CtIH4ZfoRRHn6XHBK5cki7gEO20ZQElyS3HFUEXnl2ciiAMv1k3WU4g43kL9Vqyk7GIRdS05gZPoB39A6IgVZILAi3qLecNQGYBZo5Mg==&uniplatform=NZKPT&language=CHS', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1624, '报纸', '安徽黟县箬笠岭乡村旅游项目通过专家评审', '凌云', '中国建设报', '中国建设报', '乡村旅游项目;专家评审;', '本报讯 安徽省黟县箬笠岭乡村旅游综合开发项目——柯村乡箬笠岭古徽道文化旅游项目，日前通过专家评审。 $$ 位于黟县西北部的柯村乡，是皖南第一个红色政权——皖南苏维埃所在地，有革命先辈方志敏同志率领北上抗日先遣队来到皖南红色苏区进行革命斗争指导苏区工作留', '2009-02-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PbmQJHVBGNaHy_KLaMQX1KHpgXKgQOkePZbx2h8vhkyuqj1R7nMSIvUttmmol3ivIjCAFYXsC4ezlqxEvDbgbvwQz5yhDdEdU_VeYF3ZwJmoOlYpEC0YABUs7GcJDbHSI9V4IJLp_1tw==&uniplatform=NZKPT&language=CHS', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1625, '报纸', '中国工农红军组成北上抗日先遣队', '', '人民日报', '人民日报', '北上抗日先遣队;中国工农红军;国民党军;中央苏区;刘畴西;乐少华;寻淮洲;闽浙赣苏区;', '１９３４年夏，日本帝国主义进一步扩大对华北的侵略，对中央苏区进行第五次大规模“围剿”的国民党军正以重兵向苏区腹地进攻。在此形势下，中共中央和中央革命军事委员会决定，以红７军团组成红军北上抗日先遣队，立即向闽、浙、皖、赣边出动，宣传我党的抗日主张，以推动全', '2006-10-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PPKBFfglI7gT0hrZJeoFjS61SLumn5eoaXeNWhPyVE_52qLkDtg5H43HQRrVZin8uF65ljmIPG1y_U6O7ROOKyerPIqpHYtR9fTm9Jcx83FHrION2KsWy0W5Cx9R-vtNGNFnOSHFx56A==&uniplatform=NZKPT&language=CHS', '方志敏_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1626, '报纸', '江西：反腐倡廉教育突出“红色经典”', '徐华平', '中国纪检监察报', '中国纪检监察报', '反腐倡廉教育;“红色经典”;', '本报讯 “苏区干部好作风，自带干粮 去办公……”优美动听的红色 经典歌曲《苏区干部好作风》 在“赣鄱清风”——优秀廉政 歌曲演唱会上唱起来，现场的 气氛感染了在场的每一位观 众。这是江西省充分发挥红色 教育资源优势，将红色经典', '2006-04-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MejbPHIt3n8rW21RKSWTMmAglnChBgu30BFm0JR_2e_i6y19UF1Bxu3cSVPvvu1Rdtase8e-f1foO9ydAWxMjnfWqG8hPhkUJUA9XhAKHpHH4YdLmlzudunGiz2Cw8cK9eCjTcs764DQ==&uniplatform=NZKPT&language=CHS', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1628, '报纸', '刘畴西', '', '人民日报', '人民日报', '刘畴西;北上抗日先遣队;中央根据地;', '在方志敏的狱中遗著《可爱的中国》一书中,多次记述了他的战友田寿的事迹。这位田寿就是中国工农红军第10军团军团长刘畴西。 刘畴西,1897年生,湖南长沙望城人。1920年考入湖南省立第一师范学校,同年冬加入中国社会主义青年团,1922年夏转入中国共产党。1924年5月考入黄埔军', '2006-04-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P6Eb7TS1zg8woP-npGDmVOoC0OEnhQbBu-3WyaLpCPTt4WAyNrYfqHKsxP1U-n24xrUBpGC1p4HSYr4s9alazedaoO6pcTjwxjcHluPbOJh2IjMEHmWRLrLuTLFiwGfJNr9lzOOSTBdg==&uniplatform=NZKPT&language=CHS', '方志敏_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1629, '报纸', '寻淮洲', '', '人民日报', '人民日报', '寻淮洲;中国工农红军;', '寻淮洲是中国工农红军高级指挥员。1912年生，湖南浏阳人。1927年加入中国共产主义青年团。同年9月随浏阳工农义勇队参加湘赣边界秋收起义，后随部队到井冈山，参加开辟井冈山革命根据地斗争。1928年转入中国共产党。先后任中国工农红军第4军排长、连长，参加井冈山革命根据地', '2006-02-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NeYbswyeztD2ijPmuFs2q3WJSvWYUuxtbIGE12NIpjn0G4SYip4wAQDrbqnl25AI98ESH2EZSAKLay1YE0BPNtt03Z5D8xye1S09S4nwNTV4cVkjF_jBj3XWV2i_zuZKLny1-h4Fg8Gg==&uniplatform=NZKPT&language=CHS', '方志敏_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1630, '报纸', '刘英', '', '人民日报', '人民日报', '浙南游击根据地;', '“幼时不知路，今日上坦途。赤心献革命，决然无返顾。”这是浙南游击根据地创建人刘英参加革命时写下的一首诗。在艰难困苦的革命斗争中，他以短暂而光辉的一生实践了献身革命的铮铮誓言。$$ 刘英，1905年生，江西瑞金人。1929年4月参加中国工农红军，同年9月加入中国', '2005-11-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OFhErRsrq1EOTC2H-eHhZBajpY5u8QgNUNIEKR26XZctHqVSxPz4POpUzavhVdhcy6nwM_95FuA-IpfMpO1wQMlkxOehALyfjQ5bQmyzmpl8YFJDeJGfuXXyicb-nPj9rAUXfVtQjiLQ==&uniplatform=NZKPT&language=CHS', '方志敏_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1632, '报纸', '伟大的共产主义战士 方志敏', '', '人民日报', '人民日报', '方志敏;共产主义战士;闽浙赣;', '“敌人只能砍下我们的头颅，决不能动摇我们的信仰！因为我们信仰的主义，乃是宇宙的真理！为着共产主义牺牲，为着苏维埃流血，那是我们十分情愿的啊！”$$ 当我们吟诵方志敏的不朽诗篇，无不为这位伟大的共产主义战士对党和革命事业的赤胆忠心而肃然起敬。$$ 方志', '2005-02-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PxNEZlHV_oVKFY_lmXkDrgFivfkyJhv8S5mzmk0Kvg-XR5csq7NCq4vXRTYfiGi3EGIl-64E8L-UXl9eG3HYzuOr56VP7G7HH8uVtM15ul5ZpH4Lghjr_0Z8yJSEVgvFvhjB-nMaMAGA==&uniplatform=NZKPT&language=CHS', '方志敏_screened');
INSERT INTO `ds_article` VALUES (1635, '报纸', '于都，永远的长征源头', '李聿锋; 张科进; 李怀坤', '解放军报', '解放军报', '于都县;第五次反“围剿”;《清平乐·会昌》;毛泽东;革命理想;中央红军;', '伟大长征精神，是中国共产党人及其领导的人民军队革命风范的生动反映，是中华民族自强不息的民族品格的集中展示，是以爱国主义为核心的民族精神的最高体现。$$ ——习近平$$ 细雨如丝、青山如黛，于都河水静静流淌。$$ 一阵唢呐声突然响起，一声声清脆悠扬的歌声随之传来', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004833', '十送红军_screened');
INSERT INTO `ds_article` VALUES (1636, '报纸', '理想信念的光辉永远明亮', '韩毓海', '北京大学习近平新时代中国特色社会主义思想研究院;', '中国纪检监察报', '理想信念;湘江战役;', '在人类历史上，还没有哪一批革命者面对过像长征这样的历史条件、客观环境：空前强大的敌人，悬殊的敌我力量对比，严重的“左倾”路线，严酷、恶劣的生存境遇。$$ 这一切历史条件、客观环境，就如同一堵无边高墙矗立在那里，它以铁一般的事实昭示着：长征，是理想信念的胜利', '2021-04-30 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.002015', '十送红军_screened');
INSERT INTO `ds_article` VALUES (1637, '报纸', '继承优良传统 弘扬清风正气', '徐华平; 陈新建', '中国纪检监察报', '中国纪检监察报', '廉政教育;红色资源;优良传统;反腐倡廉教育;', '这里是星星之火燃起的红土地，这里是红色革命的发祥地。$$  近年来，江西省纪委深入挖掘和充分利用红色资源，在全省大力开展以“弘扬红色传统，抵制黑色腐败”为主题的廉政教育活动，全省上下呈现出红色文化与廉政文化交相辉映、革命优良传统与反腐倡廉教育“同频共振', '2009-12-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N-BPyhO6iXuhZXRV6Q_O7bWVZZBcx7AMybYLYGxSxa5pdVNSr5GFQxbu8N8G1_bhLgZ8OdGRRHOx0KZ5EIPjbChChNeB2fh8v_Ycj88ao1dXaFUQ4lmjr4pp32tNDsuBpSiIOwQbPUWQ==&uniplatform=NZKPT&language=CHS', '十送红军_screened,方志敏_screened,瑞金_screened,井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (1642, '报纸', '朱正本与《十送红军》', '冯蕾', '光明日报', '光明日报', '《十送红军》;革命歌曲;', '中央电视台播放二十四集电视连续剧《长征》刚 刚告罄，贯穿全剧的音乐旋律正是四十年前创作的 革命歌曲《十送红军》。上了年纪的人回味起来，仍 觉历久弥新。$$  当年的曲作者朱正本先生，已经年过古稀。他 1949年7月参军，之后加入部队文工团。', '2001-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O88p8Zb9L7UmpfODRogZ0_WFfSLbpA0k9pBl41N_zRPXMr83A7tC4YQgX62kBF3RMHYk6tF1Ekg4CVyfQ5sapi5WcylXiGTEujvbiuqQ8f3qGMkUbMKOPGzsEupLjzJUj7fhASWjNWCA==&uniplatform=NZKPT&language=CHS', '十送红军_screened');
INSERT INTO `ds_article` VALUES (1643, '报纸', '从古田再出发', '李忠峰; 董丽娟', '中国财经报', '中国财经报', '才溪乡调查;毛泽东;中央苏区;中华苏维埃共和国;财政部;', '“红旗跃过汀江，直下龙岩上杭。收拾金瓯一片，分田分地真忙。”这是毛泽东早年在闽西写下的豪迈诗句。 闽西是全国较早建立的革命根据地，是中央苏区的重要组成部分，毛泽东、朱德、陈毅等老一辈无产阶级革命家曾在这里领导过革命斗争。 10月22日至28日，财政部党校第77期', '2023-11-11 08:00:00', 'https://link.cnki.net/doi/10.28053/n.cnki.nccjb.2023.002034', '闽西革命根据地_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1648, '报纸', '响应号召 不懈奋斗', '吉蕾蕾', '经济日报', '经济日报', '习近平总书记;', '7月1日，我参加了庆祝中国共产党成立100周年大会，现场聆听了习近平总书记重要讲话，非常激动。$$ 我的家乡福建省龙岩市是闽西革命根据地，是毛泽东同志写《星星之火，可以燎原》的地方，红色文化从小就滋养了我，教育引领我一路成长。党的百年历程告诉我们，每个人、每个企', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005037', '闽西革命根据地_screened');
INSERT INTO `ds_article` VALUES (1650, '报纸', '早康会议：奏响古田会议序曲', '李泉', '军事科学院军事历史和百科研究部;', '解放军报', '红四军;毛泽东;古田会议;古田镇;上杭县;', '记史$$ 1929年6月8日，中国共产党红四军前敌委员会扩大会议在福建省上杭县白砂镇早康村召开，史称早康会议，又称白砂会议。这次会议是在红四军党内关于前委与军委之争加剧的特殊背景下召开的。最终，在时任前委书记毛泽东的强烈坚持下，会议通过了取消临时军委的决定，从', '2014-10-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OrVJmi21x0DsnqCVO9H04u53NhzB7n3_Hfx7Wh407VSrLUos1iDIgUsCwy7gh0xjH7n38Vwzp-tmnN6rjv6y2Gy1KGajwpA9dFiHZOgTDD6RWe38zfdJYYKmI-cZeQY1yhfG-To4ksnQ==&uniplatform=NZKPT&language=CHS', '闽西革命根据地_screened,井冈山会师_screened');
INSERT INTO `ds_article` VALUES (1653, '报纸', '古田会议', '', '人民日报', '人民日报', '中国工农红军第四军;毛泽东;共产党;根据地;古田会议;红四军;', '１９２９年１２月２８日至２９日，中国工农红军第四军第九次党的代表大会即著名的古田会议，在福建省上杭县古田村召开。古田会议解决了如何把一支以农民为主要成分的军队建设成为共产党领导下的新型人民军队的问题，它所确定的着重从思想上建党和从政治上建军的原则，为后来', '2006-12-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P9TyJUEaAsnprZdD4MBFpVEAwUznXVi6l1RhROrY1ap186qyzXjsL_6AqoNunmtOsivtWPXgwqqwFsQKXzXEWemZbbrvlAcGXo8DrB8LMy16EggAIk0mO38mk9JQlH2eyIYZzkUoRy1A==&uniplatform=NZKPT&language=CHS', '闽西革命根据地_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1656, '报纸', '共绘宜居宜业和美乡村新画卷', '胡晓军; 王洋; 李玉兰', '光明日报', '光明日报', '寻乌县;脐橙种植;', '从江西赣州沿厦蓉、宁定高速公路往东南方向驱车约3小时，便到了武夷山与九连山余脉相交处的寻乌县，视线所及，层峦叠嶂，满目苍翠。 地处赣粤闽三省交界地的江西寻乌，是个山地占比75.62%的山区县。毛泽东同志在这里写下著名的《寻乌调查》和《反对本本主义》，给这里留下了', '2023-05-30 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.002478', '红四军_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1657, '报纸', '忆“井冈山的红杜鹃”', '陈姝', '中国妇女报;', '中国妇女报', '井冈山;中国妇女报;全媒体记者;吴仲廉;陈洪生;红杜鹃;宜章县;井冈山革命根据地;湘南起义;', '女红军，一个响亮的名字闪耀在中国革命史上。她们坚定理想信念，始终保持着对党和人民无限忠诚，书写了光辉璀璨的华章。日前，纪念井冈女红军彭儒同志诞辰110周年座谈会在北京召开。与会人员深情地回忆了彭儒一生的革命事迹。 追忆革命先辈，传承革命精神。彭儒的革命人生带', '2023-04-20 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2023.001329', '红四军_screened,朱毛会师_screened');
INSERT INTO `ds_article` VALUES (1660, '报纸', '走出大山的闽西青年又回来了', '田宏炜', '中青报;中青网;', '中国青年报', '武平县;', '把时钟拨回到2016年，当年轻人张勇决定回到福建武平县的农村老家创业做农副产品电商时，家里的长辈几乎没人支持他。 武平县地处闽西山区，是原革命老区县、中央苏区县。这里的民主乡高书村是1929年红四军入闽第一村。武平县人民政府县情概况的数据显示，该县共诞生了1位上将', '2022-04-20 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.001241', '红四军_screened');
INSERT INTO `ds_article` VALUES (1661, '报纸', '“模范兴国”的传奇“红色书院”', '戴浩; 胡锦武; 范帆', '新华每日电讯', '新华每日电讯', '书院文化;毛泽东;潋江书院;兴国县;', '在将军故里江西省兴国县，潋江水穿城而过，江畔的山坡之上，有一座潋江书院，学脉绵延百年，弦歌不绝。 自古以来，江西便以兴盛的书院文化闻名于世，白鹿洞书院、鹅湖书院、白鹭洲书院……一个个如雷贯耳的文化地标，在中国书院史上各领风骚。群星璀璨之下，仅有280余年历史', '2022-02-18 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.001328', '红四军_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1662, '报纸', '南粤古驿道：承载革命精神的红色之道', '谭志红', '中国文化报', '中国文化报', '古驿道;红色文化;', '走进广东省梅州市平远县的红四军纪念馆，参观者通过连环画、VR、场景全息影像等多媒体技术和铸铜圆雕复原以及人工智能控制系统弧幕投影、3D打印地形沙盘等沉浸式参观场景和互动式观展平台，重温当年枪林弹雨、战火纷飞的情景；穿行巷陌之间，红四军司令部旧址等革命遗迹修缮', '2022-02-15 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.000447', '红四军_screened');
INSERT INTO `ds_article` VALUES (1663, '报纸', '从起义部队成长为红色劲旅', '吴殿卿', '解放军报', '解放军报', '起义部队;赵博生;萧劲光;政工干部;红军学校;中华苏维埃共和国;古田会议决议;中国工农红军;董振堂;', '国民党第26路军在宁都起义当日，中革军委即决定，授予起义部队以“中国工农红军第5军团”番号。并由毛泽东、朱德分别以中华苏维埃共和国主席、中华苏维埃共和国革命军事委员会主席名义签发委任状，委任季振同为第5军团总指挥，董振堂为副总指挥兼第13军军长，赵博生为军团参', '2021-12-12 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007656', '红四军_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1664, '报纸', '马列主义在苏区的传播探究', '李媛; 范尊娟', '线装书局;首都师范大学;', '中国新闻出版广电报', '列宁主义;共产党人;马克思主义;共产国际;《红色中华》;马列著作;临时中央政府;《苏区工人》;《红星报》;《青年实话》;扩红运动;马列主义;革命根据地;苏维埃;武装斗争;', '马克思主义的伟大不仅在于其人民性与实践性，而且在于其科学性与彻底性。毛泽东等共产党人真正读懂了马克思主义，把马列主义基本原理运用到中国革命实践，才创造性地解决了中国革命一系列重大问题，发展了马克思主义，形成了马克思主义中国化成果：毛泽东思想。$$ 土地革命', '2021-12-07 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004790', '红四军_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1665, '报纸', '党在中央苏区时期的学习', '谢庐明', '赣南师范大学中央苏区研究中心;', '学习时报', '中央苏区时期;中华苏维埃共和国;临时中央政府;群众性;红军学校;干部学校;马克思主义理论教育;古田会议决议;苏维埃大学;政治建军;列宁室;', '中央苏区时期，以毛泽东同志为主要代表的中国共产党人高度重视学习，在建设马克思主义学习型政党的原则、方针、内容、方法、作风和制度等方面实践探索中积累了宝贵经验，形成了优良传统。$$ 一$$ 加强学习是思想建党及开辟中国革命新道路的必然要求。大革命失败后，中国共', '2021-11-24 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002230', '红四军_screened,闽西革命根据地_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1666, '报纸', '90年后，寻访绝密“红色交通线”', '邰晓安; 秦宏; 庞梦霞', '新华每日电讯', '新华每日电讯', '中央苏区;永定区;瞿秋白;周恩来;情报资料;', '这条线路由从上海出发，经香港，广东汕头、大埔，闽西永定、上杭、长汀，抵达目的地江西瑞金$$ 在这3000公里交通线上，交通员们日夜不停地传递信件、护送干部、输送物资进入苏区。据不完全统计，中央红色交通线共护送周恩来、瞿秋白、邓小平等200多位领导干部转移到中央苏区', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008784', '红四军_screened,闽西革命根据地_screened,瑞金_screened,苏维埃共和国_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1668, '报纸', '在纪念中央革命根据地创建暨中华苏维埃共和国成立90周年座谈会上的讲话', '王沪宁', '人民日报', '人民日报', '中央革命根据地;中华苏维埃共和国;习近平总书记;座谈会;', '同志们：$$ 在隆重庆祝中国共产党成立100周年和党史学习教育不断深入的热潮中，我们今天在这里举行座谈会，纪念中央革命根据地创建暨中华苏维埃共和国成立90周年，回顾党团结带领中国人民为实现新民主主义革命任务顽强奋斗的光辉历程，缅怀革命先辈和英烈的不朽业绩，弘扬党', '2021-11-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011595', '红四军_screened,闽西革命根据地_screened,方志敏_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened,秋收起义_screened,反围剿_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1669, '报纸', '江山石', '惠小勇; 吴晓颖; 尹恒', '新华每日电讯', '新华每日电讯', '烈士陵园;纪念碑;红四方面军;川陕苏区;川陕革命根据地;', '“您参加红军走时，风华正茂，青春刚好，而如今，儿孙满堂，其乐融融，遗憾的是您都没看到……您虽远离亲人家乡，却有二万五千多名战友日夜相守陪伴，您一定不会寂寞，他们大多都和您一样年轻，都是一个个鲜活的生命，为了千千万万劳苦大众的解放洒尽了最后一滴鲜血……”$$', '2021-09-10 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007149', '红四军_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1670, '报纸', '毛铭新印刷所为红色印刷服务', '毛伟先', '中国新闻出版广电报', '中国新闻出版广电报', '印刷所;印刷服务;印刷工人;印刷版;', '1927年9月，南昌起义部队途经福建长汀时帮助成立了中共长汀县支部。此后，毛铭新印刷所的毛钟鸣、毛如山和毛旭初兄弟与部分工人等10余人先后加入共产党，毛铭新印刷所成为地下党的秘密联络点。$$ 1929年3月，红四军首次入闽进入长汀县城。毛泽东同志对毛钟鸣说：“现在这个', '2021-08-18 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.003292', '红四军_screened');
INSERT INTO `ds_article` VALUES (1673, '报纸', '从“除名”到重生的红军医院', '周福志; 赵亮', '团结报', '团结报', '红军医院;古村落;古民居;周荣祥;文化遗存;红军学校;王永昌;民革党员;', '星星之火，从这里燎原。工农的武装，在这里集结。闽西，原中央苏区核心区，在这片红土地上，到处镌刻着红色的足迹和不灭的荣光。$$ 今年是中国共产党成立100周年。当开展中共党史学习教育的人们，走进福建龙岩上杭县蛟洋镇，在群山环绕之间、古树掩映之下，穿越一汪池塘，猛', '2021-07-27 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001577', '红四军_screened');
INSERT INTO `ds_article` VALUES (1677, '报纸', '罗福嶂村从党史中汲取振兴力量', '谭志红; 李昌战', '中国文化报', '中国文化报', '红四军;建档立卡;', '在粤赣闽三省交界处海拔1529.8米的项山，有一个神秘美丽又鲜为人知的村庄——罗福嶂。1929年2月，毛泽东、朱德率领中国工农红军第四军（简称“红四军”）在此召开罗福嶂会议，使其在百年党史上写下了光辉一页。在新发展阶段，红军当年割冰开路的精神让罗福嶂人在乡村振兴的道', '2021-06-29 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.001980', '红四军_screened');
INSERT INTO `ds_article` VALUES (1678, '报纸', '赤子情怀，遍撒山海之间', '袁猛', '人民公安报', '人民公安报', '公安民警;古田会议旧址;公安局;派出所;习近平总书记;下党乡;赤子情怀;', '挽住云河洗天青，闽山闽水物华新。$$ 3月22日至25日，习近平总书记在福建考察调研时动情地说：“这里的山山水水、一草一木，我深有感情。”$$ 6月的八闽大地，郁郁葱葱，生机盎然。中国工农红军闽东独立师展陈馆、毛泽东才溪乡调查旧址群、古田会议旧址……历经岁月冲刷，', '2021-06-26 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003610', '红四军_screened');
INSERT INTO `ds_article` VALUES (1679, '报纸', '红土地上日子越过越红火', '孙昌岳; 薛志伟', '经济日报', '经济日报', '革命老区;长汀县;武平县;习近平总书记;', '福建省龙岩市是全国著名革命老区、原中央苏区核心区，是红军的故乡、红军长征的重要出发地之一，享有“二十年红旗不倒”的美誉。红色基因早已深深根植于闽西人民的血脉。如今的革命老区人民生活得怎样？如何传承好红色基因、激发建功新时代的伟力？建党百年之际，经济日报记', '2021-05-19 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.004070', '红四军_screened');
INSERT INTO `ds_article` VALUES (1680, '报纸', '战斗 直到胜利', '陈贵平; 蒲江涛', '四川省通江县纪委监委;', '中国纪检监察报', '红三十军;红四方面军;', '2018年10月的一天，在四川省通江县王坪村的川陕革命根据地红军烈士陵园，汪烈山烈士的后人汪绪明一家从湖北省红安县赶到这里，他们长跪于汪烈山墓碑前痛哭失声。在汪烈山牺牲85年后，他的亲人终于得知他遗骸的埋葬之地。$$ 汪烈山，1904年出生于湖北省红安县檀树岗乡汪刘家', '2019-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ng8bsqJylquneva6MdF9VjDtNdluvIbRqKNEe_GR4yarSqSkTMTu_1ipmn-5rk83KJm4tN-9e6OvTwJGtQLos9-1zshkVvSC1d6alHrnnq8eCxG7CGlxQvwVzvJKY33JeEfFi0NLc1zA==&uniplatform=NZKPT&language=CHS', '红四军_screened');
INSERT INTO `ds_article` VALUES (1681, '报纸', '战争与和平，中国女兵从未远去', '党柏峰 ; 钱均鹏', '中国妇女报;中国女网;国防大学政治学院;', '中国妇女报', '女军人;张琴秋;战斗英雄;独立师;女性解放;黄埔军校;', '“向前进，向前进，战士的责任重，妇女的冤仇深，古有花木兰替父去从军，今有娘子军扛枪为人民”。中国共产党成立以后，从解放一切被压迫人民的立场出发，将妇女解放与民族独立和阶级解放紧密结合在一起。90年前的1927年8月1日，南昌城头一声枪响，标志着人民军队的正式诞生', '2017-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N_C1uB0oWT9LeQEXJCVqDFwPgkLzC5u5KusAHpYDt9Xl7B4ykGtEsLBG7XekayOR4DfgX9FhmXWKLtS4CDAScDfAX4MVeyliqOpRGDXs0_FQ2HVuv3y11QMjfgwOnGpF74S0IRpQFvSQ==&uniplatform=NZKPT&language=CHS', '红四军_screened,瑞金_screened,项英');
INSERT INTO `ds_article` VALUES (1685, '报纸', '体验井冈山精神的精髓', '谷春立', '中共辽宁省鞍山市委;', '学习时报', '井冈山精神;依靠群众;井冈山革命根据地;', '井冈山历史的体验$$ 井冈山革命斗争已过去80多年，但在中国井冈山干部学院进行体验式教学活动中，人们仿佛穿越时空，又回到那艰苦卓绝、轰轰烈烈的革命年代。$$ 其一，井冈山会师开辟了我党我军第一个革命根据地。1928年4月28日，毛泽东率领的秋收起义部队与朱', '2012-06-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OcQ8Zb3NScm2225rLOxknL3NYEdN87nRXDPc7-s-_OruXm2mYUbi5SdWmQvhs2pGxET95GuyAkVA6mkQ3lsiY0F2X_l-9i54kZkB-kRNrKTfYVGwiaiIZEUzwKWdHxFAwf4zEc_8wO8A==&uniplatform=NZKPT&language=CHS', '红四军_screened,瑞金_screened,黄洋界_screened,井冈山会师_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1687, '报纸', '才溪 穿越时空的光荣', '周铮 ; 李海涛', '农民日报', '农民日报', '光荣亭;中央苏区;穿越时空;', '才溪，这块热烈与厚重的红土地，革命薪火在代代相传!才溪人用无言的行动传承着才溪的精神，用骄人的业绩继续着才溪的光荣!$$ 才溪，一个著名的革命老区，一块厚重的红色土地，被毛泽东称赞为“全苏区第一个光荣的模范”。$$ 才溪，毛泽东思想的重要发祥地，毛泽东', '2011-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NTQ3Y_ocgJxIRta4S5ojyeNqPyCrwov0cyjk1Od-T_NesrqylpRyIR7D84ZwQQoi05HWuZfpN_iXHYK8sfvFP9s1SB4RdTnic4JC8KYXP5KuhH4vcwEMUBSbSOjWQMcERSkgBYDF31jg==&uniplatform=NZKPT&language=CHS', '红四军_screened,反围剿_screened,井冈山会师_screened');
INSERT INTO `ds_article` VALUES (1690, '报纸', '红色塘石踏歌行', '', '农民日报', '农民日报', '长冈乡;村民小组;新村建设;中国共产党;县委书记;', '塘石村位于江西兴国县长冈乡，因村口红石码头和村内18口池塘而得名。全村3000亩耕地，1310户人家，是赣南著名的革命村、英烈村、将军村和博士村。 1929年2月，中共兴国（临时）县委和赣南第一支正规红军江西红军独立第四团在该村成立。毛泽东在这里听《苏区干部好作风》、作', '2011-06-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P0Lk_qOu95c4PkzPkwnMuPuKFCiGuueGTNg2boIw_gDwlvH0x-dXO0uJcRQjThfx8W15FmExd5JoRrcwLyi8Z9RYzTpiaSPM1ahFcezlax9tgqdXju7fww84bSynBChr6FrYzSnqhKfg==&uniplatform=NZKPT&language=CHS', '红四军_screened,方志敏_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1692, '报纸', '长汀:“红色小上海”', '苏杰; 黄启元', '新华每日电讯', '新华每日电讯', '福音医院;红四军;小上海;中央苏区;中央红色医院;', '新华社福州5月17日专电(苏杰　黄启元)在中央苏区,闽西长汀由于经贸发达、市面繁荣,被誉为“红色小上海”。在这里诞生了中央苏区最大的一所医院；在这里红军第一次统一着装……长汀流传着许多红色财经故事。$$ 红军第一次统一着装$$ 在长汀县博物馆中央苏区“红色小', '2011-05-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NFrFneRXolXwVqinLIddyRxV6yi9cRwAM19VXYPYKWkTsM2KstuTP4q_T16whbvPYlj_rus9wlyNanV9xstfDOPzGWRATeSZDc2LLOM80nJWVsaf-knFRlmer6JF7hRutDzoZqCCK8Fw==&uniplatform=NZKPT&language=CHS', '红四军_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1693, '报纸', '红色永驻', '曹友华 ; 刘笑一 ; 杨欢 ; 宋歆', '解放军报', '解放军报', '株洲市;水口镇;炎陵县;红军标语;红色资源;党对军队的绝对领导;革命旧址;支部建在连上;', '湖南省株洲市是著名的革命老区，该市所辖的5个县市都曾是井冈山革命根据地或湘赣革命根据地的重要组成部分。踏上这片热土，会强烈感受到她的鲜明特色：红色永驻！$$ “坚持党对军队的绝对领导，是我军永远不变的军魂！”5月上旬，在修葺一新的株洲市炎陵县水口镇叶家祠，', '2011-05-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PbeLX4SIocJ1tRUTHoR3KEWbdzTo5S4UC-Eu2YacFNb1oXq1gb1tGaxNzh_5sWR5rM8Md61AC0p3RHPUBo8HcKDWCSsvd_XI1NEi9rOCU36xFG40r1mxyQHTbjw0YSy34F7f8HjokeBA==&uniplatform=NZKPT&language=CHS', '红四军_screened,王佐_screened,反围剿_screened,三湾改编_screened,张子清_screened');
INSERT INTO `ds_article` VALUES (1695, '报纸', '古田会议纪念馆', '', '中国纪检监察报', '中国纪检监察报', '古田会议纪念馆;古田会议会址;', '古田会议纪念馆坐落于福建省龙岩市，是以古田会议会址为依托建立起来的专题类纪念馆，始建于1964年，1972年兴建新馆。$$  古田会议纪念馆自成立以来，坚持高举革命传统教育的旗帜，高扬爱国主义主旋律，·学习实践科学发展观，全年免费向社会开放，累计接待观众近千万', '2010-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PacCXSlx5kRm28haoLumcHn9dPp8OGkl4j7zMN-xys0Iv8cILOYzCh-vQ9fuHB5o1jglJHPFwXGlCarDDzbv2v0uvIxheQ35zU4ECa52jupcdYpPS7ao1ABBesptBucFFwU_YNC_NxbQ==&uniplatform=NZKPT&language=CHS', '红四军_screened');
INSERT INTO `ds_article` VALUES (1699, '报纸', '井冈山,我们共有的精神家园', '刘津农', '工人日报', '工人日报', '井冈山;编辑记者;伍若兰;红色歌曲;', '红旗、火炬、红土，青山、翠竹、老表。$$ 8月22日，参加“江西老区行”的百名名编辑、名记者“千里来寻故地”，到达了向往已久的革命摇篮井冈山。一下火车，我们就感受到了井冈山的“特异”。$$ 放下行囊，未及喘口气，编辑记者们迫不及待地来到井冈山革命历史博物馆参', '2009-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P0kCvmqdEV_re5wjzmPwSwTVTE3YhjQYUsXEb0b31bx6IVFzb_H1ef7IxKlOXNKhoslVcW_ie8edr8R9AwH1nA65idpiwMjR4SvumSGVEwbBPoGmgMtULHUe4DeBf9ikrN74D-4igMqw==&uniplatform=NZKPT&language=CHS', '红四军_screened,十送红军_screened,瑞金_screened,黄洋界_screened,茨坪_screened,三湾改编_screened,朱毛会师_screened');
INSERT INTO `ds_article` VALUES (1701, '报纸', '凝聚不竭的精神力量', '朱竞若; 蒋升阳', '人民日报', '人民日报', '古田会议纪念馆;古田镇;红四军;精神力量;', '有些文字，可以贯穿岁月，唤起激情，鼓舞勇气，照亮方向！在共和国即将迎来六十华诞的时候，回望历史，依然可以感受到《星星之火，可以燎原》的蓬勃活力，它的落笔成篇，就在古田镇一间斗室里。$$ 有些文字，可以统一思想，凝聚意志，锻造灵魂，改变历史！来到古田，', '2009-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M2prLEOUwpoewRRicGZjusm1koUW2WAb38V1jGNKUFiGuSUbu7_7q1owUi2GU7uP-FSF4LM_v1OzSUaDfRAJwVeCa2CD-NYcpfJAr3h1bDmngqNTGAwQ5l1PBCyW_b25rlBrWnKXAbdA==&uniplatform=NZKPT&language=CHS', '红四军_screened,瑞金_screened,井冈山会师_screened');
INSERT INTO `ds_article` VALUES (1704, '报纸', '丰碑永载史册 精神光耀千秋', '刘源', '军事科学院政委;', '人民日报', '平江起义;一切从实际出发;红五军;滕代远;红四军;黄公略;井冈山革命根据地;彭德怀同志;', '今年7月22日，是著名的平江起义胜利80周年。80年前，在中国共产党的领导下，彭德怀、滕代远、黄公略等以大无畏的革命精神领导发动了平江起义。这是继南昌起义、秋收起义和广州起义之后一次重要的武装起义，是我党为开辟中国革命正确道路的又一次伟大实践，具有重大的历史意义', '2008-07-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Moba6qZngBUYkIbI8IsLkCIJAq63bfRKQUs7SPf3iXquKu10SnSklUzhV03l-jMEMAikqW2L94FNGnPSIHfV8dzZQTPgi6Vz59ooZs5hltLjHgJBIxjX6jKYg5zwirSVml0migdjHFXw==&uniplatform=NZKPT&language=CHS', '红四军_screened');
INSERT INTO `ds_article` VALUES (1705, '报纸', '江西东固红色旅游生机勃勃', '魏晓霞', '中国旅游报', '中国旅游报', '红色旅游;青原区;东固革命根据地;渼陂古村;', '本报讯（记者魏晓霞）记者日前从在京召开的东固革命根据地红色旅游发展座谈会上获悉：春节前夕，江西省吉安市青原区几处爱国主义教育基地———渼陂古村、红四军总部旧址、“二七”会议展览馆修缮一新，这些场所将成为革命传统教育、爱国主义教育和旅游观光的又一个好去处。$', '2008-01-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MsReUNwzau1-1x4er0ndGBj_a72dWDYQrYy445JeNjj9e8Xz2y72cNsCZREA4CEWW9yQkadDc8zq00mj_AFo5WH4DPt7ejtlvT4HXRnznSUBUbD52whdZUuEqoZIvleDF1lO0xJCcEZg==&uniplatform=NZKPT&language=CHS', '红四军_screened');
INSERT INTO `ds_article` VALUES (1706, '报纸', '扩大对外开放 加强区域协作 又好又快推进龙岩新一轮大发展', '雷春美; 张健', '中共龙岩市委;龙岩市人民政府;', '国际商报', '区域协作;又好又快;新一轮;海峡西岸经济区建设;', '龙岩位于福建西部、闽粤赣3省交界，通称闽西，是距离厦门最近的内陆邻海城市。1997年5月撤地设市，辖新罗区、漳平市和永定、上杭、武平、长汀、连城5县，面积1.9万平方公里，人口287万人。$$龙岩是革命圣地。闽西是当年中央苏区的重要组成部分，下辖7个县（市、区）', '2007-11-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MGl7noxvdF7fWaJQnsI6ZkcKUZku1jNw3JlU0e_gWaXoGzu4qkSvcncLIxGD8ycJzWy1NcTmVwm8W0u-Nz6WgNjfOxaIhLB9ZlT20rh88w4dMts-HiJNV3Qrg8JMP6xePg-ypkh-CAkA==&uniplatform=NZKPT&language=CHS', '红四军_screened');
INSERT INTO `ds_article` VALUES (1708, '报纸', '在纪念江华同志诞辰100周年座谈会上的发言', '蒋建国', '中共湖南省委;中共湖南省委宣传部;', '人民日报', '江华县;湘南特委;红三军团;红四军;工农红军;井冈山;毛泽东;座谈会;', '江华同志是从湖南省江华县的瑶族山乡成长起来的共产主义战士。１９０７年８月１日，他出生在江华县大石桥乡鹧鸪塘村一个虞姓瑶族农民家庭。全家人辛苦劳作，仍然入不敷出，难以维持生计。他从小感受到生活艰难，８岁就打柴放牛，参加劳动。１０岁以后，在乡村私塾、初级国民', '2007-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M-q2fa6En2NWmzuRo6jg-5lp7kV3Kpd1g88hC3QVQQyRXE492xceIPm-w0krOTwXId3jNEOxhyDVbKW5dlRbnq3GYyxn7UDKlWPWfz6FaLbh7-C6em_RDDgPa6q6tBjcvyoMyTvceEFA==&uniplatform=NZKPT&language=CHS', '红四军_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1709, '报纸', '中央革命根据地的创建和发展', '', '人民日报', '人民日报', '中央革命根据地;中华苏维埃共和国临时中央政府;闽西地区;', '中央革命根据地，亦称中央苏区，位于江西南部、福建西部，是土地革命战争时期全国最大的革命根据地，是全国苏维埃运动的中心区域，是中华苏维埃共和国党、政、军首脑机关所在地。$$ 中央革命根据地是以赣南、闽西两块根据地为基础创建的。$$ １９２７年１１月', '2006-12-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MHo4rsLf90zg7gfVuDai-C_yaQd6sn_4Qv5yuLhNTPt6w9cdTmMoRu3vPCbSZbX7Py7BiAPvk7t2yuXOQnFBnYJrTJKzFvxnA67MImDq-mYsYoJdIC6yJfAChuxeyxPonpWjcOAAKHiA==&uniplatform=NZKPT&language=CHS', '红四军_screened,闽西革命根据地_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1711, '报纸', '饮水思源 心系老区', '吴锦山; 许真学', '中国妇女报', '中国妇女报', '上杭县;', '在10月19日举行的福建省布料同业商会成立大会上，本报战略合作理事会副理事长吴秀冬女士等为革命老区捐款20万元。所捐款将转交给龙岩市上杭县，资助当地的老区建设。$$ 上杭县是全国著名的革命老区，1929年红四军第九次党代会即“古田会议”在该县古田镇召开；才溪乡是当', '2006-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OgnRPg8kB7yhn7L62AN2avfBRwUKU2usPMwUsjKuf9TeGDnPrCmtzViN9H9s4pmDLQZA73ldPBxlSH-b8sxVzWA98TBeY60-PHlxCkqvXRJ-DbwI5sjH2S0GIZTnO0-gram9YVTAldcg==&uniplatform=NZKPT&language=CHS', '红四军_screened');
INSERT INTO `ds_article` VALUES (1712, '报纸', '长汀打造红色闽西之旅', '史蔓蓉; 尺木', '福建记者站;', '中国旅游报', '客家文化;', '日前，由龙岩市政府、福建省旅游局主办，厦门市旅游局协办，长汀县政府承办的龙岩市第三届旅游节·长汀红土地文化节在美丽的历史文化名城———中国客家人大本营长汀隆重举行。来自广东、福建、江西等地的6000名游人，云集在当年中央苏区的“红色小上海”。在刚刚正式启用的', '2005-11-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MGTcAQzEkwLRCpZBOINu-5wR96qelRyr3_RCUqLafKHeH7XZ1JSNEJspy2PI9VYB7gwsYvNZLd7VhNayY8mzhUoxX05YLkA85guk55YhoxRXKTVkScBRboDJELCtu-VE1vkFJWmzdf8Q==&uniplatform=NZKPT&language=CHS', '红四军_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1713, '报纸', '在纪念中央革命根据地创建暨中华苏维埃共和国临时中央政府成立七十周年座谈会上的讲话', '胡锦涛', '新华每日电讯', '新华每日电讯', '中华苏维埃共和国临时中央政府;中央革命根据地;武装夺取政权;座谈会;', '同志们：$$  今天，我们在这里召开座谈会，纪念中央革 命根据地创建暨中华苏维埃共和国临时中央政 府成立七十周年，回顾我们党艰苦创业的光辉 历史，缅怀老一辈无产阶级革命家的不朽业绩， 重温党的优良传统和作风，很有意义。$$  我们', '2001-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Pdf3Pf8U2znO1EAAQWbp-G8LxnKOZ32U6EReHN5PhGU5oDxLLO9rCqZus_e4D5ZbdzD46nMmSPBwP9RlCxb6_1m3180WQCz7MPvImNLr-JORTN6UnrF3VJjs5XGlR208ewNVoGZ1UiGQ==&uniplatform=NZKPT&language=CHS', '红四军_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened,井冈山会师_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1716, '报纸', '上杭：红土地涌动旅游潮', '洪一树; 邱建柱; 钟华荣', '福建记者站;', '中国旅游报', '才溪乡;上杭县;红色旅游;红四军;', '“红旗越过汀江，直下龙岩 上杭”，写的正是第二次国内革命 战争时期的著名苏区──闽西上 杭县。毛泽东、朱德、陈毅等老 一辈无产阶级革命家曾在这里从 事革命实践，留下光辉足迹。 1929年12月底，毛泽东在上杭县 古田镇亲自主持召开了', '2001-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O7nXOJ9J8lHaRMml7JhZemzJypxg4RSyxphbFZcBckvYF4MrW4KBcXuUbX2ra2X64VI9a9AfAZDjETY3AaaOYd_BBbVhEqfh9OsxuqMOeB0QQNtvEN_wBWpRyVlWzCXtRiJSqz9nv5Xw==&uniplatform=NZKPT&language=CHS', '红四军_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1717, '报纸', '百年东华陂 丰收新盛景', '夏家祥; 温庆本', '中国水利报', '中国水利报', '灌溉面积;共产党;毛泽东;', '金秋时节，在江西省瑞金市叶坪镇东华陂灌区，新建的管道代替了原砌石渠道，汩汩水流源源不断地注入广袤田野，浇灌片片金色希望。 苏区第一陂 东华陂位于古城河下游区域，1932年，毛泽东率领当地军民筹得稻谷三担、银元三块，以杂木、松木为筋，黏土筑坝，建成东华陂。东华', '2023-11-02 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2023.002558', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1720, '报纸', '红土地“红”日子', '李文娣', '中国财经报', '中国财经报', '红土地;中央苏区;交通基础设施建设;纺织服装产业;永新县;脱贫户;乡村旅游;江西省;财政投入;纪念园;', '7月末，炎炎烈日下，青山绿水间，一抹抹红色格外亮眼——火红的“星星之火可以燎原”大字苍劲有力，在万绿丛中格外醒目；“胜利的号角”雕塑栩栩如生，嘹亮的号声似乎响彻大地；一盏盏路灯也都设计成火炬的样子，熊熊火焰喷薄欲出……这些特有的标志提醒记者，井冈山就要到了', '2022-08-30 08:00:00', 'https://link.cnki.net/doi/10.28053/n.cnki.nccjb.2022.001896', '叶坪_screened,瑞金_screened,神山村_screened');
INSERT INTO `ds_article` VALUES (1722, '报纸', '装点此关山 今朝更好看', '刘荣松', '检察日报', '检察日报', '青年干警;瑞金市;检察官;案件质量评查;检察院;', '“这里是红军的老家，喝一喝红井的清泉，看一看梦中的沙洲坝；亲亲瑞金，这里有最美的杜鹃花，听一听叶坪的故事，唱一唱红星映彩霞……” 身处人民检察制度起源地，江西省瑞金市检察院立足新时代基层检察院建设的新要求新任务，将苏区检察光荣传统镌刻在基因里、传承在办案', '2022-05-18 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2022.002168', '叶坪_screened,红四军_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1724, '报纸', '在江西赣州，听革命故事、忆红色历史', '郭媛媛', '全国政协;首都经贸大学文化与传播学院;', '人民政协报', '唐义贞;革命故事;江西赣州;', '对于红色土地，过去更多是从党史知识、教材书本上去进行主题把握、静态理解的。今年5月12日-18日，我获得了一个深入革命圣地贴近体会、感受的机会。跟随“学习百年党史 增进‘四个认同’”全国政协党外委员专题视察团，先后赴江西、贵州视察、调研。这次学习考察，在我的记忆', '2021-12-10 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.009332', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1725, '报纸', '90年前的苏区，这些“海归”干了哪些大事', '程迪; 李子健; 张欢', '新华每日电讯', '新华每日电讯', '苏区教育;中华苏维埃共和国宪法大纲;中央苏区;苏维埃政府;梁柏台;', '1931年11月，江西瑞金，中华苏维埃共和国临时中央政府宣告成立，中国共产党创建的红色政权首次以国家形态登上中国政治舞台。$$ 90年前，一群胸怀理想奔赴海外探寻救国之路的杰出知识青年，怀着共同的梦想来到中央苏区，为了挽救民族危亡，用所知所学开启建立一个新政权的伟', '2021-11-19 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008951', '叶坪_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1726, '报纸', '我军历史上的第一次阅兵', '章世森', '解放军报', '解放军报', '中国工农红军;红军战士;中华苏维埃共和国;第一次全国苏维埃代表大会;中央苏区;毛泽东;', '红一方面军连续粉碎国民党军第一、第二、第三次“围剿”后，赣南、闽西两块革命根据地连成了一片，中央苏区发展成为总面积5万多平方公里、人口达250多万的全国最大的苏区。在各根据地和红军不断发展的形势下，筹备了整整一年半、五易开幕时间的中华工农兵苏维埃第一次全国代', '2021-11-14 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007148', '叶坪_screened,方志敏_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1728, '报纸', '中华苏维埃共和国的故事', '胡昌勇', '中央党史和文献研究院;', '人民政协报', '中华苏维埃共和国;临时中央政府;中央执行委员会;中央苏区;一苏大会;苏区干部;', '90年前，1931年11月7日至20日，中华苏维埃第一次全国代表大会在江西瑞金召开，选举产生中华苏维埃共和国中央执行委员会，宣布成立中华苏维埃共和国临时中央政府。中华苏维埃共和国，这一中国历史上从未有过的新型全国性政权诞生了。这是一个什么样的政权？和今天有什么关联呢', '2021-11-11 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.008715', '叶坪_screened,方志敏_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1732, '报纸', '为党而歌，与人民同行', '赖星', '新华每日电讯', '新华每日电讯', '《红色中华》;中央苏区;红中社;苏维埃政权;梁柏台;临时中央政府;瞿秋白;列宁小学;', '1931年11月7日，她伴随着中华苏维埃共和国的成立而降生。从诞生之日起，她便为党而歌，与人民同行。$$ 她是新华通讯社的前身——红色中华通讯社。在中央苏区，新华社的先辈们谱写了她慷慨悲壮的红色序章，其中满是激扬的文字、奔腾的热血和不灭的信仰。$$ 90年的时光赋予了', '2021-11-05 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008564', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1733, '报纸', '艰苦卓绝写忠诚，一纸风行红土地', '卢刚; 强晓玲; 易艳刚; 胡锦武; 张博令; 邬慧颖', '新华每日电讯', '新华每日电讯', '《红色中华》;中央苏区;红军长征;临时中央政府;红中社;红色中华通讯社;工农群众;红土地;', '“我们需要我们的进攻，从新的小的部分的胜利，进一步变为很大的整个儿的一直到最后的胜利。$$ “在这种关头，所有觉悟的共产主义者，都应该对自己说：我们应该站在前面，领导其他同志到战线上去工作。”$$ 这是1935年1月21日《红色中华》报第264期头版头条《列宁的教训》', '2021-11-05 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008566', '叶坪_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1734, '报纸', '实践+创意，瑞金打造受欢迎的红色文创', '苏春生; 刘熙', '中国旅游报', '中国旅游报', '一苏大;红色文化;', '戴着“代表证”参加“一苏大会”，手捧“红井勺”体验“饮水思源”，玩着“小拼图”感悟“红都记忆”……日前，笔者在江西瑞金市共和国摇篮景区看到，许多游客排队在自动售卖机上购买自己喜欢的红色文创产品。“一件受欢迎的红色文创产品，必须有创意、会‘说话’，或向你‘', '2021-10-28 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.003079', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1735, '报纸', '赣州示范', '郑波; 赖永峰; 刘志奇; 沈慧; 祝伟; 刘兴; 朱双健', '经济日报', '经济日报', '赣州市委;革命老区;习近平总书记;粤港澳;赣南脐橙;经开区;', '赣州“厚重”，在于多彩。$$ 这里有红色的基因传承。中华苏维埃政权在此开启中国共产党治国理政伟大预演；中央红军在此集结踏上万里长征；苏区精神传承至今，“为人民谋幸福”的初心使命在此孕育成型。$$ 这里有绿色的生态底蕴。森林覆盖率高达76.3%，是我国南方地区重要生', '2021-09-24 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.006930', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1736, '报纸', '百年韶华 让科学走进人民', '王硕', '人民政协报', '人民政协报', '科普事业;科普创作;中国科普研究所;', '谁都无法否认，从中国共产党成立至今波澜壮阔的100年里，“科学”为中国的发展发挥了无与伦比的重要作用。新中国成立时，我国文盲率曾高达80%。$$ 1919年，毛泽东在《湘江评论》这样写道:“中国的四万万人，差不多有三万万九千万是迷信家。迷信鬼神，迷信物象，迷信命运，迷', '2021-09-23 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.007602', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1738, '报纸', '到瑞金中央印刷厂寻“根”', '张席贵', '中国新闻出版广电报', '中国新闻出版广电报', '中央印刷厂;印刷机;', '一台标有“江西民生工厂造”字样的印刷机，静静地陈列在中央印刷厂石印部旧址的一间房子里。在印刷机的台面上，摆放着一块斑驳的石板，《红色中华》字样的版面在石板上清晰可见。日前，在江西瑞金叶坪革命旧址群，《中国新闻出版广电报》记者深入学习了解我们党当年的印刷事', '2021-08-04 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.003080', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1739, '报纸', '风过沙背，花落禁山', '邓可诺', '江西省瑞金市检察院;', '检察日报', '红军长征;伤病员;烈士纪念碑;苏区时期;苏区干部;游击战;国民党;红军战士;反围剿;', '山茶怒放，弦月在天。深秋的细雨里，一支队伍，如同冷锋暗藏的箭镞，穿透苍茫的夜空……这是1934年10月10日，始于瑞金的长征出发。$$ 遥望星火拨亮的苍穹，中央苏区红军转移后的剪影，氤氲在绵延的丘陵之上，绕开宏大的叙事主题，却以微小的截面隐喻了红都人民对革命最后的', '2021-08-01 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.003810', '叶坪_screened,十送红军_screened,瑞金_screened,项英');
INSERT INTO `ds_article` VALUES (1741, '报纸', '历尽苦难 淬火成钢', '胡晓军; 马跃华; 周世祥', '光明日报', '光明日报', '中央苏区;中国特色社会主义建设;共产党人;习近平;党中央;寻乌调查;毛泽东;中华苏维埃共和国;红色政权;苏区干部好作风;中央革命根据地;临时中央政府;', '骄阳照耀下，一座正面造型如迎风飘扬旗帜的恢宏建筑巍然矗立，它的顶部，“人民共和国从这里走来”10个红色大字格外醒目。这里，是江西瑞金中央革命根据地纪念馆。$$ 今年“七一”前后，许多干部群众来到纪念馆前的广场上，升国旗、展党旗、唱红歌，开展丰富多彩的庆祝中国', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003842', '叶坪_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1742, '报纸', '苏区精神：永续传承的红色血脉', '曹溢', '中国纪检监察报', '中国纪检监察报', '苏区精神;共产党人;苏区干部好作风;中央苏区;', '瑞金中央革命根据地，共和国的摇篮。$$ 2019年5月，习近平总书记来到江西，深情缅怀党中央和中央红军在苏区浴血奋战的峥嵘岁月，专门看望了苏区的父老乡亲。习近平总书记动情地说：“井冈山精神和苏区精神，承载着中国共产党人的初心和使命，铸就了中国共产党的伟大革命精神', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003615', '叶坪_screened,方志敏_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1746, '报纸', '弘扬苏区精神 赓续红色血脉', '黄超; 沈童睿', '人民日报', '人民日报', '苏区精神;中央革命根据地;中国共产党人;中华苏维埃共和国;临时中央政府;', '在革命根据地的创建和发展中，在建立红色政权、探索革命道路的实践中，无数革命先辈用鲜血和生命铸就了以坚定信念、求真务实、一心为民、清正廉洁、艰苦奋斗、争创一流、无私奉献等为主要内涵的苏区精神。$$ ——摘自习近平同志在纪念中央革命根据地创建暨中华苏维埃共和国', '2021-07-26 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007729', '叶坪_screened,红四军_screened,方志敏_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1747, '报纸', '红土地上党旗飘', '邬慧颖', '新华每日电讯', '新华每日电讯', '“两新”组织;党支部;', '新华社南昌7月21日电（记者邬慧颖）江西赣州是一片承载中国共产党初心的红土地。在艰苦的革命岁月，苏区干部与工农群众一道“有盐同咸，无盐同淡”。党旗始终在红土地上飘扬。在新时期，赣州抓实抓细基层党建各项任务，坚持以高质量党建助力革命老区高质量发展。$$ 党建引领', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005600', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1748, '报纸', '红色故都精神永传 水利托起幸福瑞金', '温婷婷; 王子鹏; 盛晓晓; 钟建平', '中国水利报', '中国水利报', '苏区时期;叶坪镇;瑞金市;水利建设;小型水利工程;叶坪乡;', '瑞金，这个面积不到2 500平方公里的县级市，却有着“红色故都”“共和国摇篮”的美誉。这里蕴藏着红色中国的遗传密码和历史基因。当代中国的一切，都能在这里找到历史根源，水利也不例外。$$ 在这里，成立了苏区时期第一个领导水利建设的政府机构，中华苏维埃共和国山林水利', '2021-07-08 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2021.001098', '叶坪_screened,红四军_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1749, '报纸', '瑞金：红色故都孕育人民的司法', '姜佩杉', '人民法院报', '人民法院报', '何叔衡;中华苏维埃共和国;临时最高法庭;', '春夏交接时的赣南，有着北方人难以适应的湿润与炎热。但对于本地人来说，这种天气却承载着祖祖辈辈的悠远回忆。$$ 江西省瑞金市叶坪乡石岗村村民毛大香已经79岁，被太阳晒得黝黑的皮肤爬上了密密的皱纹。他记得父亲毛远富说，中华苏维埃共和国临时最高法庭主席何叔衡带着干', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003036', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1750, '报纸', '董必武：在苏区开创人民司法先河', '黄慕泽', '人民法院报', '人民法院报', '董必武;最高法院;苏维埃;人民司法;中央执行委员会;', '一张门板搭成的床，一张小木桌……在位于江西省瑞金市的中华苏维埃共和国最高法院旧址，记者看到董必武担任院长后的办公室。在这样艰苦的环境下，他工作了近一年时间。$$ “昔日红都迹尚留，公房简朴范千秋。叶坪沙坝遥相望，谒者频来总乐游。”1960年11月重返瑞金时，董必', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003064', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1753, '报纸', '心中有信仰 脚下有力量', '朱磊', '人民日报', '人民日报', '南昌起义;英雄精神;', '崇尚英雄、缅怀先烈，激扬英雄精神、砥砺家国情怀，让理想之光不灭、信念之火不熄$$ 从打响武装反抗第一枪的南昌，到燃起星星之火的井冈山；从建立第一个红色苏维埃政权的瑞金，到开始二万五千里长征的于都……走进江西，重温一段段可歌可泣的红色历史，内心总会被一种力量', '2021-04-09 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.003636', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1755, '报纸', '信念树长青', '李鹃', '中国纪检监察报', '中国纪检监察报', '叶坪乡;', '江西瑞金，叶坪乡黄沙村华屋小组后山上，17棵枝繁叶茂的松树连成一片，每棵树上钉有一块写着名字的小木牌。$$ 叶坪，中华苏维埃共和国临时中央政府所在地；华屋，远近闻名的红军村。$$ 1932年，只有43户人家的华屋积极支援革命，将村里仅有的17名青年送入红军队伍。1934年', '2021-03-22 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.001226', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1756, '报纸', '何叔衡与中央苏区依法治理的实践', '薛永毅', '西安交通大学法学院;', '人民法院报', '何叔衡;中央苏区;临时最高法庭;', '党的十九届四中全会强调，“坚持和完善中国特色社会主义制度，推进国家治理体系和治理能力现代化，是全党的一项重大战略任务。”回溯历史，倘若将中央苏区的法制建设放在国家治理体系不断演变的历史进程中去解读，其不仅有对“苏联模式”的本土化改造，更有着中国共产党人在', '2019-11-29 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2019.000136', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1757, '报纸', '不忘初心再出发', '邓逸楠', '江西省瑞金市人民法院;', '人民法院报', '何叔衡;中华苏维埃共和国;临时最高法庭;合龙乡;瑞金市;瑞金县;最高审判机关;', '在江西省瑞金市沙洲坝“红井”景区的核心区域，有一幢黛瓦黄墙的赣南客家风格的庭院格外引人注目，每天来此参观的游客络绎不绝。它，就是中华苏维埃共和国最高法院旧址。2010年8月，时任最高人民法院院长王胜俊来到这里参观后，欣然提笔写道：人民司法从这里走来。$$ 80多年', '2019-09-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MrTXjs0K_r6LtUgvUspvZymzfjbaYf9OAJhW5IksRvCTYyQJkI6p-dHvvJHdDmJLgBRGr60LQ_aW-n-1Po5XFoz_tWRaaiEGPhZtNAVfN6anL8stHToUl8HOYrNcm2FRwrvaGY5pvoJA==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1758, '报纸', '助力红色圣地“小康”梦', '谢靓', '人民政协报', '人民政协报', '政协常委;政协提案委员会;全面建成小康社会;原中央苏区;国家级经济技术开发区;移民搬迁;黄龙病;基础设施建设项目;科技城;', '初冬的赣南大地，青山掩映，脐橙飘香。$$ 82年前，长征队伍从这里出发，人民共和国从这里走来。而今，这个国家特级贫困地区正站在全面建成小康社会的新征程上，蓄势待发。$$ 由于历史、自然等原因，赣南等原中央苏区还有大量群众住着简陋的土坯房，走着崎岖的山路，面', '2016-12-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4P25JYFWLZCajcbEHrzwip1R8BvdIla-lM7hbmeBqmJYaMYP8siTmQ9evLBxCz6E8ALp8jAiUTN9cPioLMY4ZrhV6NTCcZpnpMZq_kW-L_xsoCJWvnxJJSgM9RDhbF4OnTsANnEwHlpRg==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1759, '报纸', '民主选举,用细节确保公正', '秦佩华', '人民日报', '人民日报', '代表候选人;叶坪乡;换届选举;流动票箱;人民代表大会代表;', '这里是人民代表大会制度的发源地，中华苏维埃第一次和第二次全国代表大会在这里召开；这里是闻名中外的红色故都、共和国摇篮，苏区时期苏维埃中央政府所在地——它就是江西瑞金。$$ 江西是新一轮县乡人大换届选举启动最早的地区之一，记者近日来到这里，采访了正在进', '2011-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OwTiNgKjvWSbLfbIBVPXZ2K6qsKE3zti_-icsYiKiMRf-9zs3x0GQTiEU_kD2IJfyohOkuwtPfUTV1Fmxrcpy5DVJoCcl2ziU8cDCC8h-7ePJK7p5jv2s32tHC3cHm24wiJeiuIjfFtw==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1761, '报纸', '中央苏区时期的经济建设', '鲍晓倩 ; 隋明梅', '经济日报', '经济日报', '经济建设;中央苏区时期;临时中央政府;', '1931年11月7日，中华苏维埃共和国临时中央政府在江西瑞金成立。1933年2月26日，苏维埃临时中央政府决定在中央、省、县三级设立国民经济部。人民委员会还先后在中央根据地召开两次经济建设大会。毛泽东在南部十七县大会上作题为《粉碎敌人五次“围剿”与苏维埃经济建设任务》', '2011-06-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MNGvPZ45ihfcMvtYzFsXXoTqN9Rp949Bop4ALxak1uxOHNq15pTB2PpY1MlVHlel9O7YCPwG2PnqkBqniEOvZcToayVp5rp7uasn7lK50AOSjUjytgLmuIFyidj-46rtIBoxp--rg6_Q==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1762, '报纸', '长征!长征!长征!', '甄澄; 胡晓军; 王斯敏; 姜建明', '光明日报', '光明日报', '瑞金县;刘南生;', '6月6日端午节，江西瑞金，雨后斜阳，象湖镇竹头下巷，家家户户门上插上了菖蒲。远处，高楼拔地而起，建筑工地一片繁忙。瑞金，曾经的中华苏维埃共和国首都，正深入对接海峡西岸经济区……$$ 巷子深处的一座小院，老红军刘家祁坐在轮椅上，笑着迎接远道而来的记者：“', '2011-06-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PnKrolsJQfmA_va9xauz2YAHruismS5Gys6UmHTCuTSLBO3fk1wCM-TkZj1vDxVcaHPg9lgSuz4_mMqYhPiaMg9QI_7jzagKB3NvdWA-cCbnlU8havur7t7qm09QLXnom3VBGPNwZxNA==&uniplatform=NZKPT&language=CHS', '叶坪_screened,红四军_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1765, '报纸', '苏区妇女精神薪火相传', '刘旭', '中国妇女报', '中国妇女报', '妇女生活改善委员会;中央苏区;', '开栏的话$$ 90载光荣岁月，90载光辉历程。在党的坚强领导下，广大妇女浴血奋战、顽强拼搏，在实现民族独立和人民解放，在推进社会主义革命和建设的同时，也走出了一条独具中国特色的妇女解放和发展之路。本报从今日起开辟“寻找红色巾帼的足迹”专栏，让我们循着前辈的足', '2011-05-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Mp9qfQKcIXHwtOc-RDzZCa0oWhuiQ7imfHxaLMTTQqvG5EQRQjSEaL0jPNRKMA5G-RtEbtvWoN7SpKKvAs7ePUOgAuJ7JwTTWLIcUZmbE3T5ySl_Rpym-_SSdWfF9UJPZ7tQo8gXjlPA==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1766, '报纸', '永远的“红色之都”', '张晓祺', '解放军报', '解放军报', '总装备部;', '从兴国到瑞金，有两个小时车程。对于一路上已习惯长途奔袭的我们而言，这点距离实在不算什么。远远地，一座城市呈现在眼前：红色的土地，红色的建筑，红色的星徽，辉映着她昨天的历史和今天的光荣。$$ 瑞金，因掘地得金而得名。“上海建党，开天辟地；南昌建军，惊天动地', '2011-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Olc-uudsjGKaaxHWVd7EbNLbvTTaKyjUXtLzqGn5zA3J8npN6Fz-AklPbiGlBsyY0ayWT_ofqr_5-1bXN1cCmHx5xqUgg9-QNOOcnPov9-4aNCcfFBA6JNn0IAVX1Y4yloyG4gT6VYkg==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1767, '报纸', '喜看瑞金新画卷', '鲍晓倩 ; 隋明梅 ; 赖永峰', '经济日报', '经济日报', '海峡西岸经济区;瑞金市;', '“吃水不忘挖井人，时刻想念毛主席。”在红都瑞金，几乎每个来沙洲坝红井参观的游人，在品尝完甘甜的红井水后，都会轻声念一念井边的这句碑文。$$ 瑞金缺水，当年，毛泽东率领红军战士为瑞金人民找水源，在沙洲坝打出这口甘甜清冽的红井。从此，瑞金告别饮用池塘水的历史；', '2011-04-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NLx3Dlz57D45l5bH5DMfPfriMl4lIVAKBengCCjup5Bpn7-qKYX6IdbMWQRBymBlUsGOVlIwPapdYYj-DW7lf31rTk2LAn1wMNrwIIim1-b06Jymob6Ua43enUNdv2axvZaPZ0X4ugvw==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1768, '报纸', '中央纪委监察部旧址', '', '中国纪检监察报', '中国纪检监察报', '中华苏维埃共和国临时中央政府;监察部;纪检监察;', '70多年前，毛泽东、朱德等老一辈无产阶级革命家带领工农群众，在江西瑞金创建了中国历史上第一个全国性的红色政权——中华苏维埃共和国临时中央政府，并分别成立了党和政府的监督机构，即中共中央党务委员会、中华苏维埃共和国临时中央政府工农检查委员会。中共中央党务委员', '2010-07-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N3V_XbxI8kXpIku9ct29V5I9xwC11bRU3mplzhWY9ZwuEbaiq8RbfpiLIVTir4ES-FGPt582YDGjDCaygBChoBCSgIDZM9FQAECCyJL01z6pHUuhsHql5EEi8kK6fTQBSV2pByF5EW-Q==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1769, '报纸', '全国工会系统革命传统教育基地揭牌仪式在江西瑞金举行', '梅柏林', '中国旅游报', '中国旅游报', '工会系统;执行局;中华全国总工会;革命传统教育基地;江西瑞金;', '本报讯（驻江西记者 梅柏林）5月24日上午，中华全国总工会苏区中央执行局旧址修复暨全国工会系统革命传统教育基地揭牌仪式在江西瑞金市隆重举行。中共中央政治局委员、全国人大常委会副委员长、中华全国总工会主席王兆国写来了贺信。$$ 王兆国在贺信中指出：修复中华', '2010-06-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OYV4jbsQiNPtVgsIcAneA-vfcMspnftPHojZZQ_gLKw6uiztIXIBSZ9khBXqKmTTLK5OPNgcW1l4xwgObRoctlmcc43U2u0tgN9pO0Kn-3GIbjHe2DIrH_62P-kkEoMMjf3BqEkxJNSA==&uniplatform=NZKPT&language=CHS', '叶坪_screened,土地革命战争_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1770, '报纸', '迎百年妇运 红都瑞金寻根', '赖翠红; 刘旭', '中国妇女报', '中国妇女报', '妇女生活改善委员会;中华苏维埃共和国;', '赖翠红 本报记者刘旭发自江西赣州 “这个活动真的很有教育意义，我觉得今后开展起妇女工作来也更有激情了。”在参观了红都瑞金的革命旧址群，尤其是中华苏维埃共和国妇女生活改善委员会后，江西会昌县“80后”的妇联主席邱华抑制不住内心的激动。$$ 今年是“三八”国际劳', '2010-01-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NIhsFR4CCwBopRpfz5wypxaPGP80Baf_cvLycWAynX7ywI4eNB01YbpTucML76_7rxfk8K4qJTzcMSyF8sEBOYeKgaDJqkqSBbE8tWkfiYMA73nN7NUmBf80ya1lxZedaPiAZXdRzmgw==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1771, '报纸', '从数据看瑞金的红色价值', '文艺橙', '光明日报', '光明日报', '革命传统教育;红色旅游;', '70多年前，共和国的开国将士和革命英烈们把不畏艰难、坚持真理的苏区精神留在了江西瑞金这片红色土地上；而今，带着对苏区精神的追念与坚守、传承与发扬，苏区人民携手社会各界，把对这英雄精神的颂歌唱到了北京——12月11日,随着第六次红都瑞金爱国主义教育基地联席会暨第三', '2009-12-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PqV06ksLr2Ipo2OreptIU-gMBWzN0M4ndJr_ptY9JvTEJ1hY6hQHbRgiVkMavedGjJ06DInodtdpOwtuyC5kmEELS3bb0WkpYSMyK1VvtmHrWswc1iWFZs2-Vzdd0lWojsMQuIdbpKPw==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1774, '报纸', '江西瑞金 红色文化助推地方经济', '姜建明; 胡晓军', '光明日报', '光明日报', '地方经济;红色文化;', '本报南昌6月16日电迄今为止,根据苏区时期“红都”瑞金沙洲坝杨氏八兄弟齐当红军真实故事改编的大型音乐报告剧《红都·生命的礼赞》,演出已达1200场(次),观众突破110万人,累计实现收入400多万元。 $$以《红都·生命的礼赞》为代表,红色文化这朵奇葩在江西瑞金结出丰硕经', '2007-06-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Ogn91kCfKAPRq2GYWHhgOjWcVTAVMp-icbZr6XkQAGisu3XO4CALuHuKlx5IBap8F-nRNsgkc-DP6f7Fe76fHpLBNxcDnsJ9ypeMUhoio7mh4cWLEvE1NmMFlUemnyvjfigXADpIBZ2Q==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1776, '报纸', '“红都”今日的“文教中心”', '胡晓军; 刘春春', '光明日报', '光明日报', '列宁小学;瑞金市;中华苏维埃共和国临时中央政府;各类教育;', '地处赣闽交界山区的瑞金，是客家人的聚集地，传统客家文化在这里渊远流长。有“红色故都”之称的瑞金，是当年中华苏维埃共和国临时中央政府所在地，红色中国的文教事业在这里初展风采。 $$ 在当年中华苏维埃共和国临时中央政府诞生地瑞金市叶坪乡，一座现代化校园吸引', '2006-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NMiW1nMurG4mCC01_hu0Ci0RpzpVp7ERt6ae7gaVUlzQHyM17YSJEazCwUj8_dp5pnePcjXuoXRIr-wMGwqSYzOemiv4A-ueK6ULbNnG1vD-lNMj2V_sao2_95LjwdMlpitfhHv8CUAA==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1777, '报纸', '瑞金曾经叫“瑞京”：你所不知道的红都往事', '贾永; 徐壮志; 胡锦武', '新华每日电讯', '新华每日电讯', '中华苏维埃共和国;中华苏维埃第一次全国代表大会;红色政权;中央苏区;一苏大会;', '1931年11月7日──十月革命14周年纪念日。这一天，中华苏维埃第一次全国代表大会在江西瑞金召开，标志着中国共产党人所创立的第一个全国性红色政权诞生。这，便是中华苏维埃共和国。 $$ 随着4年后雁阵惊寒季节的红军主力长征，红色苏维埃成为“马背上的共和国”。然而', '2006-08-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4Odu7k4ocp-r0-mduIizPXdWMyacv2I-7RB0gTUZbjDSABjBkxDjDk1t6wLVycSXedL2WJMLDz8BuU8cuzNZ79tYVjmvLEBIKT05r11Pti8MltQyTKjVwkxpcxK-f_Oc0LDrbUMSCWC0A==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1778, '报纸', '长征,一个在秘密酝酿中作出的抉择', '余孝忠; 陈春园; 沈洋', '新华每日电讯', '新华每日电讯', '中央苏区;于都县;中央红军;国民党军队;陈济棠;', '走进当年的中央苏区，走近红军长征出发前的那段历史，听听文史工作者的讲解，看看党史研究者的文献，越来越多的人们明白，长征虽然是一次被迫的突围转移，但并非是在敌人的飞机大炮面前，“左”倾冒险主义者仓促决定的。 $$ 正如伍修权在《我的历程》中所说，“这次战', '2006-08-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MrSXKKOOwtgfLiJesXQPz2TGcQ_Y5llmqU5YSjAIO0FrM64oOlPz5XhjlPeyF8FLIu5gUSOMZpn7HKnqiPkXjbU1F8T9hg2LwVSfce5BZqrMjeZojyoQIB8URiyTPlAUkTjA6SaU3lqw==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1780, '报纸', '赵博生', '', '人民日报', '人民日报', '宁都起义;国民党军;中国工农红军;', '赵博生是宁都起义主要领导人，中国工农红军高级指挥员。1897年出生于河北沧县东慈庄（今属黄骅市）。1917年毕业于保定陆军军官学校第6期，先后在皖系、直系、奉系军队中任职。1924年冬转入冯玉祥的西北军，任旅参谋长、特种兵旅旅长、军参谋长，参加过国共合作的北伐战争。期', '2006-02-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NPR8xsnZmu8cxftmBiOVxoNVhd0ovgVA86RpsuK392jr9qWwL_Pa2C1mJSURbnba5R0CHOJ0XkHllZz-f0h9FLsek29XR_dTF_7NOQmAkbt-B_MXrHiU9_COMXpMFnL6lflbbPaThhsQ==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1781, '报纸', '红土地涌动红色文化潮', '吴水弟; 胡晓军', '光明日报', '光明日报', '红色文化;红色文化资源;红色旅游;', '今年以来,江西省文化厅积极把红色文化资源优势转化为品牌优势,转化为服务群众、面向市场、经久不衰的精品力作,转化为代表先进文化前进方向的优秀文化作品。同时,创新红色文化题材的内容和形式,积极探索红色文化发展新路,以优秀的红色文化精品为龙头引领繁荣,实现优良的文化服', '2005-10-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OjGYhFepgjuFrbz7RKILx57giya8zghMSU0HofeTPiU6rYlC5qUajmqb2MlzbzCGGArOWOtYObGVE7fp6I5yX38yL78b_Z_Mn6pJH77riaiJJPEE05f9lTRoGgb6fE2ASW7ENb0TikXw==&uniplatform=NZKPT&language=CHS', '叶坪_screened,十送红军_screened,方志敏_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1782, '报纸', '全总在瑞金建立革命传统教育基地', '赵翔; 叶平川', '工人日报', '工人日报', '革命传统教育基地;中华全国总工会;', '本报讯（记者赵翔 通讯员叶平川）记者近日从江西省总工会有关方面获悉，经全国总工会批准，将瑞金市原全总中央执行局和全总苏区执行局旧址，列为全国工会系统革命传统教育基地，并适时在瑞金举行中华全国总工会苏区中央局旧址修复暨全国工会系统革命传统教育基地揭牌仪式。$$', '2004-05-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PIDjtWewgXaWUU2X4SP-gPXgEp80EKTkbH4aHTEsI8viN_j8rHb-3M8YNaC7BBh4i761v_bCNJYEUepxYLKxh8L6slfupthB4shfkQtAGB3y5qSUTj2r2gjHFhEx7dJHuH_B7Koj6J_w==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1783, '报纸', '江西瑞金发现中央苏区区级裁判部印章', '严帆', '人民法院报', '人民法院报', '中央苏区;中华苏维埃共和国;江西瑞金;', '本报讯 ４月２０日，江西省瑞金市人民法院研究室在本市叶坪乡黄沙村调研时，意外发现了一枚中央苏区时期福建省区级裁判部的印章，它对于研究我国早期红色司法审判史有着重要意义。$$ 经当地博物馆和党史专家鉴定，该章为樟木质，宽直径７厘米，厚２厘米，印文为“中华苏', '2004-05-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MUp6WeF_1V9YCNXbLQMgH2rN6AScpQDmvIfdpx_erj9LoE7itpK9BjVqpcV9g3d1_IMfs5G3iZSAjejTt5XPt4m-7dgKowianFEETVl1ZNplaGOWsf7Xr_Jw1TXgxFxQwW1S9LYdih6w==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1784, '报纸', '红土地上德育新篇', '姜建明; 王绍雄', '光明日报', '光明日报', '革命传统教育;老一辈无产阶级革命家;瑞金市;', '江西瑞金市是享誉中外的红色故都,毛泽东、周恩来、邓小平等老一辈无产阶级革命家都曾经在这里生活和战斗过,留下了光耀千古的苏区风范,记录下了许多闪耀着精神之光的红色经典。该市充分利用这些红色资源,在学校大力开展以革命传统教育为主的德育工作,以“苏区风范”正师、以“', '2004-04-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4O7NYeWWksWb4CtDXiSA1TLdFKv0Gwf8We37hv87zlp5a41ijJ0uP13mLeNJrDRaEen2KKbZSn6HY_KrfljnwdxLk022cfn2yey2silr0KfsveDHDsQCSEjC6J9p5RNho_sV4s4fP6qeg==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1785, '报纸', '江西 兴国又辟红色旅游新线 瑞金“红色旅游”激活经济', '姜建明', '人民日报海外版', '人民日报海外版', '红色旅游;红色旅游产业;', '本报讯 幽静的天然岩洞，绵延的红色山寨，崎岖的峭壁小道……昔日红军生活、战斗的红色大地，如今正成为兴国县得天独厚的红色旅游景观。$$ 革命老区江西省兴国县是全国著名的“将军县”，也是20世纪三十年代苏区革命的主战场。近年来，随着京九铁路的开通，越来越多的海', '2004-02-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N7VaZbqqZHb5McyZxOm7iCTP4WpelHiNSXBzANWPACbxTgi3gkExAzKnAFgG7OlHuyqW7YRAUXbC5MLJ0tApaHIM5g29x32a_UCAcrAucgXQuVuR5L7yT_Ulg_hBBa7AXdhrdwbr16CQ==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1786, '报纸', '爱民·为民·富民', '焦然; 刘思扬', '新华社;', '人民日报', '胡锦涛;中华苏维埃共和国临时中央政府;', '72年前，中国共产党领导人民建立的第一个红色政权———中华苏维埃共和国临时中央政府在江西瑞金诞生。$$ 72年来，中国共产党带领人民走出了一条前仆后继、开拓奋进的艰辛之路、创业之路、胜利之路。$$ 今年8月28日至9月1日，中共中央总书记、国家主席胡锦涛踏上江西这', '2003-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NQaY-ifiNcbKtl8muTQxXJ7BBjHab8cGN4EU90WIuBukkDyu2DKbYo9hLPA1jej-cHhiS8zA7Dhz0hOD2CNZtxHOLj_0eb9pMxK6hln_HB0xWqPwfn5c_oCji8uCv54u0IQ8bhbnqZqg==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1788, '报纸', '赣南老区成为红色旅游热线', '张秀峰; 罗璘; 王绍雄', '光明日报', '光明日报', '红色旅游;革命旧址;', '本报讯　江西省赣州市采取多种措施保护革命旧址群，楼台亭榭皆故事、水色山光有文章的赣南老区最近成了红色旅游热线，今年1到5月份全国各地到赣南接受革命传统教育和参加红色旅游的游客达160万人次。$$ 赣南是共和国的“摇篮”，是二万五千里长征的出发地，这里革命旧址', '2003-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OqH0IUmvBjSKfruZn5LyyVlx2IZj-cyzH9ggrXx21IHKvEYtybpA2QZbLu4t277cf5suxXz0M2G7xpDV0vBFhunca2NeUYyRFd98gJC2TyWlyJ_dX3W2v2jWVusUSEg7Oaun-qj57Z2A==&uniplatform=NZKPT&language=CHS', '叶坪_screened,十送红军_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1790, '报纸', '服务经济 再立新功', '梅建华', '中国质量报', '中国质量报', '李长江;中央苏区;', '本报讯 （特约记者梅建华）９月１６日至１９日，国家质检总局局长李长江率总局机关有关部门负责同志赴江西考察质检工作。他要求质检部门大力弘扬老区革命精神，扎扎实实做好质量监督检验检疫工作，为服务经济建设再立新功。$$ 在赣期间，李长江分别考察了江西省质量技监局', '2002-09-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N6eQpFILdFpo8NgXof_Wr8zDl6ZFUvvbFcwHzG4AfTCOETlGPEaqOriiwm35OfU7e9_biXv0Th4M0ovZwNCyKrfMXoXTuBZYR4dZEO_dQDO7JbDSkjx3Fl6wSx2CpLKAa-mdBujuBFMg==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1791, '报纸', '工农检察委员会旧址在瑞金揭幕', '肖玮; 周文英', '检察日报', '检察日报', '检察委员会;中华苏维埃共和国;', '本报瑞金10月29日电 （记者 肖玮 周文英 报道）在 中华苏维埃共和国临时中央 政府成立70周年前夕，中华 苏维埃共和国工农检察委员 会旧址揭幕仪式今天在红色 故都江西省瑞金市隆', '2001-10-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OdiBaL5Nd5_2-5_0XzozHBKbZ2ib8vJbDI40cUPJgLaz07sWcpJc9ZxKCRbIhBtAIzwXnZqqLXrc2SzfDgPQT6KzdI6laDlp6RhPIEA4AkSE-RdqQ-wiujVgzBbwfr1i3HTC7LYAMVTg==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1792, '报纸', '中央苏区大搞反腐廉政建设', '', '中华读书报', '中华读书报', '中央苏区;检举运动;反贪污浪费;临时中央政府;雩都县;官僚主义;反腐廉政;', '1931年11月，在江西瑞金建 立了中华苏维埃共和国临时中央 政府。在此前后，中央苏区所属省、 县、乡也建立了苏维埃政府。这是 中国共产党在政权建设方面的伟 大尝试。当时不仅在政权的组织建 设、民主制度建设和法制建设等方 面取得了丰', '2001-06-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OP-vH8xqyqh8fvvh48BthYgDN4mJ_13xyorEK7PU4vEpYrLy1q9PLMx8HLMzCGj_5A6MVlR087pVQiVR81q8Wnx1L8rRmD9lB6TU6THZFjFRrEwuqDutrlEhsoZqEfcBI4i3vFG53fzA==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1796, '报纸', '瑞金发现红军壁画群', '刘庆春; 刘文杰', '中国文化报', '中国文化报', '红军;瑞金;红都;壁画;', '本报讯：近日，江西瑞金市在未修 复的中华苏维埃共和国临时中央政府 教育部旧址的两间破房内发现罕见的红 军壁画群，引起当地史学研究者的浓厚 兴趣。$$  这个旧址位于瑞金市叶坪乡洋溪', '2001-05-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NtHcMAvycA6EPkjYvce9U5p8dXHC0tWmFRkMWPsG9M_AT2ahqhn6rPHKkFPiI1fjDsDvNxeneuTZmgCdKOCpA-Fbl-zBjRMP4kVak5vuEYJSqaYRsSJ98unZCZ4sTvzkUzZAh7TaCQ2A==&uniplatform=NZKPT&language=CHS', '叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1797, '报纸', '探访苏区治水足迹', '张元一', '中国水利报', '中国水利报', '中央苏区;水利部发展研究中心;水利史;', '1931年11月7日，赣南瑞金，谢家祠堂。一批来自五湖四海、风华正茂的人们庄严宣告中华苏维埃共和国临时中央政府成立！在这里，毛泽东同志带领广大军民修塘筑坝、车水抗旱、挖井解困、保护水土，开展了一系列的水利建设工作，创造了“六个第一”，开启了中国共产党带领广大人民', '2021-12-09 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2021.001944', '谢家祠堂_screened,十送红军_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1798, '报纸', '人民的江山', '沈锡权; 郭强; 赖星', '新华社;', '新华每日电讯', '中华苏维埃共和国;叶坪镇;一苏大;苏区干部好作风;临时中央政府;红色政权;中央革命根据地;中央苏区;', '1931年11月7日，赣南瑞金，谢家祠堂。$$ 一批来自五湖四海、风华正茂的人们，健步走进庄严的会场，宣告中华苏维埃共和国临时中央政府成立!中国共产党创建的红色政权首次以国家形态登上中国政治舞台。$$ 当夜，数万群众提灯游行、燃放焰火欢庆。$$ 中国历史上一个全新的政', '2021-11-10 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008619', '谢家祠堂_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1799, '报纸', '融入血脉的信仰，生生不息的力量', '赖星; 邬慧颖', '新华每日电讯', '新华每日电讯', '中国共产党;苏区干部好作风;马克思主义基本原理;', '新华社南昌7月29日电（记者赖星、邬慧颖）1921年，中国共产党的先驱们创建了中国共产党。10年后，以毛泽东为代表的共产党人在江西瑞金宣告中华苏维埃共和国临时中央政府成立，他们将未来中国的种子播种，开始了治国理政的伟大预演。$$ 从此，无数革命先辈用鲜血和生命铸就了', '2021-07-30 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005814', '谢家祠堂_screened,叶坪_screened,红四军_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1800, '报纸', '苏区精神照亮新时代奋斗路', '赖永峰; 刘兴', '经济日报', '经济日报', '苏区精神;中国共产党人;中央苏区;中央革命根据地;苏区干部好作风;中华苏维埃共和国;革命老区;临时中央政府;', '1927年大革命失败后，中国共产党逐步开辟了农村包围城市、武装夺取政权的中国特色革命道路。在寻找中国革命新道路而进行的艰苦探索中，中国共产党带领广大军民开辟了中央苏区和闽浙赣、鄂豫皖、陕甘边等10多块苏区根据地。其中，以江西瑞金为中心的中央革命根据地是最大、最', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005614', '谢家祠堂_screened,叶坪_screened,红四军_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1804, '报纸', '今朝更好看', '刘建林; 卞民德', '人民日报', '人民日报', '瑞金市;中华苏维埃共和国临时中央政府;红军长征;一苏大;', '瑞金，江西省东南边陲的一个小县城。80年前，毛泽东、朱德率领中国工农红军第四军的主力部队从井冈山转战赣南来到这里。1931年11月7日，中华苏维埃共和国临时中央政府在瑞金宣告成立，瑞金成为“赤色的首都”。从1929年到1934年，以瑞金为中心的中央苏区一共存续了5年零8个月', '2009-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PM2UuXWI8J3WrPBX5bfQfYlmIvSm5T7fP5eW1cpUVfxt5wu3ksA2-ux_dgrPZcSCFRxUzqv3IsI3TLKF8JKGAI2Cq47vpLY_-1BDoVXqGK-rD-omqsNeYy3EVUot8NwY2GBfXH16CXUQ==&uniplatform=NZKPT&language=CHS', '谢家祠堂_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1806, '报纸', '红色梦想从这里起步', '杨禹', '中国经济导报', '中国经济导报', '中华苏维埃共和国;根据地;粮食调剂局;国民经济部;', '$F开篇寄语$E$T在即将迎来中国共产党成立85周年和红军长征胜利70周年的时 候，缅怀革命先辈的伟大实践，回眸中国共产党在85年发展历程中的不断探索，总结 这一进程中的成败得失，是广大读者的共同愿望。这也有助于我们进一步加深对“三 个代表”重要思想的理解，', '2006-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MgZzKu31fETRiCUqLLH4tGpkvx77EZAMi_nw9UDjM_AxU8E_w7H9MWlBQ4NZZKjBjxDv5_FfbJhwSbSIBkpl45R-tNTyx2PmqfcCQCrCd3L8IXfFSt6_lZcv-Y_jpkn4FhuIrdV133QQ==&uniplatform=NZKPT&language=CHS', '谢家祠堂_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1807, '报纸', '红都溯源', '刘岚; 杨浙京', '人民法院报', '人民法院报', '临时最高法庭;中华苏维埃共和国;何叔衡;临时中央政府;', '匡庐俊美，鄱湖浩渺，井冈巍峨，赣水苍茫。山 奇水秀的江西，曾以“物华天宝、人杰地灵”享誉历 史；新民主主义革命时期，又以革命摇篮之名威震世 界。$$  五月的赣南，正是杜鹃落红，荷塘初绿。揣起一 颗朝圣的心，一', '2001-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OYE5moJMA7YwhqAUVgGJfOxLrqnS-DL8no1ICVm6eLntIhoeSjosDG6HHAExfX_xpQRlBX5U3wBFwLG6r8gyYi8sr9R2MVrZ0KF7HzSDvoJB9XftZSOp1Wf0trY-45MRz8ShU51LLQWA==&uniplatform=NZKPT&language=CHS', '谢家祠堂_screened,叶坪_screened,闽西革命根据地_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1809, '报纸', '智慧旅游爆款多 “沉浸+”频出圈', '王洋', '中国旅游报', '中国旅游报', '智慧旅游;沉浸式;中华优秀传统文化;大运河;', '泛舟600多年历史的北京亮马河上，在光影中领略风情水岸；步入扬州“5G大运河沉浸式体验馆”，开启一场奇妙的穿越之旅；身着古装夜上黄鹤楼，体验历史人文与光影演艺的时空碰撞…… 近日，文化和旅游部公布首批全国智慧旅游沉浸式体验新空间培育试点名单，24个项目入选，囊括', '2023-08-17 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2023.001830', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1810, '报纸', '长江国家文化公园建设稳步推进', '', '新华社;', '人民日报', '黄浦江;稳步推进;', '长江，我国第一大河流，造就了从巴山蜀水到江南水乡的千年文脉，是中华民族的代表性符号和中华文明的标志性象征。如何把长江文化保护好、传承好、弘扬好，延续历史文脉，坚定文化自信，建设中华民族现代文明，长江沿线省区市以长江国家文化公园建设为契机，生动作答这一时代', '2023-08-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.007816', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1811, '报纸', '《红色文物中的长征》：两年打磨让设想落地“掷地有声”', '范燕莹', '中国新闻出版广电报', '中国新闻出版广电报', '红色文物;《红色文物中的长征》;主题出版;', '两年前，广西人民出版社联合中国国家博物馆推出《红色文物中党的成长史》，它是一部以红色文物呈现中国共产党百年成长史的通俗党史读物。该书是“跟着红色文物学‘四史’”系列的首本图书。时隔两年，这一系列又添新作——《红色文物中的长征》出版。这成为广西人民社围绕“', '2023-07-10 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2023.002095', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1813, '报纸', '充分发挥文旅“黏合剂”作用', '王若辰; 薛园', '新华每日电讯', '新华每日电讯', '民族团结进步;中华民族;甘孜州;黏合剂;民族交往;', '“文旅是促进各民族交往交流交融的重要载体，也是实现民族地区长治久安和高质量发展的重要举措。”全国人大代表、四川省甘孜州州长冯发贵说。 甘孜州地处川、滇、藏、青交界处，是新中国成立后建立的第一个专区级少数民族自治州，藏、汉、彝、回、羌等41个民族在这里交往交', '2023-03-12 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.001432', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1814, '报纸', '杨朝明代表：中华文明史就是一部奋斗史', '司晋丽', '人民政协报', '人民政协报', '习近平总书记;中华文明史;奋斗史;', '2022年12月15日，习近平总书记在中央经济工作会议第一次全体会议指出，“什么时候没有困难？一个一个过，年年过、年年好、中华民族5000多年来都是这样。爬坡过坎，关键是提振信心。” “我特别认同总书记的话。能看见多远的过去，才能看清楚多远的未来。中华民族筚路蓝缕走', '2023-03-05 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2023.001327', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1815, '报纸', '中国交响 奏响时代强音', '任飞帆; 曹玲娟', '人民日报', '人民日报', '上海交响乐团;交响音乐;时代强音;', '核心阅读 交响乐已经在中国走过了一个世纪的发展历程，涌现出一批享誉世界的艺术家，创作了大量广为流传的经典曲目。进入新时代，中国交响乐工作者进一步坚定文化自信，扎根现实生活，走出一条具有中国气派、中国风格的交响之路。 近日，中国交响乐团发布2023音乐季，交响', '2023-01-05 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.000156', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1816, '报纸', '杜鹃草堂：短视频唱响侗族村寨巨变', '', '中国旅游报', '中国旅游报', '短视频;红军长征;杨少波;侗族村寨;', '湖南杜鹃草堂是通道转兵长征文化纪念地的延伸，近年来在景区建设、市场推广、带动村民致富等方面取得了成果。相对于纪念馆，这是一个开放的场景，时间、空间是对客人开放的，同时，草堂的创办者杨少波等人倾注了自己对长征历史、红色文化的热爱，所以参观者有较多的时间进行', '2022-11-15 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.003150', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1818, '报纸', '十年砥砺奋进 绘写壮美画卷', '任仲平', '人民日报', '人民日报', '习近平总书记;中华民族;人类命运共同体;中国经济社会发展;中国式现代化;', '（一）盼望着、奋斗着、创造着，举世瞩目的中国共产党第二十次全国代表大会就要胜利召开了。 多次见证重大历史时刻的天安门广场，花团锦簇、红旗招展；深圳莲花山公园里十年前种下的高山榕，亭亭如盖、枝繁叶茂；蓬勃生长的雄安新区，机械轰鸣、塔吊林立；翱翔寰宇的中国空', '2022-10-15 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.011236', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1820, '报纸', '致敬!“飞夺泸定桥般的救援”', '刘乐艺', '人民日报海外版', '人民日报海外版', '磨西镇;微信公众号;飞夺泸定桥;消防员;泸定县;救援人员;青岗坪;', '北京时间9月5日12时52分，四川省甘孜藏族自治州泸定县发生6.8级地震，震源深度16公里。截至记者发稿时，地震已造成70余人遇难。地震发生后，各方救援力量迅速集结，把抢救生命作为首要任务，争分夺秒，全力以赴。 一幕幕救援场景，令亿万网友动容：面对湍急的河水，特警队员', '2022-09-08 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2022.003019', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1821, '报纸', '一座千万人口大市的大思政实践', '王海涵; 王磊', '中青报;中青网;', '中国青年报', '大思政;马克思主义学院;思政课;阜阳市;王家坝;大学生创业;长征精神;人口大市;', '“我听过很多长征精神的阐释，也看过视频，可是没能激起太多感动，但当我刚刚戴上VR眼镜，看到战士在我身边倒下，怎么扶都扶不起来他的时候，我特别想哭……”讲着讲着，她哽咽了。 紧接着，这个女生回忆自己在虚拟世界里向死去战友脱帽敬礼的情形，那一刻，她的眼泪再也止', '2022-08-23 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.003020', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1823, '报纸', '四川冕宁：彝海结盟留佳话 红色旅游续传奇', '白骅', '中国旅游报', '中国旅游报', '彝海结盟;彝海结盟遗址;冕宁县;红色旅游;四川冕宁;', '四川省凉山彝族自治州冕宁县近日在成都市举办文化和旅游推介活动。其中，红色旅游的长足发展让人惊艳，成为这个革命老区县促进乡村振兴的全新“推进器”。 近年来，冕宁县委、县政府加快建设攀西地区创新驱动引领高质量发展示范县和安宁河谷综合开发示范县，高度重视文化和', '2022-06-29 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.001697', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1836, '报纸', '擦亮育人底色 用红色基因涵养时代新人', '吴琳; 杜佳', '光明日报', '光明日报', '党史学习;大连理工大学;时代新人;红色基因;', '“在观看的过程中几次忍不住流泪，为我们党百年来取得的伟大成就感到骄傲!作为青年党员，我要永远听党话、跟党走，不负青春韶华，不负时代重托!”大连理工大学经济管理学院研究生张雪在与学校师生近千人共同观看“庆祝中国共产党成立100周年大会”后动情地说道。 大连理工', '2021-11-25 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005971', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1848, '报纸', '中国加快国家文化公园建设', '陈振凯', '人民日报海外版', '人民日报海外版', '文化公园;大运河;公园建设;', '8月9日，一条重磅消息登上《人民日报》头版——《长城、大运河、长征国家文化公园建设保护规划出台》。消息还透露，要“加快推进”国家文化公园建设，黄河国家文化公园建设保护规划将“尽快印发”。 这一消息，让“国家文化公园”话题再度备受关注。长城、大运河、长征、', '2021-08-25 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002615', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1850, '报纸', '小世界与大世界', '张放', '解放军报', '解放军报', '地理信息;陈长捷;一张图;', '孙子曰：“知天知地，胜乃可全。”地图,作为“知地”的重要工具，在军事斗争中起着至关重要的作用。 《管子·地图》中专门论述了地图与军事行动及山川、地形、关隘、城池、地利之间的关系。秦汉以来的历次战争中，军事地图都得到充分运用。西汉初年，汉朝赴长沙国南部征伐', '2021-08-04 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004982', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1863, '报纸', '随影视剧赴一场红色之旅', '敖蓉', '经济日报', '经济日报', '影视剧;四行仓库;红色旅游地;原子城;红色旅游目的地;艺术化;红色之旅;', '《山海情》让宁夏“闽宁镇一日游”成为热线、《觉醒年代》剧迷们把6月29日修缮亮相的北大红楼列入了出游必选……今年的旅游潮主基调是红色的，众多反映中国共产党历史进程的优质影视剧集中热播，大众在观影的同时，也向往走入剧中人物所处的场景，沉浸式地了解那段筚路蓝缕的', '2021-07-03 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005064', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1864, '报纸', '牢记使命 再赴征程', '薛帅', '中国文化报', '中国文化报', '李大钊;飞夺泸定桥;开国大典;习近平总书记;', '奥林匹克森林公园以南，龙形水系旁，一座新时代的红色地标拔地而起，气势恢宏。世人翘首以盼，这座以中国共产党党史为主线、全景式展示中国共产党矢志不渝奋斗之路的永久性展馆，随着首展“‘不忘初心、牢记使命’中国共产党历史展览”的开幕，迎来期待和仰慕的参观者。', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.002079', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1868, '报纸', '昆曲艺术，在传承中创新', '杨凤一; 曹雪盟', '北方昆曲剧院;', '人民日报', '昆曲艺术;北方昆曲剧院;时代进步;', '把握时代进步的要求，聚焦人民群众的期待，以饱满的热情、独特的视角、卓越的手法、个性的表达点亮观众和创作者心灵的明灯 如何创作文艺精品，如何为时代汇聚强大的精神动力，如何把最好的精神食粮奉献给人民，应是每位新时代文艺工作者不断探索和实践的课题。 昆曲艺', '2021-03-23 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.002898', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1872, '报纸', '90年历史告诉我们什么', '', '解放军报', '解放军报', '红色基因;人民军队;听党指挥;', '首都北京，军事博物馆，人民军队最早的那面军旗格外引人注目。这件“镇馆之宝”，几十年来令亿万观众驻足、凝视、沉思。从1927到2017，人民军队走过了90年的光辉历程。90年时空流转，变幻的是沧海桑田，不变的是血脉基因。人民军队在淬炼红色基因中不断成长壮大，也必将在赓', '2017-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB5FGEjEMC3lQV8jm_zA3-e6j_ZXvoFT9_qaKIPXGNoBlPTWFVfzzn65SeWDbIx-UhZzmEwuB_P2R_gkgJnpCWfERVYhCqsX7I9ycuQHvDRvEP9EzYQX4fWD9hgyhO9xaOPjRs7YmMrTA==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1873, '报纸', '重大历史题材创作的当代探索', '施晓琴', '中国文化报', '中国文化报', '历史题材;中国工农红军长征;长征精神;馆藏作品;中央美院;', '80年前，中国工农红军完成的那场伟大远征，创造了人类历史上无与伦比的革命壮举，而长征也成为我国文艺创作中独特而重要的题材。2016年是红军长征胜利80周年，为了进一步弘扬伟大的长征精神，引领广大观众重温历史、关注当下，美术界无论是博物馆、美术馆等典藏机构，还是画', '2016-12-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB-LkpNxZIm7JX_WVHLF1vH1_Q2Z5VYnOvDuYn7hvzLYQg-S7JpVLgAsAa_Cz-1WbM1nieiHVyuMc61gnuKK2FREX-I2zW4OAvjOEl-RbIaZKYLW1NkJsUbHIlHynVpA4GJxgLscSRDeQ==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1881, '报纸', '大力弘扬伟大长征精神', '', '光明日报', '光明日报', '长征精神;哈里森;', '“这一惊天动地的革命壮举，是中国共产党和红军谱写的壮丽史诗，是中华民族伟大复兴历史进程中的巍峨丰碑。”80年前，中国共产党领导工农红军历经二万五千里长征创造了历史；80年后的今天，我们回望那段苦难与辉煌，纪念这一伟大远征。在21日召开的纪念红军长征胜利80周年大', '2016-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBH5r3e4LpFjJdQLRMFfeNe2FHM66DcVos0KaEGK4s-j4ue1A67CulfD0llCJNzbZekPQViSvwUeEoD6xTBSXUhNQExXYJBdaj3ACeeTWMnpndFoOUqs3-9mP6B6F1QgzyTrePU7X4oJg==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1891, '报纸', '今天，我们如何讲述长征故事', '戴清', '中国文艺评论家协会;', '光明日报', '长征故事;《飞夺泸定桥》;', '八十年多前的红军两万五千里长征是举世瞩目的伟大壮举，是让后人追缅敬仰、让一代代创作者不断走近深入的艺术富矿。新中国成立以后，各种艺术门类围绕长征发挥着自己的优长，抒写了各类长征故事。许多艺术作品为人们耳熟能详，也伴随着几代人的青春记忆，自然而然地内化为一', '2016-10-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAtG0yImjWZUeeSjz0aGWs_cINwMIo6V9Y2YRC997sH7o4oz08ybHCPaeJQsdu-sp391XQMwr_o7Zy7tIIZrMuv2qanf-K1zB_a6goU6dsRhiclDvx6I3q-YhLeEi_f0wkJH2PJOI70Ow==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1897, '报纸', '有梦就有痛', '伍正华', '解放军报', '解放军报', '国防和军队改革;军事变革;利德尔;', '毛泽东形容，“红军长征是打着灯笼走夜路”。深化国防和军队改革，何尝不是举着火把突围的新长征！ 转型之艰，犹如蚕蛹破茧、雄鹰换羽，有些关，必须闯；有些滩，必须抢；有些痛，必须忍。实现强军梦，必然经历转型痛。 1.任何改革都是一场自我革命。 党的十', '2013-11-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID8TFOpFWbuOTZBNGHw4svJl3dS11qsKvE0BDed39OUkfX8_oAzTGcTtdL-PesngKc2xpAllS-SPvYBPjKyP4SUnhHf9sLNV1QUDieCEMdONywYm77w7gd6tDA4JR-544lXCSB0kggEDQ==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1900, '报纸', '军事题材雕塑唱响时代主旋律', '倪敏芝; 秦超', '解放军报', '解放军报', '军事题材;时代主旋律;雕塑家;', '军事、军队、军人，从来都是社会关注的热点，也是文化艺术创作的重点。随着当代雕塑艺术的兴起与发展，军事题材雕塑往往以其形象的现实性和社会性，传达出对人类历史、人文环境、世界和平的关怀，日益引起人们的关注。伴随大力发展先进军事文化的热潮，记者近日走进中国艺术', '2012-04-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAjxdVsWD7ocxMY1XL9Tx0MiCno7ApjHVnoGWfvpp4wByZzvfDJ3T_MdN0udPaVUEp-bFTcMDsn2vvw0_xrQOrsw7ISgSmOVtpVQpnvqUw5zP2pCE2vae4d22JYU2q6GUcI5-WuscOz5w==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1905, '报纸', '22名勇士中8位得以确认', '范炬炜', '解放军报', '解放军报', '刘梓华;飞夺泸定桥;纪念碑;王永模;廖大珠;李友林;', '独家披露：经最新查证，飞夺泸定桥的22名勇士中，目前有8位勇士的姓名可以确认：廖大珠、王海云、李友林、刘金山、刘梓华、赵长发、杨田铭、云贵川，其中有照片者4位：李友林、刘梓华、杨田铭、刘金山。 站在红军飞夺泸定桥纪念碑公园门前，就会看到大道两旁的22根花岗', '2011-05-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB9oJqNW80d-JQtzi1EBGSEUjg9mHOAUbW63QyTEW4EthJ9VFn8L0hb-21G-W79QfnCjYPVyGcbWRsX8a0PDyAnzFIkgcEJzP6e20ggdCcln_h8kCQ6ySG-SCBEO_3yfTWDA13TfDeLmw==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1906, '报纸', '树根对绿叶的倾诉', '武天敏 ; 陈国全 ; 李国文 ; 刘小红', '解放军报', '解放军报', '《苦难辉煌》;周俊杰;空军工程大学;红军长征;刘伯承;', '世纪之交，西安古城，浐灞河边一片荒滩上，崛起一座崭新的大学城！ “大学从破土动工到落成，只用了18个月。”回忆空军工程大学新校园的建设，教员们记忆犹新。 当年，校园里没有一棵树。建设者们把大树从远处移栽过来，这里从此郁郁葱葱。 “大楼好盖，大树', '2011-05-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBpdFhNwz3j0JK87Hu0PRJSlTN8eC8Q_Kic6ck5kskP-vzE3HlLjRFKCiy-ENHbjM0Kopm0Uf87EQtbBz-jJjK6iQqWFMboZX9_--hJaLgtFdxFGif9G5Nj1GJ20G3eO6dT2a7QqxAkUw==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1910, '报纸', '从汶川到舟曲', '董强 ; 丁海明; 马越舟', '解放军报', '解放军报', '非战争军事行动;军地协同;武警部队;抢险救援;第二炮兵;地震灾害;救援队;指挥体系;火线入党;', '联合国减灾科技委员会在一份报告中这样描述中国：“这是世界上自然灾害最严重的少数国家之一”“从有人类记录以来，旱涝灾害、山地灾害、海岸带灾害每年都在中国发生”。 2008年以来，我国自然灾害密集而严重。在党中央、国务院、中央军委和胡锦涛主席的运筹帷幄、坚强', '2010-09-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDhYGgUczqgZQuNLJ0Rc1dqOqhfFYo9BW1iWqtZM9WfAjahYoK2ALEr3bLRK_tPi-Mm4KYYbP9I3lulb8WO4sbwAWXJI67-A42sf9KusosxiGNoPBl6QLesj1c9_IBEGcFnQdTp85VdMQ==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1912, '报纸', '兵发山野惊心动魄', '杨彪; 向辉; 王美权', '成都军区军训和兵种部;', '解放军报', '标准答案;', '本报成都11月17日电 记者杨彪、特约记者向辉报道：风大雨疾，夜黑如墨。11月10日晚8点，成都军区某装甲旅坦克分队兵发山野，举行年度军事训练考核。记者跳上一辆指挥车，雨夜长驱，全程跟踪考核。  部队驶出营门不久，即遭“敌”空中侦察。一声令下，所有车辆闭灯驾驶。', '2009-11-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB6eZLaRNMzpUBynXKNxiBmk56M-6x7Wm4qPjdt2lAiMzHP3wyGV4dAEo4TrLuKcvoguFVDRAQWelTyuRcwFTyKyie5axkXhtAPpfyy4JH-pmsXPyzM-Zi0CENA0Ge-6eeru_8OKAP44Q==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1914, '报纸', '形象的标杆 完美的极限', '唐先武', '科技日报', '科技日报', '海军学员;', '铿锵的步伐声，轰鸣的马达声，高亢的呐喊声……在这块英雄的土地上碰撞着，交汇成最美的旋律。9月2日，国庆60周年首都阅兵村接受记者采访，我们走进了这个尚未揭开神秘面纱的独特“村落”。 “向国庆献礼，为军旗添彩”“争当训练标兵，争做阅兵模范”……一进“村', '2009-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICOGMcdc1CYZLhee89GHNCLTNfwglkCcgewdbJB877qjE2y_B5vzHB9V2k92BhBvfMtR43po18sFySVfQKpPdnXzOTvY3NZLXmX2ZAYZhOi0Lyp4vdROsJ7QbOGi3dURdLjVKNOdi3jEg==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1917, '报纸', '让红色故事延续民族魂', '蔺玉红', '光明日报', '光明日报', '红军精神;红色英雄;甘孜州;康巴藏区;州委书记;红色文化;爱国主义教育;网络影视;格达活佛;故事家;未成年人思想道德建设;廖汉生;', '“我给大家讲的是‘格达活佛的故事’。”四川甘孜康定县回民小学四年级学生德钦卓玛站在舞台上，绘声绘色讲起了当年甘孜县白利寺格达活佛支援红军的动人故事。台下，贺龙元帅的女儿贺晓明听得眼含热泪。  这是今年10月中旬“雪山草地展红旗，星火相传颂英雄”——红军后', '2008-11-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBbyRKqNT3fuljDfcZ7Clh0mIpQ6w-Zi6eD9n7iN3FzPTIHMAqDxebwyI4jl9Ka759CuwillfYTLbhl2rykNnuqKkzcEyWW3OBiom9FodrNItzTPhNxlNZgeB-Q0qL4U99bM9T3kgPPnQ==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1918, '报纸', '“铁军”：一往无前敢亮剑', '费士廷; 孟斌; 李光辉; 谭雄鹰', '解放军报', '解放军报', '叶挺独立团;复杂电磁环境;秋收起义;对抗演练;', '这是一支敢于刺刀见红的部队。  从井冈山打到吴起镇，从平型关打到刘老庄，从东北打到海南……3000多次沙场亮剑，“铁军”敢于和国内外强敌血战到底。  和平年代，血性不改。一次次临危受命，“铁军”敢于战胜一切艰难险阻，敢于压倒一切对手。 ', '2007-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAAn7dXL0hAFbhzmy-SJOKwrvQle_guhqCy9ThwVHGDyrGlTSHMdNEWW3aPy6rXiu6Ugivly5IPIQ3G3iL3JXyBdX1zVnb8cReQ-4wUVpQkveojQsUaFL9H9WCbnQtPaq7LrNTdxhmN5w==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened,秋收起义_screened');
INSERT INTO `ds_article` VALUES (1920, '报纸', '“铁军”魂', '张玉清; 白瑞雪; 冯春梅', '人民日报', '人民日报', '叶挺独立团;刘老庄连;秋收起义;', '刷——如同迷彩丛中长出了金色枝干，一排排紧攥的拳头向着党旗宣誓。这誓言，穿越８０年时空；这誓言，回荡着一个响亮的名字——“铁军”！铁心跟党——党旗指向哪里，滚滚铁流就开到哪里初到红一连时，２７岁的张雄飞有', '2007-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBuyfEIlgoGg7J2ydcmsWGqVgqkaqsD20Tux65ADm9z2bdDKiU8YhttwS7_Ofu3lQfwvbIFoOxfUhtCcCchdaajlP8UjAvvGdZeLUkmkCNxB-1VBz-xi-TdoKLKXgoCEToQuAfoSevh7A==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened,秋收起义_screened');
INSERT INTO `ds_article` VALUES (1922, '报纸', '中国“铁军”', '张玉清; 徐壮志; 冯春梅', '人民日报', '人民日报', '叶挺独立团;红军师;秋收起义;', '这是人民解放军序列中历史最悠久的一支部队。 ８０年前的８月１日，有“铁军”之誉的“叶挺独立团”与其他起义部队一起打响了南昌城头的枪声；同年９月９日，毛泽东领导秋收起义，创建了中国工农革命军。１９２８年４月，南昌起义余部在朱德率领下与毛泽', '2007-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAIS9-40750YxIt_CJex-S2W53lcDKrSUob3wmcgOx30as2bAwKPsoszZInTRU9A_mtSJjNJpmKbvGhZz3wxtkS6BvcFBc7OBXKuqXEQ7HyknTNPG3wgqNk559bqjjVny8bRjgrZwHdMQ==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened,秋收起义_screened');
INSERT INTO `ds_article` VALUES (1928, '报纸', '泸定桥畔两代人', '郭亚林; 于进; 马川军', '中国经济导报', '中国经济导报', '泸定桥;物价部门;大渡河;', '泸定，长征路上名城。1935年5月 29日下午，泸定桥上高悬空中的13根 光溜溜的铁索，暂时阻隔了红军的前 进，却永久地成就了“冲锋22勇士”的 威名，谱写了长征史上突击战役的神来 之笔。  记者一行3人，驱车从成都出发， 穿越二', '2006-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBzKdq6-40f_uiM76VUQhEzGQk6-irvTcj0HwLBw0Fc7EMVb0ePJKQGAPqQu-X2xeXx9hJnuxf6xyfWQhJBAWoVIE_eN-zEzbjmhUSdSLpVe-H7vkP4Bcm3h4WAaL7Cmg9Z_itNSCYSzg==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1932, '报纸', '让感动时代的长征精神薪火相传', '柴葳; 苗艳丽', '中国教育报', '中国教育报', '长征精神;皮筏子;', '有一个壮举，历经70载斗转星移，仍用热血和坚韧阐释着感动时代的精神；有一种精神，历经70年风雨磨砺，仍以百折不挠的姿态屹立于时代的潮头。10月16日的中国人民革命军事博物馆，因为“伟大壮举光辉历程———纪念中国工农红军长征胜利70周年”大型展览的开幕而显得更加神圣', '2006-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBKqafmFgwSgCuM_vmgz1shBA22xCdz96f9UEwWnCZW41j6zUwYmkYzOmRM_LZGRPduBHuCXwur20VJx748_Rw6FtXYb0IRSZjcuvhTMK7_LsUY4d6DwWH4Rva2xB3-VV3HUDRrLOUT6Q==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1937, '报纸', '四川大渡河畔开启新征程', '曲飞', '中国交通报', '中国交通报', '大渡河;泸定桥;磨西镇;铁索桥;旅游业;', 'T四川是当年红军长征经过地区最广、最艰苦卓绝的省份，巧渡金沙江、彝海结盟、强渡 大渡河、飞夺泸定桥、爬雪山过草地的壮举，会理、两河口、毛尔盖、巴西等重要会议的召 开，红军三大主力的两次胜利大会师都发生在四川这片热土上。8月4日至6日，记者随', '2006-08-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAmqk74K2Gc9_MsOyCYCnQT61bl_4zKRcwP4gwdcxzoVLA13qTjEoDNlsZ3K4SnjxUvKsqYetbMmeZNVdrV5NPe4G7bahkKNs-HvzkK-YcTb6cTIg3TR6mKsUcvYj-vFWC2zQaTEV6Tng==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1938, '报纸', '沿着红军长征路丰富文化送农村', '干德明', '中国文化报', '中国文化报', '文化信息资源共享工程;红军长征;长征行;', '本报讯 由四川省文化信息资源共享工程小组、四川省文化厅主办，四川省图书馆和共享工程四川省分中心承办的“重走红军长征路，宣传公共图书馆服务和全国文化信息资源共享工程活动”授旗仪式，日前在成都举行。“长征行”团队接旗后分四路出发。 “长征行”团队将', '2006-08-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBSW8ESrxnWCs0u4NOXYquLxrGwXQc2C6udskYtpcSTLgpouMGVVs45iDoxuBdEf0gheUPdL0kkGOXoqmmOuKvF2OVvmD09Q4W2IFomXhyBh_4xemr8YEVktOTt68k6PqbTLrPDmEoB9A==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1939, '报纸', '“北上抗日,是我们长征路上的精神支柱”', '贾永; 徐壮志', '新华每日电讯', '新华每日电讯', '长征路上;新四军;精神支柱;', '1945年8月15日，日本宣布投降。  “那一天，是农历七月初八。”对于89岁的李水清将军来说，61年前的“八一五”和70年前的长征会师那天一样，是与生命同样重要的日子。  为了这个令中华民族含泪欢笑的日子，李水清和他的长征战友们付出了太多太多…… ', '2006-08-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAyQcGr158s4REpsGmV65UdFIt_XdaO3zKTNuhQT5B88YZM2_JRrau3UBfnP1xVcwMUzQz8uTfgvmO9uIrm7UQBiPlouS8pR03UStI2-g_w4LOhCkY6t_kEJQkry9ZESbgDIE-guW19Dw==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1940, '报纸', '大渡河 天堑变通途', '朱虹', '人民日报', '人民日报', '大渡河;人行吊桥;石棉县;', '从四川省石棉县沿大渡河而下，一边是汹涌的大渡河水，一边是巨石峭壁，公路仿佛悬挂在山腰，让人心惊胆颤。真个是蜀道难，难于上青天。 解放前，这里所谓的道路就是在山间蜿蜒盘旋的崎岖小道。长征时为夺取安顺场下游１００多公里内的泸定桥，红四团在崇山峻岭间的', '2006-08-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBz-YZo0wD6K6Mx1Vdbvov9JTLgksU-DJCdptPOYSayx2YF37s3rN4GU-NpEIKuNv_tzZmVTriwWXmLkId108XS-IJGZjPVMdxfyiF6llraJeHxI4cYOEn_RVjpOgid9eQXdpM1p75J9w==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1944, '报纸', '记者目击：三军演兵陆海空', '柳刚; 黄超; 钟海园; 谭洁; 张金玉', '中国国防报', '中国国防报', '李景高;', '炮声隆隆，铁流滚滚……  夏末，齐鲁大地天气火热。济南军区某机械化步兵团官兵的训练热情和天气一样火热。  这天，记者走进山东半岛某地训练场，一场激战呈现眼前。  在前方坦克群的掩护下，济南军区某机步团的20余辆新型装甲步战车快速出击，穿', '2005-09-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAf2YggYEIX7b199Ovq7L_DZWe4b1VYESfGKUo_MthRMq5Fcbxr0UcPqV41_Mi_-rLCFFmdDHRVU3P2vkSOIyQm46dt1eMjQbQGwlxrVW4BuEdVtJ-RWQlpYX7vIChg3FOB_W-wCTYihA==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1949, '报纸', '泸定新长征', '余长安', '光明日报', '光明日报', '大渡河;铁索桥;泸定桥;二郎山;水电农村电气化;', '一说去川西高原二郎山脚下、大渡河畔的泸定县采访，即刻想起五十年代那首唱遍全国的民歌：“二呀二郎山，高呀么高万丈，古树荒草遍山野，巨石满山岗，羊肠小道难行走，康藏交通被它挡……”然而日前驱车前往，却寻找不到歌中的景象。新修的水泥道路虽然曲折，但宽阔、平', '2004-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBRT6kCzbbRJClJNGAQGSVWO51q0gvY1ZLY45f5xBoJMDbkfyqwwcar2JAUebn8Z920PuTA7lS1yStstkOHhuzHZGeDeHINQkdYK_Kocn0XSC-YmAan7r0z48Uiy_ENCwqs1g0swu0BGw==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1951, '报纸', '向机械化、信息化奋进', '龙云飞; 曹晓明; 魏联军', '工人日报', '工人日报', '机动作战;机械化步兵团;', '这是一支有着光荣传统的英雄部队。当年红军长征途中，这个团作为第一军团的前卫，担当开路先锋：强渡乌江，飞夺泸定桥，草地突围，奇袭天险腊子口，一路斩关夺隘，确保中央红军胜利前行。如今，在新的历史时期科技强军，这个团又为实现从摩托化向机械化、信息化两个转变，', '2003-02-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIClJXLSgs2sbbfqJdYyij9TJvQAfOlPyWHUm093yQyP0ncodsirHZmQUbIclOogo3W6-7G8-ll8wYzzCb3YEsxqoClqIM0CeVOOGpaDA6PidC430jtIR02hAHytzwKK644DfN0mYr3B7Q==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1952, '报纸', '力帆费心思推出“轰轰烈”', '白勇', '中华工商时报', '中华工商时报', '大渡河;泸定桥;多气门;', '11月16日，当力帆旗下的轰轰烈摩托车在上万双眼睛的注目下、从一根比大姆指略粗的钢索上飞驰大渡河的那一刻起，以前默默无闻的“轰轰烈”一下子便让甘孜州乃至四川人刮目相看，人们纷纷打听“走钢丝”飞夺泸定桥的摩托车是什么品牌，哪儿能买到。 摩托车走钢丝飞越大渡', '2002-12-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICgGZ7RImEFdCZme-xFnA9hw63EHPl10-gycavIVyFLs8HuxUph5LlqOrt9d0B13mEzGgnFMEzUv9yZcFaP3oDB5SGwZD5cPEjUKfXsHjfJTpxymtmcGtohZ8l3_lv5tAJMjhxF8gzDgQ==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1953, '报纸', '在先进文化旗帜下壮大的军营文化', '银军; 曹慧民', '解放军报', '解放军报', '枪杆诗;军营文化;活报剧;吹拉弹唱;文工团员;周恩来论文艺;中央革命根据地;', '枪杆诗  艺术是我们的武器，为苏维埃而斗争，艺术这个武 器你们究竟拿到没有？  ──摘自瞿秋白语录  “枪杆子里面出诗”。标志着武器或武装力量的枪杆子，以 诗的形式出现后，即刻在部队官兵中发展成为轰轰', '2001-07-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDS5A4NWo5GGP32h_bg5KiQXq9zpYjiBvtVpWWEznr2Ek8gctWsIHSIvnYgsjbF5Qi1jV4dfN8W0ZuWLZfw0nTi1-248hlMyh2DmNnSBTT5wdCJLWznrpzwzCYYOs9wBYr0usc4RnjQDQ==&uniplatform=NZKPT&language=CHS', '飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (1955, '报纸', '提高依法履职能力 充分发挥代表作用', '黄庆畅', '人民日报', '人民日报', '全国人大常委会;履职能力;人民代表大会制度;法律草案;申纪兰;', '悠悠延河水，巍巍宝塔山。前不久，革命圣地延安迎来了一批特殊客人——十四届全国人大第四期代表学习班的近300名代表。在课堂上学习习近平总书记关于坚持和完善人民代表大会制度的重要思想，在延安革命纪念馆里砥砺“我当代表为人民”的初心使命，在陕甘宁边区参议会旧址前感', '2023-11-30 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.011651', '红井_screened');
INSERT INTO `ds_article` VALUES (1956, '报纸', '当红色文化遇上高科技', '刘宗炎', '中国国防报', '中国国防报', '主题公园;高科技;红色旅游;红色文化;', '“东方欲晓，莫道君行早。踏遍青山人未老，风景这边独好。” 8分钟云端遨游，俯瞰祖国壮丽河山；25分钟沉浸式观演，走进女英雄激情燃烧的岁月；35分钟视听盛宴，重温记忆中的红色旋律……当科技赋能文旅产业，在“高科技搭台，红色文化唱戏”模式下，江西省赣州市如何落子，', '2023-05-16 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2023.000721', '红井_screened');
INSERT INTO `ds_article` VALUES (1957, '报纸', '以法之力弘扬英烈精神', '朱宁宁', '法治日报', '法治日报', '保护法;纪念设施;', '“昨天你用生命捍卫我们，今天我们用法律保护你。” 五年前，2018年4月27日，十三届全国人大常委会第二次会议全票通过《中华人民共和国英雄烈士保护法》。法律通过的第二天，全国人大常委会法工委部分同志在法工委副主任许安标的带领下，来到人民英雄纪念碑前告慰先烈。 五', '2023-04-11 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2023.001824', '红井_screened');
INSERT INTO `ds_article` VALUES (1958, '报纸', '瑞金：没有围墙的红色课堂', '党云峰', '中国文化报', '中国文化报', '全域旅游;红色旅游;红色文化资源;', '江西瑞金是闻名中外的红色故都、共和国摇篮、中华苏维埃共和国临时中央政府诞生地以及中共中央、中革军委和直属部队长征出发地。这里保留了大量红色文化遗址和纪念建筑，是著名的爱国主义和革命传统教育基地。 “以前学过《吃水不忘挖井人》这篇课文，所以特地到这里喝一口', '2022-10-22 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.003616', '红井_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1960, '报纸', '江西：打造第二课堂 浇灌校园花朵', '崔怡雯; 周晨', '中国旅游报', '中国旅游报', '讲解员;中央革命根据地;第二课堂;新四军军部旧址;', '“一大早，毛泽东同志带领几名红军战士在村前几十米的地方勘探水源。当井位确定后，他挽起衣袖、卷起裤腿，带头挖了起来……”下午课后4：30，江西省瑞金市华融瑞金希望小学的“四点半红色课堂”准时开讲，红领巾讲解员杨莉讲解的《吃水不忘挖井人》故事，让同学们听得入了神', '2022-07-01 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.001713', '红井_screened,叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1961, '报纸', '让红色文化传承不息', '', '中国文化报', '中国文化报', '文化传承;讲解员;博物馆;纪念园;兰考县;传承弘扬;中央芭蕾舞团;中央革命根据地;东坡文化;《红色娘子军》;焦裕禄精神;三苏祠;抗美援朝精神;北大红楼;', '今天，我们迎来中国共产党成立101周年。从浙江嘉兴南湖驶出的小船引领中华民族书写了气壮山河的伟大史诗。红色文化正是中华民族在奋进征程中创造、积累、传承的灿烂文化。 本期“奋进新征程 建功新时代——我这十年”特别报道，从红色文化传承发展和优秀传统文化弘扬光大的', '2022-07-01 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.001984', '红井_screened');
INSERT INTO `ds_article` VALUES (1965, '报纸', '江西：红色文艺之花绽放时代光芒', '胡晓军', '光明日报', '光明日报', '红色题材;故事片;红色基因;红色文化资源;方志敏;中国电影华表奖;三湾改编;甘祖昌;', '江西，是一片充满红色记忆的土地。中国革命的摇篮——井冈山，军旗升起的地方——南昌，中国工人运动的策源地——安源，共和国的摇篮——瑞金，中央红军长征出发地——于都……一个个红色称号与地名在这里分布。 八角楼的灯光、朱德的扁担、“吃水不忘挖井人”的红井……', '2021-09-29 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.004992', '红井_screened,方志敏_screened,瑞金_screened,龚全珍_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (1966, '报纸', '红色山河当课堂 革命薪火代代传', '刘以华; 罗来明; 郭冬明', '解放军报', '解放军报', '省军区;微纪录片;方志敏;军分区;参观见学;讲解员;袁文才;', '“八一南昌起义前，周恩来将起义计划告诉贺龙，并征求他的意见。贺龙坚定地表示：我完全听共产党的话，要我怎样干就怎样干！”近日，南昌警备区官兵走进南昌起义贺龙指挥部旧址参观见学。听着讲解员动情的讲解，看着墙上的累累弹痕，官兵对“听党话、跟党走”有了更深刻的理', '2021-08-24 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.005472', '红井_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (1967, '报纸', '苏区精神放光芒 红色旅游别样红', '周晨', '中国旅游报', '中国旅游报', '红色旅游;安远县;全域旅游;苏区精神;', '老区苏区孕育了中国革命，是中国共产党的初心源泉。在革命根据地的创建和发展中，在建立红色政权、探索革命道路的实践中，无数革命先辈用鲜血和生命铸就了以坚定信念、求真务实、一心为民、清正廉洁、艰苦奋斗、争创一流、无私奉献等为主要内涵的苏区精神。 2019年5月，习', '2021-08-12 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002345', '红井_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1968, '报纸', '苏区精神，中国共产党人政治本色和精神特质的集中体现', '姚鹏; 刘旭', '中国妇女报;', '中国妇女报', '苏区精神;共产党人;集中体现;中央苏区;苏区干部好作风;苏维埃政府;毛泽东;临时中央政府;政治本色;红军战士;兴国县;精神特质;', '大革命失败后，中国共产党人面对国民党的屠杀，继续高举革命的旗帜，领导发动土地革命和武装斗争。1931年11月，中华苏维埃共和国在中央革命根据地瑞金宣告成立，谱写了革命根据地建设和红色政权建设的新篇章，苏区精神正是在苏区的开辟与发展、反“围剿”斗争和中国共产党苏', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.001836', '红井_screened,方志敏_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (1969, '报纸', '苏区精神永放光芒', '卢翔', '工人日报', '工人日报', '苏区精神;苏区干部好作风;水上漂;', '在江西东南部，有一座红色之都——瑞金。它是红色中央政权的诞生地，是共和国的摇篮。 1931年11月7日，瑞金城东6公里的叶坪村张谢家祠堂，中华苏维埃第一次全国代表大会在此召开。如今，在叶坪中共苏区中央局旧址所在地，陈列着一张珍贵的照片。那是“一苏大”召开时，中', '2021-07-27 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2021.003505', '红井_screened,谢家祠堂_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1970, '报纸', '革命薪火的时代光芒', '朱宏博; 郭冬明', '解放军报', '解放军报', '苏区干部好作风;苏维埃;临时中央政府;中华苏维埃共和国;红军长征;革命老区;反“围剿”;', '赣南，闽西，重峦叠嶂，苍翠连绵。历史在这里留下浓墨重彩的一笔。 治国理政的伟大预演在这里开启—— 1931年11月7日至20日，中华苏维埃第一次全国代表大会在江西瑞金召开，宣布成立中华苏维埃共和国临时中央政府。经历血与火的考验，这里孕育了一个国家的雏形，铺就了', '2021-07-26 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004750', '红井_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (1972, '报纸', '江西瑞金：为民情怀永赓续，红色旅游向阳开', '程晖', '中国经济导报;', '中国经济导报', '红色旅游;中华苏维埃共和国;临时中央政府;红色旅游景区;瑞金市;江西瑞金;', '一棵棵古樟树见证岁月沧桑，一间间老房子诉说动人故事。江西瑞金叶坪，是当年中华苏维埃共和国临时中央政府所在地，这里记录了中国共产党人对于如何建设一个国家的最初探索。中国经济导报记者走进叶坪革命旧址群，昔日火热的革命场景仿佛浮现眼前。 江西瑞金是闻名中外的', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28095/n.cnki.ncjjd.2021.001584', '红井_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1973, '报纸', '从党史中汲取奋进力量 在新征程上展现新作为', '王小洪', '公安部;', '人民日报', '习近平总书记;政治规矩;公安民警;两个维护;公安机关;红色基因;马克思主义基本原理;中国特色社会主义;', '在全党开展党史学习教育，是党中央立足党的百年历史新起点、统筹中华民族伟大复兴战略全局和世界百年未有之大变局、为动员全党全国满怀信心投身全面建设社会主义现代化国家而作出的重大决策。公安机关要深入学习贯彻习近平总书记关于党的历史的重要论述，增强“四个意识”、', '2021-06-25 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006702', '红井_screened');
INSERT INTO `ds_article` VALUES (1974, '报纸', '切实为群众办实事解难题', '', '中国组织人事报', '中国组织人事报', '办实事;解难题;', '中南海新华门里的影壁上，“为人民服务”五个大字金光闪闪。这是一个百年大党执政宗旨的凝练表达，是9100多万名中国共产党员初心使命的坚定宣示。江山就是人民，人民就是江山。从成立之日起，我们党就将“全心全意为人民服务”镌刻在自己的旗帜上。在我们党的价值体系里，人', '2021-04-27 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.001454', '红井_screened');
INSERT INTO `ds_article` VALUES (1975, '报纸', '红井水清映初心', '沈忠斌', '江西省瑞金市委组织部;', '中国组织人事报', '毛泽东;苏区干部好作风;', '春风拂面，沿着江西瑞金市城区，驱车西行3公里，放眼望去，群山叠翠，沃野铺金。在数百亩金黄色的油菜花环绕下，一排排古民居村庄隐约可见。这个村庄位于沙洲坝，是苏区时期中华苏维埃共和国中央政府所在地。闻名中外的“红井”便座落于此。 “瑞金城外有个小村子叫沙洲坝', '2021-04-07 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.001182', '红井_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1976, '报纸', '倾听古田军号声', '', '中国国防报', '中国国防报', '毛泽东;红四军;古田会议;全军政治工作会议;习主席;能打胜仗;', '军号声声，从古田而来。 这是令人振奋的决定：2018年10月1日，按现行规定全军恢复播放作息号；2019年8月1日，全军施行新的司号制度。 舆论普遍认为，我军司号制度的恢复和完善，在强化号令意识、传承红色基因、推进正规化建设和提振军心士气等方面必将发挥重要作用。', '2019-11-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB3cMkSqz3f8VKC4ymhlnn32wVvKjq9JsB6Fdkh4nzEL-Jt8dmIcJVIBGJgIOm0HHcGITQ0S4k1wJhyAnazTq-PLgEwHdkZV1Vc04o-OdNYqesOx4ENk6hzJIWXi67zol--iXQ1eOSPHA==&uniplatform=NZKPT&language=CHS', '红井_screened');
INSERT INTO `ds_article` VALUES (1977, '报纸', '瑞金着力打造全国红色旅游示范区', '赖联春', '瑞金市人民政府;', '中国旅游报', '红色旅游;区域性;旅游产业发展;红色旅游资源;旅游集散中心;红色旅游目的地;景区建设;', '瑞金是闻名中外的红色故都、共和国摇篮、中央红军长征出发地，有着发展红色旅游得天独厚的优势。但是，很长时间内，瑞金红色旅游发展与产业融合不深、投入不足、品牌竞争力不强、运作模式不活等问题未得到根本解决，旅游产业发展和红色故都的美誉极不相称。 近年来，瑞', '2014-11-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBpORLLKxcNDTVNpKq4AJyYqxDmAbNVk8kFTq5JMKeCSE_f8YSQxMoYeQlSnMqEbUgvAmKnbeiiFy4rRdJs1gXITfn7YUWch-m4gKP7SNMaCPT3Rn2wtQwe2Irutz4KGDEM9uX_K5W6vg==&uniplatform=NZKPT&language=CHS', '红井_screened');
INSERT INTO `ds_article` VALUES (1978, '报纸', '瑞金：人民公安雏形的诞生', '周洁', '人民公安报', '人民公安报', '国家政治保卫局;公安部;中华苏维埃共和国临时中央政府;一苏大;', '黄泥墙，乌瓦屋，古樟参天。绿草地连接着几栋普通的赣南民宅，一堵矮墙将它们围拢在一起，显得古朴而特殊。黄泥墙上依稀可见当年的标语“捍卫全苏大会”、“为着独立自由的苏维埃中国而奋斗”。 这是江西省瑞金市东北6公里的叶坪村——中华苏维埃共和国临时中央政府', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBesjOLNHGKgxwdap8jM48lmB16Kr9DSc4RNYchYk9QbKINd5nW7FuftTpb47idm9LMRRETRTm4k16kdbIvgJLV-i5cirsFzV7TeKkoTeNIWaoh_2AQohb7BSan7bkNejDtlD8kOc9sIA==&uniplatform=NZKPT&language=CHS', '红井_screened,谢家祠堂_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1979, '报纸', '让“红都检察”品牌更加闪亮', '欧阳晶; 姚卫东; 程军化', '检察日报', '检察日报', '审查起诉;瑞金市;公安机关;有罪判决;中华苏维埃;休闲中心;红军长征;', '简陋的脸盆架和木桌木椅，锈迹斑驳的铁皮文件柜，两条长凳和木板搭起的简易行军床，墙上挂着斗笠、干粮袋和草鞋……这间十平方米不到的房间，是中华苏维埃中央工农检察委员会第一任主席项英的办公室。房间里的所有陈列，都在无声叙说主人在那段火热岁月的艰辛与奋斗。', '2011-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDFZ0h2q7-G_mFfvruDi9cejvekWiEWsNrzy_-TgyQX7zEy4ppDKDbbdkX8wOGnO2F9ihHlaI0Q_9GGU2CzcSXYyNDHfNOCinVyT0WNMQIUxdf18_-EcpyoYZYVUz7b9uvezutByLzUTA==&uniplatform=NZKPT&language=CHS', '红井_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (1980, '报纸', '寻根,支书们寻到了什么', '张建华 ; 赵杰', '解放军报', '解放军报', '参观见学;古田会议旧址;支部书记;临时中央政府;', '重温历史启迪心灵，拜谒先烈寻根淬火。“五一”前夕，总参工程兵某设计研究所党委领导分两批带领支部书记和优秀党员，赴革命圣地江西瑞金和福建古田参观见学。一次独特的红色之旅，让寻根的支书们受益良多。 红军之魂 永远听党话跟党走 杉柏参天，党建圣地。', '2011-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB4rUu6d4c1tm4KKxfolB4f6LTlLb-oUlAIURvXeWUlK1BJNzszjdA-PWo-R-o4CV3zQpNdqNPZn5DOibOeqU40uHDiOurWf03xuu-o2skyCU9yIYvy0ojvgG_2yQeyFupXsgFvkubAVQ==&uniplatform=NZKPT&language=CHS', '红井_screened,叶坪_screened,红四军_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1981, '报纸', '共和国从这里走来', '杨清刚; 徐政武; 崔恒友', '解放军报', '解放军报', '中华苏维埃共和国临时中央政府;烈士纪念塔;共和国;中华苏维埃第一次全国代表大会;红军长征;', '踏上瑞金红土地才知道，《共和国摇篮》《长征》《党的女儿》等大家耳熟能详的热播红色影视剧，都曾把这里作为主要取景地。 1931年，中国共产党在瑞金创建第一个全国性红色政权——中华苏维埃共和国临时中央政府，开始了领导和管理国家政权的伟大实践，瑞金也从此作为“', '2011-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDtk-HJImCQ3a4jNQha0J020N0VVXeKMRqwACaJ7LYF-umk1KneJ61R2sohDyvYCYneXaT3IltEy_IeIA7fcNqe5n-cqLKdj1omMxwuwBA4aFTDjovATaJ5XQNhMilpPU5eSlkj_eg7Pg==&uniplatform=NZKPT&language=CHS', '红井_screened,谢家祠堂_screened');
INSERT INTO `ds_article` VALUES (1982, '报纸', '苏区好作风 今又回来了', '谢亨舜 ; 徐政武', '解放军报', '解放军报', '民兵预备役;军分区;', '本报讯 谢亨舜、特约记者徐政武报道：11月初，江西省赣州军分区领导带领16名驻村帮扶人武干部，像当年苏区干部那样打起背包，奔赴赣南贫困山区的扶贫挂钩点。这是该军分区学习贯彻党的十七届四中全会精神，开展“弘扬苏区传统、争当红军传人”主题实践活动的一项具体举措。', '2009-12-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDqCKclJEsTVINB1rf0MXwr3mQjzX68a35_1XUQ65WxcyvmrP_63ZITqBXI5BP-xq5mA2_giTEhX5hP_McAviZfhgopPoju4OwsuFSdbtjIHp7Zdk0_bRA2rp2DIMzxyGmsT56F0Lmn9Q==&uniplatform=NZKPT&language=CHS', '红井_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1983, '报纸', '江西爱国主义教育基地成育人大课堂', '徐光明', '中国教育报', '中国教育报', '爱国主义教育基地;革命传统教育;方志敏;大课堂;', '本报讯（记者 徐光明）“一苏大”前听报告、“红井”边上书声琅、“第一山”下游人稠……今年暑假，在江西省瑞金市每一处革命旧居旧址，一群群青年学子、海内外游客纷纷前来接受爱国主义教育和革命传统教育。许多学生感慨地说，一踏上瑞金这块红土地就像走进了一个红色教育大', '2009-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIASQNdISb-VwxEESXre2VxoeKlqQ1B4k3IdFCGz2vIRo7Y3csMoh3euuM1WB57ckMXKXNNPcAihAvP_GcC75dYfvZd8uB4RqCJcgclZNFL0VOw_6OefXyi1vmJjz3ma4V7QgEyNLcK4LA==&uniplatform=NZKPT&language=CHS', '红井_screened');
INSERT INTO `ds_article` VALUES (1984, '报纸', '瑞金：“红都”处处展新颜', '陆敏; 廖国良; 姜范; 刘志奇', '经济日报', '经济日报', '革命旧址;中华苏维埃共和国;临时中央政府;', '刚到瑞金，便被道路两侧飘扬的红旗所吸引。山风猎猎，吹得旗帜呼呼作响，放眼望去，红都大道被红旗点缀成一片红色。 1931年11月7日，中国共产党创建的第一个全国性红色政权————中华苏维埃共和国临时中央政府在这里成立，并把瑞金定为首都。 记者一行来到中', '2009-07-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAM4qnPH9-5AaSo53N_3YBQNPDbMx9ka3yYFFFootI4Scd25I2bZfK2SOzhjAsfXMpOl3zgrL1G-pa0iZGanYA7IEg0eh4ZKHTUZx-IlTXBrXIUZqRT1x90q6o8CYhC23DEcBfJR1wXwA==&uniplatform=NZKPT&language=CHS', '红井_screened,谢家祠堂_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1986, '报纸', '共和国摇篮 长征出发地 红色故都瑞金', '', '中国旅游报', '中国旅游报', '共和国;', '毛主席诗曰:装点此关山，今朝更好看……  周总理说:南京北京不如瑞金……  聂荣臻题写:永远值得怀念和敬重的红都瑞金。  美国记者竖起大拇指盛赞瑞金——very good!  “吃水不忘挖井人，时刻想念毛主席”。  一篇短短的小学课文把人', '2009-04-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDrhjulUjYbz-1IL8G2qkxPKbi3rVcUaVQ_QR5siuwQH57UTxjMpHKEAf9p3s13in8P2ERmVOoRg029qDV-FUgmaoTA9vUCZr15knlBMALtkDr-mfaLyJZ6t8S9ZH_NAGnLkpHjUl9OPw==&uniplatform=NZKPT&language=CHS', '红井_screened');
INSERT INTO `ds_article` VALUES (1988, '报纸', '赣州：“红色旅游”为老区经济添活力', '廖国良; 梁飞', '经济日报', '经济日报', '红色旅游资源;红色景区;', '本报讯 记者廖国良、通讯员梁飞报道：今年是中央红军长征胜利70周年，江西赣南又一次成为世人瞩目的焦点。今年1—7月，赣南共接待红色旅游人数186.34万人次，实现红色旅游收入12.85亿元，同比增长近20%。 赣南是全国著名的革命老区，是中央红军长征的出发地和南方红', '2006-09-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDpb43pdHpPfosebh0XmKfT8j6FVTc7g8SE_2bPFQM2KvBsDzMfgDh-Pi0Fzda_jsZIenkajfzIaYXhmdd8GJtG2JTRPLqkAqu3yihoQDtvGl87Fk685ScuydhOKDpFAfc_V-O19RyBeA==&uniplatform=NZKPT&language=CHS', '红井_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1989, '报纸', '瑞金：叫响红都品牌', '廖国良; 刘春春', '经济日报', '经济日报', '旅游协作;红色旅游产业;', '本报讯 记者廖国良、通讯员刘春春报道：在全国各地纪念长征胜利70周年活动的助推下，“红色故都”江西省瑞金市各个旅游景点游人如织，热闹非凡，全国各地游客纷至沓来，参与“长征体验游”、攀登“长征第一山”、品尝“红井”甘泉…… “红色故都”瑞金是共和国摇篮', '2006-09-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDYQcl2P0EktQ8nXYFs4L70EB9W-UOdYtW5DZQhh5qf9oQKi-51NuQh_TCRss_IniBheDEX8VNGyZBbEAM19I-trXf8EKSEuVCmZkz8La3TgjcELe3OOC0i3L_lK8ZgBr6dGgJ1RBToWw==&uniplatform=NZKPT&language=CHS', '红井_screened');
INSERT INTO `ds_article` VALUES (1990, '报纸', '用长征精神不断激励自己', '王庆环; 李斌', '光明日报', '光明日报', '长征精神;红军长征;长征胜利;', '“能看到天安门升起的国旗,太激动了!”9月2日,当一面曾在天安门广场升起的五星红旗,由专人从首都北京护送至江西瑞金,展示在瑞金市沙洲坝八一希望小学的同学面前时,许多小同学都发出了这样的感叹。  在离沙洲坝八一希望小学不远的地方,就是小学课本中写到的著名的“', '2006-09-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBAAyFGB6_xqhJiF768JNXGobbfz0PcJB08rfUZ3t_dmy3KlwqVdnTS9ogP4BhuDpIXx8EUILTvhovVJtyEGyVnC8jY2LDKn2Qpe5pBOlSyPmTXDToViaGmfLQtncIlNF6c6gY1SQfZ-g==&uniplatform=NZKPT&language=CHS', '红井_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1991, '报纸', '长征出发地 今朝更豪迈', '廖国良; 王姜钟', '经济日报', '经济日报', '长征精神;瑞金市;云石山;', '开栏的话 长征是中国共产党领导中国人民英勇革命的壮丽史诗，长征给党和人民留下了宝贵的精神财富。伟大的长征精神，就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神；就是为了救国救民，不怕任何艰难险阻，不', '2006-09-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDDKtjceqNeCyrNW62xPrT9XQc-mKuNmreB4HYF5jaNRK0LalVWyHRLoVdodQ4yY6mcFN8P8QEOsNsth6uoEB9D1ZMlZmbOTprQyFMmubw4o9Us3QaN_dEjf0lIFEgIllAXPy4epeaHaQ==&uniplatform=NZKPT&language=CHS', '红井_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1992, '报纸', '瑞金：“红井”为“红色故都”添彩', '赖永峰; 梁海洋; 王先文', '经济日报', '经济日报', '瑞金;红都;', '说起江西省瑞金市沙洲坝的“红井”，许多人都会清楚地记得小学一年级的语文课文————《吃水不忘挖井人》。这口由一代伟人毛泽东1934年亲自带领着当地干部群众开挖的水井，是党和政府密切联系群众、关心群众生活的历史见证。人们把此井称为“红井”，并特意在井边立了块石', '2006-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDQn6kQPJh8WAnhGNX4hI4BNi-PezNPASHD1SznOPMFDVGeJDQXd-eWBGITECzLAgPvY7wrAwyl4CCbArneQu5soG8WS3wknnpKdF1Ov34AhG893Sy3MrBx_rBEoOYfIilFpOxOqYYd-A==&uniplatform=NZKPT&language=CHS', '红井_screened');
INSERT INTO `ds_article` VALUES (1993, '报纸', '红色旅游成为新亮点', '', '人民日报海外版', '人民日报海外版', '红色旅游;叶坪革命旧址群;新亮点;', '本报讯　近年来，红色旅游作为一种新型的主题旅游形式，在中国大地逐渐兴起。中国共产党在各个时期领导革命斗争的重要纪念遗址和纪念物，成为人们参观旅游的热点。在刚刚结束的春节旅游黄金周期间，到主要红色旅游景点的游客超过百万人次，成为一大亮点。 为适应市场', '2005-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDwsBlGRqdcReeq5HwI5x0zxEAqG7YjLMvsfcxDni2OFoEAKIas23MxY-Y6q7MRKKUhOfAnpWUdiMa_US2NSoCS1N84LMH0fJSdvIDQINDRX8llK715eyTQBkHULZaJQ33y3fcZVQX9tQ==&uniplatform=NZKPT&language=CHS', '红井_screened');
INSERT INTO `ds_article` VALUES (1994, '报纸', '“红色文化”激荡瑞金', '刘春春; 刘亮', '光明日报', '光明日报', '红色文化;瑞金市;', '江西瑞金是闻名中外的红色故都,近日一部再现瑞金籍红军女战士长征途中不幸掉队、流落草原却时刻不忘寻找队伍的故事片《心动岁月》又在瑞金首映,引起红都人们的强烈共鸣。 “红色书籍”——光大革命历史  打开瑞金市小学四年级以上学生的书包,会发现他们比别的地方的学', '2004-04-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAjc_GO5qPPeEYZpCq6mriEilUBgbJOdky8d_1xZ_HfzCBeHoxdTCgcadFyxXEeaQAZLEAEFgbMHM03jHfgmc1jR--t_egAKabnE5V7rC4W9dEuy8YkoiyETX9GNR-WxiTWsxbB_5n7OA==&uniplatform=NZKPT&language=CHS', '红井_screened,十送红军_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (1996, '报纸', '江西瑞金红色旅游火爆', '姜建明; 张树生; 杨荣强', '人民日报海外版', '人民日报海外版', '革命传统教育基地;红色旅游;', '本报讯 “喝一口红井水，登长征第一山，探访中央革命根据地纪念馆，游览叶坪旧居旧址群……”，连日来，江西省瑞金市以红色故都的形象吸引着四面八方的游客纷至沓来，接受革命传统教育。瑞金红色之旅升温，每天前来接受革命传统教育旅游的人数就有一二千人。 瑞金是享', '2003-07-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDy2KQkU0WFt4YO9rjdc5kRv_bkpocYYheUy2coajCLpqF_7H6vEZDmkHiEqJEcdVnKtHOni6gRaBIcLsj_KdYDkPRPCyS_EP0FOVFcXGFRgu329yWwAehX-LwdL4ORrpBL2Pv4-dNk1w==&uniplatform=NZKPT&language=CHS', '红井_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (1999, '报纸', '走向胜利之本', '焦然; 刘文杰; 冯瑛冰', '新华社;', '新华每日电讯', '群众路线;江泽民;巩固政权;瑞金县;李自成;开国大典;共产党人;中国共产党;', '从瑞金到北京，是一条充满血与 火的征战之路，其间经过了万里长征、 8年抗战、3年解放战争的生死较量；  从红都到首都，是一条前仆后继、 开拓奋进的胜利之路，红色的理想如 星星之火从这', '2001-06-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIByodUCtsacZRLB4A3OinZuY3xxDoohiDADdP0HIJmN1ebCcspS9VBR2bK04-k88QRr444NW13K_BB4vNuAOh16lEWED8bhSKnSzn_CP-2V36taftlR5pWDnwq0IzGLVzV1WIAqyq8SNA==&uniplatform=NZKPT&language=CHS', '红井_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (2000, '报纸', '瑞金创建革命传统教育名城', '赖雨亭; 王先文; 王绍雄; 胡晓军', '光明日报', '光明日报', '革命传统教育;中央革命根据地;', '本报讯（通讯员 赖雨亭、王先文 记者王绍雄、胡晓军）江西省 瑞金市注重发扬红都优势，不断丰富教育内容，大力开展创建革命 传统教育名城活动，取得了明显成效。“红色故都”已成为培育爱 国主义精神的摇篮。  瑞金保存180多处', '2001-06-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICMsakhb_uJ1Bl0-Vly6tI0mEmXJXod8GvhYid58GPDS2uZGNGd4pL_oZuHShTdNSxEhze0AF_SDM8sWfwcGbQ7JggPnWLhvSJ-Ucv1YfIonK5lp4k82U9W1qiOp_cd6i__uxipdJZPHQ==&uniplatform=NZKPT&language=CHS', '红井_screened,叶坪_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2006, '报纸', '石榴花开映铜城 同心筑梦绘新景', '', '甘肃省白银市民族宗教事务委员会;', '中国民族报', '民族团结进步教育;中华民族;石榴花;', '白银,一座以贵金属命名的城市。千百年来,汉、回、东乡、藏、蒙古等民族在这里互嵌融居、共同生活,休戚与共、亲如一家,展现出一幅多民族、多文化交流融合的美好画卷。 自2021年被命名为“全国民族团结进步示范市”以来,甘肃省白银市进一步深入贯彻落实习近平总书记关于加强和', '2022-11-25 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2022.001187', '会宁_screened');
INSERT INTO `ds_article` VALUES (2008, '报纸', '为了祁连山下那几千年的文脉', '李韵; 宋喜群', '光明日报', '光明日报', '中国工农红军西路军;文化遗产保护;敦煌研究院;文物安全;甘肃省博物馆;文物保护;高台县;红色基因;祁连山;', '在这里，诞生了世界上最早的彩陶。 在这里，“人文始祖”伏羲“一画开天”创立了古老的华夏文明。 在这里，秦王朝先祖奋发崛起、称霸西戎。 这里是中国北方农业文明的源头之一，是古丝绸之路上的交通要道，是石窟艺术之乡，也是一片红色的土地。 这里，是甘肃。 在中国', '2022-07-06 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.003125', '会宁_screened');
INSERT INTO `ds_article` VALUES (2009, '报纸', '红色旅游专列：将红色地标串珠成线 红色记忆“圈粉”又“圈心”', '程佳', '中国文化报', '中国文化报', '旅游专列;产品升级;红色文化;革命老区;红色旅游产品;红色记忆;', '党的十八大以来，习近平总书记在地方考察调研时多次到访革命纪念地，瞻仰革命历史纪念场所，反复强调要用好红色资源、传承好红色基因，把红色江山世世代代传下去。红色旅游专列是旅游新业态，是红色文化和旅游融合发展的新空间。“流动的红色课堂”与静谧的红色故里的结合，', '2022-06-18 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.001792', '会宁_screened');
INSERT INTO `ds_article` VALUES (2010, '报纸', '甘肃：“云”逛馆让“红色”陇原更有故事', '罗赟鹏; 张陇堂', '中国旅游报', '中国旅游报', '红色景区;甘肃省;红色文化资源;会宁会师;“红色”;', '近年来，甘肃省的红色文化资源不再局限于让游客在固定地点参观学习，而是跨越时间和空间，将发生在陇原大地上的革命故事通过云端走向大众。 云上传播形式新 在“会宁大会师”微信公众号上，点击会师旧址景区VR，网友即可在线浏览会师旧址大门口的实景展示，伴随着语音解说', '2022-02-10 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.000369', '会宁_screened');
INSERT INTO `ds_article` VALUES (2014, '报纸', '又见会宁红旗扬', '贺美华; 孙晨; 李珊', '解放军报', '解放军报', '红军长征;红四方面军;', '深秋清晨，蜿蜒的祖厉河静静流淌。黄土地上，一座小城静卧在河岸边；城头上，鲜艳的五星红旗迎风飘扬。 在红军长征胜利85周年纪念日到来之际，西部战区陆军某旅官兵来到红军三大主力胜利会师地——甘肃会宁，追寻红军足迹、缅怀革命先烈。 由“会师门”入城，一座通体', '2021-10-26 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006733', '会宁_screened');
INSERT INTO `ds_article` VALUES (2017, '报纸', '把红色基因和光荣传统内化为神精动力', '宋喜群; 王冰雅; 法伊莎', '光明日报', '光明日报', '红色基因;兰州大学;党史学习;光荣传统;', '2021年盛夏，兰州大学723支团队、7271名青年学子以线上线下相结合的方式，奔赴全国30多个省区市，开展暑期社会实践活动，将党史学习、理论宣讲、志愿服务、就业实习等内容纳入青春的行走，用脚步丈量祖国的山河大地，用热爱思考如何实现报国之志。 习近平总书记在庆祝中国', '2021-08-23 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.004316', '会宁_screened');
INSERT INTO `ds_article` VALUES (2019, '报纸', '长征精神照耀小康路', '叶海晨', '中国劳动保障报', '中国劳动保障报', '会宁县;就业扶贫;公益性岗位;劳动力;长征精神;贫困户;', '甘肃会宁，一方红色的热土。1936年10月，中国工农红军一、二、四方面军在会宁会师，标志着红军长征胜利结束，在这片土地留下了宝贵的精神财富。 几十年来，会宁人民继承革命先烈遗志，为美好生活不断奋斗。在脱贫攻坚的征途中，会宁县人社部门党员干部传承红军长征精神，', '2021-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICfOJ1lX5vdZkJiuCJmTyjHVGxdCTjm1EJorrsAIx9l6ofSPo5CHioipSpdNU3n5Eb-zPAtK-aqAm3E5Ubga7RJBlA5hS4s99lET8chfz5Si69isgL7KLszT8Ekl8KBdBFCTCZ28Q33OA==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2022, '报纸', '红色陇原幸福花开', '银燕', '人民日报海外版', '人民日报海外版', '红军长征;古浪县;中国工农红军西路军;腊子口战役遗址;高台县;', '“仲夏时日长，陇上风光好。”7月的甘肃，正是好颜色。 甘肃是一片红色的热土，是红军长征经过的重要省份之一，也是红军长征走向胜利的地方。中共中央在这里作出重要决策，选择陕甘革命根据地作为落脚点，开创出中国革命的新局面，会宁作为红军三大主力长征胜利会师地永载史', '2021-07-19 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.004022', '会宁_screened');
INSERT INTO `ds_article` VALUES (2024, '报纸', '祁连黑河作证 陇原公安初心永照', '孔大为', '人民公安报', '人民公安报', '派出所;红色资源;红色基因;中国工农红军西路军;公安局;习近平总书记;山丹军马场;', '巍巍祁连，滔滔黑河。 1936年，中国工农红军西路军英勇西征、血沃祁连，在极端艰难的情况下，用生命筑起顶天立地的精神丰碑，为人民留下光辉的红色印记。 2019年8月20日，习近平总书记来到甘肃省张掖市高台县，瞻仰中国工农红军西路军纪念碑和阵亡烈士公墓，参观中国工', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003746', '会宁_screened');
INSERT INTO `ds_article` VALUES (2029, '报纸', '牢记嘱托谱写新篇章 砥砺前行奋进新征程', '尹弘', '甘肃省委;', '人民日报', '生态安全屏障;习近平总书记;', '今年是中国共产党成立100周年，百年征程波澜壮阔，百年成就催人奋进。甘肃是西北地区最早建立党组织的省份之一，在中国革命进程中发挥了不可替代的重要作用，以南梁为中心的陕甘革命根据地具有“两点一存”重大意义，会宁作为红军三大主力长征胜利会师地永载史册。 在党的', '2021-06-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.005790', '会宁_screened');
INSERT INTO `ds_article` VALUES (2031, '报纸', '奋力走好新时代的长征路', '', '经济日报', '经济日报', '长征路上;共产党人;', '从江西于都到甘肃会宁，历时两个多月的“记者再走长征路”主题采访活动正式落下帷幕。日前，习近平总书记对此次采访活动作出重要批示，对广大党员、干部提出明确要求，希望大家牢记党的初心和使命，牢记党的性质和宗旨，坚定理想信念，坚定不移贯彻党的理论和路线方针政策，', '2019-08-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDTATIpYecxMzpl8DlcTeGHtBpd-m6D41fQyuIHz0t2Lhj5DJqqq7-oaexijWcVLmOXvNiavXradiwJ1KJGpvXSoCxuJMJChTqN9gUYtrNKMcLa2sLE6s_3h47ePnb5x-vu_EtZ0APN8Q==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2033, '报纸', '罗南辉：喋血长征的青年将领', '吴文诩', '人民日报', '人民日报', '罗南辉;兵运工作;红四方面军;', '新华社成都10月13日电 （记者吴文诩）在甘肃省会宁县中川乡大墩梁一座普通的山岗上，长眠着800余名红军指战员，年仅28岁的副军长罗南辉是那场阻击战中牺牲的红军最高将领。如今，苍松翠柏掩映下的红军烈士纪念碑，默默诉说着82年前那段悲壮赞歌。 罗南辉，1908年出生于四', '2018-10-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDA6YtZ01aLVsGAEJOFCS6rIkKDEgvCfExAkoVTReUi8JJTRvGXuYe_kzu_Nm-UfCoHhZGf6Fn5kdMvb3rGzrr2i5msUH-HmwuSRKQ7coSw3QY47ZVMCQBnza538G8VOTMk-MPiRLWpFw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2034, '报纸', '扶贫之要贵在精准', '廉维亮; 刘婕', '人民政协报', '人民政协报', '精准扶贫政策;扶贫攻坚;精准识别;', '80年前，中国工农红军一、二、四方面军在甘肃会宁胜利会师，波澜壮阔的二万五千里长征宣告胜利结束，中国革命展开新的篇章。 毛泽东曾说：“会宁、会宁，红军会师，中国安宁。”在会宁这片沟壑纵横的陇原大地上，淳朴善良的汉、回、东乡等多民族群众一直在贫瘠的土地上', '2016-12-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDc0SVIStpxkSeJ_dFeDpm1XTjy9IEsjGOpYKN3MGcomwxU031PBRCiSgH1sR1MkAL98OcWt6C0HvFjwaBQZsQJ0_ImhREvmUYW5tmzPK-1zYTDVoqLy0dhiWgIEYjA7oAuASfb04EarQ==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2036, '报纸', '《大会师》：在回望历史中重温初心', '陈先义', '解放军报社文艺部;', '光明日报', '革命历史题材;《大会师》;创作者;', '纪念红军长征胜利80周年之际，一批关于长征题材的影视作品相继问世。在这批作品中，表现红军第一、二、四方面军会宁会师的电影《大会师》以其别具特色的艺术呈现受到观众的关注。这部恢宏史诗，为革命传统教育提供了一部极其生动的教材。 关于长征的题材，从电影到电视剧', '2016-10-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICNBXdhYhYAZfUJ3EKwVbYPhs96AnU7Tig3Jir98ZCTwqtBeNtM8aADDCoIs2rnX1LN5IoYI089V3ZsfbjI7WRDdKV1tn-rDmF0SafqMPYBSA-krPZ5ZfLo6DJpYJrUP6yn9kTtjoFWXw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2039, '报纸', '甘肃：探索经济欠发达但文化资源富集地区的发展新路', '崔立勇', '中国经济导报', '中国经济导报', '经济欠发达;华夏文明;创新区;传承创新;王三运;', '“我们跟发达省份拼经济、拼人才、拼科技，没太多的出路。可以拼的就是文化、资源、特色。甘肃是文物的集中点、华夏文明的闪光点，发展文化产业是甘肃省转变经济发展方式的支撑点和新的经济增长点。”甘肃省委书记、省人大常委会主任王三运曾经不止一次地这样说。如今，王三', '2013-02-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBC7usP5GJa9F07QLJZttRpBW682nN6pxbWnIi8p-uVHr3bnB8FbB2J0PaAUl6J8kBd9SrAdYX58hVncwEzWCLcA_ITRvHfs5UHCm855t4-YGHMjIPLf-szF0xHo1ren5lOaZX7iFgjSQ==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2044, '报纸', '红色,不只是一条旅游线路', '司晋丽', '人民政协报', '人民政协报', '旅游线路;红色旅游;红色资源;', '编者按 今年是辛亥革命百年纪念，也是中国共产党九十华诞庆典之年，经历了近年来的持续发展，新形势下，可以预计，全国红色旅游形势会更加一路飘“红”。记者从国家旅游局了解到，加大红色旅游宣传力度，是今年全国旅游工作的重点之一。为此，本刊开设此栏目，采访', '2011-03-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBivOqy7EGngs6Oc_PjMZeJhY3pVhlhQZq6aCKfikpuU5pDwz68SNmRxQO3ExmOdj3gtHmqgz-smOFn-juyLfWGsgiyvrFErGZ7mZrZdEX_Wfq2pY6XRGJdPOb8yymxNp6uSsekH0zYgg==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2045, '报纸', '会宁红军长征胜利廉政教育基地', '', '中国纪检监察报', '中国纪检监察报', '会宁会师;红军长征;廉政教育;', '会宁红军长征胜利廉政教育基地——红军长征胜利纪念馆，坐落于红军三大主力会师圣地甘肃省会宁县城西的会师园内，是为纪念中国工农红军第一、第二、第四方面军主力胜利会师而建设，由会师陈列馆和会师广场两部分组成，与周围的会师楼、会师塔、会师联欢会址、革命文物陈列馆', '2010-09-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC0qwlnLkbf3k2dqosZioXM1LDAOkyGJAAOTN4aGrYdkiQFL41IADgdORJiS7erg8HE1yMwvbN_2ZiYis8y--WwX7guD5RCgcmM3tLy6Y-eAQF3gRdKGZTwSGDRs9dNshbVbB37z59ssQ==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2047, '报纸', '打造红色旅游名城', '周仕更 ; 徐万佳', '中国旅游报', '中国旅游报', '旅游名城;红色旅游产业;会宁县;', '会宁地处甘肃省中部、白银市南端，是甘肃人口大县，因红军会师享誉全国。 1936年，中国工农红军一、二、四方面军在会宁会师。毛泽东、周恩来、朱德等老一辈无产阶级革命家和10大元帅中的9大元帅、10位大将中的8位大将、46位上将、127位中将、1200位少将都在会宁留下', '2010-08-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAOtly8hQ7EZh1Citgk1VDxHHycp_GK2h5YKM59BBgDSNyk6mPn8d5oGOMVvMKvYgODAIfSuRR7vA2lT7YU2Hc3RXvS5wFFStj81-qME5ULsPYPcNLIKqvsJ9arG3Q2mX3rekRzNVU2yw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2048, '报纸', '红色土地上的歌者', '杨爱芬', '人民邮电', '人民邮电', '政府网站;会宁县;', '人物档案 王兰强，1963年出生，大学本科学历，通信工程师，中共党员。1984年12月参加工作，当过线路员、农话管理员，现任中国电信股份有限公司甘肃会宁县分公司党支部书记、分公司经理。 王兰强曾先后18次荣获过电信企业先进工作者和“双文明”建设先进个人称号；1', '2010-06-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBFosi3fFQfTv6ds_um8BX0khv-phKMIKQuey6flF4MDmN8OyNPBEfPhYZ0-I6xzKM5TIcz6l5btfb93XZAtxo5ZD2i5eIr1I0b2j0lHhN4RZlDuZiZBD20JSOcpb6KcNA5bhpxctxFww==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2049, '报纸', '甘肃会宁有了全国廉政教育基地', '牛莹', '中国旅游报', '中国旅游报', '廉政教育;红军长征;甘肃会宁;', '本报讯（牛莹）近日，甘肃会宁红军长征胜利廉政教育示范基地被中央纪委、监察部列为第一批50个全国廉政教育基地之一，是甘肃省唯一一家被命名的廉政教育基地，成为广大党员干部接受廉政教育、加强党性锻炼的重要场所，是广大群众培养廉洁意识、弘扬清风正气的重要阵地，青少', '2010-06-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBhQwauNXLQm20PZ5wKDzAxNVxydzuzayG9VQoaZVxLRsOv7FtQ9BopkkkK54k3V6bigqdmELhI6mjg3Ng8r038TrarQ_AUthu1mJuvbxLh2oO8cGKogrXq3W04fGNPt5gfFqb4ZNQuQw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2050, '报纸', '第一批全国廉政教育基地名单', '', '中国纪检监察报', '中国纪检监察报', '廉政教育;', '北京市  中国人民抗日战争纪念馆  天津市  周恩来邓颖超纪念馆  新中国反腐败第一大案展览馆(天津市反腐倡廉教育基地)  上海市  中共一大会址纪念馆  陈云故居暨青浦革', '2010-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDR1dkjMA1hXVh4mjf55s9e6PueeHGSMajYlReYZxTsTysUec_ggsw-9Q-soF0RU9cQigeaxH5lYf31-mtypqRiNpckE_953BvfqcGZ901snJtZmNpwRpu4zen-5AwT9ch0sgax7oPlTA==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2051, '报纸', '会宁红色旅游成为甘肃旅游新亮点', '牛莹; 张陇堂', '中国旅游报', '中国旅游报', '红色旅游;甘肃旅游;新亮点;', '近年来，甘肃会宁县以“打红色牌，建全国旅游名城”和“旅游活县”的模式，大力发展红色旅游，使会宁成为享誉全国的红色旅游胜地。 会宁红色旅游发展迅猛 会宁红色旅游资源十分丰富，有历经烟雨的会师楼、三军会师纪念塔、红军会师遗址、红军长征胜利纪念', '2009-12-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBcEYPusYfBT1HXTDOijdPP1e-eWLRXfALqjswQJZdx7eOHAkB7WffqWFaU_LUXB9SJY83Tgaz0Jsr5P3X1DuXnlOaHWbmOSEgZxzUvMYXSdnk7NAouMbY7MZrkkDnqv9l3HqIvUQDmuw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2052, '报纸', '首批国家国防教育示范基地', '', '中国国防报', '中国国防报', '烈士陵园;教育示范基地;', '北京市 中国人民革命军事博物馆 中国民兵武器装备陈列馆 坦克博物馆 中国航空博物馆 中国少年军校总校 中国人民抗日战争纪念馆 北京平西抗日战争纪念馆 北京焦庄户地道战遗址纪念馆 北京市西城区中学生国防教育中心 天津市  平津战役纪念馆 大沽口', '2009-11-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICzvRMSFD3wbOtmDYLDue3g25gEe1O11jD1DsWfnQIe7ZhzB0vdJE-KDkBy-cFjttiXlq5QWsyEE3mbF9Qd4742Onr0cGvJgd-zYCmBKK75PbUSBXGoX3VkZj68zvNC5YwIMUbUGRknIw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2053, '报纸', '会宁是个好地方', '杨祖荣; 马三成', '解放军报', '解放军报', '会宁县;三军会师;', '陇中会宁，因两点闻名： “山是和尚头，地上无水流”。这里十年九旱，生活在这片贫瘠土地上的人们，祖祖辈辈都在与残酷的大自然苦苦抗争。会宁，首先以旱、以贫困闻名。 会宁，又有着辉煌的历史。 它素有“秦陇锁钥”之称，建县的历史可以上溯到2100多年前，历史文', '2009-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAQGEbQU9_5DjjXU7pmmyMfsBcudK4IAOIlPv1UKj6nBBPsLZ4Hjapgn82XnXgAojUxEv1IaMfO1_9fWDmolUHI7AZLFahCSz5c6q_HacDEGmdE3LFz0sEGH_woRXvs57hoVIVNDjed6A==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2054, '报纸', '红色会宁绘新图', '李战吉', '人民日报', '人民日报', '中国工农红军;会宁会师;旅游名城;粮食总产量;红军长征;红色旅游;会宁县;长征路上;', '73年前，中国工农红军第一、二、四方面军汇聚甘肃省会宁县城，在素有“秦陇锁钥”之称的这块热土上播下了红色的种子。今天的会宁，广大干部群众缅怀革命先烈的光辉业绩，继承发扬会师精神，走出了一条贫困地区科学发展的特色创新之路。 科学发展走新路 193', '2009-08-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA0kjxoE72Jw8XLM7fqOOoCzVsRboulLIQOniotjEnBp_NpHfiVWCwBSDKtehxiRpHvYoRLDyj1h5wXvfHPLc0T0Mu2bUeP3k7OEyB9bwTsNoLXWfuTacZUA7cllh3DZ1smiZ6Bx76Lew==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2055, '报纸', '会师镇里变化多', '牛瑾; 李琛奇; 金晶', '经济日报', '经济日报', '会师镇;会宁县;', '讲述者：杜守琴 1933年生人，祖籍河北邯郸，1964年因工作调动来到会宁，1994年退休前任会宁县委党校校长。 会师镇是会宁县城所在地。杜守琴的家就在县城中心，是一处平房，挨着会宁县委党校。不大的院子里，一口水窖格外显眼，这也算是会宁的一大特色。虽然退休多年', '2009-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAGsKypwYQGzH22X-1OonFS4DCDXlUPI2DXqyAVChbI9OXjS8yJzFQUNSIwknyDp4WLMOb6OJrlpegcdRkMwGOuq9ID6ep9Au-bZY3xX9iQ4K80BTHtbNDXf4jZ5BJgjbY8ZTDFkVVYug==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2059, '报纸', '胡锦涛总书记在甘肃同各族干部群众共迎春节', '孙承斌', '人民日报', '人民日报', '胡锦涛;', '新华社兰州２月１７日电 （记者孙承斌）春节将至，陇原大地处处张灯结彩，一派节日景象。在这万家团圆的喜庆日子里，中共中央总书记、国家主席、中央军委主席胡锦涛来到甘肃，看望慰问各族干部群众，代表党中央、国务院向全国各族人民致以节日的问候和新春的祝福。', '2007-02-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDQjBz-e11fTDygGrcHmTuJMihyr6WKgkFl9gn4fxv3htEspqkShw9rSSePUnbAldItk1etVk2OgvdczM2sPC5OyHmvdqY_HAfwRhZKW4FCBxkBVsUc9oZsMDoEd-c7ZuEChU08QPy_vA==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2060, '报纸', '总书记问年景看水窖察粮仓拉家常', '孙承斌', '新华每日电讯', '新华每日电讯', '胡锦涛;全面建设小康社会;', '新华社兰州2月17日电(记者孙承斌)春节将至，陇原大地处处张灯结彩，一派节日景象。在这万家团圆的喜庆日子里，中共中央总书记、国家主席、中央军委主席胡锦涛来到甘肃，看望慰问各族干部群众，代表党中央、国务院向全国各族人民致以节日的问候和新春的祝福。  2月16', '2007-02-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICB-7gXSQi4Lu-HOwe3oDw8LU9n4-nLNAdJ80i5Sedpa2kIu9u3RbEvlAOt6isbWmb5DJApx6KjtWij3HyHwCGLxqNzbPrshvV1EKhGkTAw9XinVZ9Ntwx-2ThQHVEFuyqNLM7OlhbYlw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2063, '报纸', '“八一爱民学校”,沿长征路已建成90所', '朱鸿亮', '新华每日电讯', '新华每日电讯', '长征;', '新华社北京10月30日电(记者朱鸿亮)截至10月底，全军和武警部队沿长征路援建的112所“八一爱民学校”，已有90所竣工并投入使用，2所因自然灾害原因推迟到明年建成，剩余20所将于11月中旬投入使用。  据总政治部有关部门负责人介绍，这次援建的“八一爱民学校”主要分', '2006-10-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDbJwScgI_nEFsysUiS-R-OI9lFNxszKIrsaXK8bI4_ryC2gA6HHDl_K6m66R1gKQAZ7KlL7Q3snMnEKjlhtsS4xtcLWjSbcyENp1J_RSbZrjnUJbS0N8KNg2iIaTyf-hIQyiVwzDB1FA==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2065, '报纸', '会宁——红军万里长征胜利之城', '赵彤', '人民政协报', '人民政协报', '会宁县;红军长征;马铃薯产业;', '古城会宁，位于甘肃省定西地区 东部，北靠靖远，西连定西、榆中， 南接通渭，东邻静宁，与会师有着非 同寻常的渊源。公元554年，北魏丞 相宇文泰、北周武帝宇文邕率师西 巡，两度在此会师，会宁因此得名。  1936年9月下旬，中共中央在', '2006-10-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAjzDVeQLzhqEHoHa3kR2hIQyBjlJ5j5aoT6cRBpQRzwg36YIoSsyQ2G7uFDtEwIgLxGR6BQLhEbgCA4s9M0OTIXBxMh7Z7i8dMnTXFJ7FbnsYFihgSyp6NHGH1Unh8rwQr9EtcZemGdg==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2066, '报纸', '她们的长征', '', '中国妇女报', '中国妇女报', '红四方面军;张琴秋;女红军;妇女抗日先锋团;川陕革命根据地;', 'T在红军长征千山万水 的跋涉中，有一支特殊的力 量──女红军。  饥饿、疾病、伤痛、死 亡，她们与男性战友一起， 经历了血与火的考验，创造 出妇女革命史上的奇迹。  爬雪山、过草地；冒酷 暑、趟江河；啖草根、嚼树', '2006-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIATtjpAJAooNdYiQDLDg3lUdKHViMyI_Qx5raqHvb3hmAIXBMoJYXMknOZiXPmaGuqHdLdenkdqYJPtV3jcBNhI1jUi53wcmiFH3e2r_CIwDHx_pD5bX0r2-LNaYBFDb_IFjHG456kPVQ==&uniplatform=NZKPT&language=CHS', '会宁_screened,红四军_screened');
INSERT INTO `ds_article` VALUES (2070, '报纸', '“会师”成为城市的名片', '方方', '中国经济导报', '中国经济导报', '会宁县;桃花山;红军长征;红色旅游;特色产业;', '1936年10月，中国工农红军第 一、二、四方面军在甘肃会宁地区胜 利会师。红军三大主力会宁会师是 长征胜利结束的标志，是革命力量 大团结的典范，是中国革命走向胜 利的转折点和里程碑。会宁因三军 会师，将星荟萃而彪炳史册，成为举', '2006-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICKfenk06457qlGbXw4qNbvD2_65OtGftUFTyGfUbyRZQdfGe4-KcLFGK8fRRPWksZN_5hCbv6OmLKWFMQ5mFX7_6JKZta7mCvmwyQuj_eHJWQg2V9R2c_YgQyHfqXtkBsPfol8F53Peg==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2071, '报纸', '红色旅游火了“会师地”', '方方; 苟晓晨', '中国经济导报', '中国经济导报', '红色旅游;会师楼;红色旅游产业;', '1936年10月，中国工农红军 第一、二、四方面军在会宁境内实 现了胜利大会师。红军会宁会师 是长征中的重大事件。红军会宁 会师期间，毛泽东、朱德、周恩来、 刘少奇、邓小平，李先念等老一辈 无产阶级革命家，十大元帅中的 九大元帅', '2006-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA25vL_W7mMLZzAfV081nw1iMR0OTVID10OPSYFOp_a5AVI5qPp-ruZ7q6NZeTIKae2qdQ7g98wHKH5fwLH376tHvueBSKWUQDdgLWrogfmGVSPSUo_PKMfuxvF9sQd30VAuCaIRql3yg==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2073, '报纸', '“电视进万家”情暖长征会师地', '李战吉', '人民日报', '人民日报', '电视机;', '本报甘肃会宁１０月１８日电　记者李战吉报道：“今天，政府给我家发了一台大彩电，也将党的温暖、党的关怀送到了我们这些老汉的心中，真的太感激了！”会宁县老八路裴大乾激动地说。今天下午，在红军长征一、二、四方面军会师地——甘肃省会宁县，“电视进万家”工程发放仪', '2006-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB-mx7ZpYYQ7S8VVL_8F087etZEsAhDQ7kp_Mea3hPIswrJ1t6oRd6XKI8vfrwn3OwYN_p_zhAP3XHLz2KetJVlOPRw3YRdCJ_0lganTQ14rTvkxLgPcJ8uo_vKQabGxR0rKsw9ZgQnnA==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2075, '报纸', '长征精神永不灭', '冉鸿章', '四川省气象局;', '中国气象报', '长征精神;红六军团;廖汉生;', '在我3岁的时候母亲就去世了,我们兄弟4个，我是老幺，除二哥和我另外其他两个兄弟都因病无钱医治很小就死了。1934年春天，红军来到我们贵州沿河县。我当时在家放牛,红军是个什么样的军队，我们都不了解，又加上地方上反动分子的欺骗宣传，对红军的到来没有什么兴奋之感。但也', '2006-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDDqAN1mOcrz75iGHsn3BIExUUrCmwivX8do-B3MnHYmFfXsBTdrjEgcpN---7mVIwgtle-bmD-LqRM7xOPf-VSSYdIKCsw36s2jkvqjfHsFB1utmUx-5nq0-SQAKzqW_rXhFX4RrsRgg==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2077, '报纸', '长征从这里开始', '龚达发; 刘建林; 任江华', '人民日报', '人民日报', '长征精神;', '开栏的话  ７０年前，经过艰苦卓绝的万里长征，中国工农红军第一、二、四方面军胜利会师，肩负民族希望的中国共产党和红军实现了北上抗日的战略转移。 长征是中国共产党领导中国人民英勇革命的壮丽史诗，长征给党和人民留下了宝贵的精神财富。长征精神，就', '2006-09-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICGlEYEA3Er49TGEK6Zrsn0HGGkOJPZ7Z2lQEwubRvZnPKO0DpXJRLjhNNVjkuYgcg4rq9NRnatxvNT0LwYlnNihCydnMySdJAnzWX7kgskIMF6M2r6X2RtlP3y_HwFdes2TBA3er_o9g==&uniplatform=NZKPT&language=CHS', '会宁_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2078, '报纸', '甘肃：会师塔见证“东部会战”', '刘兴增; 石强; 范沈强', '中国交通报', '中国交通报', '高速公路项目;会宁会师;平凉红牛;红四方面军;东部地区;', '8月6日17时，当从北京飞往兰州的飞机徐徐 降落时，记者见到了泛着黄色的山梁和沟壑，一望 无际，连绵不绝。在机场回兰州市区的高速公路上， 甘肃省公路局政治处主任张树泉告诉记者，车外掠 过的每一抹绿色都是人们与干旱作斗争的结果。在 这样的黄', '2006-09-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICG0dlJno7bPwl93KSVKN_FYhb6TCBLNMfdQdVK4maRPDE1-eRFuuQ33fJBK814JxcBRT0GZaCw1JSiLcrJqyJbVkNeJ_CAvCTy5HxmJWrWRIGpLQSG7uNK155IyZwAhZ-wIQH4_W53Zg==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2079, '报纸', '本报“长征路上看法院”大型报道活动启动', '杨树明', '人民法院报', '人民法院报', '长征路上;模范法官;', '本报北京8月18日讯 本报“长征路上看法院”大型系列报道活动今日启动。第一路采访记者已奔赴长征始发地红都江西瑞金，和记者共同踏上这片红土地的还有河北省高级人民法院审判员、全国法官十杰陈印田。宋鱼水、金桂兰等全国模范法官也将随各路记者参加采访活动。5位老红军、老', '2006-08-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDlSBUlYVtAsnAkg4h4e1TYjllWmh2DbAembA6g68jtT8KhbIGRzRdKaFnUZrqjY3uf_VDvFZu3wjzgqd21qWNVWH7Qecaooh-ZK2SH7ddw1Q9AD9pWoXZdvASuT0tEPxrDviYjkPdN_A==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2080, '报纸', '会宁 路通·商通', '朱虹', '人民日报', '人民日报', '会宁县;小杂粮;', '１９３６年１０月红军三大主力会师甘肃会宁是长征胜利的标志，５００多名会宁子弟参加了红军。会师期间，红军先后同国民党军队进行了６次较大规模的战斗，有１０００多名红军指战员牺牲。 从兰州到会宁的路上，满眼都是泛着黄色的山梁和沟壑，在这干旱的黄土高原上', '2006-08-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAdp5XgjcsJxElGU7uNAewpbkCfx-Cu-yl7T3_O6ecw8x6vGXM8QMyasev3ufnMlEv4RVihy7FyRFJ_MN_ApXV83THZjnDTnCS-ATFPDmhCH78v8gSh3uU3S9ldI6H23DMZ5F5ptZoTvw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2081, '报纸', '交通人“会师”平定高速公路', '刘兴增; 石强', '中国交通报', '中国交通报', '会师;', '70年前，中国工农红军第 一、二、四方面军在甘肃省会宁 县胜利会师，结束了两万五千里 长征，使中国革命发生了历史性 转变。70年后的今天，来自全国 各地的32支公路建设队伍再次 在这里“会师”，沿着当年红军留 下的足迹开始了长达250多', '2006-08-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA2czrQTaPeMSCgZu5wBYy-1kL3jg8nFD7-XKb0KL1wAR6Hk0PXj92JEl_6qR_Pd9jcRiEjHzYS-dOwW8pBoyJcntEsZNJtQQtX4ZbADT7FIRykxs_ZWsoMluPZ3aZUF-TZ-_QxTplbbQ==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2082, '报纸', '罗南辉', '', '人民日报', '人民日报', '罗南辉;兵运工作;红四方面军;', '罗南辉,又名罗曼、罗敏。1908年生,四川成都人,曾在成都一家水烟铺做工。1926年入川军江防军第7混成旅当兵。1927年秘密加入中国共产党,在所在部队从事兵运工作。他团结教育下层士兵,组织成立了“士兵联合会”,同反动军官作斗争。1929年6月参加第7混成旅旅长邝继勋等领导的遂宁', '2006-04-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBW0YvfGmKphCHc58y6Tt5SuPNzIYZKhtaDFWa-lLSSN0ZtHFJyRtVxsY8B_beEyijA58Cl_6r-BKNSjgUzDcYg4ZDqOqIuCBhToU4rM_hiPNUCTQ25ojOxfWNoLmkdoc0Sw-IuZBmSAg==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2083, '报纸', '全军和武警部队将沿长征路援建百所希望小学', '郑群; 董强', '解放军报', '解放军报', '武警部队;希望小学;', '本报北京3月17日电　郑群、记者董强报道：为纪念红军长征胜利70周年，经军委和总政领导批准，全军和武警部队将在长征沿线集中援建102所“八一希望小学”。3月14日至15日，总政在贵阳市召开全军大单位群工部门负责同志会议，部署沿长征路集中援建“八一希望小学”工作，国家教', '2006-03-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID1ZRzql3qGi3F_bQw3XFAs7WrnZMTq9VKpDmvtoUW9zakZPXCmh7F287zn7vi6V47wxJCuzZ6yZWfe6UePYJpJdwP-4X1kiwMIco1I8uDTskc_texjOQv5dViLYfRG9CtfODA4PVZCNA==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2084, '报纸', '吴富莲', '', '人民日报', '人民日报', '吴富莲;红四方面军;团政委;', '吴富莲，1912年出生于福建省上杭县。由于家境贫寒，幼年时被迫做了童养媳。1929年3月，红四军解放上杭，开辟闽西根据地，吴富莲参加了革命，不久即加入了中国共产党。1930年起，吴富莲先后调到中共上杭官庄区委、上杭县委、中共闽粤赣省委工作，任区委委员兼区苏维埃政府妇女', '2006-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAZ37Ih9GbMPpo1wVNWMUVd01tJ3oObWYdN4Z8vXLgvCUTvlvxcK5lsVj7lc8TGVYeBr05GjO0l-580_pLUW9ze8lH4AKSvY6OebrW4PRiNEUcEUWDmDImoXhszQuhIqou8tXr0nx4NYw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2086, '报纸', '当年红军会师地如今高考冠西北', '梁强', '新华社;', '新华每日电讯', '会宁县;', '共和国的国土上，有这么一块神奇的 地方：毛泽东、刘少奇、周恩来、任弼时、张 闻天、王稼祥、邓小平、李先念、杨尚昆等中 国革命史上功勋卓著的赫赫人物，都曾会 聚在这里，并且在这里书写了中国革命走 向胜利的历史。  这块神奇的土地，就是', '2004-11-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICEvA-DSbGe5PITiN1f5wlm8yr_VrcElzWSk5aqdLiNebp6xRUuJc_-FIZUvwq0eZVg2o6UQJHXacouDF00_XxyczvwAowLTGS5SOJcFZZHY2IGOCcKnbkg7iN1zz4oEvyj9oVX9IZ6OQ==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2087, '报纸', '会宁彩笔绘出新画卷', '陈宗立', '光明日报', '光明日报', '会宁会师;红军长征;', '甘肃会宁，历史上曾经是陇中“苦瘠甲天下”的一个穷县。  1936年10月，中国工农红军第一、二、四方面军经过长征，在会宁胜利会师，标志着红军长征胜利结束。会宁会师是中国革命走向胜利的转折点和里程碑。会宁和瑞金、遵义、延安一样，成为红色之都。  红军三大主', '2004-11-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAWTMDSmH_jZ_G104tMrLX8B-QraxHd9n2tT8QdcAK9Thn7FwBKH2pSlulH4ml98kFku3VfnW3Jw9rjVsNf4tAYgMGlA4EWH7Jn9IAheSOCWcEqcwg1qZ6Z3kGAzGz0pBt983QtO0Fewg==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2088, '报纸', '香格里拉当年红军经过时民不聊生如今成了“世界上最美的地方”', '李承祖; 伍皓; 曹滢', '新华社;', '新华每日电讯', '红二、六军团;红军长征;滇西北高原;香格里拉;', '这是一块宁静的土地，这是一个充满 诗意和梦幻的国度。20世纪30年代， 美国作家詹姆斯·希尔顿告诉全世界：在 世界的东方，有一处人类精神最理想的家 园──香格里拉。  无数的证据可以显示，希尔顿笔下承载着人类所有美好理想的香格里 拉，就', '2004-09-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAN_eFxWf1uVm3gXm7_msG1pHD_IcJbZlFPpJq_mjYE2Ij0OisKTM13KlTWIBDfRCTyXFnhmv4Skx1BoGawTZfILbazfdgHBA3k_wgYdldlyu69Il5z3cQKUNEywQU16UPgIc2YNWsecw==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2092, '报纸', '会师楼下唱长征', '蔡晖; 张栋; 李志刚', '新华每日电讯', '新华每日电讯', '会师楼;', '雪后初晴，红白映照着象征三支 长征大军胜利拥抱的甘肃会宁红军会 师纪念塔。  11月19日，沸腾的会宁城万人 空巷。北京军区战友歌舞团的演职员 们来到这里，给英雄的革命老区人民', '2000-11-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDfUNdcZWj5xy9XXi9K5TN9qqIkvPkNSSTEFt44QBjfE8zm9d0enV3TSsfMjBkDDfs1BGwvqediE4T0I5l8AA_8wfbdiKlCPycJQC6PhqkxuD472Faj7UiXbv0Z9PNj5eg6dGpd6ghh0Q==&uniplatform=NZKPT&language=CHS', '会宁_screened');
INSERT INTO `ds_article` VALUES (2094, '报纸', '国家繁荣富强 人民幸福安康', '', '人民日报', '人民日报', '中共一大会址;家国情怀;天安门广场;消防救援;红色基因;幸福安康;', '国旗飘扬，激发爱国力量；国歌雄壮，奏响奋进乐章。 “新征程上，我们的前途一片光明”，在庆祝中华人民共和国成立74周年招待会上，习近平总书记深情寄语，激励亿万中华儿女坚定不移朝着强国建设、民族复兴的宏伟目标奋勇前进。 10月1日，各地开展丰富多彩的活动，抒发爱国', '2023-10-02 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.009997', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2095, '报纸', '遵义：“红色+”赋能文旅产业高质量发展', '吴箫剑; 李惊亚', '经济参考报', '经济参考报', '红色旅游资源;遵义会议会址;四渡赤水;红色文化;', '遵义是贵州第二大城市。1935年，红军长征在此转战3个多月，彪炳史册的遵义会议在这里召开，四渡赤水出奇兵的传奇在这里流传，毛泽东也在这里挥毫写就了“雄关漫道真如铁，而今迈步从头越”的传世名作。 从遵义会议会址到娄山关战斗遗址，从苟坝会议会址到四渡赤水纪念馆……', '2023-07-04 08:00:00', 'https://link.cnki.net/doi/10.28419/n.cnki.njjck.2023.002295', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2098, '报纸', '震撼再现长征路上的壮阔恢宏', '胡芳', '中国文化报', '中国文化报', '《长征组歌》;兴国县;经典作品;红军战士;长征路上;', '忆往昔峥嵘岁月，品不朽红色经典。3月31日至4月10日，大型经典音乐史诗《长征组歌》在江西省兴国县长征组歌大剧院开启第一轮演出。 此次演出由赣州市委、市政府主办，兴国县委、县政府承办，《长征组歌》研究会发起，经典音乐作品《长征组歌》回到并生根在词作者萧华将军的', '2023-04-11 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2023.001341', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2099, '报纸', '讲好党史故事 坚定前进信心', '吴月', '人民日报', '人民日报', '思政课;本科生;虚拟仿真;', '粉笔起落间，红军长征途中四渡赤水、巧渡金沙江的示意图在黑板上渐渐展现。这是天津大学青年思政课教师程斯宇的“中国共产党历史”课堂。通过生动的手绘板书、声情并茂的讲授，程斯宇带领学生们感悟革命先辈的崇高理想和坚定信念。 “我们虽坐在教室里，却像回到了历史现场', '2023-04-09 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.008171', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2100, '报纸', '忆往昔峥嵘岁月 品不朽红色经典', '胡晓军; 王洋; 黄志勇', '光明日报', '光明日报', '《长征组歌》;红色经典;兴国县;声乐套曲;', '“红旗飘，军号响。子弟兵，别故乡……”日前，深沉而又气势磅礴的歌声在江西省兴国县长征组歌大剧院里回荡。这是大型经典音乐史诗《长征组歌》1965年首演以来，首次回归原创故乡的全版演出。剧院内，不断响起经久不衰的掌声，许多观众随着熟悉的旋律伴唱全程，场上场下情感', '2023-04-03 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.001539', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2101, '报纸', '廉洁文化浸润人心', '薛鹏', '中国纪检监察报', '中国纪检监察报', '年轻干部;市纪委;廉洁文化;纪检监察机关;警示教育;廉洁教育;文化浸润;区纪委;', '习近平总书记在党的二十大报告中强调，加强新时代廉洁文化建设，教育引导广大党员、干部增强不想腐的自觉。二十届中央纪委二次全会部署要求，加强新时代廉洁文化建设，树立良好家教家风，营造和弘扬崇尚廉洁、抵制腐败的良好风尚，构建清廉社会生态。 陕西省纪委监委组织推', '2023-03-24 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.001045', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2104, '报纸', '十年引导教育 青年武商茁壮成长', '庄道秋; 莫珺', '中华工商时报', '中华工商时报', '企业家队伍;年轻一代;武进区;统战部;区工商联;引导教育;', '“武进区工商联全面落实《武进区青年企业家培养五年行动计划》，以铸魂领航、赋能接力为抓手，坚持区镇联动、部门联手，创新推出‘1+3’培养模式，‘1’是指新一代企业家培训班，‘3’是指‘走进企业、学习先进’活动，‘走长征路、筑强国梦’主题教育，‘与先锋同行’对话活', '2022-07-27 08:00:00', 'https://link.cnki.net/doi/10.38311/n.cnki.nzhgs.2022.003033', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2105, '报纸', '红色文旅如何圈粉“Z世代”', '郭凯倩', '中国文化报', '中国文化报', '红色旅游景区;红色文化教育;红色旅游产品;红色景区;旅游演艺;文化创意;', '本报集体采写 6月16日，在广西师范大学校团委组织下，该校师生循着习近平总书记的足迹，来到全州红军长征湘江战役纪念馆，开展主题教育实践活动。师生们通过一幅幅图片、一段段文字，全面了解湘江战役的悲壮历史；通过了解革命先辈的事迹、学习编织草鞋，深切感受红军将士的', '2022-07-03 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.001989', '四渡赤水_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2106, '报纸', '长征线上的“检察蓝”', '曹颖频; 张星川', '检察日报', '检察日报', '未成年人;宝兴县;冕宁县;红原县;检察院;公益诉讼;红军长征;检察长;泸定县;红军烈士陵园;检察官;革命遗址;', '编者按　四川，古称天府。红军长征时期，红军三大主力部队先后在川一年八个月，行程一万五千里，越过自然条件极为恶劣的雪山和草地，留下泸定桥、红军长征纪念碑等重要革命遗址。近年来，四川省检察机关坚持以习近平新时代中国特色社会主义思想为指导，深入践行习近平法治思', '2022-06-10 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2022.002545', '四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2108, '报纸', '涵养良好家风 筑牢清廉防线', '陈昊', '中国纪检监察报', '中国纪检监察报', '廉洁文化教育;', '“诸葛亮治蜀的故事大家耳熟能详，他同样勤于治家，著有《诫子书》《诫外甥书》等名篇，劝勉后人立志报国、养德治性……”在四川省成都市斑竹园街道，数栋川西风格的灰色建筑群落掩映在茂林修竹之中，这里是天府家风馆所在地。近日，四川天府新区新兴街道组织街道办事处、村', '2022-05-12 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.001931', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2109, '报纸', '活化教学形式 增强实战本领', '彭健华; 廖理彬', '中国组织人事报', '中国组织人事报', '四渡赤水;干部教育培训;主体班;', '“互动交流、现场体验、一线实践……这次培训的教学形式有创新、有特色，让我学习得更多、吸收得更快、感悟得更深。”近日，在四川泸州市“菁苗计划”优秀年轻干部铸魂工程培训班结业座谈会上，培训学员、合江县荔江镇镇长徐波谈心得体会，收获颇丰。 去年以来，为破解干部', '2022-05-06 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2022.003294', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2110, '报纸', '数字化为红色文化资源保护传承再添动能', '王彬', '中国文化报', '中国文化报', '红色文化资源;红色文化遗产;红色基因;保护传承;红色资源;延安城;', '“用好红色资源、赓续红色血脉。”“讲好红色故事，搞好红色教育，让红色基因代代相传”……十八大以来，党和国家高度重视保护红色资源，反复强调要用好红色资源、传承红色基因。发挥红色文化资源的价值与功能，做好红色文化传播，数字化应用备受关注，肩负着让红色文化“活', '2022-03-28 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.000998', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2113, '报纸', '始终如一的精神风骨', '樊伟伟', '91208部队;', '解放军报', '人民军队;', '90多年来，人民军队历经硝烟战火、一路披荆斩棘。可以说，“三牛”精神是我军始终如一的精神风骨，制胜未来战争更需要广大官兵发扬“三牛”精神，从中汲取胜战力量。 为民服务是人民军队的不变宗旨。抗洪抢险，官兵们在滔天巨浪中挺身上前，用宽厚的身躯封堵决口；抗震救', '2021-12-03 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007496', '四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2119, '报纸', '这所医科大学从瑞金出发，演绎红医传奇90年', '于力; 王莹; 张逸飞', '新华每日电讯', '新华每日电讯', '中国医科大学;毛泽东;中国工农红军;唐山大地震;医疗队;毛主席;校史馆;吴天一;', '90年前，1931年11月20日，中国工农红军军医学校在江西瑞金成立。次年的2月22日，在江西于都一个老旧教堂，从200多名战士、通讯员、看护员中招考录取的25人成为中国工农红军军医学校第一批学员，这个被毛泽东称为“卫生小学”的我党历史上第一所医学院校，从此开启了荣光熠熠', '2021-11-19 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008952', '四渡赤水_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2120, '报纸', '教育不是“几堂课”，而是“生态圈”', '邱子健; 张磊峰; 张雷', '解放军报', '解放军报', '教育者;思想政治教育;战区空军;生态圈;', '这些天，中部战区空军某装备训练基地学兵九连新兵张哲格外忙碌。入伍前曾做过影视后期处理工作的他，参与了一堂教育课的设计，按指导员王帅峰的要求，就是用最新潮的方式讲述最朴实的道理。 这堂课的主题是“继承发扬长征精神”。受领任务后，张哲“脑洞大开”，借助基地', '2021-11-19 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007222', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2122, '报纸', '走好应急管理新长征', '李华桂', '四川省泸州市应急管理局;', '中国应急管理报', '应急管理;一级响应;', '泸州是一片红色热土。86年前,毛主席在这里指挥的四渡赤水战役如神来之笔,扭转了红军被动局面,从此中国革命从胜利走向胜利。今天,长征精神依然激励着我们走好应急管理新长征。 这次到北京,同事给我看了张照片:一个提着篮子的小伙子,正往我们应急指挥大厅里走。这不是牟宇吗', '2021-11-07 08:00:00', 'https://link.cnki.net/doi/10.28046/n.cnki.ncaqs.2021.003899', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2126, '报纸', '伟大征程的光影再现', '陈东倬', '解放军报', '解放军报', '八一电影制片厂;军事题材;电影创作;', '一直以来，长征都是军事题材影视作品创作的精神富矿。作为军事题材影片的创作主力，八一电影制片厂自1952年建厂以来，拍摄了20余部长征题材电影。一代代军影人用光影再现了先辈们的牺牲奉献。 在1952年至1966年期间，八一电影制片厂共拍摄了三部长征题材电影：《万水千山', '2021-10-24 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006681', '四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2141, '报纸', '永远跟党走 服务好国家重大科技需求', '陈建强; 刘茜; 焦德芳', '光明日报', '光明日报', '党史学习;张太雷;水下滑翔机;天津大学;北洋大学;科技需求;', '在校史博物馆，真切地体悟校友先烈投身革命事业的初心；走进大讲堂，听专家讲授中国共产党人的精神谱系……这一幕幕，是天津大学在开展党史学习教育过程中创新内容形式方法立德树人的生动缩影。 在党史学习教育中，天津大学党委把学习贯彻习近平总书记“七一”重要讲话精', '2021-09-13 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.004673', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2143, '报纸', '“彝海结盟”前，“弄染结盟”同样感天动地', '王丽; 李惊亚', '新华每日电讯', '新华每日电讯', '陆瑞光;布依族;彝海结盟;地方武装;感天动地;', '长征路上，刘伯承与彝族首领小叶丹的“彝海结盟”成为一段传世佳话。很多人不知道的是，在“彝海结盟”之前，中央红军长征经过贵州时，彭德怀与布依族首领陆瑞光的“弄染结盟”，同样感天动地。 是什么原因让布依族首领陆瑞光愿与共产党人共同签订“反蒋协定”？与红军结', '2021-09-03 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.006897', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2152, '报纸', '澎湃川电 激荡百年', '刘泊静; 向莉莉', '中国电力报', '中国电力报', '特高压直流输电工程;西电东送;四川电力;水电站;水力发电站;税西恒;用电量;纳溪区;', '编者按 这里是中国水电的起源地,这里是全国最大的清洁能源基地。这里有引领世界的特高压工程技术,这里有走向碳达峰、碳中和的最新实践。沿着西电东送大通道,记者走进清洁能源大省四川,品读这片土地上绵延百年的电力故事,诉说四川电力人坚守百年的为民初心。 展开一幅中国', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28061/n.cnki.ncdlb.2021.001407', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2153, '报纸', '周鸿祎：民企更要牢记为人民服务的宗旨', '吴志红', '人民政协报', '人民政协报', '周鸿祎;民营企业家;为人民服务;', '7月10日，全国工商联在京主办“民营企业家致敬建党百年”第39期德胜门大讲堂，全国政协委员，360集团创始人、董事长周鸿祎在论坛上解读了360集团如何在党的领导下发展起来的历程。他表示，民营企业分享了中国经济高速发展的红利，民营企业和民营企业家的成功，不能简单地归功', '2021-07-16 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005714', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2158, '报纸', '红色旅游：贵州准备好了', '黄静', '人民政协报', '人民政协报', '红色旅游;贵州省;榕江县;红色文化;红色资源;息烽集中营革命历史纪念馆;', '贵州省红色资源点多、面广、厚重，目前入选全国红色旅游精品景区名录的有11个，大部分依托国家级的革命文物保护单位打造。发展红色旅游首先是要把红色故事讲好，贵州对此下了大功夫。 资源丰富 红色旅游“火”起来 在贵州省榕江县，有一个黔东南苗族侗族自治州的“最美', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005592', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2161, '报纸', '“五心茅台”20年行稳致远', '韦夏怡', '经济参考报', '经济参考报', '茅台酒;', '位于赤水河中游的茅台渡口，是川盐入黔第一站。80多年前，红军“四渡赤水”中的第三渡，就发生在这里。曾经，中国红军指挥员用茅台酒疗伤解乏，在长征历史上书写了特殊的一笔。 从1951年整合后的国营茅台酒厂成立，到2001年登陆A股，改革创新中不断前行的贵州茅台在资本市', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28419/n.cnki.njjck.2021.003628', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2163, '报纸', '“90后”海外学子致敬长征精神', '张婷', '中国文化报', '中国文化报', '长征精神;《长征组歌》;协奏曲;海外学子;', '6月14日晚，一张张朝气蓬勃的青春面孔出现在上海东方艺术中心音乐厅，由旅德钢琴家巩慧琳和旅德作曲家谢梦昊根据大型交响合唱《长征组歌》改编并创作的钢琴协奏曲《不朽的长征》正式上演，在张亮的指挥下，70余人组成的双管编制的乐队展现磅礴气势，一曲曲耳熟能详的旋律飘荡', '2021-06-29 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.001969', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2168, '报纸', '踏遍青山人未老，风景这边独好', '单慧粉', '中国国防报', '中国国防报', '红色旅游景区;旅游专列;旅游景点;踏遍青山人未老;风景这边独好;', '年轻人成红色旅游热生力军 “我们一家人带小朋友来到泸定桥，目的就是想让孩子体验一下当年红军长征走过的路，实地感受红军的艰苦卓绝。”“五一”假期，四川成都市民刘先生专门为儿子规划了一条红色旅游路线，赴伟人故里缅怀将帅功勋，到金沙江感受“金沙水拍云崖暖”的', '2021-06-02 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2021.001238', '四渡赤水_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2171, '报纸', '七彩粉笔勾绘的是地图，更是信仰', '程斯宇; 李丹阳; 杨飒', '天津大学马克思主义学院;', '光明日报', '四渡赤水;思政课;', '去年秋至今，我在天津大学讲授“中国共产党历史”课时手绘红军四渡赤水、巧渡金沙江示意图一事，引来多方关注。我不妨分享一下背后的故事及些许心得。 一个有意思的现象是：我的图比课先“火”了，我的手绘红军四渡赤水示意图率先经网络传播而受到关注。有人问，为何选择', '2021-04-06 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.001719', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2172, '报纸', '以建设“七个组工”推动组织工作高质量发展', '梁磊', '四川省泸州市委;组织部;', '学习时报', '组工干部;常态化;智慧服务;', '习近平总书记指出，要“贯彻落实新时代党的组织路线，不断把党建设得更加坚强有力”。这为今后一段时期组织工作指明了方向、提供了遵循。四川省泸州市委组织部始终聚焦提高党的建设质量这一核心目标，坚持以建设“七个组工”为引领，以高标准要求推动组织工作高质量发展，实', '2020-12-18 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2020.002594', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2173, '报纸', '伟大的转折 之后', '朱彩云', '中国青年报;中国青年网;', '中国青年报', '毛泽东;', '望见云雾缭绕的连绵尖山，贵州到了。跟随“记者再走长征路”采访团，我们走进当年红军转战西南、转危为安的历史时刻。 80多年前，太多激烈的争论曾在这里出现，从黎平会议到猴场会议，从遵义会议到苟坝会议。太多的改变也在这里发生，一渡赤水拉开了由阵地战向运动战的转', '2019-07-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDiUfpaKERb44Sc7iJpDYf4iCjnRJ28_03WSHOsnIi4tELhr4gfd09f-0kcItMq-MKe9SOcbQecOJT0jfVgz5DnvtCNTQT_b29GO6DuKH5HhCF9qQLIOxWXb48Q04_2GkagAJ0qg2iwGA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2174, '报纸', '刘统：长征精神的当代启示', '李姝昱', '光明网;', '光明日报', '长征精神;红军长征;当代启示;', '“红军不怕远征难，万水千山只等闲。”红军长征，不是一次轻松的旅行，而是一条历尽艰辛的求生之路，铸就了伟大的精神。今天，回顾长征历史，我们感慨万千。长征精神的当代启示，主要有以下几点： 第一，方向和路线是决定一切的。历史，往往在曲折中前进。长征开始，也是', '2018-12-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBg8OLI6-mzw56Ez9YCVys_-IFHRnxlh6iJDhHyoHXD7nGak8_EcEG3pCIkICbcsV6oEs1pSDkpRB9e__X76oKniI79CSYHHRjV8Cf7m25NF_OMCRcr5VV84l3g-u8xERAwGXz3ehB2Nw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,飞夺泸定桥_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2178, '报纸', '想你的3652个日夜', '樊晓斌; 高晓杰', '郑州联保中心255医院;', '解放军报', '啼哭声;', '一声啼哭，跨越10年时空而来，时常萦绕在耳畔—— 2008年5月26日上午，汶川特大地震发生后第15天，一阵婴儿啼哭声让许多人流着泪笑了。那是全军首例在野战医疗方舱实施的剖腹产手术，清脆的啼哭声给灾区带来了战胜灾害的信心，也带来了重建家园的力量。 作为军人，作', '2018-05-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICmYXiR95bMKry6-ZoGZGSjdDv5g6Jz-11jdwH_HAAkYZKo9XkCWnGoY4CTO4EMbzgye14w0wwWLMCiAqpF62--Lx9TSe-FvoagTmjLe5l164tUWGZt8sQQbuJTVvPRp-4LYaBPHRoCdw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2179, '报纸', '让红船初心照亮新时代征途', '', '光明日报', '光明日报', '“红船精神”;共产党人;浙江嘉兴;', '2005年6月21日，在庆祝建党84周年前夕，时任浙江省委书记的习近平同志在《光明日报》发表文章《弘扬“红船精神” 走在时代前列》，首次提出并阐释了“红船精神”，提炼了中国革命的源头精神、完善了中国共产党革命精神史的建构。2017年11月30日，党的十九大胜利召开一个多月', '2017-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBsS6u5zuCqQNWvEF8ff3jGZC230v4WOKDmnoX_9iukhX0s3fb0IR2fFxRaLaVH1-ZtggjYzq2Ah25KDbMt6HhANb4TrKALSOdy9UT49Lom9_ShwAv7b0OdSdp60dCObug92Q17EGm4LQ==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2183, '报纸', '“虚拟”体验思政课 “仿真”重走长征路', '王之康', '中国科学报', '中国科学报', '思政课;马克思主义学院;体验者;北理工;李林英;长征路;虚拟仿真实验室;', '以前，长征只存在于书本上或影像资料里，但如今，走进北京理工大学马克思主义学院的“人才素质测评与培育”虚拟仿真实验室，你会发现，它竟然变成了身边的“现实”。 12月10日，在北理工良乡校区举办的“‘四个全面’与中国特色社会主义发展道路”第二届学术研讨会上，虽', '2016-12-15 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2016.000954', '四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2189, '报纸', '让长征精神照耀健康中国前行之路', '', '健康报', '健康报', '长征精神;重大传染病;', '10月22日，是红军长征胜利80周年纪念日。21日，中央隆重召开纪念大会，习近平总书记发表重要讲话，回顾长征岁月，号召面向未来，“每一代人都要走好自己的长征路”。80年前，中国共产党人肩负民族希望，行程二万五千里，书写了中国革命史上的壮丽篇章。长征是一次理想信念的', '2016-10-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBJCF3BUMAV0D40HXbeGXU1oC-vnurB_siKV2KKpsTcCwM6iV64q_tpL3MJjDh4W6FJM0cNgCJY81ohJQxcxBpytIA2KSMV4VFTTBISPQkcOpuNXlRL90TetuFr0Wfz-ib6oetMz90Rng==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2199, '报纸', '用歌声再现“长征精神”', '田思敏', '中国科学报', '中国科学报', '长征精神;艺术团;《长征组歌》;高校学子;', '作为一组激扬了爱国热情的歌曲，《长征组歌》曾经不止一次在高校学子中传唱和表演。演出中，他们用歌声和音乐再现了长征的传奇历史，共同追忆了长征的峥嵘岁月。 “红旗飘，军号响。子弟兵，别故乡”，随着《红军不怕远征难》《四渡赤水》的歌声响起，一场带有特殊情感的', '2016-10-20 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2016.001220', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2206, '报纸', '发扬老区革命传统 推进新常态下红色旅游发展', '武葳', '中国旅游报', '中国旅游报', '红色旅游;红色旅游景区;红色文化旅游;新常态下;', '近年来，革命圣地遵义抓住国家大力发展红色旅游的契机，确定了以红为主、以红带绿、红绿并重的旅游发展战略，以红色旅游为带动的遵义旅游产业快速发展，成效显著，在黔北大地奏响了一曲红、绿、白交响的动人乐章。  日前，记者采访了遵义市旅游发展委员会主任钱世容', '2015-09-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAFbVkoWtS4sfP3SNYdraH23kyeLgZnMIFant5lqFSeyp5Pi_vrjqMrau7qO_UAk9cSd4be_YQSAqqIuKAf5PTXsAp5UJOL_lP7S6z8HoJ7qIu5PcNID_htvlvctqFpKzsKUzvucKs46w==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2210, '报纸', '青春长征路', '陈兰君子; 万荃', '金融时报', '金融时报', '长征精神;', '长征，中国革命史上一部可歌可泣的壮丽诗篇。她是中国共产党和中国革命事业从挫折走向胜利的伟大转折。 青年，最富有朝气、最富有梦想。国家的前途、民族的命运与青年一代密不可分、紧紧相连。 “重走长征路”活动就这样悄然地将史诗般的“长征”同朝气蓬', '2013-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAEoanQi4E13UUbo1yI3dqUuQpFlvwasNlF46md7EMdbDYyyzq0VJSRVleJW6TjuumXwCO7_UCXOUtgkegFScPEipgBkiee92y4WSYuMjm-wpX5ftOJ2f6vWaCtPm-x19lZ0gRi08JMsA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2221, '报纸', '我们迎着太阳走', '武天敏 ; 陈国全 ; 李国文 ; 刘小红', '解放军报', '解放军报', '学员队干部;优良传统;军队院校;青年学员;空军工程大学;', '初夏时节，记者来到位于古城西安浐灞河畔的空军工程大学，与该校1990年后出生的学员3次“大考”不期而遇—— 一次“万人大考”：该校“我党我军历史和优良传统”知识竞赛，在全校4个校区同时展开，近万名学员参赛，成绩优秀； 一次“国际大考”：该校2011年首次推', '2011-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBu5vNd5GNYlu8j3vJqfhuNry25Ns75ojcjwSzAmo2W8ACLprBDChNGSm1fnyBLcuyiMNWQ8YBGnE_xDGK3MimTtMfVgY3fnBHrdWi6ysIo3GwCuNGOHjNzwelAQLcSYxDsPpxdE80TTA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2226, '报纸', '在革命老区感受红色文化的魅力', '陆敏', '经济日报', '经济日报', '红色旅游;革命老区;游客量;习水县;红色文化;综合收入;', '步入贵州遵义市习水县土城镇长征街上的四渡赤水纪念馆，倾听讲解员抑扬顿挫的解说，看着纪念馆中翔实的图片文字和视频资料，惊心动魄的历史被重现在参观者的面前——“四渡赤水战役使中央红军摆脱了敌人的围追堵截，粉碎了敌人妄图围歼红军于川、黔、滇边境的计划，中央红军', '2011-05-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIByCdLVRqy523DCBxC2vb5JbsLzp4EnPqtEedaewkrjM5EdUDnEerl9BIQrR3Fb-2dwCSNxzDSOblHEnZBeJOMSzCumxqhLioY8PwTVPCrikVVBchJQGQ5OQUAhizKqx7pfuEcKyI7DKg==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2228, '报纸', '保利文化：院线、拍卖、演出、影业,一个都不能软', '胡芳', '中国文化报', '中国文化报', '北京保利;《长征组歌》;', '4月22日晚，内蒙古自治区文化厅和北京保利剧院管理有限公司在呼和浩特市的乌兰恰特联合举办了大型交响合唱音乐会《长征组歌》。 乌兰恰特红色遍染 北京军区政治部战友文工团带来的合唱《八一军旗高高飘扬》揭开当晚演出的序幕。上半场演出，战友文工团的青', '2011-04-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICXxqJrLO3-bPZPi6Fa9Fdtp41kH34NOk93u_rzRSpdgEh_si5ofPI0KEfMCVCDDupbAh37a3yvOjcgO1-a5GKPCnH1ARYDtrCYi7MOr5RoY_aKfbw0GL719yB7OHkKZoBd5he0IUbVzw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2230, '报纸', '“文化列装”：软实力视野下的军事变革', '丁海明; 梁蓬飞 ; 李世林 ; 邹菲', '解放军报', '解放军报', '文化工作站;文化装备;第二炮兵;军事变革;青年官兵;战斗精神培育;基层文化建设;文化活动中心;动漫技术;军队战斗力;', '经过一个冬天的野外生活，第二炮兵某旅营区的角角落落，都似乎经历着一次新的苏醒。最引人注目的，当属刚刚修葺一新的旅文化活动中心。 上等兵王然走进他阔别数月的旅文化活动中心。第1个小时，王然与战友在网上展开“红蓝搏杀”。他们玩的游戏叫“四渡赤水”，电光火石', '2011-02-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBSLk64tM3eeG1kHU_aDenH7nDQQEIoffIhsbYu2Gy7biZ_arMzQknrbjJ8CRciw34Sqf5ZEZ9hJ0CN5b9PtiO_9MscZyhAse2fimKtLs5mbjk23GiS6gkXyKlr_VrQlqMk_V44l0JYyg==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2231, '报纸', '“红色资源”是个“宝”，怎么用才好?', '杨诗琪 ; 周点征', '中国纪检监察报', '中国纪检监察报', '红色资源;革命老区;爱国主义教育;廉政教育;革命传统教育;', '●对话嘉宾:  肖居孝 中国井冈山干部学院教授  徐萍 贵州省遵义市委常委、市纪委书记  李云 江西省吉安市委常委、市纪委书记  张俊雄 广西壮族自治区百色市委常委、市纪委书记  “红色资源”是中国共产党在领导各族人民进行革命斗争', '2011-02-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAiQiFFZllwq3BW7y9F07Q5pOJs8p0xSDFo2z63Rl0G2qtA_pAeGpwZIJ07NP5GLKYdhEtiP0xPDCJ2CiwadQw12ZUDez8C_JSRFZYT1G187DTo2i8FTqfVp3WDTKT6CU_IlTx7JBvUqQ==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2232, '报纸', '《何方谈史忆人》 展现真实张闻天', '李力', '金融时报', '金融时报', '张闻天;《何方谈史忆人》;国务院国际问题研究中心;外交部;', '近来《何方谈史忆人：纪念张闻天及其他师友》一书受到读者关注。作者何方，当代著名学者，重大事件亲历者。他的这本《何方谈史忆人：纪念张闻天及其他师友》，史料翔实，逻辑严谨，在恢复历史真相方面有大面积突破，振聋发聩的新鲜见解也触目可见。何方以自己的亲身经历和研', '2011-01-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAhBxTwb5mdbDWTNo1AHuL5DFE_eREnuNWT9FuIwjo3JJuJ39HstO3xYw3l0UXLMiEZFY5QAUAxPqx4U4TcOj2O8QZTvjI-d7CHt2BjNZfLTibTUyYTkJnpXno8NwE9rX3z6NBeRzwLRQ==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2233, '报纸', '唱红歌悟真谛 动真格查问题', '张文科 ; 李奇松', '解放军报', '解放军报', '长征精神;', '本报贵阳12月17日电 张文科、特约通讯员李奇松报道:“战士双脚走天下，四渡赤水出奇兵……”近日，贵州省军区座座军营广播放的是红歌，官兵唱的也是红歌。他们在主题教育中，充分利用驻地丰富的红色资源，大唱红歌，感悟革命精神真谛，增强了教育的贴近性和感染力。 贵', '2010-12-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAdNivf3PUcu76rLaTwTkX4CsaKp2BCynLiRWKsj4dPw4epYq7jSL8Cssfq1JOVXonlar2q6Nc3q32lkDP5Sa-jLAo_IRBnsTzBTeicuaD7O8aPCO4ZF085P_nfBIJypuo_PX_nEvVkDw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2234, '报纸', '红色旅游方兴未艾', '周丽燕', '人民政协报', '人民政协报', '红色旅游;爱国主义;革命传统教育;旅游发展规划;红色旅游景区;', '提起“红色旅游”，很多人脑海中都会浮现革命、红军、战斗、山区、长征、草鞋、窑洞等一系列标志性的符号。虽主题严肃，却颇具鼓舞人心的重大教育意义。当下，唱响红色经典、游览红色景区成为一种时尚，成为爱国主义和革命传统教育的新载体，尤其是红色旅游景区的免费开放，', '2010-12-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICZxAAmMWMfW9_y8OmzSqPnu3_TprZjXzx1uIon3qsXimHfYv1uzNI46sODFmGbNU9gO6gCC3SZXo1bZP8Qkp_TZgD925VEZLDjspQGw34-HeqmDizC8VlfW1MqLLN1JHEAWfYAINNEEA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2235, '报纸', '红色旅游蓬勃发展亮点纷呈', '徐万佳', '中国旅游报', '中国旅游报', '红色旅游;旅游发展规划;红色旅游景区;', '远方，八百里井冈峰峦叠嶂；身边，鲜红党旗映衬官兵赤诚。井冈山深处的小井红军医院旧址，一群来自远方的客人被烈士张文清的故事感动得泪花点点。 这是红色旅游的一个经典场景。 从《2004-2010年全国红色旅游发展规划》颁布实施到目前，红色旅游接待总人数', '2010-11-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB4YQmiAnsfGgkPgU264Cz4YR7_iDWHlOJJJen7R4l3wxyTinWPtKpmKPKeFlFCPNiEbQ4PvYsUYoN0Mq5D-usH32ZHg1UCO1VrQryG73mjs5OU4urgtxrNknJHJuU4RSeTRG_wiNx64w==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (2236, '报纸', '“红色经典”视频遭网络恶搞', '王瑜 ; 尹晓鹏', '工人日报', '工人日报', '“红色经典”;恶搞视频;《长征组歌》;网络恶搞;', '本报北京9月4日电（记者王瑜 实习生 尹晓鹏） 最近，传统红色经典《长征组歌》再次受到社会关注。原因是一系列相关的恶搞视频正在网络上迅速蹿红，并受到一些网友热捧。不少网友和专家学者对此种现象表示担忧。 今天上午，记者在某知名视频网站通过键入关键词“红军”，', '2010-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB70tPv0wutRTl8ZC-SO0bA-JfQpAUsdno4550PCZgQgWmiq5f6daMWn7xDKHPAUBQlqqBRjeacWDvRC2xZsDHYo1skjvYLmyPbvCjBI8dZLNK1_oVDeZYYV41mEljim6GP6glbsHFAUw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2238, '报纸', '酒香,爱武强兵情更浓', '张文科; 肖宁舟; 李奇松', '中国国防报', '中国国防报', '民兵应急分队;人武部;民兵队伍;仁怀市;', '仁怀，有一张近百年历史的名片：国酒茅台之乡。革命战争年代，它又有一张名片：红军四渡赤水。进入新世纪，仁怀市委市政府继承和发扬革命传统，又努力打造一张新名片：爱武强兵。 “管”就要管出成效 近几年来，该市市委书记、市长每年至少10次到市人武部现场办公', '2010-03-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICgZqkcB0Fse8eGwm2hGBzlBXvjuSJ1Y1bB2Y4-CztPucuAipb4GBArquCZKRtTDBWQOXCIXiEq500_dwDw4vCgbDXvHqxZJhIdGDaW25CNK3J_AXgjaUUjZWscp75LkiRtSRdH_qE62w==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2239, '报纸', '“国酒之乡”:酒香与红色文化同辉', '石新荣; 王橙澄', '新华每日电讯', '新华每日电讯', '仁怀市;酒文化;红色文化;国酒文化城;', '据新华社贵阳电(记者石新荣　王橙澄)赤水河畔的贵州省仁怀市茅台镇国酒文化城里,许多游客在一个雕像群前驻足凝视。这个雕像群俨然一幅缩略图,记录了“国酒之乡”酒文化与红色文化的交融:茅台镇的老乡正在用茅台酒为红军疗伤,周恩来竖起大拇指,露出赞赏的微笑,毛泽东端着土制', '2009-12-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICH0AMTLO67xqzncHtZqszNkFAzx0wE6x-n5UMbj6Yjj3yHUP7NLTABNmxbySK4kzc5tGPAxvhzd9PkVTcu_X1Z3Gi-zW25z_TR4mY9LYr6ZdNzSNYKqI-UcRSQd5-40eYDhbXBzLUXug==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2243, '报纸', '从拿来主义到自主创“芯”', '孙蔷; 姜靖', '科技日报', '科技日报', '产业化;纳米工艺;笔记本电脑;', '如果说龙芯1号是在迷雾中起步，还看不到先行者的影子，龙芯2F完成后，我们已经超过了一些同行者，看清了领先者的背影，那么，龙芯3号的完成将使我们大踏步赶上并超过领先者…… 我国民间有个说法，孩子取个“贱名”好养活，将来才好大富大贵。为此，我国第一款通用C', '2009-09-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBB4nJgj2tc2DwQuhcXk0kZ2-p6uSYcClT5n9iOHn7Znl91ZV18NOL6aNJuFAbcEMpjUlG05SgoAItBvJxijGSd1sCVkGO7HCs6kDdv3GWOPOJ07Xp99IOzCCZ6_uIoTDUswEM6G8oEjQ==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2249, '报纸', '贵州省军区积极开发利用红色资源', '柳路; 张文科; 李奇松', '光明日报', '光明日报', '红色资源;省军区;历史文化景点;', '本报讯（本报记者柳路通讯员张文科李奇松）贵州省军区积极开发利用红色资源，使之成为学习实践科学发展观的有效载体、培育当代革命军人核心价值观的生动课堂、参加和支援西部大开发的抓手。日前，成都军区在遵义召开会议，推广了他们的经验和做法。  贵州是红军长征', '2009-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLqWZrqB3BcJLEEYSK5niOvqXrM9J4NtlIW6RfbuptFDi8uVDN3yqTievKT2OYVzu8iwxZrtEDiQTRFFntBOcAjYUr1eB67Ae_4-gMxQBdEduBHQbB1SpPoG6wn-T5sv8rehxo3qVhDA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2252, '报纸', '“大课堂”上坚定价值观', '曾科; 杨彪', '解放军报', '解放军报', '预备役师;红色歌曲;红军长征;', '红色，代表活力与激情；红色资源，蕴含不竭的精神伟力。  连日来，红军长征经过的黔中大地，成为贵州省军区开展当代革命军人核心价值观教育的“大课堂”。触摸悲壮而光辉的历史，聆听传奇而生动的故事，官兵们对信念、使命、荣誉、价值等挂在嘴边的字眼有了深刻感悟', '2009-03-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDX6RWmGQLdEOe-a9_DyJbQryE1Jpl0lMR_D2BNIuaWYsBWDFpES0LuNLwweCMG65tByCb05z_bqQuJN7CykZEACeLDLLIRqDKWfYjMGcMialRlQ4Fi1cmzVL28fY2a2uoGtHpdgT68vw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2254, '报纸', '爱是世上最美的语言（下）', '黄辉', '中国纪检监察报', '中国纪检监察报', '吉嘎;林强;镜头;', '林强家的门前摆着双草鞋，邻居 都知道，又有老乡来看林强了。这次 来的是四川省甘孜州雅安县玉龙西村 小学的吉嘎老师。  吉嘎老师的守望  林强在2005年任四川省教育厅语 委办主任之前，在体育卫生艺术处工 作了十几年。他有一句“名', '2007-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDQL7L6V4CB-Ykgx7Z9JjwB68ghn3UO7YoLExrRmlzl2_ftxjSGBPrYIjnyUKSMuCiAhq1Fmx0hABhBVT71NcpcBZNhJo67zyQ8azQTXwGQA5qZpn20zlR_d-QGOjO8p7zCfgGp-6mHqA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2256, '报纸', '遵义——丰富旅游内容 形成旅游品牌', '张剑鸣', '经济日报', '经济日报', '旅游品牌;红色旅游;', '本报讯 从2005年夏天开始，贵州遵义会议纪念馆就在数十公里外的乌江边上设立了接待站。游客们从这里开始了红色旅游，讲解员向游客介绍当年红军突破乌江以及沿途相关的故事，介绍遵义的风土人情，将广大游客对遵义旅游资源的了解，从红色旅游扩展到绿色生态旅游和文化旅游上', '2007-05-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC2VOIv2eHzP5emyzVH0_c_TKHb4AwXu4DVn4eL4nGuygbGeJ4b31tSZYxK4V2D4y1oDU34k-GDEXG0X3V-mmUnl1AZDMG8Ks3mlrM8CTQrpbTHedimar0tlFnOiFMf2w1KQ26V9F_6vw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2257, '报纸', '贵州文化产业突破“一瓶一屋一树”', '张守营', '中国经济导报', '中国经济导报', '文化旅游产业;黄果树;文化资源;旅游区;民族村寨;喀斯特地貌;王富玉;文化产业;', '由北京大学文化产业研究院和国 家文化产业创新与发展研究基地联合 主办的“第四届中国文化产业新年论 坛”近日在北京大学举行。中共贵州省 委副书记王富玉指出，以前不了解贵州 的人对贵州有个不公正的评价，那就是 “天无三日晴，地无三尺平，人无', '2007-01-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBMQo100P-0d5hkvFLb7duiN5UnhI3qLfs_1_NTkGCldHYBT_XdGI1Kb4mtstNV0eFEGRMNA6mg9kBaRVpOyy0seaLub_ncRbR2aMHLwSlotNE-DOwHB-HfTpO_msqgMoSBHccWKc0MTQ==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2259, '报纸', '公共财政促和谐古蔺建设', '何广斌', '古蔺县人民政府;', '中国财经报', '公共财政体制;政府采购制度改革;政府收支分类改革;', '古蔺县地处四川省南部盆周山区,三面与贵州省交界，历史悠久，地域广阔，风光旖旎，民风古朴，其出产的郎酒蜚声海内外，与著名的茅台酒都同处于长江上游的生态河流——赤水河边。70年前，中国工农红军长征四渡赤水历时72天，在古蔺就转战了54天，足迹遍及境内大部分乡镇。 ', '2006-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDVcdvAD9x9BOuEqrLkMxTlp3oBREZETIQNr0Q3oXeqfHokM7KmeWV9w8rT5mdO44oGYBW6fLEkjz-SFJ2KqIKpgrx4K9IVboCCNS8WvQWoboIjAOlBUHzSEPrNrvs4PjgmwsnC7tK_fA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2262, '报纸', '沿着长征的足迹(上)', '卢向前; 李文学; 姚晓敏; 孙磊', '人民邮电', '人民邮电', '四川移动;村通工程;红军长征;', '在四川阿坝藏族羌族自治州松潘县川主寺镇元宝山上，静静地矗立着一座碑——中国工农红军纪念碑，它记录着当年红军长征的丰功伟绩和不朽足迹。70年前，红军在四川经历了自长征以来最艰苦、最漫长、最危险而又最辉煌的战斗历程。今天，在这片老区，四川移动的村通建设者正沿着', '2006-11-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICZ3tXCI2pjEq66Yq-6t7ObM4OvFRF5OgrXeuiFTCu1AVmtX-bpjB4eGuOrJunMO9VQVV8mRLc7bcMjyOAfbk4h-FKYDBHXoctE53hCsDMRCjY833jlj0xjF40j6HY0UgduQkZo6Jb5yQ==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2263, '报纸', '小巷劲吹“和谐风”', '余继军', '人民日报', '人民日报', '社区居民;文明单位;九龙坡区;示范社区;', '２００６年１０月１８日，深秋的山城已有丝丝寒意，但重庆市九龙坡区九龙花园社区居民却备感温暖。这天一大早，九龙坡区第一人民医院等３所医院的近４０名医生来到社区，为社区群众测量血压、做着按摩、诊断病情…… 近３个月来，像这样的大型义诊活动已在九龙花园', '2006-11-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDZc-7ZRRr-uUi0MF8LdPZpfxEwLSKadIZkyr4LXjcEqoBzBMnz0DCp2SZem31rwO8KoXZQRH5tCBOXr9OT6ocZwdBBFqcSBCKtmkWna7aCxgNGbY7Cnl5ASbgHN3ibPx_h7u2J42avpw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2264, '报纸', '中国记协七届一次理事会闭幕', '张建玲; 江山', '人民日报', '人民日报', '中国记协;中华全国新闻工作者协会;常务理事会;', '本报北京１０月２６日讯 记者张建玲报道：中华全国新闻工作者协会第七届理事会第一次会议圆满完成各项议程，于今天下午闭幕。新华社社长田聪明当选新一届中国记协主席，邵华泽被推举为名誉主席。 本次会议审议通过了中国记协第六届理事会常务理事会的工作报告，总结', '2006-10-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBt8p3GLzuqoIRMupa1axmtSED_0m1sJgaAgtS51V0F3P4N5yAsf02DEZ31eCnnxsjuSGbzHqdaMnBWUOwq3YAVtgt8sFyA0TStcYsLKZ2drcDfn8o4s6qpYqytN4o1S-oGpxx2No8Erg==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2265, '报纸', '会理：长征路上的一颗闪亮明珠', '王银胜; 赵刚; 聂敏宁', '人民法院报', '人民法院报', '长征路上;会理会议;会理县;', '四川省会理县是红军长征出滇入川之地，著名的“巧渡金沙江”和“会理会议”就在这里上演。 1935年5月初，红军占领了云南禄劝的皎平渡，在当地群众的帮助下，找到6艘木船，经过九天九夜，红军全部渡过金沙江。从此，中央红军完全摆脱国民党数十万大军的围追堵截，实', '2006-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAny6iHQ7WYPgodxJB41i9raDan311veF-PPCfFkfPdQWyz0IzEuP2PMl6N_aSv8FfWK5VcVcdQlbpRg_JUtuF29hfDy9Q0zdNVtBybwDfCg0kqMxAqLI1yNPZuWHIk8beo9EPtu89IrA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2270, '报纸', '各地多种形式纪念红军长征胜利70周年', '李战吉; 江宝章; 周志忠; 曾华锋; 刘鑫焱', '人民日报', '人民日报', '长征胜利;长征精神;中国工农红军长征;', '本报北京１０月２１日讯 连日来，全国各地开展丰富多彩的活动，纪念红军长征胜利７０周年，追忆红军长征的英雄壮举，缅怀老一辈无产阶级革命家的不朽功勋，弘扬伟大的长征精神。 这几天，在红军一、二、四方面军会师地的甘肃省会宁县、决定中国工农红军长征命运的重', '2006-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDrAZN_gB7ppSeBC7kEFVyqpheY7pHj8yrSwlQeVz6_4r8_jZBgi9uAN6JhN745EGGvA8iHKZbvfO6lNUdgZxUQeqSjA-GrS8o3j4Y5Z0wX7k3XRpOZ2f6SWIygbkMOcDyfFI-VvxD2iQ==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2273, '报纸', '“长征展”上的声、光、电', '唐先武', '科技日报', '科技日报', '军事博物馆;长征精神;感应式;展览效果;中央党史研究室;凹透镜;液晶显示屏;', '狂风肆掠，大雪纷飞，爬坡翻山的红军战士艰难前行；雷声轰鸣，电光闪闪，突如其来的暴雨不期而致；泥泞遍地，杂草丛生，观众踩入水草坑里溅起一个个涟漪。  看着这运用声、光、电制造的大型场景，布展参与者、军事博物馆设计处设计师林红钢欣慰地笑了。他告诉记者：', '2006-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDlX4xvQiZC2Yl4Atse_cS9vg4mwF2qLNcoCLO70M5Iwng4bMfOk4botvfe81T5ZemfbkjstO0HNH0JrsywuvOWbinU-Z0AstX30TYHVOVe4tDLhfJ56uwCSl3UD2MQwimhyVTVOaZRuA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2280, '报纸', '皎平渡的九天九夜', '张帆; 宣宇才; 陈娟', '人民日报', '人民日报', '皎平渡;李正芳;红军洞;中央红军;金沙江;刘伯承;', '我们来晚了。  一个多月前，９３岁的张朝满平静地离开了人世。生前，他是当年在金沙江皎平渡为中央红军摆渡的最后一名在世船工。 那间悬挂着毛泽东长征画像的堂屋里，老船工平和、沉静的眼神透过黑色相框注视着我们，似乎还想为来访者讲述他一生经历的最大', '2006-10-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICiNrfsxax9ITTMeeuAmrzYpPvRx9POFT8G6OPV_U3Fi-F-5H7R6AMixfehAagxOv8Bun9Iv2iWjWc9MU-AJwuNZcxYclg5qmSjIROLx9yvS41rzb5sXX5GbC80Gb8FmWCWWF-N6hkD6Q==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2282, '报纸', '为什么说直罗镇战役是“奠基礼”？', '孙学宝', '解放军报', '解放军报', '直罗镇战役;奠基礼;东北军;', '1935年11月，刚刚实现会师的红军陕甘支队和红十五军团，在中共中央和毛泽东直接指挥下，发动了直罗镇战役。两军团结协作并肩作战，取得重大胜利。毛泽东在《论反对日本帝国主义的策略》里评价说：直罗镇一仗“给党中央把全国革命大本营放在西北的任务，举行了一个奠基礼。”', '2006-10-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIALXvgnLcIP4rGcQoL0twQ6Qv105r1POZTwIqI6aY70meb1Manw96XDW_3uqQ2qmt82tYNpTSOjVJmrPm9ipnAWEm4co0XzP2qTpvtDe2REi8t6x-duQf9Gr-hhmlc1jrcuw5hQIteyNA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2285, '报纸', '长征：一部读不完的书', '陈洁', '中华读书报', '中华读书报', '共产党;纪实类;四川人民出版社;红一方面军;中共党史出版社;', '“长征是宣言书，长征是宣传队，长征是播种机。”——毛泽东 今年、去年我国出版界推出了200多种新版和再版的长征题材图书，集团军般大规模挺进市场，蔚为大观，呈现出高质量、大产量、全方位的态势，从各个角度再现了70年前那场举世震惊的伟大征程。  最大', '2006-09-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAUFwyqtfEHIo-RF7Y8uFUq_vYvcjO_gX0cLx_D7YZ8gAx_MNtz4gpXMIKlonrqhyIwWcvXT8Bb3kHWtHPPiL_RXvWMvNV5r8NgY2eb5IsTegI1pSUVTNe8ggLa6BRsDpxZysIMYfTI3w==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2286, '报纸', '贵州遵义：红色旅游亮点多', '张剑鸣', '经济日报', '经济日报', '红色旅游;旅游业;', '2006年9月中旬的一天，在遵义会议会址络绎不绝的参观人群中，从山东青岛前来参观的程欣与记者谈到，“遵义会议可以说是我成长过程中最为熟悉的一个词。我当过军人，深知遵义会议对中国革命的特殊意义，深知遵义会议对一代又一代人的深远影响，所以我这次专门和同事们前来参观', '2006-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA9llDJyPg5J_tJ7Ac7K1C3KQ62HFgao8JKEuOzrB0sbwM6njjlnk_u4oJkfSeJufN-Cp-CAdEK7jtb8tzj_IN8G2enXL4JGPO3o2J_4ZQ1aSwziP2G6t9s6hAJB3LIl6GnbvOWgQwI9A==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2289, '报纸', '成都军区某师赤水河畔摆战场练精兵', '罗泰平; 杨彪', '解放军报', '解放军报', '青杠坡;长征精神;信息化条件下;', '本报贵阳8月17日电　罗泰平、记者杨彪报道：16日凌晨，在70年前红军浴血奋战的黔北土城青杠坡，成都军区某师打响了一场信息化条件下山地进攻战。记者在指挥现场的远程视频传输系统上看到，千里之外的黔西南乌沙山地、黔中安顺等地，作战演练同步展开。荧屏闪闪，炮声隆隆，飞', '2006-08-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICDstSYd-nWd7ESnUEWhA_zV-KSJt1GC6-yuSVZLw_UdZZ3NuNot0zXeAB24NNBsrFSNMakRUY6bqOWb0Auu1ekqZAl4BJqdXOW9uqUHILQcP3Cbxw23rvoXebGbq75Nal5WelTNHhzlw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2290, '报纸', '娄山关沟壑相连成通途', '朱虹', '人民日报', '人民日报', '娄山关;长征精神;', '红军长征时，娄山关是由黔入川的唯一通道。第二次娄山关战斗胜利后，毛泽东写下了“雄关漫道真如铁，而今迈步从头越”的豪迈词句。在今天的娄山关口，能看到毛泽东手书的这首《忆秦娥·娄山关》，只是娄山关已不是川黔的唯一通道，在其脚下已经建起了崇溪河至遵义高速公路。', '2006-08-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICBEEZ8Q79dlKbfrE1zyCTqaD3fXRCfOYK5KZqa1bL5_Q0cYmNsNZASbZVSpYWPtIX5N8rBAPyf8f36q6gxWvWGXptn13enbmoQHu7diM9ip7Zswn9sABxM6ViuJ4LKvwsAjsMntMvuMg==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2293, '报纸', '到西部去 到基层去 到祖国最需要的地方去', '莫锋; 刘功兰; 陈春晓; 李岳韵; 王一硕; 李欣然; 魏泽熙; 李凌', '内蒙古巴林右旗卫生局;重庆市开县丰乐街道办事处;湖北省秭归县归州镇航天希望小学;鞍山真金教育咨询中心;河南中医学院;新疆建设兵团农十四师一牧场团委;贵州省遵义县西部计划项目办;', '人民日报', '大学生志愿服务西部计划;大学生志愿者;习水县;安置点;麟游县;巴林右旗;北京大学医学部;桃林乡;长期镇;南开大学;泾川县第一中学;', '编者按：青春年华，需要理想和正气的激荡。又到高校毕业生即将走出大学校门之际，“到西部去，到基层去，到祖国最需要的地方去”，与人民结合、与实践结合，是时代的潮流和祖国的召唤，也是一代又一代青年知识分子成才的必由之路。 如何走好迈向社会的第一步？回应时代', '2006-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB-sD4jYbc1mFqMjqpUZF9IaeBKJsyS_sVT5mGoSMMfNnEmj94k5fvqrpBHhOtRumNQA4MPH7igJlnBuBrKbfcqD-ZiasDwIk_VsZzoE64VJEHanJzD7NRvITYdnN_RjO6wycZnlJdh7g==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2295, '报纸', '贵州 “红绿”旅游精彩纷呈', '孙海涛', '人民日报', '人民日报', '乡村游;', '本报贵阳５月５日电　记者孙海涛报道：“五一”期间，贵州旅游呈现出“绿色乡村游”和“红色之旅”热潮。１日至４日，全省共接待乡村游游客２２０万余人次，红色旅游区共接待游客近５０万人次。 今年是“乡村旅游年”，贵州省１３０多个少数民族村寨开展了以浓郁古朴', '2006-05-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICVLBWlm28Fd5uATiYRa1vHhVS-lxDiXB55lxJYHbRuiHmxEx6wZxA7V6BQH6nZQB5ULHQgTTrJ-Lx1EcnS0hLO5Kgd0QDSctGwXlO2He2JGCpCko8pUA29vlVoAU4gT-5Sno0aGAB64Q==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2296, '报纸', '夕阳无限好 为霞尚满天', '龙云平; 秦建国', '中国国防报', '中国国防报', '王世杰;爱国主义;昌黎县;东山公园;中小学校;', '在河北省昌黎县东山公园活跃着一支老年合唱队，每天清晨人们路过公园时都会被那嘹亮的歌声吸引。只见一群人围着一位老人，聚精会神地学唱歌曲。这位老人就是昌黎县政协退休干部王世杰。 “夕阳无限好，为霞尚满天”。今年66岁的王世杰，以一个老共产党员的责任投身国', '2006-04-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIByuX29241WQaQl3Sqz9jUba1pbaPV9OuzvWIP0PIlWdir2htMiG4-jFTt-hwPOV7thseD-Lsqz40cmo7_mSsY-N8Xc5SJicfv4fdoHVsjm8BJ8NwopM6q-y5kqqxrocolEaVWsCGZyRw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2297, '报纸', '赤水河畔“红军渡”', '夏桂廉; 徐冶; 柳路', '光明日报', '光明日报', '元厚镇;红军渡;红军长征;土城镇;', '中国工农红军长征中四渡赤水,一举摆脱了国民党军队和川黔地方军队的围追堵截,跳出包围圈,挥师北上,被称为毛主席用兵的神来之笔。 今年是红军长征胜利70周年,赤水河边的红军渡口如今是什么样?那里有了哪些变化?记者日前来到贵州省习水县的土城镇和赤水县的元厚镇采访,', '2006-04-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICU2AdonYWq1m9DtJLeHDJt6qhlmlXXBIoR9y8XX0rLClEM4kFCp3jdPaYk2dzgIzJgno0pf8jzC2R91JsPFfB1w3zIGk2lKTNEBrWCUoeMIJcjGdCRqPYMX_h60TfhTdRdXqxOyfIxdw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2299, '报纸', '伟人不再是遥远的背影', '向兵', '人民日报', '人民日报', '毛泽东;周恩来;刘少奇;银幕形象;故事片;王铁成;', '中国电影诞生100年了。在100年的风雨历程里，中国电影的焦点紧随历史的脚步，银幕上流动着时代的风云，涌动着一个民族的时代情感和审美需求。在改革开放20多年里，电影创作从发轫到蔚为壮观的领袖形象塑造，便是一个鲜活的例证。 孜孜追求的电影梦想 从诞', '2005-12-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDmd7Mrf6y_v7708rkLPL4HZRH4P32GUw9I2WFja5zkAMNJTnnBrFz0TPCuVBVQeMvwKP_t_sjVqjG6tFUOHhakcaYRWfZE6Gze8OCapRd3f0jCUf4T0TBK45yr9rTaKCQka4u4TaN3uA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2305, '报纸', '导游“乱点”江山，处处都有“毛公山”', '邱红杰; 朱建军; 丛峰', '新华社;', '新华每日电讯', '红色旅游区;红色旅游资源;毛公山;', '跟随导游煞有介事的指点，游客会越来越觉得远处起伏的山峦像是 人的眉眼，通过这样的手段，已不知全国各地有多少旅游景点出现了 “毛公山”。一些人大代表对记者说，“毛公山”的大量涌现，反映出 不少地方在旅游开发中思路狭窄，仅用于穿凿附会倒也罢了，如果用', '2005-03-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBKJ9zEhxxtFk-BWausm3uyCDd5O7Ygu7-0jC_rx7Ta-g86yoORoCeViMi_WJcmYYoxRH2VhmbE9u5BhLrIhDvTqLjNmJbGKNoIifkCnfwyniu6mXxR8mTHNuAD1eh4ulEBEQVGOKm1Ng==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2307, '报纸', '四川红色旅游在广安启动', '张力; 罗阳', '中国旅游报', '中国旅游报', '红色旅游;精品线路;', '本报讯(四川记者站　张力　罗阳)1月28日，四川省委书记、省人大常委会主任张学忠宣布：四川红色旅游正式启动。由四川省委、省政府主办的“2005红色旅游(四川)启动仪式”在邓小平家乡广安市拉开了帷幕。  四川省委书记、省人大常委会主任张学忠，省委副书记、省长张中', '2005-02-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIANzUOpjKER-RGngldXjylKgqhaNYaHx4ltqfr7tKyVr1_8Tq8P46LOdCynLEGFI2kjtIm0l9HQQANst7IfhnPsQYt9SVXwXIas-AE_6jgemoQWkXT75XmfEUkS5RwZrljdcV04GNUwCw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2308, '报纸', '唐国强：成功塑造爱国教育家张伯苓', '沈卫星; 边迪', '光明日报', '光明日报', '唐国强;张伯苓;', '唐国强：1952年5月4日出生在青岛。中国电视艺术家协会副主席。主要影视作品有《小花》、《四渡赤水》、《高山下的花环》、《三国演义》、《长征》、《雍正王朝》。被授予“全国中青年德艺双馨文艺工作者”称号，并获得电视金鹰奖“终身成就奖”。  从正在中央一套黄金', '2004-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAvS21ww_lV-lojdxHVTzZl6I51ObA1jmjOw8GJwJQLwBDtrdwdrjnKqm1i8hsw0Q6QnbtIUCzMSEpJ9aDKbwLNnGrcikrBOj6-wHMou5YDmhFq6f6lPl1sJrtcogzGjOUOmpDlpQj2lA==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2310, '报纸', '贵州力推“红色之旅”', '肖江', '贵州记者站;', '中国旅游报', '红军长征;娄山关;长征文化;', '本报讯(贵州记者站 肖江)“七一”期间，贵州历史文化名城遵义迎来了来自广东、重庆、湖南以及香港等地的游客2000余人，贵州“红色之旅”正式全面启动，这标志着和国内、国际旅游市场全面开放。  以红军长征为重要标志的红色文化是贵州一大特色旅游资源，以历史文化名城', '2003-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBYOD6ZUvbSZ-a28MH5y63IQm__rZI68s8jNNwpDZFG8dTKJjAHwGERAqQWK4gJR5uwYshCHhEoeCBxd9n5lnZX13wv1yFP1DYUnFTQiHtqac7nmshCzs2K7m_IVVOdXWDZC-7eTGmepQ==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2314, '报纸', '让长征精神世代相传', '熊艳', '新华每日电讯', '新华每日电讯', '长征精神;太平渡;太平镇;', '大娄山下、赤水河边，四 川省泸州市古蔺县太平镇的长 征街上，一座小青瓦的三层小 楼格外引人注目，这就是红军 四渡赤水太平渡陈列馆。  陈列馆600多平方米展厅 里，陈列着200多件当年红军留 下的弹药武器和日常生活用具， 向', '2001-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAenWZ__W1OMQhnN1P8DN1y34asVRfg-Wq764lNWlP_XlC3vMyunUZbO4BIQ1MgWvsvyCYI4hPmiRilrQ7btrFlNeIp-JWfT92dkJwdNgk9FhuQANspjfgmwmdn30EbJPDSQvoA_Aubng==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2318, '报纸', '春染“红飘带”', '吴广生', '新华每日电讯', '新华每日电讯', '吉尼斯;红飘带;', '遵义，一个响亮而光辉 的名字。她因遵义会议成为 红军二万五千里长征这条 “地球的红飘带”上的明珠 而彪炳史册。在建党80周 年前夕，记者到遵义、赤水、 茅台镇、娄山关等革命', '2001-05-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICHaNWhNw9OjiiZTLzheBMVN4IcAewKWQxpQV_axLacBZJFiR-ueAb5sGs_ygX70jtaHIdIKzcWvb9hMLceJCY-DAGX0qeakKpxp-0etjT5nfY2-qLq6YEXxlgkGPy8z0jhbnWtJFX8pw==&uniplatform=NZKPT&language=CHS', '四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2321, '报纸', '智慧旅游令人耳目一新', '朱金宜', '人民日报海外版', '人民日报海外版', '智慧旅游;旅游演艺;休闲街区;', '在博物馆里遇到“会讲故事”的文物、“穿越”到唐朝的市坊酒肆与李白杜甫打个招呼、打开手机小程序查看当前城市的数字文旅地图…… 随着人们的旅行需求从简单观光向深度体验转变，混合现实、光影技术、人机交互等数字科技正在积极进入旅游景区、文博机构、休闲街区等空间，', '2023-08-31 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2023.002963', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2326, '报纸', '天津西青区辛口镇第六埠村 股份合作社里的“红+绿”密码', '林单丹', '农民日报;中国农网;', '农民日报', '辛口镇;合作社;天津西青区;', '大清河故道，红色精神传承不息；千亩蟹田稻，厚植绿色发展生态底气。走进天津市西青区辛口镇第六埠村，站在大清河、子牙河与独流减河三河交汇处，游人能直观看到红色文旅和绿色生态农业的有机结合。这就是第六埠村特有的“红加绿”产业结构，现已成为村子多路径拓展村级集体', '2023-05-06 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2023.002046', '血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2328, '报纸', '方城全力保障红色热土长治久安', '孙雅琼; 袁立满; 张哲', '人民公安报', '人民公安报', '方城县;矛盾纠纷;公安机关;警务室;', '位于河南省西南的方城县，有着光荣的革命传统和丰富的红色资源。其中，独树镇战斗遗址，曾发生过红25军长征中生死攸关的一战，“鏖战独树镇”与血战湘江、四渡赤水等并列为长征八大著名战役，永载长征光辉史册。 身处这片红色热土的方城县公安局传承革命优良传统，赓续红色', '2022-08-11 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2022.004169', '血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2329, '报纸', '让红色基因代代相传', '张洋', '人民日报', '人民日报', '红色基因;中国共产党历史;展览馆;共产党人;奋斗历程;长城颂;奋斗目标;党员干部;民族复兴;', '一切向前走，都不能忘记走过的路；走得再远、走到再光辉的未来，也不能忘记走过的过去，不能忘记为什么出发。 首都北京，奥林匹克公园龙形水系旁，一座气势恢宏的地标建筑巍然矗立。这里，陈列着2500余幅图片、4500多件套文物实物，全方位、全过程、全景式、史诗般展现了中', '2022-06-18 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.006463', '血战湘江_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2330, '报纸', '大思政课，总书记心中的一件大事', '田丽; 赵婀娜; 黄超; 吴月', '人民日报', '人民日报', '思政课;社会主义建设者;接班人;高校思想政治工作;思想政治理论课教师;习近平总书记;', '“思想政治理论课能否在立德树人中发挥应有作用，关键看重视不重视、适应不适应、做得好不好。” 4月25日，习近平总书记来到中国人民大学考察调研，观摩思政课智慧教室现场教学，并对思政课建设提出明确要求。 “‘要造就一大批人，这些人是革命的先锋队。这些人具有政治远', '2022-05-22 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.005350', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2331, '报纸', '创新机制 用好用活', '韩洁', '中国文化报', '中国文化报', '红色旅游产品;低级别;湘江战役;红军长征;河南省;革命文物;红色文化旅游;文物保护单位;', '近年来，各地把革命文物保护利用工作列入重要议事日程，加大工作力度，深入发掘红色革命遗址的历史价值、时代价值和精神价值，在红色资源保护方面先行先试，探索了不少新路子。在各地实践过程中，全国人大代表、全国政协委员主动参与，为如何把红色资源利用好、把红色传统发', '2022-03-07 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.000729', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2332, '报纸', '历时9个月 讲述103个故事', '范燕莹', '中国新闻出版广电报', '中国新闻出版广电报', '主题出版;湘江战役;', '湘江之战是国共两党的生死决战。88年前，在广西桂北的湘江，国共两党发生了一场力量悬殊的生死决战。成千上万的红军将士用血肉之躯抵挡敌人的猛烈进攻，为长征和中国革命的最终胜利打开了前进的通途。 湘江战役后，中央红军已由出发时的8.6万余人锐减至3万余人。今天，当我', '2022-02-14 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.000432', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2334, '报纸', '一个走宽乡村振兴路的样板', '朱东; 周仕兴; 甘海燕; 刘启强; 李佳', '光明日报调研组;广西社科联;光明日报社广西记者站;广西农学报;广西幼儿师范高等专科学校;广西艺术学院党委宣传部;', '光明日报', '毛竹山;习近平总书记;才湾镇;葡萄产业;产业集群;振兴路;', '广西壮族自治区桂林市全州县毛竹山村是距县城13公里的一个小山村，毗邻“红军长征湘江战役”主战场——脚山铺，山清水秀，民风淳朴。88年前，红军在脚山铺阻击数倍于己的敌人，构建起抢渡湘江的生命通道。88年来，红军血战湘江的英勇事迹代代相传，红军精神激励着毛竹山村人', '2022-01-14 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.000246', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2337, '报纸', '传承友好 共创未来', '李琰; 李欣怡; 朱玥颖', '人民日报', '人民日报', '中非合作论坛;', '由外交部主办、中国宋庆龄基金会承办的第六届中非青年大联欢日前在北京落幕。活动以“回望中共百年光辉历程，凝聚青春智慧担当，共创中非共同发展新篇章”为主题，邀请了来自44个非洲国家的45名非洲在京留学生和青年代表参观交流。非洲青年代表纷纷表示，活动为非中青年交流', '2021-10-26 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011233', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2350, '报纸', '“文明其精神，野蛮其体魄”', '王鹏; 康锦谦; 白丽萍; 丁春雨', '人民日报', '人民日报', '习近平总书记;少年儿童;瑶族乡;军需处长;长征故事;红色基因;', '恰似破土而出的幼苗，又如振翅欲飞的雏鹰，少年儿童是祖国的希望，民族的未来。 从“六一”国际儿童节的殷殷寄语，到外出考察时的点滴关怀，再到尺素传情的深切厚望，党的十八大以来，习近平总书记对少年儿童的健康成长十分关心，对少年儿童工作给予全方位指导。 幼有', '2021-07-10 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007080', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2355, '报纸', '你的名字永远铭刻在神州大地上', '李一叶', '解放军报', '解放军报', '', '武夷山深处的千亩翠绿竹林中，1343根红飘带在四月的春风中静静轻扬。 三块青砖做墓门，没有姓名，没有番号，没有铭文。在这个偏僻的山岗上，80多年来，1343名红军烈士屹立成一方永恒的军阵。 而这片土地曾经被英烈的鲜血染红。 福建省南平市张山头村，是土地革命时', '2020-04-08 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2020.001847', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2356, '报纸', '上下同心再出发', '霍小光; 张旭东; 张晓松; 朱基钗', '人民日报', '人民日报', '习近平总书记;全国两会;全面建成小康社会;攻坚战;上下同心;', '6次深入人大政协团组，面对面听取48位代表委员发言，聚焦主要矛盾、抓住核心环节、紧盯突出短板、谋划重点任务…… 连日来，中共中央总书记、国家主席、中央军委主席习近平同出席2019年全国两会的代表委员广泛深入交流，紧紧围绕全面建成小康社会主线，共商决战决胜大计', '2019-03-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB5yBMPQLFU6-EnvXbm3hb7VBVPabkvF8ocMNji5bYhLBt6eDOsmyuQXQpDq4XmUo9OWBl7w4nDI66Z5Gu29QwII3n2YaqMV7tQijmKONLeJpvoUMcrO7xeto85KHBAj8B-M3RbkVErag==&uniplatform=NZKPT&language=CHS', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2358, '报纸', '四十位代表委员热议改革开放40年·文化篇', '', '光明日报', '光明日报', '优秀传统文化;洞窟壁画;敦煌研究院;敦煌壁画;文化体制改革;林连昆;八一电影制片厂;习近平总书记;中华民族;年产量;', '关于文化，习近平总书记这样说—— 没有高度的文化自信，没有文化的繁荣兴盛，就没有中华民族伟大复兴。要坚持中国特色社会主义文化发展道路，激发全民族文化创新创造活力，建设社会主义文化强国。 文化是一个国家、一个民族的灵魂。文化兴国运兴，文化强民族强。中', '2018-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICYe2DCIRGEhiR6pEmnZUc2j1rU3A7pyPg59VbU1o7k0B57LG036dBnWtBBIJYl25kz661RYc9W9WR019YoGQ6Xh-c3jQNohefLoyL0A-jLbvLB-peaIiIrUHNu23iquqCq-oI4jFy5UA==&uniplatform=NZKPT&language=CHS', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2359, '报纸', '在强军兴军伟大征程中筑就时代文艺高峰', '王欣阁; 丁小炜; 李伟; 傅强', '解放军报', '解放军报', '强军实践;文艺工作者;文艺创作;习主席;战士文艺;政治工作部;时代文艺;', '坚定文化自信，振奋民族精神，在世界各种文化激荡中岿然屹立 王晓棠（八一电影制片厂原厂长）：习主席的重要讲话，是站在历史与现实、国运与国脉的制高点上，对繁荣发展社会主义文艺事业一系列重大问题的深刻阐述。体现一个国家综合实力最核心的、最高层的，还是文化软', '2016-12-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAMTEVWlP9ChFb0JNl2118gQ1WFVhNqPoOSKK4ImhA4gXFU7_BPy1a2iPQNfgbSa0TrNFwS77eZX6rUA39R6JLGU1B-Tdkbahr2oG9UMg6pXENwNtJRin-ryT_ZvJLjpkKgpu5Jzqnawg==&uniplatform=NZKPT&language=CHS', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2360, '报纸', '不忘初心 再续能源新征程', '', '中国电力报', '中国电力报', '长征;', '理想与精神贯穿时代而愈加精粹，浓缩过往，辉映现在与未来。 80年前，带着对自由与光明的追索，中国共产党领导工农红军踏上了艰苦卓绝、辉煌壮阔的伟大征程。从血战湘江的艰险壮烈、到四渡赤水的神来之笔，从遵义会议的救亡转折，到根固陕北的命运抉择。跨雪山、过草地、', '2016-10-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDPFJolUIbVuVeIBoQshcahR6m67qGCdj-YX8HStKaL61fpq5Yt8VCl_o-of43uodrP_UCdWCtKQ_6tMK3cDD_3od-_NO6H2GjFJoF56yLFhIt7EzYz6t--rR0t7jQ9sPnUPFY1sCpPQA==&uniplatform=NZKPT&language=CHS', '血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2366, '报纸', '广西新建红军突破湘江陈列馆', '陈典宏', '解放军报', '解放军报', '湘江战役;', '人物名片 吴海峰，广西兴安县人大常委会副主任、红军突破湘江战役陈列馆筹备组负责人，长期从事湘江战役史料研究。 记者：红军长征突破湘江烈士纪念碑园已于1996年建成，并对外开放，为什么现在要新建陈列馆？ 吴海峰：今天，富裕起来的人民群众更需要红军长征精神', '2011-05-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA3VZlZImS1yjqBfUnh92MbcgtcA_T5R7uNHkicq4SnIPkmBd4OT5h1vYj1zVzUIwOJxb-jEIgCKzhEiNwm9_iSSlotdKHG01AdEqxOBdhYs5pdUGClYpv5XuhFidFQ3J_q56iXbaltpw==&uniplatform=NZKPT&language=CHS', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2368, '报纸', '从历史的真实到艺术的真实', '李蕾', '光明日报', '光明日报', '重大革命历史题材;王朝柱;历史的真实;', '从开创重大革命历史题材电视剧创作先河的《巨人的握手》,到红色经典《长征》、《延安颂》,到近期引起热播热议的《解放》、《解放大西南》,再到正在紧张拍摄的为辛亥革命100周年献礼作品《辛亥革命》,著名编剧王朝柱以恢弘开阔的视角,纵横捭阖的笔法,艺术地再现了中国革命波澜', '2011-02-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBf5__Iant0J9_4AdrK9QPXjIWvqxbXKhGMJWvw9nfPo5i3m4_YtR_toJ9UGKcXMD_F2-vSDfoB6NBtCkG5QILBxjEtrLjmxTflh9vlmyn2S0ukOZsHXy4QzWbu2etsqx5aM7JY8ehxVQ==&uniplatform=NZKPT&language=CHS', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2369, '报纸', '贺兰山文化润兵心', '陈兴平 ; 李世金 ; 徐殿闯', '解放军报', '解放军报', '李道明;', '甘为打赢当基石，志在戈壁磨利剑。入秋，宁夏军区某团官兵演兵贺兰山腹地某野外训练场，他们大力弘扬贺兰山传统文化，着力打造贺兰山特色文化，积极培育贺兰山战斗文化，奏出一曲独特的塞外交响曲。 边建边思边感悟 9月11日，记者来到该团野外驻训地采访，五连指导', '2010-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAuVUfkKDxURrY4POkJHn1aC-cOfCTjZfIVzv_YALl_gvb2AfvLTEh_vbqyLvgqaMXZFaOp7wy-DutdVxedlW04mH2FyCuHgE6wOFoWqRQNuMq07Qv7hnLKiTO5VgMijKtNN5MEOFMf0w==&uniplatform=NZKPT&language=CHS', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2370, '报纸', '上杭：汀江红旗今更艳', '杨清刚; 陈小军; 赖荣恩', '解放军报', '解放军报', '才溪乡;上杭县;古田会议会址;紫金矿业;红四军;中央苏区;', '“红旗跃过汀江，直下龙岩上杭。收拾金瓯一片，分田分地真忙。”80年前，毛泽东一句千古绝唱，道出了伟人当年在上杭时的豪迈之情，也见证了上杭在中国革命历史上那段如火如荼的辉煌岁月。  在上杭这片红土地上，老一辈无产阶级革命家毛泽东、周恩来、朱德、贺龙、陈毅等', '2009-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB0vCxI-UXUQbHfVbisykC14rKHuw9NyDld4v8zcej2tOXn-vFVFtgfhg-PTp9Lojma2c9G53Qm-Yq8RHoqih2-H20T9WpDuhPZHew3oHCT_xAgO-1rFafT9e-PxC22gYOhZguZxo-qTw==&uniplatform=NZKPT&language=CHS', '血战湘江_screened,飞夺泸定桥_screened,红四军_screened,闽西革命根据地_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2373, '报纸', '江泽民同志参观纪念红军长征胜利70周年展览', '柳晓森', '人民日报', '人民日报', '长征胜利;江泽民同志;', '本报北京１０月２１日讯 记者柳晓森报道：江泽民同志２１日下午来到中国人民革命军事博物馆，参观正在这里举行的“伟大壮举　光辉历程——纪念中国工农红军长征胜利７０周年展览”。李鹏、朱镕基、李瑞环、刘华清、尉健行、李岚清一同参观了展览。 下午５时许，江泽', '2006-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDCqDljQ8B7PoSNOG9T-TPCltrofOHkxTGmpd1V-PlbViuLbLmWk1dTMVtwXFIpYcbYVnXGLYdTUwqFvmV9HTN1rmRAdtrOA11ZAMTqMOCIYMKx5JPqeJS1RW52NVghMSG3F65YnQPUcw==&uniplatform=NZKPT&language=CHS', '血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2375, '报纸', '长征：长久的精神记忆', '毛帅', '人民日报', '人民日报', '长征史;中共党史出版社;', '中国工农红军长征胜利已经７０年了，许多当年的人和物都随着时间消逝而远去，惟有记忆和精神难以被时间带走，而是随着一代代人的繁衍而传承下去，并因为时间的积淀而更显沉重和深刻，纪念红军长征胜利７０周年的图书证明了这一点。 史料类书籍准确记述历史 由中共中', '2006-10-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAofxgvS2Cxkl0-hzvv_lRu0B85BrmGU6c_4r7w1TEnZshTqy-5XBukM3lQU4zfe0PmTE3w0TtuyCRJ4IvXB-bbGXCy3Ej_fIMg4XdiYOLlpFpc0uc5lP-G38wk74sbqk4Zt0VTbe1-2Q==&uniplatform=NZKPT&language=CHS', '血战湘江_screened');
INSERT INTO `ds_article` VALUES (2379, '报纸', '《长征》缘何吸引人？', '向兵', '人民日报', '人民日报', '长征精神;周恩来;《长征》;唐国强;中央电视台;', '红色七月，文艺舞台热闹非凡，影视屏幕亦精彩纷呈，其 间最为耀眼者当数二十四集电视剧《长征》。播出期间即有统 计数据显示，全国收视率10．01％，北京地区高达17．9％，创下 了同类题材的最高纪录。在这些日子里，观众热情洋溢的电 话、信件、电子邮件', '2001-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBmuiuzZuZBMs9NzlvZwvubUxv_ZVOVatU5ca9FttqhhO6T1BZQSqOMPe_HYO7i6KkamxmCf18Nxy2VePqTRJcK13zwEr48W299RTj1gQOyxqucY0cAJ7BJCfkxGN_4PkraWO5u4LIdsw==&uniplatform=NZKPT&language=CHS', '血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2380, '报纸', '休假归来，带回一堂好课', '耿忠勇; 胡洲源; 赵杨; 唐帅', '解放军报', '解放军报', '革命故事;教育者;南疆军区;', '“六盘山是红军长征翻越的最后一座高山，山道盘旋……” 讲台上，南疆军区某团卫生连女兵谢嘉丽用自然生动的语言，讲述着她休假时参观红色景点的感受。讲台下，连队官兵听得认真，互动积极。 谢嘉丽的家乡在宁夏银川，去年休假期间，她跟着父母到周边固原市的亲戚家串门。', '2024-01-08 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2024.000042', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2381, '报纸', '“红飘带”里的“长征路”让硬汉落泪', '李丰', '工人日报', '工人日报', '红飘带;贵州省;长征故事;红色文化;长征路;红色资源;红军长征;', '阅读提示 红军长征在贵州活动时间最长、活动范围最广，留下丰富文物资源和宝贵精神财富。红军长征足迹遍及贵州9个市（州）60多个县（市、区），在此召开了党的历史上具有伟大转折意义的遵义会议，创下强渡乌江、激战娄山关、四渡赤水等经典战例。2019年，贵州被确定为长征国', '2024-01-07 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2024.000092', '遵义会议_screened,血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2382, '报纸', '赓续历史文脉 广泛凝聚共识', '张丽', '人民政协报', '人民政协报', '中华民族;中国式现代化;习近平总书记;中华优秀传统文化;现代文明;时代化;马克思主义中国化;凝聚共识;', '编者按： 习近平总书记对宣传思想文化工作作出的重要指示，明确提出“七个着力”的重大要求，其中强调“着力建设具有强大凝聚力和引领力的社会主义意识形态”等。第十三届全国政协委员，湖南师范大学特聘教授、中国统一战线理论研究会湖南基地特约研究员郑大发近年来致力于', '2023-11-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICLMzGvXjPFQcc_WXjTK8UWRW5jMZyAgZ-d-pzMTSHTCHzRXcufqDtZdEBsvr6w6s1cHNFP44fWDLYsH7IiKcFVh8rKWppmy1cuxPEZy_ZB1VqYxbbGwiMafQva0c-wl_57mF6AMN_bLw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2383, '报纸', '红色之城绿映红', '黄朝武; 刘久锋; 胡然然', '农民日报;中国农网;', '农民日报', '村级集体经济;遵义市;村干部;乡村治理;农村基层党组织;村民小组;', '巍巍娄山关，从头一越。悠悠赤水河，得意之笔。 88年前，红军长征经过贵州遵义，在此转战95天，留下了遵义会议会址等586处革命遗址遗迹，红色基因成为遵义党员干部群众的鲜明特质。 “一谢共产党，翻身把你想，以前我们做牛马，现在人人把家当；二谢共产党，吃饭把你想……', '2023-09-12 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2023.004495', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2384, '报纸', '于都河畔，又见那条“红飘带”', '尧欣颖; 梁志伟; 郭冬明', '中国国防报', '中国国防报', '肖向荣;长征故事;红飘带;舞台剧;', '8月中旬，江西于都，长征大剧院舞台上，《长征第一渡》序幕缓缓拉开。 开场，影像结合舞美形成一组巨型浮雕，在灯光的映照下，红军战士坚毅的脸庞渐渐浮现，他们矗立水面，目光如炬。舞台一侧，一位老太太一边编着草鞋，一边诉说着关于于都河的故事。灯灭，炮火声从远处传来', '2023-08-21 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2023.001053', '遵义会议_screened,血战湘江_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2385, '报纸', '西安市碑林区文化馆：在非遗传承传播中激发爱国情怀', '秦毅; 孙欢', '中国文化报', '中国文化报', '文化馆;传承人;棉絮画;碑林区;西安市;爱国情怀;', '“我这幅棉絮画的主人公是小红军，你看，他正起劲地吹响冲锋号呢……”近日，11岁的贾思露在陕西省西安市碑林区文化馆内，指着自己刚完成的棉絮画作品介绍。 与贾思露一道，在西安市红色非遗展演暨党史宣讲活动中，近百名青少年及家长通过参观一件件红色主题非遗作品，深刻', '2023-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDscrgqLlTOgVbZSJiajrfOxgL3M0XVBwutYl4CebSOf8j4PAt3EGQJZ6LCbiMxMMLYwDpmlSPgrIDq5uuLBib4aCcMCvbnh2PFQeO2dd2Z3YEgPQRhs8CS166d8Wd0SNG6G8WrznepnQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2386, '报纸', '发展红色旅游 播撒“红色种子”', '赵腾泽; 周晨; 任丽; 李金枝', '中国旅游报', '中国旅游报', '红色旅游;习近平总书记;红色文化;红色资源;文化传承;陕西旅游;', '习近平总书记在文化传承发展座谈会上强调，要坚定文化自信、担当使命、奋发有为，共同努力创造属于我们这个时代的新文化，建设中华民族现代文明。 进入暑期，红色旅游显著升温。各地红色旅游景区景点游客络绎不绝，博物馆、纪念馆迎来大批研学团队。红色旅游在赓续红色血脉', '2023-07-17 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2023.001588', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2387, '报纸', '遵道行义传薪火', '赵新兵; 王丽; 李惊亚; 吴箫剑', '新华社;', '新华每日电讯', '遵义会议纪念馆;遵义城;红军长征;红色基因;红色文化;遵义会议精神;遵义会议会址;', '北倚娄山，南濒乌江，远瞰巴巫，险要天成。这里是遵义。 历史演进，时节如流。这片积淀千年文明的沃土以“道”载义，以“义”遵道，深明大义、开放包容、勇于开拓。 如今，这座遵道行义之城接续传承红色基因、努力讲好遵义故事，正在历史长河中开出更绚烂之花朵、结出更丰', '2023-06-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.003575', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2390, '报纸', '红色资源星罗棋布 红色血脉代代相传', '文静; 孙凤莲', '中国民族报', '中国民族报', '革命文物;可移动;国家文物局;红色旅游景区;文物保护单位;遵义会议纪念馆;红色资源;', '一物胜千言，睹物思历史。 在中华民族的历史文化遗产中，有一个特殊的类别——革命文物。它们记录了一段段直抵人心的红色故事、一个个继往开来的历史瞬间，承载着党和人民英勇奋斗的光荣历史，传承着催人奋进的红色基因，是中国共产党披荆斩棘、砥砺奋进的见证。 2021年3月', '2023-04-07 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2023.000337', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2395, '报纸', '“红色旅游+”：革命精神放射新的时代光芒', '刘源隆', '中国文化报', '中国文化报', '红色旅游;遵义会议纪念馆;红色旅游景区;', '党的二十大报告提出，弘扬以伟大建党精神为源头的中国共产党人精神谱系，用好红色资源，深入开展社会主义核心价值观宣传教育，深化爱国主义、集体主义、社会主义教育，着力培养担当民族复兴大任的时代新人。 在“奋进新时代”主题成就展第五单元，一张小学生在贵州省遵义会', '2022-10-26 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.003704', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2396, '报纸', '弘扬中国共产党人精神谱系 凝聚新时代文旅奋进力量', '王洋; 郭子腾; 杨丽敏; 高慧; 魏彪', '中国旅游报', '中国旅游报', '红色资源;精神财富;红色基因;文化自信;踔厉奋发;共产党人;精神谱系;', '10月16日，中国共产党第二十次全国代表大会在京开幕。习近平总书记代表第十九届中央委员会向大会作报告。报告提出，弘扬以伟大建党精神为源头的中国共产党人精神谱系，用好红色资源，深入开展社会主义核心价值观宣传教育，深化爱国主义、集体主义、社会主义教育，着力培养担', '2022-10-21 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.002843', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2398, '报纸', '加强高校爱国主义教育的意义与路径', '周妍', '广西电力职业技术学院马克思主义学院;', '中国文化报', '高校爱国主义教育;思想政治教育;党史文化;大学生爱国主义;中国共产党党史;', '古人说，“以铜为鉴，可以正衣冠，以人为鉴，可以知得失，以史为鉴，可以知兴替。”了解过去，才能更加坚定地把握未来。中国共产党是中国人民和中华民族的先锋队，是新中国的缔造者，是中国特色社会主义事业的领导核心。对于青年人才来说，只有全面深入地了解党的诞生史、党', '2022-07-12 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.002146', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2399, '报纸', '壮丽的史诗 精神的殿堂', '', '新华社;', '人民日报', '展陈设计;中国共产党历史;党史学习;展览馆;习近平总书记;', '首都北京，中轴线北延长线的东侧，一座雍容大度、气势磅礴的地标建筑巍然矗立，这就是中国共产党历史展览馆。这座中国共产党永久性、综合性的党史展览馆，第一次全方位、全过程、全景式、史诗般展现了中国共产党波澜壮阔的百年历史，浓墨重彩地反映了党的不懈奋斗史、不怕牺', '2022-06-20 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.006471', '遵义会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2400, '报纸', '夯实法治之基 赓续红色血脉', '王家梁; 岳端; 杨文松', '法治日报', '法治日报', '革命老区县;乡村治理;', '贵州省遵义市红花岗区子尹路96号的遵义会议会址，中西合璧的两层楼房跨越百年依然矗立，静静述说着中国革命在这里实现伟大转折，从此走上胜利道路的历史。 作为红军长征时活动时间最长、范围最广的省份，贵州处处留下红军的足迹。 贵州儿女在传承红色基因、赓续红色血脉中', '2022-06-07 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2022.003050', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2401, '报纸', '共和国青年运动的摇篮', '陈书海; 陈卓琼; 周围围', '中青报;中青网;', '中国青年报', '青年运动;中央苏区;少共国际师;青年运动史;共和国;', '编者按 为迎接党的二十大的胜利召开，庆祝中国共产主义青年团建团100周年，共青团江西省委、共青团赣州市委、中共赣州市委党史研究室启动了《中央苏区青年运动史》重修编撰工作。该书介绍了第二次国内革命战争时期中央苏区青年运动的发展历程，再现了波澜壮阔的中央苏区青年', '2022-04-28 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.001529', '遵义会议_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (2402, '报纸', '“窑洞对”的第二个答案', '刘少华', '人民日报海外版', '人民日报海外版', '窑洞对;全面从严治党;中国共产党;', '参加十三届全国人大五次会议内蒙古代表团审议时，习近平总书记强调，全面从严治党是党永葆生机活力、走好新的赶考之路的必由之路。 几个月前，党的十九届六中全会上，习近平总书记专门提到“窑洞对”：我们党历史这么长、规模这么大、执政这么久，如何跳出治乱兴衰的历史周', '2022-03-25 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2022.000880', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2404, '报纸', '用好历史经验 绽放时代光芒', '雷萌', '中国新闻出版广电报', '中国新闻出版广电报', '遵义会议纪念馆;长征路;共产党人;遵义会议精神;走向胜利;习近平总书记;红军长征;中国特色社会主义道路;', '历史长河波涛汹涌，关键处往往只有几步。28年新民主主义革命，位于时间轴中点的遵义会议是伟大的转折。 1935年1月，黔北遵义子尹路96号，一幢两层砖木楼房深深打上历史的烙印。在红军第五次反“围剿”失败和长征初期严重受挫的历史关头，中国共产党人在这里召开了遵义会议，', '2022-02-23 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.000569', '遵义会议_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2405, '报纸', '“VR+”带你穿越时空学党史', '许子威; 张是卓', '中青报;中青网;', '中国青年报', '思政课;全景图;《资本论》;虚拟仿真;本科生;', '穿过枪林弹雨，顺利挺进闽西，揭开创建中央革命根据地的序幕；骑上自行车，穿梭在瑞金，感受中华苏维埃共和国的风貌；化身为一名红军战士，和战友在百姓的帮助下一起搭浮桥，渡过于都河，走上长征路……当这些场景浮现在眼前时，不要怀疑自己的眼睛，这是开在VR虚拟仿真实验', '2022-02-22 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.000611', '遵义会议_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2409, '报纸', '“小课堂”讲好党史“大故事”', '杨正军; 陈冠合', '贵州大学马克思主义学院;', '光明日报', '党史学习;理论宣讲;思政课;', '红军长征时，在贵州活动时间最长、活动范围最广，留下了极为丰富的宝贵精神财富。从郁郁葱葱的红军山到重峦叠嶂的娄山关，从波涛汹涌的乌江到奔流不息的赤水，诉说着遵义会议挽救中国革命的伟大意义，也蕴含着生动和丰富的育人价值。 在贵州讲好党的历史这本最生动、最有', '2022-01-04 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.000029', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2411, '报纸', '全面从严治党引领保障“十四五”开好局起好步', '郭兴', '中国纪检监察报', '中国纪检监察报', '全面从严治党;“一把手”;纪检监察机关;领导班子;', '2021年，伟大事业掀开新的篇章，伟大工程踏上新的征程。 这一年，中国共产党迎来百年华诞，我们党深刻总结百年奋斗重大成就和历史经验。习近平总书记在庆祝中国共产党成立100周年大会上强调，“我们党历经千锤百炼而朝气蓬勃，一个很重要的原因就是我们始终坚持党要管党、', '2021-12-30 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.005943', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2413, '报纸', '跳出历史周期率的第二个答案', '叶再春', '中央宣传部宣传舆情研究中心;', '中国纪检监察报', '历史周期率;第一代中央领导集体;全面从严治党;毛泽东;党中央;', '延安时期，毛泽东同志与黄炎培之间有一段著名的“窑洞对”。在党的十九届六中全会上，习近平总书记专门提到“窑洞对”，指出：经过百年奋斗特别是党的十八大以来新的实践，我们党又给出了第二个答案，这就是自我革命。“窑洞对”的时代回答不断拓展深化、丰富立体，深刻回应', '2021-12-16 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.005748', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2415, '报纸', '八桂山水别样红', '黄静莹; 周鹏; 吴丽萍', '中国旅游报', '中国旅游报', '红色旅游景区;红军长征;红七军;粤东会馆;精品线路;旅游区;百色起义;湘江战役;民俗风情园;红色旅游品牌;纪念园;广西壮族自治区;红色文化旅游;', '八桂大地，红色热土。5月14日，文化和旅游部、中央宣传部、中央党史和文献研究院、国家发展改革委联合发布“建党百年红色旅游百条精品线路”，其中，广西共有“百色起义·红色广西”“血战湘江·突破包围”“八桂大地·乡村欢歌”3条线路入选。这些线路特色鲜明，内涵丰富，', '2021-12-08 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.003460', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2416, '报纸', '增强历史自觉 把握历史主动', '王心富', '山东省人民政府;', '学习时报', '马克思主义政党;历史自觉;中国特色社会主义;习近平;历史决议;修正错误;“左”倾教条主义;毛泽东思想;马克思主义中国化;', '党的十九届六中全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》（以下简称《决议》），全面总结了党的百年奋斗重大成就和历史经验，是增强“四个自信”的思想武器，是迈向新时代、启航新征程的重要遵循，是增强历史自觉、把握历史主动的最新教材。', '2021-12-06 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002305', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2422, '报纸', '为了更加伟大的胜利和荣光', '张晓松; 朱基钗; 杜尚泽; 桂从路', '新华社;', '人民日报', '决议案;政治局;共产党;中国特色社会主义;中央委员会;习近平总书记;党史学习;中国共产党成立;', '这是一次注定载入中华民族伟大复兴史册的重要会议—— 2021年11月8日至11日，中国共产党第十九届中央委员会第六次全体会议在北京胜利召开。 全会重点研究了全面总结党的百年奋斗的重大成就和历史经验问题，审议通过了党的第三个历史决议，号召全党全军全国各族人民以史', '2021-11-13 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011924', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2425, '报纸', '共产国际与中国革命关系研究的重要成果', '杨云若', '中国人民大学;', '中国新闻出版广电报', '共产国际;中央根据地;', '从20世纪90年代起，原中共中央党史研究室第一研究部黄修荣同志组织有关专家编译以俄罗斯重要档案资料为基础的大型档案文献集“共产国际、联共（布）与中国革命资料丛书”，历经将近20年紧张辛勤的工作，该书21卷已陆续出版。 共产国际在指导中国革命过程中起过重要作用。', '2021-11-09 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004429', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2433, '报纸', '“迈向新长征，踏平坎坷再出发”', '张石水; 王钰凯; 钱亦然', '解放军报', '解放军报', '红一连;连队官兵;长征故事;腊子口;战斗英雄;', '1984年，美国著名记者哈里森·索尔兹伯里飞越大洋，不远万里来到中国，只为“重走长征路”。 一名76岁的西方记者为何要走这两万五千里路？ 在哈里森·索尔兹伯里的著作《长征：前所未闻的故事》中，或许可以找到答案——“在我们这个世纪中还没有什么其他事件能像长征', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006718', '遵义会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2435, '报纸', '怀化：山的那边是海', '雷绍业', '湖南省怀化市委;', '学习时报', '杂交水稻;袁隆平;今井武夫;芷江受降;', '怀化作为地名源自宋代设置的“怀化砦”，取有“怀柔归化”之义。20世纪30年代，作家沈从文先生，曾乘船沿沅江溯源而上，惊叹怀化的山水之美，发出“美得令人心痛”的感慨。 （一） 怀化古称五溪，素有“滇黔门户”“全楚咽喉”之称。 “枋船万里通六诏，五溪烟水下', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001976', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2436, '报纸', '聆听历史回响 阔步新的长征', '李学勇; 李砺寒', '新华社;', '人民日报', '长征路上;胜利之路;一切从实际出发;红军战士;习近平;毛泽东;思想路线;', '这是一条筚路蓝缕之路，也是一条通往胜利之路； 这是一条荆棘遍布之路，也是一条开创新局之路。 栉风沐雨，浴血淬火。长征，是改变中国命运的伟大远征。长征精神，已成为中国共产党人精神谱系中的宝贵财富。 历史照亮未来，征程未有穷期。 当我们站在建党百年这', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011113', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2439, '报纸', '最深厚的滋养', '吴秉泽', '经济日报', '经济日报', '红色基因;', '每次走进遵义，都有一种感觉：红色基因已经深深融入这座城市的血液之中，润物无声；人们的灵魂被这丰厚的红色营养滋润着，迸发出无穷动力。 红色基因诞生自烽火纷飞的革命年代。遵义曾经诞生了我党在贵州的第一个党组织。长征期间，党中央在遵义召开了以遵义会议为代表的', '2021-10-19 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.007402', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2440, '报纸', '让遵义会议精神永放光芒', '', '人民日报', '人民日报', '遵义会议精神;中国具体实际;党中央;马克思主义基本原理;第一代中央领导集体;', '长征途中召开的遵义会议，是我们党历史上一个生死攸关的转折点。习近平总书记深刻指出，“遵义会议作为我们党历史上一次具有伟大转折意义的重要会议，在把马克思主义基本原理同中国具体实际相结合、坚持走独立自主道路、坚定正确的政治路线和政策策略、建设坚强成熟的中央领', '2021-10-19 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.010888', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2441, '报纸', '弘扬遵义会议精神 走好新时代长征路', '黄超', '人民日报', '人民日报', '遵义会议精神;共产党人;遵义会议纪念馆;政治局扩大会议;党中央;习近平总书记;中国具体实际;长征路;', '遵义会议作为我们党历史上一次具有伟大转折意义的重要会议，在把马克思主义基本原理同中国具体实际相结合、坚持走独立自主道路、坚定正确的政治路线和政策策略、建设坚强成熟的中央领导集体等方面，留下宝贵经验和重要启示。我们要运用好遵义会议历史经验，让遵义会议精神永', '2021-10-19 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.010905', '遵义会议_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2444, '报纸', '伟大转折激励勇往直前', '吕慎; 户华为; 陈雪', '光明日报', '光明日报', '中国共产党人;遵义会议纪念馆;习近平总书记;毛泽东;中国特色社会主义道路;马克思主义基本原理;遵义会议精神;主动求变;党中央;王稼祥;人类命运共同体;', '建党百年之际，遵义会议纪念馆屡屡超过接待人数的极限。人们仰望着这栋熠熠生辉的砖楼，追寻着中国共产党的历史足迹，铭记着中国共产党人的精神坐标。 “在极端危急关头，挽救了党，挽救了红军，挽救了中国革命!”1935年1月15日到17日召开的遵义会议，改变了中国革命进程', '2021-10-18 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005296', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2445, '报纸', '遵义会议精神照亮新时代长征路', '青平', '中国青年报', '中国青年报', '遵义会议精神;马克思主义基本原理;共产党人;坚持真理;长征路;', '2015年6月，在纪念遵义会议召开80周年之际，习近平总书记前往贵州考察，他在参观遵义会议会址和遵义会议陈列馆时强调，遵义会议作为我们党历史上一次具有伟大转折意义的重要会议，在把马克思主义基本原理同中国具体实际相结合、坚持走独立自主道路、坚定正确的政治路线和政策', '2021-10-18 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.003729', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2446, '报纸', '遵义：从伟大转折中汲取前进智慧', '金晶; 汪怡潇; 刘浩', '人民法院报', '人民法院报', '红军长征;人民调解员;赤水市;', '今年，党中央决定在全党开展党史学习教育，2月3日至5日，习近平总书记在贵州考察调研，他强调，要结合即将开展的党史学习教育，从长征精神和遵义会议精神中深刻感悟共产党人的初心和使命，落实新时代党的建设总要求，实事求是、坚持真理，科学应变、主动求变，咬定目标、勇往', '2021-10-11 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.004613', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2447, '报纸', '“四个自信”的历史必然', '迟行刚', '北京市朝阳区委;组织部;', '学习时报', '历史必然;中国特色社会主义道路;人民代表大会制度;马克思主义经典作家;改革创新;共产党;社会主义核心价值观;', '对一个政党、一个国家、一个民族而言，自信是十分宝贵的精神基石。放眼百年，党领导人民探索出中国特色社会主义道路、理论、制度和文化，并验证了道路的正确、理论的科学、制度的优越、文化的先进，垒筑起不可动摇的“四个自信”。 在探索和比较中开创正确道路。道路探索', '2021-10-11 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001886', '遵义会议_screened,秋收起义_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2448, '报纸', '“公园省”力邀旅游产业投资 给予顶级服务', '王乐如; 吴承坤', '中国经济导报', '中国经济导报', '旅游业态;', '中国经济导报讯 记者王乐如 吴承坤报道 “走遍大地神州，醉美多彩贵州。”贵州因保留了大量原生态自然美景，被誉为“公园省”。贵州省省委副书记、省长李炳军出席日前召开的2021国际山地旅游暨户外运动大会和第十六届贵州旅游产业发展大会时致辞表示，“当前的贵州旅游市场商', '2021-09-30 08:00:00', 'https://link.cnki.net/doi/10.28095/n.cnki.ncjjd.2021.002333', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2451, '报纸', '万山磅礴有主峰', '', '人民日报', '人民日报', '党中央;习近平总书记;', '97.如何理解必须坚决维护习近平总书记党中央的核心、全党的核心地位？ 一个国家、一个政党，领导核心至关重要。毛泽东同志曾作过一个生动的比喻：“一个桃子剖开来有几个核心吗？只有一个核心。”党的十八届六中全会正式确立习近平总书记党中央的核心、全党的核心地位，党', '2021-09-27 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.010241', '遵义会议_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2452, '报纸', '贵州省最美退役军人陈晓义：用心讲好红色故事', '王金晶', '人民政协报', '人民政协报', '退役军人;贵州省;', '“贵州是红军长征经过的11个省中活动时间最长、区域范围最广、发生重大事件最多，留下革命精神最为丰富的省份。”在贵州海智达文化教育发展有限公司董事长陈晓义看来，红色文化是多彩贵州的文化之魂。 贵州是红色圣地，也是陈晓义从军的起点。1990年，陈晓义应征入伍，在', '2021-09-24 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.007627', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2453, '报纸', '一张收条鉴初心', '冉鹏', '贵州省遵义市委组织部;', '中国组织人事报', '红军战士;苏维埃;', '1952年春天，家住贵州遵义市红花岗区凉水乡的赵玉琳起了一个大早。一直以来，父亲赵金和口中的“传家宝”，令他充满好奇。趁着父亲不在家，赵玉琳偷偷地打开“传家宝”——一个木匣子，一张字迹工整清秀的收条呈现在眼前，里面还装有15张苏维埃币。 在中国革命进程中，中', '2021-09-22 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.003064', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2454, '报纸', '遵义：“转折之城”赓续治水初心', '段玲玲; 杨智慧', '中国水利报', '中国水利报', '遵义会议精神;乌江干流;遵义市;平正仡佬族乡;习近平总书记;污水处理厂;赤水河;水生态文明;有机茶叶;生态屏障;黑臭水体;生态渔业;', '贵州遵义，一座名城。 翻开历史课本，遵义是“红色”的。1935年，红军长征在此转战3个月，彪炳史册的遵义会议在这里召开，四渡赤水出奇兵的传奇在这里流传。 翻开地理课本，遵义是“绿色”的。它位于贵州省北部、黔川渝三省市接合部，是长江中上游重要的生态屏障区。境', '2021-09-11 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2021.001479', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2456, '报纸', '贵州：合力共建长征文化高地', '吕慎', '光明日报', '光明日报', '文化高地;贵州省;遵义会议精神;文化公园;', '长征过程中，红军在贵州活动时间最长、活动范围最广，为这片土地和人民留下了宝贵精神财富。遵义会议更是中国共产党历史上一次具有伟大转折意义的重要会议，开启了党独立自主解决中国革命实际问题的新阶段，创造性地制定和实施了符合中国革命特点的战略方针。 党史学习教', '2021-09-03 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.004544', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2457, '报纸', '伟大建党精神照亮新征程', '王瑞军', '贵州省委组织部;', '中国组织人事报', '党中央;教育引导;立党为公、执政为民;习近平总书记;长征路;共产党人;党的组织路线;马克思主义;', '习近平总书记在庆祝中国共产党成立100周年大会上，鲜明提出了“坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民”的伟大建党精神。伟大建党精神是党的精神谱系的源头，也是推进新时代党的建设新的伟大工程的根本方向和价值取向。我们要认真', '2021-08-27 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.002799', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2459, '报纸', '乘风破浪开新局', '赵承; 霍小光; 邹伟; 赵超; 韩洁; 朱基钗; 杨依军', '人民日报', '人民日报', '习近平总书记;多边主义;人类命运共同体;共同富裕;', '2021年，注定意义非凡。 中国共产党百年诞辰，“两个一百年”在这里交汇；“十四五”规划开始实施，全面建设社会主义现代化国家踏上新征程。 今年以来，以习近平同志为核心的党中央统筹中华民族伟大复兴战略全局和世界百年未有之大变局，统筹疫情防控和经济社会发展，', '2021-08-15 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.008504', '遵义会议_screened,血战湘江_screened');
INSERT INTO `ds_article` VALUES (2460, '报纸', '红色贵州 而今迈步从头越', '苏滨', '人民日报海外版', '人民日报海外版', '博物馆;精品线路;遵义会议会址;三线建设;红色文化;乡村旅游;试验区;四渡赤水;习水县;', '遵义会议会址，四渡赤水纪念馆，息烽集中营革命历史纪念馆……万峰相连，多彩秀丽，地处中国西南腹地的贵州，红色文化资源富集。贵州共有88个县级行政区划单位，红军长征途经61个。这一连串的红色烙印，镌刻于黔山秀水间，在新征程中熠熠生辉。 “建党百年红色旅游百条精', '2021-08-05 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002409', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2463, '报纸', '贵州：精神文明奏新曲', '吕慎', '光明日报', '光明日报', '营盘乡;国家森林公园;遵义市;', '贵州是中国革命的转折之地，党的十八大以来，这里不仅成为国家生态文明试验区，而且实现了932万贫困人口全部脱贫，在建设新时代文明实践中心过程中，他们统筹红色文化、生态资源、脱贫成果，以红色为旋律、绿色为背景、乡村为和声，奏响了新时代精神文明建设的交响曲。 红', '2021-07-30 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003870', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2469, '报纸', '永续不变的红色传承', '梁蓬飞; 钱晓虎; 周远; 张圣涛', '解放军报', '解放军报', '红一连;参观见学;优良传统;', '2021年7月1日，中国共产党百年华诞。 这天中午，一群年初入伍的新兵来到第83集团军某旅“红一连”参观见学。令他们惊讶的是，连队精心准备的午餐不见一个“硬菜”，只有两样：红米饭、南瓜汤。 这顿“饭”可不简单。1927年“三湾改编”，毛泽东在“红一连”亲自组织发', '2021-07-27 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004778', '遵义会议_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (2470, '报纸', '永远的军魂', '李清华; 张圣涛; 王会甫', '新华每日电讯', '新华每日电讯', '红一连;', '雄伟的井冈山， 八一军旗红。 开天辟地第一回， 人民有了子弟兵。 …… 问渠那得清如许？为有源头活水来。如果说，南昌起义塑造了人民军队的“形”，那么，三湾改编无疑熔铸了人民军队的“魂”，而保证这支军队军魂永驻的一项重要原则和制度，就是“支部建在', '2021-07-27 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005708', '遵义会议_screened,秋收起义_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (2471, '报纸', '赓续红色血脉 凝聚奋进力量', '李仁平', '中华工商时报', '中华工商时报', '理想信念教育;企业家;党史学习;民营经济;百年华诞;信念感;习近平总书记;南通博物苑;', '习近平总书记强调，红色资源是我们党艰辛而辉煌奋斗历程的见证，是最宝贵的精神财富。红色血脉是中国共产党政治本色的集中体现，是新时代中国共产党人的精神力量源泉。 如何用好红色资源，赓续红色血脉？全国工商联精心筹划组织，深入推进以党史为重点的“四史”宣传教育', '2021-07-26 08:00:00', 'https://link.cnki.net/doi/10.38311/n.cnki.nzhgs.2021.003461', '遵义会议_screened,黄洋界_screened,三湾改编_screened,朱毛会师_screened');
INSERT INTO `ds_article` VALUES (2475, '报纸', '5G赋能红色资源，为红色添亮色', '', '中国移动通信集团有限公司党组宣传部;', '学习时报', '红色文化教育;红色资源;精品网络;中国移动;', '中国移动通信集团有限公司认真学习领会习近平总书记《用好红色资源，传承好红色基因，把红色江山世世代代传下去》重要文章精神，深入贯彻落实《新时代爱国主义教育实施纲要》《关于在中国共产党成立100周年庆祝活动中突出发挥爱国主义教育基地作用的通知》等文件要求，结合党', '2021-07-14 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001279', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2477, '报纸', '历史在这里转折', '李嘉; 刘忠学; 孟威', '中国质量报', '中国质量报', '遵义市;遵义会议会址;营商环境;茅台酒;遵义城;', '遵义，地处黔北山区的一座红色之城、魅力之城。在这里召开的遵义会议，是中国共产党历史上生死攸关的转折点。 1935年1月15日至17日，中共中央政治局扩大会议（史称遵义会议）在这里召开。遵义会议集中全力解决了当时具有决定意义的军事和组织问题，结束了“左”倾教条主义', '2021-07-12 08:00:00', 'https://link.cnki.net/doi/10.28164/n.cnki.nczlb.2021.002103', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2479, '报纸', '传承弘扬伟大建党精神 在建设现代化新征程上阔步前进', '楼阳生', '河南省委;', '学习时报', '习近平总书记;全面从严治党;党中央;奋斗目标;中央领导集体;传承弘扬;', '在庆祝中国共产党成立100周年大会上，习近平总书记发表的重要讲话，高屋建瓴、思想深邃，气势恢宏、博大精深，提出了一系列新的重大思想、重大观点、重大论断，通篇闪耀着马克思主义的真理光芒，展现着“我将无我、不负人民”的领袖风范，具有很强的时空穿透力、理论说服力、', '2021-07-12 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001230', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2480, '报纸', '根植红色沃土 赓续红色血脉', '文静', '中国民族报', '中国民族报', '革命文物;可移动;红色旅游景区;文物保护单位;湘江战役;红色基因;红军长征;国家文物局;红色资源;长征精神;革命纪念地;红色旅游资源;纪念园;', '从中共一大会址到中共中央北京香山革命纪念地，从陕甘宁革命老区到福建古田会议会址，从贵州遵义红军山烈士陵园到广西红军长征湘江战役纪念馆……十八大以来，习近平总书记在地方考察时遍访革命故地、红色热土，反复叮嘱要用好红色资源、传承红色基因。今年6月在中共中央政治', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.000699', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2482, '报纸', '奋力开创新时代贵州公安工作新局面', '', '人民公安报', '人民公安报', '贵州省;公安机关;习近平总书记;', '记者：今年春节前夕，习近平总书记到贵州视察，提出一系列重要指示和殷切嘱托，这对贵州公安发展具有什么样的指导意义？ 郭瑞民：习近平总书记心系贵州发展、情系贵州人民，多次在重要历史节点亲临贵州视察指导，对贵州工作作出重要指示。今年2月，总书记再次视察贵州，就', '2021-07-07 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003826', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2483, '报纸', '弘扬遵义会议精神 走好新时代的长征路', '周文学; 缪春云; 韩涛', '人民公安报', '人民公安报', '综合治理体系;贵阳市;遵义会议精神;公安机关;易地扶贫搬迁;户口迁移;习近平总书记;公安民警;贵州省;安置区;公安厅;长征路;', '贵州——中国革命的圣地。当年，红军长征在贵州活动时间最长、活动范围最广，特别是遵义会议在最危急关头挽救了中国共产党、挽救了红军、挽救了中国革命，为我们留下了宝贵的精神财富。红色血脉始终在贵州大地赓续传承，红色基因不仅深藏着各项事业取得成功的精神密码，更成', '2021-07-07 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003827', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2484, '报纸', '传承红色基因 忠实履行职责', '彭容江', '公安局;', '人民公安报', '红色基因;遵义会议精神;习近平总书记;履行职责;', '今年2月，习近平总书记在贵州考察调研时强调，“从长征精神和遵义会议精神中深刻感悟共产党人的初心和使命，落实新时代党的建设总要求，实事求是、坚持真理，科学应变、主动求变，咬定目标、勇往直前，走好新时代的长征路”。习近平总书记的重要指示精神是我们推进工作的根本', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003751', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2485, '报纸', '勇于担当作为 建设一流商会', '', '中华工商时报', '中华工商时报', '艺术品;中国共产党成立;石材业;习近平总书记;', '全国工商联金银珠宝业商会会长、深圳市霖峰集团董事长王秀娥： 立报国之志 促商会发展 聆听习近平总书记“七一”重要讲话，让我仿佛又看到了那些为中华民族的复兴梦想而奋斗的革命先驱，看到了红军二万五千里长征，爬雪山、过草地的不屈身影，仿佛又听到了铁索桥“吱吱', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.38311/n.cnki.nzhgs.2021.003170', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2486, '报纸', '最是那一抹耀眼“遵义红”', '向婧', '中国新闻出版广电报', '中国新闻出版广电报', '遵义会议精神;长征精神;红色基因;', '红色，是遵义的底色，也是历史留给遵义的最耀眼的颜色。在这片热土上生活的每一个人，无不被红色文化浸润和感召，也在用不同的方式传承红色基因，讲好遵义故事。红色故事历久弥新。 刘霜是遵义会议纪念馆讲解员队伍中的一员，也是一名光荣的共产党员。每天，她都会为来自', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.002647', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2487, '报纸', '红色初心铸铁魂', '杨睿', '海南省海口市纪委监委;', '中国纪检监察报', '纪检监察干部;遵义会议;', '在我出生的遵义市，红花岗区子尹路96号，有一座灰白相间、中西合璧的砖木结构二层小楼，小楼的东侧有一棵高10余米的大槐树。这座别致的小楼曾是黔军军阀柏辉章的私宅，当地人称之为“柏公馆”。这一座楼、一棵树，风雨同舟80余载，见证了中国共产党的重要历史时刻——遵义会', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003219', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2488, '报纸', '“转折之城”再闯新路', '孔德琳; 江伟; 范超', '中国电力报', '中国电力报', '遵义供电局;国家能源局;遵义会议精神;电网建设;走向胜利;绿水青山;', '编者按 80多年前长征路上,中国共产党领导的中央红军在贵州转战4个多月,实现了中国革命的伟大转折。伟大转折映照出伟大精神,随着国家西部大开发战略实施,贵州实现了从一穷二白到全面小康、从发展滞后到赶超跨越的历史巨变。即日起,本报推出“奋斗百年路启航新征程一一沿着能源', '2021-07-05 08:00:00', 'https://link.cnki.net/doi/10.28061/n.cnki.ncdlb.2021.001239', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2489, '报纸', '走好新时代的阅读“长征路”', '郝天韵', '中国新闻出版广电报', '中国新闻出版广电报', '书香校园;农家书屋;区图书馆;全民阅读活动;红色阅读;读书会;主题阅读;遵义市;长征路;', '“历史照亮未来，征程未有穷期。”在中国共产党百年华诞的关键节点上，尤其需要带着初心和使命回望过往的奋斗路，眺望前方的奋进路。6月21日—23日，紧随中宣部出版局指导的“追寻光辉足迹”主题阅读活动脚步，“书香中国万里行”大型系列采访活动来到了本年度红色阅读之旅的', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.002483', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2490, '报纸', '传播红色文化 赓续红色精神', '郝天韵', '中国新闻出版广电报', '中国新闻出版广电报', '新华书店;遵义市;红色文化;农家书屋;红色精神;', '主 题：对话发行人——弘扬红色文化 擦亮红色品牌 嘉 宾：遵义市新华书店副总经理 张云平 遵义市新华书店1935分店经理 詹慧晶 主 持：《中国新闻出版广电报》记者 郝天韵 1935年1月，中共中央政治局在遵义召开扩大会议。遵义会议在中国革命的危急关头挽救了中国', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.002491', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2491, '报纸', '贵州遵义会议会址 “薪火代代相传”', '李灵娜', '中国纪检监察报', '中国纪检监察报', '纪检监察干部;遵义会议会址;基层党组织;', '贵州省遵义市红花岗区子尹路96号，一栋砖木结构、中西合璧的两层楼房临街而立。80多年前，具有伟大转折意义的遵义会议在此召开。7月1日，300多名党员干部来到遵义会议会址前的广场上，集中收看了庆祝中国共产党成立100周年大会直播。 “大家在特殊的时间、特殊的地方，用', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003171', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2493, '报纸', '古柏：“信者不惧”回应入党', '黄慕泽', '人民法院报', '人民法院报', '毛泽东;苏维埃政府;裁判部;总前委;寻乌调查;临时最高法庭;司法审判;中华苏维埃共和国;', '“信者不惧。” 19岁的古柏在加入中国共产党时面对家人的反对，坚定地说出了这句话。 在中华苏维埃共和国最高法院旧址，一块展板吸引了记者的注意，牺牲时年仅29岁的古柏烈士，生平传记并不丰富，却足以映现其短暂却光辉的一生。 古柏（1906—1935），号劲生，江西', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003063', '遵义会议_screened,红四军_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (2495, '报纸', '铁心向党军魂永固', '黄超; 李兵正; 赖瑜鸿', '解放军报', '解放军报', '党对军队绝对领导;全军官兵;政治规矩;军委主席;领导权;听党指挥;负责制;党的政治建设;习近平;指挥权;', '坚决听党指挥是强军之魂，必须毫不动摇坚持党对军队的绝对领导，任何时候任何情况下都坚决听党的话、跟党走。 ——习近平 2021年6月，3名航天员乘神舟十二号载人飞船“九霄逐梦再问天”，成为进驻天和核心舱的首批航天员。与习主席通话时，3名航天员身后，那面鲜红的党', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004158', '遵义会议_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (2497, '报纸', '敢教日月换新天', '兰琳宗', '中国纪检监察报', '中国纪检监察报', '中国共产党;党中央;农村包围城市;武装夺取政权;马克思主义中国化;武装斗争;毛泽东思想;瓦窑堡会议;政治局;', '千秋伟业，百年风华。中国共产党迎来百年华诞。 站在庆祝我们党百年华诞的重大时刻，站在“两个一百年”奋斗目标历史交汇的关键节点，站在开启全面建设社会主义现代化国家新征程的历史关头，回望波澜壮阔、震撼世界的百年征程，中国共产党始终紧紧依靠人民，跨过一道又一', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003140', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2499, '报纸', '彪炳史册的人间奇迹', '冯春梅; 李昌禹', '人民日报', '人民日报', '中国共产党历史;历史转折;邓小平同志;中华民族;红色政权;人间奇迹;', '6月18日，“不忘初心、牢记使命”中国共产党历史展览开幕式在当天开馆的中国共产党历史展览馆举行。 展览以“不忘初心、牢记使命”为主题，精心设计了“建立中国共产党 夺取新民主主义革命伟大胜利”“成立中华人民共和国 进行社会主义革命和建设”“实行改革开放 开创和', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006792', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2500, '报纸', '百年精神 磅礴力量', '', '中国新闻出版广电报', '中国新闻出版广电报', '精神谱系;', '习近平总书记在党史学习教育动员大会上指出：“在一百年的非凡奋斗历程中，一代又一代中国共产党人顽强拼搏、不懈奋斗，涌现了一大批视死如归的革命烈士、一大批顽强奋斗的英雄人物、一大批忘我奉献的先进模范，形成了井冈山精神、长征精神、遵义会议精神、延安精神、西柏坡', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.002499', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2502, '报纸', '砥柱人间是此峰', '赵承; 霍小光; 张晓松; 赵超; 刘铮; 朱基钗; 杨依军; 姜琳; 黄玥; 于文静', '人民日报', '人民日报', '习近平总书记;中华民族;民族复兴;攻坚战;中国共产党历史;人类命运共同体;', '“我们的责任，就是要团结带领全党全国各族人民，接过历史的接力棒，继续为实现中华民族伟大复兴而努力奋斗，使中华民族更加坚强有力地自立于世界民族之林，为人类作出新的更大的贡献。” ——习近平 “我们对时间的理解，是以百年、千年为计。” 中国共产党即将迎', '2021-06-30 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006768', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2503, '报纸', '贵州：走好新时代长征路', '冷秋; 徐莺; 汪建华', '金融时报', '金融时报', '贵州省;湄潭县;赤水河;贵安新区;赤水市;长征路;赤天化;产业集群;林纸一体化项目;竹产业;', '86年前，黔北重镇遵义，一场特殊的会议在这里召开，这就是中国共产党历史上生死攸关的重大转折点——遵义会议。遵义会议写下红军长征途中浓墨重彩的一笔。 遵义，乃至整个贵州，都和红色精神紧密相连。贵州是红军长征历时最长、活动范围最广、发生重大事件最多的省份之一', '2021-06-29 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.003207', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2504, '报纸', '用心用情用力做好红色资源保护和利用工作', '闫晶晶; 宁中平', '检察日报', '检察日报', '公益诉讼;退役军人;事务部;军事检察院;红色资源;检察职能;检察长;纪念设施;', '6月25日，中共中央政治局就用好红色资源、赓续红色血脉进行第三十一次集体学习。习近平总书记在主持学习时强调，红色资源是我们党艰辛而辉煌奋斗历程的见证，是最宝贵的精神财富。要加强红色资源保护和利用，尊重历史事实，准确评价历史，正确学史用史。 革命文物、英烈纪', '2021-06-28 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.003244', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2507, '报纸', '神圣的最后', '田华; 石健; 冉承莉; 张学为', '团结报', '团结报', '茨岩塘;中国工农红军长征;红军学校;湘鄂川黔省委;里耶古城;龙山县;', '一 1935年12月8日，中国工农红军第六军团十八师完成牵制敌军，掩护红二、六军团长征的任务，在望乡台集结突围，开始长征，成为最后参加长征的队伍，茨岩塘也定格为“中国工农红军长征最后出发地”。 望乡台，位于龙山县茨岩塘镇，是个一夫当关万夫莫开的逼仄峡谷。', '2021-06-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID7aZRnPtmiUSoMRsjhL8Zmhs3HkzZFLeS7DBSrf-cyYPKUv2ZnXmU8koKhtivC-pv9tgrTS5PZWHcOvAipbW_5Z9T7ujzbwfsT6B-gJkKpHXAOdaab9wY83O-DmSZumcGNZQU7xDmFjA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2508, '报纸', '运动员哈斯木·玉米西：骑行万里，向党和祖国告白', '孙文振', '中国民族报', '中国民族报', '运动员;', '100天，从江西瑞金出发，沿着长征路线骑行两万五千里，柯尔克孜族运动员哈斯木·玉米西以这样的方式，向党和祖国深情告白，庆祝中国共产党成立100周年。 “我是牧区长大的孩子，能逐步成长为一名运动员、教练，这一切都离不开党的培养。”55岁的哈斯木·玉米西，出生在新', '2021-06-25 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.000648', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2510, '报纸', '吃水不忘挖井人', '张妹芝', '全国政协;河北省人大常委会;民进河北省委;', '人民政协报', '革命老区;黔西南州;民进中央;共产党人;毕节市;', '参加“学习百年党史 增进四个认同”专题视察，从长征出发地于都，到中国共产党历史上的重大转折地遵义，其间分别走进赣州、瑞金，我们带着崇敬的心情、带着深深的思索，瞻仰了息烽集中营旧址、娄山关战斗遗址、遵义会议会址、苟坝会议会址，考察花茂村等地。我们向革命烈士墓', '2021-06-19 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005013', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2512, '报纸', '赓续红色基因砥砺奋进 践行初心使命担当作为', '', '中国建设报', '中国建设报', '红色基因;红色资源;精神谱系;习近平总书记;', '追寻红色记忆,汲取奋进力量。近日,住房和城乡建设部召开直属机关学习贯彻习近平总书记《用好红色资源,传承好红色基因,把红色江山世世代代传下去》重要文章交流会。本报选登部分参会代表发言,与读者共同深刻领会习近平总书记重要文章的丰富内涵、重大意义和实践要求,交流运用', '2021-06-09 08:00:00', 'https://link.cnki.net/doi/10.38299/n.cnki.nzgjs.2021.001453', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2515, '报纸', '闯新路开新局抢新机出新绩 开创百姓富生态美的多彩贵州新未来', '谌贻琴', '贵州省委;', '人民日报', '多彩贵州;生态美;习近平总书记;全面从严治党;生态持续;', '当年长征时，红军在贵州活动时间最长、活动范围最广，为我们留下宝贵精神财富。遵义会议确立了毛泽东同志在党中央和红军的领导地位，开始确立了以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位，开始形成以毛泽东同志为核心的党的第一代中央领导集体，开启了', '2021-05-30 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.005631', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2516, '报纸', '把党史学习教育成果转化为公安工作成效', '郭瑞民', '公安厅;', '人民公安报', '党史学习;习近平总书记;成果转化;', '在党史学习教育动员大会上，习近平总书记深刻阐明了开展党史学习教育的重大意义，勉励全党学史明理、学史增信、学史崇德、学史力行，做到学党史、悟思想、办实事、开新局。贵州省公安机关深入领会开展党史学习教育的重大意义、工作要求，以习近平总书记在贵州考察调研时的重', '2021-05-30 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.002982', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2517, '报纸', '在党史学习教育中提高领导水平', '戴焰军', '中央党校(国家行政学院)习近平新时代中国特色社会主义思想研究中心;', '解放军报', '党史学习;中国共产党;党中央;马克思主义;习近平;', '历史是最好的教科书。当前我们正处在“两个一百年”奋斗目标的历史交汇期，为实现新的目标，重温党的百年历史，对于提高干部的领导水平有着重要意义。 形势的复杂性要求我们通过学习党史提高领导水平。中华民族伟大复兴战略全局和世界百年未有之大变局，对我们党的领导水', '2021-05-21 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.003239', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2518, '报纸', '走好新长征路需要精神力量', '彭训文', '人民日报海外版', '人民日报海外版', '革命理想;', '“革命理想高于天，理想信念之火一经点燃就会产生巨大的精神力量。”习近平总书记近日在广西考察时，在红军长征湘江战役纪念园这样强调精神力量的作用。 长征是一次理想信念的伟大远征。“风雨浸衣骨更硬，野菜充饥志越坚；官兵一致同甘苦，革命理想高于天。”长征路上，', '2021-04-30 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.001289', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2519, '报纸', '鼓起奋进新征程的精气神', '', '中国组织人事报', '中国组织人事报', '精气神;光荣传统;优良作风;', '历史中蕴含着走向未来的智慧。 “发扬红色传统、传承红色基因，赓续共产党人精神血脉”“鼓起迈进新征程、奋进新时代的精气神”。习近平总书记深刻指出，回顾历史不是为了从成功中寻求慰藉，更不是为了躺在功劳簿上、为回避今天面临的困难和问题寻找借口，而是为了总结历', '2021-04-28 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.001471', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2520, '报纸', '始终保持昂扬斗志', '李家运', '贵州省纪委监委派驻第十三纪检监察组;', '中国纪检监察报', '黎平会议;党史学习;', '1934年12月18日，中央红军长征以来的第一次中央政治局会议在黎平召开，即黎平会议。这次会议否定了“到湘西去”的战略方针，采纳了毛泽东到黔西北建立以遵义为中心的川黔边区新根据地的主张。会议实事求是地解决了军事路线问题，坚定了理想信念。 近日，我们在开展党史学', '2021-04-27 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.001956', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2521, '报纸', '用活红色资源 走好新长征路', '汪海波', '贵州省遵义市委;组织部;', '中国组织人事报', '党史学习;基层党组织;习近平总书记;红色资源;', '引导党员干部在思想上弄清楚我是谁、为了谁、依靠谁，理解透中国共产党为什么能、马克思主义为什么行、中国特色社会主义为什么好，增强用党的创新理论武装头脑的政治自觉 充分挖掘革命文物和历史资料，赋予文物史料鲜活内涵，做到见人、见物、见景、见精神，让革命文物“', '2021-04-26 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.001448', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2522, '报纸', '进一步增强党的团结和集中统一', '', '人民日报', '人民日报', '党的团结;党中央;集中统一;习近平总书记;', '党的历史、新中国发展的历史都告诉我们：要治理好我们这个大党、治理好我们这个大国，保证党的团结和集中统一至关重要，维护党中央权威至关重要。 习近平总书记在党史学习教育动员大会上强调，旗帜鲜明讲政治、保证党的团结和集中统一是党的生命，也是我们党能成为百年大', '2021-04-15 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.003811', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2523, '报纸', '进一步发扬革命精神', '', '人民日报', '人民日报', '革命精神;精神谱系;党史学习;共产党人;习近平总书记;', '人无精神则不立，国无精神则不强。革命精神是党和国家的宝贵财富。 习近平总书记在党史学习教育动员大会上强调，在一百年的非凡奋斗历程中，一代又一代中国共产党人顽强拼搏、不懈奋斗，涌现了一大批视死如归的革命烈士、一大批顽强奋斗的英雄人物、一大批忘我奉献的先进', '2021-04-14 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.003862', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2524, '报纸', '学好百年党史 走好新长征路', '刘奇', '江西省委;', '学习时报', '党中央;习近平总书记;全面从严治党;政治本色;', '历史是最好的教科书，常学常新；党史是最好的营养剂，催人奋进。习近平总书记在党史学习教育动员大会上强调：“在庆祝我们党百年华诞的重大时刻，在‘两个一百年’奋斗目标历史交汇的关键节点，在全党集中开展党史学习教育，正当其时，十分必要”。江西是一片充满红色记忆的', '2021-04-07 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.000563', '遵义会议_screened,叶坪_screened,方志敏_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2525, '报纸', '改变历史的三天', '吕慎', '光明日报', '光明日报', '遵义会议会址;遵义会议精神;红军战士;王稼祥;', '从建党到开国，中国共产党走了28年，时空坐标的中点落在1935年的遵义。一场为期三天的会议，改变了中国历史。 从中国共产党成立到遵义会议召开是14年，从遵义会议召开再到新中国成立也是14年。中国革命前14年苦苦探索，几经起落；后14年昂首阔步，走向胜利。 历史何以', '2021-02-01 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.000584', '遵义会议_screened,血战湘江_screened');
INSERT INTO `ds_article` VALUES (2526, '报纸', '不能忘记走过的路', '欧阳淞', '中共中央党史研究室;中国中共党史学会;', '团结报', '湘鄂川黔革命根据地;红二方面军;中央红军;中国工农红军;红六军团;红军长征;湘西州;长征精神;', '编者按： 湘鄂川黔革命根据地是继中央革命根据地之后长江南岸最大的一块红色根据地，被誉为“中国南部苏维埃运动发展中最重要的柱石”。湘西作为湘鄂川黔革命根据地的中心腹地，为根据地创建发展和红二方面军的孕育壮大作出了重大贡献和牺牲，在我党的历史上占有重要的地位', '2021-01-20 08:00:00', 'https://link.cnki.net/doi/10.28805/n.cnki.ntuje.2021.000179', '遵义会议_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (2527, '报纸', '“高峡出平湖”华彩乐章的前奏', '王国卿', '第十一、十二届全国政协;', '人民政协报', '三峡工程建设;国务院;三峡大坝;长江三峡工程;可行性研究报告;全国人大;开发性移民;华彩乐章;', '每当我听到中央电视台的“水电名城——宜昌”的广告词时，都会情不自禁地想起，上世纪八九十年代，围绕着三峡水利枢纽工程（以下简称三峡工程）建设的上马问题，全国政协曾先后三次考察、视察三峡工程的情景。 三峡工程是一个跨世纪的宏伟工程，凝聚着几代人的梦想。源于', '2019-10-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIANBDOuyQPYuuzERxiUoS9P68SESmxypyHG0jSSrcNNH_ekiWy4STrjL-2HN08nhzvPJePmmX4euRe6bbBFBj4AQRINznR4nj4sq1XeSXegE_yPRssAUgRsFEpa64khxSlLF36Rckm6ZQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2529, '报纸', '在纪念刘少奇同志诞辰120周年座谈会上的发言', '', '人民日报', '人民日报', '刘少奇;革命家;人民代表大会制度;社会主义建设;党中央;人民代表会议;毛泽东军事思想;座谈会;', '中央党史和文献研究院院长冷溶： 今天，我们怀着十分崇敬的心情，参加中央召开的座谈会，纪念刘少奇同志诞辰120周年。 刘少奇同志是以毛泽东同志为核心的党的第一代中央领导集体的重要成员，是深受全党全军全国各族人民爱戴的老一辈无产阶级革命家。这里，我就他的革', '2018-11-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA1Yn66fR7-4JmicJINyvE62Dn3ZBprDqJGSh4nLmrjQwqM2XDHOnvt4gttWs2Of7Bg1VnTXAQRcmEoCCljftS3G2OjTWpUTSi3aNtvI1InPV3Mc92Jpf247oPs57znz_ejZGqzkHCv5w==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2530, '报纸', '以培养高素质专业化干部队伍为旨归', '龚克', '学习时报', '学习时报', '学习时报;大讲堂;习近平总书记;扶贫开发战略;干部教育培训;党的十九大精神;专业化能力;党性教育;', '学习时报：李部长：您好!学习重大理论，必须提高政治站位，增强干部培训有效性必须创新方式方法。贵州在学习宣传贯彻落实习近平新时代中国特色社会主义思想和党的十九大精神方面采取了哪些举措？ 李邑飞：干部教育培训因党而生、随党而兴、为党而强，政治性是第一属性，', '2018-10-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICDHWMYeQLAyscFDviL5PN9sQj7zz--OLLgDeS-nETLeqlGEoIFVzY9HI0LaGsXOOcOREfy78iDNTno1maztU-c-I3XwFVZYyoMU_x1c4138z8TNOfQwAghE9Eoe-U7fGE75PyBCfXO6Q==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2532, '报纸', '当好红军传人 守护遵义平安', '李堂', '贵州省遵义市红花岗区委;政法委;公安分局;', '人民公安报', '党建引领;红花岗;', '长期以来，贵州省遵义市公安局红花岗分局始终把伟大的长征精神和遵义会议精神作为建警之魂，努力将忠诚烙印在民警灵魂深处，用实际行动传承红色基因。 坚持红色传承，牢记初心使命。近年来，我们始终坚持讲好名城遵义的故事，打造红色教育平台，组织开展“红色课堂”集中', '2018-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBrYNePbLiT28wk16_p5tyaMMMRH6EUTEqEVB6DRHB463ucjnbhbZfgw3CTNHCjy6zWp8ghD_JbuTA5Q6vvrxZtpCeXV1-o9qDEnElSTEy4f_CZi4MUAiGDE9PKVsnqGbcOukbxjBm_4Q==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2534, '报纸', '“醉美”遵义', '韦夏怡', '经济参考报', '经济参考报', '总政治部;中央革命军事委员会;没收征发委员会;中华苏维埃国家银行;娄山关;军委副主席;革命委员会;特色菜;', '作为贵州第二大城市的遵义，地处西南出海要道，全域纳入长江经济带，古称播州，名始于唐贞观十六年，取义《尚书》“无偏无颇，遵王之义”。遵义旅游区是大西南旅游的重要组成部分，也是长江三峡国际旅游热点中的生态旅游的理想王国。 红色的遵义，经典磅礴。1935年，红军', '2017-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICfhgmm6vFDFcQT7uXSjTNWaCcCbFFtWgI-aM959mKuzTcIxL8xlgV3O-1JHPR5huAK1daYoHwT5SkBSE5_MoXlkDSeutaG5EFl2r8eCtNu-1cuId8_ZOjCHf1tVwYkxWiLDWoIJcfgNw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (2536, '报纸', '精彩演绎人民军队九十年辉煌历史', '刘小兵; 章文', '光明日报', '光明日报', '人民军队;九十年;政治工作部;', '8月1日，庆祝中国人民解放军建军90周年文艺晚会《在党的旗帜下》在央视播出。晚会深邃凝重的思想格调、恢宏壮美的史诗品格、创新出彩的舞台呈现，赢得广大观众的一致好评。这台晚会是如何在100分钟里精彩演绎人民军队90年历史的？有何突出的亮点和特色？创排过程中有哪些感人', '2017-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDSTafs3gqA61e4vODNxr41nWWKQg7Xu6K9PxlGzRsIMbvbirVGkhpb7A4vuJ9qCEpJzKCXdA47CRRBDC-BYvjxAgtwodCunvJIL7rKV2TlTiD9nFEMAIz7XG4OT4n0seM99DRHYE6mqQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2538, '报纸', '论中国共产党的政党自信', '董云虎', '上海市委;宣传部;', '学习时报', '社会主义;政党自信;中国共产党;', '中国共产党是中国特色社会主义事业的领导核心。坚定中国特色社会主义道路自信、理论自信、制度自信和文化自信，关键是要坚定中国共产党的政党自信。习近平总书记指出，“当今世界，要说哪个政党、哪个国家、哪个民族能够自信的话，那中国共产党、中华人民共和国、中华民族是', '2017-06-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAKHJdGlTRBWBDiKls7e8U0L9V7gGiaLB4yjms1eMTsmD1yXtMIqon1NRIj2REI77IjaVGGyzypRsp4344VbhIF3eJR26NOZY7se0qstw2KUa9t4OrbTuIwvt0wDt_W0qEIZVq823drpw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2541, '报纸', '在新长征路上交出优异答卷', '岳亮', '陕西省咸阳市委;', '学习时报', '长征路上;长征精神;长征胜利;战略转移;', '习近平总书记在纪念红军长征胜利80周年大会上发表的重要讲话，用4个“伟大远征”深情回望80年前那一震古烁今的革命壮举，全面总结长征胜利的8条历史意义和长征精神的5点深刻内涵，提出6方面要求，号召全党弘扬伟大长征精神，在新的长征路上续写新篇章、创造新辉煌。反复研读', '2016-11-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAeJ6VveAYnqOp5l0bB62vnDqH3eJUgLMUJyLdwYq4V_2DDrM23qITVZhxofGdKGzrDT_8cxjy1gKiCL4DK_KwoA8iXkqdkYzCX4zo2p29E9JiEXyysyG-ztcDB-NSgiYjvqym7Wb3J4A==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2543, '报纸', '仰望永恒的丰碑', '肖裕声', '军事科学院世界军事研究部;', '光明日报', '红军长征;湘江战役;临时党支部;中央红军;国民党军;', '“一送红军下南山，秋风细雨扑面寒，树树梧桐叶落完，红军几时再回山。二送红军大路旁，红漆桌子路边放，桌上摆着送行酒，祝愿红军打胜仗……”一首婉转动听的江西民歌《十送红军》，拉开了纪念长征80周年文艺晚会的序幕，一幕幕震撼人心的恢宏场景把观众带入中国工农红军的', '2016-10-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAUK1U-YSa0yKMk98M9UbNavU-Tn-M6Q-koib8i3xrRQuWwpqESzZdCGicjXi2YjDMbcCXeASZqz21sGIB28U0f83jhl1g8wJ2r3KecwNPmsw8cjRpJAOpTUYGAT6gyTJ7qwOngJVi6Yg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2545, '报纸', '长征，不熄的精神火炬', '', '中国民族报', '中国民族报', '攻坚克难;', '这是一个伟大的壮举。参与其中的人，迄今健在的虽已不多，但他们的足迹仍然被人们追寻，他们的故事依然为人们所津津乐道。 这是一部不朽的史诗。它的烟云虽已消失在历史的天空中，但它的名字却被人们铭记，它的精神激励着一代又一代的后来者。 这就是长征。2016年，', '2016-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAgcOARqLBLq3MbE5KPJPsvJVvRyTS-QtTR8UNW1CT9qMLUWCYyoIr1K-BAw7gX1nSmgsRLN6c2gr7QuqS1GZQ2DdTgUWMmx4m27_zDZCPJ8uxUCO2FOO_95VXfnCPxnOGR3_B7B6HceQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2547, '报纸', '走好我们这一代人的长征路', '', '人民日报', '人民日报', '长征精神;长征路上;', '岁月的奔涌从不停歇，奋斗的征程永远向前。 80年前，在生死存亡的危急关头，中国共产党领导工农红军历经艰苦卓绝的两万五千里长征，在陕甘宁地区胜利会师，把濒临绝境的中国革命引向坦途。岁月峥嵘，历史常青。今天，我们纪念中国工农红军长征胜利80周年，缅怀所有为民族', '2016-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC60UXr60tDuXi6K24KgCetF3Jg1E6wCvRHTl_fZWHHGxZc4f81DsdwKlyBND--vveH7lZSUPHh_bb6EG_7_4IouGzMPJMWsUItlh1vgCEripYOSMJSgwcFYtRmg_RkuwYTIqW13N0pOg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2548, '报纸', '长征——需要回答的六个疑问', '公方彬', '国防大学;', '中国青年报', '毛泽东;中国工农红军;红四方面军;', '有人形容，长征是个谜。正是谜，而让人倾倒。 1937年10月，斯诺的《红星照耀中国》在英国出版，连续5次印刷。次年在美国上市，迅速登上销售榜榜首。美国总统罗斯福读过后，数次会见斯诺，认为红军长征是一次“震惊世界的行军”。他们预言：“总有一天会有人写出这一惊心', '2016-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBGPVbYeeoCKitGPknMNtnQ26aMMANshYNemS0F-e1qA4yKI-LG4wAYsV69RFJQm5AkDW3CDJQrRMWVV3BqlTXSdCST5GRn7W1ebtCSoOX8mSSKXTzEsKFEKEa1-H7kxV-rk_-aCBtS6A==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2551, '报纸', '肩膀上应长着自己的脑袋', '', '解放军报', '解放军报', '教条主义;马克思主义;', '长征的胜利，是光明对黑暗的胜利，是革命对反革命的胜利，也是独立自主、实事求是精神对本本主义、教条主义的胜利。 长征前，面对国民党反动派的大规模“围剿”，由于当时党内教条主义的错误领导，军事上实行“左倾”冒险主义，致使中国革命遭受严重挫折，党和红军陷入无', '2016-10-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID_tYwPsb6Jl5izi1xBMf_TQbN1hHLO87WpjHj8reQ2BaKAFFJ192UOzkQs-O7YmG3tVfm8QiZyvsYJb_exYSDc3oFFhboED2clVad-0PcgBwkGS8YpdHJnsrAeXj4KjCwg52Vzf3yFUg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2552, '报纸', '不忘初心，弘扬伟大长征精神', '王昊魁; 李薇', '光明日报', '光明日报', '长征精神;“七一”重要讲话;长征胜利;习近平总书记;', '习近平总书记强调：“我们要铭记红军丰功伟绩，弘扬伟大长征精神。” 今年是中国工农红军长征胜利80周年。如何理解伟大的长征精神？长征胜利带给我们哪些启示？如何汲取长征精神做到“不忘初心、继续前进”？围绕这些问题，记者专访了党史专家、中央党校教务部主任谢春涛', '2016-10-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB06Zz5OCsIxmoTdQL-p2HstSTyCq_lUbG8_77u8Zm3hRDu2kE5rh38E0bT2nzGXnhodUWEiPLLwnur8ezTRMyxur7-td6xurC_uEf5cbvPiMHoNXPyJa905ebWHpo5Y_RqUHOUdaN3Dw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (2554, '报纸', '长征：展现自我纠错的强大力量', '贝骁; 徐晶晶', '中国国防报', '中国国防报', '纠错能力;展现自我;', '任何一个旺盛的生命、任何一个强大的体系，之所以旺盛、强大，一个重要原因是其具有强大的自我纠错能力，能够不断自我完善。 长征以第五次反“围剿”的失败开始，以三军大会师的胜利结束，这一从失败中奋起、坚韧不拔走向胜利的过程给我们以怎样的启迪？近日，本报记者专', '2016-09-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBpMZZW3kX4s2wiTkZneVUtvUMQUoiUw_FJULQKhCCTkbDaCdU6Ec4tMwDH1RMOtNONkQOUXEUdwQT18-XA4UqJ0NiggTHWdKPu6UjTUtAfBC_yDILTB-B8uNmJWegNo-q0a4WTFq7nAA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2558, '报纸', '不忘初心，继续前进', '吴娜', '光明日报', '光明日报', '中国共产党成立;共产党;习近平总书记;中共党史研究室;口述史料;中央党校;执政能力;', '编者按 7月2日，在纪念中国共产党成立95周年大会召开的第二天，一场以此为主题的读书会在北京西华书房举行。与会嘉宾围绕习近平总书记在纪念中国共产党成立95周年大会上的讲话，结合最新出版的两本新书：《不忘初心：中国共产党为什么能永葆朝气》（中国人民大学出版社）', '2016-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAGWTukm7QaWDn_G2-B1IkN-0HrBlpTQvqfxMj9DLbmNf0NhFeDIFjqLHEqFXxWsL7nqVcEcfQhyi0sXBBSKlZtj81N_i1cg-49xMXZkXtpqzKOuGUDYIBmzdDm7I-JPJMb2h8IOBBtwQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2559, '报纸', '中国革命在此实现伟大转折', '吴远威; 蔡伟', '中国纪检监察报', '中国纪检监察报', '伟大转折;', '在贵州省遵义市老城子尹路中段，静谧地坐落着一栋两层高的砖木结构小楼，中西合璧，古色古香。这就是遵义会议会址——中国革命的伟大转折地。 6月的黔北，阳光明媚、生意盎然。遵义会议会址在阳光映照下，显得格外熠熠生辉。记者登上二楼看到，一间仅有27平方米的小客厅', '2016-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDN0GxMZlWP_laZ1eKGo76UpbN1CifPvaKjy2rO23RyZ2QlGDYaH15EGsxqEJN5pJ7k0PeMyv_A8NgEQjkbYshrKpQKCsLsRJCi6iMVWrmgDCgb09trYsbSsBWEjvSfcC3kelFHhVNsMg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2560, '报纸', '弘扬长征精神 推动主旋律作品创作', '', '人民日报', '人民日报', '重大革命历史题材;文艺创作;长征精神;红军长征;作品创作;', '今年是中国工农红军长征胜利80周年。近日，中国文艺评论家协会、中国文联文艺评论中心、江西省文联在红军长征出发地江西赣州共同举办纪念长征胜利80周年暨长征题材文艺创作研讨会。 与会者围绕长征题材文学创作、影视创作、主题性美术创作、革命戏剧，长征精神研究的文化', '2016-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA8ZqQfN7UFWsdhng5_rNJnFL3HPgOx6MOcxNXJY05a3yRSMPGww0N1ouNwb82PgR_56Q-qTKK3XeU7kNv-MByJ8ub88k7cKAqidd_-draCc25JILcsHPLhLuFKfWk0i9WQB9_GE5_oYg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (2561, '报纸', '让红色资源成为发展支撑', '张广智', '中共贵州省委;宣传部;', '人民日报', '红色资源;红色基因;红色文化资源;', '我们党领导人民在长期革命斗争和发展实践中形成的红色文化，是中华民族的宝贵精神财富。习近平同志在贵州调研时强调，要充分利用红色资源，开展党的优良传统教育和理想信念教育，激励广大党员干部结合新的时代特点发扬革命传统、培育和践行社会主义核心价值观，更好团结带领', '2015-10-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA0uf1m9phdV1WNAshW2fWw82FFJzmUuWBWRfrcmTkBTpVU_dtsPJWsyYtCQGveXvJjtDsQRDEGji6ibIHIPdXW4qomtEC_SGJ1yzR4FTT0xLaICxK3bHlCMEt3JHQMfREkXu_wO_XWew==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2562, '报纸', '筑梦中国', '', '人民日报', '人民日报', '马克思主义;国民党反动派;中国共产党;', '第二集 中流击水 【解说】 在北京中山公园南门不远处，静静伫立着这座保卫和平坊。它的前身叫克林德碑。克林德是德国驻华公使，在八国联军侵华时多次屠杀和绑架中国公民，清政府却要为他的死谢罪道歉，建立牌坊。1918年，第一次世界大战结束，兴奋的人们推倒克林', '2015-07-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICikPGdcAkpQhlwA_n2l5Xd9T3qnQo9yast_l1wC-Cm-EIYgaYVroTdJVdd5PLj3DXIeErTQzzRxJqvwsCZyWwf3mjHp4UpxAdFosbAZQROXN5pvVKfX3bvjVq1J5pYgsv8Ik4gcviaEw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2563, '报纸', '在纪念陈云同志诞辰110周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '陈云同志;马克思主义;党的十一届三中全会;共产主义;党的纪律;座谈会;', '同志们，朋友们： 今天，我们怀着十分崇敬的心情在这里隆重集会，纪念陈云同志诞辰110周年，缅怀他为党、为国家、为人民建立的不朽功勋，追思他为党和人民事业不懈奋斗的光辉一生，激励全党全国各族人民继承和发扬老一辈革命家的崇高风范，坚定不移把中国特色社会主义事', '2015-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID54pgOOL7-QZDyAzEaHlp59q8-M2KR9ssmt4B70M90s_IVTVfmdlS6pslkWYi3RY_opO5XpZ3ssXWuvfrn0Md4j4VP2rov1BQospWNMFOCPMnVT4WmXRuDVN1th7-HMwR1HEq0e64HcQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2564, '报纸', '遵义会议永放光辉', '王晓光', '贵州省委;遵义市委;', '人民日报', '共产党;马克思列宁主义;共产主义;马克思主义;', '遵义这座城市，因遵义会议而举世瞩目； 遵义这座城市，因遵义会议而彪炳史册。 80年前，在中华民族面临深重危机的危难关头，在中国共产党面临生死考验的危急时刻，中国共产党领导工农红军开始了史无前例的二万五千里长征，遵义会议成为这万里征程中生死攸关的伟大', '2015-01-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAFgDAzkrNLUsJeUPJo1WQ8LtRKiK1uKPhjRQjdGVnkcPBWeqOfG1creFCKK5wX9IOQykK2tv6j8MRHeqncaNzfhVfxIFEFJC_X_D_pTY7ZsFcRwF18vfx0_tMrA4U-zH3NZTik-MNzRQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2565, '报纸', '让遵义会议之光照耀圆梦征程', '王晓光', '中共贵州省委;遵义市委;', '光明日报', '共产党人;战略转移;政治定力;', '1934年10月，随着第五次反“围剿”的失败，中央红军被迫实施战略转移。1935年1月15日—17日，中共中央在遵义召开政治局扩大会议，对第五次反“围剿”的失败和转移途中的失利进行反思和总结，为中国革命寻找新的出路。会议在军事上肯定了毛泽东的正确主张，纠正了“左”倾军事', '2015-01-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBqnilcmDsnr1U9TAEvILD6opt58qBAjQChW9e1YWtM-6iPTT5YgrQFFPjQsBdX3SmM8a3hZSSChcHX8spfHRZsMeGYUfgpo-GPwKDyYhbwQeb1fcVAUiBRfHy1Tm2FSYtzCoxGcfNRmA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2566, '报纸', '铁血脊梁铸军魂 继往开来树丰碑', '', '光明日报', '光明日报', '松毛岭保卫战;中央红军;温坊战斗;东方军入闽作战;红九军团;', '编者按 1934年9月，红军长征前第五次反“围剿”的最后一役松毛岭阻击战，在位于福建省连城县和长汀县交界处的松毛岭打响。红九军团、红二十四师、工人师和地方赤卫队约3万余人面对7万余装备精良的敌人，激战了整整7个昼夜，惨烈程度不亚于湘江战役。松毛岭阻击战为中共', '2014-12-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID1skUC7kTlPDJsKV-EZOLYNKXgRnaPBjvYtF6YeCyq2yoLWWHfmRyEl9tjBexRaDLQA-v5b8ofLYdPY4_4b33EmV8jDP349ZVm5HZ25O1PavoHLPgfsXRmBwOxxTwJIxOIjRLR70HCcQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (2568, '报纸', '造型大师王希钟:演员变“领袖”，靠他一支笔', '王学良 ; 侯思宇; 于琦', '新华每日电讯', '新华每日电讯', '王希钟;丁荫楠;周恩来;王铁成;一支笔;化装师;', '给“领袖”化装,是王希钟的拿手好戏。但这并不意味着他只擅长这方面。如今几乎每年都会重播的经典电视连续剧《西游记》中各路神佛鬼怪的造型,都是出自王希钟之手。在《西游记》中,王希钟几乎调动了自己所有的能量,来设计各路光怪陆离的造型。 唐国强、王铁成、刘劲、卢', '2013-04-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA42vpLagtWLGWG54QFm-a_In-_svmpqKFGPzRwt4kz4wL5_oIgUOWR8fN5y5lsLLCjWO75lHzKwf_DQ-enfsHyWMda2-lo5B6pa-wF8nYx7ZyoK9pWKtVWhNLy9vdgrSnwKKP5Q79CyQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2569, '报纸', '邓小平的智慧改变了中国命运(上)', '林义成 ; 宫力', '中国纪检监察报', '中国纪检监察报', '中国命运;历史关头;政治勇气;政治智慧;毛泽东思想;中国革命和建设;“文革”;“四人帮”;', '对20世纪的中国乃至世界有着深刻影响的伟人——邓小平同志已经逝世15年了，但他的影响和伟绩依然在广大党员干部和人民群众中传颂。或许，一般人未必了解这位伟人在中国革命和建设重大历史关头是怎样抉择的。《邓小平在重大历史关头》一书记述了邓小平波澜壮阔的一生，尤其是', '2012-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICdCi-8WMQ4LQenmpLnL2IPOZ7j0EyXk1X-JQxyzfCTggfHZP0mPQjAxGcgiGLScQ7TinTqJYdihqI58kcj6dQ7tV7vCrKrRGbRdfa9yVIpYb3n6FmpwfkEsqR6yBH8khe6b65s9KsKsw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2571, '报纸', '党性要体现在信念、能力和作风上', '孙永春', '中共贵州省委;组织部;', '中国组织人事报', '组工干部;创先争优;', '今年年初以来，贵州全省组织系统部署了讲党性大讨论活动，安排学习李源潮同志《组工干部要做党性最强的干部》等几篇文章，各级组织部长、组织人事部门负责人带头撰写了150多篇心得体会，我逐一阅读并作了点评。结合“一迎双争”活动要求和贵州的实际，我认为，组工干部讲党性', '2012-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICQWWjuXr0JPT0rbTsYaOFk6YhUsWn5qxJgkFOMwmtyIOAtgYPI2cq4m_AAZ2OyCs9C6pbRFAhu__8yZJcReSUe_18N3tAACAQKaDciXfbfrCRQCZcACGPDxwHti7q6WFlgVR1UwgkPGA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2573, '报纸', '以“七一” 讲话为指引 做好新形势下组织工作', '孙永春', '贵州省委;组织部;', '中国组织人事报', '新形势下;胡锦涛;群众工作方法;“七一”重要讲话;', '胡锦涛总书记“七一”重要讲话，全面回顾和系统总结了我们党90年的光辉历程和基本经验，深刻回答了新的历史条件下加强和改进党的建设需要解决的重大问题，进一步阐明了党在新形势下的历史任务和奋斗目标。总书记的讲话继往开来、与时俱进，思想深邃、内涵丰富，对于我们深刻', '2011-09-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBvhCNIjiGjYkcM4yu6qsfnZKfbHGGO6KAMPH81T8oF3mRVtKxxxWj3Sn-1P3uLe7M-NQSpOXAHBCSnicNWF89GuI_vtgBY77ED9hfC3aQLhX-2u4_2i3bRv9lcGohY5rzgQW8QEQzvIQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2575, '报纸', '回望90年风雨征程 再现新时期辉煌成就', '', '光明日报', '光明日报', '文献纪录片;历史观;中国共产党成立;', '编者按 由中央宣传部、中央文献研究室、中央党史研究室、国家发展和改革委员会、国家广电总局、中央电视台联合摄制的纪念建党90周年大型文献纪录片《旗帜》，全面回顾总结了中国共产党团结带领全国各族人民进行革命、建设和改革的伟大历程、光辉成就和宝贵经验，生', '2011-07-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID4_NcPVhlqC2Xo13-moXtlLsSwyp6nPwrllXZ9_ApDqNju5ppdVUX3-YCcGYhNeYK6dpyIPq0UGevU4Mm3FkcMzNowZUF3uPhhd0DM8Yt0gcDXjWNihq1F9Jbgr1KOdDVhAS6Ss2pPRA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2576, '报纸', '纪录峥嵘岁月 书写辉煌成就', '', '人民日报', '人民日报', '文献纪录片;伟大旗帜;社会主义;中央电视台;', '编者按：由中央宣传部、中央文献研究室、中央党史研究室、国家发展和改革委员会、国家广电总局、中央电视台联合摄制的纪念建党90周年的大型文献纪录片《旗帜》，全面回顾总结了中国共产党团结带领全国各族人民进行革命、建设和改革的伟大历程、光辉成就和宝贵经验，生动展现', '2011-07-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDENI_vG2CCtKzCu5wZowOD3BP1-AsumNcnYiFx0EdHuNFQx4CI7_N1cAVbnrj-7oe9fVOjym0GPTBTWfEkKU5lRU40qfE_zLUNJIGh9B4AdP9Tn_aRx5qp_FbDlr3K63-FHT1Ov50JBg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2577, '报纸', '遵义：转折之城的安保烽烟', '苏雪峰; 杨忠诚', '人民公安报', '人民公安报', '卫生员;高射机枪;刘伯承;中央军委;', '汽车飞速行驶在黔北公路上，车窗外白墙黑瓦的农舍散落在一望无际的梯田之中，群山巍峨，数峰并峙。赫然间，“转折之城”四个字跃入眼帘，“北倚娄山，南荡乌江”的黔北重镇遵义近在眼前。 转折之城 “转折之城”缘何得名？答案在遵义城子尹路上。 下', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICfD-N_aVohblvELrR7QxwjRru4uhxuZMF_OMgLOICXz4phINnCYzE5r0ZMB3-Ukj3yqfJAK7Maz0jGhekfUi42Uf5vV8Yu_njxADU_29A2gV0gCMrHbFQlPPKWpu0X1VBFvtmhV4g8zA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2578, '报纸', '迎战 壮丽的征程', '', '人民日报', '人民日报', '国民党反动派;应对挑战;“左”倾教条主义;第一次国共合作;中央红军;共产党人;战略转移;中国共产党;政治风波;新的伟大工程;执政能力;', '() 90年波澜壮阔，90年风雨兼程。诞生于内忧外患之际的中国共产党，在应对挑战中立定脚跟，化解危机，不断开创中国革命、建设和改革事业的崭新局面。 艰难困苦，玉汝于成。中国共产党人在应对挑战与危机面前表现出的智慧与勇气、积累的认识和经验，是我们党永远立于', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICJ3leYEXVUB86957TTOD0UzhuyqM00xcA3-i1njyW4dBoIlBEaBg7vEDWMWU9zabSPflVBqY-Qgvn9l6QGHA5mq1BQNbNkM4oZTfK06OHAgQ3XYgvch7f2GvesIFA8PcYUki5bMBRr0A==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2579, '报纸', '历史,在这里转折', '颜维琦; 柳路', '光明日报', '光明日报', '黔北民居;共产党;王稼祥;', '1935年1月7日凌晨，遵义城下，一群乔装黔军的红军司号员一拥而入，吹响了冲锋号。这座北依大娄山、南临乌江的黔北重镇惊醒了，当地守军四处逃窜，遵义城随后宣告解放。 刚满20岁的王道金走在进城的队伍中。5年前，他在江西兴国加入了红军的队伍。尽管这是自红军“战', '2011-06-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAqsJesusaozWPMB_l2kKkvPwQRK4ZzuLBCS2Jhqehves3cLB0RF9E5tLcZl__2HckC31tD0K7p841fXk0UAw8DNoWb9BYu81UXe4iaxz-fL8u6nVjtpFaa8jbSj6irUtNOPP8BrQU-fA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2582, '报纸', '是什么染成这永恒的“红”？', '王斯敏', '光明日报', '光明日报', '中国的红色政权为什么能够存在;红色政权;共产党人;', '●中国共产党人的最伟大之处，就在于从不将马克思主义绝对化，也从不将自身经验绝对化，而是立足中国大地，用中国的办法解决中国的问题。 90年筚路蓝缕，90年风雨沧桑。用不到一个世纪的光阴，一个原本弱小的政党完成蜕变与成长，更引领国家民族走上了独立富强的辉', '2011-06-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICxFWiIAnJCb4XJTL8cn_RupRnhx_nkQ9XMAB-KA7xkQWkgw5CdMmTI7eM51eOlcYgzD4SJQHJ9Hsfqxukmrftm1BY7A9WXtXuM2wSKjjlxhurDMiKNJ-SwLwMqGAJBwSSsubYDyllb1A==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2584, '报纸', '理想信念照耀未来', '', '人民日报', '人民日报', '理想信念;国防生;', '共同担当传承的重任 教育部副部长 郝 平 当代先进共产党员和高校大学生代表的发言，是一场关于理想、信念的对话。 人民日报、人民网为纪念中国共产党成立90周年主办的“追寻”大型主题活动，组织大学生前往革命圣地，重温党的光辉历史，考察社会', '2011-06-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICMY_ZMAkgloSNK-XYiRZgrJzZFZn13zzN7uVBSYgM46Vpv-USCAtq0KqbKhE-7HAoDY8W2ITCvk6-Waj-nogqK1Kj_D57JWjudyyD_kcVFhf3d4Rl70ruqjv-0rhlTzzlCBPdywg2qsw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,龚全珍_screened');
INSERT INTO `ds_article` VALUES (2585, '报纸', '“红军币”的传世承诺', '赵洋 ; 靳斯慰', '金融时报', '金融时报', '银行纸币;', '从农田里匆匆赶回家的汪恒礼，没顾得上换下身上那沾满泥土的衣服，拍了拍手上的土，进屋从柜子里拿出一个纸叠的荷花包，荷花包表面已经发黄并有些破损，但保存完好。“父亲就是把那张红军币，包在这里面给我的。”65岁的汪恒礼边说边小心翼翼地将包裹一层层展开，手绘的荷花', '2011-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDIGU1anC5p2VjbnZbhsTi2TdRwybjHwvVSYufTlOLboWsrHqYeG03f8ocjK9aqjktXx6SBMq8TslSGLF6QzhD4K_QsKeE6Vg-AX3PT-OLqN37H8znWx1OKs7AHxoEfExQkNuAO9hUDaA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2586, '报纸', '正视缺点,一个成熟政党的可贵品质', '张晓祺', '解放军报', '解放军报', '刘志丹;', '“红色足迹万里行”前方报道组在子长县瞻仰子长烈士纪念馆时，“肃反”这两个字眼，吸引了记者的目光。 纪念馆里，有这样一段文字记载：当年，毛泽东说“陕北救了中央”，刘志丹却说“中央救了陕北”。 看到记者不解的样子，当地75岁的党史专家王志厚解释：1935年9', '2011-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICojQ1CsRxstH78J9AzgFubG7QBcIWV_3LV-N72IbuzSM-RNF52k7b-FnrBJmOohGRaJmR8MbSqXgzWRosU_q6HtCRYl1gb61UKFEOYlXpMHNNaYlpQiDU92_ncfqwWj32fpDAkzEqwNQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (2587, '报纸', '遵义：在红色土地上诠释执法为民', '苏雪峰 ; 杨忠诚 ; 刘乙颖', '人民公安报', '人民公安报', '执法为民;公安民警;娄山关;', '76年前召开的遵义会议，在极端危险的时刻挽救了党和红军，是中国共产党历史上一个生死攸关的转折点，贵州省遵义市因此被誉为 “会议之都”、“转折之城”；76年后的今天，红色文化渗透到当地公安工作的方方面面，以执法为民为核心，把革命传统和长征精神转化为实实在在的惠民', '2011-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBOzNBRULPjgjfUc1a_uYQxfAxGI9ABS_TIpSNhSTosRxGEDvFef8AUkqvOwwM5mvZ6PHj_9txEkQe759j0fiLfuJrj9Dt6Xv_HExXyJJ4BF45BoKvrvh4K0xFWhDi6ytfF-mV7GQzX4A==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2589, '报纸', '“向革命前辈借点勇气吧!”', '李柯勇 ; 舒静 ; 张舵', '新华每日电讯', '新华每日电讯', '周鸿祎;创业阶段;互联网产业;革命者;CEO;古永锵;共产党;创业史;国民党;', '据新华社上海6月9日电(记者李柯勇　舒静　张舵)6月8日,一群中国互联网领军人物聚首上海、浙江中共一大会址,集体上了一堂“党课”。 丁磊、李彥宏、曹国伟、古永锵、陈一舟、莫天全、马晓霖……数十副网络超高人气面孔集中现身“红色圣地”,引来无数游客惊奇的目光。', '2011-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB87mwOs1-YtzO9snVHWQzfrEG-TtTHkbZoktSM_pUkClPS0_DuVJJQsgC2uSr9o72xxv5HbrNwlr1Ox5cSgwRMGUbrYV7hC6xlGsyUD_Sh8I2Qm2BnzunRCpNDdazA2vmcsb3HhhA0cA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2591, '报纸', '遵义会议,中国共产党的“成人礼”', '杨彪; 欧阳浩 ; 程必杰', '解放军报', '解放军报', '王稼祥;毛泽东;张闻天;中国共产党;柏辉章;共产国际;成人礼;', '乘车穿过黔北群山，来到红花岗隧道。隧道口两面巨大的党旗预示着眼前的地方不同寻常。驶出隧道，“遵义”二字跃入眼帘。 在中国共产党喜迎90岁生日的时候，记者来到了我们党举行“成人礼”的圣地：遵义市老城子尹路96号，这幢坐北朝南、临街而立的两层楼房。1935年1月15', '2011-06-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB8K5uRDujy7ulk54dvu5Yp2ngAAxWagqRMTxWZa_E0EpHT_L6aZwxmuY_Xr_0zohyvgHOOj0vzEiMYYAYz7IZlNAWxnubosroqpzTu4ZX3rXDV_5A_sMGqMGhY_JgEwcXB6dnnFP3GkA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2592, '报纸', '瞬间化作永恒', '赵超; 李菲 ; 胡浩', '新华每日电讯', '新华每日电讯', '湖南自修大学;国务院;社会主义现代化建设;中国共产党成立;中国共产党历史;十一届三中全会;中央文献研究室;共产党人;毛泽东;第二代中央领导集体;', '新华社北京5月28日电(记者赵超　李菲　胡浩)回望中国共产党90年历史,一曲曲壮歌撼人心魄,一幅幅画卷荡气回肠。从开天辟地到遵义光芒,从强国之梦到世纪抉择,从中国特色到科学发展,党的历史上每一个闪亮时刻,都留下一个伟大民族阔步行进的坚实足迹。 欲知大道,必先为', '2011-05-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICE2OU-4CwiQc1SGDlY1-RohyShze3vGWm14mojmxAPKG7lec0ge-FJbLCz1hKE-AjNB1n46OS6EWnJyTp56wZa_DwDEPDCUTFYU4Z4Vhq7fvK3uWWGNGxD5jmcrRF5-5DMC-ecyAxHAg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2593, '报纸', '在绝境中杀出一条血路', '陈典宏; 张碧周', '解放军报', '解放军报', '红军长征;毛泽东;湘江战役;中央苏区;中央红军;', '如果说长征是震惊寰宇的壮举，那么，红军突破湘江战役，便是这一壮举中令人瞩目的巨大红色惊叹号，它因惨烈、悲壮和辉煌而格外令人刻骨铭心。 77年后的今天，我们“红色足迹万里行”报道组小分队来到湘水边当年血战的战场，寻找那幅血与火、生与死、存与亡的历史画卷，', '2011-05-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIADc0pYsO8p_mioEY9LbiwK5LHW8QM9t0EcAOdBotBs1uulMOU2bVXxWZeyxHU_NI3f_IhZEGkpqc6EbJiLHfrtZ8hcyWmLPyXLGM88hn2sebaBoE6Hn4gdpuoLngupbh9GqB_OKIZYYA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2594, '报纸', '历史转折', '肖春飞; 朱玉', '新华社;', '新华每日电讯', '红军长征;柏辉章;湘江战役;共产国际;中华苏维埃共和国;左倾教条主义;', '【解说】历史长河中,有这样一些转折。 或许瞬间发生,但却决定了接下来的历史发展走向,几十年,甚至更长。 我们来到的这座城市,名叫遵义。 每年,都有无数游客从世界各地,辗转来到这里,他们与我们一样,都试图寻找一个答案,一个关于绝处逢生的答案,一', '2011-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBXqhrj1lFrvA7bJ7OYp4vmcrsdmCyDkIhGWSAUZtDlPIJqIwM3uIkxfOgIOfX7CulBktpd-jOiF_GilWxT32PoDonamjShtP97JoxKiXtO4cNEdDcUiCFz1iV_sebI_fI2eb53G2-o5g==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2595, '报纸', '“绿洲红城”的感动', '谢爱临', '人民政协报', '人民政协报', '博物馆群;中国作家协会;女红军;红军长征;', '一个小镇拥有五座博物馆，形成博物馆群，而且其中四渡赤水纪念馆、女红军纪念馆为全国独有，这在全国十分罕见。这个令人神往的小镇就是号称“绿洲红城”的贵州省习水县精心打造的红色古镇——土城。习水土城以其独特的魅力吸引了来自全国政协的客人。近日，全国政协文史和学', '2011-05-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAKrv04tg8S8LZ7INcI2K802Z-_h5_xlwYaATy-o258MiQwlOWNoy-b3SeKSs8M48Vg_-ePNmeznznhbs1-m8ffxw1VXZAhZxIQ5jlSff6bPcGm12e-sfq84UCavpCuBY6sd0XoBZcDqw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2596, '报纸', '红旗漫卷长征路', '周之江 ; 李惊亚 ; 白瑞雪', '人民日报', '人民日报', '中国工农红军;中央红军;湘江战役;战略转移;', '黔北重镇遵义红花岗区老城子尹路９６号，一栋两层楼房，坐北朝南，临街而立。 ７６年前，在这栋小楼里召开的一次会议，深刻地改变了党和红军的命运，改变了当代中国的历史进程，标志着中国共产党在政治上走向成熟，成为中国革命的重要“转折点”——这次会议，史称', '2011-05-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDHQ9viT51U5RFnOl_tF_njsetjZ9gcdxaUL38TG7azVgVUpwqV0U6MlOyKlzDBAMqbkCtuQcwF_xasMfgAi9tdzLW9YZ2nyto1oHnVgaw4tyHwYuGcg70GdmdrmGBA59HNEC0YKYhK8A==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2597, '报纸', '贵州瓮安：长征路上崛起现代新城', '王新伟; 吴秉泽', '经济日报', '经济日报', '陈小霞;猴场会议;廉租房;“十一五”时期;工业强县;长征路上;', '入夏时节，记者来到“猴场会议”会址所在地贵州省瓮安县。“猴场会议”在党的历史上是一次重要的会议，它是黎平会议的继续，为遵义会议的胜利召开作好了思想上、政治上、军事上、组织上、时间上的准备。如今，瓮安已经从偏僻山区发展成为一座拥有50万人口的现代新城。', '2011-05-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAfJk0_bD_V4zKiLZ968lganO1S3jcqH6FE_DZOCiT87gJCn_oBVLBJ-0Jh3uWwEeIjUxYGc1EtyEc2ZmSMhntnWVYRZ3VPtzXTNA28J_zHRtzUM5eIOP9PojJ-ap8csrVZSwU7uKe8-w==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2598, '报纸', '《红星报》：最早的军委机关报', '杨清刚 ; 危卫平', '解放军报', '解放军报', '机关报;《红星报》;', '中央军委机关报《解放军报》正式创刊于1956年元旦。而踏访瑞金中央革命根据地纪念馆，却听讲解员说，最早的军委机关报《红星报》，1931年12月11日创刊于瑞金，距今已有近80年历史。 《红星报》是中国工农红军军事委员会最早的机关报，由红军总政治部主办，一般为铅印4开', '2011-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDdMZYYXoEZxzO3v7TnIVpDLOdYLMRzxVwXtBiXUlNnjGNy3B2xn593N3icIYMQSYuY8hDWW5chXRexpHqSYE2Ydxg8dKtJND92kvEGOE8CU9P-U5bTHXNqbJsBzGY2b9s2UipZh-hQVw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2599, '报纸', '会理倾力打造金沙江畔第一县', '杨顺忠 ; 张义; 虞明 ; 何佩东', '中国商报', '中国商报', '会理县;地方财政一般预算收入;日生产能力;金沙江畔;', '核心提示 会理，因“川原并会，政平颂理”而得名，古称会无、会川，始建于西汉武帝元鼎六年（公元前111年），至今有2000多年历史。 会理位于四川攀西腹地，西邻钢城攀枝花，南与昆明市禄劝等县隔江相望，北距西昌180公里。全县幅员面积4527平方公里，辖6个', '2011-05-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIApwGcGlaD992TC85r44vZeiU9x49LCfIMhSYOAQECSpTq4tiBaCJk0Ct4bzrfbCFa8Pjin-dZuf_p6iuacju6zYfdO3zMUpT87BLL56D2s03abLPUcdCwCwHHPUqPKHhqYvIRB8z97bw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2600, '报纸', '长征路上话使命 传统教育铸军魂', '申维明; 李志红', '解放军报', '解放军报', '参观见学;军代表局;长征路上;', '本报讯 申维明、李志红报道：4月22日至26日，空军装备部党委组织大部领导、机关及所属单位主要领导在红军长征路上开展“加强党性修养，铸牢军魂意识”参观见学活动。 空军装备部机关及其所属单位高学历人才集中，人员出差频繁，单独执行任务多，社会接触广泛。近年来，', '2011-05-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAJM0SG8QNqmKf-cFAcx3XIO4YX_KtxEEwcBkJISXYasA0LF1SiVO3h-KAoI0AtNSNzVI_ODtakPBFuGeRvdDgBfCz80VmU1ehlcK4Bf-Acxw-nzuB4icObp30yj-XQG6qV6Wq4nqhczw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2603, '报纸', '让历史鲜活起来', '邹雪峰 ; 李兵正; 司儆', '解放军报', '解放军报', '官兵;', '仰望历史的天空，一张张面容依旧鲜活，一个个事例依然感人至深。每名参观的官兵都来寻找属于自己的感动，汲取精神的滋养和力量。从南湖的红船，到葱郁的井冈山；从曲折的长征路，到高耸的宝塔山……展板前，官兵们在寻访、在追思，信念越来越坚定：只有同中华民族血肉相联又', '2011-03-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAZfHvzhX3rNCkFGEqenghQmU8vuejrMkJuqL5eaSKS5mIe2pF-GqDe8qZTS8v8CDz2Aau3NYIMtyFDSyRBZ1HHLshalDh5b6DUTh6DhklLnIsgWPSnvma2ZiGEmxTm-9m4vh0aFEs8rw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (2604, '报纸', '平江起义领导之一邓萍', '', '人民日报', '人民日报', '平江起义;彭德怀;', '新华社北京２月２７日电 长期与邓萍并肩战斗的彭德怀曾说：“邓萍这个人是值得纪念的！”他深情地追忆道：“从平江起义到井冈山斗争，从江西苏区转战到长征途中，直到他牺牲前，我们一直在一起工作，互相配合得很好。邓萍对党和人民的革命事业忠心耿耿，作战指挥沉着果断，', '2011-02-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA1aCUt5Gv2pF9Mqn0m0pL5v7AUc1UTa3aw8ThshU1qiDQun9q8UAxAa7xoNqXml5RLMFa_oz4qEYrEpt-CGHR2i4J-96seIcpttcEmGLgLj9PNvmgEKkzsQxCc4r8y6syqF6i0jrmg0w==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2605, '报纸', '我们所做的只是回报', '刘淼', '中国文化报', '中国文化报', '革命老区;铁路文工团;文艺工作者;胡振民;遵义市;遵义会议会址;', '在强冷空气的作用下导致雨雪混下而形成的天气情况叫做凝冻。原本应该温暖如春的贵州最近正在遭受凝冻的侵袭。1月7日、8日，中国文联“送欢乐、下基层”的队伍来到了贵州省遵义市，艺术家们用自己的热情温暖着这座被冰花覆盖的城市。 演出从火车上开始 “为列车员演几个', '2011-01-13 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2011.000436', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2606, '报纸', '《长征组歌》历久弥新 《父亲》感动重庆儿女', '屈菡; 陈帅', '中国文化报', '中国文化报', '《长征组歌》;同煤集团;', '“红旗飘，军号响。子弟兵，别故乡。”一曲饱含革命热情的《长征组歌》在传唱了40多年后，依然铿锵有力、激荡人心。9月，北京军区政治部战友文工团携文化部首届优秀保留剧目大奖作品《长征组歌》踏上了巡演征途，他们走军营、上矿山、进院校、赴工厂，在山西、河北、天津等地', '2010-10-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBASlicQa6qV6RZmRJEUGpj1iIKIzv7gLKWak3yXd2tkQT-U6XgBrJS-kTUw0Oafy01itJU4fy1Achp8mKO68XCJOnHLoGMWAWOynjDwIQRxeFi8L8edM7e1s-FCbzxn6kkYvPY3m3W9Q==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2607, '报纸', '遵义会议会址', '', '中国纪检监察报', '中国纪检监察报', '教育示范基地;', '古城遵义是位于贵州省北部的一座历史文化名城，著名的“遵义会议”在这里召开。  1935年1月15日至17日，中共中央政治局在这里召开了政治局扩大会议，即“遵义会议”。会议集中全力解决了当时具有决定意义的军事和组织问题，结束了“左”倾教条主义错误在中央的统治，', '2010-09-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC0YvvK2Ir8WTOYnYBX8-VPWL2_Ia7wUK1ItPDsxggZ_VYEYmQNl3x9e2fjIQ1YRNgort5fATYh7bpzta_DtYB42YhlZN8vIFLwaCdQ-coOgE2IWLtI2MKv8IGKXNL_8NKbnxJ1XaHn6A==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2609, '报纸', '今天我们怎样学党史', '董宏君 ; 金冲及; 陈威 ; 欧阳凇', '中央党史研究室;', '人民日报', '《中国共产党简史》;党的历史;', '我从何处来,向何处去,这是人类对自身永恒的追问。研究历史,学习历史,了解自身的来龙去脉,对于如何走好今天的路,我们会更多一份笃定。 就像人不能选择自己的父母一样,一个国家一个民族一个政党,也不能选择自己的历史。我们看到的接受的往往是历史“强加”给我们的东西,而我', '2010-07-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICoEQhC9uJzjAJK9o5ltV9rTGuBeWEio7iMKOvojAcSn-SsutvFvaU3Ce8nMdcNKL3M1w5xaGZAKCGS6APrcDQqeN-cXuRqjO2RX_F7rhs2Y5wgmipxUXzUUkYpzjA63ybAW7QilKyZ5Q==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (2611, '报纸', '贵州红色旅游:“红”子带活一盘棋', '石新荣; 王橙澄', '新华每日电讯', '新华每日电讯', '红色旅游;免费开放;红色文化资源;', '据新华社贵阳电(记者石新荣　王橙澄)初冬的遵义阳光灿烂,遵义会议纪念馆里游人不断,红军街上留影、购物的游客络绎不绝……近年来,贵州红色旅游发展迅速,全省已初步形成以“遵义会议”为龙头,以娄山关、息烽集中营等重要历史遗址为支撑,以重走长征路、长征文化、爱国主义教育', '2009-12-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBh-TBOSjEqeG87GzgYm3f9Y5JSwBNpqpJFOrxCEGXpUkFqvsarvr03XcNoRCkOGNvtMyh7TAVCqsW3SzKd0ZyuuVBDkXlE_WKLWL1RApzNy7MLkZS8FjHdzEsvObTvdIKF8HytCh5Z2g==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2614, '报纸', '石仲泉：坚持党的领导', '石仲泉; 倪迅', '中央党史研究室;', '光明日报', '坚持党的领导;周恩来;毛泽东;石仲泉;红军石刻;', '前几年，我沿着红军走过的路，走了一遍。作为一个长期从事党史研究的学者，收获特别大。其中之一，我体会到，我们党常讲的“坚持党的领导”，决不是一句空洞的口号。这里，我讲两件看到的、听到的事情：  一件是苟坝决策——  在2003年3月考察遵义会议期间，我们一', '2009-10-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICPvfk8SddNZ7QwQUlUhgjC2y7JuqOcYZhnguWF0ev6_1xhJW9uyo7PK2Z6J6pyl-R706Wfwr3FPjy5N56sgjkda_GcX2G1nHcMK9GN3Ji6nV54htbH9DxdfOSROBgiFmx4e0g9tTSkaw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2616, '报纸', '让红色之光永不褪色', '李奇松 ; 林贵鹏', '解放军报', '解放军报', '省军区;红色资源;人武部;', '贵州是红军长征历时最长的省份，全省68个县（市、区）留下了红军足迹。红军故事、遗物、遗址，连同各个时期的革命遗迹一起，成了贵州省军地发展取之不竭的精神财富。 多年来，贵州省军区各级以高度的政治责任感投身红色资源建设，坚持在挖掘中重温历史，在利用中激发斗', '2009-08-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAav0PKjVY82G2j2QUD5KxU25Ug2aa04MNMXDrVxWZj--j3JY7o5_qcPYI5u8DstJ2Xr5QJWS56uf3V9oucOfnWBCl5ijLh5fNjxJ9QAcA3HCyiAOgDUlLGdCzNCtU5tv1giorvA1YzDQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2617, '报纸', '弘扬长征精神造福老区人民', '杨彪', '解放军报', '解放军报', '红色资源;长征精神;历史文化景点;省军区;', '贵州省军区积极支援地方开发利用红色资源 弘扬长征精神造福老区人民  编者按 贵州省军区支援地方开发利用红色资源，是从政治层面抓住了西部的优势，抓住了军队和地方的结合点，他们的经验值得借鉴。西部很多地方是党领导人民军队创建革命根据地的重要地区，这些红色资源', '2009-08-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICZTo5AtcD7PjoNknxob-t0qCw8RxnJVvZd3HlJeZ4-y9VBYyj7i--idMC4pJp8JRjjuL9AsAUKWxR9lSGa5QugZDNfSyeh4ALX6zJrsO1i9dGlLpzpCYzB675b-kX6VU-Bxpv1Xp1rGw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2619, '报纸', '遵义：传承革命优良传统 迈上创新发展之路', '陈静 ; 黄鑫 ; 徐克强 ; 张剑鸣', '经济日报', '经济日报', '红色旅游;红军长征;农民人均纯收入;优良传统;发展之路;', '遵义是一座英雄的城市。1935年1月，中央红军长征到达遵义并召开了具有伟大历史意义的遵义会议。 遵义是一座美丽的城市，满目苍翠，气候宜人，拥有中国历史文化名城、中国优秀旅游城市、国家园林城市、国家卫生城市、全国双拥模范城市等美誉。在这里，人民安居乐业，经', '2009-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA5U94WhnOmj5FY3YbxKdjNWpaEGu6gkpHAma7mhTG3K4rIySIE5i8DmsnAkIFvPAlmjERB_GSECv1PH0fh3smnzfxGiE9ZUuyrMhY4BolQivUshUjzLpEY8QNv7-8vphdgSIkdGrYlqQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2620, '报纸', '遵义：绝地逢生之城不向困难低头', '朱国贤; 周之江; 王丽', '新华每日电讯', '新华每日电讯', '毛泽东;伟大转折;政治局扩大会议;粮食总产量;马克思主义基本原理;地方财政收入;地区生产总值;革命旧址;总收入;', '新华社贵阳7月26日电(记者朱国贤　周之江　王丽)这是生死攸关之际。  1934年底，湘江战役，空前悲壮，中央红军从出发时的8.6万人锐减为3万多人。进入贵州境内，红军面对40万国民党军围追堵截，兵力悬殊为长征以来之最。  这也是命运转折之机。  1', '2009-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAzq_y_Z5RSlZPrqnFNUhPizA956U0ZwQ5qa6h4DEpKdReFFgp1qCXYA0fu7tC9oc21aX9BKeTcaiCNb9kt9kioB2PbphO9C2v8PHKKhFJXcEHPqEWN7XaN0FtPAYeQja3kF1q21u-9Pg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2621, '报纸', '弘扬长征精神 推进科学发展', '许跃芝 ; 张剑鸣', '经济日报', '经济日报', '红色旅游资源;旅游接待人数;综合收入;红军长征;长征精神;乌江战斗;', '贵 州 3月的贵州，山青水碧，层峦叠翠。大片大片的油菜花为田野铺上了一层金黄的底色。作为旅游热点地区，这里吸引游人的不仅有神奇的山水，更有厚重的红色历史文化底蕴。 贵州以“长征文化”为主线的红色旅游资源非常丰富。革命战争时期，红军足迹遍及贵州68', '2009-04-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICLGtIJdBiHuiuOJ_ePDADDWcNTaHU45Dp1EQlIfpBN_i2PwCFOVxHhz9rbCzp2UCaITHJFFIlTUxC662g75sEkpFVKxDgyNYBAOk3YPHA15NIY0bL6PvHr_-uYYzHhY0eS2FG66A72EQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2625, '报纸', '国防大学：告诉你鲜为人知的成长足迹', '李绪成; 林培雄; 刘德茂', '中国国防报', '中国国防报', '国防大学;教研人员;中央军委;毛泽东;党中央;井冈山教导队;', '在中外闻名的北京颐和园西北处的红山口，座落着锤炼人民解放军将领的国防大学。她的东面是培养中国共产党高级干部的中央党校。这一东一西，文韬武略，担当起培养共和国治党、治国、治军栋梁之才的历史重任。  公元2007年12月1日，国防大学迎来了她80周年华诞。 ', '2007-12-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBkdBou7gJVcemtaUZBdHaEkJ3vkBGd4zkIg1q_lDxxJAHHXyaVPvXRx8OE9mhaa05-U5BFKBtR8g-42pW4dnuJdGwgAVISfCd-ZLuk6lr3Jr95Md3YAzi_Kjb5NsolLXffQY074LTPtA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2628, '报纸', '红土地上的特殊报告会', '尹健', '中国纪检监察报', '中国纪检监察报', '报告会;井冈山革命根据地;方志敏;毛新宇;', '江西省纪委的领导来了，南昌市四套班子的 领导来了，各县区、市委各部门、市直各单位的 同志们来了，驻南昌部队部分官兵也来了……能 容纳500多人的南昌市红谷滩会展中心东厅座无 虚席。在纪念中国人民解放军建军八十周年、秋 收起义和井冈山革命根据地', '2007-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBEXXrQh4g53I1wmcv75nDImCkh3Z-mbSuyM8rQdZNEqm8eJJAHrU7v6ZK5pP615WAOvw3svkZMGZc15jtUpRXVJ4ALPmonx8LYDMLuoEZy4qdg9ws2ll26j2d0r2lT04in1xvjZbqdjA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened,秋收起义_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2630, '报纸', '红色遵义：找寻跨越时空的青山绿水', '王经国; 赵建平', '中国水利报', '中国水利报', '中小水电;“西电东送”;水能资源开发;雨水集蓄利用;', 'T遵义，因为一次会议而成为中国革命与一个伟人的转折点。长征胜利70周年后，伴随穿城而过的湘江河水的，不再是枪林 弹雨，而是和平与发展的音符。从此，遵义完美地记忆着历史的荣光，鲜活地走在历史的延长线上。  伴随着遵义经济社会的快速发展，遵义的水利事', '2006-12-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICMUDhvRUPrwWZIAECvXDJU6Bc7tnycdhmW7YvszbUoc1BZ-JXANuc1PMpuna1UhJpuCpreQj-AGDMJov0lIkL8AaL1Bm4AQY5zZtzsY84CxtoUCzqgA4P2iMQCXD9osE_m6B-gsnpUHg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2631, '报纸', '军民携手满眼春', '秦光龙; 李奇松; 杨彪', '解放军报', '解放军报', '省军区;民兵预备役;喀斯特地貌;人武部部长;', '地处祖国大西南的贵州，堪称中国革命的传奇之地：在这里曾召开中国工农红军长征重大转折点的遵义会议；有毛泽东军事指挥艺术上得意之笔的“四渡赤水”；有长征路上取得第一次大胜仗的娄山关；还有长征组歌中唱到的“乌江天险重飞渡，兵临贵阳逼昆明……”  然而，这', '2006-12-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC9lkXia4iSgDy9USFMNT0AMH4BttqRV5tUoJgLaz2i9H_LMBksP4DGkpsX4woLaQFSIITNEyj7ZkMYHTn4R4Q-T_d3e6Ic8FCkUQ1svyuE_2GorKBbjuvgHYrZiZjcDNk7GP5tIh99ig==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2633, '报纸', '纪念红军长征胜利70周年展览在沪开幕', '王有佳', '人民日报', '人民日报', '长征胜利;长征精神;瞿道文;', '本报上海１２月１日电　记者王有佳报道：今天上午９时，《伟大壮举 光辉历程——纪念中国工农红军长征胜利７０周年展览》在上海展览中心开幕，开始为期７天的展览。 ８时３０分，在上海展览中心门外，前来参观的市民排起了长队，许多人还带来了鲜花，放在门外的展板', '2006-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAyfCLYBge7f0QN2f5MEW7gFy5FN_ey04ZnmSvcoz9dopdU9l__HcHBOCT5OL1Oc8WvRV_xTN7_kWYBxbcz3tiECs0pairF5m-6oau7NQ8HKmkBBPx6HwTJPfc9RqalRhvM5nXCcly02g==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2636, '报纸', '在纪念红军长征胜利70周年大会上的讲话', '胡锦涛', '人民日报', '人民日报', '红军长征;继承和发扬;共产党人;长征胜利;长征精神;马克思列宁主义;光荣革命;马克思主义基本原理;全面建设小康社会;中国具体实际;', '同志们：  今天，我们在这里隆重集会，纪念中国工农红军长征胜利７０周年。７０年前，中国共产党领导红军将士完成了震惊世界的长征，开辟了中国革命继往开来的光明道路，奠定了中国革命胜利前进的重要基础。这一伟大历史事件，是中国共产党人的骄傲，是人民军队的光', '2006-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAOzUxBmONXNiqQBuBsKEf2o0dRh-EyYoDUONvdojp6qH8NT9uI4nE2Y4uPLLpT7RKlUEVbTFQieWVZS51DAS49qbgvDRamaZJnTlSukqS8cEXxfHSfc3Bx4U6dkQot0se1GTRBfXAjQg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2638, '报纸', '“我们要永远发扬长征精神”', '敖蓉', '经济日报', '经济日报', '长征精神;红军长征;', '“伟大壮举 光辉历程————纪念中国工农红军长征胜利70周年展览”开幕以来，一些特殊的展品激发了观众极大的热情。 铜制的雕塑、写实的油画、泛黄的老照片……红军战士那坚定执着的目光，照亮了展厅的每一个角落。 一进展厅，就看见观众纷纷用相机拍下', '2006-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDN0qlaPq8UraXd5u-MASdU6yZVVZjeiP9riyZ4wj2lt-91nHxu0wjJRdjrxIZvTQnjPXkC70XgVpXlhZex_O4TI-f8C8qLHLVtP4ofrmkfhSX0MBRE6d0B5tHXd_ZWbIbiTHBxIYlcRQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2641, '报纸', '首都隆重举行《长征颂》大型演唱会', '', '人民日报', '人民日报', '演唱会;《长征颂》;', '新华社北京１０月２０日电 讴歌光照千秋的长征精神，激励振兴中华的豪情壮志。纪念红军长征胜利７０周年大型演唱会《长征颂》２０日晚在北京人民大会堂隆重举行。胡锦涛、吴邦国、温家宝、贾庆林、曾庆红、黄菊、吴官正、李长春、罗干等党和国家领导人观看了演出。', '2006-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICxBgJpW8jLJJAqlXDMIFDk2hmzHk4EvstrS4rBoiIz98fdyfJ3ciexZYwmNZKwZRWMBz-bY7kY_VPGhp-t5iOYHh_UI1WHgtbIps7bBTXd7NcJfiWkTpWgc0h3bqdNvTJdgKIbQQ5osg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2642, '报纸', '遵义会议（上）', '', '人民日报', '人民日报', '中央红军;毛泽东;黎平会议;王稼祥;湘江战役;政治局;张闻天;军事指挥;', '湘江战役后，中央红军仍按原定计划，继续向湘西前进。这时，蒋介石已判明红军的行动企图，在红军前进的道路上部署了重兵。在此危急关头，中华苏维埃共和国临时中央政府主席毛泽东根据当时军事态势，力主放弃原定北去湘西会合红２、红６军团的计划，改向国民党统治力量薄弱的', '2006-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICYic4p9nfM1oLgnYY626ucOTnmpbmbM5rrotx7_UjehYlkc0YZDfB9e0nWRrhULVPBbmeyNZZxxqUg7spVUUF0T7QJaQhUb_oIt_zB_i0RBkna7egKlizlZEmRC3BEIM8dO7CsXFBf-g==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (2643, '报纸', '长征精神在这里回响', '杜剑; 韩国贤', '中国国防报', '中国国防报', '长征精神;', '站在小木船前，72岁的李学民老人给14岁的孙子担任了解说员：“当年红军就是乘坐这艘小船开始长征的。”他是在前一天参加过展览开幕式后又专程带孙子来的，老人说：“长征的故事和精神应该代代相传，现在有的年轻人吃不了苦，像这样有深刻教育意义的展览应该多让他们来看看。', '2006-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBQ1q6S8s6ZvxEKl1g2a_yioWSfjf1-3HEJ442lC22Bib77tEHNShZikU-FcI9n7ZTPdBM3Iiyaod62oAENYt-w0-QcjfNwsHQX0dC2gC_YMHDJUmDTmcByudq4bMBPOYPxBOvhgcSa4g==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2644, '报纸', '肖福：在长征中开路架桥', '王瑞水; 赵赟', '中国交通报', '中国交通报', '中革军委;工兵连;红军长征;', 'F人物档案E  T肖福，生于1917年，福建长汀人，1933年参 加红军。红军时期，他先后担任中革军委工兵营班 长、排长、连长，曾参加第四次、第五次反“围剿” 和强渡乌江、巧渡金沙江等战役。1955年他被国 防部授予上校军衔，1958年任江苏省', '2006-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAW0g3jDwius4dadgaqIvybUqpzIUT8A7Fv_ir_ZpZt6ZiI_v2mN1VoyPwmudJWWZBfjM4QEqVi5N6XNIDk6hGry-AX_BF9SY9ZQ4haz-igTBCnLmxaeVWAWsZCQJeuTYvWqlPxbi_1oA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2645, '报纸', '长征：常采常新的精神富矿', '向兵', '人民日报', '人民日报', '故事片;长征精神;八一电影制片厂;', '在红军长征胜利７０周年之际，八一电影制片厂接连推出的故事片《我的长征》和长篇电视剧《雄关漫道》，成了影视屏幕上一道撼人心魄的风景。日前，记者采访了八一厂厂长明振江。 “７０年前的长征，是人类史上的伟大奇迹它不仅属于中华民族，也是全人类优秀文化遗产', '2006-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC6eHX9zlcVCIyqnYncz5--ueek267vR-Ohlb6ZbR-DIMZ93Bug2D4mSAUcXKWo0t5uwFdP_5dnd08MhVga4KAYjVs-qk0eUwuXHxpuswuwIlPFk0Eg8nqAoUhKwz2PkpYNMnzZ87_DLg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2646, '报纸', '长征,在孩子的心中延续', '袁新文; 李斌; 张敏; 沈洋; 冯刚', '新华社;', '人民日报', '长征精神;红军精神;', '编者按： 长征的故事撼人心魄，长征的精神代代相传。在长征胜利７０周年的日子里，各地举办了形式多样的活动，在与历史的对话中，一颗颗理想与信念的种子播在了青年人的心中，他们的目光因此更深远，他们的脚步因此更坚实。 在这个值得铭记的日子里，我们', '2006-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDBCqoGESh5SddGj_V62VkXqoBMkiFLj5EV1tpyB9gfmmx0r-C5igBN8nMh_95ju-e_jkDpWBrfbfec-Fo3xRIM4cRTbH3yfqBR-L-vg6S4aT4qsoMkCiQul7pSgGhL0hIN3c51dyF0_Q==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened,会宁_screened,红井_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2647, '报纸', '长征精神永放光芒', '曹红艳; 苏大鹏; 敖蓉', '经济日报', '经济日报', '长征精神;红军长征;长征路上;', '70年前的10月，红军三大主力会师，长征胜利结束。70年后的10月16日，《伟大壮举 光辉历程———纪念中国工农红军长征胜利70周年》大型展览在北京开幕。在秋高气爽的日子里，老红军战士、解放军官兵及各界群众来到中国人民革命军事博物馆，在一幕幕场景、一幅幅图片、一件件', '2006-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBMfGrkF-e6gEbshK2uvBIy7ox8VJ4xyn4nC90T--XJfn0TF3EJLaoac0isFCs_wi50-AdeUZTsQQMCqSc82HjhTgbZRxKhyZVXnH3sviY8TNp2dBP3Ph8jokfDA1uppfkJ-PnlhRQ3_g==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2650, '报纸', '发扬长征精神 不断创造新的业绩', '秦杰', '新华每日电讯', '新华每日电讯', '长征精神;中共中央政治局常委;胡锦涛;', '新华社北京10月16日电(记者秦杰)中共中央总书记、国家主席、中央军委主席胡锦涛16日傍晚来到中国人民革命军事博物馆，参观“伟大壮举光辉历程──纪念中国工农红军长征胜利70周年展览”。中共中央政治局常委、全国人大常委会委员长吴邦国，中共中央政治局常委、国务院总理温', '2006-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICGn5npG-lH-Z8fjoroH-pvvz1BV2pwYGBU5b5r3spl2jOeWVrVnkUU5VcEXK2zhSevfvgr4VFMbi4DzpE8kX3GaW4TNtCj5hBfAG_w2XkifvyuivJi486-8iaHFSWxm6LafzCCz8a8vA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2654, '报纸', '铭记伟大壮举 续写光辉历程', '柴葳', '中国教育报', '中国教育报', '长征精神;红军长征;中国共产党领导;', '本报北京10月12日讯（记者　柴葳）由中组部、中宣部、中央文献研究室、中央党史研究室、解放军总政治部、中共北京市委联合主办的“伟大壮举光辉历程———纪念中国工农红军长征胜利70周年”大型主题展览将于10月16日在中国人民革命军事博物馆展出，目前各项展前准备工作正在', '2006-10-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB6mcWvG5yuKHR-_-P4vJOqh9BKMw0GPp_6rRJ_XuAi9R3xzTt55Jt1KC8bHEKkPEpHobilQw4zXncz1p-PhDohlodmV01gOoNbGpGUuh_2BgKyCbwg2cuHyvI7xhWMFwcVtYMlcKRVlA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2655, '报纸', '三百里竹廊铺就农民致富路', '柳路', '光明日报', '光明日报', '农民致富;竹产业;大同镇;', '71年前，赤水河畔曾上演了一场以少胜多，以弱胜强的经典战斗。毛泽东，在这块神奇的土地上展示了他的军事才华和指挥艺术。  遵义会议后，蒋介石纠集湘、川、桂、黔等各省军阀及国民党中央军薛岳兵团共150多个团，40余万人，从四面八方向遵义压来，企图将中央红军压', '2006-10-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICxUJvVNv7SPbbXLQb43BupDWni11VRY-LbjStqSCBAVeJZCQqkC7P0GrUJ-1YAZdv2V20G-PAr4VBE54z04bhwFymGvXu5WazuyoKuQ9b2Zk24QOjgXFZ4_3T8QLwWJaN6P2Mwr0XOOg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2656, '报纸', '纪念长征胜利70周年展览将举行', '唐先武', '科技日报', '科技日报', '长征精神;长征胜利;中国共产党领导;', '本报北京10月12日电 以长征历程为主线，以弘扬长征精神为主题，《伟大壮举光辉历程———纪念中国工农红军长征胜利70周年》大型主题展览，将于10月16日至11月24日在中国人民革命军事博物馆展出。此次活动由中央组织部、中央宣传部、中央文献研究室、中央党史研究室、解放军总', '2006-10-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC7l6Kl0LLRUbRqDQdXR5a-8cfqEpJhJ6IzPf2GMTc-31OKcXF50NLIns3o5J8TGt_2o_XvCdEajETwihsA3Vt4JQUFtFAmA0CEMFVtOZo9GLJyWpK9zQhXQ620zgXLDxNx00n0403vQQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2658, '报纸', '赤水翻涌发展潮', '王新民', '中国纪检监察报', '中国纪检监察报', '仁怀市;长征精神;毛主席;鲁班场;银手镯;太平渡;', '长征记忆  1935年1月，遵义会议 后，蒋介石调集重兵向遵义地区 逼近，企图“围剿”中央红军于 乌江西北、川黔两省边界地区。 1月29日，红军在土城、元厚一 渡赤水。2月18日至21日，红 军分别在二郎滩、太平渡二渡 赤水。3月16', '2006-09-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBT5LyNuTTxmh33JD3W6-WiLhJEA7M3kJOqCYFQYk8vJvgBxGof-8Hr5qWEXUqk9oaYriv4W66BU7aSOnikHs1FkOKX6UHsqEpmn-Y4p4h_G2ZE6PajXI2KtfXn0zNr8KPPXqUGCqb5eA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2660, '报纸', '向洒满鲜血的土地鞠躬', '钱江; 罗昌爱', '人民日报', '人民日报', '湘江战役;红军长征;“左”倾;杨成武;国民党军;兴安县;', '１９３４年１１月２５日至１２月１日，中央红军长征进入广西东北部，在全州与兴安之间强渡湘江，突破国民党军的第四道封锁线。  ７０多年往事飞去，湘江战役惨烈的鏖战场景还在９３岁的裴周玉将军眼前闪现。记者要去湘江上游追寻红军足迹，在北京向老将军辞行，这位', '2006-09-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBpGjb01vVmG1BD7oXf5sK1Fk_Af38OCdbZjyw7nGsiunwMpJ5HHRcAhvXV77v18Yr0hrzt0YCs_CYW6KeCiOWO2tS0TZTIe1xmi9IomPbmj7y5cfVX0RIR2-VXln2kAmBDs0ZF31Ckow==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,血战湘江_screened');
INSERT INTO `ds_article` VALUES (2665, '报纸', '遵义乡乡通坦途', '朱虹', '人民日报', '人民日报', '红军长征;种植面积;', '贵州省遵义市因红军长征召开的遵义会议而闻名天下。这里山高谷深，溪河纵横，自古以来交通不便，运输靠畜驮人背，交通之难被形象地称为“连峰际天，飞鸟不通”。 今年９１岁的王道金老人长征时是红三军团的战士。谈起１９３５年红军长征走进遵义的情景，他至今记忆', '2006-08-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAlPO2i_X1uWqFxTWFeLv0LGtJ_5znVegyxM70x-YAI93EzQrpH2P5d5Zf2CJwV2MJcjJzFWhEH1wgENCuuntUARrmrzoGyYSRYtHIRlf6_IDV_9h5EooBxx0ErIPJ9wjb_UdArE0EFnQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2666, '报纸', '遵义金融谱写今日传奇', '靳斯慰; 杨远华; 林永福', '金融时报', '金融时报', '红色旅游;金融机构;地方经济发展;综合收入;', '红色旅游令人陶醉，白酒文化让人惬意，绿色生态让人怡然……身处西南一隅的贵州遵义，不仅拥有“十大城市名片”，还享誉“红色之城”、“幸运之城”等等称号。如今，这座花园式的城市，已成为镶嵌在黔北大地上的一颗璀璨明珠。  从“天无三日晴，地无三尺平，人无三', '2006-07-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDxpvoI9FGdZkVauLKMEPev1ydz9el4j6nECtybqe9IobG67lKqXQXeDPY5swtQA-b6zLJAR_--b7lc9Spn2FILLSYygEKTPV2ol087BGiOl3RsPfId4sr1I4y92ui6x84gBTOZNO3P8A==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2667, '报纸', '丰碑在战火中树起', '郭曙光; 刘山芸; 吴晓岚; 刘必权; 胡致祥; 李向阳; 邓加荣', '金融时报', '金融时报', '中华苏维埃共和国国家银行;中国人民银行;毛泽民;华北银行;银币券;', '在庆祝中国共产党成立八十五周年之际，回顾党领导的金融事业在血与火中的成长历程，对于增强今天金融从业人员崇高的责任感和使命感颇有意义。这些鲜为人知的细节是值得我们珍藏的历史记忆。 让我们以此向党的金融事业开拓者们致敬！ 创业 中国人', '2006-06-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAX8Xneh3yNiE9KxRokkERQAsLCEpOD74BQDYMfp2k_w80vNML8QxrK1zswS0FPCyzdaV1KKWoAQ3NVJ7YB0abKu2rAoz6ApgZ4jxLsWmSraoM3nc7hEQC3WZ86e1Rs_iM9HLMZXMzxlw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,项英');
INSERT INTO `ds_article` VALUES (2672, '报纸', '2006，军事影片重拳出击', '向兵', '人民日报', '人民日报', '红军;长征;杨业;军事;', '2006年，是中国电影新百年的开始，是中国工农红军长征胜利70周年。八一电影制片厂计划生产的《我的长征》、《导弹司令》、《情暖万家》、《儿子同志》、《闪闪的红星》等五部影片将在这一年相继问世。这是八一厂近年来计划推出影片最多的一年，也是八一厂在中国电影新百年来', '2006-02-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICHD8BK912Xs_jB1Kt_MOfm4lyT-SPL2kmN_i7vuoKdrBav7j0aNoawdG0BLVfc_siNyMX5vjPzOg7WUZtTTVyLZCWe7MWRopIXC-fozjEy-hKokD9NIF3-ifJVzK5ALcKmJcfxfl-ZGg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2674, '报纸', '中共隐蔽战线的杰出代表——潘汉年', '', '人民日报', '人民日报', '潘汉年;', '潘汉年，1906年出生于江苏宜兴，1925年加入中国共产党。潘汉年是我党历史上隐蔽战线、文化战线和统一战线的卓越领导人，在长期的革命斗争中，潘汉年忠实地执行并多次出色地完成党交给的艰巨任务，在世界反法西斯战争和中国抗日战争及解放战争时期，多次为党获取重要战略情报', '2005-10-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAce45_8zL4KBLF6fca9z5c3GRwSH9IHsMeXx2dMR4qrXKBfpbJaB0sZVzU5ebyBnTAtCy558WgwhGM3eLsSCGjR00re5l8GWXyzgddp_CPdcHMZpZO-zoKlfG9yTP_hUx72cTTlC4_XQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (2679, '报纸', '让红色旅游真正“红”起来', '李晓良; 陈静', '中国旅游报', '中国旅游报', '红色旅游;红色旅游区;红色旅游资源;', '今年两会上，红色旅游成为关注的热点，记者采访了部分人大代表和政协委员，他们畅所欲言，就全国发展红色旅游积极建言献策。 人大代表、百色市委书记梁春禄：“红”“绿”结合有出路 “今年头两个月，百色旅游业持续火爆，游客人数比去年同期增长了近一倍，经济效益、社', '2005-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID6_HZSHG0Pl8N8jdMm7UDinggFfMliASekjN2_Iwq-AEDXAJoDqeFciIXpw17iTdGZMBy3dGPI2Ey1SbD0sB1ae4fjSCt5RggjnLo5PPMZ_HL6PQvl66_NeFV-55uUEgmgVZLkGMTz_Q==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2680, '报纸', '为挽救党和红军做出了重要贡献 张闻天', '', '人民日报', '人民日报', '张闻天;中央政治局;', '张闻天，1900年8月生，上海浦东人。1925年加入中国共产党，同年赴苏联莫斯科中山大学、红色教授学院学习，1930年回国，1931年任中共中央宣传部部长，临时中央政治局委员、常委。1933年到达中央革命根据地，任中央政治局委员、中央书记处书记，1934年参加长征。 在长征中', '2005-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBE2R2jw7lH2zFjm5AGp8aQhpAjdGXJ4mnC0cl5HPRr2Y_gPnKY06Slj-YlBSH16pcUsVesny3GAlYuUuFrkzMOBGgYAyT-KkdrLkF70aWUqrFxPcxKA7dm3sbO7VLA9hjFydIA-UljyA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2681, '报纸', '红色的遵义　绿色的遵义', '柳路', '光明日报', '光明日报', '中心城区;山水园林城市;', '1935年1月,中国工农红军长征到达贵州遵义,召开了政治局扩大会议,这就是举世闻名的“遵义会议”。这次会议确立了毛泽东同志在党和红军中的领导地位,在紧要关头,挽救了党,挽救了红军,打开中国革命新局面。此后,毛泽东高超的军事指挥才能再次得以施展。强渡乌江、娄山关战役、遵', '2004-11-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAkK4f0XKF6SJAAIXk37BJJt4U-iMxt384b8YnIEzAbUiGvoVDp1y8kwXfiGY74ZZSzoJ4lxs9cMmcIGcuul51JVpzJroUJpN8YaVMVpTvyzd51OoDuB0WHamCI6D1QwFkzL27AwKfGIg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2683, '报纸', '加强党史研究 实践“三个代表”', '', '光明日报', '光明日报', '“三个代表”;新民主主义革命;中国共产党领导;中央党史研究室;中国共产党历史;江泽民同志;民主革命时期;党的历史;中国共产党成立;毛泽东思想;当代中国研究所;', 'F与时俱进的党史新著E 　《中国共产党历史》第一卷是在1991年出版的《中国共产党历史》上卷的基础上，经过全面修订、增编而成的。 《中国共产党历史》上卷，是在胡乔木、胡绳同志直接指导下编撰的，比较全面集中地反映了20世纪80年代的党史研究水平和当时对', '2002-10-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBDLhGk4I7wI6CFjmKZanIswsYr_KUANu4oS5ihfgbz-kWgqf9Sg4WKnvugIlg3x3p6uJNAU_wcMSXMFVq58WbpkjoPgdfjVejMOnhmUJyMGK8SI-XUBZ9JCuD_HM5bQ94qAIJcRjwjtg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2686, '报纸', '《中国共产党历史》第一卷出版', '', '人民日报', '人民日报', '中国共产党历史;《中国共产党历史》;共产国际;', '新华社北京9月27日电　在中国共产党第十六次全国代表大会即将召开之际，中共中央党史研究室隆重推出《中国共产党历史》第一卷，向进入新世纪后党的第一次盛会献上一份厚礼。 《中国共产党历史》第一卷，记述的是1921年至1949年中国共产党领导中国新民主主义革命的历', '2002-09-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAAbGkQ1XcAToaWthiLoowktkvABL-_tYrNELZoUKxown_2mY8uOGnS-Omy5AXq7nJ9hPG11KDHQwzGrr-2CqkNiMltQnT9WI5O-kag3hOTHSS_SbPd3AtlNevgo9KLxd-DpXzIEQaHHw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2688, '报纸', '国防大学在遵义会议会址建教学基地', '李刚; 郭嘉', '新华社;', '人民日报', '国防大学;教学基地;', '本报遵义9月4日电　新华社记者李刚、本报记者郭嘉报道：经中央军委批准，人民解放军国防大学在遵义会议会址处建立教学基地。今天，国防大学400多名将校学员在遵义会议会址处举行教学基地揭牌仪式。 国防大学选择在党的十六大召开前夕，赴革命历史名城遵义开展这项活', '2002-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAqKlx8GqvaO9ZD4Uvn_KgHhUKymQPpKw-ih-j77prP1zzVfCj4C3F_bOefF22tm-Dw3IfyltdoapFsGtof2T2hAkBZcFApaMaZ2kLQZojW7TISn3MKya1YeJsQZRtPbu4YZqT4sVRlQA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2689, '报纸', '第八届“五个一工程”电视剧、广播剧入选作品简介', '', '光明日报', '光明日报', '大兴安岭;专题片;“五个一工程”;总政治部;吴登云;广电总局;张大民;公安干警;无私奉献;广播剧;方志敏;戏曲片;作品简介;', '电视剧  《长征》（24集）广电总局  该剧从井冈山的第五次反围剿起笔，表现中国共产 党领导中国工农红军在逆境中战略转移、经遵义会议解 决领导权和斗争指导方针问题、爬雪山过草地完成震惊 世界的二万五千里长', '2001-10-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC5vN8syVu9KJVEnQTpmhHFf7bFivvBNEnB38SaBwtyJcFBqtTMWc5S8qjRUAvUGJ8R966mmZRBaaZ09f2K407--R9wKVWcy_fPS2RJ7l8Hn0qg_0WO6redbBac9QAyMLLIOEVRzY2NDg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2690, '报纸', '中央军委举行纪念陈毅同志诞辰一百周年座谈会', '罗玉文', '新华每日电讯', '新华每日电讯', '中央军委;新四军;座谈会;', '新华社北京8月23日电（记者罗玉文）中 央军委今天在人民大会堂举行座谈会，隆重纪 念久经考验的无产阶级革命家、军事家、外交 家，中国人民解放军的创建者和领导者之一， 党和国家的卓越领导人，中华人民共和国', '2001-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICUlSixaTj_GxUQZ2VmfWbqRu0MRMOrwFcRgSk84UkM9eqrbr8-rT5EvHQceAErzXy9wNuaVrpq-ASZLPDbNlsrN0I0GaAeesoQA4fN8LlnBk-g3f0-7WQAwymTOzHGCk1mZWaaw0Z5pQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,红四军_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (2692, '报纸', '丰碑永矗天地间', '曲志红; 李术峰', '新华社;', '新华每日电讯', '老一辈无产阶级革命家;中国共产党人;马克思主义与中国革命;毛泽东思想;陈云同志;周恩来;刘少奇;', '“我们深切怀念为中国的 革命、建设和改革，为中国共 产党的建立、巩固和发展作出 重大贡献的毛泽东、周恩来、 刘少奇、朱德、邓小平、陈云 等已故的老一辈无产阶级革命 家……”  这是江泽民总书记在庆祝 中国共产党成立80周', '2001-07-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDjNSMfs_-abefV_3fOFLNVF9SIAQ9nsax9Dd5WBPX47DcgXJJoO-PHZ8bkhfh5zdpMJkoA0k0tCcMMnc98mFpUCuIPT6ZqS9nm5Gh7buaCXJvt-DeebMPUnddG2ZyUJnn5fuBo4QDkuw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2693, '报纸', '中国共产党80年20件大事', '', '新华每日电讯', '新华每日电讯', '社会主义初级阶段;全国代表大会;抗日民族统一战线;中国共产党;人民解放战争;澳门问题;国共合作;国民党反动派;毛泽东思想;北伐战争;帝国主义;国共两党;', '新华社北京6月30日电：新华通讯社 最近约请中共中央党史研究室专家，评出 中国共产党成立80年20件大事。这20件 大事是：  1．中国共产党成立  1921年7月，中国共产党第一次全国', '2001-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICycH0GqWgF247lzM6cIYo2tnEpygBizAogh8wRSGtesnQ8ys7rDqT0r4dgyAMCdhouK2TI4-P11Sd2VEkRqGa0_Mx56eVbV0NVFrhFpalhECTFdzaDtFXcsBvghVlNP-IUZZHjQsdUSA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2695, '报纸', '长征和遵义会议的历史文献面世', '曲志红', '新华每日电讯', '新华每日电讯', '共产国际;中央档案馆;历史文献;', '新华社北京6月24日电（记者曲志 红）一份迄今最具权威性的关于红军长 征和遵义会议的历史文献，将在建党80 周年之际由《党的文献》杂志公开发表。 这份1935年10月15日陈云向共产国际 执委会书记处报告中央红军长征和遵义 会议情况的俄文记录稿', '2001-06-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICC2m2b1muDyfAjpegcurazHMdZa0D2R4500zrK5wTORGUNB_rv37mZOljZn6tHtWz31AB14nEJDYK7uNER9fNrcEEpgMlJrKYg-eOhzOnPG7XqfmsLuylUELsTK7fimqNrhhhUaRxLlw==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2696, '报纸', '走进史诗般的瑰丽长廊', '吴坤胜', '人民日报', '人民日报', '长廊;史诗;叙事诗;', '走进中国革命博物馆一楼 展览大厅，眼前骤然一亮：天 花板被装饰成高远的蓝天白云。 “苍穹”顶下，中共一大会址、 遵义会议纪念馆、延安宝塔山、 庄严的天安门、上海浦东新区、 香港回归交接仪式……18张巨 型彩色图片被灯光映照得熠熠', '2001-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAEtNVVKC5OMsw8aB9zneLB-DNN6eDWmg-tR6PvSly89Y3MaxxyfePJRM014olpViEXqtWh9TV1vRhq3GQjloOQH_eHVggsnI89KZIWL5h8vgcuTX9k5oDpp1hZB9z4_rezTRCowW3fpQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2697, '报纸', '永远的怀念', '夏伦勤', '中国教育报', '中国教育报', '陈云同志;怀柔县;《参考消息》;', '“学师范的 就应该当教师”  陈伟华喜欢当教师，与中小 学老师的影响分不开，她曾多次 在作文中把当教师作为自己的志 愿。苏联影片《乡村女教师》她 百看不厌。她喜欢这部电影，喜 欢瓦尔瓦拉，', '2001-06-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICOD2c578omSwF0K8EKf_3u0dGyHG-M7dkPPLrvRuCiz3oAswKjIefdjyPMbjOPv5E3UjXx8go9bjpNfs3CxCP4s11IV8eOjMfA1krpDMsdrhPri6Yy1zrqBgTaKRJHNX5uBqJvcKDDvQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2699, '报纸', '五彩缤纷遵义行', '付小悦', '光明日报', '光明日报', '桐梓县;娄山关;生态示范区;', '建党80周年前夕，记者 专程来到革命圣地遵义，走 访了遵义、赤水、习水、仁怀、 桐梓、娄山关等地。在遵义采 访的一周里，自然界五彩缤 纷的颜色固然深深打动了记 者，而更令记者沉醉的，则是 遵义这', '2001-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAhcr8PMAP-bEh6HnqfeHmpChpphoZQHFPI3-Sxnub9J9EA4SqqlUKWdQdJKaykYy3dcT6g2LPnDjc43c3SE7B6hr50zZOqUP4GEuY_I_u41U2N-SiXFD9ylIVDeqbtLnmigKj60704Xg==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2701, '报纸', '长征热土腾热浪', '刘志强', '科技日报', '科技日报', '仁怀市;国酒茅台;习水县;国酒门;竹产业;', '上个世纪30年代，中国工农红军进行的 二万五千里长征是中国革命史上最光辉的篇 章，长征中的“遵义会议”是我党我军历史上的 最重要转折点，“四渡赤水”战役是遵义会议 后，红军取得战略转移的决定性胜利之战', '2001-05-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDv_5psYZye26RFagMhS-nO5SoLmRxVlyiQLfc5peqovDJ_30bpfhq4RDuOH3gEGX4s4WiOhzycM82M4su0bCKsciNZFo_j9aYYRLleIumfClWDmE1aw3_xhCCYVfk9V1pPoV0n0CTdfQ==&uniplatform=NZKPT&language=CHS', '遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2702, '报纸', '20世纪影响中国历史进程的20件大事', '', '新华每日电讯', '新华每日电讯', '帝国主义;抗日战争胜利;中国共产党;中国历史进程;', '新华社北京12月29日电：在征求中国 社会科学院部分专家、学者意见基础上， 新华通讯社最近评出20世纪影响中国历 史进程的20件大事。这20件大事是：  1、八国联军侵华和辛丑条约签订， 使中国完全变成半殖民地半封建社会 （1900年—1901年', '2000-12-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAv6vzYi4SgRJ4OWVi3XFbGN2pyaIj_tDFv0mB1HiNzSc6VjxkmCfEM9w3QeidALXmXo7qUiJD64SKLsPv5ZNtFOk_3K-6L8CHipBCxVxUr9No5I1dUpVfthHpsdMCrLwpjQsBQPbE0YA==&uniplatform=NZKPT&language=CHS', '遵义会议_screened');
INSERT INTO `ds_article` VALUES (2703, '报纸', '丹青绘彩新时代', '薛鹏', '中国纪检监察报', '中国纪检监察报', '美术馆;美美与共;老艺术家;主题展览;经典作品;习近平总书记;大众美育;美术事业;时代文艺;', '“中国美术馆有力见证了新中国美术事业的蓬勃发展，在典藏精品、展览展示、公共教育、对外交流等方面守正创新，取得了积极成效。”5月21日，习近平总书记给中国美术馆的老专家老艺术家回信，在中国美术馆建馆开放60周年之际，向全馆同志致以热烈祝贺和诚挚问候。 中国美术馆', '2023-05-31 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.001905', '强渡大渡河_screened,遵义会议_screened,血战湘江_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2704, '报纸', '礼赞时代 与美同行', '田呢', '光明日报', '光明日报', '美术馆;美术作品;吴为山;艺术家;长征精神;主题展览;写意艺术;', '仿古阁楼式主体建筑上铺黄色琉璃瓦，四周廊榭围绕，这座具有浓郁民族特色的建筑，已经在北京五四大街上迎送观众整整60年。1963年5月23日，由毛泽东主席题写馆额的中国美术馆正式开馆并对公众开放。悠悠一甲子，作为新中国成立后创建的国家造型艺术博物馆，中国美术馆60载的发', '2023-05-28 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.002435', '强渡大渡河_screened,血战湘江_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2705, '报纸', '凡人英雄', '韩亚栋; 柴雅欣', '中国纪检监察报', '中国纪检监察报', '石棉县;泸定县;救援队伍;救援力量;消防救援;海螺沟景区;跃进村;磨西镇;紧急医学救援;直升机;飞夺泸定桥;次生灾害;消防员;强渡大渡河;受灾群众;', '“泪目了，总是被中国人平凡而伟大的故事所感动”“这个故事中，有太多让人感动的人：没有放弃希望的救援队伍，一大早醒来就去找人的村民……”这两天，震后失联17天的水电站员工甘宇获救的消息，感动着方方面面的人们。 四川泸定地震发生后，大渡河右岸一级支流湾东河沿岸', '2022-09-24 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.003948', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2706, '报纸', '乡村游要规避同质化', '于帆', '中国文化报', '中国文化报', '乡村游;旅游线路;红色文化;同质化;', '近年来，乡村休闲游正在从“小生意”变成“大产业”，人们对于曾经乡村游单纯的“农家乐”印象也在不断改观。 旅游博主雨融YUKON以自己的观察告诉记者，让人印象深刻的乡村游分为两种类型，一种是将曾经落后贫困的古村结合村落原本具有的特色风俗文化，吸引了很多游客前来。', '2022-08-13 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.002653', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2707, '报纸', '牢记初心使命 凝聚奋进力量', '窦皓', '人民日报', '人民日报', '红色文物;展示馆;中国共产党历史;展览馆;习近平总书记;', '习近平总书记强调：“红色资源是我们党艰辛而辉煌奋斗历程的见证，是最宝贵的精神财富。”本版刊发有关文章，讲述中国共产党历史展览馆等场馆和馆藏文物背后的故事，展现红色资源蕴含的精神财富，总结新时代革命文物保护和利用的经验。 ——编 者 用心用情用功办好百年党史', '2022-07-02 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.006947', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2710, '报纸', '“红军是英雄好汉”', '杜敦科', '贵州省中国特色社会主义理论体系研究中心;', '解放军报', '长征路;红四方面军;长征精神;红军战士;红军长征;战略战术;习近平总书记;', '1935年12月，毛泽东同志在谈到红军长征的伟大意义时，明确指出：“红军是英雄好汉。”这是对红军将士的高度评价。自1934年10月至1936年10月，在两年时间里，红军纵横十余省，长驱二万五千里，完成了人类军事史上史诗般的伟大远征，是当之无愧的英雄好汉。天地英雄气，千秋尚', '2022-02-07 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.000599', '强渡大渡河_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2711, '报纸', '遵义会议精神永放光芒', '', '中国民族报', '中国民族报', '遵义会议精神;毛泽东;党中央;共产国际;习近平总书记;', '从建党到建立新中国，中国共产党走了28年，时间轴中点落在1935年。这年召开的遵义会议，在党的历史上是一个生死攸关的转折点。 习近平总书记深刻指出，“遵义会议作为我们党历史上一次具有伟大转折意义的重要会议，在把马克思主义基本原理同中国具体实际相结合、坚持走独', '2021-12-03 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001243', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2713, '报纸', '出发地，再出发', '沈锡权; 李兴文; 高皓亮', '新华社;', '新华每日电讯', '营商环境;赣州市;习近平总书记;水质达标;红色记忆;', '倾听历史回响，追寻红色记忆。 江西赣州是一片遍洒英烈鲜血的大地。2019年5月20日，习近平总书记在赣州市于都县中央红军长征出发纪念馆外的广场上深情寄语：现在我们正走在开启建设社会主义现代化国家的新征程上，我们要继往开来再出发! 启新程，多壮志。 初冬时节', '2021-11-30 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.009149', '强渡大渡河_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2715, '报纸', '深入学习贯彻党的十九届六中全会精神 努力做好决策咨询工作', '马建堂', '国务院发展研究中心;', '中国经济时报', '习近平总书记;毛泽东;中华民族;中央领导集体;新民主主义革命;中国共产党领导;有中国特色的社会主义;邓小平同志;武装斗争;党中央;国家治理体系;决策咨询;六中全会;', '党的十九届六中全会是在中国共产党成立一百周年的重要历史时刻、“两个一百年”奋斗目标历史交汇的关键节点召开的一次重要会议。会议审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》（以下简称《决议》），深刻总结了我们党百年波澜壮阔、气壮山河的发展历', '2021-11-29 08:00:00', 'https://link.cnki.net/doi/10.28427/n.cnki.njjsb.2021.002602', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2718, '报纸', '红色旅游带动老区换新颜', '李冰洁', '人民政协报', '人民政协报', '红色旅游;长征路;经典景区;精品线路;', '说起革命老区，你心中是什么印象呢？ 有人可能会想到雪山草地，有人可能会想到黄土高坡，也许还有人会想到一个词——“老少边穷”。 但是我要告诉你，革命老区如今已然换了新颜。跟随全国政协视察团考察长征国家文化公园建设这三年里，我们看到长征沿线革命老区在红色', '2021-11-05 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.008540', '强渡大渡河_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2719, '报纸', '地图科技赋能红色遗产保护', '王诒卿', '中国自然资源报', '中国自然资源报', '长征路;长征文化;中国地图出版社;文物保护;红色遗产;', '85年前的10月，中国共产党领导中国工农红军完成了举世瞩目的长征，历时两年，纵横十余省，行程两万五千里。近年来，随着红色旅游不断升温，江西于都、贵州黎平、四川古蔺等红军长征沿线举行了形式多样的“重走长征路”活动。参观者走红军路、听长征故事，红色教育入情入境、', '2021-11-01 08:00:00', 'https://link.cnki.net/doi/10.28291/n.cnki.ngtzy.2021.003607', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2721, '报纸', '“互联网+长征”：万水千山在云端', '单慧粉; 吴晓婧', '解放军报', '解放军报', '文物保护;贵州遵义;强渡大渡河;红军强渡大渡河遗址;', '10月22日，贵州遵义东风小学，纪念红军长征胜利85周年研学活动如期举行。在老师的指导下，五年级学生李子玉通过手机和投屏，与长征展开“亲密接触”。 由国家文物局组织开展的“互联网+长征”教育体验示范项目上线百日，已在网络上掀起“云游长征”的热潮。不用前往现地，', '2021-10-27 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006777', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2722, '报纸', '走好新的长征路', '郭权祺', '团结报', '团结报', '长征路;敢于胜利;疫情防控;', '层林尽染秋意浓，天已渐凉。本周，强冷空气来势汹汹，全国多地最低气温跌破零摄氏度，瑟瑟凉风让不少人裹上了冬衣，纷纷调侃天气堪称“垂直入冬”。 本周，与气温下降一同来得“突然”的，还有国内新一轮新冠肺炎疫情。截至目前，疫情已波及陕西、宁夏、内蒙古、北京、甘', '2021-10-23 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.002015', '强渡大渡河_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2724, '报纸', '勇士传人高擎光荣战旗', '吴俊杰; 周俊谊', '解放军报', '解放军报', '大渡河连;长征精神;', '长征是人民军队的光荣。在那场伟大的远征中，红军将士用生命和鲜血铸就伟大长征精神，涌现众多英雄模范和英雄部队，写下壮阔的英雄史诗。时光荏苒，当年“大渡河十七勇士”所在的“大渡河连”，如今已是闻名全军的英雄部队。几十年来，他们发扬长征精神，让红色基因融入官兵', '2021-10-21 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006673', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2725, '报纸', '红色文旅人气旺', '王珂', '人民日报', '人民日报', '红色旅游景区;讲解员;旅游景点;红色文化;精品线路;', '核心阅读 依托革命旧址、纪念馆、博物馆等革命传统资源发展红色旅游，既能满足人民群众出门旅行、领略祖国大好河山的美好需求，又能满足人民群众追寻先辈足迹、传承红色基因的强烈愿望，正成为旅游发展新亮点 从上海中共一大纪念馆到浙江嘉兴南湖红船，从贵州遵义会议', '2021-10-20 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011004', '强渡大渡河_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2726, '报纸', '独立自主 敢闯新路', '黄玥; 李惊亚', '新华社;', '新华每日电讯', '遵义会议会址;中国共产党;修正错误;遵义会议精神;坚持真理;毛泽东;共产党人;习近平总书记;', '遵义会议，中国共产党百年历史中的关键“章节”。 86年前，在位于遵义市子尹路的柏辉章公馆里召开的会议，在最危急的关头，挽救了党、挽救了红军、挽救了中国革命。 在探索中反思，在绝境中奋起，在挑战中开拓。遵义会议铸就的精神跨越时空、历久弥新，指引着中国共产', '2021-10-19 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008003', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2727, '报纸', '伟大转折 胜利之光', '李锦; 朱宏博; 易恢荣', '解放军报', '解放军报', '遵义会议精神;中央红军;政治局扩大会议;', '中央红军长征路线，蜿蜒曲折，在黔北打结，又在黔北解扣。贵州省遵义地区就在结扣的中间。 深秋，遵义老城，枫叶正红。在红花岗区子尹路96号，一幢灰白相间、中西合璧的二层砖木小楼临街而立，东侧耸立着一棵老刺槐，苍劲挺拔。86年前，党中央在这里召开政治局扩大会议，', '2021-10-18 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006561', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2729, '报纸', '令人回味的“意外之喜”', '乔松柏; 高杰; 李建文; 唐浚', '空军报;', '解放军报', '政治教员;思想政治教育;讲课比赛;', '政治干部这么看—— 教育不走心，官兵心就走 听完助理工程师王卓那堂题为《少年自有少年强，敢将日月再丈量》的课，某连指导员刘长鸿感觉自己“内心最柔软的地方被戳到了”。 课上，王卓深情讲道：“我曾经跟一些新兵、新干部聊天，他们偶尔会说起找不到当兵的意义', '2021-09-15 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006007', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2730, '报纸', '四川：在红色热土上讲好红色故事', '周洪双; 李晓东', '光明日报', '光明日报', '红色旅游资源;博物馆;长征路;中国工农红军;主题活动;川陕革命根据地;红色文化;讲解员;强渡大渡河;', '从春往秋走，红色旅游在巴蜀大地上逐渐走俏走红。 今年4月，四川省“重走长征路·奋进新征程”红色旅游年在全省同时启动。启动仪式的会场设置，充分展现出四川是一片广阔的红色热土——主会场设在雅安市石棉县安顺场纪念广场，分会场分别设在巧渡金沙江纪念地凉山州会理县', '2021-09-15 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.004768', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2731, '报纸', '坚定理想信念是终身课题', '贺霞', '国防大学习近平新时代中国特色社会主义思想研究中心;', '解放军报', '理想信念;年轻干部;忠诚于党;', '在2021年秋季学期中央党校（国家行政学院）中青年干部培训班开班式上，习主席明确把信念坚定、对党忠诚作为年轻干部练好内功、提升修养的第一位要求，强调“坚定理想信念是终身课题，需要常修常炼，要信一辈子、守一辈子”。这是从民族复兴伟业战略高度出发，着眼党和国家事', '2021-09-09 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.005886', '强渡大渡河_screened,血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2732, '报纸', '当好主心骨 蹚出发展路', '王明峰', '人民日报', '人民日报', '中国工农红军;李锡林;黄果柑;党员干部;民宿客栈;村党组织;党总支;村两委;战斗堡垒;村干部;红色基因;强渡大渡河;', '初秋时节，凉爽宜人。川西高山峡谷中的安顺场，天高云淡，大渡河湍急奔流。河畔的中国工农红军强渡大渡河纪念馆里，游客们沉浸在讲解员的深情讲述中。 安顺场位于四川省石棉县，1935年5月，红军长征途中，就是在这里强渡大渡河，开辟了一条北上通道，书写下中国革命战争史', '2021-09-07 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.009531', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2733, '报纸', '巴山蜀水共振兴', '何欣禹', '人民日报海外版', '人民日报海外版', '中国工农红军;红军不怕远征难;飞夺泸定桥;三线建设;水磨古镇;彝海结盟;西昌卫星发射中心;精品线路;红军长征;', '四川是一片充满红色印记的革命热土，红军长征时，在这里历经时间最久、走过路程最长、所涉地域最广、经历战斗战役最多。数十万四川儿女为民族独立、人民解放献出了宝贵生命。新中国成立至今，四川人民勇于奉献，积极改革，实现了一个个建设成就和乡村脱贫传奇。 在建党百', '2021-08-26 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002638', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2739, '报纸', '长征：一部读不尽的百科全书', '张科进; 洪大鹏', '解放军报', '解放军报', '百科全书;长征精神;', '记者：著名作家魏巍于1987年创作了长篇小说《地球的红飘带》，他把长征所走过的路形象地比喻成地球上的红飘带，非常具有革命浪漫主义精神。可能许多人没有注意到，红飘带其实是4条，能否介绍一下？ 专家：没错，长征是在党中央“北上抗日”的旗帜下，红一方面军（中央红军', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004834', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2740, '报纸', '“时空隧道”激励奋进力量', '周珊珊', '人民日报', '人民日报', '时空隧道;展览馆;长征路;', '从空中俯瞰，“工”字形建筑端庄大气；西侧广场上，鲜红的《旗帜》雕塑气势恢宏；走进展馆，砖木结构、雕花门头的中共一大会址复原模型引人驻足……最近，中国共产党历史展览馆正式面向社会公众开放，“‘不忘初心、牢记使命’中国共产党历史展览”吸引众多参观者前往。', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007836', '强渡大渡河_screened,遵义会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2742, '报纸', '浴血奋战 百折不挠', '樊曦', '新华每日电讯', '新华每日电讯', '中国共产党;中华民族;共产党人;习近平总书记;红四军;民族独立;马克思主义;', '新华社北京7月20日电（记者樊曦）“一百年来，中国共产党团结带领中国人民进行的一切奋斗、一切牺牲、一切创造，归结起来就是一个主题：实现中华民族伟大复兴。”习近平总书记在庆祝中国共产党成立100周年大会重要讲话中，阐述了我们党百年奋斗的鲜明主题。 回望筚路蓝缕', '2021-07-21 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005552', '强渡大渡河_screened,飞夺泸定桥_screened,卢德铭_screened,张子清_screened');
INSERT INTO `ds_article` VALUES (2745, '报纸', '如何理解遵义会议重大历史意义', '', '解放军报', '解放军报', '遵义会议;中国共产党;毛泽东;共产国际;', '问：习主席在纪念红军长征胜利80周年大会上的重要讲话中指出，党中央召开的遵义会议，是我们党历史上一个生死攸关的转折点。对这一重要历史结论，应该如何认识把握？ 武警某支队参谋 李家军 答：1935年1月，党中央在贵州遵义召开政治局扩大会议，史称遵义会议。这次会', '2021-07-12 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004425', '强渡大渡河_screened,遵义会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2747, '报纸', '牢记嘱托，英雄传人谱新篇', '陈典宏; 郝晴; 吴俊杰', '解放军报', '解放军报', '大渡河连;野外驻训;英雄传;', '夏日岭南，热浪翻滚。第74集团军某旅“大渡河连”野外驻训地，一派龙腾虎跃景象，官兵个个如猛虎下山，奋勇冲锋。 “习主席‘七一’重要讲话，犹如战斗号角，给我们练兵备战注入了强劲动力！”训练间隙，连队指导员李泽凡就地组织官兵开展“学讲话、强本领、担使命”活动', '2021-07-10 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004400', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2752, '报纸', '精神丰碑，顶天立地', '张一琪', '人民日报海外版', '人民日报海外版', '精神丰碑;军需处长;', '红军长征过雪山途中，有这样一个故事—— 一个穿着单薄旧衣的战士，被冻死在雪地里。指挥员让人叫军需处长来，想问问他为什么不给这个战士发棉衣。队伍里的战士含泪告诉指挥员，被冻死的这个战士，正是军需处长。 管被装的宁可冻死，也没有自己先穿暖和一点。这个军需', '2021-06-19 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.001881', '强渡大渡河_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2753, '报纸', '忘记的是名利 铭记的是责任', '钟华林', '经济日报', '经济日报', '红军长征;强渡大渡河;孙继先;', '重走红军在四川的长征路，时时让人感动。其中有两个故事让人印象深刻。 一个是关于强渡大渡河勇士名单。强渡大渡河成功后，红一军团政治部出版的《战士报》对时任红一团一营营长的孙继先进行了采访。他提供了一份跟着自己冲锋陷阵的17人名单，却没有写上自己。所以“十七', '2021-02-04 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.001323', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2754, '报纸', '“彝海结盟”的扶贫新篇', '安普忠; 黄显文', '中央广播电视总台;', '解放军报', '彝海结盟;支援部队;', '【新闻回放】2018年2月11日，习主席乘车沿着坡急沟深的盘山公路，往返4个多小时，深入大凉山腹地的昭觉县三岔河乡三河村和解放乡火普村看望贫困群众。习主席指出，易地扶贫搬迁是实现精准脱贫的有效途径，一定要把这项工作做好做实。搬迁安置要同发展产业、安排就业紧密结合', '2021-01-17 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.000266', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2755, '报纸', '《苦难辉煌》：信仰的铁流', '何新恩', '湖北省商务厅;', '中国纪检监察报', '《苦难辉煌》;飞夺泸定桥;中国工农红军;共产党人;', '《苦难辉煌》一书，以长征为切入点，把中国共产党的早期历史放在追溯探寻国家命运和民族命运的战略高度来研究，放在国际大背景下来把握，把影响当时中国社会走向的不同主义、不同政治力量综合在一起，深度剖析二十世纪二三十年代中国革命道路上最复杂、最艰苦也是最具意义的', '2018-07-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA1dwY3Aq_ZgUHZZk6ysuqPpsaCYx4FNNlfXjNhuJDQY-QWopLrA3qp8VtXJwFZkGMz_0dJPmqVho-EkD_kpIDsklOxXWvEYC_SBHuhJakYkSs6STGXu6albdwMeiHl7k-5hhCSfAqj6w==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2756, '报纸', '伟业', '贾永', '中国青年报', '中国青年报', '国民党军队;红四军;三湾改编;毛泽东;秋收起义;新四军;南昌起义;根据地;长镜头;共产党人;前敌委员会;中央军委;', '走过硝烟，走过风雨，一支在战火中诞生的军队迎来第90个生日。 “八一”两字，热血铸就；猎猎战旗，写满荣光。 穿越90年时空，有这样10个长镜头，闪烁在这支军队筚路蓝缕的漫漫征途上。 长镜头一：诞生 1927年7月31日，农历七月初三，大暑第七天。正是“火炉', '2017-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB5XRE0WCIhYTEV1dePyYX-ctP7xOKwG2869cBN8SSoj1AC2MFsC05lEA6SCBdchJcj_CAVFg7jwxaZxG4HxF4-mm1KVekmw0x54getp9UsQOaBvdYFqIUM57pjO5HFyQgQVf1UNSq9lg==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened,红四军_screened,瑞金_screened,黄洋界_screened,秋收起义_screened,反围剿_screened,农村包围城市、武装夺取政权_screened,三湾改编_screened,王尔琢');
INSERT INTO `ds_article` VALUES (2758, '报纸', '《彝海结盟》：历史背后的精彩故事', '赵明仁', '中共四川省委宣传部;', '光明日报', '刘伯承;小叶丹;歃血为盟;《彝海结盟》;重大革命历史题材;中革军委;红军长征;', '编者按：由中共四川省委宣传部、中共凉山州委策划制作，近期在央视八套黄金时段热播的重大革命历史题材电视剧《彝海结盟》，创造了同期电视剧收视新高，为纪念红军长征胜利80周年宣传增添了一抹亮色，成为业界议论的热门话题。总结这部作品的成功之道，对重大革命历史题材创', '2016-11-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDBbVuOH-BmCzM26sz_NsXafzFGbJMs0evp-FyxCbL5ip1U7E_vRhN4Qp06NScJowFC0Ej-fPQz7Bt3R0ixx-dLkoIcUfkE6zOIPK7zP80bpdUdwG65MvlH8jsirD0fLSVunfE0uto8-w==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2759, '报纸', '勾连历史与现实', '刘玉琴', '人民日报海外版;', '光明日报', '李坚真;中国工农红军;长征精神;红军长征;历史与现实;', '纪录片《永远的长征》力求用8集篇幅浓缩红军长征全貌，以全景式视角再现那个艰苦卓绝的不朽历程。该片尽量涵盖中国工农红军各路部队的长征历程，不仅记录了湘江之战、四渡赤水、巧渡金沙江、强渡大渡河、飞夺泸定桥等壮举，也勾勒了留在根据地的红军队伍和游击队，在极端困难', '2016-11-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB_9kF0CWLu-Sxjbv-RYDbu58C53btebPtXx3--dvnS7f_W8CJLzP5xQIVT_UKm1mokioQe4Oy0cdTmRCq070Q5leB_2HmP97MBh2ZCsNWCljvwfDplGV8CwaSargB0UITZ9Xqyydd9GQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2760, '报纸', '越接近民族复兴梦想 越要加强党的建设', '', '解放军报', '解放军报', '加强党的建设;民族复兴;新的伟大工程;', '一次危难中的战略转移，却成为一次彪炳史册的胜利进军。长征的胜利，首先是中国共产党领导的胜利。正如毛泽东所指出的：“谁使长征胜利的呢？是共产党。没有共产党，这样的长征是不可能设想的。”弘扬伟大长征精神，走好今天的长征路，必须加强党的领导，坚持全面从严治党，', '2016-10-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAEIQ-MNvcUQ67LAWRlKZREexsQRQW0nd90s1s5r4eou9MjThlfhNdXwPeCQQA3DTctA3RcZY7Jwr85_kBeMQS9L3MgmAUTiKO1WGuC_rabB5WiKvAV9zFLfD1O4ZOLR1E-llaVJhYSjg==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2761, '报纸', '强国必须强军 军强才能国安', '', '解放军报', '解放军报', '人民军队;红军长征;', '“强国必须强军，军强才能国安。”红军长征胜利充分说明了一个真理：建设一支听党指挥、能打胜仗、作风优良的人民军队，始终是革命的依托、民族的希望。 一次次历尽艰难险阻，勇往直前；一次次突破生死危难，浴火重生。长征使一个政党走向成熟、破茧蜕变，也使一支军队走', '2016-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBa0tRvckxM4VlAcCc_AKKjjzuvwaIRCbN5betpMp4ZGTsXCSi7dNZsovr1CnCCyW76X7seCHEx7UL5J75BKFyl5Ma9IOI6yqwT93CfRIWvj7h-9TDeIVSDy1o6DLhX-ICZl5R7q2bDlg==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2763, '报纸', '在纪念红军长征胜利80周年大会上的讲话', '习近平', '人民日报', '人民日报', '长征胜利;根本保证;长征精神;中国共产党人;', '同志们： 今天，我们在这里隆重集会，纪念中国工农红军长征胜利80周年。 红军长征的那个年代，中国处在半殖民地半封建社会的黑暗境地，社会危机四伏，日寇野蛮侵略，国民党反动派置民族危亡于不顾，向革命根据地连续发动大规模“围剿”，中国共产党和红军到了危急关', '2016-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBh7V_3ir5r2xi5ASoYT5uXwCi9788SE_0_D2W2fKtv74AKnu1dL4RZs9CWVcd3W_LeIjHGXTCPks-L_o3VGqCiJ6NsJm466bt7eo-o7uc7PKzqxXz6KQKilLAiVhAPNGc2L0b7KXNxSg==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2764, '报纸', '从长征精神读懂中共“为什么能”', '张远晴', '人民日报海外版', '人民日报海外版', '长征精神;习近平;', '近些年来，与一些海外朋友聊天，“中国共产党为什么能”这个话题总是备受关注。一个95岁、拥有8800多万党员、领导着一个13亿人口大国的政党，让中国从一穷二白成为世界第二大经济体，使中国成为世界舞台上的一个重要力量。中共是怎么做到的？有什么秘笈？ 一种观点认为，', '2016-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB0QjhgolxsmdZlx6gXroIQji15aYjtIAnMXt5arfXvmFP02ssBdEMfkV2C4ckkBDr3ftm2cClh-CNj0Rt7SR5IiWIqO2e570I_-eUkoX_Z9atKcAbsDGpPGW8hFkdTYLBQcOPg98hRLQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2765, '报纸', '推进中华民族伟大复兴的新长征', '', '光明日报', '光明日报', '中华民族伟大复兴;长征精神;马克思主义基本原理;', '今年，是中国工农红军长征胜利80周年。 80多年前，中国共产党带领中国工农红军战湘江、过赤水、巧渡金沙江、强渡大渡河、翻越雪山、跋涉草地，用两年的时间走完了二万五千里的艰辛征途。两年中，这支红色队伍翻越30余座大山、渡过20余条河流、转战14个省份，写下了一部荡', '2016-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDrECvNkk18uL2KPUIcz6QEP4VHjdrwaNLTdKBAaqG5HbJg8yQhptj0UJQxIzvvpm_YkEQJs7OSlcrNWvzMxN7Ev-aQmKk3ou1aIiANliTv3JDhHjRBRfky3KdZGfrBmMsfh42Y7YNCUQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2767, '报纸', '永远的制胜之道', '严德勇; 王卫东', '解放军报', '解放军报', '红军长征;战斗精神;信息化战场;中革军委;泸定桥;国民党军;战略战术;实战化训练;星夜兼程;', '向红军学打仗学指挥，继承“活的灵魂”是根本 历史样本 “有时向东，有时向西，有时走大路，有时走小路，有时走老路，有时走新路，而唯一的目的是为了在有利条件下，求得作战的胜利。” ——1935年2月16日党中央、中革军委发布的《告全体红色指战员书》 样本', '2016-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBbINaCCeCT0QVbnfD_3jTkjiLa1pwSZyyhp6ww8Uz-wFXM9uqeICQhqH8I1zeuxRuQdKUcaaZPXPtvUQpYocc78bqN-MTOZleZnpiI7WgxqzBQ075ov7Z4-xylwZpjLZwCWuao9_yvYQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2768, '报纸', '新长征路上的心灵告白', '', '解放军报', '解放军报', '国防和军队改革;长征精神;现代战争;长征路上;红军长征;改革强军;历史自觉;', '深掘宝贵财富 褚银 80年的时间距离为我们提供了一定的历史意识，摒弃虚伪造作，摒弃概念图解，在历史严峻的目光下，深深开掘这个宝贵精神财富，化为我们不竭的力量源泉。 一部长征的历史，就是一部用生命写就的壮歌；一条二万五千里的长征路，就是一条浸透热血的', '2016-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICU-6E6ZzZwwzOqbH6NVIuKcsDA-ukBpTd4glgwUajtKLlD5gvHRBNJEa95yTA37q7rW_XkliEL5CWqtk7mYHI5_L-HGDhFjNnmoMx-eFhWQj8RnkDQ39Yx7PfTW6jzOKtKQHXlONnr4Q==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2769, '报纸', '重温长征精神 汲取红色力量', '夏小童; 徐斐; 温才妃', '中国科学报', '中国科学报', '长征精神;思想政治教育专业;', '“正是长征路上革命先辈们的壮烈牺牲，才铸就我们今天的美好生活”“我们要站在前进的船头，唱响正义的歌曲，抵制诱惑，而这正义歌曲的主旋律就是中国特色社会主义!”……短短两小时内，饱含深情的演讲让教室内爆发出了经久不息的掌声。 10月13日，耄耋之年的老党员、西南', '2016-10-20 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2016.001222', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2770, '报纸', '在群众的海洋里最安全', '', '解放军报', '解放军报', '红军长征;', '红军长征是一次决定存亡命运的远征。途中，生与死的考验不断一时一刻，险与难的阻挡不啻万水千山。然而，强敌之追堵、河山之险固、给养之困难、病疫之交侵、霜雪之严冷，始终未能让红军停下脚步。这支军事上无后方、无依托的军队能创造万里转战的奇迹，离不开群众这片最安全', '2016-10-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBCMUwc9XfGHV-PHUke8wxKA56g7BIhLZ6MxAgOmccV5_HefxJWP3VtfEITtaNv3RvrgMeSOBQJNJVjrTSWsZgkVYsOHNDpBUPCcppMD1PKb67zUiiWptZ1ZPgO3AWrl4vsOb2A5_cAMw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2771, '报纸', '每一个壮举都是英雄传奇', '', '解放军报', '解放军报', '革命英雄主义;', '这是一次勇于牺牲、敢于胜利的史诗般远征。跋山涉水，征服无数天险；枪林弹雨，留下血色苍茫；气贯长虹，铸就不朽传奇。 胜利有多辉煌，牺牲就有多壮烈。两万五千里，步步关生死。每300米就有一名红军战士倒下，每12人只有1人能到达目的地。湘江一役，13名团以上干部牺牲', '2016-10-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID0TPZ1UZfdlJVJ7HMMH9RAfrS_dvDE82wOyNuboyZOvKRE9ls3dFfDP7jDxMXbHozVA1OXJrwmJpBoPtnVQ1kExZHXDA8SRT11Z7JXXE9HmZ3tdp0vKtfI5IHbXLIxgt82g2WElNQiNw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2772, '报纸', '弘扬伟大长征精神 走好新的长征路', '', '解放军报', '解放军报', '长征精神;', '伟大的事业呼唤伟大的精神，伟大的梦想需要伟大的力量。 习主席在参观“英雄史诗 不朽丰碑”主题展览时的重要讲话，高度评价了红军长征的伟大意义，深刻阐明了弘扬伟大长征精神的时代需求，为走好新的长征路指明了方向。 80年前，中国共产党领导中国工农红军战胜无数', '2016-09-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDOM8L62uS8kSiSwg751qnMZiq-oRV301W6bBLGXXvBG1A8Pu_x51ID0nDsL585VPRiqR7ij9241nD3aX1vDQGntEFrWLXuQcFAry1F-PzcxfGK475xL7zbBs03c7SVtaxo93iudjWskg==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2773, '报纸', '雄师阔步新征程', '樊永强', '新华社;', '经济日报', '中国工农红军;集团军;能打胜仗;红四方面军;长征路上;中央红军;红军师;团政委;共产党人;红四团;', '一次次历尽艰难险阻，勇往直前；一次次突破生死绝境，涅槃重生—— 80年前，中国共产党领导工农红军以无与伦比的英雄气概取得万里长征的光辉胜利，谱写了气吞河山的壮丽史诗。 从弱小走向强大，从苦难走向辉煌——作为人类历史上永垂不朽的精神丰碑，长征，塑造了人', '2016-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICqDn3F4tn0o7hUmJWlOTxGCGz0ZAHKu2ZJ4HwJUDc76u08OUYjIlmN23Hx5cWCrUKyb5x5KmBvOOrlROmnjCj8BdZDx2SVAWZhrVN3qzYC9w04RLGTU9H0NE-vEe0Kz6S5dLphEC5_bw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2774, '报纸', '英雄,强国强军的时代呼唤', '', '解放军报', '解放军报', '时代呼唤;', '一个国家要强盛，不能缺少雄风浩气；一支军队要强大，不能没有铁胆侠骨。实现强国强军目标，离不开英雄精神，更呼唤英雄辈出。 “聪明秀出，谓之英；胆力过人，谓之雄。”英雄的魅力之所以穿越时空、历久弥新，是因为他们具备坚贞不屈的忠诚品格、勇于献身的崇高精神、', '2015-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDzIrV6QgPz5dY_wlX1cPjzNOWxURKHuw0KFx5SaoEMe1SEg5BJ6x41DuM-TF23XVJMoIVl1bZPbpaEKGPBYsQgm0Mxhi_LOd11c0C0qRs33hGHxbhX2fMsWipNabMEDrlxAKKg8ZAq4w==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2775, '报纸', '读好书使人登高望远心明眼亮', '', '人民日报', '人民日报', '星火燎原全集;马列主义经典著作选编;经典名篇;孙中山;登高望远;', '编者按：日前，中宣部理论局、中组部干部教育局向党员干部推荐了第五批学习书目，包括《马列主义经典著作选编（党员干部读本）》、《马列主义经典著作选编学习导读》、《从怎么看到怎么办——理论热点面对面·2011》、《孙中山传》、《星火燎原全集精选本》、《日出东方——', '2011-12-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICD7CppVciOjfhqHeYyJygnl8HPIAAXJD-rHWOnyXAnERcncjy1jFgc-6bvYRpXZbt53P8ZBBpwUnurobzy66eLVr5xEw5_ZbTViBGWWf6X4GSHR2DtbgVW2q1PdQF3M6Yb8WNDZg9BTw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2779, '报纸', '百岁老红军“一生的长征”', '蒋芳', '人民日报', '人民日报', '刘应启;扬州军分区;', '两次强渡大渡河、三过雪山草地，他是长征的参与者和见证者； 离休后写下１００万字的读书笔记，到各地作报告１０００余场次，他是革命传统的“播种机”； 走访贫困群众，资助失学儿童，百岁高龄的他仍参加志愿服务。 在人们眼中，百岁老红军刘应', '2011-05-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAcaMcUhxRRGNhnXJ4IkaWD5DB6Q4NxAa7MnbSsmNUhFCQneogjMLW9743ZWacaSvtwds7mCoj5qp5R6BTsRFVoUGjETRKlKiRY7ilg4rX5qConT8d0k4MKKiyO-1k8M56LGYuxBSaW3A==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2780, '报纸', '话剧《万水千山》青春再现', '张永恒', '人民日报海外版', '人民日报海外版', '陈其通;《万水千山》;显示屏;红军长征;', '“四渡赤水”、“爬雪山过草地”、“彝海同盟”、“强渡大渡河”……一幕幕场景以宏大的气势在湖南大剧院的舞台上展示出来，由中华文化促进会发起复排的红色经典话剧《万水千山》日前在长沙彩排演出便吸引了很多观众。“演出结束后，《万水千山》剧组将沿着红军长征路巡演。', '2011-05-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAU7G_cAA7rwe5xiRHe6Ttevwrzl03QuB0M5O8kvYqXm34W_VykQx2cLM2iVwE1f2RtyYhkAUcs2DW0tJPcec8-dw2wCV2SVYiSm4PRV99GZ8UnoyweIjFlzprPa4h59iFJ-FRTCUn8XA==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2782, '报纸', '跨越“数字鸿沟” 巴山蜀水尽开颜', '姚晓敏; 康伊 ; 李世敏 ; 晋美朗吉', '人民邮电', '人民邮电', '四川移动;村通工程;甘孜州;', '作为四川“村通工程”的最主要承担者，自2004年以来，四川移动以高度的社会责任感和历史使命感，先后投资100亿元，30万建设者跋山涉水，克服种种艰难险阻，累计解决了全川10962个未通电话行政村的通信问题，为巴山蜀水的父老乡亲架起了信息沟通和致富的桥梁。 2010年10', '2010-11-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC9TzIQkqoqFyLIMWMOplbLnJMmXZjtbah0MhR0T66PU_wICqo0jb6G_ZqOSLqDqrCV5Q8E7Yf_cttsx35dnCxwhj4Ak8SSDHMA27s9sn-VWsPaFtYIdXEXDOK4DKJyBnNsKT3fBXXOcQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2783, '报纸', '百岁将军忆长征', '卜金宝 ; 程峰典 ; 易祖荣', '解放军报', '解放军报', '强渡大渡河;石达开;', '人物小传：王茂全，江西吉安人，1911年生，1930年参加红军，曾任河北省军区副司令员等职，1964年晋升为少将军衔。 10月6日，记者如约来到河北省军区石家庄干休所。这是一座宁静的院落，记者来到院子里，见一位老人正在散步，这位老人正是王茂全。近年来，记者曾拜访过10', '2010-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID-psUf8u_TdgusWHQb-Upjtd9znTxLQe5gMv_HkXYUKJVr093HKxc4qnErrypW_Yf4Rgs82JL0PLBk0TmlwwEoj4ryCvlSdDreuSyGwy9vWBLiM0BXGbi8AGPQI59fHJlCrjYZg7Afmw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2784, '报纸', '“红色土地定能结出红色旅游硕果”', '史延廷', '中国旅游报', '中国旅游报', '红色旅游;凉山州;泸沽湖;金沙江;凉山彝族自治州;中国航天城;红色旅游景区;红军长征精神;', '日前，记者来到有“中国阳光走廊”之称的四川安宁河流域，看到凉山彝族自治州旅游业一片繁荣，呈现火爆热烈的局面。红色旅游景区景点逐渐升温，吸引了越来越多国内游客的关注。 四川历史悠久、文化璀璨，红色文化与雄奇秀美的自然景观、独特的巴蜀文化和绚丽的民族', '2010-03-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICOpMZcWhExipZb9iUU8yLqNHJ30uzsPglNcpb1B2879q7r-W1_By4_fjM7zhDFbc3iUzpoGeWUZXAEUozLeP-FTji5dtYB891lQpkmZfI6oJZvdM7olIvifQDoAy9QY5f65yeYWSmieQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2785, '报纸', '共产党人的传世家谱', '王珍太; 陈先义', '解放军报', '解放军报', '文学创作;革命历史题材;《星火燎原全集》;共产党人;', '在新中国成立60周年之际，总计千余万字共20卷的《星火燎原全集》出版了，这不仅是军队出版家献给新中国成立60周年一份最隆重的厚礼，也是新中国出版史上的一件盛事。 与一般典籍不同，《星火燎原》对中国共产党和中国人民解放军来说，具有非同寻常的意义，它是一部十分', '2009-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICfMHWH3X4TzY2S6fKjf05PpeOVjLIxKubOAzta-y39PCKwAsfMhVkpXwDtkbmfLteA_Mk2iyHZI7ZvWMdByzb62nkgXcaMHO_WoBuGM65nIBPhHoMzEzTMBT_da1Gyx0HpFQ8CCudjzw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,四渡赤水_screened,飞夺泸定桥_screened,方志敏_screened,土地革命战争_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (2786, '报纸', '一批红色旅游景点成为革命传统教育基地', '黄建华; 杨彪', '解放军报', '解放军报', '革命文物;四川省;旅游景点;革命传统教育基地;抢救保护;', '本报成都8月25日电黄建华、记者杨彪报道：由成都军区与地方有关部门协力建设的陈毅故居纪念园观景亭工程8月23日在四川乐至竣工，正式对外开放。这是四川军地携手保护革命文物的又一具体成果。  四川省革命文物资源丰富，全省181个县（市、区）中有革命文物分布的', '2007-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBN2ZC2Rko6cSAMfs5FVMQPEIlj9p90ajUgwNHr-ib58ctkpOArbyhW0nr6-6GtXlQL2m45gj1-K2iMmK10I2rpgKhHUazQbd5RZK0u7xfzHPraJzi89z27TFOOQ-bNYTOVXD14e3XWiA==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2787, '报纸', '探寻不灭的精神', '董保存', '人民日报', '人民日报', '长征精神;张力雄;李中权;长征路上;', '由中国人民对外友好协会、八一电影制片厂、北方执信影视策划中心等单位联合摄制，中国联通资助的大型电视纪录片《寻访健在老红军》终于和广大观众见面了。作为这部纪录片子的总撰稿，在创作过程中可谓感慨颇多。 在小学的语文课本上，我们就认识了这两个字：“长征', '2007-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDzCV_a18-FX-1J54HSSl6t3bQfp7hcR4lSAWLajhJkdO7HlfKh7AVC53Nvz4Uf6PJWo8iwzSXyT7GIrxQ0q6F_UhvrInlrPtna2AGt7-p3PMtufdMpmsXvge_C7uGu8b3huVkuB14VjA==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2788, '报纸', '为维护香港长期繁荣稳定作出突出贡献', '李争平; 李文景; 钟友国; 陈栋梁', '经济日报', '经济日报', '昂船洲;军营生活;繁荣稳定;香港特区政府;大渡河连;海军官兵;步兵旅;突出贡献;维多利亚;', '站在中国人民解放军驻香港部队大厦26层大厅的窗口，夜幕中，维多利亚港湾的璀璨灯火映入眼帘，使人沉浸在一种安宁与繁荣的氛围之中。自从10年前的7月1日冒着大雨入驻香港，这支人民军队，就牢牢地吸引着世界的目光，成为世人观察中国“一国两制”方针实施情况的一个重要窗口', '2007-06-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAAoe_1uFMHGY5UGuDx80Mx741JejKFAQYo4WYaafoeIYUzRR0dDUZZ5dc5Jb8j_qZYrUORKstTwarMhZxkQbu12SjUxpQKy0LEa9Y2sLDCxS4oviMmfG8QSZNMc2WsObUuNUSKA3pSqw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2791, '报纸', '穿越历史的长廊', '江山', '人民日报', '人民日报', '中央红军;伙食尾子;归化寺;', '“我是一个来自农村的打工者，有幸能参观这次展出。最让我感动的是红军过草地、爬雪山的那破旧的鞋和帽等一些东西，当我看到的时候，流下了激动的泪水。我发誓我无论干什么工作都应该对得起那些牺牲的烈士，更要对得起党和人民。”这是一名叫做时彦利的普通打工者，在参观了', '2006-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICol4QaDlQZfkeeSN3VHfuSIynpcILq-GB9srOpEhwaL9n0KDNPbwmrnpguyd-MraLoS3Q0Ega1Cv5GnwPYSPIFOyfX4AbYJp_BJZ6--4EZ1KwN6Jm2quE4mpoXpeXWFT6FBgi719aeKw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2793, '报纸', '长征路上弥足珍贵的历史见证物', '唐先武', '科技日报', '科技日报', '长征路上;历史见证;红军长征;', '震撼！红军战士刘志海冻死在雪山上。临死前，他从雪堆里高举起一只手，紧握着党证和向党交纳的最后的党费———一块银元，表现出对党的无限忠诚和对革命的坚定信念。《雪山忠魂》雕塑前，许多参观者受到深深震撼，并纷纷写下留言：这样的展览效果好。在今天开幕的《伟大壮举', '2006-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICVN59Nar62LFqYq195J0Jwn_bagNYDxxIbac-cwqpTGc9sEEhBxkm0uZCRYjg4nPhqgrUhlu6G33hyA57wk2RX1YW7b0mV7s0OACoHoXozdn-OTfRNhMXzQb7n1vJWUiNMdf3vVByNvQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2795, '报纸', '彝海结盟续新曲', '唐晓兵; 钟钢', '人民政协报', '人民政协报', '形象扶贫;彝海乡;', '彝海，大凉山上一个美丽的淡水 湖，举世闻名的“彝海结盟”的故事就 发生在这里。在纪念红军长征胜利70 周年之际，记者一行驱车来到四川省 凉山彝族自治州冕宁县彝海乡，这里 树木葱郁，气候宜人。沿山坡上到海拔 2000多米的彝海岸边，眼见湖', '2006-09-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC5DBYkfQ9O93g5TBHR5siXYosCyln_bR21-3Rj4_ucxHpXv7mik4k7xyxBf7TZvqU_hVva3rLdfGe1o65FFK_35aQxl6vmYnh-JtNRRdZjA6ebJ7EqMaWA9wyM_taRLyrTqmZCd971JQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2796, '报纸', '发射架下的花环,见证豪情与悲壮', '张严平; 孙彦新', '新华每日电讯', '新华每日电讯', '戈壁滩;发射架;测试站;强渡大渡河;弱水河;孙继先;聂荣臻;刘启泉;发射工位;', '新华社酒泉9月17日电(记者张严平、孙彦新)巴丹吉林大漠深处，弱水河畔，高耸的发射塔直刺云天，这便是中国酒泉卫星发射中心。  胡杨泛黄的季节，当我们跟随发射测试站官兵来到东风烈士陵园，凭吊他们为祖国航天事业献出生命的战友，面对茫茫天地间如林的墓碑，久久', '2006-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIApyJdwTMv94scjtldP6qOzOxxT9vnjfQVy5Kgwy9zfGe30JES2LtJon_8UhzZrK3Yjdtlt0DEI_yXeracVI46Qsxf4WjLg21AnpGhyMKrcyMkxxgD4xqEPGXVoxrM0SvtP93hFUBsqkQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2798, '报纸', '弘扬长征精神 争当红军传人', '张友森; 邢珊瑚', '中国国防报', '中国国防报', '长征精神;四川省军区;泸定桥;', '编者按　当前，全军部队正在认真贯彻落实胡主席重要指示，大力开展我军历史使命教育、理想信念教育、战斗精神教育和社会主义荣辱观教育。为使几项重大教育取得实效，四川省军区以纪念红军长征胜利70周年为契机，充分发掘驻地红色资源优势，把“寻访红军足迹、聆听红军故事、', '2006-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBzz-HfqKKh5baM4Ar7gVXOoL93AOC4zprKu0be4piNaX1OYB4ndC5oF25Qi9yIrWCkkQYOY63cPNVfD5MtlMSfDDHyj6eN17qej5F0C7Rz6uy7reRPsrMepVrmgqGxxizn-Wmjua28WA==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2799, '报纸', '前进在民族复兴的新征程上', '贾永; 刘刚; 翟伟', '新华社;', '新华每日电讯', '民族复兴;长征路上;共产党人;密切联系群众;马克思主义与中国革命;', '85年前启航于嘉兴南湖的红船，使灾难深重的中华民族开始了奔向光明与希望的历史航程。  70多年前，作为中国革命的转折点，漫漫长征让中国共产党人找到了马克思主义与中国革命实际相结合的正确道路。  建党与长征──中国革命史上的两件大事穿越历史的时空', '2006-06-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICIWELGHYc5AKeA9aSep9_8uH0tO2gCMZvWuKiS897cf--Ab_-_yrPtMJPLNczyzok6b1-nRaQkOKvEgRf2Z7PWm3G0hdc7K85z6JDhaq2e3hvVo7bramM-xXGG_nP9Y9D7QOm-THO86g==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2800, '报纸', '黄甦', '', '人民日报', '人民日报', '中国工农红军;', '黄甦是中国工农红军高级指挥员。1908年生，广东佛山人。早年在香港做工，积极投身工人运动，1925年参加省港大罢工。他走街串巷，动员群众参加罢工斗争。罢工开始后，任纠察队队长。他率领队员巡逻海岸，封锁港口，缉拿私运，严惩走狗，在尖锐复杂的斗争中经受了锻炼和考验，', '2006-02-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDvJj7oL3V7KeEXWDihAkmhxNgrj3j5FQ_oqJZAQf-qyQkEP-sigWph765HATL42gpzgCUfYwsJ62u2rT-WAufP_fqIdfrLJr8k-cch1vy_GsT5qnYIMjqYM9DqwAlTMes1IkEhOx_6PQ==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,四渡赤水_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (2802, '报纸', '红色旅游热遍中国', '邓曦涛', '中国消费者报', '中国消费者报', '红色旅游;红色旅游区;国家旅游局;', 'T共和国伟大光辉的历程，留下了历史的足迹，革命先烈奋进的精神不朽。让 我们沿着红色旅游线路，重温那个火红的年代。E 解密红色旅游  如果要评选2005年中国旅游关键 词，红色旅游毫无疑问位居榜首，作为中 国旅游年度主题名副其实。', '2005-04-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBNXayDhIG0_mtut1FjpHJ2hSw7Wibk0YvsG3WudMR0c3PwL9CWdkpFsU4lm7tN7iXV13YOgBqIrCJPATs04cNxgLWSsI14-wreeWUTLOHOzeRgnVG9kDcQFVSk8KVPCHJ1LhkQ-U3fDw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2803, '报纸', '全面落实“五个统筹” 科学推进红色旅游发展', '邵春; 李晓良; 刘萌', '四川记者站;', '中国旅游报', '红色旅游;张中伟;革命传统教育;革命老区;红色文化;红色旅游资源;旅游产业发展;“五个统筹”;', '2005年是红色旅游启动和发展最重要的一年。当以红色旅游为载体，深入开展爱国主义和革命传统教育，带动老区人民脱贫致富已成为全社会的共识，作为红色旅游试点的四川省再一次感受到了自己肩上的时代使命。在京出席十届人大三次会议的全国人大代表、四川省省长张中伟接受本报', '2005-03-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC1Zpdoys4afoViQW3WtCGQkQN0yWoLK4n8kFBEjxfxw6du2K8DwU7euf7jDgPHYGaYakQ30JkFtg_L8S0dVfAGrxyS8jLK0M9VKgJuCt690nqPMhAYGFkl0dnKY8Ac-GOJNYeXFQW-Cw==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2805, '报纸', '红军强渡大渡河纪念馆落成', '颜春; 黄呈祥', '中国国防报', '中国国防报', '红军强渡大渡河;纪念碑;', '本报讯　颜春、特约记者黄呈祥报道：4月中旬，四川省石棉县安顺场彝族藏族乡的近千名各族群众载歌载舞，欢庆中国工农红军强渡大渡河纪念馆落成并正式对外开放。这标志着红军强渡大渡河纪念地整体规划已全部完成。 坐落在大渡河畔的安顺场以“翼王悲剧地，红军胜利场', '2004-04-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDmlC5pgBiF6sKq0p_QFVW-tk05J-MbOH2ypd7Ht04HMDlJCVhytx3sQtc-P4yJPtH3JwHcIFadoLNDjJH-KLR1NyyVGhvpZwWWD9h4ZGITMJux7hY31sgrHRtU4It4ZH6Bn-khyh1zQA==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2807, '报纸', '红军血脉传香江', '胡训军; 王永清; 彭泽成', '解放军报', '解放军报', '步兵旅;', '驻香港部队某步兵旅是一支有着光荣传统的红军团队。全旅有13个红军连队，其中有“大渡河连”等6个英雄连队。进驻香港5年来，他们继承和发扬红军精神，将流淌了几十年的红军血脉，传到了香江之畔。  百步穿杨惊四座  步兵旅前身是著名的“红一团”。当年在红军长征', '2002-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAIEvt86dpjpbZpckbZuBksKL1wJYV59hWi0wnmJrA5mKfJ7R3kCtMOBcdp_4HhgHOrzCHjpgizPnhSvJEYZP53i7zEvXfzufGTj1hwT7UKfWq6xu9hGme-dphLpgrZsHph4tgl5nodoA==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2808, '报纸', '让长征精神薪火相传', '翟伟', '新华社;', '新华每日电讯', '中国工农红军;长征精神;张爱萍;', '一场骤然而至的疾雨，给久旱的华北大 地带来了几丝难得的凉爽。雨后的北京，绿叶 滴翠，满目葱茏。  在中国共产党成立80周年前夕，记者采 访了百战疆场的老将军张爱萍。夏日的阳光 映照在老将军的脸上，提到战火纷飞的难忘 岁月，身经百', '2001-06-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAWN45fu4wt_wp5StJDoLZgzUSGfN9zy_TOzpmKf8ecSyl9Z1M9zXI6Th45wQufVn1s_nPLKf5opgjAZGPjgsLVFlGKzth5uOTgrd5aKxOjFbNr19fOuuWb-mrOfBtgj5MKwIccEu45Sg==&uniplatform=NZKPT&language=CHS', '强渡大渡河_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2810, '报纸', '愿得此身长报国', '丁增义; 梅世雄; 刘艺', '新华每日电讯', '新华每日电讯', '烈士陵园;天安门广场;人民英雄纪念碑;', '庄严的天安门广场，人民英雄纪念碑巍峨矗立。 1949年9月30日，中华人民共和国开国大典前一天，中国人民政治协商会议通过了在天安门广场建立人民英雄纪念碑的决议。 2014年，我国以法律形式将9月30日设立为烈士纪念日。从那一年起，天安门广场每年都要隆重举行烈士纪念日向', '2023-09-29 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.005895', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2812, '报纸', '“脚板踩出对新闻的坚守”', '孙海悦', '中国新闻出版广电报', '中国新闻出版广电报', '时政报道;新闻主播;主持人;播音主持;', '“能够近距离聆听习近平总书记的重要讲话，我感到万分激动、无比振奋!”谈起习近平总书记10月17日上午参加党的二十大广西代表团讨论时的情形，广西广播电视台播音员、主持人许菲心潮澎湃。她说，习近平总书记亲临广西代表团参加讨论，充分体现了对少数民族地区的关心关怀。她', '2022-10-19 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.003661', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2813, '报纸', '军队是要打仗的', '', '解放军报', '解放军报', '军事训练;战争形态;战斗精神;', '27.为什么说打仗硬碰硬、训练必须实打实？ 2018年新年伊始，中央军委隆重举行开训动员大会，习主席一身戎装、冒着严寒向全军发布训令。这是中央军委首次统一组织全军开训动员，此后每年开年，习主席都签发开训动员令，推动全军全面加强实战化军事训练，引领开创练兵备战新局', '2022-09-25 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.005205', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2814, '报纸', '赓续红色血脉，凝聚接续奋进伟力', '王昊魁; 刘华东', '光明日报', '光明日报', '展览馆;习近平;中国特色社会主义;中国共产党历史;共产党人;', '骄阳似火，绿意正浓。6月的一天，北京市海淀区居民侯本才一大早就乘坐公交车，来到中国共产党历史展览馆参观学习。 “太有意义、太震撼了。看不够，看了还想看!”参观学习中，侯本才难掩心中激动，“我是一名党员，看了展览更加体会到党的伟大。新时代，有以习近平同志为核', '2022-07-02 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.003023', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2815, '报纸', '铭记奋斗历程 担当历史使命', '董博婷; 黄玥', '新华社;', '新华每日电讯', '展览馆;中国共产党历史;党史学习;共产党人;历史使命;', '骄阳下，中国共产党历史展览馆巍然矗立于首都北京中轴线的北端上。这座承载百年大党峥嵘记忆、彰显新时代恢宏气象的红色殿堂，如一部立体的党史书，在时光中如炬如镜。 2021年6月18日上午，中国共产党历史展览馆正式开馆。当天下午，习近平总书记等党和国家领导人来到这里，', '2022-06-20 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.004632', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2816, '报纸', '让红色基因代代相传，努力做社会主义建设者和接班人', '王云娜; 吴姗', '人民日报', '人民日报', '社会主义建设者;思政课;红色基因;接班人;', '红军长征路上“半条被子”的故事，经习近平总书记深情讲述，已经广为人知。 湖南省郴州市汝城县文明瑶族乡沙洲瑶族村，是“半条被子”故事的发生地。 2020年9月16日，习近平总书记在湖南考察时，走进文明瑶族乡第一片小学四年级教室，这里正上着一堂思政课。 听学生讲述长', '2022-06-14 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.006221', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2817, '报纸', '传承红色基因 弘扬廉洁之风', '孙超', '人民日报', '人民日报', '红色基因;', '湖南是一片红色的土地，中国革命史上，无数英雄儿女为了民族独立、人民幸福抛头颅、洒热血。他们坚如磐石的理想信念、百折不挠的顽强意志、清正廉洁的政治本色，是新时代党员、干部锤炼党性、砥砺奋进的宝贵精神财富。 近年来，湖南省在推进新时代廉洁文化建设中注重传承红', '2022-06-07 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.005981', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2818, '报纸', '牢记领袖嘱托 走好新时代长征路', '', '中国新闻出版广电报', '中国新闻出版广电报', '向死而生;敬仰之情;湘江战役;中国报告文学;红军长征;历史时空;报告文学作家;革命理想;长篇报告文学;广西人民出版社;长征路;', '党的十八大以来，习近平总书记在多个场合多次提及湘江战役，曾专门作出重要批示，明确要求做好湘江战役烈士纪念设施建设保护和红军遗骸收殓保护工作。2021年4月25日上午，习近平总书记视察广西的第一站，便来到位于桂林全州县的红军长征湘江战役纪念园，向湘江战役红军烈士敬', '2022-05-27 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.001703', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2819, '报纸', '习近平的文化情怀', '林晖; 周玮; 施雨岑; 史竞男; 王鹏', '人民日报', '人民日报', '习近平总书记;中华民族;文化情怀;文化自信;中华优秀传统文化;', '“一个热爱中华大地的人，他一定会爱她的每一条溪流，每一寸土地，每一页光辉的历史。” 这是习近平同志30多年前在河北正定工作时的一段深情告白。 多年以后，领航“中国号”巨轮乘风破浪，习近平总书记自豪地宣示：“中华民族在几千年历史中创造和延续的中华优秀传统文化', '2022-05-12 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.004837', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2820, '报纸', '这一年，总书记的基层足迹', '', '人民日报', '人民日报', '习近平总书记;中华民族;中国共产党成立;', '“牧民生活好，全靠党的政策好，衷心感谢党、衷心感谢总书记。” “中国共产党成立一百年了，我们这个党能够发展壮大起来不容易，夺取政权不容易，建设新中国不容易。为什么老百姓衷心拥护中国共产党？因为我们党始终全心全意为人民服务、为各民族谋幸福。” 这是今年', '2021-12-31 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.013781', '陈树湘_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2821, '报纸', '用水墨动画隔时空“对话”', '朱丽娜', '中国新闻出版广电报', '中国新闻出版广电报', '水墨动画;短视频;黄文秀;', '今年9月，人民网、人民日报社“碰碰词儿”融媒体工作室联合推出特别策划——《奇迹 有密码》系列短视频，采用水墨动画形式，以小故事折射大主题。通过一个个故事，生动讲述红船启航、进京“赶考”、赤子归国等党史故事，让读者通过一个个鲜活的人物故事、一段段跨越时空的“', '2021-12-14 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004898', '陈树湘_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2822, '报纸', '最具穿透力的概括', '李云舒', '中国纪检监察报', '中国纪检监察报', '中国共产党成立;习近平总书记;共产党人;中华民族;马克思主义中国化;社会主义;中国式现代化;中国特色社会主义道路;穿透力;', '党的百年奋斗从根本上改变了中国人民的前途命运、开辟了实现中华民族伟大复兴的正确道路、展示了马克思主义的强大生命力、深刻影响了世界历史进程、锻造了走在时代前列的中国共产党。 党的十九届六中全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》', '2021-12-09 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.005626', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2823, '报纸', '爱党信党 鱼水情深', '熊丰; 余贤红', '新华社;', '新华每日电讯', '共产党;黄文秀;', '革命老区，是党和人民军队的根，是中国人民选择中国共产党的历史见证。 赓续百年来传承的精神血脉，老区人民坚定不移跟党走，在中华民族伟大复兴的奋进征程中，谱写了一组组铿锵的时代音符，奏响了一曲曲激越的奋斗之歌，构筑成气壮山河的英雄史诗。 信念，矢志不渝', '2021-11-09 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008601', '陈树湘_screened,叶坪_screened,方志敏_screened,瑞金_screened,神山村_screened');
INSERT INTO `ds_article` VALUES (2825, '报纸', '探索中国道路的百年史诗', '', '经济日报', '经济日报', '中国道路;伟大复兴;习近平总书记;社会主义制度;中国共产党;中国式现代化;', '坚定不移走自己的路！ ——这是栉风沐雨的100年间，中国共产党全部理论和实践的立足基点； ——这是矢志不渝的赶考路上，中国共产党引领中国式现代化的深刻启示； ——这是迈向伟大复兴的征途中，中国共产党向世界发出的继续奋斗的铿锵誓言。 路代表方向，也诠释', '2021-11-08 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.007783', '陈树湘_screened,血战湘江_screened');
INSERT INTO `ds_article` VALUES (2826, '报纸', '伟大的史诗 不朽的丰碑', '梁蓬飞', '解放军报', '解放军报', '长征路;红四方面军;红军长征;中央红军;赤水河;红军主力;四渡赤水;', '长征是什么？ 毛泽东说，长征是历史纪录上的第一次，长征是宣言书，长征是宣传队，长征是播种机。自从盘古开天地，三皇五帝到于今，历史上曾经有过我们这样的长征么？……没有，从来没有的。 红军长征是20世纪最能影响世界前途的重要事件之一，是充满理想和献身精神、', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006716', '陈树湘_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2828, '报纸', '太空视角全新呈现，创意解码“中国共产党为什么能”', '钟昊熹; 程瑛; 周瑜; 周锦帅', '新华每日电讯', '新华每日电讯', '创作团队;党史学习;短视频;共产党;', '谁是中国“C位”？这个“C位”又是怎样炼成的？ 10月1日，新华社推出首部卫星特色政论片《C位是怎样炼成的》，以独特视角给出答案。 这部时长38分钟的视频，以俯仰天地的宏阔视野、穿越百年的独特视角，带领观众从数百公里外的太空展开红色追寻，引发广泛共鸣，成为刷', '2021-10-15 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007891', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2829, '报纸', '天地英雄气 千秋尚凛然', '向贤彪', '中国纪检监察报', '中国纪检监察报', '敢于斗争;缅怀先烈;英雄气;为国为民;共产党人;', '福建省上杭县古田镇大源村有一座烈士碑，上面镌刻着该村为革命牺牲的33名烈士的姓名。闽西革命根据地创始人之一张鼎丞同志为之题词：“但愿子孙相继起，能和先烈共流芳。”国庆期间，村民们纷纷来到烈士碑前缅怀先烈、告慰英灵。 天地英雄气，千秋尚凛然。近代以来，没有一', '2021-10-11 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.004725', '陈树湘_screened,会宁_screened,闽西革命根据地_screened');
INSERT INTO `ds_article` VALUES (2830, '报纸', '赓续英烈精神 汲取奋进力量', '李龙伊', '人民日报', '人民日报', '民族独立;人民幸福;陈树湘;湘江战役;', '9月2日上午，第八批在韩中国人民志愿军烈士遗骸由中国空军运—20专机护送，从韩国接回辽宁沈阳，109位志愿军烈士英灵及1226件相关遗物回到祖国怀抱。 “盛世中华，英烈回家，向志愿军忠烈致敬！人民英雄永垂不朽！”机组成员与塔台的对话，让人们泪湿眼眸。 英雄是民族', '2021-09-30 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.010446', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2833, '报纸', '伟大的征程 不朽的史诗', '王思北; 王琦; 高蕾; 刘硕; 陈诺; 吴光于; 翟濯', '人民日报', '人民日报', '中国共产党历史;习近平总书记;展览馆;', '中国共产党百年华诞之际，6月18日，“‘不忘初心、牢记使命’中国共产党历史展览”在新落成的中国共产党历史展览馆举办。当日下午，习近平总书记等党和国家领导同志来到这座宏伟建筑参观展览。习近平总书记强调，必须把党的历史学习好、总结好，把党的宝贵经验传承好、发扬好', '2021-08-10 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.008345', '陈树湘_screened,血战湘江_screened,飞夺泸定桥_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (2834, '报纸', '坚定我们的信仰信念信心', '', '人民日报', '人民日报', '马克思主义;中国特色社会主义;', '坚定的信仰、如磐的信念、必胜的信心，是我们走好实现第二个百年奋斗目标新的赶考之路的力量所在 只要坚定对马克思主义的信仰、对中国特色社会主义的信念、对实现中华民族伟大复兴中国梦的信心，挺起“泰山压顶不弯腰”的脊梁，涵养“乱云飞渡仍从容”的定力，永葆“石破', '2021-08-04 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.008166', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2835, '报纸', '增强做中国人的志气、骨气、底气', '孙英', '中央民族大学马克思主义学院;北京市习近平新时代中国特色社会主义思想研究中心;', '中国民族报', '中国人;共产党;祖国统一;中华民族;中国特色社会主义;夏明翰;', '一百年前，一群新青年高举马克思主义思想火炬，在风雨如晦的中国苦苦探寻民族复兴的前途。一百年来，在中国共产党的旗帜下，一代代中国青年把青春奋斗融入党和人民事业，成为实现中华民族伟大复兴的先锋力量。在庆祝中国共产党成立100周年大会上的重要讲话中，习近平总书记寄', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.000808', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2836, '报纸', '以长征精神走好新时代长征路', '徐杰', '中国纪检监察报', '中国纪检监察报', '长征精神;中华民族;红军长征;一切从实际出发;长征路;', '“红军将士视死如归、向死而生、一往无前，靠的是理想信念。为什么中国革命能成功？奥秘就是革命理想高于天，在最困难的时候坚持下去，这样才能不断取得奇迹般的胜利。”今年4月，在参观红军长征湘江战役纪念馆时，习近平总书记的话字字铿锵。 1934年10月，第五次反“围剿', '2021-08-01 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003793', '陈树湘_screened,强渡大渡河_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2840, '报纸', '恢宏史诗的力量之源', '任仲平', '人民日报', '人民日报', '中国共产党成立;马克思主义;习近平总书记;共产党人;中华民族;人民幸福;力量之源;精神谱系;', '（一）天下将兴，其积必有源。 “你诞生在一百年前风雨飘摇，从不怕迎面而来的浊浪滔滔……我沐浴着新时代的温暖阳光，从不曾记忆模糊地将你遗忘”，修葺一新的中共一大会址前，上海小荧星合唱团唱响一首《百年号角》。悠扬旋律、天籁童声，穿越百年风雨，唱出薪火相传。', '2021-07-20 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.013786', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2841, '报纸', '永远把伟大建党精神继承下去发扬光大', '刘维涛; 张洋; 孟祥夫; 吴储岐', '人民日报', '人民日报', '丰富内涵;精神谱系;中国共产党历史;习近平总书记;共产党人;人民幸福;', '一百年风雨兼程，一百年沧桑巨变。 从成立时只有50多名党员，到今天成为拥有9500多万名党员、领导着14亿多人口大国、具有重大全球影响力的世界第一大执政党。中国共产党为什么能？ “一百年前，中国共产党的先驱们创建了中国共产党，形成了坚持真理、坚守理想，践行初', '2021-07-19 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007502', '陈树湘_screened,陈树湘_screened');
INSERT INTO `ds_article` VALUES (2842, '报纸', '全景式展现党的奋斗历程', '杨文佳; 侯颗; 段相宇', '中国纪检监察报', '中国纪检监察报', '奋斗历程;党员突击队;革命史;密切联系群众;展览馆;精神谱系;延安整风运动;《改造我们的学习》;陈树湘;李大钊;', '拾级而上走进中国共产党历史展览馆的序厅，映入眼帘的是一幅由百块漆板拼接而成的巨幅《长城颂》漆画。在万山红遍、层林尽染的背景中，长城如一条东方巨龙，穿梭于崇山峻岭中，盘旋直入云海深处。 6月25日，记者探访了中国共产党历史展览馆首展“‘不忘初心、牢记使命’中', '2021-06-26 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003111', '陈树湘_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2843, '报纸', '让信仰的旗帜高高飘扬', '', '人民日报', '人民日报', '习近平总书记;红军长征;湘江战役;', '在统揽伟大斗争、伟大工程、伟大事业、伟大梦想中，起决定性作用的是推进党的建设新的伟大工程。奋斗新时代、奋进新征程，如何更好发挥我们党的优势？如何把党建设得更加坚强有力？在建党百年之际，本版推出系列评论，与读者共同探讨我们党永葆旺盛生命力和强大战斗力的密码', '2021-06-15 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006260', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2844, '报纸', '让理想之光照亮奋进道路', '杨笑雨', '人民日报', '人民日报', '理想之光;红军战士;湘江战役;红军长征;', '在广西壮族自治区桂林市全州县才湾镇的红军长征湘江战役纪念园，一面震撼人心的巨幅浮雕墙，生动展现了长征途中红军战士浴血奋战、抢渡湘江的激战场景。1934年底，为确保中共中央和中央红军主力渡过湘江，粉碎敌人围歼红军于湘江以东的企图，几万名红军将士血染湘江，谱写了', '2021-06-11 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006162', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2845, '报纸', '把明理增信崇德力行贯穿党史学习教育始终', '许达哲', '湖南省委;', '学习时报', '党史学习;习近平总书记;', '习近平总书记反复强调，一切向前走，都不能忘记走过的路；走得再远、走到再光辉的未来，也不能忘记走过的过去，不能忘记为什么出发。在党史学习教育动员大会上，习近平总书记全面阐述了开展党史学习教育的重大意义、重点任务和工作要求，之后又在多个重要场合发表一系列重要', '2021-05-21 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.000862', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2846, '报纸', '讲好陈树湘等英雄的故事', '王雪', '学习时报', '学习时报', '湘江战役;共产党人;陈树湘;红三十四师;', '正在广西考察的习近平总书记，4月25日来到位于桂林市全州县才湾镇的红军长征湘江战役纪念园，向湘江战役红军烈士敬献花篮，瞻仰“红军魂”雕塑，参观纪念馆。在一幅油画前，习近平总书记驻足凝视。这幅油画中的主人公是红军第五军团第三十四师师长陈树湘，油画上方写着“为苏', '2021-05-05 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.000748', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2847, '报纸', '守望信仰的高山', '李洪兴', '人民日报', '人民日报', '雄关漫道;会宁会师;长征路;习近平总书记;', '雄关漫道、战胜艰险，理应激荡信仰的力量，挺起脊梁、敢于担当，执着追求、坚定前行。有了雄健的精神，就一定能不断创造新的人间奇迹 从江西瑞金出发，在贵州遵义转折，于甘肃会宁会师，在陕西延安扎根。1934年10月至1936年10月，红军第一、第二、第四方面军和第二十五军', '2021-03-16 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.002594', '陈树湘_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2848, '报纸', '守初心担使命 走好新时代长征路', '杜家毫', '中共湖南省委;', '经济日报', '红六军团;牢记使命;', '在“不忘初心、牢记使命”主题教育启动前夕，习近平总书记专门到中央红军长征出发地江西于都考察调研，向全党发出了弘扬伟大长征精神、重整行装再出发的号召。其中蕴含的特别意义在于，今天中国的进步和发展是从长征中走出来的，长征精神承载着共产党人的初心和使命。湖南是', '2019-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PHCWKjxhnCM8VlkpwBLQDEEeuRFNLuLgXAXr-vIZyNOS3EUme-yNr4B3NG6qhTqtZTiI3XL4ma_laB2d3cq4m4m1ThfWfqomts6GR7WNjW_ndOV1aCkj9r8q8CknQzyFtFeORI580N3A==&uniplatform=NZKPT&language=CHS', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2851, '报纸', '信仰之火，照亮新的长征', '刘璇', '解放军报', '解放军报', '长征胜利;中国军网;', '信仰之火，永不熄灭。 1934年10月17日夜，雩都河水被千万火把照亮，一支衣衫褴褛的队伍开始了前路迢迢却最终改变中国命运的远征。 2016年7月25日夜，于都长征广场的夜空被火把映得通红，一条红色铁流像奔放的河水磅礴向前，在LED大屏幕上绵延。 当长征之胜利印刻', '2016-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4M4oX5ortd4Lucz-u4IWb7zMYJrqBpVDTfx0BTAvIhvbsGk-AQlUIkL3NC4ES4_R3Iqit2YrP7UqmWL5SuOa2j9n69eN_CKeruN0dShTb4tiR3UGeGOfgGyjf-B08OJp3MAWcHbjTn3Ow==&uniplatform=NZKPT&language=CHS', '陈树湘_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2853, '报纸', '信仰(历史文献纪录片)', '', '光明日报', '光明日报', '文献纪录片;共产党人;张秉贵;刘胡兰;钻井队;红旗渠精神;', '编者按：由中央组织部、中央文献研究室、中央党史研究室、中央电视台联合摄制的历史文献纪录片《信仰》，在中央电视台综合频道、中国教育电视台、省级电视台和网站相继播出后，引起广大党员群众热烈反响。该片以党的91年光辉历程为背景，通过讲述革命、建设、改革各个历史时', '2012-09-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4PAwkbSmVD469r_wOXF-zLF-NAYdfuO4HMurRhiVNPy4wYJj26W_acXvh1SxvhSOgphYN9OG1g7HGG-5xJz9zHXvF3Yt73b0V_KJbfu7yLzW4004Q722Kg6jbRfPGBQQXXmRjh9evVy3w==&uniplatform=NZKPT&language=CHS', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2854, '报纸', '“红色大课堂”怎样铸魂？', '', '解放军报', '解放军报', '当代革命军人核心价值观;红色基因;红军长征;红色教育;在线交流;特约通讯员;陈树湘;大课堂;', '核心提示 今年是建党90周年，大江南北的军营，都掀起了学党史军史的热潮，打造“红色大课堂”。 开设“红色大课堂”的根本目的，是把历史变成活的教材，铸牢当代青年军人的军魂。这也是检验我们教育者功力的一个重要课题。 从增强红色教育的生命力到打造“红', '2011-05-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OAXYU68I0y0Ukac3JomyhCSnOvm0sl7VGiNZvjGsdK_RYPUBnrqehL6-tQDPvY_A_2N-0-JWSKfOPyjTyELGHEs5dtR6vIXX0n4rE40WsxN_zYv3x_ZEYCvHV2ul81lzZLE3QvF4mAfw==&uniplatform=NZKPT&language=CHS', '陈树湘_screened,血战湘江_screened');
INSERT INTO `ds_article` VALUES (2855, '报纸', '流尽最后一滴血 陈树湘', '', '人民日报', '人民日报', '陈树湘;国民党军;中革军委;', '据新华社北京３月１３日电 陈树湘，１９０５年１月生，湖南长沙县人。１９１９年参加新民学会发动的长沙反日爱国运动。１９２１年与在长沙清水塘从事党的秘密工作的毛泽东结识，受到马克思主义的启蒙教育。１９２２年秋加入中国社会主义青年团。１９２７年参加北伐军叶挺部', '2011-03-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OVtKQp7TzwSRpqe9sYtMqKSY9wrdSWlkpPZsSNV3tW8uojXajuca38FbYcbFDGZAL4pvvD0_JSfIwBeP77KhVxEm01kXNniWMv7I4TO150bG2ueM3Mds7w4SstKxTZWMAefcAmnL2RBg==&uniplatform=NZKPT&language=CHS', '陈树湘_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (2858, '报纸', '中央红军开始长征突破国民党军四道封锁线', '', '人民日报', '人民日报', '国民党军;中央红军;', '１９３３年９月至１９３４年夏，中央苏区红军进行第五次反“围剿”作战，由于中共中央领导人博古（秦邦宪）和共产国际派来的军事顾问李德，先是实行冒险主义的进攻战略，后又实行保守主义的防御战略，致使红军屡战失利，苏区日渐缩小。１９３４年４月，中央红军（红一方面军', '2006-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4NQ6aaPs5kV4DVjF8YOs-fT19YaMU8-shxNRlYmSZH66fFMKIpDAEBYXNoY29fAcr4XkZ2Cm6ZmZXGdD6GWCCBIzDWw9Tws_yp3ElbI1zJ5Zic1pd6eZCejBP-qklToKR-nrgriiQrm7g==&uniplatform=NZKPT&language=CHS', '陈树湘_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (2860, '报纸', '长征路,“我们走了三万七”', '樊永强; 黎云', '新华每日电讯', '新华每日电讯', '长征;', '新华社北京9月3日电(记者樊永强、黎云)96岁的黄家祥身板仍然硬朗，一身深蓝色中山装整洁精神，行走虽然缓慢但拒绝家人的搀扶。  “我是江西宁都人，‘扩红’时参的军。”1934年，入伍不满一个月的黄家祥就参加了保卫苏区的战斗，“我是红8军团39团3营9连4班的班长。', '2006-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4MXlQrIRI5M18ttB8xhNLSUNQdzWzc055CBfgmbOW9nhGh3nK02DNhKSAJBs7dB4H3gsJmTbrPdWrxXRLxZ8-4meyQ-w0dGCt3nAK6MymDxf0OmQRGwkgfLmC5rvGLoxIwApPPeoBjUbQ==&uniplatform=NZKPT&language=CHS', '陈树湘_screened');
INSERT INTO `ds_article` VALUES (2861, '报纸', '湘江之战：“左”祸酿我军史上第一大悲剧', '刘水玉; 徐壮志; 陈春园; 沈洋', '新华每日电讯', '新华每日电讯', '中央红军主力长征;中央苏区;军委纵队;', '湘江之战，是红军创建以来损失最大的一次战役，与后来的西路军蒙难和皖南事变，并称为我军历史上三大悲剧。这一战后，出发时8.6万人的中央红军锐减到3万。  湘江之战，宣告了“左”倾冒险主义军事路线的彻底破产，随着毛泽东在遵义会议之后重掌红军指挥权，中国革命', '2006-08-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4N56LjyXV31GVm4fLkbLeAJzAoAaRoFvyiqnJ2zasq95TwJgbNg6tiiHGuWdRPRbCDbr0WtCevRvagB9YR-v37-XjyFMt-L5HLy43lIbC8m3C0fswQzDQA4ag2ZVM7sb3LvytuEln_GCA==&uniplatform=NZKPT&language=CHS', '陈树湘_screened,遵义会议_screened,血战湘江_screened,瑞金_screened,苏维埃共和国_screened,项英');
INSERT INTO `ds_article` VALUES (2863, '报纸', '六盘山下乡村振兴“三原色”', '李钧德; 张亮', '经济参考报', '经济参考报', '六盘山;陈靳乡;红军长征;固原市;三原色;', '红军长征行军路线、400毫米等降水线、战国秦长城分布线，打开一张宁夏地图，三条属性不同的图例线在六盘山汇聚。看似毫无关联的三条线，却蕴含着这个曾“苦甲天下”之地的乡村振兴“三原色”。近年来，宁夏固原市不断激活根植于厚重黄土地上的红色遗迹、绿水青山和古韵文脉，', '2023-12-05 08:00:00', 'https://link.cnki.net/doi/10.28419/n.cnki.njjck.2023.004376', '将台堡_screened,将台堡_screened');
INSERT INTO `ds_article` VALUES (2864, '报纸', '红色文化凝聚乡村振兴精气神', '银燕', '人民日报', '人民日报', '红色文化;会宁会师;精气神;', '空气清冽、地面整洁，初冬时节，走进甘肃省白银市会宁县郭城驿镇红堡子村新时代文明实践广场，新修的乡村大舞台上，红军会宁会师旧址管委会红色艺术团正在演出。 1936年10月，中国工农红军一、二、四方面军在会宁和将台堡胜利会师，长征精神在这片土地上生根发芽，世代相传', '2023-11-29 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.011476', '将台堡_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2865, '报纸', '引领大学生走好新时代长征路', '焦敏龙', '中青报;中青网;', '中国青年报', '红军长征;六盘山;红军战士;胜利会师;长征精神;埃德加·斯诺;单家集;长征路;', '80多年前，一支过半数主力平均年龄只有24岁的红军队伍远离故土、艰难行军，翻越今天位于宁夏回族自治区固原市境内的六盘山后，彻底摆脱了敌人的围追堵截，打开了中国革命的新局面。 80多年后，公费师范生罗聪随宁小塾红色筑梦研学实践队在当地参加了8次研学活动。这位就读于', '2023-10-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID49AHXzM3qsGo-Yw_63pVRxtL54D3JQIE4YRX012QbIST-Kys6PDAL0yS7fF3pQQMN5f3aOQyteOCzHMFQr1n-44D6Ve7r-R_Egfvr0719jg-2qA9NlniQxXnWB_2BeKVtbnVbEQqrPw==&uniplatform=NZKPT&language=CHS', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2866, '报纸', '让雷锋精神在新时代绽放更加璀璨的光芒', '', '中青报;中青网;', '中国青年报', '雷锋精神;实际行动;青年志愿者;志愿服务组织;学雷锋活动;习近平总书记;', '日前，“把雷锋精神代代传承下去——纪念毛泽东等老一辈革命家为雷锋同志题词六十周年”座谈会在京召开，会上传达的习近平总书记对深入开展学雷锋活动作出的重要指示，在广大青年志愿者中引发热烈反响。 让雷锋精神融入日常、化作经常 雷锋家乡优秀青年志愿者代表、湖南省', '2023-02-27 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2023.000563', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2867, '报纸', '宁夏：塞上江南展新颜 创造美好新生活', '王永前; 何晨阳; 于瑶', '新华每日电讯', '新华每日电讯', '有效衔接;民族团结进步;习近平总书记;塞上江南;中华民族;振兴战略;闽宁镇;先行区;新生活;对口扶贫;', '新华社银川8月7日电（记者王永前、何晨阳、于瑶）党的十八大以来，习近平总书记两次到宁夏考察，作出系列重要指示，要求宁夏“贯彻新发展理念，主动融入国家发展战略，进一步解放思想、真抓实干、奋力前进，努力实现经济繁荣、民族团结、环境优美、人民富裕”。 牢记习近平', '2022-08-08 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.005877', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2868, '报纸', '望星空听历史 出游乡村好时节', '杨丽敏', '中国旅游报', '中国旅游报', '景区景点;乡村旅游;望星空;太极文化;精品线路;太极拳文化;习近平总书记;', '到乡村去，田野星空，蛙声蝉鸣，历史故事，享受寓教于游的暑期生活…… 近日，文化和旅游部、中国关心下一代工作委员会联合推出128条“乡村四时好风光——乡村是座博物馆”全国乡村旅游精品线路。文化和旅游部相关负责人表示，此次推出了一批乡土乡情、红色文化、考古遗址、', '2022-08-03 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.002102', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2869, '报纸', '新型种养带来“好钱景”', '拓兆兵', '经济日报', '经济日报', '肉牛产业;马铃薯;西吉县;肉牛养殖;马莲乡;六盘山区;', '从红军三过单家集，到红军长征三大主力军在将台堡胜利会师，宁夏固原市六盘山区有着光荣的革命历史。党的十八大以来，固原市积极转变发展理念，大力发展新型种植业和养殖业，胜利翻越了贫困这座大山，在致富路上迈出了新步伐。 日前，记者来到拥有“中国马铃薯之乡”和“宁', '2022-05-09 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2022.002745', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2871, '报纸', '“红飘带”上的“同心结”', '', '解放军报', '解放军报', '部队官兵;长征路;学校大门;同心结;海军政治工作;联合参谋部;教学楼;会宁县;红飘带;小学校长;学生宿舍楼;张大成;', '写在前面 1936年10月，红军三大主力在甘肃会宁和宁夏固原将台堡会师，标志二万五千里长征胜利结束，留下一条壮丽的“地球上的红飘带”。 2006年，红军长征胜利70周年，解放军和武警部队沿长征路援建112所“八一爱民学校”，弘扬长征精神，支持当地教育事业，回报长征沿', '2021-10-28 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006797', '将台堡_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2872, '报纸', '继往开来，重整行装再出发', '汪晓东; 李翔; 林小溪', '人民日报', '人民日报', '习近平总书记;湘江战役;长征精神;红军长征;中国共产党成立;遵义会议;奋斗目标;长征路上;', '“我到广西考察的第一站就来到这里，目的是在全党开展党史学习教育之际，缅怀革命先烈，赓续共产党人精神血脉，坚定理想信念，砥砺革命意志。”今年4月25日，习近平总书记来到位于桂林市全州县才湾镇的红军长征湘江战役纪念园，向湘江战役红军烈士敬献花篮并三鞠躬，瞻仰“红', '2021-10-21 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011037', '将台堡_screened,陈树湘_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2873, '报纸', '赓续红色基因 践行使命任务', '孙占新', '公安局;', '人民公安报', '红色基因;公安机关;将台堡;公安队伍;西吉县;使命任务;', '习近平总书记在党史学习教育动员大会上强调指出：“要教育引导全党大力发扬红色传统、传承红色基因，赓续共产党人精神血脉，始终保持革命者的大无畏奋斗精神，鼓起迈进新征程、奋进新时代的精气神。” 红色基因是共产党人永葆本色的生命密码，是推动公安工作高质量发展源', '2021-10-07 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.005526', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2874, '报纸', '单家集夜话：民族团结的红色佳话', '闫若之', '中国民族报编写组;', '中国民族报', '民族团结;单家集;红军长征;', '一九三五年毛主席率领红军转战宁夏，留下了“单家集夜话”的红色佳话。一九三六年红一、二方面军在将台堡胜利会师。红军长征在宁夏留下了弥足珍贵的红色记忆。 ——习近平总书记2020年6月10日在宁夏考察工作结束时的讲话 2016年7月，习近平总书记来到宁夏回族自治区固', '2021-09-07 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.000936', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2877, '报纸', '宁夏：胜利之山开启新长征', '刘峰', '人民日报海外版', '人民日报海外版', '走向胜利;红军长征;六盘山区;闽宁镇;长征精神;', '“天高云淡，望断南飞雁，不到长城非好汉！”1935年10月7日，在打赢青石嘴战役后，毛泽东同志沿战国秦长城一路下山，8日晚在宁夏彭阳县一户农家的土窑洞里吟出这首《长征谣》，同年12月在瓦窑堡润色修改成《清平乐·六盘山》。 80多年来，正是“不到长城非好汉”的长征精', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002231', '将台堡_screened,血战湘江_screened');
INSERT INTO `ds_article` VALUES (2879, '报纸', '从长征精神中汲取奋进力量', '潘锡才', '山东省临朐县委;组织部;', '中国组织人事报', '长征精神;', '从于都渡口到湘江岸边，从遵义到将台堡……党的十八大以来，习近平总书记足迹遍及长征征途的各个重要节点，并要求全党大力弘扬伟大长征精神。党员干部要以长征精神滋养初心、淬炼灵魂，凝聚起奋进新时代的磅礴伟力。 坚守“理想信念高于天”的战略定力。残酷的战斗、恶劣', '2021-06-25 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.002158', '将台堡_screened,强渡大渡河_screened,血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2880, '报纸', '从这里走向胜利', '范文杰', '人民政协报', '人民政协报', '走向胜利;西吉县;红一方面军;红军长征;宁夏西吉;长征精神;将台堡;习近平总书记;纪念园;', '无论在2000年前的战国，还是在中国革命的历史坐标上，将台堡都是一个闪亮的名字。 将台堡原名西瓦亭，位于宁夏回族自治区固原市西吉县境内，站在厚重的城墙外举目望去，战国秦长城由此经葫芦河向东逶迤延伸。据说，北宋期间夯筑了将帅点校军士的土台，由此得名将台堡。', '2021-06-25 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005169', '将台堡_screened,强渡大渡河_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2881, '报纸', '用好红色文化资源，助推乡村文化振兴', '马伟华; 郭怡敏', '南开大学周恩来政府管理学院;', '中国民族报', '红色文化资源;文化振兴;', '习近平总书记在党史学习教育动员大会上指出，要教育引导全党大力发扬红色传统、传承红色基因，赓续共产党人精神血脉，始终保持革命者的大无畏奋斗精神，鼓起迈进新征程、奋进新时代的精气神。民族地区拥有丰富的红色文化资源，这些宝贵的历史文化遗产为中华民族繁荣发展提供', '2021-06-15 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.000609', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2882, '报纸', '以实干担当赓续长征精神', '时侠联', '宁夏回族自治区人民检察院;', '检察日报', '长征精神;党史学习;', '2016年7月18日，习近平总书记来到西吉县将台堡，在瞻仰红军长征会师纪念碑，参观红军长征会师纪念园、纪念馆时指出，伟大的长征精神是中国共产党人革命风范的生动反映，我们要不断结合新的实际传承好、弘扬好。 四年多过去了，总书记的话始终激励着宁夏检察机关砥砺前行，', '2021-05-27 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.002656', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2883, '报纸', '六盘山上红旗展 丝路固原焕新颜', '杨梦晗; 侯觉; 张雪莹', '中国建设报', '中国建设报', '海绵城市;固原市;试点建设;城市建设项目;六盘山;', '天高云淡, 望断南飞雁。 不到长城非好汉, 屈指行程二万。 六盘山上高峰, 红旗漫卷西风。 今日长缨在手, 何时缚住苍龙? 1935年10月7日下午,长征途中的毛泽东率红一方面军在攻克天险腊子口、越过岷山草地后,到达宁夏六盘山脚下的青石嘴,并在击败了前来', '2020-05-23 08:00:00', 'https://link.cnki.net/doi/10.38299/n.cnki.nzgjs.2020.000920', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2885, '报纸', '征程山河壮 精神日月长', '鲁浩', '河南省纪委宣传部;', '中国纪检监察报', '长征精神;中国工农红军;中外历史;', '这是刻在白山黑水间的壮丽画卷， 这是写在苍茫大地上的不朽诗行! 在全国上下庄严而又隆重纪念红军长征胜利80周年之际，再次认真品读著名作家王树增毕数年心血而著的《长征》一书，脑海中顿时涌出了上面这句话。 心潮澎湃、热血沸腾中，不禁又想到，从长征这部历', '2016-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA_-YiZIKj4V46kyur9Ao4FCFiweRL9KYHRoKx_WRUikEnrT-uQfA6K6NWKHnL4_wkvnNPJcZa9MLeIzSL7lPw00vVSYMbRTjJ6iwFSWijQ7aSJ7MrjU8puCZUYVrk4rcTXCvdaRPGYeg==&uniplatform=NZKPT&language=CHS', '将台堡_screened,陈树湘_screened,强渡大渡河_screened,四渡赤水_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2886, '报纸', '民生大计连军营', '尚力峰', '武警宁夏总队;', '解放军报', '攻坚战;', '“地小物博而山河壮美，回汉共处其风情迥异。”3年前初到宁夏任职，便对这块热土有一种强烈的认同感。参与支援地方打赢脱贫攻坚战的所经所历、所思所想，更让我坚信一个道理：民生大计连军营，军人自有大奉献。 纪念红军长征胜利80周年，一桩80多年前发生在宁夏的往事再', '2016-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICPDjxhPoS10PZSj2ubNA-Ap6fDZT4t1nfmUlrG18goCTHPxyvKnAt8AXQHl9WOPzVilhMFUfGYo2tapQmaE_5uJ3EZXIeSWatmfT-VNL_oD1J8LIv_HpikRKP04F0VsqMVYQM7FqfRhw==&uniplatform=NZKPT&language=CHS', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2887, '报纸', '为什么说三大主力红军会师宣告了长征胜利结束？', '户华为', '光明日报', '光明日报', '三大主力红军会师;红四方面军;张国焘;长征胜利;', '1935年10月22日，中共中央政治局在吴起镇召开扩大会议，决定中国共产党和红军今后的战略任务是建立西北苏区，领导全国的革命斗争。1936年夏，中共中央接连致电张国焘，要求红四方面军在同红二方面军会师以后，迅速北上甘南，同红一方面军一起创建西北抗日根据地，促进抗日民', '2012-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICIZ_Z4gK0n9LqdzlM7OgwD20DTuzSAA-QVTV7nkWJ8Or7L4DnQxbJ-iVsYRqTVaN7gaanoVlEnv1P2TgKYq1H2rsn9zyRJJ3-nrIdmwr8nejtKcCqi8p9sAiDOSTk3_Ps9UUeMes1qXQ==&uniplatform=NZKPT&language=CHS', '将台堡_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2888, '报纸', '“不到长城非好汉”的精神传承', '', '光明日报', '光明日报', '红军长征精神;六盘山精神;宁夏回族自治区;红一方面军;三大主力红军会师;陕甘宁革命根据地;革命文化传统;精神传承;', '本期主题  2012年7月26日，为纪念中国人民解放军建军85周年，迎接党的十八大胜利召开，中共宁夏回族自治区委党史研究室，联合中国人民解放军军事科学院军事历史研究所、宁夏军区政治部、武警宁夏总队政治部、宁夏中共党史学会、中共固原市委、中共吴忠市委等单位，', '2012-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBcReeKZe2zOhf0cWKp8vr88sTfsfhMsKgFnBPqI3mQ-eFzNuNMMtgyXl1M_etJPUuFSe5odwAxUle_Y26rqokjycbEir7gcEW5hoEsrxA1kCDqp4y0Od99ztDSk0LKMGIksNS3Ui3qOw==&uniplatform=NZKPT&language=CHS', '将台堡_screened,四渡赤水_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2891, '报纸', '连续16年干警“零违纪”', '刘学军', '人民法院报', '人民法院报', '执法档案;审判执行工作;司法便民;', '宁夏回族自治区西吉县位于宁夏南部，仅回族人口就有27.1万人，是自治区第一人口大县。 1936年10月22日，中国工农红军会师西吉县将台堡，标志着举世闻名的二万五千里长征胜利结束。因此，这里成为全区爱国主义教育基地之一。 在这片红色土地上，西吉县法院继承', '2010-10-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAv_ecpxSX7g5W13E13s51j5grT82tQUB4KEiWgdogwOrhUMiuk96HCpaOXcZ_GbZIJ_taaqpRa4u-Hh4_fhaXwGQx18gO8fQgUbwHvwNg9AvC1mTZocc0_6kkwBdxPaamFmCLEdpeQWQ==&uniplatform=NZKPT&language=CHS', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2892, '报纸', '三大主力红军会师 宣告长征胜利结束', '', '人民日报', '人民日报', '红四方面军;三大主力红军会师;张国焘;中共中央西北局;长征胜利;', '１９３５年１０月２２日，中共中央政治局在吴起镇召开扩大会议，决定中国共产党和红军今后的战略任务是建立西北苏区，领导全国的革命斗争。１９３６年夏，中共中央接连致电张国焘，要红四方面军在同红二方面军会师以后，迅速北上甘南，同红一方面军一起创建西北抗日根据地，', '2006-11-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICmyMKvLpIlXEXUAsY2X5KE3F6sbd5EOe0uizd483DX3jbakZuPHrKUP23-6hgGLm7zOhefYHA6tdr-3qWG-_24MJbB9k1WhGDxKJ52FFLdGAKUJQXcIa3DcmqxTzW2gvAmmvX-eQ5-Dg==&uniplatform=NZKPT&language=CHS', '将台堡_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2893, '报纸', '三军会师尽开颜', '李战吉', '人民日报', '人民日报', '红二方面军;中国工农红军;三军会师;', '沿着青砖铺就的台阶，登上甘肃会宁县红军会师楼，红军三大主力会宁会师纪念馆尽收眼底。邓小平同志题名的中国工农红军第一、二、四方面军会师纪念塔，三塔环抱，巍巍矗立。会师塔后面，是红柱绿瓦的文庙大成殿。７０年前，那激动人心的一片欢呼，犹如惊雷，至今震撼人心。', '2006-10-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICp4X0cv06UXBHvIkiPRjZp4oDkdv6a-tYBF7PTQ18aBxvxYFvY71QdN-HB2By5jlEDCuuVJbcyk_V_op0mAz_dupJeazi_Bab7KH8546bh9Mwp0s34kLiE4KsKL0tJrHfS5YtowjJ4jQ==&uniplatform=NZKPT&language=CHS', '将台堡_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2894, '报纸', '红旗漫卷向陕北', '周志忠', '人民日报', '人民日报', '红一方面军;红二方面军;将台堡;红军长征;六盘山区;', '“六盘山上高峰，红旗漫卷西风……”，毛泽东同志一首脍炙人口的《清平乐·六盘山》，使六盘山声名远播。 六盘山位于今宁夏南部、甘肃东部，是当年中央红军长征翻越的最后一座高山。１９３５年１０月５日至１０月９日，毛泽东率领红军陕甘支队在六盘山区转战５天４', '2006-10-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDqINzoB_mL1hWZ7rC7yfmObsqVzOF-xq9aQ_movEEvZCI8Q3Y9rEH7UVHQ4Sc084Kjn4LqrNwWOEmyrVwzZ0lc_Ci6rLcd5LZ-2UgFswWDN_9XZowZRVwRnuZdMdPFGk-YXeqwaUNN-Q==&uniplatform=NZKPT&language=CHS', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2897, '报纸', '会宁：大路朝阳', '毛东红; 哈建设', '中国纪检监察报', '中国纪检监察报', '会宁;宁城;红军;', 'T长征记忆  1936年10月，红军三大 主力在会宁、将台堡胜利会师， 标志着中国工农红军两万五千 里长征胜利结束。从此，中国 革命进入了一个崭新的历史阶 段。  会宁地处甘肃中部，土地 贫瘠、干旱少雨，是甘肃自然', '2006-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDa6YcPl6JIn5eYH5exYXvvTlnXjaRqnyCT_hF_YUDqDiFT9Tm3UGxQ--Qh_ZcL7tafsEJCu4-FwqMqUtqEYQMGCZ9HO4FN0XP98seLo9fCra3W1Z896jn2SNbAHfg1J-kv45F8IIY6Qg==&uniplatform=NZKPT&language=CHS', '将台堡_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2898, '报纸', '出绝境向胜利,三军过后尽开颜', '孙彦新; 刘书云; 刘佳婧; 黎云; 梁娟; 朱建军', '新华每日电讯', '新华每日电讯', '中国工农红军长征;将台堡;陕北红军;三军过后;', '70年前的10月，红军一、二、四方面军三大主力在陕甘黄土地上胜利会师的时候，一条永恒的红色飘带，从此镶嵌在地球上  长征的胜利，把濒临绝境的中国革命引向了新的航程。  70年过去，新华社记者来到当年的会师地，通过亲历者的叙述和专家学者的评说，重现', '2006-10-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIASgmaKJ_9zgl1IzXSm0PjbHrcldHO8FL_YOSLLZpZWT1EU0jVt8i4h38xH9Cja7e_YkKRyHZylP6tsnTpP6ZHN4tD3lZbvxmFwLkLFRURVMquHqECVzV46zCAULQx8_q3jvQ73JAPZcw==&uniplatform=NZKPT&language=CHS', '将台堡_screened,遵义会议_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2899, '报纸', '宁夏红色旅游花开六盘山', '王涛', '宁夏记者站;', '中国旅游报', '红色旅游;六盘山;', '5月3日，六盘山天高云淡、山花烂漫，老龙潭景区人声鼎沸、热闹非凡，宁夏回族自治区党委宣传部、发改委、旅游局、文化厅联合举办的宁夏红色旅游启动仪式暨2005首届六盘山山花旅游节在这里隆重开幕。自治区人大副主任刘兴中、政府副主席郑小明、政协副主席梁俭等出席开幕式，', '2005-05-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBcqqLmMMbNHtBM9GswUi3xspQG1S181TCTmne4ZwVmghMdm4Wezrl99r0kAYkLl6us90onniaSIUE2fnQKII-h5WagGixEQrJkYQYrwvp2uG8u2pbQEo_tFydHDHSM7GwZOll3rVoVxw==&uniplatform=NZKPT&language=CHS', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2900, '报纸', '旅游扶贫百业兴', '王健生; 史蔓蓉', '本报西部采访组;', '中国旅游报', '旅游扶贫;六盘山地区;旅游扶贫试验区;旅游区;旅游业;', '1935年10月，一代伟人毛泽东率 领的红一方面军长征翻越六盘山，即 兴写下了气壮山河的光辉词章── 《清平乐·六盘山》。尔后，红二方面军 总指挥部及二军团与一军团二师在 六盘山将台堡会师，宣告红军长征三 大主力会师。从此，六盘山作为中', '2000-09-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAhlL50yoYiZiFVpPZPBiCpBOQdnlypgXhsGo-doC1q48FTSAef_GL9iWXbw-TSC_Wenaq95INOWehozGXULIFhjJbvi0pvx3_FsikS4UvSKgxXberU4ef_0zLMnKul6HY9qPv0IipqSA==&uniplatform=NZKPT&language=CHS', '将台堡_screened');
INSERT INTO `ds_article` VALUES (2901, '报纸', '开往川西北高原的“超级地铁”', '谢佼', '新华每日电讯', '新华每日电讯', '川西北高原;茶马古道;岷江河谷;九寨沟;隧道群;土地岭;跃龙门;', '岷江河谷，风带喜声。11月28日，中国最大羌族聚居地四川省阿坝藏族羌族自治州茂县开通动车，人们以藏羌风情载歌载舞，彼此欢庆。至此川青铁路成都至镇江关段，经过12年建设，首次贯通运行。 银白色的动车风驰电掣，穿云破雾，如长龙一头扎进山间。这更像是一条穿越历史而来', '2023-11-29 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.007172', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2902, '报纸', '依托汽车拉力赛 短视频传播长征文化', '', '中国旅游报', '中国旅游报', '汽车拉力赛;长征路;短视频;视频传播;长征文化;', '今年，广东天地正气体育发展有限公司（以下简称“公司”）承办的中国长征·汽车（新能源）拉力赛项目收获颇多： 4月，两次勘探了中央红色交通线的汽车拉力赛线路； 9月，研究落实了红25军长征河南段的汽车拉力赛线路； 10月，勘探了红7军从广西百色到瑞金的“千里来龙”的', '2022-11-15 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.003152', '夹金山_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2903, '报纸', '地方红色文化融入高校思政教育的价值和策略', '张丹', '雅安职业技术学院;', '中国文化报', '高校思政;思政教育;红色文化资源;文化融入;红色文化教育;', '习近平总书记在党的十九大报告中明确指出：“文化兴则国运兴，文化强则民族强。”红色文化植根于中华优秀传统文化之中，是中国特色社会主义文化的重要组成部分，是中华民族特有的精神动力。地方红色文化以其形象具体的外在特性、丰富深刻的精神内涵，展现了中国共产党为人民', '2022-03-25 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.000981', '夹金山_screened,强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2904, '报纸', '永恒瞬间中的军人表情', '孙伟帅', '解放军报', '解放军报', '航天员;', '2022年北京冬奥会开幕式上，一名中国军人凝视五星红旗激动落泪的照片，成为这场体育盛事中令人印象深刻的“中国表情”。 有人曾问，一个国家的形象靠什么来传递？有网友回答：面孔。 其实，这个答案可以更加精准，那就是：表情。 在国际舞台上，许多经典镜头定格着中国军', '2022-02-17 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.000835', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2905, '报纸', '在强军征程上绽放创作梦想', '李驰旭; 何蒙', '陆军政治工作部宣传文化中心;文化服务站创作室;中国妇女报;', '中国妇女报', '歌词创作;边防官兵;命题作文;艺术性;', '90后的我，从舞蹈起步，表演、配音、作词、编剧、导演……全身心投入军队的文艺工作中。在陆军政治工作部宣传文化中心，我的身份是创作员，但得到的锻炼是全方位的。军队文艺的正气、热血、青春滋养着我，使我获益匪浅，助我不断成长。 古诗和舞蹈是我创作的厚壤 我出', '2022-01-13 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2022.000088', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2906, '报纸', '夹金山上马灯红', '宝组轩', '四川省雅安市宝兴县委组织部;', '中国组织人事报', '夹金山;红军战士;', '文物档案 在四川省宝兴县红军长征翻越夹金山纪念馆一楼展厅，一盏使用煤油的老式马灯，静立在展台玻璃罩下。这盏马灯长19厘米，宽19厘米，高34厘米，整体由铁、铝以及玻璃构成，外有三道铁箍和提梁，内置防风玻璃灯罩，下设底座兼顾油壶，造型便携，是国家三级文物。1977', '2021-12-01 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.003763', '夹金山_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2908, '报纸', '献上一份“特殊党费”，捧出一颗拳拳初心', '李晓; 陈之殷; 张国圣; 赵秋丽; 冯帆; 张锐; 王斯敏; 于北辰', '光明日报', '光明日报', '共产党人;党组织;', '编者按 11月8日至11日，中国共产党第十九届中央委员会第六次全体会议在北京举行，重点研究、全面总结党的百年奋斗重大成就和历史经验问题。值此之际，我们回望党的百年辉煌历程，看到的是无数共产党人的拳拳赤子心、殷殷爱党情。 60多年前，作家王愿坚的小说《党费》生', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005756', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2909, '报纸', '重温红军长征光荣史 走好新时代的长征路', '李冰洁', '人民政协报', '人民政协报', '红军长征;中央红军;飞夺泸定桥;长征故事;强渡大渡河;长征精神;长征路;', '今年是中国共产党成立100周年，也是中国工农红军长征胜利85周年。日前，以全国政协副主席刘奇葆为团长的全国政协文化文史和学习委员会党外委员专题视察团围绕“传承和弘扬长征精神、讲好长征故事”，赴四川省开展专题视察。 视察团先后在礼州会议旧址、彝海结盟纪念馆、红', '2021-10-28 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.008349', '夹金山_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2910, '报纸', '护航革命老区踏上新征程', '王鹏志', '中国纪检监察报', '中国纪检监察报', '长征精神;革命老区;红军长征;营商环境;红色旅游;', '今年是红军长征胜利85周年。1936年10月，红军第一、第二、第四方面军和第二十五军在陕甘宁地区胜利会师。伟大的长征是中国共产党和红军谱写的壮丽史诗，是中华民族伟大复兴历史进程中的巍峨丰碑。 血战湘江、强渡乌江、飞夺泸定桥、爬雪山、过草地……80多年前，中国工农', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.004973', '夹金山_screened,血战湘江_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2912, '报纸', '复兴伟力在这里汇聚', '许雪', '中国国防报', '中国国防报', '党史学习;展览馆;中国共产党历史;', '在中国共产党百年华诞之际，一座永久性、综合性的党史展览馆——中国共产党历史展览馆在首都北京开馆。 6月18日，习近平主席参观“‘不忘初心、牢记使命’中国共产党历史展览”，并带领党员领导同志重温入党誓词。他强调，我们党的一百年，是矢志践行初心使命的一百年，是', '2021-08-12 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2021.001811', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2913, '报纸', '奋力谱写实现中华民族伟大复兴的新篇章', '彭清华', '四川省委;', '学习时报', '中华民族伟大复兴;新篇章;中国特色社会主义;习近平总书记;马克思主义中国化;“七一”重要讲话;共产党人;', '习近平总书记在庆祝中国共产党成立100周年大会上发表重要讲话，立足中国共产党百年华诞的重大时刻和“两个一百年”历史交汇的关键节点，站在统筹“两个大局”的时代高度，系统回顾了我们党建党100年来团结带领全国人民开辟的伟大道路、创造的伟大事业、取得的伟大成就，庄严', '2021-08-11 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001457', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2914, '报纸', '征途漫漫 惟有奋斗', '靳昊; 王昊魁; 周仕兴', '光明日报', '光明日报', '长征精神;习近平总书记;红军长征;一切从实际出发;共产党人;中国共产党历史;强渡大渡河;奋斗目标;中华民族;新民主主义革命;人民战争;毛泽东;张国焘;飞夺泸定桥;生死相依;', '夏日的于都河，水深流急。江西于都县城东门渡口外，游人如织。渡口不远处，中央红军长征出发纪念碑巍然矗立。 87年前，红军队伍星夜渡过于都河，由此踏上战略转移的征程。 这一走，就是两万五千里。高山峻岭，大河险滩，草地荒原，一路战火，一路牺牲，一路播种，一路', '2021-07-30 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003871', '夹金山_screened,陈树湘_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2915, '报纸', '金融为红色阿坝绘新颜', '吴迪; 王莉; 王峰', '金融时报', '金融时报', '阿坝县;阿坝州;信用贷款;分支机构;', '四川阿坝是长征途中红军经过人数最多、驻留时间最长、自然条件最为艰苦的革命老区之一，红色基因在这片大地上传承，党和藏羌儿女的鱼水情谊在这里延续。这里也是脱贫攻坚过程中难啃的“硬骨头”、乡村振兴的“重头戏”。人民银行阿坝州中心支行心系红色大地，带领全州金融机', '2021-07-27 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.003792', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2916, '报纸', '重走长征路 规划红色旅游线', '薛彩云', '中国交通报', '中国交通报', '红色旅游;长征路;长征故事;规划院;', '强渡大渡河、翻越夹金山、血战百丈关……1934年10月，第五次反围剿失败后，中央主力红军为摆脱国民党军队的包围追击，被迫实行战略性转移，开启了人类历史上无与伦比的奇迹——二万五千里长征。 2019年7月24日，习近平总书记主持召开了中央全面深化改革委员会第九次会议，', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28099/n.cnki.ncjtb.2021.001923', '夹金山_screened,强渡大渡河_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2917, '报纸', '别具一格的工地闯关赛', '毛浓曦; 席坤鹏', '工人日报', '工人日报', '横断山;', '6月24日，中建三局西安东三爻安置小区北区项目施工现场，塔吊飞转，机器轰鸣，数百名工人正在忙碌施工。忽然，1号塔吊下传来一阵喝彩：“长征起点，正中靶心，十环！”原来这是项目部的大型设备吊装技能比武大赛，来自两家租赁单位的5组选手正同台竞技。 “光线昏暗不吊、', '2021-07-13 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2021.003275', '夹金山_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2918, '报纸', '日出东方', '', '中国国防报', '中国国防报', '强军目标;硬骨头六连;南昌起义;中共一大会址;中国共产党历史;', '“100100”。 这组数字意味着什么？ 它是中国共产党历史展览馆主题邮局启用的特殊邮编，寓示着该馆落成于建党100周年之际，也寓意向着“两个一百年”奋斗目标勇往直前。 这座庄重恢宏的“立体党史”，记录着一个百年大党砥砺奋进的峥嵘岁月，也回响着一个古老民族迈', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2021.001463', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2921, '报纸', '过雪山草地：铸就长征的不朽丰碑', '龚自德; 李晓东', '四川省委党史研究室;', '光明日报', '红四方面军;雪山草地;夹金山;', '“红军长征举世鲜，铁流夜过党岭山；巍巍群峰银龙舞，英雄大战鬼门关。”（李布德少将《夜过党岭山》） “绿原无垠漫风烟，蓬高没膝步泥潭。野菜水煮果腹暖，干草火烧驱夜寒。”（张爱萍将军《过草地》）…… 红军长征，如果把每支部队的行军里程加起来，总共有8万里', '2016-10-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBOgLJf1C3o-_gGZyF3F4HtZxS4L0foR4-6N4Sh6J4xoPqEu3yn_1h1Zm3COkGJJbYpAfwUCvJBh35sZ7iRm617N5cfCOjcbSx4EwSO0H2PtpHKssIw1JNOQN9nnIm0rLG-NPK9SsLfTQ==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2923, '报纸', '用青少年喜闻乐见方式宣传党史', '', '光明日报', '光明日报', '动画电影;中央党史研究室;曲江新区;革命传统教育;革命历史题材;红色题材;审美表现;', '编者按 3D动画电影《冲锋号》由中央党史研究室、西安市委宣传部、西安曲江新区管委会、西安曲江宏梦卡通影视文化传播有限公司、湖南蓝猫动漫传媒有限公司等联合制作，讲述了一名流浪少年虎子在长征期间，从一个淘气的孩童，成长为一名坚定的红军战士的故事。该片从少年', '2013-05-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAt94X7KhlZ4_zQQ6DE8Ciaigs3uKBtCyOUY8BKLOKinA86qg3TUQTH0vxqyUr7SZ7zKx070Dgcy8ifwOvV_LtL5vH1IfMEYU5CbjV4a8crZ4N14JHLHZ-SvW82tx-6jRn2-de9J4vDdA==&uniplatform=NZKPT&language=CHS', '夹金山_screened,遵义会议_screened,血战湘江_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2925, '报纸', '永远顺应人民的期待', '', '新华每日电讯', '新华每日电讯', '中国共产党;中华民族伟大复兴;经济发展方式;胡锦涛;全心全意为人民服务;执政地位;勇于创新;发展是硬道理;理论创新;', '这是迥然不同的两幅画面: ——短短12天,一个国家启动陆海空立体力量,把35860名公民从山阻海隔、万里之外的动荡北非,平安接回。 ——60多年前,这个国家却饱受列强侵凌,民不聊生,风雨飘摇。一个国民在自己的国土上尚且任人宰割的国家,遑论保护在异国他乡的游', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBoAlEpr0Kl9x0q-AbjrsUyG-NlR1q4fHcCMvIcmIvNUhdFr9XhJoHjg6ldk--vAlK8G0iTJhukgEclNtmLltLGRTWbDJxdQ0FrVnE_2TMiCH_sxZfT-6GTafYTRc-06RmwN3CNEFedXQ==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2926, '报纸', '雪山作证', '朱玉 ; 肖春飞', '新华社;', '新华每日电讯', '红军长征;宝兴县;红军文化;研究者;夹金山;小金县;', '【解说】历史有这样一个不成文的规律,那就是——所有的发现,都起源于好奇。 近80年前,一位在中国的外国人,把困惑的蓝眼睛投向了一支正在翻山越岭的部队。 这个叫埃德加·斯诺的美国人,发现了红军。 他对这支军队分外感兴趣,他想弄明白,这支部队为', '2011-05-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICZaVYydxNJA5Hl_beGYGALmuOHyOtuvtO91jSNiZlbVlcF0J3vysehPLeK7cuSflK0-XnWsBI4wZ45miXBr39aAgevxl2567_TWkkNHccm_q6MUoEiOEu6CrHU9TGjdVkT3Oz2T_JkDA==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2928, '报纸', '《星火燎原》出版前后', '庄建', '光明日报', '光明日报', '《星火燎原》;中国革命战争;', '一 1956年8月9日,《解放军报》一版刊出一则三百余字的简短消息: 总政治部最近向全军和全国人民发起“中国人民解放军三十年”征文,以便汇编一部反映我军三十年斗争历史的军事纪实性质的特写散文集,在1957年7月出版,纪念我军建军三十周年。 这部书', '2011-04-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBPBX_0mwNsnlMZ8N0vNh2Gm4dvLSjvX7HLbyItDhc1_q1V7W6kq8x8wjCkR5hNuasMxvq_WY9rAiNTEyYi87vVsZPT79iVJ2zKWVes8DRJh4eFk8-1U7pucEH3_QNs-AIEmzYOGjH_8g==&uniplatform=NZKPT&language=CHS', '夹金山_screened,强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2929, '报纸', '风正海阔好扬帆', '张晓哲', '中国经济导报', '中国经济导报', '夹金山;“十一五”;', '“刚刚过去的‘十一五’，是我国历史上极不平凡的一段历程。”这是《辉煌“十一五”》大型图片展前言部分的第一句话。 3月22日，《辉煌“十一五”》大型图片展在中国人民革命军事博物馆开幕。此次展览由中央宣传部和国家发展改革委主办、新华社承办，分综合、经济', '2011-03-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID1fg35H-9IRGUOpMIhpx6D-WnpMU14hpLtSVA3MXVZmBpYm6kwhNSZIUS3kIM6vZKX0e5D5CwUZNuNSsuvUpL1oED_cpYO7gN5AAsPR6C5TE9drtMtGNAHwlhanagQQMy4ZbqYWQt4uw==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2930, '报纸', '四川地震灾区：重生在祖国怀抱中', '刘欣欣; 丛峰; 杨三军; 侯大伟; 江毅; 叶建平; 陈健', '新华社;', '新华每日电讯', '灾后重建;胡锦涛;硗碛乡;北川县;住房重建;群众路线;对口支援;都江堰市;四川地震灾区;北川新县城;青川县;汶川县;', '为有牺牲多壮志，敢教日月换新天。不到两年时间，四川地震灾区就发生了翻天覆地的变化。在一片片曾是废墟的土地上，一座座新城拔地而起，学校书声琅琅，车间机器轰鸣。  今天，当我们重新走过那些曾经令我们心酸流泪的重灾区时，我们不禁被一个又一个重建奇迹震撼了', '2010-02-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID1Mh4uNGDfOwxRWZ22-rpnSQDD37NU9oauVPUyrHUNZeOEJGR6UZf1RBgEZUtVCLy9IdAnTSMcOMF00UOHRhdmCeK0RYQX1Riq6JgestyptKdWfXtFlnthzDdLixkBXr6eedplMPHLGg==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2931, '报纸', '在纪念张爱萍同志诞辰100周年座谈会上的发言', '刘奇葆', '中共四川省委;省人大常委会;', '解放军报', '张爱萍;中国工程物理研究院;科学发展观;座谈会;', '各位领导、同志们： 今天，我们作为张爱萍将军家乡人民的代表，怀着十分崇敬的心情，参加中央举行的纪念张爱萍同志诞辰100周年座谈会，回顾他的奋斗历程，缅怀他的光辉业绩，追思他的崇高风范，学习他的优秀品质。 四川是张爱萍同志的故乡，也是张爱萍同志参加革命', '2010-01-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAOMiUISUdqibGN4bPelBLQVKBBl31eI6RSJ8ONFZdZfUyaCNEj3b4zIi6JNDZcsHPNOAxxVHy8RRqaNmuiqwYP4fft-drQ7lotxxDwaaQQhzrbcY15K103xbtEKzElDa1SfkehMHBGLA==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2932, '报纸', '无名英雄蔡威', '陈晓声; 陈国秋', '中国纪检监察报', '中国纪检监察报', '红四方面军;王子纲;马文波;鄂豫皖苏区;右路军;红军长征;无线电通信;中央红军;石达开;肖全夫;党史办;福州军区;', '在我党、我军的历史上，蔡威的名字鲜为人知。他是一位为中国人民革命事业做出特殊贡献的无名英雄，历任红四方面军总指挥部二台台长、红军总司令部二局局长，是我军无线电通信和技术侦察工作的开创者和卓越领导者之一。他的一生充满传奇，他的烈士身份更是在他牺牲50年后才得', '2009-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA0UGUfbwQ65A3qwbpJyla7INsI7zJC_3XKfwyY1YdUpJ7pbz1wHuOE9132jWM_Wlh80wdaJQStQvy6fFPSxA36zZ2JrKrFzF9Z6q-GVifZWZT8fZHPB6E7eDskx5RlZirNBf69aCaD0A==&uniplatform=NZKPT&language=CHS', '夹金山_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2933, '报纸', '会宁：今写教育史奇迹', '陈宗立 ; 韩业庭', '光明日报', '光明日报', '教育史;中国工农红军;', '在共和国的土地上,有这么一块神奇的地方。毛泽东、周恩来、刘少奇、邓小平等老一辈无产阶级革命家,朱德、彭德怀、刘伯承、贺龙等9位元帅以及8位大将、46位上将等,这些中国革命史上功勋卓著的赫赫人物,都曾会聚在此,并在这里书写中国革命走向胜利的历史。  这块神奇', '2009-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBzT99UAqVioCtFHQw8tCvswxI9qPZImQFNI5Y60coYxiLbWHSup3FD6WDL8QqHqTxbtHb3xk4cQZ8UV6gGJQqHNVpjP56-g4NdYDvMwbsI9vO4GlkpWhaqqBxxWjlU_JK24vUQ5lT5DA==&uniplatform=NZKPT&language=CHS', '夹金山_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (2934, '报纸', '“铁”“虎”两师长并肩战灾区', '张玉清; 孟斌; 张汨汨', '新华每日电讯', '新华每日电讯', '抗震救灾任务;高炮团;青川县;', '新华社四川都江堰电 汶川大地震发生后，济南军区“铁军”师长杨剑和“猛虎师”师长胡武帅反应迅速、果断指挥、决策科学，带领官兵急赴灾区，圆满完成各项抗震救灾任务。灾区干部群众和救灾官兵一致称赞：“铁军”有个“铁”师长，“猛虎”师有个“虎”师长。 率领部队', '2008-07-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDpU9aGZ_qdkJasnpFhyr3eQq3l3dtEBW2j_HnKoS1sJeIV0EIBYSl3Jc0zRd3txQanYFUjTUJp7BfgAGGpfbQQq_waCqDsL8Gt3SEgX3RyDe4pigNPGv0DeK5Xkpu-IwXz6179KL9SsQ==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2935, '报纸', '写在“长征路上看法院”采访活动结束之际', '赵俊梅', '人民法院报', '人民法院报', '长征精神;模范法官;长征路上;采访活动;', '昨天，历时两个半月的人民法院报大型采访活动——“长征路上看法院”在推出一系列精彩报道之后，画上了圆满的句号。 今年是红军长征胜利70周年。为了纪念中国革命史上这一伟大创举，本报在最高人民法院党组的直接关心下，精心推出了这次大型采访活动。 采', '2006-11-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDJVO2nakHwCmH_bYamUCph0JnfCBNTT_EoZP9gHUIhGRpVu4Qozad-2iuHutXpjTSvvi-gKYRTAu5ZcLGtXcW8gkwoDw30ujDc93CQ3SsVyBH5DM0NGAJfJfwJFL4s4TLLYhbR_PaP9Q==&uniplatform=NZKPT&language=CHS', '夹金山_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2936, '报纸', '红2、红6军团与红四方面军会师', '', '人民日报', '人民日报', '红四方面军;湘鄂川黔苏区;张国焘;', '中共中央率红一方面军主力北上后，张国焘于１９３５年９月中旬命令左路军和右路军第４、第３０军共约８万人，分别从阿坝、包座地区南下。广大指战员不顾饥饿、疲劳与险阻，再过草地，下旬全部集结于党坝、松岗、马塘地区。１０月５日，张国焘在理番县卓木碉另立“中央”，组', '2006-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBDQ2Wr0k8uhT8SHyCHKZZGTBUDlKhqHOG7WmVcT2EYJ9n54RuSsoGRHTRGnYKERANle4orEmoWfewj1CfXCz_pPfmiWRcbaDyMHd4yhwONyx4qIde3ztwRmVBcyvOm10mzj4erwfIatQ==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2937, '报纸', '中央红军与红四方面军胜利会师', '', '人民日报', '人民日报', '中央红军;大渡河;川陕苏区;', '在中央红军转战川滇黔时，红四方面军为了扩大苏区，并配合中央红军的作战行动，决定发起嘉陵江战役。１９３５年３月２８日至４月２１日，在总指挥徐向前、政治委员陈昌浩指挥下，红四方面军取得了嘉陵江战役的胜利，控制了东起嘉陵江、西至北川、南始梓潼、北抵川甘边界纵横', '2006-10-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAmAtPvTG6FlsbWvyxHttuntufZSnnoqAZ5B8-IiSYqqkZqtSQrJGK_yvCqIpICjiinGsRUrr8daCqrGCHMvQenyaDm3wZ_Pd_CW_12OEXDnGjLHUFmoGaLJtQzZ8U3Zrpo5PTfT6ovtg==&uniplatform=NZKPT&language=CHS', '夹金山_screened,强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2938, '报纸', '热血写就的英雄史诗', '李忱; 郑德刚', '人民日报', '人民日报', '红军长征;夹金山;大雪山;卓克基;小金县;', '９月的川西北高原，风清气爽。阿坝藏族羌族自治州红原县，新落成的瓦切镇牧民新村，年过八旬的罗尔伍身披褐色藏袍，端坐在院子里。这位当年因伤病而留在草原上，被藏民养育的湖南籍土家族“红小鬼”，指着村后红军长征走过的大草原，用藏语给我们讲述着当年的故事。', '2006-10-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC4NsmndzW1j87JIOBZZQGwNdsgbHBka6PU4vLgqHrGq5tkRqF5coYqH0fZie9F0kzdbYyY7QrRm-snl08KtvVoeTM-FBXa0VBHlMz5vuhc7uPX8BIfUk2NZVCjaPirCU36ptU3d99JVw==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2939, '报纸', '长征：熔铸民族灵魂的史诗', '柴葳; 马兆祥; 苗艳丽', '中国教育报', '中国教育报', '长征精神;民族灵魂;', 'F编者按E  T隔着70年的岁月回望长征，也许关于血与火、苦与累、饥饿与艰险的种种记忆， 已经随着时间的流逝远了，淡了，但由举世闻名的伟大远征凝结成的长征精神，无 疑应成为一座丰碑永远地镌刻在中国人的集体记忆中。为了让下一代在变化着的时', '2006-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAoiXUaPcDnIc5fnZuFkXJq21dvruTihgqID53_6Ovp8gupPg1BHqPRt5txy_VQyqIfv9gsjQUmuwoaT9T9ugaFCzEP2KYTnV632_pnse_tgL2fDALACUsJZbXH8kSGjyGBeXD4Jg0SMA==&uniplatform=NZKPT&language=CHS', '夹金山_screened,遵义会议_screened,四渡赤水_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (2943, '报纸', '“最悲壮的死亡行军”：红军过雪山草地全记录', '刘永华; 吴杰; 樊永强', '新华每日电讯', '新华每日电讯', '夹金山;死亡行军;红四方面军;刘洪才;红军过雪山;', '“长征苦，最苦是雪山草地。”90岁高龄的老红军郝毅缓缓地说。  采访中，提到雪山草地，几乎每一位经历过长征的老人，都用了一个“苦”字。  爬雪山、过草地，今天已成为人们体验长征精神的重要方式。然而，70多年前红色大军的雪山草地之行，却无疑是人类', '2006-09-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDvsT3zM_HLsXJBtLGXtOPXm7x84S-w43PY8ZphAn__UgMap6_3IGfP4jhgqLqqkdJUjVDlDU9pAp5G3xjmkxfigH6MxEexQFc_lGmm3ShsnDH8S-jiXi1aI71isQ2PZlUBplC92rhoOA==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2944, '报纸', '密使送张学良亲笔信,写了啥', '黎云', '新华每日电讯', '新华每日电讯', '张学良;密码本;东北军;', '新华社北京电(记者黎云)红一方面军机要三组的杨初振如今已经94岁高龄，他的腿里至今还存留着炸弹片。  长征中，毛泽东经常来到杨初振所在的机要科，守着电话指挥作战。1935年3月中旬，毛泽东正指挥红军上演他军事生涯中最得意之作──四渡赤水。  第三次渡', '2006-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC_OmCzSzm4vjnal88RrCjAE0BKhziR4VMG9UiuYaIbl7j0gAmCoRfC-sKtds1beq80ooqQWspUlpfxgmFUIJR61qW3tznNgv3oartIFAJfTG66Nqs11oMN8GxyUpmQ8KMrWf3DW_9TkQ==&uniplatform=NZKPT&language=CHS', '夹金山_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2945, '报纸', '“张国焘一闹分裂,害得我们多走了多少路”', '白瑞雪; 朱鸿亮', '新华每日电讯', '新华每日电讯', '张国焘;王树声;', '新华社北京电(记者白瑞雪、朱鸿亮)“打仗害人呐。”回忆起过去的岁月，双目几近失明的岳建平有些不安。  1933年农历正月初四，19岁的岳建平在红军驻扎的茅草屋前，他第一次见到了真正的机关枪。“那么大的枪，子弹恐怕要用簸箕来装！”惊奇不已的他被连队留下来吃饭', '2006-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICpDltHrRCX84E6mOwOO_0Y6lgcdbw6Rc288EoYrkLznWSAPQDJqKYKZYjp1TWxir9TJZuxOxsxi8tQf1dzUZTx972Go2kG4sdu5D3XCByn-spuTaWV-xnsCF0l2_YEtCrOAeY7U-ooMQ==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2946, '报纸', '西路军那位女团长,活着', '徐壮志; 梅世雄', '新华每日电讯', '新华每日电讯', '王泉媛;红四方面军;马家军;徐向前;', '她的人生有过太多精彩──“二苏大”代表，中央红军30位长征女战士之一，西路军妇女独立团团长……  她的人生有过太多悲壮──掩护主力同马步芳军队血战被俘，死里逃生后又沿长征路乞讨回家，直到1989年才被确认红军战士身份……  今天，93岁的老人对那段', '2006-08-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAgSZU7tUCfBBcudvPfyMgc7GIqzPLcxKmImRITy4hiGwg8RWBtLW3vjwF-432R2vGExwZ2B2jm6lve8VsNb9OIxRQ9YlIw3TQ4ckn6pY2LNhsIgMr4fGUX3Q9uKtpGlVvKFViJp0jwsw==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2947, '报纸', '弘扬长征精神 谱写改革发展新篇章', '林义成; 张道民; 许春华; 赵化南; 齐殿斌', '山东省新泰市委;山东省新泰市纪委;浙江省纪委机关;解放军某部;', '中国纪检监察报', '长征精神;革命英雄主义精神;共产国际;工农红军;密切联系群众;', 'T最近，胡锦涛总书记强调，坚持不懈地学习中国革命史，发扬光大党的光荣革命传统。今年是纪念中国工农红 军长征胜利70周年。在新的形势下，学习和发扬长征精神，就要坚持实事求是的思想路线，坚定理想信念不动摇， 发扬官兵一致的优良传统和革命英雄主义精神', '2006-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC6t9IJUi2o2ta0Vj5-44zOj6rB-XGv4v99TTXtcQbwuBpqv4wJgSi94thgGlLJ3ItXXo9VWC7e7Fp8SLdltlQthM2hXHkUE0THIWH7Q6fH1GtATfrJ7W1h2Iv5HaHqqOd28WSdtFK2nQ==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2948, '报纸', '信息时代的新长征', '', '人民邮电', '人民邮电', '村通工程;突击队;红军精神;四川省;四川移动;红四方面军;信息时代;', '新长征·路上  香巴拉并不遥远 毛泽东在《长征》诗中写道：“更喜岷山千里雪，三军过后尽开颜”；《长征组歌》里有一段：“雪皑皑，野茫茫”。这里指的就是阿坝藏族羌族自治州的红原县和若尔盖县。 对于阿坝移动来说，“村通工程”全都在偏远山区进行，地广', '2005-09-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICfDZQkMsVDkyr2zqT1TOc1g2cNhInUSzbYFieF1wgJpmTJSTXabGD3dIPTyTdllUHuFyKrSVpK5eM_yBAtUJwtGrp1kC1Gr2QokMIRmrOyi2w2112SObj3xMT5T1MhNRYSTwVRMMlT8g==&uniplatform=NZKPT&language=CHS', '夹金山_screened,强渡大渡河_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2949, '报纸', '突出特色综合开发红色旅游', '刘捷', '四川省旅游局;', '光明日报', '红色旅游;四川省;红色旅游区;旅游发展规划;综合开发;', '旅游资源丰富开发潜力巨大  四川是中国工农红军长征经过的主要地区，是朱德、邓小平等老一辈无产阶级革命家的故乡，是川陕革命根据地的中心区域。四川红色旅游资源具有三个显著的特点：  第一，资源丰富，品牌突出。既有重要的革命历史文化遗址，也有将帅故居、旧', '2005-02-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICgkw16n5bEf7ydKzL4_KToBi3uBF4HeCPe_TOjhNRlMR8jQkyeF3fTtJkP7u9eOHj6cUQ_YzFXZP6AztvjGzgLeUmeLNokQ7EgVNlFSAd1ywDNegqydOmqSUHu5EJNlUWb_RbG-RY4Zw==&uniplatform=NZKPT&language=CHS', '夹金山_screened,强渡大渡河_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2950, '报纸', '四川旅游迎来了大发展的春天', '', '科技日报', '科技日报', '做大做强;政府主导型发展战略;支柱产业;旅游总收入;四川旅游业;四川旅游发展大会;', '9月10日，应邀出席四川省政府召开的“第二届四川旅游发展大会”的国家旅游局局长何光暐，在大会上作了热情洋溢的讲话。他畅谈了中国旅游认真落实科学发展观所取得的成就，以及四川旅游发展的经验。对四川省委、省政府近两年来，下大力气，采取强力措施推动旅游产业发展的做法', '2004-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDeDRM01FZd928ZeEVDyz7EaGx4v03jOuJxrmTBSNTireMuJoRVwNgGGfJRouvsa5Aa8QFaf1srRVTExqq-66wnJwi7Yd2L9lfAbWkaus3qD3ndTOEQ_2i8JHqBmfE3AFEM4q-Ko4ng0Q==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2951, '报纸', '阿坝打造红军长征文化旅游项目', '曾诗安; 邓洪祥', '中国旅游报', '中国旅游报', '红军长征;川主寺;夹金山;红军长征纪念碑园;旅游项目;', '本报讯(曾诗安 邓洪祥)刚刚进入春天，就有6批来自欧洲和亚洲国家的青年旅游团到四川省阿坝州松潘县川主寺瞻仰红军长征纪念碑园，并在长征纪念碑前宣誓要学习和发扬红军长征精神，做一个有志青年。  川主寺红军长征纪念碑园坐落在世界著名风景区九寨沟、黄龙寺交汇地带的', '2004-03-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB4zD3pDg4BwfebSb-kt0fWCQVRMdp9sZCMGRB-lVqQCFQ9M6x9FIBvZy79sOoFpwBxJNdA6BwUMXfIT7JNiOn7xw1f3as5Eogs_3O3bQEi6mszSyAAb_UDMX7u3yWnSul7PSvk7XHB-Q==&uniplatform=NZKPT&language=CHS', '夹金山_screened');
INSERT INTO `ds_article` VALUES (2952, '报纸', '红军，永远的文化', '钟嘉', '人民日报海外版', '人民日报海外版', '红四方面军;红军总司令部;红军长征;', '1935－1936年，中国工农红军长征经过四川西部，在今天雅安市所辖的很多乡镇村庄，留下了足迹，最著名的是强渡大渡河的安顺场和翻越大雪山的夹金山。67年后，记者来到雅安，访问长征遗迹，发现红军已经成为那里永远的文化。 并不像安顺场和夹金山般赫赫有名，芦山县的大', '2003-07-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAFnTG4ekgEc2eJCR0ZsVWGadFOR3wgfeFLbUPP3aoidcO2Nby-At0MEyw1-AxPg6USmTzdcJ-NG_SjBp5HC7P9iQJ5mGUSAi9IahiTqy1rISW02P-pm2NB3QiWlpuutRUuCEnjCEP5ig==&uniplatform=NZKPT&language=CHS', '夹金山_screened,强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (2953, '报纸', '史国利：重走长征路的退伍老兵', '周长庆; 宫庆波', '解放军报', '解放军报', '长征精神;小叶丹;', '一位年过半百的普通农民，在200多天里孤身一人徒步1万多公里，走完了中外闻名的红军长征之路。“一位农民的长征”这段佳话正在他的家乡吉林省广为流传。 这位农民名叫史国利，今年52岁，家住东北平原中部的吉林省德惠市松花江镇老少沟村。他说：“我从小就对长征充', '2002-05-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDi85wd6XEKGfbHlZy9sCOMDn-OAnxsz_Sw2UzE3kEZRPTj0BouPUiwIdi9eUygvLB4LWP5CzIg-6_2kjze1NdTFSPsg7CslaotjgV5Z3HkhngS4HTPrhgqv4YzR2v1huTEIrvCbReaBw==&uniplatform=NZKPT&language=CHS', '夹金山_screened,红井_screened');
INSERT INTO `ds_article` VALUES (2955, '报纸', '乌蒙山新传', '李银; 吉哲鹏; 林碧锋', '新华每日电讯', '新华每日电讯', '乌蒙山;盐津县;竹产业;昭通市;乌骨鸡;', '新华社昆明1月4日电(记者李银 吉哲鹏 林碧锋)从“贫困锅底”到发展热土，地处乌蒙山腹地的云南省昭通市正悄然蝶变。乌蒙山区曾是我国14个集中连片特困地区之一，其中昭通市脱贫人口在全国地级市中最多，是观察我国巩固拓展脱贫攻坚成果同乡村振兴有效衔接的一个窗口。 气势', '2024-01-05 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2024.000063', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2956, '报纸', '中国工程院院长李晓红：绝不能让院士头衔与物质利益挂钩', '高志民', '人民政协报', '人民政协报', '院士增选;工程院院长;李晓红;中国工程院;物质利益;', '“绝不能让院士称号承载过多非学术的、功利的东西，绝不能让院士头衔与物质利益挂钩。”在中国工程院2023年当选院士学习教育暨颁证仪式现场，中国工程院党组书记、院长李晓红为新当选院士颁发证书并作了讲话。李晓红表示，院士是国家设立的最高学术称号，是荣誉的象征，更是', '2023-12-14 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2023.007214', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2957, '报纸', '以更强使命感奋力推动实现高水平科技自立自强', '陆成宽; 操秀英', '科技日报', '科技日报', '自立自强;中国工程院院士;使命感;中国科学院院士;', '“我将以当选院士为新起点，更加严格要求自己，倍加珍惜院士荣誉称号。”“获得中国科学院院士称号，是我科学研究新的起点。”“从今天起，我会将‘四个表率’的要求融入血脉，像爱护眼睛一样珍惜院士这份荣誉，从零开始、保持初心、谦虚谨慎。” 12月8日，中国科学院、中国', '2023-12-11 08:00:00', 'https://link.cnki.net/doi/10.28502/n.cnki.nkjrb.2023.007063', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2958, '报纸', '在科技竞争中创造新辉煌', '詹媛; 张晓华', '光明日报', '光明日报', '科学院;技术科学部;科技竞争;', '“这不是人生顶点，而是新起点!”“未来，要跳出科研舒适圈!” 12月8日，中国科学院、中国工程院分别举办新当选院士颁证仪式以及学习座谈会，院士们情绪高昂，“金句”频出，倍感自豪的同时，他们对肩上沉甸甸的责任也都有清醒认知，那就是在科技竞争中勇挑重担，创造新的辉', '2023-12-09 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.005778', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2959, '报纸', '更好担负起新时代新的文化使命', '曾艳', '云南省委;宣传部;', '学习时报', '中华民族;现代文明;中华文明;中国特色社会主义文化建设;云南旅游;习近平总书记;文化自信;国际文化交流;文化使命;文化传承;', '习近平总书记在文化传承发展座谈会上的重要讲话，从党和国家事业发展全局战略高度，对中华文化传承发展的一系列重大理论和现实问题作了全面系统深入阐述，为坚定文化自信自强、更好担负起新时代新的文化使命、扎实推进中华民族现代文明和社会主义文化强国建设指明了前进方向', '2023-09-15 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2023.000901', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2960, '报纸', '石榴花开结硕果 民族团结谱新篇', '王昌荣; 严国鸿; 韩冬', '人民政协报', '人民政协报', '民族团结;民族团结进步事业;中华民族;石榴花;', '“五十六个星座五十六支花，五十六族兄弟姐妹是一家……”7月10日，在耳熟能详的歌曲声中，四川省甘孜州乡城县“铸牢中华民族共同体意识·唱响民族团结进步主旋律”主题演讲比赛圆满落幕，一句句感人肺腑的话语、一个个暖人心脾的故事，不仅生动再现了各民族之间相互扶持、相', '2023-07-27 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2023.004501', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2961, '报纸', '把初心使命和责任担当写在云岭大地上', '吕金平; 李茜茜', '人民政协报', '人民政协报', '人民政协;云南省政协;习近平总书记;港澳委员;责任担当;', '过去的五年，以习近平同志为核心的中共中央，团结带领全党全国各族人民，从容应对百年变局和世纪疫情，全面建成小康社会，顺利实现第一个百年奋斗目标，胜利召开中共二十大，吹响了向第二个百年奋斗目标进军的时代号角，凝聚起奋进新征程、以中国式现代化全面推进中华民族伟', '2023-01-13 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2023.000244', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2962, '报纸', '农发行云南省分行 引来“生命水” 打通“振兴路”', '苏丽霞; 刘瑾; 刘珀辛', '金融时报', '金融时报', '云南省;农发行;振兴路;', '“感谢党，感谢政府，感谢银行，让我们一家从大山搬来这里，出了屋头就可以做活，日子好过得很咯。”从天麻园干活回来的云南彝良县村民陈小贵高兴地说。 彝良县是云南省革命老区和红色旅游景点县之一，是四面环山、地形复杂、地质灾害频发的典型山区县，易地扶贫搬迁项目建', '2022-08-02 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2022.004287', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2963, '报纸', '穿迷彩的宣传员走进牧场毡房', '李延霖; 谭健', '解放军报', '解放军报', '人武部政委;军分区;青海省军区;藏汉双语;', '心灵之桥在同声相应中搭建 军营中的“藏语角” “草原上的花只有互相簇拥、一起绽放，才能点缀出更美的景色，五十六个民族亲如一家、攥指成拳，伟大祖国才能更加稳定繁荣。”分队长索南扎西流利的藏语直切主题，围坐在一起的藏族群众纷纷拍手称赞。 前不久，在海拔4300多', '2022-05-28 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.002706', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2964, '报纸', '长征途中中共中央召开过哪些重要会议？', '', '学习时报', '学习时报', '中央政治局常委会议;中共中央;红四方面军;陕甘革命根据地;张国焘;张闻天;', '提问：韦平伟 中央团校教务部主任 长征途中，中共中央召开过多少次会议，有重大影响的有哪些？ 解读：毛 胜 中央党史和文献研究院第七研究部副主任、研究员 1935年10月，陈云向共产国际汇报红军长征情况时说：“每次战斗前，连队的党员都召开会议，选出后备指挥员，', '2021-11-29 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002254', '扎西会议_screened,夹金山_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2965, '报纸', '锤炼政治品格 鼓足干事劲头', '黄山; 李娜', '中国组织人事报', '中国组织人事报', '领导班子;责任清单;党性教育;第一责任人;党组织;思想政治建设;习近平总书记;政治规矩;政治品格;', '云南威信 三张清单 凸显政治担当 本报威信讯 （通讯员 黄山）近日，在云南威信县的扎西会议纪念馆，来自全县各乡镇的领导班子成员参加了以“弘扬红军长征精神，走好新时代的长征路”为题的党性教育。“说一千道一万，政治忠诚是第一位的，我们镇党政班子成员严格按照学', '2021-11-26 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.003713', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2966, '报纸', '第八届全国道德模范提名奖获得者名单', '', '人民日报', '人民日报', '道德模范;自治区;村委会;社区居民;退休职工;村党支部书记;贵州省遵义市仁怀市;离休干部;消防救援;公安局;获得者;', '李增军 北京市房山区霞云岭乡堂上村原党支部书记 李 斌 北京公交集团941路乘务管理员 张 琳 中国联通北京电信规划设计院有限公司高级工程师 张莉华（女） 北京利民恒华农业科技有限公司董事长 彭兴利（满族） 北京市怀柔区喇叭沟门满族乡中榆树店村党支部书记、', '2021-11-06 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011729', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2967, '报纸', '彩云之南新跨越', '何欣禹', '人民日报海外版', '人民日报海外版', '红军长征;会泽县;皎平渡口;扎西会议;彩云之南;', '云南，是红军长征经过的重要省份，也是抗战时期全国的大后方。高山峡谷、湿地草原间，留下了无数荡气回肠的英雄故事。数十年过去，在中国共产党的领导下，七彩云南风光依旧，百姓幸福安康，美丽丰饶的云岭大地上，遍布民族团结进步之花。 在建党百年红色旅游百条精品线路', '2021-09-06 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002746', '扎西会议_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2968, '报纸', '新华社记者这样挖宝“藏”', '', '《宝\"藏\"档案》创作团队;', '新华每日电讯', '新华社;和平解放;进军西藏;刘伯承;毛泽东;新华社西藏分社;西藏自治区档案馆;解放西藏;西藏地方政府;', '毛泽东为何作出“进军西藏宜早不宜迟”的战略决策？极端恶劣条件下，解放军是如何进藏的？刘伯承为何将进军西藏称作“第二次长征”？ 如此厚重的历史，如何确保事实的准确性、权威性？如何从浩如烟海的档案中找出最有价值的档案？如何让档案价值最大化，讲好西藏和平解放', '2021-08-31 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.006734', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2969, '报纸', '党史之光照亮履职路', '吕金平; 李茜茜', '人民政协报', '人民政协报', '党史学习;省政协;扎西会议纪念馆;', '近日，一堂别开生面的党史学习教育专题辅导正在云南省政协礼堂内进行。主讲人、省政协主席李江以独特的视角，生动的语言，鲜活的事例，围绕如何学习贯彻习近平总书记“七一”重要讲话精神进行深刻阐释，激起在场机关党员干部的强烈共鸣。 党史如明灯，照亮履职路。今年以', '2021-08-06 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.006362', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2970, '报纸', '以我之牺牲，换人民无忧山河无恙', '沈虹冰; 罗布次仁; 翟永冠', '新华社;', '新华每日电讯', '藏西北;解放西藏;冯桂香;阿里地区;荣誉称号;', '71年前，为完成解放西藏阿里地区的任务，由汉、藏、维吾尔、蒙古等7个民族的130多名战士，组成进藏先遣连，从新疆于田出发，以惊人的革命毅力跋涉千里，横跨昆仑山、冈底斯山，胜利进军藏西北高原，为保卫祖国神圣国土、和平解放西藏，作出了卓越的贡献。 这支队伍，“经', '2021-08-02 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005854', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2973, '报纸', '学习扎西会议光辉历史 传承共产党人红色基因', '阮成发', '云南省委;', '学习时报', '红色基因;党中央;共产党人;红军战士;扎西会议;', '党的十八大以来，习近平总书记多次强调要用好红色资源、讲好红色故事、搞好红色教育，让红色基因代代相传。在党史学习教育动员大会上，习近平总书记指出，中国革命历史是最好的营养剂，重温这部伟大历史能够受到党的初心使命、性质宗旨、理想信念的生动教育，必须铭记光辉历', '2021-06-18 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001075', '扎西会议_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2974, '报纸', '扎西旺堆：用镜头记录西藏和平解放的历史', '降边嘉措', '中国社会科学院民族文学研究所;', '中国民族报', '和平解放;摄影师;第一代;解放西藏;摄影队;谭冠三;进军西藏;摄影机;', '扎西旺堆是新中国第一代藏族优秀电影导演、摄影师、高级记者，这位将职业生涯融入西藏沧桑巨变的参与者和忠实记录者，采访和摄制了上百部作品，留存了涉及西藏的大量珍贵影像资料，见证了西藏翻天覆地的巨大变化。 8月13日，十八军老战士、在党的培养教育下成长起来的我国', '2020-09-11 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2020.000885', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2975, '报纸', '融入剪纸里的红色印迹', '尧红蕾', '江西省瑞昌市纪委监委;', '中国纪检监察报', '红军长征;国民党反动派;', '一把剪刀，一张纸，各色图案纸中来。在剪纸之乡江西瑞昌流传着“无户不剪纸，无女不绣花”的民谚，2008年瑞昌剪纸被列入国家级非物质文化遗产名录。在瑞昌剪纸作品中，不但有民间传说故事，还有感人的红色故事，75双草鞋、一艘渔船、一盏马灯……让我们通过这些剪纸，重温那', '2019-10-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDojJ3eGD-cSElojRbi0T3Vk7Z87eSSjaVm0cX_bKXJ7ESa7MAZbKDVJ5cD13qMvbE2jXBbASvUScIFSzUF83w-pmyy7zYMm1bN58nmq1vU3yohzyJ_lLJYumZymXQlfgcL7bKI3e6jig==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2976, '报纸', '长征永远闪耀着智慧的光芒', '刘小兵', '光明日报', '光明日报', '打赢信息化战争;改革强军;军人血性;主持人;国防和军队改革;', '特邀嘉宾：军事科学院军事历史和百科研究部副部长 李泉 军事博物馆馆长 董长军 国防科技大学人文学院副院长 熊杏林 国防大学军事思想与军事历史教研室主任 马刚 编者按： 长征被称为人类历史上“闻所未闻的故事”，更是人类战争史上不朽的篇章。中国工农', '2016-10-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAF5QDa0oDvV8OLHjS_zX6Z5NXZhgghHHkgbMDH6bHDIv97odEqY6x8xDGrPrk1voAtSw08XaKim_j_tz1XU-pP_iR6a0hgZPvSMtpyY1A5Zz5CCxyEksOR8duo_eWRxEUit3QU9YXk_A==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2977, '报纸', '赤水河，诉说不朽的神话', '吕慎; 柳路', '光明日报', '光明日报', '四渡赤水战役;共产党;青杠坡;', '赤水河，一条红色的河。 1935年，红军在这条“红河”上，3个月内4次横渡，3万人杀出了40万人的重围，演绎了以弱胜强、变被动为主动的神话，书写了世界军事史上的光辉篇章。 绝境中的胜利 1935年1月，红军占领遵义之后，蒋介石急调嫡系部队和川黔滇三省、共约1', '2014-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBEhpdcpnUDfYZUovGA6W7THX0GIaayejFJIQXdgKxLL7wbWkPA_0jTlbrvNiL3BxttvTWt66H2QTuKxHEoclC7nPQkQks4jXrtkM75gNN-V4-ig9dyXONmV_zgtN8k0JjLnkeuuOPvyQ==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2981, '报纸', '海拔4516米,这里有我', '刘兴安 ; 魏兵 ; 郭丰宽 ; 银军', '解放军报', '解放军报', '军分区领导;高原病;抗缺氧;社会福利院;高原反应;羌塘草原;', '生命的意义，在于长度，还在于高度。西藏那曲军分区门诊所护师彭燕，用12年的坚守和拼搏，展示了一名“雪域天使”的生命高度。 在彭燕工作的地方立着两块石碑，一块刻着“海拔4516米”，另一块刻着“祖国，这里有我”。 千年那曲，万里羌塘。这里含氧量不足海平面', '2011-06-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBCSyUKiUABy05kSRiXQXlKAYfGFbryZexSBlbpDfe6hBehtHmM73B5tBc8zAKIo_y_vHOGC8gCaRO53fClQ0EU32LBponLRyuGfI4TpleauxsXJJQ6SN4mNwqGIlPCqSCODLDzXSO9ZQ==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2982, '报纸', '第三届全国道德模范候选人事迹', '', '人民日报', '人民日报', '劳动模范;中共党员;候选人;', '全国助人为乐模范候选人 101 毛陈冰 毛陈冰，女，汉族，1987年1月生，中共党员，支付宝（中国）网络技术有限公司设计部职员。 QQ群里一则求助信息，让从未出过远门的20岁女孩，只身完成了此生第一次远征。她日夜兼程赶赴贵州山区，用自己240毫升的“熊猫血', '2011-05-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAzgDYZzHiYkNTqMIn2adiUIQ9zgxyNTp1xEi8BgjIaQDn5SdV_tzAUtZiRruInRH5bBaKKOILG0GeWFiW5Qu9qMDjCCShCA31jMyaDhqskw8coP7YtrHiR9WTfNXpd6aBlctd9uxqfWw==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2983, '报纸', '探寻红军所向无敌的精神源泉', '范炬炜', '解放军报', '解放军报', '两河口;夹金山;泸定桥;', '是巧合，还是情思神往的牵引？记者驱车夜行，沿大渡河奔泸定，忽然发现车内电子日历已跳入5月28日——哦！76年前的今天，长征路上中央红军左纵队先头部队红四团，正在这里创造着一昼夜冒雨行军120公里的神奇时速，飞夺泸定桥之战即将打响！  泸定桥，在滔滔大渡河水和静', '2011-05-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID2nZ9IPFmDSOr2e06QKEVL8AC4clf0GFqIETiUN19AF1NckoFICcG5kDn5qbCcpzq7coTnGzbbNddEEsJBX7Y1bx4v5nbDaa7uCd8M8YWv-0oH1BTnemVj870hqXhcrPeDU83PAFlQUw==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,夹金山_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2984, '报纸', '从挫折走向胜利伟大转折点', '', '新华每日电讯', '新华每日电讯', '中央档案馆;中共中央政治局;中央红军;张闻天;“左”倾;成文时间;', '新华社北京5月18日电1935年1月15日至17日,中共中央政治局在遵义召开扩大会议,史称遵义会议。出席会议的政治局委员有毛泽东、张闻天、周恩来、朱德、陈云、博古,候补委员有王稼祥、刘少奇、邓发、何克全(凯丰),还有红军总部和各军团负责人刘伯承、李富春、林彪、聂荣臻、彭德', '2011-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBC-XgV0aPYztT9jrRLkhVt8U1mFVjdKpbrt8WFytocOK2IL2xNWyo8UZuYZs-CoVaznh8mHkVRChuV9Fq2acCTVZ0aM6QQ8JjeG3BOIHhumoYX0QPSzj7guZvieD3pbo8UokdH7nsjag==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2985, '报纸', '在没有硝烟的战场', '董强; 丁海明', '解放军报', '解放军报', '抗震救灾精神;人民军队;结古镇;汶川抗震救灾;', '仰望永恒不熄的精神火炬 诗人说，有的人死了，他还活着。 历史说，有些记忆虽远去，但永远燃烧不熄。 2010年4月14日7时49分，中国玉树，7.1级大地震。从这一刻起的48小时内，解放军和武警部队1.3万余官兵，从四面八方风驰电掣集结于震中结古镇。一场波澜壮阔', '2010-08-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAV5Z_ykMGWsVVxUJ3-MIgVwzPM6oYlgLcTPCmfqlBO0BBPPb1k0jIy6oNjqMC5Gl8auNDhd3taYnBdOs7W2qN1QXC6tM7a_DKAznMT7zUf0dJlIkKUmrU0dFp9-xJ0zWQrogNN5fGgEQ==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2986, '报纸', '当人民有难的时候', '丁海明; 夏洪平 ; 费士廷 ; 李建文', '解放军报', '解放军报', '结古镇;兰州军区;帐篷学校;医疗队;第二炮兵;格萨尔王;玉树军分区;', '2010年4月14日7时49分，中国青海玉树。一场7.1级大地震，震碎了三江源头宁静的黎明。一场战天斗地、争分夺秒的生命大救援，在平均海拔4000多米的高寒地带拉开了气壮山河的帷幕。近13000名人民解放军和武警部队官兵紧急出动，义不容辞地成为救援战场上的主力军和突击队。', '2010-05-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICXkSX3ttURjFaGrNBvYx7T7LON8DK3l9ORXexrBOKgYUPRgF43jtPzmtxz7h9jvvnnGLLHQm68AZNMFUNBUMyWvb3HOiaP6jwf8jweG2FQF5o-fARKlo6goxIatd-8nGUhdDQTRGNvPA==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2987, '报纸', '乌蒙磅礴 风光无限', '姜兴华; 汪北城', '解放军报', '解放军报', '乌蒙山;扎西会议;扎西整编;威信县;鸡鸣三省;中央红军;红色旅游;', '有道是：在什么山，唱什么歌。 “红军不怕远征难，万水千山只等闲。五岭逶迤腾细浪，乌蒙磅礴走泥丸……”金秋时节，记者踏访乌蒙山深处的云南省威信县，品味毛泽东主席的诗词《七律·长征》，对其中“乌蒙磅礴走泥丸”有了更深切的体会——中国工农红军在山连山、山叠', '2009-11-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDq0AeMSLWx7M_jfbSXWkLAunc2CQ4fP487f8YMhzuRTWOg1BNt_pokDSV4-1n6QtH8MwA99-DTpAfH6UXgzEGiiYfeQ-u80eGbSzWAEPYoOF_EDu9Wae5PHHu51Pv22LwVt3xY1qE_XA==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2988, '报纸', '肩负历史使命 展示长征精神', '王燕琦; 高敏婧', '光明日报', '光明日报', '长征精神;', '长征是中国革命史上辉煌的一页，通过展览的形式将这段光辉的历史展现出来，让人们感受长征的精神，思考长征的意义，是《纪念中国工农红军长征胜利70周年》展览所肩负的历史使命，也是展览工作人员所承担的艰巨任务。  此次长征展览不仅汲取了历次同类展览的精华，还', '2006-12-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICgtaq9WjvZ1ta5VqjYU78vDwn4xzSBPcT_tyoij-b_OO2NDhO4wwLjgpzLIHAJ-EkSUSfSi5FTWjgu-B5-TflA81YpLKSjTzsGX_LQInmBsNxfrwBGY0dGAUzVbuvPGN5oXUgmQ10zrA==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (2989, '报纸', '四渡赤水(上)', '', '人民日报', '人民日报', '中央红军;国民党军;娄山关;', '中央红军占领遵义后，蒋介石为围歼中央红军于乌江西北的川黔边境地区，调集中央军薛岳兵团和黔军全部，滇军主力和川、湘、桂军各一部，共１５０个团、４０万兵力，向遵义地区进逼。中央红军只有１６个团、３.５万多人，敌我兵力极为悬殊。在这种情况下，中共中央和中革军委决', '2006-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAmYjm59p932vNl00ocx4aHd1He6MEcNXuMBVsnS7Q_wprxuwfZujOck323t82M-QAeqWyVRBtUCwnGoJzP9EnHt8UQlIlPsoBsF3KAj5kiPeoB2t2EBL76Vc_RrJAyulyxKBoRX8DfJQ==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2990, '报纸', '红原：“马背法庭”情洒高原', '王银胜; 赵刚; 聂敏宁', '人民法院报', '人民法院报', '法庭;审判庭;法官;法律工作者;', '红原县，位于青藏高原东部，四川省阿坝藏族羌族自治州中部，为纪念红军长征悲壮的历史而得名。红原，是大多数红军进入草地的起点，也是红军一、二、四方面军三大主力在四川境内唯一共同经过的地方。 10月19日，我们“长征路上看法院”采访组经过长途跋涉，来到红原', '2006-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICW04A8qvNAAZsM44ctXgL1s8lOCgYxlmtFM6dWvi48Zcf9UTD5OUsdunClNkw0gAZWfrRS8XxNSk5uDdFXes7k_LEoy31qZXM0yImbs1ngotBFWssUIAcuaBFitAz3sgVdICjUCxZ12Q==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2991, '报纸', '光彩神奇的篇章', '陈伟光; 孙海涛', '人民日报', '人民日报', '四渡赤水战役;中央红军;团政委;', '“……苍山如海，残阳如血。”毛泽东同志曾对这首作于四渡赤水战役期间的《忆秦娥·娄山关》加了一段批注：“万里长征，千回百折，顺利少于困难不知有多少倍，心情是沉郁的。”  在长征胜利７０周年之际，我们踏访四渡赤水战役发生地，上娄山、访苟坝、寻渡口……重', '2006-10-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLxQB0-CfVZv8Q8nAEdu_OPESaSskoNXdZ_djplWWO_6ChLz24otcyeak4aaFq1zFmU32UMREIzL8vOQwbkpcNNmyuRmoUpSWHVeqQkHqFz18qExMU9tgldLMsgKNLnjdd5GylHie_ow==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2992, '报纸', '在历史的转折点上', '陈伟光; 孙海涛', '人民日报', '人民日报', '张闻天;毛泽东;王稼祥;战略战术;', '“没有遵义会议，就没有长征胜利，就没有抗战胜利，就没有全国胜利！”９０岁高龄的谢振华将军（长征途中彭德怀麾下的团政委，曾任昆明军区政委）在北京接受记者采访时，谈及遵义会议，语气坚定。  时间过去７１年多了，遵义会议的２０位参加者俱已逝世。而我们至今', '2006-09-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICHM041hlMpp-62lu7Qy38CFz79AbtLcA0o0gt2SCuLwkGfIkmWpnZu7X0LADgjCnvz36HlFS2beSws43JNv4LEYhvVvARMFlP9V1z5kbgc4lyu7Zem1R3H8rmLmPWyMsUMdtRRJc_eeg==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (2993, '报纸', '扎西会议学术研讨会举行', '', '光明日报', '光明日报', '扎西会议;中央党史研究室;学术研讨会;', '由中央党史研究室科研管理部、中共云南省委党史研究室和中共云南昭通市委联合主办的“纪念红军长征胜利70周年——扎西会议学术研讨会”，6月4日在京举行。中央党史研究室副主任李忠杰、中央文献研究室副主任李捷等与来自学术理论界的程中原、张静如、张树军、何方、张琦、肖', '2006-06-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBT9tiQIwkGubu_oo-8Yu3lyEU6ot2Mvcof9BQ_ZudjpMSHMXBS2ajDTFvGgNyuG-gKyinRjP3ObN4psGmcCpGOYvCwbUgQdPLcnb3DUlshhM8R1IFMaaxzV1H3al5RzKdH3VsRk6hkpA==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2994, '报纸', '云南部署全省红色旅游工作', '刘栗', '云南记者站;', '中国旅游报', '红色旅游;旅游发展规划;', '本报讯　云南省 红色旅游工作会议日前在著名的扎西会 议召开地——威信县隆重召开。云南省 副省长刘平、省委宣传部副部长黄峻、 云南省旅游局局长罗明义等参加了会 议。据悉，此次会议是云南省政府首次 在县级城市召开的高规格、大规模的', '2006-01-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDrCXyz0tBGd5IeBL4DNYYIbA-PxmI2e18a_Z052e0g_w-dMF-4CNYZZRna3uOf2_OCRGo4SmIRE3dvj91DDhzvS4VH7AZSTdzCL4InD0Hzgf3MYySoFu8dQA_ItSWOwStjm-Ma42uSeA==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2995, '报纸', '二十年：大凉山上的铿锵承诺', '盛若蔚', '人民日报', '人民日报', '马班邮路;二十年;大凉山;', '山又高来路又险， 翻了一坡又一坡。 哪个喜欢天天走？ 因为人民需要我。 今年老王四十岁， 牵着马儿翻山坡。 为人民服务不算苦， 再苦再累都快活！ ———摘自王顺友自编苗族山歌 二十年，每年至少330天，在苍凉孤寂的深山峡谷', '2005-06-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICqJT48uNiSVClLnPyzfZ_p1Y_-5lEq8mYmvFnNztW43gI0Kgn9x_6BhAE67eU2ncC2awkUj-at9KL10dhn_ey6j-gWWcLoWRYE3Li_IR-2vgGXaOduP2YRahuJT9Z__n9JucbQ9cEq0A==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2996, '报纸', '科技中国55个新第一', '', '科技日报', '科技日报', '中低速磁悬浮列车;克螟稻;', '五十五项成果见证中国 五十五位专家寄语中国 雷凡培（中国航天科技集团公司第六研究院院长）： 我们作为航天事业的科技工作者，更要鞠躬尽瘁。 杨伟（成都飞机设计研究所总设计师）： 国防力量的增强意味着国家力量的强大，我们希望国泰民安，世界和', '2004-09-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBqzBBlja6ZbEiU0ZUrRkSt6A5HLcRtPcdBPFAkLXtJ97gTTrOHStDlP8q1Pw-CBhBSphQqGkuikodFkLB50eKoI5u0vrNPXufkpRjscbC55WzeA80uZm82kqkmDNHQl1QrY4kJC2oryw==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2997, '报纸', '坚持以人为本 推动全面进步', '董强', '解放军报', '解放军报', '以人为本;三个文明;全面进步;', '如何完整准确地理解经济社会全面、协调、可持续发展？怎样在物质文明、政治文明和精神文明共同进步中做出应有的贡献？连日来，军队人大代表、政协委员就这些共同关心的话题进行了热烈讨论。  协调发展局面来之不易  京西宾馆724房间的讨论，是由温总理《政府工作报', '2004-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBxtyv_Z7qd0N93TYoOCajPJOYShHAOcXK5YIzgH7tH5DbmlkXdGeSBEddh22Dvk4nrspErTKv7-9-g-SuM_8FhVvfrqDrB6WcG6YslhAkIOAU9OPudK8caIvI1csYBX2de_1phO7FlDQ==&uniplatform=NZKPT&language=CHS', '扎西会议_screened');
INSERT INTO `ds_article` VALUES (2998, '报纸', '第二批全国爱国主义教育示范基地名单', '', '新华每日电讯', '新华每日电讯', '烈士陵园;秋收起义;教育示范基地;爱国主义;', '北京市  1．李大钊烈士陵园2．焦庄户地 道战遗址纪念馆3．北京自然博物馆 4．中国航空博物馆5．中国科学技术 馆  天津市  1．平津战役纪念馆2．周恩来邓', '2001-06-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICTBNq0K-Xq7ms2Y6SLXmqpF8Xf9ggWIEorcPtW6xbpPMJSLfs--cBxHuVAon3kjc9raLjGy_3E-s6hB_zkOzPEGj7V7ZllpELHGra5TM7YfSW_R-JXQ7hPh2WKg7g3QcA7o-xLGg6U9Q==&uniplatform=NZKPT&language=CHS', '扎西会议_screened,强渡大渡河_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (2999, '报纸', '“护心人”光雪峰的“护心之路”', '王长山; 丁怡全', '新华每日电讯', '新华每日电讯', '昆明市延安医院心内科;', '虽然已退休，但在云南昆明市延安医院，依然能看到光雪峰医生忙碌的身影，他仍每周定期坐诊，奔忙于病房和手术室之间，同心血管内科团队的医生一起救治患者。 “心脏上的病无小事，我们就是要用心呵护。”40多年来，光雪峰和同事一起帮助大量患者摆脱病痛折磨，成为患者信任', '2024-01-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2024.000070', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3003, '报纸', '向世界介绍真实中国的大卫·柯鲁克', '孙东方', '学习时报', '学习时报', '十里店;', '大卫·柯鲁克（1910—2000年）是一位犹太裔英国人，是与白求恩、斯诺同时代的杰出人物。20世纪30年代末，他怀揣着共产主义信仰远渡重洋来到中国，从此把根扎在了中国。他在中国工作长达半个多世纪，关心、支持并积极投身中国的革命和建设事业，为新中国培养了大批英语人才，', '2021-11-22 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002207', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3004, '报纸', '与白求恩并肩战斗的珍妮·尤恩', '李彦', '学习时报', '学习时报', '白求恩;加拿大共产党;并肩战斗;', '在位于河北唐县的白求恩墓旁，紧隔着一堵低矮的石墙，立着另外一座坟茔，墓碑上镌刻着几个字：加拿大友人琼·尤恩之墓（1911—1987）。当年，受加拿大和美国共产党派遣，随白求恩同船来华的，还有一位年轻的加拿大女护士。这位白人姑娘有个美丽的中文名字：于青莲。中国国内', '2021-11-15 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002156', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3007, '报纸', '“做白求恩式好大夫”', '白剑峰', '人民日报', '人民日报', '白求恩;辛育龄;', '辛育龄，中日友好医院首任院长、新中国胸外科事业的开拓者和奠基人，“七一勋章”获得者。做白求恩式好大夫，是他一生的理想和追求。 把个人理想与党的事业紧密相连 辛育龄的从医之路，与白求恩有着不解之缘。他在战火中淬炼砥砺，从一名战士成长为专家。 1921年2月', '2021-09-05 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.009431', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3013, '报纸', '一部“新发现的《红星照耀中国》”', '王京雪', '新华每日电讯', '新华每日电讯', '《红星照耀中国》;新发现;中国共产党;拉铁摩尔;毛泽东;笔记本;埃德加·斯诺;中文课程;', '“毛泽东那年43岁了，身材瘦削，动作敏捷，浑身上下透着一股青春的活力，显示出年轻小伙子一般的气质来。” “不言而喻，在那座缺吃少穿的陕北小城里，存在着一种独特的生活方式……除却插在朱德或周恩来上衣胸前口袋里的那支钢笔之外，你几乎看不到任何等级上的标志。红', '2021-07-30 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005833', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3018, '报纸', '路远情长，人民军医回老区', '陈小菁; 崔寒凝; 周娜; 陈伟杰', '解放军报', '解放军报', '人民军医;医疗队;邓海燕;', '“你们哪个是韩英哟，我想见见韩英……” 人群中，一位头发花白的大娘嘴里念叨着，几缕头发被汗水浸湿，贴在激动得有些泛红的脸上，裤脚沾着泥点子。 “大娘，我就是韩英。”一双手握住另一双手，大娘掌心粗糙的老茧和温度，让韩英红了眼眶。 1987年冬天，一位大娘', '2021-06-30 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004138', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3020, '报纸', '延安时期中国共产党如何涤荡污名化', '敖带芽', '学习时报', '学习时报', '中国共产党;斯特朗;毛泽东;国民党;污名化;', '延安时期，中国共产党在自我构建形象方面的主要障碍来自国民党媒介的污蔑丑化以及国际上对中国的“刻板印象”。面对国民党政府对中共的政治隔离和新闻封锁，在极端困难的条件下，如何让外界真正认识中共在抗战中的中流砥柱形象，如何把延安的声音发出去，让世界认识真实的延', '2020-05-15 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2020.000980', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3021, '报纸', '白求恩精神，医者前行的力量', '', '健康报', '健康报', '白求恩精神;医务工作者;', '1939年冬，太行山东麓，国际主义战士诺尔曼·白求恩倒在了救死扶伤的前线。同年12月21日，在延安的窑洞，毛泽东同志写下了著名的《纪念白求恩》。从此，白求恩的名字在中国家喻户晓，并深深印刻在民众记忆里；白求恩精神，感召着无数中国人，并成为医疗卫生界一面高扬的旗帜', '2019-12-21 08:00:00', 'https://link.cnki.net/doi/10.28415/n.cnki.njika.2019.000470', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3023, '报纸', '光雪峰：宠辱不惊医者心', '张磊; 于梦非', '健康报', '健康报', '心内科;白求恩奖章;', '“对我而言，只是做好了本职工作，医生这份职业，正是要求极致的严谨、耐心和责任心。”见到光雪峰时，“白求恩奖章”授奖仪式刚刚结束。作为云南省昆明市延安医院心内科主任医师，他30年如一日，以极致的耐心和细腻，让无数患者的心脏“重归于好”。 每次出诊，在走进心', '2017-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDPKeGKE-4IqPI2MmUQnORlA_yUxEbCPmgzV-IDjG6XTGzAZu37TiNruEcjxpACL3tzUzWJrEZBAw7gYyd-99dccdkTtzuslQIE-MIqHsqY5cgYdI6LT3PzthM6O1Kqlog8nbCc4LJxxQ==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3026, '报纸', '延安精神，点亮医者信仰', '', '中国妇女报', '中国妇女报', '延安精神;白求恩精神;', '实事求是、群众路线、自力更生、艰苦奋斗、不断开拓创新——70多年前，包含了深厚“养分”的延安精神，在延河之畔这片黄土沟壑中诞生。 作为一名医生、一名共产党员，生于斯、长于斯的李红梅，在27年的行医生涯中，时刻未忘延安精神之于这座城市的意义，时刻未忘延安精', '2013-12-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAkTMh6Y_wbdCJUmZuaYRcY5xq1l-dAjRsNvQCnXllF051ewHlNGdQ9nb0lPPFx461uGfsrDfCdSQKO9fJxePEPlUlhqD4fgFsJKlR8uqyzVhkGP9iSp97M6FkEJrfPfAl1QmYE4llqkQ==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3029, '报纸', '以史为鉴 倡廉育人', '叱骁峰', '中国纪检监察报', '中国纪检监察报', '廉政教育;陕西省;教育示范基地;廉政文化;延安革命纪念馆;纪检监察机关;杨震墓;廉政思想;以史为鉴;', '无论春夏秋冬，他都要去给“四知先生”杨震的陵墓除草修葺。 他就是渭河边上一名普通农民，名叫杨焕海。作为六十一代杨震墓的守墓人，他目睹了这里的变迁。 “之前，这里曾多次遭到破坏，甚至被夷为平地，为了守护一代廉吏杨震的陵墓，我吃了很多苦。”望', '2013-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBvKg1V6-tM4qrbNOTHN2BHl1mqCRV7FRczJvZ3kkGAGD9BOD5ek_M1IzMR6J4ImNt2qhvtfOzvfuCJGpoajmep82Li7MejTJ6S8GydLq52v_8aFNK-pqdXRp2R-gdGC14ckJSgfYf54w==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3034, '报纸', '生死朋友永不忘', '赵焱; 张保平 ; 荣娇娇 ; 杜静 ; 刘亚南 ; 吴强 ; 蒋国鹏 ; 蒋新彤 ; 李大玖 ; 杨向若', '新华每日电讯', '新华每日电讯', '柯棣华;红星照耀中国;中国共产党;史沫特莱;国际主义;', '上世纪二三十年代,有这样一群人,他们怀着崇高理想,踏上战火纷飞的中国大地,与中国人民并肩战斗,谱写了一首首国际主义之歌。斯人已逝,余音仍存。中国人民永远不会忘记他们。 埃德加·斯诺:“我爱中国,我愿死后把我的一部分留在那里,就像我活着时那样” 埃德加·', '2011-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDnWSMCz9T0ON4TOBL7YVXiupYrCTj5O1JsiJxugWLXgCawlqXoUq3h98rPkUSjsH0bD9fot4k7ao9M6sezoc8xJ3cif9i_mim4PjlLKvrN-4aupTh2Yq8FDl7gn7AzowmqsS6608--IA==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3035, '报纸', '海纳百川汇人才', '丁增义', '解放军报', '解放军报', '海纳百川;', '如果仅仅从外表看，灰墙灰瓦的七贤庄一号院，只是古城西安一处普通的工字型土木结构平房院落。临街马路上汽车行人川流不息，人们似乎忘记了，上个世纪三四十年代，这里曾经上演了多少激情澎湃的故事。作为八路军西安办事处所在地，这里曾和国家的前途、民族的存亡紧密联系在', '2011-06-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID1SPW9d1YC2NKiTcq_2Bb9Sue4YhqYcO8HKAAJojfEGdkJQESo3Ypei-sfG_L4-FsEwhMtEhDU66yE-QxayaQGrdLodFEA3Nci-hbH4PYSw2BBm8Z8q0B3aWaAw8RtKEC4IFjHCZk6jw==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3040, '报纸', '化作春泥更护花', '赵天冬', '农民日报', '农民日报', '奶牛场;机械工业部;小王庄;', '6月8日，伟大的共产主义革命家、国际共产主义战士、中国绿卡第一人、中国农业机械科学研究院畜牧业专家寒春同志因病在北京逝世，享年89岁。农业部部长韩长赋发来唁电。6月18日，中国农机院举行寒春同志追思会，农业部原部长何康、原副部长刘成果等农业方面的领导出席了会议。', '2010-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBFMyR0T2_1OsTjWlonndaH1M63d0EEnYisvrN-5vxXIpxBP6ryB2gyj9xPcZDOLrjhN0oUpzUVaRKXECnZcTuov80qCHzzYoVVrXqqNr6oLTNER5GicwmldM0oUMhPTAcxykvaKkJQeQ==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3046, '报纸', '一心为兵让党放心', '刘玉书; 宫曦岭; 田义伟', '中国国防报', '中国国防报', '军分区;党员领导干部;', '军分区司令员与士兵，年龄相距成倍，职务也相差多级。但他能做到与普通士兵一起干、一起学、一起玩，看不出任何等级距离，您相信吗？  球场上，战士敢和他疯抢；困难时，战士能向他借钱；餐桌上，战士争相把菜往他碗里放；遇到家庭矛盾，战士肯向他亮“家丑”，您意', '2005-12-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLYZAmhHNSKvGEyVSxfp1V_6hndZgeJu121uhepWaVbfEitrSD0QaysLe4pHP_gfUmNInPN8UWVaGRdUOUaZacTXAB8qRN0st3-LP9MIyBmNnvxfm_YSyIQSwqBzxndF6PxzBKshT9KQ==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3050, '报纸', '“把手术刀变成抗日宝剑”', '李文政', '人民日报', '人民日报', '白求恩;戴维森;手术刀;', '加拿大安大略省中部的格雷文赫斯特小镇，历史上是一座伐木小村落。这个人口不过万人的小镇因伟大的国际主义战士白求恩出生于此而闻名遐迩。在这里，记者采访了现年35岁的白求恩纪念馆馆长斯科特·戴维森。 戴维森先派人带领我们参观整个纪念馆，然后介绍了白求恩49', '2005-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAwW7DnHX93qrukoMeEA1ijMPWJgOWSwPC3rVVr97eOYtCWc7Tf27kB-1-EvIfR9XUoknqVstcHq3D1OlhvQCnbtaGDKEtLyTqVIB3M9Uz_QtwdkSFkqzaqwZKnbhbWt0kJmnBNHBxBsA==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3052, '报纸', '东方主战场', '冯春梅; 王建新', '人民日报', '人民日报', '世界反法西斯战争;第二次世界大战;平方千米;全世界;中华民族;', '“中国的抗日战争不仅是一场中华民族自身谋求独立和解放的战争，更是世界反法西斯战争中不容忽视的重要组成部分，是世界反法西斯战争的东方主战场。”站在中国人民抗日战争纪念馆川流不息的参观人流中，纪念馆原馆长张承钧先生郑重地说。 墙上悬挂的《中国人民抗日', '2005-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDXvKcwGjDE68lOP19lFmUi453eClMSA8nXydixHRBq3v2bdda-jy8pFyDe5CSqZlejbBDh8kI1fSngPkx4Rd8eNC3LMwekSLtBZEYxET4nn1dqFxNZfrUxMPF19C_jagoNVuKRf94Ayw==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3057, '报纸', '跨越世纪的怀念', '张静宇', '人民日报', '人民日报', '柯棣华大夫;中印两国;', '12月9日，一个在中印两国人民友好交往史上不应被忘记的日子。60年前的这一天，一名印度医生年轻的心脏在中国人民抗日战争的战场上停止了跳动。从此，中国人民记住了这个被称为“中国儿子”的印度优秀青年的名字———柯棣华。60年后的同一天，怀念柯棣华的人们再次聚集在金', '2002-12-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBhY0xJLE6mSEOiq6_RkHstTAD4QdV-p4Ph9TBjGsKHdOK9Dsj4saiI7jSh8svrEiWPtaAShRlRl7ZO_7ium9LBYTnF5x_q7MCmR2vX2D6LEBI0d_Wt6ABn2xiWBfzID5T6FDimQgLv3A==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3058, '报纸', '踏访白求恩故居', '陈特安', '人民日报', '人民日报', '白求恩;毛泽东;八路军;加拿大;', '驱车从渥太华西行4个多小时，即抵达伟大的国际共产主义战士诺尔曼·白求恩的故乡——格雷文赫斯特镇。仅有2.6万人口的小镇干净整齐。两年前落成的白求恩铜像屹立在小镇中心的剧院广场，白求恩身着八路军军服，右手执听诊器，脚穿草鞋，双目炯炯有神，右腿有力地迈向前方。', '2002-11-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBEQMDd2lKrQuIZJCcTZ-8WvVR_Up_I6mCe36KDy6Ql3erfyxHD0YPtQzejiFZvBZWfZ9kpWWOFVmJWWpWvzwdXYiQ952eHgUEBUTOURx00riKIVzb1bEb84DDiwpcei-7WQkBpwj55sg==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3059, '报纸', '为时代描绘风云', '韩爱萍', '光明日报', '光明日报', '周而复;《夜行集》;郭沫若;', '“巍巍嵩山滔滔黄河贡献智慧培育人才建设祖国继往开来”。这是著名作家、书法家、河南大学卓越学子周而复为母校八十年校庆的题词。十年之后，为庆祝母校九十华诞，他提出要为母校捐赠图书和书法作品，并欣然为校庆丛书《河南大学作家群》题写书名、提供资料、撰写文章……拳', '2002-09-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICtQDW8g60wmmV_muES63SJqhY-LsENakmA3ZEqe2YlrdQpfQvDwtUOdPT6aFbs4asT8yPqb2nSaola8iu19Y0CMiEXVxJ4a8e--OQxqeqsexj2tjJIK67Ptjkr8_1lcx0DdoIYBpdTIA==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3061, '报纸', '用画笔为人民功臣立传', '侯尔瑞', '光明日报', '光明日报', '人民功臣;肖像画;', '中央美术学院教授李琦先生，从事革命文艺工 作已经有64年的时光了。多年来，他以其传神之笔， 为中国营造了一座独具风格的肖像画长廊，被誉为 “中国革命伟人肖像画家第一人”。如今，在陈毅元帅 百年诞辰来临之际，其新作《陈毅元', '2001-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIABgBEc153Ur3DlwhZuXtJDlVgwTGtCTezYeSoxESpw6FToKbJAmYYcg25AatKjY8n1SjFvHOlv65vP-ymg5RQB8eUIs-ieUi2xV5DKEILthKkV4_4GE8wPVSpDBPCh_llyv5Z8V-c7Ag==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3062, '报纸', '为人民服务的由来', '倪迅; 翟伟', '光明日报;新华社;', '新华每日电讯', '毛主席;李君如;', '张思德、雷锋、焦裕禄等 一个又一个楷模和他们“为人 民服务”的思想犹如中国共产 党人崇高精神的丰碑，矗立在 中国人民的心头。不仅如此， 老百姓心中评价政府公务员优 劣的“那杆秤”，常常也是 “为人民服务”。虽然《为人 民服', '2001-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDMsv5lTanKhxJEkF4sUkITDLNqloAxPoqgqSaaNLnxXBlrxvN7dy8k8fdBcmk73mIhF_pm4TtuIpp5UM_CS6OevK3j5PlhDBOt26sacQE6Msc7nsZy2azTsd3qxMW2cch1jakSWeCnXQ==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3063, '报纸', '关心农民生活 密切党群联系', '王金涛', '新华每日电讯', '新华每日电讯', '党群联系;', '新华社石家庄5月3日电（记者 王金涛）“五一”期间，中共中央政 治局委员、书记处书记、国务院副总 理温家宝专程到太行山区看望农村基 层干部群众。他强调，从事农村工作 的广大干部，一定要牢', '2001-05-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAHwcY-EuQYTimEAJLBJZ2kKXhe0UD6HMcJWIvl8DD8QnfTEFP3Hgeeh7Sw1XwkknhZZPpdB4dsMAd6ajDFz7tQWcR9S48WWPcEYmiMUWOWSQzfN7j8qWIeIuXLT5XnExvW-Ui0RSBnAw==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3064, '报纸', '白求恩铜像在其故乡揭幕', '张颖生; 肖陵军', '新华每日电讯', '新华每日电讯', '白求恩;克拉克森;', '新华社格雷文赫斯特（加拿大）8月 19日电（记者张颖生 肖陵军）伟大的 国际主义战士诺尔曼·白求恩大夫的铜像 揭幕式19日在他的故乡、加拿大的格雷 文赫斯特镇举行。  竖立在镇中心歌剧院', '2000-08-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICc532vbl2m7xyk8gWvYFc8XhdXHfcBObZ3WwieJJUBVfLl_4AHUbX_93C6NfPhvBrQKuLWmEkeSK8MXxyiuMXeNq80e9nDBhNEMqoZq7epqNY-FlFM1PPa0YEGXz0D3EDhnWjoXyy0Uw==&uniplatform=NZKPT&language=CHS', '白求恩_screened');
INSERT INTO `ds_article` VALUES (3079, '报纸', '我眼中的延安精神', '沈冲', '中央政府驻香港联络办公室协调部;', '学习时报', '延安精神;共产党人;', '5月5日，恰巧是革命导师马克思的诞辰日，我们在中国的革命圣地延安汇集。在这里，我们回溯中国共产党在延安发展壮大的13年；在这里，我们通过老师授课和阅读教学材料，在教学相长、学学相长、互相交流、互相启迪中，思想得到了充实，认识进一步升华；在这里，我们实地学习中', '2013-06-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDHmdZp9m1d4RPatP22Qst7GTOVy0HOcs3K7d-om29DUcsiNuv7RsuzgahyZChRQ6fRLTEb2HBQQv6s5Otw2pAYYBla71dfXVSmzyCgWAKpW3-AmRvbiiYHo9WjonwfzSLqVo-dDwK_hg==&uniplatform=NZKPT&language=CHS', '凤凰山_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3088, '报纸', '“红军山”下新长征', '孙海涛', '人民日报', '人民日报', '红军山;共产党;红军长征;创建点;红军烈士陵园;', '木板屋，石板路。以“红军街”为中心，方圆两平方公里的区域是贵州遵义市里最漂亮的地方。这里集中了遵义会议会址、红军总政治部、苏维埃银行、红军警备司令部、博古旧居、遵义会议陈列馆、红军干部大会场、红军烈士陵园、邓小平住居等9个长征纪念场所。 “前来参观', '2009-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB1aY1jfPQUuzV_o-3ZJWCw9LzIMs49_pbxItyAfUtepjCIHFWR8iCuXy1JELy7U_XTLs5fibH4dTgIQmdVZkbSax8vHQN1l9j8IsG-cYX7e1cs0a_LO5_f9VosELEOtTYsaDLucdsEIA==&uniplatform=NZKPT&language=CHS', '凤凰山_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (3096, '报纸', '延安：革命圣地品牌亮旅游产业潜力大', '刘晓辰', '经济日报', '经济日报', '中国优秀旅游城市;', '本报讯 记者刘晓辰报道　享誉中外的革命圣地延安正在创建“中国优秀旅游城市”，市长张社年对此充满信心。  至今没人评估过“延安”品牌的无形资产。但是，以其在中国历史上的特殊地位，延安旅游产业的发展潜力巨大是不争的事实。  1999年，市委、市政府提出建', '2002-08-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAUfQj6XSdWVfMrI048sFdBo-JKNgjD-bMwaV12G37RJxH1R4SGGE6GdG-e9vmjnox1B5-BjLlkxKVDL-lUCdS4JdfEm2fXOWYtYuOamq8CpjhKNW2R9f4e-WPs4kTXmna0WOlkHM4xcQ==&uniplatform=NZKPT&language=CHS', '凤凰山_screened');
INSERT INTO `ds_article` VALUES (3098, '报纸', '《中国共产党军事工作重要文献选编》主要篇目介绍', '', '人民日报', '人民日报', '中央军委扩大会议;习近平;毛泽东;中国共产党军事工作;军队现代化;《中国共产党军事工作重要文献选编》;', '新华社北京7月30日电 由中共中央党史和文献研究院、中国人民解放军军事科学院编辑的《中国共产党军事工作重要文献选编》，已由中央文献出版社、解放军出版社出版。现将该书主要篇目介绍如下。 《关于纠正党内的错误思想》是毛泽东同志1929年12月为中国共产党红军第四军第九', '2023-07-31 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.007710', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3099, '报纸', '延安时期中国共产党对中国式现代化的探索与实践', '徐鹏; 周瑞莹', '西北政法大学马克思主义学院;', '人民法院报', '中国共产党;中国式现代化;探索与实践;', '习近平总书记在党的二十大报告中，将新时代新征程中国共产党的中心任务概括为“团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。”实现中华民族伟大复兴一直以来是无数中华儿女的心愿，是中国人民的奋斗', '2023-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAhQ8u-GUqtQGJNNRDWHDOhSZjGl2gxEKROt6fQPgsyq7ntCk64mBxUrSfGBVw0S5DXMewGCd_xtGeqN8uTov2nwLXlHVfxFBIN_9vruu1wDr1U9ikT95j9qvWD0dHGg_-E4lylVs5z0A==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3103, '报纸', '2022展望：长期主义的当下意义', '安仁', '金融时报', '金融时报', '中央经济工作会议;企业家;市场主体;战略规划;抗战期间;《论持久战》;当下意义;', '抗战期间，一位记者采访了一名前线作战的中国军官，问他中国能不能取得最终胜利，那位军官对胜利坚信不疑。记者追问他胜利何时能到来，他回答说，那时我已经死了，看不到那一天了。 长期主义被人称道，是因当事人对长远目标的不懈坚持，最终成就了非凡的事业。在尚未远去', '2022-01-07 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2022.000086', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3109, '报纸', '延安民族学院“团结”理念的价值意蕴', '吴明海', '中央民族大学教育学院;', '中国民族报', '延安民族学院;价值意蕴;中华民族;抗日民族统一战线;', '延安民族学院是中国共产党为培养少数民族干部和从事民族工作的干部而创办的一所专门学校，成立于1941年9月18日。开学之初，毛泽东应广大师生热情要求，亲笔题词“团结”相赠，“团结”不仅成为广大师生的座右铭，而且成为延安民族学院的办学理念。在延安民族学院成立80周年之', '2021-11-02 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001118', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3110, '报纸', '穆青在黑土地', '邹大鹏', '新华每日电讯', '新华每日电讯', '东北抗联;《东北日报》;赵占魁;群众运动;新华社;周保中;黑龙江日报报业集团;吴文焘;东北抗日联军;东北日报;八路军;哈尔滨市;黑土地;', '一路从风雪中走来 “一九三七年没有芬芳，没有花香，等待我们的将是弥漫全国的抗日烽火，将是决定民族生死存亡残酷的斗争!” 在这篇《迎一九三七年》的文章中，一个叫穆亚才的15岁少年，在民族的寒冬风雪中，用笔书写出浪漫与激情，也点燃了理想的革命火种。 坐标，', '2021-10-29 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008347', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3118, '报纸', '党在延安时期的对外宣传', '杨云成', '学习时报', '学习时报', '延安时期;共产党;对外宣传;美军观察组;国民党;根据地;', '延安时期，面对国民党的封锁、诋毁、污蔑，我们坚持“走出去”与“请进来”相结合的策略，开展了一系列对外宣传和国际交往活动，摆脱了舆论困境，赢得了各界人士支持。其中所秉持的理念、建立的机制、采取的措施，对于在国际上传播中国共产党的声音发挥了重要作用。 “走', '2021-07-30 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001380', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3119, '报纸', '永不消逝的红色电波', '杨昀潮; 刘仲亚', '人民邮电', '人民邮电', '反“围剿”;毛泽东;无线电技术;中央红军;', '1921年，伟大的中国共产党诞生。从星星之火到燎原之势，从开天辟地到日新月异，中国共产党带领全国人民书写了中华民族自强不息、顽强奋进的壮丽史诗。伴随着党的发展壮大，红色电波传递党的声音，发布党的命令，助力中国革命取得了一场又一场伟大胜利。 今年是中国共产党', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28659/n.cnki.nrmyd.2021.002055', '论持久战_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (3125, '报纸', '“文风改进永远在路上”', '户华为; 王斯敏', '光明日报', '光明日报', '改进文风;习近平总书记;刘跃进;在路上;', '编者按 文风关乎世运，世运隐于文风。文风不仅是语言风格和个人喜好，更折射党风政风和社会风尚，关系到事业兴衰成败。环顾时下思想文化和理论学术各领域，文风问题依然不同程度地存在。新形势下，我们要促进文化大发展大繁荣，加快构建具有中国特色、中国风格、中国气派', '2016-10-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDrd1OEpl-kyNcVzoLMKawgzdtj7u0Lq1--s1T-z1x1ZkYwU-LmB5i09RJyjpdMT9jOzerHS8uJYQwB5RB5nbFCdc5fLDq9cVMQSfXYsM3wt18Wuyu-8rJGusVtiYT6So-oaERmClRJAQ==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3130, '报纸', '支撑起全民族救亡图存的希望', '', '解放军报', '解放军报', '抗日民族统一战线;抗日战争胜利;中国共产党;日本帝国主义;共产党人;', '“平津危急！华北危急！中华民族危急！”大厦将倾之际，总有人力挽狂澜；国家危亡之时，总有人挺身而出，他们是民族的希望。中国共产党人就是支撑起全民族救亡图存希望的人。 “遥望中原烽火急，狂流一柱在延安。”中国共产党的中流砥柱作用是中国人民抗日战争胜利的关', '2015-08-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB7dCC4pthcwqtuCFV9nF-pY36Y3dpczgGBkPyyoEfPfGqDNXm7L87oRc-Znr9xtbBxmjUzo4HARUpoNk3y3ZxA5_XsS7yZNz8ewWTqVaR2rDq2Z0L1KE50KIjM8YsMTTNGlf1MpEinoQ==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3131, '报纸', '中国取得抗战胜利的历史经验', '肖裕声', '军事科学院世界军事研究部;', '光明日报', '抗日民族统一战线;八路军;抗战胜利;卡尔逊;中国共产党领导;新四军;抗日根据地;历史经验;', '中国的抗日战争，是中国人民在敌强我弱的情况下，以坚定的决心和意志，经过14年的殊死搏斗，赢得近代以来反抗外敌入侵的第一次完全胜利，开启了中华民族走向伟大复兴的历史征程。抗日战争的胜利，为中华民族提供了走向复兴的宝贵经验与历史启示。  一是必须有一个为', '2015-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBIxWbh6ZTVXDkghfpLMPU6mRObz2XbLvuR8vbCvbIwDIRJ3d-kE_ipIuImjwy2tsdcSCWKTwbm0UCts3uxmo8n0ZuKpd9cbymfyYdWtitnTv5oVaDPF9CbA1d2r-5WZWUYYRKwMf9GXQ==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3136, '报纸', '强军事业呼唤强军文化', '', '解放军报', '解放军报', '强军文化;习主席;先进军事文化;革命军人;', '题记  “一个没有精神力量的民族难以自立自强，一项没有文化支撑的事业难以持续长久。” ——习近平  （一）  甲午秋日，古田。习主席在出席全军政治工作会议期间，邀请11位部队基层干部和英模代表共进午餐。午餐的内容非常简单：红米饭、南瓜汤……', '2015-05-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAncqaTyNVKeZFLRG2-1bcY44NnX6LQtNJ7X5ZQBZkqT92ZnN4MJjxQrySarE_hhyoRGfxwqOpZ4vpF1dFn52YK5mP-YZKUPUbRp72hiz_bp42J1XUAm3MnBokJ7KhHIwzOBk9WoJPoxw==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3138, '报纸', '《论持久战》写作发表的前前后后', '杨永林 ; 张哲浩', '光明日报', '光明日报', '《论持久战》;毛泽东;怎样进行持久抗战;', '初秋的延安，绿色漫溢，凉风习习。带着一种朝圣般的心情，记者来到延安凤凰山下的一处普通的窑洞。这是一代伟人毛泽东在延安时期的一处故居。76年前，对抗战时局产生重大影响的著名文章——《论持久战》，就是在这里挥笔写下的。 70多年恍如昨日。说起《论持久战》的写', '2014-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICarXUVcLm8USsLt1A5xyUojmsPpb7oIkJ8swRDigvtUTGLd8KW-uYctE7RLzFlLvGOHS06IUlXzyZjO7yXiIpk8gpM3GCDZVg0Jb3Lec4BYRvV_uqm62PJLk7bZOSqaGDDvG0UYTY4Cw==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3141, '报纸', '“我的笔既要对历史负责， 更要对未来负责”', '王晋军', '中国文化报', '中国文化报', '毛泽东;王朝柱;历史人物;重大革命历史题材;实现中国梦;主流意识形态;人性描写;影视作品;刘胡兰;长征精神;周恩来;中国共产党领导;《花木兰》;', '文艺作品要引领精神，烛照人心，最终还是要靠人来践行。 《长征》中我写一段“捉虱子”的情节，毛泽东在延安接见外国友人前，曾叫大家回过头去，他要脱下裤子捉虱子。他还在一次会前公然提出捉虱子比赛。这是真事，有人说这样写会不会给领袖抹黑？然而，人们看到的却是', '2013-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA9kDJUu2HfvjU4g1NjqFFdRSvCNqliRBxBFfQqqzm3ro3fX5UAGgVBNEfyhp2idQOqbXWWlsr0i78Tu0hOSi2aNms_Q7a2i4PyTtv7bl8u0hXoQgAW8TmPhAm_eUjHFLlcLYoTDWDHHQ==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3142, '报纸', '《中国抗日战争史》“总论”', '', '人民日报', '人民日报', '中国抗日战争史;抗日战争;中华民族;《中国抗日战争史》;世界反法西斯战争;抗日民族统一战线;日本帝国主义;反法西斯统一战线;局部抗战;', '中国抗日战争，是中国人民反抗日本帝国主义侵略的正义战争，是世界反法西斯战争的重要组成部分，也是中国近代以来抗击外敌入侵第一次取得完全胜利的民族解放战争。在这场战争中，中华民族同仇敌忾，浴血奋战，创造了弱国打败强国的光辉业绩。 一、反抗日本帝国主义', '2011-09-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICmojU_v3z9dGhlP4K1-qoEmB2KSiit3IlLTVHCaNoypq-QCDjX5cttZEbb_LbdwBKScXmhm1qiQRnVvlULnftb_2C1ExZw9-4xfhJFH0-Q5THq6aDY39RCMyskkyWP5I0aaG2bpmoxDw==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3144, '报纸', '宝塔山下新长征', '苏文甫 ; 刘国顺 ; 郭江山', '解放军报', '解放军报', '学习型党组织建设;建设学习型党组织;宝塔山;', '春节临近，西安政治学院虽然放了寒假，但学院“网络课堂”上的学习活动却开展得红红火火。在这个“永不下课的课堂”上，从学院领导到普通战士，从专家教授到参训学员，人人都有学习计划和成果…… 这种尚学之风哪里来？学院党委书记、政委刘强告诉记者：主要得益于该院', '2011-01-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICTD8tuvXT5MMZ-An1JSrMjaVjDVTeu4BswkyADJ1nz4afxUa6973nZhOx0j-ZiX4I8BG4wtyDI2IKKp2pHenLdsF0saTBFOSLH9Ih_-2zFhPkDGR1KBrFzf7iEk-IK-I7P5sE_kjQatA==&uniplatform=NZKPT&language=CHS', '论持久战_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3147, '报纸', '聆听延河,热泪为谁流？', '武天敏 ; 刘国顺 ; 郭江山', '解放军报', '解放军报', '延安精神;毕业学员;高粱米饭;张俊贤;毛主席;李荣贵;', '从小雁塔边的校园，到宝塔山下的窑洞，记者的心穿越历史的峰峦，徜徉在一条32年光阴铺就的寻根之旅…… 在采访西安政治学院弘扬延安精神的日日夜夜，最令记者难忘的，是许多人在追忆和倾诉中流下的泪水。 漫步在延河边，聆听河水吟唱，一首“信天游”从山梁土峁飘', '2010-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAVQ3cahvpRcOdAYRDNncJ5jPBOHjbRsOx0iURXkpouwYyVpw4ZrBKRhIKg5UABkf1m5QO1EM3qy8BG5r040tgrRmsSnjXfFCdkpF4_Z-10NmxB3PyEtGJtrrH73AEtgzozVASc_Jt8Gw==&uniplatform=NZKPT&language=CHS', '论持久战_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3149, '报纸', '学习毛泽东读书的精神', '申晚香; 林义成', '中国纪检监察报', '中国纪检监察报', '毛泽东;马列著作;党员领导干部;', '今年4月22日，中共中央政治局常委、中央纪委书记贺国强向中央纪委监察部机关团委致信，寄语青年同志勤奋学习、磨砺品质、踏实工作，并向他们推荐《毛泽东的读书生活》一书，勉励他们了解毛泽东的读书生活，学习他读书的精神、态度和方法，陶冶情操，提高素质。为此，记者就怎', '2010-05-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDxOuTZkiL1uwhuw3VdtGjE8DE2IMQ7Yjv12U0OrYWvcDy-1VoSugF-x9wDbf0uZbkakmggDmjO-vXgKshZUjWc3lPQk_q5o0_-RdQB0MifCEolPXYfY994TUb0LqKtw415yLjlqT0BjQ==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3156, '报纸', '《解放》周刊', '', '人民日报', '人民日报', '《解放》周刊;共产党;抗日民族统一战线;《解放》;抗日战争;抗日根据地;新四军;游击战争;', '１９３７年４月２４日，中共中央机关刊物——《解放》周刊在延安蓝家坪创刊。《解放》周刊辟有时评、论著、翻译、通讯、文艺等专栏，中央领导同志毛泽东、张闻天、朱德、周恩来、博古等都在该刊上发表文章。作为中国共产党的政治理论刊物，《解放》周刊积极宣传中国共产党的', '2007-02-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBISqNC4JjtELusAqY6NUhhfYPsmdUk7ZQyEqhfbGdEvJ8_GdrxWagEsC70fMZqwhUZjAxkJzbFLvlbmjOY0zX7mMBQ9BUKzM_ulP7OuXyTa7d7yISFbmhD0h5PYT9dSBSpioUjeAExSA==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3164, '报纸', '血战──抗日战争经典战事回眸', '李宣良; 梅世雄; 黄明; 孙彦新; 陈辉; 杨庆民; 王洪山; 吴杰; 刘昕; 陈玉芬; 樊永强; 孙承斌; 李斌; 邹声; 明星; 徐机玲; 石永红; 蔡玉高; 肖春飞; 金旼旼', '新华每日电讯', '新华每日电讯', '日本鬼子;八路军;马本斋;平型关;新四军;湘西会战;雪峰山;抗日战争;', '淞沪战役  粉碎日军“速战速决”企图 回放：1937年8月13日，叫嚣“三个月灭亡中国”的日军开始进攻上海。日军先后投入30万兵力，动用了300多架飞机、几十艘军舰。中国军队将70多万兵力调往淞沪战场。随着日军不断增援，中国军队逐渐处于劣势。11月12日，上海沦', '2005-07-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBgGFoXNUpxBuIiJ_oeKbKUngdfBzbWyb_u9TRDETMgy2N8qVVA_VhrN0N0aAalqICeWmGg2r7xN5v-h5iCp8hZ9cE9thmdnqjwqM_QQFjglmZu9d9vm2EbscCjLZ6dmSC371XJprRYXA==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3172, '报纸', '“七一”是党的生日', '刘宋斌', '新华每日电讯', '新华每日电讯', '中国共产党;群众性;', '中国共产党第一次全国代表大会于1921 年7月23日召开，而党的诞辰纪念日是7月1 日。为什么两者的时间不一致呢？为什么7月1 日成了党的诞辰纪念日呢？  中国共产党于1921年7月成立后，在反动', '2001-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDFdfQGbaVYl6EYVp48KBZRmRPchz4muWLcEQm9u5-r3dOovvElIropnFhtkCFtoONnA4HwCOLOUWvD4LDS8natBrFqlFGGvXd5feu94l8i5tTVOVBNNTzVfHDMt05bH8fhcqJF5Dxj0w==&uniplatform=NZKPT&language=CHS', '论持久战_screened');
INSERT INTO `ds_article` VALUES (3173, '报纸', '党史上的“第一”（6月25日）', '潘洪声', '新华每日电讯', '新华每日电讯', '中国共产党;毛泽东;中共中央;', '八一南昌起义──党 领导打响武装反抗国民党 反动派的第一枪  到1927年7月，由于蒋 介石、汪精卫相继背叛革命， 轰轰烈烈的大革命终于夭 折，血雨腥风代替了生气蓬', '2001-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBnCD60d-ycg--gGo7r1c6pGEUguj_vJLmzUcbTHKGqbpnaLD31UovlR4rWJvowA_c8R-WmwfHEnnyDZ9EfS8KNCYF8gSae4WmSEMg1zN2AXw42Ke8kmAoDvWTDwqRu8Wrg9lOqEVKS7Q==&uniplatform=NZKPT&language=CHS', '论持久战_screened,卢德铭_screened');
INSERT INTO `ds_article` VALUES (3177, '报纸', '永远在路上', '朱基钗; 孙少龙; 高蕾', '新华社;', '人民日报', '全面从严治党;党中央;习近平总书记;反腐败斗争;制度规范体系;中国式现代化;在路上;', '治国必先治党，党兴才能国强。 进入新时代，以习近平同志为核心的党中央以前所未有的勇气和定力推进全面从严治党，开辟了百年大党自我革命的新境界，探索出依靠党的自我革命跳出历史周期率的成功路径。 踏上新征程，推进强国建设、民族复兴伟业，习近平总书记向全党发出号', '2024-01-08 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2024.000213', '杨家岭_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3178, '报纸', '搭建检察干警成长成才平台', '孙立昊洋; 马金顺; 赵愿', '法治日报', '法治日报', '检察干警;延安市;人民检察院;青年干警;检察长;成长成才;', '“98、99、100、101、102……”100名书记员肩并肩围坐在一起，双手紧握并晃动由于人力拉伸变得硬如钢铁的绳圈，齐心协力突破预定圈数。 这是陕西省延安市人民检察院举办全市检察机关书记员综合素能提升班期间，干警们挑战“团队动力圈”项目的生动场景。 如何将检察人员培', '2024-01-03 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2024.000050', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3179, '报纸', '红色的歌声 永续的精神', '沈虹冰; 贺占军; 张斌; 李浩', '新华每日电讯', '新华每日电讯', '陕北民歌;陕北地区;《东方红》;南沟村;延安时期;革命老区;', '是深情的想念：“羊肚子手巾儿哟，三道道蓝，咱们见个面面儿容易，哎呀拉话话儿难……” 是非凡的巨变：“如今的南泥湾，与往年不一般，再不是旧模样，是陕北的好江南……” 是不尽的崇敬：“东方红太阳升，中国出了个毛泽东，他为人民谋幸福，呼儿嗨哟，他是人民大救星…', '2023-11-08 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.006644', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3180, '报纸', '“双节”中国风 浓浓家国情', '', '新华每日电讯', '新华每日电讯', '亚运会;世界遗产;亚运场馆;客流量;', '金秋时节，中秋国庆“双节”联动，节日氛围格外浓厚。人们或与亲朋好友欢聚一堂、或到红色景区瞻仰朝圣、或携全家老小助威亚运……丰富多彩的文化活动令假期洋溢家国温情。 情怀激荡 红色，是国庆节主色调。在革命圣地陕西延安，全国各地游客纷至沓来。 记者在杨家岭革命', '2023-10-06 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.005963', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3187, '报纸', '不忘初心 再踏征程', '李欣然', '中国文化报', '中国文化报', '中央乐团;合唱团;艺术家;《黄河大合唱》;延安精神;音乐会;严良堃;瞿弦和;李心草;', '今年是鲁迅艺术学院（简称“鲁艺”）成立85周年，值此之际，中国交响乐团合唱团前往延安，于4月7日至11日与延安大学鲁迅艺术合唱团共同举办纪念鲁艺成立85周年暨《黄河大合唱》合唱音乐会，并前往红色纪念馆和景区参观学习。 重返起源之地 追寻艺术初心 鲁艺于1938年4月成', '2023-04-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICXUbfxoaBTfGwkuBJEb1cmwERGmjRY3gwzxnPK7nReBAk_O974ACJIehJS13noRJXyDlukMC_lpp2JpUOQb9uVYdLrSlW5de-TjOfyhtneyOKWT_gVzVbUa4X1GpaEY6pDJTasZcgLHw==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3188, '报纸', '凝心铸魂向复兴', '朱基钗; 丁小溪; 王子铭; 高蕾', '新华社;', '人民日报', '习近平总书记;中国特色社会主义;中国共产党人;时代化;马克思主义中国化;', '中国共产党人依靠学习走到今天，也必然依靠学习走向未来。 3月30日，中共中央政治局召开会议，决定从今年4月开始，在全党自上而下分两批开展学习贯彻习近平新时代中国特色社会主义思想主题教育。当天下午，中共中央政治局就学习贯彻习近平新时代中国特色社会主义思想进行第', '2023-04-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.003432', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3189, '报纸', '陕西延安 红色文化搬上舞台、放进手机、引入生活', '刘源隆', '中国文化报', '中国文化报', '红色旅游;红色景区;红色革命;红色文化;实景演出;', '延安是中国革命的圣地、新中国的摇篮。春节期间，延安独具特色、内涵丰富的红色旅游景点成了全国游客自驾游、亲子游的重要选择。数据显示，“十三五”期间，延安五大文化旅游板块加快建设，到延安的游客突破2.5亿人次，红色教育培训达到80.8万人；2022年延安是红色旅游目的地', '2023-02-04 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2023.000332', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3191, '报纸', '“要把人民放在心中最高位置”', '冯华; 李心萍; 王浩; 常钦; 罗珊珊', '人民日报海外版', '人民日报海外版', '美好生活;虚拟养老院;', '“精准扶贫‘瓦吉瓦’（好得很）!”四川凉山彝族自治州昭觉县三河村村民吉好也求说。 2018年2月，习近平总书记来到海拔2500多米的彝族村寨。进了吉好也求家，掀开床褥，摸摸被子，看看够不够厚实——我一直牵挂着彝族群众，看着你们生活一天一天好起来，很高兴，希望孩子们', '2023-01-20 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2023.002618', '杨家岭_screened,神山村_screened');
INSERT INTO `ds_article` VALUES (3193, '报纸', '心怀火炬，点燃更多“星火”', '朱桁冈; 肖力铭; 张琳; 云利孝', '解放军报', '解放军报', '政治教员;理论宣讲;', '“要弘扬伟大建党精神，弘扬延安精神，坚定历史自信，增强历史主动，发扬斗争精神，为实现党的二十大提出的目标任务而团结奋斗。”认真学习习主席在瞻仰延安革命纪念地时的重要讲话，陆军工程大学研究生学员姜洋洋心潮澎湃。 探访梁家河，参观杨家岭，赶赴南泥湾……前不久', '2022-12-09 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.006420', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3194, '报纸', '管好用好革命文物 传承弘扬红色文化', '任丽', '中国旅游报', '中国旅游报', '文物局;陕西省;延安精神;文物保护;传承弘扬;红色文化;', '在陕西延安杨家岭革命旧址，来自杨家岭福州希望小学的“小小讲解员”王家逸时常在毛主席种过的菜地前为游客讲述杨家岭的红色故事。他说：“革命先辈艰苦奋斗的故事让我更深刻理解了什么是延安精神，也给了我更大的学习动力。”这是陕西用好用活革命文物的生动写照。 近日，', '2022-11-29 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.003353', '杨家岭_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (3198, '报纸', '用“延安精神”培养堪当民族复兴重任的时代新人', '孙海华', '中青报;中青网;', '中国青年报', '延安中学;少先队员;共青团员;时代新人;习近平总书记;民族复兴;', '“习近平总书记来延安中学啦!”10月26日，习近平总书记到延安中学考察，这几天学校师生们沉浸在激动和喜悦中，热议着当天的情景。 此行，习近平总书记看校史、访餐厅、进课堂，在教室里听同学们说理想，称赞他们人生目标明确，理想高尚。他勉励同学们从小树立远大理想，立志', '2022-11-03 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.003704', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3205, '报纸', '中国新法学会与马克思主义法学理论中国化', '韩伟; 薛永毅', '西北工业大学;西安交通大学法学院;', '人民法院报', '法学会;马克思主义法学;中国化;陕甘宁边区政府;李木庵;', '延安时期，随着马克思主义中国化的发展，马克思主义法学理论中国化也随着新民主主义革命、法制实践而逐步形成。在这一历史进程中，1941年6月成立的中国新法学会是在中国共产党领导下的民主抗日根据地内影响深远的一个司法专业社团。中国新法学会的成立和有关工作的开展，不仅', '2022-07-22 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2022.002586', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3208, '报纸', '“努力做祖国和人民需要的好孩子”', '赵婀娜; 黄超; 吴月; 丁雅诵', '人民日报海外版', '人民日报海外版', '习近平总书记;少年儿童;', '“从小坚定听党话、跟党走的决心，刻苦学习，树立理想，砥砺品格，增长本领，努力实现德智体美劳全面发展”“努力做祖国和人民需要的好孩子，做祖国和人民事业发展的接班人”…… 党的十八大以来，习近平总书记多次走进中小学课堂，回信勉励各族学生，深入贫困地区家访，在', '2022-05-31 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2022.001607', '杨家岭_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3209, '报纸', '赓续红色血脉 永远心系人民', '刘源隆; 刘淼; 王伟杰', '中国文化报', '中国文化报', '文艺创作;毛泽东;瞿弦和;中国煤矿文工团;延安鲁艺;习近平总书记;文艺工作座谈会;石油工人;美术馆;吴为山;文艺工作者;《在延安文艺座谈会上的讲话》;', '“以强烈历史主动精神推进社会主义文化强国建设，为实现中华民族伟大复兴提供强大价值引导力、文化凝聚力、精神推动力。”5月23日，纪念毛泽东同志《在延安文艺座谈会上的讲话》发表80周年座谈会在北京举行。结合纪念《讲话》发表80周年，学习习近平总书记关于文艺工作的重要', '2022-05-24 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.001549', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3219, '报纸', '为了人民 服务人民', '李晓明; 刘驰', '新华每日电讯', '新华每日电讯', '张思德;为人民服务;', '“张思德同志是为人民利益而死的，他的死是比泰山还要重的。” 1944年9月8日，毛泽东在战士张思德的追悼会上作了一次影响深远的演讲。这篇题为《为人民服务》的演讲，是祭文，也是宣言。从此，一个普通战士的名字，与一个政党的根本宗旨紧紧联系在一起。 张思德的一生', '2021-11-10 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008623', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3220, '报纸', '刘文西：一辈子把心思放在人民身上', '李亦奕', '中国文化报', '中国文化报', '刘文西;毛主席;黄土地;主题性创作;陕北人;', '他是拥有最多“观众”的画家，他笔下的毛主席惟妙惟肖，第五套人民币上的毛主席画像就是由他绘就；他是将根深深扎进黄土地的人民艺术家，黄土地的厚重博大在他的笔墨之间挥洒；他一生勤俭，笔耕不辍，教书育人，以一生的践行成为艺术工作者学习的楷模。 “你要创作吗？到', '2021-11-07 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.003400', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3223, '报纸', '延安：红色旅游迎新机 老区振兴添动力', '任丽', '中国旅游报', '中国旅游报', '红色旅游;革命旧址;乡村旅游;红色文化;红色旅游资源;红色旅游目的地;旅游演艺;', '陕西省政府日前印发的《新时代支持革命老区振兴发展若干措施》明确，传承弘扬红色文化，发挥革命文物资源、爱国主义教育基地等红色资源在党史学习教育中的作用，加强革命历史题材文艺创作和宣传推广，提高红色旅游产业经济占比。 作为革命老区，近年来，延安深入实施“文', '2021-09-15 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002666', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3235, '报纸', '人民是剧中人也是剧作者', '韩毓海', '北京大学习近平新时代中国特色社会主义思想研究院;', '中国纪检监察报', '文艺家;李满天;赵树理;贾大山;毛泽东;短篇小说;延安鲁迅艺术学院;《白毛女》;', '“北风那个吹，雪花那个飘，雪花那个飘飘，年来到。” 这段经典旋律，至今已经传唱了70多年，可谓经久不衰。这支曲子，就来自歌剧《白毛女》中的经典一幕“北风吹”。《白毛女》，正是在延安文艺座谈会之后，延安鲁迅艺术学院在新秧歌运动中创作出的中国第一部新歌剧。', '2021-05-21 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.002422', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3237, '报纸', '延安整风：增强党的战斗力的一个伟大创举', '孙忠法', '中国组织人事报', '中国组织人事报', '延安整风;马克思主义;整风运动;高级领导干部;战斗力;', '在延安杨家岭毛泽东旧居，有一张拍摄于1942年的照片：毛泽东穿着打有大块补丁的裤子，给八路军第120师团以上干部作报告。这张著名的照片展示的，正是抗战期间全党一场深入的马克思主义思想教育运动——延安整风运动。 在抗战紧要关头开展全党整风，是以毛泽东为核心的党中', '2021-03-11 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.000793', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3243, '报纸', '“三八”妇女节是如何传入中国的', '闫树军', '人民政协报', '人民政协报', '“三八”国际妇女节;纪念大会;“三八”国际劳动妇女节;妇女代表大会;国民党统治区;打倒帝国主义;妇女部;何香凝;妇女运动;第一次全国代表大会;传入中国;全世界;封建主义;中国共产党;美帝国主义;北平和平解放;', '3月8日是国际劳动妇女节，又称三八节、妇女节。 中国第一次公开纪念“三八”妇女节，是在何时？当时是怎样的一种情形？是谁在这次大会上发表讲话？而在武汉举行的10万人参加的“三八”妇女节大会，又是怎样的？都有谁莅临了这次大会？ 陕甘宁边区为适应抗战需要，“', '2019-03-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBjaJ-w6CR82_FmcVhtyzxfgMnka35Cn9H1ISuAPJ3f9CxuvW0GW5t-D24IsCsK6xvFAHlzZPM0y-xj7em2DQkga3oHvIdMwfMo_PaCsLTPdm4nsN3jiGwwgqBFSS492Yr90k8ZAFUmAA==&uniplatform=NZKPT&language=CHS', '杨家岭_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (3244, '报纸', '勤奋是中国奇迹的内在“密码”', '迪昂; 吕德胜; 张武刚', '空军航空大学;', '解放军报', '中国奇迹;飞行表演;', '中国是世界第二大经济体，经济和科技等不少领域都位居世界前列。许多人都羡慕中国的发展成就，但我对取得这些成就的原因更感兴趣。 经过在中国的学习，我的理解是，对外开放更像是一个外因，中国人的勤奋，才是中国奇迹的内在“密码”。 中华民族是一个勤奋的民族。', '2018-12-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDEiA39EHUoswMGS9qM99x0wQ2N_vikPJ83ni7UwRJxrnWMVQ0m1et8B8dQsZLw_rjfFlLDDMPGB5m0Bnm72WLZYhG7v-sTqdPJRwqOLWBk6LmrCP9ujlbshyv2jXy5A6fTn3-WpfwaeA==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3251, '报纸', '为人民书写 为人民放歌', '', '人民日报', '人民日报', '文化强国;《讲话》精神;文艺工作者;人民大众;文艺家;宝塔山;马克思主义;', '编者按：今年是毛泽东同志《在延安文艺座谈会上的讲话》发表70周年。70年前，黄土高原上“文艺为什么人”的提问，堪称石破天惊；而毛泽东的答案“我们的文艺都是为人民大众的”，更是振聋发聩。从此，“文艺为人民大众”就成为中国进步文艺的一面旗帜，指引和鼓舞着中国文艺', '2012-05-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIALIIbe3I48C7gHEmWMggab7UV3p5oG4bjkVf1x3eknKyZxvCf8GRjvLW7OL1KgjobKJSPkb9_0RkDWf36LSuVc5Xs6QA7AcO4Ckt_xQyFHpDJWsV_Arp8QohiXCw1XV0DKh2S_bCg6WA==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3256, '报纸', '未解之谜的历史启示', '汪金福; 肖春飞 ; 刘敏', '新华每日电讯', '新华每日电讯', '农村革命根据地;陕北根据地;梁星亮;国民党军队;中国共产党成立;红军长征;', '新华社北京6月26日电(记者汪金福　肖春飞　刘敏)从50多名到8000多万,从星星之火到燎原之势,从秘密组织到世界第一大政党——中国共产党90年创造了举世罕见的奇迹。 波澜壮阔的90年,许多重要的历史关头已被载入史册。然而,由于各种历史原因,慷慨激昂乐曲声中,也有一些', '2011-06-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDAq8xHpA7nYhdDos2N4QHoWO8Kwtp9X5SwgPuLQEylcpg2bq5qPV_wpm12A5aCZrXLmx6lfsXu3VA3VAg7IZadNkbWOPOj4GV8SOwCx66-ebZV9jvhyOumnd_OpdJrFYM-oMpA56rqfg==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3274, '报纸', '延安旅游形象大使选自旅游从业者', '金静', '中国旅游报', '中国旅游报', '旅游从业者;旅游形象;', '本报讯（金静）“宝塔山杯”延安首届旅游形象大使选拔赛决赛暨颁奖盛典近日举行。来自陕西延安10个县区、7大景区的旅游从业人员共180余人参与此次选拔。 经过自我风采展示、激情推介、知识问答、个人才艺展示等环节的激烈角逐，延安革命纪念馆选送的冯勇夺得冠军，', '2010-06-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDIsPK3DT1WsCBaWmcWg1_robe6ljhM6xzWuDxHK4_d3sk5kH3bDNoI9aKt2HQQkhgB2jfgkmFFavKTdi3tvFPWtkwLb_XlY34humRyxn5ThLid0rxdhKHotS0Az9oi5zIO6ArRsdl_Mg==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3282, '报纸', '将伟大的延安精神贯彻于司法实践', '谢圣华; 朱云峰', '人民法院报', '人民法院报', '马锡五审判方式;法官队伍;延安精神;司法实践;司法为民;群众路线;司法需求;党的思想路线;司法公正;实体公正;程序公正;', '革命圣地延安： 一次形式多样、内容丰富的革命传统洗礼 7月27日至30日，盛夏里的陕北高原，陕西全省三级法院的院长、省高院党组全体成员和中层负责人等共200余人齐聚革命圣地延安，开展了为期4天的“弘扬人民司法光荣传统，切实改进思想工作作风”研讨班活动', '2009-08-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC8B76EIrXB-7w0fYuIhn6NUIm15A0s3sPj_jMhjiAtXEzGKD_tMUhaycNwxw2-MvVdeOvFmJ8snOorXKg2uV0qS3hj_ToLHq-6og4CJqRdm3wUJvEIm4SUZJ73MIta8ELUGF7zT29qWQ==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3284, '报纸', '弘扬延安精神做好新时期法院工作', '谢圣华; 朱云峰', '人民法院报', '人民法院报', '延安精神;', '本报延安7月27日电 今天，陕西省高级人民法院在革命圣地延安举办的全省法院院长“弘扬人民司法光荣传统，切实改进思想工作作风”研讨班开班。开班仪式上，陕西省委常委、延安市委书记李希对这次研讨班和全省法院工作给予肯定，省政法委副书记郭明就加强法院队伍建设作讲话', '2009-07-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIABPGdtqQuTq4-17XsZLblAzKcfE1A78zwt13lNhVdTdXwBFTcP3Dc7OydQG4kBT68tR3ejx5QxfjJb2-yoLOqbN_R4qhU4zeeMiUuddr2qbriDuB0Aw8JwZKXwFTbP36nzb-Me57sl5A==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3293, '报纸', '延安的时间', '', '中华读书报', '中华读书报', '科学院;标准时间;陈学昭;《解放日报》;革命队伍;', '时间是人类文明的坐标，人们用不同的态度对待时间构成了这个世界不同的丰富多彩的文化。每一种文化都有它自己独特的时间指纹。认识一个民族、一个时代、一个社会，其实就是去认识它如何使用时间。延安革命队伍里的时间经历了一个从无序到统一的过程。 长征过来的革', '2007-10-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBT4YqHnGYGJop2qCc7hGWcSx9__XYD84zh4Zjg3bslqwRNlcqii2Gei1QcneJi6n5aPOXB31-0PvKoVWCv2g8qj2y7et1F3mWfTlg9lm6gjijMAnahWsc_cZFOIqx6ggQ98RBvAIW4NA==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3297, '报纸', '毛泽东论“一切反动派都是纸老虎”', '', '人民日报', '人民日报', '毛泽东;斯特朗;帝国主义;国民党;', '１９４６年６月，国民党进攻中原解放区，全面内战爆发。当时，国民党在军队数量、军事装备、后备资源及外来援助等方面，都明显超过中国共产党。国民党军队的总兵力约４３０万人，而且拥有装备较好的陆、海、空军；人民解放军的总兵力只有１２７万人，不仅没有海军和空军，而', '2007-09-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDvMAdvm-OD_lLvzBhqVyzzVt4gKwuzi7WHQB6y_9OcG_w-ofKxtVyEh0bQIqmc40Md1mzaN2fkcHyV6kR30Tr9-LsyaELFgDwFWXvYEbfJVs4JV1MlYHF4pIJyUeFyXXSPK_m6l2xgFQ==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3301, '报纸', '大繁荣 大团结 大发展', '', '光明日报', '光明日报', '中国文联;文艺工作者;文艺家;德艺双馨;', '第七次文代会以来的五年，是中国文联围绕中心、服务大局，团结广大文艺工作者,与时俱进、开拓创新，大力繁荣和发展社会主义文艺的五年。 五年来，党中央高度重视文化建设和文艺工作，做出一系列重要指示和战略部署。这一切都极大地教育和鼓舞着广大文艺工作者和文联', '2006-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA_0CgVUKnwRP0xYHm6v8YjHh3PtHN73KthLROyznxfb3btivS0Z_2c_-qIwm2vdQZd-T-x-cSqnjADvD7SB-TJpxVTYSlFDGKBC2Xkb0tNLT-5BbcMqRkudNNeDcGPnHphwPtCB-6FsQ==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3303, '报纸', '李福爱：30年剪纸圆一个梦', '熊建', '人民日报海外版', '人民日报海外版', '生活气息;', '●一边剪一边唱是她的特色 延安杨家岭，刘少奇故居旁。一孔满墙都挂着红色剪纸的窑洞里，一位身穿红毛衣的大姐信手拈来一片红纸。只见她那灵巧的双手左右转动，银剪上下翻飞。伴随着高亢的陕北民歌《赶牲灵》，红色的纸屑悠悠地飘落。不到５分钟，一组大尾巴公鸡剪', '2006-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBRRa--Ol98l5APlaNh5uxV_HCKou5PQ-pmLqId0-ap_5B0xSbxpP8t_VqVAkqzrqXKWq_lY-A-gdBHvbvnx2HOX32ldpf-ERRw07EDLkJoAtddkm0_5vVjUCbVtUX5DJu02jfsIz1E5Q==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3305, '报纸', '大生产运动', '', '人民日报', '人民日报', '大生产运动;中国共产党领导;陕甘宁边区;抗日根据地;', '大生产运动，是抗日战争时期中国共产党领导抗日根据地军民开展的以自给为目标的大规模生产自救运动。主要开展农业生产，兼办工业、手工业、运输业、畜牧业和商业。党政机关、部队、学校普遍参加生产运动，逐步达到粮食、经费自给、半自给或部分自给。同时，实行公私兼顾，军', '2006-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICAfHcPBSH4kBLOq2ZxyRaaQc1vEcUkE1Qnmf7HMC_lTIN95p7fR-Vy2CZdqw3kfre61Pj9VqFipSCDdLjp-EXnufEW74fhvX_CNiovtI-kX0uvbkCo56TKSwSp2_TTV8L0ZK0y8dNl3A==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3308, '报纸', '把意志凝聚到履行使命上', '胡禄林; 孙斌; 解学锋', '中国国防报', '中国国防报', '预备役官兵;历史使命;杨家岭;预备役部队;使命教育;', '陕西某预备役师在“忠实履行新世纪新阶段我军历史使命”主题教育中，着眼预备役部队的特点规律，注重用使命任务凝聚官兵，用优良传统激励官兵，增强了教育的主动性、针对性和实效性。4月15日，兰州军区总结推广了该师的经验做法。 共话新使命　预备役官兵同样责任重', '2006-04-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAqY3Fif5WyCyuSO-UGnLH0vzIY6LU78XthJqxJVmaa6-_8qHMYE6RpBM0lkaU50i9b4nL9Kp_xfZ9RhfhIBiwe6OFfu18O7WOfnlmrgmulYOCzjlvkVgbrAiGRmbzm6SVoYLoRtUDsXg==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3319, '报纸', '兰州军区某部赴延安受教育坚定理想信念', '宫曦岭; 宋歆', '解放军报', '解放军报', '延安精神;理想信念;受教育;', '本报讯 宫曦岭、记者宋歆报道：巍巍宝塔山，滚滚延河水。3月中旬，兰州军区某部一批党员干部来到延安，参观革命圣地，重温延安精神，进行保持共产党员先进性教育活动现地见学。  据带队领导介绍，这是该部近期深入开展先进性教育活动的一项重要内容，主要是通过踏访革', '2005-03-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICPWzSlvbqGjv664gaqH9Xzf7ovoyDJL4dhjc-d80Ctcn89PZQcgJ00GdaFLVZzjJ7tOqQo0tC98QldP8cxdshmXrAu0oY0aKZGpBN_zz-7MLL8yQi5uUFr1qOihlNxBiZsdJQtcOUhbg==&uniplatform=NZKPT&language=CHS', '杨家岭_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3325, '报纸', '代表听心声 党心连民心', '慎海雄; 刘刚; 陈芸', '新华社;', '新华每日电讯', '杨家岭村;南浔镇;厦坪镇;', '万众一心，众志成城。  亿万人民群众对党的十六大寄予 厚望。正准备来京出席新世纪党的第 一次全国代表大会的代表们对群众的 心声格外重视。他们采取各种方式，深 入到党员群众中听取意见', '2002-11-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDtntQcSKGb4CjsOwWx02z952I2TXk0ghy-a8SZWIauXKWZ6NAAdwBl4B7CIgo6ZPS2yiGvnQtnpUNed4430K3dnGSr7sC1EiWbF5NW-NiZKyqHhCmk8sHXgFwCRS8xoN7hDuTZL--7FA==&uniplatform=NZKPT&language=CHS', '杨家岭_screened,毛秉华_screened');
INSERT INTO `ds_article` VALUES (3331, '报纸', '文艺长河中永不熄灭的明灯', '华丰源', '光明日报', '光明日报', '座谈会;陕西省;毛泽东;《讲话》精神;杨家岭;毛主席;文艺工作者;', '60年前的5月23日，黄土高原上的杨家岭，座谈会在举行最后一次会议。晚上，三根木棍悬起一盏汽灯，会议厅前照得一片通明。毛主席对与会者作总结性讲话，口气是那么语重心长，观点是那么鲜明有力，这就是《在延安文艺座谈会上的讲话》。从此以后，《讲话》犹如一盏明灯，在', '2002-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA40t76BCLArBsAXQJ3ZA96eVw57OskvhaGS42YbP7v0-rDGKRINJ_Aq9JanNTrBiIH1xc13FifQcUiDeY8u2Kqo4IDGE_2c6INKXtCttTA7m1rNH9aEg5WpozNHLYIGr-IvhjSB1cHUg==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3332, '报纸', '影视剧作家：笔墨当随时代', '李春利', '光明日报', '光明日报', '剧作家;笔墨当随时代;', '“文艺必须坚持为人民服务、为社会主义服务的方向。”这是采风归来、收获颇丰的影视剧作家们发自内心的表白。 为纪念毛泽东同志《在延安文艺座谈会上的讲话》发表60周年，国家广电总局剧本策划中心会同中国电影文学学会、电影频道共同举办了大型采风活动。来自祖国', '2002-05-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAxOtc9NhIV91kkKY361vlSlrv7q6wT-4rAeFh-buu77rpO5uMueEEOeDh9EI7gA9ZfkpJzfAe7aVcFEZ9SEH1kRV5phvnSY-I5WCUcYjpBs68-UNoJwH8HRs5isNuX9PtDuJT0_2MyqQ==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3333, '报纸', '毛泽东同志《在延安文艺座谈会上的讲话》发表60年来军旅文艺硕果累累', '', '解放军报', '解放军报', '《在延安文艺座谈会上的讲话》;电影事业;延安文艺座谈会;毛主席;戏剧家;军旅文学;延安电影团;《西线轶事》;毛泽东;', '军旅文学———占据中国现代文学“半壁河山” ●本报记者　曹慧民 军旅文学的成长、发展过程，诠释了毛泽东同志《在延安文艺座谈会上的讲话》的光辉思想。它的繁荣和壮大，每一步都离不开火热的斗争生活，离不开先进文化的滋养。 在中国现代文学馆里，', '2002-05-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICy22e57ypzYvzjfBqKkSvT0hkIVJw9iRIOyRZDqxCW4hlG5kGn9waG5fOH9UWFyLjszZC1dlklZrrX9g2f_dxmBEhAgKXx3IF65LAFlgWNtcoY_tNO7nybzq_aUUPrIpbV9gkPkdEG3Q==&uniplatform=NZKPT&language=CHS', '杨家岭_screened,白求恩_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (3334, '报纸', '珍贵资料首次揭秘 曲折故事鲜为人知', '粟丹', '中国文化报', '中国文化报', '《毛泽东自传》;中译本;第一个;沈钧儒;', '国家图书馆为庆祝中国共产党建党80周 年举办的馆藏珍贵革命历史文献及图片展 览，引来了络绎不绝的观众。在许多珍贵文 献面前，人们驻足细看。特别是《共产党宣 言》的第一个中译本、《毛泽东自传》、《二万五', '2001-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB4fRuDDAdLST1NXiBYl_zo_glKADApHT3hNyYzJdRYWKBlHJz_Y4PH7TANvyatb-G5QCZiuEVqOHgVHFDx1otrOFmTJSe8Ew3OUb0ccq1lWPnRyjfzyC1AuHWT4hjcytkmhkCTSHW2iA==&uniplatform=NZKPT&language=CHS', '杨家岭_screened');
INSERT INTO `ds_article` VALUES (3340, '报纸', '培养造就堪当民族复兴重任的高素质干部队伍', '', '新华社;', '新华每日电讯', '干部教育培训;中国特色社会主义;高素质干部队伍;县级党校;习近平总书记;培养造就;政治训练;民族复兴;党性教育;', '“党的历史经验和现实发展都告诉我们，没有全党大学习，没有干部大培训，就没有事业大发展”； “要加强干部教育培训，使广大干部政治素养、理论水平、专业能力、实践本领跟上时代发展步伐”； “年轻干部培养，不能搞大水漫灌，更不能任其自然生长，要精耕细作，加强田间', '2023-10-19 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.006238', '中共七大1_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3341, '报纸', '始终做到统一思想统一意志统一行动', '胡思远; 王奇', '中国纪检监察报', '中国纪检监察报', '统一意志;习近平总书记;全面从严治党;', '党的二十大上，习近平总书记着眼深入推进新时代党的建设新的伟大工程，指出“我们党作为世界上最大的马克思主义执政党，要始终赢得人民拥护、巩固长期执政地位，必须时刻保持解决大党独有难题的清醒和坚定。”今年1月，在二十届中央纪委二次全会上，习近平总书记从新时代新征', '2023-10-09 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.003119', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3344, '报纸', '用文艺精品书写生生不息的人民史诗', '郭凯倩', '中国文化报', '中国文化报', '广西壮族自治区;文艺创作;山东省;邓颖超;文化自信;', '本报集体采写 1942年5月，毛泽东同志发表《在延安文艺座谈会上的讲话》，提出“文艺要为人民大众服务”，为中国文艺的发展指明了方向。党的十八大以来，以习近平同志为核心的党中央高度重视文艺工作。在党的二十大报告中，习近平总书记指出：“坚持以人民为中心的创作导向，', '2023-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDfYD9RhCddGxKlItzpO4aK2q1OkBI3us9rILN7fgNFKxa238286SOb-WNsriPhZmrmvB6z8KAgYKPXY09PrD9hXONASy-tQ40J1tt0jj3vRhkxczmw943SyYPpCE9lD93q-OyzeFBtcg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3345, '报纸', '延安时期党如何在高等干部学校铸牢中华民族共同体意识', '徐鹏; 王梦雨', '西北政法大学马克思主义学院;', '人民法院报', '中华民族;陕北公学;干部学校;', '铸牢中华民族共同体意识是国家安全之基、民族团结之本、中国精神力量之魂。延安时期，在内忧外患的严峻形势下，中国共产党审时度势，以高度的政治责任感和历史使命感，在高等干部学校开展了铸牢中华民族共同体意识的实践探索，如中共中央党校民族班，陕北公学蒙古青年队、民', '2023-03-31 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2023.000999', '中共七大1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3348, '报纸', '团结', '林晖; 王琦; 范思翔; 董博婷', '人民日报', '人民日报', '中华民族;习近平总书记;中国共产党人;', '“团结就是力量，团结才能胜利”“确保党的团结统一”“为全面建设社会主义现代化国家、全面推进中华民族伟大复兴而团结奋斗”……纵览党的二十大报告，“团结”一词贯穿全篇，先后出现20余次。 正如一首经典歌曲所唱，“团结就是力量，这力量是铁，这力量是钢，比铁还硬，', '2022-12-29 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.014008', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3350, '报纸', '无我', '朱基钗; 施雨岑; 任沁沁; 张研', '新华每日电讯', '新华每日电讯', '习近平总书记;共产党人;', '“必须坚持人民至上”“坚持以人民为中心的发展思想”“江山就是人民，人民就是江山”……在党的二十大报告中，“人民”一词出现170多次。 为中国人民谋幸福，为中华民族谋复兴。中国共产党没有自己特殊的利益，在任何时候都把群众利益放在第一位，这是“我将无我”的崇高境', '2022-12-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.008681', '中共七大1_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3351, '报纸', '赓续“红色”血脉 文旅融合促发展', '田新元', '中国经济导报', '中国经济导报', '红色旅游目的地;中国共产党;专题展;红色文化资源;旅游发展模式;传承弘扬;红色资源;革命老区;临沂市;促发展;“红色”;', '近日，由上海市中共一大纪念馆推出的全国首个以“伟大建党精神”为主题的大型特展——中国共产党伟大建党精神专题展正式走进福建省三明市。展览深入挖掘三明地区红色文化资源和感人故事，对苏区精神、长征精神等进行内容再创作，针对性地融入苏区标语、红军长征出发地等三明', '2022-12-20 08:00:00', 'https://link.cnki.net/doi/10.28095/n.cnki.ncjjd.2022.001930', '中共七大1_screened,遵义会议_screened,红四军_screened');
INSERT INTO `ds_article` VALUES (3354, '报纸', '弘扬延安精神，推进文旅业高质量发展', '秦毅', '中国文化报', '中国文化报', '延安精神;杨家岭革命旧址;习近平总书记;革命纪念地;讲解员;', '延安是中国革命的圣地，党中央在延安13年，培育形成了光照千秋的延安精神，留下了众多革命旧址。党的二十大闭幕不到一周，中共中央总书记、国家主席、中央军委主席习近平带领中共中央政治局常委李强、赵乐际、王沪宁、蔡奇、丁薛祥、李希，专程从北京前往陕西延安，瞻仰延安', '2022-10-31 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.003802', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3356, '报纸', '在新的赶考之路上向历史和人民交出新的优异答卷', '', '新华社;', '新华每日电讯', '习近平总书记;中央政治局常委;革命纪念地;', '10月27日，党的二十大闭幕不到一周，习近平总书记带领中共中央政治局常委专程前往陕西延安，瞻仰延安革命纪念地，重温革命战争时期党中央在延安的峥嵘岁月，缅怀老一辈革命家的丰功伟绩，宣示新一届中央领导集体的坚定信念。 习近平总书记强调：“要弘扬伟大建党精神，弘扬', '2022-10-29 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.007681', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3358, '报纸', '弘扬延安精神 走好新的赶考之路', '', '解放军报', '解放军报', '延安;中国;陕西;中华人民共和国;', '延安，中国革命的圣地、新中国的摇篮。 党的二十大闭幕不到一周，习主席带领中共中央政治局常委专程从北京前往陕西延安，瞻仰延安革命纪念地，重温革命战争时期党中央在延安的峥嵘岁月，缅怀老一辈革命家的丰功伟绩，宣示新一届中央领导集体赓续红色血脉、传承奋斗精神，在', '2022-10-28 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.005641', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3359, '报纸', '铸魂', '', '解放军报', '解放军报', '八一勋章;习近平;李延年;政治建军;南京路上好八连;全军政治工作会议;思想政治教育体系;国家荣誉称号;古田会议;政治指导员;红色基因;一以贯之;理论宣讲;', '【解说】 2021年7月1日，庆祝中国共产党成立100周年大会。党的盛典，人民的节日。 天安门广场上空，一面中国共产党党旗，由直升机护旗梯队护卫，迎风向前。紧随鲜红的党旗，人民军队新型战机振翅翱翔，向党致敬！向祖国致敬！向人民致敬！ 人民军队党缔造，人民军队忠于党', '2022-09-28 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.005285', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3360, '报纸', '无声功勋', '李惊亚; 刘智强', '新华每日电讯', '新华每日电讯', '钱壮飞;李克农;周恩来;徐恩曾;顾顺章;党史部门;国民党;贵州省毕节市金沙县;', '“七一”前夕，位于贵州省毕节市金沙县后山镇的一座烈士陵园，迎来一批批参观者，人们从四面八方赶来…… 他们共同缅怀的，是一位优秀的中国共产党人。 90多年前，白色恐怖最严重的岁月，他勇敢地深入“龙潭虎穴”，成为潜伏在国民党最高情报机关里斗智斗勇的“红色特工”', '2022-07-01 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.004949', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3361, '报纸', '十分宝贵的红色记忆', '郝思斯', '中国纪检监察报', '中国纪检监察报', '红色记忆;中国人民大学图书馆;陕北公学;《共产党宣言》;成仿吾;华北联合大学;马克思主义;胡福明;', '4月25日，习近平总书记来到中国人民大学考察调研。在藏书410余万册的图书馆，习近平总书记指出，人民大学馆藏红色文献，鉴证了我们党创办正规高等教育的艰辛历程，是十分宝贵的红色记忆。 从战火中的大学，到解放区最高学府，再到中国共产党创办的第一所新型正规大学，中国', '2022-04-29 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.001739', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3362, '报纸', '开辟自我革命新境界', '韩亚栋; 薛鹏', '中国纪检监察报', '中国纪检监察报', '全面从严治党;习近平总书记;党的政治建设;自我净化;政治规矩;党中央;自我革新;历史周期率;惩治腐败;', '勇于自我革命是我们党最鲜明的品格。3月5日，习近平总书记参加十三届全国人大五次会议内蒙古代表团审议时强调，只要大力弘扬伟大建党精神，不忘初心使命，勇于自我革命，不断清除一切损害党的先进性和纯洁性的有害因素，不断清除一切侵蚀党的健康肌体的病原体，我们就一定能', '2022-03-31 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.001284', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3363, '报纸', '这十年，总书记的新春足迹', '', '人民日报', '人民日报', '习近平总书记;中华民族;', '“大国之大，也有大国之重。千头万绪的事，说到底是千家万户的事。” “每到群众家中，常会问一问，还有什么困难，父老乡亲的话我都记在心里。” ………… 新年前夕，习近平主席发表二〇二二年新年贺词，心系民生冷暖、情牵万家灯火。真挚平实的话语，具有直抵人心', '2022-01-27 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.001024', '中共七大1_screened,杨家岭_screened,龚全珍_screened,毛秉华_screened,神山村_screened');
INSERT INTO `ds_article` VALUES (3366, '报纸', '把党史学习教育融入思政课堂', '刘力波; 张哲浩; 李洁', '陕西师范大学马克思主义学院;', '光明日报', '思政课;红色资源;党史学习;', '从嘉岭山上的巍巍宝塔，到照金古镇屹立的英雄纪念碑，陕西汇聚了极具革命性和先进性的丰富精神地标。建校77年来，陕西师范大学数十万毕业生用理想、信念和情怀，扛起了西部基础教育的大旗，在西部大地上书写着扎根西部、甘于奉献、追求卓越、教育报国的“西部红烛精神”，迸', '2021-12-20 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.006390', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3369, '报纸', '延安时期马克思主义中国化传播研究', '范尊娟; 李媛', '首都师范大学;线装书局;', '中国新闻出版广电报', '《矛盾论》;《实践论》;马克思恩格斯;马克思主义中国化;延安时期;马克思主义哲学大众化;马列著作;《暴力在历史中的作用》;传播研究;', '核心阅读 延安时期，仅翻译马列著作就达32种。其中，主要有两大丛书、两大选集。两大丛书，一是“马克思恩格斯丛书”，主要有《社会主义从空想到科学的发展》《共产党宣言》《法兰西内战》《政治经济学论丛》《马恩通信选集》《德国的革命和反革命》《〈资本论〉提纲》《', '2021-12-14 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004892', '中共七大1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3370, '报纸', '始终坚持“三个在一起”', '李澍', '解放军报', '解放军报', '为人民服务;', '习主席在陕西省榆林市考察时强调，始终同人民站在一起、想在一起、干在一起。回望历史，观照现实，这“三个在一起”是当年“延安作风”打败“西安作风”的制胜密码，更是我们党团结和带领人民从胜利走向胜利的力量源泉。作为党员干部，我们要继承发扬革命传统和优良作风，始', '2021-12-13 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007676', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3374, '报纸', '深刻理解跳出历史周期率的“第二个答案”', '何忠国', '学习时报', '学习时报', '历史周期率;纯洁性;马克思主义政党;', '1945年7月，党的七大刚刚闭幕，国民参政员黄炎培等人应邀到延安考察访问，留下了党史上著名的“窑洞对”。党的十九届六中全会上，习近平总书记又专门提到了“窑洞对”：我们党历史这么长、规模这么大、执政这么久，如何跳出治乱兴衰的历史周期率？毛泽东同志在延安窑洞里给出', '2021-11-26 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002237', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3375, '报纸', '关于《中共中央关于党的百年奋斗重大成就和历史经验的决议》的说明', '习近平', '人民日报', '人民日报', '《中共中央关于党的百年奋斗重大成就和历史经验的决议》;中共中央;中国共产党成立;党中央;邓小平同志;奋斗目标;', '受中央政治局委托，我就《中共中央关于党的百年奋斗重大成就和历史经验的决议》起草的有关情况向全会作说明。 一、关于党的十九届六中全会议题的考虑 我们党历来高度注重总结历史经验。早在延安时期，毛泽东同志就指出：“如果不把党的历史搞清楚，不把党在历史上所走', '2021-11-17 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.012023', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3376, '报纸', '在重大历史关头统一全党思想', '管筱璞; 柴雅欣', '中国纪检监察报', '中国纪检监察报', '历史决议;错误思想;历史虚无主义;历史关头;毛泽东思想;邓小平同志;党的历史;', '十九届六中全会审议通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》，这是党的历史上第三个历史决议。 我们党是一个高度重视总结历史经验、也善于总结历史经验的马克思主义执政党。每到重要历史时刻和重大历史关头，我们党都要回顾历史、总结经验，从历史中汲', '2021-11-16 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.005316', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3377, '报纸', '延安：高扬为民司法时代风帆', '张娅; 惠兴文', '人民法院报', '人民法院报', '延安精神;司法为民;陕甘宁边区高等法院;马锡五审判方式;', '“老一辈革命家和老一代共产党人在延安时期留下的优良传统和作风，培育形成的以坚定正确的政治方向、解放思想实事求是的思想路线、全心全意为人民服务的根本宗旨、自力更生艰苦奋斗的创业精神为主要内容的延安精神，是我们党的宝贵精神财富。今天，全面从严治党要继续从延安', '2021-11-14 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.005049', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3381, '报纸', '一次重要的策略转变', '王新尚', '北京市政协;', '人民政协报', '联合政府;国民党;周恩来;国共两党;策略转变;', '民盟对联合政府的两次响应 中国共产党关于联合政府的主张1944年9月提出后，得到社会各界进步人士的支持和赞誉。 中国民主民盟的响应更为有力，两次以民盟名义发表政治主张予以支持。一次是1944年10月10日，以当时双十节为契机，发表民盟“对抗战最后阶段的政治主张”，', '2021-11-03 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.008469', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3384, '报纸', '延安整风开启党的出版事业新局面', '侯俊智', '人民出版社;', '中国新闻出版广电报', '延安整风;秘密文件;整风运动;《反对党八股》;出版事业;六大以来;毛泽东;党的历史;', '1942年2月，毛泽东先后作《整顿党的作风》和《反对党八股》的讲演。整风运动在全党普遍展开。延安整风运动是中共中央发起的一次马克思主义思想教育运动，这场运动对于党的出版工作亦是一次深刻的思想变革。 1942年2月8日，毛泽东的著名演讲《反对党八股》，就是在中宣部和', '2021-10-14 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004083', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3385, '报纸', '我们怎样才能继续成功', '宣言', '人民日报', '人民日报', '中国共产党人;习近平总书记;社会主义;邓小平同志;中国共产党成立;人类命运共同体;党中央;群众组织;奋斗历程;一带一路;毛泽东;中华民族;', '2021年6月28日晚，国家体育场，庆祝中国共产党成立100周年文艺演出盛大举行。来自四川凉山的8名彝族孩子领唱的《唱支山歌给党听》格外引人注目。天籁般的声音，朴实真诚，纯净空灵，唱出了对伟大的党发自内心的真挚情感，唱出了在党的领导下创造幸福生活的坚定信心，唱出了对', '2021-09-28 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.010333', '中共七大1_screened,论持久战_screened,遵义会议_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (3386, '报纸', '学习百年党史 汲取奋进力量', '马建堂', '国务院发展研究中心;', '中国经济时报', '政治方向;习近平总书记;中国共产党;领导权;新民主主义革命时期;党的七大;', '编者按 在中国共产党成立100周年这个重要历史节点，全国正开展党史学习教育，国务院发展研究中心上下积极学党史、讲党史、懂党史、用党史。为了展示国研中心作为国家高端智库的初心使命、国研中心智库人认真履行“为党咨政、为国建言、为民服务”的责任担当，中国经济时报开', '2021-08-26 08:00:00', 'https://link.cnki.net/doi/10.28427/n.cnki.njjsb.2021.001902', '中共七大1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (3387, '报纸', '正风肃纪 公安铁军铿锵前进', '丁可宁', '人民公安报', '人民公安报', '教育整顿;从严治警;公安队伍;政治建警;', '对于一个政党而言，始终走在时代前列的能力，来自一刻不放松的自我革命。 马克思曾指出，共产党要“在全世界面前树立起可供人们用来衡量党的运动水平的里程碑”。 一份历史自觉，一种慨然担当，一种更高要求。中国共产党靠什么继续成功、赢得未来？ “我们要牢记打', '2021-08-17 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.004601', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3394, '报纸', '没有共产党就没有新中国', '司晋丽', '人民政协报', '人民政协报', '没有共产党就没有新中国;陕甘宁边区;中国共产党;宝塔山;', '6月29日，“七一勋章”授勋仪式在北京举行。获奖者深情共唱《没有共产党就没有新中国》的场景，令无数观众热泪滚烫。 “没有共产党就没有新中国……”中国人对于这首歌曲有着特别的情结，大家都没有刻意去学，却都能朗朗上口。很多孩子从小就跟着大人一起哼唱，早早就将歌', '2021-07-22 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005913', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3397, '报纸', '用纸和笔传扬好革命故事', '张春雷', '光明日报', '光明日报', '革命故事;', '今年上半年，我参与了“奋斗百年路 启航新征程”特刊的编辑工作。历时半年之久的特刊，从多维度、广视角生动展现了我们党在一百年间如何矢志践行初心使命、如何筚路蓝缕奠基立业、如何创造辉煌开辟未来。参与特刊编辑工作本身就是接受深刻的党史教育，稿件中记述的很多动人故', '2021-07-05 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003399', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3398, '报纸', '旗帜领航 再启新程', '钟超; 方莉; 龚亮', '光明日报', '光明日报', '中国特色社会主义;习近平总书记;中国共产党成立;庄严宣告;马克思主义中国化;庆祝大会;中华民族;人类命运共同体;', '百年恰是风华正茂。7月1日，庆祝中国共产党成立100周年大会在天安门广场盛大举行。置身广场，举目四望，7万余名与会者手中的党旗、100面插在广场东西两侧的红旗迎风飞扬。 风展红旗如画。旗帜，是一种意象。对一个政党而言，思想理论就是旗帜、是方向，任何时候都是根本性', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003380', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3400, '报纸', '用科学理论凝心铸魂', '付瑜', '中国组织人事报', '中国组织人事报', '党员干部;理论武装;马克思主义;中国共产党;学习贯彻;“三个代表”重要思想;思想建党;干部教育培训;在职学习;干部理论教育;科学理论;', '前言 注重思想建党、理论强党，是我们党的鲜明特色和光荣传统，是区别于世界上其他政党的显著优势。中国共产党一经成立，就把马克思主义作为自己的指导思想，并不断推进马克思主义的中国化、时代化、大众化，形成了毛泽东思想、邓小平理论、“三个代表”重要思想、科学发', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.002229', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3402, '报纸', '人才强 事业兴', '张璇', '中国组织人事报', '中国组织人事报', '职称制度;事业单位人事制度改革;', '前言 千秋基业，人才为本。 中国共产党高度重视人才工作，加强专业技术人才队伍建设，持续深化事业单位人事制度改革，建设了一支规模宏大、结构合理、素质优良、具有较强竞争力的专业技术人才队伍，形成了一套完整系统的人才工作理论体系和制度体系，架起了中国特色事', '2021-06-30 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.002198', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3404, '报纸', '在百年党史中熠熠生辉的延安精神', '王晨', '人民日报', '人民日报', '延安精神;共产党人;习近平总书记;中国共产党;马克思主义中国化;', '我们即将迎来中国共产党建党一百周年，这是令全体共产党员和全中国人民无比自豪的日子，也是抚今思昔、温故知新、开展百年党史学习教育的好时机。习近平总书记在党史学习教育动员大会上指出，“我们党的一百年，是矢志践行初心使命的一百年，是筚路蓝缕奠基立业的一百年，是', '2021-05-31 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.005661', '中共七大1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (3405, '报纸', '17万平方米的“柳暗花明” 人民大会堂这样建成', '张艺', '中青报;中青网;', '中国青年报', '人民大会堂;李国胜;建筑设计院;赵冬日;总建筑师;', '天安门广场上，矗立着中国第一号政治性建筑工程“人民大会堂”。它为“献礼国庆十周年”而生，这座17万平方米的建筑工程，仅仅用了10个月完成。 1945年，在延安杨家岭没有电灯的简陋会场里，中国共产党举行了七大，那次会议上，毛泽东就提出，要建一个容纳万人的大礼堂。', '2021-03-15 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.000933', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3406, '报纸', '中共七大：把党的指导思想写在旗帜上', '张哲浩; 王建宏; 张航智', '光明日报', '光明日报', '中共七大;党的指导思想;党的七大;杨家岭;', '冬日暖阳中，记者走进延安杨家岭朴素庄严的中央大礼堂。简陋的条桌和木椅，依旧鲜艳的党旗……一如往昔的陈设，令人仿佛回到了1945年4月23日的那个春日，回到了七百多人济济一堂、商讨国家前途命运的会场——彼时此地，连开50天的中共七大，为中国选择了另外一种命运——光明', '2021-02-08 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.000700', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3407, '报纸', '感悟党的七大精神，汲取奋进力量', '薛琳; 龚仕建', '中国延安干部学院;', '人民日报', '党的七大;', '每次来到杨家岭革命旧址，我总能看到来自全国各地的学员和游客，或是进行党性教育，或是参加红色旅游，总能听到不同口音的人们讲述先辈的革命精神和自己的人生故事。 在世界反法西斯战争和中国抗战迎来黎明曙光的时刻，中国人民面临着两种前途和命运的抉择，中国共产党在1', '2021-02-04 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.001309', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3408, '报纸', '山东八路军战略“大搬家”', '孙庆玲', '中青报;中青网;', '中国青年报', '八路军;国民党军;《中苏友好同盟条约》;', '在国人的目光聚焦在国共两党1945年秋在西南方的重庆谈判时，少有人注意到，一艘艘船正接连从山东蓬莱一带的栾家口港和黄县（今龙口市）龙口港驶出——即便多少年后，也少有人浓墨重彩地记录解放战争中这至关重要的一环，当被问及此段历史，身边几位年轻人更是一脸“问号”，', '2021-01-29 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.000360', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3409, '报纸', '自我革命，得到中国人民的衷心拥护', '', '人民日报', '人民日报', '中国共产党;衷心拥护;反腐败;', '中国共产党之所以伟大、之所以成功、之所以充满奋进力量，其中一个重要原因在于，拒绝自满、永不停滞，保持了勇于自我革命的精神 中国人民的利益和期待，正是中国共产党推进自我革命、坚决向腐败宣战的根本动力 最近，美国一家知名公关公司发布信任度调查显示，中国民', '2020-08-20 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2020.008118', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3412, '报纸', '为人民服务：从提出到写入党章', '刘思妗', '中国纪检监察报', '中国纪检监察报', '毛泽东;全心全意为人民服务;共产党人;', '12月26日，是毛泽东同志诞辰126周年。习近平总书记指出：“一切向前走，都不能忘记走过的路；走得再远、走到再光辉的未来，也不能忘记走过的过去。”今天，我们重新梳理毛泽东同志的“为人民服务”，从一个概念的提出到形成著名篇章，再到写入党章的历史过程，既感受了他的为', '2019-12-26 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2019.000634', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3413, '报纸', '对照党章找差距 提升政治新境界', '', '光明日报', '光明日报', '党章党规;', '在陕西延安中共七大会址的会场两侧，挂有六个插着党旗的旗座，每个旗座上都书写着“坚持真理，修正错误”八个大字。 也就在这次大会上，毛泽东代表中央委员会做《论联合政府》的报告，回顾了党领导中国民主革命期间发生的两次历史性转变，并从党的宗旨的高度强调了中国共', '2019-07-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICwCGtYTRXkIPX1RHLNtVRqNUnLrjodF9ji71EhdvfsdzkhL_CIWhqcFDdTDBSz4onXoNqAWkOQoPmv8oi7SaUVuCOrmcK2Y40Awgl-wt5h5UGHhnNRlHFE8ipoVrhcKG4xM6HJraQWTg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3414, '报纸', '党的自我革命任重而道远', '', '人民日报', '人民日报', '牢记使命;修正错误;习近平总书记;', '“做到不忘初心、牢记使命，并不是一件容易的事情，必须有强烈的自我革命精神。”在中共中央政治局第十五次集体学习时，习近平总书记警示全党，党的自我革命任重而道远，决不能有停一停、歇一歇的想法。今年是新中国成立70周年，我们党在全国执政也70年了。当此之时，以“不', '2019-07-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBMpNw1MXLHq8ru2j0BM2AN6B7JfnVOttcq3dGA8i55pYEQT_W__5Htgbjzv8GjEjWSyZDBbG1Wlb9j9QgmS3vMVK2fRQMi8sk_ESzEIRtNFJ5HXbp196WtxHPrut6gLvSX0UjARHhdhA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3417, '报纸', '“要把办报看成大事”', '李自强', '中国纪检监察报', '中国纪检监察报', '《晋绥日报》;', '“我们的政策，不光要使领导者知道，干部知道，还要使广大的群众知道。有关政策的问题，一般地都应当在党的报纸上或者刊物上进行宣传。” “通过报纸加强党和群众的联系，这是党的工作中一项不可小看的、有重大原则意义的问题。” 这些话语，出自1948年4月2日毛泽东', '2018-09-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID7yZDH4i1hgKizbKGCo3ZYnldf4CIw6PQOQaBhZdBFy1HTlEw_28uMXiiy48LHLr-dKleDJUzPmBfriE5g7WKO7Efg65NFKEPCszxq0QFpVPzW8LUkxgQl5DlE7EgMRZ8PsjJtJWhyMg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3418, '报纸', '不忘为民初心牢记历史使命 坚决打赢打好脱贫攻坚硬仗', '徐新荣', '中共陕西省委;延安市委;', '光明日报', '扶贫开发战略;习近平总书记;精准脱贫;历史使命;精准扶贫;攻坚战;', '摆脱贫困是国际社会面临的重大难题之一，是人类社会千百年来共同的美好愿望，也是中国共产党人矢志不移的奋斗目标和历史使命。97年前，一个大党诞生于一条小船，从此伟大的“红船精神”穿越历史、辉映未来。进入新时代，我们坚持以习近平新时代中国特色社会主义思想为指引，', '2018-05-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICNpA78-OHO1tirIsTSj6jjQQa72SHUG0sNqR_e3u0rghQiurCL-XaqTfi0-3RUYdxlOXM_4VsYFt_9yDfi9Ea1NaYVQW4vbOBBGgpss4aT3q9lTizHnI_ehL9zhkqVh9RhJxhQDXrQbQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3419, '报纸', '往深里走 往实里走 往心里走', '', '解放军报', '解放军报', '习近平强军思想;党的十九大精神;', '瞻仰党的七大会址，参观延安新闻纪念馆，深入走访驻地部队……在革命圣地延安，军队新闻工作者倾情投入“新时代新气象新作为”主题采访活动，触摸红土地的厚重历史，见证新时代的新风新貌，书写新征程的开拓奋进。 “新时代新气象新作为”主题采访活动开展以来，军队新闻', '2018-01-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA9ku2L1ITqJQaEMCylSMz56h12G_pCz_87wyBYtxF-WV4gTB9EDRnu9NeI_x3WXg6CPAwJC6sCBx9O1yBcxFPzPQp43iyjVQ9Uj8mmL1ElMCUg9sQALN5ZOy2aO1gRq1P_oGS4Tl5EWw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3420, '报纸', '深刻把握习近平新时代中国特色社会主义思想活的灵魂', '徐新荣', '中央党校省部级干部进修班;陕西省委;延安市委;', '学习时报', '习近平新时代中国特色社会主义思想;马克思主义;习近平总书记;党的十八大以来;活的灵魂;', '延安是中国革命圣地，是中国共产党人的精神家园。“延安的窑洞里有马克思主义”，人民领袖毛泽东从这里走向全中国。“梁家河是个有大学问的地方”，是中国梦的发祥地，习近平总书记在梁家河插队七年，是传承和弘扬延安精神的楷模。在实现中华民族伟大复兴中国梦的历史进程中', '2018-01-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBx8jTvaS8gzXQqdAAO3Sem_cfslVh4jkydZ3LVln2E7dxPZVOuzPCM29bgqzTKHE8_Oplu8_VR3yDjg8q4Owng6FrC6FQroJ8flyFWybIZHyepxltY3KKibxnQiIiAz7Yx85LdHThMow==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3429, '报纸', '解读红四军“寻路之旅”中的4个关键词', '曲爱国', '军事科学院军事历史和百科研究部;', '解放军报', '红四军;井冈山;国民党军;', '众所周知，人民军队的发展并非一条平坦大道，而是极其曲折和无比艰辛的，经历过苦难，遭受过挫折，甚至陷入过绝境。1929年元旦刚过，风雪交加之中，红四军主力走下井冈山，踏上了在党史、军史上都颇为重要的“寻路之旅”—— 关键词1： 绝处逢生 大革命的失败', '2014-10-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIABWXau5TJf8cPUn6CBeZCT3dl6uVi3uuviFqFzuQEsPzBX77y2B0mvTMbp-UuZcd0FqkePucH6KEnzxqqHaOle_VgxcHuPELrW0EDoUS4L9L1Jt1Gm8fROD6P2CFQrUUkrmPb0lfOz_w==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,红四军_screened,瑞金_screened,秋收起义_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (3432, '报纸', '鉴于往事 资于治道', '吴元操', '陕西省咸阳市委组织部;', '中国纪检监察报', '“四风”;修正错误;', '党的群众路线教育实践活动主要任务是解决“四风”问题，这是我们党针对自身存在问题，采取的一次“刮骨疗毒”的具体行动。如何破除“四风”，加强党的建设，延安时期的政治智慧是有力的思想武器和精神法宝。鉴于往事，有资于治道。 破除“四风”，必须把握“创业难', '2013-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICMoy7EtFgBga5MF_oNn9MhMyLqFJsrekAwwoLp2l6Nj5rw--LFUsTAAvtuQigjqUD1bSmAY543iNrP00XEsqEq7nZsI6P6DO9ROJcO3JKPebH1_kg0St2FdYjRfcFo2WbFqlJ7SKKOAw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3434, '报纸', '群众路线形成与发展的历史考究', '李曜升', '中国教育报刊社;', '中国教育报', '群众路线;优良传统;刘少奇;形成和发展;毛泽东思想;党的群众路线教育实践活动;到群众中去;形成与发展;', '群众路线是党的生命线和根本工作路线，是我们党的重要法宝。党的群众路线是怎样产生、形成和发展的？在党的群众路线教育实践活动中，对群众路线的来龙去脉进行探究，是非常有益的。——编者 当前，全党正在开展以为民务实清廉为主要内容的党的群众路线教育实践活动，这', '2013-07-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICndJh0rJBf57P5u8-3wT2e7cVUgYZWjZm_AiNkNdo4xq6N_udXBRgHTfJ9sEncmb2p_ikQKzCGWnFbwIksf3HB61rh7MLtIjWsupzrgWazUgvr_T79wgVDyBE45Lnz0c5EV5HuPRz0ow==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3436, '报纸', '培育廉荣贪耻的社会风尚', '姜洁', '人民日报', '人民日报', '廉政文化建设;中央纪委;监察部;廉政法规;反腐倡廉理论;红色廉政文化;社会风尚;', '“红色”为媒，“廉政”为题，一场场智慧和经验的交流，迸射出激情的火花。今年9月7日，“红色廉政文化·南湖讲坛”在浙江嘉兴举行，来自井冈山、瑞金、遵义、延安、西柏坡等革命圣地的纪委领导、学者交流了弘扬红色廉政文化的经验，六家革命圣地还共同发出了“红色廉政文化', '2012-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICrKSgrGhuIjUS0cpTebPQ-ozZqVRPtbW0ZsH7m00jBw9G6n5FOLXnrMoD5Iaj-dnzwwSMtLISy2puluNGs7x7tkxqgqel8q900gb11DIXJrWvf7fWrl2n1bDuf4Bvk3UEi99lDbaCNWg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3437, '报纸', '在新的历史条件下继承和弘扬《讲话》精神 奋力开拓中国特色社会主义文化发展道路', '李长春', '人民日报', '人民日报', '中国特色社会主义文化发展道路;继承和弘扬;《讲话》;《讲话》精神;新的历史条件;', '今天我们在这里隆重集会，纪念毛泽东同志《在延安文艺座谈会上的讲话》发表70周年。中央对这次座谈会高度重视，胡锦涛总书记专门作出重要指示，深刻阐明《讲话》的历史地位和重要作用，高度赞扬70年来一代又一代文艺工作者作出的重要贡献，对新形势下进一步继承和弘扬《讲话', '2012-05-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBQaStwH8NMrq_9Hkl80GHGAcHo45KwKb_rCDLCPVscx7GdNVg3DMixomPZCdpWKHU8bgWVtz-l3uqXjXWLWC9k4YITmWskcYsBsvi2k43p1FcnmO4fn_733eTfY93_u7YteQr2x8i3uQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3440, '报纸', '关于建设社会主义核心价值体系', '', '光明日报', '光明日报', '社会主义核心价值体系;宣传思想工作;人民出版社;江泽民;胡锦涛;有中国特色的社会主义;', '发扬艰苦奋斗、不屈不挠、再接再厉的革命精神。 毛泽东：《在纪念孙中山逝世十三周年及追悼抗敌阵亡将士大会上的讲话》（1938年3月12日），《毛泽东文集》第2卷，人民出版社1993年版，第112页 以民族精神教育新后代。 毛泽东：《论新阶段》（1938', '2012-02-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICc2N5oWU6HMvRwrJAXFWK0hLKbK8gkZK7GcdX6njUN82jVlcDzYsYKJE9g5ywtty7UH4mMNiWlIrz0LEqBoI_iSu4eWtfRdzW093XIWOlopwEqeydOkg8ZDGlRwnL8bNBjnOe2zbVb3A==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3442, '报纸', '论文化建设', '', '中共中央宣传部 ;中共中央文献研究室;', '人民日报', '马克思主义者;马克思列宁主义;意识形态领域;人民出版社;社会主义现代化建设;思想战线;宣传思想工作;毛泽东思想;江泽民;思想文化阵地;', '二、关于文化建设的指导思想 当作国民文化的方针来说，居于指导地位的是共产主义的思想，并且我们应当努力在工人阶级中宣传社会主义和共产主义，并适当地有步骤地用社会主义教育农民及其他群众。 毛泽东：《新民主主义论》（1940年1月），《毛泽东选集》第', '2012-02-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICNFV-JyJQ1sIXrrbeBqFiH-AjF18HrQtKoBn7yBy8d28PnHB2CVM_6zT6eynu7uzvEIFw20Nwgw7nZHJWwopH3c_GoAwWKKPxF-rbB-2rZd0Z1J0KbS81GqjfpNFCeOeWCifkc-fiHnA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,中共七大1_screened,中共七大1_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3443, '报纸', '中国立场 世界眼光 人类胸怀 全面推进现代综合新型国际传媒建设', '', '光明日报', '光明日报', '中国国际广播电台;国际传媒;国际传播体系;对外广播;', '红色电波传遍世界 1941年12月3日，延安新华广播电台开办日语节目，标志着中国人民对外广播事业暨中国国际广播电台诞生了。从此，中国共产党和中国人民的声音，通过这一红色电波，传遍中国，传遍世界。 70年来，中国人民对外广播事业暨中国国际广播电台，在', '2011-12-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICuEMs_j5xLezbURupXLYdbboFbkYFVtyuimmtxDXm0ObzqBT4_g9rK1wFIuy6qQpuKVUU7pl2G0kASDKINHZLW0U5hpmjWjvCRxKCqiMAIKMdBWn-GVyuKrForhLqIkgCc87proLMcpg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3445, '报纸', '“为人民服务”考略', '韩振峰', '北京交通大学马克思主义学院;', '光明日报', '中央印刷厂;共产党;根本宗旨;毛泽东;全心全意为人民服务;', '“为人民服务”是中国共产党的根本宗旨,也是每个共产党人的最高行动准则。在中国共产党发展历程中,正式把“为人民服务”作为一个科学命题提出来并将其确立为党的根本宗旨的是毛泽东同志。那么,毛泽东究竟是在什么时候、什么情况下提出“为人民服务”这一科学命题的呢?', '2011-11-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDw3GDC3fHyTVUC1AckoYqJq41Vp-pyYUlpg-0MsE7ZszoWMnkxcr01o9e08ns5a-x0_oWHgDKw54miQwlzmWXa1JnUfKcNCWitaIZYwV_knqiuYEEnlXceqMEk4i0lYSuZ53YDWh1qpA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3447, '报纸', '在纪念中国共产党成立90周年理论研讨会上的讲话', '李长春', '人民日报', '人民日报', '中国共产党成立;胡锦涛;马克思主义基本原理;理论研讨会;党的先进性;党的理论创新;党的执政能力建设;马克思主义中国化最新成果;马克思主义中国化时代化大众化;科学发展观;中国特色社会主义道路;', '由中央组织部、中央宣传部、中央党校、中央文献研究室、中央党史研究室、教育部、中国社会科学院、解放军总政治部联合召开的这次理论研讨会，是中央庆祝建党90周年系列活动的一项重要内容。 在中央隆重召开的庆祝中国共产党成立90周年大会上，胡锦涛总书记发表了重', '2011-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIATH23e_cMVhvLwxYYELdautFRywv6JpZkKXX_Vi_1sTndnJkltPFCpJyAr8iiYo7ICejEfNe6xdMmCS7EiZsjoiZTd5xXERafQ4ONk8hLM9UHfbevmJZtAP0JrYHZaA1bZYUFDcAHN3w==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3448, '报纸', '与时俱进地推进党的建设伟大工程 为党领导的伟大事业提供根本保证', '沈跃跃', '中央组织部;', '光明日报', '根本保证;与时俱进;科学发展观;', '我们党走过了90年的光辉历程。90年来，我们党坚持把推进党的建设伟大工程同推进党领导的伟大事业紧密结合起来，保证党始终成为革命、建设和改革事业的坚强领导核心。革命战争年代，毛泽东同志豪迈地把党的建设称为“伟大工程”。这一工程，成为夺取中国革命胜利的法宝。进入', '2011-07-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDoCDoUm3Y4KNVGtAk3vZRJP-iX5OMQQ81AKn8ExJctAAm7dE6F40qARRwQLQHGbUPjtd6jt3sSZREvjq2dcVmThw8idgmecleozZ0Mf_bh22IqAdsToHdQBHvpiZUP2qiiYq3k0XrZ8g==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3449, '报纸', '中国共产党为什么能走出一条非凡之路', '盛若蔚; 姜洁', '人民日报', '人民日报', '中国共产党;马克思主义;黄洋界哨口;武装夺取政权;秋收起义;社会主义市场经济体制;科学发展观;农村包围城市;根据地;公私合营;共产党人;', '一条窄窄的红船，穿越90年的浩淼烟云，朝我们徐徐驶来。 回望中国共产党走过的非凡道路，过去的90年，是党领导和依靠人民克服一切艰难险阻，不断谱写中华民族自强不息、顽强奋进壮丽史诗的90年，是党领导和依靠人民在中华民族伟大复兴道路上实现社会巨变并取得辉煌', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLb02Z02Qosubv8sIs1aX46uXP4-TiHLCyFw5zK8QIO6WrHt0I10fG-jg1yxtG09M64r87rRaeGTx6sG_OztAG8lGhDlM2wxaQJpzAmMjXppS8gm3S0kBpW59xfFgiiUKtnvGJHTf_9Q==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,黄洋界_screened,井冈山革命博物馆_screened,秋收起义_screened,茨坪_screened,何挺颖_screened,毛秉华_screened,农村包围城市、武装夺取政权_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (3450, '报纸', '90年9大历史追问(上)', '', '解放军报', '解放军报', '党指挥枪;马克思主义中国化;两次飞跃;党对军队的绝对领导;民主集中制;张国焘;秋收起义;军事指导理论;毛泽东军事思想;中国人民解放军政治工作条例;三湾改编;红四军;武装斗争;', '追问 张国焘变节叛逃时，贴身警卫员都没能带走。林彪作为一代名将、元帅，叛逃时同样没能带走自己的警卫员。为了确保党对军队的绝对领导，我军在政治上、思想上、组织上建立了一整套基本制度和措施。为什么我们的原则是党指挥枪？ 1938年4月，正当全国人民戮力同心与日', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDc71d33MtCqaoCCqWZPeuwUULzdp5ks2NmJtpkLtggzEwfY_HN8X_QgsyIc846HMMJn8ixaQkjZGPmmI5G65UIoUHn1rliGqD_OVzxIDmB6hihT5WTE0f-BnGzOykQckAghh6Sm6l3Tg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (3451, '报纸', '青春中国的“创新品质”', '温素威; 施芳', '人民日报', '人民日报', '青春中国;共产党人;党的理论创新;杨家岭;共产国际;创新品质;', '青春的脚步出发了。在遵义、杨家岭、小岗村、浦东，听历史转折处的激辩，看党的理论创新带来的蓬勃气象。 青春的声音响亮：我们是若干年后党的骨干力量，我们身上肩负着矢志创新、永葆党的先进性的使命；精神的藤蔓从历史中生发，为充满创新活力的青春中国续写辉煌', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDI-Avx0iyoC3fGCo8DgtU9gNTUc4-O0wGLuJNdzKKhv_QrtiqmcUQz7Q1JuK6EvllvP-eh5W8Rp9n1lG2afx-SyPd2wrrBOqluIAYkkfsBfe8G6CRGKSCe928rI7ky1o9LjvjhU8Z27A==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3452, '报纸', '“思想建党” 执着铸魂', '盛若蔚', '人民日报', '人民日报', '思想建党;党的思想建设;思想理论基础;发展着的马克思主义;', '党的思想建设是党的根本建设。90年来，我们党正是因为始终坚持以马克思主义为指导，从而保持了全党在思想上政治上的高度一致和党的先进性。 “实事求是”开启正确思想“航线” 中国共产党人经过不懈探索，在总结经验教训基础上，找到了农村包围城市、武装', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAiF8OsxcjAsKrabgnFA-Gy2fzg7ZWKqmG2MTQeGdnNG3szUzNYi8avyPHX5BC4YYmBK3SZYzP41DYP_l0OsHzt-2waMpkxD8NNIioewx_7OWw2GuL-AFBmVJo0Sl3y6TLRf7XKNqIAHQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3453, '报纸', '中国共产党人的“创新哲学”', '刘晓鹏; 施芳 ; 温素威', '人民日报', '人民日报', '共产党人;党的思想路线;', '坚持解放思想，实事求是，与时俱进。党的思想路线是一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理。全党必须坚持这条思想路线，弘扬求真务实精神，积极探索，大胆试验，开拓创新，创造性地开展工作，不断研究新情况，总结新经验，解决新问题，在实践', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC06vPPJVixUo1Ktu-1divdjWMA39nR8YMoqUa4YEC-qoGzhOwnmTIriRLC3K_3rvZhH4_PTD2huPTWGp5jjTG8_vPFyY38Jy1znW4uR2yzc9678v1uVqlpP65K47kSsq_IAfktyRl-eg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3454, '报纸', '赤诚之心 铿锵脚步', '', '人民公安报', '人民公安报', '全国公安会议;公安部;“三基”工程建设;全国公安厅局长会议;电视电话会议;公安机关;公安保卫工作;公安信息化建设;', '峥嵘岁月 风展红旗 国内革命战争社会（1921年-1937年7月） 人民公安机关的雏形—— 国家政治保卫局建立 ★事件：1931年3月18日，中共苏区中央局第一次扩大会议决定，建立专门的肃反机构——政治保卫处。1931年11月，中华苏维埃共和国成立，选举产生中华苏维', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC3aBPCT55k_tQqMd0DmpKoLSJs5GzzLtqcNXFBUZrNHWVzVOzHolF8xPCb0v1l0Ek3xygp4BuKt7VzxUa84fpz3E6Sse7Rnr27hHT8bNN7sVIsC_Zgb-uu08DD_1sGjfBxZcL984YvCw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,土地革命战争_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (3457, '报纸', '光辉旗帜', '秦杰 ; 李斌 ; 霍小光 ; 赵超 ; 肖春飞 ; 郭远明 ; 王圣志 ; 李兴文', '新华社;', '新华每日电讯', '井冈山革命博物馆;马克思主义中国化;共产党人;农村包围城市;中国特色社会主义道路;中国共产党;发展之路;文化大革命;中国改革开放;', '旗帜是形象,旗帜是方向。 在中国人民心中,红色的旗帜,是烈士鲜血浸染的历史,记载着壮烈；是前行路上的火炬,指明了方向；是更加红火的日子,昭示着明天…… 90年红旗高高飘扬,90年道路艰难曲折——高擎马克思主义旗帜,引领中华民族开辟广阔道路 90', '2011-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAScyWUOKg_fq-pK4jiy1mRGq5TRoDuIGhusih5r0SDIel1qAlNb2v_x1-oSumzDjoP8XVpi1ZWsqeGQQhGSkb9OjORrj23mW_dvHqDS1f1Z_0e45cjo1ime3O1JbLNRVUtblKwar0fIQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,井冈山革命博物馆_screened,毛秉华_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (3458, '报纸', '铁道游击队护送刘少奇去延安', '王卫东; 卢军', '解放军报', '解放军报', '游击队;刘少奇;', '1942年，在日军的残酷扫荡、分割蚕食下，鲁南根据地被严重压缩，交通线被敌人切断。紧要关头，铁道游击队被鲁南军区赋予重任：开辟湖上交通线，护送抗日根据地领导干部安全跨越津浦路，通过微山湖。 刘少奇便是铁道游击队护送的我党第一位高级领导干部。 1941年10', '2011-06-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICX9l9l91O4Vr6YVG1MwEhQ8N259WH_rZQzov9ngOekOW1VN0eFN4qEyq-LKJiw5L0Qhlws71RkIiGIHfk_LMLrjcVnpWwFVYtGLZCTtuukjqBD99bIyiPJfq1xD8cyIowi5MOEWs6cMw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3461, '报纸', '把全党变成一个大学校', '杜飞进 ; 盛若蔚 ; 李章军', '人民日报', '人民日报', '学习型党组织建设;先进性建设;执政能力;建设学习型党组织;马克思主义学习型政党;大学校;', '今年7月1日，中国共产党将迎来90岁的生日。 90年来，中国共产党何以能从小到大、由弱变强？何以能用28年的时间彻底改变1840年以来中华民族的悲惨命运？何以能用62年的时间，走过其他国家用几百年才走过的现代化历程？何以能始终走在时代前列、带领人民实现中华民族的伟', '2011-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDbSuATG_ymzKc8P_LQtC7enbmUHj-xpqTNNizrfYLfBF4RP-XDNb8-EZ0hJUxHsW2e-g5IspQwFIKiRDiwUqb6tVLrYUKx8LTDkIfraRxlVXVfCJU50AJIWBLykZloyGZVxpAuXOZA-g==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3462, '报纸', '让党组织成为群众的主心骨', '孟娜 ; 王丽 ; 段博 ; 黄艳 ; 曹国厂 ; 于力', '新华每日电讯', '新华每日电讯', '党组织;基层党组织书记;党员承诺制;', '53岁的王秀莲是陕西省延安市安塞县侯沟门村的一名党员中心户,曾为小学教师的她,平时联系两个农户、5名党员。 王秀莲联系的两个农户是弟兄两个,现在跑运输。当时他们买货车时,王秀莲帮他们担保贷款2万元。 “我是一名教师,也是一名党员,村里人熟得就像是家', '2011-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBS4-fjTV0-dUrMOBMEW2V-ELdMNYlcUq5maQCoyAWL758t5WeNMg5uxH12zyyLHvwmxlMJ340FVUbVIIMG9GnlMVMyyib5Fqwmr-oH-r6BEBffYYxtTJs_u46TfY48Y4vHi9690pqXxg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3464, '报纸', '永远呵护党的生命', '盛若蔚', '人民日报', '人民日报', '党内民主建设;党的生命;', '党内民主建设历来是党的建设的重要内容。 中国共产党90年的奋斗历史，是一部不断探索和推进党内民主建设的历史；中国共产党90年的民主脚步，踏响的是这个国家民主进步的节拍。 党内民主是党的生命。党的发展历程反复证明，什么时候党内民主得到较好发扬，', '2011-06-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICpttXG7Y1f8J21dxAF_4wMXjWODokqQjmimBt-tSlFwkKVbDfExm0pO225q_jkDxHJ7qRNX28SehWrhKNPHQWTosO8yS5Vb3FcjAGiKcHntppcm-UAUBYaA-w1TMb_gydpH7DyH7KylA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3466, '报纸', '变幻的时空 不变的信念', '黄小希 ; 邹伟', '新华每日电讯', '新华每日电讯', '平江县;国民党反动派;击剑项目;击剑运动员;共产主义;共产党员;加入中国共产党;党代表;', '他们年龄悬殊——一位是百岁老人,一位是“80后”。 他们经历迥异——一位是久经战场、铁血戎马一生的老将军,一位是驰骋赛场、勇夺世界冠军的“女剑客”。 但他们都有一个相同的身份——中国共产党全国代表大会代表。 建党90周年之际,新华社记者分', '2011-05-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID8Xqi7EsedfyYDQjd7UZiCQpcaEUYJNHb0fa5r7WhGRKMsSMtfGvU48vlBpzPLkIVZyLH-S_537keFFfTl1Y-RoP3dYNipqszjFil4XJ5lFyTLGCFN1wiasTjQm_qKg8cPK2JGVWE4Bw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3468, '报纸', '严肃认真地开展批评和自我批评', '解正祖', '国防大学军队党史党建研究中心;', '解放军报', '批评和自我批评;组织生活;', '胡主席强调指出，领导干部要坚持讲党性、讲原则，严肃认真地开展批评和自我批评，既要勇于进行真诚的自我批评，又要敢于批评错误的思想和行为，还要能够虚心接受别人的批评。加强和改进新形势下军队思想作风建设，必须大兴批评和自我批评之风。 一、开展批评和自我批评', '2011-05-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBGdYb895fx15SlEsfRQyDDLKlH6IqaPy3LoMWWKCfGbGtnZbnbwjpyJBtOGG7TuHRpXqNwQEN4GHpGkebu4SjlT99mK08WrSl43dYW-lqV6eqg005KSb0axvIUKKbloyE4jE42e5CcoA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3469, '报纸', '论党的群众工作', '', '中共中央宣传部理论局;', '人民日报', '党的群众工作;党的优良传统;高级干部;人民出版社;《毛泽东选集》;中央文献;十六大以来;江泽民;依靠群众;最广大人民;', '四、关于始终站稳群众立场 共产党员在民众运动中，应该是民众的朋友，而不是民众的上司，是诲人不倦的教师，而不是官僚主义的政客。共产党员无论何时何地都不应以个人利益放在第一位，而应以个人利益服从于民族的和人民群众的利益。 毛泽东：《中国共产党', '2011-05-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDliOd0rWv-VSbWawUt7yoOVRHv8kdk15eOhssljV9udDylUlXzupwTy-YKc2nn1ojmfVArQrnzepjMk5Xz5dqPBkGSp0F-pcQbOiIzOtLCAwuNJjdgaljZxM4epzUZXmpXYyDYXNhW9Q==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3470, '报纸', '王若飞', '', '人民日报', '人民日报', '王若飞;中共南方局;国民党;', '据新华社北京４月７日电 王若飞，１８９６年出生于贵州省安顺县。青年时代曾参加过辛亥革命和讨袁运动。１９１９年１０月赴法国勤工俭学。１９２２年６月，同赵世炎、周恩来等发起成立“旅欧中国少年共产党”。同年秋，同赵世炎、陈延年等一起，由阮爱国（即胡志明）介绍加', '2011-04-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICi1666VZuX6Uv6t5IfwtGk8-_kRXfefDSth0j4oWYdkTXyMODft5yN4x8Waa83syWPlzAHfySVNo3b_6qbmcmsvKIm51MAXeab-_unu47PGBAGDtKctKEeaaxRmLOc86xI67_xG1FLDA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3471, '报纸', '80后90后的红色微博', '关桓达; 王平祥 ; 夏静', '光明日报', '光明日报', '入党积极分子;学生党建工作;学习型党组织建设;学生党员;优秀学生干部;创先争优活动;徐本禹;基层党组织;榜样示范;共青团员;', '“今天你红色微博了吗？”在华中农业大学，上“红色微博”如今成了土地资源管理专业学生党员孙宇腾每天的“必修课”。在这片天地中，孙宇腾和他的同学们不仅吸收了丰富的精神营养，还找到了自己未来的发展方向。 在“80后”、“90后”成为高校学生党员主力军的今天', '2011-04-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBCI7TFfaV5SYjlQiz6k5tzjlfs9irLOZID6g0pqNmyJN0VuoE6sw-Up8EDtduFGA8EWRIOIsZHO6Y4q5OJppKJYsIYsfKCXuvmjsF5e5fhzbHlEtydy0ewA4UbMfZxGhemBCtKMKMkdw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3472, '报纸', '寓军于民的生动实践固国兴邦的伟大之举', '', '人民政协报', '人民政协报', '国防观念;国防教育;寓军于民;非公有制企业;', '建立强大的国防，是中国实现全面小康社会宏伟目标的一项战略任务。要实现这一战略任务，必须调动全国各族人民的力量，同心同德，走出一条中国特色军民融合式发展之路。 军以武强，武以器长。建立强大的军工体系，是建立强大国防的必要条件。 新中国成立后', '2011-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDe72aDN2SMl-X8W_vFgZIMZgIaoAGDdZiaJABq1VYhwwQuQvu26rTyfmZE3C1NdCTArX28TcfI5fKYEE4aoi-TOEC4WqKnHt9Bj3nXUgPkcFsvk-9-Iywa9OxCTT10DLYInSpopH2URA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3473, '报纸', '由中国制造到中国品牌', '齐洁; 张裕光', '中国经营报', '中国经营报', '江淮汽车;左延安;新能源汽车;', '上世纪90年代的江淮汽车技术老旧、车型单一，接近倒闭的边缘，左延安临危受命接掌江淮汽车的方向盘。经过十多年的摸索，江淮汽车销量位列全国十强，商用车销量排国内前五位，其利润也被众人所羡慕。 如今一场新能源汽车冒险之旅，再次把江淮汽车推到风口浪尖。21年来', '2011-03-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIATZPMxbiYK_PDZC9X_f4Ucsp-pI75rh5RlGLZ4UuXMCaqkmVQnoU1w3lUfcjqKsNVxsVgNEcdSMTZ5rnWLgbDJeUA5rscQJGWEen6t3ugLryRJtlug4hJdVUDfPv99WYfzCP8LDgpPmQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3474, '报纸', '我党我军卓越的政治工作者关向应', '', '人民日报', '人民日报', '关向应;任弼时;湘鄂川黔革命根据地;', '新华社北京２月２１日电　关向应，１９０２年生，辽宁省大连市金县人，满族。１９２０年在大连伏见台公学堂商科学习，开始接触新思想，积极参加反日爱国运动。１９２４年春，加入中国社会主义青年团。同年５月，入上海大学。同年底，赴苏联入莫斯科东方劳动者共产主义大学。', '2011-02-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAV5cjptzDmHZQkLn2yJ8u6i9JdxzlWORDr9Zb4g-SSkVtpVUhZ8Uva1HOr816LzN0IvZc8TwbcjxctFWHpi6ro6AFpN6scLmmQx_apmLtjZezjOicJ3r24z08B8j9fXeXeB1wxhN5XIA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3475, '报纸', '魅力红都硕果丰 和谐志丹气象新', '', '中国气象报', '中国气象报', '志丹县;陕西省;黄土高原;气象局;气象事业发展;气象服务;气象防灾减灾;', '大力支持气象事业促进县域经济发展 ○陕西省志丹县委书记祁玉江 志丹县位于陕西省北部，延安市西北部，是民族英雄刘志丹将军的故乡，是中国革命的 “红都”。全县总土地面积3781平方公里，辖6镇5乡1个管理区1个街道办，总人口14.9万，其中农业人口10万。近年来，新一届', '2010-11-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBejbKImcXcgNuwFui-AA4pEnxajBNT0fvLDphc0Vp6XQqQ-EzywC59vB-FxUQtDbrIeZEemEQyyTtKKrVJIA-pnpL_HbIucxmo7FbI36E40LZMduh45MhL-RjXN9ak9zPLj1a83GXSIA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3476, '报纸', '毛泽东提倡良好的文德文风', '胡为雄', '学习时报', '学习时报', '毛泽东;吴冷西;', '毛泽东非常注重宣传、新闻工作者的素质，强调并提倡言之有物的新鲜活泼的文风。因为舆论宣传和新闻工作质量如何，与从事这些工作的人员的素质直接相关，与文章的质量直接相关。 报刊新闻工作者具备马克思主义理论素养，根本的一条是要学会掌握分析的方法，看问题不', '2010-11-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAtjn1mYfuegCJQYO6b0gyToCREHt0x-y9Q0QhyEKnRJSVgTNGeJ6AzXPIsvDNwZPGrGOGtT_-HbcUiW8i6iydt61FbioCBYtgBCjMC_imrenlArqGX6_xO4Nq3JU4kHBOM4QyTE1DaKg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3478, '报纸', '把握主题 紧扣主线 抓住机遇 发挥优势 奋力谱写陕西改革开放和现代化建设新篇章', '谭浩', '人民日报', '人民日报', '陕西省;十七届五中全会;经济发展方式转变;灾后恢复重建;宁强县;抓住机遇;', '新华社西安１０月２５日电　（记者谭浩）深秋时节的三秦大地，清风送爽、果红桔黄，一派生机勃勃、喜获丰收的火热景象。２１日至２４日，中共中央政治局常委、中央纪委书记贺国强先后到陕西省延安、汉中、西安等地，就认真学习贯彻党的十七届五中全会精神，加快经济发展方式', '2010-10-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBJ3syr2nUToh4JhCmqna9NhPvtnXOASP4sBpsICi6oEOYWKXosi25yK9Ts9Z9EUIyL1UuxvFtAXsPy-vp97-247F1nGGDn81HnU5VaAqVPv8aKmnjegDAJ9fbdhpbLvO9lZXau6A1EtA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3479, '报纸', '1948年版《毛泽东选集》现身河北', '朱峰', '经济参考报', '经济参考报', '《毛泽东选集》;林伯渠;', '一套1948年出版的精装两卷本《毛泽东选集》日前现身河北省邯郸市，这套书曾被新中国中央人民政府第一任秘书长林伯渠使用过。 据该书的收藏者、邯郸市红色收藏委员会副会长王连增介绍，他是看到当地媒体报道“晋冀鲁豫中央局旧址进入全国‘红色景区’二期名录初选名', '2010-10-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICASrTepu7F_1eMyj5O4fCZkIzzR-sOpNXvTidlOBDy8ZVkZK0M79I41IBPUfsgYAmsHew43-FlDoDtuyGw0lCseRYsWjw1oIxoEzdWZrgLVRONcGIgcXknsDNGm_jlG1AjXiNCnW934g==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3481, '报纸', '创新路·求实效·促发展', '谭浩 ; 董宏君', '新华社;', '人民日报', '干部教育培训工作;干部自主选学;延安干部学院;促发展;', '组织调训、自主选学、在线学习、异地培训、送教上门、境外培训……点击近年来全国干部教育培训工作“关键词”，创新之风扑面而来。 “联系实际创新路、加强培训求实效……”回首过去几年，中共中央总书记胡锦涛在延安干部学院对干部教育培训提出的殷切期望犹在耳畔', '2010-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC2C8Sez2oW7mYGlyusmBCsjvG_x_kVfGqqMbkCJDeTOsftjdNdX2S-0bPktIh8HlpX_isi3PzOHXM5DsYRKNYflcMpqAOEvr_8GKUJa_mmXAg79z65BaA2PWNcg859H_X_ssy2lhIAkA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3484, '报纸', '信仰之路', '李宣良; 刘国顺', '新华每日电讯', '新华每日电讯', '延安精神教育;当代革命军人核心价值观;政治学院;', '作为西安政治学院的80后硕士研究生，孙官玺与许多同学一样，是“带着疑虑”踏上延安革命传统教学之旅的。  10天之后，当教学活动结束即将离开延安时，孙官玺捧起叶挺将军坟茔上的一抔黄土，装到随身携带的眼镜盒里，悄悄带回了学院，珍藏在自己的课桌上。“眼镜脏了', '2010-07-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBbXwuJeaKXnPmqm4f5Sw1c1FqBULRRgQoVCUBR-vLHgXbZVxcrUUkN9TCGBGIamxr0l3K_bZV-IbCXNLK4rFXQJTbZsoANTOxENGhaUDwjuevnDPCk5P538tgsEsUJsMlXo2YEcPO74A==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3487, '报纸', '中国延安精神研究会召开会员代表大会', '杨维汉', '人民日报', '人民日报', '中国延安精神研究会;会员代表大会;习近平;', '新华社北京５月１８日电　（记者杨维汉）中国延安精神研究会近日在京召开第五次会员代表大会，纪念研究会成立２０周年并进行理事会换届。中共中央政治局常委、中央书记处书记、国家副主席习近平致信表示祝贺。中国延安精神研究会会长李铁映出席大会并讲话。 中国延', '2010-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBhok0PMCccov7wd-x1iPsrR2SXo37ycGolbhRzWHo6X18L2eaiJ8fcLdjNMS2vtSXZu8LaPizy0cwe5fivD7VZBg86Hy-Wjeomy9bDb-qycoAKu3hn7hkwnjxoigYATjGdTUV0_ah6jQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3489, '报纸', '领导机关的干部要从基层来到基层去', '', '人民日报', '人民日报', '开学典礼;延安干部学院;井冈山;李源潮;培养选拔;', '新华社上海３月２０日电 中国浦东、井冈山、延安干部学院２０日举行２０１０年春季开学典礼。中共中央政治局委员、中央书记处书记、中组部部长李源潮在开学典礼上指出，要按照党的十七大和十七届四中全会精神，注重从基层和生产一线选拔优秀干部充实各级党政领导机关，建立', '2010-03-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDKEHcormHi-ubfaWpLJFe6chIhd2Y5pjUTfytt179vjnXtf4gd_7F_WMbb0hquk8f59HrezCbzk_ogeCVeDNPKLdtzKEO7PL0SN_GouYywsTooMaMXl1-CxICXMJyZcIbSPLKSxsq4iQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3490, '报纸', '红色经典《白毛女》：从1945到2010', '焦雯', '中国文化报', '中国文化报', '《白毛女》;杨白劳;红色经典;中国歌剧舞剧院;', '诞生于延安时期的新民族歌剧《白毛女》，其半个多世纪的创作、改编和演变历程，映射出时代和审美观念的变迁，也证明了优秀艺术作品的价值长存。源自民间传说、诞生于革命战争年代的《白毛女》是红色经典，是革命文艺的舞台艺术典范，中华民族文化和革命激情的内核正是其常演', '2010-01-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICnOIEwmaM332bjOttzvydgapzvoIB_c4EQo1scbykXmMQRBzicC3O_oQMF73ZpXiIaSRo7r5hRSvVH1napbFumzWzpDU_c4e6h4o6ibwhu9W101numa65fDPOFOF4gvachx5wp58oK7w==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3491, '报纸', '武警陕西总队延安支队 开展党员承诺制活动提高学习实践活动质量', '贺军荣; 白志福', '人民公安报', '人民公安报', '学习实践活动;党员承诺制;', '本报讯 “人人有承诺、处处当标杆、个个是模范。”在武警陕西总队延安支队，党员承诺制不但是基层党员发挥先锋模范作用的重要载体和有效途径，而且成了支队开展学习实践活动的一大品牌。  该支队是全军第三批学习实践活动联系点。在活动中，他们坚持把开展党员承诺', '2009-11-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICNguMbJELkWbTDJTojA01lhhdKyRfLg1ZzUPFLUqESARfp6OEnsm4DTIIytYthfSwm9xNEkHo116ntiC8JbvUKmiqNqMSQ1nkKtVl5ez_2m0DBSOBg5Uzamu1BEI_n7HCPZBHZyqVs4w==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3493, '报纸', '是什么让老百姓得实惠', '', '人民日报', '人民日报', '学习实践科学发展观;保增长;国际金融危机;学习实践活动;群众路线;保稳定;保民生;', '“满棚棚生绿满架架菜，侯沟门旧貌换新颜。泉眼眼那个有源大树树有根，科学发展让庄户人得实惠……”革命老区延安市安塞县侯沟门村村民自编的具有浓郁陕北风情的信天游，颂扬了最近一段时期以来村里的新变化：蔬菜大棚改造了，窑洞翻新了，道路拓宽了…… 安塞县是', '2009-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBEzATrZTl-mH63NzeDn531-BYqzvxEEFmi0Mbu4wHI9WNlKD2LgmpKprixUtjybFsIO7kQVbnVXFcDKUR3RmeKPINqCs9f0vW07LMBbQOJoPR3S5BH9PfnleJsekKJ1EGw7GWGnoPdsQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3495, '报纸', '在杨家岭感受延安精神', '刘亮; 张毅; 金晶; 牛瑾', '经济日报', '经济日报', '延安精神;杨家岭;杨家岭革命旧址;', '新中国成立60周年之际，记者来到杨家岭，踏访革命旧址，感受延安精神，感受共和国在这里迈出的坚实步伐。 盛夏的清晨，记者从延安市出发驱车赶往杨家岭村。杨家岭村虽然在延安市西北，其实与市区已经没有明显界线。汽车从一条两旁都是楼房的街道拐进了一条整洁的巷子', '2009-08-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAjwriOynewfOtVvpnCm3Dt0f50Ed9Wwh_NPTxWmpV_U85LeJnSYEXlR__88qbMcmpTEaFbJZJSwPzsJrLHvcgZ71kzCOJacntPCodx8Ul1AAidRvziGN9kXx56MuuR-KyH24r05VD54g==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3498, '报纸', '让延安精神成为实践社会主义核心价值体系的精神动力', '', '光明日报', '光明日报', '社会主义核心价值体系;延安精神;中国延安精神研究会;精神动力;', '中国延安精神研究会1月14日在京举行四届四次理事扩大会议，总结去年工作，部署今年工作要点。会议提出大力开展延安精神进基层活动，让延安精神成为实践社会主义核心价值体系的精神动力。中国延安精神研究会会长李铁映出席会议并讲话，常务副会长伍绍祖做工作报告，常务副会长', '2009-01-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBFRybj_44Cwu0ySKBREvy24ExHu5gr1et4iMWKsFIRcJhOwn2HA2uudBMsVy95rMJPsNvcO0qnIcWKnv4o4wCc1fozMXMoYadWm_3m1jzX1VVoOaiBSY7oqvZkFILM4fOW7leS_uIQiQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3499, '报纸', '多彩延安', '杜峻晓; 杨彦', '人民日报', '人民日报', '延安精神;延安市;红色旅游;', '延安，一个全中国几乎无人不晓的地名，可是又有多少人真正了解延安，尤其是今天的延安？ 头系白羊肚毛巾的汉子，吼着粗犷苍劲的信天游，在连绵不绝的黄土高坡上手挥皮鞭放牧的景象，该是许多人想象中的延安吧？这些从影视剧、旧画册中获得的印象，让延安在国人心目', '2008-12-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAw6EXIs1XMiJ8g4gZOP09QlgkovToh5laP3DhWUxcjp_F3Z065lqLMUOSGZeYIXE0i6CeP6wJCUkuX5x0Nob9PLLd1bP-QlLb2PyZxnsjYkvFu6oU0FT8DlQhV5ef9w8UebigaqMBwJA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3501, '报纸', '陕甘宁老区打造国家级生态能源经济示范区', '杨毅; 仵树大; 朱江漫; 王超', '中国经济时报', '中国经济时报', '生态能源;陕甘宁革命老区;示范区建设;陕甘宁老区;', 'T延安、榆林、庆阳、白银、平凉、吴 忠、固原七市，对世人来说并不陌生， 这里是孕育中国革命的摇篮，为新中 国的诞生作出了不可磨灭的贡献。  改革开放以来，在科学发展观 的指导下，陕甘宁革命老区经济社 会发展获得长足进步。但由于自然', '2008-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB3q5kPEx6fu-Ll44gh2mV-kdkQ1ZPunf9IwIo_oxNw6T_gVNmqy_M2S-UOtpJ7sTGMIpPJL9mlnIpcOrSyU8so05u-31DudPl1BW-U8rSoYK9YynTnRj_uQYjur_zvUKvXP0nUl4oQLQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3505, '报纸', '中国浦东井冈山延安干部学院举行春季开学典礼', '', '人民日报', '人民日报', '延安干部学院;开学典礼;井冈山;', '新华社北京3月21日电 3月21日，中国浦东、井冈山、延安干部学院举行2008年春季开学典礼。中共中央政治局委员、中央书记处书记、中央组织部部长李源潮在开学典礼上讲话，勉励广大学员深入学习贯彻党的十七大精神和全国两会精神，把提高推动事业发展的开拓创新能力放在突出位置', '2008-03-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA1VcAwRcrp62g013UHkv44DIN3bhx3oec-EaUKj7qIFhu6wOAgqfisqrVDJSD8QBhbVZFMHZahZrJxxUo3nuOOJWGQCp-9dHNnsRRzYOifepTlKCEHVAooy_0mJpeCTtF3jcwF3Z9U8Q==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3506, '报纸', '左延安：自主创新是企业的灵魂', '徐斌', '中国工业报', '中国工业报', '左延安;生产线;', 'T左延安　第十届、 第十一届全国人大代 表，全国劳动模范， 现任江淮汽车集团董 事长、总经理、党委 书记。E  左延安说，第十届人大期间的 五年，是我国经济全面发展、人民 生活普遍提高的五年，也是江汽集 团快速发展、全面提升', '2008-03-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDdtjYA2VHgBFMhHiFTd8B5YReiE5-ggkTVDiWLtBCBps9ebW1bH4dGwqqVuf0UU4xjMQctB_EEZaXAtOPw4qvebXzZodHbUBnO0katpSCDrieD2wj4z-i1hRnloeIBPglskjRFbATpcA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3511, '报纸', '国防大学加速培养高素质新型军事人才', '丁海明; 刘德茂', '解放军报', '解放军报', '国防大学;高素质新型军事人才;新世纪新阶段;', '本报北京12月1日电记者丁海明、特约记者刘德茂报道：我国最高军事学府——国防大学，今天迎来了建校80周年华诞。从昔日井冈山下的红军教导队，到今天闻名于世的综合性联合指挥大学，她为人民军队培养和输送了一大批将帅英才。 80年风雨历程，国防大学形成了许多办', '2007-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC17eBgXvbZFMkEWGJlc1GK7KRJlNqVuJ8SO2LppmtD04etv8Kw3xBuQVmNVFyzNKNqQRo0j3VW8cYC4GcAYQNkovWuRB-oS6xBH90zMADMFkF-8fUAAcBH6gZX7KhS61lh7lB8UWpg5w==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3512, '报纸', '陈寿朋：茫茫沙海上的海燕之歌', '叶辉', '光明日报', '光明日报', '陈寿朋;斯大林;美学思想;高尔基;生态道德教育;', '陈寿朋 他的一生，有两个黄金年代——青年时代，成为中国高尔基研究的领军人物；老年时代，走出书斋，舍弃自己挚爱一生的高尔基研究，走向茫茫沙海，投身于生态道德教育。在他的灵魂里，他是高尔基笔下那搏击风雨的海燕；在无边的沙漠中，他是誓为中 华披绿装的自然之', '2007-11-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAfUVgRvrpYxwGGYQY9v2c0bpt5jZ478vye8IZvfFx6Z5zyaQWadBpOtwfY-qZ_2lQgWBuortYwSrcr1sz18qyhYueSQPiBmxaaCjVidZmVg7rB9I0d_x4-c5UJR_B6-EQSZrwFrw7wqQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3513, '报纸', '靠得住 用得上 过得硬', '苏文甫; 陈太富', '解放军报', '解放军报', '战时政治工作;政治部主任;政治机关干部;军事训练;党的创新理论;十七大精神;信息化战争;革命传统教育;政工人才培养;', '10月上旬，西安政治学院对毕业（结业）学员进行了跟踪问效调查。结果显示：在近年毕业的400多名研究生中，有43.9%经基层岗位锻炼后被总部机关和军师级政治机关选用，成为部队思想政治工作的领导者和中坚力量。据不完全统计，从该院走出的5万多名学员中，有2000多名担任师以上', '2007-11-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICOZBijXhB2H9Had2w-uqEZwuBtAN4WyxN_ZEMqbfbIG2XIDs9Mgv0Rp1iL5p2gmZo66hFQ1I2dPPfufq2ZQxTS4Ol5tgHgQRdSLwoafK-bxpP5uN2yEjiu7FJZ6-JVidLsKD6t9PW5hw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3514, '报纸', '求真务实 推进信息化与工业化融合', '', '中国电子报', '中国电子报', '求真务实;十七大精神;信息化与工业化融合;', '在党的十七大胜利召开之际，信息产业部党组举办的第三期局级领导干部培训班在革命圣地——中国延安干部学院结业。在培训期间，全体学员聆听了胡锦涛总书记在党的十七大所作的报告后备受鼓舞。大家在讨论中认为，党的第十七次全国代表大会，是新时期中国共产党团结带领全国各', '2007-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICaAd6DMHK1CxZC0_J3ZDgnx9_gGVp5t-794PmXDyT_OEf3bPjtqSwM6sIYaDa3TTVKXugtq74REWwyR1Xa_x3HuuzicGXU9BsPeruIb_HKn2i8niC35gTyp0MRH_bt33t-I6PfT573eg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3515, '报纸', '立足信息产业服务科教兴国', '', '中国电子报', '中国电子报', '延安干部学院;十七大报告;胡锦涛;', '在党的十七大召开之际，我们在中国延安干部学院参加了由信息产业部党组举办、部人事司组织的第三期局级领导干部培训班。结业归来，收获颇丰。短短一周的学习时间虽然不长，但真正感觉到精神上受到了震撼、思想上得到了净化、认识上有了提高、决心和信心得到了进一步的', '2007-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAFdba8j2u_jSxnigsO_yJPvs2pTv_TAax9xZgS-sKPuHC7SlmukEszgH2W5eemNd9EuTol6-LEPGTDQ95Sm6P5MXeNgnUbxSIOhNOoSdghA-K7JuHlfF8fICttgAXmt-pmk7H6ij5egw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3516, '报纸', '办实事 想实招 求实效', '', '中国电子报', '中国电子报', '延安精神;电信服务;专用通信;', '自工作以来，多次参加业务技术、管理知识培训，满脑子的专业术语和单调的思维方式，有时问自己还能知道一点别的东西吗？正在迷茫的时候，部人事司举办了延安精神与实际工作相结合的培训班，真是雪中送炭。七天的教学安排使我们耳目一新，把红色旅游胜地的展馆作为活教材，把', '2007-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDh911etQMi4gRXCApMtlw12P9w-eEKc898eg3Zrn7Ce19RBAi4mMjK0pNiHIRjBut8UYxZ3AS1U-YjvFo466qcyYnXX3ORTqKvG5vWJQRvjPF5DR6cQxkgxoljf1V-5Z6dADmYTzeWEA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3519, '报纸', '“一大”至“七大”文献藏品', '秦杰', '人民政协报', '人民政协报', '抗日根据地;中国共产党党章;单行本;流失海外;中央书记处;', '在现代“红色收藏”中，中国共产党的“一大”至“七大”文件尤为难得。党的“一大”文件主要由担任大会记录的毛泽东手录整理，后由李达保管呈报。今天，能够真实反映当时文件原貌的有两件珍品传世，但均在海外。其一是1922年“一大”代表陈公博根据大会记录手抄整', '2007-10-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAK6mTnDYjUAoVn9Gnq9Mt6UbTp_D0bRsaL2wiIMSEoE6NiyG2otYyovqgsps7oJ9nixs4HW1feBpXjbmMrvMsxyihQX_bdOotzeNFFLOpJtoryJQIUz3OoK_vJQrzoi1_F_bU6u-tH0A==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3520, '报纸', '人行西安分行党建工作促业务发展', '雷和平; 潘洁; 孙庆卫; 索一琳', '金融时报', '金融时报', '党建工作;联系点;长效机制建设;', '近年来，人行西安分行以弘扬延安精神的时代价值为出发点，以增强广大干部职工的凝聚力和永葆党的先进性为目标，努力探索党建工作新路子，有效提升了党建工作水平，实现了党建工作与业务工作相互促进、共同发展。为适应新体制、新职能、新任务的要求，西安分行及辖', '2007-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBkEYSuvMH1QHOvOIPPPHGveyfbSr2BW-dqbCQpbMIrXHh49oUz1JQQ2MJjApjgiYJmcO6GNSaYYhRizDlsP5yzzxEXUUKH0hS_ZbiIfCG-j6A_cppnkqYwbYyQQHPS0YrRrAX8SeqpMg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3522, '报纸', '一切为了人民，为了人民的一切', '李新民', '经济参考报', '经济参考报', '胡锦涛;廉租房制度;城市低收入家庭;农民工工资;温家宝;最广大人民;城镇居民;共产党人;廉租住房;国务院常务会议;中共中央党校;执政党;关注民生;', '“情为民所系、利为民所谋、权为民所 用”，胡锦涛总书记2002年岁末在西柏坡考 察时讲出的这句饱含深情的话，近五年之后 再一次回响在中共中央党校。  回顾五年来中国经济社会发展的光辉历 程，人们注意到，心系百姓，关注民生，把 最广大群众', '2007-10-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICYIHP6-31wT7OM6n9MYIZI18h8kTF_t-0J9VhQ9kya1KvcTC25whcZsW_rgsDkkY505jIlp8jLSw2yMLflqz2obG8tFd7Y6uUXXeQF2-L8ebAz44MENZQNvylJ6GqWsm2H6f5cB0C-Gw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3524, '报纸', '大力提高各级领导班子和干部队伍整体素质 为推动科学发展促进社会和谐提供组织保证', '', '人民日报', '人民日报', '领导班子;促进社会和谐;', '新华社南昌9月3日电 中共中央政治局委员、中央书记处书记、中央组织部部长，中国浦东、井冈山、延安干部学院院长贺国强３日在井冈山出席中国浦东、井冈山、延安干部学院2007年秋季开学典礼视频会议时强调，要深入学习贯彻胡锦涛同志在中央党校的重要讲话精神，紧紧围绕迎接十', '2007-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBI7dJFt16qSHKBXAkywj40r1Bcqv5YQWO78Jy-KGsMkaVFTs0Y3yNODVs9hVpqZ1MzwYUi0UwMGDmmdIOPnAO90ngwaMAkxjEitB4Y2IfsqrAtEJip3_f16z5FRsicKur0xDRZPmt5Dg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3525, '报纸', '黄土高原崛起国家能源基地', '储国强', '经济参考报', '经济参考报', '陕北能源化工基地;原油产量;神华集团;黄土高原;', '位于黄土高原中部的陕北地区，到处都是苍凉而贫瘠的黄土。然而随着深埋于黄土下丰富的煤、油、气资源的开发，一个国家级的能源基地正在黄土高原迅速崛起。能源开发成 经济发展重要引擎历史上的陕北，是中华民族的发祥地之一，是中国革命的大本营，位于陕北的', '2007-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC4rWzDtcXZq_7F_balzDufOpY4VrjmIAoHJlQKkwYy-EprMXy4uyySyTEJsJFNfHZXl4I2i1AY4bLImkT95cn2kV-drk3-4-INsPPLh_6hVKzANp3k4c5Rv9YHRylR_tBCMlp2WF-WYw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3527, '报纸', '民主联合政府主张的提出', '', '人民日报', '人民日报', '民主联合政府;共产党;民主人士;国民党一党专政;', '１９４３年下半年至１９４４年，国际反法西斯战争节节胜利。在我国，中国共产党领导的敌后抗日根据地度过严重的困难局面，开始局部反攻。然而，国民党的统治却更加腐败和倒退，特别是１９４４年国民党军豫湘桂战役的大溃退，致使国统区民怨沸腾，国内外舆论强烈谴责。废除国', '2007-06-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBVDKSygT11FWIeMDYJH84eo2UMLWa19Q4fsaozRynjUCxl5JvdC3lX2UXDd5Z_ZescvuZcYRG-J87atmX_iFxDJsMpcMNy5kdYaAdsuvUQu5GdeAYQoyn9vb5rc62pXMA9ZTrBHgoOdg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3528, '报纸', '坚持实事求是与时俱进艰苦奋斗执政为民把干部教育培训工作提高到一个新水平', '', '人民日报', '人民日报', '干部教育培训工作;井冈山;与时俱进;曾庆红;执政为民;', '新华社北京５月１５日电中共中央政治局常委、国家副主席曾庆红在１４日召开的中国浦东、井冈山、延安干部学院教学工作会议上的讲话中指出，我们党的事业的承前启后、继往开来，我们党的干部队伍的兴旺发达、后继有人，都需要有三所干部学院这样特色鲜明地高扬党的理想和信', '2007-05-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDzPOrZtDKPsYF5Ia4AzhAYBbZQh8oh-KDZ0c18QYZqF_KizzicCc1-fN0ZHnsn7nhZYPQeY_LprM1FWjok6-NtApAZmo_48uuiw0mDFb868w7f4l4E6P68BlPWsiTVN3Utinr7EpwvDg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3529, '报纸', '继承和发扬党的光荣革命传统不断开创改革和发展的新局面', '', '人民日报', '人民日报', '曾庆红;井冈山;继承和发扬;光荣革命;改革和发展;', '新华社北京５月１４日电中共中央政治局常委、国家副主席曾庆红５月１０日至１４日在浦东、井冈山、延安干部学院考察工作期间，分别在上海市委书记习近平、市长韩正，江西省委书记孟建柱、省长吴新雄和陕西省委书记赵乐际、省长袁纯清等的陪同下，深入企业、农村、学校和建', '2007-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDVeb0pOwBWmsnw692dn3rqVjVg66lf9xXMEyQe2-7RohReixgr0SxlW-6JSljWYwVVMx74fB7klPqeDA1LGV0nzQrJ7J0l3HzW46QWV-OlkZWHN90ejDv5KSmRMLnwv8uXytZol5hARA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3530, '报纸', '历史和现实,让信念更加坚定', '贝骁; 田义伟; 范昕; 尉启君', '中国国防报', '中国国防报', '军分区;人武部;民兵预备役;土窑洞;历史和现实;', '历史教育人，因为它像一面镜子；现实教育人，因为它用事实说话。在“赞颂新成就、履行新使命、迎接十七大”主题教育中，延安军分区组织官兵走进历史，追寻革命先辈的奋斗足迹，感悟先辈的革命精神；联系实际，参观伟大时代的发展成果，感受社会发展的强劲脉搏，从而进一步坚', '2007-04-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDYQNP1rw5pdZuPZN6F5ieRqAeO_sOlrJzotRZ1o6DAohC1VlC-WyEIvl9l7qPJIxfSYhkiOTB7qso39QOL8Zq5nbGaTw29C_ytOmEi_Yo83qsJTiHWquOMNgRRc8VqPfIjYRK9AESY6w==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3531, '报纸', '中共中央党校', '', '人民日报', '人民日报', '马克思共产主义学校;毛泽东;中央党校;任弼时;', '１９３３年３月１３日，中央革命根据地“马克思共产主义学校”，即后来的中央党校，在江西瑞金成立，任弼时、张闻天先后担任校长。刘少奇、陈云、杨尚昆、董必武、李维汉、成仿吾、冯雪峰等先后在学校任职或兼任教员。１９３４年１０月，“马克思共产主义学校”的干部和部分', '2007-02-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAWbyGTh-Sx8XIlrzSA1PE3CuGp2js93aVWWmELvOu2nlQMoyJl-YfZ5WXLY3Ari2LsspeWlJkszI4-YIcKgn69JNOn4KGpRLRUwCjFZ0rlllbZf581qRglnV4oD1t0PYlYCkXeVtgPMw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3532, '报纸', '新华通讯社（上）', '', '人民日报', '人民日报', '新华通讯社;党中央;毛泽东;抗日根据地;抗日战争;新华社;红中社;红色中华通讯社;国民党顽固派;', '１９３１年１１月７日，中华苏维埃第一次全国代表大会在中央革命根据地瑞金召开。同一天，红色中华通讯社（简称红中社，即后来的新华通讯社）以“ＣＳＲ”（“中华苏维埃无线电台”的英文Ｃｈｉｎｅｓｅ Ｓｏｖｉｅｔ Ｒａｄｉｏ缩写）为呼号，开始播发新闻。这是中国共产党', '2007-02-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDlRwMrcV7-EolqAPxH9CW0Y3hrS_SfbgU1o5zgeV0AfVk3S0FWWjPDPjAO29bkBTRJOwLej2X_rz9AHRq0zHDx6OOZn83tkmr6W9OwQDXyjoXG7x8Xn1yVGUflArD0CbBMrwlD3faSNg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,论持久战_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (3533, '报纸', '延安马列学院', '', '人民日报', '人民日报', '延安马列学院;马列主义;列宁学院;张闻天;', '马克思列宁学院（简称“马列学院”），是抗日战争时期和解放战争时期中共中央创办的以学习、研究马克思列宁主义基本理论为重点的干部学校。 为了适应领导抗战这一历史重任的要求，党中央在延安恢复和创办了培养党、政、军干部的党校、抗大、陕公、鲁艺等一批学校。', '2007-01-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAC_75Ah1ZF7Uqgr4YTnZSYcPM8LxdZFjUk3daJHz0L_OXqRVqUeNDB5VbyV-ILwgW7vA0TG12mWtq13COUHIcya9SsYRVFwzpNPaXLnzfEj_HFtCd0G8dbO_xNEOSfHwf13fH3v2dz8g==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3535, '报纸', '党的六届七中全会和《关于若干历史问题的决议》', '', '人民日报', '人民日报', '《关于若干历史问题的决议》;周恩来;刘少奇;任弼时;', '从１９４４年５月２１日到１９４５年４月２０日，党的扩大的六届七中全会在延安召开，出席会议的中央委员和候补中央委员有毛泽东、朱德、刘少奇、任弼时、周恩来、康生、彭德怀、张闻天、邓发、陈云、博古、李富春、吴玉章、杨尚昆、陈郁、李维汉、孔原等１７人，各中央局、', '2007-01-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIATviXQSsarqo1xqQWko5vIu4caoVe7E2Ic7OBmzc4RPMVWsnwY1PsnSqDQpDlGRhe6S5zmRQi5sZU-d5DEMZ9_7pnjIsgkGjkpGgMei1irybtf6iavuIDcC7eQPhTM3WpP_QEeMBz1VQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3536, '报纸', '延安整风(上)', '', '人民日报', '人民日报', '延安整风;马克思列宁主义;整风运动;教条主义;主观主义;', '１９４２年到１９４５年４月党的七大召开前，党在领导敌后抗战的同时，在以延安为中心的全党范围内，开展了一场深入的马克思主义教育运动，这就是著名的延安整风运动。 １９３５年的遵义会议，确立了毛泽东在红军和党中央的领导地位，实现了党的历史的伟大转折，从', '2007-01-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBuNCK-1xY9nrnB6vezPMXix0kccdwtPf91LlTHRplbe58hBtm5901Jq_wLD8rfkkxKrvy9nTPt4OtVIgagp4XAmVsKpweHyGgylu0YI1SsrmSeV1XrpBMquFgpI5wq4i_xSCC_ov0IjQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3538, '报纸', '完善中央领导机构的“三月政治局会议”', '', '人民日报', '人民日报', '三月政治局会议;中央书记处;任弼时;杨尚昆;刘少奇;中央领导机构;王稼祥;政治局;', '１９４３年３月１６日至２０日，在延安整风正在进行期间，为了适应国际反法西斯战争出现重大转机和党领导的敌后抗日战场出现恢复发展形势的需要，加强党的一元化领导，中共中央在延安召开了著名的“三月政治局会议”，对党的六届六中全会以后的中央领导机构进行了一次较大调', '2007-01-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDOOs5A3ydzVQgJPKZrPlFUaZdtG672yhpjEaxXw1G9hhbN484tDoX-sRKuyDid1tzXvklm7EzvxPhBxGavdA096VX9Kih_lEknpM8EVYWrYtb_YPuTmYnJ2h2winiyZE4jGICNanaoug==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3539, '报纸', '邓拓与首部《毛泽东选集》问世', '张帆', '人民政协报', '人民政协报', '《毛泽东选集》;中共中央晋察冀分局;晋察冀日报;毛泽东思想;中国革命战争;《湖南农民运动考察报告》;', '1944年，中共中央晋察冀分局为了系统地宣传和学习毛泽东思想，决定出版《毛泽东选集》。聂荣臻、程子华、刘澜涛将这一任务委托给了晋察冀日报社社长兼总编辑邓拓。  晋察冀日报社是报社，又是出版社，还兼新华书店，它出版的大量书刊中，马列主义的书占有很大比重。', '2006-11-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAVaoTDsFcrbZsnCREeLKX6lETxtJyIh770TpmkRaeKfQct1ddAbVGYiOPdl1Ux7ezHAkUD1Q8ogAMW5SyyggNmzBfNzP_r3j5IlUkZTO9XfQPLSPnBH9PEvk9MlgTz2CCZ0zFNBR5YOQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3543, '报纸', '从一大到七大', '', '人民日报', '人民日报', '陈潭秋;张国焘;李立三;中国民主革命;李维汉;王尽美;陈独秀;瞿秋白;', '７月１日是中国共产党成立８５周年纪念日。在此回顾党的一大到七大，可以真切地看到中国共产党为了求得民族独立和人民解放，从无到有，从弱到强，克服重重困难，取得一个又一个胜利的艰辛而辉煌的历程。 １９２１年７月２３日，中国共产党第一次全国代表大会在上海', '2006-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB2iKc2tdnnyX2ko_UwAFEEJPuQwyPfimatRF9hnCvgz_DNuCoSUEsnSH7jt_yzbBsGk-TJFC7ooVwOVACKvrv2qAfIWInrFXFQ3PlgZ2TOqSCvS2eciZJvGNUCbGd__A15qqJy3bwIhg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3546, '报纸', '中国经济版图上的电力 陕西篇', '张一龙; 张辉', '中国电力报', '中国电力报', '“十一五”规划;电网建设;陕西省电力公司;', '挥戈三秦  在陕西这块神奇的土地上，有太多的东西吸 引着人们的目光。而这一次，2006年的农历春节， 陕西电力成为万众瞩目的焦点。  大年初一，胡锦涛总书记一行在视察革命圣 地延安之际，专程来到延安供电局看望慰问了春 节期间坚守在工', '2006-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB6YFKKP2p1PdygHRJ9UMaCDQAzIFDuU9wsPLwJ8DghDosyVbnihEBUsm-p4e5PMmdym9CpHg3jpLO2PriU8JcLnuAl7geeYjud-XlKeGzu8-8ItjCxrbZR1YioL1HYZOuJ_zarGqaT-g==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3556, '报纸', '学习陈云　研究陈云', '卫庶', '人民日报', '人民日报', '陈云同志;高度重视;执政党建设;陈云生;社会再生产理论;', '为纪念陈云同志诞辰100周年，根据党中央的决定，6月12日至14日，由中宣部、中央党校、中央文献研究室、中央党史研究室、教育部、中国社会科学院和解放军总政治部在北京联合召开“陈云生平和思想研讨会”，来自全国各地的180多名专家学者出席了研讨会。与会专家学者参加了中共', '2005-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC-91PRF_yEhqc2wVwGhISIzi9QYB0LTNTlYWsZt8Mxj3bFDxdmAhhBobaL79xMXwTEKTAur7BGMW57ZFGCcmbsaekTFQw5Tv-SbjV1x3bzgISLov5R3xtKIFVKcE4oJ22M-rZQJjQxsQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3557, '报纸', '红墙外的布衣陈云', '吴志菲', '中国民族报', '中国民族报', '陈云同志;于若木;', '有关宣传他的活动，只要他知道，都 要被中止  上世纪90年代中期，电视连续剧《陈云出川》 突然停播。关于这件事，陈云夫人于若木介绍了有 关情况：陈云在红军长征途中，曾奉中共中央之 命，从四川秘密取道上海，然后前往苏联莫斯科， 向', '2005-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAd2cT4SyhIoxAK2U5gsBG79JerlK1fEfvbNpdESnNvnXS2XGOP6NAuj51O0j7t8mEd0TvbW02f5pRKqKS_PXTXe-uKTNvAMTogMT56PCHPN4ptiQ7ZVXtYo7hRBIyhTaC2Sf1sleM7cg==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (3562, '报纸', '毛泽东“全心全意为人民服务”思想的形成', '', '人民日报', '人民日报', '毛泽东;全心全意为人民服务;民本思想;', '毛泽东同志在中国共产党的建党实践中，依据马克思主义基本原理，提出并发展了“全心全意为人民服务”的思想。经过三代中央领导集体核心的倡导，这一思想已成为全体党员的政治品格和行为准则，对于党的建设起到了巨大的推动作用。 “全心全意为人民服务”思想的渊源', '2004-02-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDGyWk1wXLoVAxb4UnSBKtOpoDnt3ID6rzkz8bWaKWQoA8zoEdit_cEhb40bBB0ua5ip3ewQ7EhDc7f-a6WVyHkOamo-xE0wp4ZbUNKcfzKDso386hgJJWr3Nxb5SWPB_Vxjk_UMJw4FA==&uniplatform=NZKPT&language=CHS', '中共七大1_screened,王尔琢');
INSERT INTO `ds_article` VALUES (3564, '报纸', '党的七大：确立毛泽东思想在全党的指导地位', '', '人民日报', '人民日报', '毛泽东思想;指导地位;日本侵略者;', '大革命失败后，中国革命之所以能够坚持下来并走向复兴，关键在于以毛泽东同志为代表的共产党人找到了一条农村包围城市、武装夺取政权的正确道路。革命的胜利和失败的反复，使党和红军认识到了毛泽东同志正确领导的重要性。1935年1月，遵义会议确立了毛泽东同志在党和红军', '2002-11-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICaDpyxh0ySFV9Y0xkhbxUoyuY395HrUYDzFFEWjmNDuRF3S014Nin4EeLIXBekP7zQgzSPt0qfIN6UdTGFEutFz_ztxZOwAAeXtE1BzfLuSLevfB-v5HVsf7OQ2wXBeASTEP0Bnvrt1A==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3567, '报纸', '延安整风运动', '', '人民日报', '人民日报', '延安整风运动;主观主义;右倾错误;', '1942－1945年在全党范围开展的整风运动， 对进一步端正党的思想路线，加强党的自身建 设，具有重大意义。  遵义会议后，党纠正历史上的“左”、右倾错 误，在全党形成了以毛泽东为核心的正确领导。 但是，还没有来得及对党的历史上的经验进行', '2002-01-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICuc6ZiHnUOqbK3upnfmRG61WjNKSj_A1QRSfhvLZuxrM8ieT_DiD-ZHV3HdGo6fO4IxVoovZdne2DIvQWGmuQ-BL1n8YVdFUzcq9umznwiREn4IEiZ-woSZqs6cMY1LfHlRGpg2KN6XQ==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3570, '报纸', '光辉历程 壮丽画卷', '翟启运; 赵川东', '人民日报', '人民日报', '建设有中国特色社会主义;中国共产党成立;社会主义现代化建设;社会主义道路;马克思主义;八十年;李大钊;江泽民;党的十五大;经济体制改革;', '这是一部波澜壮阔、气吞山河 的英雄史诗，这是一幅气势磅礴、色 彩斑斓的壮丽画卷。在中国共产党 迎来80华诞之际，雄伟庄严的中国 革命博物馆，成为全国人民关注的 地方。正在这里举行的《肩负人民的 希望──纪念中国共产党成立八十 周', '2001-07-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID58f22Vs9tJV4rmuCxttMz-tWe5EVXuaWcsKuFUdfFwn0q2VByc6ds9CjLs5pgKqffs9pQ6cXX4vLQrnUqapEichXmS7Pg7B22nngfJp-0TAmQ-bhZXoz4f1tRcslAtEcXIQT4fT2WYw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3572, '报纸', '陕西省军区组织干部参观延安革命旧址', '思治权', '中国国防报', '中国国防报', '陕西省;省军区;延安革命旧址;', '本报讯（特约记者思治权报道）日前，陕西省军区 领导带领50多名将校军官来到革命圣地延安，实地 参观延安革命纪念馆和“七大会址”等革命旧址，重 温毛泽东同志《整顿党的作风》等光辉著作，以发扬 延安整风精神，搞好自身思想作风', '2001-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAO19rYdA1aidu6qdiCeZr-XWhHSukWsL85pIPx5Q-Qzbc8zoNuvblqzDlfVkH95XhFjAflEUdaJBYzEAwy62l1zaAhh_hH-Wx_yMKSnWqZ9znz3Eu73x_YfhWkg02XX46Bn9wqNBruCw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3575, '报纸', '教育引导官兵知党信党爱党', '李溪; 曹晓雷', '解放军报', '解放军报', '官兵;延安;陕西;', '本报讯：李溪、曹晓雷报道：4月 3日，兰空驻延安某场站几百名官兵 来到延河桥畔、宝塔山下，向猎猎的 党旗宣誓，重温入党时的铮铮誓词。 这是他们充分发挥革命圣地的优势， 用“重走延安路”这一特殊形式，按', '2001-04-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBzr6Y3PjM3goww6shet-HO8EtlFKNE4j2YNC14UpTD_9RxyDLrLb_atCiZWqdBWSviZ2aszYrHAgSy2jaxXlScFZkYmWVLB2lA6yP59YF34Sg52HWMYlQZswuc_BBKjqz6N8dQ9RRctw==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3576, '报纸', '席国光同志生平', '', '人民公安报', '人民公安报', '政治部主任;公安队伍;公安部;社会部;执行党;河南省;', '中国共产党优秀党员，久经考验的忠诚的 共产主义战士，公安战线的优秀领导干部，原公 安部党组成员、公安部副部长兼政治部主任、机 关党委书记席国光同志，因病医治无效，于2001 年1月25日19时36分在北京逝世，享年85 岁。  席国光同志，', '2001-02-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBCIolqjWzvb2EVD3HHsuL90uFCSDcloyhpAUYjFSEzk8yPCXS13GAmPk6Exd9VLy5fmJllWGri1a45KuP5Kx9FVJCdfgujwFlrmKaVruBroxcVuV6muMibhYHF06Rrc5FEG3mo5gb39g==&uniplatform=NZKPT&language=CHS', '中共七大1_screened');
INSERT INTO `ds_article` VALUES (3578, '报纸', '以史为鉴 资政育人', '董宏君', '人民日报', '人民日报', '党史工作;高度重视;党史部门;民主革命时期;党的历史;以史为鉴;', '89年前，中国共产党的诞生改变了近现代中国历史的走向，随之也影响了整个世界。中国共产党从争取执政地位，到建设和发展新中国，再到改革开放和科学发展、建设中国特色社会主义，党的历史，已成为全党宝贵的精神财富，成为中华民族历史文化的重要组成部分。 党的十', '2010-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLJ9yHZX0xuwuInHejj7h4qRXr6iE0wkOw_ldv4-YhA45oulkx9trLSU7E9FwmEHDTv9eF18t2pv9IOEhkwkCKMhGyBimn_K5sOamyx_zhECHcUYhNUz6W0XtRqxlZNuZc7CQohE6-YQ==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3579, '报纸', '改进文风座谈会发言摘要', '李宝善 ; 杨衍银 ; 张建欣 ; 鲁昕 ; 李东东 ; 张文忠; 黄永达; 钟秉林; 许武', '求是杂志社;中央国家机关工委常务;教育部;新闻出版总署;国防大学政治部;中国华能集团公司;北京师范大学;中国科技大学;', '学习时报', '改进文风;习近平同志;中央国家机关;座谈会;', '在改进文风座谈会上的发言 求是杂志社社长 李宝善 习近平同志的讲话，围绕为什么要大力改进文风、应该提倡什么样的文风、怎样大力改进文风，集中论述改进文风问题，强调要按照党的十七大和十七届四中全会关于改进文风的要求，身体力行，勉力而为，努力克服不良', '2010-05-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAB63DJOVnrag8BCSlTRQEFMIhFo-eM_vx_slSfaagqyt3CpPF--7Q3abI7CWd6nUqN-tYDjPEmFKWhMgdDnGNQHUqV2IN6KHrSRnxRarqWA2NKu-WUtXfSxAHUkOsedo1_8oXEVVcH6g==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3580, '报纸', '民主政治的崭新台阶', '秦维', '团结报', '团结报', '民主政治;代表候选人;同票同权;', '“金豆豆，银豆豆，豆豆不能随便投，选好人，办好事，投在好人碗里头。”这一上世纪40年代流传于延安地区的民谣，形象地再现了陕甘宁边区因地制宜创造的选举方法——“豆选法”，这也成为新中国民主选举制度的前奏曲。 2010年3月14日，北京，人民大会堂。这是一个令', '2010-03-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC6QGF6uKczmKTg59E7E3hHipjDMMN7gIcMLoqgKLsVFzDqLxEoDkFBK7EC746G1RxyP4U6Al7ZRCOXY2omKOonBUwLj3IQInrT63TsKDsqFjiQffDVcPkHYeuOQ5GsMzMpPqdHJ1U54g==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3583, '报纸', '文化：唱响中华复兴之歌', '谌强 ; 李春利', '光明日报', '光明日报', '公共文化服务体系建设;中华复兴;国家文化软实力;群众艺术馆;综合国力竞争;美术作品;', '六十年前的10月1日,毛泽东同志在天安门城楼上向世界庄严宣告：中国人民从此站立起来了！也是在那一年的全国新政协会议上，毛泽东预言般地描述了中华民族和中国文化的光明未来：“随着经济建设的高潮的到来，不可避免地将要出现一个文化建设的高潮。中国人被人认为不文明的时', '2009-09-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB-72nhV_3sPGqBfsZwrXnUp8r3sbJYM-dSJX4pMkyPCaPe9m4nREsT58Ytcb_L5pGtzXFo18dtlK_tNC4Ns6ouERdcwHsWIVFkCEyDS8ugAoYowlGIdfi2Z1AYUiJVW7gG_Eg4K5FTWQ==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3585, '报纸', '生命之光献给党和人民', '杨连元 ; 武艾丽 ; 陈艳伟', '工人日报', '工人日报', '中国地质大学;', '23年前，在广州军区空军某指挥所成立了一个“老战士报告团”，这个自发成立的报告团中，成员大多是经过战火洗礼的老红军、老八路、老党员。这些革命一生的老人，工作上从部队退下来了，其传统的积淀、理想的激情依然在胸中激荡，由此开始了另有一番意义的人生历程。他们不辞', '2009-03-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICaSGVAxtExf384K7ck-sHzZAmQODmfrVa0kSZh8GO2o7105ffcAWU_UF1VKRdEsHUy9Bbqv-8aj46C0iOoaXqLJa723vKTXP-pZXPb8CQqrnPb4ukCbSGxKHnZRDabYf4frI23icH3Gw==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3586, '报纸', '强化我军官兵精神支柱的强大思想武器', '解放军总后勤部学习胡锦涛重要论述课题组', '光明日报', '光明日报', '当代革命军人核心价值观;历史使命;人民军队;社会主义核心价值体系;精神支柱;', '中央军委胡锦涛主席强调，要大力培育“忠诚于党，热爱人民，报效国家，献身使命，崇尚荣誉”的当代革命军人核心价值观。这是基于对国际国内形势、我军职能使命和官兵思想特点科学分析提出的重要时代课题和重大战略任务，是新的历史条件下我军思想政治建设的重大创举，是凝魂', '2009-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAmX2bw-74TP6hkI2bBa4ISAlPvc7uMCb1WeWl_NVcnT4jsDkjW6xE-LbH2VgpNd9cX0Au5sySeGm_Mor2HEG5sXxr22dyVcG2JUNwitO7Hn4a8FjOfhnytfLgLFum5wLJSR9ZBdgxvdw==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3587, '报纸', '科学发展好九连', '欧世金; 马三成; 宫曦岭; 游成锋', '解放军报', '解放军报', '中国特色社会主义理论;党的创新理论;兰州军区;“祥云”火炬;', '用党的创新理论建连育人，推进当代中国马克思主义大众化，基层连队有些什么新变化？产生了什么新经验？还有哪些新情况需要引起关注？  带着这些问题，今年3月，兰州军区一位主要领导率工作组来到某高炮旅九连蹲点调研，与官兵同吃同住一周时间，分别与67名官兵谈心', '2008-10-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICO-djRgR5aeoeqLVd9BBR3Lg8Bt6bZDfXFoL-MjPmVf35ppMDy7DXJLEukwzhXKGNQNjtGOr4f0OSjqvYHKQR63Ibjsnc4Z_IxBOJAmS9wAHq-SlQEDMEfrU5gz0BGnA4zkJWOcmcsIw==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3589, '报纸', '临沂凭红色文化孕育发展强势', '邢兆远; 郇恒赛', '光明日报', '光明日报', '红色文化;沂蒙精神;红色产业;', '本报临沂12月1日电记者近日穿行在蒙山沂水之间,登上孟良崮主峰,寻访当年支前的“红嫂”和身经百战的“老八路”,感受到这片红色热土充满勃勃生机,正迸发出强劲的发展劲头。市委书记连承敏说,按照十七大建构社会主义核心价值体系等精神,临沂立足新的起点，让红色文化成为凝心', '2007-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICBkmhD2CLeOOmq7uqnzta5J2zGUdtOxcmzju2vb7aHnoxbQxZNIvZnfFLvrhzH_Aoq_-XQ4S7xbAe-taMeNibM-mXB8UwHrFKx1TgrVGXSNNnsk0L7aUkL1kE6f6pmM6_LzhpYLd9l7g==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3590, '报纸', '进军东北和“向北发展,向南防御”的战略方针', '', '人民日报', '人民日报', '八路军;战略方针;刘少奇;冀热辽军区;中国共产党领导;李运昌;新四军;根据地;战略部署;', '实行“向北发展，向南防御”的战略方针，进军东北，建立巩固的东北根据地，是抗战胜利后党中央根据形势作出的重大战略决策。东北的战略地位极为重要。如果国民党占领这一地区，那就能够利用东北雄厚的工业基础，同华东、华中相配合，南北夹击中国共产党领导的各根', '2007-07-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC3_CFhAUoofr8JZ3gh4TzeDJIIEKSSnypnDnGiVGT2nI0whopmJWHN8TUmttPxSZvJW2aOu3UF-9ji3ZSDHYJiMopDTnbdMYJq2LRBAODQTsaPAei00BIB6qkvk6pncjYBB5g9PldZjQ==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3591, '报纸', '周恩来领导的中共中央南方局（下）', '', '人民日报', '人民日报', '中共中央南方局;周恩来;国民党统治区;', '加强抗日民主宣传，支持进步文化运动的发展，也是南方局的一项重要工作。在南方局的直接领导下，《新华日报》、《群众》周刊在极其艰难的条件下，在重庆继续公开出版，积极宣传共产党的主张，宣传抗日根据地军民抗日斗争的战绩和建设成就，反映大后方广大群众要求抗日和民主', '2007-01-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBVLl9nc1V17rQCnl9sNtnsW6vXYWetB6-vzjkjYfqMUuvyG5HnREMU_EDyeEt1GDQMAGkkFFwGHtwdy4cS3pFS1atvwCCPwN8F-P3bROaKqUaViZPkpSFC95U35T4ssaoF9aqrHco3bA==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3593, '报纸', '嘉康杰', '', '人民日报', '人民日报', '嘉康杰;山西省;阎锡山;', '嘉康杰，１８９０年生，山西夏县人。早年参加辛亥革命、反袁斗争和五四爱国运动。曾两次到日本留学。１９２０年，阎锡山向日本出卖山西煤矿权益，他作为留日学生代表回到北京，号召山西学界起来斗争，使阎锡山的阴谋破产。 １９２１年，他回到家乡，拒绝阎锡山的收买', '2006-04-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBxw8_2VtIgirgKIozIN1zfOsM22oJF-dav1ZjlZwTt2cM6X2E1bRq54kqP-ZY_vcggp-OciSnKr_sHKhsjjvAAJpZQRwtHFD4gZRY-PyYcmzHwNAV0NELDHbgWg6Yihy1xQFt98Vdv_A==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3595, '报纸', '爱民 为民 亲民 富民', '', '光明日报', '光明日报', '政绩观;共产党人;情为民所系;权为民所用;密切联系群众;', '编者按　日前,中组部和中宣部在京召开了“郑培民精神研讨会”。郑培民是继焦裕禄、孔繁森等先进模范人物之后，党的领导干部忠诚实践党的纲领和宗旨的优秀代表，他的先进事迹和崇高精神，生动形象地回答了在新的历史阶段，党的各级领导干部和广大党员应该如何保持清醒的头脑', '2004-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAFCfgtvmlQSnX4NolZjydvFPEFMFfr2Y8NPgJNm4GOSDnP4NyDIejSoWUMknrEJD5Bshze9LDvt70UD-FIRVqoHzsnw5bitlBY48zT-hnVvA_7YyGs_ENR-NykygFfG9j-I11eVaFPEA==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3597, '报纸', '军心凝聚在党旗下', '江宛柳', '解放军报', '解放军报', '十六大;', '迎接中国共产党第十六次全国代表大会召开，从春天就在华夏大地涌动起激情的热流。我们每一天都能听到来自四面八方的军营歌颂党的亲切旋律，歌声里充溢着喜悦和豪情，蓝天碧海和巍巍青山都传递出威武之师不懈的斗志和必胜的信心。面对庄严的党旗，三军将士和武警部队官兵捧', '2002-11-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIADJBspmBatnDwOrXCiAm583EhFOeHgO03Fzv45WNrDSf58lohgIUHTVodSRoQB5JoOqzRPr822BnZRhy9CkCb6D5n5VDme2ya6rBKnR-O_xSdAQboebnRrkq_zqdhj-xkPz38xal03Nw==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened,杨家岭_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (3598, '报纸', '解放思想攀高峰', '刘思扬; 李术峰; 翟伟', '新华社;', '人民政协报', '开拓创新;党的思想路线;中国特色社会主义事业;马克思主义;改革开放新时期;开发开放;保持先进性;江泽民;毛泽东思想;中国共产党;与时俱进;', '每一时代的历史进步，往往伴随着先进思想的指 引。在改革开放新时期，中华民族实现伟大历史跨越 的思想先导是：解放思想、实事求是，与时俱进、开 拓创新。  马克思主义的新飞跃──从毛泽东思想、 邓小平理论到“三个代表”，解放思想、实事', '2002-11-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAzb0tnFs_hrsDOrnrdG-AoRlKM4kYaBQk77tHTHWPquw-jmhDp7NjLNqrNgXeviRj3j7XJVfOVxMo_pbWGOt_BTSZ-VORF-zt06ywBh9hFQ8ALzEtQ8V1DLZrm8UJUxUtOZlt8OUchUg==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3599, '报纸', '在纪念彭真同志诞辰一百周年座谈会上的讲话', '江泽民', '人民日报', '人民日报', '社会主义;老一辈无产阶级革命家;党和国家;座谈会;', '同志们： 今天，我们在这里举行座谈会，纪念彭真同志诞辰一百周年。彭真同志是伟大的无产阶级革命家、政治家，杰出的国务活动家，坚定的马克思主义者，我国社会主义法制的主要奠基人，党和国家的卓越领导人。他为中国人民的解放事业，为社会主义革命和建设事业，建立了', '2002-10-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAuPt-FmTh4Fi7JqIc-hAf6I0hk8gnuKmT3KWZcgN2u5PHCftXg35cNBcxB4atnip4lYXjxeJoaWKsJCpwYAnjxXMb6BbMw0jlQMxTKBWxi4x6b8mD-aF2Nmo06p8xC72hZzdcWn57Leg==&uniplatform=NZKPT&language=CHS', '中共七大-2_screened');
INSERT INTO `ds_article` VALUES (3602, '报纸', '一枚无比珍贵的印章', '刘小花', '解放军报', '解放军报', '苏维埃;中革军委;中国工农红军;中华苏维埃共和国;临时中央政府;中央革命军事委员会;林伯渠;中国人民革命军事博物馆;', '在中国人民革命军事博物馆，珍藏着一枚无比珍贵的印章，即“中华苏维埃共和国中央革命军事委员会”印章。 这枚银质印章直径为9.5厘米，印面錾刻阳文隶书“中华苏维埃共和国中央执行委员会人民委员会”20个小字，字的两端各有一枚五角星。印的下方刻着“革命军事委员会”7个', '2023-02-19 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2023.002117', '洛川会议_screened,叶坪_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (3611, '报纸', '宝塔山下“石油城”', '毛浓曦', '工人日报', '工人日报', '石油城;延长石油厂;宝塔山;', '一进入延安地界，“革命圣地”与“石油城”的双重气息扑面而来。 洛川会议旧址、南泥湾、延安精神、宝塔山，这些元素就像一个个网址，直接把你的大脑链接到红色延安；磕头机、身着火红工装的石油人、星罗棋布的石油企业、川流不息的运油车，不停地提醒你这里的每寸土地', '2011-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBJ-df4LodzeU-UHM6RiwWmG08iGSJolzb81MzhbuOXVbrWmd-OnAtYr0dB_4arjElMgqTQ0rWX-OCTjIGf6TyHlXWDoMCs7GplhZCRWs6GDMc0Ct65oJ5evHB367ExLDRCMtdUXMTK_A==&uniplatform=NZKPT&language=CHS', '洛川会议_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3612, '报纸', '洛川医改：尝试紧密型整体托管', '甘贝贝', '健康报', '健康报', '紧密型;洛川县;三级医院;病人转诊;', '昔日以洛川会议闻名的陕西省延安市洛川县，如今在医改中通过探索紧密托管模式，在二级医院实行三级医院的管理，让群众在二甲医院享受到三甲医院的医疗服务，再度被社会关注。 紧密型整体托管，即在被托管医院产权主体、所有制性质不变的前提下，由托管者接过其管理', '2010-12-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIChxjtCeXa63ytVEUjTT4zTtsNQLh3arc9F9eo213lYUK4zA7p-X0nYK8ffJK9BjVMzoFrL0_RyJtNYk4KxjHnYQpz-8Xu2GABpq0taIYNpmC0yW9aw1uuUGpE_R82BqVxXquCd_SnVQw==&uniplatform=NZKPT&language=CHS', '洛川会议_screened');
INSERT INTO `ds_article` VALUES (3618, '报纸', '陕甘宁抗日根据地(上)', '', '人民日报', '人民日报', '陕甘宁抗日根据地;陕甘宁边区政府;陕甘宁革命根据地;', '陕甘宁抗日根据地是抗日战争时期，中国共产党在陕西、甘肃和宁夏三省交界地区建立的抗日根据地，也称陕甘宁边区。它的基础是原陕甘宁革命根据地。１９２７年大革命失败后，党领导的清涧起义、渭南起义和旬邑起义失败后，陕西省委派刘志丹和谢子长到陕北开展武装斗争，先后建', '2007-04-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDFgaE-2B-JLORybfNpFqTyhNThDMpUqbUKPQsZIzMI4EACMnhSRCqWLwK-RBB1wa8ql_sJBY6cxdGJG1sriNkTpMeELM7ZtH0xfrwSVEHtpd1RzMKwNAErNt0oH79-jpSyskGxsKiOmQ==&uniplatform=NZKPT&language=CHS', '洛川会议_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3619, '报纸', '中国共产党关于持久抗战的战略思想（上）', '', '人民日报', '人民日报', '持久抗战;中国共产党;抗日战争;持久战;', '１９３８年５月２６日至６月３日，毛泽东在延安抗日战争研究会作了长篇讲演，题目是《论持久战》。讲演结束时，毛泽东坚定地说：“抗日战争是持久战，最后胜利是中国的——这就是我们的结论。”  抗日战争全面爆发前，国民党统治集团内部就一直有人说：“中国武器不', '2007-03-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAcTAQSxbXVL5DT-jHtPqTx3GEpJC1sMf5yo4VkgryIiNTdjR47ejJDZz1ygz9n325pmF0wfUTscP2w2b2-a1tNWwmn1_3v5VJBNKyEei-UTi_a5xdQ37678-SYYMYi6ZGvMWZcUu2fcQ==&uniplatform=NZKPT&language=CHS', '洛川会议_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3620, '报纸', '特色“熔炉”锻造新型领导干部', '盛若蔚', '人民日报', '人民日报', '延安干部学院;革命旧址;现场体验;', '功能定位：“基地”、“熔炉”、“窗口” 作为新成立的三大干部学院之一，党中央赋予中国延安干部学院的功能定位是两个“基地”、一个“熔炉”、一个“窗口”，即把学院建设成为面向全国的革命传统教育基地和基本国情教育基地，提高领导干部素质和本领的熔炉以及开', '2005-11-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBy3y04URL9-uj1mYrLZt1eZNw3mbDJxvWV3fzDnPl5R-ZzQ0brDaJ1hCMNiWc0_Y9kp5rVFct0kB1OuKeAgtQsvxzZ0_aM6ZKg_YaERSxp0fJ-L8hvYfbqKwEHv4b6VCwBR-n-bI_KDw==&uniplatform=NZKPT&language=CHS', '洛川会议_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3624, '报纸', '洛川苹果红艳艳', '雷智学; 杨永林', '光明日报', '光明日报', '洛川县;永乡乡;', '秋日的洛川到处是一片丰收景象,汽车一驶入洛川,扑面而来的是一望无际的苹果园,在保护一新的洛川会议纪念馆门前,奔驰而过的是全国各地拉苹果的汽车。看着挂满枝头红艳艳的苹果,洛川人笑在了脸上,喜在了心头。  1937年8月,党中央在陕西省洛川县的永乡乡冯家村召开的政治局', '2004-11-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICtriK0P_z_XUC71JyxuNy3cbrLvTkNrEl8EPJGUqCUpQ-OvPun59DthD6xawiZTN0jUWF3xCOMXJBgFLcUo4Wqe3upEo9U48Pq8YuD-gU-ncrXHv9cZiUBoDHUT_TeB0fkO0VMVIZprQ==&uniplatform=NZKPT&language=CHS', '洛川会议_screened');
INSERT INTO `ds_article` VALUES (3625, '报纸', '陕西延安：以“红色+”为城市建设凝心聚力', '秦毅', '中国文化报', '中国文化报', '红色旅游;红色精神;凝心聚力;', '“在延安一路走一路看，一处处革命旧址、一件件革命文物令我深受触动。延安是一个令人魂牵梦绕的地方，更是一座充满信仰力量的红色之城。”近日，在陕西延安游览参观的南京游客吕华感慨万千。 延安是中国革命的圣地，新中国的摇篮。凤凰山、枣园、杨家岭、南泥湾……在延安3', '2024-02-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBVsFRMnxBjhKBCHNdV_axhQiK1-BU2hxlNQZVG-cYEGXOggHnybYNQldfsJQIS9edfnX548GZydHlEe9JzWlf87vXiWxY1_KVIGHJvqKI-FwokBFcI88IqZbn9KfK6Sd0IgM1FFb51sA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3626, '报纸', '延安：锻造忠诚为民的红色警队', '阮仕喜; 谢岗; 武达升', '人民公安报', '人民公安报', '延安精神;延安市;公安局;', '初冬的延安，街头车水马龙，熙熙攘攘的游客把宝塔山点缀得热热闹闹。秀美的延河旁，陕西省延安市公安局宝塔分局宝塔派出所民警徒步巡逻，成为冬日里的一道靓丽风景。 2023年以来，延安市公安局大力弘扬延安精神，始终把政治建警摆在首位，追根铸魂传承红色基因，着力锻造宝', '2024-01-30 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2024.000497', '枣园_screened');
INSERT INTO `ds_article` VALUES (3627, '报纸', '传承弘扬红色基因 活态保护水利遗产', '郑浩伟', '中国水利报', '中国水利报', '红色基因;活态保护;传承弘扬;', '2022年10月28日，习近平总书记在河南安阳考察时指出：“红旗渠精神同延安精神是一脉相承的，是中华民族不可磨灭的历史记忆，永远震撼人心。” 回顾中国共产党百余年奋斗的光辉历程，我们党带领人民治水的生动实践、宝贵经验凝聚在以红旗渠为代表的、遍布中华大地的众多红色', '2023-11-02 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2023.002554', '枣园_screened');
INSERT INTO `ds_article` VALUES (3628, '报纸', '宝塔山下 水润民心', '郑浩伟', '中国水利报', '中国水利报', '延安精神教育;水利工程;习近平总书记;陕甘宁边区;资源型缺水;宝塔山;先导区;', '“夕阳辉耀着山头的塔影，月色映照着河边的流萤……”一首荡气回肠的《延安颂》，不仅鼓舞了一批批爱国者奔赴延安，保家卫国，也见证了永放光芒的延安精神在这里诞生。 1935年10月，中央红军长征到达陕北。到1948年，十三载峥嵘岁月，见证了中国共产党由小到大、由弱变强，', '2023-10-19 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2023.002426', '枣园_screened');
INSERT INTO `ds_article` VALUES (3629, '报纸', '延安市·山丹丹花 山丹丹开花红艳艳', '张丹华', '人民日报', '人民日报', '山丹丹;信天游;', '赏花 毛主席来了晴了天，晴呀晴了天 千里的那个雷声噢，万里的闪 咱们革命的力量大发展 山丹丹的那个开花哟，红艳艳 毛主席领导咱打江山 ——歌曲《山丹丹开花红艳艳》 对于很多人来说，山丹丹花既陌生又亲切——可能没有亲眼见过，却时常能听到对它的赞美。 红红火', '2023-06-30 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.006660', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3630, '报纸', '红色延安多彩旅游', '任丽', '中国旅游报', '中国旅游报', '红色旅游;融合发展;宝塔区;革命旧址;', '“几回回梦里回延安，双手搂定宝塔山。”盛夏6月，革命圣地延安宝塔区城市地标景区宝塔山上，视野开阔，林木茂盛。一批又一批游客在讲解员的带领下，聆听红色历史故事，接受革命传统教育。 “不仅要把延安精神宝贵财富代代传承下去，还要做好‘红色旅游+’，让革命遗迹与红', '2023-06-22 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2023.001442', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3631, '报纸', '宝塔山下，共谱双拥赞歌', '金正波', '人民日报', '人民日报', '民兵连;延安精神;革命旧址;革命纪念地;宝塔山;', '“手抓黄土我不放，紧紧儿贴在心窝上。几回回梦里回延安，双手搂定宝塔山……” 宝塔山下，延河水旁，饱含深情的朗诵，伴着悠扬婉转的乐曲，温暖了新兵的心窝。 台上表演者，是陕西延安革命纪念地女子民兵连的姑娘们。她们用一首首陕北民歌、一支支红色舞曲，为即将奔赴军', '2023-05-28 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.005478', '枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3632, '报纸', '崇尚、学习、保护英烈的社会氛围更加浓厚', '金歆', '人民日报', '人民日报', '烈士褒扬;保护法;纪念设施;社会氛围;民事公益诉讼;', '天地英雄气，千秋尚凛然。江西瑞金叶坪红军烈士纪念塔前，前来祭扫的干部群众络绎不绝。肃立默哀、敬献花篮、整理缎带、缓步瞻仰……蒙蒙细雨中，一派庄严肃穆。 2018年5月1日起，《中华人民共和国英雄烈士保护法》施行。五年来，各地各部门深入贯彻落实英雄烈士保护法，使', '2023-05-11 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.004881', '枣园_screened');
INSERT INTO `ds_article` VALUES (3633, '报纸', '用好红色资源 赓续奋进力量', '叱骁峰', '中国纪检监察报', '中国纪检监察报', '纪检监察工作;陕西省;全面从严治党;党务委员会;党员干部;苏维埃政府;红色资源;延安时期;葛牌镇;中国人民解放军总部;红色文化;红色基因;', '三秦大地，红色资源星罗棋布。每一个历史事件、每一位革命英雄、每一种革命精神、每一件革命文物，都展现了革命先辈的梦想和追求、情怀和担当。 在全面从严治党的道路上，陕西纪检监察机关始终坚守初心使命，通过擦亮红色地标、打造红色精品、创新呈现形式等措施，保护好、', '2023-05-09 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.001723', '枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3634, '报纸', '延安市公安局宝塔分局枣园派出所：宝塔山下，为人民服务永续传承', '阮仕喜; 李江', '人民公安报', '人民公安报', '派出所;张思德;公安局;为人民服务;宝塔山;', '陕西省延安市公安局宝塔分局枣园派出所地处宝塔山下，延安时期这里是中共中央书记处所在地。1944年9月8日，中央机关在枣园为张思德召开追悼会，毛泽东主席发表了著名的《为人民服务》演讲。枣园派出所始终将“为人民服务”作为奋斗方向，忠贞不渝、赓续传承。 岁月荏苒，初', '2023-03-31 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2023.001735', '枣园_screened');
INSERT INTO `ds_article` VALUES (3635, '报纸', '为守护红色根脉注入法治力量', '李洁; 张哲浩', '光明日报', '光明日报', '革命文物;陕西省;文物保护;延安革命旧址;', '“你知道这五个铜像都是谁吗？他们分别是毛泽东、朱德、刘少奇、周恩来、任弼时……”大年初六，在陕西延安枣园革命旧址五大书记铜像前，从山东来陕西过年的尹先生正半蹲着给孩子讲解革命历史。 春节期间，革命旧址、革命博物馆、革命纪念馆成为不少人的出游首选。“春节以', '2023-02-04 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.000541', '枣园_screened');
INSERT INTO `ds_article` VALUES (3636, '报纸', '革命文物保护利用，来自陕西的行动与经验', '刘源隆', '中国文化报', '中国文化报', '文物保护;延安革命旧址;革命文物;', '革命文物是革命精神的物质载体，承载着党和人民英勇奋斗的光荣历史，记载着中国革命的伟大历程和感人事迹，是党和国家的宝贵财富。党的十八大以来，党中央、国务院高度重视革命文物保护利用工作，习近平总书记对革命文物工作作出了一系列重要指示批示，发表了一系列重要讲话', '2022-11-28 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.004373', '枣园_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (3637, '报纸', '延安精神 中国革命永远的灯塔', '党柏峰', '中国妇女报;', '中国妇女报', '党中央;新一届中央领导集体;习近平总书记;延安精神教育;中国革命;', '了解历史，才能看得远；永葆初心，才能走得远。 10月27日，党的二十大闭幕不到一周，习近平总书记带领中共中央政治局常委专程从北京前往陕西延安，瞻仰延安革命纪念地，宣示新一届中央领导集体赓续红色血脉、传承奋斗精神，在新的赶考之路上向历史和人民交出新的优异答卷的', '2022-11-24 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2022.003680', '枣园_screened,中共七大1_screened,杨家岭_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3638, '报纸', '让延安精神代代相传 书写文旅发展优异答卷', '任丽', '中国旅游报', '中国旅游报', '延安精神;习近平总书记;杨家岭革命旧址;革命纪念地;', '巍巍宝塔，初心永照；红色血脉，永续传承。10月27日，习近平总书记带领中共中央政治局常委李强、赵乐际、王沪宁、蔡奇、丁薛祥、李希，专程前往陕西延安，瞻仰延安革命纪念地，重温革命战争时期党中央在延安的峥嵘岁月，缅怀老一辈革命家的丰功伟绩，宣示新一届中央领导集体', '2022-10-31 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.002968', '枣园_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3639, '报纸', '弘扬延安精神和红旗渠精神 谱写新时代文旅新篇章', '张莹莹; 秦毅', '中国文化报', '中国文化报', '红旗渠精神;习近平总书记;南沟村;殷墟遗址;乡村旅游;红色旅游;讲解员;', '10月26日至28日，习近平总书记深入陕西延安市和河南安阳市的农村、学校、红色教育基地、文物保护单位等进行调研，在陕西、河南文化和旅游系统广大干部职工中引发热烈反响。大家纷纷表示，要把学习贯彻总书记重要讲话精神与学习贯彻党的二十大精神结合起来，深刻领会“红旗渠', '2022-10-31 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.003797', '枣园_screened');
INSERT INTO `ds_article` VALUES (3640, '报纸', '发扬延安精神和红旗渠精神，全面推进乡村振兴', '龚金星; 王乐文; 马跃峰; 龚仕建; 高炳; 原韬雄; 毕京津; 王者', '人民日报', '人民日报', '自豪感;红旗渠精神;延安精神;', '10月26日至28日，习近平总书记在陕西省延安市、河南省安阳市考察并作重要讲话，在当地干部群众中引发热烈反响。大家表示，一定牢记习近平总书记嘱托，认真学习贯彻党的二十大精神，坚持农业农村优先发展，发扬延安精神和红旗渠精神，巩固拓展脱贫攻坚成果，全面推进乡村振兴', '2022-10-30 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.011684', '枣园_screened');
INSERT INTO `ds_article` VALUES (3641, '报纸', '全面推进乡村振兴 为实现农业农村现代化而不懈奋斗', '', '人民日报', '人民日报', '农村现代化;习近平;', '全面建设社会主义现代化国家，最艰巨最繁重的任务仍然在农村。要全面学习贯彻党的二十大精神，坚持农业农村优先发展，发扬延安精神和红旗渠精神，巩固拓展脱贫攻坚成果，全面推进乡村振兴，为实现农业农村现代化而不懈奋斗 中国共产党是人民的党，是为人民服务的党，共产党', '2022-10-29 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.014134', '枣园_screened');
INSERT INTO `ds_article` VALUES (3644, '报纸', '陕甘宁革命老区赓续红色血脉风华正茂', '甄敬怡; 李建飞', '中国经济导报', '中国经济导报', '革命老区;保护修复;先行区;地区生产总值;陕甘宁;', '从陕西西安出发北上，宝塔山、凤凰山、枣园、直罗镇、瓦窑堡、吴起镇……革命战争年代，党领导革命军队和广大人民在这里英勇斗争，将红色的种子播撒到三秦大地。陕甘宁革命老区是党中央和红军长征的落脚点，也是党带领人民军队奔赴抗日前线、走向新中国的出发点。 2021年以', '2022-05-28 08:00:00', 'https://link.cnki.net/doi/10.28095/n.cnki.ncjjd.2022.000748', '枣园_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3645, '报纸', '陕西依托革命遗迹旧址 打造廉洁阵地培育精神家园', '黄秋霞', '中国纪检监察报', '中国纪检监察报', '市纪委;党务委员会;精神家园;', '连日来，陕西省延安市宝塔区杨家岭革命旧址半山坡上的小院参观者络绎不绝，一批又一批党员干部前来瞻仰学习。“这是群众当时赠送给边区政府的‘边区公民模范’。”工作人员刘茹之讲述，延安时期，中央党务委员会负责党的纪律检查工作。70多年前，中央党务委员会在院内的三孔', '2022-05-10 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.001884', '枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3646, '报纸', '用心办好教育 家长孩子满意', '张丹华', '人民日报', '人民日报', '杨家岭;延安市;希望小学;革命老区;学有所教;', '核心阅读 近年来，陕西省延安市多措并举办教育：促进公平发展、改善办学条件、扎实推进“双减”……一项项措施的落地实施，力求交出一份满意的教育答卷，让革命老区的孩子“学有所教”。 2015年2月14日，习近平总书记来到陕西延安市杨家岭福州希望小学，看望教职工。习近平', '2022-04-29 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.004553', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3647, '报纸', '在保护传承中汇聚创新发展力量', '倪建军; 王昱璇; 冯耀辉; 魏向东', '检察日报', '检察日报', '人民检察事业;检察院;陕西省;陕甘宁边区高等法院;革命文物;检察长;保护传承;', '宝塔山、枣园、杨家岭……作为延安精神的发祥地、红军长征的落脚点，陕西在中国革命史上占有重要地位，拥有丰富的红色文化资源。 如何传承红色基因，答好时代考卷？陕西省检察机关通过深入开展“寻访革命旧址、保护革命文物、传承革命精神”专项活动（下称“寻保传”专项活', '2022-04-10 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2022.001682', '枣园_screened,杨家岭_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3648, '报纸', '岁月流金 信仰永恒', '张博', '中国新闻出版广电报', '中国新闻出版广电报', '延安精神;《解放军报》;全心全意为人民服务;共产党人;', '延安是中国革命的圣地，中国共产党人在延安领导、指挥了抗日战争和解放战争，实现了马克思列宁主义同中国实际相结合的第一次历史性飞跃。巍巍宝塔山见证了中国共产党由小到大、由弱到强，从低谷走向高峰，从胜利走向新的胜利。十三载可歌可泣的恢宏篇章，孕育了以坚定正确的', '2022-03-24 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.000988', '枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3649, '报纸', '“延安过大年”今春展现融合之美', '秦毅', '中国文化报', '中国文化报', '延安市;文化艺术中心;春节文化;疫情防控;', '数十年来，陕西省延安市群众文化工作者在挖掘传统文化的基础上，精心创作了数以百计的优秀作品，如陕北说书《半碗饸饹》、陕北道情《一条棉被》、声器乐组合《延安红》、舞蹈《昊天沣鼓》、小品《二狗脱贫》等，其中不乏斩获全国及省级群星奖的优秀之作。这些天来，广大市民', '2022-02-14 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.000443', '枣园_screened');
INSERT INTO `ds_article` VALUES (3650, '报纸', '“幸福渠”：延安时期的红色水利工程', '薛永毅', '学习时报', '学习时报', '陕甘宁边区政府;水利工程;延安市;兴修水利;靠天吃饭;延安时期;', '延安枣园革命旧址是中共中央书记处1943年10月至1947年3月的所在地。中共中央书记处在此期间，继续领导了全党的整风运动和解放区军民的大生产运动。革命旧址内，有一条叫“幸福渠”（裴庄渠）的水渠横穿枣园流过。水渠尽管不长，却是大生产运动和延安精神的历史见证。 靠天吃', '2022-02-11 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2022.000235', '枣园_screened');
INSERT INTO `ds_article` VALUES (3651, '报纸', '用好故事讲出真感动', '晋浩天', '光明日报', '光明日报', '幼儿园;毛泽东;枣园革命旧址;杨家岭;红色情怀;', '如何让孩子们了解党的历史？讲故事，讲生动有趣的故事!这是西安交通大学《儿童与健康》杂志想出的点子。 《儿童与健康》编辑部组织策划了“红色情怀的感动——让孩子们了解党的历史”专题活动，通过开设专栏发表系列稿件、刊登幼儿绘画作品、新媒体传播等多种形式，带领少', '2022-01-21 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.000306', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3653, '报纸', '“集全党优秀代表于一堂”', '李蓉', '学习时报', '学习时报', '新四军;中共七大;陕甘宁边区;', '开栏语 明年我们党将召开二十大。在党的百年历史上，党的七大是一次十分重要而特殊的会议，“为建立新民主主义的新中国制定了正确路线方针政策，使全党在思想上政治上组织上达到空前统一和团结。”毛泽东评价七大是“团结的大会，胜利的大会”；邓小平称之为“民主革命时', '2021-12-10 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002329', '枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3654, '报纸', '陕西：以红色资源为旗帜 统筹城乡融合发展', '秦毅; 赵明楠', '中国文化报', '中国文化报', '红色旅游;革命旧址;红色文化;红色资源;延安市;城乡融合;讲解员;', '100年来，中国共产党弘扬伟大建党精神，在长期奋斗中构建起中国共产党人的精神谱系，锤炼出鲜明的政治品格。不久前，党中央批准了中央宣传部梳理的第一批纳入中国共产党人精神谱系的伟大精神，其中就包括延安精神和照金精神。 近年来，以延安、照金为代表的陕西多地，积极', '2021-11-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAr2N--uf2XJkzvXaMaubBafZ6bws1EmzkeTJcarEu_f55W6V5M1qmaRCTzqTPMEMthxBRKvSl4eNYEpjQS5pBgz67b66tGBUqyZcwbPpaVncfvipOz5ixTX_lMbmAxRnkTwl47xPntVg==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3655, '报纸', '陕西延安：红色文化滋养文明实践', '张哲浩; 李洁', '光明日报', '光明日报', '革命旧址;讲解员;文化滋养;', '“我看到红色精神在下一代少年心里发光!”在枣园革命旧址留言簿上，一位游客这样写道。 445处革命旧址，30座革命主题博物馆……陕西延安是全国革命旧址数量最多、时间跨度最长、内容最为丰富的城市。节假日去延安多个革命旧址参观，游客们都能听到“小小讲解员”生动的讲', '2021-11-13 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005762', '枣园_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3656, '报纸', '学习张思德精神 为民服务葆初心', '刘畅', '经济日报', '经济日报', '张思德精神;仪陇县;韩家湾;为民服务;', '“我们的共产党和共产党所领导的八路军、新四军，是革命的队伍。我们这个队伍完全是为着解放人民的，是彻底地为人民的利益工作的。”“张思德同志是为人民利益而死的，他的死是比泰山还要重的。”1944年9月8日，在延安枣园村西山脚下的一个小操场上，毛泽东同志参加了战士张', '2021-11-13 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.007973', '枣园_screened');
INSERT INTO `ds_article` VALUES (3657, '报纸', '全心全意为人民服务', '靳晓燕; 张哲浩; 李洁', '光明日报', '光明日报', '全心全意为人民服务;共产党人;毛泽东;张思德;人民至上;', '延安枣园“为人民服务”讲话纪念广场，张思德花岗岩雕塑巍然矗立，“为人民服务”五个字格外醒目。 2021年9月8日，山丹丹延安精神宣讲志愿服务队联合延安市张思德消防服务队、延安消防志愿者联盟成员又一次来到延安枣园，开展纪念《为人民服务》发表77周年，缅怀张思德同', '2021-11-11 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005723', '枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3658, '报纸', '弘扬张思德精神，全心全意为人民服务', '', '人民日报', '人民日报', '全心全意为人民服务;张思德精神;共产党人;', '一名普通的士兵，一个高尚的灵魂。自1933年参加红军后，张思德一切服从党和人民的利益，党叫干啥就干好啥，在平凡岗位上忘我工作，直至光荣殉职。他用自己短暂而光辉的一生，深刻诠释了我们党全心全意为人民服务的根本宗旨，锻造形成了张思德精神，为全党全军树立起了榜样。2', '2021-11-10 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011791', '枣园_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3659, '报纸', '弘扬张思德精神，践行全心全意为人民服务宗旨', '龚仕建; 原韬雄', '人民日报', '人民日报', '张思德精神;根本宗旨;全心全意为人民服务;', '全心全意为人民服务是党的根本宗旨。延安时期，毛泽东同志在追悼张思德同志时发表的《为人民服务》的演讲，深刻揭示了党群关系、干群关系、军民关系的真谛。 ——摘自习近平总书记2015年2月15日在陕西考察工作结束时的重要讲话 陕西延安《为人民服务》讲话纪念广场，一', '2021-11-10 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011804', '枣园_screened,中共七大1_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3660, '报纸', '毛泽东红色家风的几个侧影', '张保军', '中国人民大学马克思主义学院;', '团结报', '毛泽东;毛岸英;李银桥;毛岸青;廉洁自律;生产队长;', '红色家风，是指一代代共产党人在革命、建设、改革的岁月中所建立和倡导的家风，彰显了爱党爱国、忠于人民、廉洁自律、艰苦朴素、甘于奉献的优良传统和作风。百年来，中国共产党高度重视红色家风建设，党的领导干部更是身体力行。作为享有崇高威望的卓越领导人，毛泽东在革命', '2021-09-30 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001937', '枣园_screened');
INSERT INTO `ds_article` VALUES (3661, '报纸', '打开精神之渠 建设新时代延安', '李冬梅', '中国气象报', '中国气象报', '延安精神;气象事业;苹果产业;', '“中国共产党到底是什么样的？他们顽强得不可思议，怀揣着怎样的理想？”1936年，美国记者埃德加·斯诺对中国共产党提出这样的疑问。 斯诺的疑问，也是历史的疑问。 80多年过去了，在延安，气象干部从未停止作答。 传承，是最好的姿态 “走头头的（那个）骡子戴', '2021-09-27 08:00:00', 'https://link.cnki.net/doi/10.28122/n.cnki.ncqxb.2021.001329', '枣园_screened');
INSERT INTO `ds_article` VALUES (3662, '报纸', '用红色基因坚定青春之奋斗', '秦毅; 陈佳', '中国文化报', '中国文化报', '红色基因;党史学习;西安市;', '“故今日之责任，不在他人，而全在我少年。少年智则国智，少年富则国富……”9月18日，八路军西安办事处纪念馆举办“勿忘国耻，圆梦中华”主题纪念活动，来自西安后宰门小学的众多学子在致敬先烈的同时，以一首《少年中国说》抒发了以青春之我、奋斗之我为民族复兴铺路架桥、', '2021-09-24 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.002950', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3663, '报纸', '牢记初心使命 开创美好未来', '', '人民日报', '人民日报', '共产党人;千秋伟业;习近平总书记;', '我们党作为百年大党，要始终得到人民拥护和支持，书写中华民族千秋伟业，必须始终牢记初心和使命 初心就是力量，使命就是方向。事业发展永无止境，共产党人的初心永远不能改变 在井冈山革命博物馆，陈列着一只棕色陶罐，里面装的是已经发黑结晶的食盐。井冈山斗争时期', '2021-08-10 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.008369', '枣园_screened,井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (3664, '报纸', '延安精神历久弥新永放光芒', '杨开新; 张毅', '经济日报', '经济日报', '延安精神;延安精神教育;', '“一年胜利达吴起，陕北风光慰所思。大好河山耐实践，不倦鞍马证心期。坚持遵义无穷力，鼓励同仁绝妙诗。迈步前进爱日永，阳关坦荡已无歧。”1935年10月，后被誉为“延安五老”之一的林伯渠同志诗兴大发，以欢悦的心情创作了这首《初抵吴起镇》，预示着中国革命将开启新征程', '2021-08-04 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005817', '枣园_screened,杨家岭_screened,凤凰山_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3668, '报纸', '宝塔光辉 映照未来', '谢希瑶; 蔡馨逸; 邹多为; 李浩', '新华每日电讯', '新华每日电讯', '延安精神;马克思主义中国化;毛泽东思想;习近平总书记;共产党人;为人民服务;党的七大;党中央;奋斗目标;', '新华社北京8月2日电（记者谢希瑶、蔡馨逸、邹多为、李浩）“几回回梦里回延安，双手搂定宝塔山。” 延安，中国革命的圣地。 1935年到1948年，这片红色热土成为中共中央所在地。峥嵘岁月，见证我们党由小到大、由弱变强，领导中国革命事业从低潮走向高潮，从胜利走向新', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005892', '枣园_screened,中共七大1_screened,杨家岭_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3669, '报纸', '延安精神：绽放新时代光芒，凝聚伟大复兴力量', '毛浓曦', '工人日报', '工人日报', '延安精神;伟大复兴;革命旧址;', '6月22日，陕西省新党员代表入党宣誓活动在枣园革命旧址举行，省委副书记胡衡华出席并讲话，省委常委、延安市委书记赵刚领读入党誓词，230余名新党员代表集体诵读《为人民服务》。 前不久，“铭记百年党史、弘扬延安精神”研讨会在延安召开，来自全国11个省、区、市及高校', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2021.003643', '枣园_screened,洛川会议_screened,中共七大1_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3670, '报纸', '宝塔山下探初心', '李蕾', '解放军报', '解放军报', '延安精神;毛泽东;宝塔山;陕甘宁边区;', '老一辈革命家和老一代共产党人在延安时期留下的优良传统和作风，培育形成的以坚定正确的政治方向、解放思想实事求是的思想路线、全心全意为人民服务的根本宗旨、自力更生艰苦奋斗的创业精神为主要内容的延安精神，是我们党的宝贵精神财富。 ——习近平 清晨，雾气笼罩', '2021-08-02 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004924', '枣园_screened,中共七大1_screened,杨家岭_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3671, '报纸', '党建引领 吹响新时代延安整风号角', '郭坤泽', '人民公安报', '人民公安报', '公安局;延安市;教育整顿;党委班子成员;新时代;公安队伍;延安整风;', '巍巍宝塔山，滔滔延河水。陕西延安，是举世闻名的革命圣地，是新中国的摇篮，是公安机关的根脉。 今年以来，延安市公安局党委在公安队伍教育整顿中，始终用延安精神指导教育整顿，坚持把政治建警摆在突出位置，传承红色基因、赓续红色血脉，以党建带队建、抓队伍促业务，', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.004204', '枣园_screened');
INSERT INTO `ds_article` VALUES (3672, '报纸', '历史的回响 永远的力量', '郭坤泽', '人民公安报', '人民公安报', '人民警察;', '延安，被赋予了厚重的历史意义和现实意义。这里是共产党人的落脚点，更是出发点；延安时期是我们党领导的中国革命事业从低谷走向胜利、实现历史性转折的重要时期。 走上黄土高原、走进延安窑洞，红色革命的印记处处可见，人民警察的历史源远流长。 公安队伍教育整顿是', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.004206', '枣园_screened');
INSERT INTO `ds_article` VALUES (3673, '报纸', '红土地上的绿色崛起', '李冬梅', '中国气象报', '中国气象报', '气象事业;气象局;延安市;气象保障;绿色崛起;苹果产业;气象台;增雨作业;', '这里是陕西延安，中国革命的圣地。鲜红的党徽，在满山翠绿中格外醒目。如今每四个延安人中，就有一个是烈士后代。 这里是陕西延安，人民气象事业的诞生地。甘泉、黄陵、洛川、延川、吴起、安塞，一个个红色地标串起一段波澜壮阔的历史，同样以荡气回肠的气概，记载了气象', '2021-07-28 08:00:00', 'https://link.cnki.net/doi/10.28122/n.cnki.ncqxb.2021.000984', '枣园_screened');
INSERT INTO `ds_article` VALUES (3674, '报纸', '电波不消逝 精神永流传', '武聪; 吴皓琨', '人民邮电', '人民邮电', '数据中心;无线电台;《永不消逝的电波》;秦鸿钧;裘慧英;下载速率;', '从上海市黄渡路107弄15号3层小厨房的窗口望出去，弄堂里绿树成荫，雨水冲刷着石库门建筑斑驳的墙壁。时间回到73年前，1948年12月30日凌晨，中国共产党员、秘密电台发报员李白，在这个房间里被捕。特务冲上楼之前，他镇定地发完电文，并销毁了密电码。 窗口依旧，但窗外已', '2021-07-20 08:00:00', 'https://link.cnki.net/doi/10.28659/n.cnki.nrmyd.2021.002273', '枣园_screened');
INSERT INTO `ds_article` VALUES (3675, '报纸', '陕西：红色血脉代代传 老区振兴成典范', '任丽', '中国旅游报', '中国旅游报', '红色旅游;陕甘边革命根据地;红色基因;“七一”重要讲话;习近平总书记;照金镇;老区发展;革命纪念地;', '习近平总书记在“七一”重要讲话中指出，一百年来，中国共产党弘扬伟大建党精神，在长期奋斗中构建起中国共产党人的精神谱系，锤炼出鲜明的政治品格。历史川流不息，精神代代相传。我们要继续弘扬光荣传统、赓续红色血脉，永远把伟大建党精神继承下去、发扬光大! 习近平总', '2021-07-16 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002040', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3676, '报纸', '延安：感悟红色金融的力量', '朱立轩; 雷和平; 范婷', '金融时报', '金融时报', '延安市;《金融时报》;陕甘宁边区银行;金融的力量;革命老区;', '巍巍宝塔，滚滚延河。俯瞰延安——杨家岭的漫山绿色里，中共七大会址中央大礼堂若隐若现，枣园革命旧址中，花草树木枝繁叶茂，伟人旧居、苏式小礼堂、幸福渠一一点缀其间。 延安，是革命圣地，这里共有革命旧址445处，遍布全市。延安，更是革命者的精神家园。1935年10月，', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.003456', '枣园_screened,中共七大1_screened,杨家岭_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (3677, '报纸', '担起为人民谋幸福、为人类谋进步的历史责任', '潘洁; 成欣; 孙楠', '新华每日电讯', '新华每日电讯', '人类命运共同体;习近平总书记;', '新华社北京7月6日电（记者潘洁、成欣、孙楠）“政党作为推动人类进步的重要力量，要锚定正确的前进方向，担起为人民谋幸福、为人类谋进步的历史责任。” 建党百年之际，习近平总书记6日晚在北京以视频连线方式出席中国共产党与世界政党领导人峰会并发表主旨讲话。 这是', '2021-07-07 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005275', '枣园_screened');
INSERT INTO `ds_article` VALUES (3678, '报纸', '枣园灯光照警心 宝塔山下写忠诚', '邬春阳', '人民公安报', '人民公安报', '公安民警;派出所;甘泉县;延安精神教育;公安局;宝塔山;枣园革命旧址;习近平总书记;', '巍巍宝塔山，绵绵延河水。 历史总在惊叹，在延安的13年，我们党的自身建设如何从理论到实践有了飞跃性发展，由弱到强、蓬勃不息？ 世人总在探询，仅仅13年，我们党领导的中国革命事业如何从低潮走向高潮、实现历史性转折？ 延安，这座坐落在西北黄土高原上古老而鲜', '2021-07-05 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003718', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3679, '报纸', '改革创新推动公安事业跨越发展', '阮仕喜', '人民公安报', '人民公安报', '改革创新;延安精神;陕西省公安厅;公安机关;公安局;跨越发展;', '延安精神，永放光芒。红色基因，赓续传承。 延安是中国革命的落脚点和出发点。举世瞩目的二万五千里长征到达陕北，中共中央在延安战斗了13个春秋，培育了伟大的“延安精神”，为中国革命谱写了光辉的一页。 党的十八大以来，陕西公安机关深入贯彻习近平新时代中国特色', '2021-07-05 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003730', '枣园_screened');
INSERT INTO `ds_article` VALUES (3681, '报纸', '永远跟党走 再创新辉煌', '叶晓楠; 潘旭涛; 叶子', '人民日报海外版', '人民日报海外版', '群众性;共产党员;入党宣誓;主题宣传;党史学习;庄严宣誓;井冈山革命博物馆;中国共产党成立;', '6月18日，习近平总书记在参观“‘不忘初心、牢记使命’中国共产党历史展览”时强调，“回望过往的奋斗路，眺望前方的奋进路，必须把党的历史学习好、总结好，把党的宝贵经验传承好、发扬好，铭记奋斗历程，担当历史使命，从党的奋斗历史中汲取前进力量。” 中国共产党的历', '2021-06-28 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.001976', '枣园_screened,遵义会议_screened,井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (3684, '报纸', '1947：迎接革命新高潮', '熊杏林', '学习时报', '学习时报', '', '1947年是在中国共产党和中国革命的奋斗历程中书写转折的历史年份。 这一年，人民解放战争进入第二年。 在南京，蒋介石磨刀霍霍，对解放区实行被称为“双矛攻势”的重点进攻；在延安，中国共产党未雨绸缪，毛泽东为中共中央起草党内指示，号召“迎接中国革命的新高潮”', '2019-11-11 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2019.000426', '枣园_screened');
INSERT INTO `ds_article` VALUES (3685, '报纸', '锻造新时代宝塔山下忠诚卫士', '党延文', '陕西省延安市公安局;宝塔分局;', '人民公安报', '红色精神;宝塔山;', '陕西延安是革命圣地、中国共产党人的精神家园。近年来，延安市公安局宝塔分局紧扣党建引领警务主线，大力弘扬延安精神，传承红色基因，为公安工作创新发展注入强大内生动力。 红色精神筑牢忠诚警魂。宝塔分局注重忠诚教育，组织民警到枣园、杨家岭革命旧址，了解我党救国', '2018-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBatbwGjbOcV5oFYFmJikZu-jwZ6U-1_twno111yl7CymUP0xuyKqaRLiwjUl4J34lfRRzg-M-YbDLrRwTIRsPBIVTe8EnNSp-r8n6Z9GSHX0H8XBkhuVn2P4_4J2QIuu_-f4NICoDb4g==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3686, '报纸', '“陕北七年是近平一生最宝贵的财富”(下)', '邱然; 黄珊; 陈思', '学习时报', '学习时报', '延川县;习近平总书记;沼气池;延安文学;', '采访对象：曹谷溪，笔名谷溪。中国作协会员。1941年生于陕西省清涧县农村，曾任延川县革委会通讯组组长、《山花》文学报和《延安文学》主编、路遥文学院院长。1975年曾采访习近平，写成延川县大办沼气的通讯《取火记》。 采访日期：2016年1月23日 采访地点：陕西省', '2017-01-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDbu6XM2_ei1FrQeUqQfZmhxYe3rVCkURD4fTG-Vo-iK5gu9KTbJPlotr81YJegc6CgfMgZbMIQ_Ives1MmUrke4TaGvv3ML1HD_4wvvqWNUsmV9huEjM9uDyGThoo5ExWomIiX_sIibA==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3687, '报纸', '把思想政治工作贯穿教育教学全过程', '', '人民日报', '人民日报', '思想政治工作;思政课建设;教学全过程;大学生思想政治教育工作;延安精神教育;', '以思政课建设为引擎，加强马克思主义理论学习研究宣传 北京市 党的十八大以来，北京市认真学习贯彻落实习近平总书记系列重要讲话和批示精神，着眼于巩固马克思主义在高校的指导地位、办好中国特色社会主义大学，全面加强北京高校马克思主义理论学习研究宣传，取得', '2016-12-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA528KRjfM2Xr_E_2k3B25uw920pgTODYmhGS1g2cTUxqt9D1Cv0CuBIfNa8Nr6pgugu05trYsvksBjprEYJp_ci_6LeFKI7Ur0gKMeT-NQ_dLdJjZiNztDEnqyQfeVkXVKupdELVdGxg==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3688, '报纸', '不断把为人民造福事业推向前进', '', '解放军报', '解放军报', '共产党人;依靠人民;人民军队;', '一切为了人民，这是中国共产党95年永不褪色的赤子情怀；一切依靠人民，这是中国共产党95年立于不败之地的坚固根基。正因为如此，习总书记在庆祝中国共产党成立95周年大会上再次强调，“坚信党的根基在人民、党的力量在人民，坚持一切为了人民、一切依靠人民，充分发挥广大人', '2016-07-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC6sYf9OU4Ih6j2a9UQcySYdaxsntZKNMVMZL2GWEWBYdvMRD6ccS5cYXbCqtPQiVBRn1lWnvK8_19OY5G0CNKDxu08Gej-Gudun3Ou4S7_Zhp1tSuv8XN54EfyZjw_v6OUO1rQ_5SWIQ==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3689, '报纸', '三湾改编的“根” 改革强军的“魂”', '丁海明; 张良', '解放军报', '解放军报', '改革强军;中央军委;战区空军;国防和军队改革;三湾改编;', '引子 人民军队发展史，是一部改革创新史。 历史的灯盏，时代的火炬，虽然隔着万水千山、雄关漫道，却闪烁着一脉相承的真理之光—— 1927年9月29日至10月3日，江西永新一个名叫三湾的小村庄，见证了刚刚诞生两个月的人民军队的脱胎换骨。永载党史军史的“三湾改编', '2016-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA-eSqYfkLqqPxLCyIglUx2h-gF8drTEb9Zn4Zgdfih5fmuGb-MUr1Es-JuC8JzJUvIR14PYhFfFNB8gjuCBQeXkGww_V4Q_67KJTrBTSaf9SFZf_yQ1S6v7hzsO9z0lmFU8DVxAoCKog==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (3690, '报纸', '大力弘扬延安精神 密切联系服务群众', '卢力群', '陕西省延安市委;组织部;', '中国组织人事报', '延安精神;联系服务群众;', '延安是革命圣地，是延安精神的发祥地。中央出台关于改进工作作风、密切联系群众的八项规定，是弘扬延安精神的重要体现和具体措施，聚党心顺民意。要大兴密切联系群众之风，大力开展服务群众工作，让延安精神在新的历史条件下发扬光大。 坚持弘扬传统，增强服务群众意识', '2013-08-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICQMDOLKeqvYMtnVxiSq52D3KA561us0_1Eccm5D_6OW69oeYIEUwQyaR9FFbQhfnQ272mGK1CSCAds6CSJknd7g1rncYNxGGqT00SyczqfAJkPxPNw1KM0CzhJgOeSUm0rKXmOygf_LQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3691, '报纸', '纪念毛泽东同志《在延安文艺座谈会上的讲话》发表70周年座谈会发言摘编', '', '中国文化报', '中国文化报', '《在延安文艺座谈会上的讲话》;文艺工作者;延安文艺座谈会;毛泽东;《讲话》精神;', '继承和弘扬《讲话》精神 坚持中国特色社会主义文化发展道路 蔡 武 70年前的今天，毛泽东同志发表了《在延安文艺座谈会上的讲话》。这篇光辉著作运用马克思主义的立场、观点和方法，全面总结了五四以后中国革命运动的历史经验，深刻阐明了党对文', '2012-05-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIApfVyKsaivcMihdxMiCdBOKCjQeSv8cJUDGt9M-o6OPDa3di2y87hWR2TkslbvbzYJgSn62j1zzB4qA6VJNgcUClJwwGZtZZ-QxO2jKys0WiJNbdTVhCy_XtHDMSZbIRbLyIZm01F9Vw==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3692, '报纸', '用延安精神推进工管达标建设', '胡焕发', '湖北省富水水库管理局;', '中国水利报', '水利工程管理单位;防洪保安;水利改革发展;水利工程管理考核办法;', '近期，我与富水水库管理局的党员同志们一起踏上了神圣的延安红色旅程。短暂的几天时间，我们追寻了共和国缔造者在延安13年的奋斗足迹，参观了枣园、杨家岭、南泥湾等重要革命旧址，体验了当年延安革命战争的艰苦卓绝和惊心动魄，这让我感慨颇深，受益匪浅，并由此想到富水水', '2011-11-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBn_oyGv_jLqXI1RYZmg_D4_s1xbgnucQiE53jAg3yyeKzAi3n4K4kgHCBVFl9YGvWYU6dEPvuUwb5y4eyZsOyU16eEYwSwA_sj_WZJsvB8dcO-8BGpYxtxRbTLuCQFd_59O5XoRt49bQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3693, '报纸', '从党报的光荣传统看记者走基层', '陈力丹', '中国人民大学新闻学院;', '光明日报', '吴满有;新闻传播业;《解放日报》;光荣传统;改文风;', '我们现在的新闻传播业,起源于革命战争年代党的新闻事业。 新中国成立后,新闻事业较好地继承了以往群众办报、全党办报的光荣传统,报道了很多人民在生产、生活中的热点和难点,一些报道颇有感染力。 改革开放后的我国新闻传播业,在拨乱反正、贯彻以经济建设为', '2011-09-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID0Ak9UhJNo2UtTJwmz6RMkk99xc6TMso4xQ27Q_76V2aRyNT5WiF2208DmzBPtoLvv-B2NFEKf2dxhRU8Wcj9h2TVhekbR3sULfsRrZjKKUjr3xve9dj-bJK-3PPGI_MRpmtaOCOTohA==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3694, '报纸', '抗大传人,如何办好“共产党的大事”', '褚振江 ; 李绪成 ; 滕晓东', '解放军报', '解放军报', '胡锦涛;国防大学;抗大精神;“七一”重要讲话;高素质新型军事人才;', '中国共产党历来重视对人才的培养。早在革命战争时期，毛泽东就认为“最好最有效的方法是办学校”，这“是共产党的大事”。胡锦涛总书记在“七一”重要讲话中强调指出：“人才是第一资源，是国家发展的战略资源。”连日来，国防大学军师级单位党委（支部）书记结合延安之行，', '2011-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAuiMTVK0Qg-P9-sJW9iQjASwoSUuYNHtmq4A-eOLlSptrJEUcBfj1w7VtW_UsUslNK7FHlU-zop2BYSpwjyNlRZqpXVXr1Tw6LMLgakALPzV4KLp9LAevwpnB_j-rPR3drAj7ws9rSaw==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,杨家岭_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3696, '报纸', '“五轮驱动”打造旅游城市金名片', '王晓民', '中国旅游报', '中国旅游报', '延安精神;红色旅游资源;', '作为中国共产党革命时期的指挥中枢，延安拥有丰富的红色文化资源。通过红色旅游这种形式，越来越多的游客了解了延安。更为重要的是，伟大的延安精神也在红色旅游中得到传承和发扬光大。中国共产党成立90周年之际，中国旅游报记者专程来到延安，对延安市副市长张西林进行了专', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID47gu06eb-p_HMe5obDrQNwdjXYXCXqK4vwnWdeeIzvjQAs366iyzZk_TyrLhcFRTkOAaH-VspPcCmICR2QrYrJzriKfm8WzpoX5ocB0MIFKtIcVlZ46e6oR618M_nIA_D6_UaqYvu7A==&uniplatform=NZKPT&language=CHS', '枣园_screened,洛川会议_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3697, '报纸', '红色信念 穿越时空', '傅刚; 刘元旭 ; 王海鹰 ; 刘大江', '新华每日电讯', '新华每日电讯', '中央警备团;夏明翰;共产党人;张思德;惩治腐败;反腐败斗争;毛泽东;穿越时空;中国共产党;思想路线;', '一句话,经过了多少岁月还是那么难忘? 一首诗,经过了多少次诵读还如此铿锵? 一支歌,经过了多少年代还在广为传唱? 在中国共产党诞辰90周年前夕,重温不同时期的红色箴言,缅怀革命先辈的不朽业绩,会感到他们的精神穿越时空,迄今对我们仍有教育和警示', '2011-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICel_1V37kDMzmDjsn0BAdQgHJJBDnkDUm1R7ZxwXiyCXJaNnxQUyIpn0e7reD7kbrjUsJ95zzXyE1hRCM63l6ZP_WeR8JR-PQNbNDZ2_RYgdectlEu4dEmAlEBrR0q2w8yJoJPkmWGNQ==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3699, '报纸', '“为人民服务”的由来', '陈典宏; 陈鹏', '解放军报', '解放军报', '张思德;中央警卫团;毛泽东;', '站在张思德雕塑前，顺着29颗一字排开的红星向上仰望，镶嵌在枣园革命旧址半山腰上“为人民服务”五个遒劲有力的大红字显得格外醒目，引来大批游客在此拍照留念。 延安革命纪念馆工作人员告诉记者，67年前，毛泽东就是在这里同中共中央直属机关和中央警卫团的1000多名官', '2011-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAp6clLYtat8yYQvA5kXlxexLAG1DW2apO7eq98E7uoBq9BO_sVlmNxKGHFOjEkDZAXI-JwPDNLLGcwQY3Ap0PfgIv-80e0r8nldnjllYjzddb9XgJvobKg4R7TCVPdctEnrGbWufQo9w==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3700, '报纸', '宝塔山下抒写光荣与梦想', '龙平川', '检察日报', '检察日报', '宝塔区;最高人民检察院;检察处;延安精神;检察官;宝塔山;', '“延安有宝塔，巍巍高山上”。古城延安，三山对峙，二水交流。宝塔山作为革命圣地的象征耸立在延安的丽日蓝天下。  宝塔区原为县级延安市，因境内有著名的延安宝塔而得名。延安承载了辉煌的传奇，而今，这块具有光荣革命传统的热土上，宝塔区的检察官们也在全力抒写', '2011-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA0Jzjr3VUz5FkOab9IPfiHuHtCcbrUsfET4aHUGkJiPKQzLd1EvqyKVZWt8Dp-uXNtRmtufh8j8FbZ4TPrWFt7lsOdKejVy_mfY14I6tLPOU-nobrAjod6E9hfO-AW4lnkpQoRpieONg==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3702, '报纸', '宝塔山下话信仰', '张增朴 ; 阴继壮 ; 宋轩', '解放军报', '解放军报', '青化砭战役;国防大学;宝塔山;', '暮春细雨中的延安，庄严而神圣。蜿蜒百转的延河，绕着薄雾缭绕的凤凰山，潺潺流淌……  国防大学基本系联合战役指挥培训班的近百名将校学员，５月中旬来到革命圣地延安，通过红色资源现地教学，开始了一次寻根之旅。凝望纪念碑上革命烈士的英名，目睹改革开放给革命老区', '2011-05-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBUr8OcuEEe0ayv8ETdX_DFMU2SsKq1PhDK7DOmAd_G89w65suxOdtBGlo6JkqttIJBCZdQ6IVaWCPfXGNRTA-Ovtce5GBDSmYhLSrbKZO2e6BIb9QGB6plFgs0ofDszvCBfw8RC8MS9g==&uniplatform=NZKPT&language=CHS', '枣园_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3703, '报纸', '宝塔山下新事多', '李会 ; 杨国民 ; 张毅 ; 谢慧', '经济日报', '经济日报', '延安精神;洛川县;宝塔山;红色旅游;延长石油集团;', '滚滚延河水，巍巍宝塔山。 记者来到革命圣地延安采访，只见处处绿树葱茏，鲜花盛开。怀着崇敬的心情，记者在这片红色的土地上重温党中央在延安战斗生活的峥嵘岁月，感受延安经济社会发展和现代化建设的成就。 延安精神代代相传 进入延安，人们最先看到的是巍', '2011-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBu9ySURKFLJ5mXcHurfUC4jkoGJHJFmbmsPX4krGrLlvXf1ryfv1h7SMvPVAGx3HYJATF7VG5Fdz8ReV0hk2HtDBj12pyvr-idAzNNpX0OCLS9ZYlbEoLzKHe0A09Vxd2pb9GoNg1KXQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3704, '报纸', '寻根励志传薪火', '孙斌 ; 王莉 ; 陈鹏', '中国国防报', '中国国防报', '当代革命军人核心价值观;预备役军官;', '迎着和煦的春风，陕西某预备役师以“弘扬延安精神，培育当代革命军人核心价值观”为主题，组织400余名预备役官兵赴延安，追寻当年党中央到达陕北后的红色足迹，实地感悟延安精神，进一步激发了官兵树牢当代革命军人核心价值观的动力。 11堂讲座，8次辩论，13场演讲——', '2011-05-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDP1_qtMmGnulRK8UE71nGSIo2J2KNOc9TCyQ0J5NSPLUIGPUqHuxCn-5gd9Ar8Q2edy5D6bTF0FCHhmkf-SiNRsHr0Y9_9bu4F-INg26vLQeqmgvCeIxlBQ0Bvxh-R0JNKhkQlvd-GrQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3705, '报纸', '全心全意为人民服务 张思德', '', '人民日报', '人民日报', '张思德;全心全意为人民服务;中央警卫团;', '新华社北京４月８日电 张思德１９１５年出生在四川省仪陇县一个贫苦农民家庭，１９３３年参加红军，在炮火硝烟中成长为一名坚强的红军战士，同年加入中国共产主义青年团。 在红军中，他作战机智勇敢，曾在一次战斗中创造一人夺得两挺机枪的战绩，先后多次负伤。１', '2011-04-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA-dluZBxVOr9t4QFTfroEWS2f7qhWKRiW5sptjt-nrftuQ9fjL8Hvg0qER1sGIPjoVGain_-cIPuL8xYLNAQ1MvRITjuVLekag-tucye_VwjpI-u8QqNfRgXh8gBd9f2LfWnG3kiPOJw==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3706, '报纸', '延安有个健康“守护神”', '杨永林; 张哲浩', '光明日报', '光明日报', '延安市;食品药品监管;守护神;', '延安这片热土,曾经孕育了光照千秋的延安精神,哺育了一代又一代共产党人。如今,在延安市食品药品监管系统,又诞生了一名延安精神的传承者。几十年来,她始终牢记党的宗旨,在食品药品监管中,倾注了满腔热情,经受住了诸多超乎寻常的挑战和考验,带出了一支铁军,保障了延安的公众饮', '2011-03-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICItvgFbzChbui0MoWxJmcd9oDOL2eAlicQEs92VsYdNDG4BpYYvO9WoHcKvuKU2nVjWJD0p6LX7rEv7ytI4wFZlk5tuzXdm_Y61ZmmcI2eNEWYoabVzn6OJEOmGO7iX0dCkA4FKscziw==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3707, '报纸', '像史俊琴一样做人', '', '中国医药报', '中国医药报', '食品药品监管;', '“人不能忘本，做官一阵子，做人一辈子。”这是史俊琴常说的一句话。“人”字的结构很简单，只有一撇一捺，其中却大有深意：一划朝天，两笔踏地，意为顶天立地。向史俊琴同志学习，就要像她一样，做一名俯仰无愧于天地，行止无愧于良心的大写的人。 史俊琴的身上，', '2011-01-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB3O-j7rbcBVbxccXFO6hhegy-n2cA01Ik7nW5izjA0FH8mM3CqCH8HAc9qN_8pncDO0qVECtUUHmIPL7R5OqZhkwsatLZWUNEwllyuLajvOMuBbUWAFWSnK9wbJJEXujov1dZ17dlsNw==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3708, '报纸', '做人民满意的公务员', '史俊琴', '延安市食品药品监督管理局;', '中国医药报', '延安精神;人民满意;食品药品监管;公务员;', '尊敬的各位领导，同志们： 大家好！我来自革命圣地——延安。今天，有幸向在座的各位领导、同志们汇报工作中的点滴体会，我备受鼓舞。希望借此机会，共同学习、相互交流、与大家共勉。 我是土生土长的延安人，是喝延河水、吃小米饭长大的。陕北厚重的黄土', '2011-01-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBJAaN6-i7jzXPwtSH6KD6qZ3qlTJz24RYl8Q49Wn_VE1FRsm3IbC0NaQE0tr_Ly-GRWY2uram_6SagsFNt5Ig8F9FXjhcU7K9ScnjKpX_6MWQ96eGtO5uG1s21Vnz-9umW5sooQQWuUg==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3709, '报纸', '高校“两课”教学如何提高吸引力', '', '中国教育报', '中国教育报', '高校“两课”教学;“两课”教师;高校思政教师;延安精神;如何提高;', '事件：首都高校思政教师赴延安社会实践 本报讯（记者 王超群）日前，来自首都60余所高校的“两课”教师和学工干部600余人，在北京西站乘T231次“红色专列”赴延安参加学习实践活动。北京市依托延安大学建立的“北京高校思想政治教育教师培训基地”也在活动期间揭牌成', '2010-09-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDozoxl7BgBlWtVtHas3JkTtfmNSv4o54B9mxpxeXsRkkDRH3Hi6jMrPtxERdvDg21Zrm8gSBz20NvBehowIAPBPoMbDLkGIxxZ5Vg8JOZxZ8YVDvsdXYHLXHR4tlWqaZLKX0gSdycQpA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3711, '报纸', '要把造福群众作为发展的根本目标 从源头上预防和化解社会矛盾纠纷', '', '人民公安报', '人民公安报', '社会矛盾纠纷;王乐泉;', '本报西安8月25日电中共中央政治局委员、中央政法委副书记、中央综治委副主任王乐泉8月22日至25日在陕西延安和西安等地调研时强调，要高度重视在经济快速发展过程中可能出现的各类群众纠纷和社会矛盾，始终注意处理好发展与稳定的关系，深入落实科学发展观，坚持走可持续发展', '2010-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICW_6NhsGDi7DxwaNd19BFfKQDF-Xw7NoG0iuZM8SiamqiPX7Djuf0nmVlzIv5ExFWTj1s_xvKpbTorQRFuXAG-ABXws9sdNjDY0ADI29VZUfUR8faafbeQGm_Kt8fdWwTf2ODMQ-LtoA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3712, '报纸', '高度重视和稳妥处理好快速发展过程中可能出现的各类社会矛盾', '王银胜', '人民法院报', '人民法院报', '王乐泉;社会矛盾;社会稳定风险评估;', '本报西安8月25日电 （记者 王银胜）中共中央政治局委员、中央政法委副书记、中央综治委副主任王乐泉8月22日至25日在陕西延安和西安等地调研时强调，要高度重视在经济快速发展过程中可能出现的各类群众纠纷和社会矛盾，始终注意处理好发展与稳定的关系，深入落实科学发展观，', '2010-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBDadwk9ezypov1snaX8ISH9FFaSh-c9IysrM0QyNtmChfAWuG-AbV-y6fnvoGkLKAED_7J0k-zFBu4JuG7D7tXfyo6itXykwRtvdpz84z6kVGQLoBuzU1Wy0hBbVOyKResvSs-ouuoMw==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3713, '报纸', '延安的女儿', '王春梅; 陈静', '中国医药报', '中国医药报', '子长县;用药安全;延安市区;食品药品监管;洛川县;', '她是喝着延河水、吃着小米饭长大的。她常说，人不能忘本，做官一阵子，做人一辈子；做官就是一张薄薄的纸，做人才是一本厚厚的书。她这一辈子都是延安的女儿。 她是用“特殊材料”制成的。她的人生辞典里没有苦、累二字，就连常人无法忍受的丧子之痛，她仿佛也可以', '2010-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDVV2Il10UTIg4vTnby9WwfRdZEfPdIzNw1mDtAnNs8A3gkyoHPLN2jTZRb5yy3yjezOkX9D6u65YQPGGqmyxukMlCWIxyVvxcoX7OuflLsM5MFydbd75eG-oNZLSTmaGtwjpmRU6OtvA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3715, '报纸', '高擎火炬铸忠魂', '王丹; 刘国顺 ; 郭江山', '中国纪检监察报', '中国纪检监察报', '延安精神;政治学院;革命传统教育;', '巍巍宝塔山，清清延河水；  一堂延安课，一生延安人。  今年4月，随着解放军西安政治学院2000余名学员启程前往延安，该院延安革命传统教学进入了第32个年头。  延安，中国革命的圣地，记载着中国革命一段波澜壮阔、艰苦卓绝的红色岁月，也孕育了以坚', '2010-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC8Gn1GWdEsBglHgEWFXUdHAYfr2QZGQ5ICWh5mLAXk4IWOJsGB-DK9W7NThVziowZtGsf4SJn8GnhjbCQuPc-E15ldCyAdn1frNcmF1W93UktTLPAo0-nAkmDK4h0ZMfhcCzD00ZEmhg==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3716, '报纸', '追溯通信之根', '胡虎', '人民邮电', '人民邮电', '中央军委三局;对党忠诚;杨家岭;吴基传;', '永不消逝的电波、奔腾不止的热血——走进位于延安裴庄的军委三局旧址，凝神于那一尊气势磅礴的通信战士群像，徜徉于一段段荡气回肠的红色通信历史，脑海里不禁反复浮现这两句话语。一种身为通信人，有幸堪为通信革命先辈传人的神圣感、自豪感油然而生。是的，中国通信从这里', '2010-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB2L_ubQ6WPQE_bXeeo5nj2MXmTj4tXdhqgQ0DpOgB5QR-e2NV2vf7O9n8VRSxMFWIzlX411a590bTUyFUjXE5AHycVcKRBklGTo6xfxCy51rgGDyV3Jej6B3wpYEx73xaB2NyqMz15RA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3717, '报纸', '中央军委三局旧址修复完工', '尉启君 ; 陈鹏', '解放军报', '解放军报', '中央军委三局;', '本报延安7月1日电 尉启君、特约记者陈鹏报道：今天上午，中央军委三局旧址修复落成暨陈列馆开馆仪式在延安市枣园镇裴庄举行，革命圣地又添一处爱国主义和全民国防教育基地。 1934年1月，中央成立军委通信联络局，同年10月改称三局。长期的革命战争中，军委三局克服种种', '2010-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDEQCNmVU37wgB2RtfpNJSG3yUTN1zTIRdw07NaXKpA5v_zvyS2CIdNADSPYUuk-imn1ph7NwOMmLJT1pGrkfKQL4hKng1dzzE29xjtpLDMnx7k1E3J6Xkk-JIsQtZo98Z3vBZUJIl5WQ==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3718, '报纸', '电力张思德：永远牢记为人民服务', '冯义军; 潘春英; 王俪历', '中国电力报', '中国电力报', '延安供电局;张思德;供电所;', '感动心语 当一位高位截肢的残疾人听说我们采访，不远十几里赶来，向我们诉说张思德电力服务队的恩情；当一对高龄留守老人得知我们要了解服务队的事迹，夫妻相携来到我们面前，如数家珍地讲述张思德电力服务队对他们的照料；当多位县、市、区纠风办主任向我们推举张思德', '2010-05-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAXY6QDSHqIworC3hknQDR2ffZEp0FSGDHp9lN6045MpbHOo8iDBjUvzh9PLe6TSKdeOWQ-oFDQcrfHpagKL5ZIwbwrYDWKWmyp0L2kzTFNtDkYB6hKhYJFMw-74juPklKKAmpBjMgKiA==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3719, '报纸', '“寻根问祖,洗涤灵魂”', '刘嵘; 朱云峰', '人民法院报', '人民法院报', '高级人民法院;马锡五审判方式;陕甘宁边区高等法院;', '4月22日，经过一场细雨的洗礼，革命圣地延安阳光明媚，巍巍宝塔更显雄伟壮丽。 全国高级法院院长会议暨全国法院队伍建设工作会议专门安排与会代表瞻仰枣园、杨家岭和陕甘宁边区高等法院等革命旧址，重温党的历史和光荣传统，重温人民司法优良传统，使这次会议真正成为', '2010-04-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBi8HS1e7e3Oh5Hkbp--kNoey9D5_z4eTvnGZgxQfodnIz3u-uNH9foZO3hkmT71fx0Vi3P6l8mvqGYEEZ7Rzw5wgeP9ziMFuB8Bb-OqqEBR2RAcgxJJ6JpRzPo39Z4aXKfE9E-JTOYtA==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3720, '报纸', '传承延安精神 弘扬司法之魂', '周崇华', '人民法院报', '人民法院报', '政治部主任;延安精神;', '4月的革命圣地——延安，宝塔山巍巍耸立，延河水涓涓细流。 4月22日至23日在延安召开的全国法院院长会议暨全国法院队伍建设工作会议，必将成为共和国法院历史上一次标志性的会议。 “全力推进队伍建设，坚持人民法官为人民，坚持公正廉洁执法……” 认', '2010-04-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAToyVYlGtU1NbyLz6iXITNYlrA5fcABamsvRxO8tNXwuiMEsaplJ38NQnky2aSBYdAThw8SE-k5jP-Px9yO9mbu-Ju1brStIZLVp6wX13Ishn7f9zpj8n97GYUcR1Hz3oWJffSsgLgDQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3721, '报纸', '粤沪旅行社考察延安红色旅游', '苏秀芳', '中国旅游报', '中国旅游报', '旅行社;延安市旅游局;红色旅游;', '本报讯（苏秀芳）日前，延安迎来了由长三角和珠三角40多家旅行社负责人组成的红色之旅考察团，这些旅行社纷纷表示，今冬他们将大力推广延安旅游，让游客缅怀“红色文化”的壮美、黄土风情文化的豪迈。 为了让今年冬季延安红色旅游不再冷清，吸引更多的旅行社组织游', '2009-12-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAE7vDLahsY0YWkF9T0C8-p0oGuMiu7ECFjVDR12r2navogp0NGNo6O7IzJvwnDwcsWXqwpPCm45HSUPfOAcA-mrdHP6ib0136LLGrSbat2T5fZMDoCSOsF1ETggrqJ8XXaYSfo3DzTiw==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3722, '报纸', '韶山井冈山延安新颜迎游人', '', '人民日报', '人民日报', '毛泽东纪念馆;井冈山革命博物馆;', '新华社北京12月1日电 进入“小雪”，寒气袭人，可韶山毛泽东纪念馆馆长夏佑新说：“28、29号这两个双休日来韶山的游客依然很‘火’，达到27000多人，平日游客也多，主要是新场馆、新面貌比过去更吸引人。” 爱国主义教育示范基地“一号工程”协调指导小组办公室的', '2009-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAVIzyl-crFWT0AFc08sfb1fd3cM38yiOgrVL_4sBt0E6LyCoxy6mzGsh6JzzvVQSvNGZbRDYKx4hwuzQxEdjYd5KmKe_XzElLRndt2FBnGXAP1NRzQxwyO7ft-qIMi56zL4yozDRVAnA==&uniplatform=NZKPT&language=CHS', '枣园_screened,井冈山革命博物馆_screened,茨坪_screened');
INSERT INTO `ds_article` VALUES (3723, '报纸', '结合新的实际弘扬延安精神 坚持求真务实推进党的建设', '李亚杰', '人民日报', '人民日报', '延安精神;党的十七届四中全会;习近平;求真务实;', '新华社西安１１月１６日电　（记者李亚杰）中共中央政治局常委、中央书记处书记、国家副主席习近平近日在陕西调研时强调，伟大的延安精神是党的性质和宗旨的集中体现，是党的优良传统和作风的集中体现。要结合新的实际大力弘扬延安精神，以求真务实作风切实加强和改进新形势', '2009-11-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB_EemUC0wq3cNySwO6gHUGiWp0oqZHiBre4R0mIjdLwhenSOltfBM_V1alcMPeanHHgqPTMnTm03sZdavvWpfhq6axGIgNUG81VUdZpwSAEFFrJZ231PS-IAoJl84_gMqSSNRgz_eqlA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3724, '报纸', '500余件“新”文物亮相', '王乐文', '人民日报', '人民日报', '延安革命纪念馆;毛泽东著作;革命旧址;', '核心提示 8月28日，历时5年多、投资5.7亿元的延安革命纪念馆新馆正式向观众开放。新馆的展出模式突破传统，新挖掘、整理、征集的文物达到500多件，许多文物为首次展示。 开馆之际，本报记者探访新馆，重温中国革命的光辉历史。  “一号工程”展示', '2009-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBdaA2vogZ-o5z7CwxcW1-bJd33Ya3UF4YlzKdtexuEjOdOzNCvxL7xguHkEG3No04KsmdAhO6TeEM4N-xeypcOCXynxIPbdWVzSnNgNDjz-0kAOgKTE92PeGtHam5f1oSTmqlCIY26_A==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3726, '报纸', '洛川：传承革命精神 谱写发展新篇', '金晶; 牛瑾 ; 张毅', '经济日报', '经济日报', '新中国成立;陕西省;包茂高速;洛川会议纪念馆;洛川县;', '洛川，位于陕西省延安市南部，在中国革命史上有着特殊地位。1937年8月22日至25日，在县城以北10公里处的冯家村，在从一所私塾暂借来的简陋窑洞中，中国共产党召开了中共中央政治局扩大会议，也就是历史上著名的“洛川会议”。 6月，我们走进洛川，昔日的会址已成为人', '2009-08-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICY2PvSw4zI7RLj0T6BvBBsX0alpcDVyUrwjKALOz7dyzGQyGRlSNW6GW17fKBDwDfJUk9qA5qj-3CO91WWjq4T7GqOmyTxncsZ7gkhRMWP2HL7it3bQJdaOkJiOdIOz0ojAHHh0XpUfg==&uniplatform=NZKPT&language=CHS', '枣园_screened,洛川会议_screened,洛川会议_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3727, '报纸', '红色旅游 让延安火起来', '魏贺; 左娅', '人民日报', '人民日报', '红色旅游;延安市旅游局;', '【核心阅读】 延安是全国红色旅游资源最集中、最突出的城市。近几年，延安市创新旅游产业市场化经营思路，用红色故事感染人、用黄土风情吸引人、用绿色环境愉悦人，大大提高了红色旅游的吸引力。 杨家岭、枣园、王家坪……随着暑期的到来，革命圣地延安的', '2009-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC_V7DvvOF0Qbm6ltmgGBm6MplzGBBpjkXa99pqT48e-dtU8S4BLmd6I-HgEvr3tDXqSsCisRLFCL8M7nCuFS3k43iXyifSmYgPkxlpAtHMXuDjbqvF-UoquAaNdcOtOFhUB_7h-TUQ6A==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3728, '报纸', '住房和城乡建设部直属机关团干部、青年赴陕西基层调研', '汪汀', '中国建设报', '中国建设报', '直属机关;团干部;团员青年;基层调研;住房和城乡建设部;', '本报讯 记者汪汀报道 近日，住房和城乡建设部直属机关团委组织直属机关部分团干部和青年，赴陕西西安、延安进行“根在基层”调研实践和革命传统教育活动。  部直属机关团干部、青年听取了西安市城乡建设委员会、延安市城市管理局的情况介绍，并与两个单位的团员青', '2009-07-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAKWeNFm5v3gmtMvD1h9edSejZhkkFiQbrYXmMpvTYwU-SSTi96aw7j-47zllK3cjYDwzOhBQKcpfdvk69nQ48hmUt68pyGOIwY0ub-UJMfey3nfKgnDKpB8aR8zcFVUYOo2tTa02yb1w==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3730, '报纸', '弘扬延安精神 推动科学发展 建设美好安塞', '', '人民日报', '人民日报', '安塞县;学习实践活动;科学发展观;', '●　把加强学习培训贯穿始终，把深入调查研究贯穿始终，把推动解放思想贯穿始终，把解决突出问题贯穿始终，把吸收群众参与贯穿始终 ●　坚持把中央精神与县情民意相结合，把近期目标与长远目标相结合，把学习实践活动与推动工作相结合，把县级领导班子与普通党员干', '2009-03-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDzghtIvS-9tDo8TTEPKHjBp-hgJqF65gM3phh3RRT6d3uwFm7SFw6Rs7h2WJ5ywMy8EznKS3sFGgsa2wvQWefccoIjCFmgY-5t10tZXtxBvnPpkBzzdTqXc8yXNurJH-3ByJEG1ObUHw==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3731, '报纸', '延安精神薪火相传', '孟西安; 吴月辉', '人民日报海外版', '人民日报海外版', '延安精神;杨家岭;', '作家魏巍曾写道：“中国英雄的长征像一条鲜艳夺目的红飘带挂在这个星球上，给人类、给后世留下永远的纪念。” 1934年，中国共产党从瑞金拉起这条红飘带，历经两年，行程两万五千里，最终将红飘带系在陕北吴起镇，继而延伸到延安。 而今，74年过去了，虽然', '2008-11-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDe80Hjuo_QlTQ8eKXkvQ-IFyO4z9lCPGaSAhfQHwxu-6dsleyQlxZ1vetKBZKCVeZEokqW5eaUb_mJ-KO881oyK6G_Nw_rBtBWcVLSXKxpKIe7TNoijIS9U_jGgApYB0hh6G1uoomqeQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3732, '报纸', '在历史与现实结合中领悟科学发展观真谛', '田义伟', '解放军报', '解放军报', '科学发展观;历史与现实;党的创新理论;省军区;', '本报讯特约记者田义伟报道：陕西省军区日前组织百余名师团干部赴革命圣地延安现地教学，借助红色资源深化党的创新理论学习，使各级领导干部在踏访革命遗址、追寻中国特色社会主义理论体系发展历程中，加深对科学发展观的理解，理清部队建设发展思路。  这个省军区', '2008-08-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDQn0hIUU2NfDYLuftttkP9dlGfH-YJIuKGQU1IUfCcUfS8qEzuVo_JIOWt1oBTqaGD0K1QzxPJ-mABmeGsBjBcKBs637OcJRR2F9s6RLTiwwa7moIIhithUaDe341rw82bQwC0GY233Q==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3733, '报纸', '激情燃烧的“追根”之旅', '秦宗仓; 聂世轩; 张金玉', '解放军报', '解放军报', '空军工程大学;', '初夏时节，陕北高原。在这片神圣的土地上，空军工程大学2200名博士、硕士生经受了一场前所未有的体能和精神的历练。为体悟黄陵的厚重，感受壶口的博大，传承延安的精神，他们翻山越岭、风雨兼程14昼夜，徒步行军上千里，开展现地教学11场。莘莘学子带着沉甸甸的收获返回校区', '2008-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBfFTTLD4fy3oiJGzKR8ouuBZq9pQvqzdGcpC9ApW6XV143YtcXBW00lKcOVw2oZmn4iI9pUUlLIaiHaOV5iFDaIZNzVZHv3vDGNN1tc8ca4Q563lqqGjC4gKE0heczY_NBkOVbC9h8Ow==&uniplatform=NZKPT&language=CHS', '枣园_screened,洛川会议_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3734, '报纸', '延安精神时刻激励着我们', '万学斌', '湖北省随州市委;政法委;公安局;', '人民公安报', '公安机关;中国特色社会主义事业;', '2008年4月，根据组织的选派，我来到革命圣地延安，参加了中央组织部在中国延安干部学院举办的第5期省区市地厅级领导干部“科学发展与和谐社会建设”专题研究班的学习和培训。学习期间，参观了延安革命纪念馆、凤凰山、杨家岭、枣园、宝塔山、南泥湾、王家坪、洛川、抗大纪念', '2008-06-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDIOhaszGlTNp9fpsViMoT3deeGfDfelV36zWP_UJopxMt3QVT7jJB9SxdAuoRXxFNZQ4bveQd4X5JXZvqGtEVXCKb3WItcrSRyx6X1TW4zmMEsYDJx1V_mKOPcOAJHKh6Qzy72NaoeXA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3735, '报纸', '弘扬延安精神 推动通信业发展', '', '中国电子报', '中国电子报', '延安精神;科学发展观;老一辈无产阶级革命家;', '根据信息产业部人事司的安排，我在中国延安干部学院参加了为期一周的干部培训，在开班仪式上，部领导要求我们通过理论学习，不断提高思想境界，适应时代要求；不断提高能力建设，树立良好作风，始终保持共产党员的先进性。我也抱着“饮水思源，回溯根本”的愿望聆听学院教授', '2007-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICHiqA7dQ--oLexG5CXa8WHRWgzlzHeOkqn880fZKXSQzH8XrN288Uy1XFxPDtRo7qIlkCrtrO_DNLKmkpdxxfBWujKNegs4HcbsP1kfF3_WHaOUuT2P4cjrGrhGe-cgm7-hqFH9lrbWQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,杨家岭_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3736, '报纸', '三万干部再当学生,激情点燃人生', '李柯勇; 刘书云; 季明; 周伟; 李亚杰', '新华每日电讯', '新华每日电讯', '浦东干部学院;延安干部学院;执政能力;井冈山;', '党的十六大以后，以胡锦涛同志为总书记的党中央作出了建设中国浦东、井冈山、延安三所干部学院的重大决策，目的是要建设一支能够担当重任、经得起风浪考验的高素质干部队伍，特别是培养造就大批善于治党治国治军的优秀领导人才。  自2005年3月正式招生以来，三所干', '2007-10-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICNnlmeqIzswaSyS5m1KQbPtvpTi_gmvfTMkuMIs9h_RngDwmeTRhc7k6YLnSwhQu3PqEeHf0iqvlEEdZ2OdK_Wj2q7wiAXisRto2oK4Tl2JCZdLHHssKDyzR1W0wyNwrn3U_Cwlc6Csw==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,杨家岭_screened,黄洋界_screened,张子清_screened');
INSERT INTO `ds_article` VALUES (3737, '报纸', '实事求是探新途', '盛若蔚', '人民日报', '人民日报', '教学点;教学主题;毛泽东;延安干部学院;', '那一排排敞开的窑洞，如同一排排思考的机器，而每个窑门上仿佛都刻着“实事求是”……1/3时间在课堂，2/3时间逡巡在革命旧址、社会实践现场，富有“魅力”的培训模式一再触碰学员那根敏感的心弦。①“旧址”触动心弦从枣园教学现场回到学员宿舍，中', '2007-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA7E9G6D0C9ISYm5XKqWMODLkFpLaVW2wyOVR3yxoqkQ1zOduskHRrrYwYymrJLvzv7TW4luH_aXU_aTIFTZpjZYcAS8-wdrfAVJ7zXztjJDV_cLyXnuHJd1r4k_YusPvESz3omRpW3ZA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3739, '报纸', '用延安精神推进作风建设', '尹健', '中国纪检监察报', '中国纪检监察报', '作风建设;党员领导干部;', '今年2月初，陕西省延安 市委作出决定，在全市党员领 导干部中开展为期一年的“筑 防线、保廉洁、树形象”作风 建设主题教育活动。近日，本 报记者就相关问题采访了陕西 省委常委、延安市委书记李 希。  记者：您是如何看待在延 安', '2007-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBrgQZCLPedAqL6YsDgagvakmHtv8vK1RqPpC0v64YcoiqNR-DuHGAhuH0lghviq7a6I0LnfNJEqomUWzQ1Ch-c_rSdxmDbzAZFAcUGt17xeR4ZZnrQkIYqRjsLAub_pgrQa_MXcUwc1Q==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3740, '报纸', '毛泽东《为人民服务》的演讲', '', '人民日报', '人民日报', '毛泽东;中央警卫团;《为人民服务》;', '《为人民服务》是毛泽东１９４４年９月８日在中共中央直属机关追悼中央警卫团战士张思德同志大会上所作的演讲。 张思德是四川仪陇县人，１９３３年参加红军，１９３７年入党。参加过长征，作战机智勇敢，曾多次负伤。１９３８年任中央军委警卫营通讯班长，１９４２', '2007-01-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDoXc5aoqNze2kII_PE-MjjP4tm8yQEAmetq-62spd_UDHeYYIuvgd7LJeDS52EQDZDc8tu5FJCpnDCr5TEAkygDuhENMmeyLBx0qm4Tb9J3CMRvUw3RHIgkAsmz0-TwA77rnvlPa2BTg==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3741, '报纸', '宝塔山下“播火者”', '魏春; 尉启君; 解学锋', '中国国防报', '中国国防报', '民兵连;延安革命纪念馆;延安精神;宝塔山;', '红军长征落脚陕北，延安成了中国革命的圣地。走进延安接受思想的洗礼，首先面对的就是她们：一个甜美的微笑，一段深情的讲述，一曲动人的赞歌……她们用这种特殊方式传承延安精神，在每个游客心中播下延安精神的火种，被誉为宝塔山下“播火者”。  她们就是延安革命', '2006-10-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICSppAfqzdxSdAAjfxpN0E7A_AoBMljW0diwoewPn1WFPqUaVFTRJHVoPPqziHJG8wC9_0rmSZLn-haNjxgunplEtKdhoPknAj0LTz6pYWxVKAHroKz5-v7eRiVi19sqZ-lPo6Dq4QRPQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3742, '报纸', '延安红色旅游之花正烂漫', '张陇堂', '中国旅游报', '中国旅游报', '延安市旅游局;周恩来;毛泽东;红色旅游;黄土地;', '本报讯（张陇堂）巍巍宝塔山，清清延 河水。延安曾经是毛泽东、周恩来等老一 辈革命家居住地，而今这里吸引了四方游 客前来探寻足迹，成为红色旅游烂漫之 地。近日，“穿越黄土地 红色延安行”志愿 者在经过4天的跋涉后，抵达延安，受到 了延', '2006-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBJp-h7wyVxHmiJeQUgQwYgLVHeUzUa7h76oeyRrQ1awvDeqLQfJZVZOqzKcBxIFohUDy__aMxcKys8H-qjE4SJ81GTzJChVtv_do3z-0U49iC-UCxMzGypvcnYMCUTP96wBuZnSVlghQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3743, '报纸', '高速通圣地 忠诚写新篇', '王科', '人民日报', '人民日报', '黄土高原;建设者;高墩大跨;陕西省;', '全国政协推进西部大开发专题协商会刚刚落幕，革命圣地延安就传来了振奋人心的好消息——黄延高速公路全线竣工了！  一头是人文始祖黄帝陵，一头是革命圣地延安，黄陵至延安高速公路，不仅引领延安老区向现代文明迅跑，而且写下了西部大开发的浓重一笔。 老', '2006-09-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICPQ8XW9e9TjlkuVetTbkPnJJkg8oLTNPyuuJ8yLlzP3w6DJIYKS8Ll7CnhIM-AMh_re0e3QrbUmlrxcGhZ6ntQsR54BTe8ztaT5ePMAPMfx90hXgoaEGpWPhR5gLLySp2KjTG09CTiSg==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3744, '报纸', '让红色旅游“动”起来', '魏晓霞', '中国旅游报', '中国旅游报', '红色旅游;延安保卫战;', '本报讯（记者 魏晓霞）9月8日，坐 落在延安枣园的延安保卫战红色经典旅 游区迎来了一批新的客人，他们要么头缠 羊肚毛巾，骑着小毛驴，或者身穿军装跃 马扬鞭……他们的身旁紧紧跟随着身背 摄像机的景区的工作人员。不一会儿，工 作人员就把由', '2006-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDmjR9bDLtUySiBYrwyjlZ2KHHM4D7wYWap8IziRxCdl_bY2lCOeAfbFpQgt0WDEUtRwJI1lJxSqkhIFm19W_nV39lhlXtJv3jBJ6z2FYIml7Zg9K9TYYVkqZeA2_iimx9ZqchKafz6kg==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3745, '报纸', '“三多三少”看变化', '孟宪江; 王胜颜; 张毅', '经济日报', '经济日报', '宝塔区;存栏量;南泥湾精神;王文忠;柳林镇;三多三少;', '在不少地方，特别是中西部欠发达地区，保护生态环境和发展地方经济被认为是不太好协调的一对矛盾：要么不发展保持原有的环境，要么发展快一点但要以牺牲生态环境为代价。本报采访组部分成员来到南泥湾精神的发祥地延安市宝塔区，想看看这里是如何解决这对矛盾的。', '2006-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB_e8wSP6-VsMNjdWkEwrdUsSTlfbth0KwERvDkTgG5bhDmEA2aLSYhukS2o9UTfkMO8d5P1002T-07klBBFBUz4FQqPfPL8hzCa8c6hKEfhbsbri4_eWuY-er6LJiHfCYWETqWv9hhgw==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3746, '报纸', '给我一小时 还你半世纪', '赵倩', '中国旅游报', '中国旅游报', '延安保卫战;红色旅游;旅游项目;', '4月28日，延安枣园村后坝梁显得异 常热闹，彩旗飘扬，鞭炮阵阵，人潮涌 动，引得全村老少纷纷走出家门，驻足观 看。投资1000万元、占地160亩的《延 安保卫战》红色经典旅游景区迎来了开业 庆典，而给人们更多悬念的大型实景戏剧 《梦回延安保卫', '2006-05-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICeti5zqzB8snftCp3LacTgHIvs2kJr5f_PMltPOuHNkxuwazD_eLcqMIfP-4LkT0P_yKMhLG_lpxpSQa5ak46cDQFG9ACsKskGYM_ilAiW1hzP6FRmdd0mDM13aubackF8Qfos0RRA4w==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3747, '报纸', '努力当好宣传文化战线的排头兵', '刘国顺; 曹慧民', '解放军报', '解放军报', '排头兵;文化战线;', '本报延安5月27日电　特约记者刘国顺、记者曹慧民报道：今晚，在著名的陕甘宁边区参议会礼堂——延安大礼堂，总政治部纪念红军长征胜利70周年慰问延安军民文艺演出高潮迭起，掌声不断。这是总政直属单位中青年专业技术骨干培训班的学员们，继26日后奉献的第二台精彩文艺节目。', '2006-05-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC7ExOxzX8Fvc9wDwUBzxgPbq5B5aXGLUIy9mnEBO7rgPpHrBsnvOWSJ0qgnngx1XF-epZ_SPQ0KO6p0cPCF9aOQcQ0HgYt20MfUfbu6ztiIJefpyH-aLjTfygBUNfU1dO3DbppRUFUxw==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3748, '报纸', '延安喜迎“科技雨”', '蒋建科', '人民日报', '人民日报', '枣园镇;科技部;', '“要种好大棚菜，首先要选好品种……”５月２０日，在陕西省延安市宝塔区枣园镇上砭沟村，中国农科院蔬菜所研究员王耀林站在蔬菜大棚前，正向来自十里八乡的农民们讲解大棚菜种植技术。忽然，下起了大雨，乡亲们赶紧把专家拉进了大棚。棚外，雨越下越大；棚内，农民们问这问', '2006-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAb7JPO7JsRV2QX9oI9AT2PEkpCMHIdiziwOPDxgd7I7E1OQmavNgAmLYNbWeUcjN8zVyFqBzAPljiBLVZNa2VNnvMdzZnPiGWSrCWxzP6PDM54-DoxuALIzmMtn6L-rbazlHfKGWVboA==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3749, '报纸', '利用红色资源深化教育效果', '刘明松; 夏洪青', '解放军报', '解放军报', '红色资源;教育效果;', '本报西安5月2日电　刘明松、记者夏洪青报道：连日来，第二炮兵工程学院组织千余名学员来到革命圣地延安，通过“红色课堂”深化荣辱观教育，强化了学员继承优良传统、献身国防的决心和信心。 该院党委在社会主义荣辱观教育活动中感到，驻地周围革命传统教育资源十分丰', '2006-05-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA3Jdw9871vWjVE-GOj-tS7DaXSkQZE3yCoiecTv1xjBNB95uLX7gW5MQhA_oH6rX9dRge-mNwSpm0ssCohCwIozxjJSauOpGbHmuM7SKQnGDVGvLv9kecuAc_zLzv97rKMiraLIy5P2Q==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3750, '报纸', '延安红色旅游打响创新战', '杨利娜; 韩丽', '中国旅游报', '中国旅游报', '延安保卫战;红色旅游;', 'T@@@圣地延安今年的春天比往年都来得要早一些，老区人民的 干劲也比往年更足，忙春耕、搞建设，红色旅游四处飘红，开春就 打响了第一炮。近日，记者抵达延安，耳闻目睹了延安旅游界做 强红色旅游的信心和干劲。@@@E  早春时节的延安，到处一派春意', '2006-03-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIChUa-Qc225RB9B72cZ_3dlKUyv9SbhFXl5zAofEXRH8_VaOPnQyl0bJj4dq5Ea6Zd9GAzjphFTg40JllHfLSqKLtPZ5YyiY0tOhOUqKktk1yNV0I0ieGYBPvpmRnxz9cFrbSFe35h0fA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3751, '报纸', '南汉宸：新中国金融业的拓荒人', '李文玲', '金融时报', '金融时报', '南汉宸;中国人民银行;杨虎城;中国金融业;', '历史总会记住那些重要的开拓者。南汉宸就是一位这样的人物，他在那战火纷飞的年代，筹备组建了中国人民银行，是中国人民银行首任行长。值南汉宸诞辰110周年之际，记者走访了南汉宸的后人及当年在他身边工作过的同志，试图打开他们心中尘封久远却又鲜活的记忆，走进这位传奇行', '2006-02-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDwbPfO5AEYloHG1jwjdwtfKFiNhmUyHn5ubAr8HJ5o2NF8gLnqH_hImGRlYOORpd4Nddc_DRfVqUy3QN9WVL82FgRrSjBAdrG5ZyS6XLBBIXouvk0phebAgu1ZVtDDHGMS9oCCsxlbhQ==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3753, '报纸', '诚挚的祝福　殷切的期望', '孙承斌', '新华社;', '光明日报', '胡锦涛;延安供电局;延安精神;', '革命圣地延安今年的春节格外热闹,到处张灯结彩、喜气洋洋。胡锦涛总书记同延安老区人民一起过年的消息传开后,当地广大干部群众一直沉浸在喜悦之中。从农历腊月二十八到大年初一,胡锦涛走乡村、看企业、进营房,慰问老区干部群众,考察经济社会发展情况。总书记牵挂老区人民,老', '2006-02-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDQatiJ8p4avz4pfRbjbJEhnf3hSmNei7P71vr8If2J2ju8ACKQhF3V2cDB-9Ru-wk2_Ixo8M4paNxkoKFZZfjGMnhLgNVfRoYDPn1vXr8eC_RgCfh3YdnRCin3Aokd54iW2azKZTg7iQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3754, '报纸', '延安精神新传人', '宫曦岭; 田义伟; 陈劲松', '光明日报', '光明日报', '延安精神;兰州军区;军分区;', '延安——中国革命的圣地。毛泽东等老一辈无产阶级革命家曾在这里培育了伟大的延安精神。建国后、特别是改革开放以来，又有许多共产党人在这里传承延安精神。延安军分区司令员薛庆云，就是其中一位杰出代表。  为百姓办实事  1993年4月，薛庆云来到延安。他沿着', '2005-12-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDJVuURvVwxX8pW115NqD8q96ovFBJTdlDZFHvd7LvitNnKRIgXGiQSEXBDGrSz-WSapTf2Sad5V6JkzETF4UTVYOaAoyDU5JdDzP7Ko3QsK8x8zlnqnTVgqxb8pZxS4Yd47H3_8c4TSQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (3755, '报纸', '一心为民践行宗旨', '刘玉书; 宫曦岭; 解学锋', '中国国防报', '中国国防报', '延安精神;民兵应急分队;军分区;小流域治理工程;', '为民与为名，一字之差，内容迥异；同为奋斗，境界不同。  延安军分区司令员薛庆云用共产党人的奉献精神诠释着为民的内涵与精髓；用满腔热诚践行党的宗旨，动真感情，与延安人民群众共渡难关；下真功夫，率领民兵预备役人员战天斗地，为经济发展建功立业。他不愧是“', '2005-12-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAqeZwZWoX1XwlfrLo4Qw8C8_vTPPwpUUvDq5UosQbOEIM1mmujQYMRJ12rk4XHi_GtRACY6majRSxQhMT_2wvXn2czEwWhp-8s7eyhgiK2d-KvWaDq42uH4z1xX7sBL80MyxdaDICBig==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3757, '报纸', '在社会实践中深化国情意识', '李海明; 朱振国', '光明日报', '光明日报', '国情意识;暑期社会实践;', '在T43火车上，一群年轻的学生吸引了众多旅客的目光，他们穿的白背心后面清晰印着两排蓝字：“胸怀祖国人民，奉献火热青春。”他们就是北京交通大学2005年暑期社会实践赴延安革命圣地社会实践团的大学生。  今年暑假，北京交通大学共组织了34支团队奔赴全国各地参加', '2005-08-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDhLEBPr8ZBpoRsJRwmZRlJv8527tQYtRI5vuwCpMKIR1TnSDq-8HToWeOf4RzNqEkgt82uznWy8HoP9irSgH6mrFADJsPb6f-PTLRhnhkfytPz0bXo9eSEtFp0LJwQeN9So1x5c6AyLQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3760, '报纸', '延安“红色旅游”开发与保护如何并举', '王科; 王乐文', '人民日报', '人民日报', '红色旅游;革命旧址;王家坪;开发与保护;', '宝塔山、延河水、南泥湾、枣园革命旧址……“五一”黄金周期间，全国保存最完整、面积最大的革命旧址群———革命圣地延安吸引了大批游客纷至沓来。据统计，延安共接待游客近68.5万人次，实现旅游综合收入3.07亿元，分别比去年同期增长20.98％和22.31％。截至目前，延安今年', '2005-05-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICRk5etYbHzGq4JU1s1hG3N_SLd8uAJzZuB46A5Y0m3gKKgoSmvsDFO-uHxawf8xVn6Q79W_aQkNL6sTO1TMvC80ZebYa7LEWHioG6tKRkjBiwhk7c1YjR1sVqCBBLDqlt3erpt8T3YHw==&uniplatform=NZKPT&language=CHS', '枣园_screened,洛川会议_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3761, '报纸', '让延安精神存于心见于行', '杨晨光', '中国教育报', '中国教育报', '延安干部学院;共产党;宝塔山;延安精神;', '巍巍宝塔山，铭记着中国共产党的光辉业绩；滚滚延河水，传承着中国共产党的优良传统。日前，五部委组织的高校哲学社会科学教学科研骨干研修班的100多名学员分成三组，分别前往上海浦东、井冈山和延安三个地方进行学习考察。记者跟随延安考察分队，与高校从事哲学社会科学教', '2005-04-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBUGsIKC7IcatREa18LulVLC-9ZGzUu_A_nUlcxxIbiAklfUvODZ5cWKuhElo2WW7b5ZvKCCkId_y1d67CIHZSa2NRSui_dpAWn2xAC_nvdWp6gr0CpQdUEHvkOetpniIzNzgsM2MP1Ag==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened,论持久战_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3762, '报纸', '你们就像当年的张思德', '杨敏; 石国恩', '中国电力报', '中国电力报', '张思德;供电所;宝塔区;', '当你走进陕西省延安市宝 塔区枣园供电所，可以看到墙 壁上“为民办事无小事”等醒目 的标语和图文并茂的安全用电 宣传画；院落里小，但路面干净 整洁，办公室窗明几净，工作人 员着装统一；营业厅内，便民长 椅、便民卡、投诉台、意见簿等', '2005-03-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAtl9L5D2KfgVWi1IPnISyRv4m7qBh2kHUs4m9eyBORvwFcA5V5EM-RuHbIS3cPHV_ARTTt8WzvYbG1cNnkRpw-J1Xf967UIIu6QPTrDOIuzloYmp7NhdUBn3Q8uI5spd3XW94yMAOmyg==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3763, '报纸', '延安成为先进性教育“活教材”', '刘洁', '中国纪检监察报', '中国纪检监察报', '先进性教育;革命旧址;', '本报讯：“到延安来看一 看，触摸我们党的奋斗历程， 就会觉得我们党确实坚强而 伟大。一处处革命旧址，就 是我们进行先进性教育的活 教材。”近日，在陕西省延安 市杨家岭七大会址前，来自 河南汤阴交通局的一名干部 在留言簿上写下了这段', '2005-03-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIApxWBocT7Dk4Ih-T6EItVT9sr0oNGFrXx_vD3l_r5AXzmnCTO9eE0rx_tG38z-Su4sxJ8CAjdgH3tYnU2ESC9PsjwL9CZuWm-N6aO-ZmgUfSv0xP0iENPg6S-cXRznSY3e3NW2NaWnBw==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3764, '报纸', '各地开展先进性教育活动', '', '中国气象报', '中国气象报', '先进性教育活动;共产党员;气象局;先锋模范作用;', '陕西延安 自先进性教育活动开展以来，延安市气象局充分发挥延安得天独厚的优势，采取灵活多样的方式，以延安“整风”精神和延安精神，引导促进先进性教育活动顺利开展。市局组织全体党员在枣园重温了毛泽东同志《为人民服务》的讲话和入党誓词；延安大学教授为全体党员干部作', '2005-03-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID9dCrtKpi6tRmOFPNvI3QzJXpXu6hBi8LfcCtXrgaTAQDJvi1XNPCZSrvqvz6Wge3rhKp5tawMbRNysBb_lGGxxqOojULEoeTDfh7TH13os4I8awcfzap8F8RVSultmet34S6CTsumvg==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3765, '报纸', '延安：精心打造陕北中心城市', '汪俊启; 吴秋红; 刘慧', '中国经济时报', '中国经济时报', '延安城;中心城市;', '■本报记者 汪俊启 吴秋红 刘慧 延安市位于陕西省北部，地处黄河中游。它是国务院首批公布的２４个历史文化名城之一，又是全国爱国主义教育、革命传统教育和延安精神教育的三大教育基地。历史上，延安一向是陕北地区的政治、经济、文化和军事中心，是中华民族的发祥地之一', '2004-12-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDmq_cp60_-HHiPxfCDmnTXErkap5dq_BKV2YHjq4oEheKlJWixOb3datJRQK0Jlb_EEt6SV8JBQ3vJrHzYzvI4CpSsQexniKcjlePo0kicOeDbt67ax5muy98ZlFMC3C_ha_E1h4jqzg==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3766, '报纸', '为人民服务 激情燃烧60年', '', '中国商报', '中国商报', '毛主席像章;共产党;留声机;延安《解放日报》;', '今年是毛泽东同志的《为人民服务》发表60周年。六十年前的9月5日，中央警卫团战士张思德在一次烧炭事故中牺牲，毛泽东主席在追悼会上发表了题为《为人民服务》的演讲。在那个激情燃烧的岁月，张思德的事迹体现了中国共产党与人民大众的血肉联系。60年来，人们惊奇地发现，毛', '2004-11-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDeR6yEI4fBQXgcMLbzk_0aeZ3UoPH6V1XwBg40-8sEmpOMrI1Alh5qCO6y3IYgf_pnIB08AIgQPApo-lIscAsBFPK2E2aU1dz4p-0W62KUM0xf3dTJHMENzFKGYipi6cYTdnepW2mh4Q==&uniplatform=NZKPT&language=CHS', '枣园_screened,中共七大1_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (3767, '报纸', '红色旅游持续升温', '', '中国旅游报', '中国旅游报', '红色旅游;延安革命纪念馆;', '百色成为缅怀伟人热土  本报讯(广西记者站 孟萍)今年是邓小平诞辰100周年和百色起义75周年，百色吸引了社会各界关注的目光。百色市的经典旅游线路“邓小平足迹之旅”也持续升温，成为广西今夏旅游的一大亮点。  据百色市旅游局介绍，今年是邓小平同志诞辰100周年，', '2004-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAmJW7jaRStxzOw1j4htno8DJR_RUqC2iNd_YTa_ZnmI3p3tJc33zcb4CpOCUWnIECMi5WAQLVu53f22du2kkJeVHh3q40G-f1rtITophrCjMwp12-PMjqgG5705R2S-VvzgO1fWCEHGw==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3769, '报纸', '“红色之旅”红透延安', '王晓民', '陕西记者站;', '中国旅游报', '延安;陕西;旅游;', '本报讯（陕西记者站 王晓 民）秋雨中的延安国庆期间旅游 热潮不减，延安革命纪念馆、枣 园、杨家岭、宝塔山、清凉山成为 黄金周期间各地游客竞相参观的 热点。  延安是中国革命的圣地， 毛泽东等老一辈无产阶级革命 家在这里奋', '2003-10-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDyUAoekTr3Xyyu9n8I87ldmpT4SaIDvPyGsYG6PiEte_O-i6xo0XYusil6r6fbvUJwAPGNaTsxpoml9aUQzg-yzDe4Sn3TdDiGECX84AWYfEImBZB4XRMIbNMw9-_VwEjYw1rZ4IQnAA==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3772, '报纸', '延安革命旧址保护有新举措', '郑少忠', '人民日报', '人民日报', '延安革命旧址;陕西省;', '本报西安10月7日电　记者郑少忠报道：由中央有关部门出资350万元修建的延安新闻纪念馆正在紧锣密鼓地建设中，这是陕西省和延安市积极探索由中央各部委出资，实行对口保护延安革命旧址的文物保护新方式。 党中央设在延安的13年间留下了大量革命旧址。据不完全统计，', '2002-10-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBsuiR6x3Lcx2mT-bWMKH51lB_qf-TFZRfHauucrTIqI3hTjZCWdgV-_C31FCDVxVf41Arook5I5RxRHe3JTii91q_5uL8z8KgA2PrOKbw_SQbEqHD16zqB4H0VydMKa84VXrfraroMDw==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3773, '报纸', '延安精神永远不能丢', '菊文', '中国质量报', '中国质量报', '延安精神;技术监督局;李长江;江泽民同志;', '本报讯（菊文）7月18日至19日，国家质检总局局长李长江在延安考查质量技术监督工作。他强调，进入新世纪，党和人民赋予质量监督检验检疫部门更加重要的职责和任务，我们要做到“忠于职守、勇于负责、严格把关、保国安民”，就必须全面继承和大力弘扬延安精神，继续艰苦奋斗，', '2002-07-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDjrmJTO22FGY6-SS-9lwkuEerj546UsXX3a3qlbgYyU9YERSAqnrqVZSXRXMvYxR_6OZduWDU6QrmabVdByqgYx2-k33J5Xs_ftSYhx9PMh1ZJoQSa8q7U41z4Nnt4n9uyg_Ua1xDhsw==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3775, '报纸', '让先进文化的旗帜高高飘扬', '李舫', '人民日报', '人民日报', '海政歌舞团;毛泽东文艺思想;文艺工作者;中国革命博物馆;先进文化;电视艺术中心;', '大型展览《毛泽东与文艺》自5月20日开幕以来，仅一个星期，参观者已达3万人次，其中不少人“意犹未尽”，数次走进了中国革命博物馆展览大厅。 在展厅中，记者遇到了著名诗人臧克家的夫人郑曼。臧老现已97岁高龄，同毛泽东相交甚多，毛泽东的一些诗词曾听取过老诗人的', '2002-05-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAQ_t4_GNxvpvOW6BMj6s-S01W3-ESif4FGTfRA8lFsWrS9QwJD43e8P21dS_jGxzz5ao9UW5OAaIlBBbUhPzPiF1FdlDLeS43KAZXOYN9AvNcvygyrMaZddRTCexa9hm5TSHDatmOseA==&uniplatform=NZKPT&language=CHS', '枣园_screened,枣园_screened');
INSERT INTO `ds_article` VALUES (3777, '报纸', '李鹏参观大型展览《毛泽东与文艺》', '丁伟', '人民日报', '人民日报', '大型展览;《毛泽东与文艺》;毛泽东文艺思想;', '本报北京五月二十四日讯 记者丁伟报道：中共中央政治局常委、全国人大常委会委员长李鹏今天来到中国革命博物馆，观看了正在这里举办的大型展览《毛泽东与文艺》。 展览大厅里，一幅幅历史图片，一件件珍贵的实物，展示了毛泽东从五四时期到二十世纪七十年代重要的文', '2002-05-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID-JKFvsy3AOXe2JxmrP2j45u8GTk-5Gmjn8vmr9QxnZXZB8cZpC9gx_0i89IDiun9dWjMVfpiPfmqe-OBTB8lN02jfTN9Qp1Ncn1u0-u17XPVaVbB_OnUNNRWyO64fqfPrLPtnCsAOlA==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3778, '报纸', '灯塔照亮文艺航程', '秦杰; 曲志红; 沈路涛', '新华每日电讯', '新华每日电讯', '《讲话》精神;文艺发展;文艺工作者;', '1942年5月 23日，延安杨家岭， 在三根木棍悬起的汽灯下，毛泽东面 对百余名文艺工作者，发表了一个气势 磅礴的《讲话》，引发了“五四”之后中国 文艺发展史上的一次革命。60年来，在 毛泽东《', '2002-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDdJbeT17DI_37PVFfL8lhQzWaG19u3cxyKBUGQheRByex93ey6wEdDcTBmYWiKqd7grgm6UAKZtHnUXwHwDqP7dqgnydxGitEotjVkjmG05gCTfaoboZaKLRkxDjvZiHkNPLecQJvqlw==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3780, '报纸', '寻访红色圣地——枣园', '江彦博; 马金平', '农民日报', '农民日报', '枣园村;延安城;人均收入;', '延安是一个时代，是一种精神，更是一面旗帜。  在这片神奇的土地上，有着许多美丽的传说。相传雍贵的天国牡丹在这里落地生根，百鸟大王金凤凰在这里生息鸣唱。在这块人类文明最早的发祥地上，因为有了轩辕皇帝南征北战振兴华夏的火光，有了大禹历经艰辛凿石开山疏导', '2001-06-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICYp8VRAs-1joMntBDbgv7Tg2NFt2JHbhkVfYhq01SHqQ94ffdTXuDxr4eMgIuoc1fQ2Hid3nMHgbnQbR5J2_buSF7EIGIAhIq67sttfzsgkcUgC9-hZXAq1-SliYEnQY4oyoGifljeYQ==&uniplatform=NZKPT&language=CHS', '枣园_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (3781, '报纸', '用延安精神决战“两改一同价”', '黄源; 鹿飞; 杨敏', '中国电力报', '中国电力报', '两改一同价;陕西省电力公司;延安精神;', '本报讯：6月10日，国家 电力公司“两改一同价”先进事 迹报告团在陕西延安进行了最 后一场报告会。来自陕西铜 川、延安、榆林地区的电力职工 和地方政府代表以及农村用电 户代表共700多人出席了报告', '2001-06-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICp9UU5f52Dm-Vcv8NfdHYarFIsqsN26-c5cbVSkm4poI93eRZX_nYiZo11Oo2VIWFv0JUZU6oGlYO3aqrsavee21n4ak1CQQagwpj8Db-6gn7eHwchL_T6GHw14aGts15smoPF_A4A7w==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3782, '报纸', '延安四百革命旧址讲述英雄故事', '刘苏维', '中国国防报', '中国国防报', '革命旧址;国防教育;', '本报讯：特约通讯员刘苏维报 道：延安曾经是中国革命的圣地。当 年数以万计的热血青年冲破国民党的 重重封锁，来到这里寻求救国的真 理。今天，延安的国防教育宣讲团的 小分队奔赴全国各地，忆峥嵘岁月、颂 延', '2000-12-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLsyQ2sRQH1RTeBm3GmuHPL-rlClCw9RnTn6iBY4qGBhU9PTsRpxfW7CTC9aYPb2sc1xfVH8Vkov1e6fz5C38IPf4_R6eAP3TuXnnV1I_sZDyuoruFnTjCnsdGOVP2__q6sZHVbOJZXw==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3783, '报纸', '面向新世纪的“素质教育工程”', '徐生; 陈京; 卫转业; 郭凯', '光明日报', '光明日报', '电讯工程;空军工程大学;宝塔山;素质教育;', '巍巍宝塔山，清清延河 水。金秋9月，革命圣地延 安，迎来了空军工程大学 1300名新学员。他们带着“如何弘扬延安精神， 立志献身国防”的课题，在学校领导的带领下， 走枣园，进窑洞，登宝塔山，下延河边，参观博物 馆，祭扫烈士陵园，感受革命', '2000-11-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA8nMATp3SYNxYB9UQj6D6b1AU-KBVh0qAG63wiz2Qiz4bm7AK7R1cGUtrxgqhNnzMG-vWibT4Y_havvE_mW6VnMdPUeIwXJKhP-9Y9C-WL0Gn6PJ6d6lgiqRBlJbbio_OLF8MrOoSrXA==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3784, '报纸', '面向新世纪的素质教育', '', '解放军报', '解放军报', '电讯工程;空军工程大学;毕业学员;素质教育;名师工程;教员队伍;宝塔山;', '巍巍宝塔山，清清延河水。艳阳高照的9月，革命圣地延 安，迎来了空军工程大学今年入校的1300名新学员。他们带着 “如何弘扬延安精神，立志献身国防”的课题，在学校领导的带 领下，走枣园，进窑洞，登宝塔山，下延河边，参观博物馆，祭扫', '2000-11-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIATNbeF34RSNkHzIG4SVJSPVr2iIVA8uUfiCokihJcSycQ_3ZyTmcayTh35e1fLAW1prZWfDZRqL8EuMygShSw8XtlmUGIIZPHNAX2Z01b53o5JkMTRFjodHsd8OeXw2vOCbwoM7k1QbQ==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3785, '报纸', '“我们的目标是帮助他们脱贫”', '王梅', '中国质量报', '中国质量报', '大垄沟;', '到了延安就想起了枣园，想起 了杨家岭，想起了延河水与宝塔 山。  到了延安就想起了白羊肚手 巾，想起了粗犷的腰鼓，想起了嘹 亮的信天游。  除了上面人人皆知的，到了延 安，你还该想起什', '2000-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB1WD53KHiWkJybHe0bARko4Gf-ewePB2rixJA-f5zguzcfeBOlucp4p6sakcpXwkflG7g9o1jJlX6JVAyZQ3fBHTEH2P96qjwx06_YoX6hzfjPQrc2LUtJizEj3B52vR_tvbl4tXbp7g==&uniplatform=NZKPT&language=CHS', '枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (3786, '报纸', '延安精神绿家园', '杨尧鑫; 石建华', '中国纪检监察报', '中国纪检监察报', '延安精神;枣园乡;', '巍巍宝塔山，滚滚延河 水。当我们踏上这片黄土，面 对那些充满传奇色彩的窑洞， 一股前所未有的神圣感涌上 心头。在延安采访，我们从一 个个感人的故事中真切地体 会到，延安精', '2000-06-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDPqx2sx9LzWf33DiO5ZVwum11eHC9KRy-1GUrT5KiUWgsj9sSx5x--TIBx8EPf5yL6t0p6EzLK0tm8E2KAQAH5u6bFZlZNHIsLYmDRAVPRlmBr3he408fNTUY_zq91fnaD8a3qOteEDw==&uniplatform=NZKPT&language=CHS', '枣园_screened');
INSERT INTO `ds_article` VALUES (3787, '报纸', '在感悟家国情怀中寻找“诗与远方”', '单慧粉; 郭冬明; 董浩田', '解放军报', '解放军报', '红色旅游;八路军总部;古田会议会址;红色文化;旅游新业态;家国情怀;', '5月1日，陕西省延安革命纪念馆展厅内，人头攒动。 “我们从福建来，一共60人。” “我们一行25人，需要讲解服务，请问还要等多长时间？” “今天上午已登记了40多批讲解服务，解说员都在忙，还需要您再耐心等待一下。”在讲解联系处，解说员白婷婷为游客预约登记，忙碌不', '2023-05-17 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2023.002109', '百团大战_screened,遵义会议_screened,血战湘江_screened');
INSERT INTO `ds_article` VALUES (3788, '报纸', '传承“攻坚精神”，这个旅聚焦打赢立新功', '高骏峰; 李政; 张强', '科技日报', '科技日报', '实战化训练;革命先辈;英雄连;田家会;', '我旅的“攻坚精神”是革命先辈留下的宝贵财富，需要我们用实际行动来践行传承。 ——刘华勇 第71集团军某旅“勇猛果敢突击营”营长 3公里武装越野刚结束，理论考核马上进行；400米障碍一考完，手榴弹投掷随即展开…… 春节刚过，第71集团军某旅侦察营“学习报告励斗志、创', '2023-02-17 08:00:00', 'https://link.cnki.net/doi/10.28502/n.cnki.nkjrb.2023.000852', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3789, '报纸', '“天堑神兵”的成长足迹', '刘小花', '解放军报', '解放军报', '工兵连;中国工农红军学校;中央红军;成长足迹;人民军队;工兵营;中革军委;', '工兵，素来享有“天堑神兵”的美誉。行军途中，他们是开路先锋，勘察地形、搭桥铺路、排雷清障；攻城克坚时，他们是钢铁勇士，挖坑道、埋炸药，轰开坚固的城墙。作为军事技术兵种，工兵在战争中发挥着无可替代的作用。那么，人民军队的工兵在成长壮大初期，经历了怎样的发展', '2022-12-25 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.006682', '百团大战_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (3790, '报纸', '“连心碾”见证鱼水情 红土地焕发新生机', '姜军旗', '中国妇女报;', '中国妇女报', '红色旅游;武乡县;红土地;全域旅游;讲解员;八路军总部;', '一幅幅抗战题材版画、一座座八路军主题雕塑，一面面“红色武乡”宣传标语……近日，中国妇女报全媒体记者一行人来到山西省长治市武乡县，浓郁的红色文化氛围扑面而来。 “山山埋忠骨、岭岭皆丰碑，村村住过八路军、户户出过子弟兵”。武乡县被誉为“八路军的故乡，子弟兵的', '2022-08-16 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2022.002518', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3791, '报纸', '依托生态优势 推进绿色发展', '乔栋; 张腾扬; 王者', '人民日报', '人民日报', '太行山;革命老区;八路军太行纪念馆;土地综合整治;', '“北上太行山，艰哉何巍巍!”东北—西南走向、纵贯800余里的太行山脉，是我国重要的地理分界线。晋冀鲁豫根据地、晋察冀根据地、西柏坡、百团大战、大寨、红旗渠……一个个耳熟能详的名词与这里息息相关。 2009年5月，习近平同志在瞻仰八路军太行纪念馆时强调，要结合新的实', '2022-06-07 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.005950', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3793, '报纸', '“金色鱼钩”映照金色人生', '单慧粉; 叶冰斌', '解放军报', '解放军报', '王玉清;红军战士;福州军区;长征路上;', '在许多人的成长记忆中，一篇题为《金色的鱼钩》的课文，让我们认识了红军在长征路上的艰辛和战友情—— 茫茫草地中，红军战士断炊多日，一位炊事班老班长为照顾3名生病的战友，把缝衣针弯成鱼钩，钓鱼、煮鱼汤给他们吃，自己却舍不得吃一口。最终，老班长倒在草地上。 忍饥', '2022-06-04 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.002884', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3796, '报纸', '延安精神——宝塔光辉 映照未来', '', '中国民族报', '中国民族报', '延安精神;毛泽东思想;中国共产党;', '延安，中国革命的圣地。1935年到1948年，这片红色热土成为中共中央所在地。 “几回回梦里回延安，双手搂定宝塔山。”13年峥嵘岁月，中国共产党由小到大、由弱到强，从低谷走向高峰，最终扭转了中国的乾坤。任时光荏苒、岁月变迁，延安始终是中国共产党人魂牵梦绕的精神家', '2021-12-10 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001276', '百团大战_screened,枣园_screened,洛川会议_screened,中共七大1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3797, '报纸', '用主旋律电影勾勒时代风貌', '臧花', '武汉大学艺术学院;', '人民日报', '社会主义;时代风貌;', '最近，主旋律电影《长津湖》票房登顶中国影史票房冠军，引发热议。主旋律电影是展现时代风貌、传播主流价值的文化窗口，也是人民群众喜闻乐见的文化产品。许多主旋律电影反映重大历史时刻，刻画英雄人物形象，歌颂感人事迹和伟大精神，成为弘扬社会主义核心价值观、厚植爱党', '2021-12-02 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.012659', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3798, '报纸', '太行精神、吕梁精神凝聚奋进力量', '李红光', '经济日报', '经济日报', '太行精神;八路军太行纪念馆;', '巍巍太行，莽莽吕梁。这里代代相传的红色血脉，传颂着数不胜数的动人故事；这里孕育了光耀千秋的太行精神、吕梁精神。回望烽火连天的岁月，在历史中追寻红色基因，从宝贵的精神财富中汲取接续奋斗的强大力量。 烽火岁月铸精神 1937年“卢沟桥事变”后，日本侵略者发动全面', '2021-11-04 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.008932', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3800, '报纸', '太行精神、吕梁精神是我们党宝贵的精神财富', '', '人民日报', '人民日报', '太行精神;精神财富;', '巍巍太行、绵绵吕梁，忠魂永在、浩气长存。抗日战争时期，在中华民族危亡关头，中国共产党领导八路军和太行、吕梁儿女，前赴后继、浴血奋战，谱写了抗击日本侵略者的英雄篇章，培育和造就了太行精神、吕梁精神。2020年5月，习近平总书记在山西考察时强调：“山西也是具有光荣', '2021-11-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011453', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3802, '报纸', '孙立新：心中有英雄，笔下有烽火', '于园媛', '光明日报', '光明日报', '孔繁森;', '一面是军人的庄严稳健，一面是艺术家的诗意格调，两种不同的特质交织在他身上，让其作品同时具有宏大辽阔的品格和人文关切的色彩。他的作品连续入选第七、八、九、十、十一届全国美展及多个国家重大美术工程，但面对新的创作，他依然保持敬畏之心，总希望“每件作品都能有一', '2021-10-06 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005042', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3807, '报纸', '战地家书激励强军斗志', '史建民; 贾国梁; 黄宗兴', '解放军报', '解放军报', '家书;强军;官兵;驻训;', '夏日，正在喀喇昆仑驻训的新疆军区某团营区内，一堂党史学习教育课火热开讲。 “以进步来安慰自己，以进步来酬报别后衷情……”台上，主讲人、该团四连指导员向虹霖，深情朗诵左权将军牺牲前写给妻子刘志兰的家书。台下，不少官兵眼中噙满感动的泪水。 “这封家书的写', '2021-08-06 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.005047', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3810, '报纸', '延安精神永放光芒', '黄庆畅; 龚仕建; 张璁', '人民日报', '人民日报', '延安精神;精神财富;共产党人;习近平总书记;毛泽东思想;', '延安精神培育了一代代中国共产党人，是我们党的宝贵精神财富。要坚持不懈用延安精神教育广大党员、干部，用以滋养初心、淬炼灵魂，从中汲取信仰的力量、查找党性的差距、校准前进的方向。 ——摘自2020年4月习近平总书记在陕西考察时的讲话 延安，中国革命的圣地。', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.008079', '百团大战_screened,枣园_screened,洛川会议_screened,中共七大1_screened,中共七大1_screened,杨家岭_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (3811, '报纸', '“军歌之父”郑律成', '李军', '学习时报', '学习时报', '郑律成;共产党;音乐作品;八路军;中国人民解放军军歌;《八路军进行曲》;朝鲜人民军;《中国人民解放军进行曲》;朝鲜半岛;丁雪松;音乐创作;中国人民志愿军;', '郑律成是中国共产党党员，是延安时期和新中国成立后创作大量音乐作品的著名作曲家，是《中国人民解放军进行曲》的曲作者。郑律成也曾是朝鲜劳动党党员，是《朝鲜人民军进行曲》的曲作者。对此，中国音乐评论家和作曲家唐诃评价道：“两个国家的两首军队进行曲，均出自一位作', '2021-08-02 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001391', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3814, '报纸', '身先士卒范子侠', '李玘; 李红光', '百团大战纪念馆;', '经济日报', '范子侠;百团大战;正太铁路;讲解员;', '在百团大战纪念馆一号展厅的墙上，刻着这样的一段话：“我前进，你们跟着我；我停止，你们推动我；我后退，你们枪毙我。”这是抗日名将范子侠经常同部下讲的铮铮誓言。百团大战期间，范子侠任八路军第一二九师新编第十旅旅长，负责正太铁路阳泉至寿阳段的破袭任务，他身先士', '2021-02-18 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.001614', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3815, '报纸', '讲好新时代强军故事', '刘光明; 王强', '国防大学习近平新时代中国特色社会主义思想研究中心;', '解放军报', '中国梦;政治建军;强军之路;人民军队;强军目标;', '火热时节，铁血“八一”。在这个特殊的节日里，凝望八一军旗，如巨幅画卷般的军史故事扑面而来。南昌起义、古田会议、万里长征、百团大战、三大战役、抗美援朝……一幕幕雄壮活剧，述说着曾经的荣光，激扬着英雄的豪迈，启迪着未来的遐想。 一个时代有一个时代的故事。故', '2020-07-31 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2020.004062', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3818, '报纸', '电视剧《彭德怀元帅》：彰显信仰之美 凝聚中国力量', '', '光明日报', '光明日报', '中央电视台;彭德怀元帅;《彭德怀元帅》;重大革命历史题材;', '编者按 庆祝中国共产党成立95周年的重点电视剧《彭德怀元帅》5月20日在中央电视台一套黄金时段首播，引起了全社会的热烈反响和观众的强烈共鸣。为总结这一重大革命历史题材创作的新收获，指导今后电视剧的创作生产，近日由中宣部文艺局、国家新闻出版广电总局电视剧司主', '2016-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC2Q48lKvrDH50xh0U-KsYeyZonvIO8CfMf0kWmAGaQf3HE4sSOWk8sk9bA-lZiFFQP8mqI0fbI7JfRVLXZDE3dybnWjYVo-No3DEMoN8MSETMhhdtBAUmiZEdCfkRRMwIvFG4S2VRAnw==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3819, '报纸', '抗战时期武乡新闻史述略', '邓涛; 孙发明', '团结报', '团结报', '抗日根据地;《新华日报》;抗战时期;', '山西武乡地处太行山腹地，群峰壁立、地势险要，一向为兵家必争之战略要地。抗日战争时期，八路军总部以太行山为依托，率领和指挥三师（一二九师、一二○师、一一五师）主力，开创、巩固、发展了华北敌后抗日根据地，胜利实现抗日军事战略的转变，红色武乡被誉为“抗战圣地”', '2015-11-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDTASyvUx8BGZsDebtLMjYIHtuEAqBGdZFurxIwzJRp6sldHzA9-K5NG9ohoAAFA-LOsr6SGcbVL_WBEhzGEogz3aHyzTY7e7e23mztaHLV4lHUcOHKVXk9vELpvnzYqa_wnKJF3uFQhw==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3820, '报纸', '战地摄影群体掀《巨浪》', '杨雯', '中国新闻出版广电报', '中国新闻出版广电报', '原型人物;《巨浪》;罗伯特·卡帕;', '10月16日，44集红色青春献礼剧《巨浪》登陆北京卫视红星剧场。该剧以一代青年学生在历史洪流中的成长蜕变为故事主线，讲述了上世纪三四十年代，北平进步青年吴鸿运（张博饰）、高海薇（韩雪饰）、宋玉泉（印小天饰）等人接受革命洗礼，投身抗战洪流，来到晋察冀根据地组建抗', '2015-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA1fzWDDbvP7b9WScmODaUuwK3HizCtuB1IMnRniP8OfJwdnK-w13ZOZfeQiB1gnnP2DTu1_oG7c1fzjx7knj-xNQcG8iCTdvRN8dIfleGAiTnBkO74Y-4yJHX-NzWL2qfYa0H5B6W1UA==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3822, '报纸', '从历史中汲取智慧和力量', '董文先', '中国国防报', '中国国防报', '军队武器装备;国防观念;战争形态;抗日战争;武装力量;世界反法西斯战争;', '习近平强调，我们纪念中国人民抗日战争暨世界反法西斯战争胜利70周年，就是要铭记历史、缅怀先烈、珍爱和平、开创未来。为了和平，中国将始终坚持走和平发展道路，坚决捍卫中国人民抗日战争和世界反法西斯战争胜利成果，努力为人类作出新的更大的贡献。让我们共同铭记历史所', '2015-09-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAY1bfDcGOfuS8r6swa0qyX58wrcXWkYA77vFRSyOpT8kOMPibjRfhE5c-vvszETu16gntgO4pRpNZK9ma3M8j328EIvFL7CcbegTBFOJGfzEAXLuSrW9DMFyxH1bm0xpWFLatpZGmgkg==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3825, '报纸', '山西在抗日战争中的重大贡献', '', '中共山西省委宣传部;', '人民日报', '敌后根据地;八路军总部;抗战期间;抗日战争;抗日根据地;抗日民族统一战线;重大贡献;', '“太行浩气传千古，留得清漳吐血花。”在伟大的抗日战争中，中国共产党领导的八路军和山西人民，在山西这片古老而厚重的热土上，同穷凶极恶的日本侵略者展开了英勇顽强、坚韧不屈的斗争，创造性地建立了抗日民主根据地，承载起全民族抗战的希望，支撑了中国敌后抗战的战略全', '2015-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBoj-mdUV5YGl8xTnWmBO7bpSJYw8eZMD6wMnad5T2ztRj-RsrwTTkbg9xr_n8BVZ_hN-JR044ciY6ybJPFfBJc0rz29sIoyvtsdtsJ9fsn_7fK-nIT4JtBGzuIadfAzaOd_G5rhAMHwA==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3828, '报纸', '让不屈的民族血性燃烧起来', '任姗姗', '人民日报', '人民日报', '百团大战;战争片;张自忠;《红高粱》;世界反法西斯战争;正太铁路;八路军总部;宁海强;彭德怀;新中国成立;国民党;攻坚战;', '1940年，世界反法西斯战争进入最艰难时期。 欧洲战局急转直下。纳粹德国闪击波兰后，连下荷兰、比利时和卢森堡、挪威。法国宣布投降，希特勒在凯旋门前阅兵，叫嚣将实施“海狮行动”，进攻英国。 东方主战场腹背受敌。日本威胁英法封锁中缅、中越国际交通线。枣宜', '2015-08-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICZrwF38_b7pxoS72mYLkyh46fYOyezyW50hVhpz6Naj7dfNN5StE1CW1FY2VowVyckOf-Of_iICEaU7UIPtPOrh-1PwLYpMsudBb2xoyzS1pShJjwXKIoj5hik3MwzOH0OlkUMc-faXw==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3830, '报纸', '反法西斯新片：开拓新角度 体现新追求', '苗春 ; 张东', '八一电影制片厂研究室;', '人民日报海外版', '战争片;百团大战;反法西斯;《开罗宣言》;主旋律电影;商业片;', '记者：为纪念中国人民抗日战争暨世界反法西斯战争胜利70周年，国家新闻出版广电总局确定的10部新拍电影中有5部已经拍摄完毕，这些影片的基本情况是怎样的？ 张东：这5部电影中，有一部是由山东省委宣传部等单位拍摄、聚焦冀鲁豫根据地人民为抗战胜利做出巨大贡献的大型', '2015-08-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDmfQn2Gut6Wo8y8O-GmGTuA2mW2CJSFT3PN2I86C-mR_kyjNC3DTzg86sxoLWO00oGp9pMLKGj351_ek4NOdoq49nJhsg9TNVlbSqZkS4g7j2Wz2wFKdaIrJ9ELXipEvhIqtKWnuGn0Q==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3833, '报纸', '从这里，迈向伟大的抗战征程', '罗容海', '光明日报', '光明日报', '卢沟桥事变;佟麟阁;', '北京，从崇元观到南太平桥，这段古老而狭长的南北通道，近七十年来，被称作赵登禹路。这条以民族英雄命名的道路，与佟麟阁路、张自忠路一起，成为首都北京仅有的三条以英雄名字命名的道路。抗战到底、为国捐躯的抗日英雄，世世代代受到人们景仰。  1933年，日军以伪', '2015-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIArzWag8M0pVp1v6cCCamASVAVb5FSxZ7sN12Prep_o4vB_64NXHUn-ptPwl8RLOZqw35KU624ExA6FYWcBU0HHnhnw9Q9iOEpCJ6dB0l1Jp8HmuK9JRdHmCvqb2AgbSBDQxI2rr5y-Xg==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3840, '报纸', '重大历史题材油画创作座谈会发言选登', '', '中国文化报', '中国文化报', '油画创作;历史题材;历史画;座谈会;', '编者按 为搞好“纪念中国人民抗日战争暨世界反法西斯战争胜利70周年全国美术作品展”油画创作活动，中共中央党史研究室科研部、中共党史学会、中国现代史学会、中共党史题材美术研究专业委员会在京举办了“重大历史题材油画创作座谈会”。中共中央党史研究室副主任张树', '2013-03-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAfLn2wsa-bRvGxWHpzvhejHh60unBBa8X2vsfbcSmwGlMPtE4ejA0OLEmCAiU5Lvh3gT5Ilrdwmb07iO1KXjZW0dYnj52hGJ0h283tfK1Y3ArYTBTkSKfxS4AUAL0c_olWLF6NxaZPvw==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3842, '报纸', '抗日名将左权', '', '人民日报', '人民日报', '黄埔军校;八路军总部;国民党军;', '左权，１９０５年３月１５日生于湖南醴陵一个农民家庭。中学时代参加中共领导的社会科学研究社，开始接触马克思主义。１９２４年入黄埔军校第１期学习，是“青年军人联合会”负责人之一。１９２５年２月加入中国共产党。后在黄埔军校教导团任排长、连长，参加讨伐军阀陈炯明', '2011-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICTzsAyqvlRquA5es6oBICyk9a_P3a_ZKlzGhtqO2GW_NsUhh2KFaGNaiG7HeUI9VG_tYO7tNlbzzMXitnQrWPPiVmrXOyF4NKlgNySBFrbisq0u6mkHiMmRFmQSINpZgk43qsGRCNhtw==&uniplatform=NZKPT&language=CHS', '百团大战_screened,强渡大渡河_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (3843, '报纸', '侯波:见证开国大典的女摄影师', '方瑾 ; 陈小波', '新华每日电讯', '新华每日电讯', '新华社;开国大典;徐肖冰;女摄影师;', '新华社北京5月31日电(记者方瑾　陈小波)侯波记忆中,最刻骨铭心的是参加开国大典活动。1949年10月1日那天,她在天安门城楼拍下毛泽东主席宣告中华人民共和国中央人民政府成立那激动人心画面,见证了这个伟大历史时刻。 13岁参加革命、14岁加入共产党、亲历开国大典、国', '2011-06-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBW5AkxV3sbfh-MSeshd3KnVG49qvH6HzDYgVBYtNScO9QazsO_0Nvbzl0AyG_Al_Np-7wO8DhAiEfSsj8FNmlQa-ywRtZWYdWrpYomNxdsN_w4jL44jAsEAH3WO65E-_J2jGLvGilKCQ==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3848, '报纸', '让红色基因融入血脉', '杨仁福 ; 邓忠开 ; 林贵鹏', '解放军报', '解放军报', '集团军;红色基因;“六个一”;', '成都军区某集团军组建70多年来，有百团大战、淮海战役等辉煌战史，有抗洪抢险、抗击雨雪冰冻灾害等宝贵经历。该集团军坚持以“六个一”学军史、用军史活动为载体，培育当代革命军人核心价值观，有力促进了部队全面建设。 光荣历史怎能忘却 2006年初，该集团军组织', '2011-01-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDCFK-eqAsKHb2x37rvPnDq-xja9WFo989NcjTLxgM-TR9jBzvjIGaQxTQskoEnmmsn8DCWOaZyOYawzqMQWGoHIZ7jLM_WoQ5rQccufwaa_btdpXU98oStgE2dF-xOMlZVZURZkX5luw==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3851, '报纸', '抗敌决死队：铸就英雄部队的精神符号', '林贵鹏 ; 邓忠开', '解放军报', '解放军报', '决死队;集团军;精神符号;百团大战;', '一位耄耋之年的老人，一名弱冠之年的列兵，一个不惑之年的地方领导，他们的人生经历不同，却对成都军区驻滇某集团军军史馆里那段尘封的历史，有着相同的情感共鸣。 这个集团军所属某师，前身是在中国共产党领导下、老一辈无产阶级革命家薄一波创建的山西青年抗敌决死队', '2010-08-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB7MzwA9fQ_isbDNWza6swxBjl-IyGuHYSaoIEywE3QH57DoCk3wfX_qI3rdz8UrVZTiYRZ67sZg_AHQn7wsDzgnsBlNwCVp4280d5uDZz124pLLOOGyEysomnY-9wi8R9yIbrdye7Wmg==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3852, '报纸', '胡德利同志逝世', '', '人民日报', '人民日报', '胡德利;', '新华社西安９月２日电 陕西省军区原副司令员、副兵团职离休干部胡德利同志，因病医治无效，于８月９日在西安逝世，享年９７岁。 胡德利是江西省安远县人，１９２９年参加革命，１９３２年加入中国共产党。革命生涯中，他历任战士、副排长、排长、连长、营长、团长', '2009-09-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDgnN4j7QVzIesVteLYm5gG0GwP72O6fEpLfQYAYVwemUfy7LcHwF0HXnWDCvmKO8fBK8saScpm7JPhCdGEKTfVBcxsrkBbcDfCwsVHjG3UEJHu001ODmnI9ssBwsy76pMvYdUU9vL2gg==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3853, '报纸', '冯达同志逝世', '', '人民日报', '人民日报', '冯达;', '新华社上海８月５日电 海军东海舰队原副政治委员、副兵团职离休干部冯达同志，因病医治无效，于４月１８日在上海逝世，享年８５岁。 冯达是山西陵川人，１９３８年２月参加抗日牺牲同盟会，１９３９年１１月参加八路军，１９４０年２月加入中国共产党。革命生涯中', '2009-08-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICGAFcyCcKeo96aoFIzKlaSHhMviSA3MDNWn49DX3o-5gk6egIFEgUNjNoz-HoNXhp88cP34AVXUXeERDWkwXFp2shHas0DKZgMdUhJIHpQnrfU7vf0dr7VUYaMNeciq7rkm5aBbAMi7w==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3858, '报纸', '以艺术手法再现太行抗日历史', '张晶晶', '中国文化报', '中国文化报', '抗日根据地;王迎春;杨力舟;太行山;', '承接《抗日烽火燃烧在太行山上》的历史画任务，对王迎春和杨力舟来说，志在必得。他们青年时代就对历史画创作情有独钟，曾经画过《平型关大战》、《太行浩气传千古》、《战火中的姐妹》、《小二黑结婚》（连环画）、《太行铁壁》等作品，其中太行题材作品曾获得全国美展金奖', '2008-11-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDTT1ThE8dj-JrJaHxF6Cv84A8dOGQu6cK8Mws8gYQobNcTpgc307kM4u-05n7SsDWxPN6wulx6xoW54g8Qkn8LmzH3Y6M9AOqbGxlJQFnfnQ6lbqM5M_n5yd2owJHOeoLpemVXcn0SLA==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3862, '报纸', '聂荣臻战地救助日本小姑娘', '', '人民日报', '人民日报', '聂荣臻;指挥所;', '１９４０年８月２０日，八路军发起百团大战。按照八路军总部的统一部署，晋察冀军区部队在司令员兼政治委员聂荣臻指挥下，向正太铁路东段日军展开攻击。第１分区第３团重点进攻井陉煤矿，该团３个营分头攻打新矿、老矿和贾庄炮楼。激战一夜之后，攻占了新矿，随后贾庄炮楼也', '2007-04-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB0CCbU-87XWRGqNCgEtN1sne16iXludfIgy-oCEaaAcRii61OvRkNWvp4MppjLZlfaWdY9AWZOJn6_ChGYaNdhhifzPN1I0nYFXuovmZmG3zrckBAoFfhj47bLBriA1p_pBNMpjFSzTA==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3871, '报纸', '“居安思危　永志不忘”', '温庆生', '光明日报', '光明日报', '反战同盟;', '84岁的抗日老战士杨大伦仍然精神矍铄。他在战争中负伤失去右臂，人称“独臂英雄”。  回忆起60多年前的烽火岁月，老人神情激昂。  豁出命来保家卫国  杨大伦17岁奔赴延安，抗大毕业后，被分配到八路军129师冀南军区第一军分区政治部组织股当干事。194', '2005-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICOh5LMBrbvSu60AP_UIFjB68fK7JA903nJUUBc2WmNJ7Dy3Z2xa3nEVLtxS22IiYfL3PTEKPiRgvUfXoT2k7vTwgVXNrvEJG5SgPRUvmSMuN3WBluw8kxOiwIGOrENpsx1qM3JTOPdZw==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3873, '报纸', '听老英雄讲抗战故事', '', '科技日报', '科技日报', '日本鬼子;抗战时期;王树楷;百团大战;反扫荡;六十年;军分区;手榴弹;', '在敌人肚子里闹革命  本报记者付毅飞  张凯1919年11月生于山东莱阳，1937年11月参加革命，1938年2月加入中国共产党，同年调军委通信学校学习。  抗战时期历任八路军第120师电台报务员，冀中军区电台分队长、区队长、无线电训练教务主任，军区电台', '2005-08-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDlSJTkP3eOTBcJokJh7bMXAC29YmSqiURYpnN_HmKpVV1iHgl0ELHZZ6Vs9jA7WQE-ChcHYIYkVmFPcVANrcihSCYWAk5UvPb9xl1nTIarVpLF7sw4IymMQU0WYBjFWJ3ScVeIty2MbQ==&uniplatform=NZKPT&language=CHS', '百团大战_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (3877, '报纸', '续写“日本小姑娘”的故事', '于青', '人民日报', '人民日报', '聂荣臻;', '65年前的1940年8月下旬，是“日本小姑娘”故事的起点：8月21日，在百团大战攻打日军占据井陉煤矿的战火中，八路军战士抢救出年龄4岁和不满1岁的两名日本孤女；8月22日，八路军晋察冀军区司令员聂荣臻决定把两名日本孤女送还日方，并给日军官兵书信一封。 25年前的19', '2005-08-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAXwqTffQpUVIDMgFF1dfmBRcvFcWvEOB0sOKcx5GholBZO09KC77KIlxuB93a6ZLQoGUfKYLuvnQ9L3aIUnii-3gp1gxUqgrJAeROeoNAUBuM6xksgzZBPeWcTXErA8-zZHIxB9_vRpQ==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3882, '报纸', '继承先烈遗志　弘扬民族精神', '符德新', '中国教育报', '中国教育报', '关工委;教育部;中国人民抗日战争;弘扬民族精神;世界反法西斯战争;', '本报讯(记者　符德新)在中国人民抗日战争暨世界反法西斯战争胜利60周年之际，教育系统关工委开展了一系列贴近实际、讲求实效的教育下一代活动，使中国人民前仆后继反抗日本侵略者的英雄事迹和伟大民族精神，深入广大青少年心中。  为了使教育活动更深入、更有实效，', '2005-07-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICkzjICsXqur2CrKCIdSvKq2UV7RYNdQW-4LW0m5Yc7VY3_slaSv4JciKMeeH9a5r6fzUTxTcDEGhj-XCB8aAdgKCM23Paw7HdL63sroRdFLpZrBrWeC3bdnMD1p_0NI6buSPMo5DQMYg==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3883, '报纸', '借鉴历史开创未来', '张国育', '解放军报', '解放军报', '中华民族;抗日民族统一战线;正面战场;中国共产党领导;借鉴历史;国民党军队;日本军国主义;敌后游击战;全民族抗战;敌后战场;', '编者按60年前那场波澜壮阔的抗日战争，是中国反侵略战争史上的奇观。近代史上积贫积弱的中国第一次取得了反对外敌入侵的完全胜利，它洗雪了百余年来的民族耻辱，成为中华民族由衰败走向振兴的历史转折点。在民族存亡的殊死搏斗中，中华儿女奋起反抗，共赴国难，浴血沙场，前', '2005-07-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICy7wBsM6Cr3ohYWBbmimZ-4PDigtW5Ckb5zbuYejIsHx82SZCK7fntrwjZXjhbMTnRBfZUj2Tbx4fcxsCOVNIoa4UD8Jatqrx0Hyv6Rdve-YkZLf57j5Ob8QON_fxD2zqnQm3hlOb0uw==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3884, '报纸', '吴邦国温家宝贾庆林曾庆红黄菊李长春罗干等参观纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大型主题展览', '盛若蔚', '人民日报', '人民日报', '中国人民抗日战争;吴邦国;主题展览;曾庆红;李长春;温家宝;世界反法西斯战争;', '本报北京7月7日讯 记者盛若蔚报道：中共中央政治局常委、全国人大常委会委员长吴邦国，中共中央政治局常委、国务院总理温家宝，中共中央政治局常委、全国政协主席贾庆林，中共中央政治局常委、国家副主席曾庆红，中共中央政治局常委、国务院副总理黄菊，中共中央政治局常委', '2005-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID-KJEwSVLtBw-E2SXTdc3nPF32Qy38UgYXJGojalRcpzrbGrOHfon6LFWzX9hlQuZxx7Kyx99SdjCrHjGFTO8rmBY8cn7s9XM6obWwt7kYrbj3WZjmp_Y2JKoO2XGxV0MtdvIF4Out-g==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3886, '报纸', '四十载爱军尚武情', '张世斌; 唐水中', '工人日报', '工人日报', '红旗民兵营;民兵骨干;', '在河北无极县郭庄镇，有个全国闻名的“红旗民兵营”。无论战争年代还是和平建设时期，郭庄人都为国防建设做出过特殊贡献。今年2月28日，是郭庄民兵营获得荣誉称号40周年纪念日———  为了新中国诞生 郭庄一直是连接山西、内蒙古的咽喉要道。1941年8月12日，上级', '2004-03-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAH7Cag12m1z7t9sQFB7IZJhro3fJUOHtyq7sA7RirgrLtOJKGB1uUGjcKkTy5ajUVVYcg6Ke75YIHCVycCDdnnnYqMBPNhkMUO5DuG_4FHxWLwgmMfDdPuHYE26UD6gWV3V5v7lTqVlg==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3887, '报纸', '陈开路同志逝世', '', '人民日报', '人民日报', '广州;广东;参加;', '新华社广州7月1日电　广西军区原副司令员陈开路同志（副兵团职离休干部），因病于6月2日在广州逝世，享年91岁。 陈开路同志是福建漳平人，1929年参加中国工农红军，1932年加入中国共产主义青年团，1933年加入中国共产党。他历任战士、班长、排长、副连长、连长、团长、', '2003-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBAImJLAI3JVjkVyUHdE_edgs5nC_bQ0Ov6u5ppMl8QWWgnW4R9oh1qqMbKYYQ_bqvnOLjcnbMcRVAUAHPTd9hzTMExsSgHUuLHHMBF4vk3WbCijvfQoWuizqw69FTtLTYwxGDhlSAuPw==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3888, '报纸', '《河北南部解放区文学概观》读后', '范国华', '光明日报;《河北南部解放区文学概观》;', '光明日报', '河北南部;《河北南部解放区文学概观》;', '人民共和国是在战争中诞生的，从艰苦卓绝的抗日战争，到高歌猛进的解放战争，不屈的民族和英雄的人民，历经种种磨砺和苦难，胜利地走过了那段激情燃烧的岁月。今天，当我们回过头来再去审视那段难忘的历史的时候，再来怀念那些给我们留下深刻记忆的人和事的时候，我们总是', '2003-06-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIADbMl0BCD0CWvJeBYVkmwGm8Bgj5EgiRj6tWCQto6N2rZidfGCd0GiAwJJeENC8JsfJZ7Nd_UoX3tj-PUfbMRwxJ2bzPvGqr16MehMturILykBbK0aicE8wAUesRBArNh4o7ytCZp-2Q==&uniplatform=NZKPT&language=CHS', '百团大战_screened');
INSERT INTO `ds_article` VALUES (3889, '报纸', '南京博物院：九秩琢玉 玉汝于成', '蒋芳', '新华每日电讯', '新华每日电讯', '博物院;博物馆;玉汝于成;寺墩遗址;', '读懂一座城，从博物馆开始。走进“九十年春华秋实——南京博物院的珍藏”，一幅“内迁路线图”跃然眼前，直观展示了20世纪三四十年代那场波澜壮阔的国宝长征；另一幅则是出自著名建筑师徐敬直之手的国立中央博物院建筑示意图，勾勒出中国人构想中的现代博物馆。 南京博物院', '2024-01-05 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2024.000103', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3891, '报纸', '抗日英雄戴万龄和他的“戴家军”', '周长庆', '新华每日电讯', '新华每日电讯', '敦化市;吉林省;抗日英雄;周保中;东北抗日联军第五军;', '1931年“九一八”事变爆发后，年过花甲的开明乡绅戴万龄，誓死不做亡国奴，率全家老少举旗抗日。他带领“戴家军”先后跟随中国国民救国军、绥宁反日同盟军、东北反日联合军第五军、东北抗日联军第五军，英勇顽强地战斗在长白山区，最后壮烈牺牲。到东北光复时，戴家一共有50', '2023-11-03 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.006535', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3892, '报纸', '“感受大陆真实的发展情况”', '柴逸扉', '人民日报海外版', '人民日报海外版', '台湾青年;台盟中央;特色村寨;讲解员;', '走访东北抗日联军活动地，铭记先辈抵抗外辱、保家卫国的事迹；参观满族特色村庄，体会大陆农村从脱贫攻坚到乡村振兴的发展变化；考察大连海事大学及远洋教学实习船“育鲲”轮，了解大陆航海事业的发展…… 前不久，由台盟中央指导、台盟辽宁省委会主办的台湾青年历史文化交', '2023-10-10 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2023.003415', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3893, '报纸', '一刻不敢忘却 一路走向复兴', '闫松; 朱小苗', '中国新闻出版广电报', '中国新闻出版广电报', '抗战精神;中国人民抗日战争纪念馆;新华社;爱国主义;血战到底;中华民族;', '进入9月，中国人民抗日战争暨世界反法西斯战争胜利78周年纪念日、九一八事变爆发92周年纪念日相继到来，新闻媒体从不同角度，通过多种形式的报道，对伟大抗战精神作了生动、深刻的阐释，给人们上了一节记忆深刻的爱国主义教育课。 14年的抗日战争历史，是中国人民以不屈精神', '2023-09-21 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2023.002875', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3894, '报纸', '是“千年长城古镇”亦是“红色美丽村庄”', '张景华; 曹若芃', '光明日报', '光明日报', '长城文化;古北口镇;烽火台;北门城楼;', '位于北京市密云区的古北口是万里长城的一个关口，由潮河切割燕山而成，东有蟠龙山，西有卧虎山，自古为兵家必争之地。由于明、清两代均建都于北京，古北口曾有“燕京门户”“京师锁钥”之称。在1500年前，这里建造了长城；90余年前，这里是爱国志士奋战的地方。中华文明和红', '2023-09-07 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.004392', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3898, '报纸', '以抗联血脉立根 以红色基因铸魂', '孙峰松; 王娜; 王浩淼', '检察日报', '检察日报', '红色基因;退役军人;磐石市;检察干警;检察院;东北抗联;', '磐石之固，信之所诚。九一八事变后中国共产党领导下的抗日武装在东北创建的第一块抗日游击根据地就在吉林磐石，英雄将军杨靖宇的热血也洒在这片热土上。巍巍青山，铮铮铁骨，东北抗联精神深深洗礼着磐石检察人。 近年来，磐石市检察院把东北抗联精神与新时代检察业务相融合', '2022-12-06 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2022.005550', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3899, '报纸', '他们的故事，需要有人去听', '司晋丽', '人民政协报', '人民政协报', '台湾青年;军事情报;祖国大陆;隐蔽战线;《光明报》;余则成;国民党特务;', '“这里安息着846位革命者，为了谋求两岸统一之路，他们将青春和生命置于血与火的淬炼之中。因为工作需要，很多人只能一辈子隐姓埋名奋战在隐蔽战线。”在北京西山无名英雄纪念广场纪念碑前，全国政协委员、军事科学院原副政委王卫星的言语中饱蘸深情。他已经数不清是多少次来', '2022-09-29 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2022.006973', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3900, '报纸', '历史不可忘 奋斗创未来', '徐扬', '新华每日电讯', '新华每日电讯', '共产党;九一八事变;中华民族;', '9月18日，刺耳的警报声再次划破沈阳上空。这是一种警示，警示我们永远铭记历史! 91年前，震惊中外的九一八事变爆发，中国由此陷入了前所未有的深重灾难之中。91年过去，回想起来仍痛彻心扉：一夜之间沈阳失陷，几个月东北几近丧失。日本军国主义则更加贪婪，肆无忌惮地将侵', '2022-09-19 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.007008', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3904, '报纸', '缅怀先烈，传承伟大东北抗联精神', '', '中国民族报', '中国民族报', '东北抗联;杨靖宇;东北抗日联军;缅怀先烈;中国共产党领导;', '1931年9月18日，日军炸毁沈阳柳条湖附近南满铁路路轨，悍然发动九一八事变，开始了蓄谋已久的侵华战争。 白山黑水间，茫茫林海中，由中国共产党创建和领导的东北抗日联军进行了长达14年不屈不挠的斗争，开辟了全国最早、坚持时间最长的抗日战场，在中国人民抗日战争和世界', '2021-12-31 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001346', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3905, '报纸', '论致公党接受中国共产党领导的必然之路', '陈颂原', '致公党中央组织部;', '团结报', '致公党;陈演生;中国共产党领导;司徒美堂;', '致公党是由美洲洪门组织发起成立的政治组织，海外洪门是以在海外谋生和流亡的国内下层百姓为主的民间秘密组织，两者颇有渊源。海外洪门秉承中华民族爱国、爱乡之精神，因爱国而救国，大力支持辛亥革命、抗日战争。致公党与共产党合作并接受共产党的领导，有其必然性。 致', '2021-12-16 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.002348', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3906, '报纸', '90年前，宁都起义告诉我们', '肖斐杰', '江西省宁都县委;', '学习时报', '宁都起义;宝贵精神;精神财富;中央苏区;兵运工作;国民党;部队改编;赵博生;董振堂;', '1931年12月14日，国民党第26路军在中国共产党的领导下，发动了震惊中外的宁都起义。这场彪炳史册的伟大壮举，留下了“铁心向党、坚持真理、爱国爱民、敢于斗争”的宝贵精神财富。1938年，毛泽东在延安接见参加宁都起义的部分同志，与大家合影留念，并在照片上题词：“以宁都', '2021-12-13 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002352', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3907, '报纸', '宁都起义始末', '褚银', '解放军报', '解放军报', '宁都起义;董振堂;中央苏区;中革军委;刘伯坚;赵博生;国民党军队;季振同;', '90年前，在位于江西省东南部的宁都，爆发了土地革命战争时期国民党军最大规模的一次起义，国民党第26路军1.7万余名官兵响应中国共产党的号召，投入红军。 第26路军原系西北军，在中原大战时为冯玉祥第二方面军第5路军。1930年中原大战中冯玉祥失败。10月，蒋介石收编该部', '2021-12-12 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007655', '九一八事变_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (3909, '报纸', '英雄叙事的新变', '岳雯', '中国新闻出版广电报', '中国新闻出版广电报', '英雄叙事;英雄人物;普通人;', '如何书写战争，如何设身处地地想象和塑造英雄，对于今天的作家而言可谓是巨大的挑战。刘荣书的《望烽烟》（作家出版社）将笔墨对准“九一八事变”至1945年抗日战争胜利这一段风云激荡的历史，书写了战争所带来的巨大伤痛以及普通人成长为英雄的历程，从而为这一类创作开辟出', '2021-11-26 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004656', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3910, '报纸', '弘扬东北抗联精神 凝聚磅礴奋进力量', '吴浩', '经济日报', '经济日报', '东北抗联;东北抗日联军;东北抗日义勇军;', '“九一八，九一八！从那个悲惨的时候，脱离了我的家乡，抛弃那无尽的宝藏，流浪！流浪！”这首流传不朽的抗战歌曲《松花江上》，道出了九一八事变后东北人民遭遇的悲惨境地。 九一八事变后，日本侵略者用短短4个多月时间侵占东北三省，成立伪满洲国。东北人民奋起反抗，坚', '2021-10-30 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.007605', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3911, '报纸', '气贯长虹 英雄史诗', '徐壮', '新华每日电讯', '新华每日电讯', '东北抗联;东北抗日联军;中国共产党;英雄史诗;中华民族;中华儿女;九一八事变;魏拯民;杨靖宇;动车组列车;共产党人;爱国主义;陈列馆;', '“党创建最早、坚持抗日时间最长、条件最为艰苦”。 这三个“最”字形容的，是日本侵华时期中国共产党领导下的东北抗日武装，特别是东北抗日联军。 90年前的9月18日，日军炸毁沈阳柳条湖附近南满铁路路轨，悍然发动九一八事变，开始了蓄谋已久的侵华战争。 九一八事', '2021-10-29 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008299', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3913, '报纸', '用东北抗联精神教育广大党员、干部', '', '人民日报', '人民日报', '东北抗联;东北抗日联军;', '抗日战争是近代以来中国人民反抗外敌入侵持续时间最长、规模最大、牺牲最多的民族解放斗争，也是第一次取得完全胜利的民族解放斗争。作为中国人民抗日战争这部壮丽史诗中最惨烈、最令人动容的篇章之一，东北抗日联军与穷凶极恶的日本侵略者展开艰苦卓绝的斗争，在生与死、血', '2021-10-28 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011322', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3914, '报纸', '弘扬历久弥新的东北抗联精神', '郝迎灿', '人民日报', '人民日报', '东北抗联;东北抗日联军第一军;反法西斯战争;东北烈士纪念馆;杨靖宇;', '九一八事变后，中国人民就在白山黑水间奋起抵抗，成为中国人民抗日战争的起点，同时揭开了世界反法西斯战争的序幕。 ——摘自习近平总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利75周年座谈会上的重要讲话 黑龙江省哈尔滨市一曼街241号，矗立着一栋欧式白楼。时', '2021-10-28 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011333', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3917, '报纸', '血染沙场气化虹', '许大伟', '解放军报', '解放军报', '东北抗联;抗联精神;中华民族;日本帝国主义;', '“我的家在东北松花江上，那里有森林煤矿，还有那满山遍野的大豆高粱……”每当唱起这首曾经响彻大江南北的《松花江上》，人们就会联想到那段充满国仇家恨的苦难岁月。 九一八事变后，国民党政府采取不抵抗政策，使东北大地山河沦丧，人民惨遭日寇铁骑蹂躏，中华民族面临', '2021-10-27 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006761', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3918, '报纸', '铭记东北抗联精神 担当历史使命', '青平', '中国青年报', '中国青年报', '抗联精神;东北抗联;东北抗日联军;历史使命;', '1931年9月18日夜，日本关东军自行炸毁沈阳北郊柳条湖附近南满铁路的一段路轨，反诬是中国军队所为，随即以此为借口，发动了震惊中外的九一八事变。由于国民党当局奉行不抵抗政策，不到半年，东北全境沦陷。 面对日寇的侵犯，中共满洲省委当即行动起来，在东北各地组织起抗', '2021-10-26 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.003842', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3919, '报纸', '东北抗日联军纪念馆 白山黑水 忠魂永驻', '刘以晴', '人民日报海外版', '人民日报海外版', '杨靖宇;烈士陵园;东北抗联;东北抗日联军;消息树;', '国庆期间，位于吉林省通化市的杨靖宇烈士陵园暨东北抗日联军纪念馆迎来了一批批凭吊者。 81年前，东北抗日联军第一路军总司令杨靖宇在吉林省濛江县（后改名靖宇县）与敌人战斗时壮烈牺牲，年仅35岁。 1958年2月，杨靖宇烈士陵园在通化市浑江东岸靖宇山揭幕，同时为杨靖', '2021-10-12 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.003089', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3920, '报纸', '信念的颜色是中国红', '杨飒', '光明日报', '光明日报', '爱国主义教育;红色基因;红色教育资源;中国红;浙江省宁波市北仑区;', '86年前的南开大学始业式上，张伯苓校长面对全体南开师生发出了著名的“爱国三问”。今年9月7日，在南开大学2021级新生开学典礼上，4186名本科生、5347名研究生再一次重温这质朴厚重的“三问”。“你是中国人吗？”“是!”“你爱中国吗？”“爱!”“你愿意中国好吗？”“愿意!', '2021-10-05 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005092', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3923, '报纸', '沈阳：以“红”为底色绘就文旅新篇', '刘海红', '中国文化报', '中国文化报', '中共满洲省委旧址;审判日本战犯;数字化保护;历史博物馆;东北地区;文物建筑;特别军事法庭;红色文化;九一八事变;', '沈阳是中国人民抗日战争暨世界反法西斯战争的起始地。沈阳革命历史文物资源丰富，拥有沈阳“九·一八”历史博物馆、抗美援朝烈士陵园、中共满洲省委旧址纪念馆、二战盟军战俘营遗址纪念馆、沈阳审判战犯遗址馆、东北讲武堂旧居等33处不可移动革命文物，反映了不同时期沈阳人', '2021-09-24 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.002956', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3924, '报纸', '鼓舞斗志 抗战到底', '李英', '中国印刷博物馆;', '中国新闻出版广电报', '抗战到底;中共党人;九一八事变;《新华日报》;《解放日报》;抗日根据地;抗日救国;最后胜利;', '战争年代，党报不仅是宣传员和鼓动员，也是组织者，还是党与群众联系的纽带，起着组织、鼓舞、激励、批判、推动的作用。毛泽东指出，在报纸上正确地宣传党的方针政策，通过报纸加强党和群众的联系，这是党的工作中一项不可小看的、有重大原则意义的问题。 1931年9月18日，', '2021-09-22 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.003842', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3926, '报纸', '有一种可以打赢的仗，抗联却选择了放弃……', '郎秋红; 邵美琦', '新华每日电讯', '新华每日电讯', '东北抗联;根据地;杨靖宇;游击区;反日游击队;梁树林;人民革命军;赵一曼;赵尚志;', '东北抗日联军，是中国共产党领导下一支英雄的部队。其前身为东北抗日义勇军余部、东北反日游击队和东北人民革命军。自1931年九一八事变爆发开始，战士们在内无粮草、外无援兵、爬冰卧雪的情况下，与数倍、数十倍于自己的敌人战斗了14年。 在长期、艰苦、壮烈的东北抗战中', '2021-09-17 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007271', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3927, '报纸', '90年前的“最后一课”', '于力; 张博群; 郭翔', '新华每日电讯', '新华每日电讯', '奴化教育;日本关东军;最后一课;中国东北;满洲帝国;建国精神;九一八事变;侵略者;', '“我的孩子们，这是我最后一次给你们上课了。柏林已经来了命令，阿尔萨斯和洛林的学校只许教德语了，新老师明天就到，今天是你们最后一堂法语课。”1873年，法国作家都德出版了著名小说《最后一课》，讲述的是普法战争后，法国的阿尔萨斯和洛林被迫割让给普鲁士，两地的学校', '2021-09-17 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007269', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3928, '报纸', '征程万里我先行', '闫明星', '哈尔滨工业大学全媒体中心;', '人民政协报', '任震英;地下党;哈尔滨工业大学;彭德怀;白塔山公园;游击区;英勇就义;', '1932年3月伪“满洲国”成立时，颁布了所谓的“国歌”。当天，就有人把歌词改编成了《反满抗日新歌》，并秘密地散发到哈尔滨市的大街小巷、工厂和学校。 这首歌到处流传，很快传到游击区，在战士和人民群众中传唱，成为鼓舞3000万东北同胞报仇雪耻的响亮号角…… 吹响这', '2021-09-16 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.007493', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3929, '报纸', '弘扬伟大抗战精神 创新红色旅游发展', '范朝慧; 周凤文; 邰子君; 高雯雯; 任英文; 高越; 蒲钰; 刘玉萍; 王文华; 崔哲', '中国旅游报', '中国旅游报', '抗战精神;红色旅游;骆驼湾;旅游业态;中国人民抗日战争纪念馆;旅游区;讲解员;', '中国人民抗日战争，是近代以来中国人民反抗外敌入侵持续时间最长、规模最大、牺牲最多的民族解放斗争，也是第一次取得完全胜利的民族解放斗争。习近平总书记指出：“中国人民在抗日战争的壮阔进程中孕育出伟大抗战精神，向世界展示了天下兴亡、匹夫有责的爱国情怀，视死如归', '2021-09-13 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002641', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3932, '报纸', '感召的力量', '马志伟', '第十、十一、十二、十三届全国政协;第十、十一届青海省政协;', '人民政协报', '马占山;黑龙江;傅作义;蒋介石;江桥抗战;东北军;', '今年是中国共产党成立100周年，历史是人与事组成的，是有温度与故事的。在中国共产党感召和凝聚的爱国人士的实例中，我祖父马占山就是其中的代表之一。我作为马占山将军的后裔，很希望通过讲述前辈所经历的故事，让大家了解我祖父是如何在中国共产党的感召下，在共产党人的帮', '2021-09-02 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.007116', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3934, '报纸', '辽沈大地赓续红色传承', '辛阳; 胡婧怡', '人民日报海外版', '人民日报海外版', '辽沈战役纪念馆;抗美援朝纪念馆;中国人民志愿军;东北抗联;', '在这里，世界反法西斯战争打响了第一枪；在这里，中国革命取得了关键一战的胜利；在这里，百万中国人民志愿军跨过鸭绿江……从抗日战争到解放战争再到抗美援朝战争，辽沈大地记载了一幕幕中国共产党领导中国人民奋勇向前的英雄故事。 “建党百年红色旅游百条精品线路”中', '2021-08-20 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002590', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3940, '报纸', '伟大的长征精神永远焕发着不朽的生命力', '陈姝', '中国妇女报;', '中国妇女报', '长征精神;红四方面军;红军长征;', '80多年前，一支衣着褴褛、装备简陋的队伍，像地球的红飘带一样穿越了中国大地的险山恶水，冲破了敌人的围追堵截，完成了一次开创新局的伟大远征——长征。 双脚丈量大地，鲜血铸就河山。600余次战役战斗，跨越近百条江河，攀越40余座高山险峰，穿越茫茫草地……这是惊天动', '2021-07-30 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.002287', '九一八事变_screened,扎西会议_screened,将台堡_screened,强渡大渡河_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,会宁_screened,飞夺泸定桥_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (3941, '报纸', '吉林：牢记嘱托 将红色精神发扬光大', '刘冬雪; 刘玉萍', '中国旅游报', '中国旅游报', '杨靖宇;烈士陵园;民族英雄;马鞍山村;习近平总书记;三下江南战役;红色旅游;红色精神;', '“一百年来，中国共产党团结带领中国人民进行的一切奋斗、一切牺牲、一切创造，归结起来就是一个主题：实现中华民族伟大复兴。”在庆祝中国共产党成立100周年大会上，习近平总书记的讲话掷地有声。 习近平总书记曾多次到吉林考察调研，他强调，要把红色资源作为坚定理想信', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2021.002179', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3942, '报纸', '卢沟桥事变报道第一人：用生命记录抗战的战地记者', '王京雪', '新华每日电讯', '新华每日电讯', '卢沟桥抗战;范长江;卢沟桥事变;第一人;', '1937年7月10日，清晨的北平城里，一个背着相机、身材高大的青年，走出家门，跨上自行车，一路疾行。 他从北平只身穿越炮火，来到卢沟桥一带，被日军截住，“他们先疑我为中国军的高等侦探，理由是新闻记者没有勇气到日军方面来，然而由于我的态度自若，这个猜疑也就消除了', '2021-07-07 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005290', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3943, '报纸', '信仰力量穿时空', '秦杰', '江苏省扬州市江都区纪委监委;', '中国纪检监察报', '许晓轩;石榴树;', '青砖小瓦间，青苔露绿头。在扬州城里，沿江都龙川步行街一路缓行至深处，许晓轩故居便坐落在这里。 许晓轩，又名永安，1916年11月出生于江苏省江都县。少时因生活所迫中途辍学，“九一八”事变后，积极投身到抗日救亡的洪流中。1938年5月，许晓轩加入中国共产党。1940年4', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003220', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3944, '报纸', '寻访国歌最初的身影', '张进进', '光明日报', '光明日报', '《义勇军进行曲》;东北义勇军;', '“起来!不愿做奴隶的人们!把我们的血肉，筑成我们新的长城!”当慷慨激昂的音乐响起，无论此时身在何地、正在做何事，心中热血澎湃。今年4月，为了探寻《义勇军进行曲》最初的身影，我走进了位于辽宁省本溪市桓仁满族自治县的辽宁东北抗日义勇军纪念馆。这里集中展示了九一八', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003343', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3945, '报纸', '红旗漫卷映苍穹', '', '人民政协报', '人民政协报', '抗日民族统一战线;张学良;土地革命路线;国民党左派;农村革命根据地;工农武装割据;茶陵县工农兵政府旧址;红色政权;瓦窑堡会议;周恩来;季振同;武装斗争;第二次国共合作;宁都起义;中央委员;西北军;', '建立工农民主统一战线 开辟革命新道路 土地革命的10年，是中国共产党从弱小走向成熟的重要时期。10年间，党紧紧依靠农民这个革命主要同盟军，建立和巩固工农民主统一战线，开辟了一条适合中国国情的农村包围城市、武装夺取政权的革命新道路。 毛泽东提出“工农武装割据', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005341', '九一八事变_screened,遵义会议_screened,苏维埃共和国_screened,反围剿_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (3946, '报纸', '期待实现中华民族复兴梦', '胡新化; 张建友', '黑龙江省群众艺术馆研究部;', '中国文化报', '推广普通话;中华民族复兴;日本鬼子;拜泉县;党组织;教育厅;黑龙江省;共产党;', '我1931年出生，在黑龙江省群众艺术馆离休，我有一个强烈的愿望，就是在有生之年，能看到在中国共产党的领导下，让中国富起来、强起来，实现中华民族的伟大复兴。 1931年“九一八”事变爆发后，我的二叔被日本鬼子炸成重伤，身边的亲人朋友咒骂日本鬼子不得好死，从此日本', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.001997', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3947, '报纸', '历史不能遗忘 英雄应被铭记', '杨帆', '团结报', '团结报', '英雄精神;廖耀湘兵团;黑山阻击战;日本关东军;游击队;英勇战斗;', '一段历史，血火铸就。一种精神，薪火相传。历史不能遗忘，英雄应被铭记，无论时代如何变迁，英雄精神始终指引我们前行方向。 当石建芳老人翻开那沓厚厚的写满他父亲生前事迹的资料，将尘封已久的记忆缓缓打开，我们才真切感受到，英雄，从来不是一个抽象的概念，他是如此', '2021-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB4qkWTDcKj20E5-EJoB6UFR9JX4WOlEaPlQ3qY-c2Ud2y_H3Xo09IZEDZxQh3qXuLAaicpI8tdTPLK93eNxBtsxnf5DwK-MRNJhLfS6V_G0Ad_7BO-_GX7aJC3HkL78sTDmE1WLqImzA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3948, '报纸', '一家四代人 坚定跟党走', '赵亮', '团结报', '团结报', '共产党人;民主党派;江桥抗战;中国共产党领导;马占山;党史学习;', '今年是中国共产党成立100周年。一百年来，中国共产党带领中国人民披荆斩棘不懈探索，创造了辉煌的历史成就。全国政协常委、民革青海省委会原主委、著名抗战将领马占山将军嫡孙马志伟说：“我为伟大的中国共产党感到自豪和骄傲。” 从祖父马占山到父亲马奎，再到马志伟本人', '2021-06-24 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001284', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3950, '报纸', '将军手枪忆忠魂', '邹大鹏', '新华每日电讯', '新华每日电讯', '赵尚志;', '中华民族到了最危险的时刻——做亡国的奴隶，还是用生命去抗争？ 东北烈士纪念馆里，静静地陈列着一把手枪，此枪为国家一级文物，美国造，马牌，长20.5厘米，重1.2千克，枪号80292。这把手枪的主人是赵尚志，东北抗联创建者和领导者之一，与杨靖宇并称“南杨北赵”。 1', '2021-04-08 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.002831', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3951, '报纸', '东北抗战是党中流砥柱作用的发端', '侯远东', '学习时报', '学习时报', '满洲省委;共产党;东北抗日义勇军;中国共产党领导;日本帝国主义;抗日武装;东北抗战;九一八事变;党组织;反日斗争;抗日救亡运动;武装力量;杨靖宇;', '东北抗日战争是中国人民抗日战争的起点，也是中国共产党发挥中流砥柱作用的发端。在东北抗战中，中国共产党始终站在斗争的第一线，成为中国人民奋起抵抗日本帝国主义侵略的最早宣传者、动员者和最坚决的抗击者。 中国共产党在东北吹响了抗战的第一声号角。九一八事变爆发', '2021-01-01 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002526', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3952, '报纸', '抗美援朝玉成中国工业化的起点', '梅新育', '商务部研究院;', '国际商报', '中国工业化;殖民地;英属印度;钢产量;印度卢比;抗美援朝;', '雄赳赳，气昂昂，跨过鸭绿江。 保和平，卫祖国，就是保家乡。 中国好儿女，齐心团结紧。 抗美援朝打败美帝野心狼! 《中国人民志愿军战歌》经典传唱，先辈们用鲜血和生命凝成的抗美援朝精神永生! 今天的中国已是世界第一大工业国、第二经济大国，作为经济研究', '2020-10-26 08:00:00', 'https://link.cnki.net/doi/10.28270/n.cnki.ngjsb.2020.005230', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3953, '报纸', '香港某些年轻人，爱国热情哪儿去了？', '杨志红', '全国政协;香港新活力青年智库;', '人民政协报', '爱国热情;香港新一代;爱国教育;通识教育;年轻人;', '“九一八事变”纪念日刚刚过去。对于某些香港年轻人而言，历史上的这一天到底发生了什么、有什么意义、背后沉痛的历史记忆是什么，可谓一片空白。如何让越来越多的香港年轻人能够缅怀先烈、缅怀英雄，对民族苦难感同身受？ 众所周知，当下，香港爱国主义教育出现了不少问', '2020-09-24 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2020.005795', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3954, '报纸', '假如那一天来临', '', '中国国防报', '中国国防报', '“九一八”事变;', '今年9月19日，是第20个全民国防教育日。 这个时间节点耐人寻味：“九一八”事变爆发纪念日刚过去1天，距中国人民志愿军抗美援朝出国作战70周年纪念日还有36天。 20年，白驹过隙。20年前出生的婴儿，假若他从军，如今已成为合格的战士；假若他求学，也将成国之栋梁……', '2020-09-21 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2020.001815', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3959, '报纸', '百年青春心向党 矢志建功新时代', '', '新华社;', '人民日报', '中国青年运动;五四运动;中华民族伟大复兴;党的十八大以来;青年文明号;创业团队;新中国成立;', '时空，穿越到100年前—— 1919年，在巴黎和会上，英法美等西方列强完全无视同为第一次世界大战战胜国的中国提出的诉求，把战败国德国在山东的“权益”转让给日本。中华民族的尊严被无情践踏。 “外争主权，内除国贼”“取消二十一条”“还我青岛”……5月4日这一天，', '2019-05-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICMm27cWs5bxDyIPYwI3_Hokn3GdX63KlD9cZBhF0UMmBv9EVLJLW-uxuGQsqezRc1YO-ceAI6-uX4JMbRXW0T8UTPmFHHEy37fEZtp1-ixcCEzNJ8tig4TygXVgywYYzPm_gniA4lZ5Q==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3960, '报纸', '“不只是一部个人史，更是一部西南联大史”', '王洪波', '中华读书报', '中华读书报', '古籍整理;杨维桢;中华读书报;个人史;正统论;张荫麟;', '编者按 在艰苦卓绝的抗战岁月中，中国学人砥砺奋进，钻研学术，培养人才，西南联合大学“刚毅坚卓”之精神，八十年来，激励人心，不曾少歇。著名历史学家郑天挺先生，在西南联大担任总务长及北京大学文科研究所副主任等职，所见所闻，繁多具体。值得庆幸的是，郑先生当时', '2018-01-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAwd57FdTdnW3FrB9o707LaeOpXVY5e4XKZ_UeLXV7jqXwZeyXH5Gv2gS1zO1THcHZRnEgfGE5a7fq2pXWW6U8Kt_slRkAu3-tOvKy3RWH6E_dZdqMf5Zg6eTGvohKK99fY67u2YMJxzQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3964, '报纸', '红军长征与统一战线', '陈喜庆', '中国人民政协理论研究会;中央统战部;', '人民政协报', '红军长征;统战工作;地方实力派;共产国际;斯大林;抗日民族统一战线;国民党;瓦窑堡会议;统一战线工作;', '今年是红军长征胜利80周年。我们在学习习近平总书记在纪念大会上的重要讲话精神，分析研究这段震撼世界、彪炳史册的辉煌历史时，都会涉及这样几个重大问题：红军为什么被迫进行长征？红军长征为什么能取得胜利？红军长征胜利后为什么能够很快形成全民抗战的局面？要回答这些', '2016-12-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBxxo3ffbqv0Zrw7mII0qA4RHNoHd6cCafBh6IoJvlIDLK-Y6JIkl4uc6raCw_z3UQz0xvX_hjQiRGKo33bzZxauPVf5VT2S39Twkv2Egy6UXkDW-8xhKYN4dALzkdJ8PTIJwbXRXRumw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,中共七大1_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (3965, '报纸', '长征路上，凝结着我们的“根”与“魂”', '户华为; 姬泰然', '光明日报', '光明日报', '长征精神;共产党人;红军长征;长征史;长征路上;', '嘉宾： 国防大学军队党史党建研究中心办公室主任 秦利 中央党校党史教研部副主任 张太原 江西财经大学马克思主义学院院长 陈始发 编者按 “长征是宣言书，长征是宣传队，长征是播种机”。红军长征不仅书写了可歌可泣的英雄史诗，而且铸就了伟大的长征精', '2016-10-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAM_igFXZNOlOYnGRKndWmXPzeIcDrV1htan-jIjRJbkY2aHd7Z4XI72TSeIXD2jrqqztHxGpHU9woqWZPyecqAUnz8WeWIUrjivoHdQAfnbmEwQDULwPT19ARirq-CCWH18q5tExqQ_w==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (3966, '报纸', '搞好国企需要百折不挠的长征精神', '唐双宁', '光大集团;', '金融时报', '长征精神;红四方面军;长征申遗;中央红军;红军长征;长征胜利;长征史;根据地;', '我们这一代人生长在崇拜英雄的年代，长征的英雄就是我们世界观形成时期最崇拜的英雄。出于对长征的崇拜，对长征英雄的崇拜，几十年来，我几乎走遍了红军长征所有重大事件发生地，也几乎对长征思考了几十年。我的最新研究成果体现在《从完整意义上认识中国工农红军的长征》一', '2016-09-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBA9bm81CYy3XnKPJofH2W-zJ7XFLoPhgZnvjnQ-r4OlU3XlW-BAtEbx3-_pTSZhAeBim5px3cryXBp-AXcCP_-Szq3SO_uYZ90c0DOM7Db_sOPZQAKUm3XSXWQ6_lzJbAfoz53coCDag==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (3967, '报纸', '最伟大的力量是同心合力', '', '光明日报', '光明日报', '世界反法西斯战争;中国共产党领导;中华民族伟大复兴;', '1931年9月18日，日本法西斯发动“九一八”事变，悍然入侵中国东北。中国人民打响了世界反法西斯战争的第一枪，中国14年艰苦抗战的序幕骤然拉开。 14年抵抗，14年坚持，14年战斗。中国人民同心合力，赢得了近代以来第一次反侵略战争的全面胜利，中华民族迎来了由灾难深重', '2016-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAJb43HI2QOOI1W-V9WxpJygiMlXy9yI-xfux1eEUFlgt5ugNcVxcJevAXSrDtOnNhIk2tc8ogt3idh0r9lUc1P5Dj2YBb9wJbT3_6zO_n8IM0OlVteWVx59fCGvgAXca6DicScrknTBQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (3968, '报纸', '再说“李闻”忆英魂', '吕金平', '人民政协报', '人民政协报', '李公朴;闻一多;国民党特务;', '1946年7月11日，曾多次表示“前脚跨出门去，后脚就不准备再跨回来”的李公朴先生，在昆明被国民党特务暗杀，年仅44岁。 4天后，在悼念李公朴先生大会上慷慨陈词“争取和平是要代价的，我们决不怕牺牲”的闻一多先生，血洒昆明翠湖之滨，年仅47岁。 2016年7月5日，民', '2016-09-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDS0C7LW0QC72lKcG8IkbgbodF1uu27Q0f8DLhnisMSDpeWRfSxlEgmtw4L44NG110IAzyGVqqjL_J3GDL8UbEIT7iMnxzehZPfM2cDPhtWxElIf1O7-S0mJjE1CI6M8np-YOR_MgvpzA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3969, '报纸', '长征精神具有超越时空的永恒价值', '李金海; 王诗敏; 胡方良', '军事科学院政治部宣传部;', '解放军报', '中国工农红军;红军长征;中央革命根据地;“左”倾教条主义;永恒价值;', '编者按 “雪山日夜被你照耀，草地时时为你燃烧，你是炎黄子孙的骄傲，你是华夏儿女的自豪。”中国工农红军两万五千里长征，有着说不完的精彩故事，有着写不完的绚丽华章，有着穿越时空气贯长虹的英雄气概和伟大精神。在长征胜利80周年到来之际，本刊专门开辟“纪念红军长', '2016-08-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBgoAOAA6pXFOx7eFYed70Rw8Ztll_4626icPDZqxBZKmEM8FakW5s2LUI73pS7uRDe8EOV9KKub5PFm30Gr1xunTHFfaPttFzWxRijij6J9rMNl6QCuw1re9KCGhcWkTiQkVRypB5hKw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,夹金山_screened,陈树湘_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (3970, '报纸', '“为日本去一大敌”', '羽戈', '中国经营报', '中国经营报', '张作霖;袁世凯;日本人;', '电视剧《少帅》选角非常讲究，譬如让文章演少帅张学良，简直天作之合，这二人经历相近：从国家宠儿到时代弃儿，从青年偶像到英雄末路，人生大起大落，命运天翻地覆。再如请李雪健演老帅张作霖，遂令观者有惊艳之感。有人说，对一些人而言，自张作霖被炸死那一刻起，《少帅》', '2016-02-01 08:00:00', 'https://link.cnki.net/doi/10.38300/n.cnki.nzgjy.2016.003623', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3972, '报纸', '回族抗战文学，精品迭出，铿锵依旧', '石彦伟', '中国民族报', '中国民族报', '回族作家;抗战文学;横断山脉;马本斋;白平阶;', '抗日战争是中华各族儿女精诚团结、同仇敌忾的历史。故而与之匹配的，抗战文学也有中华各民族作家的贡献和参与。这里仅以回族为例，对其不同阶段的抗战文学作品进行梳理，以期对中华多民族抗战文学的评估维度有所补益。  创作之基：回族抗战斗争的丰沛实践', '2015-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAVD_fG8YNYZ9G-hUYeKOHTOwhNIdAfehlwj6he5v9KiPsFhpFLfv5YhX8b9pi8bMTd1BKOVqJAB7KqFPSj7QIqn7Ne-kpPRD_XbTQfiE-P4C57emNp7BRJFASJCVhfYCZypKyUm4daKA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3973, '报纸', '杨靖远：不灭日寇不割髯', '哈聪杰; 耿建扩', '光明日报', '光明日报', '杨靖远;河北省;八路军;盐山县;', '“抗战方兴竟在盐山留遗恨，建国未艾空对鬲水吊英魂”“断头流血乃革命者家常便饭，奋斗牺牲是抗日的应有精神”，这是1938年，时任八路军东进抗日挺进纵队司令员肖华在得知杨靖远牺牲后的题词。  杨靖远1902年出生于辽宁省沈阳市，1938年牺牲于河北省盐山县。他少年', '2015-09-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDVwxA3v5f-ShE73DYfs3TV7VW0Y0fpSN6C3yrUubW__qgB8jhYvE3D9RI_dSD9BUzVOMHIScv1P1lLYXb6WFQiwZnjiN8P8d35XPJEONOK-g_ub7BksnGa2JuKZax4lDHlxMFdWzyPKQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3974, '报纸', '敲响警钟,为了永远不让“九一八”重演', '邓艳平', '中国人民解放军档案馆;', '解放军报', '东北边防军;日本帝国主义;中华民族伟大复兴;抗日战争;七七事变;日本侵略者;', '84年前的今天，精心准备的日本突然发动九一八事变，至1932年2月，东北全境沦陷。 “血的教训不能忘却。昨天的历史不是今天的人们书写的，但今天的人们不能脱离昨天的历史来把握今天、开创明天。”习主席的重要讲话，高瞻远瞩，意义深远。对于我们这支从抗战硝烟中走过的', '2015-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBrtp-0rAFI7G5hOy5-Oqpd8YsdpPCYW1QgGW08vcGul2wOKfM0SpPGYZ1RwyO2euf5eaWAg6xj4VfBUyryK7NGVoLRSuswfyeI9pndQCQ3xXP3wf7UXOkSeFZ7skW8KI1Ko80aUwadXQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3979, '报纸', '正义的胜利 和平的胜利 人民的胜利', '蔡闯; 刘文嘉; 罗容海', '光明日报', '光明日报', '世界反法西斯战争;捍卫正义;日本侵略者;人类命运共同体;', '这一刻，天安门广场出奇的安静。  三军列队，铁甲待命，军乐暂歇。9月3日10点06分，人们等待已久的声音终于响起：习近平总书记为纪念中国人民抗日战争暨世界反法西斯战争胜利70周年发表重要讲话。  “那场战争的战火遍及亚洲、欧洲、非洲、大洋洲，军队和民', '2015-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAlEZzbGRprxR31JH90kJKghyvDSlJ9eUIkN4U2NPgjTmFcWkvJhH2IryHXgJfJjuBeRTz5C40ZqFvzAeXvd-GGsUz2lXpXVmv66ntnrW_EkkUDsWJQTnXiria9WAfLz9qZPkmL-QPmPQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3980, '报纸', '铭记历史 守望和平', '', '中国妇女报', '中国妇女报', '铭记历史;中华民族;', '70年前，那场正义与邪恶、光明与黑暗的大决战，无疑是中华民族难以磨灭的记忆。 从1931年“九一八”事变开始，到1937年全面抗战爆发，直至1945年抗战胜利，14年间，中华大地山河破碎，战云密布，面对空前强大和凶残的敌人，中华儿女同仇敌忾，共赴国难。70年后，我们以', '2015-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICQiJw4tTIuyc3E0DO1d8D11euzR9S6NDI8_ToGh8Y9lqnWoYf6KszvxuNQ5m8Jb_56vL2R4pm-VgBtFSKeOP0BWTQu-VRfotihUACnw3JZDnkOGO3IpcL1VsYr6slWH3nati5KEu-pAg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3982, '报纸', '正视历史 开创未来', '', '金融时报', '金融时报', '中国人民抗日战争;世界反法西斯战争;日本军国主义;', '今年是中国人民抗日战争暨世界反法西斯战争胜利70周年。70年前的今天，中国人民经过艰苦卓绝的浴血奋战，打败了穷凶极恶的日本军国主义侵略者，赢得了近代以来中国抗击外敌入侵的第一次完全胜利。 那是一段不能忘却的历史。 1931年，日本军国主义者悍然发动“九一', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC5kRz0QdMLBVmSXdjv-IHWO7GLrPgRbUjqlS2DryuXC1BsNBGNqlEUwXxtWMn_-6DilqZLu01lUiI33AAlOz-bfIpQIStLPzhc9BAPtus6b1svrhUnM-4Ac1db4NMe6WxOwBrGdFRg-A==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3983, '报纸', '“无论在哪里，没有人不渴望和平”', '', '人民法院报', '人民法院报', '冀察政务委员会;秦德纯;', '“九一八事变”  麦肯锡检察官：我们现在翻到第四章“关于1931年9月18日及其以后在满洲发生的事件的叙述”。这把我们带到“九一八事变”；如果法庭同意，我将宣读该报告接下来的部分。  9月19日星期六清晨，沈阳市民一觉醒来，发现他们的城市已经在日军的控', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICBD6_WDzAZYpQJSJVR3vanXSqJD1octS6jlNQjognkQgsLYHoEP37NULu5pmxqg9U75CzkQJmXDVEgzYLJ59Wxf-p_S0Uo_PFwHLhXCQ8gbqBzIr0vtniR9ypgdQE7JB57_h9vvp-72w==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3984, '报纸', '“他们没有辜负民族和国家赋予的责任”', '刘吟秋', '人民法院报', '人民法院报', '日本战犯;北平行辕;军事法庭;国民政府;', '任松林先生是物理学博士，美国华裔科技工作者，2012年退休后，主要从事抗战和国民政府战后对日本战犯审判的历史文献的搜集、整理、研究。目前是上海交通大学东京审判研究中心兼职研究员。  任松林先生的父母都曾在北平军事法庭工作过，其父亲任钟垿任当时首席检察官', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB_IF_Hr-1QyIKpBe2KfQt8B6V9Up0WarPKNIdS4ELoIEaBYOc8IyxzurTMPosZXsJ_4p3L9TwmMso0efFO6PD1nIiLA_GN3yCsz5mnFOIK9slLpsdKfe2miKGhH2FgZ3040kGa29ppgg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3987, '报纸', '迟到的勋章', '邢婷', '中国青年报', '中国青年报', '阎宝航;国民党;东北军;周恩来;阎明复回忆录;国际情报工作;', '半个多世纪后，一枚国外的纪念勋章被辗转交到一位红色特工的后代及战友手中，一段传奇经历渐渐从尘封的历史中被打捞出来。 1995年，俄罗斯驻华使馆举行了一场特别的授勋仪式。时值反法西斯战争胜利五十周年，经总统叶利钦授权，俄罗斯驻华大使罗高寿向已故的阎宝航和他领', '2015-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIADDwM0CxnHkZbE-l0R2zGxiHzumqv08Zemk6DvpzX97p5e2a-hh9-evnw-7d3L1ufUYcII_OdHk92HFlnpEEwQS3TrUuex68qTwuMJ2iVdfGjQ-TlG6dQMxRBsXDD4qB0gUnIrabGB8A==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3989, '报纸', '抗战胜利是近代以来中华民族复兴转折点', '高文', '农民日报', '农民日报', '中华民族复兴;国民党;中国共产党;抗战胜利;中国人民抗日战争;', '8月28日，中国人民抗日战争暨世界反法西斯战争胜利70周年纪念活动新闻中心举行首场记者会，中国社会科学院副院长李培林，近代史研究所副所长汪朝光和近代史研究所研究员李学通在记者会上介绍中国人民抗日战争胜利的历史意义等方面情况，并答记者问。  中国人民抗日战', '2015-08-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICKG1QT1L_KXakxxZkhsK_cgortyIYDrT9uJLoGPqM7yeTLxWZ8D-fnC96GF903DruAvNDw6HSI58NfWTsOXeQb1uKXnHoP_BRrWsARjZdwQ2CyVWIiylqjX-BedoLY0UsKcpF38Mm9TA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3990, '报纸', '大力弘扬东北抗联精神', '尤光旭', '沈阳军区政治部编研部;', '解放军报', '东北抗联精神;东北抗日联军;', '东北抗日联军是中国共产党领导的东北抗战的主力军，在14年的艰苦斗争中，转战冰天雪地、深山密林，战胜了难以想象的困难和险阻，谱写了民族解放可歌可泣的英雄篇章，铸就了彪炳史册的东北抗联精神。 1931年九一八事变后，东北沦陷、民族危亡，面对大好河山被践踏、', '2015-08-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBEmHvzqNg0P9KVINmisYBhP93zdqhVGYuLdNNvjsW2wfP4Ptk2760aZQY9xB7-sXiNovsdbwUktylV_Jtv_Vl_W1Ve5rw_cWTxbRR8gL2WLjqGvYTkVAusSyhM6G3vrOAgnczPr9zVzQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3994, '报纸', '中国人民抗日战争的回顾和思考', '曲爱国', '军事科学院军事历史和百科研究部;', '经济日报', '抗日民族统一战线;正面战场;敌后战场;共产党;游击战;中国人民抗日战争;反法西斯同盟;战略相持阶段;', '抗日战争，是中国人民反抗日本军国主义侵略、争取民族解放、捍卫自由独立的正义战争，是铲除法西斯、保卫世界和平、拯救人类文明的殊死较量。在这场中国近代规模最大、时间最长、范围最广和对手最凶残、牺牲最惨重的反侵略战争中，中国人民实现了伟大的民族觉醒，迸发出空前', '2015-08-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID_97Okt1k_pzUchS3bCr1N8IrgMl9UU3t5Zxk4Xkll2e1OYflNBsTyvxo91l4Nj8ngbOXMwiXVUHlbwTOS-PIQavZmqhlzpeMONmK1XO5RIDGCw4vDnZ78zeeuaEtFuQ6Op1-ri4i4jw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3995, '报纸', '爱国报人的抗日强音', '焦润明; 刘勇 ; 毕玉才', '辽宁大学历史学院;', '光明日报', '日本军国主义;满洲红旗;东北抗联;', '“九一八事变”发生后，《申报》直斥日本“蔑弃国际公法，破坏东亚和平”，而被日本人控制的报纸《盛京时报》却轻描淡写地称“市民未感受若何恐慌”。  日俄战争后，日本侵略势力大举进入东北，此后，日本对东北地区的舆论渗透从未停止过。到1927年，日本在东北创办', '2015-08-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA5TaDMIFqgMlztOHukBXyHGthFL8yrECN4lWLNwwoA5NH32bo6_6r90HBbaRyAyNXtBMAcTmC_K0BMkmG5TXB0OH0Wpv_FTo99jpI7EDRCORKdDggYvxzc5XZmbyrvejzm-ZV1nReclg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (3999, '报纸', '东北大学：白山黑水不屈魂', '易鑫; 刘玉; 刘海龙', '中国教育报', '中国教育报', '东北大学;大学师生;奉天省;李光忠;冀察政务委员会;', '斑驳老墙，颗颗弹痕。  走在东北大学旧址，时光恍惚间穿越近百年的风云际遇，回到那段烽火漫天的岁月。  内忧外患，日寇辱国。由于特殊的地缘背景，“九一八”事变后，东北大学就踏上了流亡之路，成为当时首个因日本侵华而被迫内迁的高校。  从暂居', '2015-07-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID6quebPO1pO9ZHznnPocJmtfTLEKeSVFaXkhTXCI6HpoXPC40mAU_toPYitofSMHrvwUg6CnwQd6fWmQ2ycv4s3RBba8Ji35fDBYv-U-yXLb7RmVFRWApf1xiUxGJ3w1IiLx9tYhtzlA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4000, '报纸', '抗战家书：中国人抗战的心灵史', '张文静', '中国科学报', '中国科学报', '戴安澜;张自忠;心灵史;中国人;', '“国家到了如此地步，除我等为其死，毫无其他办法。更相信只要我等能本此决心，我们的国家及我五千年历史之民族，决不致亡于区区三岛倭奴之手。为国家民族死之决心，海不清，石不烂，决不半点改变，愿与诸弟共勉之。”这是张自忠在致战友的信中所写的一段话。 “在闲游与', '2015-07-10 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2015.001365', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4001, '报纸', '胸怀忧患,从血泪中汲取奋进力量', '秦超', '解放军报', '解放军报', '日本帝国主义;甲午战争;日本侵略者;忧患意识;共产党人;全面侵华战争;战斗力标准;《甲申三百年祭》;习主席;', '“中华民族到了最危险的时候”，这句话要不要在国歌中保留？66年前，人民政协委员和国家领导人之间就产生过一场争论。打败了日本侵略者，打倒了蒋家王朝，新中国即将成立，可以享太平了，还需要继续高唱“中华民族到了最危险的时候”吗？ 毛泽东、周恩来等力排众议，坚', '2015-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAsyuxrQ4KNCrthbHwbhcsJ6ntS1FR_RrZswWFKbZCV6pboF0wIH7HeTIl1fimCTPo12KoFbc_Xck6W1TBM4l3W7fRJBN636S5Zwxx3aGES6m5pTgjxdiXcWj9EhwazAdncbbS0V2uAbg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4005, '报纸', '烽火岁月诞生的伟大旋律', '陈先义', '解放军报社文化部;', '中国国防报', '《义勇军进行曲》;义勇军;黄显声;前进歌;', '肃穆的重大庆典、庄严的外交场合，每当雄壮激越的中华人民共和国国歌的军乐声响起，伴随昂扬的节奏，人们常常情不自禁地产生一种昂然向上的激情，一种热血沸腾的爱国情怀。这首《义勇军进行曲》，凝聚中华民族的民心士气，凝聚着亿万华夏儿女抗敌御侮的决心和意志，鼓舞着一', '2015-06-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDIT91zbgaD06q1IEZa7UerzZIRCot6146p1zpJuln7upEP9AfgsDItJRoujQiloI1_R6KUTnBHmP9rnP2MAGod0R75TtDYV5jMHwnLdzZtJsDLvgf475S8Jd2xEOvumSbuytogh-mQtA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4007, '报纸', '生死关头，是谁凝聚血战到底的力量', '吴杰明', '国防大学;', '解放军报', '抗日民族统一战线;八一宣言;瓦窑堡会议;', '波澜壮阔的中国人民抗日战争，是在抗日民族统一战线的旗帜下进行的。这个战线从九一八事变后开始酝酿建立，逐步发展成为包含中国社会一切不愿做亡国奴的阶级、阶层在内的宏大抗日阵营，最大限度地凝聚起全民族抗战的磅礴力量。其中，中国共产党于1935年发表的“八一宣言”和', '2015-05-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBgclKW0ZVX5dfftHE2Df6Gpqw4oaSXRxvQ7d0yOeF0YcJXd-IOi5eSFQdW4F0-PnWwTssU3_WuGHbPMDl_SQCyBcfWj7Mlcw6X2GtcC5JVzlQnEdddfc80NWJFwUSYTpH1lEVsw6vWIg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4011, '报纸', '国际视野下的中国抗战', '', '人民日报', '人民日报', '中国抗战;世界反法西斯战争;侵略战争;张鼓峰;持久抗战;太平洋战争;中国人民抗日战争;中国共产党领导;', '“伟大的中国抗战，不但是中国的事，东方的事，也是世界的事。”中国人民抗日战争，开辟了世界反法西斯战争的东方主战场，为挽救民族危亡、实现民族独立和人民解放，为争取世界和平的伟大事业，作出了彪炳史册的贡献。 近年来，有越来越多的外国历史学者关注中国抗战的', '2015-05-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB2TwFAdAwT2AirrgcIJuNZlRbS1ygkAejiihr56oFT1JWvl4b2_k9FuEY44_N4B0ktJAjWW2a3ix0TDhhAg6SrgfSHVo4sSmGxqp_K4ckEjr_VeCfSAkwUa3vcEH-grKvgDuXnQNH33Q==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4012, '报纸', '2015文学新书淘宝：四个关键词', '夏琪', '中华读书报', '中华读书报', '文学新星丛书;小说集;村上春树;', '关键词之一 抗战 2015年是中国人民抗日战争暨世界反法西斯战争胜利70周年，在解放军出版社，抗战题材作品更是重中之重的选题方向。据解放军出版社副总编辑张良村介绍，2015年出版的历史题材文学作品有以下几个特点：一是在坚持全民族抗战基调基础上，突出坚不可摧的民族', '2015-01-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICp4CDbzVf6ZyxaXCYx183GcQQC94x2AgLq_K1lVtLudd5P51rCnNabrgTusD6vwUPi5GlRxb5KjWadb8NvsVxpbtZagsanLr8KEadMbOEhUxXbOJGNaCx6mXGIBb4gKKQ33P2dtZbTgA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4014, '报纸', '日本进入反思历史关键节点', '刘军国', '人民日报', '人民日报', '明仁天皇;反思历史;关键节点;', '“日本应该以战后70周年的节点为契机，充分学习肇始于‘满洲事变’（编者注：即九一八事变）的这场战争的历史，思考日本今后走向，这是当下极其重要的事情。”日本明仁天皇1月1日在发表2015年新年感言中如是说。每年新年之际，日本天皇都会向国民发表简短感言，回顾过去一年', '2015-01-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIClX02EnKo43Eoh2q4Z_LU7yf4VnGCxAI5Bp8yC4JiyMJfI0FnhBO5glqZMUmheiSLHURFp3z1YZ2dIClVZEq7EMDiKhFG7010V47wFxn8xSd-C0ghIE9XlXLX_GeuWmovlJOmh0RRGyw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4016, '报纸', '牢记血与火的历史启示', '', '新华社;', '新华每日电讯', '共产党;日本法西斯;中华民族;', '时间可以抚平创伤,却无法抹去记忆。1931年9月18日,日本侵略者悍然入侵我国东北。不愿做亡国奴的中国人民奋起反抗,拉开了长达14年的抗战序幕。“九一八”——“从那个悲惨的时候”起,中华民族开始了走出苦难的艰难跋涉,开启了逆转命运的历史征程。 国破家亡的历史记载着', '2014-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAuHTAMXlgc3rFZZbA1PPyFmOCn5-IgJkFoA46KRYtGODQQj_RfKuFbDtHLiIwuQGr5wplnFTlVicexsIU29EqkM39awB16ujBo5or5PHR1MPIFfNkOEpoH9lpeGDnPbCIdAvPSAevAKg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4017, '报纸', '《黄河大合唱》：最雄伟的抗战呼声', '郭超', '光明日报', '光明日报', '《黄河大合唱》;冼星海;光未然;', '记者：《黄河大合唱》是如何在抗战的烽火岁月里吹起爱国救亡的号角的？ 向延生：1931年日本军队悍然侵占中国东北的“九一八”事变，激起了中国各阶层人士的爱国义愤。以创作流行爱情歌曲闻名的黎锦晖，10月初率先发表了多首通俗抗日爱国歌曲；留学美国归来的国立音乐专', '2014-09-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICZV-RDHv9PXkYvdsFOuwjtzuc4OcCMqk6fWHsMDAI-fI3249VUKTgfi1qVUnahwm_TMfw-9CR4-11RNsd0yC-B3lr3J8SRrl87Gq-SVHHgGkqodYTQ_tt8VqkPK_EjJ7Pf2wd6DOl2Qw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4020, '报纸', '否认历史将重蹈覆辙', '陈效卫; 林雪丹', '人民日报', '人民日报', '日本关东军;二战期间;哈巴罗夫斯克;战争法;人道主义待遇;国际法庭;日本天皇;东北抗联;日本军国主义;', '1945年8月9日，在东北抗日联军配合下，百万苏联红军向侵占中国东北的日本关东军发起猛烈攻击。8月18日，关东军被迫投降。苏联红军为中国人民夺取抗日战争的最终胜利提供了重要支援。 如今，参加过同侵华日军作战的俄罗斯老战士健在的已为数不多。本报记者日前走访了两位', '2014-08-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC_dLGNxsD54gBKDVktLIDShB0Yjrwf00iu74EMt7oNAUHnuDIo3zbBH8f8dOn34zVgnK2Tx86d9aepdYQzgNrDX4EztxgXqIQ2VFAdlM69QbOiEhyIPMxld63rpgn6patruhzRLiVSNQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4022, '报纸', '黑土军魂：一段感人至深的历史', '常雅维; 刘辉', '中国文化报', '中国文化报', '黑土军魂;陈翰章;吉林省博物院;', '吉林省曾是日本侵华战争的重灾区，自去年12月开始，吉林省博物院、东北抗日联军纪念馆推出“黑土军魂”——东北抗日联军军史陈列展，该展吸收了最新抗联学术研究成果，展出抗联时期文物1011件，再现了抗联时期一幅幅生动场景。到目前为止，现场观众留言达4500多条，陈列展官', '2013-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBisXa9Y2FcN1CUjQmB_MVi8mKug78azTh5MDhcdG7gsjMJ4RHFuE5Reb44wuSIXOLaa4WAJ-HADWc-wheKhJvI8ggbq7sqeC9KyVaOiIXjZTlGY1T6UjciLRoASoiDrwA8MRwTiOmtMw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4024, '报纸', '徐宗汉 侠骨柔情奇女子', '茹希佳', '中国妇女报', '中国妇女报', '徐宗汉;同盟会;', '徐宗汉是辛亥革命时期中国知识女性挣脱封建桎梏，走向社会，投入汹涌澎湃的民主革命洪流中的杰出人物。她追随孙中山投身革命，不仅是辛亥革命的女杰，也是近代中国妇女运动的先驱。晚年，她致力于社会公益事业，倾力支援抗战，为反抗日本帝国主义的侵略、拯救中华民族，作出', '2011-10-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID3gXd6feQqr6n2uP3liv45QEN8ojX_Rs9j7JTkcctbnQ332q3jRMWhZquLDJGx4sTqpKNotpME653mxbxbTiO8HLBR0fqEkV8bk3NrbL2JJWpYhrR3tynSMe6izZYX6fN462LjSCJHhw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4025, '报纸', '勿忘国耻 共襄复兴', '', '人民日报', '人民日报', '共产党;中华民族伟大复兴;日本帝国主义;', '帝国主义列强的侵略，可能导致一个国家在悲惨沉沦中亡国灭种，也可能激发这个民族在危难之际觉醒和奋起。 80年前的九一八事变，就是这样一个日本帝国主义蓄意侵略中国的大事件，是日本妄图变中国为其殖民地的重要步骤。短短4个多月内，128万平方公里、相当于日本国', '2011-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB30RpCnP79kUoGFpWbCJeJz7Z4Is71d4IudZlRfB-_DvOck6aHiCt_rhPcSA2QW1qnROMBTYWV94njXJAswnLA5xxgITbxw0uKPvBIa8xviC4D8uH8RedPrh9zM_esRAZWeUtq5a6F8g==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4026, '报纸', '肩负起民族复兴的历史使命', '', '解放军报', '解放军报', '抗日战争胜利;日本侵略者;世界反法西斯战争;民族复兴;抗日民族统一战线;历史使命;', '今年是中国人民抗日战争胜利66周年，也是九一八事变发生80周年。80年前的9月18日，日本帝国主义大规模入侵我国东北地区，开始了疯狂的侵华战争；66年前的今天，以日本政府正式签署投降书为标志，宣告了日本侵略者的彻底失败和世界反法西斯战争的最后胜利。在这个永远值得铭记', '2011-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBu6VaPHwcYoG-pXJxQPYJPpwIsL7_itY3rDkmD2rGJ3U4Eu2fwC93SxBrN2V3N4eelxlSN7e8MKucy5RFwZh2CZc8TFE-Bjy2QJGQe4zpvF53j2xIVGi7mjLq2LoViMKzLc72oayPKDA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4029, '报纸', '雪冷血热中华魂', '孙兆秋 ; 朱天乐', '解放军报', '解放军报', '东北抗联;杨靖宇;', '人物名片 张正隆，军旅作家、抗联史专家，出版10余部长篇报告文学，包括《雪白血红》《雪冷血热》《战将》《战争记忆》《枪杆子1949》。 他们曾被当作“野人” 记者：是什么让您历时20年，走访大半个中国挖掘东北抗联史？ 张正隆：红领巾时代，我就听过杨靖宇', '2011-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIANNEDvGFICevYYY2ksmyc6-1jnaJf4xjJYDMlYlZd_w0CQCNpVNNi4dIQ-GI8hB8acDXSk3iMqvqK0IH9Qsi5_llYGNHAIffDhkLTe5IQjrZBN-kOnxUNs3AdeJkrAa_fAcuyqjTF7RQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4031, '报纸', '拼将热血筑长城', '王经国', '人民日报', '人民日报', '中国共产党领导;战略总方针;东北抗日联军;抗日战争时期;局部抗战;全民族抗战;抗日根据地;抗日民族统一战线;中国人民抗日战争;日本侵略者;', '春暖花开的５月，草长莺飞。 北京丰台区宛平城外，卢沟桥。这座于１１９２年建成的１１孔连拱石桥，以“卢沟晓月”闻名京城，是“燕京八景”之一。让今人难忘的，是它承载了中国人民对抗日战争血与火的记忆。 １９３７年７月７日夜，疯狂的日本侵略者在这', '2011-05-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA-PBo-xkxbj3Y87aRC9vrae6GXNq99Zgo3WoxfIWqwf_yDiqLNyvf6lSnGO0_cFuDw7xytw5_TDvU7MmDyYNOPKXdY813JEuhPoU0llZonMVq3b55-SQiPXI2R-iKtOgduYzC0xa5MwA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4032, '报纸', '同仇敌忾御强虏', '张军; 余晓洁', '人民日报', '人民日报', '抗日民族统一战线;共产党人;抗日救亡运动;日本侵略者;瓦窑堡;杨虎城;国共合作;中华民族;民族矛盾;彭德怀;', '初夏的陕北，山川披绿，杨柳青青。距离延安市区７０公里的子长县二道街秀延河畔一处静谧的农家小院，访客不绝。 瓦窑堡，一个深藏在黄土高原山坳河湾的小镇，因为７６年前中国共产党的一次重要会议，声闻天下、名留青史。在民族存亡的危难之际，中国共产党人以极大', '2011-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDSfWeRTNoqrlrJJUKbsT63PoxEQ_i0NhgsbTa-zJwQw2Si1M5EZFvDTmeVX7lBDRb-SB9FRhXd55954WnG-7v6Iayf8jDcTU8BWKB1llunmBOL3PyJplcc_uDC_uLzv6QP5hx8laPFtw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4034, '报纸', '“坚决革命的同志”董振堂', '', '人民日报', '人民日报', '党中央;中央红军;宁都起义;国民党军;中央苏区;', '据新华社北京３月２３日电　当宁都起义领导人、中国工农红军杰出指挥员董振堂壮烈牺牲的噩耗传到延安，广大指战员无不为之悲痛。毛泽东等中央领导人亲自参加了为董振堂烈士召开的追悼会，毛泽东深情地说：董振堂是“坚决革命的同志”。 董振堂，１８９５年生，河北', '2011-03-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDm7BlpPbDi0EBHUTnb3ZllHUsyDjak2uDRVqDRTQgfPsIe-EatseE88LSYTkLxKIO76JdB3UgvN_d78mimjJtfz-qLm__LSCH4JmtMZvGlqgiUi_sFOQg9NqZa8dYIbVpjp4FIg_RknA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (4036, '报纸', '抗日女英雄赵一曼', '', '人民日报', '人民日报', '珠河县;监护治疗;女英雄;', '据新华社北京3月16日电 赵一曼，原名李坤泰，1905年10月生于四川省宜宾县一个封建地主家庭。1919年五四运动爆发后，赵一曼开始阅读《向导》、《新青年》、《妇女周报》等革命书刊，接受革命新思想。1923年加入中国社会主义青年团，后任村团支部书记，在家乡积极组织“妇女', '2011-03-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDwEx5wTfN5ZdH0OPITHCNVgTYj_pvZ6NNIQRv2P7KvzaqAGBItdN3TE7rlIdV3-eD2wFg7hzcPZ0ahALuWz5O50BmlfAb_j6CSc9wFvFP8lx0Tvgposm9_BjwmJwA8TmvBzoEt2LteSA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4042, '报纸', '骂部下不如共产党，晚年不忘反攻大陆', '李梓雨', '中国国防报', '中国国防报', '国民党;反攻大陆;国光计划;共产党;', '据岛内媒体报道，“两蒋日记”引发蒋家继承权纷争，台湾“中央研究院”近代史研究史所原定2日举行的《蒋中正日记》新书发表会临时喊停，但书中内容率先曝光。  做梦都想反攻大陆  据台湾《自由时报》报道，曾赴美参观过蒋介石日记的国民党党史馆主任邵铭煌透', '2010-12-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIByVBLX9KKJfz3YAqgNfDEHGDqve_kfq5i35WrKqbYcw6Cy-Zc6qGz4JNGE373_PK3k7W5CieBHRqaqXmJDM3mJhM4RKB4V-mLWhz2w_bBQVU6QBFTzS9131jnkajpSMsg3fyzjAsQpiA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4043, '报纸', '全国百名烈士家属受邀参观上海世博会', '潘跃', '人民日报', '人民日报', '上海世博会;优抚对象;', '本报上海9月18日电 （记者潘跃）18日上午，来自全国25个省区市的百名著名烈士家属来到上海参观世博会。中共中央政治局委员、上海市委书记俞正声在参观活动启动仪式上指出，烈士们的精神和遗志，是我们不断推进现代化建设的强大精神动力。我们要弘扬爱国主义精神，勿忘历史、', '2010-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBsiFAA2JYZ7fKyan8l55uQhFHJJSTaSrs_TzZ7614z3f8dZieAnm5HTCD1sLIEtv4hlm6lDPpN30RsmeY8Cn442aZE9Ay_m3z0IgyeM6EsGIP7XNrP6b1UcatJ_o1mA_Tf5pQkwT8MxA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4044, '报纸', '纪念“九一八”,勿忘国耻振兴中华', '徐扬 ; 李克瑶 ; 徐宜军 ; 李建平 ; 毛海峰 ; 李汐萌 ; 常亦殊 ; 岳瑞芳; 张志龙', '新华每日电讯', '新华每日电讯', '东北沦陷史陈列馆;伪满皇宫博物院;防空警报;振兴中华;', '新华社北京9月18日电今天是“九一八”事变79周年纪念日。各地群众纷纷举行活动,表达勿忘国耻、振兴中华的心声。 18日,沈阳笼罩在秋雨当中,“九一八”历史博物馆内人潮涌动。当夜,在博物馆广场前,有数千名群众再次见证,鸣响防空警报,撞响警世钟。 “这是沈', '2010-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDEGHk704EuaQRkaNIFhAymi5Zl-WDoAPI9baxLd6FEkMH87uxhSoZjRkSgaLVRYi0Rvb6IesMk9Shsf-444hqtGsNODoRjWCtPm4J1vscuSNuYDj0Ji0apYMktkF7Sd_NOPOOVKKPnSA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4047, '报纸', '中国公民交国联的“九一八”罪证辗转70多年回国', '徐扬', '新华每日电讯', '新华每日电讯', '刘仲明;伪满洲国;图书馆;', '“Truth”——这是用红色丝线绣在蓝色缎面上文字。布包静静地躺在瑞士日内瓦联合国图书馆的一个角落里,尘封了70多年。当年,有9个中国人冒死将布包送给国联赴华调查团,揭露日军发动“九一八”事变的罪行。 如今,连同布包在内所有材料的复制品,重新回到了中国。9月17', '2010-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICTuSS9hOh996c6D0SqAnQPwVRXrMmvv_R-vatTz4T0bX-2uugPE-4927WiQlrXKnWgfcfOB3DhTg6gVs5zCWXVPJtjWehzC0KeQO-XqU7HL7AD_eSO2TOzu3--6mqrQNpSWPmmhTOq9g==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4048, '报纸', '在纪念中国人民抗日战争胜利65周年座谈会上的讲话', '李长春', '人民日报', '人民日报', '中国人民抗日战争;中华民族伟大复兴;世界反法西斯战争;座谈会;', '同志们、朋友们： 今天，是中国人民抗日战争胜利65周年纪念日，也是世界反法西斯战争胜利65周年纪念日。65年前，中国人民取得了抗击日本军国主义侵略的伟大胜利，维护了国家主权、民族尊严以及人类和平进步事业。在这里，我代表党中央、国务院，向全国参加抗日战争', '2010-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB-eBDM1uzFJsMQs21hq4URAoswWXqHWIxQ2giFx1kxCVqE4iDxPZb6vgo56hDTSrlrl2ZxRPKNbTLA9SSSKRCu6avOB3MbXeamHrBAJcliAYQWm3PD-BVBCSnGNRmHDfaX9-llkGqIKw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4049, '报纸', '抗战胜利：中华民族走向复兴的转折点', '韦伟', '解放军报', '解放军报', '抗战胜利;中国共产党;知识分子;中华民族;抗日民族统一战线;', '历史越久远越清晰。透过65年前的抗战硝烟，今天的我们看到了什么？“抗战胜利，对于中华民族的命运、中国的革命进程、社会形态与结构以及经济发展都产生了深刻而巨大的影响。抗战胜利，使中国从近代100多年来的衰败开始走上民族复兴的道路，对中华民族来讲是一个重大的历史转', '2010-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB0c9HPZQC-BBUmw6CFfE_Qr5GXAu0ilz3X2aM1j6vM3VSyq8Txxw79_4upt-7Wr0MHcfxfUIlxJVy8VFfnfwrhsPW1iGvo8qP1Fwqadu2lMWcBdfrwZX4Rgm4ljaS-mM_noi4vgH12tw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4050, '报纸', '烽火淬炼的宝贵遗产', '武天敏; 蔡鹏程', '解放军报', '解放军报', '人民战争;八路军;国民党军队;淞沪战役;抗战后期;新四军;抗日战争;团以上干部;', '西方军事史学家，曾称马拉松之战是“欧洲出生的啼声”。 毛泽东在《论持久战》中预言：中华民族的解放将从抗日战争中得来。 战争，总是用刀锋书写历史，强制性地伐倒腐朽的旧木，又在战火焚烧过的土地上，催生新的萌芽。 站在新时代的天穹下，用中国军人的眼', '2010-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAzzbzPdrhf0M3qIr-6aKhHZkEQCfBZBr0kIEF9CTQ0G9HVt98DzOEpRJXk2Z5RuwBL3jbbOZ1yjDOH2qaZGPkEfnhgXaSTEKK2J0BBeoJQIt2s5AwmGy_EgfUVlilvfrXR6v3ryC5xhA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4056, '报纸', '为“八一”军旗增添新的光彩', '徐生; 蔡云骜; 欧灿', '解放军报', '解放军报', '军队老干部;新的历史起点;胡锦涛;军队现代化建设;中央军委;中国人民解放军;人民军队;', '8月1日，一个中国军人备感亲切和自豪的日子。  首都北京，雨后初晴。中央党政军群各部门和北京市主要负责同志，各民主党派中央、全国工商联领导人和无党派人士代表，军队老干部代表，已故党和国家领导人以及元帅、大将遗孀，全军英雄模范代表，各国驻华使节和武官，', '2007-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDHfPSlMmbsnZeqvDpeyJ37QRBy2GnzCKtYap2fLhmpWE57nUsb7u4SGVg3m8pDm7hJg0j26mpcAHnjo48uJekZfeSY15izBEp7zfvd7rENkNpN5ZH7CZCtXl7v4DSEw_9EAoyox06Aag==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4057, '报纸', '迎接全国抗日高潮到来的党的全国代表会议和党的白区工作会议(上)', '', '人民日报', '人民日报', '白区工作;中国共产党全国代表会议;党内民主;党的全国代表会议;', '西安事变后，在中国革命进程和国共两党关系即将发生重大变化的转折关头，在全国性抗日战争即将爆发的前夜，为了使全党明确认识当前的形势、任务以及党的政策、策略，做好迎接重大转变的思想准备，中共中央于１９３７年５月至６月，先后在延安召开了两个重要会议，即中国共产', '2006-12-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICYGiXr1xQp8t5Znm8-POHvqtIkgGp8kZ3fQN7LDknJI2ADpqaZhPFtUD8WZVjaWVVrS-uy8VCCh7MUuVpINqhZEPXLtPkQpqC7tQ68TCzhj2Kzsy5uXtIz3mVWea85SVq7KB6NQXUXVA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4060, '报纸', '东北抗日联军的艰苦斗争(上)', '', '人民日报', '人民日报', '东北抗日联军;抗日游击队;游击战争;', '九一八事变后，在东北三省，除各种抗日义勇军外，中国共产党领导的抗日武装依靠群众，直接同日本侵略者进行了极其艰苦的斗争。中共满洲省委指示各地党组织，加强与抗日义勇军的联系，并组织党领导下的抗日武装。从１９３２年起，先后组织了有汉、满、朝鲜、蒙古、回等民族爱', '2006-12-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICLIeSUQv-qOoWOL-cL-NVOONwdhdzDg0fdnnBxkeQRGke3TXq2xPk_a1HSuYY8dQkglHrjgVzoK4F3eBlE1JSJJCAWDM2dZ2RrsB5feReCkT_QO9dFGNwgqmTgHQCCilfD1bJyeqZ7nw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4061, '报纸', '义勇军进行曲', '', '人民日报', '人民日报', '《义勇军进行曲》;反法西斯;义勇军进行曲;日本侵略者;', '１９３１年，日本帝国主义发动震惊中外的九一八事变，侵占中国东北。英勇的东北人民组成抗日义勇军，在白山黑水间与日本侵略者展开殊死的搏斗。１９３２年１月２８日，日军进攻上海，一·二八事变爆发。接着，日军把侵略魔爪伸向了中国华北。１９３３年１月，日军攻占山海关', '2006-12-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB9ucqNJKWxkX6ADVGKT5HNLluC07JgABq4IkCKYUrIKXoxpS92rTEPTxhTTJADYuL9nCvkjipPOV169yCA9tZ1r6lh6FBVxcbZUOXyi7UVL-juewRyh-g2yqDn6K0_ZVESqIObsK9biQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4062, '报纸', '一二·九运动和全国抗日救亡运动的新高潮（上）', '', '人民日报', '人民日报', '抗日救亡运动;冀察政务委员会;国民党政府;日本侵略者;八一宣言;', '九一八事变后，日本侵略者侵占了我东北百万平方公里的大好河山。紧接着，便按照“分离华北”的侵略政策，把侵略魔爪伸向我华北，收买汉奸，鼓动“防共自治运动”，并于１９３５年制造了华北事变，妄图将我华北五省二市（当时包括河北、山东、山西、察哈尔、绥远五省和北平、', '2006-12-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICiTqZZyDEiCeiNOFZR950IsxITAUZxAiKlT-DwMVI32FLGC6aEIIdY0Pz5cLVdnS0-YkjrrhGo0NDr5lrpRKPHolFdvoa58Gb_w12UiKYKBTsmZ7McWltKNLMVLkOSNFsnZE3igSd6mA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4063, '报纸', '长征,民族精神史上不朽丰碑', '冯春梅; 顾鑫; 朱瑶; 程步涛', '人民日报', '人民日报', '主持人;中央红军;精神史;', '嘉 宾： 徐占权 军事科学院研究员 姜廷玉 军事博物馆研究员 陈 力 军事科学院研究员 主持人：长征不仅是一次人类精神和意志的伟大远征，也是一段中国共产党领导优秀儿女寻求民族复兴的伟大征程。无论当时还是今天，这个历程都被许多人当', '2006-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID10BL57pJldcCB_YpEKQMh5KDztecO1j3BSOw5WI_2xV2lf8phZJfkRI8B--JXU97Rs6Vcp7a9ZsRc0Iwr_QpmGbyjX6kOCn4iMeth5x4rakevVD_sEd6B9LTICe-OXqCr4rTnGvqVbg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,夹金山_screened,将台堡_screened,陈树湘_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (4064, '报纸', '缅怀红军魂 励志新长征', '黄庆畅', '人民日报', '人民日报', '红军长征;战略转移;', '７０年前的远征，举世闻名；７０年后的重温，启迪后人。 １０月１６日，北京，中国人民革命军事博物馆喜庆祥和。“伟大壮举 光辉历程——纪念中国工农红军长征胜利７０周年”展览隆重开幕。 红毯引路，走进大气恢弘的序厅，党徽、军旗下的红军战士雕塑，穹', '2006-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICLj2I_3TZNwB6HQ2ZPOjfpuC89_MhbfsFLRHa3101UE5mm3VeA_som-0T2HOFW2LNT0dygElCgPYH16-y66YeYLy8Xe0DO6BzAzICfx5Ymiqq13-y7n-q0HfuIzoUAVbWIKGGMUylkJw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,陈树湘_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (4065, '报纸', '纪念林枫同志诞辰100周年座谈会在京举行', '盛若蔚', '人民日报', '人民日报', '座谈会;全国人大常委会;', '本报北京９月２９日讯 记者盛若蔚报道：纪念林枫同志诞辰１００周年座谈会２９日在北京人民大会堂举行。中共中央政治局常委、书记处书记、国家副主席曾庆红出席座谈会。 林枫１９０６年出生于黑龙江省望奎县，１９２７年加入中国共产党，是中国共产党的优秀党员，伟', '2006-09-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBfGRtbs97AvF1b3LJiCN8XbN5ZWhBrBMDhhF5uPmXZHWCpE1PsKtVkUR8g3OTw38GMhcrQrZG3CJjRiJcGuip0-bZs-8_KkFImVcriom1Vnheo7ktdUcQJ4J-fvHlONnhw2pqtJs3ibg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4066, '报纸', '永远的“八一五”', '贾永; 徐壮志', '新华社;', '人民日报', '长征路上;八路军;红军长征;新四军;', '１９４５年８月１５日，日本宣布投降。  “那一天，是农历七月初八。”对于８９岁的李水清将军来说，６１年前的“八一五”和７０年前的长征会师那天一样，是与生命同样重要的日子。 为了这个令中华民族含泪欢笑的日子，李水清和他的长征战友们付出了太多太', '2006-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAtjNgQ0CRnUulSrMO0XE6vzYjknl2KROTbnjG97MC2W-Xv99_1wbCnqDETcY2645FRLilY9X1YkkEHX3YIs4hTfMPoft091veIWrsI2ETYruw6K6jyH-ZjUCvfVdrMLxdQcfZObBKuRw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4067, '报纸', '张氏帅府博物馆：做足服务文章', '罗信; 周凤文', '辽宁记者站;', '中国旅游报', '张氏帅府;张学良将军;复原陈列;', '张氏帅府又称“大帅府”或“少帅府”， 是北洋政府末代元首张作霖及其长子张学 良将军的官邸和私宅，始建于1914年，占 地306万平方米，1988年建成博物馆开放， 被列为全国重点文物保护单位、省级爱国 主义教育基地、国家4A级景区。  尊重历', '2006-05-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICrFBeI-YcRh-hr2mLpSf51QpBg-ie-9DKUwtcrNc_DjszoToqyo9yARgLLnfLeHPAb14tJhNG3nkCl6dV35_VbSu46q0K3CzwGTiHifqXQeMBxv3WAMEnsAtdcRH5RAH1gV-l49C6ydg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4069, '报纸', '“日本从来没有否定那场战争”', '马晓毅', '光明日报', '光明日报', '靖国神社;', '以冲松信夫为团长的日本日中友好旧军人会代表团日前应中国国际友好联络会之邀访问我国，访华期间，记者对81岁的冲松信夫进行了一次专访。 记者：您为何在如此高龄还访问中国，促进中日友好？ 冲松信夫：我1925年出生在广岛一个贫困家庭，进小学时，1931年“', '2006-04-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAH2odWi0g6232NFL69fOHAoeqzk7PgKERuO7cAIpJf5rSfvJwG-BLBAa2alS46riNXYM-e9JekQA59eoK_GjSiJg_gIBlnH39uT0z-w31yGN96pLvzPaFd5ZpdVHlzF4fUCLZzokJdtQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4070, '报纸', '邹韬奋', '', '人民日报', '人民日报', '国民党;共产党;救国会;', '邹韬奋，1895年11月5日生于福建永安。先后就读于福州工业大学、上海圣约翰大学等。1922年在黄炎培等创办的中华职业教育社任编辑股主任，开始从事教育和编辑工作。1926年接任《生活》周刊主编，以犀利之笔，力主正义舆论，抨击黑暗势力。 九一八事变后，邹韬奋坚决反', '2005-11-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB1dUvhDzqqlww_2HDz1Wa1NzCoVMIcBEjJWcya7vEM8pZhZPt8oUJCOCrSpB7e7hkvz17MaaJyP8sPPvOnzwVsY87VzUsawpzrD18WwZEwT8K0jmWTiqQoUDrc68Tn6WwYMUmPRumquA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4071, '报纸', '何云', '', '人民日报', '人民日报', '《新华日报》;', '何云，原名朱士翘，1905年生于浙江上虞县。1930年8月入日本早稻田大学经济学系，后转入铁道传习所。1931年九一八事变后，他毅然停学回国，投身抗日救亡运动。1932年加入中国共产党。1933年3月，“上海国民御侮自救会”成立，何云任该组织宣传部长。同年6月，被上海国民党宪兵', '2005-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBnMhBoVpp1T0HFFsBpf4d5d3TTPZk0l0054iC5_XrXqsrl9rXnvhuPEBapP2hqrzOnIUyCG6ibfSNChMoJySJJ7ZyC5TAMCA8bp30YZBuGfUU_7_6xoE0vd-0BcUEjizptGPgJEABZdA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4072, '报纸', '李竹如', '', '人民日报', '人民日报', '山东抗日根据地;七君子;', '李竹如，1905年生，山东省利津县人。1927年加入中国共产党。1931年“九一八”事变后，任南京中央大学中共地下支部书记，参与领导中央大学师生和南京各校师生的抗日救亡运动。在国民党反动当局追捕下，李竹如被迫回到山东，先后在济南、平原乡师任教，秘密发展党员，培养出一', '2005-11-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB6OtByclSCfXFFOY-AOwPgMY1ZiXee7xd-V8Be2SJx_2XNkiY-i2GsbpOZdIRy6EuyarfWamEdYeKbV6c116L9Vaz-Ej_BsJLojgN5m3hVRFOFUSHwdYQptmTI7xmQejWPD6qupkEqgQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4074, '报纸', '江上青', '', '人民日报', '人民日报', '国民党;江都县;', '江上青，原名江世侯，1911年农历四月出生于江苏省江都县，1927年考入南通中学高中部，受刘瑞龙、顾民元革命思想影响，当年加入中国共产主义青年团，从此走上了革命道路。1928年夏，江上青转入扬州高中，同年冬被国民党当局以学运骨干分子为名逮捕入狱。1929年6月出狱后，改名', '2005-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBE5VHgfO-NMUfY4TqlAlLuMI2E80OWRYX-rChZWfuEtR8gUDZnDLu6ETRHl3dQRJTaN9VlMc23kpTkzlNggBw_j3AilgwFJeVMHt0_RJwwURNmkXW_iqCME0NBtPWNQk3fyMdU2XaORA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4075, '报纸', '牢记历史　不忘过去　珍爱和平　开创未来', '', '人民日报', '人民日报', '世界反法西斯战争;中国人民抗日战争;', '编者的话 9月26日，中央宣传部和中央党史研究室在北京联合召开学习胡锦涛同志“在纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大会上的讲话”座谈会，就如何认真学习领会、全面贯彻落实胡锦涛同志的重要讲话精神，并用以指导史学研究和理论工作等问题进行了座', '2005-09-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDBXK7W_OPo1j0Kmpse1ngxGwIrl3pb3ypBCpGZ1ifC-WqB4oKAUnnxc_tpiNTxlKIZzGh6dNLEC3K2b16dZr3gNCX_WEUpzC5NNLZYNMk9r2OGGhSTXNeERXB2VRZ6x01X-u2cZsocGw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4076, '报纸', '许晓轩', '', '人民日报', '人民日报', '国民党;抗日救亡;', '许晓轩，1916年出生于江苏省江都市。幼年时因生活所迫，不得不中途辍学，到本地的一个钱庄当学徒。1931年，日本侵略者制造“九一八”事变，强占我国东北三省，全国抗日民主运动蓬勃兴起，许晓轩积极投身到抗日救亡的洪流中。1935年，到无锡公益铁工厂当会计，参加了抗日救亡', '2005-09-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAkXuhMs01kE8Y2ZR84XDF35opRlL3rBOwArVGJ6ngg0poPZuHRUfHea-7TJsGH0zvepHjjerD-TkFnCxGhif0uO64WO2GQZhwzmtZ4ySFd-QehOBzlhoM8ujfT9nCdyRQ8MmBMcKaqUg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4078, '报纸', '不忘国耻　开创未来', '', '人民日报', '人民日报', '世界反法西斯战争;日本军国主义;中国人民抗日战争;中日友好;', '今年9月18日，是震惊中外的九一八事变74周年纪念日。 1931年9月18日深夜，日本关东军自行炸毁沈阳北郊柳条湖附近的一段铁轨，反诬中国军队破坏铁路，以此为借口突然进攻中国东北军驻地和沈阳城，从此开始了疯狂侵华战争。东三省上百万平方公里大好河山，在短短4个多', '2005-09-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBBWLVHeYU-P4Lzqr5M8fve4oM80g9MXD_KSW2VSV9x0n_bboTPI4n2fdaxXrLKJhpG_O9Ts_W_PRICde7qCy9aR-SxP9Z_tqSV6oA12BExAzA4JwoDkangqQjYfM-ygbT6fb-Duh2a8A==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4079, '报纸', '要全面研究14年抗战史', '倪迅; 韩秀琪; 王保纯', '光明日报', '光明日报', '抗战史;史学界;抗日战争;中国共产党;侵略战争;抗日民族统一战线;局部抗战;七七事变;全面研究;', '特邀嘉宾:  李君如（中央党校副校长）  郭德宏（中央党校教授）  林晓光（中央党史研究室研究员）  缘起 过去常讲“八年抗战”，在纪念抗战胜利60周年的各项活动中，常常听到“14年抗战”的说法。这是怎么一回事呢？这是不是抗战史研究的新进展？为了', '2005-09-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDQTVmWLafnToPPl3khpjMyP-WA8YkWhMopFzoV5zOwPEySQkt9VhmIeSCIxXt1mkehd5rMm8kn7EbTOITTZrwZWFTVnP4Bi1nRngTLTw4o0k6MY_GdCZeqis75Y7WAD6UXArMmUxDZyQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4083, '报纸', '继承弘扬伟大的抗战精神　实现中华民族的伟大复兴', '胡振民', '中共中央宣传部;', '人民日报', '抗战精神;中国人民抗日战争;民族解放战争;中华民族的伟大复兴;世界反法西斯战争;日本帝国主义;爱国主义教育;继承弘扬;', '编者的话 9月2日至4日，中央宣传部、中央党校、中央文献研究室、中央党史研究室、教育部、中国社会科学院、解放军总政治部在京联合举办“纪念中国人民抗日战争暨世界反法西斯战争胜利60周年学术研讨会”。这次研讨会是我国学术界和理论界交流、检阅中国人民抗日战争', '2005-09-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAXiHU7PYJ-geaEsAvAIkc53eutyvlxA4rjL-K5nKlDuINihEVtuSeeDWCPusopKmWTgB2fCleEX2SwNA627loPY0fmSdNuy5Hni3gKiJyoghXcoI8U9ycND0CEKyNKUNxDtauCktcVIw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4092, '报纸', '中国抗日战争对世界反法西斯战争有哪些贡献', '倪迅; 韩秀琪; 王保纯', '光明日报', '光明日报', '世界反法西斯战争;抗日战争;反法西斯斗争;', '特邀嘉宾:  李捷（中央文献研究室副主任）  彭训厚（中国军事科学院研  究员、二战专家）  谢春涛（中央党校党史部副主任、博士生导师）  缘起　今年是中国人民抗日战争暨世界反法西斯战争胜利60周年。当下学术界对抗日战争关注的热点之一是:中国', '2005-08-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDWdk8OwC4DBX1Ujg96S_8KUoDU547cJ-KvvGAYeHoFE1nroHsWpaY5nRF6y5L9tM2Rip_bxAnqMRpOtCiW5wFC-nUB0zrcAPRHqnjf9tGujQ5SGvm_4zej6riqR2lDz6pSH_6UKzE51w==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4095, '报纸', '傅作义', '', '人民日报', '人民日报', '傅作义;绥远抗战;百灵庙;', '傅作义（1895—1974），字宜生，山西荣河人。1910年入太原陆军小学。1911年响应辛亥革命，在太原参加反清起义，任起义学生军排长。1915年入保定军校第五期步兵科学习。1924年后，任晋军第四旅第八团团长，第四师师长。1927年参加北伐。次年任第三集团军第五军团总指挥兼天津', '2005-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB3E7siz4f3hKciltPLutn4wrJUZY1-9d0xjFhCprKVqrBz60o1GzTLrvGhInJxOK5OQVIYIOw5GryLKfx-AFjpa7fdkGSDzA5lhmlul-xnhOJifK9mnl5RarFWS49Q3xFGCsQbSs-p5g==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4096, '报纸', '近百台胞青年追寻悲壮历史', '王军; 陈黎明', '新华每日电讯', '新华每日电讯', '台胞;', '新华社沈阳7月17日电（记者王军　陈黎明）参加中华全国台湾同胞联谊会2005年台胞青年夏令营辽宁分营的90余名台胞青年，17日上午来到位于沈阳市的“九一八”历史博物馆，追寻70多年前的悲壮历史。  广场上的残历碑弹孔清晰，来自台湾中国技术学院建筑系的潘泰江缓缓念', '2005-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBWMRhIT2GfwoyHNGQXgd0lCOkT5ML3cxMHkFiIDrHSAqQscNkIzJpRTehu7tWewVEdzsrnG_2t96l0fTFpUh_KHL2wPp-VwVToJZv1ltLshjtY4npoGy4VUuUyxaUuZ0F7wUYWmBQSgw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4098, '报纸', '中流砥柱', '王建新; 冯春梅', '人民日报', '人民日报', '共产党人;日本侵略者;', '在中国西北黄土高原一个名叫延安的地方，那座巍然耸立的宝塔，宛如黑暗中国走向光明的“灯塔”，吸引着无数热血青年奔向这里…… 在《伟大胜利》大型主题展览中，一张张照片、一件件文物、一幅幅画作、一处处复制的景观，生动地展示着中国共产党引领全民族坚持抗战', '2005-07-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDj9pJitvX3EN_ACmhcrYLVAS3tdKEZPMeRtovtb2S5bbPZPcVU69kY2TyodGUq2AfHg74i1DJXhImiKH4sdCEwfmctHUIGCdoFYiMztsDuuqWYDgbUASZA5ic9EoCkSqPHjwixmDS_Dg==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4101, '报纸', '纪念抗战胜利60周年大型主题展今开展', '刘莉; 向杰', '科技日报', '科技日报', '抗战胜利;日军暴行;', '68年前的7月7日，卢沟桥枪声拉开了中国人民全面抗战的序幕。明天，一个名为《伟大胜利———纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大型主题展览》，在位于北京卢沟桥的中国人民抗日战争胜利纪念馆开幕，800余件文物、600余张照片、近40件图表再现60多年前硝烟弥', '2005-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA1UBud9nUbt3-ur7dWAIPSEDnDFeiioOD0o6Lnol2MseFrS-6cU_Jx9dj-d-OsX2m135nGOWpgPYRXL2eVF4edSxfJGlbdQZ0yQC51o7uu4Wym37cMay-sit_Euz6Vk_jfdkNzg1cjBw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4104, '报纸', '正义与邪恶的殊死较量', '潘衍习', '人民日报海外版', '人民日报海外版', '中国抗日战争史;第二次世界大战;', '今年，是中国人民抗日战争暨世界反法西斯战争胜利60周年。解放军出版社、解放军文艺出版社、昆仑出版社，最近推出一系列纪念抗日战争暨世界反法西斯战争胜利60周年的图书，全方位、多角度地再现和解析那段壮烈而辉煌的历史。 这几家出版社此次策划推出的抗战系列图', '2005-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICgJOo9pPoncjUONA2ODB0eYTyNhqCdkRlVEwp7MRM6QemOTcluo5vkFf9_W9tJz181sZPmYlFcOeouaLH_X_GcW-JFUTtzWmOU8Hr2FYsWmdy_c4WyGVlt7d6EzlnzZoSdTTeVMbqEBA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4105, '报纸', '陈翰章', '', '人民日报', '人民日报', '陈翰章;镜泊湖;帝国主义;', '“我立志从事教育事业，目的是为了培养优秀人才，改造国家，使他独立富强。但是帝国主义却不让我们这样做，想把我们变成他们的附属国！”“同学们，假如我的理想因为被帝国主义的侵略而打破的话，我将毫不可惜。为了祖国，我一定投笔从戎，用我手中的枪和我的鲜血、生命来赶', '2005-05-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC7zvmBnCi7OVZi-mUGlCptxjnkoLkI0M2Re3EQQo_ocEIYt6UT5DDD6tmdAc-Mv0QvhbC4jzs71v0FqFM6YPeUFTff408QfQ3RWvDvF8jsaDKNGWdYyPKOD4TSDSAoSdhfYsNx0PtECA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4106, '报纸', '博物馆寻踪', '', '中国文化报', '中国文化报', '故宫博物院;卢浮宫;国立博物馆;大英博物馆;纽约大都会博物馆;', '博物馆溯源 “博物馆”一词，源于希腊文“缪斯神庙”（Museion），原意为“祭祀缪斯的地方”。缪斯是希腊神话中掌管科学与艺术的9位女神的通称，她们分别掌管着历史、天文、史诗、情诗、抒情诗、悲剧、喜剧、圣歌和舞蹈，代表着当时希腊人文活动的全部。 第一个有', '2005-05-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAKiWcDfhAKny9-xMFiiGTAoyEpWgCrR3PaC1dh0ONkyq8GfubrSWQjCbeBDOBhJf-MakKUucjCLxxEPw31KKySsuhPZaFnCxOwcXKA7jQ2E1av999HBtHA9eoehN6wkX60NFaH5IS1cw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4109, '报纸', '东北抗日联军创建人和领导人赵尚志', '', '人民日报', '人民日报', '东北抗日联军;领导人;', '赵尚志是著名抗日将领，东北抗日联军创建人和领导人。毛泽东曾赞扬说：“有名的义勇军领袖杨靖宇、赵尚志、李红光等等，他们都是共产党员，他们的坚决抗日、艰苦奋斗的战绩是人所共知的。” 赵尚志，1908年生，辽宁省朝阳县人。早年投身学生爱国运动。1925年加入中国共', '2005-04-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB0_WD9j0ZuE4ZiBJCucmobMjR_XHS1OtNcYafeQ8bFGnhzLYmazTT5mEcIbnnnlgXNfaHDUgIKp2dHpSN9OLLx4lTZlsnaVtuyKZNYz9ELYfsRKhCwOehMY1lvO1XudyawhIk5zq47TQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4110, '报纸', '著名抗日民族女英雄 赵一曼', '', '人民日报', '人民日报', '珠河县;', '赵一曼是一位著名的抗日民族女英雄。四川省宜宾县人。1905年出身于封建地主家庭。“五四”时期接受进步思想，反抗封建礼教，谋求妇女解放，冲破封建地主家庭束缚，走上争取人民解放的道路。1923年加入中国社会主义青年团。1926年夏加入中国共产党。同年11月，入武汉中央军事', '2005-03-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA44nKJQRcYjlEZy3HnbXrDw692nmI3PR94TmFZk6PtOZ-BKwjpUW1UuV7GWNGdtOze7ZxN8E48ezur07X6k2i8PrYrsECdKfu9VNCYQzirdjBUkW1TD2QcNuOI3YfSZoQMp_Fof-eK6A==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4111, '报纸', '“没有记忆的民族没有前途”', '徐扬', '新华每日电讯', '新华每日电讯', '领导人;《朝日新闻》;', '新华社沈阳12月8日电（记者徐扬）正在热播的电视 连续剧《记忆的证明》的女导演杨阳8日在沈阳说，不能 以忘记历史为代价拥抱和平。  29集电视连续剧《记忆的证明》，是我国拍摄为数不 多的反映二战期间中国在日本劳工悲惨境遇的片子。这部 戏以二战', '2004-12-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBfQCVd2B3W4sLw1slFMitoUojATOSHDrDnq-i4CB2ANLoFZmeQX3TWmF1F3vZcmdzFiSzjdiW2BOzshNBbnpQlh7ljykoWKa0nchi_Que2xo2bLpKY03RyDECQw4bt6M09b6Dv_D-rKQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4113, '报纸', '忠心耿耿　为党为国', '', '人民日报', '人民日报', '刘志丹;革命武装;共产党人;中国工农红军;红二十六军;陕北根据地;陕甘边根据地;武装斗争;中国革命战争;陕甘地区;', '2003年10月4日，是刘志丹同志百年诞辰纪念日。 刘志丹是我党我军杰出的无产阶级革命家、军事家，西北红军和西北革命根据地的主要创始人之一。他一生热爱党、热爱祖国、热爱人民，追求真理，英勇善战，百折不挠，艰苦奋斗，忠心赤胆，为创建红军和革命根据地，为中国人民', '2003-10-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAgd_BvBBWXpN75pTcR9nI3Os6hpNlPMBql2-wWUTu-AFQS82wmNqoXZNfOBu_4cSu24AVI_8ALXMLAFEyuuKZyW35pjVlm0iaQ0sZ5ZKhFyssNFyVjiZSgBDk_UmAPzyIMFqnygnR4CQ==&uniplatform=NZKPT&language=CHS', '九一八事变_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (4114, '报纸', '古稀之年见辉煌', '', '中华工商时报', '中华工商时报', '陈叔通;商务印书馆;梁启超;民主人士;工商界;中共领导人;社会主义所有制;', '开栏的话全国工商联五十年的光辉历程，是和新中国三代领导集体的关心、支持、爱护分不开的。 在开国大典上，和毛泽东、刘少奇、朱德、周恩来等一起登上天安门城楼的有战功赫赫的开国元勋，有为中国人民解放事业做出巨大贡献的民主人士，有民族工商业的杰出代表。黄炎', '2003-09-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAOJWPe790N4RB_sAu2M-ZkOaOmvTzh2zqkv4uFlKcmf-Hu90DNZ4SOHyps4rt0aY9AWG8ay5WwGSFmeB4ZTJfk1ZhzQi9cmt__mJrNnvkpsO2aWI8RCMUnErvOjeypctrQ82CfI-9nww==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4115, '报纸', '那段历史，永不忘', '李术峰; 邬焕庆; 王东明; 孙彦新; 王经国', '新华社;', '新华每日电讯', '抗日战争纪念馆;日本帝国主义;', '以史自励  历史，警醒世人；历史，催人奋进。 在全面建设小康社会， 加快推进社会 主义现代化建设的新的发展阶段，我 们不能忘记中华民族的耻辱日──一 九三六年七月七日。', '2002-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDOPMchm4Y_l6eBjWgEgBrlXuORM6iDxxzexExRE5GxiNy6aKKfSL7rx8gt-8A6gDp4YZxajB_HkBXiLVIhjLXPrqSWKKYsq2_GXNgrt1vlbtTpbY3ux9RvoF4m6L5bbOg2vJvgPpeDLA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4117, '报纸', '试解张学良秘密联共的密信', '', '团结报', '团结报', '张学良;杜重远;联共抗日;东北军;', '据老头儿提出：“牵延到１１月就（会）起变化。这当中一（方）面对内亲外友做‘抗□’的大活动；另一方面，（要）捧大老板登峰造极。只要有半年功夫，大事可济。我要干就彻底干！” “抗□”即“抗日”。联合“内亲”中共和各地方实力派，联合“外友”苏联，准备在西北自', '2002-02-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICxOJ9zXuywT-JHA4xk-gUNBrktgbZ9_0b9pE6gz4cWRk0tdfDXB6rxz0egq9DyTFDhJv2Nw7OaNQW5GSFgPG8qDlCepEbhblDJVubUL9wvmGNFXx-O7ydH5iGmPYVsid-REmtB71YpXA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4120, '报纸', '外交部发言人发表谈话', '', '新华每日电讯', '新华每日电讯', '外交部;', '新华社北 京9月18日电： 外交部发言人 今天就“九· 一八”事变70 周年发表谈 话。全文如 下：  今天是 “九·一八”', '2001-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICnbrBspGZDcHaAuBYIS_yIq7aFQNI1FBBjQaA_gwkrKLW5vRuw7T9ko1J_YCLVsSG8okDGPKuXpRH0gi-oSvOankpHShfV62hO4OgaxzQz7iXi47HY0FPnuyjRdd0elQOGcV-CsfGkMA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4121, '报纸', '牢记历史 反抗侵略', '丁家琪', '人民日报', '人民日报', '右翼势力;日本帝国主义;侵略扩张;“九一八”事变;', '有一首在中国人民中广泛传唱了半个多世纪的抗日歌曲，名为《松花江上》，歌中唱道：“九一八，九一八，从那个悲惨的时候……”这伴随着血和泪的歌声，控诉了日本帝国主义1931年发动“九一八”事变，侵占中国东北三省，继而发动全面侵华战争，残酷掠夺中国人民的罪行。70年了', '2001-09-18 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2001.004684', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4122, '报纸', '一本日军战地画册记下侵华累累罪行', '满学杰; 张亚男', '新华每日电讯', '新华每日电讯', '日军;侵华;', '新华社天津9月14日电（满学 杰 张亚男）在“九·一八”事变70 周年前夕，天津碱厂退休职工张文 荣将自己保存了半个多世纪的一本 “日军（侵华）战地画册”献给国 家。  这本画册长35厘米，宽25厘 米，厚3厘米，搜集了第二次世界', '2001-09-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDnxjdUPZEeEtoUNJxp6TMQz81x9lkIosHWkFE7ex3KA9PJ_iBwuyAId6-wk4kevn-PEKp_mv_ug2FvfHkHLwQ2Hk47u4ylczTj2zDqDueCk2gXv_fBKu9LacLcaPzgiQg3lsy4hyPp5w==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4123, '报纸', '缅怀先烈 重温历史', '李煦', '新华每日电讯', '新华每日电讯', '世界反法西斯战争;缅怀先烈;', '新华社北京9月3日电（记者李煦）今天是中 国抗日战争暨世界反法西斯战争胜利56周年纪念 日。首都各界在北京卢沟桥畔的中国人民抗日战争 纪念馆召开“纪念中国抗日战争暨世界反法西斯战 争胜利56周年座谈会”。', '2001-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBqswCB2VtJx48z1-WiD_-q6G5-IEI31r2GxWrSzTfZqBjsfvHmxQIWD_ttjQcy1AKRH8JzFAEZRfD2Ih1OigX_Kj0g8CI0f4YXNqqMafN9InRLR1pY_BBqkLfBPiw6EXq7aguQAU_FPw==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4127, '报纸', '弘扬“老区精神” 开创新的业绩', '王秋林', '中国纪检监察报', '中国纪检监察报', '老区精神;', '韩光──东北 抗日联军斗争史的 见证人，德高望重 的老革命家。  在纪念建党八 十周年之际，九十 岁高龄的韩老在他 那间简朴的办公室 里接', '2001-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAPza0n6v1DzBKpSDBihwlG0_dAQV8Nhxh96xQ7YcJ9WFCWC4m7rU3C2C_IVT1JQ01Jxn06AeyhxWCyTD2PTJ4M7W_oOhUyagoqR8SJ0ITR4IKoVRDENxGzKKzEOUzzhzpLIwDzrqiEXA==&uniplatform=NZKPT&language=CHS', '九一八事变_screened');
INSERT INTO `ds_article` VALUES (4128, '报纸', '民族歌舞剧《烽火家书》：13封家书抒写有情有义的左权将军', '胡芳', '中国文化报', '中国文化报', '左权将军;《烽火家书》;歌舞剧;有情有义;', '以抗日将领左权将军的13封家书为线索创作的民族歌舞剧《烽火家书》近日在山西太原首演，这是继《太行奶娘》之后山西省左权县推出的又一部红色大戏，同时也是左权县正在打造的“抗战三部曲”中的第二部。 一封封浸透着亲情、爱情、家国情的斑驳家书，一曲曲散发着泥土芬芳和', '2023-09-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ4lLAU4a6P0BHfRz1lvTfPV9euw7k4OacSQqQjrdLjPURVytOPCnt0VlVLi3HAlN3ByNTdHVnemZOd2eLOWbpFXRzMlW-LiK-dX5aBo7w-O-W1g1YKux2LcCB0M7g5GnCmOIRoDqK2_A==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4129, '报纸', '精神与民心的胜利', '李西岳', '解放军报', '解放军报', '志愿军;抗美援朝战争;阿妈妮;战斗精神;邱少云;廖承志;上甘岭战役;', '一 电影《长津湖》的热映，又一次生动再现了抗美援朝战争悲壮惨烈的场景。影片时长近3个小时，镌刻在人心的一个镜头是耸立在崇山峻岭的“冰雕连”——整建制连的官兵全部冻死在阵地上，并且至死保持着准备射击的姿态。那是志愿军的英雄雕像，是其他任何国度的军人都无法塑', '2021-10-28 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006799', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4130, '报纸', '白山黑水铸英魂', '安柏阳; 陈玉博; 石良玉', '解放军报', '解放军报', '东北抗联;杨靖宇;东北抗日联军;陈列馆;中共满洲省委;', '战斗在白山黑水，战斗在茫茫林海 秋意正浓，笔者漫步在素有“枫叶之乡”美誉的辽宁本溪满族自治县县城，看到不少以东北抗联命名的街道、学校、广场。作为东北抗联老游击区和根据地之一，这里曾见证了东北军民在党的领导下，英勇奋起抵抗侵略者的英雄壮举。 走进东北抗', '2021-10-27 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006760', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4131, '报纸', '云南：追寻聂耳足迹 体味家国情怀', '张勇', '光明日报', '光明日报', '《义勇军进行曲》;家国情怀;', '为庆祝建党百年，纪念人民音乐家聂耳，最近，云南省玉溪市举办了2021年“聂耳和国歌”音乐文化系列活动，用心用情讲好“聂耳和国歌的故事”。 很多人不知道，聂耳出生在滇池之滨的昆明老街，家乡在抚仙湖流域的玉溪小巷。滇池、抚仙湖孕育了古滇国文明和云南近现代文明，', '2021-08-23 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.004315', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4132, '报纸', '尚志 白山黑水 英魂长留', '张士英', '光明日报', '光明日报', '珠河县;赵尚志;尚志市;《暴风骤雨》;元宝村;', '英魂不朽，浩气长存。又到一年清明时，在黑龙江省尚志市烈士陵园内，苍松翠柏庄严肃穆，珠河抗日游击队纪念碑高高耸立，来自各地的党员干部、学生、群众到此缅怀长眠在这里的革命先烈。 尚志原名“珠河”，以境内乌珠河命名，是国家级革命老区。抗日战争期间，民族英雄赵', '2021-04-04 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.001693', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4133, '报纸', '百团大战：一座永远矗立的丰碑', '姜军旗; 荣可', '中国妇女报;闽南师范大学;', '中国妇女报', '百团大战;囚笼政策;抗日根据地;八路军;百团大战纪念碑;狮脑山;井陉煤矿;', '初春的狮脑山，仍有几分寒意。百团大战纪念碑犹如一把利剑直指苍穹，阳光下“参加百团大战的烈士们永垂不朽”几个鎏金大字格外醒目。不远处的百团大战纪念馆前，游客正在倾听讲解员讲述80年前这片土地上那场震惊中外的战役。 作为百团大战的主战场之一，山西省阳泉市郊的', '2021-03-29 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.000929', '抗日战争_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4134, '报纸', '抗美援朝文艺：印象与往事', '黄国柱', '十二届全国政协;解放军报社;', '人民政协报', '军旅作家;志愿军;抗美援朝;词作者;中国人民解放军军歌;', '抗美援朝战争是人类战争史上的一个奇迹。 关于抗美援朝战争的文学艺术作品，汗牛充栋，数量众多，成为战争的另一种记忆和叙述。适逢中国人民志愿军抗美援朝出国作战70周年之际，那些在脑海里留下了深深印记的作品及人和事，挥之不去，吐之而后快。 参战者的记录。1953', '2020-10-26 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2020.006440', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4135, '报纸', '陈康容：忠勇为党的女英雄', '陈弘毅', '人民日报', '人民日报', '抗日救亡运动;抗敌后援会;', '新华社福州12月8日电 （记者陈弘毅）在闽西龙岩永定区的红土地上，一个英烈的姓名至今仍被传颂，她就是牺牲时年仅25岁的陈康容。 陈康容，福建永定岐岭下山村人，1915年出生于一个缅甸华侨家庭，侨居缅甸。1930年，陈康容随父亲回国，在厦门读中学，深受革命师友思想影响', '2018-12-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRid2FO-6f9F44GiXMBNjQdlPu3HaAy_4rYb1oC2RHEVulYoXslmW8Ygyhry1DQXdOr7yvvVoYW34BDUXBqnyP1mjitRTxoDsHHZxPigCiX9fpf4upbSrSXT9MJ1a_G1-t2ZAVzL1bLCg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4136, '报纸', '用一生实践真学真懂真信真用', '', '光明日报', '光明日报', '党的事业;共产党人;习近平总书记;马克思主义;', '周智夫的人生如同钻石，每个棱面都熠熠生辉。 部下眼中的他，经历过抗日战争、解放战争，先后参加过大大小小10余次战斗，戎马一生，军功赫赫；家人眼中的他，严格要求子女，节俭和克己到近乎苛刻；朋友眼中的他，无私奉献，一心为组织分忧解难。 在这些棱面的背后，', '2018-04-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQQma4Tj0WYlB8qU7gAK_Y7QYrS1xDaXb4pXzIVPwBn1HKotcS2qjBxeBra-4Q1mok3JcRwe2zgyOQv0v3w9BFg5Qo_ELaJygBnbAD1hUHZrHnlGWn33Ec55Y8h9dh9ezYpyE8QtR29oA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4137, '报纸', '女兵荣光 镌刻军旗', '徐章闽', '南京军区政治部编研部;', '中国妇女报', '女飞行员;两栖侦察;武装力量;海军陆战队;习主席;教导团;精简整编;正规化建设;', '1927年8月1日的南昌起义，宣告了人民军队的诞生，掀开了中国革命历史的崭新篇章。90年来，在中国共产党领导下，人民军队从无到有，从小到大，从弱到强，从胜利走向胜利，走过了波澜壮阔的光辉历程，取得了永载史册的丰功伟绩。期间，女军人为民族的解放和人民幸福进行了艰苦', '2017-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRYCiFZWd4h3jF7WvSdIlrFJZ_ZCfeLLCe9H6rtI3JfjosuU2XCVFjIoNTYPeDNmWPC4krfowbchE3GVshwwMEdYM8eTV7AIJN4nSAUguhX55SMqVK0w1ahKRQl_mI2sBpvoZi3oSWltQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4138, '报纸', '《永远追随》：儿童文学的宏大历史叙事', '', '中华读书报', '中华读书报', '少年小说;历史叙事;《永远追随》;红军长征;儿童小说;少年形象;宏大叙事;小叙事;香花岭;毛主席;柳建伟;乡村少年;儿童文学创作;文学奖;马天来;', '两个少年与他的家人，平静地生活着，他们最重要的生存基础和快乐的来源是一头漂亮的驴子。红军长征经过他们的家，在由疑惧到信任的数日相处之后，撤离时红军借走了那头对他们来说无比珍贵的驴子，却没有按照承诺如期归还。为了讨回如此重要的财产，也出于一时意气，两个少年', '2017-03-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ1IYsT9w3M1XrS0W-drFHg2v-DZsbz3JOW56TSMKC15C1GnGdJt4rPwozfwO428SEDXGG1AF4QtFQNq4xOH411iZ2oU39BZV5Sd9Akv5CAsoDIWjV5nFDK3tzub3FZTVOVftER-HyjkA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (4139, '报纸', '传承长征精神 铸造忠诚警魂', '', '人民公安报', '人民公安报', '长征精神;传承和弘扬;红军长征;长征路上;', '我们的血液里流淌着长征精神 江西省公安厅办公室副主任 孙春涛 长征，中国革命史上的伟大壮举。10年前，我们沿着当年红军长征路线，追寻红军的足迹，倾听老红军讲述当年的经历，用心触摸这段历史，一个个旧址、一条条战壕、一座座纪念碑，逐渐凝聚成一个具象的“长征', '2016-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSHX_mxCPfNF9UNsuOTgDtFYMOY-Rj6I6Xobf67bUUXbsKJ6j5fXTizGrAqB2phOad0iIaC5FXpW4degTrzDEjLM3tT8OcfigzKCSHc74YdGIaBhE6AOF6NSn3gqhH1A0l_hGBvpYEd9Q==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,夹金山_screened,强渡大渡河_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (4140, '报纸', '“没有风格，就是我的风格', '李亦奕', '中国文化报', '中国文化报', '关山月;岭南画派;', '创新精神，是岭南画派前进的动力，也是岭南画派历久不衰的奥秘。作为岭南画派第二代的杰出代表人物，关山月重写生、重艺术实践，始终坚持现实主义创作思想。其艺术生涯几乎与整个20世纪同行，艺术主题也几乎与时代同行——从20世纪30年代的抗日战争到1999年的澳门回归祖国大', '2016-06-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTbubbx94zT49OKhIdN3Ky2e0P3MoLLjIVulSQzZUaTmhBnkff9z3o6U9MJT_5p-p4XKcJIS7j32oNz5xMkjHqjjojtyIRy8LWOiAEbRiT5Tao8UDeTjuDzhIEpJRj6bCHRJhOK0fBXZw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4141, '报纸', '济济一堂叙“范亭”', '张欣然', '中国文化报', '中国文化报', '续范亭;中国剧协;中国戏曲学会;', '由中国剧协、太原市委宣传部、市文化局联合主办的新编革命历史晋剧《续范亭》研讨会日前在京举行。著名评论家季国平、薛若琳、刘锦云、王安奎、周育德、马也、安志强、赓续华、王馗等专家参加研讨会。 续范亭是著名的爱国将领。华北事变后民族危机日渐加深，国民党蒋介石', '2016-03-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTo2_LlD2vyecTDIa2ot8ADUPvbxgDF37ekjtpafjSeQi9fxY1UorlcALSbjKs4pg7GoXkfeJi3gJMmwLigcO9jd8X7knf_p0XtizJJtD4--AKsTHkWrQhYAIbIf66Jj4uOF0urDr9q2w==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4142, '报纸', '世界关注中国军事改革', '张亦驰', '中国国防报', '中国国防报', '世界反法西斯战争;指挥系统;军事改革;', '在纪念中国人民抗日战争暨世界反法西斯战争胜利70周年大会上，中央军委主席习近平发表重要讲话，宣布中国人民解放军将在现有军队员额基础上裁减30万。对此，世界媒体给予了广泛关注。外界普遍认为，此举彰显了中国捍卫和平的信心和决心，同时裁军只不过是解放军即将进行改革', '2015-09-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTdxfU3QLFYVXdRu_R4_OgbWWfz6UQHL8xRbHHnv2H9tmp0Ejv_vrPBuEThUIkGdqE35JKX8E-oHyUkGtWeHgi4WsETyMKMPnzyGdnn0KAXVeiKnznAAreTdftcLnSzuaI7VolU4VTz6Q==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4143, '报纸', '万众一心，前进!进!', '', '经济日报', '经济日报', '《义勇军进行曲》;中华民族;中华人民共和国国歌;日本帝国主义;', '在艰苦卓绝的抗日战争中，中华民族以牺牲3500万同胞的巨大代价，最终赢得了对日本侵略者的彻底胜利。历史记录了中华民族的伟大牺牲，那些在国难中慷慨前行的先烈被后人永远铭记和传扬。历史也见证了中华民族“不做亡国奴”的最洪亮怒吼，以《义勇军进行曲》为代表的铿锵战歌', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRHQcuTk6u6jW8eu6bQcmZUP8ypp7tds5LrUWUrnbQfpOOyc3PYkUZ-ckmqsQ8L9spRN-iUQjW9_hKj6eMvrCtnbdtxi9bxIM7SYPE7GCFr2njqiC4bcTG-W4qkI5AryrEIrTLVjhJYGA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4144, '报纸', '一段鲜为人知的审判有何故事', '张之库; 王伟宁', '人民法院报', '人民法院报', '战争罪犯;日本战犯;判决书;军事法庭;东北行辕;国民政府;', '8月17日，辽宁省纪念中国人民抗日战争暨世界反法西斯战争胜利70周年主题展览在辽宁省美术馆展出。  展厅一角，在陈列东北行辕审判战犯军事法庭（以下简称沈阳军事法庭）审判日本战犯的两张庭审照片和两份判决书的展柜前，不时有人驻足观看。观看展览的三位八九十岁老', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTGSb-PitQQI5kgsE4xESM8WgUUweDBdW3rLkb-7kte8FK9reL_nw2sIMnbVQMTm5OPqLLB9_ky8v5sA_v2YXhvFGfResZOQXH_En283z1uKZYrCPXuRn9O-S0kjGN0AkUgRU4JXiB8vg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4145, '报纸', '从东亚视角看中国“9·3”阅兵的历史意义', '李敦球', '浙江大学韩国研究所;', '中国青年报', '中华民族;朴槿惠;东亚国际秩序;', '在9月3日举行的纪念中国人民抗日战争暨世界反法西斯战争胜利70周年阅兵活动开幕在即，举世瞩目，目的是为了铭记历史、缅怀先烈、珍爱和平、开创未来。中国是二战东方主战场，中华民族在抗战中觉醒，对正在崛起的中国来说，此次纪念活动具有深远的历史意义和重大的现实意义。', '2015-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQtp6EcFu_v8dRWXbJv5WrNw7jUcvoX3H11m6sR53s4hp3NfM0fcp8UFnBUlk_2m9BzsYYRvrdCH3OprW_NYcc5jxtY7HGy1h6Fd3JrDBurE3VHWMB9vVkN26lAl1CwiyVufiaPRbTagQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4146, '报纸', '“八百壮士的英勇传奇在这里永留”', '董少校; 荀澄敏', '中国教育报', '中国教育报', '四行仓库保卫战;爱国主义教育;淞沪会战;', '斑驳苍旧的弹孔、阵容严整的壮士姓名墙、栩栩如生的战士雕像，共同叙说着淞沪抗战的英雄故事……在抗日战争胜利70周年纪念日即将到来之际，8月13日上午，记者走进了这天开馆的上海四行仓库抗战纪念馆。  “中国不会亡，中国不会亡!你看那民族英雄谢团长……”纪念馆', '2015-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRGgJG2R3WNLnXcU0H6TBaDUQPdjarMVzvLrac_5dBqHhiVxsDd7GXeXuxiio-90nYtWZWwTPMNveYwbNI6ii3xocra01DeqwaNPE3YUfzxi5zSx3bAqUuLTvC9Cud_5s4_zBvSI5umxQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4147, '报纸', '抗战文献：让历史“说话”', '张丽', '人民政协报', '人民政协报', '抗战文献;卢沟桥事变;图书馆;民国时期文献;东京审判;抗战期间;', '编者按： 日前，为纪念中国人民抗日战争暨世界反法西斯战争胜利70周年，国家图书馆举办了以“不朽的长城”为主题的馆藏抗战文献展。展览通过翔实的文献史料，引领民众重温抗战历史，大力弘扬抗战精神，展示了文化界人士在抗战救亡、保护中华文明火种方面所作的贡献，也', '2015-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSjp8kLlFJdR-XI3YahvJkkPQjXc3-iBv1jS8DUKJgznPn_zZCt3Va5xMRKTOz_ccaWh3Wb1qQ2LWBf9cgbnm5VtQvsEzjNS3i53HIH65aFXfoc3ERG4FEXBbq6rNg_kT7MmD13g7SbVQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4148, '报纸', '人民是打不破的铜墙铁壁', '', '解放军报', '解放军报', '人民战争;', '七七事变爆发后，蒋介石在谈到国民党军队的抗战时说，敌人的利器是飞机、大炮、战车，我们的利器是高垒厚壁。而毛泽东则坚信：对付强敌，真正的铜墙铁壁是人民，是千百万真心实意拥护革命的群众。后来的事实，印证了毛泽东这一伟大的判断。 日本侵华战争，是倾全国之力', '2015-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSVgBFchcY1qOuo_Ql2rALVEwVT0wmagkAFby1p98hlm09-R68L01urVXQqa3lu2rTYLKqYRLU-2-DRA8nR9kwVq3ph2fMwr_Q4XSu9zi-6H3I0E0EPhQ_Y_Dq2oLttsT58Gf09a2_CHw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4149, '报纸', '红色影像：老照片是最真实的回眸', '张文静', '中国科学报', '中国科学报', '老照片;摄影作品;', '对于中国人来说，20世纪上半叶是一段充满战乱纷扰的岁月。但就在战火硝烟中，仍有一批摄影人，冒着生命危险，坚持用自己的镜头记录着历史的细节。从红军时期、长征时期、抗战时期，到解放战争时期，他们在战火中保留下来的珍贵影像，成为了今天的人们回望那段历史最直观的资', '2015-07-10 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2015.001366', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4150, '报纸', '何建明:记录南京大屠杀，反思比愤怒更重要', '舒晋瑜', '中华读书报', '中华读书报', '何建明;南京大屠杀;日本兵;', '今天的中国比七十多年前强大，军队与装备也强大精良得多，但仅仅有这些还不够，我们中华民族到底应该从“南京大屠杀”的历史悲剧中吸取些什么?这是我要写这本书的目的。  对于作家何建明来说，《南京大屠杀全纪实》是一部不得不写的作品。尽管，在中国作协书记处书记', '2014-12-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSozY89occooedlWXLuFAkUptHuGs-0wIFsFkuc6dU_MYEQ1t5AaSMKkINndn-rrCQpAEm_lclbi_IjMot3dmRtq_WyjOMgh6v1iSs-oIVxtxgoKwJFyviao2Qh3Tf6VBpUTzoowgCfSA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4152, '报纸', '以报国之行 明爱国之志', '王昊男; 曹玲娟', '人民日报', '人民日报', '爱国主义教育;社会主义核心价值观;桔子树;历史范畴;习近平总书记;中华民族;', '引子 爱国主义是动员和鼓舞全体人民团结奋斗的精神旗帜。年初，我国首次以立法形式，将9月3日确定为中国人民抗日战争胜利纪念日、12月13日确定为南京大屠杀死难者国家公祭日；最近，又将9月30日设立为烈士纪念日。以国家的名义向烈士致敬，让牺牲的英烈永远受到后人缅怀', '2014-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTLBrRc5kA8QGV1ARcGLburIifD3Y7Xp7JJ2KpWsKkVot4dhztNJlIj1R2GexenrH-M0jT1Q0hhS-M2IcknppVGQfAo4z61VTiyBoSvOf_S8tviyh8E10IvZA_sP1kXYsfPOu-V0O5vRA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4153, '报纸', '历史是一道“思考题”', '谢颖; 杨雪', '人民政协报', '人民政协报', '甲午战争;冯小宁;思考题;', '编者按： 120年前，中国的大海上波涛滚滚，炮声隆隆，甲午战争战败给中华民族带来空前严重的民族危机。如今，历史已走过两个甲子。 20多年前，一部电视剧《北洋水师》让人们看到了一批仁人志士的拼搏与悲壮；2012年，一部电影《甲午大海战》再现了这场发生在黄海的', '2014-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRM6slurt0WA-puFAVqyLZzrhRlXM9lF2kaa3iKT0SyAWYSn29kEZmQIdmwOS1fhQ2yUOf5fzCi_dbLPiweLl9Db1SLG9txZAUM0-Nng1CDyAPOHowvCxFmRLTGn_rWYWquAopMO95nXA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4154, '报纸', '诗人光未然 黄河的歌者', '梁若冰', '光明日报', '光明日报', '光未然;冼星海;张光年;《黄河大合唱》;《骈体语译文心雕龙》;', '“风在吼，马在叫，黄河在咆哮、黄河在咆哮……” 黄河，以其英雄的气魄，出现在亚洲平原之上，是中国的母亲河，它象征着中华民族奔流不息的民族精神。而1939年，在中国人民抗日战争全面爆发之际，一位英俊的诗人、年轻的革命家光未然，心中蓄积已久的创作激情，被壶口', '2013-11-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTC-OL_TyHbvod04h7JeoR-gotCWwDDHzoijHdIqkzpxZUtYfFRYcTyhSq-00_PevgzS7aUpIJisLnjJLRbq8oM0UyQ0kN9qIzzPWc8sP4qZRqk_ZiZzk0JheuG1jeOt384clxIPmAUsA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4155, '报纸', '真实，自有万钧之力', '任姗姗', '人民日报', '人民日报', '《周恩来的四个昼夜》;周恩来;', '半个世纪过去了，老乡们谈论起周恩来总理在伯延的四个昼夜，仍旧无限感慨和振奋，一切仿佛就在昨天。 1961年，全党大兴调查研究之风。党中央领导人身体力行，组织调查组或亲自深入实际进行调查研究。同年5月3日，周恩来总理一行来到革命老区河北省武安县伯延公社进行调', '2013-08-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTb_RdfhPvm1TUlslWLULAGaET_6x-y4V9AfcI2VAOe0PekzKZhq7NBrL4KQNOOYjSURig-lAdQxYQ1uwt1uKC8wB3olRG_UALzQ1RDLnsLE_2CpzX_tTRjzYT3tpNlTzdIfKkoSlBz9w==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4156, '报纸', '一位鲜为人知的抗日英雄', '张忆文', '中国科学报', '中国科学报', '张灵甫;抗日英雄;南京保卫战;', '张灵甫将军对我来说既熟悉又陌生。早在中学上历史课的时候，印象最深的就是张灵甫的整编74师在孟良崮被陈毅和粟裕所领导的华东野战军全歼。他作为一名内战的先锋，被大书特书，当时对他那是恨之入骨呀。近日无意中拜读了鈡子麟写的《张灵甫传》，才重新客观地认识了他。 张', '2013-08-12 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2013.001494', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4157, '报纸', '卢沟桥如何承载“开发”', '许亚群', '中国文化报', '中国文化报', '卢沟桥;宛平城;丰台区;', '冬日里的卢沟桥别有一番韵味。 宛平、晓月二湖虽已结冰，却扔掩盖不住“燕京八景”的名贵之气。凭湖远眺，对岸的平汉铁路大桥依稀可见。雾霭茫茫中，脑海中不禁浮现起29军当年浴血激战的壮烈场面。 “宛平古城卫京都，卢沟抗战显精忠。”宛平城和卢沟桥，自古以来', '2013-01-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTBR7TBTWy8O4tYCjow3jJPzUB9h79_5LW8xItBnGrmskTZFxnmZeuHlZKXhC54ZX10sM4050TiqZFGdUNFDF7sVnEejY-NIlBAOmM0q9wzFzV9EFDOaAG2QxzNAExOfVrzmKRmRXanzw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4158, '报纸', '罗瑞卿把家规写在墙上', '张萌', '中国妇女报', '中国妇女报', '罗瑞卿;核试验基地;原子能;保育院;', '·人物档案· 罗瑞卿（1906年—1978年），四川南充人，中国工农红军、中国人民解放军、中华人民共和国主要领导人之一；早年入黄埔军校，后加入中国共产党，任红四军政治部宣传部长、红一军团保卫局局长，参加长征；抗日战争期间，任抗日军政大学教育长、十八集团军', '2012-12-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSWpnuUagM4hpucZgRyyErUZ1zxSW1HKVOuitrp87sxZ0aJRCUUE8PpVKr8MjuAUfSehnf_UkTE0o_VWX7xDEUQUSKa2-aAX4kNR5p5xSb38qPwVXJSAZxvhQvs206LePupn5GN1q7ghA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4159, '报纸', '日军眼里的抗联将军王明贵', '萨苏', '中国国防报', '中国国防报', '东北抗日联军;', '笔者在神户收集到的一本日本老兵的相册中，发现了这样一张照片。这是两名日军士兵的合影，在一名士兵的下方还注有“柳江义见”四个字，令人注目的是照片侧面有一行铅笔标注，细细辨认，是“王明贵匪讨伐阵亡”字样，还可依稀看出“克山駅(即日语车站之意)”。笔者由此推测，', '2012-01-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSOUEX-Dgzut7Mf86SS_zCEi0SiCp3t3kxy7waOhgWvfNKf2lT6xVxg_SVTrCB3WH5HcyBF8a2QNEvrG3uPxhLipCvO4hg5ek6sJGGPBgXgBBw1hJ_qm2m2pdrgfFCABzKRzRF1BTFwaQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4160, '报纸', '抗战时潜入日本本土的中国特工', '萨苏', '中国国防报', '中国国防报', '特工人员;地下组织;特工组织;留学生;高性能炸药;抗日杀奸团;', '也许，我们永远无法确定你们是谁，但请你接受后来的中国人一杯水酒的祭奠。只因为温泉关下三百勇士的墓地上有着这样的碑文:“旅人啊，去告诉我们的斯巴达人，我们矢忠死守，在这里粉身碎骨。”上面这段文字，是笔者在写这篇文章时忍不住先写下的。  右图疑为当时在日', '2011-11-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRcSknXJYHtSv_-HVqMpUWgRG5otQiarDm7DDadvw8tahayA2PsSyWn0hM6nR94o7t2fFCMU4feR5KjCo6Y24CA60Km1kfnlP0sB5c7xWtREnlq36PNIrvk9FIYtM_9MG57Wunb_u1SJw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4161, '报纸', '“九一八”启示录', '王玉山', '新华每日电讯', '新华每日电讯', '侵略者;中国共产党;甲午战争;本溪湖;侵华战争;对外扩张;中华民族;', '新华社北京9月17日电(记者王玉山)撩起空荡荡的左袖管,84岁的独臂老人孟淑珍说:“日本兵开枪打的……” 1931年9月18日夜,秋风渐冷,家住沈阳北大营附近的孟淑珍一家突然被密集的枪炮声从梦中惊醒。日本军队要打过来的消息很快传开,孟淑珍的父亲带着一家老小,匆匆离家', '2011-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQraghJPB1-xAaxShwJkXg62BIJqm_f2De9fsaBmWCoPh96ccuGHAyDAFrWb0ksMw511Plvn3xtJO6CDonH8jp9SkloHXv7VtWgMNIMve9x6Qv2x_i5i0TeNQwSB2oEerpKU-FDD64ydw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4162, '报纸', '那场堪称奇迹的文物“南迁”', '王梦婕', '中国青年报', '中国青年报', '庄尚严;故宫博物院;欧阳道达;', '抗日战争期间，13427箱故宫文物的精华被迫运离北平，先至南京，后至西南，分南、中、北三路辗转流离，跨越两万里、14年光阴、1场战争。重返故都时再次清点，几乎无一损毁、遗失。 “这在旁人看来是个奇迹，其实，不过是那时候的故宫人把文物看得比命重，他们觉得文', '2011-08-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSMMSwE7md5KtLFd6rfiAxs8xtE3iM-GjNYt5kbbws7gJx6Nl04isNkFG1igyigxi14YQFPLy1cTw3t2Y0UELSyKSGESGl68n6RfkYiRXPY-oXcvU4LR28spfQ31NrmSB-SGM0TYceZFg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4163, '报纸', '党旗耀煤海', '', '中国煤炭报', '中国煤炭报', '煤矿工人;共产党人;', '有一页历史，照亮了黑暗的岁月；有一页历史，在我们心头铭记。这一天，镰刀和斧头组成图案的旗帜，迎风飘扬；这一天，在地层深处采掘光明的灵魂，有了太阳的照耀。  7月1日，是你的生日!我们的节日!  90年前的今天，起航于嘉兴南湖的红船，为灾难深重的中国点', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQk64wCZxjZThCkejEmO-CMwzLq9vl9j7HA48SHcA0XryhoH4TQ3JiiNlDlRqWx4tqp9HLQ1xoZu-dXBgTxbsEPYm3MXon-Yat4qXLzXixB4-Dj-hbI8LWWcdNxs5C2ZMxsatY7dJJwcw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4164, '报纸', '让生命跨越百年', '李柯勇; 李舒 ; 张汨汨', '\"新华视点\";', '新华每日电讯', '毛主席;新中国成立;', '他是当世仅存的5位开国中将之一。 他是一位传奇英雄,参加过土地革命、抗日战争、解放战争和抗美援朝战争,数十次与死神擦肩而过。 当他还是“小人物”时,就为确定红军长征的胜利方向作出过贡献。党的十一届三中全会以后,在大军区正职级别上的他又做出了令很', '2011-06-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQMLlme25q3oo9hKLWXM6H4i7UBW7vNtnZWdRfUP6AD9jsJfBiFpCO6wWvsRVTeLynf0NrsZ-u0cRQKqLjZzqkd2Pj3IeiklY_nLMAhBqONKSfi8WpwJAmIspbRvRAl_s9zN-YVXsZ6dA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4165, '报纸', '制胜“法宝”：统一战线', '倪逸', '光明日报', '光明日报', '毛泽东;党中央;周恩来;孙中山;共产党员;民主党派成员;中国共产党领导;人民政协;无党派人士;宋庆龄;新政协筹备会;国民党;长期共存;', '统一战线，武装斗争，党的建设，是中国共产党在中国革命中战胜敌人的三个法宝，三个主要的法宝。这是中国共产党的伟大成绩，也是中国革命的伟大成绩。 ——毛泽东 毛主席对我们共产党的许多干部谈：你们每天写日记不要写别的，就只写一句“团结百分之九十', '2011-06-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ6lrVn3kgJxTq2IyhvtxXMuC0ZM6RDpylqqUu3jBkelGSXQ-xFoo29aAoGgnXvHKadhnNGUOYnPTPu0-tlY80y9EheWVeo9ens8SxHU8-dkXmeqrnO5ViJzBNcciShFF8uRsIgzVS9fw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4166, '报纸', '革命情怀故园心', '雷柯 ; 张国圣 ; 周华', '光明日报', '光明日报', '马德禄;武隆县;', '晚餐后，87岁的马德禄在女儿的搀扶下走出家门，沿武隆县芙蓉中路散步，不时有人停下来向他问好：“马叔叔，您出来耍啊。”  疆场青春  （1924—1949） 1924年，马德禄出生于山西长治一个贫苦的回民家庭。1938年2月，日寇侵占长治城，数千名回汉', '2011-06-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRttDW4YpVuBWBaLB-oXka5l0mUTYZHUY-0j3IGmmYDGFqQwClW1B-SV_iRKLXN3rHdr4xjnBhBbWSPG9BNZrT6NHL5I6CHSSqniUCW-uREgeWpdJb8gFhBCltO56GFwC9WjueXejA1Dw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4167, '报纸', '抗战时期,新疆有3条国际运输线', '孙兴维', '解放军报', '解放军报', '共产国际;阿拉木图;抗战时期;', '随着抗战的发展，我海路运输线被敌控制，陆路国际运输线也相继被截断。在这紧要关头，党中央决定在新疆开辟新的国际运输线。 成为抗日战争的“生命线” “当时共有3条国际运输线，成为抗日战争的‘生命线’。”乌鲁木齐边防干部训练大队政工教研室教授阎佩玮，研究', '2011-06-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ4C5NAacpFwtvTqzTbJVYv47-ukBSlCTQTz7lJXquavbJQ7UGOlKvRp0AuObDv2YpQxhK_AT15OO3nP-0pjnN0CicBENot_H_KbjPQ9U1vV0IGndywyQfcdy6N1mE1NSElAZ93w2DKZw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4168, '报纸', '56个民族的力量擎起鲜红的旗帜', '张云龙; 张钦 ; 向志强 ; 周正平 ; 叶建平', '新华每日电讯', '新华每日电讯', '中国共产党领导;共产党;革命斗争;工农红军;马思义;韦拔群;', '中国五千年文明史,是一部中华民族不屈不挠的斗争史。 中国革命的历程,是中国共产党领导各族人民赢得翻身解放、发展进步的壮丽画卷。 值中国共产党建党90周年之际,回望这段波澜壮阔的峥嵘岁月,可以清晰地看到,56个民族的英雄儿女为翻身求解放,建立新中国而', '2011-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTM11-dvg_no8Q5noSov06rWTZraDl6x8ZXpj84pMqcPLrKkUBK9vuDKAthat2_MfX67CadWg3jc5gCZCrJPsBJy5gK-eRkDB-9DgL14e-yZdI-HMrXFM3UfScpiuYBsopUDrGM1h7N-w==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened,扎西会议_screened');
INSERT INTO `ds_article` VALUES (4169, '报纸', '火红炽热的信念 跨越世纪的坚守', '李斌 ; 罗沙 ; 邹伟; 胡浩', '新华每日电讯', '新华每日电讯', '共产党人;钱壮飞;张秉贵;', '是什么,让共产党人始终挺立时代潮头? 是什么,让共产党人始终坚定不移,引领中国航船逐浪前行? 中国共产党成立90周年之际,新华社记者走近一个个普通共产党员,探寻90年光辉历程背后的奥秘—— 是信仰,引领中国共产党人从南湖一叶小舟出发,走过90年非', '2011-06-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTRQm_BQE_cvtfP5pc0iqYN5hT9hUCNaJYKwW5R9sfMiVlVtdRYBZ574AyhHx9E5giLcmHDbRFg8c04H-9ipN0x3h4Tfb7DHOniom-FAG-wN0HaO646wY9pLon-TWWu2-9W4H4-wYD_9Q==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4170, '报纸', '滋养共和国检察官的心灵', '肖玮', '检察日报', '检察日报', '人民检察制度;井冈山;检察人员;革命传统教育;检察官;人民检察事业;王桂五;最高人民检察院;国家检察官学院;', '“夜半三更哟盼天明，寒冬腊月哟盼春风。若要盼得哟红军来，岭上开遍哟映山红……”在岭上开遍映山红的季节，内蒙古自治区赤峰市检察院的检察人员来到革命圣地井冈山，在当年红军伤员牺牲的小井，深情合唱起经典革命歌曲，缅怀革命先烈，重温革命传统。  检察官们不', '2011-06-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSKn7F4EpFTnmcVYGLsyzaXtnl-zEMmj-gso1-DQOmY2BXFrcQSW59hkXl1cTOO89AnzDRJVZkTJUiQAWS-UGRX6nA7XTxsrBnWgZ_IoSgHEWjMjS7vMikCURuBa5lgfM4tTkK3JM1zFg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,黄洋界_screened');
INSERT INTO `ds_article` VALUES (4171, '报纸', '“说实情唱真理”的经典红歌', '李亚红', '新华每日电讯', '新华每日电讯', '曹火星;共产党;堂上村;晋察冀边区;群众剧社;', '《没有共产党就没有新中国》是一曲永恒的旋律,一首不朽的歌! “共产党辛劳为民族,共产党他一心救中国,他指给了人民解放的道路,他领导中国走向光明。”1943年,中国抗日战争进入第六年,胜利曙光初显。然而,国共两党在中国向何处去、中国的命运由谁主宰的重大问题上发', '2011-05-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQqf17ylXtu2Es_Wm31lMWxsX7RNQV6FrbWAL6g5kN9J7gK_UTR8RC2t5Dr7wyKEuvSbQAsD6nR69WsNO_6i8IZnGAR1-_AqsmBxgqqAJEQRrY_ga-Gsoe6crBZVuQxgilmVZ1NoUShTg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4172, '报纸', '武汉见证党史风云', '张天南; 刘念涛', '解放军报', '解放军报', '中共五大;八七会议;毛泽东;李汉俊;陈潭秋;', '就在“红色足迹万里行”采访团队冒雨在井冈山到古田的道路上奔波时，记者作为另一路独立的采访小分队，正在烈日炎炎的武汉寻访。 武汉在中国革命史上是个特殊的城市。中共第五次代表大会以及八七会议先后在武汉召开，国共两党从合作到分裂，大革命从高潮到低潮，都集中', '2011-05-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQqvQgpnBwtbOOad3sHAnRQ3boEmkoWv8ksdsHr6hfoTx12GQnKvPTiMmCzxnzUpXayDa2T8SJFetAbefpABP-IuPKKBGeYrDl1PGmUYEh__m8f4ljqgXjHAn10zzPQnL39KtJIkRjDBA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,秋收起义_screened');
INSERT INTO `ds_article` VALUES (4173, '报纸', '忠诚之路 砥砺前行', '王若冰; 王志波', '人民公安报', '人民公安报', '公安机关;公安部;执法规范化建设;公安民警;山东省公安厅;', '3月24日，山东省公安厅迎来了她70岁的生日。 70年来，山东公安历经战火烽烟的洗礼，经受了血与火的考验，在血雨腥风中前行，在攻坚克难中发展，走出了一条忠诚、爱民、奉献的辉煌之路，为党和国家不同时期的政治、经济、社会发展做出了不可磨灭的贡献。 1941', '2011-03-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRIeY8t_HDXWrqmZG0JdL69QVnuFd0w29qwgqz9ONdif_J6FJxLybQqFlYntSYbm6_E48lyQTH_tTtTyrrmUiLneg5kIiP4AoGp7D259QlRvFqDrV9SXyBaUpdE5QfUf6mpK_USqebbiQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4175, '报纸', '抗日救国民主战士邹韬奋', '', '人民日报', '人民日报', '抗日救国;共产党;国民党;抗日救亡运动;', '据新华社北京３月１０日电 邹韬奋，江西余江人，１８９５年出生于福建永安。１９２３年，负责编辑《教育与职业》月刊。１９２６年，任《生活》周刊主编。 “九一八”事变后，邹韬奋全身心投入到抗日救亡运动中,他主编的《生活》周刊成为国内媒体抗日救国的一面旗帜', '2011-03-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS-a3SCbsCmsi5ZKxaJc9DTcQ5sD2JHg5IHier2j6z4ZI0H_FE_xDEcDffmq5x1IvFM2JTKvthlVhH8qFytFFyXSSnjnOWEHUqa5lq12hVg75buSFm8RZE-xCuo9mxtzTfnEy-Qfn7X-Q==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4176, '报纸', '辛德贝格：一个应该记住的丹麦人', '陈璐', '中国文化报', '中国文化报', '丹麦王国;南京大屠杀;驻华大使馆;奥胡斯;丹麦人;', '伯恩哈尔·阿尔普·辛德贝格，一个看似平常的丹麦人，在南京大屠杀期间做出了保护近两万名中国人的壮举。他勇敢正直的品行和耀眼的人性光辉值得人们永远纪念。为纪念辛德贝格诞辰100周年，2月24日，“丹麦王国驻华大使馆向中国人民抗日战争纪念馆捐赠图书”仪式在北京举行。', '2011-02-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQgDPrlu9twrZWvgWabMQuxj1zTg6AScknp30eiavHmGxZBRdo-cgbP3HIW-YvjG_Uf9qnelHlKsRIhyI07Osrq62rzxYg8XyRPrPJFygc2rZ9hILkiyjaD4WwdnpIqfxfC_4ThKHw1XQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4177, '报纸', '中国人民解放军军歌作曲者郑律成', '', '人民日报', '人民日报', '中国人民解放军军歌;朝鲜人民军;音乐作品;中国人民解放军进行曲;八路军进行曲;', '新华社北京２月２１日电　郑律成，著名作曲家。１９１４年出生在朝鲜全罗南道光州杨林町一个贫苦家庭。原名郑富恩，后因酷爱音乐，改名律成。他的父亲是个爱国者，他的3个哥哥先后为朝鲜和中国的革命事业献出了生命。１９３３年春，郑律成和一批朝鲜爱国青年来到中国，进入朝', '2011-02-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRRL6IOmsWDUtQtx6bCgepT6sJ_HUv8GNeD_Hjz7Gn3DOLPw0QlfhK06mOexz6HW-iBvBnVPFT5G9dWURYJwZarbBZzHA8AgIdCbItjw3CqTaeBit5CL8woldB6uccwR1oSmHbaeDYTBA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4178, '报纸', '今日沂蒙好风光', '宁新路; 李忠峰; 解曙光', '中国财经报', '中国财经报', '标准化学校;革命老区;垛庄镇;中心小学;卫生所;沂南县;专项转移支付;沂蒙山;', '沂蒙山革命老区，在抗日战争和解放战争中，用“一斤粮送红军，一块盐巴给伤员，一个娃儿上前线”号召和动员了100万人拥军支前、20万人参军打仗，其中，有6万多人英勇牺牲。 沂蒙山山系大部分在山东省临沂市境内。全市12个县区和3个开发区都是革命老区县，其中9个县被列', '2010-12-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTlbSOpZvdw8zdsndAQ3nn9epk6KRNU72ZFnVMrgSymu4waPIqVOyQhiN6pqjsZnF6lJMk-fmmt_IWmTQ_VU_tr_gpE_lf7tRLNl8LQxHHhqdewVnw1m-Cf4HF9x1296N4VTwQBmnGFdw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4179, '报纸', '梦在军营报国情', '李华敏 ; 付文武 ; 胡雪锋 ; 张强', '科技日报', '科技日报', '任常伦;广州军区;工兵连;生活费;集团军;', '郑溢祥，广州军区“塔山守备英雄团”工兵连指导员。 他从地方重点大学毕业后，主动放弃年薪10万元的工作机会，矢志从军报国实现人生价值。 他家中多位亲人先后患重病，债台高筑，但他励志精武，建功基层。先后被师团评为优秀基层干部、优秀共产党员、优秀', '2010-11-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQmLjbEC7lQdD5gzndllwTsw37NeNSqcjXGwtTYMdI21qI9POrDwKOnejUG9cKY55CZ32ZCntEMHCg2OWRi6sLgNl_YLsdA7lr5qlW_FJ1paSpsqu-0ToAZNjKHW-Dva-q4VnSbyjD8Sw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4180, '报纸', '抗美援朝,需要铭记的丰功伟业', '牛俊峰 ; 李绪成', '中国国防报', '中国国防报', '抗美援朝;爱国主义;志愿军;朝鲜人民军;', '必须为之的抗美援朝 记者：今年是抗美援朝战争胜利60周年，对于这场援助唇亡齿寒的邻邦和保家卫国的战争，现在不少青年人已不大了解。您能简要介绍一下战争的起因和概况吗？ 徐焰：讲述这个问题之前，人们必须认清“朝鲜战争”和“抗美援朝战争”这两个既有联系却', '2010-11-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQgebaJR94VyVg1ebPOFgm5ayNg45QxDBRjcDYDP1yLIulFTM_5PhS65VNzqmZRyFNym1r7BvHV_HhH0gn8MuHm3lj8bzT1Yb6VBvursgIANWE8eWuS1cNRSy1o9cF1s3tY0KpLliEasg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4181, '报纸', '百余名烈士家属受邀观世博', '潘清; 卫敏丽', '新华每日电讯', '新华每日电讯', '上海市拥军优属基金会;上海市民政局;刘胡兰;民政部;上海世博会;优抚安置;优抚对象;', '18日上午,来自全国25个省区市的百名著名烈士家属来到上海参观世博会。中共中央政治局委员、上海市委书记俞正声在参观活动启动仪式上指出,烈士们的精神和遗志,是我们不断推进现代化建设的强大精神动力。我们要弘扬爱国主义精神,勿忘历史、珍惜和平,为国家富强和人民幸福而努力', '2010-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQHl0CWG6IHPGwPtrb9ZuD0ga2kAuDowCuRPBTyqDglCaxDyUa5kdcDOfa168bVJpxzPe9FJxnwWb01ppU_5PvIY3IdeAkz6P9EL5encKgOKqpYe_TgN274ZNU-p-cwzUgkM2KiHqopmQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4182, '报纸', '勿忘国耻 警钟长鸣', '董强 ; 孙振彪 ; 戴岳 ; 李大勇 ; 梅谛 ; 罗琦; 陈宇', '解放军报', '解放军报', '富国强军;国防教育;', '本报北京９月１８日电 记者董强报道：今天是第１０个全民国防教育日，也是“九一八”事变７９周年纪念日，各地围绕“富国强军，共筑长城”这一主题开展了丰富多彩的活动。 群众参与广泛，活动覆盖面广，是今年全民国防教育日活动的一个突出特点。今天上午，西藏自治区首', '2010-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQL6qhAta5KAl29nnPhTCQb2VRvfHlEsjyNuUvpMwBYWt4trg5ufWd6bdxF0qFAdbSkv0vtjkqPYD-kMtKu9jWwYB-1x2WGm5qshAM8nlZ4VI9t50aPSfS8UpWQsvm0E2WyiHuiVye5-w==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4183, '报纸', '揪心的三小时', '曹冀鲁 ; 刘强', '中国气象报', '中国气象报', '气象台;预报员;', '9月3日是中国人民抗日战争暨世界反法西斯战争胜利65周年纪念日。当天上午，党中央和首都军民在中国人民抗日战争纪念馆隆重举行纪念活动。 3日凌晨，阵阵雷声划破了宁静的夜空，风云突变。日夜监视天气变化的北京气象部门于清晨向全市发布雷电黄色预警信号：未来3小', '2010-09-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRMsbeJqdJEHMPx3ZUHz9ui9qh4ES7PQ8_onopgCaj-Ik7TCpQZnOu7EDpQsFpNzV1_V8hh0uMMymXNF7epeKHBfARA0MckPBVfKIRUBg93iXo6v-kNi4FfLwl30SEFpcPIBRaWLdItXw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4184, '报纸', '台湾光复：抗战史上的辉煌一页', '高吉全', '解放军报', '解放军报', '台湾光复;抗战史;台湾民众;日本侵略者;李登辉;', '抗日战争的胜利，结束了日本对台湾长达半个世纪的殖民统治，使台湾回到祖国的怀抱。1945年10月25日，中国战区台湾省受降仪式举行。这一天也就成为台湾的光复日。记者日前采访了北京联合大学台湾问题研究专家陈星，请他讲述了台湾光复的那段历史及我们今天纪念台湾光复的意义', '2010-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTxNXuD-Jv1dm9TQMT7JZbD7GmAhKyCiZ0alaal3HiY2ZcRzHXWaEh4oi2QI94yFFFwBNfBDTNFfqAOD_8JNYepQJm0vygahbkihC9bHXbvMsVa6DpSiAAYD576DqKN-pT28WNOVmmhTw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4185, '报纸', '《铁道游击队》：激情燃烧的不老传奇', '刘璇', '解放军报', '解放军报', '游击队;《铁道游击队》;土琵琶;', '漫长的65年，足以让人们遗忘很多。但那些反映伟大抗战的传世之作，却时刻唤醒我们的集体记忆：这个民族曾有过怎样的艰难和困苦，又有着怎样的果敢与坚强。 《铁道游击队》就是那棵“记忆树”上一段粗壮繁茂的虬枝。铁道线上游击队员们“爬飞车”“搞机枪”“闯火车”“炸', '2010-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRenPQ9Z86r41Hy_RQtQB7CUuwQlZ-2SfBaGMKpgKjOVmM2Pw2S4023NUCfC6ZGCWssnSXjm58x0jYTv1MCxV5Tjen1XMMsT0SN5qVkNg5NZJFdJTFQxYJJb555I4RDi8zh705zgNuL9g==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4186, '报纸', '他为我们留下的是精神宝库', '齐芳', '光明日报', '光明日报', '钱伟长;梁思礼;钱学森;', '“去年钱学森先生走了,昨天钱伟长先生又走了,想起来心里就难过……”中国航天科技集团科技委顾问、中国科学院院士梁思礼先生的声音哽咽了,他停了停却依然无法继续,眼泪夺眶而出。  平复下感情,梁思礼回忆起了和钱伟长相交的往事。“大概是1940年左右,我在天津耀华中', '2010-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRCt3VyYPwJS3mMWsOrBwIl6_iwFfld3uFyHkS5nlyAW0P8NhJu-igwRX8djp7rxgr0uAa0O5CXELcQ4d-gwHttcbWT2h-85h-j9bfCTaVrKMzArP8Iz2UQJWFHM_e1zE-xGst6lSEHsg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4187, '报纸', '岁月如歌映丹心', '李建文 ; 刘璇 ; 张金玉 ; 李国文', '解放军报', '解放军报', '《党的女儿》;长城长;文学部;歌剧《江姐》;奥运精神;共产党员;作曲家;主题歌;', '有人说，阎肃的一生是不可复制的传奇。但他说，他只是在用一生写一首爱党的情歌。 “一片丹心向阳开” ——对党的无限信仰是他滋养一生的“精神沃土” 这首歌的起始符，是炮火声，有硝烟味，还有苦难与涅槃。 抗日战争爆发后，阎肃一家饱尝战乱之苦，一', '2010-07-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQMKRyzztRz44jq7bMu0hnrVDnCTEt3Yv01g5d-__Xbac6vyh7ZaySUqN4tqg0IcoyT9KaPNB3Fe8WC-esBAOKTpoU6ezDYFSgYziWmxkm5K8kdoep6x54BlULBv1CWtnUol0RuXYMa0A==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4188, '报纸', '“清丰之战”探秘', '萨苏', '中国国防报', '中国国防报', '冀南道;八路军;保安队;反战同盟;杨俊生;', '“清丰之战”是冀鲁豫平原抗战的一次重大胜利，它毙俘日伪军人数多、官阶高、牵涉面广、影响大，使敌人遭受了沉重打击。本期，作者结合中日双方的史料，为您讲述这场战斗中的几个故事。  八路军的战报可能数错了  看中日两国的抗日战争史料，一个印象特别深', '2010-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQlETgcxMVscWcmwwnB221TppZShGam5vWsQTNFyxYpwV3PQkubJWDlRDJf340hPSrqY_8ekFA_FGp4etprnzS6_reIxUV2f--T6coThnA_XWqIuOaY8yaaf3cNdzSdzXV-mrOMPbgHCQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4189, '报纸', '“希望我的谢罪能唤醒日本年轻人”', '屈菡; 毛莉', '中国文化报', '中国文化报', '日本右翼;《东史郎日记》;小泉纯一郎;南京大屠杀;日本首相;侵华战争;历史教科书;妙法寺;', '岩田隆造，一个与当年侵华战争并无直接关系的日本僧人。在过去5年时间里，3次来到中国，为日军所犯下的恶行谢罪。在烈日下，这个75岁的老人绝食、长跪，希望能使战争中无辜的亡灵得到慰藉，使中日两国永久和平，使日本的青年了解历史的真相。然而，让他痛心的是，现在日本右', '2010-06-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRVKVSsXLu9X124mZA6StYNvxJKeGkZ4jpSoql1xjqRDX0h4gGGO3YGKMYFWxDXRqbUP1U0nfGZc0yDCJzX9wu_Y_koiqoUA2P0qkSU7eWv2OCiugMW2EBRjVHCRblc6LQdWgtH0TZh_A==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4191, '报纸', '每个灯箱都有一个故事', '张宗文; 海洋 ; 向勇', '解放军报', '解放军报', '三等功;', '“英雄史灯箱”回眸光荣 走进沈阳军区某防空旅的营区，一个个内容丰富、意蕴深刻的灯箱常常引人入胜。  在一个灯箱前，一群刚下火车不久的新战士驻足观望。“哇，原来咱们部队还参加过抗美援朝呀，有这么长的英雄历史……”这是该部队在“英雄史灯箱”前为新战士上', '2010-01-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRc0fUG7idCDvq2A-9StLI-gOmZNyucBgglhhBdcAmeHyelFnNqyjirzQcv8k2jjBet-aGhO4QJk1amt43QK7SopDKQVzU46lZ_cEmdS9qwEIRkqK_KZ1fy702uj36KkVZvzwxuGB5YLQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4192, '报纸', '师生情 翰墨缘', '', '团结报', '团结报', '于右任;监察院;黄埔军校;', '冯树国，国家一级书法家，大连民革党员。1919年出生，抗战时投身黄埔军校，成为黄埔军校17期学员。凭着对书法的执着喜爱和追求，他拜师国民党元老于右任先生学习书法，成为少数几个学生之一。他是目前于右任在大陆唯一健在的学生。冯的作品与齐白石、吴昌硕、赵朴初、于右任', '2009-12-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtThkDZm67LVFsjrnzLWux-9_VP6y8tMofcdruWdX7RJCk899vnRdgFQ62sBmToZuq7_itwf9wz3sHOuf4xK4yDZovks-QbeThoOH1o5SSB_rI_U9FdL_kLjRlWM0bxGWTu2Rp6WlmYTkg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4193, '报纸', '“地道战”故里演绎新传奇', '夏洪平; 司儆; 王孝建', '解放军报', '解放军报', '焦庄户地道战遗址;临空经济区;顺义区;', '地道战，地道战，埋伏下神兵千百万……”一首《地道战》之歌，曾是几代中国人的集体记忆。 地道战，这一人民战争的光辉典范，如同一座不朽的丰碑，永远矗立在中国革命的史册上。 历史似乎很遥远，却又近在咫尺。出北京城向东北方向行60公里，就到了京郊顺义区龙湾', '2009-11-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRaacm_Qs73Nvne9kk4MlzZ1NRRSPffFxH1OvlVb2-Eg1W8R4AhVqY9pBSR1DWVqKUndqiWPgAJrKwVHlyTPGz_p6JpG3oUKkJw-dO0a9kenMpVIywnUvq1crjldY2LCxbRizp3MSlAKQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4194, '报纸', '中美建交前前后后', '柴野', '光明日报', '光明日报', '中美建交;布热津斯基;外交部;', '柴泽民老先生已经94岁高龄,但在向记者讲起他的外交生涯时,思路清晰,侃侃而谈。早在上个世纪30年代,柴泽民就积极投身抗日救亡运动。抗日战争和解放战争期间, 他分别组织领导了中条山地区的八年抗日游击战争和晋南的三年人民解放战争。1960年,柴泽民从北京市委调到外交部,', '2009-10-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTFv0lutGI1OyIyeXhAtPin_DWg_m8EyWD8IU2WAELyzvVAN1Wc7_ovzx0vCYxbfuOR27Y51qSAEvKsz3XSkUidbDJ6-jydEqLoZodMecuKKYGO2Es6Rc3pnTsv-IOTvc9_w5yWy1gChg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4196, '报纸', '湖南烈士纪念塔增补63位湘籍烈士', '罗晓果', '团结报', '团结报', '烈士纪念塔;湖南烈士公园;中共湖南省委;', '本报长沙讯 （记者罗晓果） 近日，经中共湖南省委宣传部审定，湖南烈士公园烈士纪念塔将增补郑国鸿、毛泽建、谭千秋等６３位湘籍著名烈士，6位湘籍国民党抗日将领也将首次进驻烈士纪念塔供后人祭奠。 齐学启、萧山令、李必蕃、罗芳珪、彭士量、吕旃蒙等在抗日战争中', '2009-09-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRi-0BaS0fyzXSZN-4eQ9Hyf04MeoVFLjyqSjwTGwZjKlE08sYwmzDR-VHXZ86nA4_oi2CHpF8wVldGQxFbloWQIZ3pz9Z1IXaFRs0hkxT93u2hbGoEsR1STDJXFz8c-SiJF66lJUwXhQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4197, '报纸', '黄金水道振兴足音铿锵', '蓝乔', '中国交通报', '中国交通报', '长江水运;内河水运;长江干线航道;内河航运;', '“水坝将使长江上游的水位大大提高，终年四季通航大船。一万吨以上的海轮可以从东海岸上溯1 300海里，一直抵达重庆，使这个内陆城市变成海港……”1 944年，著名爱国实业家、中国航运业的先驱卢作孚先生在赴美国考察期间发表的《中国中心的伟大基地——四川》一文，着力描绘', '2009-09-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRm11i-ysUacdVfhIb3ksFw0yesO-4Blypmu66pGb2Bvpg8_NDAIpRIoxYK_KpbLg7P-rDiofz8j0uz9yzpuOkH3XeSvZ6maXythcwbJBmxg9IGcLlEnq8GZfJjsVhENR90tBkb354CIQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4198, '报纸', '战士的心和他保卫的国家紧相连', '王玉山', '新华社;', '新华每日电讯', '空降兵;开国大典;罗元发;第二炮兵;联合反恐;护航编队;武警战士;新中国成立;抗日战争;刘伯承;天安门广场;军事演习;', '日出东方，叩启苍穹。当首都北京迎来清晨第一缕阳光，有多少滚烫的心，随着初升的朝阳蓬勃跃动；有多少热切的目光，凝望着那面与朝阳共同升起的国旗。  一面鲜艳的五星红旗，交织着中华民族的光荣与梦想。一面鲜艳的五星红旗，凝聚着无数革命先烈血染的风采。 ', '2009-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQtWpiFcwgOSyGX39Vj7mg5pbg6sQkXBADnLXlHSHymPO1az2t0DeiV86SdrRC0w9wjwV_WArpkQ8yDziGTvwg0Ej3CnSjtaLTqxsQVSuPBWDk71uA4meaWWnM5TCVUV2EhOaiQf_K6-Q==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4199, '报纸', '行走在舞台光影之间', '马进; 蔡萌', '中国文化报', '中国文化报', '总设计师;灯光艺术;《大梦敦煌》;灯光设计;电脑灯;东方歌舞团;投影仪;', '2008年8月8日晚，当中国运动员李宁腾空而起，在徐徐展开的画卷中奔向北京奥运会主火炬时，身后画卷中一组组影像与奔跑的身影相得益彰：孩子们的笑脸、传递奥运圣火的人们……极具视觉冲击力的画卷图像让现场顿时安静下来，蓦地又迸发出一片欢呼声。 作为2008北京奥', '2009-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQd3J6dcWojradHXv47gQIF8k0Vzxs6axFMIPnv488JyXgrzgpl69rR9SG2HvJfOqVBAOyrbPCrq_L13fopUPvttgAodCDzExw0TY-DSdo_i3Wj9sPyDo-lmu23Kw84e2rcg1ZjKQo2RQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4200, '报纸', '林海雪原开发红色旅游精品线', '敖蓉; 李己平; 黄力辉', '经济日报', '经济日报', '红色旅游;爱国主义教育;旅游业;杨靖宇将军;旅游接待人数;红色旅游景区;林海雪原;', '相信每一个到过哈尔滨的人，都对那里的街道名称留下深刻的印象。尚志大街、一曼街、兆麟路……抗联英雄们的名字铭刻在街市上，更铭刻在人们的心中。 在哈尔滨，集中展示抗联英雄事迹的场所是东北烈士纪念馆。抗日民族女英雄赵一曼曾在这里遭受酷刑后走上刑场。', '2009-05-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSQsjkDEqLyLG2Ox4xAQ0NGbjnYIvveSU9BoEGAqOIqYJQqkB1rYat_whvJ48-JR3Y4tZAo3despPg7iu8GfwB_47xHZF0o1BGaH0a_85bn2CfMo5ePK6e48Z4_LSmilAZn4iZ5E4bKBw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4201, '报纸', '埋骨异域的抗战英灵,祖国在呼唤魂兮归来', '张汨汨', '新华每日电讯', '新华每日电讯', '拉包尔;巴布亚新几内亚;', '新华社北京3月26日电(记者张汨汨)一篇帖子激起网民关注，从声援到行动，社会各界倾心支持，只为了一个共同的心愿：让遗骨海外的抗日将士叶落归根。  外交部发言人秦刚24日在例行记者会上表示：中国政府高度重视在巴新的中国抗战将士遗骸问题，我们将以隆重庄严的方', '2009-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRTQ7XSnoeZvKtVK-TD5NgpWt9NB6_VyNJ20DZTXJwxaNCPXsQf3pUIvaeKLOVPCiQ0rFJkMrRwgIozCMrT3Cgr4KQDRRCxeKB5adDSZpdjwjonVN0JdIppWMJCBcu7Mmb3phC0pMxKkA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4202, '报纸', '李安民：突破“脑禁区”', '吴菲; 张献怀', '科技日报', '科技日报', '李安民;神经外科;胶质瘤;军队医疗;', '2009年1月9日，中华医学科技奖在北京人民大会堂颁奖，解放军总医院第一附属医院神经外科主任李安民领衔的脑胶质瘤局部治疗新技术与实验研究荣获二等奖。  “如果我们的SCI论文再多些，成绩将会更好。”走下领奖台，喜悦之余，李安民给自己提出了新的要求。 ', '2009-02-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQDQEbt1i1HufuUKNOjlJkna6JDFIwBvS0gvLR6pRXXRzcocLRvdTtUJleBq9n-jYvLBWT2SSVhUyD8c2OjxJwzkqnMHhBAkuZsFq-ALT7wqWXVe_UXHv_g_3N-w9iwn5jlw0FFwE_q2g==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4203, '报纸', '波澜壮阔之革命史', '', '中国民族报', '中国民族报', '大阿訇;革命史;穆斯林;清真寺;马良骏;回民起义;', '可以说，在一定程度上，我国穆斯林的历史就是一部波澜壮阔的革命史。孙中山先生就曾说过：“回族在中国所受压迫最甚，痛苦最多，而革命性亦最强。”  历史上，我国穆斯林进行过反封建、反压迫的斗争,也曾在中国共产党的领导下为新中国而战。1940年，在延安新建的', '2008-12-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQFPDm-Zz9lXkgScI3Ux78WWzdWkkev_ulJS1e9f10b_OxoCLfZ7mHyiOI3FuuKH-kAz-EH_bDBw6N92TGkG_QtuJsdlSj-kSYRIVXDg5C3qlFnqdXKxR4Y_qACvoZ91dy-OOLZeyKaug==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4204, '报纸', '长治：发展民营经济是摆脱滞后的根本', '王秋君; 张华钰; 郝万红', '中华工商时报', '中华工商时报', '民营经济发展;长治市委;潞城市;', '长治，是一个历史感浓重的城市，史称潞州、上党，上党意为“据太行山之巅，地形最高与天为党也”。长治，又是一个英雄的城市，抗日战争时期，这块土地是华北人民的抗日根据地；解放战争时期，著名的上党战役在这里打响。今天，她又是山西省的能源重化工基地，２００７年，其', '2008-11-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSNGN8_WCjDSq7Qb6dLsZMXrEfYYoOBhEp2o_4f-9Vvb7fQf0Fy1qjq0HFciqtIUXawEyAznYABGxbN5zXeYOLmovwDbQp3hyWpL1wQzCu4IAlZM6TcYkn30xyF2L3PV_I5FU3pqOK7Iw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4205, '报纸', '辉煌写在军旗上', '唐先武; 刘德茂; 黄莺; 于萍', '科技日报', '科技日报', '国防大学;人民军队;教学改革;毛泽东;军校教育;指挥人才;办学治校;军事斗争准备;红军大学;中国特色军事变革;中国工农革命军;土地革命战争;', '这是一所从中国工农革命军军官教导队起步，走过红军大学、抗日军事政治大学、军事学院等发展阶段的中国最高军事学府！ 这是一所经历了土地革命战争、抗日战争、解放战争等战争洗礼和社会主义革命与建设的80年光辉历程的中国最高军事学府！ 这是一所在不', '2007-12-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQoJbcpRP5rXQyUcvhrdKzZ1g9fcoGKSYbt4YbwclyrrEF9BALL-95H04UvNCFXuiYxOoAsP-JrxvZXG4-vzJRJGQQkZQVebMMaWKJoLYk3crn0p_S3FQmomXINNPq-K4ewO2c9Ndexbw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (4206, '报纸', '将星从这里升起', '林培雄; 刘德茂; 陈劲松', '光明日报', '光明日报', '中国人民抗日军事政治大学;毛泽东;军事学院;中国特色军事变革;井冈山;国防大学;', '2007年11月，中国人民解放军国防大学迎来建校80周年。 打开记忆的窗户，追寻人民军队院校发展的足迹—— 从1927年11月，毛泽东在井冈山龙江书院创办工农革命军第一军第一师军官教导队，到组建红军大学，从1936年6月，中共中央创建中国人民抗日红军大学,到1937年1', '2007-12-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTnvZ60zahsv1DZVWzm8ktlLB_UFUtl48OLPl5eCKun1e4j0xweAGt8oQb8kJt1HiC2JL_pk3KINejPz7gD6iz0i1UQgAlPuq0SbhHV4uvY8JpE--qdMVf8KGQ7cJK-2mDuuQka_NEirw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,秋收起义_screened');
INSERT INTO `ds_article` VALUES (4207, '报纸', '永远的子弟兵', '向贤彪; 刘逢安; 张建田; 翟耀; 邹波', '全国双拥办;', '人民日报', '抗洪抢险;应急部队;合法权益;华益慰;国防和军队建设;双拥运动;川藏公路;维权工作;军民团结;', '日前，一场新中国成立以来仅次于１９５４年的淮河大洪水，牵动了全国人民的心。在聚集了数万名解放军和武警官兵的淮河两岸，再现着，１９９８年抗洪时的一幕幕——一样的风雨激战，一样的同舟共济，一样的人民子弟兵……军队打胜仗，人民是靠山', '2007-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQCz7FXd-GlSj_c5oDLgdhmino9iWl_TxuycVJpUbRqiD2v4MklK9lPBcbLiWw1cEk-Iw5LJtqX9eTEXxrMg2QFnNdXnRQG53GHWD9KsICaFRWxIe-IZpqQrm9-LwB0JRuOCnPw41MuGA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4208, '报纸', '寻找那段生命的史诗', '王建锋', '人民日报', '人民日报', '红四方面军;长征胜利;曾思玉;毛主席;红军长征;王泉媛;', '为纪念中国人民解放军建军８０周年，我们《寻访健在老红军》摄制组派出６路采访小分队，分赴赣南闽西老区、鄂豫皖老区、湘西老区、川陕老区、西路军蒙难地河西走廊和部分城市军地干休所，寻访健在的参加过长征的老红军。他们当中有曾担任过党和国家领导人的开国上将，也有至', '2007-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSXsiTWpOJgKlOksKvg9daKhl06a4Sp5TVVnm6kKWZzwj61CArWtMO5QHYm_FQ-f3ytLECbHdQOvGrJ3WQF4ORaYHJ8GRwcjNu2zDyWzORGH8k0bL3DAt7tYCCojwokDngv6llHq1i8XQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4209, '报纸', '全国各地举行各种纪念活动', '张舵; 王军; 杨一苗; 陈瑞华; 张宏妹; 蔡玉高', '人民日报', '人民日报', '七七事变;纪念活动;', '据新华社北京７月７日电 (记者张舵、王军、杨一苗、陈瑞华、张宏妹、蔡玉高)今天是“七七事变”７０周年纪念日，北京、西安、沈阳、桂林、南京等地社会各界举行各种活动，纪念这一历史事件。有关人士表示，纪念“七七事变”是要提醒人们勿忘国耻，激励中华儿女团结起来振兴中', '2007-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQTBPey-ahC1kIj-vA20cpKSl6fplZb74-aK5xsmGcf8MR8MqCEO4YQkcmHS_INcWY5oLTJdoPpUqv3pKdVtZwDok1F7laJ9X6BWqDS85AFL29WyI5Nr43UCj7P4L9wQerwN9XtuQoPBw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4210, '报纸', '中国人民抗日军事政治大学', '', '人民日报', '人民日报', '中国人民抗日军事政治大学;毛泽东;', '“黄河之滨，集合着一群中华民族优秀的子孙，人类解放，救国的责任，全靠我们自己来担承。同学们，努力学习，团结紧张严肃活泼，我们的作风；同学们，积极工作，艰苦奋斗，英勇牺牲，我们的传统。像黄河之水，汹涌澎湃，把日寇驱逐于国土之东！向着新社会前进，前进，我们是', '2007-01-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRdijAsjWVXVBUXndN3xI-URUT7h-UnJa72pQEH6tcfqNr9ZwUpNhf3hCQxDlSg1bMdtkH8j7Iy3GQspFS4NY1KOXdEbCEd2ZaMqgABjbPC14-go2k0r_AARY7AdCRzkSuQXVLA3IJIgQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4211, '报纸', '党的新民主主义理论的系统阐述(上)', '', '人民日报', '人民日报', '新民主主义理论;共产党;毛泽东;帝国主义;封建主义;', '１９３９年、１９４０年之交，在抗日战争最为艰难困苦的相持阶段，为了中国的民族解放事业和抗日的民主团结，粉碎国民党顽固派在政治上、思想上的对中国共产党的诋毁，回答中国向何处去的问题，中国共产党人进行了大量的理论工作，特别是毛泽东接连发表了《〈共产党人〉发刊', '2007-01-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR8KGzWRvubAxiXtwIkVQ0k8oCJyiEHJRuY-d52nS48ypzTrh4unF3T0xGmZZknCezwe9Dnh9tRmdXZ9xcjblRVDDymYSLZ7Za9shxo1yAy7RL4WAHHoZSixbcRUwJJISOCQGheuk2bRg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4212, '报纸', '党的扩大的六届六中全会', '', '人民日报', '人民日报', '六届六中全会;王稼祥;张闻天;右倾错误;', '１９３８年９月２９日至１１月６日，党的历史上具有重要意义的扩大的六届六中全会在延安桥儿沟天主堂召开。参加这次全会的有中央委员１７人，中央各部门和全国各地区负责人３８人。这是１９２８年党的六大以来到会人数最多的一次中央全会。毛泽东、王稼祥、王明、周恩来、朱', '2006-12-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQDWqLooLEuV5SojMoaVJeK916--Ee6besuzXjBWtk-iawzewv-jDb5sBCnbDakYPPzIOui1LDVwCUMe3IODqIU9QXq2C0J8Sx7iSfXcWGPRzNP8L0Px4bn_hUfTaR0NdgGCPaVE1qBgw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,项英');
INSERT INTO `ds_article` VALUES (4213, '报纸', '长江古镇李庄 悠悠抗战浓情', '肖红', '中国建设报', '中国建设报', '旋螺殿;中国营造学社;', '俗称“万里长江第一古镇”的李庄，位于西距宜宾市区公路25公里、水路19公里的长江南岸之滨，是我国第二批历史文化名镇。李庄有着近1000年的悠久历史，古建筑众多，其中有最负盛名的“九宫十八庙”和旋螺殿等。在抗日战争时期，李庄以博大的胸怀接纳了辗转迁来的同济大学、中', '2006-11-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTTSOKo3n1xGLwCasC4ZCi4tKATky24eSa-kuyhRCytBfdU2ZVF3V4e6NXawAFXl8sWaP4EMmNbFzVrw3s_TtyO2ocboSqF-ty7BmddD47I9Ckt3FSkGxXNfLCtVgDEpV6pP1EidluFiQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4214, '报纸', '长征精神,长了中华英雄气', '贾永', '新华每日电讯', '新华每日电讯', '长征精神;长征路上;', '70年前的那个10月，从赣南、从湘西、从四川嘉陵江、从河南何家冲出发的红色大军，汇聚在西北黄土高原，汇聚在抗日救亡前线。他们的远征，从此有了一个让中华民族至今为之骄傲的名字：长征。  虽然这支红色队伍当时还十分弱小，病榻上的鲁迅却坚信，这些九死一生的红', '2006-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSF_80hxirBQaSiHoU7nmIdXZI6pmW3EMB7aQ82KCoquHi9qOrmUxYsfVRn1cEWfHvmX_hQ5wV7InZ3aUJ2jHiyKCGvmumfZ1_0Dt9m4caXFG7KIVCwUbMdY8aK807NYvhId7G5twk7kQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,夹金山_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (4215, '报纸', '脚下的土地如此光荣', '徐怀顺', '中国纪检监察报', '中国纪检监察报', '杨玉珍;', 'T长征记忆  兴国，全国著名的苏区模 范县、红军县、烈士县和将军 县。苏区时期，兴国共有23 万人口，参军参战的就达8万 多人，为国捐躯的有5万多 人。是全国烈士最多的县。其 中。有名有姓的烈士达23179 名，牺牲在长征途', '2006-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQuarYbmL0q9udJU07IzusUICk5loRvfBjwS4cLXd-O4g7n0ao1WzE-SDDorsnfXatcCWQs6m-EPAOggfEWVCq7vFHWww9UK70NZGgdr6UgZNyFeWhYQe7H03CnstDPXNNm0Yw7Ue7UHg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4216, '报纸', '中日政冷根在日本', '', '中华工商时报', '中华工商时报', '日中关系;中日关系;', '又是一年“九一八”。 与标志着全面抗日战争爆发的“七七事变”纪念日和意味着抗日战争取得胜利的“八一五”纪念日不同，“九一八”是国耻纪念日。75年前的9月18日，日本关东军突然袭击沈阳北大营的中国驻军，炮击沈阳，同时进攻吉林、黑龙江各个城市。而中国军队采', '2006-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRCIYAu76gNW3nwABDEC7CBKgXtampOY00xhXUEIioG-3IGP8RB0Kcjus2lJcGX87hUyDbsJvrev0mBWEaG6rwaQILBjyFD1Mz-lLjU015DdvHmra-fwVnCeBwJ4XVe79X6Uu-y3-rLCQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4217, '报纸', '纪念台湾光复致敬团祭黄帝陵60周年座谈会举行', '陈键兴', '人民日报', '人民日报', '台湾光复;祭黄帝陵;座谈会;', '据新华社北京９月１０日电 （记者陈键兴）１９４６年，在中国人民取得抗战胜利、台湾回归祖国怀抱一周年之际，台湾同胞曾自发组成“台湾光复致敬团”赴祖国大陆拜谒黄帝陵。时隔六十载，中华全国台湾同胞联谊会１０日在此间举办座谈会，纪念这一充分表达了台湾同胞爱国主义光', '2006-09-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSWox1O_iXadUCjQpNCGjVYoyop3XeSw81wd8upMAkyQxbMzHVt6LfJO5DSlvz3cUSEu8ESWP83EGsVUwPAwtBESHzYDC9HTQbbJplP1zOhtt9kwTPAbIilft6X6GuBskOhXqfvP-ioWA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4218, '报纸', '大匠开风气 后生常仰慕', '王明峰', '人民日报海外版', '人民日报海外版', '欧阳予倩;新剧同志会;日本留学;', '北京张自忠路有座小院，与段祺瑞执政府旧址几步之遥，别样的院门半开着，门上的油漆有些剥落，一排半拱卷式的临街灰砖房早已成店铺，要不是门口嵌着的那块纪念牌，谁都不会想到被茅盾先生誉为“大匠但开风气，后生常仰楷模”的中国戏剧艺术大师欧阳予倩曾在这里居住。走进院', '2006-08-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTERlJdglmDuSxEJWCQt6tHluGACrwiQZ6F5stoVgTroZ3ixvDUxib4yemwIcBBqqtx3amRpF-Jzsk1pVALYdyJ5k00EVplUkzK1kjgGp0CQfZkzv0Dv302CHjI0Yc3MICNvOA2fod3vA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4219, '报纸', '竢实扬华 自强不息', '余长安', '光明日报', '光明日报', '交通大学;', '今年是交通大学建校110年。历史际会造就了四所交大：北京交通大学、上海交通大学、西安交通大学、西南交通大学。与北京、上海、西安的三所交大相比，位于成都、在业内声望显赫的西南交通大学显得更低调，也更平淡。带着对一所培养了茅以升、竺可桢、杨杏佛、林同炎、黄万里，', '2006-05-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTmSdGJMhg8ErTgV8jfqmfQKpVXYhtbbgxKr3I6UQ7vtf2RUQeCALlCIthsf40UEpj6w60wk2m3q8PZFqidsmx1tl519rSJlViIOu6uHU4v2erlPzuAUaNkamVKnk_Z1xtObuc_1apmSQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4220, '报纸', '吴克华', '', '人民日报', '人民日报', '国民党军;塔山阻击战;吴克华;', '功勋卓著的一代战将吴克华在生命弥留之际,仍念念不忘在战争年代牺牲的将士,尤其怀念在塔山阻击战中牺牲的英烈。他留下遗言：“我死后,把我的骨灰撒在塔山上,让我和牺牲在那里的同志长眠在一起。” 吴克华,1913年生,江西弋阳人。1928年在家乡参加农民暴动。1929年参加中国', '2006-04-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS9wSesOzgnyVZQlH40IThmKNqTiJAFuv_-3bWIJnFIK2C_6Kjm2aXQkfQkMyofjqHcmnd9HVo5WvLb0qPl4eJ1sKt5Mt4t2e7hG-dh11sUmPIlaAf1-ZHpNfuhZUCWwyzq8JFt26WloA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4221, '报纸', '董健民', '', '人民日报', '人民日报', '国民党;机要科;', '董健民，女，1923年出生于河北省静海县（今属天津市）。1939年春，16岁的董健民在她的叔父、中共地下党员董秋斯的引导下，与两个姐姐一起渡海南下，辗转参加到抗日救国的行列中。1940年，她们姐妹来到延安，进入陕北公学学习。同年，相继加入了中国共产党。 1941年', '2006-02-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTCsu9q1Ia_FuHIBlgp2UIYKfJfDg-RVpbSBHNeHRCR6sxsLBJ3sp5vPCYO_94R_LY4ARkiSM5n1DeBTSdv428rfztJKCQjKwFrc1lHbXWTVoE4P-DmjtGft1Mvu07AiNL6Ol5WdHimog==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,枣园_screened');
INSERT INTO `ds_article` VALUES (4222, '报纸', '2005：光彩事业三大亮点', '苏琳; 吴志红', '经济日报', '经济日报', '光彩事业;促进会;大别山;民营企业家;', '2005年是光彩事业开展的第11个年头，时光的巨轮走过了一圈，光彩事业走进老区，走入边疆，走出国门。 亮点之一：光彩事业进老区  那里，诞生过3支红军主力，有人统计，在中国工农红军的队伍中，每3个人中就有1个红安人，每4名英烈中就有1位是红安籍，这里', '2006-01-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSzLVwriMzDZ6n-fA7tJ_LvImiImturonh5fXaaxi_ZM6eynH5v5rbKk837UMBQs1BjDpJWWntpUMgQQZmMLWRm9UMmXqkQyr5FdoNL6PETbGL9CcKyYkzjR21tq4Xj9vJ_6QniTZwiQw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4223, '报纸', '联合国纪念日为何不提“南京大屠杀”？', '', '新华每日电讯', '新华每日电讯', '南京大屠杀;军国主义;日本领事馆;联合国;靖国神社;历史真相;旧金山;', '12月17日，美国南加州多个华人团体呼吁当地华人华侨参加一项签名活动，向联合国秘书长安南上书请愿，要求联合国把“南京大屠杀”与纳粹对犹太人的大屠杀一样列为国际纪念日，将中国在二战期间受害历史的纪念进一步推向国际化。  ■联合国纪念未提“南京大屠杀” ', '2005-12-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR19-3e_V_ZNwU-UsEDUMxe0KfOJruW0OhlH26SoOrA9Tw2pmrbZ3fAJKWL1Gl5NfuzluAzTkPxHtPIqUcqoTWF1DSfCRIJo34rVSI2vG1dZ6efQJAHhrEKRrfIMPebC7hvLGNI0a8fRg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4224, '报纸', '张元寿', '', '人民日报', '人民日报', '张元寿;新四军;国民党军;', '张元寿是中国人民解放军高级指挥员。1913年生，福建永定人。1929年4月加入中国共产主义青年团，同年在家乡参加农民暴动，后组织游击队任队长。他作战勇敢，敢打敢冲，被闽西红军和苏区创建人郭滴人称赞为天不怕地不怕的小伙子。1930年春被编入中国工农红军太平区补充团，任连', '2005-11-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ50WF_78r8XcKV0z87hj4s3MmrMTeakhcI-9Gwe-MMAue-D4ZL9tZmtLSfBgYrmzfKBHSYNZStwsJ2UDvGVTTZkVGpbnXMEeUG8Elr9vo57u37GrL0xY_Is2vCBrgL-dZ4hPrYiGAgZQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4225, '报纸', '台盟中央全国台联举行“纪念台湾光复60周年座谈会”', '孙立极', '人民日报', '人民日报', '全国台联;台湾光复;台盟中央;座谈会;', '本报北京10月23日讯　记者孙立极报道：台盟中央、全国台联今天在北京人民大会堂台湾厅举行座谈会，隆重纪念台湾光复60周年。全国政协副主席、台盟中央主席、全国台联名誉会长张克辉，中央统战部、国务院台办的有关负责人，台湾光复的亲历者，来自岛内的知名人士和台湾抗战义', '2005-10-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSzJuQkW3lGHVagM2zt4a9zIDHV40PSy0hg8g4d6BQyqV1D7KWBleZlMbCQn7d3MPBSGTvKtygO2WgcjQJc5qLPM-_W9K7denvpUSsP2RIWtZ2d9ivl4-16MBVqwP0FXysV8WNifA8GcQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4226, '报纸', '月圆夜，更忆当年那个“悲惨的时刻”', '', '新华每日电讯', '新华每日电讯', '侵华日军南京大屠杀遇难同胞纪念馆;重庆大轰炸;济南惨案;', '新华社北京9月18日电9月18日是“九一八”事变74周年纪念日，又是我国的传统节日中秋节。在这一特殊的日子里，全国各地群众不忘国耻，举行了多种形式的纪念活动。  北京：军校新学员入伍宣誓  18日上午，位于北京卢沟桥畔宛平城内的中国人民抗日战争纪念馆迎来', '2005-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRL3azIuA7sw-ueTCo1iICcUPKIA3B_Da3SV6EG90I-Ige56Nh-LsGpnsv56G3MLT9ogTAyWJG8SSDEU0ZU67yt0VL9UEMHRyRWHBnoVDpnDXxFPlPGtYpUVNouIBOs_OR9T-RXTFLUoQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4227, '报纸', '胡锦涛讲话对维护地区和世界和平意义重大', '赵毅', '人民日报', '人民日报', '胡锦涛;中国与日本;中日关系;意义重大;世界和平;', '新华社华盛顿9月6日电　（记者赵毅）中国国家主席胡锦涛9月3日在纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大会上发表的重要讲话引起美国华侨华人的热烈反响。他们认为，这一讲话是在关键时刻发表的一篇重要演讲，对维护地区和世界和平具有重要意义。 美国', '2005-09-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTgViTna6wA3gdlLvBqWf3n09Ug2UmOzv7kMe9vm9gYBIpMxulPBR9yTCIXd86SgaqHNeP8JTiVs2Qp_2TnOk-u9-fcNhclNUhsClR_yGLX1legKBwUxsgi-nC1f2uMwMlBY3hvWqzUdw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4228, '报纸', '《永恒的记忆》大型画集在京首发', '', '中国文化报', '中国文化报', '世界反法西斯战争;北京市;《永恒的记忆》;“海派”;上海美术馆;', '本报讯　9月1日，由北京市文化局、上海市文广局联合举办的《永恒的记忆——纪念中国人民抗日战争暨世界反法西斯战争胜利60周年京沪美术联展作品集》首发式在北京举行。北京市副市长孙安民出席首发式并讲话，他对京沪文化界首度合作的这一系列大型主题性美术活动所取得的成效', '2005-09-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTjZtZ9J8w7W3ocbrIe6dhae_6W7Biipt-t3SJEcvHeoomLEl1WnHvxXMPslgSFHUx1wCP-Uz4_xv6FNbvao-AHBOhnni8wmTx1-FMPWi6TykNEUfMcE362otdGg0YaM0MKKEpVjbaHYQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4229, '报纸', '欧阳山尊：抗战导演不老心', '苏丽萍', '光明日报', '光明日报', '欧阳山尊;', '欧阳山尊　1914年生于湖南浏阳。自幼受父亲欧阳予倩爱国主义和进步文艺思想的熏陶，学生时代即参加进步演剧活动。1938年赴延安，1939年加入中国共产党。1939年至1945年编导、演出了许多反映敌后斗争生活的戏剧作品，1945年至1950年到国统区担负文化统战和宣传解放区的任务。1', '2005-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQuL8uC9d3wUpn_M2tie_JpnB-6EmfcPoSH7td1J8EcidCyLV_KHQE7LZdiuJ4OwWM96R4110Tk8qA8mlPoBlS7uKeBqin3R9_pz0koeSJ1Tkvf3-oSeZQ9LoOKWA7g2-Gagoor-7ouRQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4230, '报纸', '唇齿相依　共同抗日', '徐宝康', '人民日报', '人民日报', '光复军;光复会;', '1945年8月中旬的一天中午，设在中国安徽省河溜地区的第10战区司令部附近，传来了一阵阵“劈啪、劈啪……”爆豆般的枪声。时任韩国光复军第三支队河溜联络处负责人金国柱正在司令部附近吃饭，听到枪声立即准备迎击日寇。身旁的中国连长金召激动地告诉他说：“日本已宣布投降。', '2005-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQgiBQ09HRlP7mgQWPdcDyN2wX8qhwqN16sl0O4EXuL0xlWNNkIcYJH7KM64Reo2B2InAhBKQcAxM5L-Z_W4TRphnCSIrK606UoSQOu_QFf-g2HNcoEsrbNxBZHiTI-x-0VK6JFxxoyLg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4231, '报纸', '许光达', '', '人民日报', '人民日报', '抗大;抗日军政大学;', '1955年人民解放军实行军衔制时，根据许光达对中国革命和军队建设所作出的贡献，中央军委决定授予他大将军衔。他得知后，主动给军委主席、副主席写信，请求降为上将衔。毛泽东看罢，激动地说：“这是一面明镜，共产党人自身的明镜。500年前，大将徐达二度平西，智勇冠中州；50', '2005-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQOlUD9K-KY5CAi5XBrV2wJmTZCMq9eLvQlt67YaSN2MHIwgVHbVI0cCLzaueJNbDyEWcaoeXBMgLN18ix3Z59C49CSmlGjuWh39KVbmsLVxwL8zk5KiZUeEklyydTZTpvOLFCvsthVMw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4232, '报纸', '中美抗日老战士，60年后忆当年烽火岁月', '徐松', '新华每日电讯', '新华每日电讯', '驼峰航线;', '新华社北京8月31日电（记者徐松）由中国人民对外友好协会、“华夏文化纽带工程”组委会和美国美中航空历史遗产基金会共同主办的“美国二战飞虎／驼峰老兵中国行”活动在北京拉开序幕。100多名应邀来华的美国老兵及其亲友31日下午与中国老将军、学者和各界人士一起回顾当年的', '2005-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQIXoIcKjpmI0IbA_IKwXF97_WeYa3mybjf27VjKtmolLjTuBdIvkeeGpcDZHxOLqq6cmPR7Bes-14kb3609H90KZcazDU5mYTAIkkWoJW0Dvx7eKg1DT36IHS_p48VBr67hJ4UGEvlSA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4233, '报纸', '万人将向人民英雄纪念碑献花篮', '谭晶晶; 陈键兴; 张晨', '新华每日电讯', '新华每日电讯', '世界反法西斯战争;党和国家领导人;王国庆;人民大会堂;国际友人;纪念活动;中日关系;国民党军队;人民英雄纪念碑;', '新华社北京8月30日电（谭晶晶　陈键兴　张晨）中国将于近日举行大型活动，隆重纪念中国人民抗日战争暨世界反法西斯战争胜利60周年。  记者30日从国务院新闻办获悉，党和国家领导人及各界代表1万人将参加在天安门广场举行的向人民英雄纪念碑敬献花篮仪式，中国政府还', '2005-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ0E0OrIm8oY7klPk1qn4TGBjZwFiHrb-zuCVI6QdZHrYRsbFkWieGk4OX6jmDUKUug6QxKPeI-sJmrllX_a12HwepXHnSlNQuYBfkLXoNVsyGMWtP99LWPSGIDUfEtfUl2XCi0UxmlxA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4234, '报纸', '田沁鑫：厚重铺就话剧底色', '徐馨', '人民日报', '人民日报', '田沁鑫;国家话剧院;《生死场》;', '几天来，正在北京上演的一部话剧场场观众盈门。这是为纪念抗日战争胜利60周年、根据萧红名作《生死场》改编成的同名话剧。该剧1999年首演，曾获得中国艺术最高奖“文华大奖”、戏剧文学奖最高奖“曹禺文学奖”等多项国家级大奖，成为当年话剧界的奇迹。6年后的今天在首都的舞', '2005-08-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSWFzl8sc__-v0YluPrbaM5CMkcMpATTlPGGTVjUOSVRm_BBnL7OhnchdOu6rFkY2_Wp1ll7fl_TTqY2k5ley55ePYgFkTY4xEK_Wm8mF1k9dhcEaCUN7vT3myKZJ-xW2Mhyc6c5ZWUww==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4235, '报纸', '蒙山沂水情谊长', '刘贵和; 孟斌; 卢军; 费士廷', '中国国防报', '中国国防报', '沂蒙精神;临沂市;优抚对象;', '8月16日，中国国家博物馆中央大厅里人头攒动。由山东省委、省政府主办的《沂蒙精神大型展览》深深吸引了首都各界群众。  临沂地处著名的革命老区——沂蒙革命根据地。这个根据地经历了抗日战争和解放战争两个时期，是全国影响最大的革命根据地之一。战争年代，沂蒙', '2005-08-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSBoHp-GTUDh_PJvmjEgJnLcokJlbAmLKsthoox-KAxsYMlS7i1oF69-45raUrW4lISxpQeGHKaVv_K2_ErYPQbqqwG5Cl64ClFjUEuFQ7KFDKSS6x5PSNvAr1bH1nC3XhLVY9Xt9tDPw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4236, '报纸', '樊建川：个人建抗战博物馆', '叶紫', '人民日报海外版', '人民日报海外版', '矶崎新;大邑县;', '48岁的收藏家樊建川，已拥有200多万件藏品。其中，4万多件抗战文物是他的心爱之物。在四川省大邑县安仁镇，他以一人之力，建起中国最大的民间抗战博物馆，并定于今年8月15日抗战胜利纪念日开馆。 ●名人题写馆名 这个博物馆约有2万平方米，分为8个分馆，分', '2005-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSERspysXVxytbBf0yheXO_M0HeSiQdEN4EaNejpPV8s_L6Ah4Iy5KFortbq5t-GuYQaV7GSTPaLN_AYkApyxUC9g7tj2t5OV4xIcXEF71ChPNS7n_aghFTf-kcaYDtHbxuwr2LCnJHAg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4237, '报纸', '开创中国雕塑的新局面', '韩小蕙', '光明日报', '光明日报', '中国雕塑;纪念性雕塑;雕塑家;', '前一段北方大热，然而，在长春世界雕塑公园里，还是人头攒动，休息日更多达10几万观众——是“和平·繁荣雕塑巡展”把他们吸引来的。如今，雕塑巡展已到了第二站南京，人们观展的热情和连日的高温一样不见减退。  “和平·繁荣雕塑巡展”是中国美术家协会为纪念抗', '2005-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRYDBluhfhYXzxbp_7PBb6zZ9egBlTvvEdF87xbbVBX2jp5v6dFPA4bIPj7j__Grez4qTUFlbibkZCPiJmxbZYbgPiSMxQUeLaOr_yFsBvSza8EJHYvZ3Ok2ozvFeGvBtBN_aS00SmmeA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4238, '报纸', '新党大陆访问团抵穗开始民族之旅', '陈斌华; 车晓蕙; 范丽青', '新华每日电讯', '新华每日电讯', '抗战胜利;中共中央台办;国民党;李登辉;', '新党纪念抗战胜利60周年大陆访问团6日上午离开台北，经香港转机后，于下午2时40分抵达广州白云机场，开始名为“民族之旅”的大陆访问行程。  有很多回忆的历史时刻，可让我们记住我们必须团结起来  新党主席郁慕明在抵达机场后表示，新党追随国民党主席连战、', '2005-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQHxfIyCyA3tc8uyFHm8TuUUaTFC455o-Ugd43MrFBLJD0zTScFLokNGgiNEUXYFyAlPc758xmrXGBoeKp6UUr5oNA69MYy4kE3etKwZF2eCuYw1xa79lvdYT641iodnjobjTO_Ux7o2A==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4239, '报纸', '日军轰炸60多次，可就炸不毁贵州盘江桥', '周之江', '新华社;', '新华每日电讯', '盘江桥;晴隆县;', '二战期间闻名遐迩的“二十四道拐”盘山公路，作为当年滇缅公路的延伸线，为抗日战争的胜利做出了重要贡献，成为中美关系的历史见证。日前，记者来到贵州省黔西南布依族苗族自治州晴隆县，重访这条“历史的弯道”。  一个流传近60年的误会  上世纪80年代起，现', '2005-07-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSmLbxwTOpHfI7pHOaRmY4Et64oeUEyIkppO5XIff5oOaVmYYYIbGQ7nUYW3kcD9RfkXjjZsFg8-UTZa0hyahkqmObYgxhxIXBxo1MQ9U_PZwMaB3t_Xtjg6ydi1-iLUOoAwZGUxp0YBw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4240, '报纸', '巍巍太行　历史永铭', '刘维涛', '人民日报', '人民日报', '太行精神;', '7月的北京骄阳似火，来自太行山的一场展览又平添了人们的热情。 1日上午，“太行精神光耀千秋———纪念抗战胜利60周年”专题展览在北京革命军事博物馆拉开了帷幕。450余幅照片、500余件文物静静向人们诉说着那段可歌可泣的历史。在国家和民族处于危亡的关键时刻，', '2005-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT_B1dv4kmLAZ6CfxV0HXSTRkp8fjFc0LZrJf87zYjtKoibQnjDntI-wVcpbfDG6o8CGcweUKgLrQHDBaCRBHbY7VW37V6BF0T4yAEnrFD3qeUd-_tbMQmkyRDIutBAmyDiIEfmY_eCJQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4241, '报纸', '彭雪枫', '', '人民日报', '人民日报', '彭雪枫;新四军;', '彭雪枫是中国工农红军和新四军杰出指挥员，军事家。投身革命20年，出生入死，南征北战，智勇双全，战功卓著，被毛泽东、朱德誉为“共产党人的好榜样”。 彭雪枫，1907年生，河南省镇平县人。1925年6月加入中国共产主义青年团。1926年9月转入中国共产党。1930年5月被', '2005-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRqqFeLJGwHTr21ak8g4-0SkMl2L84MLF5qzVqxJEBaPbdo19jazsZg8LIWM7mRXG31l-CD1_mQzXxaYmfZoZ98Bd2jTPDIaVMh2sr69RdA2KtZbcZ4rAta-WZ_iLwf3PWtxpMXruprcw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4242, '报纸', '中国之莺', '王晓铭; 王春', '科技日报', '科技日报', '周小燕;廖昌永;', '万里长城万里长，长城外面是故乡。四万万同胞心一样，新的长城万里长。  1937年，20岁的周小燕在抗日战争全面爆发时，首唱了这首《长城谣》，唱出了中国人民誓死不做亡国奴的悲愤之心。1995年，当78岁的周小燕站在长城上再次演唱这首歌时，眼泪不自觉地涌出来，今天', '2005-06-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSizKWAGMWwuu342q2UjdScdpgm887hpMj8kW-g2mu5O94RXgJ5AI0vgpIqLMRTARXRUh4U3y-4TaIoxDtFDKWNbVeRwx_uqw39-W6ckcvwMUsUdpV_vJNVZEid7CXO9VKWBSBgH-18tw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4243, '报纸', '永远的艾培　永远的爱', '温红彦', '人民日报', '人民日报', '美林花园;国际主义;宋庆龄;人格力量;', '“我爱中国，爱中国人民，中国就是我的家……” ———爱泼斯坦 爱泼斯坦，一个亲切的名字，一个响亮的名字，一个见证了中国百年风雨的名字。 这位与我们党同舟共济的好同志，与人民心心相印的好朋友，杰出的国际主义战士，几天前离开了我们。 尽管他的', '2005-06-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR2qWLHtzKJHfd3u1cIcBB0VuCB3myS_qFvwDJilrehiln1b-RQFkWrC5_LOc56Gcg0tgRPG30xz_QDyP9ncEdOV4gGgY21eZ3k6hE9Y-uvI1dIW7sda-jRAf-d_pC_X3hnGNZwN1xIXQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4244, '报纸', '用舞台艺术反思历史', '张贺', '人民日报', '人民日报', '反思历史;南京大屠杀;第二次世界大战;', '“忘记历史就等于背叛。”在抗日战争暨世界反法西斯战争胜利60周年到来之际，中国的艺术团体纷纷行动起来，推出了一系列文艺演出，用艺术的形式再现和反思历史。从5月到9月，将有30多台以抗日战争和第二次世界大战为题材的优秀剧目进京展演。 热情歌颂伟大民族精神', '2005-05-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS3SK-3F3IZwnBEbaXilZeJcUvYv6QlIlSj8MhjseNwg-4sf6Wq7NHi2NcW-ikMGrEbEEZd-cSjSwGgWx9-jlRhzbDhUhWcZscf_Tuk4BjVk9yWWUcIP7q8Dv4tJwDODBoGMBxLUE2cUA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4245, '报纸', '时世造英雄', '王燕宁; 杜昌堂', '科技日报', '科技日报', '燃煤电厂;', '孙克勤，国内烟气脱硫技术的著名专家， 对技术有着非常深的“赶超欲和民族自主情 结”，这可能是受其父辈的影响，其前辈曾参与 中国第一个现代橡胶企业的创建、第一个汽 车轮胎开发以及随之而来的抗击跨国公司的 打压。经历抗日战争，少时孙克勤常听到父', '2005-03-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQzWtQAVhuEBykMdQtdWPjrI_ejCxEMCdmO9fMsYSbKdOcvBsKRN5IrZmhhvDwAV3mr6ATxfJ8Pxs9Bdn21NYdYUETaeIrm4rXSDLUlr4n_w0zITt_YKbo8E8K2xCMkmDNuDM7YGGwQvg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4246, '报纸', '代表建议设中国的“阵亡将士纪念日”', '曹智; 李宣良', '新华每日电讯', '新华每日电讯', '阵亡将士纪念日;全国人大常委会;爱国主义教育;', '“在争取民族独立和解放斗争中牺牲的将士们，应该有一个 专门的日子来纪念他们。”全国人大代表孔令人教授说，“我们有 许许多多这样那样的节日和纪念日，为什么就不能设一个‘阵亡 将士纪念日’呢？”  孔令人代表提出，通过全国人大常委会或国务院设', '2005-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQCoJy-QsWkaO-mapzBUD418pMWGoTlgkMwcEeetBSHWxgGtpdDsHUhn8L4yygqp2oHCskM_xKuE20wTHfG8KJShXiY3m_6jSEZAHtsgKOLgjKBZ_hGdv1onzGKDTU7gdu8tZ49iLsWIw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4247, '报纸', '生的伟大死的光荣 刘胡兰', '', '人民日报', '人民日报', '刘胡兰;云周西村;任弼时;', '1947年3月下旬，毛泽东带领中共中央机关转战陕北途中，中共中央书记处书记、中央纵队司令员任弼时向他汇报了一位小姑娘刘胡兰英勇就义的事迹，毛泽东问：“她是党员吗？”任弼时说：“是个优秀的共产党员，才15岁。”毛泽东深受感动，挥笔写下了“生的伟大，死的光荣”8个大', '2005-02-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQHB9xa0eoIEeCRJ1LxqEZvZ0_sr9rpSzY1ih_QAp2F5Iqkod5Wi5XB54pbb1UkcrHAooQRq6u6FjHA2Lvuh9Zq6KtKH0_ldzf2IBBOBtCr5kA3ezDRpuyNs8AtGmTD_OHphYlJltTmRA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4248, '报纸', '华裔女作家张纯如自杀身亡', '支林飞', '人民日报海外版', '人民日报海外版', '南京大屠杀;华裔女作家;历史学家;旧金山;新书发布会;', '据新华社洛杉矶电（记者 支林飞） 据美国警方11月11日透露，曾经以撰写揭露侵华日军滔天暴行的《南京大屠杀：被遗忘的二战浩劫》一书，而成为全球畅销书作家的著名美国华裔女作家张纯如，11月9日被发现在旧金山一条公路的汽车中开枪自杀身亡，享年仅36岁。 据圣克拉拉', '2004-11-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTzmLKyg3rAawtmuHT-MpAWNwQBjGsI8-eIrorKL6x3Z7JE_yoiQpmfefHzXwTqc0xcQBVVrG7PdZNTcmsvc6ZmKJ911H-mF8ueIu9CJQQjSlMmvlS86ayKpGuiT3UJpvTro4ZmkSmmWQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4249, '报纸', '不断推动国防教育事业深入发展', '寻晓明; 杜献洲', '解放军报', '解放军报', '深入发展;曹刚川;国防教育;', '本报北京9月18日讯　寻晓明、记者杜献洲报道：今天是第四个全民国防教育日，又逢“九·一八”事变73周年，全国各地广泛开展以“勿忘国耻、强我国防 ”为主题的国防教育活动。中共中央政治局委员、中央军委副主席、国务委员兼国防部长曹刚川在中国抗日战争纪念雕塑园和中国人', '2004-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSqsgyUMx8baFvRaGGWn2X5Q5O7N9jAPjrYiAf8DMfEzTkOLodqK0McfSIFjdOFbiCO5yUnVVVjAu6oTSsETEkxoyrKIKVqempu-qOL2IWo1JVoyDSCkZjIxW1y1fK0zVNmtRKv4Agdjg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4250, '报纸', '抗日老英雄的“生死”辩护', '李健', '中国消费者报', '中国消费者报', '抗日战争;经典改编;保定电视台;一审判决;', 'T已故著名作家冯志的小说《敌后武工队》是一部家喻户晓的抗日战争题材经典著作，描述了敌后武工队 员与敌人斗智斗勇、浴血奋战的真实故事。1999年，北京电影制片厂电视部、北影音像公司等联合将《敌后武工 队》改编成20集电视连续剧，并作为建国五十周年献礼片搬上', '2004-09-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQy_McOTdzG8N_r1p2yFH6daPp6iDGt5uVrWIKqI72sPAZZDdUmnE7K8tVxfrIxsb5O4gT83f05aJS98GTNMZJ9BOXmPYiAl-BZWES9-IUZfTRo6FLhoi-NtXC4G_5iZg2fcgguyXW0Rg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4251, '报纸', '在黄埔军校建校八十周年纪念大会上的讲话', '贾庆林', '人民日报', '人民日报', '黄埔军校;黄埔精神;黄埔军校同学会;纪念大会;', '同志们，朋友们： 今天，来自海内外的黄埔同学在这里隆重集会，纪念黄埔军校建校80周年和黄埔军校同学会成立20周年。我代表中共中央，向大会的召开表示热烈的祝贺！向到会的各位黄埔同学，并通过你们向所有海内外黄埔师生及亲属，致以诚挚的问候！ 80年前，中国伟', '2004-06-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR_xV85wKcRzI54t-HajUQ9a1WgiJ2swVweGFsUzasGIcabCa16Yhpxdnjnf1wDIRDedhsRvbJD52AJXAhh73DPDqfU_g7Iwql_VctFpkQZcgn4UoAcuMPTbNMRg0G-HZfZmz1YIV4oGw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4252, '报纸', '“红旗”今朝更鲜艳', '万水华; 唐国和; 吴维满', '中国国防报', '中国国防报', '红旗民兵营;', '□万水华　唐国和　本报记者　吴维满 新闻背景　在抗日战争时期，郭庄民兵自卫队共配合八路军作战200次，毙敌35人，伤敌120多人，直接参加了“百团大战”；解放战争时期，郭庄有500多民兵参加了解放平津、清风店、新保安、石家庄、太原等战役的支前工作，有264名民', '2004-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQq8hRRc2R4C_gJLrDlmwUhhdQgTCqVBNGfmeeM_p7Zc9O7O0YQUWGswbSyOaeCjN66yseqqYE1kKjEAhV8CiSY1Z9hRXBZsqQPiMTP2YKgokB2caAWBU7TRIjxkrzHFN_MStWoK5Wa-Q==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4253, '报纸', '永不枯竭的革命激情', '曹晓', '解放军报', '解放军报', '杨成武;国民党军队;', '杨成武将军是我所敬仰的老一辈革命家。2004年春节，我决心来一个节日饱读，捧起了分为上、下两卷共计近百万字的《杨成武回忆录》。透过那朴实流畅的文字，我听到了激情岁月里的战斗号角，听到了轰轰的炮声和刺刀碰撞发出的声音，我甚至还听到了杨成武将军匍匐在草丛里发出', '2004-03-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSHEpLAbvmw-Y_yUVyUhRw8oASXwh6WDaFExx3zF-YehYx4aX8R45z4rXSH179H1N3hC40CtX8G4htdRWXkBNJTYXmK1lmjbwynPHMwzw-KM5XXmgpXb96wZaeifPQ-5OR1U_4ab0uc3Q==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (4254, '报纸', '毛泽东与治水', '', '中国水利报', '中国水利报', '毛泽东;周恩来;林一山;新中国成立;水库建设;王化云;三峡工程;', '中国的水问题始终是个事关国计民生的重大课题，这是中国的自然地理特点和社会经济条件所决定的。熟谙中国历史并善于以史为鉴的毛泽东，深知治水在中国历史发展进程中所具有的重大作用，而亲身经历的国家水旱灾害频仍的严峻现实，更使他深切地感到，治水是关系安邦的大事，必', '2003-12-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTSh31AaqakBJmxOxBweBxyAZhQDTbhzKvx-YKmFbxzWpJSUN5h3f_0FqA9QSM3hnWhV-Ecp9fS5WqYEeGKf8aHvExoxW2hVZ4ozqmEBL_5WnUb8qJ9C6-tRhzAtWep-7eYWbetqK-x2w==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,中共七大-2_screened');
INSERT INTO `ds_article` VALUES (4255, '报纸', '《陈嘉庚的故事》动人心弦', '连锦添', '人民日报海外版', '人民日报海外版', '陈嘉庚;《陈嘉庚的故事》;爱国主义教育;', '本报讯记者连锦添报道：《陈嘉庚的故事》座谈会八月十三日在北京华侨大厦召开。由厦门鹭江出版社出版的该书，通过四十九个生动、感人的故事，真实地再现了陈嘉庚先生艰难卓绝的伟大一生。 座谈会由中国侨联主办、福建省新闻出版局、福建省侨联协办。全国人大侨委、全国', '2003-08-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRZiKMXP4gLXuWq7-39M02NfU42CdrGRsEPyyd9d5zGrqPsyJc7B8a_zRRQRg5VSrokG2DIoiCp6CF4ym3MpCulMj5ZQHtNUdOFVtVncinlammAhr2ie6FQreI4i81F978VJrCp6uPerQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4256, '报纸', '讲故事的“胡子”爷爷生前的故事', '白瑞雪; 孙彦新', '新华社;', '新华每日电讯', '学习成绩;', '孙毅将军再也不能讲故事了。  在走过百年人生后，这位被朱德总司令称为 “孙胡子”的将军，永远地离开了北京华家胡同4 号那座朴素的四合院，离开了他一生辛勤教育的数 万名学生，离开了听过他讲故事的几代年轻和不再 年轻的听众。  82', '2003-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRYM5R0uH6DxEZyH-TtYBjGj5q65WwgdKYzeKKI4uxyws06InpRfcej_JSHwj0LK2Rah-lL2UTOv1JBxlKLnXYTbYdu06m4D9FMk1IxAObwfdAElnheD20Pey9d_s0HvVe4y_Drk75bVg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4257, '报纸', '国藏文物丢失仅因为“家贼难防”吗', '', '中国商报', '中国商报', '民间收藏;李海涛;主持人;外八庙;', '2002年10月，香港佳士得拍卖行在秋季拍卖会上推出“皇家信仰———乾隆朝之佛教宝物”专场拍卖。国内一位文物专家参观中发现两件标有“故字留平×××号”字样标签的文物。这是1937年抗日战争爆发前，为使文物免遭战火洗劫，故宫博物院组织大规模文物南迁时留在当时北平的文', '2003-06-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTwmE3fBEWKXfiEKO_e9CI00KsM7GHNFsg90oiRSdUTVhIONwJQpabrIPhz_w619PNh_BNdu3YREXdwTMUKFtw_dXeMNRKpZSHPBsWg2ruhGcskURDsWGn_u8lvYvSZKRvbMlU43d9M5g==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4258, '报纸', '涅槃火凤入云天', '刘亚东; 隗瑞艳', '中国文化报', '中国文化报', '民间音乐研究;中国文联;音乐工作;中国古代音乐史;', '料峭的寒风吹动着花圈上的挽联，冬天又冻结了一个理想，使之冬眠、延续……  1月22日上午，北京八宝山革命公墓礼堂内外的人群分外肃穆，来自各地的人 们──既有吕骥老人生前的老友、学生，也有十几岁娃娃辈的孩子，他们手持白花，', '2002-01-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQpvO-fEtXdpHnWKNJGGmfZqLq2OkpW4k1NkDa6mDtKahHdiTZ0nLS_0n4DoT2wmghleEjv4AR_MTRBkIWFxg9xap4imjBhy_H_rzifaFnT9FCq6ZaNRDG3JjUVejkJ3zX8ZdOFYc2slA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4259, '报纸', '爱国是我终生不渝的情怀', '袁新文', '光明日报', '光明日报', '钱伟长;原子能;', '记者的话：“没有一个独立富强的国家，就没有个人的一 切。”“我们培养的学生首先应该是一个全面的人，是一个爱 国者。”这些，都是科学家、教育家钱伟长的名言。翻开他刚刚 出版的《教育和教学问题的思考》一书，第一篇文章便是《物理 教学与爱国主义', '2001-11-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRcB2uQkkOPmvegwZMeuL5yRlDghfH7ILTSmBZwsNuZj5N1U4nRoveCaeNhIVYazsFNV8gDXjJ_vD8PLu22FbfdF3bPKF2KCNLlGoDGkAeoLYsDT58ne8adnBwMHo5zlATpTioSWGUxyA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4260, '报纸', '无畏的头颅 不朽的铁证', '曹霁阳', '新华社;', '新华每日电讯', '汪亚臣;陈翰章;哈尔滨市;烈士陵园;', '哈尔滨烈士陵园有两座特 殊的陵墓，那里安放着抗日英雄 陈翰章和汪亚臣的遗首。打开特 别设置的墓室门，人们便可瞻仰 到烈士遗容。据介绍，这两位烈 士的遗首为全国仅有，而且历经', '2001-08-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTq8Q_WKOyGI_HZ0wUBzq8-OpBcydlaERcuFG4dHBRC1BJAhnXfX45JZB5xl8sMNuuC8EjG1GrpkYKhAlDZV_qeXv76RFCtoRuSuh8NnKWlQIO9SkMI6XaLoCyCXpUzIAM6k-orQQG65w==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4261, '报纸', '党的优良作风的继承和发扬', '李术峰', '新华社;', '新华每日电讯', '优良作风;加强党的建设;江泽民同志;继承和发扬;', '江泽民总书记的“七一”重要讲话， 全面深刻地阐述了“三个代表”重要思想的 科学内涵，为新世纪加强党的建设指明了方 向。中共中央文献研究室主任逄先知说： “江泽民总书记‘三个代表’重要思想，', '2001-07-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRSU3_L_zGWzp2ul0LQiVIVgU9uzPfgiFmZLfWH6wcBryqKSulg7rdyleBpDfoxIffDhNNGIMa_LKJSRwGg5C0P7krZkSo5XDPESyNIrBTQ4y8PfKkO9lXvKc0pbA3p9ch7qyFiNLecEg==&uniplatform=NZKPT&language=CHS', '抗日战争_screened,中共七大-2_screened');
INSERT INTO `ds_article` VALUES (4262, '报纸', '艰苦奋斗 务求实效', '董伟', '人民日报', '人民日报', '务求实效;宋法棠;求真务实;', '喜迎中国共产党建党80周年前夕，记者就怎样大 力发扬“艰苦奋斗、务求实效”精神采访了黑龙江省省 长宋法棠，他说：“艰苦奋斗，务求实效，是江泽民同志 大力倡导的不懈奋斗精神的重要组成部分，是我们党 的优良传统和作风，是党领导人民夺取革命和建设', '2001-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSbNPsEZ0Lm6wQjZYY9yXJZWIOscq90udOILduIG1VBpI4hpEY2c2oXgg0WO-lzYuHhhMmUggM-ismqPPe5arotv1mCXOJe5Z8A53Q14CakaqcYmiNj9OokJSdy8yZfc70iSuPqSJBC6w==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4264, '报纸', '沈兹九：独立自由的女报人', '丁秀伟', '中国妇女报', '中国妇女报', '沈兹九;独立自由;', '1935年，“一二九”学生运动 爆发，著名女报人沈兹九在《妇女 生活》上撰文高呼：“我们想做人， 想做独立自由的人！”当时，妇女运 动在共产党的领导下开展得如火 如荼，蒋介石为阻止全国妇女投入 到抗日救亡运动中，提出“新贤妻 良母', '2001-06-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSHWVObFWc_DbozmVX867Gpf_fFQz8U5G_CMXS1xn9C5nHdYQhHJ982-jTGYDFR0jGxt5qmB794Pl-PnYGor_iaCEXrNqeLXx8mHd9N5zcXyYwOH-sprMFBEtx5By9KovJ614-P4TaQmQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4265, '报纸', '樊建川和他收藏的抗战文物', '邢珊瑚', '中国国防报', '中国国防报', '樊建;地图;', '面对日本歪曲历史的教科书悍然 出笼，一个中国收藏家愤怒了！  今年4月21日，被誉为“中国民间 抗战收藏第一人”的樊建川在四川省博 物馆公开展出了他收藏的4000多件抗 战文物、图片。这些展品从民间收藏的', '2001-05-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSeqqxfRFkabrVCv8DtY_PcnkM5lZQHyC85kABqKFO4bTE0dh5JnUsEXis2O_p7n85lQIgnp9XIIOOFd8PAMvtBfFJGRAoxrX-PYUFJDdCZpD7rNeUBWhw3LJD1TerT5OtYPRaeRqIu0A==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4266, '报纸', '以身许国清华人', '冯瑛冰; 江涛', '新华社;', '新华每日电讯', '王淦昌;毕业生;朱自清;', '清华大学，她从诞生于民族耻辱之中的 学堂走来，历经20世纪的风雨，以一颗颗跳 动的赤子之心谱写出一曲曲壮美的爱国、奉 献之歌。  “千秋耻，终当雪”  90年前，清政府用美国“退还', '2001-04-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQJUEleKBDOWshtHHeBQIUyMS43EkgEBWspe9E0joeJzkZMJRcrNzhrqAGLp6y65fghNycLfwT8q2p1Q9VYYX-syC6DjSOE0vdxGxgu-QJuO5eZJ2ldZSxF8G-6Jh4IeK8JZpdpTwsXGA==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4267, '报纸', '一辈子只作中国人', '沈莹', '中国妇女报', '中国妇女报', '日本女性;', '一个土生土长的日本女性， 在本世纪30年代，当她的“同胞” 正用铁蹄大肆践踏中国土地的时 候，竟毅然来到抗日烽火燃烧的 中国，穿上“八路”服，并肩和 中国的志士仁人抗击侵略，守护和 平……这位日本女性和中国这块 土地以及生长在这', '2001-02-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ4Qz-q392VCK0VN20n8ggIW9NT_UiUj0oKDxcT2EoaIG03UEJo8_WiRN0PHQTDK_JsrjKGSXBaXTuYVSZKgXmwfCZh8u_ePKsGt-DGsOUrWTBeky1qHjYvCjbf73QPDBdcGqIzwpmOfQ==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4268, '报纸', '樊建川 倾囊不悔为记一痛', '张楠', '工人日报', '工人日报', '飞虎队;', '正值“7·7”、“8·15”抗战纪念日期间， 记者采访到抗日文物民间收藏家樊建川，六 七年间他收藏了2000余件抗日文物，其中有 大量当年侵华日军留下的极为罕见的罪恶 物证，这些民间藏品旁证了那场惨绝人寰战', '2000-07-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRfrz4JQO5ucSW9uUMV6I7rlPeKSjtPStQex7U-pn0eRW3mC8dAfQwhSihwy6Rfg85LGL2YglQH7MSlRp50WSH4LNZxl2pihrO0O3pvyRD2Lso0XVnXzq_hBvFt0uLDWOJQAKj7fodJOw==&uniplatform=NZKPT&language=CHS', '抗日战争_screened');
INSERT INTO `ds_article` VALUES (4270, '报纸', '打造百姓身边的“国防课堂”', '田国庆; 乔振友; 吕衍海', '中国国防报', '中国国防报', '全民国防教育;黑龙江省;国防教育基地;', '“三江水流淌着红色基因，大雪原耸立着英雄雕像，抗联人血荐轩辕捍中华，垦荒人备耕生产建粮仓，石油人誓死拿下大油田……”这是人们对黑龙江这片黑土地红色资源的描述。 这片热土，是东北抗联的主战场，涌现出赵尚志、赵一曼、李兆麟等大批抗日英雄人物。新中国建设时期，', '2024-01-31 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2024.000092', '抗日战争1_screened,抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4271, '报纸', '在纪念毛泽东同志诞辰130周年座谈会上的发言', '苗华', '中央军委;中央军委政治工作部;', '人民日报', '毛泽东;人民军队;毛泽东军事思想;座谈会;', '毛泽东同志是伟大的马克思主义者，伟大的无产阶级革命家、战略家、理论家，是人民军队的主要缔造者，波澜壮阔的军事实践是他伟大革命生涯中的光辉篇章。回顾缅怀毛泽东同志创建和领导人民军队的丰功伟绩和精神风范，对于我们坚定沿着党指引的方向前进，锚定建军一百年奋斗目', '2023-12-27 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.012144', '抗日战争1_screened,反围剿_screened,农村包围城市、武装夺取政权_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4272, '报纸', '定军山：忠魂宿而浩气生', '孙正好', '新华每日电讯', '新华每日电讯', '定军山;勉县武侯祠;武侯墓;诸葛亮北伐;', '公元234年秋，“郁屈如长蛇”的陕西宝鸡岐山五丈原一带，“云何西风至，忽已落大星”——毕生致力于收复汉室的蜀国丞相诸葛亮，于呕心沥血间油尽灯枯，卒于北伐曹魏的军帐之中，时年五十四岁。 彼时，蜀魏大军正如铁马云雕般对峙于渭水两岸，壮志未酬的诸葛亮留下遗命：“葬', '2023-12-01 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.007061', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4273, '报纸', '山川同念 英雄回家', '李灵娜', '中国纪检监察报', '中国纪检监察报', '中国人民志愿军;退役军人;事务部;烈士陵园;烈士家属;太姥爷;沈阳桃仙国际机场;', '11月24日，随着《思念曲》低回奏响，礼兵们抬起在韩中国人民志愿军烈士棺椁绕沈阳抗美援朝烈士陵园下沉式广场半周，缓缓走向安葬地宫，25位志愿军烈士英灵在抗美援朝战争胜利70周年之际，回到祖国和人民的怀抱，在中华大地安息。 异国埋忠骨，山河盼英魂。今年，是按照中韩', '2023-11-25 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.003579', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4274, '报纸', '再访南梁', '向清凯; 张钦; 王博; 任延昕', '新华每日电讯', '新华每日电讯', '华池县;陕甘边革命根据地;陕甘革命根据地;', '连绵起伏的黄土高原上，子午岭像一条苍翠巨龙，纵贯陕西、甘肃两省。巍巍子午岭中，南梁是一个籍籍无名的寻常小镇。翻开中国革命史，南梁却是一处熠熠生辉的红色坐标。 20世纪30年代，以刘志丹、谢子长、习仲勋为代表的中国共产党人，于南梁一带创建了陕甘边革命根据地，成', '2023-11-06 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.006545', '抗日战争1_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4275, '报纸', '百岁飞虎队老兵讲述与中国的情缘', '赵觉珵; 单劼; 胡雨薇', '环球时报', '环球时报', '飞虎队;美国陆军;志愿队;陈纳德;滇缅公路;基金会;飞行员;', '今年9月12日，国家主席习近平复信美中航空遗产基金会主席格林和飞虎队老兵莫耶、麦克马伦。此前，格林、莫耶和麦克马伦共同致信习近平主席，介绍基金会和飞虎队老兵支持推动美中友好交往的情况，表示将传承和弘扬美中合作的宝贵精神财富。 跨越太平洋的信件往来再次唤醒了一', '2023-10-25 08:00:00', 'https://link.cnki.net/doi/10.28378/n.cnki.nhqsb.2023.007649', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4276, '报纸', '“在基层工作一不怕苦，二不服输”', '李华锡', '中青报;中青网;', '中国青年报', '习近平总书记;伽师县;安徽潜山;图书角;维吾尔语;', '“为什么我们的开学典礼不在9月1日，而在9月3日呢？为什么我们的典礼不在礼堂，不在操场，而在烈士纪念塔下呢？”安徽潜山野寨中学学生王紫睿在10月14日举办的“把青春华章写在祖国大地上”网络主题宣传和互动引导活动现场提出这个问题。 9月3日是中国人民抗日战争胜利纪念', '2023-10-17 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2023.003647', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4277, '报纸', '少年不负家国情', '管筱璞', '中国纪检监察报', '中国纪检监察报', '潜山县;地方志;红色基因;品格教育;习近平总书记;青年学子;国防科技大学;军校生;红色精神;', '8月31日傍晚，安徽省潜山野寨中学高二、高三1500余名学生破例没有上晚自习，而是集体观看当天的《新闻联播》。他们的学长学姐成了新闻中的主角。 少年自有凌云志，横刀立马定山河。今年，野寨中学770名毕业生中，有133名报考军校，几乎每6人就有1人如此。其中20名毕业生分别', '2023-09-11 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.002898', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4278, '报纸', '走从军路 铸国防魂', '郑天然; 王海涵', '中青报;中青网;', '中国青年报', '安庆市;国防教育;人防教育;国防知识;托管班;军校学生;国防意识;', '今年高考，安徽省潜山野寨中学有20名学生被军校录取。在校长徐汉夫看来，今天的成果源于学校长期以来对国防教育孜孜以求的探索。 事实上，在安庆市，野寨中学绝非个例。该市近年来在各界持续掀起国防教育热潮：校园里，纪念抗日阵亡将士公墓、忠烈祠、抗战纪念馆等建筑与教', '2023-09-08 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2023.003205', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4279, '报纸', '追忆中韩共同抗战岁月', '杜白羽; 陆睿; 周思雨', '新华每日电讯', '新华每日电讯', '中国人民抗日战争纪念馆;朝鲜义勇队;', '1945年8月15日，日本宣布无条件投降，朝鲜半岛从日本殖民统治下获得解放。此后，每年8月15日是韩国的“光复节”。 上世纪初期，朝鲜半岛沦为日本殖民地，大批独立运动者流亡到中国，在中国成立许多抗日团体，与中国军队并肩作战，抗击日本侵略者，最终赢得反法西斯战争的伟', '2023-08-16 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.005000', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4280, '报纸', '定格历史瞬间，记录战地影像', '孙戎; 潘娣', '中国国防报', '中国国防报', '志愿军;朝鲜战场;边震遐;中国人民革命军事博物馆;抗美援朝战争;', '今年的“八一”，抗美援朝老兵、原志愿军第九兵团摄影记者张崇岫过得尤为开心。 “八一”前夕，武警安徽总队合肥支队执勤二中队官兵专程到张崇岫家中拜访，为他送上一套崭新的志愿军军装，和依照他在抗美援朝前线的留影照片画的素描画。 1000多公里外的北京，“现场与在场', '2023-08-07 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2023.001006', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4281, '报纸', '延安时期中国共产党开展主题教育的基本经验', '徐鹏; 贺双双', '西北政法大学马克思主义学院;西北政法大学马锡五审判方式研究院;', '人民法院报', '优良传统;共产党;思想路线;马克思主义立场;毛泽东;教条主义;辩证唯物主义思想;整风运动;主观主义;主题教育;', '一百多年来，中国共产党在各个历史时期开展了数次不同程度的主题教育活动，其中，延安整风运动是中国共产党开展主题教育活动的典范。此次主题教育活动是为了破除马克思主义教条化、把共产国际决定和苏联经验神圣化的错误倾向的思想解放运动，为中国革命的胜利奠定了坚实基础', '2023-08-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTUfmL4bMj0VyZNjk2wMtIjnWyJpOCm6c01klktgzRbnu2mf0kaTa-OH76CKkvPQvc4YN1MBQZ5QemBGWxkelGfD_MTBac2fdTdEM10VVUcgQ660RAsPeDP9olg2oFlN1lgvb0xnd7nVA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4282, '报纸', '写给2027年的信', '孙伟帅', '解放军报', '解放军报', '舰载机;王忠兴;太姥爷;飞行学员;', '2027，一个标定在中国军人心中的特殊年份——党的十九届五中全会明确提出，2027年实现建军一百年奋斗目标。 如果说南昌起义那一声枪响，开启了人民军队一往无前的出发，那么此时此刻，2023年的“八一”，梦想的脉搏，正强烈跳动在每一名中国军人心间。 不久前，解放军报微', '2023-08-01 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2023.002700', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4283, '报纸', '战旗猎猎永飘扬 奋斗强军续辉煌', '', '人民日报', '人民日报', '红一连;杨根思连;集团军;荣誉称号;硬骨头六连;', '“为什么战旗美如画？英雄的鲜血染红了它……”每当望向“杨根思连”荣誉战旗，连队二级上士付东旭总是热泪盈眶。回想起庆祝新中国成立70周年阅兵式，自己高擎着老连长用生命换来的荣誉战旗通过天安门接受检阅的场景，他坚定表示：“作为新时代的‘接旗人’，我们要一心一意', '2023-08-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.007767', '抗日战争1_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4284, '报纸', '“我愿日夜守护东兴汇路历史记忆”', '高乔', '人民日报海外版', '人民日报海外版', '东兴汇路;展示馆;华侨华人;历史记忆;', '在广西壮族自治区东兴市建设街28—1、2、3号，一座颇具南洋建筑风格的小楼安静伫立。长年累月的青苔痕迹从屋顶蔓延到白色外墙，朱红门窗里镶嵌着彩色玻璃，门前各类绿植蓬勃生长，时间在这里放慢了脚步，一草一木都仿佛在诉说小楼里的故事。 这里是东兴侨批馆，也是抗日战争', '2023-07-19 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2023.002366', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4285, '报纸', '传承红色精神 开创美好生活', '邵玉姿', '人民日报', '人民日报', '前南峪;浆水镇;南峪村;陈列馆;中国人民抗日军事政治大学;美好生活;红色精神;', '前南峪村位于河北省邢台市信都区浆水镇，是太行山深处的村庄。 1940年11月至1943年1月，中国人民抗日军事政治大学（简称“抗大”）总校在浆水镇一带办学，前南峪村是校部所在地。在抗日战争艰苦的岁月里，这里曾培育出许多抗日将士，抗大精神深深地熏染着这片土地。 20世纪', '2023-07-15 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.007106', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4286, '报纸', '以艺术真实还原历史原色', '刚罡', '团结报', '团结报', '中国远征军;昆仑关战役;油画作品;驼峰航线;艺术真实;还原历史;历史题材;', '画面中，昆仑关战场炮火纷飞，英勇的战士们正在浴血奋战，4位名将指挥若定、英姿卓然…… 5月9日，大型历史油画《铁血昆仑》捐赠收藏仪式在北京中国美术馆举行。这幅大型油画由民革中央画院副院长、云南大学艺术与设计学院教授赵力中历经一年多时间艰辛创作完成。 迎难而上', '2023-06-03 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2023.000849', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4287, '报纸', '梁晓声：把英雄崇拜情结留驻心间', '张妮; 李予澈', '环球时报', '环球时报', '梁晓声;英雄崇拜;纽约唐人街;', '编者的话：“名下有此书，身为中国作家，又去一憾也!”梁晓声在新作《父父子子》的封底写下这样一句话。去年，以梁晓声同名小说改编的电视剧《人世间》感动亿万观众，《父父子子》则将目光投射到《人世间》的前50年，展现半个世纪的中华民族奋斗史。在梁晓声看来，《父父子子', '2023-04-17 08:00:00', 'https://link.cnki.net/doi/10.28378/n.cnki.nhqsb.2023.003323', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4288, '报纸', '马英九参访抗战遗迹追思英烈', '吴薇', '环球时报', '环球时报', '马英九;张自忠;台湾学生;', '马英九一行的登陆祭祖之旅，与抗日战争相关的行程不少，包括参访侵华日军南京大屠杀遇难同胞纪念馆、湖南南岳忠烈祠、湖南受降仪式所在地、重庆张自忠烈士陵园以及上海四行仓库抗战纪念馆等。大陆经历了14年艰苦卓绝的斗争，台湾的抗日历史更是持续了70年，中华民族最终赶走', '2023-04-07 08:00:00', 'https://link.cnki.net/doi/10.28378/n.cnki.nhqsb.2023.003028', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4289, '报纸', '马英九:历史绝不可遗忘', '吴薇', '环球时报', '环球时报', '马英九;南京大屠杀遇难同胞纪念馆;侵华日军;', '3月29日，中国国民党前主席马英九一行参观了侵华日军南京大屠杀遇难同胞纪念馆，深切悼念遇难同胞。马英九受访时表示，历史绝不可遗忘，我们所有中国人都应自立自强，才不会被人欺凌、任人宰割。 “300000”是全体中华儿女的沉痛记忆 上午9时30分许，马英九一行抵达侵华日', '2023-03-30 08:00:00', 'https://link.cnki.net/doi/10.28378/n.cnki.nhqsb.2023.002685', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4291, '报纸', '在美囚禁114天，他誓言再苦再穷也要回祖国', '魏刚; 樊春华', '中国科学院长春应用化学研究所;', '中国科学报', '黄葆同;留美科协;', '一本英文字典、一本地图册，这是黄葆同书桌上的标配。 当与来访者谈到某个地方时，黄葆同就会翻开地图册指给他看，“嗯，就是这儿”。当遇到学生英文论文中出现拼写错误时，他会随手拿起英文字典，边查边强调“这个词是这样拼写的，绝对不能出错”。 从觉醒年代的求学者到', '2023-01-05 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2023.000073', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4292, '报纸', '把红色基因传承下去', '王晓; 范奇飞; 鲍明建', '解放军报', '解放军报', '辽宁省军区;抢救性;退役军人;口述历史;红色基因;', '11月中旬，辽宁省退役军人事务厅联合辽宁省军区政治工作局编撰的《致敬百位英雄（二）》付梓成书，书中收录了100位辽宁本地参战老兵的口述史料。这是辽宁省开展参战老兵抢救性口述历史采访活动取得的又一项成果。 辽宁是一片红色的沃土，作为抗日战争起始地、解放战争转折地', '2022-12-14 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.006600', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4293, '报纸', '永志不忘 继往开来', '刘已粲; 苏雁', '光明日报', '光明日报', '南京大屠杀遇难同胞纪念馆;侵华日军;', '国行公祭，祀我殇胞。2022年12月13日，是第九个南京大屠杀死难者国家公祭日。85年前的这一天，南京城破，短短6周内，30万同胞惨遭杀戮，三分之一建筑被毁，大量财物遭到掠夺…… 战争的炮火虽已远去，但累累白骨仍在无声诉说，历史真相不容磨灭!13日，南京大屠杀死难者国家', '2022-12-14 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.006111', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4294, '报纸', '发挥法律规范引导作用保护英烈名誉', '赵丽; 王禹钦', '法治日报', '法治日报', '人格利益;抗日英雄;民事责任;规范引导;', '草木含悲、山河垂泪。 12月13日是第九个南京大屠杀死难者国家公祭日。在曾遭遇浩劫的古城南京、在浸润着同胞血泪的白山黑水间、在中国人民抗日战争纪念馆等抗战纪念场所，各地群众通过各种追思纪念活动重温这段民族痛史，缅怀同胞先烈，祈愿和平永驻。 勿忘国耻，缅怀英烈', '2022-12-13 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2022.006956', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4295, '报纸', '一座红色博物馆的困境', '张培奇; 王帅杰; 范亚旭', '农民日报;中国农网;', '农民日报', '博物馆;西平县;李东海;', '如此艰难，为何还要坚持在县城办一座红色博物馆呢？ 人的一生，犹如一座博物馆。 每日清晨，满头银发的李东海都会早早起床，给门口的盆栽剪剪枝，整理下柜台陈设的藏品，打扫下室内的卫生……一切准备停当，老人便在昏暗中等待着第一批参观者的到来，继而在等待中回味着自', '2022-12-12 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2022.005134', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4296, '报纸', '古树名木，深植故土发新枝', '', '光明日报', '光明日报', '古树名木;皂角树;古树保护;', '编者按 您知道我国一共有多少株古树吗？近期，国家林业和草原局公布第二次全国古树名木资源普查结果：全国普查范围内的古树名木共计508.19万株，包括散生122.13万株和群状386.06万株。古树一般指树龄百年以上的树木，它们是历史的见证，经岁月更迭、载人世悲欢。古树还是珍', '2022-12-02 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.005901', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4297, '报纸', '开国上将钟期光之子钟德浙：父母的革命风范激励我不断前行', '陈姝', '中国妇女报;', '中国妇女报', '钟期光;革命生涯;政治部主任;军事学院;开国上将;军事科学院;', '家庭小传 钟期光，我军杰出的政治工作、军事教育和军事理论研究领导者，1909年1月2日出生，湖南省平江县人。1926年加入中国共产党，1927年参加中国工农红军。曾任红军师政治部主任、新四军江南指挥部副主任、苏北指挥部政治部主任、华东野战军、第三野战军和华东军区政治部', '2022-11-14 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2022.003495', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4298, '报纸', '走读老城：把历史从故纸堆拉出来', '王海涵; 王磊', '中青报;中青网;', '中国青年报', '三孝口;德胜门;安徽省;历史遗址;', '走一段路，读一座城。 近年来，在安徽省会合肥市，兴起了一股不一样的“走读热”。孩子们走的并不是常见的文旅路线，他们来到合肥历史上第一所官办的地市级学校旧址（现更名为合肥学宫），登上状元桥，围观状元井；在卫衙大关倾听合肥青年在五四运动中的历史回响；追寻抗日', '2022-11-10 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.003816', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4299, '报纸', '胜利的出发点', '管筱璞', '中国纪检监察报', '中国纪检监察报', '习近平总书记;全面从严治党;延安精神;毛泽东;政治方向;', '延安——中国革命的圣地、新中国的摇篮。从1935年到1948年，党中央和毛泽东等老一辈革命家在延安生活和战斗了13年，领导中国革命事业从低潮走向高潮、实现历史性转折，扭转了中国前途命运。历经荡气回肠的两万五千里长征，延安成为中共中央的“落脚点”，也成为建立抗日民族', '2022-10-29 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.005286', '抗日战争1_screened,枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (4300, '报纸', '赓续多党合作优良传统，传承老一辈政治信念、高尚风范和同中国共产党的深厚感情', '', '团结报', '团结报', '中国共产党领导;许德珩;周恩来;多党合作;司徒美堂;毛泽东;政治信念;爱国民主人士;优良传统;共产党;', '【编者按】 长期以来，各民主党派积极投身中国共产党领导的建立新中国、建设新中国、探索改革路、实现中国梦的伟大实践，走过了一条不断追求探索、不断有所作为、不断成长进步的发展道路。在中共二十大隆重召开之时，我们共同回忆各民主党派与中国共产党肝胆相照、荣辱与共', '2022-10-20 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2022.001705', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4301, '报纸', '江桥抗战遗址寻访', '邹大鹏; 陈聪; 王建', '新华每日电讯', '新华每日电讯', '江桥抗战;齐齐哈尔;马占山;', '江桥抗战纪念地，斑驳的石碑肃立。几米远的地方，湍急的嫩江水，冲刷着保护围栏。当年老江桥仅存的木桩遗址已淹没在水下，却无法阻挡这处黑龙江省文物保护单位的无声诉说。 90多年前，九一八事变后，中华民族在这里发出震天的不屈吼声，那是不愿做亡国奴的怒发冲冠，是身许', '2022-09-16 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.006986', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4302, '报纸', '抗联歌声永流传', '于力; 高爽', '新华每日电讯', '新华每日电讯', '东北抗联;杨靖宇;抗战歌谣;东北抗日联军第一路军军歌;', '一寸山河一寸血，一路征程一路歌。 1931年9月18日，日本驻中国东北地区的关东军突然袭击沈阳，以武力侵占东北，中国抗日战争也就此拉开序幕。 中国共产党在百年非凡奋斗历程中，形成了一系列伟大精神，构筑起中国共产党人的精神谱系。其中，在抗日战争时期，中国共产党领导', '2022-09-16 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.006984', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4303, '报纸', '敢打必胜“红八连”', '杜佳冰; 付君臣; 崔健', '中青报;中青网;', '中国青年报', '指导员;连队党支部;', '红色是第80集团军某旅“红八连”荣誉室里最常见的颜色。那些深红、暗红、亮红的锦旗与奖牌，记录着这个诞生于南昌起义的红军连队95年来南征北战的辉煌历史。 “红八连”的前身是朱德军官教育团警卫连，连队先后经历红军长征、抗日战争、解放战争、抗美援朝战争等，被授予“', '2022-09-08 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.004298', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4304, '报纸', '追寻南侨机工的日子', '许雪毅; 邓倩倩', '新华每日电讯', '新华每日电讯', '南侨机工;滇缅公路;陈嘉庚;', '9月3日是中国人民抗日战争胜利纪念日。每到这个日子，林少川的脑海都会浮现1945年抗战胜利场景：南侨机工们欢呼、流泪，拿出脸盆、饭碗，敲打庆祝到天亮。 华侨大学教授、南侨机工回国抗日纪念馆名誉馆长林少川，忘不了37年前，走到他面前的那位67岁传奇老人：抗战时期他奔', '2022-09-02 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.006636', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4305, '报纸', '为抗战文物筑起一个“家”', '潘聪; 郭柳娉; 郭冬明', '中国国防报', '中国国防报', '博物馆;上海劳动妇女战地服务团;', '写在前面 8月1日，江西新余，阳光明媚。位于抱石公园内的赣西抗战博物馆游人如织。 赣西有着丰富的抗战历史。近年来，新余市军地积极开展文物保护工作，充分调动了社会各界保护文物的积极性。2017年，文物爱好者宋子枫在各界人士帮助下，正式创建赣西抗战博物馆，展示多年', '2022-08-25 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2022.001574', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4306, '报纸', '英雄的军队 胜利的征程', '解辛平', '解放军报', '解放军报', '不可战胜;战争史;', '今天，人民军队迎来95岁生日。 95载，弹指一挥间。人民军队诞生那一年，世界上诞生了第一个石英钟，人类战争在计时工具进化的精确谐振中，脚步变得更加急迫而混乱；也是在那一年，“不确定性原理”从实验室里走出，原子尺度的小小粒子开始改变世界。 今天，“不确定性”依', '2022-08-01 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.003994', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4307, '报纸', '我们的队伍向太阳', '郭杰; 谢颖', '人民政协报', '人民政协报', '郑律成;《中国人民解放军军歌》;《八路军进行曲》;向太阳;八路军;', '编者按： “向前!向前!向前!我们的队伍向太阳，脚踏着祖国的大地，背负着民族的希望，我们是一支不可战胜的力量……”今年是中国人民解放军建军95周年，在中国共产党的领导下，人民军队走过了光辉的历程。雄壮的《中国人民解放军军歌》伴随着人民军队取得了一个又一个胜利，', '2022-07-23 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2022.004989', '抗日战争1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4308, '报纸', '“为我深爱着的祖国写歌”', '韩亚栋; 薛鹏', '中国纪检监察报', '中国纪检监察报', '全面从严治党;难忘今宵;《我的祖国》;', '“那个教我们‘荡起双桨’的人离去了！”6月20日凌晨3时，著名词作家乔羽因病在北京逝世，享年95岁。 “一条大河荡起双桨都说祖国风光好，难忘今宵爱我中华百姓思念夕阳红。”资深乐评人金兆钧的一副挽联，串起了乔羽作词的《我的祖国》《人说山西好风光》《让我们荡起双桨', '2022-06-21 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.002543', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4309, '报纸', '“红绿交织”绘就太行新画卷', '范世辉; 高博; 魏飚', '新华社;', '新华每日电讯', '前南峪;碳中和;太行山;南沟村;红色基因;示范工厂;革命老区;产业振兴;', '巍巍太行山，绵延八百里。抗日战争时期，中国共产党在太行山脉开辟了晋察冀、晋冀鲁豫等抗日根据地。在这里，中国共产党领导的八路军和太行人民谱写出无数英雄壮歌，太行精神孕育在太行山间。 由于历史原因，太行山部分沿线地区长期发展受限，曾被列为燕山—太行山集中连片', '2022-06-05 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.004033', '抗日战争1_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4310, '报纸', '一个文艺战士的炽热情怀', '袁丽萍', '解放军报', '解放军报', '反“扫荡”;抗敌剧社;', '写在前面 在战火纷飞的年代里，我军诸多革命文艺战士牺牲在战斗前沿，牺牲在为人民服务的道路上。他们用鲜血和生命践行着革命文艺为工农兵服务的宗旨，立起一个个光辉典范。2019年5月，笔者曾专访著名剧作家胡可，听他动情回忆起牺牲在日寇刺刀下的剧作家吴畏同志。站在延安', '2022-06-02 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.002878', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4312, '报纸', '《在延安文艺座谈会上的讲话》与延安鲁艺人', '张影', '中国文化报', '中国文化报', '延安鲁艺;《在延安文艺座谈会上的讲话》;民族危亡;文艺工作者;延安文艺座谈会;夫妻识字;冼星海;毛泽东;校友会;艺术家;', '1942年5月，延安文艺座谈会召开，出席人员中，鲁艺师生占半数之多。 延安文艺座谈会后，毛泽东同志又亲赴鲁艺演讲，号召大家走出“小鲁艺”，走向“大鲁艺”，指明了到工农兵群众生活中去的方向，极大激发了鲁艺人的创作热情。彼时，音乐家马可身在鲁艺，深受毛泽东同志《在', '2022-05-23 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.001478', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4313, '报纸', '中国人民大学的红色基因', '李云舒', '中国纪检监察报', '中国纪检监察报', '中国人民大学;华北大学;共产党;陕北公学;华北联大;红色基因;', '4月25日，习近平总书记来到中国人民大学考察调研。 85岁的中国人民大学，是由中国共产党创办的第一所新型正规大学，前身是1937年诞生于抗日战争烽火中的陕北公学，以及后来的华北联合大学和北方大学、华北大学。 自诞生之日起，中国人民大学始终与党和国家同呼吸、共命运。', '2022-04-27 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.001778', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4315, '报纸', '60多年前突破“卡脖子”技术的人', '李晨阳', '中国科学报', '中国科学报', '余国琮;化工系;', '28岁那年，他的名字被列入美国科学家名录。短短几个月后，他历经艰辛，辗转回到了自己的祖国。37岁那年，周恩来总理紧紧握着他的手，嘱托解决那个“卡我们脖子”的问题。最终他不负众望，开发出了被沿用至今的关键技术，为新中国核技术起步和“两弹一星”的突破作出了重要贡', '2022-04-08 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2022.002585', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4316, '报纸', '让英雄在文艺作品中得到弘扬', '', '中国文化报', '中国文化报', '文艺作品;《永不消逝的电波》;周文雍;习近平总书记;王佳俊;文华大奖;广州起义;舞台布景;袁慧琴;', '编者按：习近平总书记指出，“对中华民族的英雄，要心怀崇敬，浓墨重彩记录英雄、塑造英雄，让英雄在文艺作品中得到弘扬。”中华民族有慎终追远、缅怀先辈的优良传统，在清明节，我们祭奠祖先、寄托哀思，也缅怀为民族独立解放、国家繁荣富强做出奉献和牺牲的英雄先烈。本版', '2022-04-05 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.001099', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4317, '报纸', '回望光辉历史 感悟如磐初心', '李筱', '团结报', '团结报', '佟麟阁;爱国主义教育基地;', '生活在北京的人，对西城区宣武门内的“佟麟阁路”可能都不陌生。这条路为纪念抗日将领佟麟阁而得名，而佟麟阁将军则是全面抗战爆发后为国捐躯的第一位高级将领。 香山脚下，有一条不为游人熟知的杰王府路，在这条路上的香山北正黄旗18号院内，坐落着佟麟阁将军的墓地和他的', '2022-02-24 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2022.000299', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4318, '报纸', '乌斯浑河畔“烈女标芳”', '刘伟; 王春雨; 董宝森; 王建威', '新华每日电讯', '新华每日电讯', '八女投江;林口县;乌斯浑河;女战士;', '“八女投江”的事迹是我国14年抗日战争历史上的壮烈一页。84年前，以冷云为首的东北抗日联军8名女战士，在顽强抗击日本侵略军的战斗中，投入滚滚的乌斯浑河英勇牺牲，用生命谱写了一曲壮烈的战歌。 “乌斯浑河畔，应有烈女标芳”。抗日名将周保中1938年11月4日在日记中这', '2022-01-25 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.000709', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4321, '报纸', '乡村振兴手拉手，民族团结心连心', '周韵曦; 王永钦', '中国妇女报;', '中国妇女报', '马鞍山村;民族团结;手拉手;', '初冬的喀喇沁旗，天色湛蓝，浮云朵朵。山林间，积雪星星点点，群山环绕下，田舍俨然，错落有致。 喀喇沁旗锦山镇马鞍山村，因一个形似马鞍形状的山峰得名，全村总面积虽只有21平方公里，却是一个有着丰富红色基因的革命老区村。抗日战争时期，马鞍山村是冀察热辽抗日根据', '2022-01-11 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2022.000091', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4322, '报纸', '党领导中国抗战的纲领性文献', '', '中国共产党历史展览馆;', '学习时报', '《论持久战》;抗日战争;毛泽东;共产党;纲领性文献;中国抗战;游击战;', '“中国会亡吗？答复：不会亡，最后胜利是中国的。中国能够速胜吗？答复：不能速胜，抗日战争是持久战。”这段言简意赅的问答是毛泽东1938年在《论持久战》中的著名论断。在中国全民族抗战进行到10个月的时候，毛泽东发表《论持久战》，总结全国抗战经验，系统阐明党的抗日持', '2021-12-31 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002503', '抗日战争1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4323, '报纸', '铸造一往无前的精武“战车”', '谢小杭', '中国组织人事报', '中国组织人事报', '党支部;', '这是一份跨越近百年的忠诚。在抗日战争年代，它是一战成名的“夜袭阳明堡战斗模范连”；迈入改革强军新征程，它是苦练打仗本领的“强军精武红四连”。 建连94年来，这支队伍为何能一直思想政治过硬、军事训练过硬、战斗作风过硬？因为有堡垒过硬的党支部!从“全军先进基层', '2021-12-30 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.004037', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4324, '报纸', '红色村庄的绿色转型', '李慧斌; 侯馨远', '农民日报;中国农网;', '农民日报', '马安村;红色文化;绿色转型;', '说起北京市房山区十渡镇，人们首先想到的多是山清水秀的美丽景致。其实，历史上的十渡地区不仅风景秀美，还是华北地区一块坚固的抗日根据地。马安村便是其中典型的代表。 从平西抗日战争纪念馆沿涞宝路向北行驶4公里，便到马安村。村庄位于两山环抱中，谷壁峭立，峰林叠翠', '2021-12-23 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2021.005567', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4325, '报纸', '挖掘精神之源', '李丹琳', '金融时报', '金融时报', '具象化;共产党人;精神谱系;红九军团;', '一部电影《我的长征》，带我们回到红军不畏艰难险阻的长征年代；一首歌曲《南泥湾》，唱出了革命年代共产党人砥砺前行的精神面貌；一台芭蕾舞剧《沂蒙颂》，展现着军民融为一体的感人历程…… 日前，由中国文联网络文艺传播中心、光明网主创，中国文学艺术基金会支持，制', '2021-12-17 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.006633', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4326, '报纸', '专著典籍记录中国军民抗日救国最强音', '丁国锋; 罗莎莎', '法治日报', '法治日报', '南京大屠杀遇难同胞纪念馆;大屠杀;南京保卫战;南京安全区;侵华日军;中国军民;抗日救国;线上线下;中文报纸;国家公祭日;南京沦陷;《新中华报》;', '2021年12月13日，第8个国家公祭日。一场特殊的观影会在位于江苏省南京市栖霞山东麓的江南水泥厂难民营旧址举行，这座被誉为“江南方舟”的厂区深处有一座黄色小楼在树杈枝丫间若隐若现。这里曾经是两万多名南京难民免遭日寇屠杀和蹂躏的避难所，也是近代有识之士通过“实业兴', '2021-12-14 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2021.007037', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4327, '报纸', '领导抗日战争的纲领性文献', '张殿兴', '中共天津市委党校;', '团结报', '《论持久战》;毛泽东;中国政法大学;抗日武装;共产党;抗日战争;中国共产党领导;纲领性文献;', '【编者按】 百年风霜雪雨，百年大浪淘沙。走过百年历程，一代代中国共产党人留下了可歌可泣的篇章、照亮星空的思想，汇聚成一条奔流涌动的红色精神血脉。 了解历史才能看得远，理解历史才能走得远。理解历史，需要我们不时走进蜿蜒曲折的峡谷山径，重回走过的路，走进', '2021-12-11 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.002321', '抗日战争1_screened,九一八事变_screened,洛川会议_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4328, '报纸', '“支撑北线，保护边区”', '曾鹿平; 高扬', '延安大学马克思主义学院;西安翻译学院;陕西省决策咨询委员会社会组;', '人民政协报', '邓宝珊;边区政府;陕甘宁边区;', '1944年12月22日，毛泽东在给邓宝珊的亲笔信中表示：“八年抗战，先生支撑北线，保护边区，为德之大，更不敢忘。” 这封信说的是抗日战争时期，邓宝珊任二十一军团军团长、晋陕绥边区总司令，驻守榆林。当时陕甘宁边区的南、东、西三面均受到国民党顽固派的军事包围与经济', '2021-12-09 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.009308', '抗日战争1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (4329, '报纸', '杨虎城长女杨拯坤的革命经历', '郭松林', '汉中市延安精神研究会;', '团结报', '北京市;杨虎城;陕甘宁边区;西北局;川陕苏区;西安事变;张蕙兰;国民党;杨拯民;革命经历;', '1941年，在西安女中上学的杨拯坤，化名周盼，在党组织的护送下从汉中西乡去了延安，从此踏上了革命的征程。 将门虎女 杨拯坤，1924年生于蒲城，是爱国将领杨虎城的长女。她的名字是父亲杨虎城给起的，取拯救乾坤之意，寄寓了将军的远大抱负和对长女的殷切希望。她与哥', '2021-12-09 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.002308', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4330, '报纸', '党在延安时期的学习', '樊莉莉', '中央党史和文献研究院;', '学习时报', '毛泽东;中共中央;马列主义;反对主观主义;宗派主义;在职干部教育;延安时期;', '学习，是中国共产党与生俱来的鲜明品质。中共中央落脚陕北后，总结历史经验教训，进一步深刻认识到：“我们所处的环境，比任何时候要来得复杂；我们的任务，也特别来得繁重与艰难。我们的民族，正与敌人进行着决死的搏斗，要在这个空前的历史战争中，求得自己的生存，因之必', '2021-12-01 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002276', '抗日战争1_screened,中共七大1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4331, '报纸', '战斗英雄刘仁香二三事', '姜瑞荣; 孙达恺', '江苏省金湖县政协文史委;', '人民政协报', '战斗英雄;', '刘仁香（1927-2006），江苏省宝应县（现金湖县）人，1941年参加新四军，1943年加入中国共产党，先后经历了抗日战争、解放战争、抗美援朝战争。他智勇兼备，屡建战功（立大功1次、三等功3次、四等功5次），为中国人民的解放事业作出了不朽贡献，曾荣获“全国战斗英雄”荣誉称', '2021-11-11 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.008716', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4333, '报纸', '老区精神 永远镌刻在历史丰碑上', '颜珂', '人民日报', '人民日报', '人民军队;历史丰碑;习近平总书记;傅连暲;红军主力;王树声;', '老区和老区人民，为我们党领导的中国革命作出了重大牺牲和贡献。这些牺牲和贡献永远镌刻在中国共产党、中国人民解放军、中华人民共和国的历史丰碑上。我们要永远珍惜、永远铭记老区和老区人民的这些牺牲和贡献，继承和发扬老区和老区人民的光荣传统，为实现“两个一百年”奋', '2021-11-09 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011739', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4334, '报纸', '“要革命，不能顾家”的金如柏', '赵怀志', '学习时报', '学习时报', '晋西北抗日根据地;八路军;毛泽东;余秋里;', '人如其名，他如松柏般傲然挺立于世间。他经历过枪林弹雨、走过长征，新中国成立后曾任最高人民法院副院长、解放军军事法院院长。他就是开国少将——金如柏。 “只要让我革命，什么都可以忍受”。金如柏是家中独子，9岁时父亲去世。1926年7月北伐战争开始后，农民运动蓬勃', '2021-11-08 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002110', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4337, '报纸', '为解放事业光荣地流尽了最后一滴血', '张丹; 王艳', '学习时报', '学习时报', '冀南军区;解放事业;', '“五·二一”烈士陵园位于河北省衡水市武邑县任角村东，1942年5月21日，三百多名烈士长眠于此。陵园坐北朝南，园内有一座烈士纪念亭，亭内纪念碑正面刻着“三百英烈纪念碑”7个大字，背面刻着碑文，碑文如下： 烈士岗碑志： 一九四二年四月二十九日，日本帝国主义者对', '2021-11-05 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002082', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4339, '报纸', '大山巍巍 精神永恒', '杨珏; 钟超; 王丹; 李建斌', '光明日报', '光明日报', '太行精神;八路军太行纪念馆;吕梁山;', '“左手一指太行山，右手一指是吕梁……”太行山壁立万仞，吕梁山沟壑纵横，南北绵延400多公里的太行吕梁，犹如两条巨龙纵卧在中国北方。 一曲《在太行山上》，仿佛能听到太行军民奋勇杀敌的怒吼；一部《吕梁英雄传》，仿佛能看到吕梁儿女浴血奋战的身影。这些斗争音符与画', '2021-11-01 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005569', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4340, '报纸', '双峰并峙的精神丰碑', '谭靓青; 史利鹏', '解放军报', '解放军报', '八路军太行纪念馆;太行山;太行精神;吕梁山;精神丰碑;双峰并峙;', '山西也是具有光荣革命传统的地方，是八路军总部所在地，是抗日战争主战场之一，建立了晋绥、晋察冀、晋冀鲁豫抗日根据地，平型关大捷、百团大战等闻名中外，太行精神、吕梁精神是我们党宝贵的精神财富。 ——习近平 在中国，无人不知太行，无人不晓吕梁。 千百年来', '2021-11-01 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006870', '抗日战争1_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4341, '报纸', '铸就太行精神吕梁精神的不朽丰碑', '青平', '中国青年报', '中国青年报', '太行精神;抗日战争;八路军总部;', '1937年7月7日，抗日战争全面爆发。根据党中央和毛泽东的战略部署，朱德总司令率领八路军强渡黄河，挺进太行。八路军总部和中共中央北方局长期驻扎在太行山区，领导和指挥敌后抗日军民建立了晋绥、晋察冀、晋西南、晋冀鲁豫等抗日根据地，进行艰苦卓绝的斗争。平型关大捷、雁', '2021-11-01 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.003910', '抗日战争1_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4342, '报纸', '弘扬南泥湾精神 风雨无阻向前进', '龚仕建; 张丹华', '人民日报', '人民日报', '南泥湾精神;南泥湾大生产;陕甘宁边区;三五九旅;', '延安是革命圣地。延安时期是我们党领导的中国革命事业从低潮走向高潮、实现历史性转折的时期。老一辈革命家和老一代共产党人在延安时期留下的优良传统和作风，培育形成的以坚定正确的政治方向、解放思想实事求是的思想路线、全心全意为人民服务的根本宗旨、自力更生艰苦奋斗', '2021-10-29 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011393', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4343, '报纸', '吴学周院士的一生：为党奉献 科学报国', '杨仑', '科技日报', '科技日报', '吴学周;', '28年前的深秋，刚刚在病床上度过81岁生日的吴学周迎来了好消息：中共中央组织部和吉林省委接受他的入党申请，同意他加入中国共产党。吴学周终于实现多年的夙愿。 1983年1月1日，吴学周正式向党提交了入党申请书。当时的他年逾八旬，左眼失明，右眼视力仅有0.03。不到千字', '2021-10-29 08:00:00', 'https://link.cnki.net/doi/10.28502/n.cnki.nkjrb.2021.005861', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4344, '报纸', '民革成立前李济深与国民党民主派的联合', '李穗梅', '民革广州市委会;', '团结报', '李济深;蔡廷锴;陈铭枢;十九路军;国民党;生产人民党;中国国民党临时行动委员会;致公党;中国民主促进会;邓演达;', '孙中山逝世后，中国国民党分裂成不同的政治势力和军事集团，彼此博弈与交织，影响了中国道路的走向。他们中一部分人坚定维护三大政策，始终反对蒋介石集团独裁、反共的政策；另一部分人高举抗日与民主两面大旗，从反蒋、逼蒋到倒蒋，在此过程中，李济深作为扛旗者殚精竭虑，', '2021-10-28 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.002066', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4345, '报纸', '白山黑水间写下不朽史诗', '任爽; 刘勇; 张士英', '光明日报', '光明日报', '东北抗联;贫困县;东北抗日联军;杨靖宇;艰苦奋斗精神;抗联精神;', '“我们是东北抗日联合军，创造出联合军的第一路军。乒乓的冲锋陷阵缴械声，那就是革命胜利的铁证……”吉林省白山市杨靖宇将军纪念馆，激昂的《东北抗日联军第一路军军歌》响起，带头领唱的，正是杨靖宇将军(原名马尚德）的嫡孙马继民。 今年，再次回到爷爷曾经战斗过的地', '2021-10-27 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005451', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4348, '报纸', '这所高校如何铸就“共和国外交官的摇篮”？', '涂铭; 赵旭', '新华每日电讯', '新华每日电讯', '北京外国语大学;一带一路;外交官;共和国;', '1941年，战火纷飞中，中国人民抗日军事政治大学三分校俄文队，在延安成立，开创了中国共产党独立创办高等外语教育之先河，后几经合并更名，发展为北京外国语大学（下称北外）。 2021年，在中国共产党百年华诞这一伟大的历史时刻，北外迎来建校80周年。一路走来，北外始终', '2021-09-29 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007598', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4351, '报纸', '七十年寸步不退的坚守', '曹智; 陈梦阳; 李铮; 张逸飞', '新华社;', '新华每日电讯', '沙地治理;研究所;樟子松;彰武松;彰武县;护林员;章古台镇;', '中国农民丰收节就要到了。 科尔沁沙地南缘，辽西北小城阜新市彰武县，翠绿的林海、无际的草原、金黄的稻田……这与昔日的黄沙漫天形成鲜明对照。 1951年，东北人民政府在彰武县章古台镇设立苗圃，70年来，面对内蒙古高原呼啸而下的肆虐风沙，42万彰武人寸步不退、誓守', '2021-09-17 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007235', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4352, '报纸', '卫国使命犹在 思乡暂搁心头', '刘翔霄; 马志异', '新华每日电讯', '新华每日电讯', '朝鲜战场;八月十五;张德才;志愿军;解放战争;', '中秋节谁不想家？但在过去那个保家卫国的年代，中秋节或许就是在行军路上甚至战斗中度过的，一把炒面、一口凉水就是老兵们的中秋饭，他们“赏”的也不是月，而是伴着炮火、枪声。 2021年中秋节前夕，记者走近几位抗美援朝、解放战争老兵，听他们讲述烽火年代的中秋故事。', '2021-09-17 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007270', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4353, '报纸', '探抗联密营，在“生死场”体味“荒野抗敌”', '韩宇; 陈聪; 管建涛; 侯鸣; 何山', '新华每日电讯', '新华每日电讯', '亮子河;朝阳山;东北抗日联军第六军;生死场;', '中国版图的东北端，人迹罕至的密林深处隐藏着一处处废弃的壕沟和坑洞，显示着过去曾有人生活过的痕迹。这就是东北抗日联军于20世纪三四十年代在敌后建立的秘密宿营地——抗联密营。 2021年盛夏，新华每日电讯记者翻山越岭，进入这片秘境。在茂林和远山衬托下，一处处密营', '2021-09-17 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007272', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4354, '报纸', '把红色故事讲给更多人听', '李霞', '人民日报', '人民日报', '党史资料;战斗英雄;', '党的历次全国代表大会精神，他熟记于心；共和国将军功勋、战斗英雄事迹，他娓娓道来……他认真学习积累，如今党史笔记有100多万字，收集保存的党史资料摞起来有1米多高。 他是湖北省黄石市黄石港区沈家营社区退休老党员王明林，今年85岁，已经义务宣讲党史10多年，宣讲的', '2021-09-16 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.009885', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4355, '报纸', '纪律严明，人民军队从胜利走向胜利', '周文元; 赵小军; 欧阳浩', '解放军报', '解放军报', '人民军队;政治规矩;党对军队绝对领导;全面从严治党;革命军人;全军官兵;', '百年大党，在伟大自我革命中永葆生机活力！ 人民军队，在铁的纪律锻造中始终胜利向前！ 人民军队党缔造，自诞生之日起就将党的纪律写在自己的旗帜上，一路红旗漫卷，在广袤辽阔的中华大地站稳了脚跟、战胜了强敌，打出了一个红彤彤的新中国。 在热火朝天的建设年代', '2021-09-13 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.005960', '抗日战争1_screened,夹金山_screened,四渡赤水_screened,飞夺泸定桥_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4356, '报纸', '开国大将陈赓之女陈知进：从父亲的戎马一生中读懂忠诚与担当', '陈姝', '中国妇女报;', '中国妇女报', '开国大将;', '家庭小传 陈赓，杰出的无产阶级革命家、军事家，中国人民解放军的卓越领导人，新中国国防科技、国防教育事业的奠基者。1922年加入中国共产党，历经抗日战争、解放战争、抗美援朝战争等，他为中国人民的解放事业、为中国人民解放军的创建和发展、为新中国的国防科技事业做', '2021-09-08 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.002824', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4357, '报纸', '94岁交代后事，才打开锁入箱底的功与名', '王若辰', '新华每日电讯', '新华每日电讯', '陆国安;人民功臣;棕树皮;', '“我和二十几个村民被日军抓去了。我当时只有14岁，个子也小。有人训我们，说见到日本人要喊‘太君’，要弯腰鞠躬，不然就要杀头。日本人来了，别人都弯下腰去，把我露了出来——我腰板挺直，坚决不向烧了我们全村的日寇鞠躬。” “我是家里的独儿子，就在心里使劲儿盘算', '2021-09-07 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007000', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4359, '报纸', '从“红船”到“红城”，“石榴籽”是这样抱起来的', '丁铭; 达日罕', '新华每日电讯', '新华每日电讯', '内蒙古自治运动联合会;乌兰浩特;民族区域自治制度;乌兰夫纪念馆;北京蒙藏学校;蒙古自治政府;豫海县回民自治政府;石榴籽;', '1921年，在嘉兴南湖红船上，中国共产党成立，开启救亡图存之路。1947年，在“红城”乌兰浩特，党的民族政策生根发芽，结出新的果实。 中国共产党经过百年探索，历经从“红船”到“红城”的实践，形成了中国特色解决民族问题的正确道路的重要内容和制度保障——民族区域自', '2021-09-03 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.006896', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4360, '报纸', '八路军总部为何“避水而居”', '梁晓飞; 许雄; 宋育泽', '新华每日电讯', '新华每日电讯', '八路军总部;华北方面军;八路军太行纪念馆;侵华日军;敌后抗日根据地;华北治安战;武乡县;黎城县;', '“为了不和老百姓争水吃，八路军被迫转移，枪林弹雨，多流了多少血!”山西省武乡县砖壁村91岁的肖江河老人回忆起80多年前的一幕，声音忍不住颤抖。 砖壁村，地处巍峨的太行之巅。抗日烽火燃遍全国时，这个群山环抱的小山村曾是华北敌后抗战的指挥中心。 八路军太行纪念', '2021-09-03 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.006892', '抗日战争1_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4361, '报纸', '抗战胜利时各地民众的喜悦', '曾景忠', '团结报', '团结报', '抗战胜利;日本投降;陈公博;无条件投降;李庄镇;周佛海;总司令部;', '1945年8月8日，蒋介石巡视川东回到重庆，得知美国原子弹轰炸日本广岛。9日，他得知苏联对日宣战。这时，他已经在考虑沦陷区收复后免征一年田赋捐税。10日，他考虑接收东北和各省复员。这一天，他开军事会议，“指示敌寇投降时之各种措施，与预备事项”。下午8时，蒋介石忽闻', '2021-09-02 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001770', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4362, '报纸', '太行山上巾帼情', '杜京', '中国妇女报', '中国妇女报', '太行山上;八路军太行纪念馆;妇女指导委员会;晋东南;姐妹们;深秋时节;康克清;武乡县;拥军模范;做军鞋;浦安修;', '千百年来，太行山以豪迈的气势，巍然屹立在华北这片神奇的土地上。行走在太行山上，就是行走在记忆的时光里，穿梭在岁月的风尘里。 在纪念中国人民抗日战争胜利76周年前夕，我同朱德的孙女朱新华、罗荣桓的外孙女陈炎炎一行，回到我的老家长治。我们同上太行山，怀着崇敬', '2021-09-02 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.002705', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4363, '报纸', '“爱国爱党是他的坚定信念”', '高乔', '人民日报海外版', '人民日报海外版', '望远镜;华侨华人;指挥所;坚定信念;晋绥军区;八路军;军分区;共产党;抗日救国;', '在中国华侨历史博物馆“百年航程 赤子侨心——庆祝中国共产党成立100周年主题展”上，一张1937年由曼谷炮台县开具的侨民返乡许可证，默默讲述着泰国归侨回到中国参加抗日战争的历史故事。这份返乡证的主人是泰国归侨、抗战老兵苏青，他的子女于2014年将返乡证捐赠给华侨历史', '2021-09-01 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002688', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4364, '报纸', '新安旅行团与新四军', '邵雍', '上海师范大学人文学院;', '团结报', '新安旅行团;国统区;新四军;新四军军部;盐阜区;', '1929年，人民教育家陶行知在江苏淮安创办了新安小学。从1934年起，陶行知热心推广“小先生制”，“小先生”成为普及教育、宣传抗日救国的生力军。在江淮大地诞生、闻名中外的新安旅行团，就是把“小先生制”运用于抗日救亡运动的伟大实践。 听党话：新安旅行团在国统区的', '2021-08-26 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001732', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4365, '报纸', '赤子情深终未改', '穆东平; 穆晓方; 穆晓枫; 穆也平', '中国新闻出版广电报', '中国新闻出版广电报', '长篇通讯;吴吉昌;新华社;焦裕禄;', '2021年，是中国共产党建党100周年，也是我们的父亲、著名记者穆青诞辰100周年。作为党培养出来的第一代记者，穆青一生几十年的新闻足迹走遍祖国的大江南北。他用手中的生花妙笔，谱写出了一篇又一篇荡气回肠的时代华章。 一 1937年“七七事变”后，日本鬼子大举进攻中', '2021-08-20 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.003313', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4367, '报纸', '《初心》艺术再现农民将军甘祖昌感人故事', '张雪娇', '中国新闻出版广电报', '中国新闻出版广电报', '甘祖昌;艺术再现;《初心》;人民社;', '不久前，广东人民出版社出版的长篇纪实文学《初心》，以新疆军区原后勤部部长甘祖昌和爱人龚全珍先进事迹为原型，翔实记述农民将军甘祖昌在新中国成立后始终不忘让乡亲们过上好日子的庄严约定，带领乡亲们艰苦奋斗、改变家乡落后面貌的感人故事。 作为纪念中国共产党成立1', '2021-08-16 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.003256', '抗日战争1_screened,反围剿_screened,龚全珍_screened');
INSERT INTO `ds_article` VALUES (4368, '报纸', '广西学生军：战火中的青春之歌', '刘伟; 向志强; 陈一帆; 雷嘉兴', '新华每日电讯', '新华每日电讯', '甘宗容;广西团校;青年运动史;战火中的青春;', '“我们是广西青年学生军，我们是铁打的一群，在伟大的时代里担负起伟大的使命……” 这首慷慨激昂的歌曲诞生于1937年，一群意气风发的青年辞别亲人，高唱着这首歌义无反顾地奔赴抗日战场。 80多年过去，如今仍健在的广西学生军战士已经不多。90多岁的甘丽坤患有严重的', '2021-08-06 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.006114', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4369, '报纸', '弘扬抗战精神 昭前事惕后人', '赖志凯', '工人日报', '工人日报', '抗战精神;宛平城;卢沟桥;', '永定河环绕北京城，卢沟桥横亘永定河，“七七事变”就发生在这里。 卢沟桥的两头各有一位耄耋之年的“守桥翁”。在卢沟桥东头的是中国人民抗日战争纪念馆筹建人、曾任卢沟桥文物保管所所长，今年93岁的郭景兴老人。 在卢沟桥西头的是曾任丰台区宛平城地区办事处副调研', '2021-08-06 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2021.003726', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4374, '报纸', '用延安精神滋养初心淬炼灵魂', '李志勇', '中国纪检监察报', '中国纪检监察报', '延安精神;习近平总书记;解放思想、实事求是;', '延安，中国革命的圣地。巍巍宝塔山，见证了中国共产党从胜利走向新的胜利的光辉历程；滚滚延河水，映射出中国共产党人的初心使命。 从1935年10月到1948年3月，党中央在延安13年，带领全党夺取抗日战争伟大胜利、实现解放战争战略转折，开展整风运动、大生产运动，召开党的', '2021-08-04 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003742', '抗日战争1_screened,枣园_screened,中共七大1_screened,中共七大1_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (4375, '报纸', '中国革命走向辉煌的力量之源', '罗旭; 张哲浩; 周晓菲', '光明日报', '光明日报', '延安精神;共产党人;力量之源;中国共产党领导;思想路线;毛泽东;解放思想、实事求是;习近平总书记;政治方向;党中央;', '今年7月1日，陕西延安，宝塔山、枣园革命旧址、杨家岭革命旧址、延安革命纪念馆装扮一新，鲜红的党旗高高飘扬。上午8时，来自全国各地的游客纷纷驻足，就近收听收看庆祝中国共产党成立100周年大会。 “几回回梦里回延安，双手搂定宝塔山。”很多游客都是在党的百年华诞之', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003942', '抗日战争1_screened,枣园_screened,中共七大1_screened,杨家岭_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4376, '报纸', '滋养初心 淬炼灵魂 延安精神永放光芒', '党柏峰; 苗生顺', '中国妇女报;', '中国妇女报', '延安精神;根本宗旨;毛泽东;南泥湾精神;共产党人;陕甘宁边区;中华民族;', '“一道道的那个山来哟一道道水/咱们中央红军到陕北/一杆杆的那个红旗哟一杆杆枪/咱们的队伍势力壮……山丹丹的那个开花哟红艳艳/毛主席领导咱打江山。”站在宝塔山上，俯瞰滚滚延河水，聆听着信天游，环顾这片红色的土地，几百个红色革命旧址遍布沟沟峁峁。使人宛若置身于那', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.001854', '抗日战争1_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4377, '报纸', '到“红色中国”去，见证中华民族的解放事业', '蔡馨逸', '新华每日电讯', '新华每日电讯', '中国共产党;中华民族;马海德;美军观察组;陕北苏区;红色中国;解放事业;', '当国民党对延安进行军事围困和新闻封锁时，记者埃德加·斯诺冲破封锁，将延安真实的情况公之于世；当陕北苏区缺医少药，医生乔治·海德姆留下来与他的中国朋友并肩战斗，在战火中救死扶伤；当中国共产党需要与同盟国建立直接联系时，美军观察组到访延安，得出未来的中国属于', '2021-07-30 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005834', '抗日战争1_screened,白求恩_screened,强渡大渡河_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (4378, '报纸', '广东汕尾海丰县新山村 “红色”“绿色”“古色”三色发展谱新篇', '杨迪', '农民日报;中国农网;', '农民日报', '海丰县;“红色”;', '新山村位于全国十三块红色革命根据地之一广东海丰县，是全省首批“红色村”。中国共产党成立之初，农民运动先驱彭湃曾在这里宣传发动农民运动，广大村民踊跃投身革命，为人民解放事业抛头颅、洒热血，涌现了吕培其一门七英烈等广为传颂的壮烈事迹。 资源禀赋不佳、缺乏产', '2021-07-26 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2021.003430', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4379, '报纸', '战斗英雄郭瑞祥：百年足迹，丈量初心', '梅世雄; 刘敏', '新华每日电讯', '新华每日电讯', '战斗英雄;发起进攻;东明县;党组织;', '“这是党授予的最高荣誉，一定要亲自来领。” 2021年6月29日，101岁的郭瑞祥身着绿军装，坐在轮椅上接受了习近平总书记亲自授予的“七一勋章”。 中国共产党百年光辉历程，郭瑞祥既是见证者又是参与者。作为军人，他先后荣立二等功1次、三等功2次，1957年被授予三级独', '2021-07-23 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005677', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4380, '报纸', '以信仰的力量，做苍生大医', '凌锋; 王天奡', '全国政协;首都医科大学宣武医院神经外科;', '人民政协报', '苍生大医;日本鬼子;', '“生如夏花之绚烂，死如秋叶之静美!”这句诗来形容我先生的姑姑崔健吾烈士再合适不过了! 姑姑出身书香门第，家中兄妹三人，长兄继承父业，是工程师。1937年，抗日战争爆发时，她还是天津师范学院即将毕业的大学生。但她和上大学的弟弟一起，凭着年轻人的血性，很快找到当', '2021-07-21 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005869', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4381, '报纸', '前进路上不怕任何艰难险阻', '张千千', '新华每日电讯', '新华每日电讯', '长征精神;红军长征;中国共产党;', '一件满是破洞的棉衣、一双无法覆盖双脚的布草鞋，静静陈放在中国共产党历史展览馆。 80多年前，一支衣着褴褛、装备简陋的队伍，像地球的红飘带一样穿越了中国大地的险山恶水，冲破了敌人的围追堵截，完成了一次开创新局的伟大远征——长征。 双脚丈量大地，鲜血铸就河', '2021-07-16 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005474', '抗日战争1_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,红井_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (4382, '报纸', '跨世纪的“白求恩”', '王天奡', '人民政协报', '人民政协报', '白求恩;医疗队;胸外科;中日友好医院;辛育龄;外科大夫;', '用全拼方法输入“辛育龄”这个名字，一时还没有默认词组提供。 但，拥有这个名字的百岁老人，在建党百年前夕，被授予了党内最高荣誉——“七一勋章”，举国传颂。 他是中日友好医院首任院长、首席专家、胸外科主任，是新中国胸外科事业的开拓者和奠基人，更是在少年时', '2021-07-14 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005671', '抗日战争1_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4383, '报纸', '在巴蜀山水间感受多党合作事业“前世今生”', '康锦谦; 丁英华', '新华每日电讯', '新华每日电讯', '多党合作;遂宁市;筇竹杖;民主党派;统战部;夹关镇;中国国民党革命委员会;中国民主同盟;三民主义同志联合会;共产党人;山水间;', '新华社成都7月10日电（记者康锦谦、丁英华）一条不长的小街，却每天都吸引络绎不绝的游客前来瞻仰。这里是“重庆谈判”的重要场所、“双十协定”的签订地，是世界反法西斯战争中国战区统帅部所在地，也是中国民主同盟、中国国民党革命委员会前身之一——三民主义同志联合会的', '2021-07-12 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005403', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4385, '报纸', '让红色记忆代代相传', '施芳', '人民日报海外版', '人民日报海外版', '红色记忆;革命文物;长辛店;邵飘萍;主题片;专题展;', '北京，新文化运动的中心、五四运动的策源地、马克思主义在中国早期传播的主阵地、中国共产党的主要孕育地之一。 百年历史激荡，文物见证荣光。今年3月，北京市公布第一批革命文物名录，包括不可移动革命文物158处、可移动革命文物2111件/套，其中全国重点文物保护单位18处', '2021-07-07 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002030', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4386, '报纸', '95岁老党员莫天佑：走出枪林弹雨 当好人民公仆', '杨春竹; 李兰兰; 李梦媛', '中国气象报', '中国气象报', '人民公仆;共产党员;渡江战役;', '从抗日战争到解放战争，从战争年代到和平年代，从拿枪到拿笔——历史中一路穿行拼搏出来的莫天佑，有着跌宕起伏的不凡一生。战争年代不怕牺牲、不畏艰难，和平年代顾全大局、自强不息，有着77年党龄、15年战斗经历的莫天佑，用行动向我们诠释了一名共产党员的初心和信念。', '2021-07-05 08:00:00', 'https://link.cnki.net/doi/10.28122/n.cnki.ncqxb.2021.000857', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4388, '报纸', '延安：建立全新的人民司法制度', '王丽丽', '人民法院报', '人民法院报', '马锡五审判方式;陕甘宁边区高等法院;高等法院院长;司法制度;最高人民法院;', '点睛 延安，是中国革命的圣地，也是人民司法优良传统的重要诞生地之一。1935年中央红军长征到达陕北，1937年1月党中央进驻延安。1937年7月，陕甘宁边区高等法院成立，由边区政府领导，受边区参议会监督。成立之初，内设审判法庭、书记室和看守所等机构，全院编制共6人，后', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003041', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4389, '报纸', '左权：红色热土上的司法为民情', '白龙飞', '人民法院报', '人民法院报', '晋冀鲁豫边区婚姻暂行条例;参议会;司法为民;高等法院;晋冀鲁豫边区政府;岳冬至;', '2021年5月25日，正值左权将军殉国79周年。 79年前的这天，面对头顶盘旋的敌机，左权将军不顾个人安危，指挥部队突围转移，不幸被弹片击中头部，壮烈牺牲。 “名将以身殉国家，愿拼热血卫吾华”，历史的浮尘难掩英雄的光辉，英雄的精神持续滋养着这片红色的热土。为纪念', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003042', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4391, '报纸', '关向应：响应主义之召唤', '于险峰; 张仁军', '农民日报;中国农网;', '农民日报', '关向应;中央委员;', '关向应同志原名关致祥，字和亭，乳名喜麟子，满族人，满族姓瓜尔佳氏。1902年9月10日出生于辽宁省金县一户满族农民家庭。1920年4月，18岁的关致祥以优异的成绩考入大连伏见台公学堂附属商业科读书。 1922年8月，关致祥在大连泰东日报社找到了一份工作。在这里，关致祥结识', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2021.003091', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4392, '报纸', '勋章闪亮映初心', '张洋', '人民日报', '人民日报', '共产党人;陆元九;黄文秀;吴天一;习近平总书记;辛育龄;王兰花;渡江战役;村党支部书记;牧民增收;村干部;', '2021年6月29日，在即将迎来中国共产党成立100周年的历史时刻，中共中央“七一勋章”颁授仪式在京隆重举行，习近平总书记亲自颁授“七一勋章”并发表重要讲话。 29名为党和人民作出杰出贡献的“七一勋章”获得者，接受党和人民的最高礼赞。首次颁授的“七一勋章”，金闪闪', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006802', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4393, '报纸', '同心同德一戎衣', '', '人民政协报', '人民政协报', '抗日民族统一战线;国共两党合作;全面抗战路线;洛川会议;卢沟桥事变;共产党;抗日救亡;武装斗争;毛泽东思想;', '1939年，延安。7月，毛泽东在欢送一批青年学生奔赴抗日前线时说，当年姜子牙下昆仑山，元始天尊赠了他杏黄旗、四不像、打神鞭三样法宝。现在你们要出发上前线，我也赠你们三样法宝，这就是统一战线、游击战争和革命中心的团结。10月，毛泽东在为《共产党人》写的发刊词中强调', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005342', '抗日战争1_screened,洛川会议_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4394, '报纸', '“七一勋章”获得者', '', '人民日报', '人民日报', '荣誉称号;人大代表;村党支部书记;获得者;', '马毛姐，女，汉族，1935年9月生，1954年6月入党，安徽无为人，安徽省原合肥市服装鞋帽工业公司副经理。解放战争时期支前英模的杰出代表，闻名全国的“渡江英雄”。渡江战役中，年仅14岁参加“渡江突击队”，在手臂中弹的情况下依然咬牙坚持，不畏枪林弹雨6次横渡长江，运送3', '2021-06-30 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006781', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4395, '报纸', '浙江新华：发挥主渠道优势 创新党史学习教育', '黄琳', '中国新闻出版广电报', '中国新闻出版广电报', '新华书店;浙江省;桐乡市;党史学习;主渠道;', '“红梅花儿开，朵朵放光彩。昂首怒放花万朵，香飘云天外……”6月17日，浙江省新华书店集团党委组织离退休党支部赴抗日战争胜利浙江受降纪念馆开展主题党日活动，回望沉重历史、缅怀抗日英烈、牢记伟大胜利。现场，大家发自内心用歌声感恩祖国、感恩党。 浙江省新华书店作', '2021-06-28 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.002470', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4396, '报纸', '一封“寻亲信”揭开11位湘籍烈士的英雄往事', '周楠', '新华每日电讯', '新华每日电讯', '退役军人;烈士陵园;事务厅;湖南省;华北军区;', '一封特殊来信，揭开一段尘封的历史。 11份泛黄档案，隐藏着11个壮怀激烈的英雄故事。 一封穿越75年的家书，一座屹立在村民心中82年的丰碑，两名原籍信息成谜的烈士，四位仍待亲友前来寻找的英雄。 …… 近日，新华每日电讯记者追踪采访一段为烈士“寻亲”的经历', '2021-06-25 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005119', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4397, '报纸', '太行红色“信使”讲党课，让人听得泪流满面', '王学涛; 徐伟', '新华每日电讯', '新华每日电讯', '八路军太行纪念馆;纪念碑;长乐村战斗;左权将军;叶成焕;八路军总部;', '56岁的崔韶光像一个“信使”，将共产党人的光辉事迹和感人精神传播到全国各地。记者跟随她讲课月余，没有一堂课上不见听众泪光 “为啥崔韶光的课能产生这样的效果？因为她真信、真做、用真情讲” “太行山的每一块石头，都曾经生长过光荣……我深深地爱着我平凡的岗位', '2021-06-25 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005117', '抗日战争1_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4398, '报纸', '入党前后的那些日子', '朱训', '国家地质矿产部;政协第八届全国委员会;', '人民政协报', '新四军军部;根据地;华中建设大学;刘少奇;国民党;化工厂;', '今年，2021年，是中国共产党成立100周年。 今年，也是我加入中国共产党75周年。 入党前的日子是，沐浴抗日战争烽火，分享抗战胜利喜悦! 入党后的岁月是，投身三年解放战争，迎来新中国的诞生! 共产党来了!共产党真好! 我是江苏阜宁县人，1930年出生于江苏阜宁', '2021-06-24 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005166', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4399, '报纸', '别人往后退时，你要向前', '郎浩舟', '中国新闻出版传媒集团;', '中国新闻出版广电报', '新闻工作者;火线入党;基层党组织;', '在山西左权麻田西山上，有一座太行新闻烈士纪念碑，上面镌刻了这样一段鲜为人知的历史：有人以笔为枪不幸中弹、有人临危不惧纵身跳崖……在1942年日本侵略者发起的大扫荡中，57名新闻工作者壮烈牺牲，他们用鲜血书写了中国新闻史上最为悲壮的一页。 1942年5月，日军集结重', '2021-06-11 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.002220', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4400, '报纸', '刘胡兰：领袖两度题词的女英雄', '闫树军', '中国人民解放军后勤学院;', '人民政协报', '刘胡兰;胡文秀;云周西村;文水县;朱永生;女英雄;', '“生的伟大，死的光荣”，毛泽东主席先后两次挥毫泼墨，把这个评价赋予了一位优秀的共产党人、一位杰出的中华儿女——刘胡兰。这在中国共产党的历史上是绝无仅有的。 是谁第一个挥泪写下女英雄？毛泽东主席因何两次为刘胡兰题词？杀害刘胡兰的凶手是怎样找到并得到应有惩', '2021-06-10 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.004767', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4402, '报纸', '宝塔光辉映照信仰伟力', '刘笑伟', '解放军报', '解放军报', '中国共产党人;延安城;毛泽东;', '延安精神培育了一代代中国共产党人，是我们党的宝贵精神财富。要坚持不懈用延安精神教育广大党员、干部，用以滋养初心、淬炼灵魂，从中汲取信仰的力量、查找党性的差距、校准前进的方向。 ——习近平 “毛泽东的队伍穿过黄褐色的山谷——头道川，来到地处陕西黄土高原', '2021-05-29 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.003448', '抗日战争1_screened,九一八事变_screened,枣园_screened,论持久战_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (4403, '报纸', '刘胡兰：生的伟大，死的光荣', '刘翔霄', '新华每日电讯', '新华每日电讯', '刘胡兰;云周西村;文水县;妇救会;八路军;', '“姐姐性格刚烈。她被敌人带走时，特意把奶奶生前留给她的指环摘下，取出手绢以及一个用完却没扔弃的万金油盒交给了母亲。母亲当时不解，事后才意识到，姐姐既已把最珍视的东西留给亲人，就是决意与敌人决战到底。” 在山西文水县刘胡兰纪念馆内，66岁的刘继烈含泪向记者', '2021-05-25 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.004144', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4404, '报纸', '历史和人民的正确选择', '曾峻', '上海市习近平新时代中国特色社会主义思想研究中心;', '人民日报', '中国共产党;正确选择;', '习近平总书记指出：“历史和人民选择中国共产党领导中华民族伟大复兴的事业是正确的，必须长期坚持、永不动摇”。站在“两个一百年”奋斗目标的历史交汇点上，回顾历史和人民选择中国共产党的过程与原因，对于进一步坚持和加强党的全面领导、深入推进党的自我革命、永葆党的', '2021-05-25 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.005488', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4407, '报纸', '谢雪红与二二八起义', '郭海南', '台盟中央宣传部;', '团结报', '谢雪红;李纯青;二二八起义;杨克煌;', '今年是台湾省人民二二八起义74周年，也是台盟首任主席谢雪红诞辰120周年。台盟中央原主席张克辉指出：“没有二二八就没有谢雪红，没有谢雪红就没有台盟。”在二二八起义中，谢雪红是台中地区的起义领袖，是这次起义很有影响的人物。起义失败后，谢雪红等人辗转香港成立了台湾', '2021-02-25 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.000416', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4408, '报纸', '太行浩气传千古', '梁婧', '经济日报', '经济日报', '八路军总部王家峪旧址;太行根据地;抗日根据地;太行精神;人民战争;太行山区;侵略者;陕甘宁边区;左权将军;', '年终岁尾，天寒地冻，心却澎湃火热。在中国共产党即将迎来百年华诞之际，记者怀着无比崇敬的心情，来到位于山西省长治市武乡县的八路军总部王家峪旧址纪念馆。 在那战火纷飞的年代，许多重要指示、重大决策通过电波、信函从这里发往各个根据地；八路军总部的首长们在这里', '2021-02-09 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.001491', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4409, '报纸', '周恩来对台湾同胞的关怀', '郭海南', '台盟中央宣传部;', '团结报', '台湾同胞;田富达;祖国大陆;周恩来;', '1月8日是周恩来总理逝世45周年纪念日。周恩来一生十分关怀台湾同胞，为实现祖国统一大业呕心沥血，台湾同胞永远铭记在心。 支持台湾同胞的革命活动 周恩来在黄埔军校担任政治部主任时，特别吸收几批台湾青年入校学习，并派人回台湾进行革命活动，在台湾播下了革命的种', '2021-01-14 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.000105', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4410, '报纸', '李友邦和台湾义勇队的故事', '郭海南', '台盟中央宣传部;', '人民政协报', '李友邦;台湾义勇队;台湾少年团;广东台湾革命青年团;台湾同胞;', '今年是中国人民抗日战争暨世界反法西斯战争胜利75周年，也是台湾光复75周年。10月25日，“金瓯无缺——纪念台湾光复75周年主题展”在中国国家博物馆开幕。 在主题展上，“复疆”二字格外醒目。这里展出的是在台籍抗日将领李友邦的领导下，台湾义勇队充分发挥自身优势，与', '2020-12-03 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2020.007611', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4411, '报纸', '不可忘却的纪念', '郝思斯', '中国纪检监察报', '中国纪检监察报', '九一八事变;历史博物馆;中国共产党;六三指示信;东北抗战;东北军;日本关东军;抗日斗争;', '今天是九一八事变89周年。每逢这一天，警报、警钟、鸣笛会在中国许多城市上空响起。14年抵御外侮的烽火中，中华民族完成了凤凰涅槃的重生，铸就了伟大的抗战精神。 “九一八”的警钟为何要长鸣？今天我们重温抗战历史、传承抗战精神，有怎样的现实意义？本报就此对话沈阳', '2020-09-18 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2020.004635', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4412, '报纸', '“八百壮士”的最后岁月', '余玮', '《中华儿女》杂志社;', '人民政协报', '八百壮士;通城县;四行仓库保卫战;谢晋元;', '电影《八佰》的热映，让1937年8月“八百壮士”的浴血传奇重现公众视野。147分钟的精彩剧情，让我们直达历史现场，重温那裹着血与火的硝烟…… 闻名天下的“八百壮士”最后被迫放下武器，退进租界孤军营。1942年秋，日军将“八百壮士”分散押解到浙江诸暨、杭州，安徽裕溪', '2020-09-10 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2020.005428', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4413, '报纸', '《论持久战》的新时代回响与史鉴价值', '潘宏', '广西壮族自治区党委;自治区人民政府;', '学习时报', '《论持久战》;毛泽东;习近平总书记;正定县;', '今年是中国人民抗日战争暨世界反法西斯战争胜利75周年。习近平总书记指出，这场战争“是正义和邪恶、光明和黑暗、进步和反动的大决战”。这场战争彻底打败了日本军国主义侵略者，洗刷了近代以来中国抗击外来侵略屡战屡败的民族耻辱，捍卫了中华民族五千多年发展的文明成果和', '2020-09-02 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2020.001755', '抗日战争1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4414, '报纸', '中华民族共同体意识唤起巨大凝聚力', '朱维群; 孙冬冬', '中共中央统战部;第十二届全国政协民族和宗教委员会;全国政协民族和宗教委员会;', '环球时报', '中华民族;抗日战争;帝国主义;民族聚居区;', '中国自古就是一个统一的多民族国家。近代以来，帝国主义的侵略、分割和掠夺唤起了中国人作为一个民族整体——中华民族的觉醒。其中，又以抗日战争空前增强和深化了中华民族的共同体意识。在抗日战争胜利75周年即将到来之时，我们有必要深刻认识到中华民族共同体意识的重要性', '2020-08-14 08:00:00', 'https://link.cnki.net/doi/10.28378/n.cnki.nhqsb.2020.007151', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4415, '报纸', '名人记忆中的《民主》周刊', '毛梦溪', '民进中央宣传部;', '人民政协报', '《民主》;周建人;马叙伦;社会主义民主政治;中国民主促进会;', '抗战胜利后，中国面临两条道路、两个前途的抉择。 在当时国共两党的对立斗争中，《民主》周刊坚决拥护中国共产党的革命政治路线与和平、民主、团结的总方针，反对国民党反动派的独裁和内战政策，揭露反动政府的倒行逆施，对推动爱国民主运动的发展起了鼓舞群众、团结群众', '2020-07-23 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2020.004154', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4416, '报纸', '在战火中刻写民族品格', '陈先义', '解放军报', '解放军报', '《谁是最可爱的人》;志愿军;文艺创作;麻扶摇;中国人民志愿军战歌;民族品格;', '革命战争中的文艺，历来都是激励战士冲锋的号角和战鼓。 抗美援朝，是新中国成立后我军进行的第一场出国作战，也是我军与强大的帝国主义军队进行的一场保家卫国的反侵略战争。这场战争，同样是对我军文艺队伍的一次考验。响应党中央的号召，大批文艺工作者踊跃奔赴战场，', '2020-07-12 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2020.003608', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4417, '报纸', '从党的七大汲取看齐意识的精神力量', '薛琳', '学习时报', '学习时报', '党的七大;组织路线;中央委员会;精神力量;毛泽东思想;', '中国共产党是一个善于研究历史的政党，更是一个善于学习历史经验的政党。2015年2月14日，习近平总书记重访党的七大礼堂，动情地讲：这里我来过多次，插队时每次到延安都要来看看，每次都受到精神上的洗礼。七大是“建党以后民主革命时期我们党最重要的一次代表大会”，它系统', '2020-05-29 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2020.001081', '抗日战争1_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4418, '报纸', '深切缅怀马洪同志 不断提高服务中央决策的能力和水平', '马建堂', '国务院发展研究中心;', '中国经济时报', '决策咨询;国务院发展研究中心;中央决策;', '今年5月18日，是马洪同志诞辰100周年。马洪同志是中国共产党的优秀党员、忠诚的共产主义战士、当代著名经济学家，是我国决策咨询工作的开拓者和领导者之一。新中国成立后，他曾先后担任国家计划委员会秘书长、中国社会科学院院长、国务院副秘书长、国务院经济技术社会发展研', '2020-05-18 08:00:00', 'https://link.cnki.net/doi/10.28427/n.cnki.njjsb.2020.001003', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4419, '报纸', '彰显“亲劲、韧劲、拼劲”的县委书记', '蔡松涛', '河南省开封市委;兰考县委;焦裕禄干部学院;', '学习时报', '', '焦裕禄是县委书记的榜样，也是全党的榜样。2020年1月8日，习近平总书记在“不忘初心、牢记使命”主题教育总结大会上指出，新中国成立以后，正是因为我们党有一大批像焦裕禄、谷文昌、杨善洲这样的英雄模范率先垂范，才团结带领人民群众不断开创各项事业发展新局面。重读焦裕', '2020-03-13 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2020.000476', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4420, '报纸', '中国人民的朋友——贝熙业', '眉豆', '中国纪检监察报', '中国纪检监察报', '八路军;李石曾;', '中国人民不会忘记 2014年3月，习近平总书记访问法国的时候，在两次演讲中都提到了一个人——贝熙业：“我们不会忘记，无数法国友人为中国各项事业发展做出了重要贡献。他们中有冒着生命危险开辟一条自行车‘驼峰航线’，把宝贵的药品运往中国抗日根据地的法国医生贝熙业。', '2019-09-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQu5qozpWLC9fFMKgExJPHk5vxEv_P4dqMQyYl4iPW15hwT0_Okew-1Mtx1TiCzd-85fG_-ptvbIbXi5mlCKnLYdGvNReDDCj54D2Kckk3ld_tftkFtdK2xg8pOQBq6L2BNdrysKMGffw==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4421, '报纸', '大王庄传承的延安精神', '高学升', '江苏省泗洪县纪委监委;', '中国纪检监察报', '延安精神;彭雪枫;刘瑞龙;', '位于江苏省泗洪县陈圩乡的大王庄，抗日战争时期是淮北区党委、淮北行政公署和新四军四师司令部所在地，也是当时为数不多的集党政军一体化的办公场所。在抗日战争和解放战争初期，陈毅、彭雪枫、刘瑞龙、张震等老一辈无产阶级革命家都曾在这里工作、生活、指挥战斗，给日本侵', '2019-07-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ7XGMygrJ30vZY_b2uRjhhjpW4EfkDt5xqZvVgDXWgTQefFp-vJNGzXt0RzlZntG7G3k77V0E8c4JGdZjD2QHDxxgjltyYb83KlrKOTudNtYToHWkBOAwzslHOsd5CZ81DF-zO0c9iqg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4422, '报纸', '肖永顺：我就信奉共产党的规矩', '黄媛媛', '北京市顺义区纪委监委;', '中国纪检监察报', '焦庄户;共产党;', '1937年7月7日，卢沟桥事变后，抗日战争全面爆发，全国人民掀起轰轰烈烈的抗日救国斗争高潮。一个位于北京市顺义区东北部燕山余脉歪坨山下的普通小村庄，以其独特的方式——地道战，与日寇进行着顽强斗争，这就是焦庄户村。全国爱国主义教育示范基地焦庄户地道战遗址纪念馆就', '2019-07-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT3JxjzsaV9WJBxTLNN0NZ5qnMFN580vr7HZMRJnNCx4czioNZkoP0AxMKlDIXgIFLPv9EJ3n61CDqbmQSvi6NKMoOrmdWnfnB_HS71TgKwG5a40SiiNpnkDH0K8BLhV7To53Snq5biUQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4423, '报纸', '将理论武装贯穿主题教育全过程', '罗平汉', '中共中央党校(国家行政学院)习近平新时代中国特色社会主义思想研究中心;', '解放军报', '理论武装;主题教育;全过程;牢记使命;习近平新时代中国特色社会主义思想;党内教育;', '掌握马克思主义理论的深度，决定着思维视野的广度、政治敏感的程度、思想境界的高度。因此，这次开展的“不忘初心、牢记使命”主题教育，把“理论学习有收获”作为具体目标之一。这就要求我们必须将强化理论武装贯穿主题教育始终，聚焦解决影响广大党员干部“守初心、担使命', '2019-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTq1SlTzAalD9P2Bu34tgM8ru7sBd1VhDtcI9zEui_eAgF7ZekMxudvE4gZFwICwAs-MG7XiaYbvt_tlob0eb652L5lqMYxFfcEar_VJAEVGHNnD4TboPbRW-gas0ZGcOkDEm3utvPuoQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4425, '报纸', '纪念嘉兴起义70周年学术研讨会撷英', '', '团结报', '团结报', '共产党;段伯宇;国民党军队;段仲宇;国防部预备干部局;学术研讨会;', '【编者按】 今天，“团结沙龙·历史篇”与读者见面了。这是文史周刊创刊时推出的“史学沙龙”专栏改版后的新样子。“团结沙龙·历史篇”的推出，旨在以观点呈现的形式反映史学界的研究热点，将最新研究成果及时传达给读者。值纪念嘉兴起义70周年学术研讨会举办之际，我们', '2019-04-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTolQMaTMsMBR66RL97lS52_VfCRT_WM8vlRQcQya1Q-o4gLhZ-vsAMAZM_t08RxXz9oJjGHBVLM9nBmOMT0h-PWWQFX4vbaON_uFIMjQnJ37U54iHCiH653Lmlx8IDLdUK-9aQ0P6qNA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4427, '报纸', '《论持久战》发表的前前后后', '王今诚', '中国延安干部学院教学科研部;', '团结报', '《论持久战》;毛泽东;抗日战争;国民党;持久抗战;', '1938年5月的某个早晨，在延安城内凤凰山脚的石窑里熬了数个日夜的毛泽东，终于停下了笔，伸伸腰走到门外，凝视着泛起的晨曦。窑内的桌上放着厚厚一沓文稿，散发出浓浓墨香，最上面一页潇洒的题写着四个大字《论持久战》。此时的毛泽东或许还不曾完全预料到，这部著作将成为“', '2018-05-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTBC_h5YYj74z_Bqor1uYPoGNF3Q_vFtBcCAVBkrxgHj2SZg5MkzXdr5gPO6StxO8XhC0oaXAb7B22JnBocGamYnXvlKIqB_tLfbtH4BhnwSEIVih_RS3rlE-r0Z2xjMVKpcA4HoF8FJQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4428, '报纸', '在纪念周恩来同志诞辰120周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '周恩来;党和国家;共产党人;国民党统治区;座谈会;', '同志们，朋友们： 今天，我们怀着十分崇敬的心情，在这里隆重集会，纪念敬爱的周恩来同志诞辰120周年，深切缅怀他为党、人民、国家和人民军队建立的卓著功勋，追思和学习他作为中国共产党人杰出楷模的崇高精神。 周恩来同志是伟大的马克思主义者，伟大的无产阶级革命', '2018-03-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR_N-HPn0PBMEQARZOY1eO-fMbKIWt6hxljpQSALLc5ut_3Xul5wlG33ygHBoFhh7l38FP0SBB0DHbXncYXyBmOlMRewDRUq-h6JRb0J6So26pFNqKOGD19TBl2UJZ4Us1e7KufyajOUA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4429, '报纸', '陕西：六个“下功夫” 处处求实效', '张政 ; 张君华 ; 殷燕召 ; 张哲浩 ; 沈耀峰 ; 王斯敏 ; 钟超 ; 唐芊尔', '光明日报;', '光明日报', '十九大精神;华州区;渭南市;宣传贯彻;', '编者按 一座华彩庄严的历史里程碑，在中华民族砥砺奋进的道路上巍然屹立；一场凝聚人心的学习热潮，在全党全国各族人民中蓬勃兴起。当前，学习宣传贯彻党的十九大精神，用习近平新时代中国特色社会主义思想武装头脑、指导实践、推动发展，是全党全国的首要政治任务，更是', '2017-11-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQoVwdr2cH_kO5kp3blv67fAVpGHy5mkFNKxkl9Bi7OzFPi-ZElTkopnXw0cILndCLqJ-uDsd5wydxBUB7RleBCM_zz-Q0rSxfRcuZOu-MaozUgUhbl0QhxhwSGSF6YeBHLnLE0YTd1mg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4430, '报纸', '聚焦打赢砺雄师', '徐双喜; 周猛; 李宣良; 王经国', '新华社;', '解放军报', '军事斗争准备;中央军委;习主席;联合作战指挥;实战化训练;战斗力建设;', '“戎马鸣兮金鼓震，壮士激兮忘身命”。 2017年5月24日，一道电波穿越重霄，从首都北京传向辽阔大海。正在海军作战指挥大厅视察工作的习主席，在了解海军当日海空兵力活动情况后，临机与在海上执行战备巡逻任务的538舰视频通话，褒奖他们战风斗浪、连续奋战，勉励他们忠实', '2017-09-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQXRRqGxYDzF4n6mHJ7hl82vhAlBNwEiux82UEql9n3XNMhq-hb7lrGaFfPQvMhFZyfD36CnFKieWoCK4twSrS-qf55r_27dfpZew7ciXFwJ75CINh3ikoqaZm8k7xTNeBAXx-ePAH-kg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4431, '报纸', '《沙家浜》36个伤病员的由来', '高建国', '解放军报', '解放军报', '伤病员;新四军;后方医院;旅史馆;阳澄湖;政治部主任;沙家浜;《沙家浜》;', '抗日战争中新四军36个伤病员坚持阳澄湖斗争的传奇故事，经沪剧《芦荡火种》和京剧《沙家浜》广为传播后不胫而走，一些当年曾在阳澄湖后方医院养伤的老同志争相对号入座,当年曾战斗在阳澄湖上的医护和警卫人员，也都以跻身36个伤病员行列为荣。一时间，谁是36个伤病员众说纷纭', '2017-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRBbzelDtIMH347QU7ve7HPfmNYDVYhUWCOif0NcCOtru9Zx-so7vrNjTEGDdWaUAwl3VcpczlDkKTNNxD-mWCO5DDRMMr5_c_A-Gj-LfQ-Z1dg9IbhP9nE0JhdxV9Ln1lKi4LmovFq3A==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4433, '报纸', '强军之路(上)', '', '人民日报', '人民日报', '国防和军队改革;习近平;中央军委;习主席;改革强军;强军之路;领导指挥体制;开除党籍处分;强军梦;世界反法西斯战争;《新闻联播》;', '【字幕】2015年9月3日 北京 纪念中国人民抗日战争暨世界反法西斯战争胜利70周年阅兵仪式 【解说词】 金秋的北京碧空如洗，中国的首都又一次成为世界瞩目的地方。 2015年9月3日，中国以一场气势恢弘的盛大阅兵，纪念中国人民抗日战争暨世界反法西斯战争胜利70周年', '2017-07-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTvwndF3qOzj159p7kkjp4iTCm6zswLdc57zyP_KILFO5XxRCsUYcuojPDx1pSlcu8T8FfaqUHem2AwdUDNLe7A2v8puA0frkHCa-vT-Vv-pdlDsL1NU1_smi_SG3ZN0y4ARFdgqBjkBg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4434, '报纸', '如果战争再次爆发，这支驻守平型关的部队能打赢吗', '王达', '中国青年报;中青在线;', '中国青年报', '平型关;八路军;', '编者按 今年是中国人民解放军建军90周年。“军队是要打仗的。”习主席指出，“军人的主要担当就是要能打仗、打胜仗。”回顾人民解放军90年的辉煌历程，就是一部光辉灿烂、可歌可泣的革命史和奋斗史，更是一部南征北战、敢打必胜的战争史和胜利史。经过几代人不懈努力，解', '2017-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSxVjAukvo7PvNyHIrdNQunkhpELqz3toU28zaySHw2apKWYccixUMynpvDXUqAErqwlJCAEABzoAdHfg8MhSVIZjPp_g78HsMZ2OxI9v7IL61y3O0I-pXyXZLWn0aeZFzkTP_dzC2b2Q==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4435, '报纸', '小火星里蕴含“燎原力”', '周远; 何睦', '解放军报', '解放军报', '秋收起义;国民党军;三湾改编;支部建在连上;农民自卫军;', '【单位名片】中部战区陆军某旅前身是毛主席领导的秋收起义主力之一，“三湾改编”后创建全军第一个连队党支部，开创了“支部建在连上”的先河。土地革命时期，先后参加了井冈山斗争、五次反“围剿”和长征。 6月下旬，记者走进第83集团军某旅，翻开该旅前身部队在我军建', '2017-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRUu8PROE22405VraNH6DcVS5Tr4AMxRuC1QUIPHWj3V-x9jPkIQyi282HfOel8roG8fEV4ohF8cb5Dh5Q2-5zLRbkpUB0uPqsl_9YBqFAZ-t1gv-C2qqnxNE_TUPrG3fAdOYlYrNfqrg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,茨坪_screened');
INSERT INTO `ds_article` VALUES (4436, '报纸', '我们为什么怀念西南联大', '张渺', '中国青年报;中青在线;', '中国青年报', '国立西南联合大学;潘际銮;陈省身;梅贻琦;闻一多;中国青年报;李政道;“两弹一星”;南开大学;刘文典;叶公超;校友会;', '潘际銮收到国立西南联合大学录取通知书，是在1944年，正值16周岁。 他出身书香门第，总听到父亲谈及工业救国。“当时想的是，等仗打完之后，就能去建设国家了。”如今在清华大学的办公室里，潘际銮笑着说。阳光隔着窗，洒在他身前的茶几上。 这位老人如今是中国科学', '2017-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQfKs59jWKO4dsgJ9uLZ-74e0KVuuVWJv1M2_b5HZpN-xl3VNq1IwluC3IrmplZ-VfWyoSjPJDCoXk57W0G7oL5CI2AXwpXyR1K9IEmc6390BhjweCjioDehlebne16r8aG0srDVbbAOg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4437, '报纸', '北平解放前台盟革命活动', '吴艺煤', '团结报', '团结报', '革命活动;', '1945年8月，中国人民抗日战争取得伟大胜利，旅居北平的台籍爱国人士在中共领导下参加了抗日活动，为北平的抗日斗争做出了贡献。而后，他们在中国共产党领导下，投入到反对国民党独裁腐败的斗争中，为人民解放战争，为新中国的建立做出了贡献。 1947年11月12日，参加台湾', '2017-06-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQUZXVeM2Wr0kmsCWcOl4yOG2xoKzDiLCPHMt67wLhXRRUkKkWSPKPXBSAio6xRJX2leeBSQ6kYpFtJKCKVwXc8LLdCQOyr2YdrbgH5nwNlyUZeMJwjTwRT7KoQagfnppXcSBbvpHJUaQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4438, '报纸', '“八年”到“十四年”，完整呈现抗战史', '屈菡', '中国文化报', '中国文化报', '抗战史;东北抗联;', '2016年9月18日，在国家图书馆举办的“不朽的抗联——中国记忆项目东北抗日联军专题资源建设成果展”上，93岁的东北抗联老战士李敏来到现场，她含着热泪说，希望在有生之年看到国家将抗战史改为十四年，否则死不瞑目。如今，她多年的愿望实现了。 教育部日前发文，要求201', '2017-01-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT3eVC4HNRPR1hBvVLL4jOp3iFUcPfrAPJREGXxPYvXs-KD0fwMGYg6mi08CJSkHo1kz68gq3fIzABeQH1qldub3WjMdoLS3Cw-NYWH0ceB3C1DZwLHtR2E5Y94QNppArysrRAd9a7jFA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4439, '报纸', '在纪念朱德同志诞辰130周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '朱德同志;毛泽东;马克思主义;旧民主主义革命;纪律检查工作;共产党人;座谈会;', '同志们，朋友们： 今天，我们在这里集会，纪念朱德同志诞辰130周年，缅怀他为民族独立和人民解放、国家富强和人民幸福建立的不朽功勋，追思他为党和人民事业不懈奋斗的光辉一生，学习他的崇高品德和精神风范，激励全党全军全国各族人民满怀信心把中国特色社会主义伟大事', '2016-11-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTGV8InQJaxwHgL1D7-kzqcVWr6fmp_dUoRQiAiKDhNMN1WrlHVYgAvyMwYnwbPxrqDEY1OGbJkqZXC_dp5wvvBvoAvvkpKxpXUxb0b3tRgi6upaqE2ATeG-lfd7ZKzLOi4KdBKX9Qcvg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,中共七大1_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (4441, '报纸', '在纪念刘华清同志诞辰100周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '刘华清;国防和军队建设;军事斗争准备;座谈会;', '同志们，朋友们： 今天，我们在这里召开座谈会，纪念刘华清同志诞辰100周年，缅怀他为党、为国家、为人民、为军队作出的杰出贡献，追思他的革命精神和高尚品格，激励全党全军全国各族人民为实现“两个一百年”奋斗目标、实现中华民族伟大复兴的中国梦而努力奋斗。 刘', '2016-09-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQz3GLdb4GeXCee3oacQX1r1zbEzt5X3ZjojM1HM0xiAxKFbdjk77MSHbshYUW3jnUlNYBrgsgjQKok1c_0TyNhSPgCVpd-_mxkTEnHSsoWR3XeMH5K2oHj6NvupkEgekeCQM9wjzkk1Q==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4442, '报纸', '在纪念刘华清同志诞辰100周年座谈会上的发言', '', '人民日报', '人民日报', '刘华清;“文化大革命”;习近平同志;国防科技工业;中央军委;座谈会;', '中央党史研究室主任曲青山： 今天，我们怀着十分崇敬的心情，参加纪念刘华清同志诞辰100周年座谈会，深切缅怀他的光辉业绩和崇高风范。我的发言，着重回顾刘华清同志在艰苦卓绝的革命征程中，以对党的赤胆忠诚和对人民的无比热爱，为民族独立、人民解放作出的重要贡献。', '2016-09-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSIzBikHwncETr5-7USGvtRX2fpUn0YHjOFrKb66TrpKawC8uk-R1RJpguz1W1L1PoXEXx29b5LjtzWYmhkqD1KLfWPDGAd0gvPuPX_6Kqxl81iPrRY8suSK4F5x2YUm-oNC3u7zQuKIQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4443, '报纸', '寻找英烈徐志达', '王慧敏', '人民日报', '人民日报', '根据地;烈士证;国民党;新四军;泗安镇;', '2014年6月的一天，单位传达室转给我一封写着“人民日报浙江分社负责同志收”的读者来信。本以为只是一封普通的读者来信，没想到，一拆开，便引发了我将近两年寻找烈士的历程。 杭州 一封耄耋老人的来信 信是长沙一位90多岁的老人写的，从笔顺上判断，老人写信时一定', '2016-04-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRkyQYxfvEoKz8BiFzJ9lulO5CU1XsztHmfXbpC6ZuoOfKsCxAsdGXto3_9jdzfj6n93zwnVVpebOrFyQLAOHMHoJUqq-JTFW06as0QslOKFX1Euq_XQhpGG0wJ8cwVZL1lU7iENyuFFQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4444, '报纸', '在纪念陈丕显同志诞辰100周年座谈会上的讲话', '孟建柱', '中共中央政治局;中央政法委;', '法治日报', '陈丕显;座谈会;', '同志们、朋友们: 今天,我们怀着十分崇敬的心情,在这里召开座谈会,纪念陈丕显同志诞辰100周年,深切缅怀他的光辉业绩,深入学习他为中国革命、建设、改革和法治事业不懈奋斗的崇高风范。 参加今天座谈会之前,我又一次重温了陈丕显同志的生平事迹,深受教育。陈丕显同志是中', '2016-03-30 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2016.006097', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4445, '报纸', '王泉根：新世纪如何书写革命历史题材儿童小说？', '陈香', '中华读书报', '中华读书报', '儿童小说;战争题材;抗战题材;王泉根;儿童文学作品;革命历史题材;', '王泉根：北京师范大学教授、中国儿童文学研究中心主任 所以我自己的观察是，新世纪以来，尤其最近几年，抗战儿童文学写作体现出了一种群体性的创作艺术实践与收获，并已经成为我们新时期儿童文学非常重要的艺术收获。 如果说中国的儿童文学作品还有什么不足的话，我', '2016-01-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTV-sexY1o89TdLNl_j2myzhto_jr42D_yxTMznBXs6p4F1fws5OcVVd28RYwUvIEwruIKQr-kJCcfpABYV2FUlF9Vckh6gzlCtjvJ0LPqqIJwdlz3q9HpFd7vla9kR1ATrfF7MsyNQDw==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4446, '报纸', '2015年度《光明书榜》', '', '光明日报', '光明日报', '大变局;中国环境史;《光明书榜》;杨增新;伊懋可;历史学家;明清之际;文学翻译;《圣经》;叙事态度;', '1. 《抗日战争》（全三卷）（王树增著 人民文学出版社） 推荐人：孙郁（中国人民大学文学院院长） 神奇的交响曲 以恢宏的笔法和诗人的情怀重审八年抗战的历史，王树增找到了一个全景的精神表达式。《抗日战争》出笔不俗，落墨有声，东亚的历史，欧美的战云，', '2016-01-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRDF4FXklaVvk2cLZit715vVgwb_TWx2vfT48arSUGxO-nMBZgWgLFIWNo_fn-E5MARDNSlavA58M2iVJMLSiLEW90oepT0NfWOQUFB0iKux0prKZYDjjF6ZsHEzW3alm8CZUnTM5LbMg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4447, '报纸', '彭德怀到底在哪里？', '沉石', '解放军报', '解放军报', '彭德怀;太行山;山地作战;八路军总部;挺进队;', '在太行山大峡谷，在太行山如刀般的十字岭崖石上，有鲜血刻下的一段岁月——1942年5月。  那年5月，究竟发生了什么？  八路军总部面临日军3万多兵力的围追，八路军副总司令彭德怀和前方指挥部参谋长左权分头突围，左权牺牲；而被围追的八路军总部后勤人员以及', '2015-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS11Fgokp1pKVuPPsvPvXbQMsSAvvHT7LTGVdby45gqnZ1l84Ui4CO37WacM5ZnmGaysmkCj9TuAQabmXA16seccQ66y_7n7-YfsnWRudV9IvHNBiAJddoyUO9ZqeINIK5_abhbYv2SlQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4449, '报纸', '民族英雄钱学森', '宋健', '科技日报', '科技日报', '钱学森;民族英雄;吉本斯;', '钱学森院士（1911—2009）离开我们转瞬已逾六年。国内外记述、忆颂、崇扬先生功勋和风范的书文如海似潮。观瞻纪念中国人民抗日战争暨世界反法西斯战争胜利70周年盛大阅兵后，更觉千章万端，意犹未尽。  新中国成立后，钱学森应祖国呼唤，决定回国。美国麦卡锡反共恶', '2015-11-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSkD1JuX8oSzecbKjgZa9-m3c8Ds8a9aMy6r66Ty2uQ6I1gwgFFtdBi15SrT5cf-vIuimrkbE8uwafPljjAmHOOod4vNJpNnHIQwh8htdgXwNDksn3BBDEMMZUzW3kwgaynjLr4vuRGcQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4450, '报纸', '抗战中的澳门医务界', '李万山', '卫生部;', '健康报', '文化界;战地救护;医务界;秘密联络站;叶挺将军;抗日战争;游击区;抗日民族统一战线;', '澳门在我国版图上是一个弹丸之地，但在抗日战争期间，因其独特的地位成了我国抗战的可靠后方和中转站。广大澳门同胞“倾其所有，不计得失，民族利益至上，全心全意报效祖国”，澳门的医务界更是积极投身抗日救亡的洪流中，为抗战的胜利作出了卓越的贡献。本期，曾在澳门工作', '2015-11-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTGy6VgXWTVTe9578FgfRKfk0Kp5whgBDZUuqnd265ZeW3pmmNBr00cqF4uD-Ojj2a_5EUHLm0oFXxjjkCcGYQp5HnAxWzvNArKk-ujicSzYQnUedHtKRibwq_RQ8leQyOf7ya7lOeQAA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4451, '报纸', '共同铭记历史 共圆伟大梦想', '俞正声', '人民日报', '人民日报', '两岸关系和平发展;统治者;伟大梦想;台湾光复;两岸政治互信;中华民族伟大复兴;台湾回归祖国;日本军国主义;', '各位来宾，各位朋友，各位同志：  今天，我们在这里隆重集会，纪念台湾光复70周年。70年前，中国人民经过艰苦卓绝的浴血奋战，付出巨大民族牺牲，赢得了抗日战争的伟大胜利，同时也结束了日本对台湾的殖民统治，迎来了台湾回归祖国的历史时刻。抗战胜利、台湾光复，', '2015-10-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtStrj0yEX5O-uwdsusfgTgmytywQ3QjBGpiIu3aKVAOfTlLphRRDh8dXuF7jAhTMyY2PMX9ZfhtiO0OSTTh4hz_4VRIpErNFlW-wk9FrM2XlvbQWwaSIxCHUZuQuO7tQm45921vPDPaeQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4452, '报纸', '飞虎队故事里的中美情谊', '柴逸扉', '人民日报海外版', '人民日报海外版', '飞虎队;中美两国;飞行员;驼峰航线;飞机残骸;陈纳德;新津机场;', '2015年9月2日，中共中央总书记、国家主席、中央军委主席习近平在北京人民大会堂向30人颁发了中国人民抗日战争胜利70周年纪念章。其中，飞虎队创始人陈纳德将军的夫人陈香梅和原“驼峰航线”飞行员杰·温雅德作为帮助和支持中国抗战的国际友人及其遗属代表获得纪念章。', '2015-09-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQWfWo19CunNqjyarmXDTqCJzW4t4w0h927JDE3wjl6dKa89GK4mjwtKX5Owf2R07vFKA8WRML65FmgIR-bOUzxCLfuQrqXa5-jVomamsTeWNNC4c8X3FyItMJj7MkW5cC7wo4PFp_9Sg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4453, '报纸', '张震同志生平', '', '人民日报', '人民日报', '国民党军;新四军;', '中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家、军事家，中国人民解放军的卓越领导人，中央军委原副主席张震同志，因病医治无效，于2015年9月3日17时在北京逝世，享年101岁。  张震同志1914年10月5日出生于湖南省平江县长寿镇一个贫苦农民家', '2015-09-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSuVqbTpHYfuNHc0J6QuHaF9VhX1X0pk-wWXD5jSRpv11IXMJCZrVgRvTyR7DeIrQ209_DY8H-bH3bP5t3WflJw4aqzyzgkBda78Gvl3prllo8huTKUBgYDzwrn0uwdn7B8PrmTGSR6GA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,四渡赤水_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4454, '报纸', '铭记抗战历史 共筑美丽梦想', '耿兴敏; 周文', '中国妇女报', '中国妇女报', '抗日民族统一战线;国共合作;中国共产党领导;日本帝国主义;中共中央党史研究室;中国人民抗日战争;知识女性;妇女运动;抗战历史;', '由全国妇联举办的“各界妇女纪念中国人民抗日战争暨世界反法西斯战争胜利70周年座谈会”9月7日在北京召开。 座谈会上，东北抗联教导旅女兵代表李敏，沂蒙红嫂后人代表于爱梅，中共中央党史研究室第一研究部主任、研究员蒋建农，中国社会科学院近代史研究所《近代史资料', '2015-09-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRDnnEfBjf516r3QWoeqTI07IMWWPi6GJqDLNrirpGUnagoj1AN9itdp701XEqHaz0VmMWZ0r7tr1xZRD-f234NbOb81yJxXG4iTKOWBluFDhx3zPlyNQZVBWI4ARHQJsUqBkAiSY72Vg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4455, '报纸', '创造民族复兴的灿烂明天', '', '人民日报', '人民日报', '民族复兴;抗日战争;民族独立;', '“实现中华民族伟大复兴，需要一代又一代人为之努力。中华民族创造了具有5000多年历史的灿烂文明，也一定能够创造出更加灿烂的明天。” 在纪念中国人民抗日战争暨世界反法西斯战争胜利70周年的日子里，习近平总书记先后在颁发抗战胜利纪念章仪式上、在天安门广场纪', '2015-09-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQqeHaaQ2GD5E5U9nFHqRmGywhqLIK5_ms6rr30H5GX1yBIMLcn57c3ZowTYL-kYTdCMGdY3eZzRXtAIHWCeJC1qzWFoXG0JgSf6P8hnTW9a8vA6JShJvAEsBhJCQfg7KT2fYMJDbWbhg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4456, '报纸', '用信念唱响和平与发展的永恒旋律', '李晋荣; 吴春燕; 毕玉才; 高建进; 严红枫; 曾毅; 李晓东; 高平; 张景华; 夏静; 王君; 邵明亮; 贾德勇', '光明网;', '光明日报', '和平与发展;习近平总书记;中国人民抗日战争;抗日战争胜利;中华民族伟大复兴;抗战老兵;', '在中国人民抗日战争暨世界反法西斯战争胜利70周年纪念活动期间，习近平总书记发表了系列重要讲话。连日来，各地干部群众认真学习、领会这一系列讲话，纷纷从不同角度畅谈感想，抒发爱国情怀，表达和平与发展的祈愿。  “三个必胜”坚定奋斗信念  “正义必胜!', '2015-09-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSUuKF7iCbBb_kiOqxmy0Y5-HJzrVM_XaGJI79DfPHe2H0mkxY2Xk4UbNzEcYBK77icTA8sZ-0qnENVtPy7fxHE5gw6jLWPl0aQS_8uPac4uRC9VmFXXv96k9oVT_AuaW3UnxwAXmH3VA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4457, '报纸', '王树增：历史是我们民族的家谱', '李力', '金融时报', '金融时报', '抗日战争;正面战场;三卷本;阅读准备;', '8月28日，军旅作家王树增创作的《抗日战争》第三卷登陆全国各大书店、网店。至此，三卷本《抗日战争》全部集结完毕。这套6年磨一剑、180万字的宏篇，是王树增“战争系列”中最“宏阔的大书”。日前，就该书的创作，记者专访了王树增。 全景式呈现抗日战争 记者：有', '2015-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTaxi4OWwii2kDAI4O7_tzxrbNVm_EPZtaVJUSXhsUctdpD-ozU4mPoObEzVCZM9Bb3Mxqs4D78p57j5fl2FuIqmrnnZIQSe6fn9ZOtjaDZmBMXgdFeDHb4nmE5s_Oh8HFMdajDhRJmIQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4459, '报纸', '中国抗日对世界反法西斯战争的贡献不可替代', '高文', '农民日报', '农民日报', '世界反法西斯战争;抗日战争;不可替代;', '抗战胜利70周年纪念活动新闻中心于9月2日举行记者会，邀请中国国民党革命委员会中央委员会副主席郑建邦、九三学社中央委员会常务副主席邵鸿、台湾民主自治同盟中央委员会副主席黄志贤介绍民主党派人士对抗日战争的认识，并答记者问。  缅怀抗日先烈振兴中华民族', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQMj0Syl3wQ2MKpsDbDrxP-_yff3ZWBryRmvD283t40OeSLlSQzRDN7cql-uE16Ffb6GYGqiNARL-nVV-yaEQ7-00kB-WBeEqPb2zS2Z4MIfkAZcCJ9O4voJbfS6-Tx9p3BzdutE_SHAw==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4460, '报纸', '全人类相互帮助共同抗击法西斯', '高文', '农民日报', '农民日报', '法西斯;凯瑟琳;阅兵仪式;崔可夫;史蒂文斯;抗日战争;二战期间;', '抗战胜利70周年纪念活动新闻中心于9月2日举行记者会，请美国飞虎队员泰德·史蒂文斯遗孀凯瑟琳·史蒂文斯，美国飞虎队员艾伦·拉森，苏军著名统帅崔可夫元帅之孙尼·弗·崔可夫，抗战期间法国友人贝熙业之子让·路易·贝熙业和日本籍八路军老战士筒井重雄之子筒井健史介绍对', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRah23h4cx2NZdZDRxPhrHEIpV2Vh5MmgJIoEynSvKrY1j1kKmyAKb7VuUl_Nr-tLxDnusy1lOTd3ag9LbmZiQm9je4oEH2B-c7JX1ue8EMJ8xMBakOvtgaSaYttjEUG4rcbwGkW3K6nQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4461, '报纸', '夺取抗战胜利的指路明灯', '刘中刚', '中国人民革命军事博物馆展陈研究部;', '经济日报', '《论持久战》;毛泽东;土地革命战争时期;抗日战争;抗战胜利;', '1938年，中国人民抗日战争进入关键时点，在许多人被“亡国论”和“速胜论”的疑云笼罩之时，毛泽东同志发表了著名的《论持久战》。这一蕴含马克思主义辩证法的科学论著，一扫时局之阴霾，以立于高山之巅远看东方朝日喷薄欲出的远见，成为指导中国人民夺取胜利的光辉指南。', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTskljHR_4_wy4qz_0LIkXXGGpPgqYRkkjjuN2MTXsNWS5Faz0PHLYkfiQbzlazcBOXfOgIy9Z90sTaGiyFzsbDLV77a1LFV5RT6-IQQKm3qmm2OxhPiU6WPc3JgojUfPNehJ4rZr6JbQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4462, '报纸', '珍视历史遗存 弘扬抗战精神', '袁沅', '团结报', '团结报', '抗战精神;抗战遗址;民主党派;四行仓库;中国人民抗日战争;世界反法西斯战争;农工党;李国庆;长沙市委;全民族抗战;抗战老兵;文物普查;历史遗存;', '编者按  今年是中国人民抗日战争暨世界反法西斯战争胜利70周年。70年前，中国人民经过艰苦卓绝的斗争，最终实现了民族的独立。70年后，当我们再次回望这场伟大胜利，感佩于先烈的牺牲奉献，感恩于当下的幸福生活，更觉历史不容忘记。然而，70年过去了，我们能做的还', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSLBlOkOqaaslJsIInMO-qbATil5akEimRJy4GBv1GmzzT0D7h4o6XMF74BrQ8Qg293iGPwLAId4xka4RaCYX30tB6HNHQICQBGkTjUBMRiVKqrOi2cGJDlclsqVnHPiU-CfRp-kCqbRw==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4464, '报纸', '中国共产党是抗日战争的中流砥柱', '龚亮', '光明日报', '光明日报', '抗日战争;世界反法西斯战争;正面战场;中国共产党;', '中国人民抗日战争暨世界反法西斯战争胜利70周年纪念活动新闻中心8月29日在京举行记者会，请军事科学院军事历史和百科研究部解放军历史研究室副主任张从田、研究员彭玉龙解读中国人民抗日战争历史的有关情况。  两个战场相互策应是中国抗战的显著特点  张从田', '2015-08-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRA9X-0NxD4S8dxY5FCLCegsLbDDvHDBEJKENc42oIWl64Aj0RNoh8s7suTyLht68zmGnRzzUiH9AzuuEzqf_wR8T0cE88_xBxqnZDUkgVt8FtWIoDxqLmZGZ2IiY7bS9BSDwtby2zkMg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4466, '报纸', '第三集 浴血坚持', '', '光明日报', '光明日报', '持久战略;游击战争;敌后根据地;阿部规秀;战略相持阶段;八路军总部;百团大战;正太铁路;晋察冀军区;卡尔逊;新四军;新墙河;抗日根据地;日本侵略者;', '一  武汉，水陆交通便捷，20世纪30年代时，是长江中游唯一的工业城市。1938年10月25日，武汉陷落，全国抗战从战略防御阶段进入战略相持阶段。对战局的这一巨变，5个月之前，毛泽东就已准确预见到。  1938年5月19日，徐州失守，战局走向混沌迷离。亡国论者认', '2015-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQT6-jroCEb73e1cwf67w7oOjkvmqQTnVcisjkULhIaD6Zqx2c4mrnrX9nmHVj8T4cKgofP2gTB1yug358B92TEtowmRiRuzRvEVA_j5pRN-bmCZqodygOJ_TwfDmVRqm7lbz8oNU2joQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,百团大战_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4467, '报纸', '汪东兴同志生平', '', '人民日报', '人民日报', '汪东兴;中央军委;中央领导同志;“四人帮”;林彪反革命集团;中共中央办公厅;', '中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家，曾担任党的重要领导职务的汪东兴同志，因病医治无效，于2015年8月21日5时28分在北京逝世，享年100岁。 汪东兴同志1916年1月出生于江西省弋阳县一个贫苦农民家庭。少年时代，他开始接受进步思想，', '2015-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRRJnEQ6vJzOPJO7u7UhzQPDfUkkRAw4BGa4LK43mzNNzFc3g2Xg2bM1DmN3SmrmH2NTXc4YXKDc3aEwLU8kWVEAudQOsTf73Q46fqtuMGpktbZR841oo2W9e6SraQneECQUeW5ebia9A==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,白求恩_screened,方志敏_screened');
INSERT INTO `ds_article` VALUES (4468, '报纸', '冀南银行：新中国金融的摇篮', '陈聪; 郭晓东; 吴光', '金融时报', '金融时报', '冀南银行;小寨村;中国人民银行;', '在中国人民抗日战争胜利暨世界反法西斯战争胜利70周年纪念日活动前夕，记者来到了山西省长治市黎城县小寨村。这里被老一辈无产阶级革命家薄一波誉为“新中国金融的摇篮”。 70多年前，中国共产党在巍巍太行山的深山沟里，创造出了卓越的金融奇迹。在黎城县小寨村一所普', '2015-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSXr4FncAcQqJP1z15sk3uDlitpZVd1ObTgbymcT9uGXbXownh9w9Ibyt88r3qdw1uxUFKVfVZdRVkx-TaPs0Fob9VezwgbaqXQ3adgmzHx2IKVFJe9dPNcNTZkVhUJLfSh4LgTZVtwwg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4469, '报纸', '最难忘的岁月 最光荣的记忆', '', '中国科学报', '中国科学报', '新四军四师;《中国科学报》;青年远征军;叶铭汉;西南联大;军需生产;晋察冀军区;战斗部队;难忘的岁月;', '在中国人民抗日战争暨世界反法西斯战争胜利70周年之际，有一个叫“老兵”的特殊群体尤为引人注目。他们在风华正茂之年毅然奔赴战场，抛头颅洒热血，只为让祖国和后代永享和平。 他们是战争的幸存者，他们是活着的纪念碑，他们也是时间的胜利者。 70年斗转星移，再回首', '2015-08-28 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2015.001215', '抗日战争1_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4470, '报纸', '抗战老兵 重新吹响集结号', '崔雪芹', '中国科学报', '中国科学报', '抗战老兵;国民党;反法西斯战争;济南军区;集结号;', '与新中国成立以来，我国举行过的14次国庆首都阅兵不同，“9·3”阅兵有6大新的亮点。其中首次组织抗战老兵包括国民党老兵参阅，充分体现了全民族抗战特色。 这次阅兵，共编50个方（梯）队，其中安排抗战老兵和抗战支前模范300余人参阅，分为两个抗战老同志乘车方队。抗战', '2015-08-28 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2015.001216', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4471, '报纸', '“胜利日阅兵”的酝酿历程', '甘晓', '中国科学报', '中国科学报', '反法西斯战争;两岸四地;郑建邦;大阅兵;', '2014年3月，全国两会期间，民革中央向政协提交了《关于隆重纪念中国人民抗日战争暨世界反法西斯战争胜利七十周年的提案》。 2015年3月2日，外交部最终确认，今年，中国将根据惯例并参照各国做法，在北京隆重举行纪念活动，包括举行纪念大会、阅兵式、招待会和文艺晚会，习', '2015-08-28 08:00:00', 'https://link.cnki.net/doi/10.28514/n.cnki.nkxsb.2015.001221', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4472, '报纸', '电视纪录片《大抗战》研讨会发言摘编', '', '人民日报', '人民日报', '抗日战争;世界反法西斯战争;《大抗战》;抗战历史;正面战场;广东卫视;历史场景;中国教育电视台;日本军国主义;广东广播电视台;中华民族伟大复兴;研讨会;', '多集结构的抗战史话 中央文献研究室原常务副主任 杨胜群 在已有的抗战题材的电视纪录片当中，《大抗战》可谓鸿篇巨制，不只是集数多、篇幅大（128集），更重要的是因为其思想内容容量大、史料极其丰富、涉及的抗战人物事件众多，可以说，这部片子是一部电视版的抗', '2015-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTDicoOvTKqogn82KX2eojv8HfYGEbOcfJmN5bfN45dj05trckjLhiWdCyqX48i0hACa8M4vGj5nCTJdEqoY3zIiYauikobjAqBemMsh6VecEN7t5K6onge48LiiIU2trb_nCvYbyIokA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4473, '报纸', '抗战烽火中，他们选择了与典籍共存', '屈菡; 张倩竹', '中国文化报', '中国文化报', '图书馆;古籍文献;大藏经;内阁大库;副馆长;文澜阁;陈训慈;抗日战争;', '自“九一八”事变以来，伴随日军对我国政治、军事、经济的侵略，我国的文化事业也遭到了有组织的掠夺和蓄意摧残。日本侵略者所到之处，大肆破坏中国的教育文化事业，掠夺焚毁中国的文物图书，犯下了滔天罪行。  据统计，日军侵华期间，仅在华北地区就焚毁各类书刊65', '2015-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSDpF_CTDRu_9uduJDQiLI_TLZceMqhfYsoGLL_Kub-yPgt6jOUZY_FiHmqBZap9Xdvh5c8spV48yF2DgQU_SuUqB3AhAHiGZRslNjs0oewdM_NJGUNmFk3PuDnMIToqTLJwWL9veicUQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4474, '报纸', '第一集 东方危急', '', '光明日报', '光明日报', '世界反法西斯战争;法西斯主义;东北军;杨靖宇;南满铁路;中国共产党领导;抗日民族统一战线;长城抗战;', '在中国北京郊区，为纪念中国人民抗日战争暨世界反法西斯战争胜利70周年大阅兵的训练正在紧张进行。这将是新中国历史上除国庆节以外，第一次举行的国家级大阅兵。  人类有史以来，从来没有一场战争像第二次世界大战一样，给人类带来如此巨大的灾难；也从来没有一场战', '2015-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRipj1GyCuGmF37kOCNZhZPgkmI9BZHnUtfOWBScQsmM1GVFzQu7-_Zsj3p7hf3KkgRPvo1oGdNm6qrD-GqmwNIwFWWo0LZf-oSx_pfnqcefMhJMVhNkmNbk0QJkxpPpi8mcMy64hnaVA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4475, '报纸', '给年轻人看的书', '吴娜', '光明日报', '光明日报', '抗日战争;黄继光;全民族抗战;', '近日，《抗日战争》第二卷在上海书展首发，并立即和7月推出的第一卷一起，成为人民文学出版社在书展期间销售情况最好的一种图书。在读者的期待中，8月28日，《抗日战争》第三卷也将登陆全国各大书店、网店。届时，三卷本《抗日战争》将全部集结完毕。在生活节奏越来越快、更', '2015-08-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQP_jcf3sWzB1kcbKQVNscE9Sc-r_ZiC4KXnj33Hi6xdt-jnlmrmxl9LWJT_SqpR-ffjXZCl0QfLy87uepAOkp2SUpun6HsIzf2g6fvwCN3JdvUSXYhy2qT8mW8zIWlEqhivE0XRE4_8g==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4476, '报纸', '前田光繁：最早的“日本八路”', '小林阳吉', '光明日报', '光明日报', '八路军;根据地;老战士代表团;', '8月22日，我到神户看望前田光繁先生。老爷子满头白发、慈祥和蔼，坐在轮椅上，非常高兴，精神显得比去年还好。听我说要去中国参加抗日战争暨世界反法西斯战争胜利70周年纪念活动，小林宽澄是日本老战士代表团团长，他高兴地说：“太好了!太好了!”  他说：“虽然我已', '2015-08-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRYyNIV6LeZJfFeZPft7oUfEBAH1o7PWZgZ823woiYKA18g0cxdbjfUpTpShTqb0e2hxvaFWEGF0pSNj6SZJRxMvlX3pCBaLqEEP0g3Rj3-gAJXKqGL7sGu5Sp36hMjW3ToT3SQRlHjjg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4477, '报纸', '抗战遗迹如何保护', '栾絮洁; 陈梦真', '团结报', '团结报', '第三次长沙会战;岳麓山;文化园;长沙市委;抗战遗址;', '导读  日前，为隆重纪念中国人民抗日战争暨世界反法西斯战争胜利70周年，经党中央、国务院批准，国务院发出通知，公布第二批100处国家级抗战纪念设施、遗址名录。去年，首批公布的国家级抗战纪念设施、遗址名录则有80处。  抗战遗址作为我国纪念性遗产中最为', '2015-08-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQR66pPeXYupeq_GEV6t0oZXpcyfc3kz_9rZglLRUO3KhQSp8pQ-iRSQb0jZeOoS0lSrna39WtsLrzhQHj-Q8iPZVBbEC7lQhn4DmvUd6ibGlNM9z6WNgjWoXq7OMvbkvCyqfFybeyCnQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4478, '报纸', '王蒙：抗日战争的启示', '', '中国纪检监察报', '中国纪检监察报', '抗日战争;伤兵医院;中国共产党;', '抗日战争与世界人民反法西斯战争胜利已经70年了，至今我还清晰记得1945年8月得知胜利时沦陷区人民爱国欢庆的激昂景象。  我出生于1934年，九一八事变发生已经3年，中国人民的浴血抗战已经开始。我3岁的时候卢沟桥事变发生。我的幼儿与小学时代是在日本占领军的枪口下', '2015-08-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRF7Q5rSSmqR-434lazCbYBIpYTozifD00CuphlUBdNXOfVTKNF5ppXv_qj35p2Tw-94oMUwbnybcna9DouwYQe3FFM4u5irVyF-m4tbyoYBTg1SZVb9CJAmMZ32JNdoHc_L-_MAITBUA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4479, '报纸', '中流砥柱扶社稷 甘将热血沃中华', '张新 ; 周远 ; 倪震 ; 孔昊 ; 王昕霖', '解放军报', '解放军报', '雁门关大捷;国民党军;阿部规秀;长乐村;东北抗联;山西省;平型关;八路军总部;夜袭阳明堡;华北抗日根据地;游击战争;', '写在前面 冲锋，拼杀；流血，牺牲。从平型关大捷、黄土岭之战到奇袭阳明堡、血战长乐村；从百团大战、陈庄战斗到车桥战役、雁门关大捷……胜利的旌旗，浸透着先辈的鲜血；壮丽的山河，书写着英雄的诗篇。 这里刊登的这些抗战战例，只是中国共产党领导的抗日武装力', '2015-08-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRaPE_rxxD9_wJ_YUbMfMjoZlBSKo7G1YT-UHjpd3q9cAvWnB577sOsBBAEfip4U3ihxEOMthQMKkkjbsUjOBCISh9wp5Eiq9eGsi2-WtMWFyZBjLtyF0Fa-s0JyjgTBWi8nyETM0v82Q==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,百团大战_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4480, '报纸', '热血和生命浇铸的民族复兴丰碑', '任天佑', '国防大学战略教研部;', '解放军报', '日本战犯;抗日战争;民族复兴;日本投降;世界反法西斯战争;东京审判;', '引 言 明天，公元2015年8月15日。 70年前的这一天，疯狂肆虐的日本法西斯低下了罪恶的头颅，放下了沾满人类鲜血的屠刀。 70年前的这一天，世界反法西斯战争的东方战场升起了胜利的旗帜，中华民族在付出伤亡3500万人的巨大牺牲后走出了世纪的苦难。 70年', '2015-08-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTqI3nKWDpZRftWDXMw1dvSDKClK3F5bo-46xkzu9I7pJk4fTR2PV0vpvxBsxe4x9UZfdFj12N_Ei2E8aunWgjrxwV1YXOgmDwHn4DGYL7PKmTul29idH1SuA2_y1uT1fjPrVYt4emdhw==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4481, '报纸', '抗日战争是一场全民族的抗争', '张宪文; 王富聪', '南京大学南京大屠杀史研究所;南京大学中华民国史研究中心;', '团结报', '抗日战争;国共两党;张宪文;正面战场;', '记者：请您谈谈抗战胜利纪念的重要意义以及对抗战史研究有哪些推动作用？ 张宪文教授：抗战胜利以来，抗战史研究经历了四个阶段的发展变化。从抗战胜利到上世纪80年代，由于受当时的意识形态的影响，国共两党对抗战的贡献互不承认，互相否定。国民党讲共产党在敌后游而', '2015-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRSMTCWoDSu98_q-YJSZ_84C6fzg-xlx1L9YawjM513-gKVURKrKCo0GyoqwoEdZRCJSFoszmKebxsyvlaQVZfpis21TL5CCrI85sH8KlIlmseEt9LAuVb3Qr0l6xY2s46nhqJx7lakmg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4482, '报纸', '浙江大学：烽火炼就求是魂', '陆兴华', '中国教育报', '中国教育报', '浙大西迁;竺可桢;', '今年夏天，又有一批浙大师生从杭州出发，沿着抗日战争时期浙江大学的西迁路线，重走了一遍“文军西征”路。七十多年过去了，回首这段波澜壮阔的历史，依然令人刻骨铭心：在抗日战争的烽火硝烟中，浙大师生在竺可桢校长的率领下，举校西迁，穿越江南六省，行程五千余里，最终', '2015-08-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT3E-SGNrmWlmuOhjpNuB6Jti6MGThZSffGfKkabC8wZlek8No2ZCsaoiSNn1P0Ltu7TvngPRTG_G4N6xg-1NWnOSrc6I_7JuzFuK1FKLp_4r-9BFoRUOIjbqofzGAfzvhne4a1Ruqekw==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4483, '报纸', '复旦大学：光复震旦续文脉', '赵秀红', '中国教育报', '中国教育报', '复旦大学出版社;吴南轩;', '在重庆北碚嘉陵江畔，黄色小楼“登辉堂”前，“国立复旦大学”的校牌完好如初，守望着2000多名复旦师生在这里曾经度过的抗战岁月。谁也无法想象，战火硝烟中，400多名师生从千里外的上海，一路背着行李，西上庐山，再迁重庆，几经辗转，受尽困苦曲折，落脚北碚，其“V字形”', '2015-08-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTEtXSovlrQLgWoqdBLodlTwqFLlaKdWreWBr7TVwHwQc30RWA_AP-1FX2N4ZXBxr-X7l4Jq2kDdb3saEo2d7qM7VU-QFy7MBNQsnpzNSzCm7FxCZByox04KRr5qRrQrwe9RTStTABL_Q==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4484, '报纸', '在比较视野中认识抗日战争', '谢颖', '人民政协报', '人民政协报', '抗日战争;甲午中日战争;甲午战争;日本军国主义;比较视野;', '阅读提示： ■与甲午中日战争比较，抗日战争的很多特点显得更加清晰突出，而且能总结出一些历史的规律性认识。 ■抗日战争中体现出来的中华民族精神和凝聚力是宝贵的历史遗产。今天，为了实现中华民族伟大复兴的中国梦，更加需要发扬以爱国主义为核心的民族团结奋', '2015-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRdOsh5iSKuDfLqBjzHKHh9JtYy0ZfediInGFe1aFWfdPJNABIYpK2XthP-CIboEFjVoW64Gua27aPEErcF9SLjQ93nf2QKbsHeSUc3XMoPWVpKmJpbED-EiCzeaAOuZLMpT1b10I2nAQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4485, '报纸', '吹尽狂沙始到金', '杜献洲 ; 罗朝文', '解放军报', '解放军报', '廖政国;第二炮兵;徐才厚;刘志丹;听党指挥;泸定桥;杨开慧;', '高擎布满弹孔的战旗，人民军队走过88年辉煌征程。 88年来，我军留下一部波澜壮阔、气吞山河的英雄史诗。 如果把我军战斗历程比作一幅壮丽画卷，英雄主义就是贯穿始终之底色；如果用我军历史谱写一曲交响乐，血战强敌、捍卫和平就是最激昂的乐章。 88年来，我', '2015-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRG7mQafEpDHpSJ4jBlfP8ahK-8CrYhPwMXyox7BJ9NvWpfI6rjg01GZueF55_vWSdUsPvMpKARKzK7pQcTBxCrTJcv6o0DxzRpbaQuXNpvh36CIo7N9KDd1Jie5A9snFGKAC_bsW7-Cg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,陈树湘_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (4486, '报纸', '中国民兵：辉煌之旅与时代之思', '魏联军; 赵利', '中国国防报', '中国国防报', '中国民兵;后备力量建设;民兵预备役;', '中国人民抗日战争异常惨烈，从战略防御到战略相持，进而发展到战略反攻，无论是正面战场还是敌后战场，中国人民同仇敌忾、共赴国难，铁骨铮铮、视死如归，奏响了气壮山河的英雄凯歌。 ——习近平 “血火中诞生，风雨中长成，战歌中走来中国民兵，支前的车轮，胜利', '2015-07-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS_PlijGyjWlaSOSpR2mHNIdrZXJtOmdDTH8amVmkVtL6l5YW_VVv39_mIQTd8MYP5Ne2AVOy1R60cgaoB-2ddvTekNk4VRX2D2ozyIPhBQz1WO9i2H2qSdCMYn7NxJact_kWwK8UISWQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4488, '报纸', '战略思想,历史的财富和未来的制胜法宝', '柴永忠 ; 徐文耀; 黄昆仑', '解放军报', '解放军报', '抗日根据地;中国共产党领导;抗日武装;日本侵略者;共产党人;人民军队;毛泽东思想;军事变革;制胜法宝;', '写在前面 “世界上只有两种强大的力量，即刀枪和思想。从长远看，刀枪总是被思想战胜的。” 伟大的中国人民抗日战争，是一个尚处于农业社会的半殖民地半封建弱国，面对一个高度工业化的帝国主义强国的野蛮侵略，为维护民族生存而进行的殊死搏斗。浴血拼杀的背后，', '2015-07-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQtNueZZR4_xP1rrTlVNapLjX5ydeHhSXasQb7kxWIsh0kOkeER_tNDObQhM2diHvv8UPYpJ6liW-vn-VvbJdw75fdLraX-C91RbBYsPwlRb7w429FLjg-fIORpZpXjqaxJSeHWpp92ZA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4489, '报纸', '铭记历史 警示未来', '李婧璇', '中国新闻出版广电报', '中国新闻出版广电报', '世界反法西斯战争;中国人民抗日战争;铭记历史;儿童文学创作;儿童文学作品;', '站在特殊的时间节点，回望历史，纪念虽然蕴含其中，但收获更多的则是反思，即如何从中汲取经验和教训，更好地一路前行。今年适值纪念中国人民抗日战争暨世界反法西斯战争胜利70周年，一大批与之相关的图书也不断涌现，其中既有立体呈现，又有微观叙述，力图让读者全面了解那', '2015-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR4M_oYq5JN6i8Uz3vyyIXeHOoydzEx7VzoOy9Lxda9zwer4_jqCjlHDG4EeS0Ag9MCjxoCj2vfyfU4SQxjFh4qdjFLmLwJF7ps-8XW5xHwXrtamXgxlqXJWFpaEMqdBoENVh6RbG7gZQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4491, '报纸', '西南联大：抗战烽火中的不辍弦歌', '张晨', '中国教育报', '中国教育报', '国立西南联合大学;杨振宁;李政道;梅贻琦;南开大学;综合性大学;', '引言：教育史上的奇迹  一块普通的石碑，静静立于校园一隅。  石碑正面，记下一所仅仅8年的大学的历史。碑阴，刻着832个名字。  这块石碑，名叫“国立西南联合大学纪念碑”。832个名字背后，是该校抗战以来从军的832名学生。  石碑立于现在', '2015-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQw4AcdYwNytmMr1WtZlp2yQ3B7h6DZ4yfc_8LGhGKwXeJ5FlhycZHn0Um5zT6uNxFf-k8HTL2GPMn0wgr5E5aOOizR1UBcLeveZMZ5g5h_qrXTSkipiK5yJezeh5ElyOfvNwcvsR6nZw==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4493, '报纸', '兵民勠力同心，永远是胜利之本', '康庚; 韩国贤', '中国国防报', '中国国防报', '抗日民族统一战线;共产党人;人民战争思想;汪雅臣;敌后抗日根据地;千里无人区;军民融合发展;', '全民族抗战是中国人民抗日战争胜利的重要法宝。人民群众是战争胜利最深厚的伟力。中国共产党坚持动员人民、依靠人民，提出和实施持久战的战略总方针和一整套人民战争的战略战术，广泛开展伏击战、破袭战、地雷战、地道战、麻雀战等游击战的战术战法，使日本侵略者陷入了人民', '2015-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQghz5jQWcocPbFxlFGUhrM_LH7ouw-nJ41MjBda16Z7OxIUeI0xaacOZqygW99YGIxPmavOCOw3aHZUgh31CukLnc3NEItBZyM5WLGM4PgI2qwcTiyOQgBMwglU8DA4JT6CZ0F_Cf4KQ==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,洛川会议_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4494, '报纸', '电影《血战台儿庄》：国家情怀和民族魂魄的泣血长歌', '王欣阁', '中国国防报', '中国国防报', '翟俊杰;台儿庄;广西电影制片厂;《血战台儿庄》;中国电影界;', '在中国众多抗战题材影片中，由广西电影制片厂出品，著名军旅导演杨光远、翟俊杰联合执导，1986年全国公映的电影《血战台儿庄》，无疑是一部独树一帜、独具魅力的时代经典。 作为新中国成立后第一部正面描写国民党军队为抗击日本侵略军而浴血牺牲的全景式影片，《血战台', '2015-06-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSvMuZmrzd1ootzvWi1GxGxRfoL-Kf9S8-Uz9_NrLXZuhWPFMg7rjVPW8CPcKJWNFHVrmV5NhZZSOTqFiGR-0fRS1SF92elYGbK11nMTvDtsMtBvYSN1ZUnziYA8LHpWSwxX_TayoMLVw==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4495, '报纸', '太行山的岩浆地火', '曹慧民', '解放军报', '解放军报', '太行山;首都剧场;戏剧家;', '编者按 历史不能忘记，铭刻着八路军在1942年5月的那段沉重艰苦的抗战历史更不能忘记。这段沉睡70多年的抗战历史，重新被挖掘出来，通过文学作品，通过壮美的话剧舞台，呈现在读者和观众面前时，我们感受到的是对中国共产党和八路军的敬仰和崇敬，对为抗战牺牲先烈的缅怀', '2015-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT7drQv9eb3o2Z0iGcLA5_KCukRucJgF7A20tSPv6K2G4o5-QA2HYjgTtgbwZnHsE9N1EdLNv98QoyMgTkaYvSxQwbozkCcc8_8Bq8vGRKAJNMV8RFqEZH7RC2JuypiguQl8IKtklaqaw==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4496, '报纸', '历史不容遗忘', '孟祥麟; 赵成; 白阳; 杜一菲; 赵明昊; 黄发红; 李博雅; 宋豪新', '人民日报', '人民日报', '历史教科书;南京大屠杀;爱好和平;军国主义;', '第二次世界大战，是人类历史上的空前浩劫。战火燃遍四大洲2000多万平方公里土地，80多个国家和地区、约20亿人口被卷入战火，财产损失4万多亿美元。仅在亚洲主战场中国，战争造成的军民伤亡就达到3500万人。 历史不容遗忘，正义必须伸张。在中国人民抗日战争暨世界反法西', '2015-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSMNiGOwTAQ86Sm2QRLGmneoV5n1IPp5k7NQj3Fj-o85HtOX8Jo2Q__zsjYYeMkDPoIr7oWz9kqodlyt2l2x7W26iag2-Y-kkojoes62FwHcLDORndaOiK4WdWWEdkZ68nw3YK47yIBOg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4498, '报纸', '宜昌抗战在抗日战争中的地位', '李亚隆', '湖北省宜昌市政协;', '人民政协报', '宜昌抗战;反法西斯;共产党;抗日战争;鄂西会战;枣宜会战;正面战场;', '正确认识“宜昌抗战”在中国抗日战争中的地位十分重要。“宜昌抗战”不仅仅是指在宜昌的抗战，“宜昌抗战”是从战略态势的角度提出的，指的是抗日战争进入相持阶段后，从1939至1945年，在以宜昌为中心，包括湖北、河南、湖南约近20万平方公里的广大区域，中日两军为了争夺对', '2015-06-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSxYnEUuBfrrOGOm71zm45uV5oUwfOrTO_vRTjNiEXAX68RB_eO_sJZ5DluDaah5SRFRf5uXzrDW1XgKpU1egraKSJrZ9XpIw1Ehuy0jaUmtwsE6g2VqAbsMOmcoUNftjiAa2EKQ9U20Q==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4499, '报纸', '中国抗战功绩巨大而独特', '黄培昭', '人民日报', '人民日报', '中国抗战;抗日战争;二战期间;日本法西斯;', '“关于第二次世界大战，世界范围内已经出版的英文著作多达数千部。然而，英文著作里关于二战期间中国作用的研究却少得可怜，这是不公平的。历史不应该被遗忘，中国在抗击日本侵略和推动世界反法西斯战争胜利中的功绩不应该被尘封，这便是我写作《被遗忘的盟友：中国的二战》', '2015-05-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR7399-cg0j-s-U7zjyYhDdRl9SjVYOhqtM8CtbI8vI9TKGu1-0R1Kp9JVxmfYa-yqVeztdvnRXfUyHf4WRI609lZMCwObLD6LXygNPEqQ-MnKaLpbUIwlBPyh18IQBCQI9t2X1Q7aVFg==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4502, '报纸', '第六届“中山·黄埔·两岸情”论坛共同宣言', '', '团结报', '团结报', '共同宣言;', '本报天津讯5月20日，第六届“中山·黄埔·两岸情”论坛在天津市举行。这是黄埔人纪念中国人民抗日战争暨世界反法西斯战争胜利70周年的重要活动，意义重大，使命庄严。论坛通过交流讨论达成共识，形成《“第六届中山·黄埔·两岸情”论坛共同宣言》。宣言全文如下： 中山', '2015-05-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQIfIuoWdLIge_pvUEUQsZoYNeNAUvzLM5ZsChcHi0kEY9nIYjkkBSus0Knt_Sdf1lj2D7g_spP9X961JL-qvQsoRF4rgN-JVL6x95_NTdlsS1EWZBOZWaOR6fX-yDG_J0v0p87mAQMbA==&uniplatform=NZKPT&language=CHS', '抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4503, '报纸', '坚守战位 接续奋斗', '李龙伊', '人民日报', '人民日报', '连队官兵;赵鹏程;', '隆冬时节，记者来到陆军第83集团军某旅“大功三连”时，正赶上新兵下连。连队荣誉馆里，新兵们围拢在一盏煤油灯旁，聚精会神地听指导员讲述连队的历史。 “上世纪70年代，连队前辈们在国防施工间隙，挤在坑道里，借着煤油灯光学理论，事迹享誉全国。一盏小小的煤油灯，承载', '2024-02-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBOqW_FtmFMLu--saBQJzVojJhyxTh4C2Jpqr_IxP42Bqftll0H9ffiAiHugcpiN4X9U-2-BhJTLk71ClmQzXgpXuz1ipRcdcyri49QYBK-mUqWG0Sbq0l9_ZNJuBketrsoD-ehK741dQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4504, '报纸', '红色旋律 激荡人心', '乔杨; 武少民', '人民日报海外版', '人民日报海外版', '经典剧目;《同心结》;民族歌剧;红色题材;《赵一曼》;天津音乐学院;激荡人心;', '“同心结，同心结，两颗红心紧相贴……”灯光亮起，掌声雷动。5月7日晚，天津音乐学院打造的民族歌剧《同心结》在天津大剧院首演，1600多名观众沉浸在志愿军英雄黄继光及其战友的光辉事迹中。 《同心结》是天津音乐学院推出的众多红色题材剧目中的一部。如今，传唱红色经典', '2023-05-17 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2023.001589', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4506, '报纸', '抗战英雄：血肉之躯筑长城', '高蕾; 董博婷', '新华每日电讯', '新华每日电讯', '佟麟阁;赵一曼;', '新华社北京12月12日电（记者高蕾、董博婷）黑龙江的尚志市，吉林的靖宇县，山西的左权县，北京的佟麟阁路、赵登禹路、张自忠路，湖北武汉的郝梦龄路、陈怀民路……行走在大江南北城市街道，一个个以抗战英雄的名字命名的地名定格下一段段红色记忆。 烽火年代里，无数英雄“', '2022-12-13 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.008937', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4507, '报纸', '解读一座山的“精神密码”', '祝光强; 宋子洵', '中国国防报', '中国国防报', '红军战士;石阡县;军分区;退役军人;红色记忆;', '“北有狼牙山，南有困牛山。”贵州省石阡县龙塘镇有一个地方山势蜿蜒，绝壁陡峭，放牛至此无须看管，牛也走不出去，故得名困牛山。 88年前，遭受围追堵截的红军战士“宁死不当俘虏，宁死不伤百姓”，毅然纵身集体跳崖，用鲜血和生命谱写了一曲惊天地、泣鬼神的英雄赞歌。 8', '2022-09-22 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2022.001782', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4508, '报纸', '魂铸困牛山', '司晋丽; 黄静', '人民政协报', '人民政协报', '红军长征;贵州省;政协提案委员会;红六军团;石阡县;', '8月1日，在中国人民解放军迎来95岁生日之际，一场由全国政协提案委员会、文化文史和学习委员会支持，贵州省政协主办的专题研讨会在贵州省铜仁市石阡县举行。众多党史、军史专家齐聚武陵山深处，只为一个主题——“困牛山红军集体跳崖千古壮举”。 这个题目，仅仅听上去就足', '2022-08-16 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2022.005630', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4509, '报纸', '张淑芬：一方在手转乾坤', '肖俊林', '检察日报', '检察日报', '张淑芬;易水砚;', '“风萧萧兮易水寒，壮士一去兮不复还。”很多人提及这句话，都能想到荆轲刺秦王的故事。易水河畔的河北省易县是全国人大代表、河北易水砚有限公司技术总监张淑芬的家乡。 1963年，张淑芬出生在易县。这里不仅有荆轲刺秦王感人肺腑的故事，还发生过狼牙山五壮士在抗击日寇弹', '2022-08-15 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2022.003737', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4510, '报纸', '铜仁：红色血脉在黔东大地赓续', '张运修; 杨芳', '人民公安报', '人民公安报', '公安局;红军战士;公安机关;思南县;江口县;任弼时;', '武陵山间，黔东腹地，新雨过后，薄雾轻笼，位于贵州省铜仁市石阡县龙塘镇的困牛山红军壮举纪念碑巍然屹立。 革命战争年代，困牛山是一座英雄的山：贺龙、任弼时、萧克、王震等率领的红二、六军团主力队伍在这里浴血奋战。为掩护军团主力转移，红六军团第十八师第五十二团把', '2022-07-06 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2022.003468', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4511, '报纸', '讲故事的老兵有故事', '王钰; 亢福昌', '解放军报', '解放军报', '雷锋精神;白求恩;', '“采访我？采访什么？”在辽宁省军区鞍山第二离职干部休养所里，99岁老红军余新元问道。 “听您讲故事!”记者毫不犹豫地回答。 余新元会讲故事出了名。几十年来，他讲了许多许多的故事——白求恩的故事，狼牙山五壮士的故事，雷锋的故事……以前，他到全国各地去讲，辽宁、', '2022-06-18 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.003192', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4512, '报纸', '浴血奋战百折不挠', '', '人民日报', '人民日报', '革命根据地;第五次反“围剿”;国民党反动派;', '革命是历史的火车头，是推动社会剧烈变动的根本力量。纵观人类几千年的文明史，在“顺乎天而应乎人”的政权更迭中，在“一个阶级推翻另一个阶级”的暴力斗争中，革命以不可阻挡之势，牵引着历史车轮滚滚向前。近代以后的中国，无数革命者为建设一个中国人民的新社会和新国家', '2022-05-25 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.005373', '狼牙山_screened,抗日战争1_screened,九一八事变_screened,百团大战_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (4513, '报纸', '“一屏万卷”助力全民阅读 国社视野添彩书香中国', '刘婧宇', '新华每日电讯', '新华每日电讯', '全民阅读;新华社;新华出版社;新华通讯社;', '“学学八路军顽强战斗的精神吧，他们五个，我们连被地雷炸死的却去了一百多!……” 敌人是可以开两天会唱两天戏的，因为他们的“一百多”，因为他们曾经在棋盘陀上“占领”过一个钟头。 …… 就从九月二十五日起，狼牙山下数百里方圆里的每个人都在仰望着傲然的棋盘陀，不', '2022-04-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.003145', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4514, '报纸', '做“四有”新时代革命军人', '', '解放军报', '解放军报', '革命军人;听党指挥;党对军队绝对领导;军队使命;“四有”;', '第一节 忠诚·看齐 【解说】 一支军队，挺起脊梁的不仅是武器更是军魂；一名军人，挺起脊梁的不仅是体魄更是忠诚。 我军是党缔造和领导的，一诞生便与党紧紧地联系在一起。对党忠诚、听党指挥，熔铸于一代代革命军人的血脉灵魂，是人民军队与生俱来的红色基因。 1927年8', '2022-04-14 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.002068', '狼牙山_screened,抗日战争1_screened,强渡大渡河_screened,飞夺泸定桥_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4515, '报纸', '我们是英雄的传人', '', '中国青年报', '中国青年报', '集团军;红色基因;烈士纪念碑;烈士陵园;缅怀先烈;', '“今天，我们站在新时代卫国戍边烈士曾经战斗过的地方，学习英烈精神，回顾英雄壮举，就是要将英雄烈士热爱祖国、扎根高原、无私奉献、不怕牺牲的精神传承弘扬下去，用无悔青春守护好祖国大好河山。” 清明节前夕，新疆军区某红军团组织全体官兵开展“缅怀革命先烈、传承红', '2022-04-07 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.001314', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4516, '报纸', '以法之名，捍卫英烈荣光', '刘华东', '光明日报', '光明日报', '烈士褒扬;检察机关;以法之名;高君宇;提起公诉;犯罪嫌疑人;烈士陵园;民法典;中华民族;', '“我是宝剑，我是火花，我愿生如闪电之耀亮，我愿死如彗星之迅忽”。 革命烈士高君宇之墓，坐落于北京城南陶然亭公园。墓碑铭文记述了高君宇烈士生平，墓碑背面刻着高君宇这首言志诗。在清明节到来之际，高君宇烈士墓前，前来瞻仰追思之人络绎不绝。近年来社会上尊崇、学习', '2022-04-02 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.001570', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4517, '报纸', '不屈岁月 历久弥新', '雷萌', '中国新闻出版广电报', '中国新闻出版广电报', '抗战精神;抗日战争;中华民族;百团大战;攻坚战;', '“中国人民在抗日战争的壮阔进程中孕育出伟大抗战精神，向世界展示了天下兴亡、匹夫有责的爱国情怀，视死如归、宁死不屈的民族气节，不畏强暴、血战到底的英雄气概，百折不挠、坚忍不拔的必胜信念。”习近平总书记强调，“伟大抗战精神，是中国人民弥足珍贵的精神财富，将永', '2022-03-25 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2022.001012', '狼牙山_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4519, '报纸', '战地黄花分外香', '陈华文', '解放军报', '解放军报', '《星火燎原》;地黄花;三湾改编;人民军队;董存瑞;', '最近，我在书店里看到了装帧精美的《星火燎原》精选本（融媒书），一下子勾起了我的回忆。《星火燎原》在20世纪的五六十年代可以说是家喻户晓，如今的许多学者和作家在研究和写作时都曾从这部丛书中吸取过营养。《老山界》《刘胡兰》《飞夺泸定桥》《七根火柴》等故事也成为', '2021-11-27 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007407', '狼牙山_screened,强渡大渡河_screened,飞夺泸定桥_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4522, '报纸', '总书记说到过这样一些英雄', '温红彦; 宋静思', '人民日报', '人民日报', '习近平总书记;中华民族;国家富强;人民幸福;雷锋精神;', '“一个有希望的民族不能没有英雄，一个有前途的国家不能没有先锋。” 党的十八大以来，习近平总书记高度重视褒奖英雄模范、弘扬英雄精神，踏寻英雄、缅怀英烈的足迹遍布大江南北，在多个场合讲述英雄感人故事，表达对英雄的崇敬之情，号召全党全国崇尚英雄、捍卫英雄、学', '2021-09-29 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.010273', '狼牙山_screened,狼牙山_screened,抗日战争1_screened,抗日战争1_screened,九一八事变_screened,九一八事变_screened,陈树湘_screened,陈树湘_screened');
INSERT INTO `ds_article` VALUES (4523, '报纸', '用生动形象凝铸向上力量', '吴艳丽', '人民日报', '人民日报', '纪念性雕塑;纪念园;雕塑家;红色精神;生动形象;', '漫步展厅，漫步城市公共空间，漫步革命纪念园和纪念馆，红色雕塑，吸引着公众的目光。近年来，随着革命文化研究与传播持续深入，红色雕塑再掀创作热潮，以丰富的元素拓展艺术意境，以浓郁的时代气息激活城市空间，成为镌刻红色信仰、弘扬红色精神的重要载体。 主题创作', '2021-09-12 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.009688', '狼牙山_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (4524, '报纸', '烽火卢沟桥：永远不能忘却的炮声', '彭冰洁; 李伟欣; 胡丹青', '战地记者队;', '解放军报', '卢沟桥事变;卢沟桥;宛平城;反法西斯战争;中国人民抗日战争纪念馆;王建堂;', '脚下是历经风雨的凹凸石块，身旁是目睹历史风云的狮雕石刻……站在卢沟桥中央，远望宛平城、近看晓月湖，84年前的枪炮声响起之前，一切仿佛如现在这般安静。 1937年7月7日深夜，日本侵略军在星光黯淡、万籁俱寂之中，制造了震惊中外的卢沟桥事变。也就是从那天起，卢沟桥', '2021-09-03 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.005737', '狼牙山_screened,抗日战争1_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4525, '报纸', '赓续抗战精神 砥砺复兴力量', '高蕾; 孙少龙; 徐壮', '新华每日电讯', '新华每日电讯', '抗战精神;抗日战争;中华民族;中华儿女;', '新华社北京9月2日电（记者高蕾、孙少龙、徐壮）70多年前的9月3日，经过14年艰苦卓绝的斗争，中国人民取得了抗日战争的伟大胜利，世界反法西斯战争也随之胜利结束。中国人民抗日战争胜利是中国共产党发挥中流砥柱作用的伟大胜利。沉沦了百余年的中华民族从此凤凰涅槃、浴火重', '2021-09-03 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.006863', '狼牙山_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4526, '报纸', '八路军太行纪念馆 太行精神光耀千秋', '付明丽', '人民日报海外版', '人民日报海外版', '八路军;王家峪;八路军太行纪念馆;太行精神;', '巍巍太行，民族脊梁。 太行山西麓，著名的革命老区山西武乡，分布着40余处革命旧址和红色场馆，八路军太行纪念馆就坐落在这里。 八路军太行纪念馆是一座全面反映八路军抗战历史的大型专题纪念馆，1988年9月3日正式建成并对公众开放，馆名由邓小平题写。馆区占地面积14.', '2021-08-17 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002536', '狼牙山_screened,抗日战争1_screened,百团大战_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4527, '报纸', '伟大抗战精神凝聚砥砺奋进力量', '陈发明', '经济日报', '经济日报', '抗战精神;习近平总书记;', '1931年，日本军国主义悍然发动“九一八事变”，占领中国东北全境；1937年又蓄意制造“七七事变”，发动了全面侵华战争。1937年7月8日，中共中央委员会通电全国，号召全国同胞、政府和军队，团结起来，筑成民族统一战线的坚固长城，抵抗日寇的侵略！ 在艰苦卓绝的抗日战争', '2021-08-07 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005874', '狼牙山_screened,九一八事变_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4528, '报纸', '抗战精神：伟大斗争铸就伟大精神', '慕振东', '中国纪检监察报', '中国纪检监察报', '抗战精神;杨靖宇;战争史;侵华日军;狼牙山五壮士;中华民族;血战到底;佟麟阁;中华儿女;赵一曼;', '伟大斗争需要伟大精神，伟大斗争铸就伟大精神。 2020年9月3日，在纪念中国人民抗日战争暨世界反法西斯战争胜利75周年之际，习近平总书记发表重要讲话强调：“中国人民在抗日战争的壮阔进程中孕育出伟大抗战精神，向世界展示了天下兴亡、匹夫有责的爱国情怀，视死如归、宁', '2021-08-06 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003802', '狼牙山_screened,抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4529, '报纸', '万众一心，血肉筑起新的长城', '卫雨檬; 龚伟; 孙天依', '解放军报', '解放军报', '八路军总部;范子侠;黄崖洞保卫战;左权将军;百团大战;', '在中国人民抗日战争的壮阔进程中，形成了伟大的抗战精神，中国人民向世界展示了天下兴亡、匹夫有责的爱国情怀，视死如归、宁死不屈的民族气节，不畏强暴、血战到底的英雄气概，百折不挠、坚忍不拔的必胜信念。 ——习近平 “保卫黄河，保卫华北，保卫全中国” 宽阔', '2021-08-05 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004999', '狼牙山_screened,抗日战争1_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4531, '报纸', '把我们的血肉，筑成我们新的长城', '屈婷; 陈聪', '新华社;', '新华每日电讯', '中华儿女;抗日战争;抗战精神;', '“起来!不愿做奴隶的人们!把我们的血肉，筑成我们新的长城……”一首《义勇军进行曲》，铭刻着一个国家和民族永远不能忘却的历史记忆。 从1931年日本侵略者悍然策动九一八事变起，全体中华儿女前仆后继，浴血抗争14载，以巨大牺牲取得了近代以来抗击外敌入侵的第一次完全', '2021-08-05 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005936', '狼牙山_screened,抗日战争1_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4536, '报纸', '英雄是民族最闪亮的坐标', '', '中国国防报', '中国国防报', '荣誉称号;宋汉林;', '慎终追远。每当清明时节，我们总要追思与缅怀英烈，期望与他们进行一场跨越时空的对话。 “祖国是人民最坚实的依靠，英雄是民族最闪亮的坐标。”置身清明这个特殊的时间节点，与英烈对话不啻一场酣畅淋漓的精神洗礼，让人们对英雄本色有更多感悟，对英雄圣洁有更多守护，', '2021-04-01 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2021.000712', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4537, '报纸', '铮铮铁骨战强敌 血肉之躯筑长城', '', '解放军报', '解放军报', '民族;权利主体;长城;', '为什么战旗美如画？英雄的鲜血染红了它。为什么大地春常在？英雄的生命开鲜花。 在纪念中国人民抗日战争暨世界反法西斯战争胜利75周年座谈会上，习主席列举了一些抗战中涌现出的英雄个人和英雄集体，称赞他们以铮铮铁骨战强敌、以血肉之躯筑长城、以前仆后继赴国难，谱写', '2020-09-07 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2020.004827', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4538, '报纸', '在纪念中国人民抗日战争暨世界反法西斯战争胜利75周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '反法西斯战争;抗日战争;座谈会;', '同胞们，同志们，朋友们： 今天，我们在这里隆重集会，纪念中国人民抗日战争暨世界反法西斯战争胜利75周年。 75年前的今天，中国人民同世界人民一道，以顽强的意志和英勇的斗争，彻底打败了法西斯主义，取得了正义战胜邪恶、光明战胜黑暗、进步战胜反动的伟大胜利！', '2020-09-04 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2020.008646', '狼牙山_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4539, '报纸', '学习抗疫英雄 立足岗位建功', '', '解放军报', '解放军报', '疫情防控;', '编者按 一场疫情防控阻击战，许多平时坚守岗位、默默奉献的普通人挺身而出，逆行出征，用热血担当谱就一曲抗疫壮歌，成为千千万万人心目中的时代英雄。其实，英雄离我们并不遥远，正如一句广泛流传的话所说，哪有什么天生英雄，只是因为有人需要，才有人愿意牺牲自己。崇', '2020-05-25 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2020.002659', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4541, '报纸', '以史为鉴 珍爱和平', '王卫星', '全国政协;军事科学院;', '人民政协报', '抗日战争;中国共产党;以史为鉴;反法西斯同盟;', '波澜壮阔的中国人民抗日战争，既是一场伟大的民族解放战争，也是世界反法西斯战争史上的璀璨篇章。尽管距离中国人民抗日战争胜利已整整74个春秋，但这一充满苦难辉煌的胜利进程，已成为难以忘却的集体记忆铭刻在每一个中华儿女心中。今天我们回顾历史，是为了以史为鉴，获取', '2019-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBEdig8P6mDhksogO7pbRUfwK15TS_J-_DKvUQ3n3ppPyhxNpLV4k42oVz45VideXCrzfaVhkjoeEGbB4Zmwr7jhiJXo4LGbzAQkd0QFZvgc8IfuroFVk8vFjbpqn4Wsrtnc7EAv_c3NQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4543, '报纸', '后方无忧，前方无畏', '王小平', '河南省焦作市市委;', '解放军报', '无忧;军队;国家机器;河南;', '习主席强调指出，我们的国防是全民的国防，推进国防和军队现代化是全党全国人民的共同事业。深化国防和军队改革不仅是军方的“军务”，也是地方党委政府的“要务”，各级领导要有高度的政治觉悟、责任担当，全力支持这项宏图伟业。 焦作是一座英雄城，涌现出狼牙山五壮士', '2018-02-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID_q8dOdPQ4qA22TT0X7cNZmr94UuGm1gu_xoQFUawAU1ZkJKVyvm_AOc0ieNmPTI6uKCi0d7aLvNwMF7yEXpUQO3k672mqNYPh6wcr0AAX5i6uw9MqoY7rnPP8nLtkM-OAhMzoYQU0pg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4544, '报纸', '深入贯彻党在新时期的强军思想 把强军事业不断推向前进', '', '人民日报', '人民日报', '人民军队;重要讲话;习主席;强军思想;杨根思连;军事科学院;突击队;', '“人民军队的历史辉煌，是鲜血生命铸就的，永远值得我们铭记。人民军队的历史经验，是艰辛探索得来的，永远需要我们弘扬。人民军队的历史发展，是忠诚担当推动的，永远激励我们向前。” 连日来，习近平主席在庆祝中国人民解放军建军90周年大会上的重要讲话，响彻大江南北', '2017-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAacXrN8m_0-AXSxtgsuBdHGaaO8koWErlkrTz9kaLSPBb-EX8ikJ3KAEt_WpgfVN_kNSexMOlIkAj_sksTeGzycAWbAQmx_11zHbjDQtVgxffsKZnoe9rNXUVpcTy6bzVZuyzTJ5dgqg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4545, '报纸', '让青少年沐浴英雄精神的阳光茁壮成长', '黄国柱', '全国政协;解放军报社;', '人民政协报', '刘胡兰;王二小;我们这代人;', '常常有年轻的同志问我：“您青少年时代接受的英雄主义教育是什么样子的？”他们之所以提出这个问题，恐怕与当下某种瓦解中国革命叙述的历史虚无主义倾向有关：从狼牙山五壮士到邱少云，从刘胡兰到雷锋，许多革命英烈不断被抹黑、诋毁、恶搞和质疑。近日重新被翻出的三年前的', '2017-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDA76h-u8-F_snbzf3Ej3W28n3rlIhKWhWpvvmBg28AqArNuCAZ2r3qqEdAgLX46VfHwSlnVBG3qntrPrsPZFCVPU9j2GvpJAkDM8XoLTPzyTlWWThcTUlSbSjIMpCa6ir3R3JGZJ5BDg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4546, '报纸', '不忘初心，向世界一流军队迈进', '刘小兵', '光明日报', '光明日报', '听党指挥;主持人;强军目标;世界一流;', '特邀嘉宾： 军事科学院国防工程研究院政委、少将 李泉 军事科学院军事医学研究院政委、少将 刘茂杰 国防大学教授、少将 颜晓峰 国防科技大学教授 熊杏林 从南昌城头诞生的人民军队，历经90年风霜血雨的洗礼，在党的领导下不断从胜利走向胜利，建立了彪炳', '2017-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBuWXZC2kqtQVNj1A33E_nhEF2eTunUHPnk5HT1dhTrP4U6Nrnfy1Yd7dBG7x5dALadjVmFm_y3GHo-2OdkxJEATzhSXqiW77wBiVOINh2kLeSoxzqt_e021CRqUuifR9_w3uIaXst2dg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4547, '报纸', '人民法院依法保护“狼牙山五壮士”等英雄人物人格权益典型案例', '', '人民法院报', '人民法院报', '狼牙山五壮士;宋学义;基本事实;人格权益;名誉权侵权;加多宝;关于确定民事侵权精神损害赔偿责任若干问题的解释;一审判决;', '一、黄钟、洪振快诉梅新育名誉权侵权纠纷案 （一）基本案情 2013年第11期《炎黄春秋》杂志刊发洪振快撰写、黄钟任责任编辑的《“狼牙山五壮士”的细节分歧》（以下简称《细节》）一文。载明：当我们深入“狼牙山五壮士”有关叙述的细节时，就发现上述人员在不同时间', '2016-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIARW1Qs-oDt7XodTEPYsdY67ysRvRk1vxtOKLubScI-P4qqJpD_owfAq9Dp8FvNAqC_K5bgfyizJ0xoYJMFlKJsA9NBPKAU_DoYU0ZyIcmtZjjIg1FueMysvx3Mq7xopY5yf3alSVfs-w==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4548, '报纸', '捍卫英雄，就是捍卫民族的精神脊梁', '', '解放军报', '解放军报', '狼牙山五壮士;人民军队;', '今年是建党95周年，主流媒体陆续推出专栏、纪录片、电视剧等文艺作品，向党的生日献礼。那些党史军史上的英雄人物，又一次鲜活地呈现出来，在全社会掀起一股崇尚英雄、缅怀先烈的热潮。 “我们中华民族有同自己的敌人血战到底的气概，有在自力更生的基础上光复旧物的决心', '2016-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICUorNDh6RA6CFjfuLJF3p-WTjuwbTtAdA1q4E67_DsmwTsTZMFr79td43vMPqIPa-fFxtRukHBJYd-41tPxGhHE_hWq2VOFO8HBeCijjWrC2UwV5y8szNX0RAY_39J6e20UvUM6gT9kw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4549, '报纸', '捍卫民族共同的英雄记忆', '', '中国青年报', '中国青年报', '狼牙山五壮士;名誉侵权;', '6月27日，北京市西城区人民法院对“狼牙山五壮士”名誉侵权案作出一审判决：判决被告洪振快停止侵害名誉，赔礼道歉，消除影响。法院认为，在没有充分证据的情况下，洪振快发表文章对“狼牙山五壮士”作出似是而非的推测、质疑乃至评价，否认了主要史实的真实性，降低了这一英', '2016-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBE0a7_qMtM-M_QbWaz0Z5EjcfLFpKEfwzHcyvnoie3pPofOmL6cTGlfgzwianh17qmpU-be-UBd2X9AaEWpB65WdC0HcICqRTChSJRHDFFE40ojV3KQd1UJeS4xpVZd8BE0Xyh9N94LA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4550, '报纸', '英雄不是独行者 青年人需要与英雄同行', '靳晓燕; 晋浩天; 陈鹏', '光明日报', '光明日报', '主持人;独行者;南开大学;', '嘉宾 中央民族大学原党委副书记（1944年参加八路军）武耀芝 北京师范大学教育学部专职辅导员 任雅才 南开大学法学院辅导员 李高扬 中国政法大学学生 李明然 北京理工大学学生 陈毅昆 编者按 风雨95载，是英雄辈出的时代。他们是民族的丰碑、国家', '2016-06-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB9Iul4_pMmK4y7bxey1KUEEgpNAcG7E5GWob1x-71IR2Diifg80ToNqq3ATA-lW4wY5tqpZM2t5XLh2yyGuqso-jgSYHApuXyTBIyyrsWf3MXNB4WeoGd-MqhVFvY9CT3N6lzYSho9CQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4551, '报纸', '尚武，国防动员文化之核', '吴晓源', '安徽省池州军分区;', '解放军报', '国防动员;尚武精神;使命担当;', '梁启超曾说过：“尚武者，国民之元气，国家所恃以成立，而文明所赖以维持者也”。回眸历史，正是尚武精神捍卫了民族尊严、雕刻了中华风骨、激荡了中国军人的勇士雄风。尚武精神是一个民族的精神脊梁，是一个国家最深厚的战争潜力，也应成为国防动员文化的核心价值。 激发', '2016-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAfxFBWrCgFl0cE68XrDnZouhWAFK8TNVb0dQE6PTbvYSGJ4EgVPt_0ue2SN1twgyPpvHOE2B4mtaka4JM2pvfLlKavOEx37Dvv9O462WihnH207q-gevU-B07vuocEiA52NnonM5NlTA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4552, '报纸', '英雄是一束纯净的阳光', '王卫星', '军事科学院外国军事研究部;', '光明日报', '历史观;第一次世界大战;历史虚无主义;', '纪念英雄、缅怀英烈是人类的一种良知，是国际社会的普遍价值追求。世界各国在捍卫英雄形象、培育民族精神方面有许多值得我们借鉴的经验教训。“他山之石，可以攻玉”。分析总结国外的相关做法，对于我们强化对英雄的崇仰、反对历史虚无主义、弘扬社会主义核心价值观具有重要', '2015-10-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAaN5_FRLZ8fvR9mcN8VOFupLFMnHVXxNW9BREsGhksImDsR1LcGI-1jqyoz5VoiXmR7PvzjocTukYbsfIbUPr00QcsbGyT_dMvfptHk7l22Tq2um55-HBPcA7msfAVwv7SFVUcG1AOvA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4553, '报纸', '千凿万刻,打造《永远的丰碑》', '菁欣', '中国新闻出版广电报', '中国新闻出版广电报', '演播室;中国人民抗日战争;世界反法西斯战争;《永远的丰碑》;广播电视台;', '9月3日，中国人民抗日战争暨世界反法西斯战争胜利70周年纪念大会在天安门广场隆重举行。北京电视台作为在天安门阅兵活动核心区设置直播点的唯一一家地方电视媒体，在全台12个频道同步推出《永远的丰碑——纪念中国人民抗日战争暨世界反法西斯战争胜利70周年大型直播报道》。', '2015-09-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDvn_wU4ANr_DkRePamk3xJsU7efeoct-NjKX2BDRL3Ha1v6sEBlZ4-jxyB8HUr2eAuAOhFnt27vDvgeIFW5OPJoIyf3316iUJf4RxOkpztB8enIOl0_8nQPpZpGNseKfpFSzctIgTV9w==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4554, '报纸', '挺起中华民族不屈的脊梁', '', '经济日报', '经济日报', '中华民族;风险挑战;“四个全面”战略布局;', '今天的中国，正在推进“四个全面”战略布局，走上民族复兴的伟大征程。实现我们的奋斗目标，仍然是一场波澜壮阔的持久战，需要一大批勇于承担历史使命、为祖国和人民奉献一切的英雄人物，需要克服一切艰难险阻、百折不挠一往无前的英雄精神，去克服前进道路上诸多可以预见和', '2015-09-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAao3ginqzzz5YbeokjblT466wqPhOIZrM4r9adgRBDtijXS1mNqNle48tdTaUfuLAFznuEhhrOx7FFSrMXrwgy3qmCuWChYDTHN1QAkKYsZ2A2kNg2kEJoHRMOSw021Y6c-6G8I3oajw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4556, '报纸', '抗日战争的光辉历程激励我们奋勇前行', '张士涛; 戴旭光', '第四军医大学;', '光明日报', '抗日战争;创业精神;世界反法西斯战争;凝聚力量;实现中国梦;抗战历史;中华民族;红色基因;共产党人;', '中国人民抗日战争，作为世界反法西斯战争东方主战场，历时最长、牺牲最重，为赢得世界反法西斯战争的胜利作出了巨大贡献。中国共产党科学指明争取抗战胜利的正确道路，促成全民族抗日统一战线，组织指挥一系列战役战斗，支撑配合国民党正面战场，发挥了抗日战争的中流砥柱作', '2015-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBz_tUA1bkZmI9S5A0haErwA03jmmQXFMSBWMMAarpi5TfK5fheeKs0m2Mr1ESPPCBxeisv6IBX9ZgcbOgi4CIfrNLTh7vK2B8ogy5sArHHiu73H2A2go62ipAXWNk8aX08lC7Yq99qWw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4557, '报纸', '弘扬抗战精神 奋力开创未来', '雷汉发; 郑明桥; 张毅; 周斌; 冉瑞成; 薛海燕; 李治国; 孙潜彤; 郑杨; 杨学聪', '经济日报', '经济日报', '世界反法西斯战争;中国人民抗日战争;阅兵仪式;抗战精神;', '9月3日上午，全国各界干部群众以多种形式收听收看纪念抗战胜利阅兵盛况。蓝天白云下，飒爽英姿、整齐划一的三军队伍，接受全国人民的检阅；拥有现代化装备的文明之师、威武之师雄壮的步伐，响彻在天安门广场，回荡在亿万中国人民心中，激励人们不忘使命、砥砺前行', '2015-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAo5lVhxxtN7HXz6Mlmo6FID2rxOkyibdH6tKsUhvgPHM28oSoxgQoN1h8YhixUKOaFYPphULX9oEDbXggnYfMVUWLATg2CzAaxsJI1AzYUKiV3aniRUToQCoFrWJn6j_nOvHRBRBOy_w==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,抗日战争1_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4558, '报纸', '前进!向着和平与复兴之梦', '王斯敏; 谢文; 刘文嘉', '光明日报', '光明日报', '世界反法西斯战争;中国人民抗日战争;狼牙山五壮士;天安门城楼;天安门广场;', '1200名军人唱出同一个声调，一首首抗战歌曲响彻云霄。昂扬音符诉说着苦难和抗争，向一个国家的不屈与尊严致敬。  56门礼炮代表56个民族，交替鸣出70响炮声。70年前的荣光穿越硝烟铿锵而来，为一次决定性的伟大胜利喝彩。  红旗猎猎，笑意盈盈；喜悦如潮，豪', '2015-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBUrgLme3oT06ZEbbpu746XGdTRSu5JJFyso9Gtn8w7TLN23xO2GJpfWOYIj3HLCQ2BmD7BEG37vnvqO53ev1UQyUu16EK0_CvEehsuD_YhPYTtGa431aYDccJRGYPBECLB9FHh_7mymA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4559, '报纸', '在颁发“中国人民抗日战争胜利70周年”纪念章仪式上的讲话', '习近平', '人民日报', '人民日报', '中国人民抗日战争;侵略者;', '同志们，朋友们： 今天，我们在这里隆重举行仪式，为抗战老战士、老同志、抗战将领，为帮助和支持中国抗战的国际友人或其遗属代表颁发“中国人民抗日战争胜利70周年”纪念章，目的是表达对抗战英雄的崇敬，弘扬伟大的抗战精神，宣示中国人民铭记历史、缅怀先烈、珍', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBuHhqcIEfAuhiKUIVDG5EVWPjV-SEd4pxzJ7JTZ_zrmKYu3Osr6UYlUua6wFqId24_gCN8tV0RG_W7mzNhJau6jQO4Pj5xHi8zR694p5I9kDjwplYS4KULCeU9CG8qS6lxWzyEfO_N3Q==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4560, '报纸', '大力弘扬伟大抗战精神 凝聚强国兴军磅礴力量', '李玉梅; 晓海', '学习时报', '学习时报', '抗战精神;世界反法西斯战争;中国人民抗日战争;习主席;中华民族伟大复兴;', '中国抗战胜利是世界反法斯战争胜利的重要一环  记者：今年是中国人民抗日战争暨世界反法西斯战争胜利70周年，我国将举行包括阅兵式在内的各种纪念活动，并邀请外国领导人和有关国际组织负责人参加。请您谈谈为什么要举办隆重的纪念仪式，抗日战争胜利有什么重要的历', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBwVVLwEYha046jAYNC15_uHOvtFKT70_voh7K0NaiMHAYF_SphZPCyCwKWAzo7QJTxPW-vQlI2WmYRwW1NGf9KLlmtG5jT27joV3ihBBQCLzAFqdUfVxxuTXSPJwASAWcMgBmBRa6-ng==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4561, '报纸', '大阅兵是对抗日英雄的伟大致敬', '曲延涛', '解放军报', '解放军报', '反侵略战争;抗日英雄;抗日战争;甲午战争;', '抗日战争的胜利，是近代中国第一次赢得对海洋民族的胜利 记者：您在最新著作《精神》中说，中国自秦皇汉武之后就失去了原来的精神。那么，今天我们找回失落的精神了吗？ 刘亚洲：抗日战争是一曲壮丽的史诗，不仅属于中国，也属于世界。在抵抗法西斯侵略的', '2015-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDaL2-W6hPmsVTIBiEuRm1iHR0omhjHEcNrepjpgDvK4DlrXXMKWyZDOv-W_LyqvsyRNOwpxi72Ra3rMa2GNlGWObvIwtK7kH1fpwOlQRMlehL5AE4w61Drlq-HPdm-Zte_xmYnosNPAw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4562, '报纸', '从伟大胜利向着伟大复兴奋勇前进!', '李斌 ; 李忠发 ; 熊争艳 ; 罗宇凡; 白瑞雪; 杨依军; 蒋芳; 邹大鹏; 李丹 ; 王菲菲 ; 李华 ; 李萌', '人民日报', '人民日报', '世界反法西斯战争;伟大复兴;日本侵略者;中国人民抗日战争;', '有一段记忆，在血与火的洗礼中永恒； 有一种精神，在今与昔的交替中闪耀； 有一个梦想，在时与空的变换中升腾…… 中国人民抗日战争第七十个胜利日到来之际，新华社记者奔赴一些抗战历史发生地，一路追寻，一路叩问…… 世易时移，山川', '2015-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBU2iM-rn0IgtCuVfjqvEf9CDB9bp4isB6-UXA-ugmdo8Q6myIxymIJFTVArRLoGPoKP7rs6jUqMs0LCXyuxNKber6ml8mI1A2kSFeMBzkTE3fel_qjIQ7lGTJGWuLmtCFR9QM_j9fzlA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4563, '报纸', '抗日战争与中华民族精神的崛起', '刘亚洲', '国防大学;', '光明日报', '抗日战争;中华民族精神;团结统一;日本帝国主义;军事斗争;抗日战争胜利;', '以爱国主义为核心的民族精神是中华民族赖以生存和发展的灵魂。在中华民族反抗外敌入侵的所有战争中，抗日战争最惨烈，也最悲壮。在这场战争中，中国共产党引领并激发出中华民族的伟大民族精神，推动并实现了中华民族在抗战旗帜下的空前大团结，成为赢得抗战胜利的中流砥柱。', '2015-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBbU2VrzO7OGcjKanCWUjaVxg0z_EiAORBMr64uu0wu-T8gvMnGWI9kr9t-RtLEaFMZyYs9sYAZG4LV-dlUjEtuywbDmKiNmJn318jSH4D9MgRxNiWvOvS0azdwe5_P_YbutK5rFXEAHQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4564, '报纸', '传承伟大的抗战精神', '', '经济日报', '经济日报', '抗战精神;日本法西斯;中华民族伟大复兴;', '今年是中国人民抗日战争暨世界反法西斯战争胜利70周年。回溯70年前那段鲜血凝结、顽强不屈的抗战历史，有家国破碎、血染河山的悲壮和伤痛，更有前仆后继、奋勇抵抗的抗战精神熠熠闪光。这一伟大精神值得每一个中国人根植头脑、融入血脉，化为中华民族的精神基因，世代弘扬。', '2015-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC8mnzhWXQT-2Z60CAobUjqZVF9PVBDD5oTDGeru75HyyVugCvHIEXxXIiHZtyUv8x0Bso3gTAAvBw0Kn4Y6-KzMwYSfr55ut3zh0EI9uoeQ10iuf_QhyWEZ1Y2BstfE4KKKIzQapUrZQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4565, '报纸', '回望，是为了更好前进', '周根山', '中国纪检监察报', '中国纪检监察报', '平型关;抗日民族统一战线;抗日战争;新四军;危急存亡;帝国主义;共产党;中华民族;', '70年后，当我们回首凝望那个用鲜血与生命铸就的历史坐标——1945年９月３日，感慨潮生：这是一段黑暗屈辱旧历史的终结，更是凤凰涅槃新征程的开启。  一寸山河一寸血。中国人民以伤亡3500万人的代价，彻底战胜日本侵略者，取得了百余年来反抗外敌入侵的第一次完全胜', '2015-08-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICV4MzyacrzVxpWyLEImUPONkaXf5eZGzT_a7_YVN0aYtTz-CDB7HbcUF_2ys14EYkQKiCluz6LZWzTQ4Wq8uLnVk2jw48Q5HiXLDplrivZWL_RBqU8HFYyZYtbIw1UC81czb7_ExmkIQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,抗日战争1_screened');
INSERT INTO `ds_article` VALUES (4566, '报纸', '胜利在此刻凝固', '郑晋鸣; 张玲', '光明日报', '光明日报', '侵华日军投降;中国战区;投降书;签字仪式;日本侵略者;何应钦;无条件投降;七七事变;', '1945年8月15日，日本天皇宣布无条件投降。9月9日，中国战区日本投降仪式在南京陆军总部举行，侵华日军总司令冈村宁次在投降书上签字。  在中国人民抗日战争暨世界反法西斯战争胜利70周年纪念日来临之际，记者走进侵华日军投降签字仪式旧址，重历那振奋人心的一刻，寻', '2015-08-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA24T4Yxb_7GNbqmhyM7JoIAeUjkip9TUu8XQrkfoBWH0wDQ701pOOh_yPZP26Tf3Z5f02NqxEUkHj7UTlMIy1wYnoAK9ZkxiBootmIiggRt_996jGzM6J8byOQqEl3PkKFihxP8L7_Jg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4567, '报纸', '珍惜英雄,就是珍视民族的未来', '', '解放军报', '解放军报', '珍视;', '“没有足够的兵器，且拿我们的鲜血去；没有热情的安慰，且拿我们的热血去。”70年前的英雄们，我以我血保家园，我以我血复山河。  抗日战争，败则亡国灭种、万劫不复，胜则凤凰涅槃、浴火重生。民族存亡绝续之际，中国人民同仇敌忾、共赴国难，铁骨铮铮、视死如归，奏响', '2015-08-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBzyM65amj_SJfF1T15a7B4x8bHRqv-lgsgNWA94qCv9eU8dKHcuQNY3GaOXS4jDZNWUXJPM_I53zDFX77CJ8Zgjxz7QHfowqFjTJzD3HNU1ljhHBxl2KQ7NZbKj1QPbRjo3Uyca4G84A==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4568, '报纸', '弘扬抗战精神 推进伟大事业', '黄坤明', '中宣部;', '人民日报', '伟大事业;中国特色社会主义;中国人民抗日战争;反侵略战争;中华民族伟大复兴;抗战精神;世界反法西斯战争;', '站在中国人民抗日战争胜利70周年的时间节点上，回望那段用鲜血和生命铸就的伟大历史，深深镌刻在我们民族记忆中的，既有家国破碎、同胞死难的伤痛，也有中华儿女英勇抗敌、浴血奋战的壮烈，更有气壮山河、光辉永在的伟大精神。习近平总书记指出：“在中国人民抗日战争的壮阔', '2015-08-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC1WW7EzJZb4_JfBGc3D51738dxRIwBMKrJHIj9uJJ37-bmXJVZIYQsyrWmZwgrE4yAnzH03fwDCNm-qKK0_HRKjP5uqsOtNXqlhKIoV-Fee5cweFQntttQFKJ9pypOS2RM08G70keKUw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4569, '报纸', '捍英雄之名 聚舆论共识', '刘聪', '人民网舆情监测室;', '中国纪检监察报', '黄继光;狼牙山五壮士;历史虚无主义;主流媒体;《解放军报》;', '1舆情概述 7月6日至20日，“我们和英雄在一起——网络名人进军营”活动于邱少云、黄继光、“狼牙山五壮士”生前所在部队举行。52位网络名人、新媒体账号负责人和媒体记者走进军营，重温革命英雄事迹、感受当今英雄风貌。 从6月初开始，主流媒体即开启了系列追访宣', '2015-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBkC4ScAtyv4r1eivr0zsHNSRdz5hR6pjzl_lbqAY5i-gZXm2vtqgpFUgxfuluvm815ehaG34rEa139ljw8yYSPwx_3wTofKPVBaV239rud3j46H7HfRlAhxEnhnYZA9d7E1x4HLM9IoQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4570, '报纸', '守卫民族不灭的精神薪火', '', '人民日报', '人民日报', '', '在一个民族的精神图谱上，英雄是最醒目的标识。英雄星光闪耀，浓缩可歌可泣的民族历史；英雄浩气长存，照亮迈向未来的进步征程。 连日来，针对扭曲历史、抹黑英雄的诋毁与恶搞，一场“捍卫英雄”的自觉行动在军营、校园和各类媒体上展开。社会各界正义之士以事实为依据', '2015-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAJqlsDDm7II_HjMDmZI4s9PlYL8K0O5j2wxY13cUxw7zgceipySzqW_gQXx9qk-T19ckiV5bPZqG7e_12l1iV_4SOeJ8trNv7K_lmA1yC4BN93M7tpKT51urHlKxsuua9M2tB4dWQmbQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4571, '报纸', '对否定英雄的错误思潮说不', '王卫星', '军事科学院外国军事研究部;', '人民日报', '错误思潮;民族独立;人民解放战争;', '英雄，是一个国家光辉历史的记忆，也是一个民族坚强不屈的脊梁。但近来，社会上出现了一股否定英雄、歪曲历史的错误思潮，一些别有用心者大肆诋毁狼牙山五壮士、邱少云、黄继光等家喻户晓的革命英雄，严重扰乱了人们对英雄形象的认知，冲击了社会主流价值观。应当认识到，一', '2015-07-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAoNDN_DoxCVs81rsaqYt9wQn7aYyi71itCosQeIFlDxt0fF3dX21aWztOdWCDkEEBx1zhniiWBaPMl43a9FU0xmsVEOacME0oRzRgK8QTZRSYnz-TfLJau7oew8dH1FT7_muw8E5ap-w==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4572, '报纸', '血染战旗,见证我们永远的军魂', '王通化', '解放军报', '解放军报', '国民党军队;听党指挥;黄克诚;平型关;《游击队之歌》;', '烽火岁月，牺牲之前，我们的战士在想啥做啥？ 马宝玉，狼牙山五壮士班长，跳崖前做的最后一件事，是掏出一个小本子，在膝盖上为3位没有入党的战友匆匆写就3封入党介绍信。 多年之后，幸存下来的“狼牙山五壮士”之一宋学义，仍清晰记得班长的最后遗言：“', '2015-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBfpG1D6wBltq5JzfDfFvF8t_-lITUoqj9_uEmWiMRFnZb0nxS9rogns5RQa88LqAAJ1DesVivfxAixCbjmX-hiMcEl7agyaBxuDSCP0JYm99X9m7VlFwG-CCleltNLlDC6JSJpboV-mQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4573, '报纸', '纪念全民族抗战爆发78周年', '', '人民日报', '人民日报', '阿部规秀;黄土岭;仁安羌;全民族抗战;日本鬼子;', '抗战大事记 1931年9月18日，日本关东军蓄意炸毁沈阳郊外柳条湖附近铁路，并栽赃给中国军队，炮轰中国军队驻地。九一八事变标志着中国人民反法西斯战争的开始。 1935年12月9日，北平学生举行抗日救国游行，反对日本帝国主义侵略。运动掀起全国抗日救国运动新高潮，', '2015-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAwsyigA5m9EMK5asM6eXyQ6NX4McioQlW3WYFh6hy6m0rEacfvmBPWArMk3vDe00BixPL7dY3x8S5gI_tEF2q9W5CkfvPmrYOnzgoX4pfm8RR7eTHc8e-xWXCGha88c4KxIHTXua2YNQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,抗日战争1_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4574, '报纸', '英雄信仰,让灯塔永远照耀民族心灵', '魏兵', '解放军报', '解放军报', '黄继光;狼牙山五壮士;上甘岭战役;人民英雄纪念碑;王铭章;天安门广场;烈士陵园;吕秀兰;', '引子 英雄，对于历史和未来，对于国家和民族，到底意味着什么？ 1949年10月1日，响彻天安门广场的那个声音震撼了世界。毛主席庄严宣告：中国人民从此站立起来了！你可知道，此前一天——1949年9月30日，毛泽东带领他的战友们，为历史为未来，立下一座人民英雄纪念', '2015-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICPYwxBHUvyEVpeutPINBaArTiGy6YseEAW_Lgj4uByb9q9lJ7rCGOroGweXsh1M67n9M9bQalC-LfaJ3JbxJxQI9TYgWsSeDqActzpHyueesfC50TQxpW_EnXalIk1ZUVqBdIMkH9X_w==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4575, '报纸', '英雄,社会应有的价值认同', '', '解放军报', '解放军报', '价值认同;社会主义核心价值观;', '英雄，言炳丹青，德配天地，功昭日月，是看得见的哲理，是社会的价值标杆。尊重英雄、敬仰英雄，理应成为全社会最起码的情感认同和价值认同。 历史长河奔腾向前，英雄人物像一道道闪电，穿云破雾，喷薄而出。他们或以冲锋陷阵、视死如归的勇敢而令人敬佩，或以不惧苦难', '2015-06-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDbVma2bB0F9nEbpVlCbWBq2TKEU9pj2kFDiX3_Snixcme74aXkLQGl0IAnPDfK3R2EV7jqMo-HRT53wRAjJ0aRG6yReD05c1J47syxkmmxVWZn72A8ZeMPuGZkoVaoLmh248EYzafLCQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4576, '报纸', '在新的历史条件下大力弘扬抗战精神', '', '解放军报', '解放军报', '抗战精神;抗日战争;新的历史条件;中华民族伟大复兴;日本帝国主义;', '写在前面  在中国人民抗日战争的壮阔进程中，形成了伟大的抗战精神，中国人民向世界展示了天下兴亡、匹夫有责的爱国情怀，视死如归、宁死不屈的民族气节，不畏强暴、血战到底的英雄气概，百折不挠、坚忍不拔的必胜信念。硝烟散尽，精神永存。今年是中国人民抗日战争', '2015-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICVYxGib8HdB7jGxh1vWDh9XS3bhlVCbTgyZdMe2ubpeFkxhPmN04Ej5SnD44J0RBDr-e7OrhUjXkxw3A15Ewn1cs3Ey0TlOlPDzOT_5plV-UxQSJKkX3iFdknufQVlIvqc9HtmtZr9Rw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4578, '报纸', '中国共产党是抗战的中流砥柱', '', '光明日报', '光明日报', '抗日根据地;中国共产党;共产党人;新四军;八路军一二九师;中共满洲省委;抗日战争;', '编者按  为纪念中国人民抗日战争暨世界反法西斯战争胜利70周年，5月19日，中宣部在山东省菏泽市召开“抗日根据地的共产党人”座谈会，大力宣传中国共产党在全民族抗战中的中流砥柱作用。中宣部《党建》杂志社将以增刊的形式，将全国抗日根据地共产党人英勇事迹汇编成', '2015-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICnzXnuQpMpkZk3ZgYe1XJaAyNs40J079ZCddLsYSgy9sMNJpi4A_Yf5T-esYUzT-xBoTlm8FpelmNL0KMP0jkmH0i4f-e2gcgXm3FECeeB1G9PzcIEeqfkAgEhGJLiVt6pCToVIlGehA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,抗日战争1_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4579, '报纸', '昭昭前事 惕惕后人', '', '解放军报', '解放军报', '抗日战争;爱好和平;世界反法西斯战争;日本军国主义;中华民族伟大复兴;中国共产党领导;', '历史不能忘记。如果历史的火炬不再照亮未来，人类将会在黑暗中徘徊。  2015年是中国人民抗日战争暨世界反法西斯战争胜利70周年。70年前结束的那场战争，是正义与邪恶、光明与黑暗、进步与反动的大搏斗，中国人民和世界反法西斯人民取得的胜利，永载中华民族史册和人', '2015-05-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB96BMj6wmbN-EOa-n3kPN3N--SSGNC15u_6T7_hFi20uRcVEmFrUYF8uuAGWU9agP28CNubcXZyMKptNNeYbRu49OMfphwp3BgJxs5z9EjjTgtmbMHuVv2LzjThvpRQTjgt0HtHANnkg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened,百团大战_screened,洛川会议_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4580, '报纸', '在纪念中国人民抗日战争暨世界反法西斯战争胜利69周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '世界反法西斯战争;中华民族伟大复兴;中国人民抗日战争;日本军国主义;座谈会;', '同胞们，同志们，朋友们： 今天是中国人民抗日战争和世界反法西斯战争胜利纪念日。69年前的今天，中国人民经过艰苦卓绝的浴血奋战，打败了穷凶极恶的日本军国主义侵略者，赢得了近代以来中国反抗外敌入侵的第一次完全胜利。 中国人民抗日战争的伟大胜利，为中华民', '2014-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBoOtWut-qDokXRXUSBRnCPMYLJWIMU7fXyZXBHuOm6I51dY8nlogsiWbngka3yRhwjvtAO9adYs7-KFOnBkbxopZOKi8OBjB_69voO6GALD7Pob0a4D7zAjKsFcehXxwy70-_7zuRoAg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4581, '报纸', '唱响繁荣发展先进军事文化的时代强音', '刘璇', '解放军报', '解放军报', '先进军事文化;当代革命军人核心价值观;延安文艺座谈会;军营文化建设;繁荣发展;', '中国，五千年文化延绵不绝，却从没有哪个时代像今天这样，把繁荣发展文化置于强国兴邦的战略高度。 70年前的春天，毛泽东同志在延安文艺座谈会上发表讲话，开创了中国文艺发展的新纪元；2011年金秋，党的十七届六中全会上“建设社会主义文化强国”奋斗目标的提出，又在', '2012-05-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBCfbwVlGET5Ry31L2o9DkUIxw82RXvxC5jb9SGQn0v0Qu8Hz4Uq4FwHcjwGrR1zDG0US3IoLkj9mYz8mq25yfRGo2STGUi4vCf7NW_4q0lPGXnAdA8ezWCErZnkVf5llfW-wMueWONTQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,杨家岭_screened,遵义会议_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (4582, '报纸', '红色电影的历史地位、美学特征和演进趋向', '', '光明日报', '光明日报', '红色电影;美学特征;', '编者按 红色是血与火的颜色，也是我们的党旗、国旗的颜色。红色电影主要是指革命历史题材的电影，包括重大革命历史题材的电影，也包括革命领袖、英雄前辈和当代先进模范人物的传记。 河北省和红色电影有着密切的关联。《地道战》、《狼牙山五壮士》、《小兵张嘎》、', '2011-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAiaR807MNlHt5Eb40m7N5tor42wvdbMf-yVnc2RhmesO2XSleVlcmPuu8yV4MoqDUrykHPqSP8u-8x74qCc9OtJTUp0mvZoVbdaFh7XKvxyZC9RSm8oHeAOrw4sVLWV8FDhgo2Er74-Q==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4583, '报纸', '铸就永远的“军魂”', '冯春梅', '人民日报', '人民日报', '党支部书记;基层党组织;党务公开;支部建在连上;', '党在人民军队中的基层组织，自建立之日起，就是铸就党对军队绝对领导这一“军魂”的组织基础和战斗堡垒。 70多年前，红军之所以艰难奋战而不断壮大，“支部建在连上”是重要原因。 今天，我们仍然可以看到这句话的新时代印证。 在汶川，在玉树，', '2011-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID1T-6V6ybfChLszdPk9x-2VDfhvdKEvihiosrj3I-slvAtyHM9qGlWtzvWLO5Mxcm8HOcJJscdJTQiwGgXyyb-S6Fsgpk2DNO7PRMl9ISkxdRsYDyJmf9356OcvtS76VWNCkEK3nk_TA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4584, '报纸', '视死如归 宁死不屈 狼牙山五壮士', '', '人民日报', '人民日报', '狼牙山五壮士;马宝玉;晋察冀军区;', '据新华社北京３月１７日电 抗日战争时期，在河北省易县狼牙山战斗中英勇抗击日伪军的八路军５位英雄，用生命和鲜血谱写出一首气吞山河的壮丽诗篇。他们是八路军晋察冀军区第１军分区第１团第７连第６班班长、共产党员马宝玉，副班长、共产党员葛振林，战士宋学义、胡德林、', '2011-03-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICif6aE8X0aEWxxWEcEQMHMZvOSOmKDaJA0Mt3NWqJc-aQf6LUbAzjEAlP7ma0jjWrOEwIhAmIL0ImST1pQcD9ZNlalI3P9QPEqYZqTH1U8ybjM7xTVQlwLelf7ofvYTS7IuA-48Z5-OQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,抗日战争_screened');
INSERT INTO `ds_article` VALUES (4585, '报纸', '贺捷生委员——中小学课本不能没有红色经典', '邹维荣; 卜金宝', '解放军报', '解放军报', '红色经典;中小学;红色文化;', '“执政的中国共产党人，绝不能离开红色文化。”军队政协委员、军事科学院原军事百科研究部部长贺捷生说，“这是共产党人的灵魂，必须大力弘扬。” ２０１０年９月，一些版本的小学课本将《狼牙山五壮士》等红色经典删除，引起广泛关注。贺捷生委员认为，红色文化见证了', '2011-03-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICRTu9iyNR77PnQU7oNhM6JDx8gbbXBvsBQ8iXbFoyVBu7LODPg-LdxjYdL6CYqbUOFaFrFdzr4VL7KTknJRTGI-WBmYuvpctJq9Fi5cOHHOiUBOBctQ1NfMC-6fgxKmIFHKqVKULdxYw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4586, '报纸', '英模群雕传承崇高信仰', '李华敏; 罗辑', '解放军报', '解放军报', '尖刀连;密云县;塔山英雄团;崇高信仰;', '广州军区继2003年为所有团以上单位配发了7位英模人物铜像雕塑后，今年5月，又铸造并配发了以杨业功为原型的英模铜像雕塑。除此之外，几年时间里，广州军区各部队结合本单位团队历史、英雄人物形象、营院建设理念等，又相继建成200多座各具特色的军营主题雕塑。雕塑这门艺术从', '2010-09-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAHo5kOShxKNDlVl7azAnj9EBTTyODP9BHbYZW23Ve68Y7t04Doe3j3QNrjeA8yp1NxqBNuBrmsejiznT2_9PF3MD5eDgNvPA1d1XcSlrYqRxeX0Zqv73phiKSqiPjydM5rPn0fCehucw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4587, '报纸', '65个历史细节 令人荡气回肠', '曾火伦; 梁培 ; 唐亮 ; 彭亮', '解放军报', '解放军报', '东北抗联;李桂丹;四行仓库;中条山之战;吴淞要塞;新四军;张自忠;历史细节;魏拯民;马玉仁;晋察冀军区;手榴弹;', '真实的历史，常常隐藏在细节中。65年前结束的那场战争已经渐去渐远，今天的我们，很难想象刀光剑影、血流成河的战场到底是什么样子。但是，当我们从历史的旧纸堆中，重新翻检那些的细节，抗战英烈面对滴血的屠刀和发烫的枪炮，所表现出来的坚定与从容、刚烈与无畏，依然震撼', '2010-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB9v9H8hBOk9uRFXC_B_PIhdTRJRsBEqnAPidSj2qoRFmpqBvH7FboyL6yOybwK8JmWYnUxumTjxvVnQ-exhEauzQLW8X8hmm0fvdkrW2HH-IdmWEeBrZEfmVHzSjfLpKAXyj7FtP8ThA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4588, '报纸', '铭记伟大历史 开创美好未来', '', '光明日报', '光明日报', '反法西斯战争;共产党;中国人民抗日战争;全民族抗战;', '今天,是中国人民抗日战争伟大胜利65周年纪念日。此刻,我们手捧鲜花缅怀先烈,我们掩卷长思铭记历史,我们把盏举杯欢祝胜利,我们昂扬斗志面向未来。 65年前,中华民族冒着战火硝烟,用血肉筑起新的长城,英勇奋战,前仆后继,最终赢得了战争,赢得了进步,赢得了荣耀。这是一', '2010-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIClhMN4fPWIJpAwSGdb7UyNtJJJ2FTe3gm2fAYEhsq0vyAXi1buMFYB3j1M507cocdFObk1jxsGQxynpuR_98xfe2Z1xD-C6hJkVV9mymzxH3bQ1pxohsZd4s2h4e8mMEpF2-BZBfP2Xg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4589, '报纸', '曹坝岗五勇士：神勇堪比狼牙山', '陈豪 ; 李东星', '解放军报', '解放军报', '李连山;晋察冀军区;狼牙山;狼牙山五壮士;', '许多人从读小学就知道狼牙山五壮士。在当年晋察冀军区第十一军分区所在的河北涞水县，有一个与狼牙山五壮士齐名的英雄群体——曹坝岗五勇士。他们在弹尽粮绝、敌军包围之中纵身跳崖，无一人生还。这一段事迹很长时间不为世人所知。 1942年12月27日深夜，日军纠集1000多', '2010-08-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA4vcwFEeyZ3BjUvq5aQ7X_zBAcIFg3ELJSAJve_HGg1evZqM3QQUP-sHT9cRQCroCVMAOd2Uz1KBaB-9ncnhrvsAPXrEoSOVwbxzD-bWOLHY4rsuPr9wLazR-RmPbNMUhGZ7ptfoGtAg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4590, '报纸', '探寻“七七事变”的精神坐标', '白瑞雪 ; 王玉山', '新华每日电讯', '新华每日电讯', '七七事变;中国人民抗日战争纪念馆;', '一把近一米长的钢铁大刀,陈列在位于北京西南郊的中国人民抗日战争纪念馆里。  刀刃不再锋利,银色的刀背有了些许青锈。但,大刀光华仍在,璀璨如昨。  “七七事变”,日本全面发动侵华战争。这是中国全面抗战的开始,更是民族精神新的起点。 举国万众一心', '2010-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBo6APJUGE4MzBWNnZfPydzrmgNi_KLTKzjoYp17Stxr7zZI9VwMDDPQryhZ7xfyn2vjLUuaxeRxaRhnrhtrUC2x5us875XXRqglmGyibfGDqMlCMBDHizZS8fSIql95vMNQ5vwtg_sBA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4591, '报纸', '英雄足迹在这里延伸', '林山杰; 李华敏; 罗辑', '解放军报', '解放军报', '狼牙山五壮士;大渡河;国庆阅兵;', '“马宝玉。”“到！”“葛振林。”“到！”……在阅兵训练的日子里，首次参加国庆阅兵的广州军区某部履带式步兵战车受阅方队，每天都采取几十年来部队传承的例行点名方式。每当值班员呼点英雄的姓名时，所有官兵便会齐声答“到！” 记者翻开方队花名册，看到“狼牙山五', '2009-11-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAltqwQsx6rWscy4vYjatcpqiBWQGzITvjPH3A_MY0gxU6XcDsG2rnyQw8NY_PilVWA9WS3OnNkfiUy7Sij34DO5NB4foxlCqnNpE-lOb5ka0cL0hdLULbS2b_BQvAnVQ9S0xaItWUrzQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4594, '报纸', '“让他们的精神代代相传”', '隋笑飞', '人民日报', '人民日报', '狼牙山五壮士;感动中国;时传祥;孟二冬;劳模精神;新中国成立;', '据新华社北京９月１５日电 （记者隋笑飞）“先辈入选‘双百’人物，我们感到无比光荣和自豪！作为他们的后代、新一代共和国建设者，我们将以先辈为榜样，继承发扬他们的精神，共创祖国的美好未来！” “１００位为新中国成立作出突出贡献的英雄模范人物和１００位', '2009-09-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBur5VtMG8eR8WmVvoyR0uxUpme0qA4LGTqinW3w092s-7n-8EV_pje5zLXapwZXV8n9I2LUI-3Hq4iIT__g0S0IpQuvhNlxH4jhUpSyQBxJuhMyQMmCvtcal7oafxND54Y2PfzP2MztQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4596, '报纸', '穿越时空的力量', '廖宝祺; 李华敏; 罗辑', '解放军报', '解放军报', '狼牙山五壮士;阿部规秀;尖刀连;穿越时空;', '伴随井冈风云，踏着抗日烽火，淌过平津硝烟，广州军区“红一团”所在师走过了极其不平凡的70年，涌现出强渡大渡河的“十七勇士”，击毙日军“名将之花”阿部规秀的功臣炮连，“狼牙山五壮士”、“密云尖刀连”等几十个英雄群体和数百名英雄个人。  时光荏苒，斗转星', '2009-06-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID9hPmXuDXTkkSInydR4jEGEnp7zc86B4PIfEh0dc_-cktmTQknqKsdyIrU1_Q2GqK0QO66Do0kSYMNH4NyUaZhdiyJ0T49M-MY3G8kxnpIjYXwwN0tV8SIMF-_dsNTxhOrLd6jQeYvLA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4597, '报纸', '不分党派,为中华民族牺牲的都是烈士', '黎云; 张汨汨', '新华每日电讯', '新华每日电讯', '中华民族;民政部门;', '清明节将至。  一篇《上海四行仓库保卫战的“八百壮士”遗骨在海外无人问津》的网帖，在清明节前夕，唤起了人们对烈士的思念。  尘封的记忆被打开。“八百壮士”“狼牙山五壮士”、邱少云、黄继光、张自忠、佟麟阁、赵登禹、王铭章……这一个个浸染鲜血、', '2009-03-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDN9wcF5JHOv6lQJ09Lk2T12CfA09aNua2T1_KywOfwyPl8ziPHRZNH4feVnYKHM6CR1qWkJZbrLlxEURCGdtZonyGD3Kcx_AAAS0lCW5pa1ycL8Y6WGYuvkWcWdQMaDt2tY7m6O5wTvw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4598, '报纸', '追寻在太行山上', '郭建跃; 杨鸿; 郭冬旭; 刘计平', '解放军报', '解放军报', '太行丰碑;在太行山上;国家安全形势;太行精神;', '今年8月1日，66岁的苑桂生冒着生命危险爬上了太行山第二高峰——奶奶顶。陡峭的山峰无路可行，但只有爬上去才能找到当年跳崖抗日壮士的墓碑。  终于把你们找到了！老人热泪纵横，用颤抖的笔记下了刘玉英、曾仁文等6位英烈的名字……走过八百里太行，寻遍晋冀豫65县', '2008-09-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAjANi8sL31Bi7cIR0CTOGWTr38JmWA8Yb7FYHi1i3Q-0JfFZAXyAr6bnuSUkkOZI6-mBg0NymVYSmEDkRCQlTf7zXRnbl-U-uTJf4pscLYy_T4GdlbVv_yLsOGOaMFY8iPJ8dYj5vbgQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4599, '报纸', '毕生星火志 半世燎原情', '张以瑾; 刘国顺; 王南方', '中国教育报', '中国教育报', '共产党;红色经典;', '《朱德的扁担》、《我跟父亲当红军》、《刘胡兰》、《狼牙山五壮士》、《草地晚餐》……类似的革命故事，中小学课本总共收录了36篇。许多人并不知道，这些故事出自一套名为《星火燎原》的丛书。这套六七百万字的皇皇巨著，凝聚着一位老编辑的毕生心血和信念。他就是黄涛，解', '2008-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDi04eqTsNPn9fPCc6NOEFLTI8KyNpqLGz8zkDXi9GxVEtYsUwPxS9wMnoRn3GrNGmX1gLQ7ZrSCrE7l1q9kcdqZ7PqUBfNfDSbZlrIR7Z7hd5N7LD1rGoXLJVjaF10-pc1Zlw8hFDxYQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4600, '报纸', '激荡80年的英雄乐章', '', '解放军报', '解放军报', '黄继光;人民军队;革命英雄主义;', '每一个时代、每一个民族，都有属于它自己的精神高地。如果把我军80年历史比作一首精彩乐章，那么英雄就是跳动的音符；如果为我军80年历史勾勒一条清晰线索，那么英雄就是串在这条红线上的一颗颗珍珠。 经党中央、国务院、中央军委批准，今年“八一”建军节将在北京', '2007-07-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAzoEcZHwX4Z-zwhmqxtPmwbUcaM_dxzI3Wkn4fhyCSbTteYuSQbLw0yXiJqH3o92hK5Q5eOJbz1kZw32m6jDIB9g8qArLYVeKsrbAjDiL5z-qRmXLUbi7q3QH9ecLFYimaly340bXX1Q==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4601, '报纸', '敢打头阵立新功', '黄庆畅', '人民日报', '人民日报', '强渡大渡河;清风店;长征精神;', '开栏的话  作为一部生命写就的英雄史诗——长征，锤炼出了党和军队的一代精英；长征精神，成为党所领导的日益强大的人民军队不竭的精神动力。 今年是红军长征胜利７０周年。为回顾和纪念中国共产党领导的工农红军艰苦卓绝的光辉历程，宣扬人民军队无往而不', '2006-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBbEiAAebuG_F38TPvYQBckM07Dx1Jcba3s1VGZY22UbCyA5LQAGuk6UjBa-XrNVAI7qmxthgM1lPKxTK4UgcR9Yl-39YtA-J0f3sr3Z2eDrKVoS14UvebDiVDIagvTiUmNEKs7XdMkeQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,强渡大渡河_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (4602, '报纸', '历史的硝烟 血染的记忆', '潘衍习', '人民日报海外版', '人民日报海外版', '抗日战争;美术作品;', '今年８月１５日，是中国人民抗日战争胜利６１周年纪念日。由中国文化艺术界联合会、中国老教授协会文艺专业委员会联合策划编辑的《历史的硝烟 血染的记忆——老艺术家笔下的抗日战争》大型画集将在这一天由中国文联·大众文艺出版社出版发行。 关于伟大的抗日战争，', '2006-08-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBzoPEvYxOi46_0irRpu_lEyIvd0YsTrAi2z5zJeRe3Pwhz_D2h6lIa0As3QiorrOICUjYr1yVjcmMHKRa2bheiYWIwodKd9SSU3qsgUun8I8RBWBfx2ZaUoOB1mGQSiP2EEMK5PqIr3Q==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4603, '报纸', '用抗日战争的生动历史推进青少年学生爱国主义教育', '袁贵仁', '教育部;', '人民日报', '抗日战争;青少年学生;爱国主义教育;抗日民族统一战线;', '伟大的中国人民抗日战争，坚决维护了民族的独立和尊严、国家的主权和领土完整，也孕育了以爱国主义为核心的抗战精神。这种精神，凝结着中华民族的光荣传统，凝结着中国人民的坚强品格，凝结着中国共产党人的优秀品质。这种精神，是我们民族的无价瑰宝，是推动我们前进的巨大', '2005-09-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDaEF1Cn536ImDgd0u2VtMblKRZ2k5rNOuuXeSJJ_fypoiloO_MblyB0GW8wR6sCvdtF6qPne64axNIcBOkiXX_KK3V1QUnPd44SBdYf0kr7iECbaOBkKf2w4ae50vx4VXliUGN2VI54Q==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4604, '报纸', '历史启示未来', '沈路涛; 田雨', '新华社;', '人民日报', '中国人民抗日战争;世界反法西斯战争;', '“牢记历史、不忘过去、珍爱和平、开创未来”。 9月2日至4日，170余位抗战史研究的专家学者齐聚一堂，进行学术研讨，纪念中国人民抗日战争暨世界反法西斯战争胜利60周年。 专家学者们认真学习胡锦涛总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利60', '2005-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA8N6vu-RL1HgmpXKyJq7XF9NpQoJnB7iDCkxK-FEOk_0BvU-_zvi9tSP9d6nEzuGNNKoMdJUm_9dB2kV_I6Gd2Em_2hTg06_CWsemTPuPvTP-CrYYL0KBlbqEUA_M41YMv0IcOXtCk0A==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4605, '报纸', '弘扬伟大抗战精神　忠实履行新世纪新阶段我军历史使命', '李宣良', '人民日报', '人民日报', '军事斗争准备;中国特色军事变革;新世纪新阶段;历史使命;', '新华社北京9月4日电　（记者李宣良）胡锦涛总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大会上的重要讲话，极大地鼓舞了人民解放军和武警部队广大官兵。官兵们纷纷表示，要大力弘扬伟大抗战精神，切实把爱国热情转化为报国之志、强军之举，为加强国防和军队现', '2005-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBMh5aVDx0dJ-_n_5pVCr6q41nY9P5wDW07625NtXbp-M3dL7FejS5nN76UgHiTtzD9P0ji5NuxabV-XDPvRKLeBTQYlp91g6f_aE9sM5-QkGY7xrdTPj4f5imAfE1OlkUhByivEQhHEQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4606, '报纸', '在纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大会上的讲话', '胡锦涛', '人民日报', '人民日报', '中国人民抗日战争;世界各国;中华民族伟大复兴;全面建设小康社会;世界反法西斯战争;日本侵略者;', '同胞们，同志们，朋友们： 今天，是中国人民抗日战争胜利纪念日，也是世界反法西斯战争胜利纪念日。我们在这里隆重集会，同世界各国人民一道，纪念中国人民抗日战争暨世界反法西斯战争胜利60周年，纪念这一正义战胜邪恶、光明战胜黑暗、进步战胜反动的伟大胜利。', '2005-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID61yw6qjd9qkpwk1nQRNzNJvSV-LiBXdrH2eOjDMt-WUeeg0Snxh3nDXpsKckV8FxFUvifyUnFuTNqde3a8SQeZGsmi3vyUkfp1NYgJe01_G71bUOab7LM34fD3fq8KfqG8fkeARn4ag==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4607, '报纸', '保定军分区学习抗战历史探索人民战争新样式', '张潇贤', '中国国防报', '中国国防报', '抗战历史;人民战争;军分区;', '本报讯 “地道战故乡”清苑县冉庄，敲响了 老槐树上的洪钟，百余民兵在地道 战遗址广场接受爱国主义教育…… 河北省保定军分区以纪念抗战胜利 60周年为契机，依托丰富的抗战历 史资源，采取多种形式开展“学习 抗战历史，弘扬抗战', '2005-08-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDAgCFU4AvVici523ALedZx7l7H6oh8QgenjKxmHNLrrQd_14lUCd_Ts5l1exnoXVByzJKdA-dp1qGYVsrWh0Y1CZqJouVxBg4mj9-ZRLjRIX1kDlArWcxDtQb9czDSQ87pShDkzpKrcg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4608, '报纸', '徐信：再艰苦，也要打鬼子', '董宏君', '人民日报', '人民日报', '日本鬼子;晋察冀军区;手榴弹;抗日战争;', '人物小传 徐信，1921年生，河北灵寿人。1937年参加八路军，同年11月加入中国共产党。抗日战争时期先后在晋察冀军区任政治指导员、连长。1944年9月，只有23岁的他开始任冀中军区第44区队区队长、第32团团长，参加了百团大战和多次反扫荡作战。新中国成立后，曾任北京', '2005-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAc9asxhx4Wla-Aaxn8P11BPJaI-tpvP0Jpq9R4tFq5Hkuw_-HD_Ui19-8UNWs_KGG3Bvo7Taqry6eXqou335h4it_2A98cq3xzlApqhIkw1zAt-0XfP3gq5I4_SNof5Dq-SHS0snHyYg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4611, '报纸', '走进英雄团队', '', '人民日报', '人民日报', '抗日战争;海上猛虎艇;叶挺独立团;威震天;军事训练;东海舰队;秋收起义;三等功;二等功;第二炮兵;', '因为有了他们，一部中华民族的史诗更加绚丽；因为有了他们，一部人民军队的历史更加灿烂。他们，就是我军各个时期涌现出来的英雄团队。 为纪念抗日战争胜利60周年和建军78周年，我们特别选择了一些英雄团队的事迹奉献给读者。这些都是各个历史时期特别是抗日战争时', '2005-07-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBT7qfmhYcGEPXCVrhc7kQw29XLrcSlmAb-y_Yge51rRGzLHSCf0ZxvMB32065fsW5oz_fSL8gdenoRPpF2xrRRCY9NcmTbWSbYFS9gQwo1KzpFQdmbeF4osJR5sgU3Q9vojchQydsDeA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened,百团大战_screened,飞夺泸定桥_screened,秋收起义_screened');
INSERT INTO `ds_article` VALUES (4612, '报纸', '舟山群岛上的“海上狼牙山之战”', '郑黎; 李稳', '新华每日电讯', '新华每日电讯', '大鱼山岛;日本鬼子;新四军;狼牙山之战;', '新华社杭州7月21日电（郑黎　李稳）61年前，为配合盟军太平洋大反攻，新四军浙东纵队海防大队在东海大鱼山岛进行了一场恶战。面对8倍于我的日寇陆海空现代化重兵，我军以落后的武器装备，苦战孤岛，临危不惧，宁死不屈，最后坚守阵地的40余名指战员壮烈殉国。此战在当时产生', '2005-07-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC8C9YXD8cKHEHgXzN3sAsWWPE9rCLEGYZETkyjB5ynR806n8DfE9Ss6DBcxNyKElSoFTfoM_3pcl-xFTaNzcam5BYF2dd5xoNynE_bmVdNgpPfWDQKVDp40Cti7cS2zAnqOjO72nFZZQ==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4613, '报纸', '祖国至上', '王建新; 冯春梅', '人民日报', '人民日报', '狼牙山五壮士;历史遗产;爱国主义;抗日战争;张自忠;', '一步一步迈上台阶，跨入中国人民抗日战争纪念馆庄严肃穆的大厅，“血肉长城”巨型雕塑巍然矗立：一个个挺直的脊梁，一双双坚毅的目光，展现中华民族的英雄儿女面对外敌入侵时不屈不挠的民族气节和崇高爱国主义精神。 “艰苦卓绝的抗日战争为我们留下了内容丰富的历', '2005-07-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAAa2KICDga8f8W_9z8TO2F_hRw5RfrdrM-BWeZ52yvpjaqgSOw-1qOlKqWsZWHr1QoikMheSWM9nEx2aQ1AONSKMkxtXlxqiJKWiQmFiIJbmTtzuA06SgE6hFb6jo605Fra4ppCJOuAg==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4615, '报纸', '易县：狼牙山下春常在', '朱虹', '人民日报', '人民日报', '狼牙山;春常在;', '编者的话 地处河北省易县西南部的狼牙山是著名的抗日根据地。“狼牙山五壮士”的英雄故事感动和激励了一代又一代人。易县充分利用丰富的红色和绿色资源，脚踏实地建设生态文化旅游强县，促进了经济社会迅速发展，老区人民过上了幸福生活。 7月的狼牙山，峰', '2005-07-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDd6157tIzod8tbENNRxH64ZteF1BiiOhOMxH6f0G-MelTrpcsErC_KKabBJiebwD3zSMrxTWtA459eVKIPa_hQMQSkl8IkmEIQp1Nwul2NMzUzGtzqdIkBeFSvBTcyy88U9aBCziFUtA==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4617, '报纸', '千里行军路 处处设课堂', '李玉金; 彭泽成', '解放军报', '解放军报', '东江纵队;', '本报讯 李玉金、记者彭泽成报道：深秋，刚参观完“中国工农红军东江纵队旧址”的广州军区某高炮旅数千名官兵，以昂扬的战斗精神冒雨行军两昼夜，克服“蓝军”设置的重重障碍，攻克了“防空兵动中空情传输”等5个训练难题，齐装满员到达某海域。  这个旅从营区出发后', '2004-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBHe7WhSvoggCC6F1MGc2LrxOmHKlpHAdVe51UCWAkexeDnlmnNpQ9MvchhdDjZGZ__dyu1PXjLPVL6BvKR-hyaG7ENqgVEZQvymVaPEIW2kABZn0CkPpiXW_RB30aLZbMp8RK_KCzLQw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4618, '报纸', '浓墨重彩绘时代画卷', '曹慧民', '解放军报', '解放军报', '美术作品展;绘画艺术;社会主义文化;“七一”重要讲话;', '世纪之交，军旅画坛两件盛事被载入史册── 《抗洪精神赞──全军美术作品展》，上百名部队画 家激情挥毫，再现气壮山河的抗洪抢险斗争。其飞动 的色彩，雄浑的场景，在中国美术馆卷起阵阵热浪， 震撼万众心弦。另一件是在第九届全', '2001-10-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA7TGfOPVWmIjV8tJl6djGItq-6W5agVdL37N453O4meFLWC1G7Ym1b_2kS00AwxHtH13nHLCHwAU5QLKChsH64_fyUjBsts3B9sTTY4qJFOxCwJcWdA7ugrki1BdZtlb2_YhSnKooZKw==&uniplatform=NZKPT&language=CHS', '狼牙山_screened');
INSERT INTO `ds_article` VALUES (4619, '报纸', '延安整风的基本经验及现实启示', '黄昆仑', '解放军报', '解放军报', '延安整风;现实启示;高级学习组;', '2015年春节前夕，习主席在中国延安干部学院主持召开陕甘宁革命老区脱贫致富座谈会时强调，革命老区是党和人民军队的根，我们永远不能忘记自己是从哪里走来的，永远都要从革命的历史中汲取智慧和力量。延安整风是中国共产党1941年至1945年进行的一次全党范围的马克思主义教育', '2015-04-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSHutJD0Q6Za5eUJJlE8hz8dPyb8FoqQMYzI4ftwTXdP5EhvhOpq1uCJWySSO2Qehsi4SV6kN0nq_0RmKbfIcd8NAhwmwm-Eq1w7Jr2oTAffmZtqLszDzkn5m-Nb03sdpQtoMU_k82m4g==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4620, '报纸', '在纪念彭冲同志诞辰100周年座谈会上的讲话', '李建国', '中共中央政治局;全国人大常委会;', '人民日报', '共产主义;副委员长;新四军第二支队;全国人大常委会;党中央;省委第一书记;座谈会;', '同志们、朋友们： 今天我们怀着十分崇敬的心情，在这里举行座谈会，纪念彭冲同志诞辰100周年，深切缅怀他的生平业绩和历史贡献，追思和学习他的革命精神、崇高品德和优良作风。 彭冲同志是中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家，我', '2015-03-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSl03Dk9XuUf-_HUcP9GS2szRYz7k4qmRDrV2b8ZZSIWzhErpvgIQEFFdJUB6DrmV70QVISHUNrplum24Ky9aow8fQtI9w61Y0RUjhxHuny6StgogV9ozFq2C6X70y_XWFA4DzZNm_91w==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4621, '报纸', '在纪念赛福鼎·艾则孜同志诞辰100周年座谈会上的讲话', '李建国', '中共中央政治局;全国人大常委会;', '人民日报', '新疆维吾尔自治区;新疆和平解放;座谈会;', '同志们、朋友们： 今天，我们怀着十分崇敬的心情在这里举行座谈会，纪念赛福鼎·艾则孜同志诞辰100周年，深切缅怀他为中国革命、建设、改革事业，为国家统一、民族团结、边疆稳定建立的不朽功勋，学习他为国家、为民族、为人民不懈奋斗的崇高品德，弘扬他始终不渝的革命', '2015-03-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRSYlU4XD3rg_wEiy0SKw3StKAxSonFOxul-KF_4NjyZNRKA4dKghjbEndVJyHJXxxltwF6x0KG_PcJRunPMZZ71SLSZlzw3nIQ008Gzny2K7RycwyOXu_RcCpG6nZDornPn39M3SFzlQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4622, '报纸', '文艺中的“战争与和平”', '张丽', '人民政协报', '人民政协报', '文化周刊;文艺工作者;大刀队;抗战题材;文艺作品;陈维亚;文艺晚会;习近平总书记;中日关系;《拯救大兵瑞恩》;', '阅读提示： 1945年9月2日，日本签字投降，标志着中国人民抗日战争的胜利，也标志着中华民族屈辱历史的终结。伟大的胜利离不开社会各界的积极抗战，文艺界也不例外。其间，以宣传民族救亡、抗击侵略为内容的文艺作品大量涌现，为抗战中的中国人民带去精神上的强大支撑与', '2015-03-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQS4Nc6DALH0oYVWB5_5W8iQvfG0PvlZDtDIil7Pdj6tKzETk0_t6bIvdk17PQ_gjnOYGqqkftj6pW3TtOJ7nG8DYVvw_Q2ED_a13KvbvUbCX8oWn_WZnIQG0PQYwZ-cbe0as4Z4rR1WQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4623, '报纸', '“学习周恩来同志的优良作风和优秀品德”座谈会发言摘登', '', '光明日报', '光明日报', '周恩来精神;优良作风;座谈会;', '周恩来的优良作风与优秀品德永远是我们学习的榜样 中央文献研究室主任 冷溶 周恩来是中国共产党人的优秀代表和精神楷模。他的精神风范，内涵非常丰富，是一座精神宝藏，我们要不断挖掘，从中汲取力量。我想着重就周恩来精神风范中体现出的“忠”“严”“实”这三个', '2015-03-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSRtUZEX5pcHd7e8DDTbk3cCqhMPw_cRHDcM9Rodb_xv6vY-Su60Pq4HTn2ancMrZ9mJAXFyK3f6cKw2_qW3xHygs33D7Soya0B1In2eO9NiUoi1D7ySFXtvSKOSFPtsIWX-1TJRUqhLQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4624, '报纸', '服从组织不容讨价还价', '', '人民日报', '人民日报', '非组织活动;政治规矩;', '区分党员干部与普通群众，检验一名干部合不合格，一个重要方面就看讲不讲党性，懂不懂规矩，守不守纪律 邓小平晚年时，女儿曾问他长征是怎么过来的，回答只有三个字：“跟着走！”几近山穷水尽时，一路枪林弹雨中，坚定不移跟党走，步调一致不迟疑，革命队伍就这样迎来', '2015-01-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQEwcxe74J_kfqXn-1OB50Bk8AazoLwYGpKoEQSsvI-y7EA8TwVvjd9BtFgiI1NZH-dhoXnWmLAUQt9p4kt0C67bOsYGhLba4W0hkLLY4Pea9mdExczwbUa7NBWTejILuRa3v6ZM3Tajg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4625, '报纸', '气壮山河的爱国精神 荡气回肠的侠骨柔情', '', '中国文化报', '中国文化报', '义勇军;北市场;', '为了纪念世界反法西斯战争胜利70周年，重现当年东北人民抗击侵略者的英勇气概，辽宁人民艺术剧院创排了大型话剧《祖传秘方》。目前该剧已在沈阳演出多场，并参加了辽宁省第九届艺术节、第六届国际戏剧奥林匹克展演，获得了专家和观众的一致认可。 话剧《祖传秘方》以九', '2015-01-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTTGT00UVpd1hnVz4sPtRHtI1HIyBjaGeqtzXDmL-o7OaRHlV_Jq6IvRwJo4k6K2PHTTj18jLjpu2FH3FHN-VWUXBK2lZAD14HWbajQs5z0VSx8khNJ2O9PlvqDQ4U8lglY1mjyw9iv7w==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4626, '报纸', '一部感人至深的爱国主义精品力作', '', '中国文化报', '中国文化报', '杨靖宇将军;现代京剧;吉林省文化厅;中国艺术研究院;爱国主义;', '吉林省戏曲剧院京剧团排演的大型原创现代京剧《杨靖宇》，以生动的细节和深厚的情感，艺术地再现了革命烈士杨靖宇的爱国热忱和献身精神，在天津举办的第七届中国京剧艺术节上，赢得了广大观众和专家的一致好评。 11月21日，文化部艺术司组织召开专家座谈会，出席座谈会', '2014-12-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRFr9r_mG_uIuI3jM2NvYUlPGAUeiJrVmZ2sClXCU1BbfdDznPtWVNPwXsNa7zbpiVpfmqfcer8bG9ZuytzhQsmUlmw-8ka3Ot5XNFhvjbhZJh5FzYdJPMNboCjmcc-Ps0t8tTQG1syIQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4628, '报纸', '锻造中华民族的精神品格', '戴旭; 蒋正翔 ; 章丽鋆', '中国人民解放军国防大学;兰州大学新闻与传播学院;海洋安全与合作研究院;光明网;', '光明日报', '中华民族;中国共产党领导;帝国主义;上甘岭战役;《马关条约》;精神品格;', '地点：齐齐哈尔大学音乐厅（“核心价值观百场讲坛”第八场） 时间：2014年11月 2014年是甲午战争失败120周年和抗日战争胜利69周年。中国举行了多种形式的纪念。同时纪念一场败战和一场胜利，这是一个世界奇观。 这是在同一个战争舞台上，与同一个对手，在不同', '2014-11-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQPLkyeFSIRsZRcEXpIesj5El9NoUnK_OPxOPhARYFViQcp5loyZ3VFXaCuC3dAG0IEXOPBMvbtc1eXu8LkzvlAoY-DVOGhIEJN1i8vpytkDue81t6rU4-mASsyKlsuIcPfaiVrFcrQkw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4629, '报纸', '中国文化的“老道理”', '王炳春 ; 梁枢', '山东省尼山书院;', '光明日报', '乡村儒学;尼山书院;山东省;梁漱溟;乡村建设运动;', '时间：2014年9月13日下午 地点：山东泗水尼山圣源书院 开栏语 发源于孔子诞生地尼山脚下、由一群“背着干粮为孔子打工”的学者义务到农村讲授传统美德而演发的“乡村儒学现象”，在古老的齐鲁大地已洋洋乎蔚为大观。山东省尼山书院与光明日报国学版共同推出“乡村', '2014-10-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRVo0AZDcejjGNLXimzOsBWbkb-RXHpHv6bguG97Uou8cRaRJphlg34V2DjJRhWO4-KSQYmuyXsPMylSBc5BaalNrq5Ws2cpZT_qRVDfjnJzYKnblcX5Srw0_yN2K8Cf7oA8BxDvWENug==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4630, '报纸', '让法槌敲响历史的警钟', '韩芳; 刘宝权', '人民法院报', '人民法院报', '日本战犯;国际法;最高人民法院特别军事法庭;出庭作证;战争犯罪;战争罪犯;', '编者按 9月3日是全世界反法西斯战争取得最后胜利的日子，也是中华民族近代史上一个值得扬眉吐气的日子。为牢记历史，缅怀英烈，弘扬以爱国主义为核心的伟大民族精神，2014年2月27日，十二届全国人大常委会第七次会议通过决定，以立法形式确定每年9月3日为中国人民抗日战', '2014-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT_11L9bDofQb1tgzpLaIGfF6hZkv34qOH92pKrj4QDKJkybCAXbbpRueoQvpfYaGg3FTyViNu9qiMaqCHJeKOv7OEeor_kbpZqihC9bPvhBdtiQBHiXY_2fpgrqWhtZ3_GyAOVE9ikdg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4631, '报纸', '铭刻心中的记忆', '', '经济日报', '经济日报', '张自忠;受降纪念坊;日本投降;中国人民抗日战争;宋哲元;华东革命烈士陵园;甲午战争;抗日根据地;小白鸽;以史为鉴;国家档案局;中华民族;', '历史不能忘记。69年前，中国人民取得了抗日战争的伟大胜利。今年的“中国人民抗日战争胜利纪念日”即将到来，让我们重温那段华夏大地上全民抗战的峥嵘岁月，缅怀那些逝去但又未曾远去的英魂 中国人民革命军事博物馆： 历史从未走远 孙 璇 历史从未走远，', '2014-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR0Tl3Hk7KJczTXuAtrtVgE57GNAdQUmZubPiLdr1Y-w9qyXCIhlM9aLnXs2H-Ywa26tfP5qkwMxSYP024LkOAfYdoWKR_hbp_hMsX2-iAvtwZsoNlPJZghGWKMa-CL2N2QGpIGUvmuPQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4632, '报纸', '“9·3”为了胜利的纪念', '刘少华 ; 柴逸扉', '人民日报海外版', '人民日报海外版', '抗日战争;世界反法西斯战争;王新华;南京大屠杀;全国人大常委会;', '翻开泛黄的旧报纸，1945年9月3日的重庆，纪念抗战胜利的场景仍历历在目。 电力公司拉响解除警报长音，轮船汽笛长鸣达10余分钟；军舰上，101响礼炮响彻云霄；彩灯高挂，锣鼓喧天；数万人自发参加声势浩大的庆祝胜利大游行……人们的喜悦写在脸上，挂在心头。 关于抗', '2014-08-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRGl5Y32WvWyXKWkRIZkw1KTFsdWNOswa3ADLBY3cFwMrv5-b8LvVWty7Y7Udg1DkSoEq1Akzxi6V6XIArIGpMq3zcz0BmLK3WEaI6clwkhYSRq04cEv02XwBlkYgSJbMhu7RhPbgQkFw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4633, '报纸', '八年抗战从未失守的“阵地”', '姜锦铭 ; 刘小草; 王小舒', '新华每日电讯;', '新华每日电讯', '八年抗战;南开大学;《大公报》;金岳霖;《国史大纲》;黄子卿;', '69年前,1945年8月15日的正午,日本天皇向全国广播了接受波茨坦公告、无条件投降的诏书,第二次世界大战随之结束。 整个中国沸腾了,胜利来得太艰难了,付出的牺牲太多了,压抑在心中的屈辱太久了,整整8年抗战,不,应从1931年9月18日起,如果再上溯还可以从1894年的甲午海战算起', '2014-08-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSVVGb-gF9HXxZ10GW_ay43mvZWr4PWQE7eSmAN_gkd4ZGdD6NCQRwLBwBI6fPvMwMO0r_JTuIDBDMHtt0xs7y0S8GkwmOSkY65_Mcvy_8uYorWQ33o1ZrLt5UKjQoawhuCDbuwS7qDOg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4635, '报纸', '甲午海战120周年祭', '', '人民政协报', '人民政协报', '甲午海战;甲午战争;日本军国主义;', '今天是中日甲午战争爆发120周年纪念日。 我们不缺纪念日，我们缺的是反省与行动。而反思那段惨痛的历史，不单纯是专家学者之事，应该是全社会全民参与。反省那段惨痛的历史，应如一位媒体人所说，“站在新的历史起点上，我们不是要沉湎于历史苦难，也不是要陷于历史泥淖', '2014-07-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTtoCtJSd_TKmLpeAlC7VpkmI3H9yncXgHuu2MO1kYcUCmjXMOp9gLiZvkuRwGyc4sWrZL79FjxkT5DunIbzexfnLx0IRPF8dWGxqn-gyLvnPFYzJw8Gh0-xsFhxv61RGV2gf4Vsgn-MQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4636, '报纸', '在纪念叶飞同志诞辰100周年座谈会上的讲话', '李建国', '中共中央政治局;全国人大常委会;', '人民日报', '福建省;闽东地区;独立师;新四军第一师;座谈会;', '同志们、朋友们： 今天我们怀着十分崇敬的心情在这里举行座谈会，纪念叶飞同志诞辰100周年，深切缅怀他为中国革命、建设、改革事业建立的不朽功勋，追思和学习他为国家、为民族、为人民不懈奋斗的崇高品德和始终不渝的革命精神。 叶飞同志是中国共产党的优秀党员，', '2014-05-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRT-fu6im0mbrgBfrobHint45G73NE4zF5Smt2HJyld-fTTnpABBs9BOU7nbWZvyBJfMqvVsXetPQHoAPTQTqVvRceU-u4JTEIRbErKwPIZxKmF2rhx1CkKAsnpFPB71L9gbAWU1a5CDQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4639, '报纸', '长安敞怀 新月高悬(下)', '唐荣尧', '中国民族报', '中国民族报', '大学习巷清真寺;学习巷;穆斯林;伊斯兰文明;图书馆;《新华日报》;张寒晖;抗敌后援会;大皮院;救国联合会;伊斯兰教;', '《松花江上》从大学习巷清真寺传唱 抗日战争期间，陕西西安大学习巷清真寺再次为世人瞩目。 1931年“九一八”事变后，东北三省沦陷。1935年，10余万东北军被调遣到陕西、甘肃一带。古城西安出现了不少东北军官兵和流亡的百姓，其中不乏来自东北地区的回族群众。因', '2013-12-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRzh7xj-dJ9d5GUMa879JdYlrt9YaZFi6Tae4uLEF1I3N81tooF9uAZSzSK2C4x2mDX-59knhDDUWK25LglZ_VIk2jzLL4f3uhqcdlgP035ghD3SwIWiH9UGKYihjlH4v43dv_GEjHUDQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4640, '报纸', '在纪念习仲勋同志诞辰100周年座谈会上的讲话', '李建国', '中共中央政治局;全国人大常委会;', '人民日报', '习仲勋;国务院;爱国统一战线;中共中央西北局;陕甘边革命根据地;座谈会;', '同志们，朋友们： 今天我们怀着十分崇敬的心情在这里举行座谈会，纪念习仲勋同志诞辰100周年，深切缅怀他为中国革命、建设、改革事业建立的不朽功勋，追思和学习他为国家、为民族、为人民不懈奋斗的崇高品质和始终不渝的革命精神。 习仲勋同志是中国共产党的优秀党', '2013-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQcKJvXfV7_pdZcON-OBMcVbz9VaUqJszHvFo8JKSRN4h10Rc2hQEElQCkD3fTFfaZ9oKL_IasB-AcOWPdUmUrAoTB40pnqpXZ5recPd4t1wcrUy1P16mZg9GQV20FJvnXQG5ZhzacGJQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4641, '报纸', '在纪念习仲勋同志诞辰100周年座谈会上的发言', '', '人民日报', '人民日报', '习仲勋;党中央;习近平同志;陕甘边革命根据地;全国人大常委会;青化砭、羊马河、蟠龙;刘志丹;陕甘宁边区;群众领袖;陕甘革命根据地;地方各级人大;两当兵变;座谈会;', '从群众中走出来的群众领袖 中共中央党史研究室主任 欧阳淞 今天，我们怀着十分崇敬的心情，参加纪念习仲勋同志诞辰100周年座谈会。我的发言，侧重缅怀习仲勋同志在新民主主义革命时期所建立的不朽功勋、所表现出的崇高品质和革命精神。 习仲勋同志是在艰苦卓', '2013-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRpNT3KxlMvFLpUgusg0QCVbHgQYemD9HClfU9s9py0f1YBTKVhQXB9dkaqCvQNJgzSYRHjNUegFUJzDKObiar_sVKnEcHQ88_UqkrCjgQhpO4khT6DcBwk68gPg1hunY_4nMtDfC-K7Q==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4642, '报纸', '一曲依靠群众克敌致胜的抗日赞歌', '', '光明日报', '光明日报', '《我的故乡晋察冀》;周振天;依靠群众;', '编者按 40集大型电视连续剧《我的故乡晋察冀》继在中央电视台电视剧频道播出后，近日又在河北卫视播出。由中央电视台电视剧管理中心、河北省委宣传部、中国电视艺术家协会、海政电视艺术中心等联合摄制的这部剧，生动反映了从平型关大捷到新中国成立期间晋察冀抗日根据', '2013-08-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR7u_m7Nk6Jx3JbkrgUb3LXLRskwb71UHoJb7unM_FjKPOFawQIGMkF8qU7LQqnVLjCvq4o1F7uQWnvNiheq7zxgijVhhdFyEcMzG5SSi5MF_augwOMiA2bvmnKTKmM2j0ts4pmwTs1nQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4643, '报纸', '用延安整风精神开展群众路线教育实践活动', '赵正永', '中共陕西省委;', '人民日报', '群众路线教育实践活动;延安整风精神;批评和自我批评;', '延安整风，彪炳史册。她是一次全党范围普遍的马克思主义教育运动，也是中国共产党历史上一次伟大的思想解放运动。最近，我们在开展党的群众路线教育实践活动的学习教育阶段，重温了延安精神和延安整风，努力用延安整风的精神开展好我省的群众路线教育实践活动。一份重要的史', '2013-08-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQpm7RuraxmfM8ANkSJJYFZt5kwDE8TETo_uFZKpYs7RW51MTW05Zd7LTUwbMVv7RMtNcyqdRjYM99DH1dJrf1olkxox-gepbjuNJWSuTe95YLA3Zzwmw33DxfjttqUAuwhZj_3LXaZrA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4644, '报纸', '一位献身革命道德高尚的巾帼楷模', '王潇', '国际商报', '国际商报', '张承先;教育部;革命道德;新四军;', '中共中央国家机关工委一位离休老干部的一封举荐信，揭开了一段尘封已久的革命历史。当日本军国主义的战火燃遍大半个中国，国难当头民族危亡之际，一个年轻的女教师毅然投身到抗日救亡的革命洪流中，启蒙恩师把她领进革命队伍，新婚丈夫与她并肩作战。抗日战争，她失去刚刚出', '2013-08-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtST8euZPuuFTxrSJ7lx9EJMckyXNDh3a5aBEr5UcZZRKuQjYzCDvHejS_k0gJRMJy0l5kCCcht3Nh9mF_oNhZi5N7pMFUM5quANmHmWL8kGgDL35VmL6apRtHUqUYwV7hRKYCFqt6-u5A==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4645, '报纸', '一座日本城市坚持61年的反省', '庄庆鸿', '中国青年报', '中国青年报', '中国劳工;', '在日本，有一个城市分外不同。 它叫大馆市，位于日本东部的秋田县。 二战中，这个城市的军警、市民曾经残酷地虐杀过中国劳工。现在，这里的人们坚持祭奠死难的中国人，反省战争罪孽，已经持续61年了。 从28年前开始，大馆市成为日本全国第一个，也是唯一一个坚持', '2013-08-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRnB3kpFfxl-9afuQFHdtZPhz0oIQqrI8dC4VkI8v_Aunn89WWdBYf1QtRHnPN8CjDuDT_OHpy9ALCtq8sQubRCmI_aTFln3EK7VXNUVr6VLkJv38ce1HfRiJ66o9rTiZxtrNSj8CTn0A==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4646, '报纸', '弘扬延安精神 坚定理想信念', '赵克石', '中央军委;总后勤部;', '学习时报', '延安精神;民主集中制;理想信念;', '近段时间，我先后两次踏上延安这片革命圣地，祭奠“4·8”烈士英灵，瞻仰老一辈革命家工作生活旧址，实地学习，接受教育，脑子里一直在思考：那时的延安，环境如此艰苦，物资极度匮乏，为什么会有成千上万的热血青年和仁人志士义无反顾地奔赴延安，为什么我们党能够在延安由', '2013-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT0A9mCRSuxGKHVw4l7kml7pH-uereP2yCarLLgZ7EBtZF6jxqIp_wMihUurgnLbIEugN1tNef75v0i9Lm85u0TCYN9KWFo2mNCSihRtQP2WT-lwKD4Y4smRIWB_YyztKM0aPj_cZCFQA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4648, '报纸', '女勇士', '虞国芳; 王磊', '中国青年报', '中国青年报', '《支那事变画报》;战斗序列;新四军;童子军;李宗仁;县档案馆;女勇士;', '四川安仁古镇的建川博物馆群落，设有专门的“不屈战俘馆”，以纪念抗日战争中的中国战俘。出口处，一个年轻女人的全身照片被放大制成一幅浮雕，背靠着古铜色的墙壁。 被馆长樊建川视作不屈战俘代言人的这位女性，叫成本华。 “成本华是这近百万战俘里边最值得敬佩、', '2013-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSF0SDB_CcNcCmaX0reSw6bO-ek-VgcmgXqtfa3VKFUSNtrKuTA5ej5wR7D2xAy5wePjUrX3VDBL1_AjmBx-xoa6XeDSgGDn-KsyXnsh2wLe_P-OoS8eAUCjs3jVZ3IWTLNfmPGnl_vIQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4649, '报纸', '肝胆相照耀史册 德高品重昭后人', '', '全国政协办公厅;', '人民日报', '宋庆龄;多党合作;爱国统一战线;人民政协;孙中山;中国共产党领导;新三民主义;三大政策;', '宋庆龄同志是中华人民共和国的缔造者之一,也是中国共产党领导的统一战线事业的积极推动者、人民政协事业的杰出领导者。在70年波澜壮阔的革命生涯中，宋庆龄同志满怀爱国热忱，顺应历史进步潮流，坚决拥护和支持中国共产党的领导，全身心投入中国的革命、建设和改革，为国家独', '2013-01-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSS2cHSm-FwD7b1jBF__5P85RzqYptNd2fcz6fCBTLa3dLwCyCbb8mTAqgFZ7m51II2d7eSTO43ytkkYEIfkuekUcKCoWiscv0b5pJP-wFOh2tLd_hinwvaf1rxPNAcohgEol0JOXLgAQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4650, '报纸', '坚强的党性 学习的楷模', '宋清渭', '济南军区;', '解放军报', '黄克诚;人民至上;抗日战争;政治品格;共产党人;优良传统;', '最近，我认真读了由国防大学原副政委谭乃达担任编委会主任，当代中国出版社出版的《黄克诚传》。全书全面、客观、生动地记述了黄克诚艰难而伟大的一生，展现了他的政治军事才能和人格魅力。读黄老的传记，被他的辉煌功绩和崇高精神所感动，引发了我许多思考。特别是他突出的', '2013-01-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTWAaD0yrsZEbnPf_qPyj0ww_CYg6LmaeDyvvOMpAEJ_kkwFh-6Q87lRTgiWWpjyO4PTzJgVWKVjvEv-qQPVYOm4MOvP_0Mj85_MoztYy8TFtJQzBMg9mYUjo-LbvTa3ES1P2aEGcOLzA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4651, '报纸', '《吴子》安国之道的时代启示', '李卫星', '解放军报', '解放军报', '仁义之兵;《吴子》;时代启示;', '开篇的话 《吴子》，又称《吴子兵法》、《吴起兵法》，是中国古代军事名著，为战国时期吴起所著。吴起是中国历史上唯一能与“兵圣”孙武齐名的著名军事家，世称“孙吴”。史书亦多有《吴子》同《孙子兵法》并举齐称的记载，如“藏孙吴之书家有之”、“天子尝欲教之孙吴兵法', '2012-09-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTC_AP2nOnnyFY6FgPtRnvniq2PWfum9CqQUJZ_U1oy83V0WsDn21jjOIf_K_3nTggnzRBr6CNyZ4GPF6cPSnINSZh2Q7-Bcrl101L-QXo1yrjNXEq0Kh7Oh0wRtG6eFdiAJx5kXKrgRA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4652, '报纸', '继承和弘扬《讲话》精神 坚持中国特色社会主义文化发展道路', '刘茜', '中国文化报', '中国文化报', '文学艺术遗产;延安文艺座谈会;《讲话》;文艺工作者;音乐史研究;中国艺术研究院;文艺家;秧歌剧;中国特色社会主义文化发展道路;现代文艺思潮;抗日战争胜利;《讲话》精神;继承和弘扬;《兄妹开荒》;文艺运动;', '为纪念毛泽东同志《在延安文艺座谈会上的讲话》发表70周年，学习贯彻胡锦涛总书记5月23日关于《讲话》的重要指示和李长春同志重要讲话精神，5月28日，中国艺术研究院主办的“纪念《讲话》发表70周年研讨会”在京召开。文化部党组书记、部长蔡武出席会议并作了题为《继承和弘', '2012-06-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTSS0HCt5MT2aW78jnLWXyGpxurMvyVUORdbSHqy_Of8jiah4INV2GGGNDEvduS33zto-SJTmyNCbPACCRVdIRhe6Rm7CIbyBTaaF7nFav6rYw9RTJ5RPfl2f5dX1FdrshzxFW0A45YXg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4653, '报纸', '爱党爱军 开拓奋进 艰苦创业 无私奉献', '', '光明日报', '光明日报', '沂蒙精神;社会主义核心价值体系建设;沂蒙地区;抗日民主根据地;共产党人;无私奉献;中国共产党历史;', '编者按 沂蒙山区是中国共产党领导开创的著名革命根据地之一，也是夺取抗日战争和解放战争全面胜利的重要战略基地。在长期的革命实践中，沂蒙根据地党政军民同心协力、浴血奋战，熔铸和形成了“爱党爱军、开拓奋进、艰苦创业、无私奉献”的沂蒙精神，并随着社会主义', '2012-06-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTD8iAX92_PrcSk9S1YST8BCS3xiYwyuAZ0NSViM54GUEQn5UOCyWcIO8GyMmZRPMSSlosXOr5f9XfzV4uNyzZA_7nRzYSFThqZIY5UmI2SlK-MeR2-LHkMj8iGxSMOE3SI01wh_LI6Kw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4655, '报纸', '坚持以人民为中心的创作导向', '', '人民日报', '人民日报', '创作导向;民众剧团;小资产阶级知识分子;坚持以人民为中心;', '编者按：今年是毛泽东同志《在延安文艺座谈会上的讲话》发表70周年。70年来，作为马克思主义文艺理论和思想的重要文献，《讲话》对我国社会主义文艺实践产生了重要的指导意义，催生了一大批深受人民群众欢迎的文艺作品，为我们留下了宝贵的精神财富。 70年后的今天，党', '2012-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQi5v0a15hhFCzOSa0mipiEjautvrIx51SyJ7RUACkKz16kFRML6Rsaiq2R2Dh25RmyTkhFY2nNtu9dXpJbokpzwXh2TJkq-upDwr1cGekA2de0LMKFbmbaVk1BeAgf9U_SDQLt_hYWXA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4656, '报纸', '仁者寿', '', '中华读书报', '中华读书报', '历史地理学;招待所;中关村;侯仁之;徐霞客;', '今年是侯仁之先生的百年华诞，“人生七十古来稀”，能活到百龄，更是稀之又稀，古代称为“人瑞”。 侯仁之先生生活的这一百年，并不都是在和平安祥的时代中度过的，而是在中华民族几度危亡、频经动荡的年代里。侯仁之先生经历过北洋政府统治时期、国民党政府时期、', '2011-11-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTR8i79qJXt-0Gh11juvapHruqrxsQXU1v49BQES4RXeA31wP2YrMN-XbdHF65Qd_BDmodi49gY8lexYx8BzwMAiRSELlbDEoY7lfwN-gXWfbKzY4TQg49h_xSFUEi40CqQ9pumg8aHpA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4657, '报纸', '人民空军“红色雏鹰”历险记', '谭超; 张力 ; 张军胜', '中国国防报', '中国国防报', '人民空军;盛世才;吕黎平;张治中;滕代远;', '抗日战争爆发后，中国共产党于1938年初至1946年5月，选送一批年轻红军干部到新疆学习航空。这批航空骨干队伍后来被称为我党的“新疆航空队”，成为首批搏击蓝天的“红色雏鹰”。在诞生之初，他们也经历了一番磨难。  11月10日，坐落在新疆乌鲁木齐市幸福路的空军新疆', '2011-11-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRdadwTYCpefXeBmNlfu_Y00f9NnQVGO8h6A2W7otydwJ0w6B5BiWsi0TDY6v2dUqp6lCyAP6NoCrS75zwmIXxQ9mDkBkXhIhZ2P9T9uPawmSqbThqXSTf2G_4kFzGwddr8EM9KbyceNw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4658, '报纸', '在纪念廖汉生同志诞辰100周年座谈会上的讲话', '王兆国', '中共中央政治局;全国人大常委会;', '人民日报', '廖汉生;全国人大常委会;座谈会;', '同志们、朋友们：今天，我们怀着十分崇敬的心情在这里举行座谈会，纪念廖汉生同志诞辰100周年，深切缅怀他为中国人民的解放、社会主义建设和改革开放事业建立的不朽功勋，追思和学习他为国家、为民族、为人民不懈奋斗的崇高品质和始终不渝的革命精神。廖', '2011-11-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSbbH5_iysE9oxOsMi24A4qVqWmtQviTKrfpo7y2c6jxjEw4bSyDUKW8nNb-LpRqXX5dhR9PPSZIG9LjfPlNZt3I310Q-9RY4i_YDUy8aHtB1aegvoYGSXfUXFA8U3-3wMBLh7tme2qDA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4660, '报纸', '朱学范生平事迹研讨会暨民革前辈纪念场馆联谊会成立大会发言（摘登）', '', '团结报', '团结报', '中华全国总工会;中国共产党领导;国民党;研讨会;生平事迹;', '继承和学习他的精神风范 民革中央原副主席 朱培康 父亲朱学范的一生是艰难曲折的一生，也是辉煌的一生。当他走完生命的里程，安详地躺在八宝山公墓的告别室时，身上覆盖着鲜红的中华人民共和国国旗。人们怀着崇敬的心情，在朱学范的名字前加上了“中国共产党的', '2011-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQNFDr2tUFH5EhzVgIUDJSToaJrZFK7ri8ZC6HEgni8JMm3p-VhbaBsKBa6jVD3ZFvyuBtFavRouJlLq5l1aIW-HSCNdd0_rq-5PvmqENPhcoU3DkQgjRgw35B0qzNDtHtljGYDbtlSRA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4661, '报纸', '开掘中华民族伟大历史文化精神', '', '光明日报', '光明日报', '《小站风云》;周振天;小站练兵;中华民族;创作者;博士生导师;《神医喜来乐》;', '编者按  中共中央政治局常委、中央书记处书记、中央党校校长习近平在中央党校2011年秋季学期开学典礼讲话中强调，领导干部不管处在哪个层次和岗位，都应该读点历史。习近平同志还特别强调：鸦片战争以来的中国近现代历史，所经历的困难与风险也世所罕见……只有学习历史，', '2011-09-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR5VgTrMIMSDN3EzXwquVdGFu7xRH7YxVUHOw4M--gO8-04UQAOa-DKjbAL7RI1EOPk3fUlvWfXavU7sGVM8lHoCcidI1JNqxKaUhVGSJXaa02Qd2ziJRPzKUz1H5PK7L33uPV0wHuCWw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4662, '报纸', '女权斗士邓蕙芳', '林志文', '中国妇女报', '中国妇女报', '同盟会;孙中山;夏重民;民主革命;中华民国;', '在近现代历史上有这样一位值得铭刻的女性——她先后参加了辛亥革命和抗日战争，为我国的民主革命和妇女解放事业作出了积极贡献。她就是来自广东东莞市石排镇福隆村的邓蕙芳。 记者近日来到邓蕙芳的故乡——东莞市石排镇福隆村寻访邓蕙芳的故事和足迹。从地方史料记载、', '2011-09-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS1e7_RW_ys18udb_da0CwNLVE3EqNLCpkS8Ntb3S5i15Gje-a3q4-JadSOEKgiiZbhuskvnT7HG6c5Rbxw1xHyEPpwlHdJ5w6QWfq91isEGJwGgsNHCPAgRGpOoq-E9Fds_yfo6okgFQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4663, '报纸', '“笔摇五岳”', '何也', '中国民族报', '中国民族报', '金四把;国家至上;中国万岁剧团;《归去来兮》;抗战文艺;《新蜀报》;谁先到了重庆;张自忠;抗战戏剧;中国回教救国协会;桃李春风;剧作家;', '抗战爆发后，老舍从驾轻就熟的小说领域转向通俗文艺(相声、鼓词等)和对他来说还较陌生的戏剧舞台，自觉自愿地使自己的创作活动服从于民族革命战争的需要。“战争的风暴把拿枪的，正如拿刀的，一起欢迎到战场上来，我也希望把我不象样的诗、不象戏剧的戏剧，如拿着两个鸡蛋而', '2011-09-09 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2011.001371', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4665, '报纸', '功勋永存的红四方面军总医院', '白国志 ; 王砺锋', '健康报', '健康报', '总医院;红四方面军;张琴秋;伤病员;中国工农红军;川陕革命根据地;红军烈士陵园;政治部主任;', '诞生于上世纪30年代鄂豫皖革命根据地的中国工农红军第四方面军总医院，其前身是红四方面军总指挥部医院。1932年冬，红四方面军挺进川北，开始了以通江城为中心的川陕革命根据地创建工作。总医院领导全军医务系统的军政工作，积极救治红军伤员，为保存和壮大红军实力，扩大根', '2011-08-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTvRjiFDlL-LbsjjUasY99ZNXPtpmJUvJ9rxkXPYW8N_pqcEwGIostIH1AQgIisX8YYTV0mCmmhzmKyDIYfF3Q8qbAQYnFIvhjzfvI1VP9sS-AUDoy2Fyj30Kb0QkgYhfo3uw5E8mgWMw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4666, '报纸', '红军精神代代传', '唐湘岳; 徐虹雨; 胡洋', '光明日报', '光明日报', '红军精神;共产党;长征路上;日本鬼子;', '老红军梁庆轩今年91岁。6月20日，在湖南常德家里，梁治成手里拿着爷爷梁庆轩写的回忆录，一边翻看，一边陪老人乐呵呵地看电视剧《幸福像花儿一样》。梁治成幽默地说：“爷爷是我们家快乐的老宝贝。” 投身革命 （1934—1950） 梁庆轩是湘西龙山县', '2011-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQZmXn28UIRYnHwvpOhi7N8CxbV5_h4pFAxPSIko4gRpR52TZOHYWmmRSPCmtbC2aP9A4FT5mKcqUGSY2noSH5U3DJKs5YuvAY3zuGok6Lr09wWRF4ZwMvRIAi4WPFVfLsR4JPSoNzmdQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4667, '报纸', '丰碑', '赵婀娜 ; 陈原 ; 王尧 ; 李舫 ; 常丽芳', '人民日报', '人民日报', '恽代英;毛泽东;黄公略;左权将军;', '恽代英　永远的青年 恽代英（1895—1931），原籍江苏武进，生于湖北武昌，中共党员。中国无产阶级革命家，中国共产党早期青年运动领导人之一。 他的生命，定格在人生最美好的青春年华。 “蒋介石走袁世凯的老路，屠杀爱国青年，献媚帝国主义，较', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQR3VJy8QprYNmf1PMIlU73tneBIngZ1Ir5j4jWluy7rz8Ixk2kBep1GWEclbKbuKJkYCqNlAGxoEGZFAZLaJ8zFp-qb1XejmUOI-dfMdbgx2K9sXQXxK-m7fLjxPQYS_0ujCrMX63BZQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4668, '报纸', '助力中国革命', '李学江 ; 吕鸿 ; 于景浩 ; 王小光 ; 牛瑞飞 ; 王如君 ; 王新萍', '《党建》杂志;', '人民日报', '柯棣华;毛泽东;中国革命;库里申科;红星照耀中国;白求恩;', '诺尔曼·白求恩 ——毛泽东的《纪念白求恩》，让中国人记住了他的名字 白求恩，1890年3月3日生于加拿大安大略省，毕业于多伦多大学医学院。1935年11月加入加拿大共产党，1936年冬志愿去西班牙参加反法西斯斗争。 1938年，白求恩受加拿大共产党和', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRANr98E1QsJalo2UtMkbb3F738tocgkyxxU-ilALqw3bwqQ__VqdybLQsPWPt6J2KHgnqsi8gFCT_vv-XBfDPI0Rf9bp8eqOgOw_i-bkQ2SzDScZqlgvfsHkLDLiJXx_k5Sh27zj0eBA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4669, '报纸', '宜洛煤矿“斗”出一个新矿山', '杨晓东; 王庆林', '中国煤炭报', '中国煤炭报', '地下党组织;', '河南义马煤业集团义洛煤业公司的前身是宜洛煤矿，在这里我们见到了周凤桐老人。他是一名老党员，今年已经90岁了。在他的口中，我们得知了许多地下党组织开展工人斗争的往事。  宜洛煤矿位于宜阳县县城旁边，当时的资本家根本不管工人死活，强迫工人使用陈旧落后的工具', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS0h95ofBwB8N90zqqUeRovGpw5ZU8c1KsgBj4UQKPsFAgmruScj2fIGi8BCe5zI4ugs_r10qSZ5cfmB4yVifpUHLmAIq9XNMWGx1naSzL-nkXjcmf5unuKtMsWyTxZy30YMt-YEDV52A==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4670, '报纸', '加入中国共产党的外国友人', '毛莉 ; 陈璐', '中国文化报', '中国文化报', '加入中国共产党;中西功;马海德;中国共产党党史;少将军衔;中共党员;', '从1921年到2011年，中国共产党走过了90年的风雨历程。在这段充满艰辛又遍布辉煌的历程中，很多外籍人士参与、见证了中国共产党为革命与建设所做的不懈努力和伟大成就。建党90周年之际，让我们回望历史、翻阅记载，撷取几位与我党结下不解之缘的外国人的动人故事。在与中国人', '2011-06-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS2n6BY3yq9-MnE35xXPYsECCVSMk11M43Mqpt9vN848VQkiBBlHzL4yoYMOseXkK295WCHLQPRjiIn9fdINrtU_0TX2MACBtDImoWdQiWInfgv2cNZHafUlrayxPqykgNL9imTHtK6pA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4671, '报纸', '《改造我们的学习》：倡导理论与实践相结合', '朱波', '光明日报', '光明日报', '马克思主义中国化;教条主义;建设学习型党组织;《改造我们的学习》;理论与实践相结合;', '我们党的历史，可以说是一部不断创新的马克思主义中国化的学习史实践史。这就是从《改造我们的学习》到“建设学习型党组织”，既一脉相承又开拓创新的最终落脚点。 中国共产党是一个重视学习，勤于学习和善于学习的党。从1941年延安整风运动时的《改造我们的学习》', '2011-06-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRH1k6uunjJ3Gj_iJIv0WWVL5FQ-yRT73T_4BNUmTK9_HLXglluhcGsxW0ODZrpAOpso9R9dOW-0J1GoJabYcNOs6tG2sAaK5pDCv-AUvSB8FvqxWtkWG6jXYmvGLcnwczuRqFbtnXaXw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (4672, '报纸', '百谷壮乡的红军村', '孙乃会; 黄朝武', '农民日报', '农民日报', '百谷村;农民自卫军;', '广西壮族自治区田东县百谷村，在中国革命史上留下了波澜壮阔、浓墨重彩的一笔。“百色起义”的烈火从这里燃起，邓小平、张云逸等老一辈无产阶级革命家曾到这里进行革命指导，韦拔群、余少杰、韦如山等革命烈士曾在这里宣传革命理论，朱鹤云少将和一批无产阶级革命者曾在这里', '2011-06-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTpMAE_6oij0PEVUDJ5dnyNZRgouHO-npq1VN56WvhOH6HZBvC3o0cxXEFVtf6NwOShLSXZydGDR5heVgOv4FwS8zSeKHOhuabB7-WzScqpdEe4HSN77PyicYMFwWwk15g2a7eFcO3b2A==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4673, '报纸', '延河滚滚浪潮东', '洪黎明', '人民邮电', '人民邮电', '延安市;中央军委三局;无线电台;', '一碗热腾腾的羊肉汤，清亮的油花上反射出沟壑纵横的脸，黑里面透着红。春雨敲打着屋檐，笔者接过老汉手中的塑料瓶，斟满一杯烧酒塞进他的手里，他有些局促地整了整他那身绿得油亮的解放服，唏嘘中，一段70年前的战火硝烟在他的思绪中缓缓流淌。 这是延安，一个名为', '2011-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTKJTYY7J7Z3fFPr9u7kr1qEmGJ8qH_BL0xJi-9VtuZEeXiipjgQX9qOIIBsLcq276jcjMxT4AS0sJ6cQZgV23YMCgxihz_X6HzgFbpZaZnQYxWIEZDtNX6s0TJBSdfoiLO-8dQhqMh9g==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,枣园_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (4674, '报纸', '金达莱盛开在“抗联”路上', '祝连勇 ; 史怀冰; 金星骅', '检察日报', '检察日报', '汪清县;刑事和解;童长荣;长白山;吉林省;', '5月的金达莱花开遍延边大地。5月31日，记者来到了位于长白山脚下嘎呀河畔的吉林省汪清县。昔日，杨靖宇、李兆麟、童长荣等抗联英雄曾经在这片土地上与日寇浴血奋战，丛山密林述说着前辈们反讨伐、袭马队、夺粮草、救百姓等一个个血与火的故事。坐落在南山脚下的吉林省爱国主', '2011-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTBoz7xxpsAXgRSxSwIX17DPfyJ4dFMUQHO4i96DRe4vNznW9ATWSntw9QHdbTBBiI0ovYFv7bNkUGaAMSFdWuksuvqm6-YL0gTgHPFvI4NSXJusBfrGzl95fVuAJ1M0MSq5UyOU4b4uA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4675, '报纸', '新疆航空队：走出14位空军将领', '孙兴维', '解放军报', '解放军报', '吕黎平;盛世才;开国大典;天安门广场;乌鲁木齐;', '这是一段鲜为人知的历史：1937年，空军的摇篮、我党第一支航空队——新疆航空队在迪化（即今天的乌鲁木齐）诞生。 今天，记者走进位于乌鲁木齐市西后街37号的中国工农红军西路军纪念馆采访。“新疆航空队队员参加过开国大典和抗美援朝。全国解放后，人民空军组建第一批', '2011-06-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR05Y-R9OT1lVHzdYH6fOIrdLnNndW87mu_cEBggYNXY1NhkasrqBY8P0LNbiGpA-wI9J21oJwNHSDfZqHEd4xACQqP_AjJIy581kbLBrKRj-JRNtzFxr5AGOIrvIUcukih8rTp3pRv6w==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4676, '报纸', '穿越世纪的风雨携手', '吴小军; 吴晶晶; 崔静', '新华每日电讯', '新华每日电讯', '民主党派;国民党;周恩来;胡厥文;中国共产党;', '新华社北京6月9日电(记者吴小军　吴晶晶　崔静)北京西山脚下的中央档案馆,数十张泛黄的纸页向人们讲述着新中国成立前夕那激动人心的故事—— 在页眉都印着淡黄色政协徽章的纸上,竖排毛笔字签的是那些鼎鼎大名——毛泽东、周恩来等共产党领袖,以及张澜、黄炎培、李济', '2011-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQYryWFLZ7ucGp8PBI9LNlx-v2kbKtV2wtKKxIHcpzpWtm409fgniNZlYiiAHZvHaT6I1b9kd0TXdu2hiHm5OEDQ76-2joQgVeaBMdcNM4CDYaF82wZrlKit1XBLlcvfDrLxY9llgE5MQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4677, '报纸', '港澳：红线相连90载', '王平', '人民日报海外版', '人民日报海外版', '香港海员大罢工;民族精英;民主人士;廖承志;工人运动;战略物资;', '翻开1921年中国共产党建党后的港澳史，我们发现，似有一条看不见的红线，将港澳的命运与祖国紧紧相系，哪怕身遭掳掠，不论和平战时。 中国弱，港澳同受欺凌，中国强，港澳同蒙其利。每一个历史时期，从中共建党初期、抗日战争、解放战争到新中国成立再到改革开放，', '2011-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSIIvhhbqANtb4PcTRx06XCFtVduXBKOV5_ZtsgjR20awFwRG7IqsclGqpSfL5COu7bXFpXfYwaDJcsyv41hXraLPLWPQ6pqvFkyTnES8nlFGe6ryPRX25yu9y1BqlnxlV0kN1je3O0NA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4678, '报纸', '85岁老人回忆打捞中山舰', '叶晓楠', '人民日报海外版', '人民日报海外版', '中山舰;整体打捞;孙中山;金口镇;民革党员;熊秉坤;湖北省;', '1997年1月28日上午10时，湖北金口大军山江面冬云低垂，寒风凛冽，海内外各界近万人面对波涛迎风肃立。这是一个庄严而凝重的历史时刻，在抗日战争中被日本飞机炸沉的中山舰将被打捞出水，重见天日。 一代名舰中山舰的打捞出水，与民革中央、民革湖北省委会以及许多民', '2011-06-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTWvm0AYSfJ4lCIbRfZXOhnhnjsSPs2fK9TC2bQKrfZOIWWB2b2Kmw6kox6LYO_Ons6FBet4PA_rUuakpybUqHj8aj20FZWHZSxEHkpJPU6V0PQXCFP2WEo9-rJDHuGd0Kb71NKHRVjKg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4679, '报纸', '纪念张学良将军诞辰110周年座谈会在全国政协礼堂召开', '', '人民政协报', '人民政协报', '张学良将军;爱国将领;于凤至;全国政协礼堂;座谈会;', '为了纪念我国历史上杰出的爱国将领、民族英雄张学良将军毕生追求国家统一和民族振兴精神，深切缅怀先辈的丰功伟绩，增强民族自信心和自豪感，加强两岸交流合作，推动两岸关系和平发展，促进祖国和平统一。由张学良基金会主办的张学良诞辰110周年座谈会暨学术研讨会于2011年5', '2011-06-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQz5g6BQxLtCvu15mdvXhP-_DeF-p6zmoW0sf0BbJCQ5b2W6Nv8gsrweA1igOoyjW86p8YfGXCHniMNW9khcJ_wVvm2Lsf1DIUoxtkygYHRRTWC_lKgT1xUtCfCYemQrtBQIPG6eWg0mw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4680, '报纸', '颂歌一曲动九州', '陈建强', '光明日报', '光明日报', '曹火星;霸王鞭;堂上村;群众剧社;铁血剧社;霞云岭乡;共产党;晋察冀边区;平山县;抗日根据地;', '有这样一支歌，它的音符从太行山里飞出，越过崇山峻岭、平原大川，在华夏大地不绝回响…… “没有共产党就没有新中国，没有共产党就没有新中国。共产党辛劳为民族，共产党他一心救中国……”1943年10月，年方19岁的曹火星在北京房山区霞云岭乡堂上村创作了这首《没', '2011-06-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQam2MEBwaWF18kZ9zXuy8uUa3V5kkpol2W4U_TuxSkqSe-pbZ2cDXaZ3QHTFdJ0rM5rrPK1bHpJdjHyI3_rOHoY6P34QmTf-glOVAUC2aGzeSSZseOBodb12MPTkrgLWyYAHdN56-gQQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4681, '报纸', '今日韶山红胜火', '张天南 ; 王雁翔 ; 王希明', '解放军报', '解放军报', '中共韶山特别支部;韶山毛泽东同志纪念馆;', '毛泽东创建我党最早的农村党支部 春夏之交的韶山，微风清爽，遍地花香。清晨，毛泽东同志故居前的南岸塘四周小路上就排起了长长的队伍，山路上驶向这小山村的车队一眼望不到头。记者一行沿着麻石小路，走进这个叫上屋场的地方。 接踵而至的人们，并非人人都熟悉86', '2011-06-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTn7Pa6HQwAAoY7VAvLUX4zzvvUafH3jr6qUlM1MDAJuVl0QB9bPHpdbYTJxnP7JwMXu5b9AboNWODGzTufRV79fsVg8utgN2PZCBOPKI2IQwmbFUQHRJ2ErTn5aP6WXe4yPBOqcQcyMA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4682, '报纸', '东江纵队抗日谍战风云录', '宾阳; 毕中林', '中国文化报', '中国文化报', '东江纵队;情报合作;八路军驻香港办事处;抗日游击队;启德机场;军事情报;美军观察组;情报工作;', '广东人民抗日游击队东江纵队是抗日战争时期，由中国共产党领导的在华南敌后建立的一支人民抗日武装队伍。在长达8年之久艰苦曲折的抗日斗争中，东江纵队在曾生、林平、王作尧、杨康华等领导的指挥下，积极配合全国各地抗日战场和盟军，英勇地打击敌人，成为蜚声中外的华南抗日', '2011-05-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQkmseJaD-XK0Zy5FhUQPd3Dh2fUa_BAT7dtm5VtOukm1LgyttxrBT2SZnKUKrMqzC6MQlMjtwsLg2TRtNczlPIhbDyq4_YNQKteUbeSPO1MGWer_BUGzCxpGlpvrx705_zIm76RREzXg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4683, '报纸', '永不褪色的记忆', '张旭; 殷丽娟', '新华社;', '新华每日电讯', '月坛街道;晋察冀边区;战斗英雄;', '“上刺刀,把手榴弹弦拉出来!”说到打鬼子的战斗经历,90岁的老党员闫占江时而面色凝重,时而眉开眼笑。 听老人讲故事的是一群“90后”大学生。讲到紧张处,大家凝神屏气,讲到胜利时,掌声四起。 在迎接中国共产党成立90周年之际,北京月坛街道的90位老共产党员', '2011-05-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSJMmJI2INELQHCSwoKyN-Q1SNan_aIzemG64uQe11uA6f4exioSzWHmNdnYJBRkRi9gRlCyoeL3LENPSqglO1z1EUWcmjxM7W8l8pSXFj_vaFryf87_7se2z5tAOWPa46TZeQARESEBw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4684, '报纸', '李德生同志生平', '', '人民日报', '人民日报', '李德生;晋冀鲁豫军区;“九一三”事件;川陕革命根据地;上甘岭战役;中共中央顾问委员会;中央政治局常委;叶剑英;郭兴福教学法;中央委员会;黄维兵团;', '中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家、军事家，我党我军卓越的领导人，中国共产党第十届中央政治局常委、中央委员会副主席，原中共中央顾问委员会常务委员，中央军委原委员，总政治部原主任，北京军区原司令员，沈阳军区原司令员，国防大学', '2011-05-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR9kDGzYUztM_mEItplerY3HeArN3j8fnZ0SgX4mIXCxgVSwc6f-t9mWOqk0qmwU6GC0K4FUMbm-KyYUtpKQlKowC5CmwISM_pUJ6zosGo0DGbts92z7sU1GwACck-g8v-PgiJYLcxOCg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4685, '报纸', '驻印远征战士撒世良的坎坷人生', '宾阳', '中国文化报', '中国文化报', '国民党军队;', '普通人的一生总随着民族的命运而起伏。20世纪的中国史可谓波澜壮阔。中国人民争取独立与自由的过程，实际上也是以个体的付出甚至牺牲来保全民族利益的过程。时光飞逝，数十年过后，当我们重新提及那些人、那些事，该是带着一份肃穆和沉思。例如，面对那些曾经驻印远征抗日的', '2011-05-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRxNiNW7nQV6_eRSrpLk1DhXjLJEmgbprdzXV8idDKaizsojc8eujY88ICq12VTcKhYMdqsQ0axiiSbutqp87s8QamUyY7KrAi7Ol6svjBj3UYTKk_8iKC7Q5d13uiHvlwGJRH3aAiNwA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4686, '报纸', '增进同胞骨肉亲情', '高杨', '人民政协报', '人民政协报', '周铁农;', '以“缅怀历史、纪念英烈、放眼未来”为主题的电视剧《中国远征军》海峡两岸座谈会，4月28日在北京卢沟桥畔的中国人民抗日战争纪念馆举行。民革中央主席周铁农、海峡两岸关系协会副会长王在希以及两岸的专家、学者、远征军将领的后代等100多人出席。 电视剧《中国远', '2011-04-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRVfVwg2Of86SNcK5LY4r46CjSWtHWi3aTMzJFNpHvX78XFn1widIxnxXysKoVyrzLkL2spafeV-EBmk6EJjSbMcJKfG9uJ6tXRsU05jlxlg8ye53dNXB3zirdRzxyUmhoYQiyzSZxZSA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4687, '报纸', '水木清华 人文日新', '赵婀娜', '人民日报', '人民日报', '水木清华;清华大学;世界一流大学;“两弹一星”;泱泱大风;综合性大学;厚德载物;', '一世纪沧桑砥砺，一百年春华秋实。 在清华大学即将迎来百年华诞之际，4月20日，胡锦涛总书记来到清华园，对清华大学未来的发展提出殷切希望，为百年学府朝着更高目标迈进增添强大动力。 百年风雨，百年征程。从诞生于中华民族灾难深重之年代的留美预备学校', '2011-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQz9S0OD7j-_-UL7gUPtlc3fGH2h-m28iRZr5mI68bptOgVBzzgbkdLjJrjI_tO6yzbYNQali7k9QsKkpBM6E15zno2xXUG_ZP-hty4PYVSXK_gsITBpd5yAmwxeQAXZyc5FmP0Qh5LqA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4688, '报纸', '钱壮飞', '余靖静', '新华社;', '人民日报', '钱壮飞;徐恩曾;国民党;李克农;中央特科;顾顺章;', '新华社北京４月１１日电 周恩来曾多次满怀深情地提起这样一个名字：钱壮飞。他说，要不是钱壮飞同志，我们这些人都会死在国民党反动派手里。钱壮飞同志在对敌斗争中立下的丰功伟绩，的确使我们的党少走了弯路，全党将永远纪念他。钱壮飞作为党的重要情报工作人员，为保卫在', '2011-04-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS0VaiOmNf-XxyUOagJJoJEcuMASxQZdVTK_CqIaxeS5pUAjrTV_Wze1rQ7y6RPYmM6vfDAnDgi-yiPycDv4RQNuLhp88PPQ7C9bx3IJrpZ2ASYhlC4dWZ9X3reULsGvwDv8r7LOR6CCw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (4689, '报纸', '河北农民建陵园,给抗日英灵“安家”', '范世辉; 白明山', '新华每日电讯', '新华每日电讯', '烈士陵园;纪念碑;日本鬼子;', '新华社石家庄4月5日专电(记者范世辉　白明山)这是一座特殊的“烈士陵园”。它坐落在乡村附近的田地里,没有围墙,只有尚未成才的小树静静地环绕。 清明节到了,在河北海兴县张皮村的“烈士陵园”,不少村民自发来扫墓、祭奠。村民们介绍,这个陵园是村民巴连甲倡导,在村', '2011-04-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRVAfu4aDY5hn2STPGnajtF0GBzlak7qqGw8uQzTKJDMMr3g1btpRvIHrHfYyQ5cpsblMcduMdtLncTygc-OCB3GjGDUM0-LWKd3I9XXny7taYv9yieArM12QOkSZS3pKyAtljR_nuy4w==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4690, '报纸', '三晋春来早 教育竞芳菲', '余冠仕', '中国教育报', '中国教育报', '校舍安全工程;幼儿园;刘延东;校安工程;中小学校舍;左权县;春来早;', '阳春三月，暖风拂面，三晋大地初见新绿，每个角落都传递着春的讯息。 3月20日至22日，中共中央政治局委员、国务委员刘延东来到山西太原、左权、阳曲、忻州等地，深入各地中小学校、幼儿园，考察调研革命传统教育、农村教育和中小学校舍安全工程建设等情况，看望慰问广大', '2011-03-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRosi9V5ZnXp95pazbB1hMTuTGJOxn8lAUZsLMMDN4Ezhshul-LShTThm3uG6IEewzWg7Zq6eEXduxyeYKk6ZXaTBqBYpwCZ9P8Kn4_ujKidqzkpTg4kGIKj3oyJM8tvXquvTzMJp8-ow==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4691, '报纸', '彭儒:永不凋谢的红杜鹃', '沈俊峰', '中国纪检监察报', '中国纪检监察报', '中央纪委;吴仲廉;陈正人;井冈山时期;', '特别报道  2010年10月5日，井冈山革命时期最后一位老红军、中央纪委原专职委员彭儒同志辞世，享年98岁。彭儒生前嘱其子女将其积蓄的5万元人民币交给党组织，作为自己的最后一次党费。中共中央政治局常委、中央纪委书记贺国强对此作出了重要批示，要求广大纪检监察组', '2011-03-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSUZqphGZUH6hnymUo0qCO3aQxBc_OKLWHROuCp0EUEwartm4_U0XYcr2z7aDEUXh3UVjGpVnoHODbpEEIysfal3fbQjLrIcLIYIbdxvUYaXRAyJMAw7Xowt6iCKLuShVZy5S5XuHpecQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,红四军_screened,瑞金_screened,王佐_screened,朱毛会师_screened');
INSERT INTO `ds_article` VALUES (4692, '报纸', '生的伟大 死的光荣 刘胡兰', '', '人民日报', '人民日报', '刘胡兰;云周西村;阎锡山;', '据新华社北京３月２７日电 刘胡兰，1932年出生在山西文水县云周西村一个贫苦农民家庭，小小年纪，便对黑暗的旧社会产生了强烈的不满。全国抗战爆发后，中国共产党领导山西人民开展救亡运动，文水县成立了抗日民主政府。从此，刘胡兰开始逐步接触革命道理。 在党的', '2011-03-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTdKBrpox6rkLSNRX6WZQp2-55bxS1a2fbXE1Ls66M_wWFjVPqIJiAfL42oSYPZp4BR0X6H0HBAAbjsQCy37upIbgAQS6F0t0Lc4GXG_-RQwcw06u9UruLorfHFqg9rtS47g6xlMulKaA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4693, '报纸', '抗日民族英雄杨靖宇', '', '人民日报', '人民日报', '杨靖宇;民族英雄;东北抗日联军;', '新华社北京２月２２日电 今年２月２３日是抗日民族英雄杨靖宇壮烈牺牲７１周年纪念日。 杨靖宇，原名马尚德，１９０５年２月出生于河南省确山县李湾村一个农民家庭。１９２３年考入开封纺织工业学校。在学校期间，受到中国共产党和共产主义青年团组织的培养教育，阅读进', '2011-02-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQlz1Qj3YwwzxS4Z4iuPMuPtfTYClXCEleKbLtFqAsTEOe6CZv4nBWfjN3qMXgFodpn1b9u3RWoXtCHmslG4VA8-0-3PtxSaFDW8JJO_eCup6Aw2zmuOnizCcvjG8EUmJrkoIT1toZkvA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4695, '报纸', '纪念汪锋同志诞辰100周年座谈会发言摘编', '', '人民日报', '人民日报', '统战工作;社会主义建设规律;杨虎城;座谈会;', '在纪念汪锋同志诞辰100周年座谈会上的讲话 全国政协副主席、中央统战部部长 杜青林 今天，我们怀着崇敬的心情在这里举行座谈会，纪念汪锋同志诞辰100周年，缅怀他的光辉业绩和杰出贡献，学习他的革命精神和崇高风范。 汪锋同志是中国共产党的优秀', '2010-12-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQHGqlaYWcD0QE6n07URwvfCfESj2cW7X2aIf2WJxhOK7V_U0Yl0ePrifefXYsywkxO7-vXyXzAuvntJXDS5y_fXzMwiwqQfqh1Uf990pa92VyQpq6BCsFvoM3cVvs0P2p_gRTH4uEPcw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4696, '报纸', '在纪念刘澜涛同志诞辰100周年座谈会上的讲话', '', '人民日报', '人民日报', '刘澜涛;人民政协理论;爱国统一战线;座谈会;', '中共中央政治局委员、全国政协副主席　王　刚 今天，我们怀着十分崇敬的心情在这里举行座谈会，纪念刘澜涛同志诞辰100周年，缅怀他为党和人民建立的卓著功勋，学习他的革命精神和崇高风范。借此机会，我们诚挚表达对刘澜涛同志的深切怀念，并向刘澜涛同志亲属表示亲切的', '2010-11-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQCe-kh7tohh-63i-e6UG8vdVBuCxzpRyqEZr-3QFnToJghrbiEN2aZsHxhZAJWnRaYrh1SJOdi5zpzbnb2uRgeasCGrqOuIO847rLodI-yW3OOsghMBcclpTPmzEr3chqasd2rDCsfQA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4697, '报纸', '千磨万击还坚劲 一片冰心在玉壶', '丁晓璐 ; 李科', '人民公安报', '人民公安报', '公安机关;整体作战能力;鲁中军区;浙江省公安厅;第七兵团;保卫部;', '抗日战争中，他曾是艺高人胆大、经常单枪匹马深入虎穴、斗顽敌于谈笑间，令驻山东侵华日寇闻风丧胆又咬牙切齿的八路军“小白龙”，日军曾专门制定“生擒小白龙计划”，悬赏5000大洋要捉拿他……  曾有人将他誉为“活着的李向阳”，实际上不只是《平原游击队》中的李', '2010-11-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTDti55VpneND-ls1DcKBl0YOJFLUfSM8ydG1_8etTss91hwx9XZlpPZqGotHC0gju2xluWHtCFA3KB38_Wkx_mMr0FwEe37tnE_-GTUPUaCGtnde3KgA4Qh8iHe1R04wYMzdTsNK6oZQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4698, '报纸', '“这段血和泪的历史不应该被淡忘”', '牛锐', '中国民族报', '中国民族报', '台湾光复;台湾少数民族;太鲁阁;日本殖民者;', '在中国抗日战争胜利65周年、台湾光复65周年及雾社起义80周年之际，由全国台联、北京市台联和“台湾原住民出版社”举办的台湾少数民族抗日史实图片展于10月25日（台湾光复纪念日）至11月4日在北京台湾会馆举办。展览通过27个单元、约500张历史图片及两万余字的简介，真实地再', '2010-11-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRNeirCM6lPaQT2w2lOCNLpNxWL9-sAhG9DDwpGEstCwRKSEZMCtLhSHG1wbUOwsoxbnp83l8bRCvSHYbwpgL2NaNIcFz1z-luRfnWYcHhUvw1bnRqjyi132BV6q163fzn4WgqYifNBAQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4699, '报纸', '我们为什么纪念台湾光复', '王平', '人民日报海外版', '人民日报海外版', '台湾光复;', '“张灯结彩喜洋洋，胜利的歌儿大家唱，唱遍城市和村庄，台湾光复不能忘……”10月25日在京举行的“纪念台湾光复65周年学术研讨会”上，来自台湾元培科技大学的女教授孙若怡用这样一段歌声作为演讲开场。 歌名叫做《台湾光复纪念歌》，孙若怡说，她这个年纪的朋友，', '2010-10-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRNLczE-Qa6DZlGGe1lAs6adX2pTM8ZKJ9YnkTSaBUjgxUDl6z3TBHBu629r4lY_ARID3YlF_mQhiipKS2OdwjuP-3C1XWc6DuiVvcwdI1w3fgqWa0VdyRxK-d6_8PAcu9wM4qD3779vw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4700, '报纸', '马海德与宋庆龄：半个世纪的友谊', '王亚丽 ; 杨晓静', '光明日报', '光明日报', '马海德;宋庆龄;医疗卫生事业;', '他与埃德加·斯诺并肩走进延安，但《红星照耀中国》里隐去了他的名字； 他鲜为公众所知，但他对中国医疗事业的贡献却不亚于诺尔曼·白求恩； 他出生于美国，但他将毕生献给了中国人民的革命和建设事业； 他被宋庆龄称为一团火，温暖了数十万的麻', '2010-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSyPC7UNziT205OLC9jRcrwS049FVhABCiqzpZ1kxWf90gBTru5ynFzuygCcOpb3OJ7byxQHBmfuzx-M1wWT8QHAedrxrNXtAJtugvxqV0zDc2b-PN7QjIQzRH2bD-pQdlqLb1imJh6cA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4701, '报纸', '美国飞虎老兵感恩来华 “龙腾虎跃”行动再续新篇', '', '中国文化报', '中国文化报', '华夏文化纽带工程;湖北省;飞虎队;埃莉诺;中国人民对外友好协会;李先念;监利县;新四军第五师;陈列工作;', '近日，1944年所驾驶战机被侵华日军击中后跳伞、被湖北省监利县人民营救、后又受到李先念将军的亲自关心照料、伤愈后归队、现已86岁的美国老飞虎队员格伦·本尼达先生率他的家人和亲属重访中国，感谢中国人民，特别是感谢李先念将军当年的关心；同时，也了解“龙腾虎跃”行动', '2010-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT9rqFRoxielRwBDkHt0OmGn-zRpUmxZ5Ii2XvPXzoRyC1ib_sQAh8k0S10ICzTvWJbVSeshQ0pE-ldcV9wJ6Pc7gdniI5nYZrchRcAgqDtdFssQJUGuW1pPNnTgNltEGH2_ww3hOfKuA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4702, '报纸', '流亡女生的教育记忆', '曹庞沛', '中国教育报', '中国教育报', '唐山交大;抗日救亡;平越县;', '抗战硝烟中，他们行行复行行，辗转流亡，在烽火中的一方教育圣土上坚守中国教育和学术研究的阵地。在纪念抗日战争胜利65周年之际，我们借有“中国第一流亡女生”之称的王德懿老人的亲历故事，回忆那个国难当头、壮志凌云的年代，品味那些可歌可泣的校园往事，铭记那些呵护并', '2010-10-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQO4-iaTLGxYP1jzZ-rS4jo39YpiuvIbs79AtMguDz_tcvP-FhCweI4M51SoGeYW-SB1OL_Q-j2FppPamfidSZmVtNwazgCz9ePFGdA4HzjRILc3AUNL1Nu0SFP7iaS9AqB4ximkjgblQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4703, '报纸', '创新人才不能在一个模子中塑造', '张宁锐', '人民政协报', '人民政协报', '徐特立教育思想;研讨会;北京理工大学;科学院;创新人才;', '“延安自然科学院，可能是我们‘科教兴国’战略思想的最早发源地之一。”上世纪40年代，在革命圣地延安，由徐特立担任院长的延安自然科学院，开创了中国共产党培养科技人才的先河。在9月25上午召开的徐特立教育思想研讨会上，中国工程院院士、北京理工大学原校长王越接受本报', '2010-09-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRzgqMK6teUzKqX87MY62j0LGjji2Je2xdMBi87kTkJmkHRNUc9rgjd0wyOn7TMIjLig4Qr51FRtH2TfVBIPn3HJcZ-AF6_-AfmwVpYmYqiiivINhymAhb6GaSXvbX0keMUUu6Z5HZFyg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4704, '报纸', '李力：战火中的通信专家', '罗凯', '人民邮电', '人民邮电', '八路军办事处;有线通信网;国民党军队;李力一;', '李力简介 李力，原名李潜修，1924年8月19日出生于安徽省芜湖市，1938年4月到延安参加革命，同年6月加入中国共产党。在延安，他先在抗日军政大学第四期学习，后入军委通信学校第十三期学习无线电，毕业后，担任军委通信学校教员和军委三局电台报务员。1940年5月，受党组', '2010-09-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTyKTF5KW1HdomXsVOUm4ip_lmC3WMHMSwnagakbpOaRbQ5HX2VltSP3M_y2EZSB1ADgBmbk3DEfKBTRXTnfZioBXDdxS95n4WO5CCw0GjRMQNA1yHEwUqduAQuHpmLRE7SzBjo4Qmmvw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,杨家岭_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4705, '报纸', '薪火传承谱新篇', '王娇萍', '工人日报', '工人日报', '工会干部;王兆国;企业工会工作;', '初秋时节，天高气爽、云淡风轻，三秦大地处处洋溢着收获的喜悦。 9月8日至12日，中共中央政治局委员、全国人大常委会副委员长、中华全国总工会主席王兆国到陕西考察、调研。几天时间里，他先后来到西安、延安等地，深入工厂企业、走访高新技术园区和工会帮扶中心，看望', '2010-09-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT9yDJkcDIUvSOl9G6dZhJ8-v-VJnGVoLu63arOAEqC5wS4haRnpx3ac04uIfCpq6hojKhElrU-yT8bl0K0bJzPVHZorWqftgz0fG0dQ1WDzqzrySkvkPIF8KrqghTZqzhR3qhukdEGng==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,枣园_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (4706, '报纸', '侦察事业的开山人 通信事业的奠基人', '罗凯', '人民邮电', '人民邮电', '吴人鉴;国民党;奠基人;红一方面军;', '刘寅生平 刘寅，1910年出生于江西安义。1930年参加红军，1931年1月参加了我军第一部电台的组建工作，1936年加入中国共产党，参加了举世闻名的二万五千里长征。在红军时期，任红一方面军总部电台报务主任，中央政府电台主任。积极参加创建我军通信事业，精心培养无线电通', '2010-09-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTpmJOsY9-kQi96cKZ1-_vLSIXK3wZwrN2k08RIZUKyjMxjVgbi2aZRvT4MLwVxMm_O56x68zccNOwUKAiW4ajfBohoXNqf2haitn1_gUhV3ytDIV64h0gA1J7KOAznVtOlbxkwTTWdPQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,瑞金_screened,项英');
INSERT INTO `ds_article` VALUES (4707, '报纸', '铭记历史 珍爱和平', '周之然 ; 刘刚 ; 张光政 ; 席来旺; 吴云; 顾玉清 ; 刘华新 ; 李景卫 ; 孙广勇 ; 李潇 ; 李学江 ; 李文政', '人民日报', '人民日报', '中国人民抗日战争;电影招待会;世界反法西斯战争;铭记历史;', '本报北京9月4日电 综合本报驻外记者报道：9月3日是中国人民抗日战争胜利暨世界反法西斯战争胜利65周年纪念日。近日，中国驻外使领馆纷纷举行纪念活动。 中国驻朝鲜使馆3日举行招待会，庆祝中国人民抗日战争胜利暨世界反法西斯战争胜利65周年。中国驻朝鲜大使刘洪才', '2010-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQPD9-0bWjwuSOZHUFyAZSFSmhPpPhNMJqgOX5jD6UFRS23FYRKgO0MEA8EjcAQy1N7x9JE3R7ck332nIIJA1A-0F1V7W-z8isP5UGr6ke8rDftYHbmNmumxyoAD-1cSLEwZsROl0aO_Q==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4708, '报纸', '教育部隆重纪念中国人民抗日战争胜利六十五周年', '张晨', '中国教育报', '中国教育报', '中国人民抗日战争;教育部;继承和发扬;', '本报北京9月3日讯（记者 张晨）今天是中国人民抗日战争暨世界反法西斯战争胜利65周年纪念日，教育部机关在京召开纪念中国人民抗日战争胜利65周年座谈会，隆重纪念这一伟大胜利。教育部党组向部机关参加过抗日战争的老战士、老同志发出慰问信，教育部党组成员、副部长、直属机', '2010-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQg_6X0ngghfEdVfKOhRqATrhaY5TtfuKQDg9BSwtViv8Ey7vMCVy6GAKHbaoB3qo7msuDBjnRo2BnH0HOl1xrBFu-6MBYlrl6WhW_ImW4VmZITtFOrgCXmRH-LN9tLiOJxKCmjDnd37A==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4709, '报纸', '以史为鉴 面向未来', '于青; 崔寅', '人民日报', '人民日报', '以史为鉴;留学生;日中协会;中国人民抗日战争;面向未来;', '今年是中国人民抗日战争胜利６５周年，也是世界反法西斯战争胜利６５周年。9月1日，中国驻日本大使馆在东京举行纪念中国人民抗日战争胜利65周年座谈会，旅日学者、华侨华人、台胞、留学生代表，以及日本反战人士、友好人士等齐聚一堂，回顾历史，缅怀先烈，共叙友谊、和平与', '2010-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTeka4e-o_LjCmK4vyaOe4HSyiSJJfBGnrXgQYsZVAoaxvmVeCN3Ddmr_co_xVPftq67kjhIpSZRplVRdeFyub076Xp6bgeDse4waXiAzTg0MW7dBN0EfgCc_KKaeZZq2jdEqaHlkIeEg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4710, '报纸', '气壮山河的历史 穿越时空的昭示', '李斌 ; 杨维汉 ; 邹伟 ; 黄小希 ; 苑坚 ; 朱峰 ; 陈文广 ; 罗争光 ; 伍晓阳 ; 魏飚; 贾楠', '新华社;', '新华每日电讯', '中国人民抗日战争纪念馆;中华民族;侵华日军南京大屠杀遇难同胞纪念馆;四行仓库;穿越时空;', '抗日战争是持久战，最后胜利是中国的——这就是我们的结论。  ——毛泽东《论持久战》  “那天晚上，我被密集的枪声惊醒。”  卢沟桥边，永定河畔。年近八旬的村民郭忠福放起了荷花灯。65年前“七七事变”的那一幕，老人记忆犹新……  恰逢八月', '2010-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRvrF3jsN6Ggz9gFXS4p_k38MQVzyRKL8rUX0R_44lFCACi55L4NtRcOkBSVhDv8fN3p8OqTRX-i-5Yc1TCrXPmoYcvLTog1TNwnHdrIMjr7kRO3Vs9DxTKyRJ39vCvt10QvWYljUewIQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4711, '报纸', '通信英雄王子纲', '罗凯', '人民邮电', '人民邮电', '王子纲;党中央;张国焘;中央红军;中央军委三局;张沈川;', '王子纲生平 王子纲，1909年出生于河北定县，1929年加入中国共产党。土地革命战争、抗日战争和解放战争期间，他先后担任军委分会参谋部电信处秘书长兼无线电训练班教员、红四方面军电台台长、红四方面军总部电台台长、中央军委三局一科科长、军委三局120分队队长、留守兵', '2010-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQU0K6v8LsVIljbGZ-e4LaOjT9a1E2UUZYvYc_WkmBSszGr4zZi4COrqvye_MPK2zA9rUgt5hZgJgDm9dq9qJrNqvmcZi-MGznJTMyVfrlfCva3fcYAzlYaGErRZhdwPcrLKxEXG34kUA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,遵义会议_screened,会宁_screened,土地革命战争_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (4712, '报纸', '抗日战争得道多助,曾有“日本八路”', '朱峰 ; 李亚楠; 骆珺', '新华每日电讯', '新华每日电讯', '抗日战争;反战同盟;新四军;八路军;', '新华社石家庄8月31日电(记者朱峰、李亚楠、骆珺)当日本侵略军踏入中国土地时，一些同样来自日本的人士公开反对他们的侵略行为。河北省委党史研究室研究人员2004年起系统研究抗战时期在华日本人反战活动。他们走访上百名当年亲历者和知情者，留下数十万字笔录及大量音像资料。', '2010-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRGSyFaWRKzAy7-V3Vf8y4zWDrpmnFkSN54x1tu5R3F4z-nykL5ADzmqx7G-EDNwFiGMUbHxVSnSDpWgTmUWLdqv_kRSJOcRlpF6hAJjPrmps60Vo-XGzYH4LluvKJRbu0kDw5X2y3-zA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4713, '报纸', '在更广阔背景下揭示抗日战争', '吴娜', '光明日报', '光明日报', '抗日战争;军事小说;抗战文献;', '对每一个热爱和平的人而言,抗战胜利65周年绝对是一个值得纪念的重要日子。为了迎接它的到来,出版界的众多有识之士以高度的社会责任感和积蓄已久的激情,向广大读者奉献了一大批全方位、多角度记录抗战历史和反映抗战生活的优质图书。  抗战史料的全景式记录 ', '2010-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRwRFXr83Ca50dvBqkuPH69SppfJlbLXSXIpleGceV43iASHFO2epBqVLSZ1Nhrv6jLuwhZmK-l9a1vwO0FmBM_4eTjX0IFXB6sSjivuJWQcEDwu7F7hdkwAyeC1VQjHwW1Ou5EU5hxBw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4714, '报纸', '通信业的先驱 共和国的功臣', '罗凯', '人民邮电', '人民邮电', '红四方面军;中央军委三局;无线电分队;共和国;', '编者按：日前，被誉为“通信工作的开山鼻祖”——中央军委三局旧址修复落成暨陈列馆开馆仪式在陕西延安裴庄隆重举行。中央军委三局不仅是我党通信事业的根源和基石，同时还为邮电事业、电子工业、广播事业、气象事业、航天事业等领域的发展培育了人才，奠定了基础。为追忆红', '2010-09-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTV7DFpytV1Qg5DLuK67q6GEnIMnysgCwMIx1NYfdIhbgEzRto0eFSnNBIHVk6VV2PROcqLWvg1gn092X2ATi9pky0xn8k9PqUTCIjRG1UkI3wtlV2sB5cLuvdcqCkEKxLGoxoWzf6Stw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (4715, '报纸', '普希金和苏联援华航空队的故事', '李学勇', '解放军报', '解放军报', '库里申科;普希金;飞虎队;飞行员;空军中将;陈纳德;', '说到抗战，人们常常说起陈纳德率领的“飞虎队”，其实在美国“飞虎队”之前，苏联的援华志愿航空队就同中国空军并肩抗日，击落炸毁敌机近200架，炸沉炸毁敌舰船14艘，并有236名飞行员长眠在中国大地 寻访飞行员普希金 在纪念中国人民抗日战争胜利65周年之际，一篇', '2010-08-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQNsH5kdnMsBRZsC7BUw4UoeqeocyMQi4ot5mxyP06xTf7aJbRjIN_c_ulld_gNb17QGm0iJJOaU6dycmGykZ25beh0sQIVUSIUKtIleteqlICihULpW4rrZVojGPbA6f6lmiwxA-kLpA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4716, '报纸', '缅怀抗日将士英魂共期两岸和平发展', '杜军玲', '人民政协报', '人民政协报', '《喋血孤城》;国民党;两岸和平发展;常德会战;', '1943年，湖南常德，这个被认为是桃花源的地方，发生了一场抗战史上最惨烈的守城战。代号“虎贲”的国民党第74军57师，在师长、黄埔一期生余程万的率领下，以八千将士之力，对决日军四万精锐之师的大举进攻，苦战十余日，最终拼到只剩80余人。8月13日，中国电影博物馆，当包括', '2010-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSocfX2Wx51WTpLJcXatMohMe7N2zWV9NjZdW8w_qUkAPouqPHqwnhYhaHO7QUO-BxAslUwOiLaOS7OwTn5UOTK9bHLpwCwpjeL2kRT0V6oJqR42b2f6mAEgbLyvuFLWQDlrC7_u2orfw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4717, '报纸', '65年前,他们见证胜利', '刘琼瑶; 许晓青', '人民日报海外版', '人民日报海外版', '日本鬼子;新四军;', '总有一些时刻，让人们永远铭记。 著名电影表演艺术家秦怡，８９岁；新四军老战士王志昂，８４岁；上海老太太应文选，８８岁。他们苍颜白发，垂垂老矣，但一说起６５年前的８月１５日，他们依然控制不住自己的激动心情——那时，他们青春年少，他们见证了祖国的伟大', '2010-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSui12NHq3ftNQlDDLkeuDW-WRc0bSiBt8vtgobru-Cb_6RNR3-jPRzW20scLeJv_KbAglCe3ccsnKatnkbtWb3kVhnKwRdEMXHWTBbEx3dZCgz0fIi2iZ7d0IcQ7eWmTkafOS-v5JhJw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4718, '报纸', '抗战胜利：全人类的宝贵遗产', '韦伟', '解放军报', '解放军报', '抗战胜利;中华民族;世界反法西斯战争;日本侵略者;民族解放战争;抗日战争;中国共产党领导;持久战;', '中国人民抗日战争胜利已经有65年了。中国人民在这场战争中的伟大胜利，不仅赢得了中华民族自身的解放，也为世界反法西斯正义斗争和世界和平、人类进步事业书写了辉煌篇章。这场战争给我们中华民族和人类留下了什么样的遗产？对今天的中国和世界产生着什么样的影响？日前，记', '2010-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS-IsYucqGxtZflG0f9d1makplm0jqCVaoM1HYYoesImTOmBt_A0JCP64Nb_Ugi9nzX6ej8AWJiYhOXeLvRv3DZX3OCpfnI5QeT6qaHgIZT1ORsEypPOJM8QNsenY2nUpjIsXnOKVRzhA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4719, '报纸', '伟人毕竟居功伟 钱老一生不为钱', '何苗', '中华工商时报', '中华工商时报', '钱伟长;清华大学;上海工业大学;冯·卡门;钱三强;科技发展规划;加州理工学院;科教事业;', '作为学界巨星“三钱”之一，钱伟长的一生可谓成果丰硕，为后人留下了众多宝贵的学术财富与精神财富。然而，他的一生却经历过大起大落。面对人生的转折，钱伟长曾这样描述自己的命运：“回顾我这一生，归根到底，我是一个爱国主义者”，“我一生当中所有重大选择都是为了祖国', '2010-08-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR5OeU6AVFpJNupnQ8xXnfcg1urNPgEbD18pQf15TX22dAsvcxx0slx83ybkPaz-Hub1aMC-VXzycQd-ibfb5mQDCXhVXrUPqPjvso_aOPEXZhdhjp2m_x79sPE5v5ZSL3dCijdZqykZg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4720, '报纸', '钱伟长：科学巨子 传奇人生', '高博', '科技日报', '科技日报', '钱伟长;钱学森;冯·卡门;吴有训;传奇人生;', '一个黑色的星期五。 钱伟长，为中国人熟知的科学家，“三钱”中的最后一位，7月30日在上海走完了98岁的一生。 这位爱国学者近一个世纪的历程，犹如一条大江，时而浩荡，时而曲折。像很多同辈的中国科学家一样，钱伟长在民族危亡之际，选择了科学救国的道路', '2010-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSBAw0UUbUDN7OUptTBkCRl_R1y_NSMaggJiQMry4T3GKl8w-R6xlC7GIfgiOrs-Ova9QdKjHpmJrPOiwY4K3pCI0tHr5CbetGqSJqMikFexWDpGEtU4dtyo-OoeemFPQWf3_suat5Crw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4721, '报纸', '看老兵们如何发挥光和热', '吴琳', '光明日报', '光明日报', '先进离退休干部;高玉宝;沙河口区;大连市;革命传统;老年型社会;', '【心声】  “一定要把我嗓子治好,我还要作报告!”  ——2001年,报告团成员张云晓患肺癌住院,由于手术伤及声带神经,他这样一再恳求医生  “上联:赤条条来,哭降人间;下联:清白白走,笑别人生;横批:参加共产党是我一生最大的幸福。”  ——', '2010-07-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRbrIeHjXJEhJEStfOiKmQXFn7IKSJmOZoperrECyETpVAmMkZCWqVZVfPgH8_cBfBFipR_WheYvkVSOQxVZsf_QhvyTxbCH3QdHMHOTBHhfYzx20vYIZLX4N-Ryc2dykvi3-99d1xpPg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4722, '报纸', '学习陈云同志崇高风范 努力建设马克思主义学习型政党', '', '光明日报', '光明日报', '建设马克思主义学习型政党;陈云同志;党的十七届四中全会;马克思主义哲学;学习小组;不唯书;', '编者按 在陈云同志诞辰105周年之际，中共中央文献研究室第三编研部、中共上海市委党史研究室、陈云故居暨青浦革命历史纪念馆管理委员会于6月7日在上海联合召开“学习陈云同志崇高风范，努力建设马克思主义学习型政党──纪念陈云同志诞辰105周年”座谈会。来自中共中央纪委、', '2010-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTw2Gj2cFaYe-A0MC4yYII8xZ2VXodWRAc9DTyJ1teXK_kdSsMusdvcJewVS3psed_nGHBIwWVr7jwxCtWtoM2vBPnrl4WU2XKbqZ4-75dISBgd35g1E5P9tsBxqdIMe7xGuezRDnEubQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4723, '报纸', '排爆专家王百姓拆弹1925枚', '苏银海', '人民公安报', '人民公安报', '王百姓;河南省公安厅;', '本报讯 记者苏银海报道：8年前，河南省公安厅排爆专家王百姓在河北省邯郸市磁县成功排除一枚抗日战争时期留下的特大型号航空炸弹；8年后，他应邀再赴邯郸，成功排除销毁战争时期遗留的炮弹、地雷、手榴弹等爆炸物1925枚。7月16日，邯郸市公安局有关负责人专程来到河南省公安', '2010-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRJvVKZmFjzeEidS3QIk8SD4EaxlJRuNb1SnyK0KAOuD_XgpSZnAwNKcceJU8_vQgAOJDV1kAgTh6oxIwcgepAcyo5gFyJ9DlOO9uTHoeyJzVHL6Ic6DapcRyWi0o7l7YfesgHuZI6fgg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4724, '报纸', '宝塔山下,32年不了情', '武天敏; 刘国顺; 郭江山', '解放军报', '解放军报', '延安精神教育;战时政治工作;革命军人;宝塔山;不了情;凤凰山;政治学院;教学基地;共产党人;革命传统教育;', '黄土高原，千沟万壑，如凝固的惊涛骇浪。 高天下的厚土，承托着这样一条路—— 从古城西安，到圣地延安，32年，车来人往，络绎不绝，像骀荡的长风，像奔流的延河。 32年来，西安政治学院先后组织393批、15万余名部队干部和地方各界人士赴延安现地教学，累计行', '2010-07-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTNETBNF93EIU2QfKXV4PeKKBMoStuzfcLmfqwbjepiHpzQ6HfGdSDXJ9jeEFrXr4_y7Jb5-ScRh3953x8wzyR-RZ8QRG5djAX45kuxgyvaIRhDfcrNd9FH7LzQfJSKX1ggdRXRTsHBqg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,枣园_screened,杨家岭_screened,凤凰山_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4725, '报纸', '坚守心中的圣地', '温庆生 ; 刘国顺 ; 苏文甫', '光明日报', '光明日报', '延安精神教育;传统教学;教研室;革命传统教育;政治学院;', '那是一个注定要载入我人民军队发展史册的日子。  1978年6月，十几辆解放牌卡车载着西安政治学院300多名学员，颠簸在通往延安的黄土沟壑间。他们奔向心中的圣地——延安。  从那时起到今天，西安政治学院坚持延安革命传统教学32年不断线，先后组织393批、15', '2010-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSNpgsejnMOcLWJviySYlA3Jnpwd3g2OLKexRh45wM4ec6qP7LR1VkDplmcaTJ5pC7S_ZgbGn4g1wwvvkd8Cp8rZEJeIFi_Z-8OvRas6_xgh2hDp3K7GadD3lfGj0_CYp2xQW4e-pkeBg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4726, '报纸', '红色洗礼与晋商感恩', '张华钰', '中华工商时报', '中华工商时报', '左权县;统战部;结对帮扶;光彩事业;非公有制经济人士;民营企业家;山西省;', '山西省左权县，一个有着光荣革命传统的红色县域，她的县名因一位68年前在此殉国的共产党高级将领而得名。 革命战争年代，这里为了中华民族的独立和中华人民共和国的建立贡献了巨大的人力、物力——一个当时只有7万人的小县就有1万多人牺牲，1万多人参军，1万多人支', '2010-06-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT6xiRnCjQCUnIwIc7MbtSwolEFW-_1W3-1uLNXAiB5N0JDf_BMSV4vcF655TVxyyqsDjCAnuH1TELDlkhvWrILAS3vFv2Thehts6vbhwAUi_QwtiCNyMfYI1WsFr6ka94qYoKd29dx6w==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4727, '报纸', '澳门儒商吴利勋', '傅旭', '人民日报海外版', '人民日报海外版', '吴利勋;收藏家协会;', '世界不动产联盟中国澳门分会于5月22日在澳门旅游塔举行了成立暨揭牌仪式，首任主席为澳门地产商会会长吴利勋先生。 吴淦记建筑有限公司董事长、广东省汕尾市政协常委、澳门收藏家协会会长、澳门历史研究会会长……吴先生这一串头衔既折射出其多姿多彩的人生，也给人', '2010-06-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRx3S9x0P3PNhIQEZYXg5wrYqgGnZZyu5h9QqJOOqBFPpd1VT2trgq0dRA62m2_PWxExYnjsd6FTanLcEcSUQiNC8pHXTjDI3nJmMy3suqFPfQZpC4kBxJS46utgj547G_uB5zr8TAwFg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4728, '报纸', '忠贞昭日月 业绩铸丰碑', '', '中共中央党史研究室;', '人民日报', '李富春;总政治部;党中央;政治部主任;东北解放区;陕甘宁边区;', '今年5月22日，是李富春同志诞辰110周年。李富春同志是中国共产党创建时期入党的老党员，杰出的无产阶级革命家，忠诚的马克思主义者，党和国家的卓越领导人，我国社会主义经济建设的奠基者和组织者之一。在50多年的革命生涯中，他英勇奋斗，无私奉献，为中国人民解放事业和社', '2010-05-22 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2010.007426', '抗日战争2_screened,遵义会议_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4729, '报纸', '牢记历史 珍重和平', '吴绮敏; 张光政', '人民日报', '人民日报', '世界反法西斯战争;俄罗斯;日本侵略者;胡锦涛;中俄两国;中国人民抗日战争;卫国战争;日本军国主义;', '俄罗斯纪念卫国战争胜利65周年庆典在即，莫斯科洋溢着热烈的气氛，激荡着胜利的豪情。曾经参加中国人民抗日战争东北战场战斗的20位俄罗斯老战士代表尤为激动。因为，前来出席庆典的中国国家主席胡锦涛5月8日下午抵达莫斯科后，第一场活动就是同他们见面；而且，对其中10位老', '2010-05-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQOeu5nngTthFU9jM0y80E1Sr6fIiZUcgL8piyJT6WtQVzg4ozo6IaAozgZBCEch5wpP5p26id-5NPJQqZpwUfKrvxMOOOWSf0YzpSJFWJH4GZv8BuYbiNB7tQ9B7RAnqj17Oal0x4dXA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4730, '报纸', '科学发展 安塞春好', '张军', '新华社;', '新华每日电讯', '安塞县;学习实践活动;胡锦涛;学习实践科学发展观;', '胡锦涛总书记深入学习实践科学发展观活动联系点陕西安塞县，是抗日战争和解放战争时期党中央重要的后方基地和“为人民服务”精神的发祥地。从“为人民服务”到“科学发展观”，一脉相承的精神，在这片红色的土地上与时俱进 春到人间草木知。  春分过后的陕北黄', '2010-04-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTEPzK7wdAwz84ym54Fg-SXSUXCr-3qaZ7FgESB6LXhDNvoa7b7Q0dlSWhGquEnktGjzHTceCC8Dpo0LPlKQ1AasgAtMSAAP8Z1VWFOsvsWs3EB5L3wKKpyf32pgP2bbCqe9P_nYbodzA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4731, '报纸', '孙起孟：民建工商联的卓越领导人', '安冠英', '团结报', '团结报', '工商联;孙起孟;工商业者;领导人;', '孙起孟生于1911年3月2日，安徽省休宁县人，1929年毕业于苏州东吴大学政治系，曾在江苏省苏州女子师范学校、上海中华职业学校任教。抗日战争爆发后到重庆任中华职业教育社四川办事处主任。新中国成立后曾任中华职业教育社理事长，名誉理事长。 抗日战争胜利后，中国', '2010-03-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSX8BkSrbh5RtGtMXkZyXbWhg1zkb4GfuJdyNEsrLPqXSGX-blUkhAxEdkJeYrlKlShdzC4lwTSd3HBgrzFOx-lVRbdHc9ebsikBS2SmD8F3crUYhpsjEce1Pceoi6kOvrbPHZjsalU8g==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4732, '报纸', '在纪念段君毅同志诞辰100周年座谈会上的讲话', '刘淇', '人民日报', '人民日报', '段君毅;十一届三中全会;“文化大革命”;老一辈无产阶级革命家;平反冤假错案;成渝铁路;座谈会;', '同志们，朋友们： 今天，我们怀着崇敬的心情，在这里举行座谈会，纪念段君毅同志诞辰１００周年，追忆他革命战斗的一生，缅怀他为党和人民建立的历史功勋，学习和弘扬他的革命精神与崇高风范。借此机会，我们谨诚挚表达对段君毅同志的深切怀念，并向段君毅同志的夫', '2010-03-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSjZjQG4vGpIVV8RXOsF-mRnhkSFwZryyks9QpQ72Qzbr1ll8P2Vnrp1MNck1_z1dBbhxLeQ62jes1_egLMfkE1_ZRdgFS5DJ4K-GLVZ8y5Nw05SEgLbHMCoEYmiaUpvulF-CU7_EJtSQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大-2_screened');
INSERT INTO `ds_article` VALUES (4733, '报纸', '在纪念段君毅同志诞辰100周年座谈会上的发言', '阴法唐', '西藏自治区党委;第二炮兵;', '人民日报', '段君毅;抗日根据地;座谈会;', '今天，参加纪念段君毅同志诞辰100周年座谈会，我心情分外激动，感慨万千。我的发言，主要回忆抗日战争时期段君毅同志战斗、工作的一些情况。 段君毅同志从我参加革命起就是我的老领导。抗日战争的大部分时间，段君毅同志在鲁西和冀鲁豫地区工作，而创建泰西抗日根据', '2010-03-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRRYrheRRSl_JD6IAVTFZ9hCapLq0d-938am5azLZzlgdkjFpBhj55AVC8nm_s-_-tB4ebjhQxyb4GnU6-nGU8Bd86x8xcNaW_gv7IZeBju9cAEnB7L5NijT5_zT6FhPguRSdzGkQPM1g==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4734, '报纸', '抗战风云下的联大知识分子', '刘宜庆', '中华读书报', '中华读书报', '闻黎明;知识分子;抗日战争;南开大学;', '西南联合大学大师云集、群星璀璨，它不仅仅是北大、清华、南开三所大学的联合，更是战时中国知识分子个人命运和国家命运的联合，学术成果与民族复兴责任的联合。“内树学术自由之规模，外来民主堡垒之称号”,“绝徼移栽桢干质”，“尽笳吹弦诵在山城”。这是联大师生谱写的中', '2010-02-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRaitSMJuadtP5DO7Eh53NZei-CfBFTsWr9N7jceX4nsLvgP3gMI0hZ1Glis25VQKcO1_vNqN-mw9jMPbjo4qtr-bbLQUB9YTWTdtBqh7TltnxwrcVGHJcXlq5dXz54plNk_5AqAmhM5g==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4735, '报纸', '萧克与新中国首所民办大学', '李时平', '人民日报海外版', '人民日报海外版', '九嶷山;乐天宇;民办大学;', '2008年10月24日中午，开国上将萧克逝世，终年102岁。 萧克将军百年人生，戎马关山。他参加过北伐战争、南昌起义、湘南暴动、井冈山斗争、二万五千里长征、抗日战争、解放战争等历次武装斗争，为中国人民的解放事业立下赫赫战功，是威扬华夏大地的一位战将。但鲜为人', '2010-01-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTcNH3M-OBUVnsKaZnRRHk6kWaB1yQikagLhKcbNs4-RI52BfLon8WuNWYGRavYl9R2YVDiSdLQAU8f15ToDSA-4caeMrxttagV28_AVWGkAVfgaKpiW66qTEreUumQSDMlXIT5dWRHGA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4737, '报纸', '“红色资金”惠老区', '薛建刚', '中国财经报', '中国财经报', '陕西省;专项转移支付;村卫生室;安塞县;', '陕北，中国革命的红色摇篮。 1935年10月，中共中央和中央红军长征到达陕北。从此，中共中央在陕北战斗、生活了13个春秋，延安成为中国革命圣地，为中国革命做出了巨大贡献。 近年来，中央财政对陕西革命老区的建设和发展给予了大力支持。2006年—2009年，中央财政', '2009-11-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTAVXv-bljd0AK1w_z9_Iw_qMfI6BSxvyQRvFJghEjwJY0wRFEiI0BqJyj0sZiyt-OMuO14QWg1pifhBiv5sJXDF_oxI-WxbJFMRGhmjB7wxtDEIrSghx3b9kJ3iGa6HMDVDsAcup0syA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4738, '报纸', '在纪念李井泉同志诞辰100周年座谈会上的讲话', '王兆国', '中共中央政治局;全国人大常委会;', '人民日报', '李井泉;中共中央西南局;座谈会;', '今天，我们怀着崇敬的心情在这里召开座谈会，纪念李井泉同志诞辰100周年，深切缅怀他的生平业绩和历史贡献，追思和学习他为国家、为民族、为人民不懈奋斗的崇高精神。 李井泉同志是中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家，我军优秀的', '2009-10-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR_YoKpY0nSj0RiLfZhVeOxQ-fqosL6UCzX8Men8tIjcdne0tYjNMbxCs7INVHYFcPA9yPst-fRxPUeDgzhzIj7KCVmazWe6gUfUOdwKtVtxupXhDZenzRjNQqYFC72iVwMLScuhMuE7w==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大-2_screened,遵义会议_screened,红四军_screened');
INSERT INTO `ds_article` VALUES (4739, '报纸', '杜义德同志逝世', '', '人民日报', '人民日报', '义德;参加;', '新华社北京９月１４日电　原中央顾问委员会委员、中央军委原委员、兰州军区原司令员杜义德同志，因病医治无效，于９月５日在北京逝世，终年９８岁。 胡锦涛、江泽民、温家宝、李长春、习近平、李克强、贺国强、周永康、王刚、王兆国、刘云山、李源潮、俞正声、徐才', '2009-09-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQHTjFbveI9kBIPFboSjQHW0_BtsN0VaiBzm4kgrZ_YF0sHS5Wo_SCh52auFcgpXt_YcZICS73IYX9DkSTD6QNUGW4eIfrWwAjriBjuhk_GGpl_qfBMS814HLlgBqKgzLXPiaxao2luQg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4740, '报纸', '王义之同志逝世', '', '人民日报', '人民日报', '卫生部;', '新华社北京８月１７日电 原解放军兽医大学校长、副兵团职离休干部王义之同志，因病医治无效，于７月３０日在北京逝世，享年８８岁。 王义之是四川省苍溪县人，１９３２年参加革命，同年加入中国共产党并参加中国工农红军。土地革命战争时期，他历任学员、宣传队员', '2009-09-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTCujZkpy-Ps5gwrjlA4BbMCuZ8b5d8fVaPnfRPFdqPMRPGA4ZJW2ZonDZtBgWSFq9b9s7dPWl_xNfz0VLq-xdygWk15R7E4X9wPt4mdPesRxl-GTtkceCrYAU-IN5ujq2WynRYIu0cBw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4741, '报纸', '张铚秀同志逝世', '', '人民日报', '人民日报', '张铚秀;昆明军区;新四军;', '新华社北京８月２３日电　原中顾委委员、昆明军区司令员张铚秀同志，因病医治无效，于２００９年８月１４日在北京逝世，享年９５岁。 胡锦涛、江泽民、温家宝、李长春、习近平、李克强、贺国强、周永康、王岐山、回良玉、刘淇、刘云山、刘延东、李源潮、汪洋、张高', '2009-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRliCx7Ygl2f85L--FjFyn20HZrHanMNIzji3UGQKVgOnv0eUCg74oF8hWV7R9AKur-u8YtW9W7ConZ8eYdIjmfcPNXxzPYqZLqduPpp0NwgYpfE-GeWtyaviL8RHOid6xyPiEH4eYlKw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4742, '报纸', '在纪念耿飚同志诞辰100周年座谈会上的讲话', '王兆国', '中共中央政治局;全国人大常委会;', '人民日报', '“四人帮”;晋察冀军区;座谈会;', '同志们，朋友们： 今天，我们怀着崇敬的心情在这里举行座谈会，纪念耿飚同志诞辰100周年，深切缅怀他为中国人民的解放事业和社会主义建设事业建立的不朽功勋，追思和学习他为国家、为民族、为人民不懈奋斗的崇高品质和始终不渝的革命精神。 耿飚同志是中国', '2009-08-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT7OUcGbwKBn5IT1GQk8h5fqB_R_mdyBm4STI7lBzmdSQSCKFEEWTO4hvi2F0zQWZTBwf3M58_8XdsprSF9GIW9DreqvT-iQ2zxLwLNktODUP61jmSq5iC9hRE8X8suEbR_GUpyjPHKaA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大-2_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (4743, '报纸', '延安：永远的精神财富,不竭的力量源泉', '张军', '新华社;', '新华每日电讯', '延安精神;老一辈无产阶级革命家;力量源泉;', '延安，被誉为中国革命的圣地。1935年到1948年，党中央、毛泽东等老一辈革命家在延安生活战斗了13个春秋，领导了抗日战争和解放战争，奠定了新中国的基石，确立了毛泽东思想在党内的指导地位，培育了光照千秋的延安精神。是什么力量，让延安荒凉的山坳如同磁铁，吸引着无数进', '2009-08-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS72SB3jcsJ11V2WVhCttA858DIE79QGtkBT-lidDS5Q_2g67MwSp1h0W4fmtc6S6RRfbWnkbFQkGc9Chk3PRCjScVWjCfYdEdDI56_sBJBlKK7MC1VWcrS-KPuJpFJRUoCVquJIBYP-A==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,枣园_screened,中共七大1_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (4744, '报纸', '长兴：青山绿水存浩气', '施文杰; 任保玉; 左贵东', '解放军报', '解放军报', '新四军苏浙军区纪念馆;军民团结;小延安;环太湖;', '西依巍巍天目山，东濒渺渺太湖水。 素有“丝绸之府”美誉的浙江省长兴县，位于杭嘉湖平原苏浙皖三省交界处，距离上海、杭州、南京均在150公里左右，是浙江的北大门，当年的新四军苏浙军区指挥中心就设立在这里。 夏日里的长兴，满目苍翠，生机勃勃。一踏上这片土地', '2009-08-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSFxMZEj-7xDxO5vFbnfhRSu4MyQ7-pqAC474suHfar6k1P0SsxwLF6crSE8FuDydnqg4xIUkgiDhCcM9u4C4ay7Rz_FxfomDTsvlZwJea8IqXchcutc1ZuJqP_0x3YEY7gIU5XkMKKHg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4745, '报纸', '辛育龄 无影灯下“不老松”', '陈飞; 徐宏', '健康报', '健康报', '白求恩;肺切除手术;针刺麻醉;胸外科手术;电化学疗法;无影灯;', '他是新中国首批留苏的医学生，作为创建新中国胸外的先驱者之一，他领导完成胸外手术15000余例，指导全国40余家医院建立了胸外科。  他曾是白求恩身边的”小八路”，白求恩的教诲影响了他一生的职业生涯。上世纪50年代，他致力于重症肺结核的外科治疗；60年代，他精心', '2009-08-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSIKSZsRJP-uBp00gpFpvCs1mftpjL4DmyGDhAz33-7MHGf-ssVMRfzYh83YIXeHaZ3tvfKnxvQkQ-q89IQvelhUwl6vbW8rTXDu1DD4fK-4PNgo-ebMAdDDNcwQGSeuPnl6jTtYRfBGQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4746, '报纸', '在纪念宋任穷同志诞辰100周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '宋任穷;座谈会;', '同志们，朋友们： 今天，我们怀着崇敬的心情在这里举行座谈会，纪念宋任穷同志诞辰１００周年，深切缅怀他为中国革命、建设、改革作出的卓越贡献，深入学习他的优秀品质，大力弘扬他的高尚风范，进一步激励全党全国各族人民同心同德、共克时艰，把中国特色社会主义伟大事业', '2009-07-11 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2009.006448', '抗日战争2_screened,四渡赤水_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (4747, '报纸', '缅怀他的业绩 学习他的品格', '刘永治', '解放军总政治部;', '人民日报', '总干部部;陈再道;冀鲁豫军区;宋任穷;', '今天，我们怀着十分崇敬的心情，参加纪念宋任穷同志诞辰100周年座谈会，缅怀他的光辉业绩，学习他的思想品格，进一步激励全军在新的历史条件下为继续发扬优良传统、培育当代革命军人核心价值观而不懈努力。 宋任穷同志具有坚定的理想信念，始终忠诚于党和人民 他1926年投身', '2009-07-11 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2009.002373', '抗日战争2_screened,土地革命战争_screened,反围剿_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4748, '报纸', '总结延安文艺成就继承弘扬延安精神', '王文章', '文化部;中国艺术研究院;', '中国文化报', '延安文艺;中国艺术研究院;座谈会;延安精神;文艺史;继承弘扬;', '编者按《延安文艺史》是中国艺术研究院1988年正式立项的重点科研项目，近日由河北教育出版社出版。《延安文艺史》出版座谈会于2009年5月21日在中国艺术研究院隆重举行。座谈会由中国艺术研究院和河北出版集团主办，中国艺术研究院马克思主义文艺理论研究所和中国延安文艺学会', '2009-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTIlYRK8yURW28vKTg7uU7vsWkTovdotIFP5EECMqLfhZqXYqQAJvE-jvfS6zbW-rQHRQSGWxZT4mEikmzmSN86ohdrNRTtRQzA5famW89kCefp_OT6JzKtBnreCTS2jfEw_mmdZvCmvw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4749, '报纸', '音容笑貌长留家乡人民心中', '罗清泉', '中共湖北省委;', '人民日报', '李先念;湖北省;中原军区;', '今天，是李先念同志百年诞辰纪念日。我们带着湖北6100万人民的敬仰和思念，参加中央举办的纪念李先念同志诞辰100周年座谈会，深切缅怀李先念同志的丰功伟绩，学习他的崇高品格和风范。李先念同志是在湖北孕育和成长起来的一位革命伟人。他生长在湖北，长期战斗在湖北，始终关', '2009-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS6EiKNZNbZ1zxHD2IPGgoz2B0VABnYG_rScgwMFvud5cmFuR22rYcCP-08Vrfy1IUR2EQb0u3pmCmTvTe88L_xK5Ohe3b1g_IpDwzhBTQZ1J7iEQKSok2ygkcLuEwGZu0MOr3X3JHu0A==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4750, '报纸', '在纪念李先念同志诞辰100周年座谈会上的讲话', '胡锦涛', '人民日报', '人民日报', '李先念;党和国家;抗日根据地;社会主义现代化建设;座谈会;', '同志们，朋友们： 今天，我们怀着十分崇敬的心情在这里隆重集会，纪念敬爱的李先念同志诞辰１００周年，深切缅怀他为党和人民建立的历史功勋，追思和学习他为党和人民事业不懈奋斗的崇高品德和风范，进一步激励全党全国各族人民投身改革开放和社会主义现代化建设伟', '2009-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSVzuBBjyrAzuflfWdNc53OJONv6FINSVTqx4otXym9y9WMj4WtsDeyfAGosSUkCfZgBlFwWFWXi4hpctLTM4dOxbV_3jM8B4MpeoO9BIjsM99uwjbY6cY0R55iges5qhVpAq791gAQHw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (4751, '报纸', '《李先念同志诞辰一百周年》纪念邮票首发', '方政军; 杜江玲', '人民日报', '人民日报', '李先念;《李先念同志诞辰一百周年》;', '据新华社武汉６月２３日电 （方政军、杜江玲）《李先念同志诞辰一百周年》（１９０９—２００９）纪念邮票首发式２３日上午在他的故乡湖北省黄冈市红安县举行。 2009年６月２３日是李先念同志诞辰１００周年，为了纪念他为中国革命和建设事业建立的不朽功勋，缅怀', '2009-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTUtbs5Ai-ezxA20bmktpVuyByEY8L1XPLat5pm9Gx1pESJCs2dwweLVH9PZkTyvjW3gHrBRssDZcVNMspUT2SD8d3QAsimdnp_IBaZjKYRcgpSKrXde6DqQr5stIXKNVaRWjqc-VndNQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4752, '报纸', '胡鹏飞同志逝世', '', '人民日报', '人民日报', '胡鹏飞;', '新华社北京６月９日电　海军司令部原正兵团职顾问胡鹏飞同志，因病医治无效，于５月６日在北京逝世，享年９４岁。 胡鹏飞是安徽省金寨县人，１９３０年参加中国工农红军，１９３１年加入中国共产主义青年团，１９３３年转为中国共产党党员。土地革命战争时期，他历', '2009-06-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ_VM7nWVu6AlG5PlhEk8jWQcV8CSgub8DW0dBO6rF6aIK0IO0P17zzOBWi3UBCa-HNGqNYumpBt0fLMUCu6529mv-zOFX4DAnc_aQ4hkhiADZPo7UoMB_BhHDeHX2T9CqyMWJ2ga1pHg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4753, '报纸', '栗光祥同志逝世', '', '人民日报', '人民日报', '总政治部;', '新华社北京６月５日电 解放军总政治部原秘书长栗光祥同志，因病医治无效，于５月２３日在北京逝世，享年８８岁。 栗光祥是山西省襄垣县人，１９３６年参加革命，１９３８年加入中国共产党。抗日战争时期，他历任干事、团教育股长、营政治教导员等职，参加了晋西北', '2009-06-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRhPlyJ6NGbv1l21tKWhiDh_5SW-q9LTTLVxlaPHRORbsJhD2H21mX2xVAaC0i8oP0gcxM76pjjWevrIKYfYNPpvOxB-oQlvaoHczR-Dg-wQNXwGJQUCH_Vi0BtZEToguGJQNDqjcd0ng==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4754, '报纸', '本色人生', '冯春梅', '人民日报', '人民日报', '党的理论;科学发展观;', '杨德千，94岁的老红军战士、北京军区装备部干休所副军职离休干部。 即使是躺在北京军区总医院的病床上，他每天也要手拿放大镜，逐行逐字地读报、看书。 护士长禁不住说道：“您年纪大了，身体又不好，还是要多休息、多调养呀！” 杨德千听了，不', '2009-05-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSy3AgVrvSCPEFrY-I21-Zvf_fo3KK04K4KlOitA7smy-ZiR0uX-prCRlLvINxk3q0b4eJs43BM0Cex183kGem_ojDJ0pf-8AXwQSsI7FTFVcb8pfWa1566Vczw3wW-urxIVOtqmyYpUg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4755, '报纸', '继承革命前辈遗志坚定不移走新型工业化道路', '李毅中', '工业和信息化部;', '中国电子报', '新型工业化道路;无线电;电子工业;国际金融危机;', '5月16日是王诤同志诞辰100周年纪念日，工业和信息化部、总参通信部、总参第四部联合举办座谈会，缅怀王诤同志的不朽业绩。我代表主办单位对各位领导和同志们的到会，表示热烈欢迎和衷心感谢。 王诤同志是我军高级将领，是中央苏区和我军无线电通信事业的创建者，是我', '2009-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTxKmev2irciJDgZ4SmOS67TYRDptmPK2C-TfxttAbbctSmaDxxoOD_F_r5vVQyNsJQYgc_reGU7B2HDtYwl-1BOb-zF6vYv3y2wGAxiQpzdlSt7rIwZTtkTsPzrDZfOhTwqE5YI6qiTA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4756, '报纸', '展明同志逝世', '', '人民日报', '人民日报', '政治部主任;', '新华社北京５月２０日电 原铁道兵政治部主任展明同志，因病医治无效，于５月７日在北京逝世，享年９１岁。 展明原名王恒业，山东省荣成人。１９３７年参加革命，１９３８年入伍，同年加入中国共产党。抗日战争时期，他历任文书、学员、保卫队中队长、指导员、教导', '2009-05-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTXWHrvR3lQ8twQxJy29m9ps8TU6n8Cn7fO8Y7SEUxB6eeddFTb78Zlzp8GZCA9k9vXpmEOtuXPsHQIBdGnY7P5RTX39272ToiYqxd_cqny1TzFZpd9hodXUO30dI1-58NCF2XFv1GJkg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4757, '报纸', '孙树峰同志逝世', '', '人民日报', '人民日报', '北京军区空军;', '新华社北京５月１５日电 北京军区空军原副政治委员孙树峰同志（副兵团职），因病医治无效，于４月２０　日在北京逝世，享年９４岁。 孙树峰是天津武清人，１９３７年入伍，同年加入中国共产党。抗日战争时期，他历任指导员、教导员、县敌工部部长、团政治委员等职', '2009-05-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS1n1ojFzuwK7WVTTtE984Qk-pBIV4ZwdLv0wel8N7LHqhORS4vatcB03uH9gcRMWBXNE8gi_OWumFcjxLlArLo-mxjq3QR5TcgHtbWjWJyY127UYJW1LPIFuEzkJycNCgomhHBT9d5Dg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4758, '报纸', '彭仲韬同志逝世', '', '人民日报', '人民日报', '政治部主任;', '新华社大连５月８日电 沈阳军区原旅大警备区政治委员彭仲韬同志（正兵团职），因病医治无效，于３月７日在大连逝世，享年８９岁。 彭仲韬是河南省洛宁县人，１９３９年入伍，１９３７年加入中国共产党。抗日战争时期，他历任干事、指导员兼政治教员、教导员、团政', '2009-05-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQAdMrrTUS_rfH8V0ZTgK1ajBk9lKeJpF6vNA1qKJt_t2DTwcGogJFysitsv7qG7S6PaIg93VFfCmEL7eJ4OxseGhhM-kZRyM3RXfnC0cPX-8vVoUnscGb033KuTh17vjluPa7qBHqtdA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4759, '报纸', '杨卫群同志逝世', '', '人民日报', '人民日报', '杨卫群;空军学院;', '新华社北京５月４日电 空军指挥学院原院长、正兵团职离休干部杨卫群同志，因病医治无效，于４月１３日在北京逝世，享年８７岁。 杨卫群是辽宁海城人，１９３７年参加革命，１９３８年加入中国共产党。抗日战争时期，他历任学员、队长、干事、参谋、副科长等职，参', '2009-05-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQbTHCTG3E6F1Ie6upV_cgiP2I3UtdKr-no2KLaSNFcP7m_H-ID89sWlPFiTHWrXCdMaKzL3qu6pYogbOkkxaRGVJh47462HU7kP50lTzPbaEt93KIAtGnnyOtBx2mUwbFIdOV3DsRv6g==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4760, '报纸', '做红色山水文章 促老区经济发展', '韩霁; 单保江; 王金虎', '经济日报', '经济日报', '沂蒙精神;山东省旅游局;红色旅游;', '沂蒙深处访“红嫂” 蒙山高，沂水长。在抗日战争和解放战争时期，位于鲁西南的沂蒙山区是著名的革命根据地，当地百姓和子弟兵结下了深厚的军民情谊，沂蒙山小调、“红嫂”成为那段历史的生动见证。 从济南出发向东南行进，一路高速公路连接，两个小时后，记者', '2009-04-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTxQtNtXY0mZaVZNF2NrqEBaNPTNfSReF3UN-PpvXoowSALxwRuiBV2EsIv1Rf70u_iTAd4JljTjZeekSpyAG2EVwWkUulHHBdQZhuB3tVeEtycpYt1c5zBrJrKXnLiJBynnRvmZe6W2g==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4761, '报纸', '开发红色资源 培育支柱产业', '王玲; 刘晓辰', '经济日报', '经济日报', '延安保卫战;瓦窑堡会议旧址;红色旅游资源;旅行社;延安市旅游局;支柱产业;', '延安，陕北黄土高原上的美丽城市，因在中国现代史上占有的特殊地位而闻名中外。“滚滚延河水，巍巍宝塔山”。走进延安，你会感受到，这里的每一寸土地，都有不寻常的经历；这里的每一处遗址，都有动人心弦的故事。 从1935年到1948年，毛泽东同志和党中央在延安13年，', '2009-04-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRMf33V_JRcmb85_KhZuHtoxJTYV3vjU_AH1Hj45mda829Hf9Ht290w7xWxbGRSaNICDaVGa0axNwr71rEBy7T9YgPCE4F5LJOW3LH2KeFIyejk9V9wWEaY34u3RseMWndVo7G3W-r9uQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,枣园_screened,洛川会议_screened,杨家岭_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (4762, '报纸', '冯征同志逝世', '', '人民日报', '人民日报', '政治部副主任;', '新华社北京４月２日电　总参谋部政治部原主任（副兵团职）冯征同志，因病医治无效，于３月２１日在北京逝世，享年８９岁。 冯征是河北邯郸人，１９３８年加入中国共产党。抗日战争和解放战争时期，他历任政治助教、干事、代理教导员、火线剧社社长，冀晋子弟兵报副', '2009-04-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTiOXjAX4uxiorSy9TGyESeLsimPPCPjC2K-V1S-e5pf7_uCsysE65hAmqI1AqhsuHuAaGwjJBDkLnkiGmN8pWgFHulWi03FHtC1mBFe30cltQMwG8ANahTAUUN-MSGQ7pino_tVgg5nw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4763, '报纸', '一位老红军的“遗产”', '李兵正 ; 李建文 ; 李国文; 曾宝瑜', '解放军报', '解放军报', '当代革命军人核心价值观;离退休干部;党的创新理论;共产党人;服务员;杨新勇;抗美援朝战争;王宁宁;', '人物小传：张绪，山西平遥人,1921年7月出生，1937年2月入伍，1938年2月入党，1983年4月从原武汉军区空军副参谋长岗位上离休。2008年5月1日因病在武汉逝世。自参加革命以来，张绪经历了抗日战争、解放战争、抗美援朝战争，参加大小战斗100多次，先后3次负重伤。离休20多年来，', '2009-03-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTV5q6Eko7Rk-AYQENIJnQMtEu482SwoaNzNUQwLKnurzwPaXz3angu660C5Lp1TWV5mGU7xjdqeFPC4y7lYtURP_Id77p6ggR01XmAvSDFfmvqeEvV028KPPOUznqOw5gqndb4wcqEsQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4764, '报纸', '把一切献给党和人民', '李争平', '经济日报', '经济日报', '把一切献给党;科学发展观;抗日战争;共产党人;共产主义;', '2008年5月1日，广州军区空军“老战士报告团”团长张绪与世长辞。告别仪式上，高高悬挂的“爱党跟党走奋斗一生铸忠魂 离休不离志殚精竭虑哺后生”的巨幅挽幛，表达了武汉市各界干部群众和部队官兵对这位老将军的深切缅怀和崇高敬仰。 “要想红旗飘万代，必须教育培养好', '2009-03-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTj6VJYUFDEE3BShyD9YZsODoFFL2CMULll9JbkwIPpDnVtqRbTVl_z2aUUVdcj6-M3xiM0Kapho_swv8t7qvD9yM_uGbN4WFBf_PTyulwYllnKmLEYS3n66hus7KkPzKJiuza4_zjGWQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4765, '报纸', '萧克同志生平', '', '人民日报', '人民日报', '战术教材;中央革命根据地;国民党军;红六军团;中共中央顾问委员会;', '中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家、军事家，原中共中央顾问委员会常委，中国人民政治协商会议第五届全国委员会副主席，中央军委原委员，国防部原副部长兼军事学院院长、第一政治委员萧克同志，因病医治无效，于2008年10月24日12时51分在', '2008-11-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTj8XF8PNxjPY2XGGHh8xTlP0vNcN_TedR_rwK7PksK3iuRc4h1MQjrAHJ9022zGDGJ0TWcghC1HkIp7yB5M_pJfvQfxuZ_k0QTuFW_kfR6B3lEsI3jxU-LD0wJk1OV0vTt_aSRLbLKYw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,红四军_screened,土地革命战争_screened,苏维埃共和国_screened,反围剿_screened,井冈山会师_screened');
INSERT INTO `ds_article` VALUES (4766, '报纸', '在纪念程思远同志诞辰100周年座谈会上的讲话', '李建国', '全国人大常委会;', '人民日报', '程思远;李宗仁;中国共产党领导;爱国民主人士;全国人大常委会;座谈会;', '今天，我们怀着崇敬的心情纪念程思远同志诞辰100周年，深切缅怀他的生平业绩和历史贡献，追思和学习他为国家、为民族、为人民不懈奋斗的高尚品格和始终不渝的奋斗精神。程思远同志是著名的无党派爱国民主人士，杰出的社会活动家，中国共产党的亲密朋友。他胸怀对中华民族的历', '2008-10-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRu_h2Np3o5PYTQa6EbP5t0qa4G_Ix8AcA6_Nntn-vUq_oJaNeUnoZA0RKt06ybjxYDajLpAInVMMqeLA1gf1ZjV7u0hUKaafN-CMzpIo_CXj-WJs59rG5DOhRpDsdOS2E8_-UvOFMPhQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4767, '报纸', '韩光同志生平', '', '人民日报', '人民日报', '中共中央纪律检查委员会;中共中央东北局;', '中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家，我党纪律检查战线的杰出领导人，中共中央纪律检查委员会原常务书记韩光同志，因病医治无效，于２００８年９月２７日５时０６分在北京逝世，享年９６岁。韩光同志１９１２年３月出生于黑龙江', '2008-10-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTHVf2-r9Fm4l8flvFVr4GneVklU4FHGDco3i-guGAWkqxMi5xnywRKNaweXySnf30agqoTnNrleXI09p-1nCQOiAu8HWS9H2zwmDa2tX8OdQ_T-1cMEzqvGEJFyhJ35M9ENsTgCCDhWA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4770, '报纸', '在纪念周恩来同志诞辰110周年座谈会上的讲话', '胡锦涛', '人民日报', '人民日报', '周恩来;党的团结统一;严以律己;座谈会;', '同志们，朋友们： 今天，我们怀着十分崇敬的心情在这里隆重集会，纪念敬爱的周恩来同志诞辰１１０周年，深切缅怀他为党、人民、国家和人民军队建立的丰功伟绩，学习他的革命精神和崇高品德，进一步激励全党全国各族人民全面贯彻党的十七大精神，把中国特色社会主义', '2008-03-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRMesKC6nfJcJ6cfIIPdLR0bzORSKcxQoENpx9QVmm4UdTHu5SH4FykTTasZTnhVZScWNwABMLnuYCiwa8hPsFe71PRadBxQhKxA0h_em8oYA5QGWlC-0fEyilC47kKl6MaN7oATM5CGA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (4771, '报纸', '在纪念周恩来同志诞辰110周年座谈会上的发言', '梁保华', '中共江苏省委;', '人民日报', '周恩来;座谈会;', '今天，我们怀着十分崇敬的心情，参加中央举行的纪念周恩来同志诞辰110周年座谈会，深切缅怀周恩来同志的光辉业绩和不朽功勋，追思他的革命精神和崇高风范，以寄托对他的无尽怀念。江苏淮安是周恩来同志的诞生地。少年时代，他从家乡的自然胜景和人文历史中汲取了许', '2008-03-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTCv8DmbN127t9JQytofI1OGF5RvlZnjMBz1Xkosg54O-dsbLX4qSnAbcnVx0iDSrkSUewHQWmpQFIQvL6M_6ILZIgP1-tQzPwMyo1vNfSqvbVpFpe-A240Osi1SddXZWXnarOcyxz6FQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4772, '报纸', '在纪念薄一波同志诞辰100周年座谈会上的讲话', '贾庆林', '人民日报', '人民日报', '毛泽东;上层统一战线;太岳抗日根据地;华北人民政府;抗日战争;党中央;《若干重大决策与事件的回顾》;阎锡山;托拉斯;陈云同志;中央人民政府;共产党人;共产主义;座谈会;', '同志们：今天，我们怀着崇敬的心情在这里举行座谈会，纪念薄一波同志诞辰１００周年，深切缅怀他为民族独立、人民解放和国家富强、人民幸福建立的历史功绩，追思和学习他为党和人民事业不懈奋斗的崇高风范，进一步激励全党全国人民在中国特色社会主义道路上开拓奋', '2008-01-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRewkPYMPzgon6mYVPdi-XCmZAqXv4VuTlC1cPyilaadvwkXQFswsZBRkjrLi4r_hNSOJZtnD6JuuujqzhpyWkSpULzuUiYY_aaYQrvNoV5s7Eq5RsN3J69HFAEGuL5yTZMBEeGzE_7Gg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4773, '报纸', '在纪念陶铸同志诞辰100周年座谈会上的讲话', '李长春', '人民日报', '人民日报', '中南局;政治部副主任;中共中央书记处;中南地区;知识分子;农村人民公社;广东省;“文化大革命”;中南军区;大革命失败;武装力量;座谈会;', '同志们：今天，我们怀着崇敬的心情在这里举行座谈会，纪念陶铸同志诞辰１００周年，深切缅怀他的历史功绩，追思和学习他为党和人民事业不懈奋斗的崇高风范，进一步激励全党全国各族人民把中国特色社会主义伟大事业不断推向前进。陶铸同志是中国共产党的', '2008-01-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSP2lbt0MnH268oCyrELxdqGwt_Ld406T2AEvNS2cXtc7XYsND-bjYfR3eM_LzuT8VbIhfpdmar7pe5MgWO2QoEKp1K8NfWJK89cemEDUiMRDSmGHTsIG8lCf4qnwI1u6TyOb8m6Qlr6Q==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4774, '报纸', '大型主题雕塑学术研讨会摘要', '', '中国文化报', '中国文化报', '主题雕塑;吴为山;雕塑语言;纪念性雕塑;历史题材;雕塑家;南京大屠杀;学术研讨会;', '邵大箴（研讨会学术主持人、中国美术家协会理论委员会主任、中央美术学院教授）： 各位朋友，各位同仁，侵华日军南京大屠杀遇难同胞纪念馆扩建工程大型主题雕塑学术研讨会开始。今天上午已经有了一个很好的开幕式，王文章院长、范迪安馆长，他们都做了很好的发言。', '2008-01-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTYVLJywZIKeBK_eb2NkTlkjudQwn6Dyi4isSMDDHW-pSkXp5WfN3zbgItL83EmlO-Xci-0O0sDQ7G7QmDzmsjm5iC5QY1A893h2VWpEM3pcAvVbtL-IREztQlzYi600BaXYRT8pZ7Obw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4775, '报纸', '一个四十年代海归的延安情结', '余晓芒', '人民日报', '人民日报', '《解放日报》;毛主席;四十年代;国际统一战线;反法西斯;阿洛夫;余光生;铁路运输;', '离别了我的出生地延安半个多世纪后，来到了延安新闻纪念馆，仰望着父亲余光生的大幅相片，心中感慨万千，父亲的往事一幕幕涌现在眼前……我的祖父余遂辛是我国早期的留日学生，是早年追随孙中山参加过辛亥革命的同盟会成员，新中国成立后任国务院参事，直至1969年', '2008-01-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRtpF_MDgWx09mTA_KmSFFCSONjJBeI38aA6ginqrZufa-JErYguqJf2rnXLRv_Y0bjUvtMZ55rJxfwS3VjZELwJb5lbOrLbR9vwY5CDjT1qKtl5bS-pIdTuqSrx35RzkP5fOaWocSQyw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (4776, '报纸', '在纪念刘宁一同志诞辰100周年座谈会上的讲话', '王兆国', '工人日报', '工人日报', '刘宁一;党的十七大精神;全国人大常委会;工人运动;科学发展观;中国特色社会主义道路;全面建设小康社会;座谈会;', '同志们，朋友们： 今天，我们在这里举行座谈会，纪念刘宁一同志诞辰100周年，缅怀他的生平业绩和历史贡献。刚才，中央党史研究室、全国总工会、全国人大常委会办公厅的同志和刘宁一同志家乡河北省的代表都作了很好的发言。 刘宁一同志是中国共产党的优秀党', '2007-12-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRYthndWs-cXUh2sAkQrl_TaVtUTdnB3T52tbnLWUg_Qaz7MRpLowM5qg2lnovkEUCcYknMvCtEKzzdX7SBfDROa6eZuuG3TsHbAh2rOAlJgAknBzYeYuWYYXsN6725iGcTxpCE0Al4Dw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4778, '报纸', '邱式邦：我国现代生物防治的先驱者', '', '科技日报', '科技日报', '生存率;预防为主;植物保护;玉米螟;综合防治;害虫防治;', '人物档案 1911年8月10日，邱式邦出生于浙江省吴兴县(今湖州市)。 1925年，邱式邦考取上海沪江大学附属中学。 1931年，考入沪江大学生物系。 1935年冬，以优异成绩毕业。 1936年，邱式邦到南京中央农业实验所工作。抗日战争爆发后，实验所', '2007-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRCb8hZ50ECV4zJKdWbx-qutSbbT0bRw4MGnBPlHkhKaayT10gdoaMpF5QgXkX1zPsEHlIXGZs2Q_G3Fqf6ItG4Kjvv0YUUpkRcQEVIICLBev4lFTgDVe-vwft6A3xVakzk8XnY3kmZdg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4779, '报纸', '在纪念彭雪枫同志诞辰100周年座谈会上的发言', '刘源', '军事科学院政委;', '解放军报', '彭雪枫;新四军游击支队;淮北抗日根据地;新四军第四师;敌后抗日根据地;座谈会;', '在杰出的无产阶级革命家、军事家彭雪枫同志百年诞辰前夕，我们隆重召开座谈会，回顾他的战斗历程，缅怀他的光辉业绩，研究他的军事论述，学习他的革命情操和道德风范，这对于继承革命先辈的遗志，弘扬我党我军的优良传统，加速推进中国特色社会主义和军队现代化建设，具有十', '2007-10-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ8RVh4ntcjO-xV25v9J95biyslVyRLkSspxyfGh4NBuHdV2UElgp-DL0QdHC8nrMED_wmzIqUWdRQ0sswhIEqkJpD7zFtaGyIXVnxdB-BcdbMUSBCOGpNCte1oMmv6SWOIChY8paJD2g==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4780, '报纸', '在纪念江华同志诞辰一百周年座谈会上的讲话', '肖扬', '最高人民法院;', '人民日报', '最高人民法院;法官职业;座谈会;', '同志们，朋友们： 今天，我们在这里召开座谈会，纪念江华同志诞辰１００周年，深切缅怀他为民族独立、人民解放和国家富强建立的历史功勋，追思和学习他为党和人民司法事业不懈奋斗的崇高风范，进一步激励全国各级人民法院解放思想，与时俱进，不断开创人民法院工作', '2007-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTh06y2GGflSd7UWGSPIYNAU1lXuguvCv4HEjddHkzPz5Lmsce8k0q9j4V5auVCJd_l02DQd5Iv0c8L2UtGruH1cWdHdEe6OvahxznSUJyudOUpe8_5_G6zd_SEdag4fX7T3fo4Jh2emQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,红四军_screened');
INSERT INTO `ds_article` VALUES (4781, '报纸', '在纪念杨尚昆同志诞辰100周年座谈会上的讲话', '胡锦涛', '人民日报', '人民日报', '杨尚昆;中共中央;周恩来;中央军委;中央办公厅;社会主义现代化建设;彭德怀同志;座谈会;', '同志们： 今天，我们怀着崇敬的心情，在这里隆重集会，纪念杨尚昆同志诞辰１００周年，缅怀他为党、国家、人民军队建立的历史功绩，学习他的优秀品质，激励全党全国各族人民把中国特色社会主义伟大事业继续推向前进。杨尚昆同志是伟大的无产阶级革命家、', '2007-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQdJ68J-RImj5IjjjMme6BfqCltDN7kbcXpPK6X84DQDpa0OB-GYpTX7O5VCeZyzAFTsxUB_thr6ia9915MNPsxwAvS01LL1f28laGQzrtfZ6FMpK2DjuU58JF9B6p4QpA4tLXTw0n4cw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (4783, '报纸', '流过血的人怎能再流泪', '郭中; 马永亮; 薛克; 范永慧', '中国财经报', '中国财经报', '卫生院;魏家滩镇;革命老区;岢岚县;优抚对象;抗日战争;民政局;敬老院;五台县;武乡县;', '老革命的新家 红色记忆 1938年3月10日，八路军120师359旅在王震旅长的率领下激战岢岚县三井镇，消灭日寇300余人，缴获了120师在抗战中的第一门山炮，此炮被贺龙师长命名为“功臣炮”，现陈列于中国军事博物馆。中国三大卫星发射场之一的太原卫星发射基地就在岢岚境', '2007-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTqGR_Go0MDhAUFVWmDp_5ncagsO4iCA2B7nFXNep8UuNhciQR8qdGIy0oC5YDCsK7XWWia8nCjOF66i-T-ymuKrr7I_QfCXzx1CzctXdaaVEpZ-MsXNcJULO2HYqVJtM45uFfzFL0bUw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4784, '报纸', '毛泽东思想指导地位的确立', '', '人民日报', '人民日报', '毛泽东思想;马列主义;指导地位;', '１９４５年４月２３日至６月１１日，中国共产党第七次全国代表大会在延安召开。党的七大的一个重大历史性贡献是确立毛泽东思想为党的指导思想并写入党章。七大通过的新党章指出：“毛泽东思想，就是马克思列宁主义的理论与中国革命的实践之统一的思想，就是中国的', '2007-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSuF_RqEjQi01ifK_97S63fhNm_2gmgRrGguo-IlD9nGc17tBKueI8fDAOT2gs_lD577JFMtCZjJE05Q0DdUvdzsEMc0O1CZqEHtcrCyqbWMfprUmxYI8PAtkQaeP01Ek-aoR7BOaLkDA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4785, '报纸', '欢庆抗战胜利的延安', '', '人民日报', '人民日报', '抗战胜利;抗日战争;', '１９４５年８月１０日晚，延安清凉山新华通讯社的报务员像往常一样接收电讯时，突然收到了发自路透社、合众社有关日本向美国、中国、英国、苏联发出乞降照会的电讯。副社长吴文涛接过电讯稿，激动万分，直接拨通了枣园毛泽东的电话，报告了这一振奋人心的喜讯。 日', '2007-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ4ueONEeVGjo9sjZ-4W2T7UHc2FhX9Un_C8Nfm7wQbR-JXcbA_a8kw-VFWUOf7oNhq2PW34BDZgG9mtcyFJbL3Ul5DobebJip-JFNWiGuHjnTYWW0SCYuWQeeXxPYTuhunEhWTnxp8Nw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,枣园_screened');
INSERT INTO `ds_article` VALUES (4786, '报纸', '在中华民族最危急的关头（上）', '', '人民日报', '人民日报', '卢沟桥事变;日本帝国主义;国民党;国共合作;中华民族;彭德怀;', '新华社北京２月２１日电　１９３７年７月７日，日本帝国主义挑起了蓄谋已久的卢沟桥事变，发动了全面的侵华战争。驻守卢沟桥的国民党第二十九军奋起抵抗，全国性抗日战争爆发。卢沟桥事变是日本帝国主义全面侵华战争和中国全国性抗日战争的标志性事件，是“世界反法西斯战争', '2007-02-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRZ6n3WHUZcSuWmDIaoPQ58YyDHei7JY9vEq5K--O1Gs03PcjgR-yTvIXZj_IOYL8gCiSap2yCVVHOPPpxQg28JFWlVoVAv77zD_TjVo6GcXMMKY_ooiLmWgxoOhHy3g-0vg63L8sPt4A==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4787, '报纸', '陕北公学', '', '人民日报', '人民日报', '陕北公学;毛泽东;抗日战争;李维汉;', '陕北公学是抗日战争时期中国共产党创办的一所具有统一战线性质的干部学校。 １９３７年７月，全国性抗日战争爆发后，大批爱国青年从全国各地来到革命圣地延安。一所抗大已不能满足需要，为了把大批爱国青年培养成为优秀的抗战干部，１９３７年７月底，中共中央决定', '2007-01-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTDk2kVS2OSZbEgCmp1vjGsn7hllarG9rG9uBlPQbVJmQ79CbVoI0tfb9e6MshbXFeU5vGY_NTKRebwfmzUMwKggiPNGvBtso3cCzdc5WB7MjvrD-61m6a599Sc4do-Ikg9houwuki65w==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4789, '报纸', '毛泽东发表《纪念白求恩》', '', '人民日报', '人民日报', '毛泽东;白求恩;《纪念白求恩》;', '诺尔曼·白求恩，１８９０年３月出生于加拿大安大略省格雷文赫斯特城一个牧师家庭，加拿大共产党员，著名的胸外科专家。中国抗日战争爆发后，受美国、加拿大共产党的派遣，白求恩率领一支由加拿大人和美国人组成的医疗队来华，支援中国人民的抗日战争。１９３８年１月来到中', '2007-01-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRqi1LIQ13jf-SCwiG1SwnUCLu6vRHxbeY5x1qQlORdz-k_tbR8nG_8WmA4sgpWyI7LOcaI3xmWPbn0REJBbjS1upg1AdKvDFCriwAN8oBXYdtnipnmksIDfzDSlYYLLwuWuEDWI2-AXA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4790, '报纸', '《彭雪枫将军》打造红色经典', '马霞', '中国文化报', '中国文化报', '彭雪枫;红色经典;《彭雪枫将军》;', '本报讯 为纪念彭雪枫将军诞辰100周年，第二炮兵政治部电视艺术中心摄制的20集电视连续剧《彭雪枫将军》历时80天，辗转河南、陕西、河北、天津等地，近日在北京拍完最后一组镜头顺利封镜，进入后期制作阶段。 彭雪枫将军是中国工农红军和新四军高级指挥员，是中央', '2006-12-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQXK2wxDy4TDMAHT4UCMAxRRV_c4_WUNWL8pobDfvYH1YCrvqBiStBM8nhi2jHfEUEFahdK8o8cYT99NKJm4gieIyHGlsVjd6zejMo03G8fZNBPtxqA_891pQ4jMyeu1LrG2gtZmnyHEw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4791, '报纸', '民族骄子 世纪伟人', '金炳镐; 魏鸿鸣; 李资源; 张俊; 江平; 云杉; 黄庆琳', '中国民族报', '中国民族报', '乌兰夫传;民族区域自治法;刘玉堤;民族法制建设;民族平等权利;延安民族学院;', '在中国革命和社会主义建设的实践中，在马克思主义理 论的指导下，乌兰夫形成了独特的民族工作思想，并在实际领 导工作中不断发展和升华，为中国共产党的民族理论和民族 政策丰富了内容，为中国民族问题的解决做出了重要贡献。  乌兰夫民族工作的思想与', '2006-12-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSLBfdIJrFEo_B5F-9xET_OmzerIAAlH_9hcFOq_0hmkEshria532kANm5IxYe-vu_ZZMKVtuxXhdiE2T7kH2c-SDw0Xdp9H2mhet6Zc84v1eCmWjevOZy5wMiwcRjfLFW6dRQZquETBg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4792, '报纸', '在纪念乌兰夫同志诞辰100周年座谈会上的讲话', '曾庆红', '人民日报', '人民日报', '乌兰夫;马克思主义;内蒙古自治运动联合会;内蒙古自治区;座谈会;', '同志们： 今天，我们满怀敬仰和思念之情，纪念乌兰夫同志诞辰１００周年，缅怀他为党、国家和人民建立的历史功绩，学习和弘扬他的革命精神与品德风范。 乌兰夫同志是久经考验的共产主义战士、党和国家优秀的领导人、杰出的无产阶级革命家、卓越的民族工作', '2006-12-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTG8Y-mVARXYDi1QDQhY9JjIhIIZCUUWvMH2gh-ego6xANbkbLpMItOdfdPfvS5hIyEM5bzPuj9ACcYlYapfqx5dY-Opxt8qIvUO25yvwR12Ll9uVBSpco0l0GTEzT9qAlzC_KFeead_w==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4793, '报纸', '在纪念朱德同志诞辰120周年座谈会上的发言', '张学忠', '中共四川省委;', '人民日报', '朱德同志;仪陇县;座谈会;', '同志们： 在朱德同志诞辰１２０周年之际，党中央隆重举行座谈会，追忆他的光辉人生，缅怀他的丰功伟绩，学习他的崇高风范，意义十分重大。朱德同志是中国人民的光荣，也是四川人民的骄傲。 １８８６年１２月１日，朱德同志诞生在四川省仪陇县马鞍场。他青', '2006-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRVrFqcqaGG_PVYUd0qgGtXrlnOaN998sGDra1kvpeMyemtNZCi4bRfsnfIeLK18vABaZdaZ_VlQQnD4Bir1fp-twy9vfxocPdEmfgSrQFRBdigEtzeaDarmbuYi24tG7BxoSRmNrUZkw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (4794, '报纸', '向着太阳歌唱', '孙雅莉', '中国民族报', '中国民族报', '丁雪松;八路军进行曲;《延安颂》;朝鲜革命军;向着太阳;朝鲜人民军;', '“向前，向前，向前，我们的队伍向太阳，脚踏着祖国的大地……”这首威武雄壮、高亢嘹亮的乐曲，从抗日战争时期到解放战争时期，再到共和国建设年代，鼓舞了千百万中华儿女为民族的独立、祖国的强大，走向战场，走向边疆。这首军歌的谱曲人就是郑律成，一位著名的作曲家，伟', '2006-12-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRy1XtyTjPSmsu6pppGvXdPIv996-AJyGPopTNXQLDDOY4YQtZu979vyhgj4IyaOcHtYq7KxSWD1a1w33faJiiYMeWvfsfwXyHQjaqOROHVu43cjqFeSkfNPmSZ7UDqyoTPJG1bI5Z0hQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4795, '报纸', '洪学智同志生平', '', '人民日报', '人民日报', '洪学智;总后勤部;中央军委;志愿军;新四军第三师;', '中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家、军事家，我军现代后勤工作的开拓者，中国人民政治协商会议第七、八届全国委员会副主席，中央军委原副秘书长，中华人民共和国中央军事委员会原委员，中国人民解放军总后勤部原部长兼政治委员洪学智同志', '2006-11-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtStnYVjuC64_pVguh6U0oZch2FCf2JRjwmnPb8Dz-lA2XIMLF39bZjISnCMVU6w5JlRXC6yHP_8HaJY__rhIUWtfgI3-s3zmX_kkmIi4bXCQ9R1MrGneK4RbrCk63QqTJJUcUbx5bifDw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4796, '报纸', '老红军的新“长征”', '李大伟; 梅世雄; 郭嘉', '新华社;', '人民日报', '刘应启;刘东星;', '１９３３年６月２６日，２２岁的红军战士刘应启面对马克思画像，庄严地举起右手，向党宣誓。７３年后，江苏扬州军分区第一干休所正军职离休干部刘应启说：“我这辈子，最自豪的是认真履行了入党誓言。” １９３５年３月，刘应启随红四方面军强渡嘉陵江。此前，为准', '2006-10-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRMLVZ8ygwEZlxTCUlcjbWDx-pELXK0ko63VRkZJcZazNT8gZpOfUbxxT2cKH-mLIAvFKTrXvwrlgccCrK1MG6zfwSew0Vfv0zFWfJV3TMJ4lwSjVvoWBSl4bmseF8kt6R5sB_GTs3IVQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4797, '报纸', '艰苦卓绝的万里长征', '王邦玉', '新疆维吾尔自治区气象局;', '中国气象报', '夹金山;红四方面军;红军指战员;伤病员;', '1933年9月，徐向前同志率领中国工农红军解放了我的家乡，我和成千上万的劳苦大众一样，看到了共产党领导的红军是咱们自己的队伍，是为天下受苦人争取幸福生活的队伍，是劳苦大众的希望和光明。所以，我报名参加了红四方面军，和广大红军指战员一起，参加了举世闻名的两万五千', '2006-10-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTNnxTOgfaUoTEWG7OoAQ-VrSXE1AXh_upj7X6P0GJC1Teg1I0xbJcLnE2awS-d5rLFd-SpwvkYvkrlBtUVRxk1KkCxCAXNKN6G5Bs6ZV0AMvbye3ZeVQuOXGmLC2ZFdYO-PmM396Jzyw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,夹金山_screened');
INSERT INTO `ds_article` VALUES (4798, '报纸', '廖汉生同志生平', '', '人民日报', '人民日报', '廖汉生;野战军;', '中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家，我军杰出的政治工作领导者，第六、七届全国人民代表大会常务委员会副委员长，中央军委原委员，国防部原副部长，沈阳军区原第一政治委员廖汉生同志，因病医治无效，于２００６年１０月５日６时３０分在', '2006-10-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQXKlwn6-0qd2lgeTbhCvrdmkzht8QtHgSmktGPRR8vxJL5BA764wXpck3EpS928mwdmfZadsUi-kahv6HuQHFOfUBR7sX8U20DP6g3wLLm0nItLBs1t_AcIyfyGxuV1KHvb_mESedUKQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4799, '报纸', '两岸血脉紧相连', '王平', '人民日报海外版', '人民日报海外版', '台湾光复;祭黄帝陵;', '“甲午不幸，乃沦倭寇……五十年来，惨苦痛疚……向往故国，日夜祈救，八年战争，民族更生，旧耻尽雪，旧土重享……时将周岁，特回告祭。”这是６０年前、台湾光复的第二年，由台湾社会贤达组成的“台湾光复致敬团”在陕西耀县遥祭黄帝陵时，宣读的祭文。 一甲子后', '2006-09-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSur5YFrRv4z4FyLmAxgpF2I-5Z3PLD07Bs9GNRBLfKIrOdSClm5KsvKxa-BqesLhLS8QgXTGNtgQ0E5C8dKKkSeeg2MWzTgxVZA44LAkPppkXNHflBMZCcQRYk4xIgGpliPn8dv0FIMA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4801, '报纸', '涂通今：长征中走出的医学博士', '单三娅', '光明日报', '光明日报', '涂通今;钱信忠;神经外科;索尔兹伯里;红军卫生学校;医学博士;', '你也许不信，老红军中还有博士。但这是真的，一共三位。他们是钱信忠、涂通今、潘世征。现在在世的，还有钱信忠和涂通今。  涂通今，二万五千里长征中的医生，中国人民解放军的将军，留学前苏联的医学博士，我国神经外科创始人。这么多头衔集于一身，本身就是一个奇', '2006-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSZfa3IPA0cmmcLR2N243fByCNfRwnjmoihO2VR8Yp6A4gn73f5dspq9EulTbqDB-e_C8VORz_GgnokL4nXKfqhyDNORUkgHVYi5LUEbulOFuXD5WcsgNIFjIos8DiyqDbI7rH6LBg9Vw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4802, '报纸', '一段真实的传奇', '', '中国民族报', '中国民族报', '马宗晋;李四光;地震预报;地震工作;', '从“亡国奴”到中国地质力学的第一个研究生 “九一八”事变后，日本侵略者侵占了东三省。为了实现长期霸占中国的野心,他们一手采用武力征服，一手推行奴化教育。1933年，马宗晋出生在吉林省长春市，他的童年，就是在日本侵略者的奴化教育中度过的。上小学时，他只', '2006-07-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSFdAI5vsU72clslHEUIAovQiV7d2cwKH67j15RO-GMPVja2w8cXIu2mIAERQjNy0aGPIz3darGVR23aYUrERPDUgO0B43SC8gPcLxpqxbD9xf5xflakWWGwhsBwZXX44aB0r-pMjshcQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4803, '报纸', '在激流中永生', '郑盛丰', '人民日报', '人民日报', '冲锋舟;桂林市;灵川县;消防官兵;救生衣;', '在风景如画的桂林山水间，一个“虽死犹生”的英雄名字，正在广为传播。 他敬业爱岗奋发向上，他能歌善舞多才多艺，他热爱生活也创造着生活。 然而，为了群众的安宁和幸福，他作出了一名共产党员、消防警官的英勇选择：跳进滔滔洪水，救起了遇险农民，而把', '2006-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRYrKPJHtOWNNKpBaDGxs2PeWJwr4iEB6va8rfYDqwzgIMMrqGg8HOH1JBWvGCOo8AzsqsH6zYtDw-N1W_63jYeEg4NjdFGdowOLQS32-yhFm6HN96Pm4mjcbTynV-CFyB730-Fy8PAxw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4804, '报纸', '来自抗战博物馆的四个关键词', '邢宇皓', '光明日报', '光明日报', '侵华日军南京大屠杀遇难同胞纪念馆;中国抗日战争史学会;', '7月7日，是“七七事变”爆发69周年纪念日。69年前的那一天，中国人民的抗日战争全面爆发。  成都向西四十公里，大邑县安仁古镇。苍翠环抱中，占地500亩的建川抗战系列博物馆格外引人注目。去年8月15日，5座抗战系列博物馆同时在这里开馆，引起了不小的轰动。日前，在“', '2006-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSdXMi6NzgWil5c5oMd9BmSBsiCQyi-Rv0urTjeYbrVLwn_8Q_3ewJfmkFXB_mKiiDiDNfuXKERY4NnJ9zs9iz1QX8za_B8Vb1AUpFO1oH8x1a5YwHqXwar0ELYr-Mdy5WUrcjSPfN4vw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4805, '报纸', '民营博物馆令人担忧的兴盛', '陈念', '中国商报', '中国商报', '民营博物馆;民办博物馆;侵华日军南京大屠杀遇难同胞纪念馆;', '民营博物馆灵活的机制让国有博物馆自叹不如；但民营博物馆的生存之忧又是国有博物馆无法体察的。 日前，位于四川大邑县安仁镇的建川博物馆聚落迎来了一批特殊的客人：国内8家著名抗战博物馆的“掌门人”。他们除了参观落成不到一年的建川博物馆聚落——建川抗战系列', '2006-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQDia7myDDBWuFjE2-h_w7MJzGEWzizk78HIqlfe1WIUj9rjKQb6LV4VrfnetzQmaIpJuZrcZ5sguVhc29e2MIfvqiW9YU7tl74XPpXpiWCtg-IJITYJCBorYZTCYvl64QfkoFXxneYpA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4806, '报纸', '革命的力量在这里壮大', '宋时飞', '中国经济导报', '中国经济导报', '大生产运动;共产党;抗日战争;吴起镇;抗日根据地;', '前不久，记者前往陕北走访了南泥 湾大生产运动纪念馆。望着广场上的军 民群雕，延安市委宣传部副部长白小平 深有感触地说，“如今的南泥湾，如今的 延安，民生富裕，风景秀美，是个真正的 好地方！”  “这话对着咧！”延安市吴起县委副', '2006-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS2psOGBDmWCpQqoXUWEkCO4TrZh0qSTeBaXHj5GnUz0Sp8KVWU_q4aDD1QhubLxEgeHCQTwyiJ5WL5kletKfJKSpzhfAxdFPRaC74OAaDBDxhSfz2mwO2ZWMIdhrE98UGiMT1MILC8zw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4807, '报纸', '在陆定一同志诞辰100周年纪念座谈会上的讲话', '刘云山', '中共中央政治局;书记处中宣部;', '人民日报', '陆定一;思想战线;党中央;共产党和工人党代表会议;总政治部;纪念座谈会;', '今天是陆定一同志诞辰１００周年，我们举行纪念座谈会，深切缅怀陆定一同志的生平业绩和历史贡献。 陆定一同志是中国共产党的优秀党员、伟大的共产主义战士、杰出的无产阶级革命家、我党宣传思想战线的卓越领导人；中国共产党第七、八、十一届中央委员，第八届中央', '2006-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTw4FL11tGaZcxuqLBg7tldHZWuLDcZR1TZlv3N9jLQjFfjFTkGC7oVmnQWcl9NkOLQkDM0GEPSaNpnfv_iXPkmlnKEZ3YWetIKMDDfp14V2HaHmU5LGoLmtPBLALQqPBhBTCwmbwDhMw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (4808, '报纸', '在陆定一同志诞辰一百周年纪念座谈会上的发言', '李景田', '中央党史研究室;', '人民日报', '陆定一;思想战线;“左”倾错误;一百周年纪念;座谈会;', '今天，我们满怀崇敬之情，隆重纪念老一辈无产阶级革命家，我党宣传思想战线的卓越领导人陆定一同志诞辰１００周年。我着重追忆他在新民主主义革命时期作出的主要贡献。 一、投身革命和宣传思想工作，在艰难曲折中坚持和促进对中国革命道路的探索。 陆定一', '2006-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTyPZIHgnoxbMgqw4DuC9PX5yvR2ToCts6Q3HgBznxyzLbtceFZsPnIx_yPXoYtqafW25ONIZgiSwDNLMs_2J87ROs5k_FWBn1-xayqH4zg8dX_lwV3DzVLTfazW-5xvcvucice4mr2Zw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,中共七大1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (4809, '报纸', '76载漂泊路 烈士铜像终于荣归故里', '于萍', '团结报', '团结报', '济南市委;新加坡中华总商会;', '5月2日，晴空万里，阳光普照。前一天还是阴霾密布的天 空，今天却展开了她灿烂的笑脸。  上午9时，蔡公时烈士铜像安置暨“五三纪念馆”奠基仪式 在著名的风景名胜山东济南趵突泉公园内隆重举行。  铮铮忠骨落济南  “家可以不支', '2006-05-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTNwJfIYeuobDF_fDJH52E2pIZwx-ubRaQdMAASEtVgv0B_-p-cccngzR_OKy1Jt2vigX7hnzj1F2QO8BU1X0IGgVWEvkmmADby6yXvWm7b2tBvHTBwgPzkYZnsNrpUKGcdEl7Y33Ghag==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4810, '报纸', '王首道诞辰100周年纪念座谈会隆重召开', '刘布阳', '中国交通报', '中国交通报', '王首道;共产主义战士;老一辈无产阶级革命家;纪念座谈会;', '本报讯　5月10 日，王首道同志诞辰100周年纪念座 谈会在人民大会堂举行，中共中央政 治局常委、全国政协主席贾庆林出席。 全国政协副主席王忠禹主持会议并讲 话，中央党史研究室副主任李忠杰、交 通部部长李盛霖、湖南省委副书记戚 和平和王', '2006-05-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS-xay9KnYUyfSSVAptGa2nFPkN8YeDwZej4OESFsZBUr_BMnC_F7vvULoR4yRSi9leV4uHLFhklQWb7yc-uZuRQ-wi7up4mfE3i2Kxe4cB17txvLN0eMZsxTiksdfaprS3QaegMeU4fw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4812, '报纸', '近代教育家的光辉典范——张伯苓', '张宝敏', '中国教育报', '中国教育报', '张伯苓;爱国主义;南开大学;南开学校;光辉典范;', '知道有中国的，便知道有个南开……天下谁不知，南开有个张校长？今年4月5日既是清明节，也是著名爱国教育家、南开系列学校创始校长张伯苓先生(1876￣1951年)的130周年诞辰。 在南开园内的中心花园，矗立着张伯苓先生的铜像，先生在世时曾说：“我死后一定要埋在南开', '2006-04-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQTZIkrXnX2Cqs46UbA3l_EyRnMx7gnWM5sqEeLLo87J7-MpzMZ1wVQP1nH_TJaPhAN18lZE1SRRieYwDHm70fXzYWfhfDO3Mk4Cn0pDb4NGVIXTkvVYmGTEE5WGrdrHIBb-Z8sA2LRFA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4813, '报纸', '张谦光', '', '人民日报', '人民日报', '共产党;应城县;抗日战争;', '张谦光，１９０８年出生于湖北省新洲县。幼年家境贫寒，靠半工半读于１９２９年毕业于武昌中华大学教育系。１９３４年任大冶县政府督学，两年后调任应城县政府督学。 １９３７年全面抗战爆发后，为开展敌后抗日救亡运动和建立敌后抗日根据地，中国共产党派董必武、陶', '2006-04-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT1F3FG6O5_9Myhjbff43KsUcYCuiBalqBMlL8Rn8UgFlYARhFz4JZP9jUDQM461XVmP4KQiiLsEYOiOTrY26mK__aP4Vf6CbNRYuDMj2lvG8TSrhuk8q80LVdGiNUvOL6lhTdAae65TQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4814, '报纸', '黄源：鲁迅先生的学生', '秋石', '人民政协报', '人民政协报', '新四军军部;刘少奇;鲁迅精神;皖南事变;', '今年，是鲁迅先生逝世七十周年，同时也是跟随他达十年之久的忠诚学生，著名作家、翻译家、编辑家黄源先生百年诞辰。 上世纪三十年代，在鲁迅和茅盾的精心扶持下，黄源编《文学》、代鲁迅主编《译文》，积极参与粉碎国民党反动当局围剿左翼文学的伟大斗争，鲁迅赞誉他', '2006-04-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR5OcIOqgFY44MN4fmHRGjWiJsTH_sSsqf3JZjykQ5t3MjhRyhjvUXkPoBfX9QiUeMgHBBeekx5F47fIThz8Kc5xTaFM1tBcMJs-UjQZC0EMo8jMhiOOQ11o7GB0o9_LhJSZCOk4lu7gw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4815, '报纸', '深切怀念陈丕显同志', '曾庆红', '人民日报', '人民日报', '陈丕显;南方三年游击战争;根据地;', '今年3月21日，是陈丕显同志诞辰90周年纪念日。陈丕显同志是中国共产党优秀党员、久经考验的忠诚的共产主义战士、无产阶级革命家。他的一生，是革命的一生，光辉的一生，全心全意为人民服务的一生。党和人民深切地怀念他。 陈丕显同志年仅13岁就参加了革命，是我们党', '2006-03-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRTnJsCdQ-PeTXDHpu7yg_acfIHsM5nxMUxy3ZP8Oi3RopjFeLbC3K5Nuodk_iVWdjTBRV-imNe4TKwOdyMZX6iMiCWGSXGOU1QKVDgttFmiRuH__MGa-wLdZ0QJB16Zw_VThc2w7emOA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,闽西革命根据地_screened,项英');
INSERT INTO `ds_article` VALUES (4816, '报纸', '西班牙纪念白求恩', '张金江', '人民日报', '人民日报', '白求恩;加拿大;马拉加;反法西斯战争;', '白求恩，伟大的国际主义战士，1938年初到中国帮助中国人民的抗日战争，后来不幸以身殉职。中国人民感谢他，怀念他，纪念他。毛泽东同志专门写了《纪念白求恩》一文，要求每个中国共产党员都学习白求恩的国际主义和共产主义精神。在西班牙，白求恩也是英雄，人们也感谢他，怀', '2006-02-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTVR-FWp2hXKC3e5FiaOzWqVcPc3qw3hGAD3hqC6zfR0qAZ5unqT2Z0OgvEUuc_CaxGUxs8357IPn7VKnKEV5fTyLuU-jxG-9RbEwziAnTsFyzx25z9a_B9LeVYvL2BYMo-xP_KeON7tQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4817, '报纸', '有大功于党的统一战线事业的忠诚战士', '', '人民日报', '人民日报', '潘汉年;统战工作;党中央;爱国民主人士;', '在潘汉年同志诞辰100周年之际，我们怀着崇敬的心情回顾潘汉年光辉的一生，缅怀他为党的统一战线事业作出的重大贡献。潘汉年同志是坚定的马克思主义者、卓越的党的统一战线领导人。在长期的革命生涯中，他出色地完成党交给的各项艰巨任务，尤其在统一战线工作中，取得了许多极', '2005-12-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQp7fB00kuoFhXR_b-i48JlSRglULhhcrFCTRneV5BrMBAa_0ZxOckEwjpfEhwK56AB_YG7mXwgKQZ5j0VERKBtCG-yDE57J8d92W4hLXzG5D15KquIedjLdND9CeD_eDkcaDIHC7oKSw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,遵义会议_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (4818, '报纸', '伟大的光复　共同的怀念', '殷泓', '光明日报', '光明日报', '殖民统治;抗日斗争;中华民族;', '正在国博展出的《台湾同胞抗日斗争展览》,连日来吸引了成批的观众前来参观。作为纪念台湾光复60周年的系列活动之一,人们纷纷通过参观展览的方式,来纪念这个对于中华民族和现代中国有着重要意义的历史性时刻。这共同的纪念,再一次唤醒两岸骨肉同胞共御外侮、捍卫国家和民族生', '2005-10-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTH1oqpGkhKl40aLQzrGKSfMW03Gab9xlMPK9uXgyAxNLEwX6v9MEW1trPA9biEiVVc93W-jtKVHkrykvhyTU1-ay7dTtMfMCse9F7gkAW89OYIRBcE9Fm9zoNyQrk-pvzBo4msvq5BdQ==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4819, '报纸', '纪念中国人民抗日战争胜利暨台湾光复六十周年', '', '人民日报', '人民日报', '台湾光复;台湾文化协会;中国人民抗日战争;《开罗宣言》;日本帝国主义;六十周年;', '历史将永远铭记 ———写在台湾光复六十周年之际 本报记者 王尧 吴亚明 孙立极 1945年10月25日，台湾光复。“全岛各处，欢歌燕舞，家家户户，祭祖谢神，告慰先灵……”，“台北市30余万人，不分男女老幼，皆盛装而出，家家张灯结彩，相逢道贺，如迎新', '2005-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTWn8zKyvEUYQLYd6MGeNAosWnG7bVQnpj__gyOedJ_9tVz98PIYa1lFENSo3-1l3w0Qnqpb6h3zcuV8mKlBg_Y1wpyY0XgTAOosWl9xq08bc1YS5MRB-vfG51LOy18uQaZ7cGI85UnCg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4820, '报纸', '台湾光复是两岸中国人共同的光荣', '颜军; 包国俊', '中国国防报', '中国国防报', '台湾光复;日本军国主义;台湾民众;', '今年10月25日，是台湾摆脱日本殖民统治回归祖国60周年的纪念日。从1895年台湾沦失，到1945年重新光复的整整半个世纪，既是台湾人民遭受深重苦难的历史时期，也是台湾人民抗击日本侵略者的历史。台湾的光复是中国人民抗日战争取得伟大胜利的结果，是台湾同胞浴血奋斗50年的结', '2005-10-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS8eFm5ReGKgwmIaCPEMxXA3JZbRiCbuQierBkET3Ih0rXTzlWmZuPunbCfzp_twx4yHkRJwlse7_O-GFXfCYOSzS8Ft_JsyjuPZAl7dHlrxhp0Vpu1h62N3K9dp_s7PShG2R8wnT7PJw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4821, '报纸', '弘扬抗大光荣传统　忠实履行新的使命', '李殿仁', '国防大学;', '光明日报', '战略战术;抗大精神;新世纪新阶段;光荣传统;', '举世闻名的抗大，是国防大学的前身。这面在抗日烽火中猎猎飘扬的光辉旗帜，为中华民族夺取抗战胜利作出了不可磨灭的历史性贡献。邓小平同志早在1941年就指出：“抗大成为建设抗日军队的火车头”。今天，重温抗大的峥嵘岁月，弘扬抗大光荣传统，对于忠实履行新世纪新阶段我军', '2005-10-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRaDpLjfUAchjZ79NCwFSATufYEtmNTFzXW5ONb2xScajzO8DTMwFx0kvzVFZvO9SQd4Vek2DlzOZFlFGO8wQsowPWtuMDiUv-3Od9l5FAPKkISttiojj59DiIyKg_I50j6xS0HbAUcbA==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened,百团大战_screened,论持久战_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4822, '报纸', '全面认识抗战历史　努力实现民族复兴', '陈建栋', '光明日报', '光明日报', '中国人民抗日战争;座谈会;胡锦涛;抗战历史;世界反法西斯战争;民族复兴;', '“中国共产党在抗日战争中的‘中流砥柱’作用的表现形式是什么?”“为什么说抗日战争的胜利弘扬了中华民族的伟大精神?”今天上午,在“深入学习宣传胡锦涛总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大会重要讲话精神”网上座谈会上,专家对网友提出的问题进行', '2005-09-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRRoW0JY3U5fpCvaAGET8ChANKYUZg_fqCUCYPobwGE5ioeVdUboYzhBkM-DKMaGq85iU1aXypjLeAOAQukjEindzjJm2aBpeGucNGKTjgts65T53GlhVoG8nueaDbfhATcTJorkflcPg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4823, '报纸', '巍巍太行炳千秋 铸就抗战民族魂', '申维辰', '山西省委;', '中国纪检监察报', '太行精神;民族精神;根据地;日本侵略者;抗日战争;中国共产党领导;', '抗日战争时期，八路军总部和中 共中央北方局长期驻扎太行山区，领 导和指挥敌后抗日军民建立了晋绥、 晋察冀、晋冀鲁豫等抗日根据地，进 行了艰苦卓绝的抗战，铸就了光耀千 秋、彪炳史册的太行精神。中共中央 政治局常委李长春同志精辟地把太', '2005-09-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSJ4222Kb7pgAoooCsBk2gTx4ftlfcgDwGWM2uCuywAZJbqOifSeI_MK6GhRDHhPjA-FBS0Ge-itUwJ1WUGHHSPywEU56Q9hEnQ_7ZnfWM3mBRK_7boqgYpBvrNca7e21_RTOTVEPnUMw==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4824, '报纸', '月圆之夜，警钟敲打民族记忆', '徐扬; 王军', '新华每日电讯', '新华每日电讯', '柳条湖事件;沈阳市;防空警报;日本侵略者;沈阳城;日本关东军司令部;日本兵;北大营;日本帝国主义;东北大学;振兴中华;历史博物馆;', '“日本统治的时候，我们每天早晨得面向东方向日本天皇鞠躬，我们不敢说自己是中国人。屈辱啊！”  ──沈阳老人郝松青 “沉重的国耻，正通过尖锐的警报，化作精神的力量，成为这个民族不能忘却的东西。”  ──吉林青年王锦思 ■策划者 ', '2005-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTYltTFNUdT_bhQwt6F9JPjBCEI6mqljnk9-kVqtZ1CJ5IRgAPLuc0qPUeWcKKwQG-aN4yUAc9iyZw19JdyAMrnHTfcbV2lir2aU4-X_cjAnKSzA4ZEtXBh-_hj-z2jWEoUDC9oWE0RLg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4825, '报纸', '南京大学记忆中的抗战', '袁李来; 陶大镛; 王运来; 王春慧; 张生; 屈胜飞', '光明日报', '光明日报', '九三座谈会;罗家伦;沙坪坝;民主科学座谈会;', '编者按:  抗战时期，是中华民族“最危险的时候”，也是中华民族同仇敌忾、浴血奋战的时候。在那个年代，中华民族的知识精英如何面对国难？如何构筑起“文化抗战”的长城？今日本报选登一组回忆南京大学的前身中央大学、金陵大学师生抗战生活的文章，以激励我们进一', '2005-09-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR_22mHwJpD7ycNduYOMbMscTchmiSLYBnh4PNdOt0Jayj5siyyvPrs5LuzRr936ORh8IzAH6vbfhxtBiO9Rw_b0O7ksdsfSnvzYJHd6I0Mp9T6hMl7KTv2twNbQs8wr05ET0R-AcjaKg==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4826, '报纸', '革命新兴音乐的旗帜　自学成材的音乐巨人', '李岚清', '中国教育报', '中国教育报', '联华影业公司;《义勇军进行曲》;人民音乐家;', '聂耳是伟大的人民音乐家：中国革命新兴音乐的旗帜。 在20世纪初中华民族面临生死存亡的危急关头，聂耳及其继之而起的一大批革命音乐家的音乐，就像一道耀眼的闪电划破昏暗的夜空，打破了当时乐坛萎靡之风盛行的局面，开创了用音乐“代替着大众在呐喊”、吹响“中国', '2005-09-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRQAjUK_FiulbzIOCybBeh1uu-UNeehpOCDzddErKHZaOuCoU0_o3mYo6JojYrkWaZ4vHp-e3e2-ssmIl5-SN961KaN2v_GymH57byMrhOJRybB6IbRhQ1wzTwsoa381BQqA2qweLi-3A==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4827, '报纸', '燃烧当年红色激情', '李舫; 徐馨', '人民日报', '人民日报', '欧阳山尊;独幕剧;战斗剧社;', '《虎列拉》、《求雨》、《打得好》、《粮食》是流传了60年的经典独幕剧，是延安时期的战斗剧社创作并演出的优秀剧目。60年前，这些充满喜剧风格的独幕剧反映了抗日战争中敌后人民的斗争生活。这些戏曾在1942年由敌后根据地剧团在延安演出过，曾极大地鼓舞了当年浴血奋战的抗', '2005-09-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR8vbRS5lGa4rTLGh1UJo0amvqCrM6EhAz9tryJCenRqiS_1b-drOF5s_zuKssytnPeCUIF9uqTW_WJXObrgRqLlMBpT8eYfYnLxyXVNZ39_caNn6rzEsQ4TZBR_qWNa8tNGtMJ6dmEww==&uniplatform=NZKPT&language=CHS', '抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4828, '报纸', '用好生动教材', '薛鹏', '中国纪检监察报', '中国纪检监察报', '新四军纪念馆;盐城市;教育引导;生动教材;军事纪律;', '习近平总书记近日在考察新四军纪念馆时指出，新四军的历史充分说明，民心向背决定着历史的选择，江山就是人民、人民就是江山。这是开展革命传统教育、爱国主义教育的生动教材，要用好这一教材，教育引导党员、干部传承发扬不怕困难、不畏艰险，勇于斗争、敢于胜利的精神，紧', '2023-12-26 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4829, '报纸', '北国冰城点燃红色火炬', '李颖超; 吴安宁', '解放军报', '解放军报', '东北抗联;社团成员;哈军工;哈尔滨工程大学;', '“老师，我们找到了赵元文爷爷的家，他参加过解放战争、抗美援朝战争。”近日，哈尔滨工程大学马克思主义学院教授李世辉收到学生王传霖发来的微信，他们冒着严寒实地走访，找到了102岁的老兵赵元文。 近年来，李世辉和学生一起寻访了30余位抗战和抗美援朝老兵，与他们建立联', '2023-12-02 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4830, '报纸', '本溪：“钢铁之城”的东北抗联情结', '孙仁斌; 李铮; 王莹', '新华每日电讯', '新华每日电讯', '东北抗联;陈列馆;本溪市;抗联精神;', '秋去冬来，山城本溪红枫似火。持续走低的气温并没有影响人们穿越山林，重走抗联路的热情。42岁的本溪县委党校教研室主任杨宏带领学员们沿着蜿蜒的山路，穿梭在密林中。 作为东北抗联的重要根据地，年初以来，本溪市已吸引了超过50万名全国各地的游客到这里“重走抗联路”，', '2023-11-13 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4831, '报纸', '港府计划设立香港抗战纪念馆', '叶蓝', '环球时报', '环球时报', '立法会;', '香港《星岛日报》16日独家披露称，特区政府新一份《施政报告》除了拟增设“宣扬中华文化办公室”外，还计划设立香港抗战纪念馆，加强市民尤其是青年人对抗战历史的正确认识。 报道称，目前部分香港抗战史料分布在香港历史博物馆和香港海防博物馆，两馆均设有与抗日战争有关', '2023-10-17 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4832, '报纸', '牢记使命 为强国建设民族复兴集智聚力', '蒋天羚', '团结报', '团结报', '民族复兴;中国特色社会主义;中国式现代化;习近平总书记;主题教育;中国民主同盟;丁仲礼;领导班子;微信公众号;生态文明思想;费孝通;', '“今年是全面贯彻落实中共二十大精神的开局之年，坚持以中国共产党为师，开展主题教育，对于用习近平新时代中国特色社会主义思想凝心铸魂，为强国建设、民族复兴集智聚力，具有重要意义。”6月7日至8日，民盟十三届三次中常会在陕西省延安市召开。全国人大常委会副委员长、民', '2023-10-12 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4833, '报纸', '辽宁：弘扬“六地”精神 赓续红色血脉', '葛鑫', '中国文化报', '中国文化报', '辽沈战役纪念馆;红色文化;抗美援朝纪念馆;雷锋精神;鸭绿江断桥;黄显声;红色基因;陈列馆;讲解员;发祥地;', '红色，是辽宁最鲜亮的底色。立足抗日战争起始地、解放战争转折地、新中国国歌素材地、抗美援朝出征地、共和国工业奠基地、雷锋精神发祥地，辽宁“六地”见证着革命传统、传承着红色基因、记录着中华儿女砥砺奋进的伟大征程。多年来，辽宁赓续红色血脉，凝聚新时代振兴发展的', '2023-08-24 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4834, '报纸', '“期爱国之士，至诚团结”', '鲍家树', '团结报', '团结报', '嘉兴市委;共产党人;九三学社;褚辅成;', '【编者按】 5月27日，纪念褚辅成诞辰150周年全国学术研讨会在浙江嘉兴举行，全国政协副主席、九三学社中央常务副主席邵鸿出席并讲话。本期“团结文史访谈·多党合作历史启示录”系列报道以“期爱国之士，至诚团结”（语出褚辅成之遗嘱）为题，聚焦统一战线史相关论题，从“', '2023-06-01 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4835, '报纸', '向先烈们致敬', '韩寒', '光明日报', '光明日报', '梁晓声;高鹏举;', '“中国之近代的史，不唯苦难，不唯悲情，亦有大气节大义勇在焉!一批批铁血男儿，坚毅女子，乃是真真实实的存在。他们和她们，当年为救亡图存，振兴中国，肝脑涂地终不悔的初心，与日月同光，共山河永在……”在作家梁晓声的新作《父父子子》封底，郑重地印着这样的话。 近日', '2023-05-24 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4836, '报纸', '百年邹承鲁：“直言的科学家”', '李晨阳; 孟凌霄', '中国科学报', '中国科学报', '邹承鲁;西南联大;科学院;中国科学院院士;人工合成牛胰岛素;', '2023年5月17日是中国科学院院士、近代中国生物化学奠基人之一邹承鲁的百岁诞辰。 这是一位充满传奇色彩的科学家：他早年求学于西南联大，抗日战争期间投笔从戎，加入远征军；他以第一名的成绩通过二战后重启的首届“庚子赔款”留英公费考试，在剑桥大学与李四光的独生女相识', '2023-05-18 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4837, '报纸', '75年前，集结令和冲锋号从这里发出!', '李木元; 周佳佳; 宋宝刚; 汪凯; 刘佳政', '人民政协报', '人民政协报', '政治协商会议;中共中央;城南庄;五一口号;毛泽东;晋察冀军区司令部旧址;民主联合政府;民主党派;九三学社;冲锋号;', '4月的太行山，峰峦巍巍，草木苍苍。 在太行山深处有一个闻名遐迩的小村庄——河北省阜平县城南庄村。在村庄主峰苍山山腰处，草木掩映着一处幽静的小院。走过一段石子小路，一块“晋察冀军区司令部旧址”的石碑矗立在石阶右方。 拾级而上，全国政协委员，九三学社社员许进和', '2023-04-29 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4838, '报纸', '此生许党 永葆本色', '章文', '光明日报', '光明日报', '八路军;高作镇;', '“不要留骨灰，让它随着烟雾空气飞向祖国空中，再落入祖国大地，为发展农业再尽微薄能量。”这是第七届全国道德模范、北京卫戍区某干休所离休干部周智夫的遗言。 19岁入党、20岁入伍，周智夫经历了抗日战争、解放战争，先后参加江苏睢宁县高作镇、安徽灵璧县后马家等10余次', '2023-02-02 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4839, '报纸', '无论顺境逆境始终保持共产党人本色', '陈姝', '中国妇女报;', '中国妇女报', '共产党人;志愿军;', '家庭小传 邓华，中国共产党的优秀党员，久经考验的共产主义战士，我军优秀的政治工作者和军事指挥员，为中华民族的独立和解放建立了不可磨灭的历史功勋。邓华1910年4月出生于湖南省郴州市，1927年3月加入中国共产党，参加了土地革命战争、抗日战争、解放战争等。1950年10月', '2022-12-19 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4840, '报纸', '革命旧址作“教室”，文物史料成“教材”', '张影', '中国文化报', '中国文化报', '革命文物;陕西省;思政教育;文物保护;高校思想政治工作;革命旧址;文物史料;', '党的十八大以来，在以习近平同志为核心的党中央坚强领导下，陕西省委、省政府深入贯彻落实习近平总书记关于文物工作的重要论述和指示批示，推动全省革命文物工作取得令人瞩目的成效，大力弘扬延安精神，特别是发挥在学生思想政治教育中的作用。 “1937年抗日战争全面爆发，', '2022-11-28 08:00:00', NULL, '抗日战争3_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (4841, '报纸', '弘扬黄埔精神 共谋民族复兴', '金晨', '人民日报海外版', '人民日报海外版', '民族复兴;传承发扬;融合发展;黄埔精神;祖国大陆;两岸交流交往;', '第十五届黄埔论坛近日在江苏南京举行。130名来自海峡两岸及港澳地区的黄埔组织和亲属代表、专家学者、在陆台胞代表等，围绕黄埔精神传承、凝聚反“独”促统力量、推动两岸融合发展等主题展开座谈。 与会人士表示，广大海内外黄埔军校校友及后代必须牢记历史使命、顺应历史大', '2022-09-13 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4842, '报纸', '85年前，椎心泣血的淞沪会战', '肖春飞; 吴振东; 潘旭', '新华每日电讯', '新华每日电讯', '淞沪会战;上海宝山;《最后一课》;大夏大学;淞沪抗战;太平洋战争爆发;日资企业;慰安所;', '85年前的8月13日，“八一三”淞沪会战爆发。 历经重重苦难的上海，记录着日军的侵略历史和战争罪行，铭记着中华民族近代史上全民族浴血抗战的历史。 大屠杀不限于南京 一个婴儿，在被日军轰炸后的断壁残垣中嚎啕大哭——这是淞沪会战中日寇暴行的铁证。 1937年8月28日，', '2022-08-12 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4843, '报纸', '“愚公移山”新传', '崔志坚; 王胜昔', '光明日报', '光明日报', '王屋山;纳米技术;《愚公移山》;', '“愚公移山”这个典故，国人不知道的恐怕不多。 这个典故出自战国时的典籍《列子·汤问》，强调的是人在自然天地间的积极作用——只要不畏艰难、坚持不懈地与自然抗争，终将征服自然获得胜利。抗日战争胜利前夕，在延安召开的中国共产党第七次全国代表大会上，毛泽东以《愚', '2022-07-22 08:00:00', NULL, '抗日战争3_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4844, '报纸', '《狙击手》原型邹习祥：比电影更传奇的上甘岭“冷枪英雄”', '李惊亚; 刘智强', '新华每日电讯', '新华每日电讯', '狙击手;上甘岭;《狙击手》;', '“嗖——砰——”中国志愿军狙击手端着步枪，弹无虚发，战壕中的敌人被一枪爆头。 这是春节档热映电影《狙击手》中多次出现的镜头，该影片根据抗美援朝战争冷枪冷炮运动中神枪手群体事迹改编。导演张艺谋曾在接受媒体采访时表示，抗美援朝战争中涌现了张桃芳、邹习祥等很多', '2022-02-15 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4845, '报纸', '父亲的作品写在革命前线', '林子涵', '人民日报海外版', '人民日报海外版', '白彦镇;长篇小说;解放战争;《战斗到明天》;', '在白刃的文集中，他自嘲是“闽南海隅的村野顽童”，但就是这样一名“顽童”，却在年少时毅然走上革命的道路，闯过沂蒙山的日寇大扫荡，上过辽沈、平津战役大战场，用一支铁笔记录了中国将士浴血奋战的烽火岁月。 近日，白刃之女白安丹接受本报记者采访时回忆，父亲数十年', '2021-12-21 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4846, '报纸', '妙峰山下的秘密情报站', '黄光炎; 李孟远', '中国国防报', '中国国防报', '妙峰山;情报工作;', '在北京市门头沟区妙峰山镇涧沟村的西头，有两间看似不起眼的农家院落。这里曾是我党在华北地区一处重要的“地下交通站”——平西情报联络站的驻地。平西情报联络站是抗日战争和解放战争时期党中央联系北平地区的主要情报枢纽，北平通往平西根据地的3条路线就汇合于此。同时，', '2021-12-09 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4847, '报纸', '弘扬长征精神 走好新的长征路', '', '中国民族报', '中国民族报', '长征精神;长征路上;红军长征;', '这是一条筚路蓝缕之路，也是一条通往胜利之路； 这是一条荆棘遍布之路，也是一条开创新局之路。 栉风沐雨，浴血淬火。长征，是改变中国命运的伟大远征。 习近平总书记深刻指出：“伟大长征精神，就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和', '2021-11-26 08:00:00', NULL, '抗日战争3_screened,强渡大渡河_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (4848, '报纸', '“铭记这段保家卫国的历史”', '冯学知; 连锦添', '人民日报', '人民日报', '中国共产党领导;沙头角;东江纵队;英雄群体;纪念园;纪念碑;游击队;历史研究会;', '临近深港边境的香港新界沙头角石涌凹村，坐落着一幢有90多年历史的旧屋，名为“罗家大屋”。1941年12月，日军入侵香港。香港沦陷期间，中国共产党创建领导的东江纵队港九独立大队（简称“港九大队”），就把打击日军的重要交通站设在罗家大屋。 沉寂多年后，如今，罗家大', '2021-11-14 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4850, '报纸', '红旗屹立 薪火相传', '丁一鸣; 常河; 王胜昔; 夏静; 张锐', '光明日报', '光明日报', '大别山地区;大别山精神;鄂豫皖革命根据地;伤病员;鄂豫皖苏区;中国共产党;黄梅戏音乐;薪火相传;', '“一山复一山，一岭高一岭。学堂遍黄冈，处处读书声。百年老师范，代代铸师魂。初心似红烛，不畏霜天永放光明。”10月19日晚，黄冈师范学院大型原创黄梅戏音乐剧《霜天红烛》在京首演，现场座无虚席，气氛热烈。 “近年来，我们以大别山革命史为主线，组织师生自编自演了', '2021-11-03 08:00:00', NULL, '抗日战争3_screened,红四军_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4851, '报纸', '中美脊骨神经医师学会会长董安立博士：挺直中国人的脊梁骨', '王天奡', '人民政协报', '人民政协报', '脊柱侧弯;脊椎病;医师学会;神经学;脊椎矫正;儿童青少年;中国人;', '国庆期间，中美脊骨神经医师学会会长、北京凯诺脊椎专科诊所院长董安立博士特地去看望他的二舅——北京积水潭医院烧伤科创始人常致德。1950年，抗美援朝战争打响，北大医学院的常老作为第一批专业医护工作者报名奔往前线，今年，老人98岁了。 “情况比电影《长津湖》惨烈', '2021-10-20 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4852, '报纸', '弘扬光荣传统 赓续红色血脉', '李慧; 胡晓军; 靳昊; 刘华东; 周晓菲; 钟超; 章文', '光明日报', '光明日报', '井冈山精神;光荣传统;共产党人;抗战精神;习近平总书记;', '人无精神则不立，国无精神则不强。唯有精神上站得住、站得稳，一个民族才能在历史洪流中屹立不倒、挺立潮头。 “一百年来，中国共产党弘扬伟大建党精神，在长期奋斗中构建起中国共产党人的精神谱系，锤炼出鲜明的政治品格。”习近平总书记在庆祝中国共产党成立100周年大会', '2021-10-17 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4853, '报纸', '不灭的记忆 历史的回响', '曹智; 徐扬; 汪伟', '新华社;', '新华每日电讯', '九一八事变;防空警报;杨靖宇;东北抗联;北大营;', '2021年9月18日，沈阳。 尖厉的防空警报声划破天际，沉闷而有力的钟声敲击着这座古城的记忆—— 勿忘九一八! 90年前，山河变色，国土沦丧，中华民族的苦难时刻刻骨铭心。 90年后，安不忘危，治不忘乱，中华民族的复兴脚步不可阻挡。 警报为历史而鸣，钟声为和', '2021-09-19 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4854, '报纸', '一次跨越时空的“相遇”', '程雪; 胡勇华; 胡世坚', '解放军报', '解放军报', '午城战斗;纪念碑;八路军;平型关大捷;午城镇;王泰然;革命先辈;', '黄河东渡渡口 “现在看到的风景是绝美的，而父亲当年渡河是绝难的” 黄河水流湍急，奔腾着，呼啸着。湿润的水汽扑向口鼻，微阖双眼，他静静感受黄河的壮美。 站在陕西省韩城市芝川镇黄河渡口，王克西临风东眺，仿佛看见84年前那令人热血沸腾的出征，听见八路军将士', '2021-09-06 08:00:00', NULL, '抗日战争3_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4855, '报纸', '从台湾“秋祭”想到的', '陈键兴; 姜婷婷', '新华每日电讯', '新华每日电讯', '台湾光复;民进党;翁泽生;', '9月3日，台北有一场每年一度的“秋祭”。早年为何选择这天纪念“忠烈”？当日担任主祭的民进党当局领导人未提，或是说不出口。而近年来台湾社会，尤其年轻一代，有多少人还记得？ 这一天，是抗日战争胜利纪念日。过去五年里，对那场全中华民族决死图存的伟大战争，台湾岛', '2021-09-06 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4856, '报纸', '鄂托克前旗别样“红”', '丁铭; 魏婧宇', '新华每日电讯', '新华每日电讯', '鄂托克前旗;延安民族学院;纪念园;杨宝山;鄂托克旗;', '鄂托克前旗是一个位于内蒙古自治区西南端的旗县，南接原陕甘宁边区。红军长征时期，中国共产党在这里创建了内蒙古地区第一个根据地；抗战时期，中共中央西北局在这里建立了专门培养少数民族干部的城川民族学院；八路军战士在这里为老百姓挖井，秘密交通员在这里潜伏传递情报', '2021-08-13 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4857, '报纸', '“起来!起来!起来!”', '王慧峰', '人民政协报', '人民政协报', '《义勇军进行曲》;中国人民解放军军乐团;中华民族;', '“起来!不愿做奴隶的人们!把我们的血肉，筑成我们新的长城……”战火纷飞的年代，它是“誓与国家共存亡”的冲锋号；和平年代，它是“而今迈步从头越”的进行曲；奥运会赛场上，它是中国体育健儿追求“更快、更高、更强、更团结”的澎湃心声。一首《义勇军进行曲》，唱出所有', '2021-08-12 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4858, '报纸', '皖鲁人民社携手挖掘乳娘传奇故事', '刘蓓蓓', '中国新闻出版广电报', '中国新闻出版广电报', '人民社;乳山市;传奇故事;出版社;', '抗日战争时期，胶东大地上发生了一段感天动地的传奇故事：300多位乳娘（保育员）在极端艰苦的环境中，默默哺育了1223名八路军和革命烈士的后代，而且无一伤亡。 如此独特的事例，在皖鲁两地人民社历经3年的通力合作下，终于以长篇报告文学《乳娘》的形式出版，并以此献礼', '2021-08-02 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4859, '报纸', '继承长征精神 共铸复兴伟业', '王尧; 江琳; 程龙', '人民日报', '人民日报', '长征精神;中国共产党;共产党人;红军长征;湘江战役;长征路上;国民党反动派;习近平总书记;', '伟大长征精神，就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神；就是为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲的精神；就是坚持独立自主、实事求是，一切从实际出发的精神；就是顾全大局、严守纪律、紧密团结', '2021-07-29 08:00:00', NULL, '抗日战争3_screened,将台堡_screened,陈树湘_screened,强渡大渡河_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (4860, '报纸', '红色井冈，英雄山脉', '张科进; 段江山', '解放军报', '解放军报', '井冈山道路;井冈山革命博物馆;人民军队;井冈山精神;秋收起义;红带子;', '今天，我们要结合新的时代条件，坚持坚定执着追理想、实事求是闯新路、艰苦奋斗攻难关、依靠群众求胜利，让井冈山精神放射出新的时代光芒。 ——习近平 井冈逶迤五百里，红旗一展乾坤赤。 盛夏时节，记者走红军路、上井冈山，在先辈们曾战斗过的地方一路探访、回望', '2021-07-21 08:00:00', NULL, '抗日战争3_screened,黄洋界_screened,井冈山革命博物馆_screened,秋收起义_screened,茨坪_screened,龚全珍_screened,贺页朵_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (4861, '报纸', '“让红色基因代代相传”', '刘少华', '人民日报海外版', '人民日报海外版', '红色基因;遵义会议会址;', '贵州遵义红花岗区，有一个地方总是人流如织。游客们换上红军服在大门口合影，小学生排着整齐的队伍有序进入，还有人携家带口，赶来体验感受……这里，是遵义会议会址。1935年1月15日至17日，中共中央在此召开政治局扩大会议。 遵义市委党史研究室原主任张黔生介绍，会址二楼', '2021-07-19 08:00:00', NULL, '抗日战争3_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (4862, '报纸', '斗志在这里激扬', '姚延敏', '中国质量报', '中国质量报', '磨盘柿;盘山柿子;地理标志产品保护;', '蓟州区位于天津市北部，全区总面积1590平方公里，总人口86.57万人。作为天津市唯一的国家级一类革命老区，蓟州大地遍布着革命英烈的红色足迹，有120余处红色遗址，36处爱国主义教育基地。 红色基因在这里扎根 “盘山柿子鼓梆梆，八路军用它做干粮。打一仗来吃一阵，至', '2021-07-15 08:00:00', NULL, '抗日战争3_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (4863, '报纸', '任弼时出使共产国际', '张保军', '团结报', '团结报', '共产国际;《真理报》;执委会;任弼时;抗日民族统一战线;', '随着全面抗战的深入开展，中共中央和共产国际之间，虽然在坚持抗战，巩固国共合作的抗日民族统一战线上是一致的，但是在如何坚持政治上、组织上的独立自主方面存在着分歧。因此，1938年3月，政治局会议决定，派任弼时立即起程去莫斯科，向共产国际说明中国抗战的情况和国共两', '2021-07-15 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4864, '报纸', '中国医科大学走过两万五千里长征路', '刘勇', '光明日报', '光明日报', '中国医科大学;共产党;中国工农红军;红军长征;毛泽东;两万五千里长征;', '“救死扶伤，实行革命的人道主义”。在中国医科大学第十四期学员申玉英的毕业证书上，毛泽东同志的两行题词苍劲有力。 1941年夏，红军卫生学校第十四期学员作为更名为中国医科大学的第一期学员即将毕业，毛泽东同志为十四期学员欣然题词。题词不仅印在了第十四期学员毕业证', '2021-07-11 08:00:00', NULL, '抗日战争3_screened,白求恩_screened,强渡大渡河_screened,四渡赤水_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (4865, '报纸', '妙手仁心，做白求恩式好大夫', '代小佩', '科技日报', '科技日报', '白求恩;辛育龄;', '今年百岁的辛育龄，与中国共产党同龄。 这位拥有82年党龄的老党员，曾是一名小八路，与白求恩共事过。后来成为了一名外科医生，开展了我国首例人体肺移植手术，创建了中日友好医院，是新中国胸外科事业的开拓者和奠基人。 建党百年之际，他被授予党内最高荣誉“七一勋', '2021-07-07 08:00:00', NULL, '抗日战争3_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4866, '报纸', '河北博物院 激活红色文化基因 打造红色主题教育阵地', '', '中国文化报', '中国文化报', '博物院;抗日烽火;红色文化;主题教育活动;教育阵地;', '河北是一块革命的土地、英雄的土地、“新中国从这里走来”的土地。这片英雄辈出的红色热土，有着光荣的革命传统和革命历史。燕赵儿女在党的领导下，书写了可歌可泣、厚重壮丽的红色篇章，镌刻下荡气回肠、永不磨灭的红色记忆，留下了极其丰富的红色资源。作为河北历史文化的', '2021-07-01 08:00:00', NULL, '抗日战争3_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (4867, '报纸', '闵刚侯：活跃于地下战线的法律人', '赵利丽', '人民法院报', '人民法院报', '闵刚侯;中央人民政府最高人民法院;法律人;', '走进中国法院博物馆，展览厅一处，陈列着一张保存完好、色彩鲜艳、字迹清晰的任命通知书，写着：“任命闵刚侯为中央人民政府最高人民法院秘书长。” 抗日战争、解放战争时期，闵刚侯作为中共地下党、民盟盟员，一直活动于敌后战线；新中国成立，他成为最高人民法院的审判', '2021-07-01 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4868, '报纸', '再一次相遇', '陈小菁; 崔寒凝', '解放军报', '解放军报', '医疗队;人民军队;人民军医;白求恩;军医大学;', '再次回到老区延安，韩英依然捧着炽热的初心。 30多年前，这位空军军医大学第一附属医院消化内科专家就曾到过这里，为老区人民送来暖心医疗服务。当时延安只是陕北一座小城，目之所及皆是黄土。 如今，这片热土增添了新的颜色：漫山遍野绿意盎然，庆祝建党百年的红色标', '2021-06-30 08:00:00', NULL, '抗日战争3_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4869, '报纸', '光芒在这里闪耀', '刘佳; 王惜纯; 王梅', '中国质量报', '中国质量报', '延安精神;延长石油;二道街;杨家岭;市场监管部门;红色基因;消费维权;石油装备;食品安全;八路军制药厂;延安市;', '陕西延安 延安，是中国革命圣地，是全国革命根据地城市中旧址保存规模最大、数量最多、布局最为完整的城市。毛泽东等老一辈革命家在这里生活战斗了13个春秋，领导了抗日战争和解放战争，培育了延安精神，是全国爱国主义、革命传统和延安精神三大教育基地。 黄河犹如一', '2021-06-29 08:00:00', NULL, '抗日战争3_screened,枣园_screened,中共七大1_screened,杨家岭_screened,论持久战_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (4870, '报纸', '两岸当共同努力积累善意', '王佳雯', '团结报', '团结报', '台湾光复;黄埔军校;台湾同胞;共同努力;', '“中山先生军事思想，在当时中国实际上居于次殖民地的环境中孕育，目标高远，从今天来看，仍令人敬服；而黄埔建校奋斗的浴血历史，更让后来者相信，再困难艰巨的目标，事在人为。”在不久前召开的“孙中山与第一次国共合作研讨会”上，台湾黄埔军校同学后代联谊会会长丘智贤', '2021-06-29 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4871, '报纸', '《28岁的你》：厚重题材，年轻表达', '山月', '中国妇女报', '中国妇女报', '节目组;青壮年;毛泽东;中共一大;《28岁的你》;杨开慧;湖南卫视;向警予;沈安娜;妇女运动;赵一曼;李大钊;《共产党宣言》;于都县;杨根思;', '从毛泽东、李大钊、周恩来、彭湃、杨根思，到长征中牺牲的于都县青壮年、三位女共产党员、《共产党宣言》救护者等，他们中既有伟人，也有平凡人，还有一些不被人们所关注的群体，但脸同样年轻，血同样鲜红，背同样挺直，心同样滚烫。 “青年如初春，如朝日，如百卉之萌动', '2021-06-24 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4872, '报纸', '从学习党史中汲取砥砺奋进的精神动力', '陈建华', '湖南省郴州市中级人民法院;', '人民法院报', '人民法院;中国共产党历史;精神动力;', '习近平总书记曾深刻指出：“历史是最好的教科书。对我们共产党人来说，中国革命历史是最好的营养剂。”通过阅读《论中国共产党历史》一书，我们得知，党的红色基因，淬炼于我们党百折不挠的抗战历程之中，磨炼于我们党艰苦创业的奋斗历程之中，书写着一代又一代中国共产党人', '2021-06-18 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4873, '报纸', '导演《白毛女》我向生活学习', '张奇虹; 肖人夫; 祁倩倩', '中央歌剧舞剧院;', '光明日报', '《白毛女》;黄世仁;', '跟《白毛女》结缘，要追溯到1946年的春天。 1945年8月，抗日战争刚刚取得胜利，我跟随长兄（中共地下党员）进入解放区，在华北联合大学政治班学习。由于当时年龄很小，又活跃，半年后我被选入华北联大文工团，和王昆、孟于（原创歌剧《白毛女》第一代喜儿扮演者）等从延安', '2021-05-28 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4874, '报纸', '“我对他们是身体保健，他们对我是思想保健”', '杨娜', '学习时报', '学习时报', '马海德;中国共产党;身体保健;麻风病;国民党;史沫特莱;根据地;', '开栏的话 在新民主主义革命时期，一些外国知名人士来到中国后，接触到了中国共产党。他们对中国共产党从理解到认可，从同情到支持，在强大力量的感召下，有的人留在了中国，有的人为让外部世界更好了解中国而呼号，有的人督促本国政府客观认识中国共产党。本期开始，学习', '2021-05-17 08:00:00', NULL, '抗日战争3_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4876, '报纸', '先生之风，山高水长', '楼遂', '中国大百科全书出版社;', '中华读书报', '', '2月20日中午一点突然接到一黎的电话,他哽咽着告诉我,他的父亲身体情况非常不好,可能撑不了多久了。我的头嗡地一下,本来一直为武汉疫情牵扯的心一下子提到了喉咙口,眼泪涌出,一时竟不知对一黎说什么才是。几个小时之后噩耗传来,我的恩师黄鸿森先生仙逝。 恩师在上,受学生一', '2020-03-11 08:00:00', NULL, '抗日战争3_screened,抗日战争2_screened');
INSERT INTO `ds_article` VALUES (4877, '报纸', '战争与和平的断想', '', '中国国防报', '中国国防报', '国家公祭;南京大屠杀;', '再过10天，12月13日——南京大屠杀死难者国家公祭日就要到了。 这是中国政府设立的纪念日，以国家公祭的方式，祭奠在南京大屠杀中死难的30多万同胞。 根据国务院批复，自2014年起，每年这一天,在南京大屠杀死难者国家公祭仪式主会场降半旗。 从1937年12月13日到2019', '2019-12-02 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4878, '报纸', '爱国奉献赤子心', '', '团结报', '团结报', '沈钧儒;毛泽东;救国会;民主党派;中共代表团;国民党;办事处;', '1935年华北事变后,中共中央发出著名的《八一宣言》，号召停止内战，一致抗日，随后“一二?九”运动在北平爆发并迅速波及全国。沈钧儒与马相伯、邹韬奋、陶行知等上海文化界爱国人士发起声势浩大的救国运动。1935年底,上海文化界救国会成立，沈钧儒当选为大会主席。1936年5月', '2019-09-12 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4879, '报纸', '忆彭康 传承西迁精神', '黄辛', '中国科学报', '中国科学报', '', '习近平总书记在2018年新年贺词中，列举了他过去一年中收到的4封群众来信，其中一封来自“西安交大西迁的老教授”。总书记对来信指示：“传承好西迁精神，为西部发展、国家建设奉献智慧和力量。” 上世纪50年代，党中央、国务院作出交通大学西迁的重大决定时，彭康正是“掌', '2018-01-26 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4880, '报纸', '森正孝：我为何要揭露日本731部队细菌战真相', '张蕾', '中国青年报;中青在线;', '中国青年报', '细菌战;犯罪事实;战争犯罪;东京审判;', '“历史问题是中日两国之间最大的问题，责任在日本方面。”日本细菌战研究专家、76岁的森正孝对中国青年报·中青在线记者这样说。今年，是日本发动全面侵华战争以及南京大屠杀80周年。前不久，森正孝来华在京沪两地作了为期一周的学术讲座，讲座的主题是“731部队细菌战真相以', '2017-12-27 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4881, '报纸', '红色记忆 香江传奇', '陈然', '人民日报', '人民日报', '八路军驻香港办事处;爱国民主人士;东江纵队;廖承志;潘汉年;', '编者的话 香港，在抗日战争中经历了苦难，书写了责任。当年，许多海外爱国华侨及同胞，经过这里的八路军驻香港办事处，前往八路军或新四军各分支。而活跃在这里的港九大队更以血肉之躯打通了12条营救路线，为近千名文化界人士的安全转移保驾护航。 70余年风华流转，', '2017-07-01 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4882, '报纸', '弘扬共产党人践行理想信念的大无畏精神', '李晋荣 ; 陈旭 ; 王晓樱', '光明日报', '光明日报', '《天涯浴血》;创作者;重大革命历史题材;琼崖革命;共产党人;理想信念;大无畏精神;', '编者按 电视连续剧《天涯浴血》，近日在中央电视一套黄金时间播出，全景式展现了大革命失败后，琼崖党组织领导琼崖人民坚持武装斗争23年红旗不倒的革命历程。该剧由海南省委宣传部、海南省政协文史委员会、海南广播电视总台、海南恩祥影视文化传媒公司联合拍摄，旨在落实', '2016-07-07 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4883, '报纸', '历史的选择 人民的选择', '', '团结报', '团结报', '民主党派;中国共产党领导;', '今年7月1日,是中国共产党95岁生日。我们向伟大的中国共产党致敬! 1956年2月11日，正是春节。已七十高龄的董必武重访了位于上海兴业路的中共一大会址纪念馆。纪念馆的工作人员请董老题词留念。几天后，他派人送来两幅题词。其中一幅就是：“作始也简，将毕也钜”。“作始', '2016-06-30 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4884, '报纸', '一个爱国的“叛国者”', '关愚谦 ; 谭洪安', '中国经营报', '中国经营报', '毛主席;外语系;天安门城楼;“文革”;红卫兵;叛国者;', '我这辈子经历很复杂，可以说是中国的一个“怪人”。  日本侵略时期，我当过亡国奴；抗战胜利后，我在上海。那时候，我看到英美的战舰停靠在上海滩，美国大兵在霞飞路（就是今天的淮海路）荷枪实弹巡逻，头盔和臂章上写着MP（military police，宪兵）。我年纪还小，就', '2016-03-21 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4885, '报纸', '《历史永远铭记》：平凡中见伟大', '李琳', '健康报', '健康报', '马海德;共产党;《历史永远铭记》;', '9月2日，国家卫生计生委在京召开电视剧《历史永远铭记》座谈会。这部基于马海德真实事迹创作、历时4年精心打造的红色情感史诗巨制荣获中宣部、文化部等部委的重点影视项目，被列入中宣部、国家新闻出版广电总局推荐的十大抗战剧之一，将于近日在央视播出。我们撷取了座谈会上', '2015-09-11 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4886, '报纸', '浴血奋战 艰苦卓绝', '苏银成', '人民日报', '人民日报', '东北抗联;集团军;反日游击队;杨靖宇;侦察兵;东北人民革命军;东北抗日联军;', '东北抗日联军，简称东北抗联。前身是东北抗日义勇军余部、东北反日游击队和东北人民革命军，是中国共产党创建最早、坚持抗日时间最长、条件最为艰苦的一支人民抗日军队。这支武装在极端艰难困苦的岁月里，独立坚持游击战争14年之久，涌现出了杨靖宇、赵一曼、赵尚志、八女投', '2015-09-08 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4887, '报纸', '崇尚英雄 捍卫英雄', '倪光辉 ; 冯春梅 ; 葛亮亮', '人民日报', '人民日报', '社会主义核心价值观;公方彬;黄继光;中华民族伟大复兴;狼牙山五壮士;历史虚无主义;张颐武;民族独立;文化血脉;人民英雄纪念碑;习近平总书记;', '引子 在纪念中国人民抗日战争暨世界反法西斯战争胜利70周年的庄严时刻，天安门广场上，抗战老兵方队率先驶过，接受祖国和人民的检阅，也接受祖国和人民的至高敬意……连日来，致敬抗战老兵、缅怀抗战英雄成为社会的热点；英雄先烈的事迹震撼人心，英雄人物的精神催', '2015-09-07 08:00:00', NULL, '抗日战争3_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (4888, '报纸', '先进性光芒永不退色', '刘启明; 赵淑伟', '中国电力报', '中国电力报', '宏志班;物质生活;游击战;门头沟区;共产党员;', '在纪念抗战胜利60周年之 际，我们见到了80高龄的史一老 人，他耳聪目明、步履稳健，和蔼 可亲。这位老人，参加过波澜壮阔 的抗日战争，九死一生，至诚无 悔；新中国建立后，史一又以饱满 的工作激情投入到电力建设的热 潮中。', '2005-09-10 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4889, '报纸', '“红色科学家”侯祥麟', '李大庆', '科技日报', '科技日报', '侯祥麟;卢沟桥事变;', '侯祥麟是个不懈追求的人。在业务上他不断追求中国石化科技的腾飞，在政治上他则始终不渝地追求共产党人和国家的最高利益。  侯祥麟是两院院士，曾留学美国，是中国石化技术的开拓者之一。然而他也是一位1938年就加入共产党的老党员。在科技界人们称他为“红色科学家', '2005-09-08 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4890, '报纸', '抗战文学作品的现状与反思', '舒晋瑜', '中华读书报', '中华读书报', '抗战文学;文学作品;阎延文;抗战题材;现状与反思;', '文学是历史的镜子。抗战时期的进步文学是唤醒民众、鼓舞人民奋起反抗的号角；在民族危亡的时刻，进步的文学家、艺术家总是与祖国和人民的命运息息相关，他们一方面拿起笔作刀枪，在思想和精神层面发挥着重要作用，另一方面他们自己也在抗战的烽火中接受革命的洗礼，使自己的', '2005-09-07 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4891, '报纸', '历史的镜子', '', '中华读书报', '中华读书报', '梅汝璈;日记体;国际军事法庭;日本战犯;历史的;', 'F编者：ET60年前抗日战争的硝烟虽然早已散尽，但这场战争留给我们的荣辱悲欢却永远铭记在 心。江西教育出版社编辑出版《东京大审判──远东国际军事法庭中国法官梅汝璈日记》之后，并在 梅汝璈先生的家乡──南昌举行座谈会，以这种形式来表达对这场战争取得胜', '2005-09-07 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4892, '报纸', '纪检监察干部认真学习胡锦涛重要讲话', '王少伟', '中国纪检监察报', '中国纪检监察报', '纪检监察干部;胡锦涛;反腐倡廉工作;重要讲话;', '本报讯　9月3 日在首都举行的纪念中国人民抗 日战争暨世界反法西斯战争胜利 60周年的各项活动和胡锦涛同志 在纪念大会上发表的重要讲话，极 大地激发了广大纪检监察干部的 民族自信心和民族自豪感，大家纷 纷表示，要认真学习领会胡锦涛', '2005-09-05 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4893, '报纸', '纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大会在京隆重举行', '', '人民日报', '人民日报', '中国人民抗日战争;世界反法西斯战争;胡锦涛;', '本报北京9月3日讯　纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大会，3日上午在人民大会堂隆重举行。中共中央总书记、国家主席、中央军委主席胡锦涛发表重要讲话强调，我们隆重纪念中国人民抗日战争和世界反法西斯战争的伟大胜利，就是要牢记历史、不忘过去、珍爱和平', '2005-09-04 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4894, '报纸', '胡锦涛在纪念抗战胜利大会上的讲话在海外华侨华人中引起热烈反响', '陈一鸣', '人民日报', '人民日报', '世界反法西斯战争;中国人民抗日战争;海外华侨华人;胡锦涛;抗战胜利;', '本报伊斯兰堡9月3日电　记者陈一鸣报道：巴基斯坦著名华人、巴基斯坦刘氏企业总裁刘江虽然自幼生长在异国，但始终关心着祖国的发展和进步，这几天他连续收看了中国电视台播出的纪念中国人民抗日战争胜利60周年系列节目。3日，通过现场直播收看了胡锦涛主席在纪念中国人民抗日', '2005-09-04 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4895, '报纸', '纪念中国人民抗日战争暨世界反法西斯战争胜利60周年招待会在京举行', '', '人民日报', '人民日报', '中国人民抗日战争;世界反法西斯战争;', '新华社北京9月3日电　共话昔日峥嵘岁月，展望未来美好前景。纪念中国人民抗日战争暨世界反法西斯战争胜利60周年招待会，3日晚在北京人民大会堂举行。党和国家领导人胡锦涛、吴邦国、温家宝、贾庆林、曾庆红、黄菊、吴官正、李长春、罗干等，与抗战老战士和老同志、海内外爱国', '2005-09-04 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4896, '报纸', '胡锦涛重要讲话对中华民族伟大民族精神作了高度概括', '', '人民日报', '人民日报', '胡锦涛;中华民族;重要讲话;', '本报北京9月3日讯　综合本报和新华社消息：9月3日在首都举行的纪念中国人民抗日战争暨世界反法西斯战争胜利60周年的各项活动和胡锦涛总书记在纪念大会上发表的重要讲话，极大地激发了全国人民的民族自豪感和民族自信心。各地干部群众纷纷表示，胡锦涛总书记的讲话高屋建瓴、', '2005-09-04 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4897, '报纸', '历史是发展的精神动力', '', '中国财经报', '中国财经报', '中华民族;精神动力;', '15年前，中国改革开放之父邓小平在一次会见客人时说：“我是一个中国人，懂得外国侵略中国的历史。当我听到西方七国首脑会议要制裁中国，马上就联想到1900年八国联军侵略中国的历史。”接着，他便讲出了一句极为深刻的话：“要懂得些中国历史，这是中国发展的一个精神动力。', '2005-09-03 08:00:00', NULL, '抗日战争3_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4898, '报纸', '陈云林会见台湾抗战老战士许历农', '陈键兴', '人民日报', '人民日报', '陈云林;中共中央台办;国务院台办;', '新华社北京9月2日电　（记者陈键兴）中共中央台办、国务院台办主任陈云林2日下午在此间会见了来京参加中国人民抗日战争暨世界反法西斯战争胜利60周年纪念活动的台湾抗战老战士许历农。 陈云林指出，中国人民抗日战争，就是以国共合作为基础，全国各族人民包括港澳台', '2005-09-03 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4899, '报纸', '血战', '', '新华社;', '人民日报', '台儿庄战役;八路军;专家点评;平型关战役;百团大战;正面战场;黄土岭战斗;', '平型关大捷：显示人民军队力量 【回放】1937年9月23日，企图攻占太原的日军先头部队进抵平型关附近，八路军115师决定在平型关东北公路两侧设伏。25日8时30分，日军坂垣师团21旅团的两个联队进入伏击圈，八路军设伏部队居高临下，向敌猛烈射击，将其分成几段，各个歼灭', '2005-09-03 08:00:00', NULL, '抗日战争3_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4900, '报纸', '让战斗过的一代留下历史回声', '柴葳', '中国教育报', '中国教育报', '座谈会;老同志;教育部;', '本报北京9月2日讯(记者　柴葳)“黄河之滨，集合着一群中华民族优秀的子孙”……伴随着雄壮的《抗日军政大学校歌》的歌声，今天上午参加教育部机关老同志纪念抗日战争胜利60周年座谈会的52名抗日老战士仿佛又回到了烽烟四起的战争岁月。在党旗下，在歌声中，重温自己入党抗敌', '2005-09-03 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4901, '报纸', '让伟大民族精神浸入学子灵魂', '杨晨光; 姜洁', '中国教育报', '中国教育报', '东北大学;民族精神;日本帝国主义;九·一八;社会实践活动;中国人民抗日战争纪念馆;世界反法西斯战争;历史与现实;', '东北大学是一所具有爱国主义光荣传统的大学，在抗日战争中，有许多重要事件和人物关连着东北大学。为纪念中国人民抗日战争和世界反法西斯战争胜利60周年，东北大学今年暑假举行了“抗日战地行”主题社会实践活动，选择全国各地10个具有典型意义的抗日战争胜利的纪念地点，组', '2005-09-02 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4902, '报纸', '展现一部真实而鲜活的历史', '李宏伟', '光明日报', '光明日报', '亲历者;抗日战争胜利;《儿女英雄传》;', '为纪念抗日战争暨世界反法西斯战争胜利60周年,中央电视台《儿女英雄传》摄制组运用全新视角,走访了100多位抗战亲历者和历史学者,制作成30集大型系列纪录片《儿女英雄传》。该系列片自8日15日在央视新闻频道播出以来,受到了观众的高度赞扬和肯定,认为该系列片第一次将普通人作', '2005-09-02 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4903, '报纸', '建筑师雕塑家共铸“青铜史诗”', '贺慧宇', '中国建设报', '中国建设报', '雕塑家;纪念性雕塑;宛平城;隋建国;纪念碑;', '参观过北京宛平城中国人民抗日战争纪念雕塑园的人，无不为园中庄严肃穆，气势宏伟的几十座雕塑震撼，这些雕塑宛如一部反映悲壮时代的青铜史诗，向人们展示出那段惨绝人寰、艰苦卓绝的历史。今年，正值纪念抗日战争暨世界反法西斯战争胜利60周年，中国人民抗日战争纪念雕塑园', '2005-09-02 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4904, '报纸', '农业部召开纪念抗日战争胜利60周年座谈会', '白锋哲', '农民日报', '农民日报', '抗日战争胜利;老干部工作;座谈会;农业部;', '本报讯　9月1日， 农业部召开纪念抗日战争胜利60周 年座谈会，缅怀为抗击日本侵略者而 英勇献身的先烈们的丰功伟绩，追思 抗战老战士为中华民族的解放事业 而浴血奋战的艰苦历程，学习抗战老 战士无私奉献和英勇献身的精神。杜 青林部长', '2005-09-02 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4905, '报纸', '刘家栋：抗战八年 永怀延安', '石艳红', '中国纪检监察报', '中国纪检监察报', '延安精神;刘家栋;陈云同志;', 'T刘家栋，1917年7月生，河南修武 人。1935年参加革命工作。曾任党的十 二大中央纪委专职委员，中央纪委研究 室主任（正部长级）。  1935年冬在北师大附中读书时，参 加了“一二·九”救亡运动。1936年1 月参加平津同学南下宣传团，1936', '2005-09-01 08:00:00', NULL, '抗日战争3_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4906, '报纸', '中国抗战中的越南将军', '张静宇', '人民日报', '人民日报', '抗日战争;共产党;晋察冀抗日根据地;毛主席;中越两国;胡志明;八路军;五台县;', '在灿若星河的中国人民解放军将军队列中，曾出过惟一的一位外籍少将———越南将军洪水（原名武元博）。他与中国人民共同走过了8年抗战的艰苦岁月，对中国人民的民族解放事业做出了特殊贡献。最近，记者几经辗转，找到了洪水将军的中国遗孀、91岁的陈剑戈老人，听她娓娓讲述了', '2005-08-31 08:00:00', NULL, '抗日战争3_screened,枣园_screened,论持久战_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4907, '报纸', '纪念抗战胜利暨台湾光复六十周年座谈会在京举行', '陈键兴', '人民日报', '人民日报', '台湾光复;中国和平统一促进会;中国统促会;座谈会;抗战胜利;六十周年;', '据新华社北京8月29日电　（记者陈键兴）中国和平统一促进会与台湾“中国文化统一促进会”29日在人民大会堂共同举办座谈会，纪念中国人民抗日战争胜利60周年、台湾光复60周年。 全国政协副主席、中国和平统一促进会副会长张克辉出席座谈会并讲话。他说，台湾军民反抗', '2005-08-31 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4908, '报纸', '王在希：国民党军队为抗战胜利作出重要贡献', '陈键兴; 谭晶晶', '人民日报海外版', '人民日报海外版', '国民党军队;正面战场;世界反法西斯战争;抗战胜利;', '据新华社北京8月30日电（记者　陈键兴、谭晶晶）　国务院台湾事务办公室副主任王在希30日在北京指出，中国国民党军队在正面战场的各次重大战役，是中国抗日战争乃至世界反法西斯战争的重要组成部分；台湾同胞的抗日斗争是整个中华民族抗日斗争的重要组成部分，为全面抗战的胜', '2005-08-31 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4909, '报纸', '郝志伟：艰苦奋斗不能丢', '袁海涛', '中国纪检监察报', '中国纪检监察报', '抗日战争;经济困难;', 'T郝志伟，1918年出生， 陕西省延长县人。1935年参 加革命工作，1936年加入中 国共产党。抗日战争期间， 历任中共中央组织部干部、 中共西北局组织部干部。建 国后，曾任中央纪委机关党 委书记。1984年离职休养。E  “42年那', '2005-08-31 08:00:00', NULL, '抗日战争3_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (4910, '报纸', '中华民族的重大转折', '王宏苗; 李东航; 柴华', '解放军报', '解放军报', '中国人民抗日战争;世界反法西斯战争;中华民族;', '“这是一个转折，一个中华民族发展史上的重大转折！”  应本报编辑部之邀出席“纪念中国人民抗日战争胜利60周年座谈会”的军内外专家，在谈到抗日战争的胜利对60年来中国与世界的影响时，都作出了同样的评价——伟大的抗日战争作为自鸦片战争爆发100年来中国人民反', '2005-08-29 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4911, '报纸', '“日本八路”忆抗日', '曹鹏程', '人民日报', '人民日报', '反战组织;八路军;野坂参三;反战团体;', '在艰苦卓绝的抗日战争历史中，有一群特殊的功臣不应被忘记：他们来自当时的敌国———日本，有的是坚信真理的无产阶级战士，有的曾是顽固的军国主义少年，有的还曾是凶残的日本兵，最后他们却都以自身的抗日义举创造了一段“世界战争史上的奇迹”。前田光繁就是他们中间最早', '2005-08-29 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4912, '报纸', '中国抗战，史无前例的军事创举！', '', '解放军报', '解放军报', '正面战场;《论持久战》;毛泽东;全面抗战;八路军;战略防御;世界反法西斯战争;中国人民抗日战争;反法西斯统一战线;游击战;抗日民族统一战线;国民党军;日本帝国主义;战争形态;日军大本营;日本法西斯;敌后战场;中国抗战;', '持久战 游击战 全民皆兵 人民战争陷敌于灭顶之灾 军事科学院战略研究部研究员 刘庭华  ●“共产党的一个最大优点，就是它的持久战思想。”——美国前国务卿基辛格  ●“毛泽东是一位伟大的战略家。他的游击战和运动战相结合，在中国打败了', '2005-08-29 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4913, '报纸', '陈麒章：投笔从戎 抗日救亡', '李玉龙', '中国纪检监察报', '中国纪检监察报', '新四军军部;抗日战争;金戒指;抗日救亡;夏令营;', 'T陈麒章，1919年12月出生， 广东省澄海县人。曾任中央纪委 研究室副主任（副部长级）。1938 年4月参加革命，1938年7月加 入中国共产党。并在浙江参加地 下党工作。1940年2月，在皖南 军事教导队学习，后任教导队总 俱乐部干事。1941', '2005-08-29 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4914, '报纸', '深刻汲取中国人民抗日战争胜利的历史经验万众一心实现全面建设小康社会的宏伟目标', '', '人民日报', '人民日报', '中国人民抗日战争;世界反法西斯战争;全面建设小康社会;', '新华社北京8月26日电　中共中央政治局8月26日下午进行第二十四次集体学习，中共中央总书记胡锦涛主持。他强调，我们要深刻总结党团结带领人民开展抗日斗争的重要历史经验，并结合新的历史条件，用这些重要历史经验教育党员、教育人民，激励全党同志和全国人民进一步认识和把', '2005-08-27 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4915, '报纸', '发扬老同志的革命精神做好新形势下的科技工作', '刘恕', '科技日报', '科技日报', '新形势下;中国人民抗日战争;徐冠华;', '本报北京8月25日电 英勇不屈的抗日战士塑像，气势雄伟的万里长城，巍峨壮丽的天安门城楼,象征着伟大的中华民族精神。在由这组形象组成的巨大背景前，科技部抗战老同志追忆中国共产党领导全国各族人民打败日本帝国主义的峥嵘岁月，以此纪念抗战胜利60周年。今天，科技部召开纪', '2005-08-26 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4916, '报纸', '论伟大的抗战精神', '', '人民日报', '人民日报', '抗战精神;日本帝国主义;帝国主义列强;中华民族;', '今年是中国人民抗日战争暨世界反法西斯战争胜利60周年。重温那段血与火的悲壮历史，缅怀抗日先烈的丰功伟绩，弘扬中华民族伟大的抗战精神，在今天仍然具有十分重要的意义。 1931年，日本军队制造“九一八”事变，侵占中国东北。1937年，日军又悍然发动“七七”卢沟', '2005-08-25 08:00:00', NULL, '抗日战争3_screened,狼牙山_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4917, '报纸', '40余位老战士追忆抗战史', '李立桢', '中国妇女报', '中国妇女报', '全国妇联;顾秀莲;抗战史;', '本报北京8月22日讯 (记者 李立桢) 60年前，她们艰苦抗战，冲锋陷阵，她们是那段悲壮历史的见证人。60年后，她们会聚一堂，追忆抗战，缅怀英烈。8月22日，全国妇联纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大会隆重举行，40多位抗战老战士的再聚首，会场上摆放的抗战', '2005-08-23 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4918, '报纸', '学习老同志的革命精神和优秀品质进一步做好新形势下的组织工作', '崔士鑫', '人民日报', '人民日报', '老同志;新形势下;抗日战争;优秀品质;', '本报北京8月22日讯　记者崔士鑫报道：中央组织部机关22日召开老同志纪念中国人民抗日战争胜利60周年座谈会。中共中央政治局委员、书记处书记、中组部部长贺国强在座谈会上强调，要大力弘扬抗日战争中形成的优良传统和作风，学习老同志的革命精神和优秀品质，进一步做好新形势', '2005-08-23 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4919, '报纸', '全国妇联纪念抗日战争暨世界反法西斯战争胜利60周年', '李薇薇', '人民日报', '人民日报', '全国妇联;黄甘英;抗日战争;世界反法西斯战争;', '据新华社北京8月22日电　（记者李薇薇）“1938年，我和黄甘英（原全国妇联副主席）一起奔赴冀南抗日根据地，参加了平原游击战。黄甘英生完孩子刚4天，就把孩子留在群众家中寄养。6天后，为了躲避敌人扫荡，她又在天寒地冻中随队行军，终身落下腰腿疼的毛病……” 在', '2005-08-23 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4920, '报纸', '党的抗日民族统一战线思想的成功实践', '胡长水', '人民日报', '人民日报', '山西青年抗敌决死队;阎锡山;牺盟会;山西新军;抗日民族统一战线;成功实践;', '今年是中国抗日战争胜利60周年。对于中国共产党、中国人民和中华民族来说，这是一个永远值得纪念的伟大日子。在这场战争中，中国人民所表现出的万众一心、喋血奋战的伟大爱国主义精神，永远是中华民族的宝贵财富；中国共产党在民族危亡面前所表现出的宽广胸襟和远大视野，以', '2005-08-23 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened,百团大战_screened,洛川会议_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4921, '报纸', '韩光：我所认识的抗联英雄们', '沈俊峰', '中国纪检监察报', '中国纪检监察报', '杨靖宇;东北抗联;', '曾担任中央纪委常务书记 的韩光同志，是我党在东北地 区早期的革命活动家和东北抗 日联军组建者之一。1932年 起，他以中共满洲省委特派员 名义，在东北抗日联军第一 军、第三军主要做政治工作， 协助杨靖宇、赵尚志等同志工 作，打响了中华', '2005-08-21 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (4922, '报纸', '烽火岁月熔铸优良作风 继承传统开创美好未来', '', '中国纪检监察报', '中国纪检监察报', '优良作风;张闻天;彭德怀同志;大生产运动;新四军;继承传统;', 'F编者按E  T抗日战争时期是党的历史发展的一个重要时期， 也是党的自身建设的一个重要历史时期。在抗战的烽 火岁月里，为了坚持党的阶级立场和政治地位，保持 党的无产阶级先锋队性质和优良作风，以毛泽东同志 为代表的中国共产党人始终坚持将马克', '2005-08-21 08:00:00', NULL, '抗日战争3_screened,百团大战_screened,枣园_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4923, '报纸', '陈达之：我亲历了那场战争', '石艳红', '中国纪检监察报', '中国纪检监察报', '抗日战争;日本鬼子;凤凰山;青年救国会;', 'T陈达之，1925年3月出生，山东省肥城市人。曾任中央纪委常 委（副部长级）、全国政协委员。1938年10月加入中国共产党，并 于当年12月参加八路军工作团。在此后的抗日战争中大部分时间 从事党的群众工作。先后任肥城县青年救国会主任、顿丘县抗联主 任、', '2005-08-19 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4924, '报纸', '纪念伟大胜利 民间收藏大显身手', '', '中国商报', '中国商报', '民间收藏;收藏家;台儿庄战役;', '今年的8月不同凡响，为了纪念抗日战争胜利和世界反法西斯战争胜利60周年，国内各种纪念活动纷纷登台。8月15日，《伟大胜利——纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大型主题展览》在北京中国人民抗日战争纪念馆隆重开展。与此同时，全国各地的抗日胜利纪念活动', '2005-08-18 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4925, '报纸', '牢记历史 振兴中华', '李玉龙', '中国纪检监察报', '中国纪检监察报', '世界反法西斯战争;中国人民抗日战争;振兴中华;', '8月17日，北京雨后初晴、风和 日丽。一大早，坐落在卢沟桥畔宛 平城内的中国人民抗日战争纪念 馆又迎来了一批批参观者。上午10 时，中央纪委、监察部机关党委组 织机关干部来到这里，参观“伟大 胜利——纪念中国人民抗日战争暨 世界', '2005-08-18 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4927, '报纸', '海峡两岸暨港澳佛教界道教界分别举行法会', '刘维涛', '人民日报', '人民日报', '佛教界;祈祷法会;中国佛教协会;中国道教协会;', '本报北京8月15日讯　记者刘维涛报道：由中国宗教界和平委员会、中国佛教协会发起组织的海峡两岸暨港澳佛教界纪念中国人民抗日战争暨世界反法西斯战争胜利60周年祈祷世界和平法会15日在北京灵光寺隆重举行。 中国佛教协会会长一诚法师以及来自内地、香港、澳门、台湾', '2005-08-16 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4928, '报纸', '鲜血和意志，浇出胜利之花', '鹿永建', '新华每日电讯', '新华每日电讯', '靖国神社;世界反法西斯战争;抗日战争;抗战老兵;日本军国主义;南京大屠杀;沂蒙精神;日本侵略者;中华民族伟大复兴;', '8月15日，中国很多地方以各种形式纪念这个特殊的日子。60年前的这一天，中国人民在世界正义力量的支持下，打败了日本帝国主义者，迫使日本投降。  1937年7月7日，日本策划“卢沟桥事变”，发动蓄谋已久的侵华战争。他们曾叫嚣：一个月占领上海，三个月占领中国。然', '2005-08-16 08:00:00', NULL, '抗日战争3_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (4929, '报纸', '委部机关召开座谈会隆重纪念抗日战争胜利60周年', '刘熙颖; 李玉龙', '中国纪检监察报', '中国纪检监察报', '抗日战争胜利;中央纪委;监察部;座谈会;', '本报讯（记者 刘熙颖 李 玉龙）中央纪委监察部机关8 月15日召开座谈会，隆重纪念 抗日战争胜利60周年。中共中 央书记处书记、中央纪委副书 记何勇出席会议并讲话。中央 纪委副书记夏赞忠主持会议。 委部机关有关领导同志李至 伦、刘', '2005-08-16 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4930, '报纸', '继承传统 开创未来', '刘熙颖', '中国纪检监察报', '中国纪检监察报', '抗日战争;座谈会;继承传统;', '8月15日上午，中央纪委小礼 堂。委部机关纪念抗日战争胜利60 周年座谈会在这里隆重举行。  座谈会在庄严的国歌声中拉 开了帷幕。  伴着欢快的进行曲，何勇等领 导同志来到委部机关参加过抗战的 老领导、老同志面前，与他们亲切', '2005-08-16 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4931, '报纸', '中国共产党是全民族团结抗战的中流砥柱', '', '人民日报', '人民日报', '中国共产党;毛泽东;中华民族;抗日统一战线;团结抗战;新四军;抗日根据地;日本侵略者;抗日民族统一战线;共产党人;', '60年前的今天，1945年8月15日，一个令中国人民欢欣鼓舞、倍感自豪的日子：日本宣布无条件投降。 经过中华儿女的英勇斗争，无数人的流血牺牲，我们终于赢得抗日战争的伟大胜利。 这是近代100多年以来，中国人民反抗外敌入侵取得的第一次完全胜利，是中华民', '2005-08-15 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4932, '报纸', '60年前的今天，日本降了！', '', '新华每日电讯', '新华每日电讯', '法西斯;中国人民抗日战争;全面侵华战争;无条件投降;世界反法西斯战争;靖国神社;', '1945年8月，中国抗日武装力量向日军发起全面反攻。朱德命令日军向人民军队投降，但受到美国和国民党政府的阻挠。8月21日，中国军队代表在湖南芷江召见日军洽降代表，指示日方投降准备事宜。9月9日，中国战区日军投降签字仪式在南京举行。中方代表、陆军总司令何应钦主持受降', '2005-08-15 08:00:00', NULL, '抗日战争3_screened,枣园_screened');
INSERT INTO `ds_article` VALUES (4933, '报纸', '在抗战的日子里', '杨尧鑫', '中国纪检监察报', '中国纪检监察报', '办事处;八路军;日本鬼子;三五九旅;', '85岁的彭祖贵双眼几乎看不到 什么东西了，但他的耳朵还非常灵 敏，头脑清晰，精神矍铄，讲起八 年抗战的烽火岁月，他打开了记忆 的闸门，任思绪飞向那激情壮怀的 年代——  开赴抗日前线  抗战爆发时，我17岁，在贺龙', '2005-08-14 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4934, '报纸', '牢记历史　发愤图强　为实现中华民族伟大复兴贡献力量', '沈路涛', '人民日报', '人民日报', '日本帝国主义;侵华日军南京大屠杀;李长春;中华民族伟大复兴;', '新华社北京8月12日电　（记者沈路涛）中共中央政治局常委李长春12日晚来到中国国家博物馆，参观正在这里展出的“12·13———侵华日军南京大屠杀史实展”。 1937年12月13日，侵华日军侵占南京，30多万中国同胞惨遭杀害。展览通过600多张历史图片、753件珍贵文物和史', '2005-08-13 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4935, '报纸', '牢记历史 珍爱和平', '姚晓刚; 王少伟', '中国纪检监察报', '中国纪检监察报', '南京大屠杀;', 'F开栏的话：E  T今年是纪念中国人民抗日战 争暨世界反法西斯战争胜利60周 年。以此为契机，用抗日战争的 生动历史推进爱国主义教育，对 于进一步弘扬民族精神，凝聚民 族力量，增强民族自尊心、自信 心、自豪感，激励和动员全国各', '2005-08-11 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4936, '报纸', '时代的强音 震撼的旋律 普遍的音乐', '李岚清', '光明日报', '光明日报', '生平事迹;冼星海;《黄河大合唱》;', '冼星海是一位伟大的人民音乐家。他在短暂的一生中,创作了大量的音乐作品,特别是《黄河大合唱》等不朽名作,在抗日战争时期,大大激发和鼓舞了中国人民抗敌御侮的士气和斗志,为夺取抗日战争的胜利,发挥了重要的作用。他的音乐至今仍有着旺盛的生命力,对振奋民族精神,具有积极的', '2005-08-09 08:00:00', NULL, '抗日战争3_screened,抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4937, '报纸', '抗日战争时期坚持共产党绝对领导人民军队的思考', '温宗仁', '军事科学院;', '光明日报', '人民军队;绝对领导;共产党;抗日战争;', '一  坚持中国共产党对人民军队的绝对领导，始终是人民军队建设的根本问题，也是60年前中国人民抗日战争取得胜利的根本保证。坚持党对人民军队的绝对领导这一在土地革命时期提出和确立的建军原则，在抗日战争时期得到了进一步丰富发展，并成为我军克敌制胜的强大武器', '2005-08-02 08:00:00', NULL, '抗日战争3_screened,洛川会议_screened,中共七大-2_screened');
INSERT INTO `ds_article` VALUES (4938, '报纸', '继承光荣传统弘扬民族精神为中华民族伟大复兴而奋斗', '', '人民日报', '人民日报', '胡锦涛;弘扬民族精神;中国人民抗日战争;光荣传统;中华民族伟大复兴;', '新华社太原7月31日电　在纪念中国人民抗日战争胜利60周年和中国人民解放军建军78周年之际，中共中央总书记、国家主席、中央军委主席胡锦涛近日来到山西省考察，瞻仰抗战旧址，缅怀英雄业绩。胡锦涛代表党中央、国务院、中央军委，向抗日老战士、老民兵、老支前模范表示崇高的', '2005-08-01 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4939, '报纸', '太行精神永存', '刘伟; 刘思扬', '新华社;', '人民日报', '胡锦涛;老同志;太行精神;八路军总部;日本侵略者;抗日战争;', '巍巍太行，雄踞华北。 60年前，在中国和中华民族处于生死危亡的关键时刻，中国共产党领导八路军和太行儿女，在这里前仆后继、浴血奋战，谱写了抗击日本侵略者的英雄篇章，培育和造就了太行精神。 在纪念中国人民抗日战争胜利60周年之际，中共中央总书记、', '2005-08-01 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4940, '报纸', '抗战精神仍激励我们奋勇前进', '', '新华每日电讯', '新华每日电讯', '胡锦涛;山西省;老同志;中央军委;八路军总部;中国人民抗日战争;抗战精神;八路军太行纪念馆;日本侵略者;', '新华社太原7月31日电在纪念中国人民抗日战争胜利60周年和中国人民解放军建军78周年之际，中共中央总书记、国家主席、中央军委主席胡锦涛近日来到山西省考察，瞻仰抗战旧址，缅怀英雄业绩。胡锦涛代表党中央、国务院、中央军委，向抗日老战士、老民兵、老支前模范表示崇高的敬', '2005-08-01 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4941, '报纸', '“海上猛虎”跃海疆', '钟魁润; 徐纲要; 唐先武', '科技日报', '科技日报', '海上猛虎艇;信号兵;', '7月11日，记者来到东海舰队某水警区，登上了这艘名扬军内外的“海上猛虎艇”，并随艇出海，观看了艇员的部署操演，令人振奋。  数十年过去了，这艘英雄艇几经换装，成为一艘猎潜艇了。艇上的官兵换了一茬又一茬，但大家不忘肩负的重任，不断为“猛虎精神”注入时代', '2005-07-28 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4942, '报纸', '侨胞抗日赤子心', '何洪泽', '人民日报', '人民日报', '抗日救国;', '在中国人民抗日战争期间，旅居海外的侨胞始终是祖国人民坚定的支持者。记者日前采访了纽约华侨衣馆联合会（下简称衣联会）主任委员林以和先生，听他回忆了当年纽约侨胞踊跃支持祖国抗战的动人情景。 纽约华侨衣馆联合会成立于1933年。它的诞生是与祖国抗战紧紧联系', '2005-07-19 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4943, '报纸', '地雷战：鬼子魂飞胆丧赵疃村', '刘海民', '新华社;', '新华每日电讯', '地雷战;', '赵疃是胶东的一个普通村庄，因为地雷战，它成了一个世界军事史上神秘的战场。脍炙人口的影片《地雷战》，其故事原型就是从这里找来的，《地雷战》中的赵虎，表现的就是赵疃的老民兵赵守福。赵守福如今已经不在了，但赵疃民兵巧布地雷阵、打得鬼子魂飞胆丧的事并未被人们尘封', '2005-07-15 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4944, '报纸', '伟大的人民赢得伟大的胜利', '朱玉; 万一', '新华社;', '人民日报', '抗日战争;中国人民抗日战争纪念馆;中华民族;', '“伟大胜利———纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大型主题展览”，开展于今年的7月7日。这是一个比滚烫的天气更让人热血沸腾的展览。 展览最初设计为每天接待参观者4000人左右。但主办者中国人民抗日战争纪念馆也没有想到，展览一开幕，观众的热', '2005-07-14 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4945, '报纸', '那是伤痕累累后绽放的笑容', '朱玉; 万一', '新华每日电讯', '新华每日电讯', '伤痕累累;中国人民抗日战争纪念馆;抗日战争;', '据新华社北京7月13日电（记者朱玉　万一）纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大型主题展览，开展于今年的7月7日。这是一个比滚烫的天气更让人热血沸腾的展览。  展览最初设计为每天接待参观者4000人左右。但主办者中国人民抗日战争纪念馆也没有想到', '2005-07-14 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4946, '报纸', '抗日战争纪念馆馆长：我们是战胜国,抗战不是国耻', '李煦; 张舵; 万一', '新华每日电讯', '新华每日电讯', '抗日战争;抗战精神;中华民族;王新华;', '针对我们应该如何看待和纪念抗日战争，如何准确理解伟大抗战精神，如何更好地加强爱国主义教育，切实落实胡锦涛总书记提出的“牢记历史、不忘过去、珍爱和平、开创未来”的指导思想，中国人民抗日战争纪念馆馆长王新华接受了本社记者的专访，畅谈了他的观点和看法。  抗', '2005-07-14 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4947, '报纸', '扬起脸来　写下历史', '陈晓星', '人民日报海外版', '人民日报海外版', '中国人民大学;高金素梅;交趾陶;陕北公学;', '“我们觉得今天在中国人民大学的演讲堂里面，面对着年轻朋友，我们应该抬起头来，过去我们的年轻人牺牲生命扬着脸走进历史，今天我们的年轻人应该抬起头、扬起脸写下中华民族的历史！”7月12日上午，中国人民大学逸夫会议中心，在此演讲的新党主席郁慕明此言一出，掌声四起，', '2005-07-13 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4948, '报纸', '为了延续民族的血脉，向西，再向西！', '肖春飞; 金■■', '新华社;', '新华每日电讯', '南京国民政府;宜昌大撤退;抗日战争;闻一多;敦刻尔克;国民党;黄浦江;李政道;', '〖TPXHMR20050713Z02500,+76mm,+27mm，BT〗 抗战期间，中国的大地上，由东向西，进行着一场史诗般波澜壮阔的大迁徙，政府官员、大学教授、工商企业主、小工苦力……挈妇带幼，从海边走向大山，从富饶的江南奔赴偏远的西南。为了延续民族的血脉，他们不分老幼、不分', '2005-07-13 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4949, '报纸', '抬起头来写下历史', '孙立极', '人民日报', '人民日报', '卢沟桥;中国人民抗日战争纪念馆;', '追忆60多年前的抗战，“七七事变”不能不提，卢沟古桥不可不访。7月11日，新党纪念抗战胜利60周年大陆访问团来到了卢沟桥和中国人民抗日战争纪念馆。 今天上午9时10分，新党主席郁慕明率访问团抵达卢沟桥。走过“卢沟晓月”碑，访问团一行走上桥头。两侧桥栏上，500', '2005-07-12 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4950, '报纸', '京台合作前景美好', '聂传清', '人民日报海外版', '人民日报海外版', '合作前景;反法西斯战争;', '本报北京7月11日讯　记者聂传清报道：中共中央政治局委员、北京市委书记刘淇今晚在北京饭店会见了由新党主席郁慕明率领的新党纪念抗战胜利60周年大陆访问团一行。刘淇认为，两岸同胞应该继续弘扬以爱国主义为核心的民族精神，共同为改善和发展两岸关系、促进两岸交流与合作', '2005-07-12 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4951, '报纸', '两岸同抗战，诠释“同是中国人”', '张勇', '新华每日电讯', '新华每日电讯', '一个中国原则;中华民族;抗战胜利;抗战精神;抗日战争胜利;', '北京的台湾问题专家及新党访问团成员11日下午在座谈中一致认为，中华民族之所以能够取得抗日战争的伟大胜利，根本原因在于爱国主义精神所产生的坚强的凝聚力和生命力。如今，在发展两岸关系上，两岸同胞应站在中华民族的立场上，加强合作，互利双赢，共同开创属于全体中国人', '2005-07-12 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4952, '报纸', '投笔从戎的“洋八路”', '董学清; 张民华', '新华社;', '人民日报海外版', '反法西斯;新四军;国际主义;', '●在延安见到毛泽东 希伯生于克拉科夫（现属波兰），后到德国上大学并加入德国共产党。通晓英、德、俄、波兰和中国5国文字。希伯不是他的原名，他的原名波兰文CRZYB，德文名Muller，英文名Hans Shppe。来到中国后，新四军卫生部长沈其震给他改名为汉斯·希伯。', '2005-07-11 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4953, '报纸', '老将军老战士及各界老同志参观抗战大型主题展', '张舵; 万一; 李煦', '人民日报', '人民日报', '世界反法西斯战争;', '新华社北京7月8日电　（记者张舵、万一、李煦）重新追忆往昔峥嵘岁月，感怀伟大民族精神，牢记历史，放眼未来…… 8日傍晚，夕阳西下，古老的宛平城安静祥和。500余位老将军、老战士及各界老同志走进修葺一新的中国人民抗日战争纪念馆，参观刚刚在这里开幕的“伟大', '2005-07-09 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4954, '报纸', '中华民族的伟大胜利', '冯春梅; 王建新', '人民日报', '人民日报', '八路军;中华民族;', '站在整面墙的抗日英雄谱前，杨平强一个一个仔细阅读着英雄的生平，不知不觉就是一个多小时。他告诉记者，他是河北承德人，现在北京做生意，7月8日一大早就赶到了中国人民抗日战争纪念馆参观。“我现在的感受可以用两个词概括：感动与震撼。没有这些英雄前仆后继，哪有我们现', '2005-07-09 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4955, '报纸', '新党大陆访问团抵达大连', '王金海; 申琳', '人民日报', '人民日报', '日本军国主义;', '本报大连7月8日电　记者王金海报道：今天15时30分，郁慕明率领的新党纪念抗战胜利60周年大陆访问团一行从南京飞抵此行的第三站大连。当晚，中共辽宁省委书记、省人大常委会主任李克强会见并宴请了访问团一行。 李克强对郁慕明一行表示欢迎。他指出，从甲午战争到日', '2005-07-09 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4956, '报纸', '捐献抗战文物 体现爱国热情', '丁国元', '工人日报', '工人日报', '中国人民抗日战争纪念馆;抗战时期;爱国热情;', '文物是物化的历史，历史题材的展览需要大量的具有较强冲击力和震撼力的文物资料来再现，这对建馆较晚、文物展品相对匮乏的中国人民抗日战争纪念馆来说，要办好7月7日开幕的《纪念中国人民抗日战争暨世界反法西斯战争胜利60周年大型主题展览》，存在着许多困难。在大型主题展', '2005-07-09 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4958, '报纸', '新党即将踏上“民族之旅”', '聂传清', '人民日报海外版', '人民日报海外版', '陈水扁;台北市;国民党;', '继连宋之后，台湾新党主席郁慕明也将于7月6日至13日率团访问大陆。该团名为“新党纪念抗日战争胜利六十周年大陆访问团”，将前往广州、南京、大连、北京四地进行为期八天的访问。新党的此次访问将再次奏响两岸交流的强音。 新党将此次访问称作“民族之旅”。郁慕明', '2005-07-05 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4959, '报纸', '不该忘却的纪念', '王玉芳', '人民日报', '人民日报', '中国美术家协会;世界反法西斯战争;雕塑家;', '高亢激昂的乐曲中，数千只和平鸽冲上蓝天，为纪念中国人民抗日战争暨世界反法西斯战争胜利60周年而举办的大型美术活动———“和平·繁荣”雕塑巡展于6月18日在长春世界雕塑公园拉开帷幕。来自全国的雕塑家、学者及7万余市民参观展览，感受浴血岁月。 出自全国70多', '2005-07-03 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4960, '报纸', '民族独立中流砥柱 伟大复兴时代先锋', '贾永; 刘刚', '新华社;', '新华每日电讯', '共产党人;中华民族;伟大复兴;民族独立;', '国破家亡关头，谁能凝聚力量？民族复兴之路，由谁开辟引航？ 60多年前，面对中华民族生死存亡，是中国共产党人挺身而出，肩负起救亡图存的历史重任；如今，当全面建设小康社会进入关键时期，担当率领中华民族奔向新征程时代使命的，同样是中国共产党人。 ', '2005-07-01 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened,中共七大1_screened,论持久战_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (4961, '报纸', '程子华同志诞辰100周年纪念座谈会在京举行', '邹声文', '人民日报', '人民日报', '程子华;民政部部长;纪念座谈会;', '新华社北京6月20日电　（记者邹声文）程子华同志诞辰100周年纪念座谈会20日在人民大会堂举行。中共中央政治局常委、全国政协主席贾庆林出席。 程子华是我国无产阶级革命家、我军卓越的指挥员和政治工作者、我国经济战线杰出的领导者，全国政协第五、六届副主席。1', '2005-06-21 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4962, '报纸', '刘爱芝同志逝世', '', '光明日报', '光明日报', '副总编辑;东北日报;光明日报社;', '本报讯　中国共产党的优秀党员、忠诚的共产主义战士、杰出的新闻工作者,原光明日报社副总编辑、离休干部刘爱芝同志,因病不幸于2005年6月17日逝世,享年81岁。  刘爱芝同志1924年10月13日生于山东省寿光县,1939年2月加入中国共产党。抗日战争时期,刘爱芝同志在家乡参', '2005-06-21 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4963, '报纸', '文艺之声20小时演绎“最长的一天”', '韩晓东', '中华读书报', '中华读书报', '反法西斯战争;文学作品;', '1944年6月6日，世界上有史以来最大的舰队运载着20多万陆军、海军和海岸巡逻队的士兵，在盟军最高统帅艾森豪威尔将军的指挥下，穿越英吉利海峡，驶向法国诺曼底。清晨六点半开始，在猛烈的军舰炮轰和飞机轰炸后，盟军士兵涉水登陆，浴血奋战，取得了决定性的胜利，史称“诺曼', '2005-06-01 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4964, '报纸', '61年前，他亲历诺曼底战役', '余靖静; 张乐', '新华每日电讯', '新华每日电讯', '驱逐舰;海上行动;抗日战争;值更官;黄山松;', '新华社记者余靖静、张乐报道  对87岁高龄的中国老人黄廷鑫来说，1944年6月6日永难忘记。人类历史上最大规模的登陆战这一天在诺曼底海滩打响，同时也奏响了第二次世界大战解放西欧的序曲。  61年弹指过，满头华发的黄廷鑫成了中国大陆唯一健在的诺曼底战役亲历者。', '2005-05-27 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4965, '报纸', '抗战中的“在华日人反战同盟”（下）', '陈劲松', '人民日报海外版', '人民日报海外版', '在华日人反战同盟;八路军;松野觉;日本兵;', '三、反战与牺牲 为促使日军士兵觉醒，瓦解日军斗志，反战同盟成员竭尽自己的聪明才智，借鉴八路军、新四军的对敌工作经验，创造出十几种行之有效的斗争方式与方法，如：印制日文传单、制作发放节日慰问袋、给日军中的熟人或朋友通信、在前线和碉堡前喊话等等，直攻日本', '2005-05-21 08:00:00', NULL, '抗日战争3_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4966, '报纸', '一位老省纪委书记的读书人生', '王乐乐', '中国纪检监察报', '中国纪检监察报', '岳麓书院;纪委书记;“文革”;新华书店;《实践论》;正规教育;', 'T在10年的省纪委书记的领导岗位上，他好学深思，学以致用，着力对纪检监察工作理论进行有益 的理性思考；退休7年，他读了73本书，写了4本书。原湖南省委常委、纪委书记杨敏之近日在岳麓 书院与记者恳谈了他的读书生涯及学习体会。E  读书不在于多', '2005-05-21 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4967, '报纸', '忆往昔垂首思过 维和平不遗余力', '米根孝', '中国民族报', '中国民族报', '飞虎队;抗日战争;侵华战争;慰安所;慰安妇;加害者;座谈会;', '5月18日下午2时，91岁的侵 华日军老兵本多立太郎走进中国民族 报社会议室，向在座的人们深深鞠躬， 为自己60多年前在中国犯下的罪行 忏悔。  本多立太郎先生虽然已经91岁 了，但身体硬朗，思惟敏捷。他向大家 讲述了60多年前，作为', '2005-05-20 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4968, '报纸', '历史不容忘记', '李文云', '人民日报', '人民日报', '南京大屠杀;世界反法西斯战争;', '经历一个甲子的漫长岁月，中国人对八年抗战和南京大屠杀等沉重历史的记忆决没有远去。 人们时常缅怀、祭奠那些为抗战、为不做亡国奴而付出鲜血和生命的杰出中华儿女。如今，在这个长得令人心痛的名单上又多了一个芳名———张纯如（Iris Chang）。她是著名美籍华裔畅销', '2005-05-10 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4969, '报纸', '难忘“5·9”这一天', '', '新华社;', '新华每日电讯', '欧洲战场;国民党第六次全国代表大会;《新华日报》;历史系;《朝日新闻》;', '没有熬不过的黑夜，没有盼不来的黎明。  1945年5月8日深夜。柏林郊区的卡尔斯霍尔斯 特。法西斯德国正式签署无条件投降书。饱受战火 蹂躏的欧洲终于迎来和平。  同一时刻，已是1945年5月9日的东方战场， 中国人民抗日战争已进入战略反攻。同仇', '2005-05-09 08:00:00', NULL, '抗日战争3_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4970, '报纸', '胜利的记忆　共同的纪念', '潘衍习', '人民日报海外版', '人民日报海外版', '世界反法西斯战争;俄罗斯;抗日战争胜利;爱好和平;反法西斯统一战线;', '今年，是全世界人民共同纪念世界反法西斯战争胜利60周年。中国人民还要纪念伟大的抗日战争胜利60周年，俄罗斯人民要纪念伟大的卫国战争胜利60周年。中国人民和俄罗斯人民在60多年前的那场世界反法西斯战争中，既是对抗共同敌人的盟友，也是并肩战斗的战友。 伟大的中国', '2005-05-06 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (4971, '报纸', '一位共产党人的炽热情怀', '曾毓善; 李立峰; 陈晓声', '中国纪检监察报', '中国纪检监察报', '共产党人;专题片;党的事业;将乐县;人民群众;', 'T他曾是一个老先进，1960年的《人民日报》曾大篇幅地报道他的事迹，中央新影厂还拍了专题片。  开国前，他曾为中华民族的解放冲锋陷阵；解放后，他曾为建设人民美好家园殚精竭虑；新时期， 他又为维护党的肌体的纯洁而不辞辛劳……当他微笑着离开我们，他对党', '2005-01-02 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4972, '报纸', '2004，永远的怀念', '', '中华读书报', '中华读书报', '文学博士学位;中国现当代文学研究;加入中国共产党;武汉大学;', '周而复，原名周祖式，笔名吴疑、荀寰等，1914年1月3日出生于南京，祖籍安徽旌德。1933年考入上海光华大学英文系后创作诗和小说，合编《文学丛报》和《小说家》月刊。1938年大学毕业后在延安、重庆等地作文艺和编辑工作。1939年2月加入中国共产党。先后任陕甘宁边区文化协会', '2004-12-22 08:00:00', NULL, '抗日战争3_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (4973, '报纸', '接过英雄丈夫的“接力棒”', '逄守江; 王庆伟; 卢军', '中国国防报', '中国国防报', '王玉林;三等功;', '□逄守江　王庆伟　本报特约记者　卢军 8月28日，笔者推开住在烟台某部干休所的殷咏雪老人的家门，只见她正专注地对照地图校对为丈夫撰写的回忆录第四稿。“快坐，快坐！”一边招呼我们，一边收拾着摆得满桌、满地的地图和军史资料，殷咏雪老人向我们打了话匣子……', '2004-09-23 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4974, '报纸', '《茶马古道》激情演绎多民族英雄群像', '孙雅莉', '中国民族报', '中国民族报', '电视连续剧;《茶马古道》;横断山脉;抗日战争;尼玛次仁;纳西族;民族英雄;傈僳族;电视制片人;澜沧江;', 'T古道、马帮，国难、家仇，奇异的自 然风光，厚重的人文景观，激荡的故事 情节，多民族文化元素──今天举行 开机仪式的电视连续剧《茶马古道》将 其融合在一起。通过多民族英雄人物 的塑造和多元民族文化的展现，这部 大型民族题材电视连续剧将再', '2004-09-03 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4975, '报纸', '在纪念任弼时同志诞辰一百周年座谈会上的讲话', '胡锦涛', '人民日报', '人民日报', '任弼时;领导人;毛泽东;共产党人;共产国际;座谈会;', '同志们，朋友们： 今天，我们在这里举行座谈会，隆重纪念任弼时同志诞辰一百周年。 任弼时同志是伟大的马克思主义者，杰出的无产阶级革命家、政治家、组织家，中国共产党和中国人民解放军的卓越领导人，以毛泽东同志为核心的中国共产党第一代领导集体的重要成员。', '2004-05-01 08:00:00', NULL, '抗日战争3_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (4976, '报纸', '红七军板寨会师旧址5月首度开放', '应春华', '中国民族报', '中国民族报', '红七军;中共党组织;张云逸;', '本报讯（记者 应春华）历经 战火和70多年风雨的红七军一、二 纵队会师旧址，经过1年的整修，将 于5月中旬在贵州省荔波县洞塘乡板 寨村首次向游人开放。届时，原红七 军部分将士、家属将应邀前来参加隆 重的纪念活动。这是该', '2004-04-30 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4977, '报纸', '曾威同志逝世', '', '人民日报', '人民日报', '天津警备区;军分区;', '新华社北京3月1日电　天津警备区原政治委员曾威同志（副兵团职待遇），因病于1月24日在北京逝世，享年88岁。 曾威是江西省泰和县人，1930年加入中国共产主义青年团，1931年参加中国工农红军，1932年加入中国共产党。土地革命战争时期，他历任战士、班长、特务员等职，参', '2004-03-25 08:00:00', NULL, '抗日战争3_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4978, '报纸', '硬六连——— 战旗为什么这样红', '李大伟; 翟启运', '新华社;', '人民日报', '硬骨头六连;硬六连;', '一帧年代久远的照片珍藏在“硬骨头六连”荣誉室里：1946年12月5日，毛泽东同志身着军大衣，在延安机场检阅为保卫边区立下赫赫战功的部队，六连就挺立于受阅部队的行列。 诞生于抗日战争烽火中的六连，曾作为八路军120师的一把尖刀，转战华北、西北战场，以敢于冲锋陷阵', '2004-01-06 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4979, '报纸', '吴子杰同志逝世', '', '人民日报', '人民日报', '山西;参加;', '新华社北京12月9日电　沈阳军区原顾问吴子杰同志（大军区副职），因病于11月24日在北京逝世，享年91岁。 徐才厚等领导同志以不同方式，对吴子杰同志的逝世表示哀悼。 吴子杰是湖北天门人，1930年参加中国工农红军，1932年加入中国共产主义青年团，同年加入中国共产', '2004-01-04 08:00:00', NULL, '抗日战争3_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4980, '报纸', '伟人毛泽东——光辉永在的名字', '', '光明日报', '光明日报', '战略家;编辑部;中央民族大学;毛泽东军事思想;二十世纪;毛主席;伟人毛泽东;毛泽东思想研究;当代中国研究所;新闻出版总署;', ' F世界性的伟人E 《伟人毛泽东》丛书的出版，是理论界、图书出版界一件重要的事情。这部丛书汇集了众多的革命家、理论家关于毛泽东和毛泽东思想研究的重要成果，全方位地反映了毛泽东伟大的一生，反映了他的政治、经济、军事、外交、文化等各个方面的理论', '2003-10-30 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4981, '报纸', '党对军队的绝对领导是我军永远不变的军魂', '', '解放军报', '解放军报', '敌对势力;人民军队;中国特色军事变革;军队非党化;党对军队的绝对领导;', '从历史规律深刻理解我军军魂永远不变●卫晋  江泽民同志在总结我军建设历史经验的基础上明确指出：“一个军队要有军魂。我看，我们军队的军魂就是党的绝对领导。”他还多次强调，“党对军队的绝对领导是我军永远不变的军魂”。这一科学论断中，“永远不变”四个字', '2003-09-17 08:00:00', NULL, '抗日战争3_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4982, '报纸', '烽烟滚滚唱英雄', '汪泾洋', '解放军报', '解放军报', '新四军;', '26集电视连续剧《新四军》，以准确的史料和扣人心弦的情节，讴歌了新四军将士为了民族和人民的解放，不屈不挠，前赴后继，英勇斗争的精神，成功地塑造了叶挺、项英、陈毅、刘少奇、粟裕等一大批新四军将士的光辉形象，弘扬了革命英雄主义的精神。日前，记者访问了这部电视剧', '2003-08-29 08:00:00', NULL, '抗日战争3_screened,项英');
INSERT INTO `ds_article` VALUES (4983, '报纸', '毛泽东著作旧版探源', '', '中国商报', '中国商报', '毛泽东著作;', '毛泽东在解放前的著作，已成为藏书家们热烈寻求的红色藏品，认真考察其著作和出版的情况，才能评估其历史价值与经济价值。 毛泽东的名言：“没有调查就没有发言权”。表明了他对讲话、写文章、出书是何等的严肃认真。他告诫人们“文章是客观事物的反映，而事物是曲折复', '2003-07-24 08:00:00', NULL, '抗日战争3_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (4984, '报纸', '龙书金同志逝世', '', '人民日报', '人民日报', '广州;广东;参加;', '新华社广州5月7日电　原新疆军区司令员龙书金同志，因病医治无效，于4月16日在广州逝世，享年93岁。 龙书金同志是湖南省茶陵县人，1929年参加农民赤卫队，1930年编入中国工农红军，同年加入中国共产主义青年团，1932年转为中国共产党党员。土地革命战争时期，他历任班长', '2003-05-13 08:00:00', NULL, '抗日战争3_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (4985, '报纸', '解力夫：笔走惊雷写春秋', '李升旗', '中国民族报', '中国民族报', '抗日战争;', '解力夫，一个对于中国 亿万读者来说并不陌生的名 字。他以描写第二次世界大 战的风云人物而著称。  文学评论界称解力夫为 “中国当代的蔡东藩”，这是 再恰当不过的了。作为新闻 记者，因采访和写作任', '2003-05-09 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4986, '报纸', '何自坚：笑度人生一百年', '罗昌爱', '人民日报', '人民日报', '龙州起义;红八军;农工民主党;', '春暖花开，踏着稳健的步履漫步青秀山公园，一双有力的手握得年轻人直喊疼———当年跟随邓小平参加并领导震惊中外的广西龙州起义———原中国工农红军第八军第一纵队司令员何自坚老人，4月15日在广西南宁笑度他100岁高龄的生日。 下午，广西农工民主党为何自坚老人举行', '2003-05-08 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4987, '报纸', '纪念邓兆祥诞辰一百周年座谈会在京举行', '李术峰', '人民日报', '人民日报', '全国人大常委会;座谈会;', '新华社北京4月25日电（记者李术峰）　纪念著名爱国主义者、中国共产党的优秀党员、中国人民解放军优秀领导干部邓兆祥同志诞辰100周年座谈会，25日在全国政协礼堂举行。中共中央政治局常委、全国政协主席贾庆林出席座谈会。 邓兆祥1914年3月考入黄埔海军学校，后来陆续在', '2003-04-26 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4988, '报纸', '继往开来', '', '光明日报', '光明日报', '孙中山;毛泽东;社会主义;民主革命;', '问：纵观历经沧桑的过去，展望充满希望的未来，我们从中可以汲取的丰富经验和巨大动力应该是非常多的。 重庆师范学院历史系教授管维良：我们要铭记中华民族的先人，他们创造了灿烂的中华文明，以东方的智慧和中国人的气度，为我们提出了关于大同的思想。纵观历史，我', '2003-02-01 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4989, '报纸', '郑洞国诞辰100周年纪念座谈会举行', '潘跃', '人民日报', '人民日报', '纪念座谈会;全国政协副主席;社会主义;', '本报北京1月13日讯　记者潘跃报道：民革中央今天在京举行纪念郑洞国诞辰100周年座谈会。 郑洞国是我国著名爱国民主人士、抗日将领、中国国民党革命委员会卓越的领导人。郑洞国1924年考入黄埔军校第一期。1925年到1928年，他先后参加了东征北伐。抗日战争爆发后，他', '2003-01-14 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4990, '报纸', '纪念罗荣桓同志诞辰一百周年', '罗玉文', '人民日报', '人民日报', '罗荣桓;江泽民;曹刚川;座谈会;伟大旗帜;总政治部主任;', '新华社北京11月26日电（记者罗玉文）　中央军委今天在人民大会堂举行座谈会，隆重纪念久经考验的无产阶级革命家、军事家，党、国家和军队的卓越领导人，中国人民解放军的创建人之一罗荣桓同志诞辰100周年。国家主席、中央军委主席江泽民出席座谈会并发表重要讲话。中共中央', '2002-11-27 08:00:00', NULL, '抗日战争3_screened,遵义会议_screened,秋收起义_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4991, '报纸', '在纪念罗荣桓同志诞辰一百周年座谈会上的讲话', '江泽民', '人民日报', '人民日报', '罗荣桓;山东抗日根据地;党对军队的绝对领导;座谈会;', '同志们： 今天，中央军委在这里举行座谈会，隆重纪念罗荣桓同志诞辰一百周年。罗荣桓同志是久经考验的无产阶级革命家、军事家，我们党、国家和军队的卓越领导人，中国人民解放军的创建人之一。他为人民军队的成长壮大，为中国人民的解放和社会主义建设事业做出了重大贡', '2002-11-27 08:00:00', NULL, '抗日战争3_screened,反围剿_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (4992, '报纸', '历史辉映未来', '孙承斌; 朱玉; 李术峰', '新华社;', '人民日报', '马文瑞;建设有中国特色社会主义;江泽民同志;张劲夫;王世泰;毛泽东思想;李葆华;九旬老人;党的理论;共产党人;全面建设小康社会;十六大;党的十五大;时代主题;', '丰收的季节迎来一个庄严的日子———2002年11月8日，中国共产党将举行新世纪的第一次全国代表大会，为进入全面建设小康社会、加快推进社会主义现代化新阶段的中国规划新的蓝图。 刘华清、薄一波、张劲夫、谷牧、马文瑞、陈慕华……盛会前夕，我们走访一位位德高望重的', '2002-11-08 08:00:00', NULL, '抗日战争3_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (4993, '报纸', '中国百姓营救美国飞行员的故事', '谭新木', '新华社;', '新华每日电讯', '飞行员;无名战士墓;卡罗尔;', 'T在华盛顿，美国老兵与中国老人为生死情谊而紧紧握手。此情 此景，人们不禁忆起当年中美携手抗击共同敌人的难忘岁月E  深夜，罗光甫背着卡罗 尔回村疗伤  84岁的卡罗尔很少向家人说起', '2002-10-20 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4994, '报纸', '侯镜如百年诞辰纪念座谈会举行', '崔士鑫; 潘跃', '人民日报', '人民日报', '侯镜如;中国国民党革命委员会;爱国统一战线;纪念座谈会;百年诞辰;', '本报北京10月17日讯　记者崔士鑫、潘跃报道：民革中央今天在京举行纪念著名的政治活动家、爱国将领、中国国民党革命委员会杰出的领导人侯镜如诞辰100周年座谈会。 中共中央政治局常委、全国政协主席李瑞环出席座谈会。 侯镜如1924年5月进入黄埔军校第一期学习', '2002-10-18 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4995, '报纸', '纪念黄克诚诞辰一百周年座谈会在京举行', '曹智', '人民日报', '人民日报', '黄克诚;中央军委;座谈会;', '新华社北京9月20日电（记者曹智）　纪念杰出的无产阶级革命家、军事家，党和军队的卓越领导人黄克诚诞辰100周年座谈会今天在人民大会堂举行。中共中央政治局委员、书记处书记、中央军委副主席张万年出席座谈会，并发表讲话。 张万年在讲话中高度评价了黄克诚光辉战', '2002-09-21 08:00:00', NULL, '抗日战争3_screened,血战湘江_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (4996, '报纸', '纪念关向应同志诞辰100周年', '罗玉文; 郭嘉', '新华社;', '人民日报', '关向应;张万年;国民党军;', '本报北京9月10日讯　新华社记者罗玉文、本报记者郭嘉报道：中央军委今天在人民大会堂举行座谈会，纪念忠诚的共产主义战士，坚定的马克思主义者，老一辈无产阶级革命家，中国工农红军和八路军高级指挥员、卓越的政治工作领导者关向应同志诞辰100周年。中央政治局委员、书', '2002-09-11 08:00:00', NULL, '抗日战争3_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (4997, '报纸', '亓谦斋同志逝世', '', '人民日报', '人民日报', '政治指导员;', '新华社北京7月17日电 原铁道兵副司令员亓谦斋同志，因病医治无效，于7月8日在北京逝世，享年82岁。 迟浩田、张万年、张震、洪学智等分别以不同的方式，对亓谦斋同志的逝世表示深切悼念。 亓谦斋同志是山东莱芜人，1939年参加八路军，同年加入中国共产党。抗日战', '2002-07-18 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4998, '报纸', '莫春和同志逝世', '', '人民日报', '人民日报', '参加;', '新华社北京7月9日电 贵州省军区原副司令员莫春和同志（副兵团职），因病于6月29日在北京逝世，享年87岁。 莫春和同志是四川阆中人，1933年参加中国工农红军，1934年加入中国共产主义青年团，1936年转入中国共产党。土地革命战争时期，他历任战士、译电员等职，参加了', '2002-07-16 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (4999, '报纸', '王昆仑诞辰100周年纪念座谈会举行', '张忠; 潘跃', '人民日报', '人民日报', '王昆仑;纪念座谈会;中国共产党领导;', '本报北京6月19日讯 记者张忠、潘跃报道：民革中央今天在人民大会堂举行王昆仑同志诞辰100周年纪念座谈会。中共中央政治局常委、全国政协主席李瑞环出席座谈会。 王昆仑是我国忠诚的爱国民主战士、著名的政治活动家、中国国民党革命委员会卓越领导人。他1922年参加国', '2002-06-20 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5000, '报纸', '峥嵘岁月 侨史佳话', '连锦添', '人民日报海外版', '人民日报海外版', '陈嘉庚;中国侨联;', '5月28日，中国侨联爱国主义教育基地在延安侨联旧址揭牌。地点在王家坪原中央军委机关合作社和军人俱乐部原址，距毛泽东故居仅百米之遥。在这所几十平方米的平房里，当年延安侨联的归侨们经常在这里举办报告会、联欢会等活动。如今整修后辟为侨史陈列室。 数百幅珍贵的', '2002-06-06 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (5001, '报纸', '习仲勋同志生平', '', '人民日报', '人民日报', '习仲勋;中共中央西北局;革命根据地;刘志丹;中央书记处;全国人民代表大会常务委员会;', '中国共产党的优秀党员，伟大的共产主义战士，杰出的无产阶级革命家，我党、我军卓越的政治工作领导人，陕甘边区革命根据地的主要创建者和领导者之一，国务院原副总理，中国共产党第十一届中央委员会书记处书记，第十二届中央政治局委员、书记处书记，第五届、第七届全国', '2002-05-31 08:00:00', NULL, '抗日战争3_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (5002, '报纸', '肖健章同志逝世', '', '人民日报', '人民日报', '广州军区空军;', '新华社武汉5月16日电 原武汉军区空军副司令员肖健章同志（副兵团职），因病于4月5日在武汉逝世，享年78岁。 肖健章同志是湖北安陆人，1939年入伍，当年加入中国共产党。抗日战争时期，他历任连政治指导员、科长等职，参加了大悟山阻击战和中原突围战役。解放战争时', '2002-05-29 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5003, '报纸', '弘扬《讲话》精神　发展先进文化', '', '光明日报', '光明日报', '文艺工作者;延安文艺座谈会;毛主席;江泽民同志;军队文艺;马克思主义文艺理论;《讲话》;毛泽东文艺思想;《讲话》精神;发展先进文化;', '继往开来拓展我国文艺事业新天地文化部副部长　陈晓光 1942年，毛泽东同志在延安杨家岭窑洞前，发表了著名的《在延安文艺座谈会上的讲话》。60年过去了，重温《讲话》，我们心潮激荡，思绪万千。 《讲话》立足于民族解放的现实要求，总结了新文化运动以来的历史', '2002-05-23 08:00:00', NULL, '抗日战争3_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (5004, '报纸', '倡建保护区　魂系大竹岚', '李荣禄', '武夷山自然保护区管理局;', '光明日报', '综合科学考察;', '在福建武夷山国家级自然保护区，提起赵修复教授，可谓家喻户晓，人人皆知。人们都知道赵教授是建立武夷山保护区的倡议人，但对赵教授与武夷山保护区有着一生的不解情缘，却知之甚少。 远在抗日战争时期，赵先生在当时内迁在邵武的协和大学生物系任助教时，即到当时', '2002-05-04 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5006, '报纸', '在纪念谭震林同志诞辰一百周年座谈会上的讲话', '胡锦涛', '新华每日电讯', '新华每日电讯', '无产阶级革命家;共产党人;座谈会;', '同志们：  在谭震林同志诞辰一百周年之 际，我们相聚一堂，缅怀他的革命历 史，追思他的卓越功勋，学习他的优秀 品质，这对于大力弘扬老一辈无产阶 级革命家的崇高精神，坚定不移地推 进建设有中国特色社会主义伟大事 业，是很有意', '2002-04-16 08:00:00', NULL, '抗日战争3_screened,抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5007, '报纸', '结合新实际大力弘扬延安精神开创新世纪改革发展生动局面', '单向前; 孟西安', '人民日报', '人民日报', '延安精神;江泽民;农村基层党组织建设;', '本报西安4月2日电 记者单向前、孟西安报道：中共中央总书记、国家主席、中央军委主席江泽民近日在陕西考察工作。他强调，在新的历史条件下，在充满新的希望、也充满新的挑战的征途上，我们始终要大力弘扬延安精神。延安精神，体现了我们党马克思主义政党的性质，体现了我们党', '2002-04-03 08:00:00', NULL, '抗日战争3_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5008, '报纸', '侯老驾鹤西去', '宋安明', '检察日报', '检察日报', '最高人民检察院;政治部主任;', '本报北京3月28日讯　记者宋安明报道　哀乐低回，寄托着人们对这位久经风雨的老红军的绵绵哀思；鲜花、翠柏丛中，安放着中国共产党优秀党员，久经考验的忠诚的共产主义战士，最高人民检察院原检察委员会委员侯政同志（享受部长级待遇）的遗体。侯政同志因病于2002年3月2日5时', '2002-03-29 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5009, '报纸', '重庆抗日战争历史博物馆何时能建？', '周少诚; 段明良', '人民政协报', '人民政协报', '抗日战争;历史博物馆;', '本报讯（记者周少诚 通讯员段明良）日前，在重庆市 政协一届六次全会上，徐朝鉴委员提交的“恳请建立重庆抗日 战争历史博物馆”的书面发言，引起了与会委员的强烈共鸣。  重庆是抗日战争时期中国的战时首都和陪都，是当时', '2002-01-25 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5010, '报纸', '中国民族工作的第一个经验总结', '江平', '中共中央统战部;', '中国民族报', '经验总结;地方民族主义;杨静仁;汉族地区;少数民族地区;第一个;', '1953年7月召开的全国统战工作会 议通过了《关于过去几年内党在少数民族 中进行工作的主要经验总结》（以下简称 《主要经验总结》）。这是中国共产党关于民 族工作所做的第一个系统的经验总结。在 全', '2002-01-15 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5011, '报纸', '中缅边境找到美机残骸', '杨清舜; 范卉', '德宏团结报;新华社;', '新华每日电讯', '日本鬼子;傈僳族;李永美;驼峰航线;中缅边境;', '20世纪40年代，在喜马拉雅山 东南麓开辟的著名“驼峰航线”上， 中美两国有1500余名飞行员牺牲和 514架飞机坠毁，为中国抗日暨世界 反法西斯战争做出卓著贡献。  就在2001年岁末，人们在“', '2002-01-03 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5012, '报纸', '纪念徐向前同志诞辰百年', '王文杰; 罗玉文', '解放军报;新华社;', '新华每日电讯', '徐向前;红四方面军;', '新华社北京11月7日电（解放军报记 者王文杰新华社记者罗玉文）中央军委 今天在人民大会堂举行座谈会，隆重纪念 忠诚的共产主义战士，坚定的马克思主义 者，久经考验的无产阶级革命家、军事家，', '2001-11-08 08:00:00', NULL, '抗日战争3_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (5013, '报纸', '《丰碑——中国共产党80年奋斗与辉煌》', '', '学习时报', '学习时报', '马克思主义中国化;中国共产党;《丰碑——中国共产党80年奋斗与辉煌》;江泽民同志;共产国际;', '铸造新的理论丰碑 ──在党史系列丛书《丰碑》出版座谈会上的讲话  党史系列丛书《丰碑── 中国共产党80年奋斗与辉煌》 问世了，值得我们大家一起来 庆贺吗？我想是值得的。因为这 几年党史方面的书出得并不', '2001-10-29 08:00:00', NULL, '抗日战争3_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5014, '报纸', '王从吾同志遗体送别活动在京举行', '', '中国纪检监察报', '中国纪检监察报', '王从吾;中央纪委;监察部;', '本报讯：中国共产党的优 秀党员，久经考验的忠诚的共 产主义战士，我党纪律检查工 作和监察工作的杰出领导干 部，原中共中央顾问委员会委 员，中共中央纪律检查委员会 原书记王', '2001-10-19 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5015, '报纸', '吴志远同志逝世', '', '人民日报', '人民日报', '华北军区;', '新华社北京9月24日电：北京军区后勤部政治部原主任 吴志远同志（副兵团职待遇），因病于8月12日在北京逝世，享 年93岁。  吴志远同志是江西省波阳县人，1931年加入中国工农红 军，1935年加入中国共产党，历任文书、技术书记、晋察冀军区 政治', '2001-10-18 08:00:00', NULL, '抗日战争3_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (5016, '报纸', '卢沟桥畔的道歉和反省', '杨国强; 倪四义; 车玉明', '新华每日电讯', '新华每日电讯', '日本军国主义;全面侵华战争;中国人民抗日战争纪念馆;卢沟桥畔;', '“参观中国人民抗日战争纪念馆，我再次深刻认识到战争的悲 惨，谨向遭受侵略而死难的中国人民表示衷心的道歉和哀悼。”  今天，日本首相小泉纯一郎来到北京西南的卢沟桥畔，向中国 抗日英烈群雕鞠躬、默哀、敬献花圈，并', '2001-10-09 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5017, '报纸', '燃烧的记忆', '张宝印; 张明军', '新华社;中央人民广播电台;', '新华每日电讯', '九·一八;历史博物馆;尚志市;沈阳市;历史遗址;伪满皇宫博物院;柳条湖;', '“九·一八”，一个永远不能忘却 的日子，一个让人刻骨铭心的日子。  在“九·一八”事变70周年到来的 日子里，曾经饱受战争创伤的东北军 民，又一次沉浸在回忆和激愤之中， 白山黑水间响', '2001-09-18 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5018, '报纸', '江泽民的讲话', '', '新华每日电讯', '新华每日电讯', '新四军;江泽民;红四军;', '同志们：  今天，中央军委在这里举行座谈会， 纪念陈毅同志诞辰一百周年。陈毅同志 是久经考验的无产阶级革命家、军事家、 外交家，中国人民解放军的创建者和领 导者之一，党和国家的卓越', '2001-08-24 08:00:00', NULL, '抗日战争3_screened,红四军_screened');
INSERT INTO `ds_article` VALUES (5019, '报纸', '谴责日本首相参拜靖国神社', '', '新华每日电讯', '新华每日电讯', '日本首相;南京大屠杀;历史教科书;九·一八;靖国神社;', '新华社北京8月15日电：辽宁、江苏、甘肃等地群众今天举 行活动，纪念发动侵华战争的日本帝国主义在56年前的今天 宣布投降，中国人民艰苦卓绝的抗日战争取得全面胜利。  辽宁省的一些专家学者上午在沈阳“九·一八”历史博物 馆举行纪念抗战胜利座谈', '2001-08-16 08:00:00', NULL, '抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5020, '报纸', '历史，在这里沉思', '李术峰; 王思海', '新华每日电讯', '新华每日电讯', '中国人民抗日战争;日本军国主义;', '岁月的风雨，掩不住累累的弹 痕；桥头的石狮，似乎依然挥不去那 惨烈的一幕……在纪念“8·15”日 本投降的日子，北京卢沟桥凭吊者 络绎不绝──正是从这里，中华民 族发展史掀开最为残酷的一页；正 是在这里，中国军队打响了全面抗 击日', '2001-08-16 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5021, '报纸', '强烈谴责日本首相参拜靖国神社', '', '新华每日电讯', '新华每日电讯', '日本首相;靖国神社;', '新华社南京8月14日电：在纪 念抗日战争胜利56周年之际， 辽沈地区各界人士及在南京、 哈尔滨的中、日、韩三国学者今 天分别集会，强烈谴责日本首相 小泉纯一郎参拜靖国神社。  辽沈地区参加集会的有当年 “九·一八”事变的见证人、', '2001-08-15 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5022, '报纸', '农民利益再小也是大事', '郝富友; 魏永刚; 马小林', '农民日报', '农民日报', '农民利益;实践“三个代表”;', '盛夏的上党盆地生机盎然。八路军总部旧址武乡县王家峪的村口，那棵“红星杨”枝繁叶茂。记者弯腰拾起一截树枝，掰开一看，截面上一颗红星正向你眨着眼睛。  当年目睹朱德同志种下这棵白杨树的老党员朱银江，今年81岁了，他向我们回忆起过去的岁月：当年，朱德总司令', '2001-07-28 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5023, '报纸', '重访延安看变化', '孟西安', '人民日报海外版', '人民日报海外版', '南泥湾;安塞县;', '延安，是中国革命的圣地，是新中国的摇篮。  在庆祝建党80周年之际，记者再一次回到延安，看到延河之 上，彩虹铁桥飞架；宝塔山下，高楼新厦林立，道路平展宽阔，山峁 开始变绿，心中不禁泛起一阵惊喜。曾在1956年写过《回延安》著 名诗篇的76岁高', '2001-07-12 08:00:00', NULL, '抗日战争3_screened,枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5024, '报纸', '共产国际对毛泽东的关注', '倪迅; 翟伟', '光明日报;新华社;', '新华每日电讯', '共产国际;毛泽东;季米特洛夫;', '（记者追述：毛泽东与共产国际的关系，一直是党史界 关心的问题。因为毛泽东探索的中国革命独特的道路，不同 于苏联道路，引起过共产国际的怀疑和不满。但是毛泽东在 扩大的六届六中全会上被确立为全党的领袖，也得到了共', '2001-07-05 08:00:00', NULL, '抗日战争3_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (5026, '报纸', '“没有知识分子是不行的”', '倪迅', '光明日报', '光明日报', '知识分子;李四光;毛泽东;郭沫若;', '毛泽东在我国革命和建设不同时期，对知识分子问题都提 出了重要思想；在领导革命和建设的每个重大关头，都十分重视 知识分子的作用。  毛泽东很欣赏舒同的文章和书法。两人经常 切磋书法，在江西苏区毛泽东就送给舒同两个 “雅号”，一个是“', '2001-06-26 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5028, '报纸', '光辉永在的文字', '', '光明日报', '光明日报', '兵民是胜利之本;新四军;社会主义;《论持久战》;', '论持久战  《论持久战》是毛泽东1938年5月26日至6月 3日在延安抗日战争研究会上的讲演，同年7月1 日在延安解放周刊社出版的《解放》第43、44期合 刊上首次发表，题为《论持久战──论抗日战争为 什么是持久战与最后', '2001-06-21 08:00:00', NULL, '抗日战争3_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (5029, '报纸', '日破云涛万里红', '贺劲松; 陈芳; 张旭东', '新华每日电讯', '新华每日电讯', '党的十一届三中全会;万里红;抗日战争;中国共产党;江泽民同志;', '80载风雨兼程，中国共产党闯过生死攸关 的重重险阻。  80度春华秋实，中国共产党写下可歌可泣 的光辉历史。  在光辉而曲折的80年艰辛历程中，我们党 创造了惊世的辉煌，也曾有过严重', '2001-06-15 08:00:00', NULL, '抗日战争3_screened,遵义会议_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (5030, '报纸', '永不凋谢的信念与追求', '徐江善; 王蔚', '新华每日电讯', '新华每日电讯', '陈琮英;共产党人;党的宗旨;任弼时;共产主义;全心全意为人民服务;博士生;', '从大革命失败的血雨腥 风走来，从枪林弹雨艰苦卓 绝的战争年代走来，从共和 国诞生喜庆的礼炮声中走来， 从改革开放明媚的阳光中走 来……  一代代共产党人的信念', '2001-06-12 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5031, '报纸', '浩荡依然六十年', '王立彬', '新华社;', '新华每日电讯', '宗派主义;延安整风运动;六十年;', '60年前的延安整风运动，在 我党历史上具有深远的历史意义， 是党的建设史上的一个伟大创举。 通过延安整风运动，全党确立了一 切从实际出发、理论联系实际、实 事求是的辩证唯物主义的思想路', '2001-06-07 08:00:00', NULL, '抗日战争3_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5032, '报纸', '何长工百年诞辰纪念座谈会举行', '潘跃', '人民日报', '人民日报', '何长工;纪念座谈会;百年诞辰;', '本报北京12月8日讯：记者潘跃 报道：全国政协今天在京举行座谈 会，纪念中国共产党久经考验的忠诚 的共产主义战士、老一辈无产阶级革 命家、卓越的军事家、军事教育家何 长工同志诞辰100周年。中共中央政 治局常委、全国政协主席李瑞环出席', '2000-12-09 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5033, '报纸', '胡绳同志生平', '', '新华每日电讯', '新华每日电讯', '中共中央党史研究室;中共中央南方局;统一战线工作;', '新华社北京11月12日电：中国共产党的优 秀党员，久经考验的忠诚的共产主义战士， 无产阶级革命家，著名的马克思主义理论家、 历史学家，中国人民政治协商会议第七、八届 全国委员会副主席胡绳同志，因病于2000年11 月5日8时10分在上海逝世，享年82', '2000-11-13 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5034, '报纸', '首都举行抗战胜利五十五周年纪念演出', '沈路涛', '人民日报', '人民日报', '抗日战争胜利;抗战胜利;革命文艺;', '新华社北京9月17日电 （记者沈路涛）为纪念中国人民 抗日战争胜利55周年，缅怀在 八年抗战中艰苦斗争、流血牺 牲的人们，中国老教授协会文 化艺术专业委员会今晚在中国 儿童剧场举行抗日战争胜利55 周年纪念演出。中共中央政治 局委', '2000-09-18 08:00:00', NULL, '抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5035, '报纸', '《粟裕传》出版座谈会在京举行', '罗玉文', '人民日报', '人民日报', '《粟裕传》;座谈会;', '新华社北京8月31日电（记者 罗玉文） 《粟裕传》出版座谈会今天在北京举行。中共 中央政治局委员、书记处书记、中央军委副主 席张万年出席座谈会并讲话。  张万年在讲话中代表中央军委对《粟裕 传》的出版表示热烈的祝贺。他说，粟裕同志', '2000-09-01 08:00:00', NULL, '抗日战争3_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (5036, '报纸', '用艺术作品向全世界宣告：百年伟业来自于人民', '刘森; 薛帅', '中国文化报', '中国文化报', '艺术作品;共产党;党中央;党史学习;中国共产党成立;习近平;交响化;入党申请书;艺术手段;全世界;', '“伟大的中国共产党，乘风破浪，扬帆远航!领航中国在新时代的征程上!领航中国在新时代的征程上……” 6月28日，当《领航》磅礴恢弘的歌声在国家体育场响起，历时两年创意策划、数月排演的庆祝中国共产党成立100周年文艺演出大型情景史诗《伟大征程》完美收官。 序幕“', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.002070', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5037, '报纸', '贾潜：被毛泽东“钦点”审判日本战犯', '赵利丽', '人民法院报', '人民法院报', '最高人民法院;武部六藏;审判庭庭长;审判日本战犯;毛泽东;', '“今天我站在我们祖国庄严的法庭上，对日本帝国主义分子战犯武部六藏、古海忠之，奉行侵略政策，操控伪满洲国政权，奴役东北人民的罪行作证。” 1956年7月2日，沈阳特别军事法庭上，伪满洲国皇帝溥仪出庭指控战犯古海忠之等在中国犯下的滔天罪行。 审判席正中坐着的审', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003067', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5038, '报纸', '王稼祥与抗日民族统一战线', '孙建猛', '湘潭大学马克思主义学院;', '团结报', '王稼祥;任弼时;抗日民族统一战线;共产国际;', '1937年6月，王稼祥因伤病严重，赴苏联疗伤，后在共产国际的要求下担任了中共驻共产国际代表。此后，一直到1938年8月回到延安，王稼祥才彻底告别滞留共产国际的时期。王稼祥在担任共产国际代表前后，对抗日民族统一战线工作作出了积极贡献。 对国内抗日民族统一战线的思考', '2021-05-20 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001035', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5039, '报纸', '完善基础设施建设支持乡村振兴', '刘安天', '中国会计报', '中国会计报', '庆阳市;革命老区;基础设施建设;车购税;习近平总书记;镇原县;', '全面实施乡村振兴战略是未来一段时期党和国家重点推进的重要战略。其中，提升乡村基础设施建设水平是重要的组成部分。 过去，甘肃省庆阳市的公路基础设施建设稍显落后。这在未来有可能制约乡村振兴战略的全面推进。基于此，全国政协委员、立信会计师事务所甘肃分所所长张', '2021-03-12 08:00:00', 'https://link.cnki.net/doi/10.38301/n.cnki.nzgkj.2021.000303', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5040, '报纸', '毛泽东战争年代的新闻作品', '王凯捷', '中共天津市委党史研究室;', '团结报', '毛泽东;新华社;国民党军队;解放战争;新闻作品;', '在长期的革命生涯中，毛泽东十分重视新闻的战斗和舆论作用，曾为新华社撰写和修改了大量的新闻稿件。这些文稿，从一个侧面反映了中国革命艰苦和辉煌的历程，具有重要的文献价值和历史意义。同时，毛泽东亲笔撰写的新闻文稿，与他的文章和诗词一样，不仅具有战略思维的大手笔', '2021-01-07 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.000056', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5041, '报纸', '红色家风培育家庭文明新风尚', '', '中国妇女报', '中国妇女报', '新风尚;', '我是来自天津滨海新区塘沽海关的党群，党员的“党”，群众的“群”。习近平总书记教导我们要继承和弘扬革命前辈的红色家风。我出生在红色家庭，爷爷是一名经历过抗日战争、解放战争血与火洗礼的老兵，他给我取这个名字，就是对党和人民充满挚爱，就是让子孙不能忘记党和人民', '2020-11-23 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2020.003206', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5042, '报纸', '9月3日，请所有战胜国都莫忘初心', '', '环球时报', '环球时报', '俄罗斯;华盛顿;', '9月3日是中国抗日战争胜利75周年，俄罗斯将二战结束纪念日从9月2日调成9月3日后，中俄两国首次同庆战胜日本军国主义。在夏威夷，美国于当地时间9月2日也举行了庆祝活动，美国的庆祝活动与中俄从来都是分开搞的。 中国、俄罗斯同美国共为二战中的盟友，可惜的是，战争结束7', '2020-09-04 08:00:00', 'https://link.cnki.net/doi/10.28378/n.cnki.nhqsb.2020.007894', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5043, '报纸', '汲登百丈路迢迢', '李亦奕', '中国文化报', '中国文化报', '徐悲鸿;美术馆;《巴人汲水》;宗其香;李可染;重庆江北;张安治;中央美术学院;廖静文;嘉陵江畔;', '在重庆江北，有这么一座古宅经历过抗战那段动荡艰辛的岁月，它耸立在盘溪山头八十多载，秘密收藏过10余万册抗日时期的珍贵史料，创办过中国美术学院及私立蜀都中学，这座古宅就是位于江北盘溪的“石家花园”。 百年老宅的前世今生 石家花园始建于1931年，是一处比较典', '2020-07-05 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2020.000927', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5044, '报纸', '为了人民勇往直前', '郭凤海', '国防大学习近平新时代中国特色社会主义思想研究中心;', '解放军报', '人民军队;疫情防控;', '编者按 新冠肺炎疫情发生后，全军部队坚决贯彻党中央、中央军委决策号令，闻令而动、勇挑重担，不负重托、不辱使命，为打赢疫情防控人民战争、总体战、阻击战作出突出贡献。 从强军文化的视角看，在此期间，人民子弟兵展现的忠于党、忠于人民的政治品格，能打仗、打胜', '2020-05-07 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2020.002331', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5045, '报纸', '从三个历史断面看“两论”的思想光芒', '孙东生', '中央党校(国家行政学院)省部班;民建中央;', '学习时报', '“两论”;战略决战;中国特色社会主义事业;', '82年前，延安窑洞里诞生了伟大的《实践论》和《矛盾论》，毛泽东第一次对“认识与实践相统一”和“矛盾普遍性与特殊性相统一”作了系统阐释，丰富和发展了党的创新理论。在革命战争、改革开放和伟大复兴的三个历史断面中，“两论”揭示的哲学思想、阐明的基本原理，始终闪烁', '2019-10-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR0XZxdKtiIVTRs7UKRbq0LbavnsIZKeR73CV7d4T-_votVpDy15oEUxaaEQEx0bYnJbzcBr3oW0iBkH6KuF1rxXdhsdP8qOTxOLxpV1D-spm4q-nDaBbt-fAoQUysP3wVdcV37Q1AY5Q==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (5046, '报纸', '祖国，请您检阅', '李宣良; 梅世雄', '新华每日电讯', '新华每日电讯', '常规导弹;空中梯队;天安门广场;', '“今天是你的生日，我的中国。清晨，我放飞一群白鸽，为你衔来一枚橄榄叶……” 10月1日，迎着黎明的曙光，特级飞行员房海春情不自禁地哼唱起熟悉的旋律。 这是房海春第5次参加阅兵。数小时后，作为空中护旗梯队长机机长，他和战友们驾驶国产新型直升机，护卫党旗、国', '2019-10-02 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2019.001102', '抗日战争5_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5047, '报纸', '解放战争时期“云南起义”新解', '雷希', '云南师范大学哲学与政法学院;', '团结报', '云南起义;潘朔端;滇桂黔边纵;曾泽生;国民党;', '今年是新中国成立70周年，也是解放战争时期对解放大西南具有重要历史意义的云南起义（以下简称“云南起义”）胜利70周年。通过学习与研究，笔者对这一重要历史事件又有了新的理解、新的认识。 “云南起义”单纯是“昆明起义”吗？ 长期以来，谈到“云南起义”，学界和', '2019-08-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTiNKZ5JaCU9SMm4ekudZlhDJr90DEnuTM2RJLg8ukVA6k_eVjlLzatBeOKfVOLV8DLuzDBgQm92y_vahZgIx-RU4ptbTlstgzCZRBxooxivWOkYeTmpXoJwM3mdUBSXtQOEBsDZ3lSIg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5048, '报纸', '铭记海上抗战历史的光辉一页', '葛传根', '学习时报', '学习时报', '革命烈士纪念碑;大鱼山岛;新四军;抗战历史;', '在浙江省舟山市岱山县西北的东海海域，有一个形如遨游在海中的大鲨鱼的岛屿，这就是大鱼山岛。抗日战争时期威震东海的大鱼山血战就发生在这里，它是新四军唯一一次海岛战斗，也是人民军队进行的第一次海岛作战，在军史上留下了独特而又光辉的一页。 在当年烈士血染的地方', '2019-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTLsytO_oGk3cGQwTHUvNBr3Kub_urYzE4P33NgVd38efx6Ii8_c-F_dc-f_CJkE_KvJ1BNVl4EhFm1ozFGXSw2r_lFPIHefQcQq9PT8waYORAq8hgzD6xOdlJk6Z8ROt7_HX84Livq8Q==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5049, '报纸', '国防教育与城市建设同步发展', '罗正然; 刘小翔; 李健南', '解放军报', '解放军报', '国防教育;嘉兴市;德育教育;主题公园;同步发展;', '春日的周末，上海市民伊先生携老带幼来到浙江省湖州市南浔古镇旅游，两天下来，在领略古镇悠久的历史积淀、中西合璧的江南建筑之余，还有了意外收获，观光赏景时不觉间步入离古镇景区不远的一个充满军事元素的公园。 只见公园里立起了军队英模的塑像，展陈着退役的飞机坦', '2019-03-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQIO12NYnpc0AMFEFmX_Tdmlxsy7pxiDeyjh3QovWtQfceGmLVuZvpihXjMSoUrK1b0UARKsnv1p9WgAysV6ldR7rbTE3e7FAGhzSrMCxNu3tAAY_MTEkbs3vjw8lrmah9vvhCeQneCfw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5050, '报纸', '施计诱敌入瓮，一炮斩毙敌酋', '尚祥胜', '黑龙江省齐齐哈尔市碾子山区人武部;', '中国国防报', '阿部规秀;八路军;黄土岭战斗;杨成武;', '1939年11月7日，八路军在河北涞源黄土岭地区集中优势兵力，伏击前来“扫荡”的日军独立混成第2旅团，取得重大战果，毙伤日军900多人、击毙敌旅团长阿部规秀，沉重打击日军的嚣张气焰，极大提振中国军民的抗日信心。 抓住骄兵易怒的薄弱点。黄土岭战斗的结局，是日军将领', '2018-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRvJew4xvrK6LbjUCsuxStyLd1rW9z-HEA1otvSB2DQLNVMXaIA2UUjSJI2IvlfbT3w3fV7548AADfNetCtXU7pcRWkUEjNgJIV9H1c49NPCTBKETMCbf6KvE69Dn5QYptHWJadMmkjUw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5051, '报纸', '国歌神圣', '于海; 张丽', '人民政协报', '人民政协报', '国歌法;《义勇军进行曲》;中国人民解放军军乐团;', '有一首歌，革命时期传唱广泛，激励着仁人志士在“最危险的时候”前仆后继、舍生取义；和平时期影响深远，鼓舞着有志青年在新时代居安思危、拼搏奋斗……它从历史走来，不仅是一种声音，更是一种精神，时刻提醒着人们坚守中华民族的自强、自立、自豪感，铭记历史、珍惜现在、', '2018-05-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR_rQQEZQ5nP3ffuT949TxawtxgUGfKHTm7geCloGjHc54XC71bMKJRg5XCHHf-iTQo-H2-WvdtlCsyW9ilyWo7i4YoOw8zE85FhqcgCQq-egetU0Zs2umji-j2vd2-qfBo9D0mxyNCYQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5052, '报纸', '到刘集看红色中华第一书', '肖家鑫', '人民日报', '人民日报', '党支部;共产主义;红色中华;安格尔;女共产党员;', '在山东省东营市广饶县大王镇刘集红色旅游区，《共产党宣言》纪念馆的讲解员们又迎来一批新的游客。他们慕名而来，就为了看看首版中文译本《共产党宣言》和刘集党支部的历史变迁。 封面被误印 历尽战火终留存 走进刘集村，就见一面面墙上都印着铁锤镰刀，大红标志让这', '2017-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQv06nnElMq7PnxNlyqxGEcBPH0Y-ej1Pd01mkDQxJW3-pAZ4zopJzUhek88kzLGZ3ZFDJyoRKdUmWjUmQfoYxbgEAb5Gbzhv6vhdULTabt29l6A8RQ5thtIkbjsxyx-9GCDd9If31xbw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5053, '报纸', '民族区域自治的中国经验', '彭训文; 王萌', '人民日报海外版', '人民日报海外版', '民族区域自治;金炳镐;内蒙古自治区;少数民族干部;', '5月1日，内蒙古自治区迎来自治区成立70周年纪念日。1947年5月1日，在迎接新中国诞生的曙光里，内蒙古自治区宣告成立，成为新中国实践民族区域自治制度的光辉起点。 这些天，很多海内外读者来信来电，希望了解中国民族区域自治制度的缘起及实施70年来的成就。为此，本报记', '2017-05-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQOLPuUcUjaXkMip1duoB_nqfqZBibu2_kl67JqkcM63shDwvJMfGUtvov4Xs_A5LYq66_sZYdIgGHc7UeKEX7Qfj9zOZ-yU8Ta_SpsFpnxwWzjrX3FPaVqvhvfy1Mf-NVfj5rzGEoOew==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5054, '报纸', '垒筑国防教育的“希望工程”', '罗正然; 刘小翔', '解放军报', '解放军报', '国防教育;长兴县;国防教育课;', '位于苏浙皖交界处的浙江省长兴县，是抗日战争后期我党创建的一个重要革命根据地，红色教育资源丰富。 19年前，煤山镇槐坎小学遴选一批小学生担任苏浙军区新四军纪念馆讲解员，成为该县国防教育的新品牌。 光阴荏苒，当年的“一枝独秀”已是“春色满园”：国防教育正', '2017-02-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRlEzjleLrVv0HJEnATdIkuDI2w5gRttTRoPOimK7_o_Xg9YhFO36lhGpXpmVsSB5s_c2ytV29uC2G2J_oNumKZDHFEkXeFd9mTkbjuysCdEZ3U_8PB44WR0Oe0o0Pn02w_2qt8XHrPsQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5055, '报纸', '秉承“抗大”精神 建好最高军事学府', '张仕波; 刘亚洲', '国防大学;', '光明日报', '毛主席;联合作战指挥人才;国防大学;', '中国人民抗日军事政治大学（简称“抗大”）于1936年6月在陕北瓦窑堡成立，一建校就担当起民族救亡、人类解放的使命责任，成为名副其实的红色熔炉和精神高地。在9年多时间里，“抗大”为我党我军培养了10多万名优秀的军政干部，为中国共产党及其领导下的人民抗日武装的发展壮', '2016-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSq5E6CQnNLS4j5vb0yqXJr4olreQC0pvL7B5jebDiojpypskalyqDBR-NCcYjESsWb5fTPS38VfKv-ql4fMIOOe_n2UnYhibNymg6-godvIkvpqZ6Jihoc7xnf7MEnyRdnlY1VWc4vPg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5056, '报纸', '我满月那天是“九一八”', '刘德有 ; 黄悦', '文化部;', '中国文化报', '殖民地;统治者;日本帝国主义;勤劳奉仕;', '编者按：为落实中央领导指示精神，抢救老同志留下的宝贵精神财富，2014年以来，文化部将文艺战线老领导、老艺术家回忆录整理工作列为一项重要工作，通过录音、录像等方式，完成多位文化部老部长、老艺术家口述史的摄制。为纪念中国人民抗日战争暨世界反法西斯战争胜利70周年', '2015-09-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ1MYKhG8MHqRDrpFrtvSHnzj-Gb0HN-Wo482hyBRYjEpIW5H0nt2WOLYW6idXJhZG5OlMJxhkO5hJiajXa43jzxENJEWe_DAcOMFF9Cx9njYxkQ5lt-aLDHxAICzlAKc3Yah8i6_siag==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5057, '报纸', '日本华南派遣军最高指挥官在此伏法', '马守敏; 林晔晗', '人民法院报', '人民法院报', '战争罪犯;指挥官;军事法庭;主任检察官;广东省档案馆;广州行辕;主任书记官;检察处;高等法院;', '在广东省档案馆，记者查阅到了一些抗战文献：广东高等法院的《日本战犯审判记录》《广东高等法院检察处工作报告书》《日本战犯审判报告》，以及中国国民党军事委员会委员长广州行营参谋处编著的《广东受降纪述》。发黄的草纸，工整的毛笔字，文雅的文言，让人仿佛穿越时空感', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTJKidaH9EhVRu00ssCX875-MchqIOBnxcr5KHTsepkxD5pfSqlgWAnbD-MVOv1ARO9rXfpKx5jypwjN8ttDvwaykFQMVS1u_XIviP426rq5avyzF1b8cEQOo1a2QqCc2oZZFx95ky96Q==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5058, '报纸', '揭露日本宪兵“天职”的罪恶', '窦玉梅', '人民法院报', '人民法院报', '日本战犯;战争罪犯;军事法庭;国民政府;施行细则;', '在抗日战争中，从1937年12月27日济南被日军占领，到1945年8月日本无条件投降，济南人民残喘在日本侵略者铁蹄之下达8年之久。抗战胜利后，国民政府在济南成立第二绥靖区司令部军事法庭（以下简称济南军事法庭）对日本战犯进行审判。1946年8月25日，济南军事法庭开庭，共审判了', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRka3-pL5_gtwGCbftS9JpYVXSLtjHc69J7DpLuTvwIQ9vW9HIdyD177KWtSWH6HBJ4J9xOqFTADVTYIQi7rcNEIExanqRniDJGMtHEmdCCByXdp9NpuqbsnO-bSCy4e2BAkrNyqegDlQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5059, '报纸', '张世铮：辩护遵循东京审判的方式', '郭春雨', '人民法院报', '人民法院报', '东京审判;特别军事法庭;日本战犯;张世铮;伪满洲国;法律顾问处;最高人民法院;', '今年85岁的张世铮老人，现居住在吉林省长春市区，身体比较虚弱，但精神出奇的好，耳朵特别灵，谈起话来，虽然声音偏低，但思路清晰，吐字清楚，上下连贯。谈起59年前，1956年最高人民法院沈阳特别军事法庭审判日本战犯，他曾作为日本战犯伪满洲国间岛省省长歧部与平、日本战', '2015-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTAKjikZLgCQ3S9sojA0oE-JNQvCpu8gdlyOqchLNXUXmoD5Ht74QrmoOHwqZE8Kx8wp-SFT2_NGc0iN5GWgp_Fo6CVP7rKJc6LGAMG7WvrJruy0NR2sRVRWZ0CdPjzmIbMhTYhOYtr6w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5060, '报纸', '东江纵队纪念馆 孤悬敌后的南粤旌旗', '郑杨', '经济日报', '经济日报', '东江纵队;百花洞战斗;抗日根据地;爱国民主人士;抗日游击队;抗日救亡;抗日武装;', '在中国的抗日战争史上，有一支特殊的部队立下了赫赫战功——那就是孤悬敌后而威震南粤、蜚声海外的广东人民抗日游击队东江纵队。在长达8年的抗战中，这支英雄的抗日武装远离八路军和新四军主力，得不到来自党中央的直接支援，在日军与国民党军队的残酷夹击之中，开展独立自主', '2015-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS-HerVLJ__ZbigEbPihI0KuSx6rr4jTJ6xe5b_hkcdefOQ5GxmyAv6TzwIsBdgghMyqf3wf4YGdmbne0AbTWJcQKE3lUiCtXP2MPx64si7lh9W_carClAZSFg2nToMctVi1nXzewKaBQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5061, '报纸', '“铁西瓜”让鬼子闻风丧胆', '王金虎', '经济日报', '经济日报', '地雷战;', '上世纪六十年代，《地道战》《地雷战》《南征北战》这三部俗称“老三战”的电影，几乎家喻户晓。其中，反映山东海阳民兵在艰苦的条件下，碾炸药、造石雷、打鬼子的电影《地雷战》，让海阳人民的英雄事迹闻名全国，“不见鬼子不挂弦”、“铁西瓜威力大，炸得鬼子飞上天，炸得', '2015-08-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQlpc_oElRnNBsgP1kx24viZfhLGXhm5bQEliN4CocdB3KwyZ66Cc45qUsgPg_nywWHnjXqre54uLN1ORkowSRtXX8YUnnnZnUgYk6xXeJgNy6fE8cqHCox3RxeLb0vAVQYTB6wzJHoeg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5062, '报纸', '王二小是无数少年英雄的化身', '耿建扩', '光明日报', '光明日报', '王二小;歌唱二小放牛郎;', '《歌唱二小放牛郎》，创作于1942年的爱国歌曲，热情讴歌了抗日战争时期13岁的少年王二小机智勇敢地与敌人斗争，将日寇引入八路军伏击圈，而自己却英勇牺牲的感人故事。  《歌唱二小放牛郎》这首旋律优美的儿歌，鼓舞激励了一代又一代中国人。王二小的故事先后被编入', '2015-08-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQwhmJ_cND_oscXYzoxDHG_KvB_vOF58Y1FDgm0kD8p9nex4PpPQc00LGkFz2dlqG0UGKO265wfwuTyBPlQ8NaT6YbXl2glOteQsEzaoJkoeQrjxuLzqbbT2T7DpZ_iiRkvDMrDfh20Hg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5063, '报纸', '东方主战场,为世界反法西斯战争胜利做出重大贡献', '杨祖荣', '解放军报', '解放军报', '世界反法西斯战争;反法西斯统一战线;重大贡献;', '写在前面 思考二战，有两则关于中国的假设： 假如没有中国，二战是何结局？“假如没有中国，假如中国被打垮了，你想有多少个师团的日本兵，可以调到其他方面来作战，他们可以马上打下澳洲、打下印度……”这是1942年，美国总统罗斯福的回答。 假如中国当时富强一些', '2015-07-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQzdiq5GoyPUwsJ7qlRJ04WmBw5ceU-GWNrjezyeaq2DhnJQ82bR4VJAnbcmJy0U6pLjhfpm5EellXS3QXnu38ARdty8mW_YaiYJmBOmrSvknRw0xdBHGmU3cqlZoVdofg31RapuJ7Agg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,九一八事变_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (5064, '报纸', '“中国是二战胜利中坚力量”', '任彦', '人民日报', '人民日报', '中坚力量;', '“在有关二战的历史中，中国作为战胜国的贡献并没有被全面地展现出来。更准确地说，中国的贡献几乎被忽视了。这种历史性错误必须得到纠正。”希腊克里特大学政治学教授伊莱亚斯·乔泽坦斯日前在接受本报记者采访时表示，“中国在二战中的突出贡献应该得到全世界的肯定。”', '2015-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTXN_H97kRD1WWd2p_r9GM_v7KS_nscO1U6iouRq5CophboviOEj-D9Ej4W7eps0X0P8QGxIUSCqU7AoAqqWGxmAIVCvw061jTZacWLOIYBbFpAZm3eBxBzcCoKWbaFSVXiutQxfgJmFA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5065, '报纸', '维护胜利成果要有新作为', '', '人民日报', '人民日报', '日本军国主义;凡尔赛;华盛顿;战争责任;二战期间;法西斯;联合国;日本右翼;安倍晋三;', '是谁用生命换来和平 安德烈·纳扎洛夫 反法西斯同盟最终取得胜利，帮助人类走出战争的泥沼，走向稳定与发展。可以说这场战争改变了世界。 战争爆发最直接的导火索是法西斯政权的崛起。1933年，刚刚上台的希特勒宣誓要修正世界秩序，为日耳曼民族夺取新的生存', '2015-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT4C7an6oltA9IqoLRYSTZrhQn3DlpJaYoBKOOAlBub38vhIZSvLNcI5jzCaNBEAToomoCRTPr57o9zNwZ79IJX-UUzZ-7NztzFKhlyYpJgd_yxVQlTM5JPVheSudXWHJSh-FQnMMNhnQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5066, '报纸', '永远的生命线', '欧世金; 曹智; 李宣良; 白瑞雪', '新华社;', '解放军报', '中央军委;习近平;党对军队的绝对领导;当代革命军人核心价值观;古田会议纪念馆;人民军队;中国共产党红军第四军第九次代表大会决议案;红四军;', '有一种信念，可以统一意志，凝聚力量； 有一种追求，可以锻造灵魂，改变历史。 在中华民族上下五千年的历史时空中，从来没有一支武装像人民军队这样，同一个政党的血脉、一个民族的命运紧紧相连。在九死一生的历程里，是什么样的力量使这支队伍愈挫愈勇；在千难万', '2014-10-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQeFHxKjbN5Bu5YRdr4x1gO1KmL29SHShQ5exFokWmEVTIT0u9xPvTYfF3nVwJt638_Ot9pzirHEyooicLaIHVXl8mBUw6k3sQA4p_-mvydOuCGVlg5D8HSuBv4LxDOqhtZwYMC9wgUJg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,红四军_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (5067, '报纸', '镌刻永不磨灭的抗战功勋', '', '人民日报海外版', '人民日报海外版', '第九战区;昆仑关大捷;枣宜会战;细川忠康;随枣会战;反围攻;张自忠;根本博;骑兵团;阿部规秀;', '《伟大胜利——中国受降档案》 受降档案 第二十二集至第二十四集 （续9月5日第11版） 【第二十二集】 山东区和热察绥区受降 山东区受降以第十一战区副司令长官李延年为受降主官，负责接受山东地区。该区日本投降代表为侵华日军第43军司令官细', '2014-09-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQk-L8iT6ical7KIzQLllDw3AXnUIvszSdQ6THXnjA9uWwSSHcDRPqY-kMKrhRmSjEbpka0AkbKOfG3ay5gW77XDx_DTTOtnrEGeLUhbeAbbkdWKNvadUR3DT-qWJK9SS4eZmi95NY0Xg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5068, '报纸', '牢记教训 勿让历史重演', '汤先营', '光明日报', '光明日报', '抗战胜利;日本法西斯;', '今年中国首次以立法形式确定9月3日为中国人民抗日战争胜利纪念日，体现出纪念抗战胜利所具有的国家意志。对于这一举动，外国友人如何评价？为此，本报记者走访了位于仰光的缅甸国际战略研究所联合秘书吴钦貌林先生。 吴钦貌林首先告诉记者他已经通过媒体了解到中国设立', '2014-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRgq-GpBHgYxW1rDXs6pS4zKR_7exlsN1mGxYRS7nlMHPDSu-Rb1QWrV6J39D0xYL-DvcJdrTAulKAndDtobbkDZ2DHPGB73zc4wDOVXsgd09MQE6X3q7022JNP4AF0dUH6wkygg7GsbQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5069, '报纸', '伟大精神产生伟大力量', '', '人民日报', '人民日报', '抗美援朝战争;专题片;', '今年是抗美援朝战争胜利61周年，由北京电视台创作的6集系列专题片《伟大的抗美援朝》3月上旬在北京电视台《档案》栏目播出后，社会各界反响热烈。中共中央宣传部文艺局、国家新闻出版广播电视总局宣传司与本报文艺部日前在京举行了专题座谈会，中共党史军史专家、中国人民志', '2014-04-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSHMpiT4J2kgyWQXINZEthIJaQfGicksI07CgnmEeOXWV7vZ-FEuxqabO04nc-XM0pooawKoRwKgwxQZkbXEaoeNog6uhNfaWJeWRGc951oyoegKKUwOIRMaZ1HqQ6n06l6lZR97D7n5A==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5070, '报纸', '政府收权推改革', '谭洪安', '中国经营报', '中国经营报', '国防设计委员会;钱昌照;南京国民政府;', '1932年11月29日，南京国民政府收到了一份署名“参谋总长蒋中正”的机密公函，内容是为刚刚成立的国防设计委员会“呈请备案”。 该机构直属国民政府参谋本部，由已集党、政、军大权于一身的蒋委员长本人，亲自担纲执掌，其特殊地位与分量，可以想见。 自新', '2013-11-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRYn5BOUIWACKXQKuXQSObBSLquLYrdnWoLOHb184qhZ7PBLkDOeTRbXBTUpf7yMiawkfiQk59qhyV2KzRRnn5RI1o39gixqi3tdONSmK6LvBpIyc0s5pkpTeoTUzjKwm_Do6vg_7dCYw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5071, '报纸', '历史的警钟 永远的昭示', '周婷玉 ; 徐扬 ; 朱薇 ; 蔡玉高', '新华每日电讯', '新华每日电讯', '日本军国主义;日本右翼势力;', '新华社北京9月17日电(记者周婷玉 徐扬 朱薇 蔡玉高)1931年的9月18日,炮声轰隆,炸毁了南满铁路,炸开了沈阳城。这一炸,在中国人心里烙上了一道永恒的伤疤。这一天,成为中国人民14年艰苦卓绝的抗日战争的历史起点。 历年“9·18”这天,在沈阳,在南京……在中国的许多城镇,', '2012-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQKTpSFaYbJlFCLtUS_Eds2QyOJpWNig4w66rAe6MbaEyOa_uRgDr9x1YjtfVKhn-dE7DgFOYnmhsVbiSSu6KgIoU3gK5WHFnK37sJlOHC5kpvi_vq5LrF7tSs3LC8kX9ENBdjaUeUkPQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5072, '报纸', '继承和发扬沂蒙精神 加强新时期人民法院队伍建设', '傅国庆', '山东省高级人民法院;政治部;', '人民法院报', '沂蒙精神;社会主义法治理念;继承和发扬;群众路线;无私奉献;队伍建设;', '中央领导同志指出，沂蒙精神与井冈山精神、长征精神、西柏坡精神一样，都是我们中华民族的宝贵精神财富。前段时间，到临沂革命老区进行参观学习，重温了那血雨腥风、艰苦卓绝的战斗岁月，精神上受到强烈震撼，思想上受到深刻洗礼，对沂蒙精神有了进一步的认识。结合中政委、', '2012-02-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS-R_lxMr9tNfqpNLw6d8J3mxJSEe1unt78Pzh3F0iEILNpbaUEKoxlpae2kRaa_ukUgkunyPtisBUGFtla9FxDf9Zmmv8P7LqvxaOXlKyjb7M2I2R0MYyqem9UB4KkN4AsxUbtnYhiTg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5073, '报纸', '延安：构筑保卫边区的铜墙铁壁', '马卫东; 阮仕喜 ; 鲁强 ; 陈雅娟', '人民公安报', '人民公安报', '延安市;陕甘宁边区政府;公安保卫工作;保卫边区;', '“几回回梦里回延安，双手搂定宝塔山。”宝塔山给见过它姿容的人留下的魂牵梦绕，是永远的牵挂。延安的一山一水都是一个个的传说，延安的一草一木都有神圣的印记。 “七一”前夕，记者再次踏访延安，重温延安精神，寻访公安前辈的足迹，向历史求证、让心灵感触、用', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRBA7_vey32lUWOhNTmZJDmBOj9i1CnjdrEaeET0jv5veHsOZSIHmwbQbgnbrKRDFbN04-jyf452yHqmofE7-s3cpqby3nOP6WotbktjLsXkVImhTadF2dxjwvvTPLSzcn4b_d9amIjMA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,枣园_screened');
INSERT INTO `ds_article` VALUES (5074, '报纸', '鹤岗:坚固大后方', '孙佰忠', '中国煤炭报', '中国煤炭报', '矿务局;东北电影制片厂;煤矿工人;鹤岗矿区;', '掀开龙煤集团鹤岗分公司的荣誉史，一张已经泛黄的嘉奖令呈现在眼前。这就是1947年由中共中央东北局签发的嘉奖专电:“鹤岗矿务局负责同志:三下江南，四保临江，军用煤无缺，有功焉。特此传令嘉奖。”  这张嘉奖令，是鹤岗煤矿工人在获得解放后光荣历史的开端。', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQNTlIXGA1XCP8f_DIqJSiEkVq3QNSF_9iKc8mFvqey68K7D_YeVCgU_o9B32B92qi-yWCIk7PGKOqhGPpAP7LA6lbVhXBjDyZny0vBxu-cZk1mON3lIW_6Vea0pA0iv6PbO9h3oJ41Lg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5075, '报纸', '沉浮 中共一大会议代表人生道路各不相同', '仇逸 ; 罗争光', '新华社;', '新华每日电讯', '中共一大;王尽美;张国焘;人生道路;', '沧海横流,方显英雄本色。在历史的洪流中,追寻13位代表参加中共一大会议之后不同的人生沉浮轨迹,让我们看到了革命道路的曲折艰辛,更看到了坚定信念的无穷力量。 名垂青史 中共一大后,全国50多名党员使革命的火种迅速在各地呈现燎原之势。28岁的毛泽东回到长沙,', '2011-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT65fTO2Y9LXWorhmMPJU8dB3Is7PaQNz53Aa6T2rrmZRlWI7XtBbVAMhEo5STL9pGNSqd-v8W1W5HOB2ehoAOumyQf5EO81mI-xpGy-hOyjeBoFRLyk9qIVd3NS1HEIIeevm8T1j2G3g==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5076, '报纸', '瓦窑堡会议：吹响民族抗战的号角', '陈典宏; 李秦卫; 尉启君', '解放军报', '解放军报', '瓦窑堡会议;抗日民族统一战线;关门主义;共产国际;瓦窑堡会议旧址;张国焘;红四方面军;', '神秘“货郎”赶来 传达共产国际的声音 穿过子长县城熙熙攘攘的人流，走过蜿蜒曲折的胡同小巷，我们来到了位于县城中山街南侧下河滩田家大院，这里便是瓦窑堡会议旧址。光阴流转，当年颇为气派的大院如今已稍显简陋，曾经的风雷激荡变得一片安宁祥和。 1935年1', '2011-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT9gfxFjT1I7CHgBpiJA2PesuzW3N7mzxSAE1xtA_dgKd5CY15yTx6rnft0FK-BfHzjP-CVomNrvBs_43JQZSidX9dropGVrg059gZD1u_DKIowHv4OIxubFKhtGhsnKEeDYSl-BzQ7dQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5077, '报纸', '天下归心', '徐京跃 ; 李亚杰 ; 徐剑梅; 谭浩', '新华社;', '新华每日电讯', '中国共产党;中央档案馆;叶剑英;马克思主义;十月革命;世界第二大经济体;李大钊;毛泽东;陈独秀;军阀混战;', '从南湖烟雨中起航,中国共产党经过90年艰苦卓绝的奋斗,众望所归地成为中华民族复兴伟业坚强领导核心,成为中国特色社会主义事业的领航者。 这是历史的必然、人民的选择、时代的召唤。 目光穿越历史迷雾,苦苦探寻前行道路。高扬马克思主义旗帜的中国共产党成', '2011-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRWf6w9BHGSJlb-4jLD10rvl9P07nDDBo7TAJM6Z9ztrETK6R8vEl2pgdDmCU8l-jc6nrUghKvDatZkzVD6RkaFG0kYV7ETcIGstLEAV0qm8DCVVAVHUGw2tjTykftcLQdari_YslAmHA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5078, '报纸', '四渡赤水：毛泽东最得意的战役', '欧阳浩; 李奇松 ; 程必杰', '解放军报', '解放军报', '毛泽东;青杠坡;红三军团;红五军团;加入中国共产党;娄山关;王家烈;', '人物简介 李光 1920年8月出生，贵州遵义人，1934年12月在遵义参加红军，1938年2月加入中国共产党。参加了长征、抗日战争、解放战争，曾担任朱德、彭德怀的警卫员。 王道金 1915年5月出生，江西兴国人，1930年8月参加红军，1935年2月加入中国共产党，参加了5次反“', '2011-06-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT9CAFpKP2zMZjzzmX_B8m_iIKARNlvIop_2-EckXHbYjAZNbfv_OytNTEUPLR7fVv2GWiPDv65oGSSQbeHwk_kYCku3QGMDIaBT6VXEiqH0JaLXul1j5D7qG4oFAB_lApDSzEPPgF1cg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,扎西会议_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (5079, '报纸', '天翻地覆慨而慷', '梅世雄; 霍小光', '人民日报', '人民日报', '国民党军队;淮海战役;战略决战;人民解放战争;中国共产党;中国革命战争;打不死;和平谈判;', '“１４２天歼灭国民党军队１５４万余人。”今年８２岁的解放战争亲历者、军事科学院百科研究部原副部长王辅一说，“辽沈、淮海、平津三大战役，使国民党赖以维持其反动统治的主要军事力量基本上被摧毁，大大加快了解放战争在全国胜利的进程。” １９４８年９月１２', '2011-05-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ_OxlO7Ql01Gy1R9WEjWIJcjIXuRGsAlb68vX8S54U2ASO2jTt4G-bqaKoEXABLGJ4YBp-iP93C2eFhDOxJEAIkzJ8UjgUaxGUHUOWpEblTlRHGdFPlbk0JfEcQ1VIDTA_BWH6CzvVvQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5080, '报纸', '让革命精神永流传', '张建友; 刘艳婷', '中国文化报', '中国文化报', '梧桐河农场;宝泉岭;文艺宣传队;革命精神;', '位于黑龙江省汤原县的梧桐河农场活跃着这样一支队伍：他们身着东北抗日联军军服，神情肃穆、慷慨激昂地演唱着东北抗日联军歌曲，宣传抗联文化，宏扬抗联精神。这支队伍几年来行程近万公里，演出近百场，观众人数达40万余人，参加各类公益活动11次。他们就是荣获第二届“感动', '2011-05-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSnoU8COU4RGtXuWkPimIbiLOmOtIB4dnwz5nLQlA3sY_b8KDExIAhMjz45HgDxQSp7V1LDJR2avST0OoLQqlPA_owapUBelFm-sffRXrM7-1fg3E9YPYJEw2RznnCsIfgCy3X-MGwaMw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5081, '报纸', '永远高扬的旗帜', '张军', '人民日报', '人民日报', '杨家岭革命旧址;共产党;整风运动;共产国际;延安文艺座谈会;毛泽东思想;党的历史;整顿党的作风;', '“杨家岭的红旗啊高高地飘，革命万里起高潮……” ５月的延安，遍布城乡的革命旧址迎来一批又一批参观者。在杨家岭革命旧址，来自山西省太原市的十几名老干部齐声朗诵起这脍炙人口的诗句，仿佛回到峥嵘岁月。 杨家岭，这个原本寂寂无闻的陕北小山村，因中', '2011-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRrw-vpsbHh2SPQsdqRV4Ip_YT1zH1LSIee9ywEih0sSh1nDV0ubLBEbBt9Ev37HEJCa2M3W6CPZG0EH_n-d8eu9RIVb8Vb8wXuxamqSr7dRotGzntwGY371ICmgJbSso7q-pWSWx7NKQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,百团大战_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (5082, '报纸', '学习伟人风范 倍加珍惜当今', '吕明军 ; 牛一兵 ; 颜珂 ; 孔祥武', '人民日报', '人民日报', '中国传媒大学;临时党支部;', '本报长沙5月5日电　（记者吕明军、牛一兵、颜珂、孔祥武）5月5日，来自本报“追寻”湘鄂分队的10名80后、90后大学生来到湖南韶山，开始一次精神洗礼之旅。 5月4日，湖南省委书记周强寄语前来“追寻”的学子“坚定信念 建功立业”。 站在毛泽东铜像前，“追', '2011-05-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSwssqXy85JVR7tluAw5umBFOGJw9T4y5GS81yT86aYggo6FvTl7u4zQHA967pDnGEZK_KsTCkCiMi_zlEoKjZP6HjfvZpMxY-DjjHBokkE8rjw0c_tnGbsweasr0sY_wOAJsvgF3Ltzw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5083, '报纸', '震撼 感动 奋进', '郭洪平', '检察日报', '检察日报', '郭韶;', '88岁的老将军董占林一个标准的军礼，全场立时响起热烈的掌声。  8日上午，北京人民大会堂三楼小礼堂。中央政法机关光荣传统教育报告会正在这里举行。  报告团成员之一，胸前挂满奖章的董老将军，和其他三名成员一起，为来自中央政法各部门的数百名听众，奉', '2011-04-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTXncXf9ajStZ2rmlD9rFbclIoSAW2Y_LEnewxL6eJTm_bhnon40HSu-e1XENIUGsX9AGW6c-hVaaxCpcbXbXl-Z-zC7SDgoB8nb8T8zgP63aOQT3srRAJVOr_BxDxb5_9IyoG9FZ9Hzw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5084, '报纸', '朱瑞', '', '人民日报', '人民日报', '中共中央;政治部主任;东北军区;延安炮兵学校;', '据新华社北京４月3日电 朱瑞，１９０５年生，江苏宿迁人。１９２４年加入中国社会主义青年团，同年考入广东大学。１９２５年赴苏联，先后在莫斯科中山大学、克拉辛炮兵学校学习。１９２８年加入苏联共产党，后转为中国共产党党员。１９３０年春回国，先后任中共中央特派员、', '2011-04-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSSt85rH95Lyt2udWLtkwrP01bWfehteQ8_WM2G2d4zEDfDeqvaFG9jb2PAZzn1wUUHwEBJundRAD4W67VnMYA2_qotil5jzMnH8VVWmblbl_nF1eXg_6dik8fwzMtkABy-_IrndSlX2w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (5085, '报纸', '海峡两岸祭拜黄花岗七十二烈士', '郑天虹 ; 张建华 ; 田建川 ; 颜昊 ; 陈斌华', '新华每日电讯', '新华每日电讯', '黄花岗七十二烈士;', '1911年4月27日(农历3月29日),黄兴率120余名敢死队员直扑两广总督署,发动了同盟会的第十次武装起义——广州起义。起义失败后,其中72人的遗骸收葬于广州东郊红花岗,后改名为黄花岗,这次起义因而又被称为“黄花岗起义”。“三·二九”广州起义揭开了推翻封建统治的新篇章,2011年', '2011-03-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQJBvkUljx4nmd-27r7ZQY5zeryTdC9brKdt9oKHm8Px60hKdDTQx-QRmOSTCpStTk0PUVbkpERJKZA7wzo6M65A2HJ0wad1B6E4h-A7O6iAW38jmH-HNHVbSJgKFqDWyzYPp6t7LulJw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5086, '报纸', '江苏 请英烈“回家”', '申琳', '人民日报', '人民日报', '民政部门;烈士陵园;', '江淮大地，一块具有光荣传统的革命之地，一块先烈热血染红的英雄之地。 为了民族解放、新中国建立，无数仁人志士英勇牺牲，长眠于此。据不完全统计，录入烈士英名录的江苏籍烈士有98300多名。根据2009年底的统计，江苏共有县级以上烈士纪念建筑物保护单位73个，乡镇', '2011-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSoblrzwR80kakoVlFmt_JoMsc6V31dml8cdY1pjXKW5EnPbJS0j0VvIqO3Yf7e1R8clRQqY7M-DHKG26iE1xwfzy5xHdlsp9veQ2lhAWFRxho2OCDLGOm9_NjuqNunxdHIT5Bsw5ccVw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5087, '报纸', '新四军抗日名将 罗忠毅', '', '人民日报', '人民日报', '罗忠毅;廖海涛;新四军;', '据新华社北京３月１５日电 罗忠毅，原名罗宗愚。１９０７年出生于湖北省襄阳县一个贫苦农民家庭。１９２７年入冯玉祥部当兵。１９３１年随国民党军第２６路军到江西。同年１２月参加宁都起义，编入中国工农红军第５军团。１９３２年加入中国共产党。１９３３年起任福建军区', '2011-03-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSoLH3b3vWh4oBhFnxNfUHpv13I1y4pqeMFWZqv0L6aYuaGWtnnw8040XlBEN8N6uR-sBsAnjf_lqrtF_TMuM4FMsCf9xGcPWs9kKpzVDmbU_UcaCCmOMkXUtnKFYT3R4W7U9ySYd3L8A==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5088, '报纸', '续写“史迪威公路”传奇', '平晋恩; 邹新林; 刘周兵', '中国交通报', '中国交通报', '史迪威公路;高黎贡山;山顶洞人;国际大通道;测绘分队;', '日前，一部热播的电视剧《中国远征军》让“史迪威公路”再度为公众所熟知。无论是这条为中华民族取得抗日战争胜利立下汗马功劳的神奇道路，还是两千多年前声名显赫的“南方丝绸之路”，都见证了滇西高原险峻。  如今，为早日打开滇西高原封闭的大门，完善云南省干线', '2011-03-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRjeHa5ouSUFUPmxbo3tq0iumhFG1qCTTYWdOgjjF0TI64SK6rzo8HMILhIf57m37qMZoMnm0E1kI39VtqUB2eRT31sz5GVUKWAQP8qMkJwSh7ZZjIRS4sthcMP3ym381Y94-g7_KZguA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5089, '报纸', '不屈的抗联将领李兆麟', '', '人民日报', '人民日报', '李兆麟;东北抗日联军;中共满洲省委;反日游击队;哈东支队;', '据新华社北京３月８日电 今年３月９日是李兆麟将军牺牲６５周年纪念日。 李兆麟，化名张寿篯，1910年出生，辽宁省辽阳市人。“九一八”事变后，到北平参加由中共北平地下党员任骨干的抗日民众救国会，在平西一带进行抗日救亡活动，并与党的地下组织取得联系。1932', '2011-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQay123Oi26I7WtjTEZqfGU5FZuhJahVT5SCNwTDAdyq9HptkObULqMC99nE3qPoXv_DOSJtyT9XhtT9YJVpmiC1BdyJSpjc9iwuKEckoFuhb4SEKa1E16WRiw5n08p9twe8QM5EQob5Q==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5090, '报纸', '同侵略者血战到底 八女投江', '', '人民日报', '人民日报', '八女投江;侵略者;', '新华社北京２月１６日电 抗日战争时期，以冷云为首的东北抗日联军８名女战士，在顽强抗击日本侵略军的战斗中投江殉国，表现了中华民族同侵略者血战到底的英雄气概，在人民群众中广为传颂。她们是第２路军第５军妇女团指导员冷云，班长胡秀芝、杨贵珍，战士郭桂琴、黄桂清、', '2011-02-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSTfLvaFAfskQTXMmZHE7bcbO-EkyWYXXzJ2QY3hcDVP8eYxa28Yf2y5s_Dxm_tzIMchuzjsPdAgKVjH1hVDoxxziLp4liVR9P3wZT_joODH9NcoESma55H0MDaD1tKlh-sutE6JMVQNA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5091, '报纸', '方志敏最后岁月见证人的书稿尘封50年后出版', '王洪波', '中华读书报', '中华读书报', '方志敏;乔信明;', '本报讯（记者 王洪波）披露方志敏领导下的狱中斗争传奇、由曾庆红同志作序的长篇纪实小说《掩不住的阳光》最近与读者见面，小说作者系南京军区空军后勤部原政委乔信明和他的夫人、新四军老战士于玲。 乔信明曾任方志敏领导的红军北上抗日先遣队（红十军团）第20师参', '2011-01-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTjPT4dmaGeDIL3AUyJ-TquxKUtiAPyfpksW-4YjUx659GtftWlD-tGKeF2RNP3I56CXzg87I5iAxsjhT7ptsSF_pRm6joyYGuxqD-nlMJaT1ChahdeaakGMJf5ltmhwCzPPBo22_fHeg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5092, '报纸', '支持革命老区加快发展的理性思考', '潘永东', '金融时报', '金融时报', '革命老区;金融机构存款余额;政府融资平台;理性思考;', '革命老区，是指土地革命战争时期和抗日战争时期，在中国共产党领导下创建的革命根据地。它分布全国28个省、自治区、直辖市的1300多个县（市、区）。革命老区为中国革命的胜利和新中国的诞生作出了巨大牺牲和突出贡献，但由于自然条件限制等原因，老区的发展总体来看比较缓慢', '2010-11-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQRlp2tp431UaQGdGr_P3lSv00LHHmx7V8qt7-mf1PENZL468KgSxeEyLyNoeOTa0C7jpDXIy7ZUCpVP0zJOl-ZhrKfFTmtilOt84dJ4ZOPMpkjQR8WCpIJgqB0qG0GZekR_rTMg797LA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (5093, '报纸', '铭记历史 珍爱和平 携手合作 共创未来', '杨洁篪', '中华人民共和国外交部;', '人民日报', '铭记历史;世界反法西斯战争;法西斯主义;', '今年是中国人民抗日战争胜利和第二次世界大战结束65周年。应俄罗斯总统梅德韦杰夫邀请，中国国家主席胡锦涛5月9日专程赴莫斯科，出席了俄罗斯卫国战争胜利65周年庆典，并亲切会见了俄罗斯老战士代表。应胡锦涛主席邀请，梅德韦杰夫总统将于9月底对中国进行国事访问，并将会见', '2010-09-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSP5aopLosDdxbt10fHFsj6v7hMzB6P2LrjHHO19pL30jk_WVhCM-7fYpiggVUfvzYaQNRrPRyCMCN6sVaUn6SuGS8H-GGm_jkfJzlw9wZbaNIHLVpgn0RhkNRqEauDfEJGRtnRydwaOQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5094, '报纸', '日本籍老八路重返山东寻亲', '李东航', '解放军报', '解放军报', '反战同盟;八路军;', '手抚着当年战友的墓碑，９１岁的日本籍八路军老战士小林宽澄禁不住热泪盈眶：“对不起，我来晚了！早上个３年找到你，我们还能一起唠唠家常，忆忆当年，那该多好啊！” 今年６月２５日，小林宽澄来到山东省新泰市龙廷镇龙溪村，寻访失去联系半个多世纪的老战友——时任', '2010-09-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQITVgq6ESPAuRDXCs5RbwEyy9R1FwMytxcSpSC1hij3_kqu3hHP_Q7cAPL51h2a54BOKDczsCa5ky1SxJecJM2wHHVddyEdOmKCP0LPyhk87u-nfhi8VFQrrO8tT2YEnm_MEy9b6Gavw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5095, '报纸', '“解放军是我的大学”', '李东航; 李啸', '解放军报', '解放军报', '刘玉堤;国民党军;', '“向前！向前！向前！我们的队伍向太阳……” 当北京军区装甲六师军乐队奏响这熟悉的旋律时，兵头义清等日籍老战士的眼眶湿润了。 ６０年了，终于回到阔别已久的“老家”，怎能不激动呢？ 面对官兵们一张张年轻的脸庞，兵头义清深情地回忆起当年参与平津战役', '2010-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSgit9_R7E9o2qsLI4Ijnuwx5no5i26f_Q4I-YSBI8aRI550KoWzyOWDYeRXl-rDRFX6c_aUiZScgnpHwzbHI-74Rdo5lPJ2t0e2IRyv22v5FzJtunF2cAn0OPM5HxS8D40jduRCTLu9g==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5096, '报纸', '聆听延河,热泪为谁流', '武天敏 ; 刘国顺 ; 罗方堃 ; 林木', '中国妇女报', '中国妇女报', '延安精神;张思德;', '6月下旬，记者随中央新闻采访团来到解放军西安政治学院，采访他们坚持32年矢志弘扬延安精神的先进事迹。 从小雁塔边的校园，到宝塔山下的窑洞，记者的心穿越历史的峰峦，徜徉在一条32年光阴铺就的寻根之旅…… 在采访西安政治学院弘扬延安精神的日日夜夜，最令记者', '2010-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSNdLpDcem9146HMF5DnMoFSkpzHwjt_CHygst2UDkZbwLsAVQNO1ue309ut_Y0DeAVVFKmy6XAY3qOuBBW0RHN-M-M4abm8JHBV9E7GrSfYoGwsXDxR56YEhywIdHosrtRh0YV8MSFMA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (5097, '报纸', '中央军委三局旧址陈列馆开馆', '胡虎', '人民邮电', '人民邮电', '中央军委三局;开馆仪式;王子纲;', '本报讯 7月1日，被誉为“通信工作的开山鼻祖”的中央军委三局旧址经修葺一新后首度亮相。工业和信息化部、总参谋部通信部在延安裴庄隆重举行了中央军委三局旧址修复落成暨陈列馆开馆仪式，缅怀王诤、王子纲、刘寅等革命前辈的不朽功勋，追忆火热的红色通信发展历程，为建党89', '2010-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR1ThxVlqbXtybqLIwqVQzEZu48QmbiWcB1lD7-D1k2rg-bjHmB87AXxcJqNo6_oorMxuPy3j9U3iMP3HDeYHLS6aJCov9bU_SwOiHMNifr2miJLOh6Zg-8pKdyjmEqagwKtjvalR6_LQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5099, '报纸', '钓鱼城的秘密', '陈彬斌', '中国文化报', '中国文化报', '钓鱼城;钓鱼城之战;南宋王朝;', '历史在这里发生了一个意外。 一个仅仅只有2.5平方公里的弹丸小城，挡住了横扫欧亚大陆的蒙古铁骑长达36年，甚至蒙古大汗也因此丧命城下，南宋王朝的灭亡由此得以延迟，蒙古军队在世界各地的锐利攻势由此得以削弱。 这就是发生在宋元时期的钓鱼城之战。', '2010-03-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtThTIgbq4i35T14gHTbPTpIuAl3e-49cx5oxmiAQXkJLyamS-S_FA82iUGLzHd1De0HQP5EoXEqoL8RtqGDJplc3RpHoknOF8HHJreyGuqLUD7BDldh0sqcf5mba-N6iHpC5b50Ek5vdA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5101, '报纸', '沂蒙老区谱写发展新篇章', '陈莹莹 ; 单保江 ; 胡红军; 庄光平', '经济日报', '经济日报', '金正大集团;物流业;临沂市;缓控释肥;沂蒙精神;沂蒙老区;', '抗日战争和解放战争时期，沂蒙山人民为中国革命做出了巨大贡献。 如今，一座融现代商贸城、山水生态城、历史文化名城为一体的新临沂城正迅速崛起在沂蒙大地上，更多更美的歌曲正被人传唱，如同大型水上实景风情歌舞《蒙山沂水》主题歌里唱的：“我的家乡飞出一支歌，', '2009-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT_zufs1_-TfEVYxfg4NiiQfkp_Z6lYPIpov0_lP2amXTfM9iehD6gQPMTMZxA0Y6KNVM-h5D47oQxhRNw_VjQm2qyKzDSbF0ddWWjbeRIDhzfqPDWXZbOO3GivaRbqtgbqXvcjWapduw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5102, '报纸', '《耿飚传》出版发行', '', '人民日报', '人民日报', '出版发行;《耿飚传》;', '新华社北京８月２３日电 经中央军委批准，《耿飚传》近日由解放军出版社出版发行。 《耿飚传》全面、客观、生动地记述了耿飚革命的一生、战斗的一生、全心全意为人民服务的一生。传记语言朴实，情节生动，许多珍贵资料为首次披露。 耿飚１９０９年８月出', '2009-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTyztkwPICh_xndMjWTLsn1tx0nDu6udnGMGw14vrKaJRNXgtgg7oiy3YXxqWVlQdvN_mQmSz6cimWGDyipb02Zja0pvCN9jnlRPJo-nxpzuUG8ahpFEfeawjzRF8U3wL0XObQWrd00cA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,血战湘江_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (5104, '报纸', '喜看今日新洛川', '杜峻晓; 杨彦', '人民日报', '人民日报', '洛川会议;农民人均纯收入;', '一座陕北小城，因72年前的一次会议而名存史册。 如今，这座陕北小城，又因盛产品质上佳的苹果而驰名中外。 这座城叫洛川，属陕西延安市管辖。 一次会议，让历史发生转折 自洛川县城北行约10公里，即可到达国家重点文物保护单位——洛川', '2009-08-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQdF-KPntJy4eIbpHUDtRCR4PMnGJrRmzG1rGFiWOmh_8yEJ06bovIphVxYw0X5Dfu-NSB0vOXRkLg8J8hjYF7CRryo0sdqMBvrdZyv0QJGdNl5fMUCM66B4LYSLhZGj_kjZ83EqqJEdQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,洛川会议_screened');
INSERT INTO `ds_article` VALUES (5105, '报纸', '湖北监利：老区变化大 城乡面貌新', '庄光平; 赖薇; 韩叙; 魏劲松', '经济日报', '经济日报', '湘鄂西革命根据地;周老嘴镇;', '湘西、鄂西山水相连。 1927年秋到1928年春，党在湘鄂西地区领导的一系列武装起义，为湘鄂西革命根据地的创建打下了坚实的基础。 走在湖北省监利县周老嘴镇的老街上，沿街78处革命旧址，似乎仍在诉说着那段战火纷飞的历史。 在中国工农红军第二军团总指', '2009-08-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQHGnB4gRr-TTM_evbTqwwdM5pGcG0UIIQiz1UPWu6rkDvLBtNc3HonbyX1FicxbrOTEmt_w0FHXxmiuB2WgmOjrolT0jF1ynowWN2AO21vNg0HO-4ZrbexLb8ljsGuFWiJtM2kKUSkNw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5106, '报纸', '盐城：江淮河汉的丰碑', '代烽; 王余根; 郑朝兵', '解放军报', '解放军报', '新四军纪念馆;盐城市;黄克诚;湿地生态旅游;沿海开发;华锐风电;丹顶鹤;新四军军部;汽车产业;主要经济指标;', '这里是一片神奇土地。沃野千里，河荡纵横，有着“东方湿地之都”的美誉，号称“神鹿、仙鹤”故里。 这里是一方红色热土。抗战时期，在15000平方公里的土地上，曾久久萦回着嘹亮的新四军战歌，众多新四军名将，跃马挥戈、抗日杀敌，铸起一座座铁血丰碑。 这里更是一', '2009-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQz30BgnqJrpYz6UwgNznh8YQa1GvUn6uSb4Vht6PNt6EEqvdGJFT6wWwq4hxBlCyqWtFExReonWNfRQVLqExDQrudtTCZ6EhWuE6yUocELpjZrbTzCXoJJKxkf8KLgcGddNPV6IbK1FA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,项英');
INSERT INTO `ds_article` VALUES (5107, '报纸', '“红军会师中国安宁”,会师精神励会宁', '宋常青', '新华每日电讯', '新华每日电讯', '中国工农红军;红一方面军;会宁会师;', '这里见证了一个重要的时刻：1936年10月红军三大主力一、二、四方面军在甘肃会宁会师，长征胜利结束。这一刻，是中国革命走向胜利的转折点。从此，中国工农红军破天荒形成一个拳头，开创历史新纪元。  73年风霜雨雪，73年艰苦卓绝。抚往追昔，红军长征会师地会宁已经', '2009-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT-zs142tkOaurvxixWta6vnRQ292qqK7Q6YuCEyFx_V9fK-P9BJ03Gn_bGL9q9QjoM62C2lq6NvJT2WRqD65ywZvnoyRpbmHSYTrqBjQNuqTZcLtiINueYGO-VfowQt-ZZZvaNOTGS-w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,四渡赤水_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (5108, '报纸', '山花烂漫新武乡', '郭建跃; 邹维荣 ; 唐亚平', '解放军报', '解放军报', '红色旅游;人武部政委;八路军太行纪念馆;武乡县;', '迎着漫山遍野的山桃花，记者踏上了仰慕已久的革命热土——山西武乡县。走进著名的“八路军太行纪念馆”，随着讲解员的介绍，记者了解到,在抗日战争期间，仅有14万人口的武乡县就有4.1万人参军、参战，其中2.1万人为国捐躯。解放战争时期，又有1万多名武乡子弟，告别亲人和故', '2009-05-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQPLH1F-yOhx5-NJRmfPb-7HGxecrvekEbdZGiF_YvJPfkW_TAtlowJxhAoOoO4DRBOEM4h5RzVhYvfMShZXFVvqfMF7jotWV5y3X5jNNr-CGh3WYfbvztN7QRaY97xA94G1IG8xHE33A==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5109, '报纸', '没有军衔的“飞虎队”', '齐越', '中国国防报', '中国国防报', '飞虎队;飞行员;', '日机再也不敢在昆明上空现身  印度支那半岛天空云雾笼罩，10架日本轰炸机从基地陆续起飞，这一次他们的目标依旧是中国昆明。  “九州勇士”们自信地认为这次轰炸几乎不会遇到中国空军的抵抗，所以他们连护航的战斗机都不用派。他们似乎没有理由不高兴:中国空', '2008-12-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS5kXEiNOPirjx8tUOs4JUMi1HitDdr7POWUoYoH654iUdehLvPzjGwphaK_ECODtocMHt2HdjScK-FP5sNPWGE73frAs6S-mkxxh335aHLscN5pbbVaRWWfDkNH9xY06AaylPeE026-w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5110, '报纸', '一座辅导站和一个人的追求', '伍修琼', '人民日报', '人民日报', '李运;网吧;农家;', '在一个收拾得干净整洁的农家小院里，温软金黄的柿子高挂枝头。与普通农家小院不同的是，院内挂满了名人名言，室内摆放着整齐的桌椅板凳，还有1万多册图书。小院里有两位老人和一群孩子。一位独眼独臂的老人，正在给孩子们讲抗日战争故事。他老伴则和几个小女孩一起', '2008-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS84JoXKDSSThamISOWME6UZB1Wb4UK3csFezcHaFz_VNHda5Iu8Ca8r_D9ZJRpVRo9_1LpQL3ruGEjpMlSPb-NK684kNbCAEGNLbx0xGR9hcT3ZUAbY8y9bhMpAOBPvkaOjWwYVU9XVw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5111, '报纸', '委部机关召开青年干部革命传统教育报告会', '瞿芃', '中国纪检监察报', '中国纪检监察报', '革命传统教育;报告会;青年干部;', '本报讯(记者 瞿芃)6月30 日，委部机关召开青年干部革命传 统教育报告会，请离休老干部李继 伟作题为《坚定理想信念、艰苦奋 斗，忠于党和人民》的报告。中央纪 委常委、秘书长吴玉良出席会议并讲 话。', '2008-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT7sFqeyQ5GV34VwRdLVfSnrS6NlV9604m3V9A_qgcKmFL2barZGGia-opn9JccFJoEloh6PFKp_TKvt8iZRuZTJh03897tvNALXyHa89UwSeP92_zqPOjr_r5OLZuoLv2yTGhxAcUYWQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5112, '报纸', '《王震与湖南》一书与读者见面', '', '人民日报', '人民日报', '《王震与湖南》;', '新华社北京４月１２日电 为纪念王震同志诞辰１００周年，由中共湖南省委党史研究室编著的《王震与湖南》已由中央文献出版社出版，即日起在全国新华书店发行。王震是我国老一代无产阶级革命家、政治家、军事家，在他战斗的一生中，为中国革命和建设事业立下卓越功', '2008-04-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSQJ0b8PSvUQlbCHY3FZZeWGOe9y-Ld4Z-vmydBjXBiP1z2vZ6x7KVM92eg4OoOsR8xByJb55qMj0JEpsuM5PQraPrrMHX7fLeCsb6eOE2p8p1WlbVEBCREsZu7O1pkHcOWTbiHMZHy2Q==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5114, '报纸', '黄埔军校同学会举办“黄埔论坛”', '', '人民日报', '人民日报', '黄埔军校同学会;', '据新华社上海８月１４日电黄埔军校同学会联合上海市黄埔军校同学会、民革上海市委于１４日在沪举办“黄埔论坛”，纪念抗战全面爆发暨“八一三”淞沪抗战７０周年。为弘扬抗战精神，不忘历史，缅怀先烈，激励后人，黄埔军校同学会此次联合上海市黄埔军校同学会等', '2007-08-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQbFKrBWxX1w_cWIBONKDyP8Ld5hF-W7KK9DC2r915qwzqE2oEEOEqSOyDemZPZk1BeV2LtcBesk2S_WBfwPZThXOTWMvF5AS9NxBFO6EL8oEoBGLsyS3-FqFQw2uPwKPrpAixRv4OU-g==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5115, '报纸', '铁血铸就无敌雄师', '朴淑瑜', '科技日报', '科技日报', '叶挺独立团;红军师;实弹战术演习;', '北伐战争中，这个师当先锋、打头阵，赢得了“铁军”的美誉；土地革命战争中，该师坚持党对军队的绝对领导，开创了我军“支部建在连上”的先河；反“围剿”斗争中，该师为创建和巩固中央革命根据地，建立了震古烁今的伟绩；二万五千里长征中，该师强渡乌江、智取遵义、飞夺泸', '2007-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQx0QYknfhvDA9AfapY_ZYzVy5i6N6lF-2o56D5VSpqQdnzgImbmJRef0no1m6OuH3vEYlSd9E3_2o4wXbD-5tnRw-l176favpngoAeHaBZEDbCKNp_LfMocbmRCdxpv4qp7uGw93LQSQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (5116, '报纸', '汉川纪检监察干部情系烈士后代', '胡晓英', '中国纪检监察报', '中国纪检监察报', '纪检监察干部;汉川市;', '本报讯：“这是我们纪检 监察干部的一点心意，请收下 吧！”近日，湖北省汉川市纪 委书记黄毅带着全体机关干部 的爱心捐款，到革命烈士后代 方忠良家中，看望并慰问了重 病中的方忠良。  方忠良是革命烈士方植三 之孙。在抗日战争时期', '2007-05-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS0x_Y0jqAfhThIXv2vcffvlgiEZXJD6ViXZEtFOsS-f1WMl6OhBzjmSYqexDnZJ7mHHnGi7O2RBisVfpEr1eofCad_Cg4Xxqgm_KROI1VSgH4omoP1z3VCfq6H9PuVYCWL85AZBZ8yfw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5117, '报纸', '陕甘宁抗日根据地(下)', '', '人民日报', '人民日报', '陕甘宁抗日根据地;陕甘宁边区;', '中共中央十分重视陕甘宁边区的巩固和建设，提出要把边区建设成为全国抗日民主的模范区。实行民主政治，是陕甘宁边区建设的一项重要内容。从１９３７年５月起，边区进行不分阶级、不分党派、不分宗教信仰、男女平等、民族平等的民主选举，到１０月相继完成了乡、区、县的选举', '2007-04-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR_uSfkctQ-VOXIA3q1Z-LHdlYr96E8lYX_qLJEKQt3O3Kb0uVYWrLBVHxqASgWvc9inYfcVwQTDSsETxV93t-vY35gZyNKWZC7oNVBpbr_HFauEWmWOgJe0C6SiPC6FMwWfLjudkn_Ug==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5118, '报纸', '白洋淀上雁翎队', '', '人民日报', '人民日报', '白洋淀;', '白洋淀位于冀中平原新安（今安新）、高阳、任丘和雄县境内，由９９个大小淀泊构成，面积３６６平方公里。抗日战争时期，在这里活跃着一支英雄的水上游击队——雁翎队。他们利用河湖港汊的有利地形，神出鬼没，给日伪军以沉重打击。人民群众歌唱他们：“白洋淀上好武装，日日', '2007-03-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRF9_k3u0kENCcSz-WkZAE_QNgXdejomv5t6He-edMNZxA5cQcr2352yUwEyL7ziAJc2zmQ3WKgTnIhJNIrK1-gTJBMreaY-2qwzYewWTqF4UXyHB2UhGBQWrYdXuFrjvSc59NhoKjzsw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5119, '报纸', '延安《解放日报》', '', '人民日报', '人民日报', '延安《解放日报》;毛泽东;机关报;《解放日报》;新闻史;', '抗日战争进入相持阶段后，随着党领导的敌后抗日根据地和抗日武装力量的日益发展壮大，中共中央亟需主办一个大型日报，以加强对各地的宣传和工作指导。 １９４１年春，中央政治局决定停办三日刊的中央机关报《新中华报》，将该刊与新华社编发的《今日新闻》合并，在', '2007-02-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR7eNyg_W8cq7BAonFt8GgkE3sOmSrvxlLO6_kMywV4t4O48IRGX0KXWesGn1a1f2GvNfxLvaPUcIBQR24cff8DfPgBeQANq1-OwM5nhcPuGOYW813oV9rb3fgEvx9i1rKIPizNpWqnhQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5120, '报纸', '迎接全国抗日高潮到来的党的全国代表会议和党的白区工作会议(下)', '', '人民日报', '人民日报', '白区工作;张闻天;刘少奇;党的全国代表会议;', '党的全国代表会议结束后，紧接着于１９３７年５月１７日至６月１０日，中国共产党白区工作会议在延安召开。中共中央北方局及其所属的北平、天津、河北、山西、河南、山东、绥远等地党组织的负责人共２０多人出席了会议。张闻天、刘少奇主持了会议。刘少奇在会上作《关于白区', '2006-12-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQB1aIRDPp1VekNbRJVO5USU1fJhPUV7TNABp2D0NxKEKn3cexO9nZ3PJ0uy2sTQ_phH-v7Io204qX0GTWWCuKyJnrV2NsaciR1O5lq73IwSvgX6OUBajal_HCFSSnvBNpzB6EgGm9LMg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5121, '报纸', '在新的起点上', '段兵; 孙江', '光明日报', '光明日报', '法学院;陕北公学;新闻传播学院;', '2006年11月18日，西北政法学院正式更名为西北政法大学。  69年前，党中央决定在延安成立陕北公学，吸引了千百万全国各地和海外的进步青年奔赴这里，毛泽东主席亲自给陕北公学学员讲课，并说：“有了陕公，中国就不会亡！”四年后，在陕北公学的基础上，中国共产党创', '2006-11-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRiqYuKyxAyuFPeATC9vTpWiH_qj8LJ1uA_39FKNHx4L3oA7GF3w7hxccreEAp4Cll1TEpBgvPw7MBMcDVLF_qzf74D1VPtIVNZ7X9qDXKp1S-C-mNjWHjnPQniV7xz-uoRRa2ECMPF5w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5122, '报纸', '长征精神 我心中的灯塔', '郭春雨', '人民法院报', '人民法院报', '吉林省高级人民法院;最高人民法院;', '在纪念中国工农红军长征胜利70周年到来之际，记者近日采访了在第二次国内革命战争中参加革命的老红军、原中国法学会常务副会长、第六届吉林省人大常委会副主任、吉林省高级人民法院原院长王吉仁。 王老住在吉林省长春市东朝阳路一栋干净整齐的院内。推开两扇对开', '2006-10-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRzZbm-Z7J2WbNE9qmVBeGX6Svm9k8-VxgRHV0TsJzfTKn55GekMvhSJsr3M0009fIVRUF-1ieJWwvpr3p-Hk2uvjaBqElezYjbM4b7L0xyIdoqMo4s53cX5mzjtccbSqJvqFd9TF3D3w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5123, '报纸', '中华人民共和国国歌、国旗、国徽的确定(中)', '', '人民日报', '人民日报', '《义勇军进行曲》;中华人民共和国国歌;', '最早建议用《义勇军进行曲》作为国歌的是周恩来。１９４９年７月初，他在审批“征集条例启事”时就说：我个人的意见最好就用《义勇军进行曲》为国歌。不过大家可以讨论，再征求一下群众的意见。果然应征稿中有很多人提出这样的建议。 《义勇军进行曲》诞生于中华民', '2006-10-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ8pQ6d0Aw2zDzIk8BVA-i3kO1EDu0xm6DY6VvqTnPiqVUrP07BS2ToWHb4uDzvJLFEZ6T2bEA0HRyiIpaMYl_TW7CgbpFx0TotfMvGzvo27hurmqtJKKJNpjFm3uZ8hoJnrq6xZ6M__w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5124, '报纸', '弘扬长征精神 履行历史使命', '张国育', '解放军报', '解放军报', '红四方面军;新世纪新阶段;历史使命;', '长征是人类战争史上无与伦比的壮举，是中国共产党及其领导的工农红军创造的战争奇迹。我党我军在长征中成熟壮大起来，在艰苦卓绝的战争环境中，积累了弥足珍贵的历史经验。直至今日，长征留下的丰富而宝贵的精神财富，对于我军现代化建设和军事斗争准备，仍然具有十分重要的', '2006-09-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSGupsl_POHrMIUdeF6ryOKtcFfFUUJNKMWXht2_q_BtFbFYTTyev0NVZuqzHAqRpWj5itOHQrJfhDCEpkDVqTO0867IPS0gXM6NEIvMmavu-E00c8JGbiuV9N75yVNzhz_ufhCqb3kjw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5125, '报纸', '党的七大(上)', '', '人民日报', '人民日报', '中国共产党第七次全国代表大会;毛泽东;决议案;任弼时;', '在抗日战争即将取得胜利的前夜，１９４５年４月２３日至６月１１日，中国共产党第七次全国代表大会在延安召开。出席七大的代表共７５５名，其中正式代表５４７名，候补代表２０８名，代表全党１２１万党员，分为中直（包括军直系统）、西北、晋绥、晋察冀、晋冀鲁豫、山东、', '2006-05-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQgWNGufxmrJYNTi27NDBuu8GEhHkEB0G-n0sZd4dCMMF2cQvawjrQGK1cAbzLedUGiqmMQ14NofctWruc4PXd-LQv0LVj9pKpOYjeLj015xQqwzSTuTd9mXugTe4sOCp03r9rcbmqauA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,抗日战争5_screened,中共七大1_screened,中共七大1_screened,杨家岭_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (5126, '报纸', '爱国主义教育基地对学生应免费或低价', '蒋夫尔', '中国教育报', '中国教育报', '爱国主义教育基地;免费开放;', '爱国主义教育基地及一些革命传统教育基地对学生实行低价或免费开放，这样才能达到弘扬爱国主义的目的，为青少年成长贡献力量。参观收费会影响中小学生的参观和学习热情。  “当我和同学们为了更深刻地了解抗日战争的历史，来到当地的一家革命历史纪念馆，却被告知要', '2006-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSYq-FywO8QIAm-proNcbehkYGu8HKbPsurNefxbylt2pR5hUK88CvGI5q-CJkTu81n_MhQMUaHsrZtgjm_X4a1BYA9MjznAgscZZny40Lie50ZbCbqFuvjPgYNU9DF6ICkic6J5RxbkQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5127, '报纸', '刘亚生', '', '人民日报', '人民日报', '刘亚生;三五九旅;胡宗南;', '“德才兼备，英勇牺牲的楷模———刘亚生烈士永垂不朽！”这是1983年，王震同志为自己的战友、35年前英勇牺牲的刘亚生烈士的题词。 刘亚生，又名刘伟光，1910年出生于河北省河间县，1927年考入保定第二师范学校，1932年考入北京大学历史系。1935年因积极参加抗日救', '2006-03-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtThv1JKN85s73SUBA0lpSGuVFJTMieLTV9Q6Cf2m0RnPcN3yvW-Ic9ZYmT77ijQ7dL79WyZIohi7csl6UdSjpYZBO2gXgPB8djS1vZ9aJ2PlyW1K92pXJvCe-sG3jLUFsx4at1NCI00sw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5128, '报纸', '陈海松', '', '人民日报', '人民日报', '红四方面军;陈海松;', '1935年6月，红一、红四方面军在四川懋功地区胜利会师时，时任红四方面军第9军政治委员的陈海松才21岁。为红军中能有这样年轻的军政委，毛泽东等中央领导同志感到由衷的欣喜。 陈海松，1914年生于河南罗山宣化店李陈洼村（今属湖北大悟）。1930年春参加童子团，任大', '2006-03-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSIMG4p_AZ2fxVxNXhGeK9AAgt7qov89VDbx6UKns_X_rpStAT-Im8HMLNMPN94bM8274qSzGmfKthtgxNd71kSeQP5KAqxAH-827idoQImWquhhIfPnuSRiL2K2Jkqk3wYj7ADUP7a6w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5129, '报纸', '把别人装在心里', '杨连元', '工人日报', '工人日报', '丁晓兵;', '丁晓兵所在的部队，正是全军声名远扬、威震敌胆的“皮旅”。　“皮旅”的称号，源自部队领导皮定均。在抗日战争、解放战争、抗美援朝战争中，部队作战1000多次，歼敌11万多人，立下赫赫战功。　记者在采访中发现，作为这支英雄部队培养的众多英雄之一，丁晓兵在官兵和老', '2006-01-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTN4az-V6xk69ZFB437pmIPAmVs0THeiwtVnGNop2Y7i1-Q0LHVfY8O7PPgViMWj6fGdzfLDW2s1iImE699MMDEeBbDjTm7e9Ms74MEk063hulTSuNBxRd14FPfZ__cpf5ka1vkUerS9A==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5130, '报纸', '情系临沂新发展', '何建昆', '科技日报', '科技日报', '临沂经济开发区;临沂市;工程机械;', '10月30日，九届全国人大副委员长吴阶平 以80多岁的高龄风尘仆仆来到了革命老区沂蒙 山区的山东临沂市，这是他第二次来到临沂。  临沂有着辉煌的历史和光荣的传统，沂蒙 山区是山东最早建立中国共产党组织的地区 之一。抗日战争和解放战争', '2005-11-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQpDGH2HPglWYCT3mxRo2xTRNiJ-NJyd8by0E7a55i9ktDU7kjUzwR2gVNkF7QRsvjYSVnQx_caAeVTxZSTze8bpYe2aDcv3xNpaHWtQYYesoxEPrnpr1Zxdj6AomfNppMNIj_WyPZ6OQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5131, '报纸', '医疗救护战线上的女模范——丁志辉', '', '光明日报', '光明日报', '丁志辉;医疗救护;新四军;', '丁志辉是中国人民解放军医务工作模范。女。1918年生,江苏无锡人。1939年参加新四军,1940年加入中国共产党。抗日战争和解放战争时期,担负战地救治工作,在黄桥、辽沈、平津等战役中救治了大批伤病员,被评为“模范党员”、“模范医务工作者”、“模范女干部”。 1941年', '2005-11-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRvd8XFwDsJJjOVpbdttv_iNMZaMrCp9H4CclygSgiIx4UgpFdANYE01JaS97KrdUKHdZzxXhBKAZCeeZs8vLF_Z75Ewi1RKc44IqLsRd1Wx5HYvBmp3FF2UGmByHqJ_pmXkYjCaVmoXg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5132, '报纸', '谢祥军', '', '人民日报', '人民日报', '新四军军部;', '谢祥军，1914年生，湖北大悟人。早年就追求进步，向往革命。1930年参加中国工农红军，次年加入中国共产党。曾任红四方面军排长、连长、营长、团长、师长等职，参加了鄂豫皖、川陕苏区反“围剿”、反“围攻”和长征。他作战勇敢，不怕牺牲。一次战斗中，他腿部受重伤，由于缺', '2005-11-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSusZWWXczUdLTv8s-pr4LgiCcxE3f9IcOjSgf16mpRDrX9kYI3Hf2zxYB8I6C_-rel2tXEA0dalHS5Flx1NV_glbj8hMgBNpxIGQNEc8urriDniWrrahqwsQczie276bI1H1JNVFp10g==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5133, '报纸', '甄济培：出生入死杀敌寇', '黄庆畅', '人民日报', '人民日报', '百团大战;', '人物小传 甄济培，82岁，河北唐县人，原北京军区炮6师政治委员。1938年2月参加革命，当过通讯员、司号员，历任班长、排长、政治指导员、副政治教导员、政治教导员、团政治处主任、团政治委员、师政治委员。抗日战争时期，参加过“百团大战”、反“扫荡”、解放张家', '2005-09-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQuXNw_vFpDwTNnKZBHKgDwj6DhbZp7gnH3AbS80RBNcpIJk6A7lLGcOEQ91A9v5Av7HucfLOPddGYJ92NIvDN7fYOOZCf35uoaBCdx29NQPInHY5P1q660Eydx7NPhDDnXjl7PQLBusw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,百团大战_screened');
INSERT INTO `ds_article` VALUES (5134, '报纸', '日本友人 加藤克己', '', '人民日报', '人民日报', '新四军;中日友好;', '加藤克己1918年1月21日生于日本九州大分县。他是家中3兄弟中的次子，学生时代成绩优异。毕业后就职于三菱制铁公司，1940年被强征到中国战场。 加藤对侵华战争很反感，内心是反对这场战争的，在驻扎安徽省蚌埠市时，因拿军中的食品和日用品分发给当地老百姓，被关押', '2005-09-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTO2s47y_gjBWtI30Fxrf8yvlp6wHhALJMJf-3_ylAO7ChXpH8E2aC9PGcZhQLXh7E3-dY9RXxs-xLE6fPKRnIhToe9CPrP0bkTYeK7Pc-GpDeabBZXdBANi5saARvFTcy68PinTLTPEA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5135, '报纸', '国际友人与中国抗战', '张胜男', '光明日报', '光明日报', '中缅印战区;医疗队;司令部;根据地;国际友人;海伦·斯诺;工合运动;马海德;埃德加·斯诺;新四军;空军志愿队;', '“我们的敌人是世界性的敌人，中国的抗战是世界性的抗战”。中国遭受日本法西斯的疯狂侵略，中国人民艰苦卓绝的正义斗争得到了世界上爱好和平、主持正义的国家和人民的深切同情和真诚帮助。来自五大洲的国际友人与中国人民患难与共，从多方面给中国以实际的援助。  参与', '2005-09-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTe-pKp5fFvkAlf6bfzoIt8v7-pERrQJ8XeP2tmc53Ih8tTIw8aELCd4jse1auKLrrcM_0ikn_wT4_nqDo2GGwc3D6PQER-94IQoG2RdZoMpYNTtN1Xp_laMrNHr0t9SCa3P6m0J9pMjA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,百团大战_screened,中共七大1_screened,白求恩_screened');
INSERT INTO `ds_article` VALUES (5136, '报纸', '大青山的回忆', '包国俊; 温庆生', '光明日报', '光明日报', '骑兵支队;抗日根据地;反扫荡;游击战;', '8月的军事科学院干休所，金风送爽。80高龄的八路军老战士郑肇东，向记者讲述了60多年前，他在内蒙古大青山骑马打鬼子的那段往事。回忆起那段艰苦的岁月，老人无限感慨，言语中流露着对已牺牲战友的深切怀念，对草原蒙古族群众的万分感激。  1938年9月，年仅17岁的郑', '2005-09-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQH8A9C53NX4xu3YWTNB1vgcNR0aSMlm73r4adRM3NtkVVnvKDYM7arn0nszhb82nijh2K3lc1er_kRM5jF_iNtjkF1vW9oy2R8t94Bw7LPubnZgGNVoN351FHw4c8x0wTZkp4t2g5usg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5137, '报纸', '《我的鄂尔多斯》再现成陵西迁的历史画卷', '阿勒得尔图; 牧兰', '中国民族报', '中国民族报', '成吉思汗陵;《我的鄂尔多斯》;历史画卷;鄂尔多斯;', '反映抗日战争时期成吉思 汗陵西迁的18集电视连续剧 《我的鄂尔多斯》已于8月28 日在中央电视台八套黄金时段 开始播出，本剧以蒙古民族心目 中的圣地、蒙古族的精神象 征──成吉思汗陵西迁为背景， 描述了两国四方（国、共、蒙、日）', '2005-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT7wFbvcfb6IYUgF4x7VFOm1oWh5x5HyKTEwDpPIi_53sQiOHMlx3qSKnWa1TUGgpoAtofwpNF-UFb_dnHUJGAobokfBrswVGTRtkRbrG7_E8LJ540d6MLPgoTrIk0snA4jjyXGfcOU6Q==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5138, '报纸', '罗生特', '', '人民日报', '人民日报', '罗生特;新四军;八路军山东军区;', '抗日战争中，在新四军和八路军山东军区中活跃着一位医术高超的外国医生，他就是被陈毅称为“活着的白求恩”的奥地利友人罗生特。 罗生特（原名雅各布·罗森费尔德），1903年1月出生，犹太裔奥地利人，毕业于维也纳大学医学院并获医学博士学位。由于受到纳粹迫害，他', '2005-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRkgvAijh53xoHhTGX_G_4hpM0Ub5B0lR25ygVfQoPu6_LJrhwUA3M2-4SnTmn6T2SzYXPOvQoeXkDXg10aSfe6AqxFrYTx7sR6ZZNY8KQQZzgh5Njj6V7McCyi2UEFATwdsPcuZhFA3w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5139, '报纸', '北京中小学开学——— 爱国主义第一课：“唱响国歌”', '王建新; 杨明方; 李舸', '人民日报', '人民日报', '爱国主义;中小学;张自忠;北京市;中小学校;第一课;', '“起来，不愿做奴隶的人们，把我们的血肉筑成我们新的长城……”9月1日上午，新学年开学第一天，在北京市朝阳区白家庄小学操场上，近千名小学生注视着五星红旗冉冉升起，动情地唱起了国歌。 “我们今天的幸福生活都是革命先辈们用鲜血换来的，我们一定要好好珍惜，', '2005-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQ2kOuBKJ78d4lP1uTpq2jWGEaQKkZrndPBy6Mb9qv_MDytWxaNhMPiE6xiOQH9PB5eTC7dgQydJF9-13g3mSPeZW1XHiydqr21sBcLNQ-wC6scy4jsdxEjxxzuPgOQOGpw5bQqojZdDA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5140, '报纸', '李昌：为抗战呐喊', '金玉萍; 邹爱华', '中国纪检监察报', '中国纪检监察报', '民先队;抗日救亡;', '秋高气爽，天高云淡。8 月17日下午3时，北京东总 部胡同34号院。一排简易平 房内，91岁的李老正戴着老花 镜，坐在房屋中央一条长桌 旁，认真地阅读文件。  “日本帝国主义强占中国 领土，烧杀抢掠，爱国的学生 们忍无可忍，用鲜血和生', '2005-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRoyd-x2K5Qwc4aYzG_5GxqnB4zk1zZgDCbMja5GhfMBbAuwYpNGZdWxs_eOuTEJfxBXSFQ-jyimeDGX97jSNtzDzUpj6Lao-d0Stbb1XtkZPL0MvOXfJzcQeWxQ7N3btkZOGg3kE5_Pg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5141, '报纸', '地狱深处怒火喷发', '王曰文', '中国煤炭报', '中国煤炭报', '日本侵略者;', '60年前，中华民族取得了抗日战争 的胜利，结束了日本侵略者对中国人民 的欺凌和残酷掠夺。  据史料记载，日本侵略者1936年至 1945年在阜新疯狂掠夺煤炭资源，犯下 了累累罪行。10年间，日本侵略者共掠 夺煤炭2500多万吨，7万名矿工被虐待', '2005-08-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtT9D4njNnWav0GOPzmmj0d7TLYZJl3NVJ5SKcnzOtXjBCHh0M_kQLypWMfdmY-UotgORUU8Z6omwHem_PcdlWyL4nVSjeLHfthSxf4Sh4-tKsScWADLNyNeNz-AGBYuRu3Ub4V6jjkXwg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5142, '报纸', '庞然：义勇军英勇顽强志如钢', '孟德成', '中国纪检监察报', '中国纪检监察报', '义勇军;李春润;', 'T庞然，1918年出生，辽宁省新宾县（今新宾满族自治县）人。曾 任中央纪委审理室主任，第三检查室主任，打击经济犯罪办公室主 任和办公厅主任（副部级）。1932年参加辽宁省民众抗日自卫军第 六路司令部宣传队。1937年加入八路军第一游击队参军入党。E  ', '2005-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTXK8QbH2gtPVk2m94hWlrHrwQUcUgXyGOpL_vRCGy1AgHGqJq0-PZZFD8fA_JdgYXERxzM90EswSqVpM7jo_ec8XrUi6tB0pV08spyBsRjNBYtpOaQpb9I1G4xXzWqb8FnFr51Zj97GQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5143, '报纸', '不忘过去 珍惜今天', '', '中国文化报', '中国文化报', '木刻;版画;', '8月11日，在北京协和医院的病房里，记者采访了当年参加过抗战的革命老人、木刻艺术家彦涵先生。 问：在纪念抗日战争胜利60周年之际，您作为曾参加过抗战的革命艺术家，一定对那段岁月记忆犹新吧？ 彦涵：应该说我是战争的幸存者，也是见证人。1937年卢沟桥', '2005-08-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS_al89FuRrpSUB4ntRMvaGQ540CkJorWQShR3wxUX_t9sPowApg1IkKLWfzAxFeGP_G5VMtbCjJUtQ1iL6gfMusrszcaPQ_eAI9pM7wAMIjGCTtJnJytS0psFfHJx5MTtvdW-cfD1wdw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5144, '报纸', '广东系列活动激情澎湃', '刘松媛', '中国文化报', '中国文化报', '冼星海;人民音乐家;系列活动;《黄河大合唱》;', '本报讯 今年是人民音乐家冼星海诞辰100周年，抗日战争胜利60周年。为纪念这位伟大的人民音乐家，弘扬以爱国主义为核心的民族精神，按照中宣部和广东省委宣传部对抗日战争纪念活动的宣传要求，在广东省委常委、宣传部长朱小丹指挥下，该省精心策划、组织，于6月12日至9月30日', '2005-08-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSyr83MBYXiAVUbfd0VY7s9174uRl1_crzcxCmIObXUcl1hXHjboiDvycEUAS8ztR8xpbbaWTL_wB5thXVkdabcToFciUfzTsSrC11R3qpldkjbQp7eSsjvlTcq48iFNWwbsjc_Wi-jWg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5145, '报纸', '中国，我为你骄傲', '张静宇', '人民日报', '人民日报', '南京大屠杀;', '夕阳映照在宛平城头。城内象征中华民族觉醒的雄狮铜像被镀上了一层金色的光芒。11日晚，位于卢沟桥畔的中国人民抗日战争纪念馆在神圣肃穆的气氛中，迎来了一批特殊的参观者———来自60多个国家驻华使馆、商务和新闻机构的200多名外交官员和国际友人。 他们当中，有', '2005-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQp4oLtZrJJadjjcZrzlKruErRnpn8G1NvPaC5Xv9S-PgeS3IuvDbSkjpxYQIO-IEPPv3lua6WJieeQs14MxVjQiI5gh1zDxx4fKTwfti9-jdxobwftA2iqPtlZ8gi8VgR8AGE0AXqNKg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5146, '报纸', '李兆麟', '', '人民日报', '人民日报', '李兆麟;东北抗联;东北抗日联军;', '“……朔风怒吼，大雪飞扬，征马踟蹰，冷风侵人夜难眠。火烤胸前暖，风吹背后寒。壮士们，精诚奋发横扫嫩江原！伟志兮！何能消减，全民族，各阶级，团结起，夺回我河山。”这是东北抗日联军创建人和领导人之一的李兆麟在极其艰苦的东北抗战岁月写下的《露营之歌》，这支歌成', '2005-07-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRAK4fCQxMt5wFuI8_jSMbo2AlL05FktxbeQXh0HTNirE_YkKV7r3KlWmHymQ32t1ZikFAChG0JavYPcw3pFBlgi5qyutmIMnjJS2GDBrqBmcDOcHuJkwMyTuDXf8APRAgVIJYR1k1RmA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5147, '报纸', '千万不能忘记：卢沟桥的枪声', '赵鹏', '新华每日电讯', '新华每日电讯', '卢沟桥;', '7月7日是“卢沟桥事变”68周年纪念日。68年前卢沟桥的枪声，揭开了中国人民反击侵略、全民抗战的序幕，中华民族自此血火抗争直至赢得抗日战争的全面胜利；中华民族的百年衰败沉沦自此开始扭转，古老中国从此走向民族的独立和自强。  68个春秋过去，中国已不是过去的', '2005-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtToXx3Ig5rN-AjvmLPIi-HqDQLTwdI2-ZVR8P5HSQaUahXIsAFv7tmVQ6Ll3ToGBahYeSGfrutoThj4RBG5ZHjy46Twu0ZiIN-cGUaIkLkOQcyZkgUp9GsOc0m7cYana6wwgGwh2b00ng==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5148, '报纸', '“为日中友好决不退缩”', '张静宇', '人民日报', '人民日报', '中归联;抚顺战犯管理所;', '60年前结束的那场惨无人道的日本侵华战争，不仅给中国人民造成巨大伤痛，也决定和改变了一批特殊的日本人的人生追求。曾经亲身参与了当年那场野蛮战争、并在抚顺战犯管理所接受过教育改造的原日本“中国归国者联合会”（由中国政府释放回国的日本原战犯组成的进步组织，简称', '2005-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQq_xp5_uxxYM05dLTqyAKHaQhnR0vbaBUru03WhN2lbPDTX-Eq8hDZT3TsoNLkybg1ldYAa5w-R-KfGvQ964Wxup_E35h6SaJUOT9nK7LGORy3swCJwkRrhDQS7n73gr7oM6r0fRPyHg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5149, '报纸', '桂河大桥的诉说', '', '本报记者组;', '人民日报', '桂河大桥;', '一条铁路，埋葬着十多万冤魂；一座大桥，见证着60余年前日寇无比残忍的战争罪行…… 今年是中国人民抗日战争暨世界反法西斯战争胜利60周年。本报记者组5月下旬赶赴泰国西部的桂河，踏访了那条被称作“死亡铁路”的泰缅铁路及有着“死神之桥”称谓的桂河大桥。', '2005-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSMSa49n4WvCWp0WJx3Q0nLHSjTprcv2PNCzGFufAB3_2Ry9WtcWtDIY1XPYkJ1RYiKvLfwUGaUU0yF52yv7u_FjLZBr2UaeU8uSstv_ItgV_hCpg-tmF2ikHgmVAa9QPoeLPPv20YAvw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5150, '报纸', '人艺老将再演《屠夫》', '蒋多', '中国文化报', '中国文化报', '首都剧场;北京人艺;《屠夫》;', '本报讯起立鼓掌和高声欢呼的人们久久不愿离去，大家知道这样的场面也许再没有下次。5月25日，北京人艺在首都剧场上演《屠夫》。在3幕11场共两个半小时的时间里，这部为纪念世界反法西斯战争胜利暨中国人民抗日战争胜利60周年而复排的德国现代经典话剧，除了将人艺鲜明的现实', '2005-05-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRHtvDPKcIMbj7eX2fA3_HaQbmOiCGu4p-JOEvGl-Aw2gFZdyIAFHKo4o2k3mr2ZwfzBdgp89B5iVp473fB28ECp1KVgzFN7fmA9T67DIMGSoKaXpuXEVCgT5ukXz8duwB0auCDsSWirQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5151, '报纸', '重庆各界纪念张自忠殉国65周年', '张琴; 方立新', '新华每日电讯', '新华每日电讯', '张自忠;尽忠报国;', '新华社重庆5月16日电（记者 张琴）16日，重庆各界人士 隆重纪念著名抗日爱国将领、原国民革命军第33集团军总司 令张自忠牺牲65周年。  在重庆北碚区张自忠纪念馆，300多名来自重庆等地的 各界人士参加了此次纪念活动。少先队员、军人、张自忠牺牲', '2005-05-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR_iA4sDEAiaz9wN_MbEeptC0Y4MnylBMp14kOV8bfkLNoF0fjNJgHFAyDXUODq0p0ET7ETImjzf03fhEwd1KUKy6V5_O7SGdH9PENiTpkJnHWI1Wv81rZqIvfhirxlMgF_FsNIv7T6Nw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5152, '报纸', '牢记历史　共护和平', '王恬; 吕岩松; 马剑', '人民日报', '人民日报', '反法西斯战争;卫国战争;俄罗斯;纪念碑;纪念活动;日本侵略者;', '欧洲战场：苏联人民为世界反法西斯战争的胜利付出了巨大牺牲，谱写了感天动地的壮丽诗篇 亚太战场：中国军民粉碎了日本军国主义称霸亚洲的野心，为世界反法西斯战争的胜利作出了重大贡献 雄壮激昂的乐曲，迎风飘扬的战旗，整齐威武的方队……5月9日，莫斯科的红场', '2005-05-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTAyEhND4v9Nwul_1QVdjWGiSbE7hQJeB9Bw9D2nDRRZTBJMaeqIgNxseUVZfkQkGf2R-w_zVDjPnF2MoQIRqj5iikq6_xogBAVDFnj66i3hYy7PTjzlTx7NBv1cL7yhCGF7eTnPCptOA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5153, '报纸', '二战，假如没有中国……', '贾永; 徐壮志; 冯坚; 刘芳; 晓墨; 陈玉芬; 何毅', '新华社记者;', '新华每日电讯', '反法西斯战争;印度洋;', '5月9日，欧洲反法西斯战争胜利纪念日。  60年前的这一天，整个欧洲都在泪水中欢歌而在亚洲，进入第15 个年头的中国抗战仍在激烈进行。中华民族的最后胜利，还要等到三 个月后。  抗击时间最长、付出代价最大、牵制和消灭日军最多对于中国人 民', '2005-05-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQfVjLfDZuMsUL391LugEL2PFhg5UL5JbHn5z_6xEL-aGTqv8Rrl9Ur7m7X7QMgjNPcrfdBRaotkAHSjZu30Pw8ZgMxQkwxJzD8hDVh5Mj8a2hZm3e2Far61w9bG-4SuLUbYQ3ejH-xGg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5154, '报纸', '边区英模赵占魁', '', '人民日报', '人民日报', '劳动英雄;革命者;', '赵占魁是一位用革命者的态度对待工作的“新式劳动者”，山西定襄人，1896年出生于一个农民的家庭。他是抗日战争时期陕甘宁边区农具厂化铁工人，是在生产竞赛中涌现出来的劳动英雄。 赵占魁1938年到延安参加抗日并加入中国共产党。经过抗大的学习，他清楚地认识到：自己', '2005-04-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQaWgPcmsGOTcvxBk5H5_OIhnG1tD3O_8fDt6LivWkakYnHvpRr981jvKbx9GPdq_osum0obSraY5XUdlqrYmSd69Qj3zdW1xzDB8FmgqCvjpChzJyGY2HsLIvmAhW_IJRC09s4tJVbJw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5155, '报纸', '悠久“永安”今日安', '', '本报福建报道组;', '中国财经报', '纤维板;上市公司;永安市;', '“永安，建县于1452年，历史上就寓有永久安定之意。现在，经济发展，百姓富足，真的是永久安定了！”汽车穿越在一个又一个隧道之中，当地同行的同志向记者展开了永安的美丽画卷：“这里森林覆盖率83.2％，木材蓄积量居全省第一位，毛竹面积76.8万亩，为中国笋竹之乡。抗日战', '2005-01-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR812hChsBLcXyHNe6YN2eQRj4uo-3inMvcYTNXSzxP-fjT_DPdgfDKN_A8B4TOPrqLOE7hoI6ie794wQ-Gx-eDPqnJgg1aPkS6oW4wNvGQdjGw6Z5KlhaMhSVwOXYOd9KSl-gEC-dS6Q==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5156, '报纸', '芦苇荡里好风景', '苏雁', '光明日报', '光明日报', '沙家浜镇;阿庆嫂;', '沙家浜,给每个走近它的人以惊喜。广场上十八位新四军伤病员的雕塑栩栩如生,一望无际的芦苇依水迎风飘摇,依稀可辨战火纷飞岁月的痕迹;宽阔的公路两旁农民别墅规划整齐,生态工业园内大批外资企业落户投产。一位新四军老战士感慨万分：“想不到昔日的抗日革命根据地能有今朝这样', '2005-01-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQcjUXNqCRfhhmzYcMxMvq7hXM2Azvvnjm3Vu_YeFlnK7OIlr6qskBzzgklhwDIxa8cWe2VIpRy4NeTYFnWCm3wBdoaMjt5RaYvtmR1ezY1-A4D0iQRPLDId91_Hi-hsukRScdiD42ZZA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5157, '报纸', '历次大阅兵展现人民军队发展历程', '白瑞雪; 温庆生', '新华社;', '光明日报', '天安门广场;歼击机;李水清;第二炮兵;骑兵师;机动作战;开国大典;北京军区;万国牌;', '87岁的老将军李水清多年来保持着一个习惯,每年“十一”这天,无论天晴还是阴雨,总要到天安门城楼前走走看看。 55年前的开国大典上,作为受阅部队陆军师长,李水清率领1800余人的陆军方阵,第一次以新中国军人的姿态,昂首阔步走过这里。 “那是我一生中最漫长的等待', '2004-10-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQrPpNgVkVPe-QuhIB2iWROIvINvACsnfaNPjYEcz9h27cxDKg1ruVgwT1Xj0uNcF1Xha9a3lUbnZcflPAL5yxf87SwGel07PVWcOYSj6iMsOejUe9d7HQFCRoH7PBypbZxPj9kXZfOqw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5158, '报纸', '“应把每年7月7日定为‘国耻日’”', '王燕萍; 李晓玲', '新华社;', '新华每日电讯', '南京大屠杀;日本右翼势力;侵华战争;卢沟桥事变;国耻日;', '当日本首相小泉纯一郎将参拜靖国神 社作为每年必为之举之后；当中国劳工向 日本索赔遭到驳回之后；当日本通过蓄 谋已久的海外派兵大大突破战后和平宪 法的限制之后……“七·七”事变纪念 日──这个烙在中国人心底的日子，更 激起人们对历史的沉思', '2004-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQI2hjN4ikEVwd_yqOJJr9nxT-UFdYVXBQUWjWoxbjyXu9knN_3kVqNbaVbhQRd-4c57ZRbNtDBUjZ07836Kg5Uy99D4ODKmcVKkIrAeuxxbKxUNFwP-Q1N7aimdi2BsOMQgbq_Xigfrw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5159, '报纸', '洛阳王礼锡墓遭破坏', '谢琰', '光明日报', '光明日报', '王礼锡;爱国诗人;作家战地访问团;', '本报讯　65年前葬于河南洛阳市龙门西山的著名爱国诗人王礼锡墓被人平掉,墓前的石碑也被砸为几段。当地文化界人士对此大声呼吁：历史文化名城更要重视发扬爱国主义精神,保护历史文化遗存,王礼锡墓不能毁掉！ 据当地群众反映 平墓砸碑系洛阳市洛龙区有关部门所为。当', '2004-06-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSSeN_B81aTvPo8TCY8JYIHSg1gfEgEWD0-p1APRz0EglMg9kRvlYCV4NwmDdXJMEI8oebf-QeR0LJWGHR1BrXmGlk5O4bGzYk5ZWzChD5NoqfD_E9YNoMA9WhavgFxL_tXMgljrJ034w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5160, '报纸', '电影频道展播红色经典 荧屏高扬“心灵的旗帜”', '', '人民日报', '人民日报', '电影频道;红色经典;《青春之歌》;', '杨利伟的太空之旅，让我们见证了英雄对于一个民族复兴的伟大贡献；张晓晨们的衡阳救火，让我们唱响了一个民族送给英雄的不朽赞歌。俯仰中华民族解放、复兴的历程，那些为此抛头颅、洒热血的英雄人物，犹如一颗颗璀璨的明星，苍穹都因他们而深邃，银河都因他们而浩瀚。现实生', '2003-11-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtROxSbav6q0aXBjpbwYYSVodpSCm7JF9D4XlUfUlerlNQFM5wrGl0rcwqt9Sc9R6YrUfz3LJnKGB4dfmsUG4e2N2ubJ6L_gAueaWIocBPdKk14Eu0AcKGxWhNl_p06GNP0lJ4tbPNO_mg==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5161, '报纸', '9·18，难忘那个悲惨的时候', '张宝印; 张琦; 王永国', '新华每日电讯', '新华每日电讯', '沈阳市;第七三一部队;', '“九一八，九一八，从那个悲惨的时候……” 这首唱了半个多世纪的抗日歌曲《松花江上》，倾 诉着东北人民曾经遭受的深重灾难。  “九一八”前夕，在东北这片黑土地上，人们 纷纷以各种方式纪念“那个悲惨的时候”。走进 “九一八”历史博物馆', '2003-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS8AHwAU7pjw7Hsp8YZNS0PP3vEM8bsKOOBklnEAXV81U_kM4ZslrAQqlwB98bXdIizPWv_7ukM9DaVvQW6gtS5-I2BVLpp1hS6eobU72dhHRHtDIaBPx9YMTaedP16G_MvyuvcWBp4fw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5162, '报纸', '让爱国传统代代相传', '王凡凡', '新华社;', '人民日报海外版', '翁泽生;爱国传统;', '“此时此刻，我特别想告诉大家的就是，台湾人民是具有爱国主义传统的，应该牢记这一点，并把这一光荣传统在台胞中一代代传下去。” 七月十六日是爱国先烈台胞翁泽生诞辰一百周年纪念日，台盟中央与全国台联将在厦门举行纪念大会。会前，应邀前来参加活动的翁泽生之子、', '2003-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQvRE9JUgTQJZcnpD_e4FjrscrrjDVWOObAX2pWl1trBO6q4q3zCqD-xsEBqSjCjTy28hmu6Krx_WBjGz5dSUsTMhyGR3gtRERy-Ew3pd3q5UOqBJnEhvXy35eAE0Nj33VP9sf0o6D9BQ==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5163, '报纸', '沈阳各界人士批驳日本全盘否认侵华战争', '姚剑锋', '人民日报', '人民日报', '侵华战争;', '新华社沈阳8月15日电（记者姚剑锋） 57年前的今天，日本帝国主义宣布无条件投降，中国抗日战争取得胜利。今天，沈阳各界人士举行座谈会，纪念这一历史性的日子。 座谈会上，参加抗战的革命老前辈讲述了他们年轻时浴血奋战的情景。一些学者和其他社会人士也对日本政', '2002-08-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS0WldQXU4iGn6IsnB72y6ET-vMZGD0ajCawdtp6mTPkM1CU4Zk2cQbqUqrcVfDvC-_rv_o3xtx5wtIyocSAmWC8w8UoNiRGSF3hORAnQ0nVz3Q4c_BGIMpAHw3HPVrZGNI3siqutztRw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5164, '报纸', '江泽民观看大型展览《毛泽东与文艺》', '丁伟', '人民日报', '人民日报', '江泽民;文艺工作者;《毛泽东与文艺》;毛泽东;大型展览;', '本报北京5月26日讯 记者丁伟报道：中共中央总书记、国家主席、中央军委主席江泽民今天下午来到中国革命博物馆，观看了正在这里举办的大型展览《毛泽东与文艺》。 一帧帧图片、一件件文物、一篇篇作品，勾画出一幅中国革命文艺运动和社会主义文艺事业发展的历史长卷', '2002-05-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtR76mdW5RHdJjOG4oiCBamskAd-hl76iQ1g-5BLj10uj_7rcivN7_E4bNghheqR6OOhORBvSgUGU_r6dG7r7S87MVI6QZQAA5wqZa8GxKPxzJGb0SA1JlKP4PQ5OrB0bkk8_tVmFecWoA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,枣园_screened');
INSERT INTO `ds_article` VALUES (5166, '报纸', '以史为鉴 登高望远', '邬焕庆', '新华每日电讯', '新华每日电讯', '以史为鉴;登高望远;', '70年前的9月18日，是一 个让中国人民永远难忘的日 子。“九·一八”事变是日本法西 斯大规模武装侵略中国的开 始，由此也开始了中国人民长 达14年的抗日战争。  每年我们都', '2001-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTfBHRUTQ1M3xSJNgc2S8oY0DUXkH7xRollYDMTK3EvlmKhGJXFIWq61TOg9Jbjon5NR1ySXjtGHOvaMEhtG4tpn2a8NK19zYjHPbX5YXX38V75o_lh-o1K17mnfFHGIKp9OOTgqLyUFw==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5167, '报纸', '历史和人民的选择', '王树成; 刘江; 李烽', '新华社;', '新华每日电讯', '中国共产党;李大钊;', '朴实无华的人民英雄纪念碑，在天 安门广场巍然耸立。随着“七一”的临近， 天南海北的人接踵而来，追思英烈，寄托 发自内心的崇敬。  从1921年到2001年，中国共产党由 成立而成长而成熟，经历了奋斗与探索 并进、光荣与梦想交织的80年漫', '2001-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTXIgPo20Tb6jZ2KHs70-QQlw36B4tOWD3iVJje-u7Z2h8KT21ljKXz93AI8U-IEL_Yb6AEA9Lcn5OctmBLiMRW4LAeKVuvFOAXCbRn1OOEKRvE1ZzlXjTDwbnn7vh1gL3hgF6AoafD8w==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5168, '报纸', '红军长征', '', '新华每日电讯', '新华每日电讯', '红军长征;共产党;红四方面军;红二、六军团;右路军;', '由于王明“左”倾教条主义 的错误领导，中央红军未能打破 国民党军第五次“围剿”，被迫 退出根据地进行长征。1934年10 月10日晚，中共中央、中央军 委率红军主力五个军团及中央、 军委机关和直属部队共8．6万人，被迫 实行战略大转移。', '2001-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtS1inVv1hcah9mEbcIvD6JmJDuLCK6XyLbXLd4qIPNi6GO92_-h1y8xOkCRIM_BlPSwN4v5WhIJbE8upIR7U4EP9McXaN3U_urNFROCPP4u_TqlWdIMgMSGfPc-6TFoOxTdEmK23WTNkA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened,夹金山_screened,遵义会议_screened,四渡赤水_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (5169, '报纸', '广州“十九路军淞沪抗日阵亡将士陵园”展新貌', '彭宇; 萧秋荣', '人民政协报', '人民政协报', '保护和修复;广州市政协;十九路军;', '本报广州讯（记者 彭宇 通讯员 萧秋荣）10月26日，广东省、广州市政协 联合视察了广州“十九路军淞沪抗日阵亡 将士陵园”的保护和修复情况，认为历经 省、市政协十年呼吁和提案追踪，保护和', '2000-10-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRvb3p6Hrwbu1tKMJWbStNh__v2wVCIoaCAMAYj6jTUukdfEAUFq1797qGwTJozMJavLE5KB1hVQ3-Bv09wuWuA5WgBbME-qJb1ZJ4umGAX2sX6bOP849z8i6-kkXU6lQhx8i5yOObM-Q==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5170, '报纸', '榴乡行', '任之', '人民日报', '人民日报', '旅游;榴花;游客;', '金秋时节，记者赴抗日战争时期铁 道游击队与日寇浴血奋战的山东省枣庄 市采访。  在峄城区榴园，沿途星星点点的榴 树点缀在田间、山坳、屋前、道旁，越向前 行，榴树越发多起来，一株株、一丛丛、一 片片，蓦然，一幅壮阔的画卷进入视野', '2000-10-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtQHtBYWOWU1gM3xZvW1xUwzhSgQePRwRwDzTVYE14maL7AJECNv0u1XsI3PUu16xzA_-_kJTD1XJ2TlrOn3gguj6BwUWniYU9CBOpof2zOF5KGnbzraSTwA7t0xOmc5S-pXthJNoPjm5Q==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5171, '报纸', '长沙发现日本侵华纪念币', '张翼飞; 杨骄', '新华每日电讯', '新华每日电讯', '纪念币;支那事变;日本侵华;', '新华社长沙7月4日电（张翼飞 杨骄）长沙最近发现一枚记录“七七 事变”时日本妄想鲸吞我大好河山历史 事实的纪念币。  这枚纪念铸币为红铜质地，外镀白 银，无币值，重88．5克，直径55毫米', '2000-07-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRBm20okoxu_R43BDrducXX7nJIrE5Do66v5o3cHoaGcQS2tXhU2qCMn3sVm4jfkHJkuIR6qaxUVZLGIkOCf8XdjKSjHh24ihtCZzCXrBC4oZ6mZ_t9e1hPc8Bfcl8TXe5ZmrZ6b3fxEA==&uniplatform=NZKPT&language=CHS', '抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5172, '报纸', '内蒙古：把东北抗联革命文物保护好、管理好、运用好', '王慧', '中国文化报', '中国文化报', '东北抗联;文物保护;东北抗日联军;内蒙古;', '在内蒙古自治区呼伦贝尔辽阔的土地上，曾发生过东北抗日联军可歌可泣的战斗故事，伟大的抗联精神永久回响。 1939年12月至1942年2月，东北抗日联军三进呼伦贝尔，不仅扩大了抗联活动区域，而且为推动内蒙古东部地区的抗日斗争作出了重要贡献。 内蒙古自治区文化和旅游厅党组', '2023-12-23 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2023.002961', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5173, '报纸', '“教润”兴工报华夏 “技泽”湖湘写荣光', '苏晓洲; 谢樱; 王宜玄', '新华每日电讯', '新华每日电讯', '陈润霖;教育救国;新化县;工业学校;湖南省教育厅;湖南大学;', '东方的曙光，空谷的足音。 全面抗战期间，一条用血肉筑成的“后勤长城”——滇缅公路，成为决定中国生死存亡的“生命线”之一。10年前，有研究滇缅公路历史的学者发现，很多奋不顾身投身建设的工程师都毕业于湖南省同一所学校——“楚怡工业学校”。 革命，捐躯流血，是苦', '2023-12-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTiHg6SxlKr6Eqo1ibjO-X6RLPzQDk-Gk_1OCvGfihRQfDCSAl-SLX-aA1fEQGtOPTNPSrZ9eT3CHof8g0SjtQbVFGQnvjqe4_6vCWbMB_AB-VI_bCVQenme6fN34WPEMJGsZh6_J6Q5g==&uniplatform=NZKPT&language=CHS', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5174, '报纸', '英雄名字融入城市记忆', '吕百新; 常智科; 乔振友', '中国国防报', '中国国防报', '赵一曼;英雄精神;英雄城;尚志市;城市记忆;', '提起黑龙江省哈尔滨市，很多人会脱口而出：“冰城！”其实，与浪漫的冰雪白色相比，这座城市的红色底蕴更鼓荡人心。“红色之路枢纽城”“东北抗联英雄城”“全国解放第一城”“支前参战基地城”“国防军工制造城”“人民防空示范城”“全国双拥模范城”……红色“七城”，让', '2023-11-17 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2023.001314', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5175, '报纸', '青年师生用分子考古技术让烈士“回家”', '李斯嘉; 张菲垭; 王烨捷', '中青报;中青网;', '中国青年报', '课题组;DNA;方山县;考古技术;', '山西省吕梁市方山县方山南村的北川河谷中，长眠着49位在抗日战争或解放战争中牺牲的无名烈士。今年3月，在复旦大学科技考古研究院副教授文少卿的带领下，一支由5位青年教师及11名学生组成的考古队抵达方山南村，对长眠此地的革命烈士进行系统发掘和分子考古鉴定。近日，这支', '2023-10-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtRPT5YN_WyI45kmOL475wr1hqaahD1FL5yPqALF5CJtlSGaWLpTB2cTxdp9Wzk6eMxJjg-6286Tn3_ZcbJ6ju9C48W6k3HimIBybXACx5yTMkYiSY_GjeibsqDVWZPanu4pvWNFfFmdVA==&uniplatform=NZKPT&language=CHS', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5176, '报纸', '通俗歌剧《红雪花》：情里有根 血里有魂', '张建友', '中国文化报', '中国文化报', '黑龙江省;富锦市;《红雪花》;抗日英雄;', '观演之后，黑龙江省佳木斯市富锦市富锦镇居民李红还常常回想起通俗歌剧《红雪花》中的情节。李红说：“《红雪花》反映的是中国共产党人为了追求革命真理、取得民族独立解放，展现出坚如磐石的理想信念、不怕牺牲的斗争精神和崇高的革命品质，值得我们深入学习和深刻反思。”', '2023-08-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtSayaIGPzpkdfbvzTFPZwHOiZvhv7_Nn-62EsVRn9qubVN-Netsny1Wk9Wisyw0105w7tLjeqvezvpgsuF4LHP2yELqr9UdCPthKsO0HAiULcByIt_4n6LdNIh6QnpWPhHel2MhbnOzFw==&uniplatform=NZKPT&language=CHS', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5177, '报纸', '一个英模连队的“朋友圈”', '张磊峰; 马振; 张石水', '解放军报', '解放军报', '董存瑞;邱少云;朋友圈;', '跳出九连看九连，置身更大的坐标系对比认知 九连一直是第76集团军某旅的荣誉连队和窗口单位。 论历史，九连人抬头挺胸，分外骄傲：建连以来，连队先后参加抗日战争、解放战争、抗美援朝等战役战斗百余次，2次荣立集体一等功、6次荣立集体大功，被授予“抗日模范连”“攻坚', '2023-05-29 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2023.002188', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5178, '报纸', '黄炎培与毛泽东“窑洞对”前后', '薛永毅', '学习时报', '学习时报', '窑洞对;黄炎培;毛泽东;《延安归来》;', '1945年7月1日至5日，国民参政会参政员褚辅成、黄炎培等6人赴延安访问。返回重庆后，黄炎培将在延安的所见所感形成书稿《延安归来》。这本薄薄的小册子，记载了毛泽东与黄炎培关于历史周期率的谈话，“窑洞对”成为党史国史上的著名典故。 六参政员访问延安 抗日战争胜利前', '2023-02-03 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2023.000119', '抗日战争6_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (5179, '报纸', '用亲身经历讲述革命故事', '刘苏闽; 曹玲娟', '上海市新四军历史研究会;', '人民日报', '革命故事;亲身经历;习近平总书记;', '我的爷爷、奶奶上世纪20年代参加革命。父亲14岁参加红军，参与了南方红军三年游击战争、抗日战争和解放战争，经历多次绝处逢生，几块弹片永远留在了他身上。母亲是新四军战士，战争年代3次负伤，荣立二等功2次、三等功3次。父亲临终时留下遗言，要把骨灰撒在武夷山，和当年牺', '2022-12-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.013017', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5180, '报纸', '绘就强国强军同心圆', '柴华', '解放军报', '解放军报', '军队现代化;事务部;退役军人;同心圆;', '秋日北京，天高云淡。中国人民革命军事博物馆，参观“领航强军向复兴——新时代国防和军队建设成就展”的人们，络绎不绝。 观众留言处，人们纷纷写下观展感受。一位观众深情写道：“我为这10年的非凡成就感到自豪，也为有这样一支人民军队守护我们而感到心安。”另一位观众', '2022-10-14 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.005446', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5181, '报纸', '《钢铁战士》：“保卫我们人民的胜利”', '胡谱忠', '学习时报', '学习时报', '《钢铁战士》;电影人;革命战争题材;东北电影制片厂;历史题材;钢骨铁筋;', '“不要忘记，我们的胜利，是多少烈士们的血换来的。他们为了国家独立，人民的幸福，付出了宝贵的生命。还有多少同志，受了多少严重的磨难，才使我们获得了幸福的日子。我们要好好地保卫它，保卫我们人民的胜利，不允许任何人来破坏它。”这是1950年电影《钢铁战士》中的一段', '2022-10-14 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2022.001998', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5182, '报纸', '盐池：红色警队助力老区发展', '苏婕; 伍甜甜', '人民公安报', '人民公安报', '盐池滩羊;公安局;盐池县;老区发展;', '盛夏的一场骤雨过后，位于宁夏回族自治区盐池县的李塬畔革命旧址格外醒目。这里曾是革命战争年代盐池县委、县政府机关所在地，见证了战争时期许多重大历史事件。 “盐池是宁夏唯一经历过红军长征、抗日战争、解放战争的革命老区，是中国人民选择中国共产党的历史见证。”参', '2022-07-07 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2022.003491', '抗日战争6_screened,红井_screened');
INSERT INTO `ds_article` VALUES (5183, '报纸', '《从延安出发》：在艺术回望中吹响前进号角', '牛梦笛', '光明日报', '光明日报', '文艺创作;《从延安出发》;文艺精品;青年一代;', '“风在吼，马在叫，黄河在咆哮，黄河在咆哮……”跨越八十余载光阴，曾经激励着中华儿女前赴后继奋起抗争、保卫祖国的《黄河大合唱》，如今依然激昂雄壮。在近期播出的《从延安出发》的舞台上，观众得以了解当年冼星海抱病创作的艰辛历程，重温这波澜壮阔、震撼人心的音乐史', '2022-06-17 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.002845', '抗日战争6_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (5184, '报纸', '儿童剧《遇见星海》：重温群星闪耀的那片“星海”', '刘淼', '中国文化报', '中国文化报', '儿童剧;《黄河大合唱》;冼星海;《遇见星海》;群星闪耀;', '鉴往知来，中华民族曾经的苦难与抗争史尤其不应被忘记。音乐是闪烁在中华民族至暗时刻的那束光，慰藉、激励着人心。如果说抗日歌曲吹响了人民心中抗日的号角，那么唤起民族认同感、激发民族自信心的《黄河大合唱》则奏响了时代的最强音。 在纪念毛泽东同志《在延安文艺座谈', '2022-06-14 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.001720', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5185, '报纸', '父亲用军乐表达赤子之心', '林子涵', '人民日报海外版', '人民日报海外版', '军乐队;华北军区;赤子之心;', '从一位归国华侨青年，成长为新中国军乐事业里程碑式人物，罗浪走过抗战的烽火，见证解放的号角，指挥开国大典激昂的国歌，为新中国军乐的建设和发展夯基培土。近日，罗浪之女罗静接受本报记者采访时回忆，父亲一路走来，不变的是他为民族创作的初心。以下是罗静的讲述。', '2021-12-10 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.003738', '抗日战争6_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5186, '报纸', '新四军军部在武汉成立始末', '陶爱民', '武汉市民政局;', '人民政协报', '国民革命军陆军新编第四军;游击队;新四军军部;', '在第二次国共合作谈判中，中共中央代表向国民党提出统一整编南方各地区的红军和游击队，开赴华中敌后抗战的要求。经过艰苦谈判，国共两党谈判达成协议，赣、湘、闽、粤、浙、鄂、豫、皖八省的红军和游击队整编为国民革命军陆军新编第四军（新四军），由叶挺任军长。随着1937', '2021-12-09 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.009309', '抗日战争6_screened,项英');
INSERT INTO `ds_article` VALUES (5187, '报纸', '杨春增：抗美援朝的“特等功臣”', '张嘉升', '中央党校中共党史教研部;', '团结报', '朝鲜民主主义人民共和国;抗美援朝;中国人民志愿军;战斗英雄;', '“撼天震地敌丧胆，英雄血战京畿山。千古流芳中朝史，热血浩气壮河山!”这首读起来让人慷慨激昂的诗歌，赞颂的是一位把生命留在抗美援朝战场上的中国人民志愿军一级战斗英雄——杨春增。 1952年8月，杨春增在朝鲜金城前线作战中坚守重要的541高地，与敌人拼至弹尽粮绝，最', '2021-12-09 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.002306', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5188, '报纸', '永远植根人民', '刘阳', '人民日报', '人民日报', '共产党员;优良传统;', '前不久读到一则报道，亲历淮海战役的魏玉华老人回忆起当年热火朝天的支前场面，她组织了2000多名村民碾米磨面、赶做军鞋，用小推车装上麻袋，冒着枪林弹雨，一趟一趟往前线送。为什么老百姓冒死也要支前？在魏玉华看来，“百姓跟共产党亲，是因为共产党时时处处为百姓做榜样', '2021-11-16 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.013883', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5189, '报纸', '弘扬老区精神 创造新时代“第一等工作”', '赖永峰; 刘兴', '经济日报', '经济日报', '习近平总书记;井冈山;红色旅游;', '从井冈山两年零四个月的武装割据，到中华苏维埃共和国的艰辛探索实践；从东北抗日联军在白山黑水间与日军长达14年的英勇斗争，到党中央在陕甘宁边区的13年坚守；从800万太行子女燃起的抗日烽火，到大别山老区飘扬28年的红旗……每一个革命老区，都满载着党同人民风雨同舟、血', '2021-11-11 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.007899', '抗日战争6_screened,红井_screened,叶坪_screened,方志敏_screened,瑞金_screened,苏维埃共和国_screened,神山村_screened');
INSERT INTO `ds_article` VALUES (5190, '报纸', '向大医马海德学习', '申鹏章', '中国麻风防治协会;马海德基金会党支部;', '中国新闻出版广电报', '马海德;发布会;中国共产党成立;国际主义;陈敦德;人民卫生出版社;精神财富;麻风病人;卫生事业;', '2021年9月26日是中国共产党优秀党员、新中国卫生事业的先驱、杰出的国际主义战士马海德111周年诞辰，由陈敦德编著的记述这位伟大的革命者光辉一生的纪实文学专著（人民卫生出版社）正式出版，我有幸在这一天参加新书发布会，并作为马海德曾经的学生发言，至今想来仍激动不已', '2021-11-08 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004421', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5191, '报纸', '英雄山上红旗飘', '胡璞; 孙明江; 石良玉', '解放军报', '解放军报', '大别山精神;根据地;红色基因;红四方面军;红二十五军;王树声;安徽金寨;', '大别山，南接长江，北抵淮河，横亘鄂豫皖三省交界。有人说，这是一座革命的山，一座英雄的山，一座精神的山。这是一片红色沃土，在中国革命的历史上书写了不朽篇章。 李大钊、陈独秀、董必武、陈潭秋等在这里亲自指导建党活动；徐向前、刘伯承、邓小平、李先念等在这里留', '2021-11-03 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006923', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5192, '报纸', '大别山精神激励我们奋勇前行', '青平', '中国青年报', '中国青年报', '大别山;精神激励;鄂豫皖革命根据地;革命老区;鄂豫皖苏区;刘邓大军;习近平总书记;胸怀全局;中央红军;', '大别山位于安徽、湖北、河南三省的交界地带，从1921年中国共产党诞生到1949年新中国成立，党领导大别山区军民创造了“28年红旗不倒”的革命奇迹。气势雄伟的大别山区，见证了中国革命从星星之火到燎原之势，太多令人心潮澎湃的往事，都在这里发生。 早在五四运动时期，董', '2021-11-02 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.003912', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5193, '报纸', '自力更生 艰苦创业', '谢希瑶; 邹多为; 蔡馨逸', '新华社;', '新华每日电讯', '南泥湾精神;陕甘宁边区;三五九旅;大生产运动;艰苦创业;', '“花篮的花儿香，听我来唱一唱，唱一呀唱，来到了南泥湾，南泥湾好地方，好地呀方……” 南泥湾，一个响亮的名字，一片红色的沃土。 80年前，以八路军三五九旅为代表的抗日军民，在困境中奋起、在艰苦中发展，树立了抗日战争时期陕甘宁边区开展大生产运动的旗帜，创造', '2021-11-01 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008390', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5194, '报纸', '红色热土青山常在', '李己平', '经济日报', '经济日报', '杨靖宇;抗联精神;', '靖宇县位于吉林省白山市、长白山西麓，这里是抗日英雄杨靖宇将军的殉国地。抗日战争时期，在艰苦恶劣的条件下，杨靖宇将军领导抗日武装同数倍于己的敌人浴血奋战，牺牲时胃里全是枯草、树皮、棉絮，没有一粒粮食。吉林省委宣传部副部长张志伟认为，以杨靖宇为代表的抗联战士', '2021-10-30 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.007606', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5195, '报纸', '回眸“陕北的好江南”', '刘笑伟', '解放军报', '解放军报', '南泥湾精神;大生产运动;共产党人;毛泽东;三五九旅;延安城;陕甘宁边区;人民军队;', '80年前，南泥湾是什么样子？处处荒山，没有人烟。陕西人民美术出版社出过一本《延安精神颂》，生动记录了1941年春天，王震带领第三五九旅官兵，在这里征服荒山野岭的最初时刻：“一连驻地在西沟，连长带领战士来到了这里，呼的一声，从芦苇蹿出一只大灰狼，直扑过来，二排长', '2021-10-29 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006829', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5196, '报纸', '做新时代垦荒人 让南泥湾精神代代相传', '青平', '中国青年报', '中国青年报', '南泥湾精神;陕甘宁边区;大生产运动;', '1938年10月，抗日战争进入战略相持阶段，八路军除了面对日军实行的“三光”“蚕食”“清乡”等政策，还要应对蒋介石国民党军队对抗日根据地进行的严密军事包围和经济封锁。打破国民党“不准一斤棉花、一粒粮食、一尺布”进入边区、“饿死八路军，困死八路军”的阴谋企图，关', '2021-10-28 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.003861', '抗日战争6_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (5197, '报纸', '天目山战役：以少胜多的运动战范例', '杨益', '学习时报', '学习时报', '天目山战役;第三阶段;新四军苏浙军区;运动战;', '1945年2月至6月，粟裕领导的新四军苏浙军区在浙江天目山脉打了三次运动战，精心谋划、屡出奇兵，消灭国民党顽军1.2万多人，打了一场十分漂亮的歼灭战。天目山战役使得新四军提早实现了从游击战到运动战的战略转变，锻炼了部队、积累了经验，为解放战争实施大规模的兵团作战作', '2021-10-25 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001999', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5198, '报纸', '创意讲述党史上的惊险“瞬间”，传播效果“破圈”', '张博令', '新华每日电讯', '新华每日电讯', '中共一大;传播效果;', '你应该在影视剧中看到过这样一幕：拆弹专家面临“红蓝抉择”，选错一根线，可能就来到了生命的终点。 观众每每看到此处，都会为其中的人物捏一把汗。 也许你不知道，中国共产党“创业”之初也经历过无数次关键的“红蓝抉择”，要是有一个瞬间没走对方向，也许就不会有', '2021-10-12 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007825', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5199, '报纸', '为实现民族复兴接续奋斗', '王琦; 孙少龙; 王子铭; 任沁沁; 廖君', '新华社;', '人民日报', '民族复兴;中华民族;社会主义;辛亥革命;孙中山;中华儿女;', '历史，往往在经过时间沉淀后可以看得更加清晰。 “亟拯斯民于水火，切扶大厦之将倾”。110年前爆发的辛亥革命，以其惊心动魄的时代伟力，打开了中国进步闸门，为中华民族发展进步探索了道路，成为民族复兴伟大征程上一座巍然屹立的里程碑。 一百余年岁月山河，沧桑巨变', '2021-10-09 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.010566', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5200, '报纸', '纵横决荡斗敌顽', '杨佳斯', '学习时报', '学习时报', '新四军第二师;战斗小组;陈庆先;淮南抗日根据地;梅花桩;纵横决荡;主力部队;烈士纪念碑;', '新四军第二师烈士纪念碑，巍然耸立在安徽省定远县藕塘镇境内。纪念碑始建于1944年7月，1946年6月国民党撕毁停战协定，悍然进攻解放区，野蛮炸毁了该烈士纪念碑。1964年当地政府重修纪念碑，碑文如下： 路西襟江带淮，左津浦而右淮南，素为兵家必争之地。自卢沟桥事变以来，', '2021-10-08 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001870', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5201, '报纸', '咱们工人有力量', '刘梦丹', '人民日报', '人民日报', '马海星;佳木斯;', '咱们工人有力量 嘿 咱们工人有力量 每天每日工作忙 嘿 每天每日工作忙…… 这首诞生于1947年的歌曲《咱们工人有力量》，生动地塑造了抗日战争胜利后中国工人阶级顶天立地的英雄形象，传唱至今，仍让人斗志昂扬、热血沸腾。歌词朗朗上口，曲调铿锵有力，歌曲加入', '2021-10-02 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.010319', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5202, '报纸', '铭记英烈 奋勇前行', '任欢', '光明日报', '光明日报', '志愿军;中华儿女;英雄辈出;民族独立;习近平总书记;中华民族;', '2021年9月30日，第八个烈士纪念日。近代以后，特别是中国共产党成立以来，为赢得民族独立和人民解放、实现国家富强和人民幸福，无数革命先烈矢志不渝、前赴后继，无数平凡英雄艰苦奋斗、无私奉献，谱写了气吞山河的英雄壮歌。 英雄者，国之干。我们不会忘记，今天的幸福生', '2021-09-30 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005050', '抗日战争6_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5203, '报纸', '勤奋工作 踏实劳动', '周圆', '新华社;', '新华每日电讯', '劳动创造;劳动者;习近平总书记;太钢集团;', '民生在勤，勤则不匮。 历史长河中，中华民族勤于劳动、勇于奋斗，创造出灿烂的文明，历经沧桑而生生不息。回望百年，在中国共产党坚强领导下，广大劳动者辛勤劳作、艰苦奋斗，谱写出“换了人间”的壮丽史诗。 习近平总书记在2020年全国劳动模范和先进工作者表彰大会上', '2021-09-23 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007419', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5204, '报纸', '西北政法大学：继承红色文化传统 打造特色育人模式', '张哲浩; 杨永林; 戴鲲; 张佼', '光明日报', '光明日报', '西北政法大学;陕北公学;西北人民;红色文化;育人模式;红色基因;', '步入位于古城西安南隅的西北政法大学新、老校区，“陕公大礼堂”“陕公路”“老延大路”“红色基因石碑”……这些古风扑面的楼宇、道路和墙面，默默地诉说着这里曾有的因缘和血脉；睹之，仿若置身于一个历史的红色时空，让人触景生情，油生敬意。 “西北政法大学是一所具', '2021-08-22 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.004302', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5205, '报纸', '小石磨里的抗联故事', '周长庆', '新华每日电讯', '新华每日电讯', '东北抗联;', '在吉林省长春市宽城区富丰教师新村一个普通民宅里，长春72中退休教师纪福来珍藏着一盘小石磨。在抗战胜利76周年纪念日前夕，这位69岁的抗联后人向记者讲述了石磨的来历。 纪福来的父亲纪荣年轻时，家在伪满洲国统治下的吉林省敦化县前河村。他为人正派，憨厚老实，善交朋', '2021-08-20 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.006486', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5206, '报纸', '太行山上谱新歌', '冷秋; 常琳; 张伟', '金融时报', '金融时报', '太行山;冀南银行;全域旅游;农商银行;井店镇;红色旅游;一二九师;', '盛夏时节，骄阳似火，千里太行万物葱茏，清漳河畔流水潺潺，红色圣地游人如织。在建党100周年的特殊时刻，记者深入太行山腹地河北涉县，这里是一二九师司令部旧址和晋冀鲁豫边区政府旧址、冀南银行旧址所在地。 一二九师司令部旧址是刘伯承、邓小平和战友们在涉县工作、生', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.003971', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5207, '报纸', '理想信念的伟大远征 一代代人的血脉传承', '张千千', '新华每日电讯', '新华每日电讯', '长征精神;长征路上;红军长征;理想信念;', '血战湘江、强渡乌江、飞夺泸定桥、爬雪山、过草地……中国共产党历史展览馆里，“4D+六面”沉浸影院，将观众带入当年红军长征的真实场景。 “每一代人有每一代人的长征路，每一代人都要走好自己的长征路。”影片最后打出的字幕，动人心魄、感人奋起。 80多年前，中国工', '2021-07-31 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005850', '抗日战争6_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (5208, '报纸', '毛泽东革命战争年代的新闻作品', '王凯捷', '团结报', '团结报', '革命战争年代;新华社;毛泽东;新闻作品;', '在毛泽东长期的革命生涯中，十分重视新闻的战斗和舆论作用，曾为新华社撰写和修改了大量的新闻稿件。这些文稿，从一个侧面反映了中国革命艰苦和辉煌的历程，具有重要的文献价值和历史意义。同时，毛泽东亲笔撰写的新闻文稿，与他的文章和诗词一样，不仅具有战略思维的大手笔', '2021-07-29 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001535', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5209, '报纸', '党史照亮奋进路', '肖亮升', '人民政协报', '人民政协报', '自治区政协;党史学习;广西壮族自治区;', '“中华民族凭什么复兴？” 近日，广西壮族自治区政协第54期“同心”讲座现场座无虚席，党史学习教育中央宣讲团成员、国防大学战略研究所原所长金一南以《百年沧桑：从东亚病夫到民族复兴》为题作的专题报告赢得掌声阵阵。 为推动党史学习教育扎实开展，广西壮族自治区', '2021-07-20 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005847', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5210, '报纸', '中共在陕甘宁边区的财经突围', '安仁', '金融时报', '金融时报', '陕甘宁边区;《金融时报》;边区银行;财经工作;抗日根据地;', '轰轰烈烈的大生产运动，使土地贫瘠、地广人稀的陕甘宁边区创造了历史奇迹，也在战火纷飞、内外交困的艰苦环境下创造了财经突围的经济奇迹。在这场惊心动魄的突围中，中国共产党领导下的红色金融家们凭借其智慧和魄力，保持了边区货币和金融的稳定，为边区恢弘的财经突围画卷', '2021-07-16 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.003587', '抗日战争6_screened,抗日战争1_screened,抗日战争1_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (5211, '报纸', '南梁精神孕育形成的历史揭示了什么？', '王志民', '中央党史和文献研究院;', '学习时报', '南梁精神;陕甘边革命根据地;谢子长;刘志丹;孕育形成;', '87年前，刘志丹、谢子长、习仲勋等老一辈无产阶级革命家，团结带领陕甘边区军民艰苦奋斗、浴血奋战，开辟了以南梁为中心的陕甘边革命根据地，成立了陕甘边区苏维埃政府。不断发展壮大的陕甘边革命根据地，与陕北革命根据地连成一片，形成陕甘革命根据地，成为土地革命战争后', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001256', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5212, '报纸', '“十户联创”一股绳 放心消费暖民心', '闫冬; 刘佳', '中国质量报', '中国质量报', '市场监管部门;', '延安是中国革命的红色圣地，在这片土地上，抗日战争、解放战争以及中共七大等一系列影响和改变中国历史进程的重大事件在这里上演，由此也诞生和传承了“延安精神”。经过多年的发展，延安变化巨大，从风沙漫天到山川披绿，焕然一新的面貌让人大为惊叹。 日前，记者来到了', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.28164/n.cnki.nczlb.2021.002029', '抗日战争6_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5213, '报纸', '平心做事 朴素做人 为民服务', '任会君', '河北省商务厅;', '国际商报', '为民服务;平山县;人民功臣;王震将军;', '在建党100周年的日子里，我们省商务厅综合处、法规处、外经处和厅进驻省政务服务大厅工作组全体党员，一起来到华北军区烈士陵园，联合举办党日活动。 活动后，我想到了从我家乡平山县走出去的革命队伍平山团的英雄事迹，也想到了平山团如今依然健在的老英雄，“共和国勋章', '2021-07-05 08:00:00', 'https://link.cnki.net/doi/10.28270/n.cnki.ngjsb.2021.003153', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5214, '报纸', '改天换地 敢从何处来', '李云舒', '中国纪检监察报', '中国纪检监察报', '中国共产党人;专题片;马克思主义;党的十一届三中全会;毛泽东;亢慕义斋;马克思列宁主义;半殖民地半封建社会;淮海战役;', '24集大型文献专题片《敢教日月换新天》近期热播，引发新一轮追剧“旋风”。 欲知大道，必先为史。《敢教日月换新天》围绕我们党百年奋斗历程，全景展现了中国共产党以“敢教日月换新天”的志气、脚踏实地的苦干精神、始终不忘为人民谋幸福的初心，团结带领中国人民迎来了', '2021-07-04 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003181', '抗日战争6_screened,井冈山革命博物馆_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (5215, '报纸', '闽西苏区：红色法治的成功探索', '乔文心', '人民法院报', '人民法院报', '闽西苏区;裁判部;苏维埃政府;临时最高法庭;郭滴人;司法审判;中央苏区;', '点睛 闽西，福建省西部地区的简称，亦指清末行政区划的汀州府属和龙岩州属的区域，北接赣南，南邻粤东。包括龙岩、漳平、宁洋、永定、上杭、长汀、连城、武平、归化(今明溪)、宁化、清流、平和等12个县。闽西是全国最早建立红色政权的地区之一，是中央苏区的重要组成部分', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003031', '抗日战争6_screened,闽西革命根据地_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (5216, '报纸', '中央苏区：人民司法巩固红色政权', '姜佩杉', '人民法院报', '人民法院报', '中央苏区;司法审判;公开审判;中华苏维埃共和国宪法大纲;临时最高法庭;裁判部;何叔衡;司法机关;梁柏台;苏维埃政府;人民司法;红色政权;', '点睛 九十年前，中华苏维埃共和国临时中央政府定都瑞金。 在那个烽火连天、艰苦卓绝的岁月，中国共产党带领人民绘就了波澜壮阔的历史画卷。在这幅画卷中，中华苏维埃共和国的法治建设无疑是浓墨重彩的——在立法方面，颁布了宪法大纲、刑事、经济、土地、劳动、婚姻、', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003037', '抗日战争6_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (5217, '报纸', '四川：红四方面军在根据地的法治探索', '沈圆圆', '人民法院报', '人民法院报', '革命法庭;苏维埃革命;恩阳县;红四方面军;审判委员会;根据地;', '点睛 1932年冬，在第四次反围剿作战中，红四方面军主力退出鄂豫皖根据地，翻越巴山天险，解放通江、南江、巴州、平昌等地，1933年2月，川陕省苏维埃政府成立，以“通南巴平”为中心的川陕革命根据地正式诞生。红军在根据地开始了认真而艰难的法治探索。 在立法方面，制', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003039', '抗日战争6_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (5218, '报纸', '伟大觉醒', '郭兴', '中国纪检监察报', '中国纪检监察报', '动车组列车;中国人;中华民族;中国共产党领导;中国高铁;王进喜;', '精神是一个民族赖以长久生存的灵魂，唯有精神上达到一定的高度，这个民族才能在历史的洪流中屹立不倒、奋勇前进。 近代以来，在国家危急的关头、民族自信的谷底，中国共产党登上中国政治舞台，在持续的伟大斗争实践中支撑起全民族救亡图存、谋求复兴的希望。 在中国共', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003144', '抗日战争6_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5219, '报纸', '每位老干部都是生动教材', '安普忠; 岳雨彤; 周仁', '中国国防报', '中国国防报', '国防动员;生动教材;党史学习;', '“12岁时鬼子打到家乡，逃难的娃娃遇上八路军……我这辈子最自豪的就是一生坚定跟党走。”渡江战役胜利暨4·23南京解放纪念日前夕，江苏省军区组织的“百名战将忆党史”大型全媒体新闻行动启动仪式上，年过九旬的原第28军副政委李剑锋深情讲述了自己从农家娃参军入伍，矢志听', '2021-06-28 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2021.001438', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5220, '报纸', '统一，全国人民的共同夙愿', '司晋丽', '人民政协报', '人民政协报', '《国民革命歌》;北伐战争;领导权;国民革命军;帝国主义;', '20世纪初，帝国主义列强入侵，军阀割据混战，民众贫苦离乱……中华大地一派苍茫悲歌。 苟利国家生死以，岂因祸福避趋之。以振兴家国为己任，无数仁人志士踏上了寻求救国“药方”的道路。他们勇敢地走上街头宣传反帝反封建的思想，把黑暗冰冻的旧中国撞裂开一角，让光明的', '2021-06-24 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005144', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5221, '报纸', '是什么拨动了青年官兵的心弦', '杜善国', '中国青年报', '中国青年报', '青年官兵;当代革命军人核心价值观;', '60多年前，在中国人民解放军南下征途上，两个被革命豪情点燃的年轻人——陆原和岳仑，在小马灯下，挥笔写下朴实无华的歌曲《我是一个兵》。这首曾被西方舆论界称为“朝鲜战场上一枚重磅炸弹”的歌曲，从硝烟弥漫的岁月一直唱到鸽哨飞旋的年代，成为代表兵之旋律的传世之作。', '2011-03-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=HboJJBuTKtTFU4QX9exxRO5-AXiO_Gv6x-IMNhyswqXm8i1vuc_36s-xIlqI4srvzswp41N7mMNktiIasuzEbSOcMRECnFJiNcMIIdD0CFYrHrI7jcYGQlL97PR4VFlRJZjuw-K_OVOaJTB8TRUWpQ==&uniplatform=NZKPT&language=CHS', '抗日战争6_screened');
INSERT INTO `ds_article` VALUES (5229, '报纸', '当红岩响起《国际歌》', '程雪; 李一叶', '解放军报', '解放军报', '《国际歌》;', '热泪，悲愤地流。沉默的群众，伫立街道两旁，垂泪目送。囚车上，共产党员们放声高歌…… 这一幕，定格于光影中，至今保存在重庆王朴烈士陵园展厅里。记者凝神望向这张老照片—— 1949年10月，因叛徒出卖，地下党员王朴、陈然等被捕一年后牺牲。奔赴刑场的路上，囚车上', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004950', '陈然_screened');
INSERT INTO `ds_article` VALUES (5242, '报纸', '春光和煦，一等好事仍是读书', '韩寒; 李晓; 张胜; 王美莹; 陈之殷; 刘彬; 王斯敏', '光明日报', '光明日报', '亲子阅读;少儿出版;讲述人;实验物理;短视频;图画书;', '编者按 草长莺飞，又一年“世界读书日”已然临近。 去年4月23日，习近平总书记在致首届全民阅读大会的重要贺信中指出，阅读是人类获取知识、启智增慧、培养道德的重要途径，可以让人得到思想启发，树立崇高理想，涵养浩然之气。贺信中，总书记还对广大党员、干部，对孩子们', '2023-04-21 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.001849', '罗广斌_screened');
INSERT INTO `ds_article` VALUES (5243, '报纸', '它们在时光的田野中摇曳生辉', '彭程', '光明日报', '光明日报', '文学作品;《暴风骤雨》;红色经典作品;《创业史》;', '有这样一个长长的文学作品名单，已经作为一种公共记忆，镌刻在时光深处：《可爱的中国》《青春之歌》《暴风骤雨》《红旗谱》《红岩》《创业史》……它们被一代代读者阅读和喜爱，化为优质的精神食粮，滋养着他们的灵魂，促进了他们的成长。 这些通常被称为红色经典的作品，', '2022-08-20 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.003909', '罗广斌_screened');
INSERT INTO `ds_article` VALUES (5249, '报纸', '《红岩》：信仰的力量', '晏震宇', '江苏省高邮市纪委监委;', '中国纪检监察报', '共产主义;革命者;《红岩》;共产党人;', '“竹签子是竹子做的，但共产党员的意志是钢铁铸成的。”酷刑之下，身体单薄的女子可以成为铁骨铮铮、宁死不屈的硬汉；“从来壮烈不贪生，许党为民万事轻”“愿以我血献后土，换得神州永太平”，铁窗之下，遍体鳞伤的革命者还能拿起纸笔做刀枪……再读《红岩》，又是一次心灵', '2018-06-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDwjPfWXyH-sHbcFwMGnkuFTYLi8oaRWTR0TD92dnJYMJ28qRKiay1ZuOZCXPS3eGYKxBT_6CQoA0lmoEiZm8G1WD7FptJcjad0J7mD949TjhPE_MkU6EwlZ-2uDsJk8ciGbBN0TboE-A==&uniplatform=NZKPT&language=CHS', '罗广斌_screened');
INSERT INTO `ds_article` VALUES (5252, '报纸', '民族与时代的歌者', '沈俊峰 ; 李国文 ; 肖海洪', '中国纪检监察报', '中国纪检监察报', '《党的女儿》;长城长;时代性;中央电视台;男子汉;王祖皆;网络歌曲;歌剧《江姐》;空政文工团;作曲家;陈晓光;音乐界;', '“最难忘，最难忘，妈妈脸上又见皱纹添……”一位老人，半头银发，有点罗锅，却念得字字有力，句句深情。这是老人80岁生日会上的一幕。这位老人叫阎肃，空军政治部文工团创作员。  那天，军委首长送来花篮，称赞他是“德艺双馨的老艺术家”，文艺界朋友送来贺卡，祝', '2010-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBPZBZ7VLPfkEwfXZkwu9rWAdR73XGVhG0gRh48DN6lFQJ5z32-ZKJVkTrhsh92ouTZrkmyApMDcNp-lrWuWNUqcqye9nxoFToUfmNpXRmPRICEqUQIybEg3ylZ6XVmoziyr-hOmG8-7w==&uniplatform=NZKPT&language=CHS', '罗广斌_screened');
INSERT INTO `ds_article` VALUES (5256, '报纸', '铸魂育人 攻坚克难', '张菲倚; 高召锋; 杨君子', '中国组织人事报', '中国组织人事报', '习近平总书记;领导班子;主题教育;西南大学;研究生教育;攻坚克难;', '“红岩上红梅开，千里冰霜脚下踩……”走进西南大学光大礼堂，数百名师生正沉浸在《红梅赞》的歌声中。连日来，西南大学以“千秋红岩 信仰力量”为主题，充分挖掘红岩精神和学校红色文化的时代价值，通过排演思政大课、参观红岩革命纪念场馆、袁隆平院士主题教育展等，点亮了', '2023-07-04 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2023.001664', '红梅赞_screened');
INSERT INTO `ds_article` VALUES (5257, '报纸', '“大思政课”视域下红岩精神融入高校思政理论课育人路径研究', '傅小珮', '重庆人文科技学院;', '中国文化报', '红岩精神;思政理论课;思政课;路径研究;', '每一个历史事件、每一位革命英雄以及每一件革命文物，都见证着我们党走过的风雨历程和取得的巨大成就，也彰显着我们党的追求、奉献与担当，进而汇聚成我们党的红色血脉，为新时代中国共产党人提供深厚的精神滋养，为国家和民族发展提供强大的前进力量。红岩精神作为革命精神', '2022-11-22 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.004326', '红梅赞_screened');
INSERT INTO `ds_article` VALUES (5259, '报纸', '红色旋律歌颂伟大历程 初心不改阔步新的时代', '李志刚; 魏彪; 黄高原', '中国旅游报', '中国旅游报', '交响音乐会;《红梅赞》;共产党;没有共产党就没有新中国;奋斗目标;历史节点;《红旗颂》;红色记忆;', '7月1日是中国共产党101岁生日。这天晚上，中国共产党历史展览馆红色大厅灯火辉煌，一枚巨大的红色五角星镶嵌在天花板上，放射出的光芒普照大厅；鲜红的舞台布景和飘逸的帷幔，让大厅充满了庆祝氛围；身着靓丽演出服的文艺工作者，步履匆忙，一边走一边整理衣袖；来自各方的观', '2022-07-04 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2022.001755', '红梅赞_screened');
INSERT INTO `ds_article` VALUES (5265, '报纸', '红岩上 红梅开', '陈劲松; 李国文 ; 万天兵', '光明日报', '光明日报', '歌剧《江姐》;文艺作品;空政文工团;民族歌剧;', '一部歌剧，一唱就是50年，她就是红色经典《江姐》。6月下旬，空军政治部文工团将在四川成都演出5至7场，以此向中国共产党成立90周年献礼。 这是一个特殊的艺术现象。歌剧是歌唱艺术皇冠上的明珠，2007年，国家大剧院刚落成，就选定《江姐》为首演歌剧。这一年10月1', '2011-06-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAHB1FsS0WlaR9ZxiYEKQx5V1cuTTZcEuEhy07Qdcwp_RM4OYYkoHlTvtMMscR0F6BJlPF2chWQc5pDhP53TTGfPc549K9caybeKnSwU0VCytydFsmC6xHi6VK_jzSRH6BSDN1C7i0V6A==&uniplatform=NZKPT&language=CHS', '红梅赞_screened');
INSERT INTO `ds_article` VALUES (5269, '报纸', '为时代而舞', '郭凯; 肖海洪; 周宇', '光明日报', '光明日报', '现代舞剧;空政歌舞团;红色艺术;', '上个世纪60年代，空政歌舞团的艺术家们怀着对红岩烈士的景仰，创作出歌剧《江姐》、歌曲《红梅赞》等经典作品；  37年后，他们又将一部气势磅礴、催人泪下的大型现代舞剧《红梅赞》推上舞台，在中华大地掀起竞相观看“红色艺术经典”的阵阵热潮。  浪漫的舞剧', '2003-09-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA3h-A8qlWBpHz76yWJTRZz_et5yWtIMuNjbzAOM0euU4SL2TkiQ6enY0Nk-UezMixajzM9F43Ioz0Fi2ZkjSuDUQPzHZn3SnMUvs11orJQnjVdDvSbFMDFOXZAm10rszQrsDaxCUs4MQ==&uniplatform=NZKPT&language=CHS', '红梅赞_screened');
INSERT INTO `ds_article` VALUES (5270, '报纸', '京剧《江姐》丛中笑', '周向阳', '中国文化报', '中国文化报', '《江姐》;', '本报讯（记 者周向阳）“红岩 上红梅开，千里冰 霜脚下踩……”一 段悲怆激昂的曲 调响起，人们熟悉的江姐依然是 那身熟悉的装扮──红色毛衣 蓝色旗袍，在一丛丛红梅花的 掩映下，她是那样的妩媚动 人。这是6月29日晚在北京长', '2001-07-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAHMmYFi_5aZoa46nJYaNsQBaZGC3T0MWFKM2_ZZK5czcrK3F6sKjyAQQWRPuawS5L-GTNPq4oMIxK0niqQJL1Bj2os3aIDzISIMcDR2iNXBHeEKfetyJqiJDOdmOC48Aw6p26saQl-mA==&uniplatform=NZKPT&language=CHS', '红梅赞_screened');
INSERT INTO `ds_article` VALUES (5279, '报纸', '学好百年党史 践行“两个维护” 谱写重庆高质量发展高品质生活新篇章', '唐良智', '重庆市人民政府;', '学习时报', '两个维护;习近平总书记;高品质生活;', '党的历史是最生动、最有说服力的教科书。习近平总书记在党史学习教育动员大会上强调，“回望过往的奋斗路，眺望前方的奋进路，我们必须把党的历史学习好、总结好，把党的成功经验传承好、发扬好”“做到学史明理、学史增信、学史崇德、学史力行，学党史、悟思想、办实事、开', '2021-05-07 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.000765', '狱中八条_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5284, '报纸', '新安小学学生：争当新时代的“小好汉”', '尹晓宇', '人民日报海外版', '人民日报海外版', '新安小学;周恩来;中学生;红色文化资源;', '“我们是女民兵，我们不怕！”5月30日，在“红色基因代代传”2023第三届青少年红色故事宣讲活动上，江苏省淮安市新安小学四年级学生夏添穿着一条红色裙子，动情地讲述着刘胡兰壮烈牺牲的感人故事。 新安小学创办于1929年。1935年10月，该校14名学生组成“新安旅行团”，以文', '2023-07-06 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2023.002228', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5288, '报纸', '假期释放新活力 红色旅游来“圈粉”', '赵垒', '中国旅游报', '中国旅游报', '红色旅游;红军山;红色景区;红色旅游景区;旅游节;旅游专列;红色文化;讲解员;', '“我志愿加入中国共产党，拥护党的纲领，遵守党的章程……”5月1日，在山东东营广饶县红色刘集旅游景区《共产党宣言》陈列馆内，有着30年党龄的游客李先生正在重温入党誓词。 五一假期，不少游客和李先生一样选择走进红色旅游景区，重温入党誓词，回顾峥嵘岁月，感悟红色精', '2023-05-03 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2023.001142', '渣滓洞_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (5289, '报纸', '探寻红色经典的时代表达', '胡芳', '中国文化报', '中国文化报', '音乐剧专业;教学方向;《江姐》;红色经典;北京电影学院;', '今年，北京电影学院表演专业新增了音乐剧表演方向，由北京电影学院出品的大型原创音乐剧《江姐》已开启创排，成为第一部北影制作的音乐剧。该剧以“红色经典、时代表达”为特色，以时下流行、国际先进的音乐剧编创手法，再度演绎红色文化经典和革命历史题材的大IP，在守正创', '2022-09-15 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.003128', '渣滓洞_screened,红梅赞_screened');
INSERT INTO `ds_article` VALUES (5297, '报纸', '讲述红岩故事 传承红色基因', '蒋云龙; 刘新吾', '人民日报', '人民日报', '红岩精神;红色基因;', '“说起来也奇怪，工作8年多，红岩故事我讲了上万场，但再一次讲起江姐的故事，我还是激动到眼含热泪。”说这话的李婧，是重庆红岩革命历史博物馆的一名讲解员，她的工作是为来自天南地北的游客讲述红岩故事。一次次讲述中，李婧感觉自己也在渐渐走进革命者们的内心。她说，红', '2021-10-21 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011057', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5299, '报纸', '王莉：无论在舞台还是讲台，传承始终如一', '胡芳', '中国文化报', '中国文化报', '《江姐》;《红梅赞》;', '从第一次与江姐“合体”到现在，尽管上百场歌剧《江姐》的演出让王莉对江姐这个角色驾轻就熟，但每一次登台，王莉仍不敢懈怠，“每一场都想把最好的状态呈现给观众，每一场都是新的。”近两个月，王莉一直步履未停，8月29日，她在北京领衔主演了庆祝建党百年版经典民族歌剧《', '2021-10-21 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.003199', '渣滓洞_screened,红梅赞_screened');
INSERT INTO `ds_article` VALUES (5303, '报纸', '敬读感人肺腑的烈士绝笔', '叶子', '人民日报海外版', '人民日报海外版', '方志敏;八路军总部;《可爱的中国》;《挺进报》;农民协会;《红岩》;共产党;国民党特务;最后时刻;', '9月30日，是中国的烈士纪念日。今天上映的电影《长津湖》，将观众带回70多年前那场艰苦卓绝的浴血奋战，那是“气多”战胜了“钢多”的伟大胜利。 提到抗美援朝战争，不禁使人想起“冰雕连”的故事。在朝鲜战场零下40摄氏度的低温之中，伏守在冰雪之中、保持战斗姿势的战士', '2021-09-30 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.003047', '渣滓洞_screened,狱中八条_screened,陈然_screened,百团大战_screened,强渡大渡河_screened');
INSERT INTO `ds_article` VALUES (5304, '报纸', '“那片天空，妈妈也曾仰望过”', '程雪; 李一叶; 郭淑军; 张琳亚', '解放军报', '解放军报', '杨汉秀;渣滓洞监狱;', '一份特殊的礼物 这是一件今天看来都很时尚的旗袍。黑色哑光缎面，别致的小立领，搭配淡粉色绸制内衬。 50多年前，这件黑色旗袍作为一份特殊的礼物，送到了女孩李继业手上。在她还不满1岁时，母亲杨汉秀就已“寄出”这份礼物。 这一“寄”，就是20多年。 28岁那年', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004951', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5309, '报纸', '总有一种情怀，让我们心向往之', '吴玫', '中国妇女报', '中国妇女报', '姑苏春;许云峰;《红岩》;《烈火中永生》;心向往之;《野火春风斗古城》;', '因为歌剧《江姐》，这些天我搜寻着我的青春记忆，或者再次打开小说《红岩》，或者重看电影《野火春风斗古城》，甚至在遍寻不着后到上海图书馆翻出了1978年出版的长篇小说《姑苏春》，无论是老电影还是老小说，它们都没有因为岁月流逝而变得寡淡如水。 与其说是想验证自己', '2021-06-24 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.001999', '渣滓洞_screened,罗广斌_screened');
INSERT INTO `ds_article` VALUES (5310, '报纸', '播撒红色精神的种子', '谭孝曾; 谢颖', '十、十一、十二届全国政协;全国政协京昆室;', '人民政协报', '谭元寿;许云峰;《红岩》;谭富英;红色精神;马长礼;红岩精神;张学津;', '“做一个好党员我理所当然!”这是现代京剧《许云峰》中的一句台词。回望百年岁月，无数英雄先烈用鲜血和生命换来了我们国家现在的繁荣昌盛。对文艺工作者来说，充分挖掘革命历史、积极传播红色经典、大力颂扬红色精神，致敬一代代继往开来的英雄共产党人，并以英雄的精神激励', '2021-03-22 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.002447', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5312, '报纸', '江姐的青春回响', '王鑫昕', '中青报;中青网;', '中国青年报', '四川大学;江竹筠;歌乐山;手术记录;绝育手术;', '为什么29岁的她会抱定个人“向死之心”去为更多大众争取“活的生机”？ 究竟什么样的价值光芒指引她从容又义无反顾？ 为什么她就不能像今天的我们在大学绿荫下对自己放纵一些、享受一些，“好”哪怕那么一点点？ …… 在2020年江姐诞辰100周年之际，四川大学精心', '2021-01-29 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.000361', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5315, '报纸', '读万卷书 行万里路', '阎肃; 郭超', '光明日报', '光明日报', '万卷书;文艺工作者;修道院;雪域高原;', '我是一名老文艺工作者，一直信奉“读万卷书，行万里路”，把它作为我的座右铭，作为自己修身立德、学习创作的力量源泉。  今年5月，我已经85周岁。这么多年来，不知读了多少书，走了多少路，但我深知：一个人的财富不是金钱，而是阅历。“阅”即阅读，“历”即经历。', '2015-08-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDBIqV5fmwCOSxOnpCVFrvGLyobxQvjuEH8VYZztarkq9_Zq7pp79BcKH04zKfFCK2U0HT8fq9mSTjxtOOvGKOe0IR-xrLyQe_n5SUPBmL9ymOPGb0BH9MvPmIx7xLIRzMzrYYefw-wfg==&uniplatform=NZKPT&language=CHS', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5323, '报纸', '让统一战线和多党合作事业薪火相传', '木佳; 白勇', '中华工商时报', '中华工商时报', '胡锦涛;中共中央统战部;无党派人士;领导人;全国工商联;多党合作;民主党派;', '【记者木佳白勇29日重庆报道】　经中共中央批准，28日至29日，中共中央统战部组织各民主党派中央、全国工商联领导人和无党派人士代表赴重庆开展“重温历史，同心同行”主题教育活动。中共中央政治局委员、重庆市委书记薄熙来，全国政协副主席、中共中央统战部部长杜青林出席', '2011-03-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBMpvuifyOIob8ZEDnFIL8qfd3f1ampXkW9znUFjK2FHHEDKqjaLnRAceL4u6xOyTZ1LN2hFtO-Fb6ie0K4wiFVHs7PVBw581Nn868Aep1ChwdlxqgaM773AYodh4PU0_QP8i6X_vM3EQ==&uniplatform=NZKPT&language=CHS', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5325, '报纸', '岁月如歌,他们激情走过', '张力 ; 梁顺霞; 陆彬彬', '解放军报', '解放军报', '空政文工团;全军文艺会演;佟铁鑫;为兵服务;歌剧《江姐》;杨月林;', '这是一段忠诚的历史，他们高歌远航，引领时代。 这是一段战斗的历史，他们艰苦创业，以艺为枪。 这是一段如歌的历史，他们意气风发，百舸争流。 这是一段辉煌的历史，他们誉满全国，桃李天下。 1950年3月25日，中国人民解放军的文艺队伍中多了一名“新兵', '2010-07-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID0hCojttUK1HGPM_v1olLNVDS6lKdjnc0qio6tlcWeFyXuQbQf9GpBsZD3BKmKWi0D52MUhnzlgo3oQLblipFwmGVGo-QVXaaygywjvuUPJlIzV-tikiwRF5kTn3VgB0ijJnKClb2QJQ==&uniplatform=NZKPT&language=CHS', '渣滓洞_screened,红梅赞_screened');
INSERT INTO `ds_article` VALUES (5326, '报纸', '德艺双馨的时代歌者', '李亚新', '农民日报', '农民日报', '德艺双馨;空政文工团;《唱脸谱》;金娃娃;歌剧《江姐》;长城长;', '《红梅赞》、《绣红旗》、《我爱祖国的蓝天》、《敢问路在何方》、《前门情思大碗茶》、《故乡是北京》、《唱脸谱》、《风雨同舟》、《雾里看花》、《长城长》……在音乐的流转回放中，这些创作跨度达半个世纪之久的经典作品，与一个人的名字联系在一起，并成为一个时代的记', '2010-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDeCkC44oqWsDxBwJtoLJYhIfeB9272TFsKkfgHG-EL1JN1nHqqkQYjEdeNZNp0kFliZnrtzb17MQ6hiMUIVH1NcuL2_h-B_Q_72KcxlsMGfDrVj371NZSIQ5F6nlEFOONn_DQeHhYTzw==&uniplatform=NZKPT&language=CHS', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5331, '报纸', '传承革命精神 弘扬时代旋律', '刘茜; 徐梦菲; 刘伟', '中国文化报', '中国文化报', '红色题材;剧目创作;歌剧《江姐》;空政文工团;革命历史题材;红色经典;', '编者按：由中宣部、文化部共同主办的“庆祝中华人民共和国成立60周年献礼演出”正在精彩上演，在全国调集的110余台优秀剧目中革命历史题材的剧作占到1/4以上。芭蕾舞剧《红色娘子军》，歌剧《党的女儿》、《洪湖赤卫队》、《野火春风斗古城》，京剧《华子良》，豫剧《铡刀下', '2009-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLM2mIGGjXokc1HrH3Sedt4qwT7CQuDom1xJCxi-m21LPII8AH90HgZhADmJnrKCz8Cx32KZQH_vj9gTTu0poW08NP899ikJcVNag8aJ5y-j4gCU5a5SzW5_v6jhrLF0Goc-Z93ceTkw==&uniplatform=NZKPT&language=CHS', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5345, '报纸', '经过是最丰厚的礼物', '', '中国文化报', '中国文化报', '江姐;监狱;国家机器;', '回想创作舞剧的那些日日夜夜，我的心开始隐隐作痛，我想每个编导在回想创作经过时可能都会和我一样，因为创作本身是孤独的、艰辛的，甚至是痛苦的。 创作舞剧《红梅赞》任务接下后，我将所有关于红岩题材的资料、小说、电影、纪录片、电视剧、诗集等等都收集在一起反复', '2003-12-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICDwGbngOF1bknA2OLRLLYSiIWdoUkeO-ZqSL3ZxNuCzRxko8LZDJyoXxsYjLVX5nH0hpBIzC_4up74yFe9bB2mJebOZVFdBSBHDztaXpkqa2F1e8V-Ch9K_Z5fBVLxoC6L5J4WsY2gjQ==&uniplatform=NZKPT&language=CHS', '渣滓洞_screened,红梅赞_screened');
INSERT INTO `ds_article` VALUES (5353, '报纸', '关于西部大开发中的文化建设问题', '孙家正', '人民日报', '人民日报', '革命文物;文化资源;文化遗产;文化生态环境;历史文化遗存;江泽民同志;', '实施西部大开发战略，是以 江泽民同志为核心的党中央总揽 国家现代化建设的全局、面向新 世纪作出的重大决策。它关系到 东西部地区协调发展和最终实现 共同富裕，关系到民族团结、社会 稳定和边防巩固，具有重要的现 实意义和深远的历史', '2000-09-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBAsbuZludcCgz79IhCtXSnj_UI8MmPrA37t5sya7P2NLUilnLueJDq57ZGaopqTk9mWPRMuzXjEV0ogXvIK5bRJc6hu7VYPcGmhC10XEjQG334hCwh8CNwLUXIUO8xNU31BZ6XdWsTDQ==&uniplatform=NZKPT&language=CHS', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5354, '报纸', '交响清唱塑造“江姐”', '严长元', '中国文化报', '中国文化报', '歌剧《江姐》;', '本报讯（记者严长元）记 者从北京市文化局获悉，由著 名作曲家鲍元凯改编、北京交 响乐团与中国交响乐团合唱团 联合演出的交响清唱剧《江 姐》将于10月7日、9日搬上 首都舞台。  小说《红岩》、电影《在 烈火中永生》、歌剧《', '2000-09-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA9Spd1SuXp1rOV4HM1CK8m5ndoEyjYAFds1adbdm3kZ8_ftY7_y0pHoJBgQeWuOEYeGIW3IChEE4yn9JRbUJYxr5MksNRd95kvwUhQAHvUHCETCkEz0nckt6KJFyW7kh_nhZLe_S0YXQ==&uniplatform=NZKPT&language=CHS', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5355, '报纸', '历史形象活起来', '周向阳', '中国文化报', '中国文化报', '红岩魂;活起来;', '连日来，“红岩魂形象报告展演”在京 城的演出非常火爆。早在未演出之前就售出 10场演出票。从6月7日起演出3场后，反 响强烈，一下子定满了20场的票。每场演出 座无虚席，掌声不断，观者泪流满面。首都医', '2000-06-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDm_4Cr9IazQy7z3jsFxOwbfVfj26cP_rR7JjsFhqW309e6KeiC0ekrofDfD0DK-oJGWriJNRBWQeHmJaTmsfDFZn1jvdo8dArsYY6LJDRVBexx-3xMBrfqxYy-f4_-aY2WEXU7spwoTA==&uniplatform=NZKPT&language=CHS', '渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5357, '报纸', '重庆沙坪坝：赓续红色基因 争当红岩传人', '周捷; 任学意; 瞿毅', '人民公安报', '人民公安报', '红岩精神;红色基因;沙坪坝区;', '6月19日下午，冒着阵阵细雨，重庆市公安局沙坪坝区分局35名入党积极分子走进歌乐山烈士陵园，缅怀革命先烈，接受红岩精神的洗礼。在烈士公墓，大家举起紧握的右拳，庄严宣誓。 沙坪坝是红岩精神的重要发祥地。近年来，沙坪坝区分局用好、用活红色资源，坚持把红色基因融入血', '2023-06-28 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2023.003395', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5358, '报纸', '文润山城气自华', '李勇; 张桂林; 周文冲', '新华社;', '新华每日电讯', '重庆奉节;红岩精神;朝天门;', '“城门城门几丈高，三十六丈高，骑马马坐轿轿，城门底下走一遭……” 在重庆巴蜀小学，唱着这首童谣做游戏，是孩子们喜欢的课前活动之一。学校不远处是保存至今的明代城门通远门和城墙，孩子们的歌声萦绕门墙，连接古今。 重庆，山环水绕、江峡相拥，人文荟萃、底蕴厚重。', '2023-06-14 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.003423', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5359, '报纸', '陈晋：弘扬红岩精神 传承红色基因', '郑芳芳', '光明网;', '光明日报', '红岩精神;精神谱系;红色基因;共产党人;', '历史从哪里开始，精神就从哪里产生。中国共产党一经诞生，就把为中国人民谋幸福、为中华民族谋复兴确立为自己的初心使命。一百年来，中国共产党团结带领中国人民进行的一切奋斗、一切牺牲、一切创造，归结起来就是一个主题：实现中华民族伟大复兴。 中国共产党人的精神谱系', '2023-06-02 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.002535', '白公馆_screened,渣滓洞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5360, '报纸', '重庆沙坪坝：红岩精神融入公安血脉', '郑欣; 瞿毅; 马晓蕾', '人民公安报', '人民公安报', '红岩精神;沙坪坝区;', '山雨沥沥，微风扑面，初夏的歌乐山一片绿意葱葱。 5月18日下午，重庆市公安局沙坪坝区分局组织数十名民警辅警来到位于歌乐山麓的红岩魂广场开展读书交流活动。这是沙坪坝区分局继承弘扬红岩精神、加强队伍思想教育的一项具体举措。 沙坪坝区是红岩精神的发源地。近年来，沙', '2022-06-17 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2022.003159', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5361, '报纸', '铸魂之旅', '罗金沐; 闫晓强; 王裴楠', '中青报;中青网;', '中国青年报', '联合作战指挥;毕业学员;大西柏坡;八路军一二九师;战例教学;民兵训练基地;政治理论教学;正定县;习近平;', '5月26日，革命圣地西柏坡迎来了“中共中央和人民解放军总部移驻西柏坡”74周年纪念日，国防大学联合作战学院组织第九期联合岗位资格培训班的65名学员专程来到这里学习调研。学员们在这里看地形、忆战史、上党课，在历史与现实中探寻未来战争的制胜之道。 据学院领导介绍，调', '2022-06-16 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2022.002083', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5362, '报纸', '科技助拳舞台剧 带你穿越时空感受红色魅力', '雍黎; 单倩澜', '科技日报', '科技日报', '舞台剧;红岩精神;钢结构屋顶;', '吊脚楼、长石梯、老牌坊、纤夫拉着木船、码头人来人往……随着灯光亮起，曾经让人熟悉的老重庆出现在观众面前。随着音乐变换、舞台转动，观众座位也随之旋转，凭借高科技的舞台表现手法，观众们仿佛又穿越回“黎明”前的山城，重温那段满含悲壮而又令人肃然起敬的历史。', '2022-01-07 08:00:00', 'https://link.cnki.net/doi/10.28502/n.cnki.nkjrb.2022.000097', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5363, '报纸', '主旋律剧目市场化运营的底气从何而来', '王金涛; 陈国洲', '新华每日电讯', '新华每日电讯', '舞台剧;影视剧;', '今年是中国共产党成立100周年，重庆推出了一部演绎红岩故事的大型舞台剧《重庆1949》，演出期间几乎场场爆满，有时甚至一票难求。更出乎意料的是，这部红色剧完全由社会资本打造创作，政府财政未出一分补助资金，全部实行市场化运营。 近年来，我国主旋律题材的影视剧日渐', '2021-12-28 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.009975', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5364, '报纸', '重庆：以红岩精神赋能法院高质量发展', '刘洋; 李错', '人民法院报', '人民法院报', '红岩精神;', '“解放战争时期，众多被关押在渣滓洞、白公馆的中国共产党人，经受住种种酷刑折磨，不折不挠、宁死不屈，为中国人民解放事业献出了宝贵生命，凝结成‘红岩精神’。” ——习近平 “红岩上红梅开，千里冰霜脚下踩，三九严寒何所惧，一片丹心向阳开……” 一曲《红梅', '2021-11-22 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.005135', '白公馆_screened,渣滓洞_screened,红梅赞_screened');
INSERT INTO `ds_article` VALUES (5365, '报纸', '弘扬红岩精神，赓续红色血脉', '', '人民日报', '人民日报', '红岩精神;抗日民族统一战线;', '重庆是一块英雄的土地，有着光荣的革命传统、丰富的红色资源。习近平总书记指出，“解放战争时期，众多被关押在渣滓洞、白公馆的中国共产党人，经受住种种酷刑折磨，不折不挠、宁死不屈，为中国人民解放事业献出了宝贵生命，凝结成‘红岩精神’”，强调“要运用这些红色资源', '2021-10-21 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011043', '白公馆_screened,渣滓洞_screened,狱中八条_screened,红梅赞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5366, '报纸', '传承红岩精神 走好新的征程', '王斌来; 蒋云龙; 吴月', '人民日报', '人民日报', '红岩精神;共产党人;渣滓洞;江竹筠;', '重庆要运用这些红色资源，教育引导广大党员、干部坚定理想信仰，养成浩然正气，增强“四个意识”、坚定“四个自信”、做到“两个维护”，始终在政治立场、政治方向、政治原则、政治道路上同党中央保持高度一致。 ——摘自习近平总书记2019年4月17日在重庆考察时的重要讲话', '2021-10-21 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011056', '白公馆_screened,渣滓洞_screened,狱中八条_screened,红梅赞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5367, '报纸', '坚如磐石 百折不挠', '张国圣; 周洪双; 潘洵; 郭亮', '光明日报', '光明日报', '中共中央南方局;理想信念;毛泽东;周恩来;共产党人;人民民主统一战线;罗广斌;红岩村;红岩精神;革命志士;国统区;斗争到底;抗日民族统一战线;党组织;《我的修养要则》;党中央;', '1938年，抗日战争进入相持阶段。这年秋天召开的中共中央六届六中全会，决定成立以周恩来同志为书记的中共中央南方局，加强党对国民党统治区工作的领导。1939年1月16日，中共中央南方局在重庆正式成立，同年5月因驻地被日军炸毁搬迁到红岩嘴。“红岩”从此与中国共产党领导的', '2021-10-21 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005361', '白公馆_screened,渣滓洞_screened,狱中八条_screened,罗广斌_screened,陈然_screened,抗日战争1_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5368, '报纸', '在烈火中永生', '钱宗阳; 闫昱燃; 罗杨', '解放军报', '解放军报', '在烈火中永生;红岩精神;渣滓洞;武装斗争;烈士陵园;江竹筠;歌乐山;国民党反动派;罗广斌;', '舞台上，巨大的LED屏幕显示着明艳的红色背景。站在摄像机前，“七一勋章”获得者张桂梅，用那双布满皱纹的手轻捧起一篇书稿，以微微颤抖的声音开始朗读—— “江姐双手接过红旗，迎风一抖，五颗晶亮的金星，立刻随着红旗飞舞……” 这是小说《红岩》的经典片段。1961年', '2021-10-20 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006625', '白公馆_screened,渣滓洞_screened,狱中八条_screened,罗广斌_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5369, '报纸', '坚定信仰 宁死不屈', '刘敏; 陈国洲; 周文冲', '新华每日电讯', '新华每日电讯', '红岩精神;渣滓洞监狱;革命志士;', '“红岩上红梅开，千里冰霜脚下踩。三九严寒何所惧，一片丹心向阳开……” 红岩，不仅是一个地理概念，更是一个精神地标。 七八十年前，一群中国共产党人胸怀为真理而斗争的坚定信念，抱定为人民解放事业而牺牲的壮烈情怀，以崇高的思想境界和非凡的政治智慧在国民党统', '2021-10-20 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008049', '白公馆_screened,渣滓洞_screened,狱中八条_screened,红梅赞_screened,陈然_screened,抗日战争1_screened');
INSERT INTO `ds_article` VALUES (5371, '报纸', '旅游“中国红”点亮国庆“黄金周”', '吕梦琦; 王学涛; 陈志豪', '新华每日电讯', '新华每日电讯', '红色旅游;八路军太行纪念馆;“黄金周”;红色景区;出游人数;旅游景点;', '新华社北京10月8日电（记者吕梦琦、王学涛、陈志豪）“十一”假期，全国各地的红色旅游景点熙熙攘攘，不同年龄段的游客参访革命遗址、聆听红色故事、回望百年征程……在重温红色记忆中感受家国情怀。红色旅游再次成为中国国庆黄金周的一大亮点。 红色旅游热再攀新高 连', '2021-10-09 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.007777', '白公馆_screened,红井_screened');
INSERT INTO `ds_article` VALUES (5373, '报纸', '穿越时空对话的红色魅力', '陈国洲', '新华每日电讯', '新华每日电讯', '项目部;保育院;舞台设计;红色文化;渣滓洞;', '这是一个讲述中国老百姓与中国共产党之间深厚感情的故事。 在党的百年华诞到来之际，一群心怀信仰、崇敬先辈的人，打造了一部红色旅游演艺剧目《重庆 1949》。他们中有文艺工作者、企业家、设计师、工人等。两年多时间，他们克服疫情、洪灾影响，完成了从创意、编剧、剧院', '2021-06-30 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005173', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5374, '报纸', '忠诚与捍卫之歌', '郑欣; 何斌然; 陈燕; 王人玉', '人民公安报', '人民公安报', '公安民警;公安派出所;重庆市;党史学习;公安机关;为民服务;红岩精神;安保任务;红色资源;公安局;', '“山水之城·美丽之地”重庆，因其独特秉性，成为中外游客行千里、致广大的打卡胜地。重庆之所以这么“红”，不仅源于其山环水绕、江峡相拥的山水颜值，江汇百川、开放包容的城市胸襟，更源于其顶天立地、铁骨铮铮的英雄气质。 这是一块英雄的土地，有着光荣的革命传统。', '2021-06-29 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003653', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5375, '报纸', '传承红色基因 锻造高素质重庆公安铁军', '', '人民公安报', '人民公安报', '红色基因;', '记者：今年是中国共产党成立100周年，请您结合党史学习教育谈一谈新时代传承红色基因有何重要意义？ 胡明朗：红色基因是一代又一代共产党人在百年历史中创造并积淀形成的，是中国共产党安身立命的伟大精神内核和中国特色社会主义事业不断发展进步的强大动力。党的十八大以', '2021-06-29 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003654', '白公馆_screened,渣滓洞_screened,狱中八条_screened');
INSERT INTO `ds_article` VALUES (5376, '报纸', '“狱中八条” 警示当下', '王鑫昕', '中青报;中青网;', '中国青年报', '中共重庆;渣滓洞监狱;党组织;地下斗争;罗广斌;', '30多年前一个偶然的发现，在中国共产党党史上留下了一份宝贵的遗产。 1989年，时任重庆市委党史研究室副主任的胡康明，根据川东地下党老同志提供的线索，在重庆市档案馆内找到了一份珍贵的党史材料：《关于重庆组织破坏经过和狱中情形的报告》（以下简称“报告”）。', '2021-02-02 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.000391', '白公馆_screened,渣滓洞_screened,狱中八条_screened,罗广斌_screened');
INSERT INTO `ds_article` VALUES (5377, '报纸', '巴渝山水育忠魂', '郝思斯; 徐杨', '中国纪检监察报', '中国纪检监察报', '廉政教育;市纪委;廉政文化;张鹏翮;', '重庆是一座山城，也是一座江城。三千年来，从“巴”到“重庆”，巴渝文化在这里发祥，“红岩精神”在这里起源。这里有“锣岩月峡谁传去，要使前贤畏后贤”的豪情壮志，也有“克忠克孝，惟读惟耕”的清风传承；有“愿以我血献后土，换得神州永太平”的英雄气概，也有“人的躯', '2020-12-25 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2020.006374', '白公馆_screened,渣滓洞_screened,狱中八条_screened,罗广斌_screened,陈然_screened,抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5378, '报纸', '点亮红岩精神的信仰之灯', '黎余', '重庆市委党史研究室;', '中国组织人事报', '红岩精神;共产党人;习近平总书记;国统区;抗日民族统一战线;南方局;', '在中国革命精神谱系中，有一种革命精神与党的大多数革命精神诞生于革命根据地或革命军队不同，它诞生于党在重庆国统区的革命实践中，这就是红岩精神。 2016年以来，习近平总书记在关于重庆工作的系列重要讲话中多次谈到红岩精神，要求运用这一宝贵红色资源教育引导广大党员', '2020-04-08 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2020.000986', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5380, '报纸', '何建明：我为什么重写“红岩”', '舒晋瑜', '中华读书报', '中华读书报', '何建明;共产党人;革命者;', '作为报告文学作家，何建明的每一部作品，都是辛辛苦苦“走”出来的，而寻找“真实的红岩故事”，他走得更深，更远，更累。 这大概是何建明执笔以来写作最艰苦的一次。作为中国作家协会副主席、中国作家出版集团管委会主任和作家出版社社长，他有做不完的大量行政事', '2011-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDb_FWXY0gEVDiZcpxdEA4kouIT2sqDKYVb4Jz7tSnJQcr8PWB95l52t9EeXSZSnSPUt94KCIktpgPRHZhBw18-EHqHB7uOHj_oZwjcjQHPa-0KJWDVT8xsy7VqfeuNyEKX7nddgMpWKg==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,狱中八条_screened,罗广斌_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5381, '报纸', '《狱中八条意见》——振聋发聩的警世钟声', '范炬炜; 郭小强', '解放军报', '解放军报', '《狱中八条意见》;生活作风问题;', '新中国成立了、天亮了，自己却看不见光明、即将遭受反动派的屠杀——白公馆和渣滓洞监狱里的革命志士，你们在想些什么？ 没有抱憾，没有叫屈，至死不改信念的共产党人啊！你们最后想到的是：为终于建立起新中国的伟大的党，提几条有益的建议。 来到“白公馆”监狱', '2011-06-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICzm-XtOfM8C9NoLFd8XIVCxZ2jF43T4Pdu3BDH-cePnc20fg-tectaRYi18CDF7WUyuXpAcA8SOOwXxsn9HVMJ2WNo8W9xmZ8isQsa_9x0LGQAu4VJ-07mwgtcQ9I9syZjJVhLrQ9CKQ==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,狱中八条_screened,罗广斌_screened');
INSERT INTO `ds_article` VALUES (5382, '报纸', '不朽的丰碑 永远的怀念', '赵承 ; 李斌 ; 李柯勇 ; 周英峰 ; 卫敏丽 ; 俞菀 ; 蔡玉高', '新华社;', '新华每日电讯', '夏明翰;天安门广场;共产党人;中国共产党成立;人民英雄纪念碑;瞿秋白;', '清明,是一个涤荡心灵的日子。 上海,龙华烈士陵园。青松挺拔,绿草茵茵。“丹心碧血为人民”纪念碑前,一群年轻人围着一位耄耋老人,听他讲烈士的故事,言者动情,听者动心:“信仰支撑着共产党人前赴后继,视死如归。今天,我们更需要这种信仰……” 清明,是一个追', '2011-04-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAxkM35Nff3ktZq7A5YHLaUkT1DyyN1Dfw_y_KuVg0SLnYHicsZXRCmia2J1Q0qtthMCllSnWGjzvtwWe6S_TDVjaFNgLcoByFpIgbT7wkH5oEJ1ZniGmooClh4cYMii9Nnu0s7N3DaAA==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5383, '报纸', '重温历史忆峥嵘 同心同行向未来', '廉维亮', '人民政协报', '人民政协报', '多党合作制度;领导人;民主党派;无党派人士;同心同行;', '山城重庆一如既往的雾霭重重，但和煦的春风已经让居住在长江、嘉陵江岸边的百姓们感到了温暖。3月28日至29日，这里的红歌又一次唱起，既唱给90周岁的中国共产党，也唱给了前来山城参加统一战线“重温历史，同心同行”主题教育活动的各民主党派中央、全国工商联领导人和无党派', '2011-04-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBXlDc4UYcatxyvuR18DQgqLQi6z6Z3vRP3AcLNMVTZahSZb0tbNpbSAlzB98iaYhTNyBVVpsKKtp-UoE9AzEskhhVkUkTRdz6ZXCRtP2txt9FBeYVRA98MUi65tQUHY1_FQviWbKX7ZA==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5384, '报纸', '从实业救国走向同舟共济', '木佳', '中华工商时报', '中华工商时报', '实业救国;无党派人士;中国共产党领导;胡子昂;工商业者;民主党派;非公有制经济人士;官僚资本;场景复原;中共中央南方局;', '3月29日下午，素有雾都之称的重庆，阳光分外的明媚。 各民主党派中央、全国工商联领导人和无党派人士代表齐聚重庆，为全国唯一一个全面反映中国共产党领导的多党合作和政治协商制度的综合展馆——中国民主党派历史陈列馆剪彩。 而这一天，重庆上清寺依旧车', '2011-03-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICuepHIPvsQU_x9EdkZCQ-qoRwYG1yBXC2T1NO-n4RYs-TUsE8GCSG0ySCFAUUYoRLrBJlvtG_oxsIZa6wVxwT3G7ozc91sBFHUMPQNsIT06liJpJJSklfaOVbNXORsCsniGM9sEX9BGA==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5385, '报纸', '肝胆相照化同心 携手同行创辉煌', '王海磬', '光明日报', '光明日报', '多党合作制度;领导人;民主党派;无党派人士;参政党;', '春天的山城暖意融融,素有“红色之都、统战名城”美誉的重庆,迎来一批特殊的客人。3月28至29日,各民主党派中央、全国工商联领导人和无党派人士代表齐聚重庆,参加统一战线“重温历史,同心同行”主题教育活动,亲践历史足迹,缅怀老一辈民主人士与中国共产党肝胆相照的高风亮节,憧', '2011-03-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAuH1uOk9jkktLy9B-evnNFD3717gqh9U9lDQ-4skAo9PPK2lDkRChyYNHTr1e6Hga2qudtObeKM9d9uJLL_rzUNw5tItYpXfYoOmbmpNgshWDUqfX1WqAdAKan9KppxCP_awthF11WRA==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5386, '报纸', '“小活动”蕴含大道理', '沈义', '检察日报', '检察日报', '人民检察官;大道理;宪法和法律;主题实践活动;红色遗址;社会公平正义;', '8月11日上午，重庆市检察院检察长余敏及全院干警，激动地聆听了四川省汶川县检察院检察长孙力的专题报告“灾难磨砺意志，忠诚铸就检魂”。  “恪守检察职业道德、促进公正廉洁执法”主题实践活动开展以来，重庆市检察机关按照“深入、生动、实效”的要求，充分利用', '2010-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA6YWToxncG1oAsv5ZAeyV4bSKiksgHxt8ZJgivJLSz70MVr_9hIZ7aAHydx9lym2WW-gNJOlhTYbZKaqnrAC6b-08_SPHQmSWrfIG2giQGoSSH2flCbOl9diPfDYkJVgDJICHVv8rGCA==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5387, '报纸', '重庆红岩革命历史博物馆', '', '中国纪检监察报', '中国纪检监察报', '红岩精神;历史博物馆;', '重庆红岩革命历史博物馆是重庆红岩革命纪念馆、重庆歌乐山革命纪念馆、特园——中国民主党派陈列馆等九个革命纪念馆的总称。主要以红岩精神的传播宣传为主要工作任务。红岩精神是以周恩来为首的中共中央南方局抗战期间在重庆亲自培育缔造，无数革命志士用自己的生命和鲜血实', '2010-06-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBmS5kWVqamdcEl2E9BXdjPEgSogifzVJGvJjTuc8LD_vQdjiV60-QEENk-V-rURFEYj-CG8rSF0a2C1zzrlJ9qVMlEFZ4bNuMUlyx09aT1hKDkpXFGesU8Rx2cfGHv3mg96RroV_K4kg==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5388, '报纸', '重庆：红色旅游之路越走越宽广', '李明明; 谢倩', '中国旅游报', '中国旅游报', '红色旅游;红色景区;重庆市旅游局;无障碍旅游;', '景气市场显示“红色实力” 2009年，重庆的红色旅游突出了持续、快速、健康发展的良好势头。记者从重庆市旅游局了解到，2009年重庆市红色旅游全年接待游客达到890万人次，同比增长14.9%，其中接待入境游客8.1万人次。重庆市著名的红色旅游品牌红岩联线延续了旺盛的人', '2010-01-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDSMb6WU3hNRh96Fb8p4llzZA1_vbuVVg_B0u2WndryCCGXImMRaWxM3PzCkM_uR9N3A-0c75oR4hRynHE62UZLIIlYcQ75aF76ditj5wF8ZNSZtszxDr37RS1ghTte713zstZDUJB6pw==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5389, '报纸', '故事中的重庆大学', '', '中国教育报', '中国教育报', '重庆大学;马寅初;红歌会;全国重点大学;大学师生;', '引言:重庆大学80年的历史长河由一滴滴水珠和一朵朵浪花汇流而成。回顾过去，无论是闪烁着爱国光辉的寅初享、宁死不屈的红岩战士、爱校如家的郑思群、激情飞扬的红歌会，还是敢于探索办学的新体制、冲破国外技术封锁国内首创的ICT、短期内深度融合的新重大、引领“重庆速度”', '2009-09-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID74EdsR32Qs9O4zMimyqwHjNrZSn7N7aqrOaPErWCkTZiB8iQdJnuHaQqm7_MUgs4mHgiloRKyooMahWPlfDFKlRe48Q2u6pQEZ2NffmMYlPBEnFiIXBjT5a3xEKIYGoZMQ8BUF5uS2g==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5390, '报纸', '“监狱游”引发追怀与警醒', '冯新生', '中国旅游报', '中国旅游报', '爱国主义;监狱文化;', '监狱见证时代风雨 为撰写报告文学《中国监狱》，作家武韬历时2年，在江西上饶、四川重庆、河北石家庄等省市的监狱进行采访。 在接受记者采访时，武韬表示，在新中国成立60周年之际，连续热播的一些反映革命先烈在狱中与敌人斗争的老电影，引发了人们前往囚', '2009-09-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDi-2-NpHjoOOrpnTWAd6wIoB0iNJxEKn0Lgd4tPNbhTIRIXvi4JguXY_8SOIgmVW1kvxVe5YrU3MC_hh0_56dN9xi9zGNWgmrOsRlARoy_jzikvaO5aQtynwY0u6C9LsX1yWfPgAKI7Q==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5391, '报纸', '红色联盟成就绿色通道', '李明明; 谢倩', '中国旅游报', '中国旅游报', '红色旅游;息烽集中营;精品线路;绿色通道;', '2005年，重庆、贵阳、遵义、广安3省市4城市签署了旅游合作协议，联合打造红色旅游精品线路，渣滓洞、白公馆、红岩村、息烽集中营、遵义会议旧址、赤水河、小平故里等全国知名的红色景点串联成线，以“新型红色旅游产品”的姿态亮相。4年多来，当初由4个城市联手培育的“红色', '2009-07-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDpfKsRrXRXf9zBMKdSuqIYikKTPrZK5p0XZCvUaUpXVfqfx9fkBCix5GA4lr7mb3YfOzTgz1b2_NIqKZOCtTj5hEbDqJLxBPwXnYl8hnyZNuPUebLjUQK3spjLdEtz8V6V8N4YtwBQYA==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5392, '报纸', '洪灾后文化遗产受损状况调查', '乔欣', '中国文化报', '中国文化报', '文化遗产;状况调查;明城墙;', '6月底以来，我国南方的广西、江西、湖北等十几个省区因为连日的降水引发了严重的洪涝灾害。在遭受水患的地区，历史文化遗迹是否受到了影响？记者就此进行了采访。 南京：喷水如注的明城墙 7月6日晚至7日，江苏南京遭遇了一场特大暴雨，拥有600多年历史的南', '2009-07-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDxrcQTTO-JKUoIwzkHFOduU-UApAw4IiaFs8bXU7mXSG5CQc9M5AkFPVX-doOft7e5BhM0mgx2hft_2PvZ6LdO8wFE_ISWeeGMM7SYGJLfKzn36RaxQpqT3yT-tOLQFZfqhi9Z4pikhw==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5393, '报纸', '红色旅游让这个时代激情燃烧', '班若川', '中国旅游报', '中国旅游报', '红色旅游;旅游发展规划;', '72年前的初夏，美国记者埃德加·斯诺踏上前往陕北延安的旅途。他的那部不朽的作品———《西行漫记》，让许多西方人第一次知道这里有个“中国革命圣地”，而他与那个名叫“季邦”的小红军的对话，总是令人忍俊不禁。 72年后的今天，数不清的西方人、东方人，沿着斯', '2008-12-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBZ3pqYaA4pipF9Y0J-_hXYeUj4wrswHnDh4JMSbjzKaiXibZKN_n-mMvvkpVGDV1ImvsEEOkgscKAGrm9DlrRFEgeL2uad77V8K0kR7tykFucTVyG5Pz532tMIUsXS7WpBFM4JYcTDZQ==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,茨坪_screened,井冈山会师_screened');
INSERT INTO `ds_article` VALUES (5394, '报纸', '演艺文化成为红岩联线“特殊”名片', '田凤; 谢倩', '重庆记者站;', '中国旅游报', '情景剧;红色旅游;', '上世纪60年代出版的红色经典小说《红岩》曾经风靡一时，影响和教育了几代中国人；上世纪80年代开创的《红岩魂》巡展、报告会，让许许多多的人受到烈士们英雄事迹和崇高品格的熏陶；上世纪90年代末，《红岩魂形象报告展演》首次运用文艺演出的形式掀开了红岩文化发展的新篇章', '2008-12-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDoUO-6EHL7fPDGH03vWo3XukEd3JmCnNuVcD13w8FXW-gOpnvYl-BREULcuej_G9EYvErCQ-hnnczG8_hQSFtanGmZ3DPDoQTm4p69BH5Fbowpzowj9uOW8JLcrJFDdgSRDAWOu8WsPw==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,罗广斌_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5395, '报纸', '炼狱忠魂 烽火不熄', '', '人民日报', '人民日报', '息烽集中营;爱国民主人士;宋绮云;罗世文;', '１９３７年７月７日，卢沟桥事变爆发，抗日烽火席卷全国。在抗日民族统一战线的旗帜下，全国人民奋起抗战。但是，以蒋介石为代表的国民党统治集团内的顽固派，仍坚持其一党独裁统治。为此，他们大力强化特务组织，设立集中营，继续逮捕和秘密关押共产党员、抗日民主人士和爱', '2007-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDVrToL-_UCXXxd3JX7isx_1EPVWnxm7fC0JKzHlyH4jDB1vykoyWZLNdj2rHh8v8JIpxEMT3098bOS-MuAPCUKxDelcHSa7aKLY96cZ0QEyGEru_bq1X7nJ8BS4TBlaXDOlGWlrZWvXA==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5397, '报纸', '文化部举办第六期处级干部任职培训班', '文华', '中国文化报', '中国文化报', '长征精神;干部任职;', '本报讯 4月19日，文化部第六期处级领导干部任职培训班在遵义会议遗址开班。文化部副部长赵维绥参加开班仪式并讲话。他要求学员加深对长征意义和长征精神的理解和认识，深入思考如何把长征精神落实到实际工作当中，全面提高思想水平和精神境界。 赵维绥指出，长征', '2007-04-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC6Zw5dI8gsWth_6CEVG0-bNHU14Sjqgh5_na5bY45Xbqubr6sB9jy8CbNAY98WxG5N85dRw9Bv_4c2IqFMBRgE0FfQiMt2YBlOC-EmJCFtxR_ecn-YU0DGLyK4nUjSGkLQJlFu4j8R-A==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5398, '报纸', '重庆拟投资9亿打造五大红色景点', '唐敏; 陈敏', '中国旅游报', '中国旅游报', '聂荣臻元帅陈列馆;红色旅游;', '重庆市红色旅游规划日前全面启动，计划投入9.1亿元，重点打造五大红色景点，规划现已通过市发改委审批立项。  据介绍，重庆市计划投入9.1亿元，重点打造红岩村纪念馆、歌乐山纪念馆、刘伯承元帅纪念馆、聂荣臻元帅陈列馆以及赵世炎烈士故居5大红色旅游项目。其中，', '2005-08-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBpbwGP34_bGYwYkdWHbAbUTN-gYso9My1qPalNFLO7BbgTor_l89xciU20V9Z7eh3-AfdnUkH5oDQVZBL3rz1-TRk5XmppuGnIWt56ktMtnvGRNW_7cUYu996OuO1axY_upgQLGhGkPQ==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5399, '报纸', '重庆利用“红色资源”增强教育感染力', '程世平', '人民公安报', '人民公安报', '红色资源;教育感染力;革命传统教育资源;', '本报讯 重庆市公安局充分运用本地革命传统教育资源，把缅怀革命先烈与学习身边先进典型相结合，增强了先进性教育的感染力。  重庆是“红岩精神”的发祥地，有红岩村、白公馆、渣滓洞、歌乐山革命烈士陵园等一批革命传统教育资源。该局党委充分利用这一“红色资源”，以', '2005-03-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDtB8ReBVYuUCTLI7qSo31Jm6IO7LZL6kX5aTb5dNz1bvZ44rhpmU8BmUIKelVVNs3Hz4fngPhVUjZJ9tOt8Wy3fAF5utOWSXAqMagJlSbHsSFZNJtwd1TRPC4iCiQ3XwK07T_45f7Cpg==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5400, '报纸', '要将广安打造成为全国红色旅游名城', '张洵涛', '中国旅游报', '中国旅游报', '旅游名城;红色旅游区;华蓥山游击队;红色旅游资源;', '问：能否简单介绍一下广安的红色旅游资源情况？  答：广安是邓小平同志故里。1904年8月22日，邓小平同志诞生在广安，并在这里度过了15年的青少年时光，留下众多遗迹。四川省委、省政府于2001年6月批准设立了面积为29.91平方公里的邓小平故居保护区，其核心区为现已建成', '2005-03-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB4-UrwoMZNnBJK-rT2oMWcN9CJlp87oDQME1ARjVLZHE5yyaCbiI_fLVSG5G8koKsb5p7nVtX6dXZSOnX88iUKPAavTZrJbEaHxRGc-ntbo82PEacjF-_OX8shBhJLFtGIfvzwlqWHBw==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5401, '报纸', '重庆旅游该打什么牌', '李晓良', '中国旅游报', '中国旅游报', '重庆都市旅游;陪都文化;', '“虽然拥有长江三峡、大足石刻等高品位旅游 品牌，但重庆缺乏个性鲜明、富有魅力的整体形象 定位，尤其是重庆曾因作为二战反法西斯远东战 场的指挥中心，以及历史上的抗蒙要地而影响世 界的历史名城形象，远未在旅游市场上树立起 来。”在刚刚结束的', '2005-02-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBVl3mEMkOOm5gU7hyr-zgEzwvoIPMPhqb8GTkbvDHU6D0od9Mj0K-mVG41FJyj_I-zN6K_IFsIS-vVA-rKbij2mHeP7tSdpnBuZveikjjecJs8gEnK1gnV95ibtoNuQLCIsatf-uOmtg==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5402, '报纸', '全国统一战线传统教育基地在渝成立', '段明天; 周少诚', '人民政协报', '人民政协报', '陈喜庆;', '本报讯（记者 段明良 周少诚）日 前，重庆红岩革命纪念馆广场鲜花簇拥， 鼓乐喧天，重庆市各族各界人士1000余 人列队举行“全国统一战线传统教育基 地”（以下简称“教育基地”）挂牌仪式。中 共中央统战部副部长陈喜庆、民革中央副 主席李赣骝、民', '2005-02-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDJmHscds5opd1n72sPox4B4NZGN4Oo1KuVmZ3aUUo0pknjR4NrgPOY-zfIlqZy_y7e7Olm1w7jF5yYCbQHZvY8CjiSk_k_RTwVMS98uS4yUuoQ6ldPGCfngX7BDqyGpozrVZ1cvlUAKw==&uniplatform=NZKPT&language=CHS', '白公馆_screened');
INSERT INTO `ds_article` VALUES (5403, '报纸', '重庆“红岩文化”的商业味之辩', '李建勋', '中国商报', '中国商报', '革命纪念馆;重庆市;研发中心;文化局;红岩文化;革命烈士陵园;', '2004年的最后一个星期天，记者来到重庆市歌乐山革命纪念馆和红岩革命纪念馆参观。尽管冬日的山城因为寒流而冷雨潇潇，但两家纪念馆仍然人流如织。 庄严肃穆的氛围与游客乱扔的瓜壳纸屑及摊贩的吆喝叫卖显得有些不协调,管理者将此归因于景区旅游“综合症”。而一些缅怀者', '2005-01-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICNMVQKz4ViX2uM86cnHsmkMxs8kHqX-8qh7YDyqYjyiXbXHGAKYyX79XGgEZdLAz9hD_VKq-efLnMlu9SYIhJAxWW9Okl6E3L8vFh1lBe5kgbLTijiV3rQC80f04WI8uRv29IwjqFkSQ==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5404, '报纸', '小平故里构建红色旅游圈', '刘谨', '经济参考报', '经济参考报', '旅游圈;红色旅游;旅游目的地;广安市;华蓥山游击队;中国优秀旅游城市;', '今年以来，前往四川广安邓小平故里瞻仰、游览的海内外游客络绎不绝，平均每天达到上万人次，使得“小平故里游”成了四川旅游最热门的线路。 近年来,广安市加大了对“红色旅游”资源的开发，对众多革命纪念遗址进行了修复和完善，同时，随着广（安）渝（重庆）、成（都）', '2004-12-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDbeCSteWtbjPL1yM-K0f9KKEuF7g-iZl9-6E4WNnjoDN7wn-fF3E23UakyZyf_aF0Q73eRok_CPyxSAIWxyajnKojZzWLhr4x9vqntQm21TYS5Y54hj1U0jq5yyM5dna94nSlHNgs0-g==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5405, '报纸', '红梅，绽放在冬雪时节', '郭凯; 肖海洪; 刘璇', '解放军报', '解放军报', '空政歌舞团;“红色经典”;现代意识;精品工程;', '在晶莹剔透、纷纷扬扬的白色精灵簇拥下，美丽的缪斯女神手捧一朵娇艳盎然的红梅向我们款款而来：空政歌舞团大型现代舞剧《红梅赞》成为首届国家舞台艺术精品工程的惟一入选舞剧，为军旅文艺创作再添殊荣！11月25日，来自军内外的首都文艺界专家聚集一堂，就《红梅赞》的艺', '2003-11-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC1FDxliY4AhraPo5XL6SzxBwOxc0dWVTEobqQlKlh_aGaKkaQhXaJEFJ3-4ipJDRYZUhqhMRxT2U1jgYz3IEqZfsITZbUztzKeKgvWtsD3LFIaXA0_6sXsyfuQsiJn_kiE5Xo8cTO6cg==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,红梅赞_screened');
INSERT INTO `ds_article` VALUES (5406, '报纸', '重庆歌乐山革命纪念馆为何能红遍全国', '刘文新', '中国消费者报', '中国消费者报', '歌乐山革命纪念馆;红岩魂;', 'T八一建军节前夕，重庆市文化局副局长、重庆歌乐山革命纪念馆馆长厉华向新 闻界自豪地宣布：歌乐山革命纪念馆今年已接待游客214万人，游客量连续12年 保持全国同类行业第一──E  厉华馆长介绍，经过多年发展重 庆歌乐山革命纪念馆不仅成为全国参', '2003-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICv57P7xlzekqzLnyIabyF68dVYR64d_yceiuEW93QbXAH9gbIPdIb3Cm-KA5Pe23kEowelB51P6V0YkRE3axjsY3TpggFi997QcOfaBgNxQ-BPqJeprNViQtp0Y43Zjv_4KkSYn4ewVA==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5407, '报纸', '红岩魂现象：精神财富的巨大魅力', '陈林; 陆晓平', '中国财经报', '中国财经报', '红岩魂;红岩文化;歌乐山;精神财富;', '一部小说 一个城市 一种产业  红岩，一个史诗般的称号，她是国家历史 文化名城──重庆的光荣象征。  上世纪50年代，杨益言、罗广斌在创作 《红岩》时不会料到，这部小说竟然传扬了一 个城市，成为今天年轻直辖市手中的一张“红 色', '2003-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAH4fCOBrWDbI-xkKwab6VC4Dp-a0yX9tLOv1MAP9I6LFeMnTKrdlfp-ZO0ozXYub91zuoVL8yUNmVoVO6qN1EYekMn6o13E0mmgv8nwhuwws5HWRLQnH2qiSxoe_BO4dUwTclP-ZAXiw==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,罗广斌_screened');
INSERT INTO `ds_article` VALUES (5408, '报纸', '“红岩精神”走出去找观众', '熊艳; 徐旭忠', '新华社;', '新华每日电讯', '歌乐山革命纪念馆;红岩精神;渣滓洞;', '在人们精神生活多元化的今天，原来教育意义极 强的展览已难以吸引观众，展览的主题和形式必须从 教育向启发方向转变。这是自1985年就任重庆歌乐山 革命纪念馆馆长厉华的深切体会。  歌乐山革命纪念馆1963年建馆，最初名为“美蒋罪 行”展览，', '2003-03-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBAt2jXZmj4sPD4q7d9ymyKr_UUvf3BiUJPGmmtEysCDqvge-J0-t6NW2piV3-WGx4_fX7RbJCkyYS1KqwjrbdZynIPhMMeTVYYXz-DMSsWUe_VMpGIedl4s8qbBp54J5YKdNs4Vs2T8g==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened');
INSERT INTO `ds_article` VALUES (5409, '报纸', '永恒的红岩魂', '金野; 高龙; 何永红', '解放军报', '解放军报', '保持共产党员先进性教育活动;红岩魂;', '歌乐山，一座由烈士鲜血染红的山，一座充满内在精神动力的山。今年4月以来，驻守在这里的成都军区某团，充分利用“红岩精神”，对党员干部进行“自重、自省、自警、自励”教育，从而把学习实践“三个代表”重要思想、保持共产党员先进性教育活动不断引向深入，使党员干部始', '2002-07-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB0tKg64T6wj4KsM1cDA5uwsG5qMFW1kPk5D7KiFGsfdqkj2JOupGIODYw3TuFcDL1Gqr6HG30K2PFckf-PIil5FglbUXioUZMfPR__oc2iechqdGTOE8_3Dv0fqV5M4bla5M5y7_fzCw==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5410, '报纸', '烈士血凝万代心', '纪家梅', '中国气象报', '中国气象报', '革命者;歌乐山;气象事业;', 'T重庆西北郊，有一山，山中林木 葱茏，遇风雨则万簌齐鸣，丛林清 响，古人会意，名之为歌乐山。  拥有如此美好名称的这座山， 在新中国诞生的前夜，却成了中外 特务倒行逆施的大本营；成了关押、 迫害、屠杀共产党人和革命志士的', '2002-05-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBK3t0IfgZ4RCzSnw7O0YY3u7R8KQVtYtREEejlznzXXN19QRbeciBQN7KaYP2LyXcx8QZbSaAeMzRES70B2I_WGHhXhSaxtyho57xF43YQh-npyD7A2WVD459myNaSGMfgvE0LUsonWA==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5411, '报纸', '探讨“红岩魂现象”', '刘琼', '人民日报', '人民日报', '红岩魂;渣滓洞;', '去年酷夏，重庆歌乐山烈士 陵园创作排演的“红岩魂”形象报 告剧进京演出，“场面火热如京城 的天气”，某报记者连用三个“没 想到”表示讶异：没想到，报告剧 买票竟然要开“后门”；没想到，台 上的演员全是业余的；没想到，往 常步履', '2001-11-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDP0dzGyh0qzvoJ3wAnzUSNbRrnYEg4dCKt0CwI5G-aALhMIhE3KocO5Vqo_c3fU0HmGiT_ahAkvD0nvsuFhZ3UiuJtZ27DGpwKrJQ9F6qDCtba08upuE1JYTIhqz5KoqidnsoLEfW1qg==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5412, '报纸', '把团小组建到寝室', '左益; 叶勇', '中国教育报', '中国教育报', '团小组;团员青年;团组织活动;', '2001年3月2日，重庆交通学院交通及汽车 工程系2000级最后一名非团员学生林辉终于向团 组织郑重地递交了入团申请书。这个在中学六年 一直未入团的学生，何以会在进入大学的第二个 年头想到入团呢？  了解情况的人告诉', '2001-04-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDG2V7LP0D8eGUObBi7SoS80Tc2bSHJ2v2vYDGkChHVWzD1HcNI7Gx4QwZ323Nr6Ur53MhgafYuBb-iVL66va8QtVaWtJqYQMjtVwsXJ8XXMHeFQ7htW3Kw00syowdjnTHNO-ebcYl5vw==&uniplatform=NZKPT&language=CHS', '白公馆_screened');
INSERT INTO `ds_article` VALUES (5413, '报纸', '用红岩精神建红岩', '马利', '人民日报', '人民日报', '红岩精神;渣滓洞;歌乐山革命纪念馆;', '半个世纪过去了，从1949年震撼中外的“11·27”大屠杀以来， 50 年的岁月，人们仍没有忘记白公馆、渣滓洞的惨绝人寰，没有忘记江 竹筠、罗世文、叶挺、王朴等共产党人的坚贞不屈。近年来，歌乐山革 命纪念馆又积极地开发红岩的革命文化资源，把展览办得丰富、', '2000-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDCIv-8x93kdwQbZ0UgQxORY88TzxV48Ufmuw4nOlIni66IBafJ9EPtJZVD490XgywhgcsdYso6kkn7oT6Kuo-p1YmN33fU43vNBw8U6n6iX9wRhKuHQOP7xQkKyqoyfYfc1ay6KFYgHQ==&uniplatform=NZKPT&language=CHS', '白公馆_screened,渣滓洞_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (5414, '报纸', '一生献给中华民族奋起复兴的事业', '', '中共中央党史和文献研究院;', '人民日报', '邓颖超;周恩来;革命家;中华民族;习近平总书记;对台工作;人民政协;婚姻法;', '2024年2月4日，是邓颖超同志诞辰120周年纪念日。邓颖超同志是伟大的无产阶级革命家、政治家，著名社会活动家，坚定的马克思主义者，党和国家的卓越领导人，中国妇女运动的先驱。她把一生献给中华民族奋起复兴的事业，是20世纪中国妇女的杰出代表，在国内外享有崇高声誉，深受', '2024-02-04 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2024.001234', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5416, '报纸', '高举永不熄灭的火炬', '梅世雄; 郭明芝', '人民日报', '人民日报', '烈士褒扬;制度体系;习近平总书记;英雄精神;缅怀先烈;伤残军人休养院;', '历史记忆历久弥新，英烈精神传承永续。 为民族独立、人民自由幸福、国家繁荣富强作出突出贡献的英烈，祖国和人民从未忘记。 党和国家历来高度重视英雄烈士褒扬纪念工作。党的十八大以来，习近平总书记从实现中国梦、强军梦的战略高度作出一系列重要指示批示，强调要永远铭', '2023-09-30 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.009779', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5420, '报纸', '档案里的家风故事', '韩亚栋', '中国纪检监察报', '中国纪检监察报', '共产党人;毛泽东;谷文昌;杨善洲;', '“生活上要向低标准看齐，思想上、工作上向高标准看齐”“路只有自己走才能越走越宽广”……最近，《中国共产党人的家风》档案展在重庆市档案馆和重庆市党风廉政教育基地同步展出。这些意味深长的家训，令观展者深受触动。 《中国共产党人的家风》档案展由中央档案馆国家档', '2023-08-08 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.002545', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5421, '报纸', '共话革命文物保护', '王洋; 李玉兰; 胡晓军', '光明日报', '光明日报', '文物保护;革命文物;革命旧址;', '江西瑞金叶坪，“一苏大”旧址静穆矗立，青墙黛瓦，一如往昔。1931年，中华工农兵苏维埃第一次全国代表大会在此召开，大会通过的《中国工农红军优待条例》，开启了党领导的政权保护革命文物的先河，瑞金也成为新中国革命文物工作的摇篮。日前，全国文化和旅游、革命文物相关', '2023-05-10 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.002127', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5422, '报纸', '行动是最好的传承', '郭权祺; 周福志', '团结报', '团结报', '参政党;共产党;中共中央统战部;郑建邦;李家庄;中国式现代化;民主党派;', '初夏的华北大地，草木葱郁，生机盎然。 5月5日，细雨蒙蒙中，位于太行东麓的革命圣地西柏坡，迎来了一批特殊的客人。在中共中央发布“五一口号”75周年之际，民革中央理论学习中心组在西柏坡开展2023年度第二次集体学习，第一站便来到了距西柏坡仅十几公里的李家庄——中共', '2023-05-09 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2023.000769', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5423, '报纸', '英雄故乡崛起和美乡村', '李克强; 赵大永; 刘松峰', '中国国防报', '中国国防报', '河北省军区;军分区;人武部;示范村;乡村旅游;', '春天的燕赵大地，草长莺飞，一派生机盎然。 太行山下，八路军129师司令部旧址、河北省涉县河南店镇赤岸村，游客熙来攘往。在河北省军区的帮建下，这个小山村已成为远近闻名的红色旅游目的地。 渤海湾畔，抗日英雄马本斋烈士的故乡、献县本斋回族乡本斋东村。看着眼前飞驰而', '2023-04-06 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2023.000542', '西柏坡_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5425, '报纸', '以法为基，筑牢精神丰碑', '詹丽红; 海洋; 宋子洵', '解放军报', '解放军报', '雷锋精神;雷锋班;精神丰碑;学雷锋活动;', '编者按 不懂历史的民族没有根，淡忘英烈的民族没有魂。《中华人民共和国英雄烈士保护法》明确，国家保护英雄烈士，对英雄烈士予以褒扬、纪念，加强对英雄烈士事迹和精神的宣传、教育，维护英雄烈士尊严和合法权益。今年是毛泽东等老一辈革命家为雷锋同志题词60周年。作为雷锋', '2023-03-10 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2023.001100', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5430, '报纸', '奋力实现中华民族伟大复兴的中国梦', '', '人民日报', '人民日报', '中华民族伟大复兴;习近平总书记;中国式现代化;中国梦;', '“我们要埋头苦干、担当作为，以更加强烈的历史主动精神推进马克思主义中国化时代化，不断谱写新时代中国特色社会主义新篇章，奋力实现中华民族伟大复兴的中国梦。” 23日，人民大会堂金色大厅，刚刚当选的中共中央总书记习近平和中共中央政治局常委同中外记者见面。习近平', '2022-10-24 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.011497', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5433, '报纸', '新时代 新气象', '周福志', '团结报', '团结报', '民主党派;中国共产党领导;新气象;多党合作和政治协商制度;政党协商;习近平总书记;政党制度;无党派人士;统一战线工作;', '10年，弹指一挥间。 中共十八大以来的10年，是中国特色社会主义奋进新时代的非凡十年，也是我国多党合作事业焕发新气象的非凡十年。以习近平同志为核心的中共中央统筹中华民族伟大复兴战略全局和世界百年未有之大变局，把坚持和完善中国共产党领导的多党合作和政治协商制度', '2022-10-15 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2022.001684', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5434, '报纸', '致奋斗的你我!', '关铭闻; 王慧敏; 邢宇皓; 刘文嘉; 王斯敏; 卢泽华; 谢文', '光明日报', '光明日报', '奋斗者;共产党人;中国人;我们这代人;李自成;', '目光呆滞的烟客、衣衫褴褛的商贩、瘦骨嶙峋的流民……这是百余年前苏格兰摄影师汤姆逊拍摄的晚清影像——一张张枯槁麻木的面孔，诉说着光景困蹙的悲凉。 朝气蓬勃的学生、光彩照人的白领、笑逐颜开的农人……这是近些年苏格兰摄影师布鲁斯镜头下的中国图景——一个个意气风', '2022-09-26 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.004711', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5435, '报纸', '永远不变的军魂', '', '解放军报', '解放军报', '党对军队绝对领导;党中央;人民军队;军委主席;指挥权;领导权;负责制;中央军事委员会;武装力量;党指挥枪;中央军委;', '12.为什么说党对人民军队的绝对领导是我军的建军之本、强军之魂？ 2021年7月1日，习主席在庆祝中国共产党成立100周年大会上鲜明指出，坚持党指挥枪、建设自己的人民军队，是党在血与火的斗争中得出的颠扑不破的真理。90多年来，我军之所以能够战胜各种艰难困苦、不断从胜利', '2022-09-18 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.005040', '西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5437, '报纸', '脱贫摘帽不是终点而是新生活、新奋斗的起点', '罗晨', '中国食品报', '中国食品报', '京津冀协同发展;建档立卡;北庄村;河北省;习近平总书记;新开工项目;攻坚战;', '河北省是中国唯一兼有高原、山地、丘陵、平原、湖泊和海滨的省份，也是中国重要粮棉产区，其工业生产中的一些行业和产品在我国居重要地位。70多年前，党中央从西柏坡出发“进京赶考”，新中国从这里走来。70多年来，在中国共产党的领导下，燕赵大地发生了历史性变化，经济社', '2022-08-25 08:00:00', 'https://link.cnki.net/doi/10.28137/n.cnki.ncspb.2022.001169', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5438, '报纸', '河北 燕赵大地换新颜', '倪泰; 王秀恩', '中国市场监管报', '中国市场监管报', '燕赵大地;企业信用风险;商事制度;市场监管部门;双随机;信用监管;营业执照;政务服务;市场主体;西柏坡镇;河北省;营商环境;习近平总书记;保定市;', '党的十八大以来，习近平总书记先后九次赴河北省考察调研，为新时代河北高质量发展指明方向。从太行深处到渤海之滨，从冀中平原到塞外山城，习近平总书记的足迹遍布燕赵大地的乡村田野、城市社区，指导河北走好改革发展新路。 牢记总书记嘱托，河北省市场监管卫士坚持以习近', '2022-07-19 08:00:00', 'https://link.cnki.net/doi/10.28075/n.cnki.ncgsb.2022.002469', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5441, '报纸', '传承红色基因 彰显新时代“央企力量”', '', '中国联通党校;', '学习时报', '红色基因;信息通信业;企业家精神;全面从严治党;数字化转型;', '中央通信企业的诞生和发展是中国共产党领导革命、建设和改革的一个缩影，蕴含着丰富的红色基因和精神力量，是中央通信企业兴企强企之根、汇力聚力之源。 一 中央通信企业是在党的领导下诞生于新民主主义革命时期，从一开始就具有革命精神的红色基因，伴随着红色通信事业不', '2022-05-16 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2022.000854', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5442, '报纸', '总书记这样话奋斗', '汪晓东; 张炜; 段宗宝', '人民日报海外版', '人民日报海外版', '习近平总书记;春节团拜会;中华民族;中华儿女;人民幸福;', '“成就源于奋斗，胜利来之不易。回顾7年来不平凡的筹办举办历程，我们不仅在奋斗中收获了成功的喜悦，也在奋斗中收获了丰厚的精神财富，收获了弥足珍贵的经验，值得我们倍加珍惜、发扬光大。”今年4月8日，习近平总书记在北京冬奥会、冬残奥会总结表彰大会上指出。 历经7年', '2022-05-02 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2022.001323', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5443, '报纸', '二〇二一，党史智慧花朵在理论百花园中灼灼绽放', '赵建国; 户华为; 张雁; 曲一琳; 王琎; 张颖天; 赵凡; 冀文亚; 陈恒; 曹建文', '光明日报', '光明日报', '重要论述;“七一”重要讲话;习近平总书记;马克思主义学院;', '以纪念党百年华诞为标志，2021年注定将深深镌刻在中华民族的历史长卷中。 “勿忘昨天的苦难辉煌，无愧今天的使命担当，不负明天的伟大梦想。” 为着这个深切寄望，习近平总书记亲自谋划、亲自部署、亲自推动党史学习教育。在党史学习教育动员大会、庆祝中国共产党成立100周', '2022-04-13 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.001849', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5444, '报纸', '保护好中华民族精神生生不息的根脉', '张毅; 袁新文; 张贺; 王珏', '人民日报', '人民日报', '习近平总书记;文化遗产保护;共产党;中华优秀传统文化;中华文明;人类命运共同体;历史文化遗产;中华民族精神;', '“历史文化遗产承载着中华民族的基因和血脉，不仅属于我们这一代人，也属于子孙万代。要敬畏历史、敬畏文化、敬畏生态，全面保护好历史文化遗产，统筹好旅游发展、特色经营、古城保护，筑牢文物安全底线，守护好前人留给我们的宝贵财富。”今年1月27日，习近平总书记考察调研', '2022-03-20 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.002779', '西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5445, '报纸', '2021年度法学教育十大新闻', '', '全国法学教育十大新闻评选委员会秘书处;', '法治日报', '习近平总书记;法治思想;法学教育;中国政法大学;民法典;', '1 《习近平法治思想概论》出版发行 为推动习近平法治思想进教材进课堂进头脑，由中央宣传部、中国法学会组织编写的马克思主义理论研究和建设工程重点教材《习近平法治思想概论》（以下简称《概论》）一书，已由高等教育出版社出版。 《概论》由“绪论+三编”构成，共20', '2022-01-26 08:00:00', 'https://link.cnki.net/doi/10.28241/n.cnki.nfzrb.2022.000502', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5448, '报纸', '鲲鹏展翅九万里', '赵承; 张旭东; 张晓松; 赵超; 林晖; 朱基钗; 杨依军; 孙少龙', '人民日报', '人民日报', '习近平总书记;中国特色社会主义;人类命运共同体;全面从严治党;', '历史时针指向2022，新年曙光照耀神州大地。 站在新的历史起点上，回望党的十八大以来波澜壮阔的伟大实践，我们无比自豪—— 以习近平同志为核心的党中央，以伟大的历史主动精神、巨大的政治勇气、强烈的责任担当，推动党和国家事业取得历史性成就、发生历史性变革，中', '2022-01-02 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.000002', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5449, '报纸', '具有里程碑意义的一年', '郝思斯', '中国纪检监察报', '中国纪检监察报', '习近平总书记;庄严宣告;中华民族;中国特色社会主义;共产党;中国共产党成立;奋斗目标;', '2021年，是党和国家历史上具有里程碑意义的一年。 中国共产党迎来百年华诞，“两个一百年”历史交汇；“十四五”规划开始实施，全面建设社会主义现代化国家踏上新征程。 一年来，以习近平同志为核心的党中央统筹国内国际两个大局，统筹疫情防控和经济社会发展，统筹发', '2021-12-27 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.005902', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5451, '报纸', '百年初心成大道 万里征程作雄行', '朱基钗; 王子铭; 黄玥; 刘硕; 熊丰', '人民日报', '人民日报', '党史学习;党中央;习近平总书记;基层党员干部;组织生活;教育部;红色基因;红军长征;杨家沟革命旧址;', '“回望过往的奋斗路，眺望前方的奋进路，我们必须把党的历史学习好、总结好，把党的成功经验传承好、发扬好。” 在中国共产党百年华诞的重大历史时刻，以习近平同志为核心的党中央作出战略决策，一次特殊而重要的党内集中教育——党史学习教育今年在全党如火如荼开展，掀', '2021-12-24 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.013530', '西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5452, '报纸', '奋力走好新时代赶考路', '侯颗', '中国纪检监察报', '中国纪检监察报', '全面从严治党;习近平总书记;革命史;中国特色社会主义;奋斗目标;', '党的十九届六中全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》指出，过去一百年，党向人民、向历史交出了一份优异的答卷。现在，党团结带领中国人民又踏上了实现第二个百年奋斗目标新的赶考之路。 这是立足党的百年历史新起点、接续推进中华民族伟', '2021-12-23 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.005830', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5454, '报纸', '党领导下的三联书店：从分散走向联合', '侯俊智', '人民出版社;', '中国新闻出版广电报', '三联书店;读书出版社;黄洛峰;', '就在党的出版事业在艰苦的战争环境中发展壮大的同时，党领导的另外一支重要出版力量，也在国民党统治区逐步壮大。这就是以生活书店、读书出版社、新知书店为代表的进步出版机构。 生活书店于1932年7月成立于上海。前身是邹韬奋主编的《生活》周刊社。邹韬奋任理事长，徐伯', '2021-12-07 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004787', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5455, '报纸', '党领导民营经济发展和工商联工作的重大成就和历史经验', '徐乐江', '中央统战部;全国工商联;', '学习时报', '民营经济发展;工商业者;工商联工作;', '党领导民营经济发展和工商联工作的历史是党的百年探索奋斗史的重要组成部分。我国民营经济的发展，是在党的领导下开辟出来的一条道路，也是中国特色社会主义筚路蓝缕开出的一条路。我们党成立以来，坚持把马克思主义基本原理同中国具体实际相结合，在领导民营经济发展和工商', '2021-12-06 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002302', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5456, '报纸', '“赶考答卷”中的深谋远虑', '王树理', '全国政协;', '人民政协报', '中共中央;毛泽东;共产党人;民主人士;', '“解放区的天是明朗的天，解放区的人民好喜欢，民主政府爱人民呀，共产党的恩情说不完。”在西柏坡群众脍炙人口的秧歌小调和欢快的舞步中，中国共产党的五大书记和中央机关即将向北京转移。作为正式进入京城之前的“打尖”或者“歇脚”之地，香山成了这个大党进京赶考的第一', '2021-12-06 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.009215', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5458, '报纸', '继续发扬彻底的革命精神', '李佑新', '湘潭大学毛泽东思想研究中心;', '中国民族报', '革命精神;中华民族;共产党人;精神丰碑;', '革命精神是党和国家的宝贵财富，伴随共产党人的奋斗征程，在时间的坐标上形成了精神长河。在中国共产党带领中国人民实现中华民族伟大复兴的百年奋斗历史进程中，无数先烈和英雄模范用生命和鲜血铸就了一系列伟大精神，诸如井冈山精神、长征精神、遵义会议精神、延安精神、西', '2021-11-30 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.001230', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5459, '报纸', '无愧时代，以更加昂扬的姿态奋进新征程', '肖春飞; 吴振东; 郭敬丹; 程迪; 郑昕; 闫起磊', '新华社;', '新华每日电讯', '中共一大会址;井冈山市;上海自贸区;奋斗目标;六中全会;参观者;习近平总书记;', '历史，是最好的教科书。 党的十九届六中全会是在重要历史关头召开的一次具有重大历史意义的会议，全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》，是新时代中国共产党人牢记初心使命、坚持和发展中国特色社会主义的政治宣言。 连日来，中国大地', '2021-11-19 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008905', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5460, '报纸', '践行太行精神 造福老区人民', '陈聪; 郭晓东; 李安民; 王麟', '金融时报', '金融时报', '太行精神;红色旅游;黎城县;太行山;新型农业经营主体;武乡县;《金融时报》;长治市;', '“红日照遍了东方， 自由之神在纵情歌唱! 看吧! 千山万壑， 铜壁铁墙! 抗日的烽火，燃烧在太行山上……” 这首《在太行山上》创作于1938年7月，是为在山西境内浴血奋战、抗击日本侵略者的抗日军民而创作的一首歌曲，描绘了太行山中游击健儿们的战斗生活和', '2021-11-17 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.006023', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5462, '报纸', '血肉相连 生死相依', '俞海萍; 耿建扩; 胡晓军; 杨珏; 赵秋丽', '光明日报', '光明日报', '共产党;求真务实;生死相依;习近平总书记;游击战;大柏地战斗;中国共产党历史;', '2021年6月28日晚，国家体育场，庆祝中国共产党成立100周年文艺演出盛大举行。第一篇章“浴火前行”中，情景舞蹈《起义 起义》、戏剧与舞蹈《长征》、情景大合唱《怒吼吧 黄河》等节目，生动演绎了一幕幕发生在红色革命老区的故事，将观众拉回到大革命的硝烟之中、艰险的长征', '2021-11-10 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005700', '西柏坡_screened,抗日战争1_screened,遵义会议_screened,四渡赤水_screened,会宁_screened,土地革命战争_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (5463, '报纸', '总书记心中的“国之大者”', '杜尚泽; 邝西曦; 林小溪', '人民日报', '人民日报', '习近平总书记;中国共产党人;', '历史的维度，铸就了格局的宏阔。 人心的向背，定义了最大的政治。 百年风云，变了人间。不变的是信仰的追寻，是初心的坚守。 在上海中共一大会址、在浙江嘉兴南湖红船，在陕北榆林杨家沟的窑洞，在戈壁滩蘑菇云腾空而起的欢呼声里，在“绿水青山就是金山银山”的声', '2021-11-09 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011730', '西柏坡_screened,将台堡_screened,陈树湘_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5464, '报纸', '星火点亮东方红', '杨悦; 郭冬明', '解放军报', '解放军报', '共产党人;红军长征;中华苏维埃共和国;人民军队;东方红;', '1927年10月，红色的星火落在井冈山旷野。毛泽东引兵抵达井冈山茨坪，建立起中国共产党第一个农村革命根据地。 从1927到1949，20多年的崎岖征程，伴着共产党人艰苦跋涉的足迹，红色火光照亮了瑞金、延安，映红了太行、沂蒙，沿着西柏坡的“赶考”路漫出了山村田野，在天安', '2021-11-08 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007007', '西柏坡_screened,抗日战争3_screened,红井_screened,叶坪_screened,方志敏_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened,茨坪_screened');
INSERT INTO `ds_article` VALUES (5465, '报纸', '蒙山沂水 精神绵长', '赵秋丽; 冯帆', '光明日报', '光明日报', '沂蒙精神;厉家寨;大樱桃;', '“都有自己的爹，都有自己的娘，省下最后一口粮，为了前方。都有自己的儿，都有自己的女，送上最后亲骨肉，血洒战场!”10月13日晚，民族歌剧《沂蒙山》作为第四届中国歌剧节的开幕演出，反响热烈。 民族歌剧《沂蒙山》是根据抗日战争时期沂蒙山革命根据地发展壮大的真实历', '2021-11-08 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005659', '西柏坡_screened,抗日战争1_screened');
INSERT INTO `ds_article` VALUES (5466, '报纸', '彪炳史册的伟大成就，坚如磐石的中流砥柱', '', '人民日报', '人民日报', '中国共产党人;中华民族;中国特色社会主义;习近平总书记;伟大成就;民族复兴;党中央;马克思主义基本原理;人类命运共同体;', '本报北京11月6日电 新华社6日播发署名钟华论的文章《彪炳史册的伟大成就，坚如磐石的中流砥柱》，全文如下： 青史如镜，鉴照峥嵘岁月；初心如炬，辉映复兴之路。 在实现中华民族伟大复兴的关键时期，在“两个一百年”奋斗目标历史交汇点上，即将召开的中国共产党第十九', '2021-11-07 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011689', '西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5468, '报纸', '让沂蒙精神在新时代发扬光大', '赵成', '人民日报', '人民日报', '沂蒙精神;新时代;根据地;临沂市;', '沂蒙精神与延安精神、井冈山精神、西柏坡精神一样，是党和国家的宝贵精神财富，要不断结合新的时代条件发扬光大。 军民水乳交融、生死与共铸就的沂蒙精神，对我们今天抓党的建设仍然具有十分重要的启示作用。 ——摘自习近平总书记2013年11月在山东考察时的重要讲话', '2021-11-04 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011559', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5469, '报纸', '为实现中华民族伟大复兴凝聚更为主动的精神力量', '', '中共文化和旅游部党组理论学习中心组;', '人民日报', '中华民族伟大复兴;马克思主义基本原理;中国具体实际;伟大成就;精神力量;习近平总书记;中国特色社会主义道路;', '习近平总书记指出：“一个民族的复兴需要强大的物质力量，也需要强大的精神力量。”中国共产党团结带领中国人民创造了新时代中国特色社会主义的伟大成就，为实现中华民族伟大复兴提供了更为主动的精神力量。习近平总书记的重要讲话坚持马克思主义唯物史观，深刻阐明了伟大成', '2021-11-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011622', '西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5470, '报纸', '以新华之名', '刘菁; 李亚彪; 杨玉华; 张紫赟; 刘美子; 陈诺; 水金辰', '新华每日电讯', '新华每日电讯', '新华社;红中社;《红色中华》;吴文焘;不列颠尼亚;北京电影学院;人民战争;', '历史是昨天的新闻，新闻是明天的历史。 翻开新华社新闻“档案库”，仿佛穿越时空，一篇篇文章、一幅幅图片，把风起云涌、波澜壮阔的时代画卷展现在人们面前。 90年来，新华社始终坚持党指引的方向，与人民同呼吸、与时代共进步。一代代新华人前赴后继、薪火相传，燃烧', '2021-10-29 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008344', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5472, '报纸', '关于长征和长征精神，习近平这样说', '李贞', '人民日报海外版', '人民日报海外版', '长征精神;习近平;红军长征;', '今年10月22日是长征胜利85周年纪念日。85年前，中国共产党领导中国工农红军战胜千难万险，胜利完成举世闻名的二万五千里长征。“红军不怕远征难，万水千山只等闲。”这一伟大壮举，充分展现了革命理想的伟大精神力量，永远铭刻在中国革命和中华民族的史册上。一代人有一代人', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.003206', '西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5479, '报纸', '坚定理想信念 让红岩精神永放光芒', '青平', '中国青年报', '中国青年报', '红岩精神;解放战争;共产党人;国统区;抗日民族统一战线;南方局;理想信念;', '20世纪30年代，嘉陵江畔的红岩嘴山谷，有一处开垦不久的花果农场。1939年秋，面对日寇轰炸的威胁，年初成立于重庆市区的中共南方局在农场主人、爱国知识妇女饶国模的支持下搬迁至此，“红岩”之名从此与中国革命紧密相连。 红岩精神是中国共产党在国民党统治地区革命实践', '2021-10-19 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.003773', '西柏坡_screened,白公馆_screened,渣滓洞_screened,狱中八条_screened');
INSERT INTO `ds_article` VALUES (5480, '报纸', '信一辈子 守一辈子', '乐兵', '中国纪检监察报', '中国纪检监察报', '理想信念;', '烈火焚身仍岿然不动的邱少云，“永不消逝的电波”的原型李白，刑场上高呼“中国共产党万岁”的恽代英……近日，第二届全国红色故事讲解员大赛正如火如荼举行，一个个感染人、教育人的红色故事，再次将大家带回到过往的峥嵘岁月中，接受一场革命精神的洗礼。革命先烈这种舍生', '2021-10-19 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.004907', '西柏坡_screened,贺页朵_screened');
INSERT INTO `ds_article` VALUES (5481, '报纸', '激昂旋律颂红旗', '朱婷', '人民政协报', '人民政协报', '《红旗颂》;吕其明;', '“有五星红旗的地方，就有信念的灯塔，如果信念有颜色，那一定是中国红。”9月25日晚，中国公民孟晚舟在经历了近三年的非法拘押后回到祖国，面对挥舞着红旗迎接的人群，她的感言让无数国人为之动容。 红旗，引领中国人前进的精神标识。自20世纪60年代诞生以来，交响乐《红', '2021-09-28 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.007699', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5482, '报纸', '伟大建党精神与伟大民族精神', '杨子强', '中国人民大学习近平新时代中国特色社会主义思想研究院;', '学习时报', '共产党人;中华民族;马克思主义基本原理;中国共产党;精神谱系;', '伟大的事业需要崇高的精神，崇高的精神支撑伟大的事业。精神是一个党、一个国家、一个民族赖以生存的灵魂，唯有精神上达到一定的高度，这个党、这个国家、这个民族才能在历史的洪流中屹立不倒、奋勇向前。习近平总书记在庆祝中国共产党成立100周年大会上提出了“坚持真理、坚', '2021-09-20 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001741', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5484, '报纸', '周建人的爱国民主活动', '戴海荣', '民进中央宣传部;', '人民政协报', '周建人;马叙伦;爱国民主;瞿秋白;', '周建人是民进创始人之一，他的一生，始终与中国共产党的事业伴随在一起。 追随长兄 参与爱国民主活动 1888年11月12日，周建人出生于浙江绍兴周家新台门，两位兄长周树人（鲁迅）和周作人在中国新文学发展史上享有盛名。 周建人一直抱憾两件事：一是他没有赶上绍兴府', '2021-09-02 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.007119', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5485, '报纸', '坚守红色通信百年初心 续写网络强国建设伟业', '周景耀', '河北省通信管理局;', '人民邮电', '习近平总书记;鲁班石;时代定位;信息通信;电信普遍服务;', '2021年是中国共产党成立100周年。从“小小红船”到“巍巍巨轮”，我们党百年光辉历程，创造了世界瞩目的丰功伟绩。党的红色通信发展史作为百年党史的生动缩影，蕴含着丰富的革命传统和精神滋养。我们始终坚持以习近平新时代中国特色社会主义思想为指导，深入学习贯彻习近平总', '2021-08-31 08:00:00', 'https://link.cnki.net/doi/10.28659/n.cnki.nrmyd.2021.002856', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5487, '报纸', '“洪湖水”何以“浪打浪”六十多年', '瞿祥涛', '中国文化报', '中国文化报', '《洪湖赤卫队》;湖北省;浪打浪;洪湖赤卫队;久演不衰;', '“洪湖水呀浪呀嘛浪打浪啊，洪湖岸边是呀嘛是家乡啊……” 伴随着经典的旋律，湖北省歌剧舞剧院携红色经典歌剧《洪湖赤卫队》，于今年5月7日在“洪湖赤卫队”诞生地湖北省洪湖市开启全国巡演，此后陆续走进了嘉兴南湖、西柏坡、延安等革命圣地。每次演出谢幕时，台下掌声', '2021-08-24 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.002605', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5490, '报纸', '新时代“延安整风”的检察“答卷A”', '姜洪', '检察日报', '检察日报', '政法队伍;教育整顿;延安整风;', '2021年是个不平凡的年份。在举国欢庆中国共产党成立100周年的同时，全国政法队伍以刀刃向内的勇气进行自我革命。触灵魂、见真章、祛痼疾、建铁军……从2021年2月起，一场被称为新时代“延安整风”的全国政法队伍教育整顿分两批开展，市县级政法机关作为第一批首先进行。 5', '2021-08-13 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.004053', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5492, '报纸', '团结就是力量', '王一婷; 耿鹏宇', '解放军报', '解放军报', '北庄村;', '一首歌，为人们所广泛熟知，在中华大地传唱已78年。 “团结就是力量，团结就是力量。这力量是铁，这力量是钢……”铿锵的音符，激越的歌声，一次又一次响彻在武警平山中队，回荡在西柏坡的苍松翠柏间，成为人们心潮逐浪、团结奋斗的精神力量。 2021年7月，记者跟随中队', '2021-08-05 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.005000', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5493, '报纸', '石西民：中国新闻工作的践行者', '何金海', '浙江省浦江县政协;', '人民政协报', '石西民;践行者;周恩来;新闻工作;游行队伍;国民党;新华日报;', '1935年12月25日，上海市各界举行大规模的抗日爱国游行，声援北平“一二·九”爱国学生运动。指挥这次示威行动的负责人因被英国巡捕包围而不能按时赶到现场，眼看游行队伍要失控。这时，从游行队伍里走出一个中等身材、神情坚毅的青年，带领队伍向目的地进发……这位处变不惊', '2021-08-05 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.006359', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5494, '报纸', '必须进行具有许多新的历史特点的伟大斗争', '刘开雄', '新华每日电讯', '新华每日电讯', '历史特点;中国共产党;习近平总书记;', '新华社北京8月2日(记者刘开雄)在庆祝中国共产党成立100周年大会上，习近平总书记指出：“以史为鉴、开创未来，必须进行具有许多新的历史特点的伟大斗争。” 百年来，中国共产党带领中国人民斗争不息，斗争精神贯穿于中国革命、建设、改革各个时期。 今天，我们比以往任', '2021-08-03 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005891', '西柏坡_screened,狼牙山_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (5495, '报纸', '解放区的天是明朗的天', '白杨; 胡京春', '人民政协报', '人民政协报', '民主人士;哈尔滨;新政协筹备会;解放区;中共中央东北局;谭平山;政治协商会议;共产党人;人民团体;', '“马迭尔宾馆有着强大的‘磁场’。无论春夏秋冬，门口总是聚集着大批慕名而来的游客……”黑龙江省政协委员、土生土长的哈尔滨人欣莉走在中央大街的面包砖上，向记者介绍着。 其实，七十多年前，哈尔滨作为全国最早解放的大城市，“磁场”更是超乎想象，这里明朗的天空吸', '2021-07-21 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005851', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5496, '报纸', '“大决战”时期的“大统战”', '高新国', '人民政协报', '人民政协报', '大统战;民主人士;民主党派;统战部;李家庄;大决战;', '在中国的版图上，“李家庄”比比皆是，而位于河北省石家庄市平山县岗南镇的李家庄，因与“统战”结缘与众不同。这里见证了各民主党派的历史选择，记录了新政协筹备过程，孕育了中国共产党领导的多党合作和政治协商制度。“新中国统一战线从这里走来”，投射在李家庄中共中央', '2021-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICrdP9hEz_U_rrvPWPjmDwKSiBQz67pDl183HYwQn19ouTin9GLZnF88SREq_DgWa0l-ha_ellb-WOTGDqv8aLNMujQBpH0VN028uwNYr90hXRT6OIvA_tI7Qw-l5NWnSADGg3Umu81Iw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5498, '报纸', '“解放全中国”：伟大口号从陕北喊过长江声震全中国', '贺占军; 姜辰蓉; 孙正好; 李浩; 邵瑞', '新华每日电讯', '新华每日电讯', '毛泽东;', '“打倒蒋介石，解放全中国!”1947年，中国命运的十字路口，转战陕北途中的党中央和毛主席发出战斗号召。 从黄土沟壑中飞出的口号，道出了全国人民的心声，激励着军民斗志。一时间，“四海翻腾云水怒，五洲震荡风雷激”。 军歌嘹亮，冲锋，冲锋!这响亮的口号伴随人民解', '2021-07-16 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005489', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5500, '报纸', '而今迈步从头越', '霍小光; 张晓松; 朱基钗; 黄玥; 孙少龙', '新华社;', '人民日报', '习近平总书记;中国共产党历史;展览馆;中国共产党成立;奋斗目标;党史学习;人民万岁;共产党人;', '这一刻，浓缩百年奋斗历程。 这一刻，铺展复兴光明前景。 公元2021年7月1日，既是时间的刻度，更是奋斗的标尺。 万众瞩目，中国共产党人将以什么样的精神状态和奋斗实绩，庆祝这一伟大时刻的到来？ 世纪考题，需要在新时代中国共产党人手上交出答卷。 “历史', '2021-07-15 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007376', '西柏坡_screened,遵义会议_screened,遵义会议_screened,遵义会议_screened,四渡赤水_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (5501, '报纸', '薪火相传的红色精神', '郑海鸥; 张贺', '人民日报', '人民日报', '红色精神;精神谱系;红军长征;中国人民志愿军;革命英雄主义精神;抗美援朝精神;革命理想;中国共产党历史;攻坚克难;共产党人;中华民族;薪火相传;', '宏伟的中国共产党历史展览馆西侧广场上，名为《旗帜》《信仰》《伟业》《攻坚》《追梦》的五组雕塑庄严矗立，气势恢宏。参观者纷纷合影留念，“鲜红的党旗是血染的风采，是无数革命先烈用鲜血换来的！” 习近平总书记在庆祝中国共产党成立100周年大会上指出：“一百年来，', '2021-07-13 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.007184', '西柏坡_screened,强渡大渡河_screened,遵义会议_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (5502, '报纸', '共产党人的精神，在舞台上闪耀', '罗群', '中国文化报', '中国文化报', '共产党人;', '经过战火与硝烟的洗礼，成就历史与人民的选择，中国共产党今年迎来百年华诞。中国共产党在长期的奋斗中，形成了井冈山精神、长征精神、遵义会议精神、延安精神、西柏坡精神、红岩精神、抗美援朝精神、“两弹一星”精神、特区精神、抗洪精神、抗震救灾精神、抗疫精神、脱贫攻', '2021-07-08 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.002135', '西柏坡_screened,遵义会议_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (5503, '报纸', '一部改变旧中国土地关系的纲领性文献', '董丽; 刘斌', '中国财经报', '中国财经报', '共产党;中共中央;《中国土地法大纲》;土地制度改革;旧中国;土地改革;纲领性文献;中国土地法大纲;', '在中国历史上，土地一直是最重要的生产资料，也是农民最基本的生活保障，土地占有和分配情况对经济发展乃至政权更替都有很大影响，其重要性不言而喻。进入新民主主义革命时期，土地问题成为中国革命的核心问题。众所周知，大革命失败后的第二次国内革命战争之所以又称为土地', '2021-07-08 08:00:00', 'https://link.cnki.net/doi/10.28053/n.cnki.nccjb.2021.001678', '西柏坡_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (5504, '报纸', '碾庄之战，一场齐心协力的合围', '贺逸舒; 王戈; 李政; 蒋雨铖', '战地记者队;', '解放军报', '庄之战;淮海战役;黄百韬兵团;碾庄镇;', '访谈专家：徐飞 1948年11月17日，美国《太平洋邮报》记者罗文在飞机上拍下这样一张照片—— 辽阔的大地上，战火弥漫，硝烟四起。历史在这一刻，选择了这个名叫碾庄圩的江淮小镇。 这是一场“小推车推出来的胜利”。73年前的淮海战役，我军在广大人民群众的支持下，', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004280', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5505, '报纸', '让历史照亮前行之路', '刘建伟; 彭兵根; 祝光强; 孙禹', '中国国防报', '中国国防报', '党史学习;军分区;国防动员;人武部;', '欲知大道，必先为史。习主席在党史学习教育动员大会上强调，了解历史才能看得远，理解历史才能走得远。 如何推动党史学习教育入脑入心、见行见效，防止学习和工作“两张皮”？盛夏时节，记者踏访多家国防动员单位发现，他们坚持把党史学习教育作为当前一项重要政治任务，', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.28072/n.cnki.ncgfb.2021.001479', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5507, '报纸', '实现中华民族伟大复兴中国梦的关键一步', '汪晓东; 张炜; 王玉琳', '人民日报', '人民日报', '中华民族伟大复兴;奋斗目标;十八届五中全会;中共中央政治局;习近平总书记;全面建成小康社会;中国梦;', '今年7月1日，北京天安门广场，庆祝中国共产党成立100周年大会在这里隆重举行。 习近平总书记发表重要讲话，代表党和人民庄严宣告—— 经过全党全国各族人民持续奋斗，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会，历史性地解决了绝对贫困问题，正在', '2021-07-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006869', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5508, '报纸', '历史交汇点上的庄严宣告', '赵承; 霍小光; 邹伟; 韩洁; 林晖; 朱基钗; 高敬; 丁小溪', '新华社;', '新华每日电讯', '天安门广场;中华民族;中国共产党;天安门城楼;庄严宣告;习近平总书记;人民万岁;', '历史，立下又一座丰碑—— 2021年7月1日，中国共产党百年华诞，天安门广场见证历史性盛典。习近平总书记代表党和人民庄严宣告： “经过全党全国各族人民持续奋斗，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会”! 百年砥砺，几多沧桑。千年梦想，', '2021-07-03 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005176', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5510, '报纸', '起点', '张国; 陈卓', '中青报;中青网;', '中国青年报', '李汉俊;陈独秀;陈公博;俞秀松;李大钊;', '后来的事情，尽人皆知：58人里的13人，秘密开了一次会，那被认为是一个政党的起点。 会议开得悄无声息，所有原始记录都散失了，而且找不到任何新闻可以佐证。多年之后，这些人连开会日期都说法不一。不过，与会者陈公博的日记里记载了1921年7月31日他隔壁房间的一起枪杀案', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.002503', '西柏坡_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5511, '报纸', '“琉璃人赶上了一个好时代”', '解磊', '消费日报', '消费日报', '琉璃艺术;', '在山东省淄博市博山区，有位钟情于“鸡油黄”琉璃的轻工“大国工匠”，让“鸡油黄”重现往日的辉煌。他是孙云毅，几十年如一日潜心研究琉璃历史文化及琉璃制作技艺，用自己的坚持和精益求精研制出的“鸡油黄”。他的作品已经成为博山琉璃艺术的标志性产物，孙云毅和他的团队', '2021-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAAph4_c1qHRoqv5ki9EwrQGeNvderZ7BQmBgkL2Cm4ceu1ALtg-2_EXp9Nz6pNSZcjyq7oh_gcGPwl_AvjppQXYSFLSQRI4hfupmkAEjYA1XnbsFwb0vh714jdjzGakh-1ubGA4TIBgA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5512, '报纸', '护航千秋伟业 谱写法治华章', '', '人民法院报', '人民法院报', '人民法院;司法案件;全面从严治党;司法责任制;立案登记制;马锡五审判方式;巡回法庭;中华苏维埃共和国;千秋伟业;', '斧头劈开新世界，镰刀割断旧乾坤。 1921年，中国共产党成立，这是开天辟地的大事变。 这一历史大事变，深刻改变了近代以后中华民族发展的方向和进程，深刻改变了中国人民和中华民族的前途和命运，深刻改变了世界发展的趋势和格局。 100年来，风雨兼程，我们党团结带', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.002954', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5514, '报纸', '北京：进京“赶考”书写红色司法新答卷', '王贺', '人民法院报', '人民法院报', '北平市;人民法院;巡回审判;北京市;精神赔偿;', '六月的北京，耀眼的阳光在长安街上洒下一地金黄。天安门广场西侧，巍峨的人民大会堂静静矗立，见证着新中国法治建设的巨变沧桑。 然而许多人不知道的是，现在人民大会堂所在地曾有一条司法部街。自清宣统二年（1910年）在此地建造大理院衙署起，这里就是司法审判机构的聚', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003050', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5515, '报纸', '风展红旗如画', '李昌林; 李刚; 王传宗; 付静; 郭坤泽; 谢俊思', '人民公安报', '人民公安报', '公安队伍;人民公安;从严治警;中国共产党;政治建警;公安机关;习近平总书记;人民警察;执法办案;公安部;“枫桥经验”;红旗如画;', '（一）“我们对于时间的理解，不是以十年、百年为计，而是以百年、千年为计。”100年，对于一个立志开创千秋伟业的政党，“如朝日，如百卉之萌动”，正是风华正茂。 100年前的那个夏日，十多位身着长衫、中山装、西装的热血志士，怀着对马克思主义的信仰，从四面八方聚集', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.003671', '西柏坡_screened,抗日战争1_screened,红四军_screened,瑞金_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (5516, '报纸', '在党的旗帜下奋斗强军', '欧灿; 费士廷; 钱宗阳', '解放军报', '解放军报', '人民军队;党中央;习近平总书记;党对军队绝对领导;全军官兵;中央军委;政治建军;中国共产党领导;改革开放新时期;', '百年光辉历程，百年历史见证。世界上从来没有一支军队的命运与一个政党如此紧密相连—— 100年前的那个夏天，中国共产党登上历史舞台。犹如擎起的一把熊熊火炬，给近代饱受战乱、灾难深重的中国人民送来了光明和希望。自那时起，我们党义无反顾肩负起为中国人民谋幸福、为', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004139', '西柏坡_screened,遵义会议_screened,三湾改编_screened,三湾改编_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (5517, '报纸', '当家作主', '郝思斯', '中国纪检监察报', '中国纪检监察报', '中国共产党领导;民族区域自治制度;人民代表大会制度;人民当家作主;习近平总书记;多党合作和政治协商制度;人民民主专政;党和政府;为人民服务;', '5月13日，习近平总书记在河南省南阳市考察调研时指出，“我们党的百年奋斗史就是为人民谋幸福的历史。人民就是江山。我们共产党打江山、守江山，都是为了人民幸福，守的是人民的心。” 成为自己命运的主人，这是中国人民多少岁月以来梦寐以求的理想。建立一个人民当家作主', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003147', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5519, '报纸', '理想之火', '张琰', '中国纪检监察报', '中国纪检监察报', '共产党人;理想信念;革命理想;中国共产党;', '革命理想高于天。一百年来，理想信念如火炬，如灯塔，照亮我们党从小到大、由弱到强的奋斗历程。 对共产主义的信仰，对中国特色社会主义的信念，是共产党人的政治灵魂，是共产党人经受住任何考验的精神支柱。回顾党的历史，为什么我们党在那么弱小的情况下能够逐步发展壮', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003149', '西柏坡_screened,遵义会议_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (5521, '报纸', '发扬红色传统 赓续精神血脉', '王召杰', '人民铁道', '人民铁道', '红色基因;主题宣传;群众性;旅游列车;铁路局;精神血脉;', '“几经风雨更懂得，跟着共产党才有新中国……”6月10日晚，一曲齐声高唱的《在灿烂的阳光下》拉开了“中国梦·铁路情·劳动美”全国铁路职工庆祝建党100周年第二届职工艺术节优秀作品展示暨慰问活动的序幕。 《中国铁路全图》、林祥谦烈士怀表、杨连第大桥桥墩铁夹板等铁', '2021-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICJnA3cO_dn8SHGkp4n7_RfRGnwNVNEzCrpnLnYBFHFnJrASNg3xZlKLUA5uqjlh2ZLc1pCcMfWcXTFXeF_skKhPQOAEBzqySH0YQy-i-kPR8PeF5WwkIMS_EeAUTiipU8Trpob-sft1Q==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5523, '报纸', '煌煌伟业开新纪 熠熠光辉照远程', '吴姝静', '团结报', '团结报', '中国共产党领导;井冈山;周铁农;', '100年的理论和实践证明，中国共产党能带领中国人民取得巨大成功绝非偶然，她的身上有着一系列的优秀特质值得世人赞颂和学习。经过长期与中国共产党合作共事，民主党派领导人如何看待中国共产党？对身边的共产党员又作何评价？在庆祝中国共产党百年华诞之际，全国人大常委会原', '2021-06-29 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001308', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5524, '报纸', '引领中华民族走向伟大复兴的百年', '李志伟; 肖静芳; 牛锐; 张国欣', '中国民族报', '中国民族报', '中华民族;共产党人;伟大复兴;民族独立;中国共产党;习近平总书记;人民幸福;', '让我们穿越百年来的历史烟云，放眼中华民族5000多年的文明发展史，近代以来争取民族独立和人民解放、实现国家富强和人民幸福的奋斗史，去回溯、去思考—— 100年，中国共产党团结带领各族人民走过的苦难与辉煌，带给中华民族的光荣和梦想。 胜利完成了近代以来争取民族', '2021-06-29 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2021.000670', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5528, '报纸', '我们党的百年奋斗史就是为人民谋幸福的历史', '', '光明日报', '光明日报', '中华民族;中国共产党;习近平总书记;中国特色社会主义;奋斗史;', '一百年前，一群播火者在上海石库门钻燧取火，以马克思主义真理之光照亮了中国人民谋幸福的前进道路。 一百年前，一艘满载中国人民幸福和希望的小小红船，从浙江嘉兴南湖起航，越过急流险滩，穿过惊涛骇浪，成为今天劈波斩浪、行稳致远的巍巍巨轮。 百年征程波澜壮阔，', '2021-06-25 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003220', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5529, '报纸', '百年征程路 初心映江山', '', '新华社;', '新华每日电讯', '习近平总书记;全面从严治党;人民至上;共产党人;', '兴起于暗夜的星星之火，绽出万丈霞光。劈开混沌的一叶红船，驶向光明未来。 历史在惊叹，历经血与火的洗礼，为什么这个马克思主义政党可以由弱到强、蓬勃不息？ 世界仍在探询，直面生与死的考验，为什么中国共产党总能续写不懈奋斗的时代传奇？ 新时代中国共产党人', '2021-06-25 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005086', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5530, '报纸', '坚守初心的为民本色', '齐中熙; 安蓓; 樊曦', '新华社;', '新华每日电讯', '习近平总书记;中国共产党人;谷文昌;千秋伟业;共同富裕;移民村;', '“从石库门到天安门，从兴业路到复兴路，我们党近百年来所付出的一切努力、进行的一切斗争、作出的一切牺牲，都是为了人民幸福和民族复兴。” 回首奋斗路，中国共产党来自人民、植根人民，为人民而生，因人民而兴；奋进新征程，中国共产党始终同人民在一起，凝聚起实现中', '2021-06-25 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005094', '西柏坡_screened,枣园_screened');
INSERT INTO `ds_article` VALUES (5532, '报纸', '大智慧，中国道路开天辟地', '仲农平', '农民日报', '农民日报', '农民运动讲习所;共产党人;社会主义;', '一切历史都是当代史。 只有站在现实的维度，从当下出发，回望历史的长河，我们才能真正明白这100年的价值和创造，这100年的改变和重塑，这100年血水泪水汗水写就的功勋和智慧。 从石库门到天安门，从兴业路到复兴路……我们党从最初的几十个人发展成为拥有9100多万名党', '2021-06-23 08:00:00', 'https://link.cnki.net/doi/10.28603/n.cnki.nnmrb.2021.002940', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5534, '报纸', '无党派人士“一心跟党走”的闪光足迹', '张连起', '全国政协;', '人民政协报', '无党派人士;民主人士;毛泽东;郭沫若;符定一;人民民主统一战线;', '无党派人士是我国政治制度中特有的政治概念，是中国共产党领导的多党合作和政治协商制度的重要组成部分，是人民政协的组成界别，在中国革命、建设、改革、复兴的各个历史时期都发挥了重要作用。无党派人士的称谓和实质经历了时代的变迁，从民主革命时期的社会贤达到新中国成', '2021-06-02 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.004492', '西柏坡_screened,抗日战争1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5535, '报纸', '珍贵的照片 党史的佳话', '宋振峰', '人民政协报', '人民政协报', '中国共产党领导;邓宝珊;傅作义;毛泽东;中国人民解放军总部;', '春日，走进第九、十届全国政协常委、原文史和学习委员会副主任邓成城先生的家中，我们见到了一张弥足珍贵的照片。这张照片穿越奔腾不息的历史长河，向我们讲述着中国共产党统一战线的一段佳话…… 他们在西柏坡刚见过 照片中，毛泽东主席一只手拉着邓宝珊将军的手，一', '2021-05-27 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.004335', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5536, '报纸', '牢记初心使命团结拼搏奋斗 凝心聚力建设经济强省美丽河北', '王东峰', '河北省委;', '人民日报', '习近平总书记;经济强省;凝心聚力;', '今年是中国共产党成立100周年。在波澜壮阔的历史进程中，我们党团结带领人民创造了一个又一个人间奇迹。河北是革命的土地、英雄的土地，是“新中国从这里走来”的地方，河北人民始终坚定不移听党话、跟党走，燕赵大地生机盎然。 党的十八大以来，习近平总书记8次考察河北', '2021-05-08 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.004779', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5537, '报纸', '从沂蒙精神中汲取奋进力量', '魏勇', '山东临沂市委组织部;', '中国组织人事报', '沂蒙精神;', '党的历史是最生动、最有说服力的教科书。临沂是全国著名的革命老区，也是沂蒙精神的主要发源地。2013年11月，习近平总书记视察临沂时指出，军民“水乳交融、生死与共”铸就的沂蒙精神，与延安精神、井冈山精神、西柏坡精神一样，是党和国家的宝贵精神财富。今年是中国共产党', '2021-04-30 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.001525', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5538, '报纸', '人民币从这里走来', '崔仁斌; 李彬', '中国银行旧址纪念馆暨河北钱币博物馆;', '中国银行保险报', '华北财经会议;办事处;货币兑换;解放区;中国人民银行;冶陶镇;董必武;东北局;', '中央高度关注“货币不统一” 根据毛泽东主席和中共中央的战略部署，刘邓千里跃进大别山。1947年6月底，刘伯承、邓小平率晋冀鲁豫野战军主力进入鲁西南，向国统区展开大规模进攻，揭开了人民解放军战略进攻的序幕。 由于战争规模的扩大，军费开支急剧增加，财粮供应数量', '2021-04-23 08:00:00', 'https://link.cnki.net/doi/10.28049/n.cnki.ncbxb.2021.001452', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5539, '报纸', '任弼时的红色家风与崇高品格', '张保军', '湘潭大学马克思主义学院;', '团结报', '任弼时;新中国成立;工作人员;崇高品格;', '红色家风，是中国共产党人在长期的革命和建设实践中形成的家庭风尚，是红色足迹、红色文化、红色精神的重要组成部分。任弼时同志非常重视家风建设，身体力行，严格要求亲属和身边的工作人员，对红色家风的形成与发扬，增添了厚重的积淀。本文选取任弼时同志带头践行廉洁奉公', '2021-04-22 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.000866', '西柏坡_screened,抗日战争1_screened');
INSERT INTO `ds_article` VALUES (5541, '报纸', '各地争建红色堡垒', '黄明明', '中国银行保险报', '中国银行保险报', '党史学习;习近平总书记;基层党组织;自选动作;', '今年，在全党开展党史学习教育，是以习近平同志为核心的党中央立足党的百年历史新起点，统筹中华民族伟大复兴战略全局和世界百年未有之大变局，为动员全党全国满怀信心投身全面建设社会主义现代化国家而作出的重大决策。习近平总书记在党史学习教育动员大会上发表的重要讲话', '2021-04-14 08:00:00', 'https://link.cnki.net/doi/10.28049/n.cnki.ncbxb.2021.001313', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5542, '报纸', '西柏坡时期中央妇委会：掀开中国妇女运动新篇章', '周丽婷; 孙浩翔; 付玉涓', '中国妇女报;中华女子学院;', '中国妇女报', '西柏坡;邓颖超;妇女运动;妇委会;解放区妇女工作会议;第一次全国代表大会;', '如果没人介绍，东柏坡村柏坡湖边上的那处农家小院，不会引人注目。 然而，这个小院里，曾“风云激荡”，妇女运动在这里绽放出新的华章。 这里是中央妇委会旧址所在地。 从1948年5月到1949年3月，不到一年的时间里，蔡畅、邓颖超、康克清等老一辈妇女运动先驱领导中', '2021-04-13 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.001118', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5543, '报纸', '发挥好红色基因库在党史学习教育中的独特作用', '李曼青', '学习时报', '学习时报', '党史学习;红色基因;烈士陵园;独特作用;', '全党开展党史学习教育已经有一段时间,各地方各部门通过多种形式、运用多种手段、组织多种活动,不断推动党史学习教育走深走实。尤其是在刚刚过去的清明假期,纪念馆、烈士陵园等成为开展党史学习教育的热门地点。例如,“清明节近4万人到沈阳抗美援朝烈士陵园祭扫”、“群众自发', '2021-04-09 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.000577', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5544, '报纸', '初心照征程', '曾诗阳', '经济日报', '经济日报', '入党誓词;中共一大会址;', '聚光灯下，200余件展品将故事娓娓道来，凝练展示中国共产党从建党到建立新中国的伟大征程；展墙上，一位位英烈的名字如同一簇簇火苗，让我们看到艰难的过去，也照亮着中国共产党光明的未来。 3月，首都博物馆联合上海市历史博物馆（上海革命历史博物馆）、河北博物院、中', '2021-04-04 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.003026', '西柏坡_screened,抗日战争1_screened,贺页朵_screened');
INSERT INTO `ds_article` VALUES (5545, '报纸', '从“红色档案”中读懂胜利密码', '贾云生', '吉林省和龙市委;组织部;', '中国组织人事报', '红色档案;红船精神;红色基因;红色资源;知行合一;', '党史、新中国史、改革开放史、社会主义发展史记录了党团结带领全国人民百折不挠开创辉煌的不凡历程，而红色档案中记录着诸多鲜为人知的历史细节。近日，央视新闻推出百集微纪录片《红色档案》，通过红色档案展示党的辉煌，用红色档案讲好党史故事，带领我们从一件件红色档案', '2021-03-22 08:00:00', 'https://link.cnki.net/doi/10.28127/n.cnki.ncrsb.2021.000969', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5546, '报纸', '中国抗疫实践体现责任担当', '卢林; 郭树合', '全国人大;山东省立医院;', '检察日报', '党中央;疫情防控;新型冠状病毒;习近平;责任担当;', '“在以习近平同志为核心的党中央坚强领导下，中华儿女风雨同舟、守望相助，筑起了抗击疫情的巍峨长城。我们要坚持科学谨慎的态度，总结中国抗疫经验、讲好中国抗疫故事、宣传中国抗疫精神。” 2020年新冠肺炎疫情，是新中国成立以来我国遭遇的传播速度最快、感染范围最广', '2020-12-28 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2020.006097', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5549, '报纸', '民进先贤的新政协记忆', '毛梦溪', '民进中央宣传部;', '人民政协报', '新政协;周恩来;中国人民政治协商会议第一届全体会议;人民民主统一战线;中国民主促进会;马叙伦;毛泽东;雷洁琼;王绍鏊;民主联合政府;', '1948年，在解放战争迅速发展的形势下，中共中央发布“五一口号”，各民主党派在热烈响应的同时，围绕新政协的认识、目的、任务、时间、地点、召集者等与新政协筹备有关的方面展开热烈讨论，表明立场和观点，就新政协的方向和任务，提出意见和建议，为新政协的顺利筹备和召开', '2020-06-11 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2020.003265', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5550, '报纸', '民主人士北上参加新政协会议始末', '张学继', '浙江省社会科学院历史研究所;', '团结报', '民主人士;政协会议;民主党派;', '1948年下半年至1949年春，聚集在香港的民主人士响应中共中央的号召，在中共有关部门的周密安排下，克服重重困难，从香港分批由海路北上解放区，协商召开新政协会议，筹建中央人民政府。那么，这个时期究竟有多少民主人士从香港北上？最重要的有哪几批？每批都有哪些人？由于', '2019-12-05 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2019.000078', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5551, '报纸', '1948:风卷残云如卷席', '聂文婷', '学习时报', '学习时报', '', '1948年，解放战争进入第三个年头。人民解放军在各个战场上的节节胜利，使战争进入夺取全国胜利的战略决战阶段。 在中国共产党的团结争取和鼓励支持下，各民主党派和许多民主人士在政治上实现了历史性的转变。1948年元旦这一天，中国国民党革命委员会成立，宣布“当前之革', '2019-11-13 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2019.000409', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5552, '报纸', '弘扬沂蒙精神 传承红色基因', '刘家义', '山东省委;', '学习时报', '沂蒙精神;习近平总书记;红色基因;', '2013年11月，习近平总书记视察山东时指出：“山东是革命老区，有着光荣传统，军民水乳交融、生死与共铸就的沂蒙精神，对我们今天抓党的建设仍然具有十分重要的启示作用”“沂蒙精神与延安精神、井冈山精神、西柏坡精神一样，是党和国家的宝贵精神财富，要不断结合新的时代条', '2019-10-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAv4j-Ybe8fn-ztBRUWSAA0nKANzF3BM8MyWEN_GTbAXVYLkZr0rLFbT7L0RxPUy1ZGTYUmOhDU5_1lVyoL6aJ_-fVsi09JXHpb5LJU9rAihM_Yuto9UXxOhXJ6lZsn1RYICUZnZWf5Lw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5553, '报纸', '铸就中华文化新辉煌', '周玮', '新华每日电讯', '新华每日电讯', '中华文化;文化自信;文化馆;', '文化兴国运兴,文化强民族强。没有高度的文化自信,没有文化的繁荣兴盛,就没有中华民族伟大复兴。 进入新时代,以习近平同志为核心的党中央带领全党全国各族人民,更加自信地行进在中国特色社会主义文化发展之路上,为中华民族伟大复兴积蕴更基本、更深沉、更持久的力量。', '2019-09-20 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2019.004542', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5554, '报纸', '民进在筹备新政协的日子里', '毛梦溪', '民进中央宣传部;', '人民政协报', '新政协;民主人士;政治纲领;中国民主促进会;民主党派;政治协商会议;马叙伦;', '1948年4月30日，中国共产党发布了具有重要历史意义的《纪念“五一”劳动节口号》(即“五一口号”)，共23条。其中第五条提出“各民主党派、各人民团体、各社会贤达迅速召开政治协商会议，讨论并实现召集人民代表大会，成立联合政府”。 “五一口号”一发表，民进就立即表示', '2019-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBoQvg42QpwqqaoQGdaw1VXOmPrs09_fXlS8W9ovRJMgirWWQto27eYKijrqPjENgnnLe0BLX5QjILjSEg_W4I-j29ZDSfTxgsSdK-A33wHgHOJt8yOtpHZHw8mB9jhdqUQs15RPuNnWA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5555, '报纸', '以永远在路上的韧劲推进作风建设', '李照达', '中央军委政法委;', '解放军报', '作风建设;反腐败斗争;党风廉政建设;', '一句“用延安作风打败西安作风”，毛泽东同志道出了共产党人创造历史的奥秘：以优良作风赢得人民、凝聚民心。 一个党的作风，是其在思想、政治、组织、生活等各方面表现出来的态度和行为。执政党的作风，关系党的形象，关系人心向背。党风好，则政治生态清明，赢得民心；', '2019-09-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICkD_jrDlz5-T9P92xgIHJR-WSgvsBpw03-8VXKtbfWUagE61HFoGFDEFY4PGNOWGmO5GzlXPAZbVrm72x2xvr1Wwh4JVAF6pjcHfpUo8teFjm5L8SA0LNzAb_PUKDW0KSOFFb9Z6pYQQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5557, '报纸', '以赤子之心叩寻初心之道', '陈家兴', '人民日报社评论部;', '学习时报', '党报评论;共产党人;牢记使命;', '一个人长大后，因受环境影响，往往会变得世俗、圆滑。这也是“在山泉水清，出山泉水浊”的一种意含。然而，也有人不论在社会中如何摸爬滚打，仍然不失有一颗童稚般真诚、纯洁、善良的心。孟子讲“大人者，不失其赤子之心者也”，老子说“含德之厚，比于赤子”，都极言赤子之', '2019-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBXtI9KUatU9AFKrEKB5y3yzKvo8I-qR8lHV_PW3zoEsZ8-jMzZkSikgST2hqNHQOisAwkOxVNFdf1KI-98gCj1zz8gB65DwbDEc8pCqPiL_FYH30kqZDzzxjt4kpnOLYZzV__KfySKgg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5558, '报纸', '在新时代的“赶考”路上努力交出优异答卷', '王东峰; 许勤', '中共河北省委;河北省人民政府;', '人民日报', '习近平总书记;习近平同志;牢记使命;专项整治;防范化解;经济强省;党中央;重点领域;全面从严治党;京津冀协同发展;习近平新时代中国特色社会主义思想;攻坚战;中国共产党领导;', '70年前，党中央从河北西柏坡出发“进京赶考”，新中国从这里走来。70年来，在中国共产党领导下，中华民族迎来了从站起来、富起来到强起来的伟大飞跃，燕赵大地发生了历史性变化，经济社会发展取得历史性成就，河北人民过上了前所未有的幸福生活。 新时代，新起点，新征程', '2019-08-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICHhOYAk_ROTJf32kUjFlU38wPGDAEDN3NoWR6J1hkOObc8YFj1DuKrR_mzfufngzkxLx0gQlKl9Q3aHCtpgO1wzh4cFdH98s28O39jdOGqkK3xsFv29WGcjzMnz7S2Cn92ZgPrRegfCw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5559, '报纸', '伟大长征精神激励我们砥砺前行', '魏永刚', '经济日报', '经济日报', '长征精神;红军长征;长征路上;杨成武;', '历史是一部教科书，长征是这部教科书中永远值得珍视和铭记的一页。每次翻动这一页，扑面而来的都是英雄气息，激荡心底的都是奋进的力量。正如习近平总书记指出的，伟大长征精神是全党全国各族人民不断砥砺前行的强大精神动力。 在新中国成立70周年之际，在全党深入开展“', '2019-08-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDhJSUkzFFVvbiTUgmY-sfSAetJ_yJnN2MPHUv-yvWXPClD_8FWSGcm_8M1HedvBAw8jEH1vd-69BNbRax5tAgozzGfXEvcsMYWdxGNiD1TFId_r0CieFYkUiTATXcguuGiYn4_Z2Is-w==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (5561, '报纸', '文脉同国脉相连', '', '人民日报', '人民日报', '社会主义文化强国;社会主义核心价值观;中华民族伟大复兴;', '《我在故宫修文物》通过介绍稀世珍宝的修复过程和修复者的生活故事，展现了中华优秀传统文化的博大精深和精妙绝伦；《上新了·故宫》采用“专家与明星联袂”的方式，把故宫文化元素转化为创新产品的过程完整呈现给观众；“紫禁城里过大年”还原昔日清代皇宫的节日景象，让沉', '2019-08-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBMT7R7N3ZFPuVeCw2fbiFKXJRW0Q13usOlCq_RH9pwyvyZELjk0K4FnDUxfzYZMBewNwvhufs9MTJe65tJ7SuWTj0giNxVyrLm_PneXTvNqDn8HFFaZP_OEuUYJ2upl-ObodS3zrT65Q==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5562, '报纸', '不忘初心使命 永立时代潮头', '黄小希; 朱基钗; 王琦', '新华社;', '人民日报', '中国共产党;马克思主义;共产党人;习近平新时代中国特色社会主义思想;牢记使命;党的先进性;', '98载奋斗拼搏，亿万万人家国。 非凡的初心和使命，引领中国共产党由小到大、由大向强，创造“地球上最大的政治奇迹”，更把这个政党和一个国家的梦想、一个民族的向往、亿万人民的期盼紧紧融为一体，书写了人类历史上激动人心的发展篇章。 为中国人民谋幸福，为中华民', '2019-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBVm05_6CWKgMql7txx1ZSCntCKfhbsO14SjSLNodX6d2VLjGFnB1HuZIOxl4qQ-aqYwQEGEn9QEWvpYeDMaoy5zh4nEah9bsUYBfZU1IyBy-MUpCTMZvNuuX1S5PswxdcZ7aFY-Eam2w==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5563, '报纸', '铸牢忠诚警魂 强化责任担当', '闫明杰', '河北省平山县公安局;', '人民公安报', '强化责任;对党忠诚;', '河北省平山县是革命圣地西柏坡的所在地，也是全国著名的革命老区。平山县公安局始终牢记初心使命，扎根红色沃土、传承红色基因，全力锻造忠诚警队、全力打造为民警务，用实际行动彰显新时代“红色圣地”公安机关的担当作为。 以红色精神育警塑魂，坚定对党忠诚的政治本色', '2019-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAg28zaWxyAp3iA6woCDn1dN4jKpRQ8jghPZxHo2wWYHptH8-Dqlw6f-PmE6-3Fce4a_c-hiqYwpBPjxm4w9UvITcGO20Uhzlz7Z0BtnTwcw4BqHSkj846J_TW3i9teD0Ski4gEmjKybQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5564, '报纸', '永葆“赶考”心态', '厉辉', '河北省承德市双滦区委;组织部;', '中国组织人事报', '牢记使命;', '1949年3月23日上午，党中央从西柏坡动身前往北京时，毛泽东同志庄严宣告：“今天是进京赶考的日子。”今年是中华人民共和国成立70周年，中共中央政治局决定从6月开始，在全党自上而下分两批开展“不忘初心、牢记使命”主题教育。这是我们党的又一次“赶考”，在这个时刻开展', '2019-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDvtPMzr7-aKAibWe97yLzRKB1krjrCB0MfpommDmkT2KQpTC5Uk5bmjCJVpKqLgXghmKLB27NZl7eSqH-k0P328JjFE4D8eU_3RX1IJhBUS2f7fIwva6-aMDSnf640ubpu-xwtYPq19g==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5566, '报纸', '哈尔滨与新政协纪事', '张军', '哈尔滨市政协文史和学习委员会;', '人民政协报', '新政协;哈尔滨;民主党派;中共中央东北局;民主人士;冯玉祥;沈钧儒;东北解放区;政协会议;人民团体;章伯钧;', '哈尔滨，这个在1946年即获得解放的大城市、东北解放区当时的首府，书写了人民政协和新中国诞生前一段倍感荣耀的传奇，也赢得了中国现代史上一座城市的殊荣…… “开会地点拟在哈尔滨” 1948年春，弥漫着战火硝烟的中国到了历史重大转折关头。 国民党政府于战场颓', '2019-05-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAQgyPLmEsrs1XrEksU6HIK7sozy8qZrBWWsu8E5UZ7W_SfgwJ-3l-o_hh1VXmOG7-cUhMzvQJaE8SA4es4lskdQcchyrci-xdOGh_c7LsVRDCAKdQvNbF1pnFA041rOk0Y3s5tr_RXuw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争1_screened');
INSERT INTO `ds_article` VALUES (5567, '报纸', '从实求知', '丁元竹; 杨雪', '全国政协;', '人民政协报', '小城镇;社会学系;学术风格;人类学;吴江县;全国政协副主席;知识分子;一以贯之;学术研究;', '成为十三届全国政协委员，我既感到无上光荣，也感到沉甸甸的分量。如何当好政协委员，做好调查研究，写出高质量提案，是我最近思考的问题。因此我也常常想起我的博士生导师、著名社会人类学家费孝通教授。他在担任全国政协副主席期间，身体力行，深入实地，从实求知，努力做', '2019-05-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDh19tsEYt9MNMk66CWPes9I4TaN_JqhF2DLyxO1tP-n8miRVzJqrhdUgLisxY9lYKwgdIC5A_y5H13SEaS479rFsyz4vuTYm_epLOw32mfab3JoNlFr7jeWDLkQLZ4Neej3ug_E6l5hg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5569, '报纸', '中共中央发布“五一口号”始末', '李红梅', '中国政协文史馆;', '人民政协报', '“五一口号”;新华社;毛泽东;中国共产党;中共中央;民主党派;', '1948年4月30日，中共中央发布纪念五一劳动节口号，提出召开没有反动分子参加的新政协会议。 “五一口号”迅速得到各民主党派、无党派人士和社会各界普遍而热烈的响应，开启了中国共产党领导人民、团结各民主党派和社会各界人士协商建国的辉煌历程。在中华人民共和国成立7', '2019-04-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDJCIf4M87w02Vg61FvWHm7Y67nhjD1YpA_EoYCbAHRHIslUjd1YrV7VQqTyGT5ZaMMRDuMoko5sc___iEu6lCfUq5XA6EVlpAynmK_Yib8D2w4O1wfpmIe9NCRuiG95q_MmnmlLzJ59g==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5570, '报纸', '初心永不忘 建功新时代', '', '中国妇女报;中国女网;', '中国妇女报', '妇女运动;', '春寒料峭时节，中共中央妇女运动委员会西柏坡旧址的杏花开了。陈列室里，斑驳的旧桌椅镌刻着激荡的大历史。照片上的先驱们意气风发，参加土改、起草婚姻法、筹备妇女一大，然后，跟着党中央进京“赶考”…… 70年前的4月3日，全国妇联成立。今天，我们怀着虔诚和敬意，翻', '2019-04-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBoa-No-wDOVzQfaq3_VAgWhxv4_XgvCs-ca-w0P-3plDKW25UdRAawyZTS9TeyiuzWZpEqQlBCO7h3wFED-OUlNJviLZD1J1-Lf9rXaJv1EsfwVJGTObdEavuVnFPg4H3TXVRknYwU4Q==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5572, '报纸', '天将破晓 同心向前', '李朝俊', '民盟中央宣传部;', '人民政协报', '民主党派;罗隆基;东北解放区;毛泽东;沈钧儒;章伯钧;', '民盟积极响应中共中央“五一口号”，接受中国共产党的领导，为新政协的召开、新中国的建立，以及中国共产党领导的多党合作和政治协商制度的确立，作出了重要贡献，民盟的历史也由此揭开了新的篇章。 积极响应“五一口号” 中共中央发布“五一口号”的次日，即5月1日', '2018-05-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBEHlwp2wgx0xU1oZyZz_3vt0UfSfjhDuvLTnrpAkDcYE6nTQFihF_jfHq8RgNGkT2jVsjaDgQ8IUvOGFJA0vzv9Db9lVrr8M1SXKc3qlIra88YJloKsiewlUcYqMoA3wKxY-9wOXIQNw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5573, '报纸', '政治文化、政党制度的伟大创造', '邓凯; 俞海萍', '光明日报', '光明日报', '政党制度;中国共产党领导;民主党派;协商民主;政治协商会议;无党派人士;无党派民主人士;“五一口号”;人民政协;多党合作和政治协商制度;', '4月19日，西柏坡、李家庄。 这一天，这里迎来一批特殊的客人——各民主党派中央负责人和无党派人士代表聚在一起，纪念中共中央发布“五一口号”70周年。 70年前，在新中国诞生的曙光里，为响应中共“五一口号”的号召，在南方的民主人士纷纷从繁华的上海、美丽的维多', '2018-04-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBErACai45KROwbJab8IpCURO-aSsFrOlezBN8yMzkDwnh5UA8q3MuXjKhc9t0730J2R4ibkNxQzaUTi9B8_OEHnvi76vTHb4DVJNM6ZXxFbZJW4PBR5tbRw89zm4f2ETPPR1xrqjggOQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5574, '报纸', '砥砺前行忆往昔 风好扬帆正当时', '万鄂湘', '团结报', '团结报', '“五一口号”;中共中央;中国共产党领导;新型政党制度;多党合作和政治协商制度;各民主党派;中国特色社会主义参政党;参政议政工作;', '同志们： 今天，我们十三届民革中央中心学习组举行第一次集体学习活动，纪念“五一口号”发布70周年，以更好地推动“不忘合作初心，继续携手前进”活动的开展，促进民革各项工作的开展。最近一段时间，我特别结合当前形势就“五一口号”进行了学习，阅读了一些文献和学习', '2018-04-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID0t-5ZE7UoA5ffoLUszeuYJfIqlAjtu-AG6r7dGnSycLuvXnTGDWLiY-ymWmgNu5-h3dCI9ttpDQmItq8anJO0rXhFQHjMWePwd9IQwpr924h86LBNFyQSqAZ316dY2LdWz-7E2aZXIA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5575, '报纸', '各民主党派积极响应“五一口号”', '宗鲍', '团结报', '团结报', '民主党派;人民团体;民主人士;“五一口号”;民主联合政府;', '1948年中国共产党发布“五一口号”，各民主党派积极响应，在政治上实现了从同情和倾向中国共产党到公开自觉接受中国共产党领导的转变，为各民主党派在革命、建设、改革时期，与中共真诚合作、荣辱与共奠定了重要基础。今年是“五一口号”发布70周年，本版将连续刊文纪念，敬', '2018-04-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID6ZA_mClLZCQfHHiXDU1m5yQhsaLvTwE0NOw11_hx99t2P2S0e1fAC_zIDl4qQ1KbdwSmNA6o5Z-AdD06ASzqu2kC-PHGC1epsmQsUW2AbzGqrQNtVyUdaCvtletvRBSbtAy2LS3qjng==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5576, '报纸', '在纪念周恩来同志诞辰120周年座谈会上的发言', '', '人民日报', '人民日报', '周恩来精神;党的十九大精神;习近平新时代中国特色社会主义思想;人民政协;国民党反动派;座谈会;', '中共中央文献研究室主任冷溶： 今天，我们怀着十分崇敬的心情，参加中央召开的座谈会，纪念敬爱的周恩来同志诞辰120周年。这里，我就周恩来同志的思想理论贡献谈点学习体会。 周恩来同志为我们党的自身建设作出了重要理论贡献。他高度重视党的政治建设，自觉维护毛泽', '2018-03-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA-UmZrJpawPKMXmuzkKkYWCX9ur3swkvMXXBvUmTDbp8MJ9Pff4aitxnCCzxOjEz6At6r_fmxx3bA9PXGAyMU36p6C4_PimNeDLGxRtJRKSqwisWpbWIDtbY5kbbRpi1IpSOWRbRSIvg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5577, '报纸', '从延安到北安', '黄士伟', '中央党校县委书记研修班;黑龙江省北安市委;', '学习时报', '干部团;根据地;黑龙江省;红色基因;', '北安和延安有着重要的红色基因传承。这段历史虽然不为很多人所知，却放射着耀眼的光芒。北安与延安，一个在东北（黑龙江），一个在西北，相距几千里，相隔万千重，是伟大的革命斗争把两地紧密联系起来，并铸就薪火相传的红色血脉。1945年11月15日，受党中央派遣，延安干部团1', '2018-01-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICPwCx2q096qBYzYpTAR33MZFt7ld4a8VqtY6-RS2bjYDx1fZpl222NgdoHybGD3lM7PT7ZJRcjoc_NH9t4I9XhTLneanqXhoDvLVkQ1TuDi6ItcN67FLRt3F-h23NH3TTgI0H8LKOP5Q==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5580, '报纸', '中共靠什么屹立于当今世界？', '刘少华', '人民日报海外版', '人民日报海外版', '中国共产党;', '正如一切伟大的故事都不平淡，中国共产党也曾历尽苦难。 它创始的那天就颇多曲折。如今在上海最为繁华的新天地附近，那座低矮的石库门建筑日日游人如织，人们在附近喝完下午茶，总想来这里转转。但96年前，“开天辟地的大事变”发生，中国共产党第一次全国代表大会在这里', '2017-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC8-tyGq82QyqyLWwaK-XLFuO7TzGfIsfP7Iis91lTdc6qdqfDaSEqLm5FOenkphschIZXUG6ZaBZvbvJw4wafb4FmmBgqBl3-fQPHi_33Lrh-RsyTqb-_fvhyxIlTBz0nQeJ1xjlueeg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5582, '报纸', '习近平全面从严治党思想和实践的重要标志', '王昊魁', '光明日报', '光明日报', '习近平全面从严治党思想;习近平总书记;从严治党;八项规定;党风廉洁建设;重要标志;', '八项规定具有全局性、历史性、系统性、战略性的重要作用，是我们党管党治党从宽松软走向严实硬的一个重要标志，是思想建党制度治党的一个重大成果，其精神内核是习近平总书记全面从严治党思想的重要组成部分。 “八项规定出台以来的四年，是作风建设雷霆迅进、正风反腐', '2016-12-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDRH-TZFQuI1RVHT51cMYQzt4lrZFiiwFZq-PF5PBVH20wNHFzAfwWCbMQrGfeRY0zujk1xnx8RK9VduMynZJ6HtDEY56LaHm-eO_P0TkRvJpgnQgCfKEMNhR-CLMHnnHwJARPMiFWAgg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5583, '报纸', '穿越时空的精神力量', '李苑', '光明日报', '光明日报', '《穿越历史时空看长征》;历史任务;精神力量;中国共产党的三十年;长征精神;长征史;《中国共产党的九十年》;中华民族伟大复兴;党史工作;穿越时空;', '为什么已经有那么多权威著作，今天还要重新整理和撰写党史和长征史？ 黄一兵：《中国共产党的九十年》可以说是《中国共产党历史》（第二卷）后，中央党史研究室出版的又一本具有权威性和相当历史价值的党史基本著作。 继《中国共产党的三十年》《中国共产党的七十年', '2016-11-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBmKcinb9-Ltw3nTBwEXd9m37y-AgAiJSry0dcVjabQLP_LnmHS_Wp2EVX3NnJWdrJUQWxWTxSCgXE66l6AVBBE1x22EHsyc7dzGdPimVUbDC60qGmbyvGqQ27eqr_zGTIqMeEK7wV6Ig==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5585, '报纸', '文化出版界的巨人', '胡序威', '光明日报', '光明日报', '胡愈之;章锡琛;新加坡;七君子;《东方杂志》;', '编者按：胡愈之（1896-1986），《光明日报》首任总编辑，一生集记者、编辑、作家、翻译家、出版家于一身，“是一位廉正勤奋、博爱慈祥、淡泊名利、无私奉献的文化巨人，其崇高品德永远值得我们学习和景仰”。2016年9月，恰逢胡愈之先生诞辰120周年，光明人物版特别邀请了中国', '2016-10-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDtWE3Ta5srqNgubNjsp9koSL56HK0N4NQUBveRONvdriSR_5z5GA2OCRBliF0SZU-jE7rVSjXtTbw3jxmSsmYIr39TAmTKU7ZVYMmC4mIPSvSVeVupOCs_JBwRK3-gkLDrnVhCG_Pqxw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5587, '报纸', '着眼民族复兴伟业 推进文化发展繁荣', '王蒙', '文化部;', '人民日报', '文化发展繁荣;中华民族伟大复兴;创新性发展;创造性转化;中华优秀传统文化;中华文化;习近平同志;中华传统文化;社会主义核心价值观;民族复兴;', '改革开放以来，我国经济快速发展，中国特色社会主义事业全面推进，我国国际地位大大提高。与此相适应，我们的文化视野不断拓展、文化自信不断增强。所有这些，为中华民族伟大复兴提供了前所未有的历史机遇。习近平同志指出：“中华民族伟大复兴需要以中华文化发展繁荣为条件', '2016-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDlGN_CueShN_kyjMiVTgPKoKXWgEE99_F2wjyb4kEIpxzqdEDCwORi3QXynMsGmem01TOm6rskAYdZrhLwLdzkzdIAyrpHQkHf98N7nfUajFWBWRCzacGitsqSaNhuA2KPci9IBj5GjA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5588, '报纸', '在庆祝中国共产党成立95周年大会上的讲话', '习近平', '人民日报', '人民日报', '中国共产党成立;中华民族伟大复兴;中国共产党领导;党内政治生活;马克思主义;两岸关系和平发展;全面从严治党;共产党人;全面建成小康社会;团结统一;', '同志们，朋友们： 今天，我们在这里隆重集会，庆祝中国共产党成立95周年，回顾中国共产党团结带领中国人民不懈奋斗的光辉历程，展望党和人民事业发展的光明前景，表彰全国优秀共产党员、优秀党务工作者、先进基层党组织，动员全党全国各族人民更加充满信心朝着实现全面建', '2016-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAxYdkuLcLgnUa9IT3xQPscvkeOdnHkoRymdIoV-ZMGf-4ys7qAI0T07B_Rf1A_hjP-edtvSEhGUgErUmGCXu-XufxTUFLtisn1XpJEU3ivlPCaiqIMSzR_sQ8cWq8AkrW1k66sVBf9YA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5590, '报纸', '砥砺三十年，奋进谱华章', '杨雪', '人民政协报', '人民政协报', '建言献策;少数民族戏剧;现代公共文化服务体系;传承与发展;戏曲表演;京剧表演艺术;专题座谈会;参政议政;历史文献资料;戏曲传承;三十年;', '小小机构，载国粹精华，乘风逐浪三十年，为梨园百花争艳，润物有声； 大大平台，聚精气神情，而今迈步再从头，助中华命脉根基，戏剧常青。 这是不久前，全国政协京昆室（以下简称“京昆室”）成立30周年专题座谈会上与会领导和委员的即席之作，概括了全国政协京昆室3', '2016-02-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBNLcCuhTGVoPHxHrBe5H6_EXilOorbmN3_Q8ipKq5bl3W3DXefQd6wuHO8P5WTAr1YTxrujEOSFNBHbQ-y-pAmvyvGkfzvIrgJVtZQ_5rFRezprzS4nSHc9SAXscTXvq-1YVSD2ofngA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5591, '报纸', '“习近平对中国发展战略有深刻见解”', '尤里·塔夫罗夫斯基', '学习时报', '学习时报', '习近平;宣传画;中国发展战略;', '2012年11月29日，中国共产党这个由8000多万党员组成的、领导着全中国近14亿人的党，在第十八次全国代表大会落幕两周后，新当选的7名中央政治局常委，出人意料地去了国家博物馆…… 按照毛泽东、周恩来、刘少奇等中华人民共和国开国元勋定下的传统，中央所有党政领导生活', '2016-02-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID4tpxrcNxxywl9R8um_PD3kTgTCqrgcj52WlnrYer231vFUvOi2J-hRriPWjbvILXPY2bqEz3qweydI5MvjifuhCqAyxQB-iAEmDHnCzmVvwjhvBIYach4bfRAFd7LnD_oCNxClpo_8A==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5592, '报纸', '弘扬雨花英烈精神 用好用活党史资源', '郑晋鸣; 储宴宴; 张广宇; 贺庆', '光明日报', '光明日报', '雨花英烈精神;习近平总书记;重要讲话精神;红色文化资源;', '本期主题  去年12月，习近平总书记在江苏调研期间指出，在雨花台留下姓名的烈士就有1519名，他们的事迹展示了共产党人的崇高理想信念、高尚道德情操、为民牺牲的大无畏精神。要用好用活这些丰富的党史资源，使之成为激励人民不断开拓前进的强大精神力量。', '2015-11-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAIu1obF7YPJPJ759hT8KGksg8g6CDW7PLfy4isRtQwYB4e9ADZz9C490SBKjKUXr6vjEtQWoN_v0PnCilCKILf5ieQ_hWgJQ98YdlQIwCyftiJAPtKweYnBQNtu8LxTPGod4u6tnTnzg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5593, '报纸', '时刻不忘从哪里走来 自觉践行“三严三实”', '赵正永', '中共陕西省委;', '学习时报', '“三严三实”;专题教育;习近平总书记系列重要讲话;', '党的十八大以来，习近平总书记反复强调我们党和国家、民族、军队从哪里走来的问题，令人深思、发人深省、让人备受教益，也为我们坚持和弘扬党的优良传统和作风、扎实搞好“三严三实”专题教育指明了方向。  习近平总书记多次论述我们从哪里走来  2012年12月', '2015-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICjveVXTz1y4hALBbiNTgZV5AIl8slI0vxurSCN86-A2vKMF08cKQc_Efs00Nhf9BcRS5dzljO2rt-ZUqJVfXAF75sKQq0_PKgdSazceeMZs3-Y3B70tP82rX8stdqj-AyaVyjB9tqJdA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5595, '报纸', '不忘本来才能开辟未来', '赵正永', '中共陕西省委;', '人民日报', '习近平同志;第一要务;中华民族优秀文化传统;全面从严治党;专题教育;执政兴国;全心全意为人民服务;中华民族伟大复兴;共产党人;社会主义核心价值观;', '党的十八大以来，习近平同志在多次会议、多个场合上强调我们党和国家、民族、军队“从哪里来”的问题，令人深思、发人深省，为我们在新形势下弘扬党的优良传统和作风、开辟中国特色社会主义事业新局面提供了依据、指明了方向。 深刻领会我们党“从哪里来”的丰富内涵', '2015-08-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID9tI2hVgZAMPVXonmEgjS_-Hr5YHRJRD2eb8P_ecjMcOOfg0HCE69zynj_xCvPJPvyycJDL8KEfrkmfdYmYCDnmBlW3TubVkuNr1Mj3irDObyiBKcsPSyTOOg5pkyBqO54lFmaZTM47g==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5597, '报纸', '弘扬“红船精神” 践行“三严三实”', '夏宝龙', '中共浙江省委;', '光明日报', '“三严三实”;习近平总书记;“红船精神”;党的先进性;', '10年前的“七一”前夕，时任浙江省委书记习近平同志在《光明日报》发表《弘扬“红船精神” 走在时代前列》的署名文章，首次凝练概述了以“开天辟地、敢为人先的首创精神，坚定理想、百折不挠的奋斗精神，立党为公、忠诚为民的奉献精神”为主要内涵的“红船精神”。我们要深入', '2015-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDO3M5KGSO-AJwIfrvWZjl4e8BfonGVf2I9qpgaBjvLEFIlhE9reVGHQgDMk2ZVaGrg2SpNabd36k29jTtoBra7pSgPnmJ7-nW7CqkA0DeYW2rnqG3Ji-SzuL2BaaQbp7NiEV1Z5JwKeA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5598, '报纸', '从韶山旅游看我国红色旅游发展', '晏晓明', '湖南韶山管理局;', '中国旅游报', '红色旅游;景区景点;红色资源;红色旅游景区;', '韶山是全国爱国主义教育和革命传统教育示范基地，也是红色旅游胜地。她开辟时间早、发展过程长、参观观众多、中外影响大、综合效果好。据统计，60多年来，韶山共接待国内外游客1亿多人次，其中党和国家领导人及部分社会知名人士256位，外国国家领导人和政党领袖247位。可以说', '2015-06-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDgJyFCIogET2zXL6efA9vV3DswO7Yrc2XfF7FdlK7G35LziErm44ozEasEr0K5pqQOOe0W9BGmKYlwZEjeHa2Hm96LIqwDKT4qX7u_XzWtPVD4OZL051iptqPQq9tSBmKEwM2fedLWXg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5599, '报纸', '挖掘古城厚重历史 弘扬优秀传统文化', '耿建扩', '光明日报', '光明日报', '中山国;优秀传统文化;晋文化;游牧文化;雪浪石;中山松醪;李延年;京津冀一体化;《说苑》;', '编者按 日前，由光明日报编辑部、河北省委宣传部、中国秦汉史研究会共同主办的中华优秀传统文化与中山文化研究研讨会在河北定州举行。定州是联合国地名组织命名的“千年古县”，也是中山文化的发祥地和重要传承地。来自中国社会科学院、北京大学等研究机构和高校的专家', '2015-01-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAuP60s3zF7KH5kS82vcSV9ZkwRBwP2QMJ1LoyA-QgaZh1yAullPuREMSQPKqUInFcsKN7XK2V_9c4SDymh_Q9JIs3qPKFZ-gqJN8QbHvSzJ4jvwDwYT1JsN6GGawuE8cKe22PNgvZvsA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5600, '报纸', '常怀忧患意识 加强作风建设', '刘云', '中国组织人事报', '中国组织人事报', '忧患意识;作风建设;《甲申三百年祭》;', '在群众路线教育实践活动总结大会上，习近平总书记强调，历史使命越光荣，奋斗目标越宏伟，执政环境越复杂，我们就越要增强忧患意识，越要从严治党，使我们党永远立于不败之地。 为何增强忧患意识如此重要？如何增强忧患意识？忧患意识与作风建设有何关系？在11月21日-22', '2014-12-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBcHtEf0i_Yu1Fj98spBDNqyEKab6PNDDfvfTB-OX6403xKICGXc2TkApSt6kPP64r2dAoo7uMraElA0EnNIFXoBlgaxXUNHQBl9br_9jc2iGcSW0-8bpjK1UrJqDW2-O9jQ4wNsg-Bcg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5601, '报纸', '弘扬渤海革命传统 建设现代幸福滨州', '周华 ; 李雪海 ; 王栋', '光明日报', '光明日报', '革命传统;无私奉献;社会主义核心价值观;渤海军区;', '渤海区是中国共产党领导的重要抗日根据地和解放战争后期山东三大战略区之一。渤海区东至胶莱河，西抵津浦线，南跨胶济路，北止天津南，东北濒临渤海，版图面积最大时达5.4万平方公里，中心地域在现山东省滨州市。解放战争时期，渤海区党政军领导机关驻今惠民县何坊乡。渤海区', '2014-11-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAwAraV9YR1DZsPpIvxIYht_tlkhqT_dP6KB3afDS7QQkuyISYPA7MUcpJXrD3xQB8C4lIhTz-EU-sa5ClHXVAnATrYn0eDzVcqf-aC7i0KsZnYVikJ5BH8SWEsxank-s79K40MuzWl4g==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争_screened');
INSERT INTO `ds_article` VALUES (5602, '报纸', '为繁荣军事文艺冲锋向前', '', '解放军报', '解放军报', '军事文艺;习主席;军队文艺;为兵服务;强军实践;雪域高原;文艺工作者;文艺工作座谈会;中国革命战争;晋察冀根据地;强军梦;军区政治部;', '弘扬军队文艺工作的优良传统 解放军艺术学院 胡 可 我是一名离休多年的军队文艺工作者，能参加今天这个座谈会，感到十分荣幸。 习主席在文艺工作座谈会上作了重要讲话，让我联想到72年前毛主席在延安文艺工作座谈会上的重要讲话（以下简称《讲话》），那次《', '2014-11-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAv-IFKAxjlA4sjngPWGlUQ9UkUtULnLa6sNIi3sjPYEyk8DrIM0dPpnKRocGpyYHiTIKKQOdiSvixMXilPx_gEV3bpsmENgoKUNcXkOeffJefsUvaChHz1c91CV0RV_KCzpSvk0F4yrg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争2_screened,白求恩_screened,方志敏_screened');
INSERT INTO `ds_article` VALUES (5603, '报纸', '获益终生的一段经历', '费孝通', '中国人民政治协商会议;第三、四届全国政协;第五届全国政协;第六届全国政协;第七、八届全国人大常委会;', '人民政协报', '中国人民政治协商会议第一届全体会议;', '屈指算来,这是50多年前的事了。这件事的发生对于我们的国家和这个国家的每一个人，都产生了极大的影响。这件事就是新中国建立前夕，在北平召开的中国人民政治协商会议第一届全体会议。我作为一名代表参加了这次会议。 作为民主党派的一员、一个在大学里教书的知识分子，', '2014-09-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDWv9fo9bh9pbkdnQFptjsEeZJ4UVmpDyzg_aJiVQH1GElYTE-BX-BAlU9HR2kcfgSZCetSM-PAgId1GOL5qPyk4PM7CJj-lizRmqUGPmq-MuJbEecSq6xnOG7BFDuQSXZXae77AaTBjg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5605, '报纸', '在纪念任弼时同志诞辰110周年座谈会上的讲话', '刘云山', '人民日报', '人民日报', '任弼时;革命家;党性原则;密切联系群众;共产国际;大生产运动;座谈会;', '同志们，朋友们： 今天，我们怀着十分崇敬的心情，在这里隆重举行座谈会，纪念任弼时同志诞辰110周年，深切缅怀他的不朽历史功勋，学习和弘扬他的崇高精神品格。 任弼时同志是伟大的马克思主义者，杰出的无产阶级革命家、政治家、组织家，中国共产党和中国人民解放', '2014-04-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICJ1wuTV5ZAri66oVDeVR1rJpY648TOj6qkFOzPFOcreWfpV1QjmdK5nJR4YnDBDqM05K2jQww3WMP5xbcU9U5Vbtzoudh0IICBKylNo8A-N_3Ev5hGCMwiWAUlhB6bj53vs6pW9otCHA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5609, '报纸', '赶考，中国共产党人的历史任务', '', '新华社;', '新华每日电讯', '共产党人;历史任务;', '中共中央从西柏坡迁往北平65周年之际,适逢第二批党的群众路线教育实践活动全面铺开之时。从当年“进京赶考”到今天的作风建设,中国共产党人进行着“赶考”接力。 历史是最好的教科书。65年前,毛泽东将中央机关由西柏坡这个中国革命的最后一个农村指挥部迁往北平比作“进', '2014-03-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICYOus1r3miDmJSQ1zVk9P2vsKdkCVSh9hCy7qKDGqAv_hqf79BIwN3FK-o34uys1bf6DbbUuR7-0RUkXf-Vurqiqy57xVjXlDEyeun1SKYwNqodE18BujvV46_aMtzNwdNDMxiQQgJNg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5610, '报纸', '影视冀军 河北现象', '', '中国文化报', '中国文化报', '影视剧创作;文艺精品;精品创作;《周恩来的四个昼夜》;', '1河北影视展现看得见、摸得着的“中国精神” 高小立 作为具有深厚历史文化、鲜明革命文化和先进当代文化的河北，近几年，随着《唐山大地震》、《周恩来的四个昼夜》、《打狗棍》、《闯天下》等一批影视剧的上映与热播，我们从中看到了河北影视人的身影，这些影视作', '2014-03-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA4MGHbjDgSP47jngrp-vNDbdseMMvyyZeGmzlJEASfNCNFqLbIVrRx0s4iKVmWI3VU0TIp_cIk4YFKo5oSbxKMqSYLvuxz-bopJdArKstmITZ5VuQes5klFRH8JnWu_UjAXcCQ1L2OJQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5614, '报纸', '协商民主的伟大实践', '陈延武', '团结报', '团结报', '协商民主;中国共产党领导;多党合作和政治协商制度;新中国成立;旧政协;社会主义协商民主制度;政治协商会议;无党派民主人士;“五一口号”;伟大实践;', '1948年4月30日，中共中央发布“五一口号”，各民主党派、无党派民主人士热烈响应，由此走上了新民主主义、社会主义的道路。 “五一口号”的发布，成为中国政党制度和人民民主政治发展的开端，开启了我国协商民主的新征程。 中国共产党的十八大报告首次提出“协商民', '2013-04-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDhiFfHE2mXSM43wyFGzZ6mz329cn5IzlpjyvrJHuckmchCWxOzRr1kL-dXexOHPkOFY91KHk2Lc2BGWs6hg5tzWFPnoxghkuFdt7nflhafbUai0JdN63PNUOkRQs6z2Bx0M_aVApoiNg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5615, '报纸', '银幕尽显风流人物 大爱铸就时代传奇', '', '光明日报', '光明日报', '李林森;王二小;湘南起义;罗布泊;《铡刀下的红梅》;电影工作者;', '为迎接党的十八大胜利召开，广电总局电影局积极组织、推出了一批具有思想性、艺术性的优秀献礼影片。这批影片坚持贴近实际、贴近生活、贴近群众的创作原则，坚持“思想性、艺术性、观赏性”相统一的标准，面向市场、面向群众，创作质量上乘，显现一种示范和导向性的重要价值', '2012-10-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDbwyfdXtHCUiSRHelcYqNF7xPhgMlBcDWqQjci2jsXE1Hmq9y8pv3sXCSjt0o2makxnK6QfAHi6A8F4dsNRko84S1P7XkUV13y0D06U7pWXmRu0Ap4UtqaxMrh3ILMG5Cic_aL5y507A==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5616, '报纸', '建设“京畿强市、善美保定”', '耿乙丁', '消费日报', '消费日报', '旅游产业;旅游业;白洋淀;狼牙山;旅游资源;保定市;旅游强市;野三坡;景区建设;', '保定曾是新中国工业的摇篮、社会主义商品经济的代表，北方改革开放的典范，“文化古城”、“抗战脊梁”、“冠军摇篮”等形象在全国都颇具影响，在旅游资源方面也极其丰厚。 日前，河北保定市委、市政府在提出发展战略时提出要建设“京畿强市、善美保定”。对此，保定', '2012-09-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDEg-5lmnKB5Ahu9En4M0s5vfyhZOWR3vDwF5yB3gZOPbT3jWFsbNlVkW69p6I1H_56gSGLa8-IvlOocQs7GpnYA4OplhNfmb65sH9nDueeMPTtFXTWL1JgSUxuobX7suII6lM0USA-jQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5617, '报纸', '科学发展十年间', '李斌 ; 赵东辉; 肖春飞; 周英峰 ; 华春雨 ; 何宗渝 ; 叶前 ; 侯大伟 ; 齐雷杰 ; 李俊义', '新华社;', '新华每日电讯', '党中央;社会主义;胡锦涛;科学发展观;党的十六大以来;国际金融危机;', '“党的十六大以来,以胡锦涛同志为总书记的党中央,坚持以邓小平理论和“三个代表”重要思想为指导,深入贯彻落实科学发展观,团结带领全党全国各族人民攻坚克难,锐意进取,在中国特色社会主义征程上阔步前行” 在历史长河中,十年,不过弹指一挥间。 在中华民族的煌', '2012-07-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDEdWV7iAcBC0tx54Xl5dUO7NYVoOyY-3TsRU3pPYNREAT1KlWDSaRBCu0yOJXUstI03jo6gN7fn7GBmH8Cs0_DF_8pvQ-Ac0E-MsZo6RwXhOIU8TUMX5whfofYnCeG3e82LmCu4kTXzA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5619, '报纸', '在纪念胡乔木同志诞辰100周年座谈会上的讲话', '刘云山', '人民日报', '人民日报', '胡乔木;中国社会科学院;社会主义现代化建设;毛泽东思想;马克思主义;哲学社会科学;马克思列宁主义;知识分子;党的思想理论建设;座谈会;', '同志们，朋友们： 今天，我们怀着崇敬的心情在这里举行座谈会，纪念胡乔木同志诞辰100周年，深切缅怀他的生平业绩和历史贡献，学习和弘扬他的革命精神和崇高品格。 胡乔木同志是中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家，杰出', '2012-06-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC-7ZOojXH8MCt8j36rgF9782AqtMrD988qPiQhSN1oSJvB4vKOtsf3ax3JD-QJ8lbCekddgfILxr-HKw9xf7ZVL5Z_EV4hNDTF02Bq4FfVNGxv5egNRVPtPhNbsEYl2bnKIyyFHiooxw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争2_screened');
INSERT INTO `ds_article` VALUES (5625, '报纸', '把群众当亲人：共产党人的必然选择', '', '人民法院报', '人民法院报', '创造者;优良传统;共产党人;党的群众路线;必然选择;', '胡锦涛总书记在庆祝建党90周年大会上的讲话中，“人民”一词用了１３６次，平均每１０４个字里就有一个，充分体现了我党全心全意为人民服务的宗旨，说明党一切为了人民，一切依靠人民，一切服务人民，党同人民心连心。胡锦涛动情地说：“只有我们把群众放在心上，群众才会把', '2011-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBbzCN6AAqQcAxxImUVSA6eDNHNBj0UexCtjVavGbWKKeaXom9T6cqv2cQJO_UgD05T4fs-Gh9Bv7K6UlVMHzyol4f5ZD6oapEJiykg9OPcd9JFiLqKMoJhlnsNVmKthTTIgSsknq9dtA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5626, '报纸', '战火中耸起水利丰碑', '', '河北省水利厅;', '中国水利报', '华北水利委员会;平山县;防洪安全;华北解放区;华北人民政府;河北省水利厅;', '编者按:随着河北省修复西柏坡革命旧址首批工程告竣，华北水利委员会旧址于今年7月1日对外开放，以隆重纪念中国共产党成立90周年，展现水利先辈们在战火纷飞中创建的治水伟业，激励广大水利人在中央1号文件指引下继行开来，再创辉煌……  华北水利委员会负责人', '2011-07-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAvKKg0ViBMW8DoVBEc5MoOi8ZQKIn6_oqQo83_-YXwlus1LFouNVZhZU1m097biNUJdRR8h7FrnHtBRlu9uB77I7qXyRJMvNZSIoyFfeBVIaliCgVFdkCYSW2FOpTG1SjoaOy-GXAZ0g==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5627, '报纸', '西柏坡：黎明曙光映照金色盾牌', '黄明健 ; 于明旭 ; 盖志勇', '人民公安报', '人民公安报', '华北人民政府;公安机关;社会部;中共中央;公安部;', '新中国从这里走来——西柏坡遥望北京，是党和人民的又一处心灵故乡。在党的90华诞来临之际，在太行山麓、滹沱河畔，华北人民政府公安部旧址等一批革命遗迹相继修复开放。 迎着夏日灿烂的阳光，怀着无比崇敬的心情，记者近日来到河北省平山县，走进红色革命圣地西柏坡', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIANQNqlQRAyExkoj8yzEtFwVtPVfQY7jJ3WSwjjBh_wbyNkv4se5XKusn14WzNPqkhwkhpm0MpvK-UWCUNZa8_8qI9kqwt5TFqjbOWTuGmG7os2YuiNkXeJZXpoXc7tDPFHBo5Wk0qXbA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5628, '报纸', '协商合作 共襄伟业 英雄云集 深孚众望', '', '人民日报', '人民日报', '民主党派;毛泽东;知识分子;国民党反动派;', '【记者观察】 协商民主生命力无限 □本报记者　刘维涛 “各民主党派、各人民团体、各社会贤达迅速召开政治协商会议，讨论并实现召集人民代表大会，成立民主联合政府” 1948年4月30日，全国胜利在望，中共中央发出历史上著名的“五一口号', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDygmQn5iLwXz-iXiHpZK9GWoCn-ksHkAKfayT92d4fSO4jxN8fyalHi9CFG4Tqe1oSzLEELwORC3jl7xb-MKTBFCNB6ask3dnRVji-OZ9qlYNrHSiv__zSnz_5DdPhrsioLz0CjP5FJg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5629, '报纸', '中国卫生的“红色地图”', '王玲玲; 姚常房', '健康报', '健康报', '中国工农红军卫生学校;中央军委;白求恩精神;军医处;医疗卫生工作;红军医院;中央苏区;卫生运动;', '今天是中国共产党建党90周年纪念日。在90年的历程中，中国共产党带领人民不懈奋斗的历史征程和光辉业绩，犹如一幅气势磅礴、雄浑壮丽的画卷。伴随中国革命起步与发展的中国卫生事业，是这幅历史画卷中浓墨重彩的画面。让我们展开画卷，追寻“红色卫生”的印记。 井', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBUYNf-k9snbln_YuoUsd_haEjd2NBmMoF0HjADXXSvBhKPHqedaqgfWphIej7izneaPlkicOvpqE8jeJarmzK5FntIKmkN3IsNwZQwpxJETi5ntwcpAAnKICmJI2rUglwJjnA-v3nw2A==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,强渡大渡河_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (5630, '报纸', '坚持党的领导 确保“两个健康”', '', '中华工商时报', '中华工商时报', '非公有制经济人士;共产党;坚持党的领导;中国共产党领导;', '成立于1921的中国共产党，至今已走过了90年的光辉历程。中国共产党成立90年来，始终站在时代前列，依靠和团结全国各族人民，为实现民族独立、人民解放和国家繁荣富强、人民共同富裕的伟大目标，进行了不懈奋斗和艰辛探索，夺取了革命、建设和改革开放事业的伟大胜利。在这个', '2011-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICJ-Qo7QPUHgxeJfK5n2s89OSgQHovI1L3UYtVP-RIaU5eZ0ZvzXGL5T2e9S2Wg0m22e6xkBMm49X6_OJvue6ynqWeoWYafCF77YCoErYx7TE21IJZWGfs8LZovQABkU6DImqPcRajCQg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5633, '报纸', '“小灰楼”：人民银行诞生地', '张明亮', '金融时报', '金融时报', '中国人民银行;中华人民共和国;河北省;晋察冀边区银行;中国金融史;南汉宸;第一套人民币;', '从一楼到二楼，从东到西，在每个展室里转一遍，隔着防护玻璃“触摸”一下闪烁着历史光辉的一件件展品，回味一下其蕴含的特殊意义，这已经成为中国人民银行旧址纪念馆、河北省钱币博物馆馆长魏占辰每天要进行的一项必修课。 在石家庄市中华北大街55号(原中华北大街11', '2011-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBYMs4bYD55TQZW3sDNB4ZwWMsHTspwlfx2b04Vv8-G04Txku6syD2cDaiZ8XjeeUucjxu3vFUp1A4MJvQH_mG8f5LftEInr2KbaWeyVxX4Nf1ssyr_MWzdoeBJUYjpLjPh6ms6_wNXVA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5634, '报纸', '追寻红色足迹 接受心灵洗礼', '李蕾', '光明日报', '光明日报', '精神传承;烈士证;敬一丹;中央电视台;新闻频道;', '在举国欢庆建党90周年之际，新闻人纷纷行动起来，用镜头、话筒、笔杆挖掘出一段段耐人寻味的红色记忆，记录下一个个历史与现实对话的感人瞬间。由中央电视台新闻频道特别制作的系列专题节目《重访纪念地》在众多节目当中脱颖而出，新颖的节目形式、深刻的思想内涵，自6月13日', '2011-06-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID4sI9wRaiZ1N9Nk-DrkABg_SO7pJOhQ3bOlBF9MLkiMgf0xq62tGVUf2mBlQTR9_xBwJHy6g257KR-6LiFZcb2x_fiaCNTBNyTTa_0fy99lIfWUfJ4yO9TsfqsCceQLJpX01FBo3w4QA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,白公馆_screened,渣滓洞_screened,遵义会议_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (5636, '报纸', '优秀文化资源用之不竭', '谢颖', '人民政协报', '人民政协报', '长篇小说;红色文化资源;红色历史;共产党人;', '为迎接中国共产党成立90周年，引导文学创作高扬主旋律，贴近实际、贴近生活、贴近群众，展示革命纪念地的历史与今天，中国作家协会从去年开始了“走进红色岁月”中国作家采访采风活动。作家们深入西柏坡、井冈山、延安等革命老区采访座谈，目前已有几十部作品出版或正在创作', '2011-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBenoKhfqgYAN98HtPJjXwoyoVO5oGhahYpWBMqS1mDYrUNK7kJM5fDs9YL5M4wmzM4UAyoLPSd3WasV9UVH1myKsiMme92ci0TuurrAnciF9SPFeG5N_oB2qgEl6xsCNxPrNY2M-AgpA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5637, '报纸', '成功实践 基本理论 宝贵经验', '', '光明日报', '光明日报', '党史工作;延安整风;第一代中央领导集体;中共党史人物研究会;党史部门;中国共产党成立;党史界;中央党史研究室;局部执政;马克思主义中国化;宝贵经验;', '编者按 近日，中央党史研究室、中国中共党史学会和中国中共党史人物研究会在京联合举行全国党史界纪念中国共产党成立90周年学术研讨会。来自全国党史系统、党校系统、军队系统、社科院系统、高校系统的160多位专家学者参加了会议。与会专家围绕“中国共产党领导革命', '2011-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIARNDUUUqeTH3cK-7kr9-tTUGV8LLoNZyjaGypIxsn_l4zNkXG6OuUIEYNfj6ZQUiNB4UwYwqX0sMzn-Knq28_rdMscFCysKl4TZ65mGPwS_9af5_OJ_UdIth4H974lY2RmLS3aj51y4A==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5638, '报纸', '民营企业家要从井冈山精神中汲取营养', '木佳', '中华工商时报', '中华工商时报', '井冈山精神;企业家;公益慈善事业;中国泛海控股集团;政协常委;', '6月9日，由中央统战部和中国光彩事业促进会主办的“非公有制经济人士感恩革命老区井冈行”纪念建党90周年座谈会在井冈山举行。全国政协常委、全国工商联副主席、中国泛海控股集团董事长卢志强，全国政协常委、中国民间商会副会长、新奥集团董事长王玉锁，江西省政协常委、江', '2011-06-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB5KOoJTM9URPZPm8NFuoXTn50QdahCENBbLZWphxqucqS2hlKcgZrBUiOlLfnjkrpLRhwXC7KuDctbtSz1sPcyI_Dm885zATzxdE-t2-BnW4b-2RvQpC6sue8wnbqCAcLM6Zrm_bbyUA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5639, '报纸', '中国人民银行命名的故事', '罗宇凡 ; 华晔迪 ; 王宇', '新华每日电讯', '新华每日电讯', '中国人民银行;晋察冀边区银行;南汉宸;', '“如今我们的军队称‘人民军队’,我们的政府称‘人民政府’,何不将我们的银行也称‘人民银行’!”中国钱币博物馆的讲解员马静指着墙上的一张老照片介绍说:“讲这句话的人就是这张照片里的何松亭,时任晋察冀边区银行副行长。” 1947年,随着解放战争的节节胜利,分散在', '2011-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBjA89XBFQpDuveCDprkSj7oFOsNAjaTnJMWhF5Xbu4lZoy1QXFsdzkC0UrENLMw8L1QCuAHBxsURDTpeSfHUDHfg9HssecvUHXzvEM_cNmWvJjPETnH6p8ViZMY4d-KSGgzHKClC8p8A==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5643, '报纸', '从一个“幽灵”到中国伟大实践', '陈振凯', '人民日报海外版', '人民日报海外版', '井冈山革命根据地;共产党人;伟大实践;', '起初，《共产党宣言》被错印成了《共党产宣言》，而一个“幽灵”，被翻译成一个“怪物”。那时，中共创始人之一，王尽美还没改名，他叫王瑞俊。　 1一个幽灵 事件：1920年8月，《共产党宣言》中译本出版；1921年7月23日，中共召开一大 镜头：1920', '2011-05-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAFjDc9Ba8RLeCM8QOsY4dp8busSOaarof3ecPf58p8tXd1Su_k0Y0iGmr-uAiuFvfl4wI5_wQcZjSAzG28IJEY26JxClrqNQKmRvWnMiiGDj0piUSlmTdtQGY34393nXEZanjbniI9CQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5646, '报纸', '永葆艰苦奋斗的政治本色', '解正祖', '国防大学军队党史党建研究中心;', '解放军报', '政治本色;战斗作风;勤俭建军;共产党人;高中级干部;军事斗争准备;', '军委胡锦涛主席指出，艰苦奋斗既是我们必须大力弘扬的工作作风，又是我们必须大力弘扬的思想作风。在新的形势下，我们要认真贯彻胡主席指示要求，把大兴艰苦奋斗之风、保持共产党人的政治本色作为重大课题紧抓不放。 一、艰苦奋斗永远是我们党和军队的传家宝 艰苦', '2011-05-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA9_58rM8IRXoL-yBNTxSOCAOFcz0hs7I9zPTYVb3K18WPFkWggD1ExhCce0k3X4i1lGDs0QchNfx-_ljz7OH2JJUE-dT2BidWX2amWfPyf_-TNZOBScn1jGmVBtLvsaezbRXw1smXZCw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5648, '报纸', '闻喜:“廉”意化作“及时雨”', '任丽红', '中国纪检监察报', '中国纪检监察报', '廉政教育;', '廉政教育如何入脑入心?如何化为党员干部的自觉行动?记者日前在山西省闻喜县廉政教育基地采访有了新发现。  “一墙之隔坠深渊，一念之差毁终生”。走进设在闻喜县看守所里的该县廉政教育基地，墙上的这副对联映入眼帘。教育基地设在看守所大院的一栋三层小楼里，它与', '2011-03-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDoqONAVNGnrUgGne_JnivxxbJGu7npYoy7b7TZZjyAXxSmo_GJLeQf2RO8m5Q8LYkXTtseB2u7Yt3Am7969R7ximNd4G6c-mN25cqL8TDpzMt6t8OjODbXcXMtHLNCznf4qyEVCx1WEw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5649, '报纸', '唱响科学监管的铿锵之音', '王越', '中国质量报', '中国质量报', '科学监管;执法程序;检验检测体系;沧州市;食品检验中心;特种设备安全监察;国家质检中心;政府质量奖;技术监督局;', '太行在这里悠悠穿越，长城在这里蜿蜒盘旋，新中国在这里迈出腾飞的起步，这就是内守京津、外环渤海的一方热土——河北。 60多年前，中国共产党在西柏坡吹响了嘹亮的号角，在这里实现了将党的工作重心从农村到城市、从战争到建设的转变，为从新民主主义向社会主义过', '2011-03-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICKHK8FugwnnRpNL_jpBEw2YznqfD9hd-dQOFBcV69YBy5QgaUI_M8z2YTAc2-jOY_MNU9jgmHFZxqT8X4MkT99w_iGe_6IeYmpOPpFyyvjldWAvH5k0J9ASGSXiPIIIODBT27asExP7g==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5650, '报纸', '斯人已逝 风范长存', '严隽琪', '全国人大常委会;民进中央;', '人民日报', '民进中央;中国民主促进会;和平民主;', '2011年1月9日，著名的社会学家、法学家、教育家，杰出的社会活动家，中国民主促进会的创始人之一和卓越领导人，中国共产党的亲密朋友，全国政协原副主席，全国人大常委会原副委员长，民进中央原主席、名誉主席雷洁琼同志，走完了她一个多世纪的辉煌人生，永远地离开了我们，', '2011-01-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAx59O9RHOFexHV5M1UoF72m06qhJYtnvKT3EZUhIaRUvVLSUdcFzTGg2bhh7b_CIvc3AWdYqAqfDEMi-OpwxCa1Q-wogpxJcJR5sczWrPOV_gHXDqlJOaKTdBk985_ewUBl5T8HF7ZRQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5651, '报纸', '雷洁琼同志追思会(发言摘登)', '', '团结报', '团结报', '民进工作;中国民主促进会;雷洁琼;民进中央;“五一口号”;民主党派;多党合作;', '高山仰止 精神永存 全国政协副主席、中共中央统战部部长 杜青林 1月9日，敬爱的雷老离开了我们，中国共产党失去了一位肝胆相照的真诚朋友，统一战线失去了一位广受尊敬的老领导、老大姐。她的离去，是国家和人民的重大损失，是统一战线和多党合作事业的重大损', '2011-01-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIByLYhPPaX_yrA3s7D0DnlwmFYRLQbLfI3hfLmChf_USyxEl93PIeLBQSDA56g4nBObpKQM56d7EeEw1jAQGWUrFxyqKexy-wkE2alYtlhOAdvW1NeqfVKtaxzkuV9V2Q2eJoPk9kqrxg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5652, '报纸', '雷洁琼：“说到底我只是一名教师”', '俞水', '中国教育报', '中国教育报', '雷洁琼;应用社会学;北京大学社会学系;', '2011年1月9日，雷洁琼在北京溘然长逝，走完了她106载的传奇人生。 这是一位览尽中华百年风云，见证民族沧桑巨变的伟大女性。 她的名字，或许对很多人来说耳熟能详。作为民主斗士，她参与抗日救亡运动，亲历“下关惨案”，曾和毛泽东一起商谈建国大业，出席开国', '2011-01-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA1JnzaU8b1ofKjtHQ5YjRqV3ZpTzm-p5jUrXvq4xptk1NG_VjsL6miHYL8OwTt0fzzao_GpdjO_u12wk_tETvgMO7559QbaOqX1z8hiseB62BzdgQF9Gns_ykxr0kN2fIVUXf8Rlxu2Q==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争2_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5653, '报纸', '雷洁琼同志生平', '', '人民日报', '人民日报', '雷洁琼;民进中央;中国共产党领导;政协第一届全国委员会;', '著名的社会学家、法学家、教育家，杰出的社会活动家，中国民主促进会的创始人之一和卓越领导人，中国共产党的亲密朋友，中国人民政治协商会议第六届全国委员会副主席，第七届、八届全国人民代表大会常务委员会副委员长，中国民主促进会第七届、八届、九届中央委员会主席和第', '2011-01-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICT_vqHWhLFmXZjI8DyWjnA3QxzJIlnTxhDV7896qQolXTgkC_8txAlwyYJ-Qfyx02_WU1DnIkyN4NVIL2NItqoSP4gYLupTQwl7kxv2BoaNOuSO6l9xGiFfqj3TF2tS-uQjTCt9x9hGQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5654, '报纸', '黄华同志生平', '', '人民日报', '人民日报', '外交部;联合国大会;中共中央顾问委员会;朱德同志;日本帝国主义;中共中央军委;对外交往;政治秘书;', '中国共产党的优秀党员，久经考验的忠诚的共产主义战士，无产阶级革命家，我国外交战线的杰出领导人，国务院原副总理、国务委员，第六届全国人民代表大会常务委员会副委员长，原中共中央顾问委员会常务委员黄华同志，因病于２０１０年１１月２４日３时８分在北京逝世，享年９', '2010-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBalEoc06UPkE5csv8f1hKviPy9geipEbm0Cqdrcg2HqR2NcpUxayPxyZevbY2YxpKzNuaW5sEbSC34Ibp88eDJnp693gNAUnqHfOgYbAoftAPAvfovnPpV9Hz_swYl_CtDTUXR10FwlA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5655, '报纸', '在纪念费孝通同志诞辰100周年座谈会上的讲话', '王兆国', '中共中央政治局;全国人大常委会;', '人民日报', '中国共产党领导;中共领导人;全国人大常委会;香港特别行政区基本法;中央民族学院;多党合作和政治协商制度;民主党派;座谈会;', '今天，我们怀着十分崇敬的心情在这里举行座谈会，纪念费孝通同志诞辰100周年，深切缅怀他的非凡业绩和杰出贡献，追思和学习他为国家、为民族、为人民不懈奋斗的高尚品格和始终不渝的理想追求。 费孝通同志是我国著名的社会学家、人类学家和社会活动家，中国民主同盟', '2010-11-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIACnxMHp9lY4XKx5b4RNAKVrHSunjzwwBJUfysUoL0TA8wjMPVDpqV0logkXEB9ghzrrvd2Sw7t_jt7eKg7614J0P5RJXRFhmZx4sr80M6WcPfQX56IxnzQLjcpVX1B1LoHomhuzxQ7lw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5656, '报纸', '庆祝雷洁琼105华诞座谈会（发言摘登）', '', '团结报', '团结报', '民进中央;全国人大常委会;中国民主促进会;雷洁琼;座谈会;', '在奉献中感受幸福 严隽琪 敬爱的雷老在105年的人生历程中，经历了近现代祖国从衰弱到奋起、从新生到繁荣、从积贫积弱到全面建设小康社会的全过程。在80多年的革命生涯中，她从一名追求真理与进步、倡导民主与科学的革命青年，成长为我国著名的社会学家、妇女运动', '2010-09-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICDRXMHIkFEQ6jq_9Xt5Q7xi1iT9UFA8ykGD_0skOEoIfDzk9dAbtO2XKaISZIe46UPQ2HxyF-sDPURC0Xnx8IMcpBdLPRHE23JikJUKQPqggn0IWhCY60b6foLu8XcbfBlo4VmHkB5yQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5657, '报纸', '第十三届文化大奖获奖剧目：彰显人文精神 体现国家水准', '', '中国文化报', '中国文化报', '《寄印传奇》;杂技艺术;上海昆剧团;《我那呼兰河》;《长生殿》;钟离昧;创作者;人文精神;', '结构·难点·价值 ——评京剧《成败萧何》 龚和德 《成败萧何》是上海京剧院继《曹操与杨修》等尚长荣三部曲以后在新编历史剧上又一个成功的创作。这出戏以三个精彩的情节设计，完成了全剧的戏剧性结构；通过克服两个难点，把主要人物的行为和内心活动写', '2010-07-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB8olNBwj7tpxKavzqM_BBVeQnRAoEQmZGhMLWDjgXVIs4dgrvS4YkXR8F1VPJItA7oRdIOBA7SX487T7Ty9ajhTMz5pUbmtZXXV7PAAPnJfdBFe-_9pnxdlRN8Z1XS-eb8TKYu4khQBg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5658, '报纸', '探索作家艺术家深入生活的新途径', '', '光明日报', '光明日报', '井冈山;中国作协;摄影家;深入生活;采风活动;', '编者按　为推动深入生活、促进创作繁荣,中国文联、中国作协从今年3月开始,先后组织25批作家艺术家赴井冈山、延安、韶山、西柏坡、遵义等革命纪念地进行采访采风,收到良好成效,产生热烈反响。6月23日，中国文联、中国作协联合召开“倡导深入生活、推动文艺繁荣”座谈会。参加', '2010-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB1LvhM_I3mu9FVxqo7-geaD0s_yOxFgZ11o_cT3-kfVAlEwksOci60SK0JHCVutsEKhLPeM9A_ao0cpcWHRtD97gMFBfCkl-KaE3gLPRjeHi-rMm8Z7aEVvLfu5puc_fUNRQ4aUtgxZg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,黄洋界_screened,王佐_screened,茨坪_screened');
INSERT INTO `ds_article` VALUES (5661, '报纸', '拿什么回报你,我的老区人民', '徐叶青; 秦超 ; 王振江', '解放军报', '解放军报', '青年编辑;', '“我们在感动中前行，我们在感动中思索——新的历史条件下，我们向老区人民学习什么？我们给老区人民什么回报？”参加中央新闻单位百名青年编辑记者“寻根西柏坡”活动，这两个问号一直在我们心中萦绕。一座座旧址、一件件史物、一片片追忆，100颗年轻的心在曾经的炮火硝烟、', '2010-06-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICcbCde6XmOABXd1Q1LkNPTxsV3aFaMAkSCF32gm3KO4SELjm_a0rvMAGewWvlrJQo8Xch3Bv_vJ-2fVSq80J1sfdvbh1BzhGojyAwIMr_K53AjgVw2WM_ruAP6XFAKcJkljOEnfTqxpg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争5_screened');
INSERT INTO `ds_article` VALUES (5664, '报纸', '“马背上的摇篮”走过70年', '曹健 ; 刘国顺; 周猛', '解放军报', '解放军报', '幼儿园;阳光雨露;', '今年“六一”前夕，总政幼儿园在孩子们的欢歌笑语中迎来了70华诞。 1940年，正值抗日战争最艰难的时期，总政幼儿园的前身——“中央托儿所”在宝塔山脚下诞生了。从此，“马背上的摇篮”成了培养革命后代的基地。从延安到西柏坡、再到北京，从战争年代的“中央托儿所”', '2010-05-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDruTQcbWNKWT13zi86FW_Zicm8phoA_IFTkHnn-mjppzQSqj5P7Z2pc4CDIbsjavLA6burut_vBP4Qb_B_TdbqmRaaxf9eXTEkv4WmAVVOdL6J-WOITXY8YZdEFWHW0DuQVvlVfdXHOw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争_screened');
INSERT INTO `ds_article` VALUES (5665, '报纸', '新中国财政奠基于华北', '', '中国财经报', '中国财经报', '审计委员会;中国财政部;抗日战争;晋察冀边区;根据地;', '开栏的话：原国务委员兼财政部长、全国人大常委会原副委员长王丙乾同志新著《中国财政60年回顾与思考》日前在京发行。对广大财政工作者来说，这是一本不可多得的教科书和研究文献。它的出版，无疑是我国财政理论和实践的一件大事。为此，本报特辟专栏，节选书中部分精彩内容', '2010-04-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBGuEXL8tPb8WQn8hZVWdT6be_5hMAYmL4hkg95AkxWCKIUcitzDUXFZBMGgaGc-fYmg-FmBcoSjJOrgfjwG9C0fCB6FJYnlEHauYREHgJ0YQ9eVjnPPDYQsrFfH6n_0cH5cXQDHE9-Cg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5666, '报纸', '见证历史发展进程 彰显时代精神风貌', '徐涟', '中国文化报', '中国文化报', '城市雕塑;新中国成立;吴为山;侵华日军南京大屠杀遇难同胞纪念馆;雕塑家;纪念性雕塑;雕塑理论;纪念碑;江小鹣;人文精神;雕塑创作;中国雕塑;精神风貌;', '矗立在天安门广场的人民英雄纪念碑，将波澜壮阔的革命历史事件浓缩在一组组艺术高超的汉白玉浮雕中，不仅成为新中国城市雕塑历史中的经典之作，更成为中华民族不屈抗争、勇于牺牲的精神象征；侵华日军南京大屠杀遇难同胞纪念馆的大型雕塑，以悲愤和激情雕塑出令人震撼的艺术', '2009-12-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDHbZO1P1GmmMF1LkRY4YsqUGDkiaWT0mhLze_lTd4Pe7NnvT_D13TdlZyRx2nnbLQ-oB_Fvv2y7VqpIcRpVwx7r_f2p27FY2TnRdMeyBeV_rptzBssuo9Lge2cIaZiwfQptEQ8_ZMlHg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争2_screened');
INSERT INTO `ds_article` VALUES (5667, '报纸', '60年政协足迹 鲜花告诉我你曾怎样走过', '杜军玲', '人民政协报', '人民政协报', '王兴东;', '9月20日上午10点，当《义勇军进行曲》嘹亮的歌声在全国政协礼堂回响，那铿锵的节奏仿佛把900多名首都各界代表带回到60年前:一个甲子前的那一天，正是在第一届政协会议上，这首歌曲正式被确定为即将成立的中华人民共和国国歌。 \"60年来，人民政协走过了不平凡历程，', '2009-12-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDGlHI1Q1F7n5G6DRh3ViFQ22SiUSCekkZUzQyE23uTxWWbB-cOJQ2bbPmpv2_Z10QHkmNh1-68tYK5dflTwsByJV6mtWAFoiSRKkEF4GXjOr2T0h6Vk2SD_hcUdwsaT1qGS5pAcwKNGA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5668, '报纸', '我们靠什么赢得人民真诚拥护', '张弛; 滕晓东; 代烽 ; 邵敏', '解放军报', '解放军报', '红四军;古田会议;红军长征;井冈山;高中级干部;夏明震;红军医院;盲动主义;', '今年纪念新中国成立60周年，起码有两件事将会长久地留存在人们的记忆中。其一是国庆阅兵。人民解放军向世人展示的，并不仅仅是现代化的飞机、导弹，还有从南昌城头、罗霄井冈流传至今、一脉相承的精神力量；其二是双百英模评选。那些闪闪发光的名字提醒着青年一代：没有这些', '2009-12-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDQwNLt5wDqrQKi_-Eer8K0Jetbv8va9q83rJSOR8Vudw0oU1lz-kkyEHADns_MscS4ER1FMjZAhffkkGcZe39QEw87kugUfnaJrYzFVeWaQya8WDJhs8Bz5yLXOhZkFRbjyuTrR3vJdA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,红四军_screened,瑞金_screened,井冈山革命博物馆_screened');
INSERT INTO `ds_article` VALUES (5669, '报纸', '反哺老区 正当其时 扶持老区 义不容辞', '王作义; 李永海; 李仲彬; 赵文忠; 宋增建; 高吉全', '中国老区建设促进会;四川省巴中市市委;延安文化展示中心;江西省南昌警备区;', '解放军报', '优良传统;促进会;座谈会;新中国成立;老区精神;', '我们的三个心愿 到12月4日推出第66期报道，本报为纪念新中国成立60周年而特别策划的“革命老区行”大型系列报道结束了。12月7日、8日两天，由本报联合中国老区建设促进会组织的“革命老区宣传暨建设座谈会”在河北石家庄和西柏坡举行。 座谈会上，来自江西', '2009-12-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDTsutrkBA5I6N0TAZpCPI644HSlMJJI6iE3eP14bwgDOax6t0XnTsW-oMpkojW09v_OjoEI68T2bsbuiTOHUI9370TMXAYcZkSslhjEcDdobnyvIrxZCnYEoKuP2HX3rp1ui64qUINgA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5671, '报纸', '“无期大学”的一个大课堂：党委中心组学习', '倪迅', '光明日报', '光明日报', '党委中心组学习;胡锦涛;干部在职理论学习;学习型领导班子;党委中心组学习制度;大课堂;', '“要把全党变成一个大学校。”  “我们这个大学,可算是天下第一,叫做无期大学。”(《毛泽东文集》第二卷第183页)  这是毛泽东在延安时期对当时建立的干部在职学习小组的评价。  站在新的历史起点上的中国共产党,怎样把各级领导班子建设成为学习型', '2009-11-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBJKOsijrqczZLn7a1fRIqbi-rDcd84TW1C3rppjlnFHRqnjO8ia0e7J_YIbKIjN7VuF8nOoOc_vjQDDmmAlkUZSa-Ht0aVu2M4o51HqIZWVt4cWRPfVpXrR2G8yTkNDmwUDwCBzlXnTQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (5672, '报纸', '快马加鞭未下鞍', '徐莲英; 王成锋', '国际商报', '国际商报', '梁场建设;滹沱河;制梁场;甬台温铁路;中铁十三局;', '西柏坡，这个光耀中国革命史册的名字，原本是河北石家庄市平山县一个只有百十来户的普通山村。 1948年5月，毛泽东同志率领中共中央、中国人民解放军总部移驻这里，使这个普通的山村成为“解放全中国的最后一个农村指挥所”，成为中国共产党领导全国人民和人民解放军', '2009-11-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBH9VHSApgCjn8HFFFrAn2i-WYeBFIHQIlFt1wJ02UMTPCxBnpORk0Di7f7OzfofbfYKCr_nY05hK4cxqLiH2WUu-5P5cOZFR2PsR1DMy6-XN4N2Q4beH47fIng5eBCYHAQFfojjyQxFg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5674, '报纸', '从“学习型社会”到“学习型政党”', '倪迅', '光明日报', '光明日报', '学习型政党;战略任务;首要任务;中国共产党人;党的十七届四中全会;学习型社会;', '“学习是前进的基础。”  邓小平这一至理名言,说的是做人做事的基本道理,也体现了中国共产党人永不满足、永不停滞的鲜明特征。  引领中国发展进步的决定性因素  新中国欢庆60岁生日,中国共产党在960万平方公里国土上执政,走过了60年的历程。 ', '2009-10-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA0WubWRtUY1wkelo6lHyDNH-hcOZyiYFLQ2dN2n3eG1zypcD_8BE2vtjfcNzTYB50ZgyVVNcQFIZTtBYFvdXy06efitz-BXUVGV6SxJmqHMIg3Yy0Vzv-SVVuM2mQ87wiT2od4ZTkGjg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5678, '报纸', '托起中华民族复兴的希望', '', '新华社;', '新华每日电讯', '中华民族复兴;科学发展观;执政党;', '一个国家的发展，只有在世界和时代的坐标上去认识，才更有高度；一个民族的复兴，只有从历史和现实的对照中把握，才更加清晰。  新中国的60年激发了一个古老民族的巨大活力，唤起了整个中华大地的勃勃生机。开创辉煌道路，肩负复兴重任，这既是使命，又是考验。一个', '2009-09-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLZPimvpP8xLHigu0_7Td_vr-QHz6LURnuEYRHJIc2V7TZqL2ElLKPm_9WpDrvaBCLu-15dua3k_TMWsh5fV_dzmFG5ewii6o9iSkn6dVuFLwlOMcAfbUcjACdCDQH3Fl0Az0YbvTI-A==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5679, '报纸', '挺立,一个民族的伟大精神', '李泓冰; 郝洪 ; 陆娅楠 ; 任胜利', '人民日报', '人民日报', '伟大精神;时传祥;共和国;新中国成立;中华民族;模范人物;', '一个伟大的民族，一定有远大的理想。 一个胸怀远大理想的民族，“一定有个可赞美的光明前途”！ 此时此刻，当人们以自豪的神情，翘首以待国庆盛典的到来，可曾想起孙中山先生“振兴中华”的呼唤？可曾想起方志敏烈士在狱中昏暗的油灯下书写《可爱的中国》', '2009-09-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICtLsCH2YLiTWrPUX1ffODuVnmWn1jQ6YGoOL3zdfbj9ob4__dljD0zBGqPmLz8-hGN75y-7kM_C_-D0k_-_BpqqDjvjbDXXP9lJeg7AFzGqf4QIZpGptL2Z9V5hEWyC2-VhLhG_fbe-g==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5682, '报纸', '中国精神——共和国之魂礼赞', '徐京跃; 谭浩; 隋笑飞', '新华社;', '人民日报', '时传祥;共和国;大写意;新中国成立;陈德华;', '伟大时代孕育伟大精神，伟大精神塑造民族之魂。 在新中国成立６０周年前夕，李大钊、“狼牙山五壮士”、时传祥等当选为“双百”人物。 １９２７年４月２８日，绞刑架下，李大钊发表了最后一次慷慨激昂的演说：“不能因为你们今天绞死了我，就绞死了伟大的', '2009-09-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBav9R6b0OtF37hev0YiXN6ZlwxhGnnU7SCIBwTji1GqpRw5Af6g6bdBDktCr-3farROyla6PA_2sDXYKFHAI72oZ8JVIZiqL8Ys3r5StuQmEJMLCLJ5eMBeTHazifow7_1vIIq2Qg_kg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5683, '报纸', '中国精神：凝聚民族复兴的力量', '徐京跃; 谭浩; 隋笑飞', '新华社;', '新华每日电讯', '共产党人;新中国成立;大写意;时传祥;个体工商户;民族复兴;陈德华;社会主义核心价值观;', '伟大时代孕育伟大精神，伟大精神塑造民族之魂。  在新中国成立60周年前夕，“100位为新中国成立作出突出贡献的英雄模范人物和100位新中国成立以来感动中国人物”评选结果于9月10日揭晓。李大钊、“狼牙山五壮士”、时传祥等当选为“双百”人物。  1927年4', '2009-09-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICkbKCftlSu3YaO2yAGOwaUTBGx2D0BT5qcBKQTA71QmwfOMqKejaJc3XP51rN2gl_AS7cwrcneR2W7dR4oNHlX2dDXVpeXlb-fcHZsN9szpioiYlRGX9HRpjUXkYHb7MTYcIhuadRIqg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5684, '报纸', '中国道路：走“人间正道”圆“中国梦想”', '李斌; 杨维汉 ; 崔清新', '新华社;', '新华每日电讯', '共产党人;中国特色社会主义道路;开国大典;', '60年前开国大典那天，罗浪在天安门广场指挥军乐团演奏。  “当时有人说用德国曲子，有人说用苏联老大哥的乐曲，还有人建议用美国的，一时间议论纷纷。”今年90岁高龄的罗浪说，“最后，是毛主席确定了‘以我为主，以我国为主’的方针，就是要听自己的乐曲，走自己的', '2009-09-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA4OPa5IZ-YmKinTNCltxHEAnZJyNbIVrYiOmGqVK2ZeDlFiHfiUu4x8YcBzLCD95cOUxVoFW1zMn0cIqteRsVTs0BR_gezntih7RrQ6BkyZEdyAuiHueQzWPgxZcpXuvA3-zCdohmVow==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5685, '报纸', '中国曙光——1949年10月1日历史再现', '孙承斌; 谭浩; 白瑞雪; 贾楠; 侯大伟; 季明; 郑黎; 张琴; 黎昌政; 黄枚; 胡锦武; 张云龙; 王建华; 赵志鹏; 陈键兴; 杨蕾; 何自力; 张军; 刘景洋', '新华社;', '人民日报', '宋美龄;开国大典;宋庆龄;何鲁丽;中南海;天安门城楼;国民党;天安门广场;', '１９４９年１０月１日。星期六。农历八月初十。 北京。微风。阴间多云转晴。 迎着东方黎明的曙光，这一天，中华民族获得新生—— 毛泽东：为筹备开国大典紧张忙碌 蒋介石：面对风雨飘摇的统治黯然神伤 晨曦轻拂，中南海菊香书', '2009-09-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDVyrgmu39DQj8t3_DXZ4FXXctEKirz3Xiio3IP7UkdYuGsF6s9-DvqWhXE7kEr5IymSPW-JU89kMjnYWHU9q1hYD0gWp8Y_E5OB3MWqr2TJw3NTN7r2WCKYRGLijmv4Cw6-Rsv2v8Yfw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5687, '报纸', '“答卷”得高分', '张涛; 曹国厂 ; 任沁沁', '新华每日电讯', '新华每日电讯', '共产党;平山县;毛泽东;汪玉凯;涿州市;', '新华社石家庄9月14日电(记者张涛　曹国厂　任沁沁)西柏坡地处河北省平山县中西部，是一个偏僻的小山村。解放战争时期，中共中央进驻西柏坡，并在这里指挥了震惊中外的三大战役，取得革命胜利。 1949年3月23日，中共中央从西柏坡出发，经河北唐县、保定、涿州抵达北', '2009-09-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA9KlCs4MG3LiEysegI32H_Jq7k-h2-onbCIEoxMIq3RbU6arperiqpKYcwNkWBk8uh0eO9lD_-NA0okLi39birh0L8Rsv2aW5vrt94g6Ejgsc1_znh9CdKYHhJkXxJdwyFSeYR6BnhyQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5688, '报纸', '太行明珠耀神州', '彭波', '人民日报', '人民日报', '八路军一二九师;河北省;太行山;革命老区县;前南峪;中国人民抗日军政大学;', '【阅读提示】　 作为中共中央、晋察冀边区政府、八路军一二九师、中国人民抗日军政大学曾经的所在地，太行山革命老区闻名全国。 当年,依靠不畏艰险、无私奉献的太行精神，800万太行人民筑起抗日的铜墙铁壁；赶走了日本侵略者后，又全力支援解放战争；还是', '2009-09-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICTPU_p8ZrWBHuwteAhdq3yhsjWyNCH3tsuMpmCgpRTYJm8scntuRXrhBZk9dGbPJ2RhBbfHCFnbTb98IKncKQ2DArL3GlRLKxvc8zfnsaUu8LTNcaO9t0f3WFlzxwo9TkrOOW8MEK2nw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争5_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5691, '报纸', '河北开展爱国主义教育基地巡学活动', '耿建扩', '光明日报', '光明日报', '爱国主义教育基地;青少年爱国主义教育;', '本报讯(记者耿建扩)河北省注重发挥爱国主义教育基地功能,从今年4月以来,谋划并开展了以“新中国从这里走来”为主题的全省青少年爱国主义教育基地巡学活动。截至目前已有300万人次青少年接受了爱国主义教育。  河北省具有丰富的革命历史资源,全省共有革命圣地西柏坡', '2009-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID_tT7Glzc9nmwMrVbGSRhjsENNnZZ7m9dzq9Y-J8S3J_Ygt7bdZup0uLUjDBnY83jhdEXfiwQFe155TrTbJg9PtPgrMT4oO3Z_M80Hf4jW0rTj8vPS1xPMDJhNy5iVLqfUYOHZFeIyFw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5695, '报纸', '《沂蒙六姐妹》再塑临沂城市品牌', '丁凤云', '山东省临沂市市委宣传部;', '中国文化报', '沂蒙精神;《沂蒙六姐妹》;临沂市;城市品牌;', '日前，一部以反映人民群众对战争的奉献和牺牲、诠释女性与战争关系的电影《沂蒙六姐妹》在全国推出。该片是山东省唯一一部向新中国成立60周年献礼的影片，被中宣部、国家广电总局确定为“全国迎接新中国成立60周年重点影片”。在北京举行的全国首映式上，1200余名观众被影片', '2009-07-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAo_hGSwFMqFieM6BczOqLZaftdII7FjQl9Ui8QymI6ZdHh29tmgskNENxXMJs0RB6GN4kyh-jWVbmiXMV9yUecZ06VYAwKUb0-orsRHRlHB6vT9xk19ViU0HOrD3JdLUrUL4Te57xIrg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5696, '报纸', '始终为人民执好政掌好权', '', '人民日报', '人民日报', '党的先进性;共产党;六十年;中国特色社会主义道路;科学发展观;矛盾和问题;马克思主义中国化;新中国成立;中华民族伟大复兴;', '今天是我们党诞辰八十八周年，再过九十多天，我们将迎来新中国成立六十周年。 这是一段波澜壮阔的历史进程。我们党紧紧依靠和紧密团结全国各族人民，经过艰苦卓绝的斗争、坚持不懈的奋斗，开辟历史新纪元，缔造了新中国，确立了社会主义制度；开启历史新时期，引领', '2009-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDrDHM3KPrNJ8u5fAKMN--2VCbdZcJSzte8zSao9mz7wYnBdy6fptu3MCq3yYfbQp-1FWaxtUtv8OSkb1iwgFqdA-KxKZtZn44amyoxqF4SdVs4K2hsquCs7nvk98Itr9Z0xVojdHONaA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5697, '报纸', '雄浑的史诗 不朽的丰碑', '谭浩; 魏武 ; 肖春飞', '新华社;', '新华每日电讯', '中国共产党;社会主义;马克思主义;刘光人;中国特色社会主义道路;共产党人;', '这是一段段血火交织的岁月；这是一场场风雨砥砺的记忆。  从上海石库门和南湖“红船”出发，中国共产党人的足迹遍及南昌、武汉、瑞金、延安、西柏坡……从这里出发，共产党引领共和国走过整整一甲子。  88年过去，南湖烟雨依旧。在五星红旗的辉映之下，中', '2009-06-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDo6HcQgoeqsSpu-xGpojtO3YU6GEaLJzZf8FzuFtbKknoeyXCC25TUheNKJ46ud5vhcb7jBVCAIHvIT4Yl38Z-YIc35aYxknV-2W39KxDPvoP7TppAkenQ-sgKYCi22BgkbQgZhlwKOA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5698, '报纸', '红色征程续写辉煌篇章', '吴凯; 李治国', '经济日报', '经济日报', '现代化国际大都市;新中国成立;社会主义;', '开栏的话 革命圣地、革命老区记载着中国革命的伟大历程和新中国诞生的光辉足迹。在庆祝新中国成立60周年之际，本报派出多路记者，分赴上海、南昌、武汉、井冈山、古田、瑞金、遵义、会宁、洛川、延安、西柏坡、北京，以及太行山、大别山等重要的中国革命历史纪念地和', '2009-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDr8TisVlGUBLCM89l-9YoGSXiE6lZ0PtMQe1oIQVu6pJyLIHJ75NrJKi8CezhJGkwdH_sXuhlLuXRsYwQ4LFIzH6eReUjmVQkn_Hh4FukvRpTvfae29QC3Q-PwXqaamN7EOFzi3Ax3DQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5699, '报纸', '千里来寻故地', '张弛 ; 滕晓东 ; 代烽 ; 邵敏', '解放军报', '解放军报', '井冈山斗争;秋收起义;红军长征;三湾改编;烈士纪念塔;支部建在连上;红四军;民主集中制;毛泽东;古田会议;反对本本主义;', '引　子  最近一段时间，军队政治工作战线出现一些值得关注的新动态。  4月中下旬，南京军区党委常委和军师旅政治主官180多人，赴革命圣地井冈山、瑞金、古田，专题研究在新形势下大力加强思想政治建设，如何实现胡主席提出的“三个确保”的时代课题。 ', '2009-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDVbrREDTt_S_2ZQSJev4i4ZHOqgpSTENuhMyrmoQyb51aL3OqhefUZxWsQ5dlfh2vH3OEYJQzY8tGGCV6y9gc7iQAuN5lfKZ5Zzo1XdxRwOb7LzPbaV98FBc2ovcH0LqcNvlmBsF3UsA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,中共七大1_screened,红井_screened,红四军_screened,瑞金_screened,黄洋界_screened,井冈山革命博物馆_screened,秋收起义_screened,贺页朵_screened,卢德铭_screened,三湾改编_screened,朱毛会师_screened');
INSERT INTO `ds_article` VALUES (5700, '报纸', '人民共和国,从这里起步', '许晓青 ; 吴宇', '新华社;', '新华每日电讯', '共产党人;石库门;人民共和国;中共一大会址;张建民;', '开栏的话：在新中国成立60周年之际，根据安排，从14日起，新华社开辟专栏《共和国从这里走来》，通过对中国共产党成立至新中国成立过程中重大历史事件发生地的今昔报道，描绘中国共产党带领中国人民前赴后继、艰苦奋斗、建立新中国的历史画卷，在全社会深化爱国主义教育和革', '2009-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICm-WcSje9LeWLceNVXFaNYngs63vba9oxukY9dtsNGqPu_VgYEEbM3CpWsxzBJhthMFMrLmT3Z9v5kZd64MWQVNYHh2B8ddR1anvOZhbItXa03B6D3vQgTARon7kXBQ9p0i9LGnuZCWA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5701, '报纸', '贾庆林观看大型交响音乐会《柏坡交响·新中国从这里走来》', '廖翊', '人民日报', '人民日报', '交响音乐会;《柏坡交响·新中国从这里走来》;交响乐团;', '新华社北京６月８日电 （记者廖翊）６月８日晚，河北交响乐团大型交响音乐会《柏坡交响·新中国从这里走来》在国家大剧院隆重上演，拉开了“庆祝中华人民共和国成立６０周年献礼演出”活动帷幕。中共中央政治局常委、全国政协主席贾庆林与上千名观众一起观看了开幕演出。', '2009-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICfWfxsKeGxO6586CM4B3jW5LP2U_ENQgHPR59oXfVbnQOMSL_eAgpicLI-IscD5N-M3FPTYzaEWzO5ZabJD7YLjFxyoyUzcq5eaxOKbpu7SSotgw05mvSqhG401OhEh7QstH5VeZy2Rg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5702, '报纸', '“柏坡交响”拉开献礼演出帷幕', '黄小驹', '中国文化报', '中国文化报', '交响乐团;交响音乐会;作曲家;', '本报讯 （记者黄小驹）“西柏坡我是你的读者，读你的草木我读到了蓬勃。西柏坡，小小村落，走近你我感到博大胸廓。”6月8日晚，河北交响乐团的大型交响音乐会《柏坡交响·新中国从这里走来》在国家大剧院隆重上演，拉开了庆祝中华人民共和国成立60周年献礼演出活动的帷幕。中', '2009-06-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDd_iaP_G57VIm-WqNU0LKlF56ZZ1d1mBNdWaZdJP6-qbt6vK48VBkCmMTV-qEYipwt8ukRj-ysKab4SCHwsdua4JyRokkciYshTAj001Hpulw7NsDS8R216sWvfTcLhYuZXUUZ4_Im5A==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5703, '报纸', '爱国主义,永远飘扬的旗帜', '孙承斌 ; 谭浩 ; 李亚杰', '新华社;', '新华每日电讯', '爱国主义;群众性爱国主义教育活动;中国特色社会主义道路;中华民族伟大复兴;社会主义建设时期;', '爱国主义，是动员和鼓舞中国人民团结奋斗的旗帜；  爱国主义，是推动中国特色社会主义事业不断前进的力量。  在庆祝新中国成立60周年之际，在党中央的部署下，全国即将深入开展群众性爱国主义教育活动──  广泛开展面对面的宣讲活动，深入开展有', '2009-04-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDRrAhNeaKKkwwyeaFh6Lq_cK1a3OvjLrKh9SWlBheb3LRBjyDA2iD54q24g8dc51j3vsDa7Zi2C6LPhI6ETSMv4ta55iip2iG5qif-Ed_uuBeqXHHzi2XF9ujcxWJ-ln6ZbPM1F4pF_A==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5706, '报纸', '平生惟有赤子心', '孟秀敏', '中国财经报', '中国财经报', '李成瑞;农业税;吴家庄;减租减息;晋察冀边区政府;统计局长;工农大众;华夏诗词奖;', '李成瑞，1922年生，华北联合大学第一期毕业。1937年冬参加敌后抗战，曾任记者、编辑，后长期从事财经和统计工作。新中国建立后，历任中央财政部农业税司副司长、李先念同志秘书、国家统计局局长。业余爱好读诗、写诗，所作《千人断指叹》获首届华夏诗词奖一等奖。 “几', '2009-01-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAqyyszsSOWww4bwDB2o7Rm3xwWXa0AXcEtyni61ZXmzNeDqHzgO5VU8J8PQXckwx7u-qra8IpE4QuO4xmX9qiz8wAgw0rKnIkBgZB_sgitx8iAhMo4iDTNOKM1slReVpXoOlaIgucFuA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5707, '报纸', '见证不平凡的一年', '刘华', '团结报', '团结报', '多党合作制度;民主党派组织;“五一口号”;', '2008年，必将在我国的多党合作历史进程中留下浓墨重彩的一笔： 这一年是极不平凡的一年：南方雨雪冰冻、汶川特大地震、成功举办北京奥运会、航天员漫步太空、纪念改革开放３０周年……中国的坚强和勇敢感动世界，中国的胆识和智慧震撼世界； 这一年，各民主党派在', '2009-01-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICGCOiYll9RQhRbHxH_Lo-vKRr6V9F67jHFt2pk-9kc4gXqouoECxPbp4qREXopdcdeOwFWFyEOfhyox2B_wIDR5u49QEz8jdYoXy8TTHWyDx0-Y2Bc6BkcXU0lAIw4kXfISYmLRYxnCQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5708, '报纸', '抗震救灾 众志成城', '', '光明日报', '光明日报', '胡锦涛;抗震救灾精神;抗震救灾工作;中华民族;', '“没有哪一次巨大的历史灾难，不是以历史的进步为补偿的。”恩格斯的这句名言，在2008年中华民族惊天地、泣鬼神的抗震救灾斗争中，再一次得到了深刻印证。 5月12日14时28分，四川省汶川县发生里氏8.0级特大地震。面对这场新中国成立以来破坏性最强、波及范围最广、救灾', '2008-07-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDqjD3Euim5MTvwmgWX4BFkpXipxsYGPmOfRD8qkYPMdHoYcBx16klWm47ePmRsCOLL99qabEhxXAdSqpP3lWEAIwczQ5Xw20g4hLs1Bh4iBNzw65tFQkBwr29nkxvtznnuAh7guhFsqA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5709, '报纸', '忠诚于党和人民的审判事业', '王银胜; 张建忠', '人民法院报', '人民法院报', '忠诚于党;三个至上;', '在中国共产党成立87周年前夕，全国各地法院以及广大法官结合当前的大学习、大讨论活动，以不同形式开展了丰富多彩的纪念活动，讴歌中国共产党建党87周年的光辉历程。广大法官表示，要以对党、对人民、对法院事业绝对忠诚的态度，在思想上始终清醒、政治上始终坚定、工作上始', '2008-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICKAHlHPpas6GCjkhy1Fy--XS4Te1By0NjGblw1G2ZsRWRcWG3EB4EJvCtcTlMMf-fkz6US7PTGw0jdXhj69EeMIz2iGU8qYPtvscGcgNgol5SYu2s3u8_jpNGcLAkebOg2uY7tiwUAlQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5710, '报纸', '让党放心 让人民满意', '', '人民日报', '人民日报', '人民日报海外版;人民满意;党中央机关报;《环球时报》;', '在人民日报创刊60周年之际，6月20日，胡锦涛总书记来到报社考察工作，对人民日报60年来取得的成绩给予充分肯定。总书记说，人民日报具有辉煌的历史、优良的传统，一代又一代人为党的新闻宣传事业付出了大量心血、作出了重要贡献，是一支党和人民信赖的队伍。60年前', '2008-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAxTftEN90hCc7zs9sxXlHtBfKTDPd9MYB2mUeb1Ov_2dyxJXv0RUqzCDLw_lUSXNs1oowfdbqzrJg9BnySYrBRGboC71j6JXhKSSn6puHUYsV8SXxOdOXu3W26SSu02309zkaUcYcjhg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5711, '报纸', '河北红色旅游成为地方经济“助推器”', '乔木; 李勇', '河北记者站;', '中国旅游报', '红色旅游;红色旅游景区;景区景点;助推器;', '红色旅游异军突起，不仅大大促进了旅游产业的升温，而且也成了推动地方经济迅猛发展的一支新生力量。这是我们在河北采访红色旅游时得到的最深的感受。 河北是著名的革命老区，红色旅游资源比较丰富，有大小景区景点130余处。在这块热土上,曾涌现出像中国共产党的主', '2008-04-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBLoeb5gQVFo900RCKsYn76NZ3dY5AWEAcPnLW4O7Tt11vr4-CU66S_T2stmitlMUJjnxTka3YU4NJgWkea4XD32knTAWpqgZRxgB4TQPZQGowfQbYT_Fi0fip-k7jfcCh0Xh2ipVbbaw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5712, '报纸', '建设符合时代要求具有我军特色的最高军事学府', '贾永; 曹智; 黄明; 郭嘉', '人民日报', '人民日报', '国防大学;胡锦涛;中央军委;联合作战指挥人才;', '８０年前的南国深秋时节，国防大学前身——工农革命军第一军第一师第一团军官教导队在赣南红土地上诞生。 ８０年来，在以毛泽东同志、邓小平同志、江泽民同志为核心的党的三代中央领导集体和以胡锦涛同志为总书记的党中央关心下，当年的军官教导队与人民军队一起从', '2007-12-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA9QFTWsnS2md72vD5hyMbLy0fbsyONcTgxbALA4XFhs2GV4aYfgchUX6UQrV3OAbRP-iJhAdI9P1q6EECPU8ORomrOw_QzKXLkObPIfHzEnQrSjKB7cm2qcYXbj9WkYjwB20Z3No2ATQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争2_screened,中共七大-2_screened,瑞金_screened');
INSERT INTO `ds_article` VALUES (5713, '报纸', '长期执政之路的探索', '杨磊; 马连鹏', '中国经营报', '中国经营报', '初次分配;十六大以来;', '居安思危，中国共产党一直在强烈 的危机意识下，加强长期执政能力建设。 近年来，关于党的执政能力建设的讨论 再次成为热点。  不断强化的危机意识  时光倒流到2002年12月5日。 初冬的冀北大地，瑞雪飘飞。刚刚当选为 总书记的胡锦涛', '2007-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAyy_i3vERJrKFF5RY-xsB81gqUwAND88bfOFDRDdFZEanSRBbciPbO0kz-KfzFGDF3YxW9BV5sYCQoTadCDKPYGLI82EWyv0qdsC1oJFNWif_4T6oWrTYQaVmEHBwMPHi6uFkzigfKgg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5715, '报纸', '“舞动的路”牵引“致富的心”', '林妍', '中国经济导报', '中国经济导报', '旅游业;平顺县;平山县;红色旅游;农村物流;', '7月中旬，我们“老区新路”采访团 来到了太行山老区，当年党中央和毛主 席就是在这里指挥了震惊中外的三大 战役，为新中国的建立奠定了坚实的基 础。现如今，巍巍太行依旧，可山上却镶 嵌了无数条“舞动的路”，他们牵引着老 区的发展，牵引着老区人', '2007-07-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBffaDJh9BAi0v-qZrTjnfw6DWtt8wcIJJ_khwehM57NoT5jAsHRDgXHT5CDpRhFGUsingOUZW2tSuuRRRNBFLNC84zcUv6w0H0f0vZSyxuSL3O-glHBVrTiq8wFNs9uaVyYty9z0xBIQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5716, '报纸', '在纪念杨尚昆同志诞辰100周年座谈会上的发言', '李景田', '中央党史研究室;', '人民日报', '杨尚昆;中央军委;红三军团;党中央;中央办公厅;总政治部副主任;座谈会;', '今年，是杨尚昆同志诞辰１００周年。今天，我们满怀崇敬之情，参加中央举办的纪念座谈会。这里，我着重追忆杨尚昆同志从新民主主义革命到全面开展社会主义建设时期的主要功绩。一、在丰富的革命实践中锻炼成长，为红军建设和长征胜利立下功勋杨尚昆同志', '2007-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB1s-dze1NwvU56mpV25SGdeYlDH3sBMkxwKzLBJ38CQ80--YKuEOhh2yedoSYs8ofHWc7dUW6Dt0EqCzmTGfoCEHztMMyfbrRRBwcwkw9aPyuOysRpw7SHGD_EXZ-MGQP13cGjknVyzA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争2_screened,百团大战_screened,遵义会议_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (5717, '报纸', '新华书店的诞生与发展', '', '人民日报', '人民日报', '新华书店;《解放》周刊;张闻天;', '红军长征到达陕北后，党中央决定由张闻天、秦邦宪、周恩来、何克全（凯丰）等同志组成中央党报委员会并出版党中央机关理论刊物《解放》周刊。１９３７年４月２４日，《解放》周刊创刊，署名“陕西延安新华书局”发行。当年１０月即改名为“陕西延安新华书店”，新华书店的店', '2007-04-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICjIxMyVJzfP6F7yJBzKXyw5VbYbalE6uSlHYgeQeh7KfMRKODzJ8MgbsQY2kz5Sv33NAtF8U7H-5z4-rQxXW0Xq6hYfRuv6-QJ6J1d-GkTG_nJW5VsjDUiAGA2U2QaU7_i-dNLXpKA0w==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5718, '报纸', '红色通信 可歌可颂', '', '人民邮电', '人民邮电', '党中央;香山慈幼院;无线电通信;鲁班石;北平军管会;中南海;真空管;电信局;', '对于位于北京香山公园内原“香山慈幼院”理化馆旧址的香山电话专用局来说，3月23日是一个值得纪念的日子。58年前香山电话专用局在这里诞生，今天，香山电话专用局纪念碑在这里揭幕。“为党中央通信服务的香山电话专用局旧址”碑名与碑后面的那段文字把我们重新带回到58年前的', '2007-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICMe9tU-wxskX4Z82pZ4kbB7-WH5gIdmAhX6lVM4C9uR-6SfK-gyx325fUiWQsFKBpLjUAuprwdLaXe1i7pDeFwCpAtzex4mrUz0tlEJUBEwKtjJGf-fjIShLTkd3qPe1kHFk6ZQFWfvg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5719, '报纸', '薄一波同志生平', '', '人民日报', '人民日报', '决死队;晋冀鲁豫解放区;阎锡山;', '中国共产党的优秀党员，伟大的共产主义战士，杰出的无产阶级革命家，我党经济工作的卓越领导人，中国共产党第七届、八届、十一届中央委员，第八届中央政治局候补委员，国务院原副总理，原中共中央顾问委员会常务副主任薄一波同志，因病医治无效，于２００７年１月１５日２０', '2007-01-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB_iWhJ-_IcCNP5bEokkctdu85WJ5kWiK3DejMFVTb-BMhbOBSoqROtKAsm-Rg-0kJfC16wpFgHboBKwVtjjzxumkDndvHH0l5b1kPspAjvIgyEfcUre7tUSWGiFlfn3l4yZYkD5qfVcw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5720, '报纸', '红色政权的“耳目喉舌”', '曹智; 樊永强', '新华每日电讯', '新华每日电讯', '红中社;中央红军;清凉山;红色政权;新华通讯社;国民党军队;长征路上;中华苏维埃共和国临时中央政府;中央苏区;耳目喉舌;', '★红中社对中国古老土地上千百年来都未曾发生的新奇变化进行了及时、充分的报道  ★长征路上，红色的电波并没有完全终止……由于电台的出色工作，毛主席亲切地赞誉他们是“长征路上的灯笼”  ★这座林木掩映的小山，抗战时期曾被称为“新闻山”。它聚集着', '2006-11-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAg3ZZMI4kDAJe8hiLCD3yGb-cgywA0YEemsAeWmzII7tUAJg_l1ZgbuWDhGslM-hx1WYReJJMp8IoOApmkVl9r-EXlss77JAaj7T9DkB-75kkDgNkPsb4AXwhf3uV2gBZqzoWP9HS6fw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (5722, '报纸', '扎根沃土 百花争妍', '周婷玉; 卫敏丽', '新华社;', '人民日报', '文艺工作者;百花争妍;采风活动;文艺家;文学艺术事业;', '５年来，我国文学艺术事业硕果累累，百花园中飘满芳香。文学、戏剧、电影、音乐、美术、曲艺、民间艺术、舞蹈、摄影、书法、杂技、电视等各个门类的创作精品迭出，呈现一派欣欣向荣的景象。 与此同时，各类文学艺术活动也丰富多彩。广大文艺工作者深入基层采风、慰', '2006-11-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB7sPYSkuCSoV1kgdJoHFRlDd0cCfDq1LcMg_MwgIZfNz_gSh2TTKA4JRLKtP-t-KOii7zktf8l5ItKDglsTSKqrhoAx713XGV473Xm_CysuATdr7Thah8XK0oi9TIWTqTtHvu7lCpxSQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5723, '报纸', '穿越时空的壮歌', '冯春梅', '人民日报', '人民日报', '长征精神;红军长征;根据地;穿越时空;', '是什么让人们敬仰而来、昂扬而去，是什么让人们心潮澎湃、热泪盈眶，写下如此动情的留言：“震撼心灵！”“洗涤灵魂！”“人世间最美的一支壮歌！”……  从１０月１６日起，浓烈的激情在这里汇聚和涌动。每天，数以万计的观众从祖国的四面八方奔向中国人民革命军事', '2006-10-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICpMwwRU_KEO6GTP3Fa1RMxksIIpv69eITLxXJMvZ0ilzXhUaS_x64SeqKQHF2gDtntivTYUCbw3-TjQW3y1sdC2zcnwfgwERBChz2oN8SjthaNm25M8umIFD8ZqK0Y6vaFajGrvYHONQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,陈树湘_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5724, '报纸', '发扬长征精神 创造辉煌业绩', '', '中国青年报', '中国青年报', '长征精神;当代青少年;中华民族伟大复兴;红军长征;', '70年前，中国工农红军三大主力在甘肃会宁、将台堡会师，宣告震惊世界的长征胜利结束。长征实现了中国革命从挫折走向胜利的重大转折，谱写了中华民族历史上的壮丽篇章。70年来，无论时代如何发展，条件如何变化，在艰苦卓绝的斗争中培育的伟大长征精神，一直是激励我们战胜困', '2006-10-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAFtrV4zaQn1h8Va9U-n3oBQS_qQoJXEXHgY6ElmE6QGvmoMBNCTUyL4CxsrF1UeR5uqanL0JOBgH3zdTN4N9RizeXhKAjjO3ByUCQLWrlvdE-k87EJ4rKWHIcoyfgF-Yrfr79Y2pzWzQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,将台堡_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (5727, '报纸', '著名音乐家曹火星纪念园在平山县落成', '蔺玉堂', '光明日报', '光明日报', '曹火星;平山县;音乐家;', '本报河北平山7月1日电（记者蔺玉堂）《没有共产党就没有新中国》词曲作者、著名音乐家曹火星纪念园日前在河北省平山县西岗南村落成。面积10亩的纪念园坐落在通往革命圣地西柏坡的路边，纪念园建有题词碑、词曲碑、纪念亭、曹火星雕像和曹火星生平简介。  曹火星，19', '2006-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICJ5OtWMkXI36yt5HWqY1qH1KEuF2fgMiPC3oOzZBkOLMgOzyMbiPBy_GNKfo-Hsnb8hLwX54CUMX-twexZJ8ZH4EmislibBvgOKdZGYvENXygpUSVfFdJlohEtiPVDzUiv7bWBpeI81g==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5728, '报纸', '罗琼同志生平', '', '中国妇女报', '中国妇女报', '妇女运动;毛泽东;马克思主义妇女解放理论;妇女解放;妇女理论研究;全国妇联;', '中国共产党的优秀党员、忠诚的共产主义战士、中国妇女运动优秀的领导人、全国妇联原副主席、书记处第一书记罗琼同志，因病医治无效，于2006年4月19日23时45分在北京逝世，享年95岁。 罗琼同志1911年12月出生于江苏省江阴县，1932年毕业于江苏省立苏州女子师范学校后从', '2006-04-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB0LohhSBumxCeIMYpRatlHJNEHhiwl-Fp9TksVv9sZup7bPA5VCMTwHeCmvVrzxwXeqIYuEJQA8mcymsjGXUCKmSS4paN-a1ARy162798o3zuZbixvqMlGbbTqRdI2RzYjraAlmoC_Bg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,九一八事变_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5729, '报纸', '一万年还是要进行调查研究', '卢洁', '光明日报', '光明日报', '刘少奇;胡锦涛;周恩来;群众路线;中共中央文献研究室;亡党亡国;党的作风;思想路线;一切从实际出发;毛泽东;共产党人;“左”倾错误;革命家;', '编者按 2月6日，新华社播发了中共中央文献研究室编辑的《毛泽东周恩来刘少奇朱德邓小平陈云论调查研究》一书出版消息。今天，本报刊发中共中央文献研究室卢洁同志撰写的文章《一万年还是要进行调查研究》。文章既介绍了全书的主要内容，又系统阐述了我们党调查研究的', '2006-04-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAdDwdoV-K5sjbxuPfCQcmF6TDVBHG-VwDKtISYkuxu8Fa6hg9VkXYl4GEKuwLesLa4ct7UzjRtEHm6fWJRIeZaLE4x1yfC7UUlo153p9YvCA4VH8UeEbEPyLntl6bzDiH71-1rikZcjw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5732, '报纸', '解读太行精神', '殷泓; 王葆纯; 张传亚', '光明日报', '光明日报', '太行精神;中华民族;社会主义;八路军太行纪念馆;太行根据地;', '特邀嘉宾：  赵子平（中央组织部党建研究所副所长、研究员）  申维辰（中共山西省委常委、宣传部部长）  魏国英（山西八路军太行纪念馆馆长）  缘起　巍巍太行,雄踞华北,虎视中原,战略地位十分重要。60年前,中国共产党领导的八路军和', '2005-07-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA-3SP1aBLvq8QyHIect4iu11jXVBfW9RtwVwZZjIZB0_uULvj0FNkpF7Z1pEtMVI6nBEwKYTOMbN8dvaJSGs60WdYuWSCp1RuhIE-eCRJSWio6aJRkZ2hgCHlL33WfxA5loi6vySxCXQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5733, '报纸', '费孝通同志生平', '', '人民日报', '人民日报', '社会学家;人类学家;东吴大学;', '著名的社会学家、人类学家和社会活动家，中国民主同盟的卓越领导人，中国共产党的亲密朋友，第七、八届全国人民代表大会常务委员会副委员长，中国人民政治协商会议第六届全国委员会副主席，中国民主同盟中央委员会名誉主席、北京大学教授费孝通同志，因病于2005年4月24日在北', '2005-05-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDXT_ooqZy2vQlna6DTUo_2NGvrkmuQjBUS-A3gDV-D-O1gWJsCP3wIRDpxCC6MRxjVdQ5dQp3I1d0H9z2ysVA_gWVpwkPz6cSsULkCC_AVULN3RTZzwMgzS2BCxUfHVnmtRWL9muJwAg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5734, '报纸', '瞄准一流铸精品', '杨泳', '中国民族报', '中国民族报', '北京市回民学校;少数民族学生;非典时期;民族学校;空中课堂;成达师范;', 'T4月24日是北京市回民学校的80周年校庆，对这所坐落在 北京市少数民族聚居地区牛街的著名中学来说，这并不仅仅是 一个生日Party，更多的是对历史的回顾、未来的展望──E  从表到里的民族特色  “学校坐落在少数民族人士聚居的牛街，本', '2005-04-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICzP6vAB38Q_ZONGAgRi_dmBxrWY9srHCzz1g9uLoGu7FEymrSfQsTYL5HaHbAMnRY5DSvwYWEl3WvBr_dbTYPE_TiwGXDC1s04OLhgn6P_t_g4aUwB-eYzqQU9WwP1U5qockDAUnaSqA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5735, '报纸', '“红色电站”引发“旅游经济”升温', '刘富亭', '中国水利报', '中国水利报', '发电厂;平山县;旅游经济;', '提起“平山”来，可能会有 好多人不知晓，要是说起党的七 届二中全会旧址，党在农村最后 一个根据地──西柏坡，恐怕不 知晓的人就不多了，西柏坡就在 河北省平山县。西柏坡西南20 公里处有座■■水发电厂，这座 小型水力发电厂因建在■■水河', '2005-04-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC_u2npEoA6M3wF6FpytCOP0ItCnhb_OeXxV7qgDbUABhbUm4yq2JZHg4TqYRyg6VPyu0SdWVx5jrLetRk_joukxkPY6z_ywwbULUDGXlyEuNS08IAhApDi3YuUwF6jhK43DcY57GLgoQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5736, '报纸', '红色旅游 市场潜力巨大', '意赅', '消费日报', '消费日报', '红色旅游景区;黄金周;市场潜力;', '为充分挖掘和利用革命历史文化资 源，广泛开展爱国主义和革命传统教育， 大力弘扬和培育伟大的民族精神，不断 增强民族凝聚力，推动革命老区经济社 会协调发展，中央办公厅、国务院办公厅 去年底印发了《2004－2010年全国红色 旅游发展规划纲要》，', '2005-03-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICkHyUN6dUdIjgSBdswHyg6t69aDjm70grIU6489L-z8vIB7j8Pv1sCPjFGuJd-EM-AkOp7gCbWAe-iWFphsadvZ0GZPv0uTfiKTiprjjOvreSzRpO9liKzPV9AbljkYIOoQKtknJ9Zbg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5737, '报纸', '河北精心打造十大红色旅游线路', '王民', '人民日报', '人民日报', '红色旅游;河北省旅游局;', '新华社石家庄2月21日电　记者王民从河北省旅游局了解到：2005年河北省将重点打造十大红色旅游线路，力争建成国内高水平、具有感染力和震撼力的红色旅游胜地。 这十大红色旅游精品线路分别是西柏坡、八路军129师司令部、白洋淀、冉庄地道战、狼牙山、董存瑞烈士纪念地、', '2005-02-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDY_mQQ-kdRmQFrH4sTcPlMlFhOBXl8NvMrWO7PARUHLoIi4k4JJyVuyibh5LIOqY0HyBGn0x2mLwyaCiSPvqdlw98xttGqd-cFl4QoWhXsCUS4_ER058E1E0NlPPHp7Q3FzXzfVVsSPw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,狼牙山_screened');
INSERT INTO `ds_article` VALUES (5738, '报纸', '西柏坡将军岭红色展览推动旅游产业', '姚意克', '国际商报', '国际商报', '将军岭;旅游产业;平山县;', '本报讯：记者姚意克报道：尽管 晚秋已至，但位于河北省平山县将军 岭红色旅游区的各地游客却依然不 断。据了解，这条辐射华北、连接晋冀 两省的红色旅游通道──西柏坡将军 岭爱国主义教育基地，以革命历史题 材的系列展览为景观，自2003年正式', '2004-11-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDoAr7WkBTTyUnGnNp59Jjm2nYKaDG5MQJpNlvCJDBoOmzOMFudlUoNYGaLsxtocx8fpmzBIa5IqdjC20R_UrNUHnbmrYXIVbYP4AjrTGR-8dscGRcnQT45aEx_Z9hNwlHXTGmp5tnNZw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5739, '报纸', '“经典中国”宣传报道在网上引起强烈反响', '', '人民日报', '人民日报', '宣传报道;', '新华社北京7月12日电　今年是中国共产党建党83周年、新中国成立55周年、红军长征出发70周年和邓小平同志诞辰100周年纪念。为进一步宣传中国共产党的奋斗历程，弘扬革命传统，展示新中国伟大成就，在中宣部的统一部署下，自6月27日起，各媒体组织了以“经典中国”为主题，以弘', '2004-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDxdPb-HbaSg9dbusN5uFMTdjkqrtSPi8-TOWMbijMGvbDd7gBH73eYuHtGpyHwcfChyaXJRyWLAkxKe_WR99NsQlWE0M8ZATNKDE9MACHqJAR_SjBYpl7B1ocGS9X86BK-o8Bf3kPYCQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5740, '报纸', '大力弘扬延安精神', '', '人民日报', '人民日报', '延安精神;全面建设小康社会;', '继西柏坡精神巡回展览开展之后，《延安精神永放光芒》大型展览在北京展出。连日来，参观展览的干部群众络绎不绝。人们深情回忆中国革命走过的光辉历程，热情赞颂我国改革开放取得的伟大成就，充分表达大力弘扬延安精神，全面建设小康社会的共同心声。延安是中国革命圣地。从1', '2004-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAvjd1aBwxHZ8ct2tQu_tCLLSBU6OoVpf147uE0g6muTm1L99vC-F-iUL77EICj_m6RWwbj1tDOiYHIt3yseuosOtRo5zNzFNglthLL6h4zbfWcOUNgOUa6gLzFtQzAAl5nk43x-J263w==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5745, '报纸', '继续推进马克思主义的中国化', '', '学习时报', '学习时报', '马克思主义;中国化;毛泽东教育思想;《论十大关系》;中国社会主义建设道路;毛泽东精神;', '马克思主义中国化道路的伟大开创者 □中央党校国际战略研究所教授 金春明 在毛泽东留下的众多财富中，我认为最具有根本性的，有长远指导意义的，是他创造性地开拓出的马克思主义中国化之路。 二十世纪之初的中国，最需要的就是革命理论。十月革命给中国送来', '2003-12-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAIV3v9SefYJ6mgsKCXw-gVIpjLtslW8TTNYQrQWKQgHiX_bHp1Mp4T60d4PLonUnE4WYSEZ1LZ676GxHZIUprg75IoGh_ICxIm4BSE9A3syOYlV7KhoodHtKCDsamiNU8hye_Mj5jhAw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5747, '报纸', '培育时代英才　书写教育华章', '李海秀', '光明日报', '光明日报', '海淀区;推门课;北京市;家长会;录取率;领导班子;', '11月7日，是一个让育英全体师生和历届校友难忘的日子。他们为之工作、从中学习的学校就是在1948年的这一天，诞生在河北省西柏坡党中央驻地。沐浴着解放战争的烽火，伴随着祖国现代化的前进步伐，英姿勃发的育英学校，迎来了55周年华诞。  55年弹指间。当年第一任校长刘', '2003-11-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDbnEJE2-KFlXU_AjuxkogelGYYsoYl2cjviSacp-ASxL3vf2jn1BKZd5nf6644uuX7a1XCIu9vzYV95YvxKY1736xnf2uuBZUnTXcyaUnHPBcdF62umwJmwhQhBVO0Af3qOp8BznA0mQ==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5748, '报纸', '关于艰苦奋斗精神', '王孝忠', '湖南省水利厅;', '中国水利报', '党的先进性;共产党人;执政为民;廉洁从政;民营水利;党员的先进性;建立和完善;', '艰苦奋斗是中华民族的历史传统 在数千年的历史长河中，中华民族以艰苦奋斗著称于世。数千年的中华文明史，实际上就是一部艰苦奋斗史。夸父追日、精卫填海、铁杵磨针等，这些神话与传说，是中华民族的精神动力；浩瀚的中华民族文化表明，一个民族的兴旺发达离不开艰苦奋', '2003-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICOuvyHkTAQ2Mvq-o2VIkeqUMrg00lf9QhYulFp_emnoGBesWxYlulk08NBnb2vj8RY59rmsKVPvs4aNfrc7-wL4LFBGWs1S9lA8w4hoFrh6WW1im3eR80dmJm31dDOE7oChX7gFTsF2w==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5749, '报纸', '胡锦涛、温家宝主政100天', '徐昙', '中国经营报', '中国经营报', '胡锦涛;温家宝;', '中共中央总书记胡锦涛、国务院总理温家宝等新领导集体主政三个月以来，内政外交呈现的“新政”气象得到了国内外各界的肯定、赞赏和拥护。 亲民的高度：执政为民 从一个细节可以看出新领导集体和前任的区别：胡锦涛和温家宝经常的行礼方式是鞠躬，而非惯常的挥手。', '2003-07-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICPsp-HzyUWghkj1YP7DZX2XHI3YFSMkZm64_U6st9F9hqTemw8pDFVKenPBK49sec2K4zVnya8x4CTivd3Ik0jc5-_XYflAjy4UI1cD-wzT-HfCgw3CYfO--wt2FptYz5Ow3y-HvIMKg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5750, '报纸', '老区人民 共产党永远的挂念', '师晓京', '农民日报', '农民日报', '生态家园;共产党;', '“七一”前夕，记者来到革命老 区河北省平山县西柏坡镇。这里曾 是中国革命最后的一个农村指挥 所，新中国从这里走出去。  走进柏里村，不少农家正在忙 着修沼气池和改厕、改圈、改厨房。 瓦工的敲击砖瓦声，木工的刨门板 声，施工', '2003-07-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICVi48GVExFVVNgdv-i85XIER4hjos-W3E54U9zv6770GGsCzpza91g9ytuXZrDyABx8a6syeQ0rqI43rwj6DeOxeaFHPYWNGHWpvND68m2fhPfR2L80at5sal-3Vnr22qZTq60OBYpDA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5758, '报纸', '亲切的关怀巨大的启示', '高初建', '中华工商时报', '中华工商时报', '胡锦涛;非公有制经济人士;全国工商联;黄孟复;中共中央政治局常委;', '12月23日，北京城内飘着漫天的雪花。上午10时多，中共中央总书记胡锦涛，中共中央政治局常委贾庆林，中共中央政治局常委、书记处书记曾庆红，中共中央政治局候补委员、书记处书记王刚，在中共中央统战部部长刘延东等同志的陪同下，冒着严寒，迎着纷纷瑞雪来到全国工商联机关', '2003-01-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDNLsOA0EU-MZW_w3rRHaufdWqwUqLBCRw9fb5axm4NTci1sKm1DVB-AHK8S2L4mketVJdX4LYGzn4N3szhZE2baOlPSla8klZIu_kKVejsvZid5gjYLk6arPBWwjDLCtvOD0x9T16b5Q==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5762, '报纸', '圣地西柏坡　红色将军岭　打造“红色旅游通道”', '李玲', '中国旅游报', '中国旅游报', '将军岭;红色旅游;爱国主义教育基地;', '河北省平山县是有着光荣传统的革命老区，红色圣地西柏坡就坐落在平山境内。目前，随着一项以弘扬爱国主义精神、讴歌革命历史的宏大红色旅游项目———“将军岭爱国主义教育基地”的开工建设，平山———这个昔日的革命老区将焕发出新的生机。  平山县地处太行山深处，其', '2002-09-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIASp3Mc-YZWh4uiFecMVPxm2j3vHeeKk3h5Lh8vVmvKQjaESAK9lC3DlFmCeYTI-Ef3imfibf1q3WVvQS_6zWY7GX6yF6OIIxDij_i_iJN2uqEJKRIqFMa-7sNsiMsBrbEeqtPdGXpDHA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5764, '报纸', '以史鉴今 资政育人', '谷安林; 董宏君', '中央党史研究室;', '人民日报', '建设有中国特色社会主义;红色旅游;宣传教育工作;党史工作;毛泽东思想;马列主义;加强和改进;党史学习;中国共产党;', '董宏君：去年以来，中国共产党诞生地嘉兴，革命摇篮井冈山，革命圣地延安、遵义、西柏坡等地都成为旅游热点，很多游客认为，这些与中国革命、中国共产党密切相关的地方，具有更多的精神文化内涵，希望借助这样的旅游重新感受我们党所创造的惊世辉煌。请问，对这样的“红色', '2002-07-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDwOaBxMOO5IHOdkDOIIfngG-AuOFcSLcVhokrOYqtYTeULAcEh2eS44x5z9H4bfnGPpGn9si-lnxOT7Blj6-o6-Bf3u_wyQ0V_4rxyhK6eI3Gg5cWYP18no3JSD92pineSYymUkl4fKw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5766, '报纸', '工商联事业的大胆探索', '胡德平', '中共中央统战部;', '中华工商时报', '非公有制经济代表人士;工商联会长;人民团体;非公有制经济人士;工商联;', '2002年全国工商联换届工作面临两大变化。一是解放后，工商联作为人民团体和统一战线组织，既带有鲜明的中国特色，也始终走着一条创新之路。1947年解放战争之初，哈尔滨就成立了工商联。1949年2月毛泽东同志在河北平山县西柏坡接见苏共代表时，就谈到新中国成立后，准备成立', '2002-04-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBjY2d5X4NnQFW8ZrEkvS55LUQ_3oiQg3g-HDIwW3BW72IzubVNCG8uORSVtRSTnGSapqmK2vZEbRdDovNrfVAIR-fUMNkK43ZeJapSG4TDAOKQwBoy3HCoeWmedDxMHyrZ6oNtB5tfCw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5767, '报纸', '理论家黄铸 俯仰无愧天地', '华兰', '中国民族报', '中国民族报', '李维汉;统战理论研究;统战部;理论家;', '初出茅庐  1953年5月的一天，一份关于《资本主义工商业中 的公私关系问题》的报告吸引了毛泽东主席的目光。报告 中提出了国家对资本主义工商业改造的两套办法（即通过 国家资本主义的形式，实现对资本主义工', '2002-01-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB5HauI78L01o_Rgl8jPTddT4_ztJIvz7OLxVzVxvqWMEOc406w4YwRncLpFfQCaCtCLekqEMKkdghHurcO7f1GRmhouchrzCcnQJbCLsItR8GHJsBng_VhLjkxMJ5Vy-Ltv8f-ai_fFA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5769, '报纸', '时代的旋律 七月的共鸣', '陆彩荣', '中央电视台文化视点节目组;', '光明日报', '文艺作品;共产党;红色经典;', '红旗如画，岁月如歌。刚刚过去的七月，以庆祝中国共 产党建党80周年为背景，以江泽民总书记“七一”讲话为契 机，中华大地掀起了强劲的文化冲击波。  从长城内外到大江南北，从珠江之滨到天山脚下，全国 各地文艺舞台热闹非凡', '2001-08-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIABha2gBz7H905UZkWcrxonBsIPMmrIbp44uZwKgAq5dUZzpHRv2h1y0PZcLNSIRSa6BVQgJNXxGqDgLoGl0IOwPYGooj4gzErjDitZv3rgucFFOlIu1iQyZlcz7zMKdkW0h03w3_vTyw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5770, '报纸', '感受忠诚', '施乾元', '中国消费者报', '中国消费者报', '开国大典;公安民警;前进巷;', '长时间的炎热让古都北京显出 了几许平静。在一条曾经百年沧桑的 胡同──东交民巷中，以首都公安事 业所走过的艰辛历程及所取得成绩 为主题的北京警察博物馆，在一样平 静的细雨中迎来了正式开放后的首 批客人', '2001-08-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIALInQKfguN2pd17Vomdx2gKaMbnB2KamECw-O1WLofflM3UxaM4UGQOxktFAXumbTGL5hwUsOQdHhNtaFIs-cuHNEqY8zrEDztbfeu6tcqNOCT-jD6l8eRiuDf2S_9Lj3GJnJexegwZg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5772, '报纸', '在先进文化旗帜下发展的中国电影', '张伟峰; 汪泾洋', '解放军报', '解放军报', '电影工作者;故事片;共产党人;中国共产党;', '风云激荡的壮丽画卷  （中国共产党的创立及大革命时期）  反映这个时期的影片首推彩色故事片《开天辟地》。这部 长达170分种的故事片，表现了从“五四”运动到1921年7 月1日中国共产党成立的全过程。影片将这风云激荡的历', '2001-07-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICk-DxcwNqUMJAhnaywWej0tA8XMJIHqEYkShObuqdEAtJN5fP8MIctdmkxiDGg5Kl2KELwh66L9bA6n-xAjzcQG23-hyiDwE5-PqdSN8L2sAW7HYenxPmO5IQvj4yyOUVUZN4sUelH7w==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,四渡赤水_screened');
INSERT INTO `ds_article` VALUES (5773, '报纸', '统一战线：从胜利走向胜利的法宝', '', '本报编辑部;', '人民政协报', '革命统一战线;抗日民族统一战线;', '1939年，毛泽东在欢送一批青年从 延安奔赴抗日前线的集会上说：“当年姜 子牙下昆仑山，原始天尊赠了他杏黄旗、 四不象、打三鞭三样法宝，现在你们出发 上前线，我也赠三件法宝，这就是统一战 线、武装斗争、党的建设”。  中国共产党人', '2001-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICrFcl_1kjoxPA9XL47aJ9zQllAXrKjwN6feRMCDbmOIRPhUQZTa3JqRwge_W3Js1_luyeyKj8Vsnpz7BZNhUKTXAABJeE80lWs4gI_s3uiXWxkBBEfRVvUtQOWHAv8ILspdpbuLRuBxw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争3_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (5774, '报纸', '“只有跟着共产党走 才是在正道上行”', '', '中国民主促进委员会中央委员会宣传部;', '团结报', '民进中央;中国共产党领导;', '今年七月一日是伟大、光 荣、正确的中国共产党成立八 十周年纪念日。八十年来，中 国共产党带领全国人民赢得 了民族独立，建立了新中国和 社会主义制度，开辟了建设有 中国特色社会主义道路，实现 了国家富强和人民幸福。历史 和现', '2001-06-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBVAz3pW9YUochec-bz95lqIeKJoUsAtfumQD8D1pcqDRiZlrdVQRD3pens-Wevi-xcbyjkCygLMkEw8QoNUXNLDC4ltRLhiumSMGp5q5yJkECyqZFieptcJsVcTgSTASqR1Kbsm77Lsw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5775, '报纸', '火红的事业', '', '本报编辑部;', '中国财经报', '预算外资金;工业化建设;党中央;国务院;分级财政;共和国;', '建设财政：共和国大厦的基石  1949年10月1日，中华人民共和国成 立。此时，一个颇有名的民族资本家放言：“共 产党军事100分，政治80分，经济打0分。”显 然，“马背上得天下”的中国共产党人面临着严 峻的经济考验', '2001-06-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDY5YS6v70Wv6OchYR6Y33Zef7zUgOXuwt5mCPY1nGRNGlufoqlVWHBoGzgpOViYMmKgMG6cNOX1-L94CEepl_CPBaA4DsO1mkh9OsS0AmJDDO5xeLI4Cwt2sjWyQF7Bj4xs6SRcMOMEg==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5776, '报纸', '学法用法为治国', '林世钰', '检察日报', '检察日报', '宪法和法律;执法水平;', '中共中央党校教授史泰丰：党领 导人民制定宪法和法律，并在宪法和 法律范围内活动。领导干部不懂法用 法。就不能担负领导重任。现在中央 党校学员都主动要求增加法制课的 分量，学习法律的热情', '2001-06-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBaF94mdwyD-6u5zZH-cgQpjIf5XhPktUcoQbzATcShGo15zZDwMx3arMv8U9_xdBOXUx4RW3PB5CWbRgctF6Vuylv4no92oXv_EMJBFdgxGsLf8oqDZliLsma3PDoWBJROSoEjfV47XA==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5777, '报纸', '中华民族的脊梁', '李术峰', '新华社;', '新华每日电讯', '中国共产党领导;民主人士;中华民族;建设有中国特色社会主义;江泽民同志;社会主义道路;阿沛·阿旺晋美;工商业者;多党合作;雷洁琼;', '历史长河浩荡而过，一种 感情却在岁月的奔流中，愈益 浓厚；一种信念却在时光的洗 磨下，历久弥坚……  在中国共产党建党80周 年到来之际，我们走近一位位 老一代党外人士', '2001-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICQ5hcdJ38Ir4HAIfJ8b_Yhqktlxs2VE_JyZ9zhYmjT_xEoZ7-mH0R-C9ZR42zy0NmsH-jkfA7NGp6Ojss-WPuiIjyuTKvgQ29SyFgd7EJoiot6ke2PBQAYitsCwZOpr-v30ZDLKUuAZw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened,抗日战争3_screened');
INSERT INTO `ds_article` VALUES (5780, '报纸', '不断挖掘爱国主义教育资源', '', '新华社;', '新华每日电讯', '爱国主义教育资源;共产党;示范基地;文物史料;', '中宣部昨天公布了第二批全国百个爱国主 义教育示范基地名单，引起社会各界广泛关注。 为使大家更好地了解这方面的情况，本社记者 专门采访了中宣部负责同志。  问：请您谈谈在建党80周年前夕，中宣部', '2001-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICNt74mK_vLcrZnefQMsqYWIODfv1j_CDIUsXgdj7tg5p9BQSPiUKtupJR0icNAaxwUDHakeoXgeOaR6HelrurB2z1XW66lcxOhYTx1APDha4phr8P1u-jauxLUALuVkbcrWfcVjHXmaw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5782, '报纸', '40个重点文艺项目推出', '', '中国文化报', '中国文化报', '文艺创作;中国共产党成立;', '本报讯：中宣部、文化部、广电总局、 新闻出版总署、中国文联、中国作协5月 23日在北京联合举行新闻发布会，隆重 推出纪念中国共产党成立80周年的40 个重点献礼文艺项目。  这些重点文艺项', '2001-05-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBDThPcz60ecL0rsJ1b8W7fOF39O6gXRNQcZrIDgpB31ifLaLKPW4SzBxKrjPinra4fgmdVvYFFM9FwfIKviZySZEbOUOfebQubV4lCSdazPPMAclusv3Tz-YHgkfEjmUqSBJd8Yw_E6g==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5783, '报纸', '《西柏坡与新中国》', '', '光明日报', '光明日报', '有中国特色;《西柏坡与新中国》;党中央;', '河北师范大学王玉平教授主 持完成的1998年度国家社会科学 基金项目《西柏坡与新中国》，其 最终成果为72万字的同名专著 （中央文献出版社1999年12月出 版）。这项成果通过梳理研究中国 共产党在西柏坡时期的重大革命 活动和卓越的理论建', '2000-08-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAgNylDzxTM3GLm9UBJZuZMdpO-Dok4tMStH3piirzOBKJVfkYktLJCb8jUuKemoPJaBfcd0UY_b73ax_xLaU2xcEAAedGHk-SVUSwzpJgcYIoacYoJUC2lB2j-dMJ8JFkuRe0XNVK1ow==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5784, '报纸', '马克思主义理论家——胡乔木', '程中原', '光明日报', '光明日报', '胡乔木;马克思主义理论家;中国文字改革委员会;', '胡乔木原名胡鼎新，江苏盐城 人。1930年就学于清华大学历史系。 1932年加入中国共产党。1933年转入 浙江大学外文系，因领导学生运动于 1935年初被迫离校，即到上海参加左 翼文化运动，曾任文总党团书记、中共 江苏省临委委员。1937年5月奉调赴', '2000-07-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAgup3gGQVfVWO3Wszkz1dgRXKkKLVQqjbdwHZuSEtMQbWUDaGtyxFp7hbHH2Qj-MSsjwi-8n2_Lvhj1qep1z4MloU9LPotxlySR2TGaU26VBUwtVpMZLkwBZsNvrAuPriytW8vNhZMdw==&uniplatform=NZKPT&language=CHS', '西柏坡_screened');
INSERT INTO `ds_article` VALUES (5786, '报纸', '创新传承方式 弘扬红色精神', '徐晓', '中国旅游报', '中国旅游报', '红色旅游;红旗渠精神;林州市;红色资源;红色精神;传承方式;', '一曲清水绕群山，红色精神永相传。林州孕育了“自力更生、艰苦创业、团结协作、无私奉献”红旗渠精神，这种精神是中原大地上动人的精神图腾和耀眼的精神高地，是中国共产党人精神谱系中的闪亮坐标。 近日，2023全国红色旅游宣传推广周活动在河南林州红旗渠精神营地举办。活', '2023-10-30 08:00:00', 'https://link.cnki.net/doi/10.28109/n.cnki.nclyb.2023.002271', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5787, '报纸', '石家庄：“赶考”之路启新程', '李凤双; 曹国厂; 齐雷杰; 杜一方', '新华每日电讯', '新华每日电讯', '石家庄;滹沱河;正定古城;石家庄市;古城遗址;太平河;魅力之城;', '新华社石家庄9月24日电（记者李凤双 曹国厂 齐雷杰 杜一方）2013年7月11日，习近平总书记到石家庄市正定县调研之后，来到革命圣地西柏坡，在同县乡村干部和群众座谈时表示，“从实现‘两个一百年’目标到实现中华民族伟大复兴的中国梦，我们正在征程中。‘考试’仍在继续，所', '2023-09-25 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2023.005811', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5789, '报纸', '中国共产党如何解决大党独有难题', '王霞', '中国纪检监察报', '中国纪检监察报', '全面从严治党;政治生态;中国共产党;习近平总书记;本领恐慌;干部教育培训;党的领导;', '我们党已走过一百多年的光辉历程，是世界上最大的马克思主义执政党，大要有大的样子，但大也有大的难处。在党的二十大报告中，习近平总书记向全党提出必须时刻保持解决大党独有难题的清醒和坚定的重大命题。在二十届中央纪委二次全会上，习近平总书记进一步从“六个如何始终', '2023-04-17 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.001401', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5790, '报纸', '准确把握“六个如何始终”的重大意义和深刻内涵', '', '中共中央党史和文献研究院院务会理论学习中心组;', '中国纪检监察报', '纯洁性;执政能力;党中央;全面从严治党;习近平总书记;马克思主义政党;深刻内涵;', '“大党独有难题”是习近平总书记提出的重大理论命题。习近平总书记在党的二十大报告中指出：“我们党作为世界上最大的马克思主义执政党，要始终赢得人民拥护、巩固长期执政地位，必须时刻保持解决大党独有难题的清醒和坚定。”在二十届中央纪委二次全会上，习近平总书记从新', '2023-04-06 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.001253', '两个务必_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5793, '报纸', '解决大党独有难题的创造性探索', '王昊魁', '光明日报', '光明日报', '全面从严治党;习近平总书记;使命任务;时代化;马克思主义中国化;', '习近平总书记在二十届中央纪委二次全会上强调，如何始终不忘初心、牢记使命，如何始终统一思想、统一意志、统一行动，如何始终具备强大的执政能力和领导水平，如何始终保持干事创业精神状态，如何始终能够及时发现和解决自身存在的问题，如何始终保持风清气正的政治生态，都', '2023-01-16 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.000197', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5798, '报纸', '解放思想，奋发进取，加快建设经济强省美丽河北', '', '人民日报', '人民日报', '加快建设;经济强省;', '讲述红色故事 传承红色基因 本报记者 徐运平 张腾扬 雨后西柏坡，艳阳高照，松柏苍翠。柏坡岭下的红旅小镇上，大型沉浸式实景演出《梦回西柏坡》正在上演，吸引了众多观众驻足观看。“最后的一碗米用来做军粮，最后的一尺布用来做军装，最后的老棉被盖在担架上，最后的亲骨', '2022-07-13 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.007471', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5799, '报纸', '中国共产党基层党建的百年实践与启示', '贾钢涛; 高红波', '北京市习近平新时代中国特色社会主义思想研究中心;北京化工大学马克思主义学院;西北工业大学马克思主义学院;', '光明日报', '基层党建;基层党组织建设;中国共产党;', '习近平总书记指出，“党的基层组织是确保党的路线方针政策和决策部署贯彻落实的基础”，要把“基层党组织建设成为宣传党的主张、贯彻党的决定、领导基层治理、团结动员群众、推动改革发展的坚强战斗堡垒”。在中国共产党百年发展历程中，重视基层、强基固本，是我们党的光荣', '2022-07-07 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2022.005623', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5800, '报纸', '深刻认识跳出历史周期率两个答案相互关系', '薛鹏', '中国纪检监察报', '中国纪检监察报', '历史周期率;全面从严治党;反腐败斗争;相互关系;', '习近平总书记在十九届中央纪委六次全会上发表重要讲话指出，一百年来，党外靠发展人民民主、接受人民监督，内靠全面从严治党、推进自我革命，勇于坚持真理、修正错误，勇于刀刃向内、刮骨疗毒，保证了党长盛不衰、不断发展壮大。习近平总书记的重要论述，深刻揭示了跳出历史', '2022-01-20 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.000259', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5804, '报纸', '从党的奋斗历史中汲取前进力量', '张洋; 赵兵; 赵成; 孟祥夫', '人民日报', '人民日报', '习近平总书记;中国特色社会主义;党史学习;党员领导干部;奋斗历史;', '百年大党，风华正茂。千秋伟业，再启新程。 2021年，在庆祝我们党百年华诞的重大时刻，在“两个一百年”奋斗目标历史交汇的关键节点，以习近平同志为核心的党中央作出重大战略决策：在全党开展党史学习教育。 “回望过往的奋斗路，眺望前方的奋进路，我们必须把党的历', '2021-12-25 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.013506', '两个务必_screened,西柏坡_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5805, '报纸', '始终掌握新时代新征程党和国家事业发展的历史主动', '王灵桂', '中国社会科学院;', '学习时报', '全面从严治党;纯洁性;党的先进性;习近平;党中央;中国共产党;马克思主义基本原理;党的领导;马克思主义中国化;中国特色社会主义;', '党的十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》（以下简称《决议》），全面总结我们党一百年来走过的光辉历程、取得的重大成就、积累的历史经验，是指引我们以史为鉴、开创未来、创造新伟业的马克思主义纲领性文献，是新时代中国共产党人牢', '2021-12-13 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002342', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5820, '报纸', '满怀信心踏上新的赶考之路', '何显明', '浙江省习近平新时代中国特色社会主义思想研究中心;', '人民日报', '全面从严治党;奋斗目标;中国共产党;习近平总书记;', '习近平总书记在庆祝中国共产党成立100周年大会上的重要讲话中指出：“过去一百年，中国共产党向人民、向历史交出了一份优异的答卷。现在，中国共产党团结带领中国人民又踏上了实现第二个百年奋斗目标新的赶考之路。”我们一定要深入学习贯彻习近平总书记“七一”重要讲话精神', '2021-08-13 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.008537', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5822, '报纸', '不断推进新时代党的建设新的伟大工程', '', '人民日报', '人民日报', '习近平总书记;党的组织路线;毛泽东;全面从严治党;党的建设;中国特色社会主义制度;基层党组织建设;党中央;党建理论体系;中国化的马克思主义;', '根据党中央安排，中共中央组织部、全国党建研究会9日在京召开庆祝中国共产党成立100周年党的建设历史经验研讨会。会议指出，要深入学习贯彻习近平总书记“七一”重要讲话精神，深入总结和运用100年来特别是党的十八大以来党的建设历史经验，不断推进新时代党的建设新的伟大工', '2021-07-20 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.013826', '两个务必_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (5824, '报纸', '有志气骨气底气交出新答卷', '蒲实', '学习时报', '学习时报', '习近平总书记;共产党;', '习近平总书记在庆祝中国共产党成立100周年大会上发表重要讲话，全方位、全过程、全景式、史诗般回顾了中国共产党百年奋斗的光辉历程，号召继续弘扬伟大建党精神，以史为鉴、开创未来，带领全体共产党员以坚定的意志、清醒的头脑、铿锵的步伐踏上新的赶考之路，向党和人民交出', '2021-07-16 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001292', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5825, '报纸', '做百年大党忠实传人', '姚焕', '中央党校(国家行政学院);国务院国有资产监督管理委员会党建工作局(党委组织部、党委统战部);中央企业团工委;', '学习时报', '党的作风建设;中国特色社会主义;党的领导;习近平总书记;中国共产党;敢于斗争;', '习近平总书记在庆祝中国共产党成立100周年大会上发表重要讲话，深情回顾我们党团结带领亿万人民筚路蓝缕波澜壮阔的奋斗历程，庄严宣告引领全国人民迈向第二个百年奋斗目标、实现中华民族伟大复兴的行动纲领，重新标定我们党奋进新征程、开创新纪元的坐标原点。在新的赶考之路', '2021-07-12 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001244', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5826, '报纸', '走出现代化新路', '韩亚栋; 吴晶', '中国纪检监察报', '中国纪检监察报', '社会主义初级阶段;第一个;共产党人;全面建成小康社会;奋斗目标;四个现代化;中国共产党成立;中国式现代化;', '2021年7月1日，在庆祝中国共产党成立100周年大会上，习近平总书记代表党和人民庄严宣告：“经过全党全国各族人民持续奋斗，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会，历史性地解决了绝对贫困问题，正在意气风发向着全面建成社会主义现代化强国的第二个', '2021-07-06 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003211', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5828, '报纸', '华北人民法院：共和国最高法院的前身', '刘婧', '人民法院报', '人民法院报', '人民法院;最高法院;平山县;共和国;中央人民政府;', '点睛 河北省平山县城城南1公里处的平山镇王子村，曾是华北人民政府的所在地。因为华北人民政府是“中央人民政府雏形”，这个小山村得以蜚声中外。 在这个村子里，1948年9月到1949年2月，革命前辈们用短短不到5个月的时间，为新中国的最后成立做好了政治、经济、民政、', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.003049', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5830, '报纸', '砥柱中流', '李鹃', '中国纪检监察报', '中国纪检监察报', '全面从严治党;党中央;理想信念;红军长征;反腐败斗争;', '中国特色社会主义最本质的特征是中国共产党领导，中国特色社会主义制度的最大优势是中国共产党领导，党是最高政治领导力量。 从石库门到天安门，从兴业路到复兴路，从50多名党员到9500多万名党员，中国共产党团结带领人民，创造了举世瞩目的伟大成就，书写了一个世纪的奋', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003146', '两个务必_screened,西柏坡_screened,强渡大渡河_screened,血战湘江_screened,会宁_screened');
INSERT INTO `ds_article` VALUES (5831, '报纸', '铸就百年辉煌 书写千秋伟业', '', '人民日报', '人民日报', '习近平总书记;中国共产党;中国特色社会主义;奋斗目标;千秋伟业;中华民族;马克思主义;发展史;', '一世纪风雨兼程，九万里风鹏正举。在全面建设社会主义现代化国家新征程顺利开启的重要时刻，我们迎来了中国共产党百年华诞。站在这个重大历史节点上，回望过往的奋斗路，眺望前方的奋进路，我们心潮澎湃，豪情满怀！ 1921—2021，百年成就辉煌。从建党的开天辟地，到新中', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006791', '两个务必_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (5832, '报纸', '“为什么大地春常在”', '王春霞', '中国妇女报;', '中国妇女报', '疫情防控;党中央;长征精神;延安精神;精神财富;抗震救灾精神;抗洪抢险;春常在;', '穿越历史的沧桑巨变,回望中国共产党百年苦难与辉煌,我们更加坚信,伟大精神的磅礴力量。 习近平总书记指出,在一百年的非凡奋斗历程中,一代又一代中国共产党人顽强拼搏、不懈奋斗,涌现了一大批视死如归的革命烈士、一大批顽强奋斗的英雄人物、一大批忘我奉献的先进模范,形成', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.002631', '两个务必_screened,西柏坡_screened,白公馆_screened,渣滓洞_screened,遵义会议_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (5833, '报纸', '弘扬革命精神 确保步调一致', '', '人民政协报', '人民政协报', '共产党人;党史学习;党中央;习近平总书记;', '编者按： 6月，全国政协委员“中共党史学习读书群”认真贯彻落实习近平总书记在党史学习教育动员大会上的重要讲话精神和《中共中央关于在全党开展党史学习教育的通知》要求，重点学习了习近平《论中国共产党历史》《毛泽东、邓小平、江泽民、胡锦涛关于中国共产党历史论述', '2021-06-30 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.005318', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5837, '报纸', '弘扬西柏坡精神 推动检察工作高质量发展', '丁顺生', '河北省人民检察院;', '检察日报', '西柏坡精神;习近平;', '西柏坡，是党中央解放全中国的“最后一个农村指挥所”，毛泽东同志在这里指挥了震惊中外的“三大战役”，指导中国革命取得全国胜利，进而建立了新中国。以“两个务必”“赶考”等为主要内容的西柏坡精神，激励一代又一代检察人，至今历久弥新、鼓舞人心。 一直以来，河北', '2021-06-18 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.003061', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5838, '报纸', '坚持领导干部示范带头 扎实开展党史学习教育', '王东峰', '河北省委;', '学习时报', '党史学习;全面从严治党;习近平总书记;', '在全党开展党史学习教育，是以习近平同志为核心的党中央作出的重大决策。习近平总书记在党史学习教育动员大会上发表的重要讲话，高屋建瓴，思想深邃，内涵丰富，博大精深，是一篇闪耀着马克思主义真理光辉的纲领性文献，具有重大的政治意义、历史意义、时代意义、现实意义，', '2021-04-21 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.000654', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5839, '报纸', '充分认识党史对公安队伍的政治育警功能', '袁忠民', '浙江省公安厅;', '人民公安报', '公安民警;', '习近平总书记在党史学习教育动员大会上指出：“全党同志要做到学史明理、学史增信、学史崇德、学史力行，学党史、悟思想、办实事、开新局，以昂扬姿态奋力开启全面建设社会主义现代化国家新征程，以优异成绩迎接建党一百周年。”习近平总书记的重要讲话高屋建瓴、视野宏大、', '2021-03-25 08:00:00', 'https://link.cnki.net/doi/10.28651/n.cnki.nrmga.2021.001529', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5840, '报纸', '江山就是人民，人民就是江山', '杨栋', '甘肃省中国特色社会主义理论体系研究中心;甘肃政法大学马克思主义学院;', '光明日报', '中国共产党人;', '习近平总书记在党史学习教育动员大会上指出：“历史充分证明，江山就是人民，人民就是江山，人心向背关系党的生死存亡。”从上海石库门到北京天安门的百年行程中，一代代共产党人不忘初心、砥砺奋进，创造了巨龙腾飞、万民康乐的伟大成就，书写了披坚执锐、全面小康的壮丽史', '2021-02-23 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.006641', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5842, '报纸', '缅怀光辉历史，共创复兴伟业', '', '新华社;', '新华每日电讯', '胜利;光辉;共创;', '在庆祝新中国成立70周年前夕,习近平总书记专程前往中共中央北京香山革命纪念地,瞻仰双清别墅、来青轩等革命旧址,参观香山革命纪念馆并发表重要讲话。总书记回顾中国共产党领导中国人民夺取全国胜利和党中央筹建中华人民共和国的光辉历史,缅怀毛泽东同志等老一辈革命家的丰功', '2019-09-14 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2019.006168', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5843, '报纸', '弘扬革命传统 坚定理想信念 为首都安全站好岗守好门', '刘凯', '公安厅;', '人民公安报', '理想信念;', '革命圣地西柏坡是“两个务必”的发源地、“进京赶考”的出发地，新中国从这里走来！华北人民政府公安部在这里诞生。河北地处首都“家门口”，是首都的政治“护城河”。 70年来，有着深厚红色基因的河北公安机关在党中央和公安部、省委省政府坚强领导下，坚定理想信念，弘', '2019-08-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBsIvN0fWg9m-txFcdMtGqRLV3Gv0sXEjLi-VtMrnuR1SGKraNDXP3ViAUt_GotQLu75PXPCnSujwR1HXGLXlKtWy5c0pimNxDgYgVu9ifcQoeymYNRYUgL0eiIr0pIDg-uoDYGMhOBpQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5848, '报纸', '发扬光荣传统 锤炼优良作风', '马爱军', '公安局;', '人民公安报', '优良作风;平山县;', '河北省平山县西柏坡是闻名全国的革命圣地，新中国从这里走来。作为西柏坡精神的红色传承人，平山县公安局始终将“两个务必”和“赶考精神”作为“传家宝”，将传承红色基因作为一项永久工程，发扬光荣传统，锤炼优良作风，着力锻造新时代忠诚、干净、担当的公安铁军。 捍', '2018-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAN1dOTsP5p73LyEdHeDsfkaqH320L1he5mAlrdiOPwUtALQpiI6nn-bAyVxZjyCiKDZc-Dxtdf01a_yNfUgtXTRu1Fw5boe-QWqg3UzgGr3Bfx52TFJS5F5AvjFPisXJxp8_lmbYfWsg==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5849, '报纸', '坚定信念 艰苦奋斗', '', '光明日报', '光明日报', '坚定信念;中国特色社会主义;党的十九大报告;', '1936年和1939年，美国记者斯诺两次采访延安和陕北革命根据地，有感于中国共产党人在异常艰苦的条件下勤勉奋斗，盛赞这种精神、力量、热情是人类历史丰富灿烂的精华，是“东方魔力”“兴国之光”。 光明日报2月23日刊登署名“宣言”的文章《艰苦奋斗再创业》，回望我们党', '2018-02-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICJwiKpxMe6oGPv7taiae2Rf6Knm40DkpEymwis4i43hLdzKroeNYL1mDccs_Z9nzUm7f7ng1dv8WpVCxiarCZ5hyV6dj62QtTBEnnrtukmyXJkicwibZfC5iPAb43IIG3ZGhbXHpVrgw==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5851, '报纸', '在纪念朱德同志诞辰130周年座谈会上的发言', '', '人民日报', '人民日报', '朱德同志;中国人民解放军总司令;党中央;人民代表大会制度;国防现代化建设;中国工农红军总司令;人民军队;座谈会;', '中央文献研究室主任冷溶： 朱德同志是伟大的马克思主义者，伟大的无产阶级革命家、政治家、军事家，中国人民解放军的主要缔造者之一，中华人民共和国的开国元勋，是以毛泽东同志为核心的党的第一代中央领导集体的重要成员。他在近70年的革命生涯中写有大量著述，集中收入', '2016-11-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBhfxlOVwy1DYPFqAzZKLH17jPg77KTs0D-FJH9d6MEibxZ-66njug9QF-rjXkoEdwsJ-f2yeRfGYwK0pOjEEeRkHpEJPy7Fr20KC6w-vHP5k5nzbcoMy8yBGyEK9L_9bwWvESU3DPD8w==&uniplatform=NZKPT&language=CHS', '两个务必_screened,抗日战争1_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (5854, '报纸', '始终保持党同人民群众的血肉联系', '王昊魁', '光明日报', '光明日报', '习近平总书记;作风建设;党的优良传统;“七一”重要讲话;', '党的作风关系人心向背，关系党的生死存亡。 习近平总书记在庆祝中国共产党成立95周年大会上发表重要讲话时强调，坚持不忘初心、继续前进，就要保持党的先进性和纯洁性。同时，他还强调，“党的作风是党的形象，是观察党群干群关系、人心向背的晴雨表”“作风建设永远在路', '2016-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDP6S6uOJSz0ImV8MVrFaOXHOgYpDdHc5tlsAf_bo7QmULxHT4vdmllUdAWGMhBOuIolQZD2dHOWYqrZnVpQXiSL89Lj57n2Y_d9kLV3JAFxxZ7PTmoHXo6FvFt4gQ4hPpnziDkzX7NAQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5855, '报纸', '永葆奋斗精神 永怀赤子之心', '', '人民日报', '人民日报', '中国共产党领导;', '不忘初心，方得始终。 “我们党已经走过了95年的历程，但我们要永远保持建党时中国共产党人的奋斗精神，永远保持对人民的赤子之心。”习近平总书记在庆祝中国共产党成立95周年大会上发表重要讲话，高度评价我们党为中华民族作出的伟大历史贡献，科学概括历史给予我们的深', '2016-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID-UxxPgVAXfj28M1pvE8MO-Deu0mOG-t_S10b6N16pGH8sPh7H_JEvnxhAR4UIjg7gOimUj5CSHSApE9eIsmLA0E2iT6QdxOb3xuL_lZykk_T3PuskdK_oTgAv3sfTMl-lLAalOCzjXw==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5857, '报纸', '全面从严治党要继续从延安精神中汲取力量', '', '人民日报', '人民日报', '全面从严治党;专题教育;延安精神;延安城;习近平同志;共产党人;密切联系群众;', '传承延安精神根脉　汲取从严治党力量  中共陕西省委书记　赵正永  今年2月，习近平同志到陕西视察，对陕西工作提出了“五个扎实”的具体要求。在讲到扎实落实全面从严治党时，习近平同志特别强调，“我们党是一个具有长期奋斗历史和优良革命传统的党，也是一', '2015-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC0VaZPnvXuatGurJDQqoG_86eeSKXKa_eymmodT2ifvCxNfV_kNfwTf6fflr_oMEAkrCsr8gBzJ5B_54b35lUD3XCB6ZC6H4bIbBIklFO9btQYWmvVNPrS-pEgpphl4JdIa-Cci2CK7Q==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened,中共七大1_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (5858, '报纸', '国难当头,共产党人挺起民族的脊梁', '丁海明; 张良', '解放军报', '解放军报', '共产党人;八路军太行纪念馆;国难当头;', '引子 回望70多年前，那国难当头的岁月，许多历史瞬间永远不能忘却—— 1931年秋，东三省黑土地上最黑暗的夜，有一支队伍昂着头颅向前冲，尽管这支队伍不仅没有精良装备，而且饥寒交迫，但这支共产党领导的队伍誓与敌人血战到底。 这一幕岂止在东北：1934年夏', '2015-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICaFyImSNZcsrv8vTPSxk_YpXcRI_InXnRPzqtlib2fEvsnNgQjU4ceAFNT95Zty1KhdU0JqS2xnuT4qZT7VJqddyGbY0b_X8SGsp2wTkFgiAwrk_c9kKz9uIJXCJaykcLIDSCnRpvmwQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened,抗日战争1_screened,百团大战_screened,论持久战_screened,项英');
INSERT INTO `ds_article` VALUES (5859, '报纸', '弘扬“两路”精神 助力科学发展', '', '西藏自治区人民政府;', '人民日报', '交通运输部;重要批示;习近平总书记;综合交通运输体系;青藏公路;农牧民;高等级公路;雪域高原;民族团结;', '在川藏青藏公路建成通车60周年之际，习近平总书记作出重要批示，把“两路”精神概括为“一不怕苦、二不怕死，顽强拼搏、甘当路石，军民一家、民族团结”。“两路”精神传承着中华民族的优良传统，蕴涵着中国共产党人的红色基因，彰显着中国人民的坚强品格，是伟大民族精神的', '2014-10-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDlrq270PiTiAV2GCsea6P7TpLJAxOUSpZWuYsxYDrsyD_wzitk0yPDp2CqY4CPU-bJ864jhgAUnuClB_k9Q7B9qP2hPJdTTM6T8E_R3VvIF7cawCLtOAwGoUdov85hmsaFgWf2choIFA==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5860, '报纸', '弘扬沂蒙精神 践行群众路线', '赵秋丽; 刘广阔 ; 邢子文', '光明日报', '光明日报', '沂蒙精神;社会主义核心价值体系;群众路线;党的群众路线教育实践活动;', '本期主题 沂蒙精神是党践行群众路线的实践结晶，是中华民族宝贵的精神财富。习近平总书记在沂蒙地区考察工作时指出，历史不能忘记，沂蒙精神要大力弘扬。 在新的历史时期，弘扬沂蒙精神是山东党政军与沂蒙人民共同践行党的群众路线的成功典范，是开展党的群众路线', '2014-08-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICf7zDXwGKXGsYN3wext7SyROI5Eya70qwzRdHTHwVcYBsX70ba1vnd9ehLtKtXrAiNhNZdA4EwdPuHvTcGoV24MFvlAH6Pl4Tm8IB4LN6bKWjVMChI76uUjlun6OQUSnG5pVOuh54w9A==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened,抗日战争2_screened');
INSERT INTO `ds_article` VALUES (5861, '报纸', '牢记甲申历史教训 走好新的赶考之路', '田向利', '中共河北省委;秦皇岛市委;', '光明日报', '“两个务必”;群众路线;李自成;党的群众路线教育实践活动;党要管党;从严治党;“赶考”精神;', '河北省委把3月23日作为全省县以上领导干部集体“警醒日”，在全省广泛开展“中国梦·赶考行”宣传教育，对于深入推进第二批党的群众路线教育实践活动具有重要意义。370年前的甲申之年，李自成兵败山海关，导致攻占北京仅42天的大顺政权迅速土崩瓦解，其顺势而兴、抚民而盛、', '2014-04-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDRKjBriQvtouJCcCw4pQR0L-XcQc_xTPkeCfI6-S3rppg2cd9EBq_o-sRNHLiOiJ7OBI0O6DaehTGCcwLckwc2C6JE2FcNawhJ4hpU7DWNNRVU78zz6otD76LoRJvopbe2R3fwjRFgrw==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5862, '报纸', '弘扬“赶考”精神 交出满意答卷', '建扩', '光明日报', '光明日报', '“两个务必”;无私奉献;“赶考”精神;焦裕禄;党的群众路线教育实践活动;习近平总书记;塞罕坝机械林场;', '本期主题 3月23日是毛泽东同志提出“进京赶考”65周年纪念日，河北省委在革命圣地西柏坡召开了“中国梦·赶考行”省级领导干部集体学习教育座谈会，重温毛泽东同志“进京赶考”重大警示的历史意义，学习领会习近平总书记“赶考远未结束”重要论断的深刻内涵。本期《论苑', '2014-03-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDeovpZdvtgDW9lLggqpjLpfE5CYKhRgxmTUvwhViLf8g08-UdRLCf2zMMmtQb6AfeqnXH0QcbEMewSA_9CG6rYE1X2OntFaoowzzOXpZZyveiqGxJRvsPiV0xEuualZI8HxYGNpP2BWg==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5863, '报纸', '永葆赶考心态成就伟大梦想', '', '新华社;', '新华每日电讯', '伟大梦想;两个务必;全面深化改革;', '不管走出多远,都不能忘记自己从哪里来,到哪里去。65年前,中国共产党人带着对历史治乱规律的深刻借鉴,对艰苦奋斗历程的深刻总结,对国家长治久安的深刻忧思,对党的根本宗旨的深刻认识,走出西柏坡这个中国革命最后的“农村指挥所”,踏上了执掌全国政权,领导人民建设新中国的伟大', '2014-03-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICwXU2pUY_Im7AkkzjMW1Yy8duq5KSTvgi-8JCMx2-Y1z4ZuTxN9jfrksUyM99IM1DBzBCSUmktE6okpoDuCXfDx1GPk8-7h2Z_FCB4eSNH1zpCyQxIoi3663J6CMvQNUeqX6w9FvlKRA==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5864, '报纸', '在全国纪念毛泽东同志诞辰120周年学术研讨会上的讲话', '刘云山', '人民日报', '人民日报', '毛泽东;毛泽东思想和中国特色社会主义理论体系;中国革命和建设;党的群众路线教育实践活动;坚持和发展;“两个务必”;历史唯物主义;共产党人;党的十八大以来;密切联系群众;奋斗历程;学术研讨会;', '同志们： 今年是中国共产党、中国人民解放军、中华人民共和国的主要缔造者，中国各族人民的伟大领袖毛泽东同志诞辰120周年。在隆重召开纪念座谈会的同时，中央决定由中央有关部门举办全国纪念毛泽东同志诞辰120周年学术研讨会，深切缅怀毛泽东同志的丰功伟绩，学习他的', '2013-12-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA7vY91ary_d-o0iWX2k3y8BoFuSYAQfgKx-m0WSwTcV1eXU79bj-SGnCVTxyXGBWyey1l3pFgowZuxPsVR7oCT2SAbPqJSEkfixUEvFJuit1_FWj19mp2xO2baXUNqvqkq5cOD4iQuUw==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (5865, '报纸', '在纪念毛泽东同志诞辰120周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '毛泽东;马克思列宁主义;共产党人;革命家;毛泽东思想活的灵魂;座谈会;', '同志们，朋友们： 今天，我们怀着十分崇敬的心情，在这里隆重集会，纪念中国共产党、中国人民解放军、中华人民共和国的主要缔造者，中国各族人民的伟大领袖毛泽东同志诞辰120周年。 毛泽东同志是伟大的马克思主义者，伟大的无产阶级革命家、战略家、理论家，是马克', '2013-12-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDfFQn45uuLNnTZypwG8kcixpATHpFwHVlOTLTInV531Yi6Jj_BIHke0q07_dCiWCemveqeqyThWM2k_tGDEKUcoms3igKHhauLmE5AqElxbdbsiEbu8ckR33DyvoWXflSA6xDy3i6KHA==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5867, '报纸', '重大革命历史题材创作新探索', '', '人民日报', '人民日报', '《周恩来的四个昼夜》;群众路线;重大革命历史题材;周恩来;', '由河北省委宣传部、华夏电影发行公司、八一电影制片厂等联合出品的电影《周恩来的四个昼夜》，日前在河北革命老区武安、涉县、西柏坡及石家庄等地巡映，反响热烈。影片通过周恩来总理身边随行摄影记者的视角，讲述了上世纪60年代周恩来在河北邯郸武安县伯延公社调查研究后，', '2013-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB0iwIgizt7_n6_aJbgbjaU1SeL24ovVMXUHTmSdVSMuP0OJmvPn5AopadAbOoHgF2HoEhnyfMGatpeC_2l9TyzL-bSDoWGUMSMkhPKmjt9vcglFNCE-v7A5ukmcHlgu9jaQRmLHvbN0w==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5868, '报纸', '弘扬西柏坡精神永葆共产党人的先进性与纯洁性', '艾文礼', '中共河北省委;宣传部;', '光明日报', '共产党人;纯洁性;', '伟大的事业需要并产生崇高的精神，崇高的精神支撑和推动着伟大的事业。90多年来，我们党领导中国人民展开了艰苦卓绝的革命和波澜壮阔的建设事业，中华民族从任人欺凌到振兴自强，国家从贫穷落后到初步繁荣昌盛，人民从受苦受难到富裕安康，党也从成立时只有几十名党员发展成', '2012-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDdfSsTTqG43S0U_rfLInl4gNLlR7rYvhu6X1s89k1Q0RS0Q-TGRV1ffuOmZXxb7hTfw5com9YNzgzULtz0Dvgzr7zJ3EEHQWN6Hd3bDt3r_o1pOWunnKneIGs8rWL3xA4gc2TZou6hEA==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5869, '报纸', '在纪念中央革命根据地创建暨中华苏维埃共和国成立80周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '中央革命根据地;中华苏维埃共和国;马克思主义基本原理;红色政权;社会主义物质文明;座谈会;', '同志们： 80年前，中华苏维埃共和国在中央革命根据地的瑞金宣告成立，谱写了中国共产党领导的革命根据地建设和红色政权建设的新篇章。今天，我们在这里举行座谈会，纪念中央革命根据地创建暨中华苏维埃共和国成立80周年，回顾我们党领导人民为实现新民主主义革命任', '2011-11-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAJbfBp-30g8g9DvUL4yAOr9B8XHsD7AVAgere0ebtLopADB9hQ0Lajkaus4hyJQtbg0IL7xSWabNIz3fa1KEhiWNuloKO8bAP46-EJWZ3Wc2wawSsZxjEHf0JWBNfRLqpMke_iOwKw2Q==&uniplatform=NZKPT&language=CHS', '两个务必_screened,抗日战争2_screened,红四军_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (5873, '报纸', '发展新篇', '', '人民日报', '人民日报', '胡锦涛;同期声;科学发展观;棚户区改造工程;全面建设小康社会;免费义务教育;两癌筛查;人民当家做主;全国人大代表;经营性文化产业;文化体制改革;民主党派;共产党人;新型农村社会养老保险;公共文化服务体系建设;', '２００２年１２月５日，胡锦涛率领新当选的中央书记处成员，冒雪来到了革命圣地西柏坡。 １９４９年３月２３日，当中共中央从这里出发前往北平时，毛泽东意味深长地说，我们此去是“进京赶考”。 ５３年后，胡锦涛来到这里，要求全党牢记“两个务必”，牢', '2011-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICECQXB2g2uf_iWnscaCyB_Qy1odN_h7ots9FYMD2Cb8ZG87yQENBUoocGL4F0SSb8_1LXmk-l4mljUO4wSpbuD7tx_wlaOx_bHKvphfOsNDNwRvRgBS9CSB3Klrf_qG5jKhjKj-tUOTQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5874, '报纸', '弘扬党的优良传统 建设中国特色社会主义', '张全景', '全国党建研究会;中央组织部;', '中国组织人事报', '中国特色社会主义;党的优良传统;毛主席;毛泽东思想;马克思主义基本理论;共产主义理想;民主集中制;群众路线;', '中国共产党走过了90年的光辉历程。这是波澜壮阔、天翻地覆的历程，是在崎岖道路上披荆斩棘、开拓创新的历程，是从挫折乃至失败走向胜利的历程。我们党在长期革命斗争和建设实践中，积累了丰富经验，形成了自己独特的优良传统。例如，理论联系实际，认真看书学习；密切联系群', '2011-06-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICSrOvgyoWBJs3ynmM4ZFebgxho4OtbGHolmEmIt-XY2IqVm_xlecoI21eDrF7655iAId4IC9QredFG5jY9hrc7GiwSWOfO02QoNefgUmUGAXtDwL0aO0Q7oUhKdG7Grscj5hiUAULAMA==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5880, '报纸', '人民至上', '李亚杰 ; 杨雪梅', '新华社;', '人民日报', '共产党人;人民至上;村党支部书记;抗灾救灾;灾后重建;灾后恢复重建;农房重建;受灾群众;地震灾害;农房建设;北川县;', '风一更、雨一更，我们风雨兼程；日一轮、月一轮，我们日月同辉；拼一路、搏一路，我们拼搏前行；情一腔、爱一腔，我们情爱无疆。 ——题记  在一个国家和民族的发展道路上，总会发生一些影响深远的重大事件，成为这个国家和民族的集体记忆。 ２０', '2011-05-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBrINbcdu1bI830EBjlo-HQJVnPnj8tegrILRopIj0OkVD8SEiV9Mp7uDUiNY5OcFXzYJCg-zuxKCPvwloqzyad95AFTJ8LCZC26rXADzygtZWgxSiYUnbVhD-0rxlC7MhhLe0cSfSg-g==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened,西柏坡_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5881, '报纸', '在纪念孙起孟同志诞辰100周年座谈会上的讲话', '王兆国', '中共中央政治局;全国人大常委会;', '人民日报', '孙起孟;中国共产党领导;中华职业教育社;多党合作和政治协商制度;和平民主;民主党派;加入中国共产党;我国职业教育;中国民主建国会;座谈会;', '同志们、朋友们： 今天，我们怀着十分崇敬的心情在这里举行座谈会，纪念孙起孟同志诞辰100周年，深切缅怀他的生平业绩和历史贡献，追思和学习他为国家、为民族、为人民不懈奋斗的高尚品格和始终不渝的理想追求。 孙起孟同志是我国著名的教育家和社会活动家', '2011-03-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIALzfdTvLXYA8hdAxT1rstooDLPXgxUXH4ifU4tb8Ex43Ur0eHK9dn_ehh90CXruwq2tp9GqOELgpj3IS0aP1FCVkS43Al_dSXj3X-zUxgmZ_tqTBeAAKetay6fdlGGtnZ2NFn2H5_9WA==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5882, '报纸', '深入贯彻落实科学发展观 进一步推进党委工作科学化制度化规范化', '党武 ; 毛俊', '解放军报', '解放军报', '临时党委;国防和军队建设;科学发展观;中国共产党军队委员会工作条例;全委会;军事斗争准备;中央军委;学习型党组织建设;工作科学化;', '经胡锦涛主席批准，中央军委近日发布了新修订的《中国共产党军队委员会工作条例》(以下简称《党委工作条例》)。为帮助全军各级党委和机关理解掌握《党委工作条例》精神，全面抓好贯彻落实，总政领导就有关问题接受了记者采访。 问：请谈谈这次修订颁发《党委工作条例》', '2011-02-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDWMVjDD5DTxR5h_8cHmE5-uM644D0Ksmm6FC3QO-LNrto19qbJDJbUbE7GohQC29zvO7RpbKGqCHSIkraLMfEs0W_4ycn90kudkd39gXOvJF6VcYIIVTY9zpI9M7cnI2GN3Dxzo108lw==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5885, '报纸', '石家庄研讨西柏坡精神', '耿建扩', '光明日报', '光明日报', '“两个务必”;石家庄;国家行政学院;', '本报讯　（记者　耿建扩）62年前的5月26日,毛泽东主席率中共中央和解放军总部移驻西柏坡,并在那里为新中国诞生谱写了不朽篇章。62年后的今天,各界专家学者齐聚石家庄共同纪念这一历史性时刻,并就西柏坡精神展开深入研讨。  研讨会上,来自中央文献研究室、中国社科院', '2010-05-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC1RpC5tS1SmOZNyhURSAfMU4DYiChgTmPvuPQ4VoRU-3pbi3n8WNSQXGyvJFlmuhANaGV7vK_3Y5uByheBhsGhyzjj3YeDC_ZTTeV_zs6z_QeuqSC8B7maLUiP3XJKhrZIinwuUUHcQg==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5889, '报纸', '引航,一个执政党的历史担当', '贺广华; 汪晓东; 颜珂; 李鹤', '人民日报', '人民日报', '历史担当;新的历史起点;中国共产党;党的十七大报告;社会主义建设;社会主义民主政治;江泽民;人民代表大会制度;共产党人;党的理论;本领恐慌;', '共和国六十华诞到来之际，人们用鲜花与掌声、赞美与祝福表达着内心喜悦。  此时，执政的中国共产党人，显得格外清醒和冷静。 9月15日至18日，中共十七届四中全会在北京举行，审议并通过《中共中央关于加强和改进新形势下党的建设若干重大问题的决定》。 “', '2009-10-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDGrLje3lFIHOJRP-sodEl7jfQH-CW3r3MTw5fK-k5B5_NorHYlVD9W24wTHKmfT4pRyDu4Ac8dujqqpAbhkX-x-G29dR11H4sjzJO41OjoLy-5v2FCtyGP_uZsmIWsW2-ARvLWF_k4FQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5891, '报纸', '铸就党执政为民的中坚力量', '董宏君', '人民日报', '人民日报', '领导班子;中坚力量;执政为民;干部队伍建设;干部制度改革;干部人事制度改革;', '焦裕禄、孔繁森、郑培民、任长霞…… 这些名字让我们刻骨铭心，他们是党的好干部，人民的好公仆。 这是弹指一挥间的60年——我国经济社会发展取得了举世瞩目的巨大成就，这其中凝结着各级领导班子和广大干部的心血和汗水。 这是记忆永存的60年—', '2009-09-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDrf5JrIiy9chmBTEW25XrT0d92NH8LZk02yvJ2DPCD0XXLgyD8ZWQNmvNyWiyLLPK7fk3NNuR5Mc14cSU8c8GagRFnXx4CB4osLMCsjZZJa4E5SEaFghjWoRb0zAyHaefKHnlTg64WIg==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5893, '报纸', '热烈庆典前的冷静思考', '叶小文', '中央社会主义学院;', '人民日报海外版', '共产党;', '共和国60华诞将至，万方乐奏，举国欢腾。从北京加紧准备游行、阅兵的忙碌里，从人们透着喜气的眼神里，从“今夜无人入睡”的歌声里……到处是大庆之前的欢乐和热烈。 热烈的理由，诚如《剑桥中华人民共和国史》所言，“恢复中国的伟大所必需的全国统一是所有爱国的', '2009-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBzGyBbWDxcoZh81CU9OtC-xtXmldpqkHKcA9Mjptn-4iacWii9fPQxhlWntuu8Hq4ApovmM0SxDnkugtTFXuCoeQjMqTsXO36luut9F5xtSuUbtwrEiR2LoWbLR8B7rl5fAMxKSLPz9g==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5894, '报纸', '咬定青山不放松', '', '光明日报', '光明日报', '中国特色社会主义道路;不折腾;改革开放;中国特色社会主义事业;社会主义现代化建设;胡锦涛;', '2008年12月18日,胡锦涛总书记在纪念党的十一届三中全会召开30周年大会上发表了重要讲话。当他用铿锵豪迈的语言讲到“只要我们不动摇、不懈怠、不折腾,坚定不移地推进改革开放,坚定不移地走中国特色社会主义道路,就一定能够胜利实现这一宏伟蓝图和奋斗目标”时,会场里响起了热', '2009-09-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDE7x99-MvNLEErDL4J1VFdkQ1Wj19LfY872oijF9orRo-pzSaBUplxN5snokjZ841Z_lSJkpMvzw1sbWAXlDGtgrcPV1clU-sRAaZs-8g8ahGt_T58a7o3r4zwuDXOMy4gaDyiLm9QSg==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5900, '报纸', '西柏坡头缅怀先烈', '耿建扩; 史进平', '光明日报', '光明日报', '缅怀先烈;主题活动;石家庄;两个务必;', '本报石家庄4月3日电（记者耿建扩通讯员史进平）由河北省委宣传部、省文明办、省文化厅、省文联、团省委联合主办的“缅怀革命先烈，牢记两个务必”清明节主题活动今天上午在西柏坡纪念馆广场隆重举行。  初春的西柏坡万木吐绿，春意盎然，驻石家庄武警官兵、西柏坡纪念馆', '2009-04-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICsnEtyP4rVbAAyt2ZSiO5XhjBHNmPnF9gHFUgzEjfJI1cbLdKG7cvskijOnuZf9QO2ySm1oKEx6_ejAD7s3w4_9UN-pkNCJ9V6zoG6vcXpi56fOwwbXtqWz2Z5Nw1AQuty3stOjP8jaQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5902, '报纸', '学习王瑛：将反腐倡廉进行到底', '赵达; 罗旭', '光明日报', '光明日报', '反腐败斗争;', '从巴山蜀水到华夏大地,连日来,一个鲜花般美丽的笑容在人们的脑海里定格,一个红叶般灿烂的名字被千万人传颂——她是原四川省南江县委常委、纪委书记王瑛。  人们在关注王瑛先进事迹的同时,亦将目光聚焦于她所从事的事业——党的反腐倡廉工作。  全国两会前', '2009-03-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICw4KQAVy-3Lu7Y5Rww30dd5GXi3kVdQxIX6xkXD_rbmFoEf2cNp2sAqgIDFWLds16ITHANVmUSIz0mblUGa2k9rHJgbUgja2Hg63YDoJAFD5DlXMYhUoQY1ycU1ONgqGI5Wq4u9Aq-KQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5903, '报纸', '在纪念党的十一届三中全会召开30周年大会上的讲话', '胡锦涛', '人民日报海外版', '人民日报海外版', '党的十一届三中全会;中国特色社会主义道路;政治体制改革;社会主义基本制度;', '同志们： １９７８年１２月１８日，也就是３０年前的今天，党的十一届三中全会隆重召开。这次会议，实现了新中国成立以来我们党历史上具有深远意义的伟大转折，开启了我国改革开放历史新时期。从此，党领导全国各族人民在新的历史条件下开始了新的伟大革命。', '2008-12-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC4_KG88vM9MnqCLqwc1Ug1HcI_hbfqtkJt7Eb4Lc-IHZwfXnFsK9pL9wq9VXkEgnky4-HVw2Am5Y85Jp3gUsaANFcJzXlOYi60suXaPATlq8DpyF2n0gfFR0dfWRnHjsTbSpAeBgbQEA==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5905, '报纸', '风正一帆悬', '', '光明日报', '光明日报', '领导干部作风建设;党的执政能力;民主集中制;“两个务必”;中国共产党党内监督条例;党的作风;以权谋私;党员领导干部;党的形象;党内法规;', '1940年秋的一个上午,延安马列学院专门派4名同志到杨家岭接毛泽东同志来作报告。当他们走到延水河桥头时,正好碰上迎面走来的毛泽东同志。毛泽东同志打量了来接他的4个人,严肃认真地说:“从杨家岭到马列学院,才十里八里路。二万五千里长征都走过来了,这几步算不了什么。我又不', '2007-10-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA4-Zbqap7DxdFdkulnR2DgY0qPBe8XckxNKOEd5cmSsMqqoQBnWlAKA2XtIGmKlF32mqbXdIBcFle2mjSc3ZBqOVccJzhoZnhqANrUh256HoOGgQ9JhdUuLl4KCE4A6S7vd5ovV00wKg==&uniplatform=NZKPT&language=CHS', '两个务必_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (5906, '报纸', '为全面建设小康社会、开创中国特色社会主义事业新局面而奋斗', '', '中共中央文献研究室;', '人民日报', '中国特色社会主义事业;新局面;全面建设小康社会;全国人大常委会;国务院机构改革方案;胡锦涛;科学发展观;', '新华社编者按：为了迎接中国共产党第十七次全国代表大会的召开，中共中央文献研究室应新华通讯社的约请，编写了《为全面建设小康社会、开创中国特色社会主义事业新局面而奋斗——党的十六大以来大事记》。 这个大事记集中记述了党的十六大以来的五年间，面对复杂多', '2007-10-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDyuYobpLFB25krgILGg1-oYqG67kvTLj1yGQnkbb1ECQu8NeSplW3kEDlnRFRh2mdrwb83BdyKCsmFrOkH1O2by8GP-Ny8FlLQb4Ofjq27gOFD9j7CWk1xITEpGzi_9BSsg_2aWWWZoA==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5907, '报纸', '天津新一届市委市纪委组成人员参观周邓纪念馆平津战役纪念馆', '张楠; 马红刚', '中国纪检监察报', '中国纪检监察报', '纪委委员;张高丽;', '本报讯　6月3日，刚刚当选的天 津市委新一届市委委员、候补委员和市纪委委员的第一项集 体活动就是参观周邓纪念馆和平津战役纪念馆。缅怀老一辈 无产阶级革命家的丰功伟绩和革命先烈的英雄事迹，学习他 们的革命精神和崇高品德。天津市委书记张高丽指出', '2007-06-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC66ndBNeFUCsVvE40HFeHV_FZZ4nPWr3QIKgs6NyP3MAhSHaU3zios_HUNVDlMNZxT_2nVUuDHwWNJWsqZo_buVT_SXIM778RQErE03LnKrLS0V-l60-1aE-SFARTLGHroeLm0xzbqhw==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5908, '报纸', '为建设和谐社会贡献力量', '许小峰', '中国气象局;', '中国气象报', '气象事业发展;胡锦涛;建设和谐社会;立党为公、执政为民;业务技术体制;', '在今年的“两会”期间，胡锦涛总书记 强调，各级干部特别是领导干部要进一步 增强忧患意识，始终保持开拓进取的锐 气；要进一步增强公仆意识，始终牢记全 心全意为人民服务的宗旨；要进一步增强 节俭意识，始终发扬艰苦奋斗的精神，团 结带领广大群', '2007-03-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBABnD_X8VuVvJECU3UOfOtAUV-OkTwEdDQ45fh-WFNz5FQa2si9_kgYyV_o4Adqxv8dGQ98aysRbu_vP_DUe0Dnq8VuNaSadFLNFtVCPqlAvexFxbb5tkDToFYkxPD6SE0Z4auTE8GeQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5909, '报纸', '在纪念朱德同志诞辰120周年座谈会上的讲话', '胡锦涛', '人民日报', '人民日报', '朱德同志;共产党人;国民党反动派;南昌起义军;纪律检查工作;座谈会;', '同志们：  今天，我们在这里隆重集会，纪念朱德同志诞辰１２０周年，深切缅怀朱德同志为民族独立、人民解放和国家富强、人民幸福建立的历史功勋，追思和学习朱德同志为党和人民事业不懈奋斗、鞠躬尽瘁的崇高风范，激励全党全军全国各族人民在中国特色社会主义道路上', '2006-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBfZhUrbBI3gfvB0un96z0RFFPfXbQPXs2PeQVma076UiR9kwDgeTSDfY35GRhgSpqJ-_s12gbtQyqKcsY0ZNPpuEOOjTqM0mbhzXPibqOMetpxMkefT6lzS9b_UtgeciW6Na6raOAKfQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,中共七大-2_screened,遵义会议_screened,反围剿_screened');
INSERT INTO `ds_article` VALUES (5912, '报纸', '纪念王稼祥同志诞辰100周年座谈会在京举行', '崔士鑫', '人民日报', '人民日报', '王稼祥;曾庆红;座谈会;', '本报北京８月１６日讯　记者崔士鑫报道：纪念中国共产党的优秀党员、忠诚的马克思主义者、杰出的无产阶级革命家、我党我军卓越的领导人、新中国优秀的外交家王稼祥同志诞辰１００周年座谈会，１６日上午在北京人民大会堂举行。中共中央政治局常委、书记处书记、国家副主席曾', '2006-08-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDSOMgz7kufitMB0CjIlVw1aQXfHLBG7fx8DeH8iHRrGhzqnHqGq6ZldG8cIOKmUO7ImLKQTlWoB_GGlsvQnRwHz9fgKWXjAvQfgGHJ2fsQCjK_ekg9cQpXPkneo83K_IxIqkETQzmJGw==&uniplatform=NZKPT&language=CHS', '两个务必_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5914, '报纸', '功垂千古 德昭后人', '', '中共湖南省临澧县委;临澧县人民政府;', '人民日报', '林伯渠;维新思想;社会主义革命;第一次国共合作;陕甘宁边区政府;国民党;孙中山;', '２００６年３月２０日，是中国共产党德高望重的领导人之一、伟大革命战士和杰出的政治活动家林伯渠同志诞辰１２０周年。林伯渠同志是跨越两个世纪，历经旧民主主义革命、新民主主义革命、社会主义革命三个历史阶段的彻底的革命家，为中国人民的解放事业和社会主义建设事业付', '2006-05-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID3kA4xZ9RD1AAILFaha2vCBraLm4xO8sBbjIE-7Lr9InMf3Vyr-tTthyPgJZ3IUaRxVrRyTEns5wKfWSotys-N7eXso5GD0H9c1i6yIPrnveRlcEq1CmkN3KPgOUBjiWer6F0LTdEfzQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,抗日战争2_screened,中共七大1_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (5916, '报纸', '马克思主义执政党建设理论的创新与发展', '卫庶; 叶帆', '人民日报', '人民日报', '执政党建设理论;三个代表;马克思列宁主义;毛泽东建党思想;党建理论;马克思主义;创新与发展;', '加强和改进党的建设，是全面建设小康社会、加快推进社会主义现代化的根本保证。加强和改进党的建设，必须加强马克思主义执政理论建设。中央党校邓小平理论和“三个代表”重要思想研究中心承担了马克思主义理论研究和建设工程的“毛泽东思想、邓小平理论和‘三个代表’重要思', '2005-12-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB6Po1D9iZtN30RcYFFpY_WEaF-h1zTUZBo0AQxctZIp1qurBNb0Dg9mzOFnASbrciwUy0RubziDxT9QQgt5cTSVIGj7Ax62ejRLjVjmhFGa4GJIWe_2P8407LAtx1mKu3vuPyvYAaqVQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5918, '报纸', '陈云同志诞辰100周年纪念大会在京隆重举行', '李斌; 沈路涛; 胡锦涛', '人民日报', '人民日报', '陈云同志;社会主义经济建设;执着追求;无产阶级革命家;吴官正;纪念大会;', '新华社北京6月13日电　中共中央13日上午在人民大会堂隆重举行大会，纪念伟大的无产阶级革命家、政治家，杰出的马克思主义者，中国社会主义经济建设的开创者和奠基人之一，党和国家久经考验的卓越领导人陈云同志诞辰100周年。中共中央总书记、国家主席、中央军委主席胡锦涛', '2005-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDUNQooIQLnCPl27eSBXpWVXdZqlpdmm5OhfAQjnf5nwtG-dk0cRl55YdIZ8LzTeeSWai6MfAaSVwmDpfjtKnBQjtjIBUcn6CjI1xFwY7qUi0k51VfcEooyg1o9q6LJm5NRALWgFGDuYQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5919, '报纸', '国家旅游局党组中心组组织先进性教育活动专题学习落实《实施纲要》', '', '中国旅游报', '中国旅游报', '先进性教育活动;党风廉政建设;反腐倡廉工作;《实施纲要》;反腐败斗争;惩治和预防腐败体系;中心组;专题学习;', '本报讯　3月10日上午，按照国家旅游局党员先进性教育活动工作安排，局党组中心组围绕学习贯彻落实中共中央《建立健全教育、制度、监督并重的惩治和预防腐败体系实施纲要》(以下简称《实施纲要》)，进一步做好国家旅游局机关反腐倡廉工作，进行了专题学习讨论。学习讨论由局党', '2005-03-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBiKuNXROTZ3p2WDHUyyVywCzYivtxKgRqS-cnVWQUMWH1k20kN5clQMn2N_PSwwdJks84WOpWIy8ThhFvkL_7FflD0JAAI_F4wejVDCMFZAwGhrBTzZbOCXc1lXuxTDLHEKn0dNpPfTA==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5920, '报纸', '在邓小平生平和思想研讨会上的讲话', '李长春', '人民日报', '人民日报', '马克思主义理论研究;马克思列宁主义;毛泽东思想;有中国特色的社会主义;社会主义现代化建设;意识形态领域;研讨会;', '在纪念邓小平同志诞辰一百周年之际，中央有关部门联合举办邓小平生平和思想研讨会，这对于深切缅怀邓小平同志这位历史伟人，学习他的光辉思想、崇高品德和革命风范，进一步加强邓小平理论的学习、研究和宣传，坚持用这一科学理论指导实践，具有十分重要的意义。我代表党中央', '2004-08-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDGHNC3-ZpAGoqCnaX7A5LKEQRk02nclxl66yhee7QDhX47QJWk3s6g4fgVtlH5bY9bzfnSjn049oQkE4HyY7guK7CSzfOtKJR8seHPEvr5KUudZsltJfpe8JrreMP_Fh0LyHPRr7tmBA==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5922, '报纸', '“两个务必”：精神财富世代相传', '翟伟; 邱红杰', '新华社;', '新华每日电讯', '“两个务必”;精神财富;共产党人;', '“这些珍贵的文物、感人的故事，昭示着共产党人对 理想的不懈追求、对人民的无限深情、对事业的执着忠 诚。”站在《牢记“两个务必”永葆政治本色──西柏坡 精神巡回展览》会场前方摆放的大屏幕前，观看着新中国 的创建者们迈步“赶考”的珍贵镜头，13岁入', '2004-06-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDCoaqS9dRJdA0ydxoJQDJ24aE3smmuFMB125ldOdCZx3_ilzbCwX-dbAAoBEwcVwRyNNFcWY-XZYwGbQ-vTbqaw_pgmtNmp82Q-uxur2cmA18wz_pQmdI-f6Y_myKssRr4lPr3oDkajQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5926, '报纸', '毛主席走过的地方 红色旅游一片火红', '', '中国旅游报', '中国旅游报', '旅游交易会;井冈山;瑞金市;红色旅游;', 'T今天是毛泽东同志诞辰110周年 纪念日，全党全国各族人民都在以 各种方式缅怀毛泽东同志的丰功伟 绩，我们也专门编发了这组报道以 示纪念。  近年来，从韶山到南湖，从井冈 山到遵义，从延安到西柏坡，在毛泽 东同志当年走过的地方', '2003-12-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDbgtgi0OZKxPgb8VBtZGVsfUtE2bfqgo2uTAx-EksKzeEGDehtRBcQG0_87cgji_AxcSKtNb-higW6GN4cNYrbFIXzVP1VFaVk818TeamTAL_VdQZZcCPZdwfs4yEBmePvmLjU2f3Acw==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened,枣园_screened,凤凰山_screened,红井_screened');
INSERT INTO `ds_article` VALUES (5927, '报纸', '“毛泽东与马克思主义在中国的发展”研讨会召开', '倪迅', '光明日报', '光明日报', '毛泽东;马克思主义;中共党史学会;研讨会;', '本报北京12月14日电　为了更好地继承毛泽东的宝贵遗产，推进马克思主义中国化与中国化马克思主义的发展，在纪念毛泽东诞辰110周年之际，中共党史学会毛泽东思想邓小平理论研究会、安徽省委党史研究室、安徽省中共党史学会和安庆师范学院日前共同举办了为期五天的“毛泽东与', '2003-12-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBM4FWKFl-9YiJkzLqUpvBhE3qb1JBxT8Q2ZJhUcRpXKK1oiH9IcC49ro5uDulVp2YJ7SAKW5mPZLQ3bQR-3yF0NBF_Sbh1nxwncyW_nKTo_ncflnDquMLy9yAQLQc40zX0nvi7x0DmSQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5928, '报纸', '一片丹心可对天', '孟东明; 黄明', '工人日报', '工人日报', '汽车厂;中国汽车工业;', '编者按：7月15日，是一汽诞生50周年纪念日。本报谨以此长篇报道敬奉给这位共和国的长子。本文所披露的史料，许多系第一次见诸报章，弥足珍贵。除今天刊载的之外，陆续刊出的还有六个部分，敬请读者关注。  一汽50年了。50年奋斗，50年辉煌；50年拼争，50年血汗；', '2003-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDJ0qeev8ou16O1r2UXfTXgbnS3Nl3WNXGsr4na3dD-qfiUg9aUHcYv8xnrl79sGoANNxOgIdieB9yLpjKPbEnwPY1FO6i1T7KiBHXz9Y1sVGlANXfjLnbqlt0HD5jNKGeRTOsqtD121w==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5933, '报纸', '最高人民检察院工作报告', '韩杼滨', '最高人民检察院;', '人民日报', '最高人民检察院工作报告;检察官法;市场经济秩序;全面建设小康社会;职务犯罪案件;预防职务犯罪;办案质量;严打整治斗争;', '各位代表： 现在，我代表最高人民检察院向大会报告工作，请予审议，并请全国政协各位委员提出意见。 第九届全国人民代表大会第一次会议以来，全国检察机关以邓小平理论和“三个代表”重要思想为指导，认真贯彻党的十五大、十六大和九届全国人大历次会议精神，坚持', '2003-03-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBZf8lRwQedsOE1STZN-sK8qoWc3uzhujLY-b0dHdHVuJN1icDRypcApfywCg4osgiVGnaK4xowF_qlwYxds_DF1CJ7o2DDtRc0Iksl6tRP5EVDT720FbqdZ8O_lKf4WjRIZ4yPC2PeZg==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5935, '报纸', '戒骄戒奢成伟业', '张忠; 丁伟; 郑少忠; 盛若蔚', '人民日报', '人民日报', '“两个务必”;', '54年前，在新中国即将诞生的前夜，毛泽东同志谆谆告诫全党：“务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风。” 出席十届全国人大一次会议和全国政协十届一次会议的代表、委员们在接受记者采访时纷纷表示，“两个务必”', '2003-03-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBiwCQbdJQkO43yXu3HsRPbYcCvwKdPfTOklSFALx45-Pjjzd38u-AqV7OLa063MhLbHqDJY8oZeZOo1Gbe6uDt9YAi3HrabfpKWvPf35sez0ELxEzfM1tRjy0XQn36_gtK82i8rUheTQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5936, '报纸', '我们已站在更高的历史起点', '张弛', '解放军报', '解放军报', '全面建设小康社会;历史起点;人民代表大会制度;', '春风送暖，万物昭苏。党的十六大之后的第一个春天来到了。  肩负着全国各族近13亿人民的重托，5100多名新一届人大代表和政协委员，从长城内外、大江南北会聚北京。他们将肩负起新的历史使命，集中起一个民族的智慧，描绘共和国复兴大厦新的宏伟蓝图。  1、人民代', '2003-03-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDU6rSryUWNECw4sol-RvwuYy2MmBGO_rNPYzVGYr03cqtw-eiqwPZxO4BCIJTinjaFyj02KUS8u72_gdWBQ7DLH8OnrjmALrTegpVHziOC1hypNtdtOwvO0is-E_DJ0sm9YHHm0n9HrA==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5938, '报纸', '牢记“两个务必” 积极奋发进取', '申进科; 马飞', '解放军报', '解放军报', '“两个务必”;', '本报讯　特约记者申进科、马飞报道：连日来，位于塔克拉玛干沙漠南缘的 “王蔚事迹陈列馆”，成了兰空某雷达团党员干部接受“两个务必”教育的“第二课堂”。大家学习王蔚这位新中国水利专家踏遍昆仑四十载艰苦创业的感人事迹，联系自身思想实际，对积极进取、保持艰苦', '2003-02-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICl1BwnANvVA5-W_P6V2NLeUKeIYdjrwP9AkcdFkJ9TLnhr8Qb2lWWjEyQ3-JF_ObvSXDIRpK4q_DSyq-hPNiBlaoRcj8mUCoDejll14VoRTDe6EOnCR2l1o0zM5G-9t9ajDY3MrFTjuQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened');
INSERT INTO `ds_article` VALUES (5941, '报纸', '利用革命圣地资源 加强军队党的教育', '', '解放军报', '解放军报', '三湾改编;党对军队的绝对领导;“两个务必”;秋收起义;军分区;人武部;', '始终沿着党指引的方向胜利前进 ●袁训忠　赛宗宝 1 嘉兴南湖畔，鲜红的党旗迎风飘扬，向一批批仰慕而至的军旅之子讲述那红色的故事；井冈山深处，飞出“八一军旗红”的嘹亮歌声，抒发着人民军队忠于党的激越豪情；宝塔山上，响起新党员铿锵有力的宣誓声，传递着铁血', '2002-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICJHfWCzfOTCpubUMNkbr0i--QK7zRG_JXwrgI_lixv-fZhVESDFtMkg6-HIwHDrqJnGPIAk5rDt9Ow7DJT0ubNUtAo7-op0Xy9e6yDRaQLRv8Hrqh8uTTNgOKfZyd8p_W2ck-HTxVjQQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened,枣园_screened,遵义会议_screened,红井_screened,叶坪_screened,瑞金_screened,苏维埃共和国_screened,秋收起义_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (5946, '报纸', '不能让革命纪念地蒙羞', '李晋鸿', '人民日报', '人民日报', '革命纪念地;展览馆;', '“七一”前夕，北京农工商 联合总公司朝阳农场组织党员干 部和优秀党员20人赴河北平山县 西柏坡革命纪念地参观学习，但 万万没有想到，他们在这里被一 个假冒的展览馆编了，气愤之余 向本报反映了这一情况。  记者日前前往西柏坡了', '2000-07-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDlzZtS9RMndIb2GP6l0jQCggwsiybdMPYtEsOfXLi07LfJfUBhpmXPFfZGvgOPWO3nxopKulNRDCHPGIyRhFGElh0ptUAOI-W0RqxM2MqbwZM1dpyb3BQbQg7jfC0yGEGIwRzP8R7oeQ==&uniplatform=NZKPT&language=CHS', '两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5947, '报纸', '把以权谋私、贪污腐败看成是极大的耻辱', '郝思斯', '中国纪检监察报', '中国纪检监察报', '贪污腐败;以权谋私;党性党风党纪教育;', '在二十届中央纪委三次全会上，习近平总书记要求，深入开展党性党风党纪教育，传承党的光荣传统和优良作风，激发共产党员崇高理想追求，把以权谋私、贪污腐败看成是极大的耻辱。 “极大的耻辱”这五个字，振聋发聩、发人深省。“把以权谋私、贪污腐败看成是极大的耻辱”是党', '2024-01-23 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2024.000216', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5952, '报纸', '践行“三个务必” 赓续红色血脉', '邢婷婷; 蔡艺芃', '中国纪检监察报', '中国纪检监察报', '中国共产党人;中国特色社会主义;习近平总书记;斗争策略;人民根本利益;', '习近平总书记在党的二十大报告中强调：“全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，坚定历史自信，增强历史主动，谱写新时代中国特色社会主义更加绚丽的华章。”为何要向全党发出“三个务必”的伟大号召？如何理解“三个务必”的丰', '2023-05-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICbY8cYB3erhBx87hrhPFMZfsdIz4cjEkFA8ebXCoaiWfN9bMFfP_DkU5CTR08dXl8nQ4UFJEQ4Cl-0aHvVYZdyZP81bpxUdG2bC6L3C_oWi2B_G-E8vA3UAvGtqnLVHpBSuQlrwp4m6A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (5953, '报纸', '毛泽东是在什么情况下，集中在哪段时间学习《共产党宣言》的？', '', '学习时报', '学习时报', '《共产党宣言》;共产党人;毛泽东;马克思主义者;', '提问：李后强 四川省委四川省人民政府决策咨询委员会副主任、四川省社会科学院二级教授 经常看到这样的说法，毛泽东读《共产党宣言》，读了不下100遍。请问，毛泽东都是在什么情况下，集中在哪段时间读《共产党宣言》的？ 解读：李庆刚 中央党校（国家行政学院）中共党史教', '2023-03-27 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2023.000519', '七届二中全会_screened,抗日战争1_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5956, '报纸', '务必谦虚谨慎、艰苦奋斗', '任理轩', '人民日报', '人民日报', '习近平总书记;政治本色;优良作风;光荣传统;全面从严治党;马克思主义政党;', '习近平总书记在党的二十大报告中强调，全党同志“务必谦虚谨慎、艰苦奋斗”。党的二十大闭幕不到一周，习近平总书记带领中共中央政治局常委来到陕西延安，瞻仰延安革命纪念地。总书记指出：“全党同志要把老一辈革命家和共产党人留下的光荣传统和优良作风传承好发扬好”“全', '2023-01-04 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.000093', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5957, '报纸', '务必不忘初心、牢记使命', '任理轩', '人民日报', '人民日报', '中国共产党;共产党人;习近平总书记;全面从严治党;', '习近平总书记在党的二十大报告中指出：“全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，坚定历史自信，增强历史主动，谱写新时代中国特色社会主义更加绚丽的华章。”这是党中央在全党全国各族人民迈上全面建设社会主义现代化国家新征程', '2023-01-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.000040', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5958, '报纸', '感党恩 听党话 跟党走 在新时代继续保持模范自治区崇高荣誉', '孙绍骋', '内蒙古自治区党委;', '中国民族报', '自治区;民族团结进步教育;党中央;习近平总书记;内蒙古自治运动;中华民族;共产党;', '内蒙古是我们党领导建立的第一个省级少数民族自治区。习近平总书记始终深情牵挂内蒙古各族人民,高度重视内蒙古民族工作。今年3月5日,总书记在参加十三届全国人大五次会议内蒙古代表团审议时重点就铸牢中华民族共同体意识、促进民族团结,对我们作出重要指示、提出明确要求。党', '2022-11-25 08:00:00', 'https://link.cnki.net/doi/10.28114/n.cnki.ncmzb.2022.001179', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5959, '报纸', '牢记“三个务必”', '韩亚栋', '中国纪检监察报', '中国纪检监察报', '习近平总书记;中国共产党历史;奋斗目标;湘江战役;', '习近平总书记在党的二十大报告中号召全党同志牢记“三个务必”：“务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，坚定历史自信，增强历史主动，谱写新时代中国特色社会主义更加绚丽的华章。” 这一伟大号召，充分彰显了百年大党坚定的战略自信', '2022-11-03 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.004398', '七届二中全会_screened,陈树湘_screened,血战湘江_screened');
INSERT INTO `ds_article` VALUES (5960, '报纸', '践行“三个务必” 新征程上苦干实干再立新功', '刘维涛; 赵兵', '人民日报', '人民日报', '全面从严治党;共产党人;习近平总书记;', '习近平总书记在党的二十大报告中指出：“全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，坚定历史自信，增强历史主动，谱写新时代中国特色社会主义更加绚丽的华章。” 10月26日至28日，习近平总书记在陕西省延安市、河南省安阳市考察并', '2022-11-01 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.011811', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5961, '报纸', '深刻领悟“三个务必”', '韩亚栋', '中国纪检监察报', '中国纪检监察报', '习近平总书记;', '习近平总书记在党的二十大报告中提出：“全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，坚定历史自信，增强历史主动，谱写新时代中国特色社会主义更加绚丽的华章。” 73年前，在中国革命即将取得全国胜利之际，毛泽东同志在党的七届二', '2022-10-19 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2022.004196', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5962, '报纸', '“三个务必”彰显百年大党新时代赶考的清醒和坚定', '何忠国', '学习时报', '学习时报', '社会主义;习近平总书记;“两个务必”;', '在中国革命即将取得全国胜利的前夜，毛泽东在党的七届二中全会上向全党同志提出了“两个务必”的要求。习近平总书记在党的二十大报告中又郑重提出，“全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，坚定历史自信，增强历史主动，谱写新', '2022-10-19 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2022.002016', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5963, '报纸', '推进文化自信自强，铸就社会主义文化新辉煌', '于帆; 薛帅', '中国文化报', '中国文化报', '习近平总书记;文化自信;社会主义;', '10月16日10时，举世瞩目的中国共产党第二十次全国代表大会在北京人民大会堂开幕。习近平总书记代表第十九届中央委员会向大会作了题为《高举中国特色社会主义伟大旗帜 为全面建设社会主义现代化国家而团结奋斗》的报告，全面总结了过去五年的工作，勾勒出党和国家未来五年及今', '2022-10-17 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.003573', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5964, '报纸', '深入推进新时代党的建设新的伟大工程', '冯留建', '北京师范大学中共党史党建研究院;', '中国妇女报', '党的建设;底线思维;习近平总书记;全面从严治党;毛泽东;新民主主义革命;共产党人;中华民族;', '2022年7月26日，习近平总书记在省部级主要领导干部“学习习近平总书记重要讲话精神，迎接党的二十大”专题研讨班上发表重要讲话。习近平总书记在讲话中指出，必须持之以恒推进全面从严治党，深入推进新时代党的建设新的伟大工程，以党的自我革命引领社会革命。坚定不移推动全', '2022-08-30 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2022.002705', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5965, '报纸', '“总书记把百姓放在了他的心里”', '罗景月', '中国水利报', '中国水利报', '西柏坡;河北省;北庄村;', '8月5日—12日，在中国记协、全国三教办、河北省委宣传部、河北省记协的组织带领下，记者与行业类媒体近40名青年编辑记者从西柏坡走到阜平县，从雄安智慧社区走到鱼水情深的白洋淀，在革命老区的新面貌和曾经贫困县的振兴现状中，深刻领悟到了“中国共产党为什么行”。 修身', '2022-08-20 08:00:00', 'https://link.cnki.net/doi/10.28136/n.cnki.ncslb.2022.001808', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5966, '报纸', '雄浑河北，慷慨燕赵踏歌行', '吴艳霞; 孟冬; 王泽帅', '人民法院报', '人民法院报', '习近平总书记;社会矛盾纠纷;人民法院;张家口市;巡回法庭;滑雪场;', '河北是一片蕴含光荣革命历史的红色热土，西柏坡是“两个务必”发源地和“进京赶考”出发地，正定被习近平总书记称作“第二故乡”，总书记对河北充满感情、寄予厚望。 党的十八大以来，总书记9次赴河北考察。从生机勃勃的塔元庄到郁郁葱葱的塞罕坝，从徐徐铺展的雄安画卷到惊', '2022-08-08 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2022.002827', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5967, '报纸', '增强忧患意识 始终居安思危', '陈家兴', '人民日报社评论部;', '学习时报', '忧患意识;习近平总书记;', '在庆祝中国共产党成立100周年大会上，习近平总书记指出“过去一百年，中国共产党向人民、向历史交出了一份优异的答卷。现在，中国共产党团结带领中国人民又踏上了实现第二个百年奋斗目标新的赶考之路”，强调“新的征程上，我们必须增强忧患意识、始终居安思危”，并代表党中', '2022-07-22 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2022.001346', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (5968, '报纸', '致敬百年辉煌 谱写新的篇章', '韩洁', '中国文化报', '中国文化报', '博物馆;共产党人;红色旅游;延安精神;红色资源;古田会议;红色基因;南湖红船;西柏坡精神;教育示范基地;红船精神;', '本报集体采写 101年前，浙江嘉兴南湖上一条小小红船播撒下中国革命的星星火种，开启了中国共产党的伟大航程。如今，这里成为无数后人游览参观学习的地方，大家在这里缅怀先辈、回望历史、领悟伟大建党精神。 不止嘉兴南湖，井冈山、古田、延安、西柏坡……这些在党的历史中', '2022-07-06 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2022.002060', '七届二中全会_screened,西柏坡_screened,井冈山革命博物馆_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (5970, '报纸', '“窑洞之问”的答卷人', '杜尚泽; 刘少华', '人民日报海外版', '人民日报海外版', '全面从严治党;毛泽东;六中全会;习近平总书记;', '黄土地上的几孔窑洞，在百年党史上留下了不可磨灭的印记。 在陕北考察结束后不久，习近平总书记在党的十九届六中全会上，再次讲述了发生在延安窑洞里、昭示了中国共产党未来走向的一场对话。 1945年夏天，民主人士黄炎培应邀走进毛泽东同志的窑洞。彼时，距离1840年鸦', '2022-01-14 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2022.000177', '七届二中全会_screened,七届二中全会_screened,两个务必_screened,两个务必_screened,西柏坡_screened,西柏坡_screened,抗日战争1_screened,抗日战争1_screened,遵义会议_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5971, '报纸', '常怀远虑 居安思危', '', '解放军报', '解放军报', '忧患意识;应对挑战;共产党人;', '历史的画卷，在砥砺前行中铺展。1949年3月，面对全国胜利已成定局的大好形势，毛泽东同志在党的七届二中全会上明确提出“两个务必”，要求全党在胜利面前要保持清醒头脑。 时代的华章，在接续奋斗里书写。喜迎新年、举国欢庆之际，习主席在新年贺词中再次强调忧患意识，要', '2022-01-02 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.000007', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5972, '报纸', '坚持自我革命的力量源泉', '戚建国', '全国政协;提案委员会;', '人民政协报', '革命史;中国共产党;百年历程;习近平总书记;马克思主义中国化;力量源泉;', '习近平总书记指出，勇于自我革命，是我们党最鲜明的品格，也是我们党最大的优势。中国共产党的伟大不在于不犯错误，而在于从不讳疾忌医，敢于直面问题，勇于自我革命，具有极强的自我修复能力。党的十九届六中全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的', '2021-12-29 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.009831', '七届二中全会_screened,两个务必_screened,中共七大1_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (5973, '报纸', '千万别在喝彩声中迷失自我', '辛源', '32737部队;', '解放军报', '迷失自我;奋斗历程;毛泽东;优良作风;忧患意识;“两个务必”;', '对于一个人来说，经得住批评是一种考验，经得住赞扬有时则是一种更大的考验。这对于一个政党也不例外。 习主席在党的十九届六中全会第二次全体会议上谆谆告诫全党：“我们党历经百年、成就辉煌，党内党外、国内国外赞扬声很多。越是这样越要发扬自我革命精神，千万不能在', '2021-12-14 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.007694', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5974, '报纸', '党在西柏坡时期的学习', '李祖发', '军事科学院;', '学习时报', '西柏坡时期;政治成熟;华北解放区;', '党在西柏坡时期，从1947年7月12日中央工委在西柏坡宣告正式成立至1949年3月23日中共中央迁往北平（北京），围绕马克思主义理论、党的政策和纪律及城市建设管理等，在全党全军干部中开展了一次范围广泛、内容全面、意义深远的学习，极大地促进我们党的政治成熟，大规模地培养', '2021-12-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDPp5VqrXP-OfA8uUZPzaURwyf_4RKbVrkukAgofclwHFoALTtQjqtPab4J3g4m6YBPdy3ubgyo4cY8tqS5xmXIhziXk7m6YRkRwtJDw5pEDn_gh9DS4g_4ECp7wBpQ7n6VkEFubTGXDg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5975, '报纸', '《香山叶正红》：以“正在进行时”回望新中国诞生路', '杨雯', '中国新闻出版广电报', '中国新闻出版广电报', '中共中央;七届二中全会;《香山叶正红》;', '由巴特尔执导，盛和煜、柳桦编剧，唐国强、言午领衔主演的重大革命历史题材电视剧《香山叶正红》正在CCTV-1热播。该剧聚焦中共中央在香山181天的光辉岁月，引领观众回望新中国成立前夕的风云际会，回顾党的奋斗成就和历史经验，重温了历久弥坚的“赶考精神”。 没有共产党', '2021-12-01 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004723', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5976, '报纸', '理论新意讲述 融媒创意表达', '齐雅文', '中国新闻出版广电报', '中国新闻出版广电报', '创意表达;', '湖南日报社自9月起在多平台推出11期大型融媒体访谈节目《真理的光芒》，受到读者的关注和喜爱，多平台呈现刷屏之势。为庆祝中国共产党成立100周年，生动讲述党史故事，《真理的光芒》邀请到党史理论专家、思政学者教授等，带领观众读伟人著作、重温经典文献，各路记者纷纷进', '2021-11-23 08:00:00', 'https://link.cnki.net/doi/10.28907/n.cnki.nxwcb.2021.004585', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5977, '报纸', '按照共产主义理想，创造一个新社会', '', '中国共产党历史展览馆;', '学习时报', '《共产党宣言》;陈望道;中译本;《星期评论》;中国共产党历史;马克思主义;共产党人;共产主义理想;展览馆;', '习近平总书记指出：“《共产党宣言》是一部科学洞见人类社会发展规律的经典著作，是一部充满斗争精神、批判精神、革命精神的经典著作，是一部秉持人民立场、为人民大众谋利益、为全人类谋解放的经典著作。马克思主义理论的科学性和革命性源于辩证唯物主义和历史唯物主义的科', '2021-11-19 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.002193', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5978, '报纸', '重走新中国走来之路河北西柏坡:', '楼家强', '全国政协;香港青年联会;', '人民政协报', '西柏坡;七届二中全会;红色精神;', '中国共产党成立百年以来，无数革命事迹和红色精神激励着一代又一代青年。回想起10年前，我与诸多香港青年同行的那次西柏坡红色之旅，仍然感受到满满的力量。 西柏坡位于河北省石家庄市平山县中部，这里曾是中共中央所在地。当年，党中央在此指挥了辽沈、淮海、平津三大战', '2021-11-12 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2021.008732', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5979, '报纸', '书写中华民族几千年历史上最恢宏的史诗', '汪晓东; 张炜; 宋静思', '人民日报', '人民日报', '习近平总书记;中国共产党成立;党史学习;中国特色社会主义共同理想;信仰者;中华民族;全面从严治党;', '“一百年来，中国共产党团结带领中国人民，以‘为有牺牲多壮志，敢教日月换新天’的大无畏气概，书写了中华民族几千年历史上最恢宏的史诗。这一百年来开辟的伟大道路、创造的伟大事业、取得的伟大成就，必将载入中华民族发展史册、人类文明发展史册!”今年7月1日，习近平总书', '2021-11-06 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011711', '七届二中全会_screened,两个务必_screened,西柏坡_screened,抗日战争1_screened,中共七大1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (5980, '报纸', '感悟百年党史 践行延安精神', '冯鹏志', '中央党校(国家行政学院)哲学部;', '学习时报', '延安精神;中华民族;中国具体实际;', '延安是中国革命的圣地，延安时期留给我们最宝贵的财富，就是跨越时空的延安精神。伟大的延安精神，特别是其所承载的坚定正确的政治方向、解放思想实事求是的思想路线、全心全意为人民服务的根本宗旨、自力更生艰苦奋斗的创业精神这一根本内涵，深刻地凝练了中国共产党人在百', '2021-10-25 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001987', '七届二中全会_screened,两个务必_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (5981, '报纸', '弘扬西柏坡精神：走在新时代的“赶考”路上', '李昱霖', '工人日报', '工人日报', '西柏坡精神;张家口;', '1949年3月23日，党中央从河北平山县西柏坡动身前往北平。毛泽东主席说，今天是进京赶考的日子。 2013年7月，习近平总书记在西柏坡表示：“考试”仍在继续，所有领导干部和全体党员要继续把人民对我们党的“考试”、把我们党正在经受和将要经受各种考验的“考试”考好，努', '2021-10-24 08:00:00', 'https://link.cnki.net/doi/10.28277/n.cnki.ngrrb.2021.004850', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5982, '报纸', '传承西柏坡精神 书写新时代赶考答卷', '陈发明', '经济日报', '经济日报', '西柏坡;七届二中全会;中国共产党;西柏坡纪念馆;毛泽东;共产党人;习近平总书记;“两个务必”;李家庄村;', '西柏坡，一个太行山东麓的小山村，在中国共产党百年历程中，是一个耀眼的红色地标：享有“两个务必”诞生地、“赶考”出发地、“新中国从这里走来”等盛誉。 1948年5月至1949年3月，中共中央在河北平山县西柏坡办公，指挥了辽沈、淮海、平津三大战役，召开了著名的七届二', '2021-10-23 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.007525', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5983, '报纸', '精神如炬 征途如虹', '窦道琴; 徐亚军', '解放军报', '解放军报', '长征精神;红色基因;听党指挥;红军长征;精神谱系;人民军队;共产党人;战略转移;', '编者按 今年是红军长征胜利85周年。历史的硝烟，血染的记忆，雄关漫道二万五千里。长征这一惊天动地的革命壮举，是中国共产党和红军谱写的壮丽史诗，是中华民族伟大复兴历史进程中的巍峨丰碑。心中有信仰，脚下有力量。在中国共产党百岁诞辰之年，在我们党带领全体中华儿', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.006728', '七届二中全会_screened,强渡大渡河_screened,遵义会议_screened,血战湘江_screened,四渡赤水_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (5984, '报纸', '弘扬西柏坡精神，不断从胜利走向新的胜利', '', '人民日报', '人民日报', '西柏坡精神;共产党人;毛泽东;奋斗目标;七届二中全会;', '西柏坡，一个永载中国革命史册的名字。2013年7月，习近平总书记来到西柏坡，指出“西柏坡我来过多次，每次都怀着崇敬之心来，带着许多思考走”，告诫“党面临的‘赶考’远未结束”，强调“全党同志要不断学习领会‘两个务必’的深邃思想，始终做到谦虚谨慎、艰苦奋斗、实事求', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011116', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5985, '报纸', '牢记“两个务必” 传承西柏坡精神', '徐运平; 张贺; 郑海鸥', '人民日报', '人民日报', '西柏坡精神;党中央;毛泽东;“两个务必”;习近平总书记;', '全党同志要不断学习领会“两个务必”的深邃思想，始终做到谦虚谨慎、艰苦奋斗、实事求是、一心为民，继续把人民对我们党的“考试”、把我们党正在经受和将要经受各种考验的“考试”考好，使我们的党永远不变质、我们的红色江山永远不变色。 ——摘自习近平总书记2013年在', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.011132', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5986, '报纸', '赶考永远在路上', '王昊魁; 王琎; 陈元秋', '光明日报', '光明日报', '习近平总书记;中国共产党成立;共产党人;西柏坡纪念馆;西柏坡精神;党中央;敢于胜利;请示报告制度;毛泽东;中华儿女;九月会议;敢于斗争;中共中央旧址;在路上;', '金风送爽，硕果盈枝，10月的西柏坡碧空如洗，天远地阔。 位于河北省平山县的西柏坡纪念馆和中共中央旧址，参观者络绎不绝。广场上，五大书记塑像前，人们或驻足凝视，或排队合影。鲜花簇拥的“西柏坡 新中国从这里走来”几个大字，格外耀眼夺目。纪念馆内，一页页泛黄的文', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.005377', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5987, '报纸', '艰苦奋斗 一心为民', '范思翔; 闫起磊', '新华社;', '新华每日电讯', '西柏坡精神;习近平总书记;七届二中全会;毛泽东;奋斗目标;西柏坡镇;共产党人;', '西柏坡，一个永载党史的精神地标。 70多年前，新中国从这里走来——1948年5月至1949年3月，中共中央在河北省平山县西柏坡办公，描绘新中国的宏伟蓝图，这里成为党中央解放全中国的“最后一个农村指挥所”。 70多年后，“赶考”之路仍在继续——“全党同志要不断学习领', '2021-10-22 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.008125', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5989, '报纸', '弘扬西柏坡精神 当好新时代“答卷人”', '青平', '中国青年报', '中国青年报', '西柏坡精神;七届二中全会;人民代表大会;毛泽东;共产党人;西柏坡时期;习近平总书记;人民民主专政;', '1948年5月至1949年3月，中共中央曾在地处太行山东麓的河北省平山县西柏坡办公。在这个解放全中国的“最后一个农村指挥所”，党中央指挥了辽沈战役、淮海战役、平津战役三大战役，召开了著名的七届二中全会，作出了关系中国革命前途命运的一系列重大决策，为夺取全国政权奠定', '2021-10-21 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2021.003774', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5990, '报纸', '重温《党委会的工作方法》 提升新时代审计工作效能', '程光', '审计署长沙特派办;', '中国审计报', '《党委会的工作方法》;毛泽东;领导班子;习近平总书记;民主集中制;工作效能;', '新中国成立前夕,毛泽东同志在党的七届二中全会上所作的结论中,系统阐述了党委会的工作方法并将其概括为十二条,是一篇加强党委领导班子建设、提升党的领导水平和执政能力的光辉文献。习近平总书记曾就学习毛泽东同志《党委会的工作方法》作出重要批示,要求各级党委(党组)领导', '2021-09-29 08:00:00', 'https://link.cnki.net/doi/10.28132/n.cnki.ncsjb.2021.001206', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5991, '报纸', '华北银行：短暂而辉煌', '郑志瑛', '邯郸银行股份有限公司;', '金融时报', '人民政府;晋冀鲁豫边区政府;', '中国人民银行是以华北银行为基础筹备建立的。华北银行虽地位重要，却未发钞票，存续时间极短，史料很少，是中外银行史上的一个特殊的存在。为揭开华北银行的神秘面纱，笔者数次赴石家庄市参访原华北银行总行办公楼——中国人民银行成立旧址纪念馆，遍览了1948年全年《人民日', '2021-09-24 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.005044', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5992, '报纸', '中国共产党勇于自我革命的百年演进', '王岐海', '中央党校(国家行政学院)厅局级干部进修班;', '学习时报', '中国共产党;党的政治建设;自我净化;', '勇于自我革命，是中国共产党最鲜明的政治品格、最大的优势，也是中国共产党区别于其他政党的显著标志。勇于自我革命是我们党事业取得成功的关键所在，也是我们党发展壮大、长盛不衰的内在动力，永葆蓬勃朝气和生机活力的动力源泉。百年党史就是一部我们党勇于自我革命的历史', '2021-09-22 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2021.001761', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (5993, '报纸', '“我们是从这里走过来的”', '杜尚泽; 王乐文; 张晓松; 朱基钗', '新华社;', '人民日报', '习近平总书记;共产党人;毛泽东;', '陕北的路，是一眼望不尽的峁梁连绵，沟壑纵横。飞机、火车、汽车，一路辗转奔波。 9月13日至14日，在赴西安出席全运会开幕式前夕，习近平总书记到陕西榆林考察调研。中国共产党人对陕北有一份深深的感情，习近平总书记对陕北有一份深深的牵挂。 发展的转型： 从“黑', '2021-09-18 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.009979', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5994, '报纸', '百年来中国共产党经济思想之演变', '焦建华', '厦门大学经济学院;', '金融时报', '经济思想;党的领导;中国共产党;', '中国共产党的经济思想是在马克思主义指导下，在长期革命斗争和经济建设中逐渐形成的，并随着现实条件的不断变化而进行相应的修正与总结，从而呈现出明显的阶段性。回顾一百年的历史进程，党的经济思想随着形势变化而不断创新发展，深刻影响着当前及未来党的经济思想的发展方', '2021-09-06 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.004712', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5995, '报纸', '汲取红色力量 奔向“诗和远方”', '范海刚; 李秋云', '中国文化报', '中国文化报', '旅游大省;张家口;文化旅游区;红色旅游目的地;河北省;燕赵大地;旅游景区;旅游强省;大运河;', '2013年7月，习近平总书记来到革命圣地西柏坡，动情地说：“西柏坡我来过多次，每次都怀着崇敬之心来，带着许多思考走。”并意味深长地告诫全党，“党面临的‘赶考’远未结束。”在西柏坡，中共中央指挥了辽沈、淮海、平津三大战役，七届二中全会上毛泽东同志向全党提出了“两', '2021-08-25 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2021.002625', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5996, '报纸', '“四个全面”擘宏图', '', '人民日报', '人民日报', '全面从严治党;纪律建设;党内法规;党的纪律;四个全面;', '47.为什么要把纪律的螺丝拧得紧而又紧？ “党的纪律为铁的纪律”，这是1920年蔡和森给毛泽东同志写信，探讨建立中国共产党时提出的重要论断。延安整风时期，毛泽东同志形象地指出，孙行者头上套的箍是金的，共产党的纪律是铁的，比孙行者的金箍还厉害，还硬。党的纪律是党', '2021-08-19 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.008753', '七届二中全会_screened,西柏坡_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (5997, '报纸', '标本施治稳经济', '吕立勤; 梁剑箫', '经济日报', '经济日报', '人民政府;共产党;物价波动;财政赤字;人民币;恶性通货膨胀;中财委;货币发行;物价上涨;资本家;', '1948年秋至1949年春，中国共产党先后组织辽沈、淮海、平津三大战略性战役及其他重要战役，以气势磅礴的大手笔，精心绘就解放战争恢弘的历史画卷。 走进刚刚从国民党手中夺回的一座座城市，摆在中国共产党人面前的，是扑面而来的和平渴望、重整河山的民生期待。如何稳定经', '2021-08-06 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2021.005831', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5998, '报纸', '为社会主义事业奋斗余生', '李文泉', '中华女子学院;', '中国妇女报', '社会主义事业;反动派;党中央;', '我生在旧社会、长在红旗下，自9岁时父亲为革命牺牲后，就是在共产党和人民政府的关怀照顾下成长。从小学到中学都是人民助学金养育的我。在中学毕业时，我心怀继承父亲的革命遗志，参加了中国人民解放军。在党的培养教育下，我入伍第二年就成为一名光荣的中国共产党党员。65年', '2021-08-05 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.002565', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (5999, '报纸', '中国共产党党内法规体系', '', '中共中央办公厅法规局;', '人民日报', '党内法规;党中央;党的领导;中国共产党;中国共产党纪律处分条例;', '前言 2021年7月1日，习近平总书记在庆祝中国共产党成立100周年大会上宣布，我们党已经“形成比较完善的党内法规体系”。这一制度建设重大成果来之不易，是我们党100年来持续推进建章立制特别是党的十八大以来全面深化党的建设制度改革的结果；这一党的建设重要成就彪炳史', '2021-08-04 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.008151', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6000, '报纸', '百年大党组织建设的发展历程与经验启示', '赵智奎', '中国社会科学院马克思主义研究院;', '金融时报', '党的组织建设;政治局;全面从严治党;组织工作会议;战斗堡垒作用;干部队伍建设;中国共产党;习近平总书记;民主集中制;基层党组织带头人;经验启示;党的基层组织;支部建在连上;党内民主;', '今年正值中国共产党的百年华诞。在波澜壮阔的历史进程中，中国共产党由小到大，从弱到强，义无反顾肩负起实现中华民族伟大复兴的历史使命。习近平总书记在庆祝中国共产党成立100周年大会上的讲话中指出：“以史为鉴，可以知兴替。我们要用历史映照现实、远观未来，从中国共产', '2021-07-19 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.007289', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6001, '报纸', '河北：赶考路启航新征程', '赵珊', '人民日报海外版', '人民日报海外版', '精品线路;跳台滑雪;红色旅游资源;', '习近平总书记在庆祝中国共产党成立100周年大会上的讲话中指出，过去一百年，中国共产党向人民、向历史交出了一份优异的答卷。现在，中国共产党团结带领中国人民又踏上了实现第二个百年奋斗目标新的赶考之路。 河北是中国共产党“进京赶考”的出发地。河北是革命的土地、英', '2021-07-16 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.002141', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6002, '报纸', '会师金汤桥：一座城市的浴火新生', '卫雨檬; 李伟欣; 赵婉姝; 邢邦明', '战地记者队;', '解放军报', '金汤桥;天津城;城市攻坚战;天津战役;解放军;解放战争;', '访谈专家：军事科学院 徐飞 夏日雨中。海河轻曼蜿蜒，从天津城中温柔流过。 站在金汤桥头举目望去——东岸，是复古的老津门，旧时“十里洋场”的异域建筑在雨雾中愈显沧桑；西岸，是广厦万间的新天津，因降雨而略显空旷的街道上，一辆辆闪亮的小汽车鱼贯而过，尽显现代', '2021-07-09 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2021.004375', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6003, '报纸', '感悟追寻理想之路', '李笑萌', '光明日报', '光明日报', '理想之路;', '在建党百年系列报道中，我踏上了河北这片革命热土。从西柏坡纪念馆到中央统战部旧址，从晋察冀边区革命纪念馆到阜平县烈士陵园……革命先烈的故事在我面前一页页打开。而在时光的另一头，是干净整洁的农家小院，是鳞次栉比的致富大棚，是乡亲们用红火日子绘就的一幅多彩画卷', '2021-07-05 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003409', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6004, '报纸', '走好新时代商务发展的“赶考路”', '陈高鹏; 田甜', '国际商报', '国际商报', '政务服务;自贸试验区;河北省;', '太行山东麓，滹沱河北岸，绿水青山环抱西柏坡。燕赵大地辽阔壮美，众山之中，得开一番红色天地。这里有不可磨灭的红色印迹，“三大战役”在这里指挥，“两个务必”在这里诞生，“进京赶考”从这里出发，新中国从这里走来。 1949年3月23日，党中央从河北平山县西柏坡动身前', '2021-07-02 08:00:00', 'https://link.cnki.net/doi/10.28270/n.cnki.ngjsb.2021.003133', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6005, '报纸', '迈进伟大新时代', '李志勇', '中国纪检监察报', '中国纪检监察报', '习近平总书记;战略布局;党中央;全面从严治党;', '百年风华正茂，百年风雨兼程。 经过长期奋斗，中国特色社会主义进入新时代。党的十八大以来，以习近平同志为核心的党中央团结带领全党全军全国各族人民，不忘初心、牢记使命，统筹推进“五位一体”总体布局，协调推进“四个全面”战略布局，推动党和国家事业取得历史性成', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2021.003143', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6008, '报纸', '强基固本筑堡垒 凝心聚力担使命', '', '新华社;', '新华每日电讯', '基层党建工作;党中央;疫情防控;全面从严治党;农村基层党组织建设;习近平总书记;村党组织;非公企业党建;党的政治建设;企业党建工作;农村基层干部;社区党组织;高校思想政治工作;联系服务群众;凝心聚力;', '党的力量来自组织。上下贯通、执行有力的严密组织体系，是马克思主义政党的优势所在、力量所在。其中，党的基层组织是党的肌体的“神经末梢”，是党执政大厦的地基。 1927年9月，三湾改编决定“支部建在连上”。毛泽东同志曾指出，“红军所以艰难奋战而不溃散，‘支部建在', '2021-07-01 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2021.005192', '七届二中全会_screened,七届二中全会_screened,七届二中全会_screened,三湾改编_screened,三湾改编_screened,三湾改编_screened');
INSERT INTO `ds_article` VALUES (6009, '报纸', '中国共产党一百年大事记', '', '中共中央党史和文献研究院;', '人民日报', '中国共产党;周恩来;抗日根据地;决议案;毛泽东;武装斗争;', '1840年以后，由于西方列强的入侵，由于封建统治的腐败，中国逐渐成为半殖民地半封建社会。实现中华民族伟大复兴成为全民族最伟大的梦想；争取民族独立、人民解放和实现国家富强、人民幸福，成为中国人民的历史任务。许多献身于民族进步事业的爱国先驱，前赴后继、不懈探索。', '2021-06-28 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.006749', '七届二中全会_screened,两个务必_screened,两个务必_screened,西柏坡_screened,西柏坡_screened,扎西会议_screened,夹金山_screened,将台堡_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (6010, '报纸', '百年大党恰是风华正茂', '刘少华', '人民日报海外版', '人民日报海外版', '中国共产党成立;改革开放;习近平总书记;新民主主义革命;社会主义建设;奋斗目标;社会主义基本制度;共产党人;', '建立中国共产党 夺取新民主主义革命伟大胜利 一百年前，中国共产党成立，这是开天辟地的大事变。 在中国共产党历史展览馆中，摆放着19世纪末20世纪初很多书籍报刊，《时务报》《洞庭波》《中国女报》《浙江潮》《猛回头》《革命军》《警世钟》《湘江评论》《新青年》…', '2021-06-28 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2021.001975', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6011, '报纸', '我们要坚定不移拥护党跟党走', '周福志; 王欣雨', '团结报', '团结报', '中国共产党领导;百年华诞;共产党;祖国统一;何鲁丽;参政党;', '2021年，中国共产党迎来百年华诞。中国共产党成立100年、执政72年，始终坚守为人民谋幸福、为民族谋复兴的初心和使命，团结带领中国人民顽强拼搏、接续奋斗，创造了一个又一个让世界惊叹的“中国奇迹”。中国共产党为什么能？这是值得深入思考研究、科学阐释解答的重大课题。', '2021-06-24 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.001280', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6012, '报纸', '中国共产党对外开放思想与实践的百年回顾', '陈建奇', '中央党校国际战略研究院;国际战略研究所世界经济室;', '金融时报', '对外开放理论;习近平;WTO;经济全球化;对外开放思想;国际经贸合作;自贸试验区;中国共产党;关贸总协定;世界贸易组织;百年回顾;', '以习近平同志为核心的党中央总揽战略全局，推进对外开放理论和实践创新，确立开放发展新理念，实施“一带一路”倡议，共建开放型世界经济，积极参与全球经济治理体系改革。对外开放新战略顺应全球化大势，不断深化中国国际经贸合作，释放对外开放新动能，推动国内国际双循环', '2021-05-31 08:00:00', 'https://link.cnki.net/doi/10.28460/n.cnki.njrsb.2021.007183', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6013, '报纸', '坚持效果导向 做到“五个自觉”', '贺恒扬', '重庆市人民检察院;', '检察日报', '习近平总书记;绝对领导;党史学习;人民检察制度;检察官;中国特色社会主义道路;法治思维;修正错误;全面依法治国;监督职责;党中央;政治自觉;', '习近平总书记对中国共产党历史的深邃思考，饱含他对重大史实的深刻总结，展现了战略思维、辩证思维、系统思维、底线思维、创新思维。通过学习习近平总书记《论中国共产党历史》，我深刻体会到，革命、建设、改革、复兴，必须有科学的理论指导，必须有正确的方针政策，必须有', '2021-05-21 08:00:00', 'https://link.cnki.net/doi/10.28407/n.cnki.njcrb.2021.002554', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6014, '报纸', '中国共产党百年辉煌与中国现代化', '顾海良', '北京市习近平新时代中国特色社会主义思想研究中心;', '人民日报', '中国共产党;治理能力现代化;中国式;社会主义初级阶段;中国特色社会主义现代化建设;“三步走”战略;奋斗目标;四个现代化;国家治理体系;邓小平同志;', '核心阅读 一百年来，我们党带领人民不懈探索，走出了一条中国式的现代化道路，丰富和拓展了对社会主义现代化的认识。中国特色社会主义现代化建设的伟大成就，深深镌刻在中国共产党百年奋进的光辉史册中。在新征程上，我们要不断开创全面建设社会主义现代化国家新局面，书', '2021-04-22 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.004185', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6015, '报纸', '天津解放：天津市归为人民所有', '高丽; 贺文聪', '中国妇女报;天津农学院;', '中国妇女报', '天津市;天津战役;', '四月的天津，海棠花开满城。刚刚过去的清明节小长假，五大道风景区的大理道，也因落英缤纷的海棠花火出圈，每日游人如织，在粉色的花海中徜徉。 前来驻足打卡的游人想象不到，72年前，这座城市曾经历一场激战，也正因这场战役，从此发生了翻天覆地的重大变化——天津解放', '2021-04-15 08:00:00', 'https://link.cnki.net/doi/10.28067/n.cnki.ncfnb.2021.001132', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6016, '报纸', '从志愿讲解中感悟伟大的精神力量', '凌达; 陈元秋; 耿建扩', '河北地质大学;', '光明日报', '精神力量;讲解员;西柏坡纪念馆;', '“最后的一碗米，用来做军粮，最后的亲骨肉，送到战场上”，每当回想起我当志愿者讲解员时经常唱起的这首《西柏坡拥军小唱》，心中总是为之颤抖。 2019年1月，我报名参加了学校组织的前往西柏坡纪念馆的实习活动，担任学生志愿者讲解员。参加之前，我对西柏坡这段历史的了', '2021-02-09 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.000715', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6017, '报纸', '对美国对华政策侵略本质的深刻揭露', '许宝健', '学习时报', '学习时报', '司徒雷登;对华政策;帝国主义;艾奇逊;白皮书;毛泽东;国民党反动派;', '（一） 1949年8月5日，离中华人民共和国成立不足两个月，美国政府发表了《美国与中国的关系》白皮书。白皮书在这个时候发表不是偶然的，它有着深刻的时代背景。 经过3年的解放战争，特别是辽沈、淮海、平津三大战役取得决定性胜利之后，中国东方的地平线已经渐渐露出曙', '2020-11-04 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2020.002229', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6018, '报纸', '人民军队战旗妍', '夏明星', '中国人民武装警察部队警官学院;', '人民政协报', '中国人民解放军军旗;国民党反动派;武装反抗;共产党;南昌起义;中央军委;工农革命军第一军第一师;湘赣边界秋收起义;中国工农红军;', '军旗，又称战旗，是一支军队的灵魂和象征，也是激励全体官兵团结战斗的精神旗帜。1927年9月，毛泽东领导湘赣边界秋收起义，创建了中国工农革命军，开始了农村包围城市、武装夺取政权的伟大实践，从中诞生了人民军队的第一面军旗——工农革命军军旗。 从工农革命军军旗到中', '2020-08-06 08:00:00', 'https://link.cnki.net/doi/10.28660/n.cnki.nrmzx.2020.004522', '七届二中全会_screened,苏维埃共和国_screened,秋收起义_screened,反围剿_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (6019, '报纸', '从党史中汲取攻坚克难智慧力量', '王向明; 成山', '中国人民大学习近平新时代中国特色社会主义思想研究院;西北工业大学马克思主义学院;', '中国纪检监察报', '必修课;历史观;中国共产党;习近平总书记;智慧力量;攻坚克难;', '我们党在内忧外患中诞生，在磨难挫折中成长，在攻坚克难中壮大。99年艰苦奋斗创造出的重要历史经验，为我们提供无尽的力量和无穷的智慧。面对深刻复杂的国内外形势，我们更加需要加强党史学习，深入思考，更好地认识过去、把握当下、走向未来。 中国革命历史是最好的营养', '2020-06-30 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2020.002999', '七届二中全会_screened,两个务必_screened,西柏坡_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (6020, '报纸', '万古官箴“两为耻”', '左连璧', '辽宁省高级人民法院;', '人民法院报', '为官者;真德秀;', '真德秀，南宋后期理学家，官至户部尚书，翰林学士。他对时政屡有直声，奏疏不下数十万字。一次，与皇上对话时他说：“有位于朝者，以馈赂及门为耻；受任于外者，以苞苴入都为耻。”这里的“苞苴”，本指包裹鱼肉的蒲包，后泛指赠送的礼物，引申为贿赂。这段话说的是，凡是在', '2019-12-20 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2019.000468', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6021, '报纸', '中国特色社会主义道路来之不易', '王雅婧', '中国纪检监察报', '中国纪检监察报', '中国特色社会主义道路;封建主义;帝国主义;中国共产党成立;李君如;', '中国共产党自成立之日起，就始终坚持群众路线，始终扎根于人民大众之中。一切为了人民，一切依靠人民，带领中国人民走出一条中国特色社会主义道路，迎来了从站起来、富起来到强起来的历史性飞跃。 是什么让中国共产党永葆年轻？中国特色社会主义道路为什么越走越宽广？围', '2019-08-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAU127ZB2wmD5gbpXxgPuVlNHVSEupNMFTWk8OeIykssquNi1xQgdK3yWyqOAa2WEqwQhY0IrDeYYZnzVvb9NHEzTI9wUqolmuTrF3BHoA9orkkN3dhR28y5DybUHJlEPU5Xj_j37N8zQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6022, '报纸', '回望政协初创路', '张同乐; 史宝强; 王冠军', '河北师范大学;中共河北省委统战部;河北省政协研究室;', '人民政协报', '决议案;毛泽东;人民团体;新政协筹备会;民主党派;全国人民代表大会;“五一口号”;', '和舟共济七十载，岁月峥嵘谱华章。在举国同庆新中国成立70周年、人民政协成立70周年之际，河北省政协、石家庄市政协成立了《人民政协与西柏坡研究》课题组。本文是课题组的成果之一，就是对毛泽东对“五一口号”的修改细节、“五一口号”的不同版本、新政协概念的提出及新政', '2019-08-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBF_z1wDZG6kcJgiBkEg0s_ObXY5m9GqXg0cpUcZoIh-YqptUuXQUQm7YSS_tLJBUCWd4WXqnoJyyuuKQXbDzuvq_SdYtxrXnnV_DhwVCkBiztACd8cfzIyyGdbi_oHxdBgXPEL5uCkNw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6023, '报纸', '谋划和建设一个新中国', '毛胜', '中央党史和文献研究院;', '中国纪检监察报', '人民民主专政;人民解放战争;中国共产党;机车司机;民主主义;帝国主义;新政协筹备会议;毛泽东;', '1949年的7月1日，是个特殊的日子。这一天是中国共产党成立28周年纪念日，党领导的人民解放战争即将迎来全面胜利，几代中国人期盼的民族独立、人民解放已经指日可待。在欢庆这个不同以往的“七一”之时，全党、全国人民回望来路，眺望远方，开始谋划和建设一个新中国，彰显了', '2019-07-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDkDSKVkOoAAmsu9e8jdYiHvmdgIpptiFgONCz6ii7P5KBIwW5869A3K_rlWhbvQPT-Bud6_0nfn4K07OpEmRm0zb8-QeU6UQfZUJ4T3DYtyg-Z8o2ECyvQvZ5voCOVbZDqrpwtrNc8Aw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6024, '报纸', '为建立新中国作出战略部署', '白瑞华; 沈传亮', '学习时报', '学习时报', '七届二中全会;战略部署;“两个务必”;', '1949年3月召开的中共七届二中全会，是中国共产党在即将成功夺取全国政权前夕召开的一次重要会议。毛泽东在会上作了一个蕴含丰富战略思维、带有极强预见性的报告，为建立新中国作出战略部署。重读这篇讲话，对于我们在新中国成立70周年之际，回顾过去，立足当下，更好谋划未来', '2019-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA9_1lv-3S1xJDh0MGt77-jsQM9aUReUC5-K5x2uZI-ld_WydoLOhtFq2W7JR4JIxfAag6mOQlqw9-bfUdMrxsIstqgfKQKQfkvfC7fMPs59sBRYXfjHHmmv_NQks5E0xUCdF37OBbqTQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6025, '报纸', '郭建宁：中国共产党人的初心和使命', '郑芳芳', '光明网;', '光明日报', '中国共产党人;中华民族伟大复兴;习近平新时代中国特色社会主义思想;', '初心是本心、本源，党性修养是共产党人的“心学”。初心是本色、底色，要永远保持共产党人的政治品质，筑牢共产党人的精神基石。初心是信仰、理想，具体体现为坚定马克思主义信仰和共产主义远大理想。初心是信念、信心，要始终坚定中国特色社会主义的信念和中华民族伟大复兴', '2019-06-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDRCPLVwM9liNGppxdWlgW9xbDDCvk8GByaTG_wkPtHGk5akUokPrjEmTFZUz3LW_CydwJyP0zI1d9iqA3n22f1yNMxvCg4ZGjGdZnKc_6hxir-9hptb9WT9MaD1Pxnqwr9AVZmLHQWOg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6026, '报纸', '赶考，永远在路上', '', '光明日报', '光明日报', '“两个务必”;在路上;习近平总书记;', '70年前，党中央从西柏坡进京“赶考”；70年后，西柏坡和其所在的平山县一起脱贫出列，交出了一张新时代的“赶考”答卷。西柏坡，这个太行山东麓的只有几十户人家的小山村，借助红色旅游的东风，打造了一个宜居、宜业、宜游的美丽乡村精品村，成为红色旅游发展的新样本。本报4', '2019-04-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICVVyBNKH-97gsX189jdFB9j9r11MIgWHYyfgX0vI9g4KID70RlcrwbwANuOdsALdhrvDpBye5-NdljReCb-etad9-XfbxLhJEUF97dCgG1yq17W6t8n4ZCD3wECQEeP4q1XYhO5kjwVg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6027, '报纸', '在新的“赶考”路上交出优异答卷', '', '中国青年报', '中国青年报', '共产党人;“两个务必”;新的伟大工程;', '70年前的早春三月，从当时的中共中央驻地西柏坡动身前往北京的时候，毛泽东同志说：“今天是进京赶考的日子。”70年后的今天，中国共产党人以勇于自我革命的胸襟和气魄，交出了一份令世界刮目相看的答卷。 西柏坡是党中央解放全中国的“最后一个农村指挥所”，是中国共产', '2019-04-11 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBZRTHBQE764u8WTLSa74OAl2o5qcLF6zxUQ3buZKUWpM4MBd582MxqxsF0r7rinkBCjhuko6Ssxdtm3soavd_OtMBBQYfsqcOQ0KY2mNB7tOPNzSX41PNKuylZv5MnMdfVPLQpsxsm0w==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6028, '报纸', '永葆再出发的劲头', '尉承栋', '中国纪检监察报', '中国纪检监察报', '“两个务必”;共产党人;', '“壮丽70年·奋斗新时代”大型主题采访活动正在全国铺开，数百名新闻工作者从西柏坡出发奔赴各地蹲点调研采访。河北省平山县西柏坡村，是党的七届二中全会召开地，也是在这里，毛泽东同志提出“两个务必”，带领中共中央启程踏上了希望考个好成绩的“进京赶考”之路。 “', '2019-04-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICmAUemPh7B6A-DXS8wtLR8Uru52S1GATDjm5uPEG68PSfPVzgEKyPdtChCLVsFIRElWL63h3rBXUMp99dPmzB-ualUmeMRMrxJpe7OB_5yd661MMuoam7XJK_mBLjAxTBU0MZdIehpSA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6029, '报纸', '行政改革40年：从放权开始，向服务转变', '张守营', '中国经济导报;', '中国经济导报', '服务转变;建设服务型政府;审批制度改革;国家发展改革委;管理体制改革;', '编者按 为了纪念改革开放40周年，我们开辟了“庆祝改革开放四十周年·这些……”专栏，从历数“这些年”开始，重温了“这些人”的往事，惊叹于“这些术”的非凡，目睹了“这些债”的创新，振奋于“这些品”的成长，如今，走到了这组系列报道的尾声——“这些事”。 4', '2018-12-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBTCGHmrFitITKu-6e2hj7na8GLj2OoeW6B0PFAMlnUM4DjuLYn0s__6WbQzGdyGqDn_7kdVo33viLtUI1jEMmDj66NBZQzqLl8J5H4QlZmbjiQsv5ebvUmvBBXhL0TfCStKTujLVO3Hg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6030, '报纸', '在纪念刘少奇同志诞辰120周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '刘少奇;白区工作;共产党人;座谈会;', '同志们，朋友们： 今天，我们怀着十分崇敬的心情，在这里隆重集会，纪念刘少奇同志诞辰120周年，缅怀他为党和人民事业建立的不朽功勋，追思他为民族独立和人民解放、国家富强和人民幸福不懈奋斗的光辉生涯，学习和继承他的崇高精神风范，激励全党全国各族人民为全面建成', '2018-11-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB0AkwLEMmupf3U-pMCMXsPOKCI3RUP8Ai7fKmj_jq_lXw5ecgxV_2OJhkybXDLMAPoSr1a0WRIdJvC-_VXXxv1pTwXov08GKroKR-aI7O_OsFzzz8Kf70EM6jjwsVm-JRQKcDRuBgpHA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,抗日战争1_screened,中共七大1_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (6031, '报纸', '我的人生导师马洪', '王肇文', '广东省人民政府;深圳市企业竞争力战略咨询委员会;', '中国经济时报', '东北局;深圳发展银行;国务院发展研究中心;民间智库;社会主义市场经济体制;第一个五年计划;工业体系;会展经济;工业七十条;政策研究室;张闻天;人生导师;毛主席;企业制度改革;', '在敬爱的马老离开我们十周年之际，来回顾马洪同志一生留下的闪亮足迹，对我们这一代、对下一代都是一笔宝贵的精神财富。 马洪同志的一生，对我们党和国家作出了多方面的重要贡献，在经济理论建设、推进决策科学研究和建立民间智库等方面有特别突出的贡献。 马洪同志', '2017-11-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBOyGGqbB2fdUI6Fqq8NXLL3FWeL2XUDLlmorMmYMwf-TkDjrXJA0eLztqVC-4sb5mYIkbBTd_QfcPNbjMd-B_KTX-RUljfChQwhsyI19aagjFS7y2IakuYrFBG98KKFKzfA3_K_-swFQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6032, '报纸', '三份老报纸记录“中共七届二中全会”', '彭援军', '中国收藏家协会;', '人民政协报', '中共七届二中全会;老报纸;群力报;', '中共七届二中全会于1949年3月5日至13日在河北省平山县西柏坡举行。七届二中全会不仅迎接着中国革命的胜利，而且对新中国的建设有着重大作用。 笔者收藏有三份报道中共七届二中全会内容的老报纸，成为重要的历史佐证。 《大连日报》的实况记录 《大连日报》是中共', '2017-11-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAE3EKStFK_77BvbaxQReQXdIE0JRxzgL1SEjSC3BnNRa110u1ltcQPDk2UCP-r7-YJfQbSArjE4wftypxr24tn2y-LIVDVFGUH4ivM0twRriFrlZdSb-ARu7BlVQKMkIaSK5mQk7RUpg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6033, '报纸', '坚决打赢反腐败这场正义之战', '温红彦; 盛若蔚; 姜洁; 孟祥夫', '人民日报', '人民日报', '反腐败;习近平总书记;十八大以来;反腐败斗争;全面从严治党;党内政治生活;党内法规制度;不能腐;不敢腐;党风廉政建设;', '激浊扬清，大道之行；时光流转，不忘初心。 党的十八大以来，以习近平同志为核心的党中央以强烈的历史责任感、深沉的使命忧患意识和顽强的意志品质，大力推进党风廉政建设和反腐败斗争，在这场“输不起的斗争”中向党和人民交出了一份优异的答卷。要问这5年党和国家工作', '2017-09-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB9AH1j59zyjQwPIIF98y2Az9rtxiq44SNs7Hv-Lc_DsQc-tg51ocy3_cORCIfUkSURUsoTnBas2H4Iupftlm9xqCdeEKsFwGsOlJJFtlFmgq6awhM3i-aASXlv7TnuMQU7KeQ8MWgN4Q==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6034, '报纸', '不懈奋斗 壮丽人生', '', '中共中央党史研究室;', '人民日报', '杨尚昆;中央办公厅;中央军委;彭德怀同志;中共中央北方局;中央革命根据地;敌后抗日根据地;红军长征;中央红军;党章修改;党中央;总政治部副主任;', '今年8月3日是杨尚昆同志诞辰110周年纪念日。杨尚昆同志是伟大的无产阶级革命家、政治家、军事家，坚定的马克思主义者，党、国家和人民军队的卓越领导人。在70多年革命生涯中，他为中国革命、建设、改革事业不懈奋斗，贡献了毕生精力，作出了重大贡献。 一、为人民军队建', '2017-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA_y1uaF9-twbhJz8JsmjdI7Vegobr8H5OxbiMUEu6KYd9vP2fdJJdpSvBwR0Jfb0_S0r6Jzm3w2isleRe_ufaymQDsEg1zxsPrvQkvY9q9ramJ0SLtJb_9qQNhcqsN034DCcTCdhrp5A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,抗日战争1_screened,九一八事变_screened,百团大战_screened,遵义会议_screened,四渡赤水_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (6035, '报纸', '让优良的作风成为人民法官的工作和生活习惯', '缪蒂生', '辽宁省高级人民法院;', '人民法院报', '人民法官;作风建设;习近平总书记系列重要讲话;法官队伍;', '自古以来，崇尚高风亮节，鄙视歪风邪气，一直是中华民族最核心的道德价值准则之一。孔子在《论语》中关于作风的论述很多，比如“敏而好学、不耻下问”，说的是学风；“其身正，不令而行；其身不正，虽令不从”，说的是领导作风。孟子的“我善养吾浩然之气”“天下之本在国，', '2017-07-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBFM6QPgZ5Pk9W6ODC6NaHjLda8DlAzMLdfqlmP5Dr0cZ9jHKDX7XPOvUK_qjke6K9vozDBaUCwL49wIBTGbmKmCgP07rVOBLCT8UUGKKTBFeXcUPClV4YWpH-0dhfDx2CfUs0zUPaxDA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6036, '报纸', '党内政治文化建设对推进中国特色社会主义文化建设的重大意义', '马援', '中国社会科学院科研局;', '学习时报', '中国特色社会主义文化建设;党中央;政治生态;党内政治文化建设;党员领导干部;重大意义;', '习近平总书记在党的十八届六中全会上指出，要注重加强党内政治文化建设，不断培厚良好政治生态的土壤，努力建设先进的、健康的、富有生机活力的党内政治文化。这一号召，既是在顺利推进具有许多新的历史特点的伟大斗争、党的建设新的伟大工程、中国特色社会主义伟大事业中全', '2017-04-05 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBkRsakUnbtFnmBCtF2ni6flzNXxZgNIfktshwCX5gFLLbM31Mxs2tMB6YOPFFjhboiLMAcycXSargq2yy1G71mA-RjRqJI0SgIdDs9eDAGI6bPFmOZso5a82lF4Yu1TJGET-XXlrlVHA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6037, '报纸', '艰苦朴素、廉洁奉公的共产党人楷模', '李慎明', '第十二届全国人大内务司法委员会;中国社会科学院;', '学习时报', '共产党人;王宗武;', '3月12日是王震同志逝世24周年。王震同志于1982年至1987年任中央党校校长。为纪念王震同志，本报今日特刊发此文。 ——编者 《关于新形势下党内政治生活的若干准则》明确指出：“各级领导干部特别是高级干部要坚持立党为公、执政为民，坚持公私分明、先公后私、克己奉', '2017-03-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC6dDWNxdxV7SwYuJFRrrxAug0xjf1tbuRDI2Nxbbq-W9cmm6cPUAOrYRV8TYhcn_MN0M2dp2oOjSoD4A4HZt4wjRWgx7zJB3pMiNJUcWMGNjmA_rMgH6imbWkA-roF4mkIVnfIQqCQqA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6038, '报纸', '坚强领导开创反腐新局', '', '人民日报', '人民日报', '反腐败斗争;全面从严治党;', '“反腐败斗争压倒性态势已经形成”。这是振奋人心的判断，更是来之不易的成绩。 压倒性态势的形成，源于以习近平同志为核心的党中央坚强领导，源于全党上下同仇敌忾、齐心协力，源于深谋远虑、高瞻远瞩的治党智慧，源于亿万人民的信任和支持。党的十八大以来，反腐败斗', '2017-01-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICCMCGDyff6g-pxbFro-vXEvFWNnRi4PBLnUg2LmciMEgPo_QX6GUHuiAfhr1Zt3G-jzZhA60DTs3UOzOPFfDQcBc0k3WfRk4CJ9j30PgpjdsE1S2piLHCWbcmBIIf_4vXKYhrccgiS0Q==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6039, '报纸', '历史的选择，人民的期待', '秦杰; 张旭东; 李忠发; 陈芳; 张晓松; 韩洁; 刘铮; 熊争艳; 王敏; 罗宇凡; 何雨欣', '人民日报', '人民日报', '习近平总书记;党中央;伟大斗争;中华民族伟大复兴;习近平同志;党的十八大以来;全面从严治党;', '时间是伟大的作者。 67年前，新中国成立的前夜，毛泽东同志勉励全体中央委员会成员—— “夺取全国胜利，这只是万里长征走完了第一步。如果这一步也值得骄傲，那是比较渺小的，更值得骄傲的还在后头。” 67年后，庆祝中国共产党成立95周年大会上，习近平总书', '2017-01-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDC7ubGP8gxJwp7BgNP7_juuLFMsuuwHMLKrZ1hh3Hz_3mtIkENA48-JM0ZgxWIZDULDS5x_AQJv0SSHUppNNZAAp9_W3F0QeXkszudNMsBhgDx1rPpECO7Ztvunch5cHYT3xHSOa6qiQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened,将台堡_screened,神山村_screened');
INSERT INTO `ds_article` VALUES (6040, '报纸', '走好今天的长征路', '', '光明日报', '光明日报', '长征精神;', '“精神是一个民族赖以长久生存的灵魂，唯有精神上达到一定的高度，这个民族才能在历史的洪流中屹立不倒、奋勇向前。”在纪念红军长征胜利80周年大会上，习近平总书记站在历史的高度，对于精神之于民族发展进程的意义，做出了上述精辟凝练的概括。 对于刚刚走过95周年的中', '2016-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC5wunCVC7ZQn7ja0z-Ok4Kufwex2kvNKBtdiWdhN9IpZRKb5m7kD-SZj1SFNCTPxqvyoJJGSEk_JPLNpEFf1ruCUM7u8jM-MSHzObdJeAtxOF-5n9Hb9oW1Dacg8R5HO7LQBlgvGZ-9A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6041, '报纸', '在学习《胡锦涛文选》报告会上的讲话', '习近平', '人民日报', '人民日报', '《胡锦涛文选》;党中央;胡锦涛;科学发展观;全面建成小康社会;报告会;', '同志们： 党的十八大之后，党中央决定编辑出版《胡锦涛文选》。现在，这一重要文献已由中央文献编辑委员会编辑完成，并在全国出版发行。这是党和国家政治生活中的一件大事。党中央作出了《关于学习〈胡锦涛文选〉的决定》，各地区各部门要按照党中央要求，切实抓好落实。', '2016-09-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBD4CNmETFaOU3jXdm8KRA3j3okHOTiEIzTIIC0uEKgMzUOrG4onh6hcWOfjubyyPqawZ7uArfcBCpH8apxhG9-vTP6UvAo_TX5n0EvMR5kjb7FPcnyrpFOQzmRWrgheY3d9813LZtzXw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6042, '报纸', '《胡锦涛文选》第三卷主要篇目介绍', '', '人民日报', '人民日报', '《胡锦涛文选》;中央经济工作会议;当代革命军人核心价值观;经济发展方式转变;胡锦涛;党内民主建设;中央纪律检查委员会;', '中共中央文献编辑委员会编辑的《胡锦涛文选》第三卷，收入了胡锦涛同志在2007年12月17日至2012年11月8日这段时间内的重要著作，共有报告、讲话、谈话、信件、批示等86篇，相当一部分是第一次公开发表。现将《胡锦涛文选》第三卷主要篇目介绍如下。 《深入学习领会科学发', '2016-09-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAGdPMbLgEjOpl-FpZeLnjTI5xGr7FiqR0q06sSd_eNoAbGa0CifTTh-32WrBENErzyEERRa8xn5Nsmgd_KwEPPYUd70VX-pLPRXef8Qpvs-M26f3VlOU3cltBh0wRYNopkjONp4qKnOA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6043, '报纸', '《胡锦涛文选》第二卷主要篇目介绍', '', '光明日报', '光明日报', '《胡锦涛文选》;科学发展观;全面建设小康社会;新世纪新阶段;胡锦涛;马克思主义政党;意识形态工作;党的执政地位;利为民所谋;党的先进性建设;构建社会主义和谐社会;中国特色城镇化道路;权为民所用;情为民所系;', '中共中央文献编辑委员会编辑的《胡锦涛文选》第二卷，收入了胡锦涛同志在2002年12月6日至2007年10月15日这段时间内的重要著作，共有报告、讲话、谈话、文章、信件、批示等82篇，相当一部分是第一次公开发表。现将《胡锦涛文选》第二卷主要篇目介绍如下。 《在西柏坡学习', '2016-09-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBcJgaLEjt2FbM7JnQLuOt1FAg3-NCfsdbJ9_Jx--vDS7XOtj5j47FHNwrQFcB1liaVGitUIzT2uBQV7IFXMsdvh8atcicniqMRCi54HCRq8NHBPIJr2dzJgb3v-DQu8su9YlL73fMFvw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6044, '报纸', '做好党委工作的“金钥匙”', '彭友东', '宁夏石嘴山市委;', '中国组织人事报', '党委工作;《党委会的工作方法》;政治规矩;', '《党委会的工作方法》是建国前夕毛泽东同志在党的七届二中全会闭幕时所作讲话的一部分，深刻阐释了党委会工作的一般规律，是做好党委工作的一把“金钥匙”。习近平总书记着眼于新的历史条件下全面从严治党的内在要求，明确提出把这篇著作纳入“两学一做”学习教育内容，就是', '2016-09-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDQkBVNlUWEUyT28AH8FqxNrm3lFGTDT-VXLy3NTzGhE07wdxkOsQ-BeKSvHyHVYQsloiJQID68ULpHDOVtH5H_oZv_OaQLyugAwXHkpUqhWkGtPmcH_BxDJTxAEbHHa1Iqz4ryZfVc4g==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6045, '报纸', '以“进京赶考”的精神状态推动党风建设', '沈根泉', '中央党校办公厅;', '光明日报', '党风建设;习近平总书记;管党治党;党的作风;“七一”重要讲话;四种危险;党的先进性和纯洁性;', '精神状态反映党的形象、关乎事业兴衰。习近平总书记在“七一”重要讲话结尾处，以“进京赶考”的故事语重心长地告诫全党：“全党同志一定要不忘初心、继续前进，永远保持谦虚、谨慎、不骄、不躁的作风，永远保持艰苦奋斗的作风，勇于变革、勇于创新，永不僵化、永不停滞，继', '2016-09-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIArtSUh1iuY5UR-FkKKdml28Ds3hpk6r1yiiTMAgiIFaQp9TvYjMQbXjL_5e4Rh1VP3TJmj392p9yhhTCrfp9b44-qyiF0bgFlYC-2a6G1RvKbpBqrbq9K-83J2X2bWInY4W6worih94A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6046, '报纸', '严肃党内政治生活，永葆先进性纯洁性', '王昊魁', '光明日报', '光明日报', '严肃党内政治生活;党内政治生活准则;“两学一做”学习教育;纯洁性;', '编者按 习近平总书记在庆祝中国共产党成立95周年大会上的重要讲话，全面总结了我们党团结带领中国人民不懈奋斗的光辉历程、伟大贡献和历史启示，深刻阐述了不忘初心、继续前进必须牢牢把握的八方面要求，是全党在新的历史条件下进行具有许多新的历史特点的伟大斗争的政治', '2016-07-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC9Cff5xM2KDacCNCxK0DPmUtyIUvqeqJnnty3iyS0P0qn4bM0i54ymhRUdZpaAGorl9I2PEKBpHrEy5QHIB-DtbwCh2rhh6jdovbU0PUuxiNVPhYp6IV5HDhDF4a9PwNsagvSrg71UzA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6047, '报纸', '在新“赶考”中交出优异答卷', '孙万勇; 王惠周', '河北省政府;石家庄市人大教科文卫委员会;', '人民日报', '“两个务必”;习近平同志;七届二中全会;政治规矩;“两学一做”学习教育;', '习近平同志在西柏坡调研时指出：“从实现‘两个一百年’目标到实现中华民族伟大复兴的中国梦，我们正在征程中。‘考试’仍在继续，所有领导干部和全体党员要继续把人民对我们党的‘考试’、把我们党正在经受和将要经受各种考验的‘考试’考好，努力交出优异的答卷。”弘扬西', '2016-06-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBcY6l4iGo0lfCqnswQf04qtJW__tDJsTFu0B4-yIcZDqMBCS9nM64AEC-PFUmTS9TEGdShphI6IhML5qWSJ03-T1X1RQhqZG4E3ZuvfyVW6pgx1RyWtBwYcfqtVpbGbpMtYcqXmZDcgA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6048, '报纸', '从《党委会的工作方法》看毛泽东的领导方法', '张太原', '中央党校党史部;', '光明日报', '毛泽东;相结合;《党委会的工作方法》;《香山记》;领导方法;', '最近，习近平总书记就学习毛泽东同志《党委会的工作方法》作出重要批示，明确要求各级领导干部重温这篇著作。在党的作风建设已经取得了很大成效的今天，进一步改善工作方法，有着重大的现实意义。任何一种工作都需要方法，特别是领导工作，“不仅要决定方针政策，还要制定正', '2016-03-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICRsWHd9t-FE8FmEwA5DvKypwmBHJE2YXwjw32xkHUMeyFHXFeJTa4-SoleZ-EE9rfMGFctYDo6wAy-0tdpBQFIoKFzDINynllKsVeAkoV_ZZ1wGqRHktdIvDlQJm-uhKHc9o32PONVJg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6049, '报纸', '着力营造政治上的绿水青山', '王昊魁', '光明日报', '光明日报', '纪律检查体制;反腐败斗争;提名考察办法;全面从严治党;党风廉政建设;制度治党;中央纪委;绿水青山;', '2013年7月11日，河北平山西柏坡——中国共产党“进京赶考”的起点。纪念馆内，有一块记录党的七届二中全会作出“六条规定”的展板：“根据毛泽东的提议，全会作出六条规定：一、不做寿；二、不送礼；三、少敬酒；四、少拍掌；五、不以人名作地名；六、不要把中国同志同马恩列', '2016-01-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBH6a4xvzEfDDW1OWIICI_2yiDI16INW9wY-FTUQq3s0jcfn0jtQy-ASuLv-nQrTqb3YBZtmcPS-JDy4q-iJgxfdU98FJAUnqF44m6McD1jwn2nEOWAHvvW8kJ4oGCVMfKYCBx28dIDRA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6050, '报纸', '一个时代对一个智者的尊敬', '李成刚', '中国经济时报', '中国经济时报', '杜润生;百岁老人;土地改革;中国农村改革;包产到户;农村工作部;永佃制;集体所有权;农村土地产权制度;陈锡文;', '2015年10月9日，百岁老人杜润生走了。无论是政界、学术界、新闻界，对他的怀念是如此深刻——尽管他已经淡出人们的视界很多年，似乎都已经快被遗忘，但只要谈及中国的农村改革，任谁都无法回避这个名字，在过去、现在和未来，杜润生——都是一个传说。如2012年杜润生百岁生日', '2015-10-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAtKJVUV3lvApvZqeBqvfDDIQT3TFoC52sxsDT12lTHbYNwKJkWquGG5g71Gc-LavfQfSkN33QxfONi8nVTB7gmitA_-VN6yhapjUwlXdpZx5Y5IMmVVH0FBDx9dxsHc1EkjGXKnyxqOg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6051, '报纸', '传承西柏坡精神 奏响新时代强音', '', '解放军报', '解放军报', '声乐套曲;平津战役;“两个务必”;军民关系;发报机;党的群众路线;七届二中全会;党群关系;指挥所;', '深情的回顾 深刻的回答 石才 《西柏坡组歌》，是北京军区政治部战友文工团近几年精心打造的一部力作。组歌中好歌很多，《天下乡亲》一歌用形象而深刻的诗句，深情而高亢的旋律，加之演员荡气回肠的演唱，描绘出恢宏的历史画卷，对如何认识与处理党群关系、军民关系', '2015-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAjCXJtgKCWRRIwPjOaxQ8xB2DNVnmxBH6mxcFmNwH7Eg6nGLMM33QIHUWt2cc6aNO52jD9rMr16oJS8uDDwsLwS_edMaRQHuDtAzBlFCn7-c13tNRhg4Wn4yfFdJk5wVYjkGVk3ZgZ5A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6052, '报纸', '以史为鉴 积极推动法治建设', '张丽', '人民政协报', '人民政协报', '黄克功;审判长;雷经天;王兴东;法治建设;以史为鉴;', '编者按： 9月9日，由全国政协社会和法制委员会、全国政协文史和学习委员会及机关党委组织的《黄克功案件》观影活动在京举行。电影《黄克功案件》是全国政协委员、中国电影艺术家协会副主席、著名编剧王兴东继《建国大业》、《辛亥革命》之后，从政协文史资料和党史资料', '2014-09-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBxuYtRO458dD7hUeI5S2wzd6n2-ZBA7th6Ka222rrrQZBpRAa_vlj7Hi5AyaIhMzUP22ujUoBOme8-nXRQoKsEmDgKkgJWYfbkbHI5RSAWTNv2118JPwDgzQyKXFFP-t7kc5WvcykULg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6053, '报纸', '纪念任弼时同志诞辰110周年座谈会发言摘编', '', '人民日报', '人民日报', '任弼时;红六军团;马列主义理论;座谈会;', '铭记历史功绩 继承精神风范 中央文献研究室主任 冷 溶 1945年，党的七大及七届一中全会选举出以毛泽东同志为主席的中央委员会和中央书记处，标志着党的第一代领导集体形成。任弼时同志当选为五大书记之一。随后，他同朱德、刘少奇、周恩来同志一起，协助毛泽东同志', '2014-04-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAvREK0o-yTA3r3TD1QLwpjx4JqzUGr_2UWBXdlnvEiGpw7qpLYCuv2CIugCOiPgh3xctfAhOTUUr_DCKm7O_xY5yjznAIO6uwTtRvsIujOwq8YZeAUy9YKzXtiq97fhox66Sq6HNEiyA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,抗日战争2_screened,中共七大1_screened,土地革命战争_screened');
INSERT INTO `ds_article` VALUES (6054, '报纸', '国家一要勤，二要俭，不要懒，不要豪华', '高斌', '检察日报', '检察日报', '毛泽东廉政思想;反贪污;官僚主义;批评与自我批评;', '毛泽东廉政思想是我们党建理论的重要组成部分。从延安时期的局部执政到新中国成立初期的全面执政期间，中国共产党在党风及廉洁廉政建设方面成效显著，这与毛泽东高度重视党的建设直接相关。 今年是毛泽东诞辰120周年，《检察日报·廉政周刊》对毛泽东关于廉洁廉政的阐述', '2013-12-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDtfvXqVCGX3mr5vgN8CzZJ3Mqb01N8-8sywOshvGbli7WBcD0LVJ91gyGkR6KFjKqnCiWT6FMAAwsACsBwLw_oo-qtSC_Ut9eGIOui0f269x5bOEqviWvd-AaEgJyKIoZBH_w8qIbfCA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6055, '报纸', '纪委是一把永远出鞘的利剑', '陈治治; 姜永斌', '中国纪检监察报', '中国纪检监察报', '中央纪委;党风廉政建设;反腐败斗争;十二大;党的纪律;纪律检查委员会;纪律检查机关;监察部;监察委员会;', '在许多人眼中，中央纪委是一个“神秘的机关”——它是什么时期建立的，经历了一个怎样的发展过程，产生方式是什么，职责和任务都有哪些，在中国共产党的建设中发挥了怎样的作用？围绕人民群众关心的这些问题，10月18日，中央纪委副书记吴玉良做客中央纪委监察部网站《在线访', '2013-10-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBfVpa8So8_TsrbGjldn5yiWy_IzVCQJmY2nH56rkt0WAqUe30vQZ9fst6A2ApfKzFYvXT8IShKVA0USdiSOBIsgigVNVh7_1T5kvFtwQppein2FHcyl57muQsmXLV4VtYfMn267_PTKA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6056, '报纸', '反腐败：也是一场人民战争', '侯磊', '河北省检察院;', '检察日报', '反腐败;张子善;人民战争;', '我2006年退休后，“红色收藏”成为我新的人生频道的重要组成部分。近日，整理藏品，当年公审刘青山、张子善的老照片跃然在目，不禁思绪万千，感慨良多。反贪当用重典，治党务必从严，唯此才能巩固我们党的执政之基，唯此才能时刻保持我们党的先进性、纯洁性。 他们倒在', '2013-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICRHNUuuexfqHGPtYgwoqv0NMeTRltu-giVOsNv87FZGwrwvZz5Pr95yqX334GuuL5z4QNSpxSviKMxHbPmkXYhBOuj9hexGyNxZOpxb1w5sDZ61AISz2Jq4Ru0gZn2Q0gb2txqjpsKXg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6057, '报纸', '牢记“两个务必” 坚决反对“四风”', '周本顺', '中共河北省委;', '人民日报', '“两个务必”;习近平同志;反对“四风”;党的群众路线教育实践活动;', '7月中旬，习近平同志到河北调研指导党的群众路线教育实践活动。在西柏坡，习近平同志围绕“两个务必”作出了一系列重要论述，对弘扬西柏坡精神提出了明确要求。习近平同志的重要讲话，对于深入开展党的群众路线教育实践活动、有效反对“四风”、保持党的先进性和纯洁性具有十', '2013-08-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAtsuitbzmS-nuVDp0S9vXv3hBjgqhp_vAgfX4ngFEAYAlziU46WLn0Fo2-CqPYveisXhSJ8mRNiv_Wnng-C3aJexNqX9sI8peWbDywgWVC3Aoc_t8beCl1X07qszSQPHxvNPIZCv1LhQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6058, '报纸', '享乐主义，根源在革命意志衰退', '辛士红', '解放军报', '解放军报', '享乐主义;', '明代的监察御史杨爵，看到嘉靖皇帝即位不久就耽于享乐，不见当初励精图治的雄心，就大胆进谏。结果，皇帝勃然大怒，将杨爵逮捕入狱，打得“血肉狼藉”。毛泽东读到《明史·杨爵传》中的这个地方，重重地批了“靡不有初”4个字。 “靡不有初，鲜克有终”，这和黄炎培提出', '2013-07-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAbGDd_lL6JSuO-Fd9tnINHZymZcOhKZf-aW1QDJHH5FEpo3d9UhApo9jGlQEj3gXZ5LPJxKc8hSyesnOd2EuJwnJJDu7D40iulu6384U-d3CSTDnSUxEZ10Ny7jlPxrTQxG-7YbEyJig==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6059, '报纸', '劳动筑就中国梦 幸福汇聚正能量', '尹慧敏', '山东省人大常委会;省总工会;', '工人日报', '全心全意依靠工人阶级;正能量;劳模精神;劳动模范;体面劳动;实现中国梦;劳务派遣工;社会公平正义;全面建成小康社会;', '习近平总书记4月28日同全国劳动模范代表座谈时的重要讲话，高屋建瓴、精辟深刻、语重心长，充分肯定了工人阶级的重要地位和伟大创造，高度赞扬了劳动模范的崇高精神和卓越贡献，明确提出了“四个必须”的重要论断，进一步指明了当前和今后一个时期我国工运事业发展的前进方向', '2013-05-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDkjAXT4cxx8IDd1LK0sdFOYBVnqf0IanFnd9OfHCMv2HAVDM7CfaBizJ7Dq5JUZ5ElzmNy6LnwtBujNkXvzjX6yuzDiKtIF9tllfkHxAktxJt8Zw-K7WVlqLD8YGjwLcdXTPEWfGFmIg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6060, '报纸', '推进反腐倡廉工作需汲取中外历史经验', '王守泉', '检察日报', '检察日报', '反腐倡廉工作;反腐败斗争;防治腐败;惩防并举;中外历史;', '4月19日下午，在中共中央政治局第五次集体学习时，习近平总书记强调，深入推进党风廉政建设和反腐败斗争，需要坚持发扬我们党在反腐倡廉建设长期实践中积累的成功经验，需要积极借鉴世界各国反腐倡廉的有益做法，也需要积极借鉴我国历史上反腐倡廉的宝贵遗产。习总书记的这些', '2013-04-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDSRyPOfDT-VMoVe4UjNwfLtc9dIYO-t9aPldAJQ7EdH4Z4a62zy5HrWD84ut9BKv5mihxDVTEfuZnEIBBCLGEvhqWkd5708magqlb2Gp8R3D9hdBpAdpOv8SrzKvsVF5tibrj6XzDZTw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6061, '报纸', '从十八大报告中读出的道理', '兰文飞', '学习时报', '学习时报', '马克思主义经典作家;十八大报告;社会主义阵营;中国特色社会主义事业;理论品格;“两个务必”;共产党人;胡锦涛;', '编者按：为帮助广大读者加深理解和认识党的十八大精神，本报特别约请中央党校常务副校长李景田做了一个访谈。李景田同志曾参与十八大报告起草小组的有关工作，又是中央宣讲团的成员，他的体会对我们有帮助。 记者：您曾参与十八大报告起草的有关工作，会后又作为中', '2013-01-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBVWc9NjpzLTFQrSDj9yyFltxYBtvWaf1Z3gJHb8l7BFsBeTugFFlCELbzcE8Y0A0r1veIBn-hdHLQmORUl-QUM5t7tDxA4rMN2qY1GRUgrPulhzpgMGFFZRK66UFQDpFHUder9h-8aZw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6062, '报纸', '更好地服务人民群众安全便捷出行', '李盛霖', '交通运输部;', '人民日报', '交通运输安全;政府还贷;综合运输体系;收费公路;综合运输枢纽;应急救助;交通运输服务;交通运输业;二级公路收费;', '胡锦涛同志在“七一”重要讲话中指出，以人为本、执政为民是我们党的性质和全心全意为人民服务根本宗旨的集中体现，是指引、评价、检验我们党一切执政活动的最高标准；我们必须始终把人民利益放在第一位，把实现好、维护好、发展好最广大人民根本利益作为一切工作的出发点和', '2011-09-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICi9F7aO3IPbrOS9NdBrSXwBeQcGQkkG1BQvp1pHqOvuHk7F7ZFZipYKjJAG_LAKTS-IUrMPTJuE420eWSiemWIafICFcAxPjOWtqIPWlXDeBGsPJFigrwlpma7ykZWPiWAWnynTWd_CQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6063, '报纸', '政府绩效管理制度建设提速', '姜洁', '人民日报', '人民日报', '绩效管理制度;部际联席会议;国务院;监察部;政府绩效管理;绩效管理工作;', '2010年7月，中央纪委监察部正式组建绩效管理监察室；今年3月，由监察部、中组部、中编办、国家发改委等9个部门组成的政府绩效管理工作部际联席会议成立；今年6月，国务院批准8个地区和6个部门开展政府绩效管理试点工作。这一系列动作，标志着政府绩效管理工作开始从国家层面', '2011-09-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICrxEu0oG4OQ839YXSPweElSQMn3FLfdwGhDaXrujsSoZ-Vg79a7AAryGsSAmRzhe4eIJCUO5TL9ITxGs0r9S7PQkRMMWBuKf1JOx_3-9KM8wNl2Dn0I0GoJfxsIJ80UXyW6eDe4sbxHg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6064, '报纸', '播火记 ——新中国成立前党的人民出版事业', '侯俊智', '人民出版社社委会;', '光明日报', '新中国成立前;党中央;长江书店;新青年社;中央党报委员会;根据地;出版事业;华兴书局;无产阶级书店;马克思主义著作;中国工农红军;《解放》周刊;中央苏区;', '今年的“七一”前后，上海成都北路七弄30号，中国共产党第二次代表大会旧址游人如织。新中国成立前，这里称作南成都路辅德里625号，是党的创始人之一李达同志的寓所，也是我党第一个出版机构——人民出版社的所在地。党的人民出版事业从这里起步。 一、人民出版社的', '2011-09-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDqlUoyYWWyu71rQAOLxShn_kn9bzQYcHCgymSUUshmsMtt4iVeELItWH_qkZCM7JimSwp-KII6Vs4yAkvXQ91Fh3z49DJ7mQVOKDLBE3kMR9zZPJjhO5d8dUE-mWBmskCUJgOGVmxaIg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened,抗日战争2_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (6065, '报纸', '治贪防腐需要走出五种认识误区', '丁继明', '安徽省机关事务管理局;', '检察日报', '反腐败;为官者;反腐倡廉工作;治理腐败;惩治腐败;', '反腐成就斐然但形势依然严峻  中国共产党从成立那天起，对贪腐就是深恶痛绝的。贪腐与党的性质、宗旨、目标、任务都是水火不相容的。早在建国前，在西柏坡召开的党的七届二中全会上，毛泽东同志就谆谆告诫全党，务必使同志们继续保持谦虚谨慎不骄不躁的作风，务必使', '2011-08-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID10uc03abT39x-jJ3FEqGwpVR6XMiZbvgT3sLkeIjsWwcgFJBP__lcAVJjLG9SZQYJvNtl44gObRjblZ12kUreJMUgpPcRRMh44wfflWeODuRcUAv7kIjJLy2yW0DD3T-_qtV28riP6w==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6066, '报纸', '时刻保持危机意识', '', '光明日报', '光明日报', '四种危险;执政能力;“两个务必”;张子善;危机意识;', '1944年,抗日战争胜利的曙光初现。3月,《新华日报》全文连载了郭沫若写于三年前的《甲申三百年祭》。《祭》文秉笔直书,言说了明末李自成进京出京,由胜到败,39岁战死在九宫山的历史悲剧。 毛泽东同志深刻地洞见到《祭》文在历史转折关头的重大政治意义,立即批示《解放', '2011-07-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLj3BMVo27Uq-0YhECdLWQgPa0Kwf5VqjsRKij0AYWSCKxmHy1yypXcMeU9b0T1WgciNgLHcQDM7BArMwsjYAm0UiiwVCkRQuWs6n99lHTTx6OW-uLZvoTRdsQYg4ksUtLhlm2F2vsIQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6068, '报纸', '中国共产党历史大事记', '', '中共中央党史研究室;', '人民日报', '中国共产党;红二、六军团;毛泽东;周恩来;任弼时;抗日根据地;国民党军队;中国工农红军;古田会议决议;新四军军部;张国焘;中华苏维埃共和国临时中央政府;红军建设;中共中央政治局;历史大事记;', '1840年以后，由于西方列强的入侵，中国逐渐成为半殖民地半封建社会。灾难深重的中华民族面临着两大历史任务：一是求得民族独立和人民解放，一是实现国家富强和人民幸福。从鸦片战争开始，中国人民进行了不屈不挠的斗争。20世纪初，孙中山领导的辛亥革命，推翻了统治中国几千', '2011-07-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDNlisbbFJsmUXn8SW8GihX3CnjyCSYOM20AG7ZFRSSHjcg10JXsj1GhmPrYI9YRZUHUd5cIqlvhwqlmxiuUSAOB7Z0cMqSBKieANAuArzXkVw5dePRD2gvmeyoWGyJrplXzDPWGMm6iQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,七届二中全会_screened,两个务必_screened,西柏坡_screened,西柏坡_screened,扎西会议_screened,夹金山_screened,将台堡_screened,强渡大渡河_screened,遵义会议_screened,四渡赤水_screened,会宁_screened,飞夺泸定桥_screened');
INSERT INTO `ds_article` VALUES (6069, '报纸', '永葆蓬勃生机 担当历史使命', '', '新华社;', '新华每日电讯', '历史使命;“两个务必”;', '胡锦涛总书记在“七一”重要讲话中,面向我们党成立100年时、新中国成立100年时的两大宏伟目标,语重心长地指出:“我们完全有理由为党和人民取得的一切成就而自豪,但我们没有丝毫理由因此而自满,我们决不能也决不会躺在过去的功劳簿上”。 建党90年来的伟大成就,值得', '2011-07-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICDUi2BY6TK7Hnand9gLUGih6luQmja55z-I3HrkTxQGvTCLVDMSg_aZwo9nRfwS0XPvEuh50ogbTOToOyE-4o10rmnVyvRkfCFrvtvUzXVfAYAnsLGaxR9VoFxOGToH-dzwgzbADIaxw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6070, '报纸', '浴血奋斗', '', '人民日报', '人民日报', '国民党反动派;农村革命根据地;中国共产党领导;', '雄伟壮观、庄严肃穆的人民英雄纪念碑，巍峨耸立在天安门广场中央。纪念碑的正面是毛泽东题写的“人民英雄永垂不朽”八个鎏金大字，背面是毛泽东起草、周恩来题写的碑文。 碑座四周的大型浮雕，生动地表现了近代以来中国人民前赴后继、顽强不屈的奋斗历程和伟大民族', '2011-06-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICoitP7rO3VK2NrFPoesdHCpEA_fQcbBvBrcxuGBTmJAwzMrns7hNgbd0b8F-eNsOxbU5CkYgFwFQfwFG7YquvKau281Fbfu27tZud5mV0kS6yknYdn0vOdfN4Zxg9esbI4pIrsryExIg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened,将台堡_screened,四渡赤水_screened,会宁_screened,红四军_screened,土地革命战争_screened,瑞金_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (6071, '报纸', '黎明曙光', '朱玉; 肖春飞', '新华每日电讯', '新华每日电讯', '七届二中全会;副馆长;革命纪念馆;李庆安;“两个务必”;胡宗南;平山县;毛泽东;中国共产党;', '【解说】每一次惊天动地的巨变,都可能有这样平静的开始。 1949年1月1日,新年的太阳,升起在河北平山县一个叫西柏坡的小村子里。 这个元旦,国共两党的领导人,过着一样的新年,有着两样的心情。 节日之前,毛泽东为新华社撰写的1949年新年献词《将革命', '2011-06-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBsC_nZN516LO9QFctjtu-WS9jSzkgW8RhjiJjRumvx5xD786B_F4FwjC0HOOU-2pf34KhV2CFyaKMfqrt2WHFYNHh3lACbRW4evuEHxp_qO0CklrezJ9bsRBQGPSlDk1EXtFLONke8dA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (6072, '报纸', '正本清源惩腐蠹', '杨维汉 ; 陈菲 ; 周英峰 ; 崔清新', '新华每日电讯', '新华每日电讯', '反腐败斗争;标本兼治;综合治理;反腐倡廉建设;何叔衡;历史周期率;防治腐败;张子善;中国共产党;惩治腐败;', '1949年3月,河北平山县西柏坡村,七届二中全会会场。毛泽东向全党发出郑重反腐告诫—— “可能有这样一些共产党人,他们是不曾被拿枪的敌人征服过的,他们在这些敌人面前不愧英雄的称号；但是经不起人们用糖衣裹着的炮弹的攻击,他们在糖弹面前要打败仗。我们必须预防这', '2011-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID-HxeOCNShen4YGHgAdS6nzh9drUmB-DauUdWKH-xdO3_iuix8q0WzH52AoBS134Ekm6bE9DdUjtBy1bZ3l2GEpiPX0VGfAQDJISgJ7rG3wDGbPlaB1x5ghIqeD5QcVOF-_2KyIsmpDg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened,叶坪_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (6073, '报纸', '永远信守的承诺', '张宗堂; 陈菲 ; 史竞男', '新华社;', '新华每日电讯', '共产党人;全心全意为人民服务;为人民谋利益;宗旨意识;最广大人民;', '北京西长安街,天安门城楼西侧。中南海新华门影壁上“为人民服务”五个烫金大字熠熠生辉,鲜艳夺目。 这是中国共产党历史上最具号召力的宣传和动员口号,也是中国共产党对人民群众始终不变的庄重宣誓和戮力追求。 90年风雨兼程,90年矢志不渝。党成立至今,从“', '2011-05-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICXqMSHjFBBJt5af0CJgkw6i9S3ocUhVQKCl-TlNhUNus8J-tQv7WO9Ijsp0wUh7u_gAvf4iouHRIuJ21jzn7XQvHmNNfP6d4ECFj1cdhCR_fGNd4OoA7_7LsJZP-tHU9zDrosVaa-xCA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (6075, '报纸', '豪情满怀绘蓝图', '齐雷杰; 齐中熙', '人民日报', '人民日报', '七届二中全会;共产党人;政治局;毛泽东;', '太行东麓，滹沱河畔，群山环抱中的西柏坡村花红柳绿，翠柏苍郁。走进位于村口的中共中央旧址，一座座普通而肃穆的北方旧式民居映入眼帘。 这里有毛泽东等中国共产党领导人在西柏坡时期的故居，有党中央指挥全国解放战争的中央军委作战室。旧址西北角一个简陋的长条形土', '2011-05-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICewKUJFgArYyY2vKNKQvDBKtCc_P-_sLc-9xkarG4Exm_RggkTFP7UP7__owwrI2HxkwZtUhiUaAbf1H9lWEfR21KUE7k3CkpueybHtkVl8EkasFdHU32QxUIfwiD6xy5T5SSXy4e-EQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,七届二中全会_screened,两个务必_screened,两个务必_screened,西柏坡_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6076, '报纸', '河北有序推进“大西柏坡”建设', '武卫政', '人民日报', '人民日报', '大西柏坡;平山县;有序推进;', '本报西柏坡5月19日电 （记者武卫政）虽然不是周末，但河北省平山县西柏坡依然人来人往，一批批游客走进中共中央旧址、西柏坡纪念馆，讲解员的声音此起彼伏。来自山西太原的张先生说：“本来想趁‘五一’小长假到这里受教育，考虑到人太多，现在才过来。” 西柏坡是', '2011-05-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICWdIKeFJvPjMrNefdTWt7v6OXRIvTHiIgz9lRanlfZaOg9iqP_b8S0uS6ZZUVjIp-NEhyecFJ95gKSMS_BmHswGIEqQmVXasAORb1irp3T93RcKQx_aWLNiG5Ps2d8KULQbaNsDBp16g==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6077, '报纸', '永远直面执政考验', '李章军', '人民日报', '人民日报', '执政能力建设;民主执政;科学执政;执政考验;党的执政地位;', '今天是5月17日，普通的一天。 时间前溯5天，是汶川特大地震三周年。从“灾后恢复重建取得了决定性胜利”、“灾区面貌发生了脱胎换骨的变化”的豪迈宣告中，我们能读出什么？时针后拨44天，即是中国共产党成立90周年。从中国“由贫穷走向富庶、由封闭走向开放、由落', '2011-05-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDoY-k7z-bMeVi0XZbyJPhs5KZgZgPz1_ZVyIRp61Apga0JydgkdUg--o69hqtP15EA2ypgWWEIFyIyZp12Pc3pFQEsjbrgEP3ucWQDD2cQrD1MCH2e8Wnx1ylRmtiCmS707U853sn6cQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6078, '报纸', '做一辈子的共产党员', '钱建强', '光明日报', '光明日报', '共产党员;共产党人;', '面对杨善洲,很多人既崇敬又不解。崇敬,是因为杨善洲行得正,坐得直,一辈子做好人,一辈子做好官。不解,是因为杨善洲对自己,对家人,对身边人,都很严格,甚至严格得很“苛刻”,苛刻得有些“不近人情”。 按照世俗的眼光看,这样的想法一点都不奇怪。可不是么?作为云南省原', '2011-05-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBDLFzGwYbZPQ3hsIGX6c_XTj7bgRXFy9kg2SbCjVo6E5fhsBquhF2VC70S40Kq8J79rOQCCJHY4EveZc28i_whQZQIrEelsFHCLo-GyikVCmWirADeCottQ10PxmxvMv5wOIwlJqoLog==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6079, '报纸', '进军西藏,巩固新中国国防', '宋月红', '中国民族报', '中国民族报', '毛泽东;刘伯承;', '新华社1949年9月2日播发《决不容许外国侵略者吞并中国的领土——西藏》的社论，阐明了中国人民、中国共产党和中国人民解放军对于西藏地方坚定不移的方针，即两个“绝不容许”：西藏是中国的领土，绝不容许任何外国侵略；西藏人民是中国人民的一个不可分离的组成部分，绝不容', '2011-03-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICcGKxzAEZJL4BGxvDI7X4ekWdY2ysQkSppPMlwK0YSABpq6VJEgEnZSDpv8VckQB4o-v13U6GL0BvlBLwSiaYJoqNrCKLnAmPQeVUIB8H0HndE1mdOi751WdDUY9DhjMUmK92hbCV83Q==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6080, '报纸', '以史为鉴 居安思危', '王新民 ; 王素艳', '中国纪检监察报', '中国纪检监察报', '李自成;秦皇岛市;农民军;明王朝;“两个务必”;以史为鉴;《甲申三百年祭》;吴三桂;惩治腐败;反腐败斗争;山海关;党风廉政建设;', '以史为鉴知兴替，居安思危忆甲申。  8月7日，全国第一个以“以史为鉴、居安思危”为主题的廉政教育展馆——甲申史鉴馆，在河北省秦皇岛市山海关区正式开馆。  “保持党的先进性，加强党的执政能力建设，甲申的这段历史要永远读下去。”出席开馆仪式的河北省', '2010-08-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDv0u7RI-Bc7jNJmUZt5n3nogLJbsfyFdffxarEuf0MYgu51O00TYc2xrYjhsMb8Ic1L3dIEGJ41imSexXBeuLU9PVm9vmz91WFX-3o38Oh6kmGOwazuTjirrKI2XnBDrNe0rGNf4uUTg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,中共七大-2_screened');
INSERT INTO `ds_article` VALUES (6081, '报纸', '“红十字”方阵的“寻根”之旅', '唐先武; 黄显斌 ; 洪建国', '科技日报', '科技日报', '传染病防治;传染病医院;', '京西郊外，一座“红十字”方阵医院格外引人注目。她从解放战争的炮火硝烟中坚强地走来，搏击传染病防治战场数十载，先后在抗洪抢险、抗击“非典”、抗震救灾、奥运安保、抗击“甲流”等急难险重任务中屡建战功，为人民和军队筑起了一道道坚不可摧的“防疫长城”。这就是全军', '2010-08-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICb60ofrRruXl3ufK045ZcLjx7l_1429rsfnCj21pvncGEl3wtuBhOcScIx69hlRGbN4ipH0Dyp5mDLjoyy5chuB4sgYuypIbBgusHoHjp35R0zlnSHkXQzjmnIszvj0Jd-TxeJwYcNFQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6082, '报纸', '忆峥嵘创先优', '冯君 ; 毛翠辉 ; 谢盼', '中国气象报', '中国气象报', '“两个务必”;两个务必;七届二中全会;气象部门;气象事业发展;气象局;创先争优活动;思想武器;平山县;', '6月26日，放弃节假日的休息，中国气象局办公室党支部和人事司党支部的部分党员来到革命圣地西柏坡，重温那段峥嵘岁月，向党的89周岁致以崇高的敬意，以更加昂扬的姿态吹响创建先进基层党组织、争当优秀共产党员的号角。中国气象局党组书记、局长郑国光，党组副书记、副局长许', '2010-06-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDLg6hTESeV2LMLm4kE7QUGkMFBg8g8H4aue5wdmLEf8U49JiIFOKBVrSIauqbzSQurJiGF0WsL3biY1rR-XoUgiFgCQn_bXLVxAVUrwsWYRIgQu3oYSrMmjeGnl13ERWP-xgHQQa9GyQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6083, '报纸', '寻根西柏坡：追忆新中国第一缕光明', '周龙 ; 王逸吟 ; 张凌云 ; 姚晓丹 ; 贾宇 ; 郭冠东', '光明日报', '光明日报', '“两个务必”;李家庄;七届二中全会;晋察冀日报;李维汉;胡愈之;王二小;岗南水库;龙沟村;民主人士;中共中央旧址;宅北乡;平山县;新闻工作者;共产党人;', '清晨的薄雾笼罩着山脚的小学，静谧，清新。  上课铃声响起，向教室奔去的孩子程柏旭急急转回头，大声用河北平山方言解释他的名字：“‘柏旭’嘛，就是西柏坡的‘柏’，旭日东升的‘旭’”。  举起相机为孩子拍照。不经意间，校园围栏外、蓝天白云下一块硕', '2010-06-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICfdvmSsa_u2oXOfkgjPIc-zfjEckuOoc3AU2D9AFUIjPkhNqu3miTw4ebvT58js54InNXrnxVfn9ph7tGTORZ6nrFZo03M4_nixH3Gk2HDK2MXWtRIdFM42B3PhqKKgRJFgZG8yiY9pg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6084, '报纸', '红色圣地寻革命之根找新闻之源', '徐福平', '工人日报', '工人日报', '青年编辑;龙沟村;人民日报社;', '5月的太行山区，正是桃李花开时节。位于太行山东麓、滹沱河北岸的河北省平山县西柏坡迎来了一支年轻的队伍，他们在巍巍耸立的西柏坡纪念碑前、光华闪耀的中共中央旧址、里庄人民日报社旧址等地驻足沉思。 5月23日至29日，来自中央新闻单位的百名青年编辑记者在中宣部、', '2010-06-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBt4ljztEfnGSOzI1Xj6aTZhkBsguoz6U6AV69ZeCFwCHJYddr_NANUmSwCeGPAPO0xldXeQoa96Q0V2BDTpYnzGfF7SuZnc1W-FIb-tvoVxBwAchpbRkaVA5x-XHih1YQQp2rBHUz75A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6085, '报纸', '红歌谣里我们心手相连', '秦超; 徐叶青 ; 王振江', '解放军报', '解放军报', '青年编辑;“两个务必”;', '“最后的亲骨肉含泪送战场，最后的一尺布送去缝军装，最后的一粒米送去当军粮，最后的老棉被盖在担架上。”85岁的老党员、老军人刘书彦深情地哼起这首歌时，我们流下了眼泪。 红色歌谣历时60多年久唱不衰。在平山县委书记王俊英的情况介绍中阐释着它，在河北省社科院教', '2010-05-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICNN5oT6iuVWShSNAg2B8eQcxxFrK-yHrne5rtJ-RPUuYDwKI50YL-eDtiIYosz92fwWO9Lq5q7j5lRNcjaMzbDkzcXIYeBxqXz9yCKdl5OCsa3lApJpZayMpKQG_dLElJswC0jZmYlfA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6086, '报纸', '毛泽东反腐败思想的特点及其启示', '穆红玉', '最高人民检察院机关;', '学习时报', '毛泽东;共产党;反腐败思想;反腐败斗争;', '毛泽东是一代伟人。他虽然已离我们而去，但他的正确思想和丰功伟绩将永远铭记在人们心中。现在，全党正在开展一场反腐败斗争。在反腐斗争中，我们重温和回顾毛泽东关于倡廉反腐的教导及其实践，无疑是有重要意义的。  在毛泽东的整个革命生涯中，他用巨大的精力和心血凝', '2010-03-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIApTg5H3UsE6Q84taXOn3ynIf8fPDIwKzSGLXi8EMldc--0Om5WOG9wXrYCr0B6EmKKn4qNbWPuYQbohYFJVcYYncpPis2L4bapB7wkamnIjmfi28oDzkd7C9kNTkRY7gBwWcFByqzJlA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6087, '报纸', '情系西柏坡', '孔晓宁', '人民日报海外版', '人民日报海外版', '全国土地会议;七届二中全会;刘少奇;', '天寒地冻的日子，从京城驱车南行300余公里，走进“红色首都”西柏坡，内心热得竟像雪地里的温泉。 这儿其实全无“首都”的气派。中共中央和中央军委旧址，不过是一道土墙围着的几排土坯房。它们也并非原物，1958年修岗南水库时，旧址全部沉入水下。现在见到的房舍，', '2009-12-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDz8jfAuSb4IrZN87IQNoazIqgoOOtCheQ_5Uh5b_nk117o8ehDvPY7SJXvkjQAxYpWTLThSftPQDyPKYAes09Vftqlbxj3Ne7jg3pRiRcEalCEWnSaA6I46uOPSiW1YiedvnCN2L3YbQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6088, '报纸', '薪火传承西柏坡', '程峰典 ; 郭建跃; 刘松峰', '解放军报', '解放军报', '红色旅游;平山县;“两个务必”;全国土地会议;石家庄市;中共中央旧址;', '秋高气爽，阳光明媚。记者从石家庄出发穿过平山县城，沿着新开通的西柏坡一级公路，一路疾驰，来到了令人向往的革命圣地西柏坡，在景区入口处，有一新建标志性大型雕塑——“新中国从这里走来”。 这是一个依山傍水的小山村，位于平山县中部，背依苍松翠柏的柏坡岭，前', '2009-11-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBAf4LGidZhQiW51JkF8wJbZIw-b-Lbhl7-Q8M1mDnzjKUWZA8bUiIgAijCozL46eZwcZGfzf--s-2_rJlYLwO6zsufmKBf824ayid7RjSxNypNsHXWiCiZPIF0wAyFShzcDXVkEYmbEw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6089, '报纸', '奋飞在新世纪的天空', '', '解放军报', '解放军报', '人民空军;空军飞行员;空中梯队;', '剑啸苍穹，风雷激荡。 国庆阅兵盛典空中梯队的壮观阵容背影不远，与共和国同龄的人民空军又将迎来成立60周年的纪念日。 值此之际，本报记者采访了中央军委委员、空军司令员许其亮上将。  ■人民空军已形成以第三代主战装备为骨干的空中作战体系，战斗力水平', '2009-11-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDx-TUiG5mSMLe4OGMGjTiagnjwRDd7GFjYYcYhRJW6PBkySenRF7jsnvMBqLl15s4Evxttsj2ErlDaZKbra92wfgkLVVMOoNWEIJbG6XMnbAJSaJXlxVslMGt73DC_UY6vUbaFa_974g==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6090, '报纸', '中华人民共和国大事记(下)', '', '中共中央党史研究室;', '人民日报', '国务院常务会议;全国人大常委会;科学发展观;全面建设小康社会;江泽民;胡锦涛;中共中央;中央委员会总书记;政协主席;中华人民共和国大事记;中国体育代表团;中央军事委员会主席;中央军委扩大会议;澳门特别行政区;', '１９７９年 １月１日　全国人大常委会发表《告台湾同胞书》，提出尊重台湾现状、实现和平统一的大政方针，建议两岸实现通商、通邮、通航。同日，国防部长徐向前发表声明，宣布从即日起停止对大金门、小金门、大担、二担等岛屿的炮击。至此，从１９５８年开始的对上', '2009-10-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICXryhyfm16DHVU1VgRKQc0m6E2_Axa5DrDXv9GhE5M55EP2Yyk5QIs3Ve6RJ7uVFWSFCmGNrh8NPe4_3utJWVLUjjojzncwYQK6vOzeGAsXEU2cjg23wOtAH4kok6O8L9trg53CZy9ow==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6091, '报纸', '“赶考”起点的新答卷', '王方杰; 姜艳; 郭伟; 李巍; 张许峰', '河北日报;', '人民日报', '三年大变样;现代产业体系;新中国成立初期;“两个务必”;人均期望寿命;', '核心提示 新中国从这里走来。 60年前，新中国成立前夕，毛泽东率党中央从西柏坡出发“ 进京赶考 ”。 60年中，作为“ 赶考 ”起点的河北，与新中国一同成长，奋力书写改天换地的壮丽篇章，努力交上一份让党和人民满意的“ 答卷 ”。', '2009-10-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDkkZpcRoXchU-xTi0UQ1q4ryL9DCOTfgSdnNHzuYWtITyOwJyrmjtC6pNgcvvwlp4W6nPe1xXKWoL86FRvGf9HqZJH6q5556h1QertRzUSobrmlz2Mr1UGqYG4h3tJxlwKe_aR7uwKXw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6092, '报纸', '评剧电影《西柏坡》向共和国60华诞献礼', '童刚 ; 裴世杰; 康式昭; 袁淑梅', '国家广电总局电影局;', '中国文化报', '现代戏;《西柏坡》;首映式;“两个务必”;时代特质;新中国成立;电视连续剧;胡锦涛;红色文化;飞天奖;文艺工作者;共和国;', '在评剧电影《西柏坡》首映式上的致辞 国家广电总局电影局局长 童 刚 尊敬的各位领导、各位来宾、同志们、朋友们： 大家上午好！ 在全国人民满怀激情迎接新中国成立60周年的喜庆时刻，由河北西柏坡影视制作中心、开滦（集团）有限责任公', '2009-09-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICAPFbYhi9aKqLXVB0URWfyNLecV-9GCuO0F0gDxWZXcUNRh47XZQk8_sCGeweACd-4CJFqgZv0leyyM0BW29VtBaEpUSOWmSSmtWIk2ws-HmHGV4n_IfBV8hHiFytaUT_rBdButo8QBw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6093, '报纸', '老区人民欢歌劲舞迎国庆', '乔欣', '中国文化报', '中国文化报', '沂蒙山革命老区;河北省石家庄市;', '近年来，在国家政策的强力扶持下，诸多的革命老区经济社会快速发展，城市建设日新月异，许多地区还发展成为著名的红色旅游胜地，人民群众的生活发生了翻天覆地的变化。在新中国六十华诞来临之际，各地的革命老区纷纷以不同的形式表达着对新中国的祝福。 延安：', '2009-09-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID0O0qd-m58lRdjQbf0Zp-I80xTXXLWcp2cZ2JK_Tq3BBVlIxXeeGKxpirp2Ne0tHITAXzHR1baFia70wGVj8dxjyGIV95MxEc2ZFHT8okNcduhOq6kBsClI6X52qpRv5o4SIqL_ppfqQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened,抗日战争_screened');
INSERT INTO `ds_article` VALUES (6094, '报纸', '“赶考”一甲子', '贾永; 李亚杰; 刘娟', '新华每日电讯', '新华每日电讯', '中国共产党;社会主义;新中国成立;粮食自给率;张子善;中国特色社会主义道路;十六大以来;执政兴国;', '新华社北京9月14日电(记者贾永　李亚杰　刘娟)60年前那个初春乍暖还寒，21辆陈旧的吉普车和大卡车疾驰在华北大地上……  1949年3月23日，河北省平山县西柏坡村。就是从这个小山村出发，毛泽东率领从炮火硝烟中走来的中国共产党人，意气风发地进京“赶考”。临行前，', '2009-09-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA6lbhoEpJ8p27xx2DAOVTKv14ew80KGLKpUSzYw--B0LPE6Qf2sLR697uhNSkPQGKbpUYydtpQhc9wBeydwTmoQe5vFifnYD-LTGwmiJjdk6ux3FFdmnECh_KLRL1gswSYwJi8YcgoJQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6095, '报纸', '西柏坡：继往开来绘新图', '胡红军 ; 雷汉发 ; 庄光平 ; 陈莹莹', '经济日报', '经济日报', '全国土地会议;“两个务必”;平山县;', '8月24日，记者来到西柏坡时，天空下起了小雨，太行山更加显得郁郁葱葱。西柏坡纪念馆、中共中央旧址等就掩映在山脚下的绿色之中。 西柏坡————河北省平山县的一个普通村庄，60年前成为中国历史巨大转折中的枢纽。中国共产党人在这里开创出翻天覆地、沧桑巨变的辉煌', '2009-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIApNMDwcMbFaGSEDrv1c_taEi8UXdEPTJCaXVvKiGeCrgjHW_TMlTIgyedM6lfkOlQJAJNOKkFBqVNsZxLyaiwMK0ilBSUUfTMgIcPL1LwnFqwgpRbFS_PhSbUnDWNFNB70Cjm1RSAzRA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6096, '报纸', '西柏坡：山更绿,水更清,经济活力增', '庄光平 ; 雷汉发; 胡红军; 陈莹莹', '经济日报', '经济日报', '平山县;经济活力;何连芝;中国人民解放军总部;中共中央旧址;核桃树;杨梅生;', '西柏坡位于河北省平山县中部，解放战争时期这里曾是中共中央和中国人民解放军总部所在地。 上世纪40年代末，中国共产党在西柏坡召开了全国土地会议，领导了解放区的土地改革运动；组织指挥了辽沈、淮海、平津三大战役，夺取了解放战争的决定性胜利；召开了具有历史意', '2009-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBl-m8s-yAgBi-XWhgOcPlA1wCqzJjfbRKXdO8xbF5BdeQ6BBKQk1_nzXPzxsdLriqMWt_4ZtaaK68jISbLg3JbweTFP7keHsfzjDonMcFA7A7krDZTQoQpf9Gvdm9GH8z1CONjOm3KAQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6097, '报纸', '西柏坡铺展“红绿蓝”新画卷', '王方杰; 王明浩', '人民日报', '人民日报', '平山县;“两个务必”;红色旅游;岗南水库;县财政;中共中央旧址;', '翻越道道青山，穿过座座村落，记者来到河北平山县太行山东麓、滹沱河北岸的革命圣地西柏坡。 在西柏坡纪念馆、西柏坡中共中央旧址，在五大书记铜铸像前，游人如织。人们凝神瞻仰，驻足沉思。 “今年以来，到西柏坡参观的游客已接近90万人，‘七一’前后每', '2009-08-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDPsLnFO8Ju-IbqC5ZCuBtkkPrKaauhjlm5cuhkBCmc_rtrVzgdVAiPnDv9Cw7YYYvpfJ79naOz67xHv9H2PNDEKX6I4eqf6w4bnXb7uksIIcGSwPiiEhdNU87GcYGMpCx-czZZ2Cg1Ug==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6098, '报纸', '《十七大以来重要文献选编》上册主要篇目介绍', '', '人民日报', '人民日报', '科学发展观;改革创新精神;十七大以来;党的十七大精神;《十七大以来重要文献选编》;惩治和预防腐败体系;加强党的建设;新的伟大工程;惩防并举;反腐倡廉建设;反腐败斗争;党的执政能力;中国特色社会主义事业;党的先进性;党性修养;', '《高举中国特色社会主义伟大旗帜，为夺取全面建设小康社会新胜利而奋斗》是胡锦涛同志二〇〇七年十月十五日在中国共产党第十七次全国代表大会上的报告。报告回答了党在改革发展关键阶段举什么旗、走什么路、以什么样的精神状态、朝着什么样的发展目标继续前进等重大问题，总', '2009-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDgCbdudeXbZpvQqiASRSKvAXC8TH4oZdCv1SAmhU0C354kTbfsmdbNJ9Kj7O5qKp6Sc5Z8upij-lWkwDDjfF8b1t3aZBHRuyPrKcGf2Snz-59QtHpSgIwFa5020Ix9c2b98LDs2IxakA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6099, '报纸', '西柏坡：伙房中诞生“两个务必”', '王文化; 曲澜娟', '新华每日电讯', '新华每日电讯', '“两个务必”;全国土地会议;平山县;岗南水库;石家庄市;', '新华社石家庄8月23日电(记者王文化 曲澜娟)中国革命史的宏大叙事，在一个小山村里谱写了夺取全国胜利的宏伟乐章。 村边的空地上，议定出改变两千多年土地制度的纲领；静寂的农居里，指挥过波澜壮阔气吞山河的决战；简陋的伙房中，提出了“务必使同志们继续地保持谦虚', '2009-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID3q46-VPhJXMnLX44pm4V291rR1sr4JFoBWq7XHeYarNS66xBHzin7a42fv5LfBIX0vcE269n1gWmPfdVRiLwKWb9U_g-8xC7Hq0JQtnfExzF6rVIG3pZqRoZNJHYq5dTFclpY-7f4FQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6100, '报纸', '青青柏坡万象新', '耿建扩; 韩剑', '光明日报', '光明日报', '“两个务必”;平山县;', '这里的山,钟灵毓秀,翠满山坡;这里的水,湖光潋滟,碧波荡漾。这里是太行东麓一颗璀璨的明珠,这里是中国革命的圣地——西柏坡。青青柏坡岭,如今万象新!  圣地精神代代传  8月13日,记者来到西柏坡纪念馆,抚摸着毛主席旧居中那盘曾经当做书桌谱写了三大战役辉煌胜利', '2009-08-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAmJtr8NKsukFC6sIwmZip73jplnGMqo2pVej22esllIo49r1lLc8B26gzHkdWoJ8WOKwC-tOQG72VY4nGM-8Yn7LogJ3a9dNSt6IddhArncKwVfhz62tF7nFBNhfAWFK70VyJd2iooNQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened,抗日战争5_screened');
INSERT INTO `ds_article` VALUES (6101, '报纸', '从西柏坡到慕田峪 谭晶边走边唱', '胡芳', '中国文化报', '中国文化报', '独唱音乐会;万里长城;七届二中全会;亲历者;', '本报讯 （记者胡芳）8月12日，河北省平山县西柏坡七届二中全会旧址内，人头攒动，摄像机、相机连拍不停，这间简陋小平房侧开的窗外，也挤着几位争先恐后对准室内拍照的游人，“那是谭晶吗？” 在七届二中全会旧址主席台两面党旗映衬下，由中国人民解放军总政治部歌', '2009-08-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAxsSlFOgHLhR6ecZYYIUu_y0edukr_I1PCMb7dWfKsThdlu8vjuis3NpY50iTSwQZuS4a1Hroc3iaH1wUM9ycb5FvxwUIlCJX3VRxXwEIlzn-49S1sN2ZN--F2Y5qRvls-cHAS1yMZsg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6102, '报纸', '重访革命圣地,重温党的精神财富', '李柯勇; 储国强; 王文化; 肖春飞; 周伟; 董智勇', '新华每日电讯', '新华每日电讯', '精神财富;“两个务必”;', '上海：面貌日新月异，凸显“锐意创新”的进取精神  上海，中国共产党的诞生地。站在中共一大会址的乌漆大门前，几乎能触摸到历史的沧桑，而放眼现代国际大都市的繁华景象，又鲜明地感受到，创新是这个城市最突出的特征之一。  “某种意义上，中国共产党的', '2009-06-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDNRC3Lt608S6V-65K6cnxZlJionyZv0a9nDbCK1on0vXGqErHu4P2f2hTuhldZov2hMkJXvc6LbMmSJ4fFbgAUczkuULlgeGn12X5gFw5NzpE_Sj_r4GPeSCrHmhL3UDZ0YD0iV5Kxiw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6103, '报纸', '进城一甲子,向世界交圆满答卷', '慎海雄; 肖春飞', '新华社;', '新华每日电讯', '共产党人;国民党;浦东开发开放;不法资本家;现代化国际大都市;', '2009年5月27日，上海解放六十周年纪念日。  60年前，当红旗插上外滩高楼、枪声逐渐淡去、大军露宿街头之际，上海被担忧、疑虑与嘲讽所包围。国民党断言：共产党在这里维持不了三个月；上海的资本家说：共产党军事打100分，经济是0分；国际社会在观望：从农村走出来', '2009-05-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDhS6cjKMQrRyEUVgI5pH2ULQzcAQYeGhNkX3lcjwC9nU2-6Evk4dMN7m_veCeE_9X2mzN0bhntVdk4dOT2krgqCAqf_VkNZR4LJp_exANGI48tnd47kKHQSzBOYZgLXKjL1zmPyOo5sw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6104, '报纸', '牢记“两个务必”弘扬王瑛精神', '孟德成', '中国纪检监察报', '中国纪检监察报', '“两个务必”;七届二中全会;', '阳春三月，冀中大地万物复苏、春意盎然。3月20日，由中央纪委、中央组织部、中央宣传部组织的王瑛同志先进事迹报告团来到河北省平山县西柏坡参观，缅怀党带领人民进行伟大革命斗争的光辉历史，重温毛泽东同志在党的七届二中全会上的重要讲话，特别是关于“两个务必”的重要论', '2009-03-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAmJtQahJ7OXwMpmzRXJGiGpYhAg-JfYXxPw7YebzZ1-muFZi-8QP0ZUWR5XrmuluFv1HkehhTAwTD-_6XWlhk-LkygytUj6AQTNPJFLk6J5Lr7j5-1N8p-g82KUmCctklVOdrae4zl_A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6105, '报纸', '坚定信心保增长 凝聚人心促和谐', '', '人民日报海外版', '人民日报海外版', '人民政协;履行职能;科学发展观;凝聚人心;灾后恢复重建;中共十七大;民主党派;政协委员;海外华侨华人;保增长;', '深入学习贯彻中共十七大精神 全国政协主席贾庆林说，学习贯彻中共十七大精神，是本届政协的首要政治任务，也是贯穿各项工作的一条主线。 贾庆林说，我们组织开展形式多样的学习贯彻活动，全面准确领会十七大提出的一系列新的战略思想和决策部署，增强了高', '2009-03-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBzuYwpwusJ-8XBcQGipYJzw3PyXzOnhgEZ8NbqxbbIXmWmm0rBtdtOnnmtm7kaAGZNUC46lhEOA_ooA1ey7y3v9hSLkF0ltXtVQs94XF4QjVzfzmT9-PDdlLFY8rNohR5pfSjmfgAW9g==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6106, '报纸', '改革开放三十年大事记', '', '人民日报', '人民日报', '国务院常务会议;中央军事委员会主席;重要讲话;胡锦涛;全国人大常委会;中共中央军事委员会;科学发展观;政协主席;江泽民;全面建设小康社会;中央委员会总书记;改革开放三十年;', '一九七八年 12月18日—22日 中国共产党第十一届中央委员会第三次全体会议举行。全会作出把全党工作的着重点转移到社会主义现代化建设上来和实行改革开放的决策。邓小平在此前召开的中央工作会议闭幕会上作了《解放思想，实事求是，团结一致向前看》的总结讲话。', '2009-01-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDgr2O9ihpRgJOSCtOk7nsi9pSXCe41CpB1HnGehRYUuULauRsHsOkj_gKzJacehcpfqo9ZL-81mb3Ad41u-DoDiI3S6NtJ8eMQtPYQbC8Mu55f6_xE38eZCldiuV8pGzRXMegOgsMzzQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6107, '报纸', '纪念改革开放30周年——中国成长报告 改革篇', '倪迅', '光明日报', '光明日报', '天津滨海新区;改革开放;开发开放;社会主义;科学发展观;深圳市;国务院;管理体制改革;政治体制改革;江泽民;全面建设小康社会;', '改革开放大事记  如果现在再不实行改革，我们的现代化事业和社会主义事业就会被葬送。 ——邓小平  改革开放，是新时期中国最鲜明的特征。没有改革开放，就没有建设有中国特色社会主义。 ——江泽民  改革开放是决定当代中国命运的关键抉择，是发展中国特色', '2008-12-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICZtelO8ITcGt-Kmd9ym6n1DrZlZmIKaIBz6m-GNYyUX41KCrhLt9ocJ3fxINEYn1YgL-7XKd-ahk701no2fDW2K-EarEOQ3cAugWaDAi2EFuG8DgGWaXRUr4K5N2x9LcTuNFh_x8a_Hw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6108, '报纸', '在纪念刘少奇同志诞辰110周年座谈会上的讲话', '胡锦涛', '人民日报', '人民日报', '刘少奇;党中央;社会主义建设道路;白区工作;座谈会;', '同志们，朋友们： 今天，我们怀着十分崇敬的心情，在这里隆重集会，纪念敬爱的刘少奇同志诞辰１１０周年，深切缅怀他为民族独立、人民解放和国家富强、人民幸福建立的历史功勋，追思和学习他为党和人民事业不懈奋斗的崇高风范，激励全党全国各族人民满怀信心投身全', '2008-11-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAOv5a-yp13Y6mf3MiP0DvOhZH8XTtwt9PTLh9ReeytQD1dLHzyrMFA2i2IiWbMIoQqirpeL_Gw2zXVobsMXlGdsoa6tJeJZS6Ljrbq-i2GKVbI6K9PCwVu4bcmp7dzikKWM0ti--Ieaw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (6109, '报纸', '胡锦涛的讲话', '', '新华每日电讯', '新华每日电讯', '刘少奇;党中央;社会主义建设道路;白区工作;胡锦涛;毛泽东思想;华中抗日根据地;', '新华社北京11月11日电在纪念刘少奇同志诞辰110周年座谈会上的讲话  (2008年11月11日)  胡锦涛  同志们，朋友们：  今天，我们怀着十分崇敬的心情，在这里隆重集会，纪念敬爱的刘少奇同志诞辰110周年，深切缅怀他为民族独立、人民解放和国家', '2008-11-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA8i-kELZlR36zThF135EWxlaTpQCEEoZrigDpkdWLmN2NuhUi7qmxNKiP26ZjCvJ_ztTH2Gdcb7lRj22ZJJTakeAwbPQltNyNBIqQ-6jQLnj5Hx2Ga1NhUrapRXuJhy5gUBg29o-YXLA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (6111, '报纸', '探索大部门体制 创新机构设置', '', '中国工业报', '中国工业报', '大部门体制;工业和信息化部;“三定”;军民结合;机构设置;', '大部门体制有利于整合职能，形成精简高效的政府组织结构。党的十七大和十七届二中全会提出，探索“实行职能有机统一的大部门体制”，这是新形势下转变政府职能、建设服务型政府的重要举措。在《国务院机构改革方案》中，把组建工业和信息化部作为大部制改革的内容之一。工业', '2008-07-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDb_Mkjtwi3PhcO4TtaEqNBzqBp047eB-JO1HJeB3xCS4Lbr79brHTLzg_hSDFuPTHc1qEGCodfvrjbPcNbhsk7NOsQdisizekIhPKMtoaogMEhyqxry3IPY9ewk_V-vuhFWZnEjozf5w==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6112, '报纸', '温家宝主持召开国务院常务会议', '', '人民日报', '人民日报', '国务院常务会议;温家宝;“三定”;', '新华社北京6月25日电 国务院总理温家宝25日主持召开国务院常务会议，审议通过部分国务院组成部门、直属机构和部委管理国家局的《主要职责、内设机构和人员编制规定》。会议指出，制定和完善职责、机构和编制的“三定”规定，是贯彻落实党的十七届二中全会精神、进', '2008-06-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDg6mbjysOVE0WLU3jLyB5kcvGNzZcjDb8Bdsz2eQOKIM_R9LxtjGkuOiH_k3A3iTbDd3o1ZRhvApN_fjLwrMP86DcKs5XI25m0WYLFy8haZRO35l8esT414q9ePtLAHy4gtly_j-mjZg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6113, '报纸', '我们对中国的民主政治充满信心', '裴智勇', '人民日报', '人民日报', '民主政治;中国特色社会主义理论;社会主义民主政治建设;党内民主;', '胡锦涛同志在党的十七大上提出：坚定不移发展社会主义民主政治。 4月的北京，春意融融。来自各省区市和中央国家机关的40多名省部级干部，在中共中央党校，直面新的世情、国情、社情、党情，就发展社会主义民主政治展开了为期10天的专题研讨，他们对中国的民主政治', '2008-04-30 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB6meukuisx3jYCSrNVRRN5_UcOB8SEmvXO5uwqwmA977VEuuA6nIEBM8J3uhCDq-oc5-16w8mcGEbLk85rW62PA_QV9giKewIwUBQEM96mBdAqL2DCcytYyd7HZYYASgxjKS5Cp5qBWw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6114, '报纸', '在纪念王震同志诞辰100周年座谈会上的讲话', '习近平', '人民日报', '人民日报', '座谈会;', '同志们： 今天，我们满怀敬仰和思念之情举行座谈会，纪念王震同志诞辰１００周年，深切缅怀他为党和人民建立的卓越功勋，追思和学习他的革命精神与崇高风范，激励全党和全国各族人民为建设和发展中国特色社会主义而努力奋斗。 王震同志是中国共产党的优', '2008-04-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDrccpxklJaDWrqLz6i0fuSJ3d3ZZKoymIfNRiRABqJ-kRyPdpo6IDJCsVO--G3EhuNvpRwCErVYRnH8evJLlj1S8yXFBM3NKnVq9NDmEuJDyTxSBMvvrJVFAxOg-amQu_4GdVUfvIzRw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,抗日战争2_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (6115, '报纸', '监督制约权力,今年着力五项制度', '田雨', '新华每日电讯', '新华每日电讯', '制约权力;损害群众利益;反腐败工作;合法性审查;防治腐败;反腐倡廉建设;', '新华社北京3月25日电 国务院今天下午召开新一届政府第一次廉政工作会议，温家宝总理发表讲话。这次会议的主要任务是，贯彻党的十七大、十七届二中全会、中央纪委二次全会和胡锦涛总书记重要讲话精神，总结过去五年政府系统反腐倡廉工作，部署2008年的工作。  国务', '2008-03-26 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICsC-WX4stT-W7GDA6FzDFZf6yTDD6WFVhp6qpRs2w-vMvOe0pReYsHs5Wn3agdhT1HxtpH4Y-d-eUHTdd-MSmtbm_69RUBJUtUcQMIl7kWcBWqoifVq9vuLrdn_2BdV5L1cpkm9aEHbQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6116, '报纸', '温家宝：国务院组成人员要约法三章', '', '新华每日电讯', '新华每日电讯', '国务院;温家宝;组成人员;', '新华社北京3月21日电 国务院总理温家宝21日上午主持召开新一届国务院第一次全体会议，并发表了重要讲话。会议宣布了国务院领导同志分工和国务院机构设置，讨论通过了《国务院工作规则》。会议分析了国内外形势，对当前政府工作作出部署。  温家宝指出，本届政府任', '2008-03-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDYwUYjOa-cEmJrQ3bbdgsCMJh8OhKKqTyLopu90MGXXhb1W40XcGdD27OeRFyRcfkKV9UEOSohiZu5EXag7cMjrq2y0R9IEyyBWWRYIPlmgSlrt5FNThuT1WMCqC2SsqPuA5wbEAWhCA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6117, '报纸', '中共十七届二中全会在京举行', '', '人民日报', '人民日报', '七届二中全会;人民代表大会制度;中央委员会总书记;国务院机构改革方案;党的十七大精神;中国共产党领导;管理体制改革;政治体制改革;中国特色社会主义政治发展道路;社会主义民主政治;多党合作和政治协商制度;抗灾救灾;', '中央政治局主持会议 中央委员会总书记胡锦涛同志作重要讲话通过拟向十一届全国人大一次会议推荐的国家机构领导人员人选建议名单和拟向全国政协十一届一次会议推荐的全国政协领导人员人选建议名单；通过《关于深化行政管理体制改革的意见》和《国务院机构改革方案》，同', '2008-02-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDftm0n8GF3GqH6JuDp1pY3x5Io_HZTalZdTTqZNEn7iuWvkLfUXh5e6c81XmVewVU-b8vEPCAHmsnk4pf37so9eIRTiXH52M3NlB5uxMx4Ib6-W0GXeATp9ZLcUmLaYFwsYV5nF7izwA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6118, '报纸', '中国人民解放军军旗、军徽的诞生', '', '人民日报', '人民日报', '中国人民解放军军旗;八一军旗;', '军旗是象征军队或建制部队的旗帜。军徽是象征军队的标志之一。中国人民解放军的军旗是在革命战争时期产生和逐步定型的。从毛泽东领导的湘赣边界秋收起义开始，就制定了旗帜。１９２７年９月初，为筹备秋收起义，刚成立的中国工农革命军第１军第１师奉命研制了起义的旗帜样式', '2007-08-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAlaAcgeYtYa6sD4YMqXnZLySxMUtaLyvNoDjxPrfTJ-gWj7pmaYWiqjHDTKB5h3Yfntq1ZdrQxY1V69wdwL0gXWSCEq1431-vEklnnMGSUgWyt0jTe0jdwHxTDangC3IgZu9_CLKNaBg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6119, '报纸', '烈火中永生', '', '人民日报', '人民日报', '渣滓洞监狱;国民党;《挺进报》;宋绮云;杨虎城;大屠杀;李青林;歌乐山;政治犯;', '以白公馆、渣滓洞监狱为主的重庆歌乐山军统集中营，是１９３９年至１９４９年１１月间，国民党军事委员会调查统计局即军统秘密关押和屠杀共产党人和抗日爱国民主人士的监狱。 从１９３９年到１９４３年，军统在歌乐山下修建了包括白公馆、渣滓洞、杨家山、黄家院子', '2007-06-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAHWbD_AQVdo6fW3cL0_GT60-qbKtQMDhsw7eWcXLhQ5t_xTiNiNxP8wU6ZjfwhpQm6sMhel1_oPS4sb71I8-vZuIw1GQkfrmbUZQG-yxZ9Vfzg462woeBX4Fa7ZI7l_uviGyJljHeMdQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,白公馆_screened,渣滓洞_screened,罗广斌_screened,陈然_screened');
INSERT INTO `ds_article` VALUES (6120, '报纸', '新华社西柏坡旧址复原对外开放', '张宗堂', '新华每日电讯', '新华每日电讯', '新华社;毛主席;新华通讯社;', '新华社北京11月6日电(记者张宗堂)作为中国的国家通讯社，新华通讯社11月7日将迎来她75岁生日。按照“忠于历史、修旧如旧”原则复原的新华社西柏坡旧址已于近日正式对外开放。  1948年5月至1949年3月，是党史上所称的“西柏坡时期”，这是中共中央领导指挥人民解放战', '2006-11-07 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDxoJy-BCpuPk8AqgXUWwVpFsN7hkqngm41e3vhSpbKeLm1yoGdV8ELTNWU7q0YAFJUYPV5ejpSWKWaWZoNSu4FsWws26zbF6v9yziPVZKJ3WNL-QkvDgRAYeZ_HrBIwAMfnMPQ1Hva7A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6121, '报纸', '“进京赶考” 我们不当李自成', '', '人民日报', '人民日报', '李自成;人民解放军;中共中央;七届二中全会;毛泽东;', '根据七届二中全会的决定，为适应党的工作重心转移，迎接新中国的诞生，中共中央办公地点将在全会后由西柏坡迁往古都北平，即北京。西柏坡成为中国共产党领导中国革命的最后一个农村指挥部。  １９４９年３月２３日上午，七届二中全会结束后的第十天，全会新闻公报由', '2006-09-29 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBuL_mmGaq5021LxjsA-WEooQnI5ERyg58oGvdkoUbWeAuilvIbLzj_SdpXZ0PRbi07cEbOS_RwM3KNeweYRrjxbKfNhXQiLoZrg0E0VCbSS9MKn50AXOrDXot6GebG0qMMb8_gXhIJig==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6122, '报纸', '党的七届二中全会(下)', '', '人民日报', '人民日报', '七届二中全会;党的领导人;党的思想建设;', '在新中国诞生的前夕，在党的工作重心面临由农村向城市转变，新民主主义革命即将在全国取得胜利，我们党即将成为执政党的历史性时刻，怎样保证党在新的历史条件下永不变色，顺利地适应工作重心的转变，担负好新的历史重任，是摆在党中央领导集体和全党面前的重大课题。', '2006-09-27 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBPhldYCI9_YoOAI_NeOfO02HCEG_JMia8JRucVUXXp6rzsneB435mOlh36vXtCHFsq7Bf3mzV1Y48u9r0RcM8HZ_0LI3NHldts6H0YU_HxRM5N0Eo14xyLW8Zec5yHphzxFf3k2PDPMw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6123, '报纸', '党的七届二中全会（上）', '', '人民日报', '人民日报', '七届二中全会;共产党;任弼时;刘少奇;', '在中国人民解放战争即将取得全国胜利的前夕，经过充分准备，中国共产党于１９４９年３月５日至１３日在河北省平山县西柏坡中央机关食堂，召开了第七届中央委员会第二次全体会议。出席这次全会的有中央委员３４人，候补中央委员１９人，列席会议的１１人。会议由毛泽东、刘少', '2006-09-23 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDNswZrHnb4pYpTtxNK4rAurDta3HlX2gw3KrLy2bXqRePnSe38hCI7BRVsZ_qZmTucdEjHyrIkF3KEGHl9sMSzHuLRCl9kx_KNPcdtZlotFW5YP3EKqhvqTyLiN1Q3ds14yMJYEantdw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6124, '报纸', '在纪念王稼祥同志诞辰一百周年座谈会上的讲话', '曾庆红', '人民日报', '人民日报', '王稼祥;马克思主义;毛泽东思想;中央红军;座谈会;', '同志们： 今天，我们怀着深切怀念与由衷敬仰之情，纪念王稼祥同志诞辰１００周年，缅怀他为党和人民建立的不朽功勋，学习和弘扬他的革命精神与崇高风范。 王稼祥同志是中国共产党的优秀党员、忠诚的马克思主义者、杰出的无产阶级革命家、我党我军卓越的领', '2006-08-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICN_6006h9TjsyaANMJ19_qgH3ZHpe_8ifs9s9A0KCfoS9nesPwSqBC5w9R-9d0QCAHvrw5ngXHkbJ3DKan4asdezEbB0X14tvXEDg_nPNvcOxCC-vx6xiRDrvDqu4O_V_wZL4MtSHk8Q==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,抗日战争2_screened,中共七大1_screened,遵义会议_screened,苏维埃共和国_screened');
INSERT INTO `ds_article` VALUES (6125, '报纸', '民革北京市委赴西柏坡参观学习', '刘华', '团结报', '团结报', '保定陆军军官学校;', '本报讯　16日，民革北京市委组织20余名中青年党员赴西 柏坡中共中央七届二中全会旧址参观学习，这也是民革北京市 委“庆祝中国共产党成立85周年主题活动”之一。  在西柏坡纪念馆、中共中央和解放军总部旧址，大家认真观看 馆内的陈设，详细了', '2006-06-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICugmB2pdzwtxWWFEVW7kTk1oktLnodMZYiC1opkz3Z0o43Bt6kXEmgpyT9E5SaWtWavCAKIawZzqkffqZJwUSUJ6tECOjcsl0etg8Wdsms7CQTcDSupkNqdQgAt5Jfj5JW3bm8piqJZQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6126, '报纸', '十三大以后党史研究中的一股强劲思潮', '', '学习时报', '学习时报', '社会主义初级阶段论;于光远;新民主主义社会论;', '十三大以后，从社会主义初级阶段的观点来回顾和反思建国以后的历史，成了人们关注的一个热点。  首先提出这个问题的，应该说是一九八七年十三大结束不久在汕头召开的那次党史会议，在我这篇系列文章的“之一”《读林蕴晖〈走出误区〉》中已经谈到，这里就不重复了。 ', '2005-12-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICaa2haE1eVIPOj6EyuSgzPsUHWbyPT7hV_hfTSMaOdn5qkwKFsRu9AIuQhLm11WGXxgdSlur7RS4a-TepIOMSuQFyS4rrKWHRRAfUV0VP_sQnUZJI5qbrS2agSBuxDKLIr0hi0pHkbGQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6127, '报纸', '平山老区奋斗3年换新颜', '王方杰', '人民日报', '人民日报', '平山县;胡锦涛;', '本报石家庄12月7日电　记者王方杰报道：快到年根了，盘点一年的收获，河北省平山县西柏坡村村民闫文翠喜上眉梢。前些年，她家投资80万元开了一个家庭招待所，3年前胡锦涛总书记到她家走访时曾问过几年才能收回投资，当时她心里没底。随着这3年西柏坡经济的繁荣，她家收入稳步', '2005-12-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDnDbt90wcXmPPHv8bmoIw7nFv4AXBSf3JbuYhdhLUTvbcybLYVCAWRsRWqNhfiUNBDbjTaG6bHMNjb907QP6vK0HDzcjv07epjbqYNc3ocZB12iCP5DRHiuC0IjYuIJ8irCstc_ufk4Q==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6128, '报纸', '军徽在老区土地上闪光', '马杰坤', '中国国防报', '中国国防报', '人武部部长;基层民兵;平山县;征兵工作;', '河北省平山县人武部，时刻牢记毛泽东同志在党的七届二中全会上关于“两个务必”的论述，勤勤恳恳干事业，求真务实抓工作，新一届党委班子组建6年来，人武部先后有23项工作受到北京军区、河北省军区表彰。近日，河北省军区党委给该人武部部长张兴祥、政委薛少华分别记三等功一', '2005-09-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDGv1L4Zxd10j8hUM-pmg64kpMKBYe6MMwIaQEw4Yq-29wCaV0EVpD8G_9sBZ4MnaxKpCTQ2Wef6EA57jbNv8DxFTSV27Vn1D9fHYXdPpwpZdiSMKXaQR6g1ZgHLlhfuUKjw1SBRIkVeQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6129, '报纸', '《感受西柏坡》序', '龚育之', '学习时报', '学习时报', '胡乔木;毛泽东;中华人民共和国;米高扬;《感受西柏坡》;党中央;平山县;', '一九九六年十月，我同中央党史研究室的同志们一道，专程到西柏坡参观。本书的作者张志平同志当时是西柏坡纪念馆的馆长。他热情地接待了我们，如数家珍地向我们介绍了党中央在西柏坡的历史和故事。显然，他对这段历史和这些故事非常熟悉，只是限于时间，不能更详细地讲解。现', '2005-08-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICi6dg2z_j04PE6kqGwnw-8-F3gwJSXZTaW8g-eSYOnrzo1-sSq1uDeFMUXaUzv1EuLvpipYJ8FztTz_qertiVYFF4DFTODf-37Teg8w71jDX23JsjMu27-72gzKzA-NWQD5LHQGiWwwQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6130, '报纸', '在陈云生平和思想研讨会开幕式上的讲话', '李长春', '人民日报', '人民日报', '陈云同志;党的执政能力建设;先进性建设;执政党建设;马克思主义理论;建设中国特色社会主义;陈云生;研讨会;', '同志们： 在陈云同志诞辰100周年之际，中央有关部门联合举办陈云生平和思想研讨会，深切缅怀陈云同志的不朽业绩，学习他的光辉思想、崇高品德和革命风范，这对于推动马克思列宁主义、毛泽东思想、邓小平理论和“三个代表”重要思想的学习、宣传和研究，进一步弘扬党', '2005-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICsQE5t1nHZuPK7KpG82mfPG2Bd9coo5fjdn9jpz8ZGoadqoNn6s0FblJEEsMn4GulKiT8enZ7tS9QaXl5ixM42Yhgq66BewTYNFn12iFBQvE1Vi9dtYSOY5i2VZUFS4jCXQpCNbrzxPQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6131, '报纸', '牢记“两个务必”　弘扬优良传统', '', '人民日报', '人民日报', '“两个务必”;优良传统;地位观;', '在保持共产党员先进性教育活动中，广大党员和领导干部回顾党的光辉奋斗历程，重温党的优良传统作风，更深刻地认识到，不论时代发生什么样的变化，我们都必须始终牢记“两个务必”，永葆共产党人的政治本色。 许多老同志深情地说，毛泽东同志在党的七届二中全会上提出，', '2005-05-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAqeb36neimfQisy8RKtkNrzAKQrH8UHYRKm9j9Yf_em_LXV7dVw36skBNcFUO9jIXSh2EzjiNcwdyuhQ9mZ__4W4h6r532FMKJGviHoA2dytlimOvDKCzF1-YM2Sq-fSKyTnpxIn-FAA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6132, '报纸', '缅怀世纪伟人 推进中国工运', '', '工人日报', '工人日报', '全心全意依靠工人阶级;燕山石化;工会工作者;', 'F实事求是、拨乱反正的伟大旗手E 在全国人民隆重纪念世纪伟人邓小平同志百年诞辰的日子里，作为一名工会工作者，我深感小平同志为中国工人运动和工会工作立下了丰功伟绩，在这里，仅谈一点浮浅的感受，以表达自己对小平同志的崇敬和怀念之情。 一、邓小平同志', '2004-08-21 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDwsPjmqG_BjBblMFeGPHK_hW4RjM5uaBxZAcpi5O-StKF_ODZK2L2xVudp89xW5kp6GnWA91_DQ4BFsw7GuDEqxa8l4dk4aOHyXSGu8y0v4mxUva1m53cAp3dhNaQThJSuNX_V4XiLBQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6133, '报纸', '把弘扬艰苦奋斗精神作为自觉追求', '唐国和; 郭建跃', '解放军报', '解放军报', '团以上干部;', '本报讯　唐国和、记者郭建跃报道：在纪念党的七届二中全会召开55周年之际，石家庄警备区党委又一次组织全区28个团级党委的百余名团以上干部，走进革命圣地西柏坡，重温“两个务必”的嘱托，弘扬艰苦奋斗精神，不断强化团以上干部的“赶考”意识。  这个警备区党委充分利', '2004-07-19 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC8gUD7vnCqHmMYX6zOhDBZKB4Cr6qboapUe4Z80v6jiFL3cqJN6iyMlV_cdlQfHui1wfe6OIqPnv2oqHDshFOlzWD5MAVNXdDkQ5c-Rks2BcXy4nDrNIY9imyxOVIa9hJyYAEiBRgYTw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6134, '报纸', '牢记“两个务必”大力加强党的执政能力建设', '孟宪玲', '中国民族报', '中国民族报', '“两个务必”;党的执政能力建设;毛主席;', '本报讯（记者 孟宪玲）“七一” 期间，国家民委主任李德洙带领国家民委司 局级以上领导干部60余人，踏上了革命圣地 西柏坡这块土地。大家通过亲身感受当年毛 主席提出“两个务必”的环境，重温老一辈 无产阶级革命家对于全党同志提', '2004-07-06 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAm9V-RgAvZbB8U2ODttm4RnpStdJUlJ8oLLE1aKYb271lL_xLdA5H5huRNIOcUrmxXgOhTXWblZz8sWtU4JIZucKYAO6CyXbCPAM_9GPPYDFneF9m78eNJaVpjuv437Z3VCmvtobkycQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6135, '报纸', '牢记“两个务必” 实践“三个代表”', '', '中国中医药报', '中国中医药报', '“两个务必”;革命传统教育;“三个代表”;', '为提高广大党员、公务员的政治素质、理论水平和思想认识，加强党性教育，按照局直属机关党委的部署，在庆“七一”前夕，国家中医药管理局科技教育司党支部组织全体党员参观了西柏坡党建教育基地，接受革命传统教育和爱国主义教育。局纪委副书记王先锋同志应邀参加了这次活', '2004-07-01 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAXDw9DYttuk1OvVNi98LWQq8YaJagFWXlV7HqL4yyZcOj3owlCdBTRCds-6QuEnuhUzPPYkeqy56mNAF7uZrfpVuC-sdDSN0ciksSDGX82wTiz3uvG-4pLkAhCV4Fi7zxkmwliREgxjg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6136, '报纸', '革命题材展览的新美学', '郑立华', '中国商报', '中国商报', '美术学院;清华大学;革命题材;“两个务必”;', '牢记“两个务必”西柏坡精神巡回展在北京国家博物馆展出已经接近尾声。这一次观众感觉不同的是，展览没有一点说教的成分，展览的设计效果让观众感到真实而震撼。当人们沉醉在现场的革命历史气氛的时候，我们不得不钦佩给我们带来这种气氛、再现特定历史场景的设计者们。', '2004-06-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICGMy-C3f6uHkKaZPXeYRtzRekHbqEla5iMilkjgbJqWleC-cDxUsGNtLWZ3x4_qo2uRU8GG-NgiDJWsQ7e-n3Ip_0n5N06U9XrUKJkQDUvPDDAejY2Wc_xhNuBXyQ58dDnYTeneI5YgQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6137, '报纸', '让西柏坡精神代代相传', '', '人民日报', '人民日报', '“两个务必”;政治本色;巡回展览;', '《牢记“两个务必”永葆政治本色———西柏坡精神巡回展览》在北京拉开帷幕。这对于在全党深入学习贯彻“三个代表”重要思想，全面推进党的建设新的伟大工程，加强和改进未成年人思想道德建设，具有十分重要的现实意义。 西柏坡是我们党领导中国革命、解放全中国的最后', '2004-06-16 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA08i9pN-hTehQjf-8jJv-fm_HD0XTE1rkcnagxqjY58ndgAkW3Nv3VgC6bSWyAG0mV2WevqBJ4qJLY2sRohcSNBMSTsxTfHFeyAXue4BhD0vo-ndjW2trrzMF72jzNmhRtwFeu2DW5pg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6138, '报纸', '西柏坡人眼中的“西柏坡精神”', '耿建扩; 夏桂廉; 蔺玉堂', '光明日报', '光明日报', '“两个务必”;七届二中全会;何莲芝;岗南水库;', '缘起：55年前，在夺取全国胜利的前夕，具有重大历史意义的党的七届二中全会在西柏坡召开。毛泽东同志高瞻远瞩地告诫全党：“务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风。”从此，以“两个务必”为核心的西柏坡精神，激励着', '2004-06-15 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA3L0-xaW6XqWlykfQ9M7Hz991opecSLHookIj9usU3AMFyVmg-TyouMxjexesamKpbw_BJt3YqfZREDx8il3Mo_UGV-gwDvSVLUlgUQik7l_sMqtX_0m97Lg_hYrwTr_dMBZlyls7z_g==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6139, '报纸', '实施西柏坡红色文化战略 积极开展主旋律创作和各种文化活动', '', '中国文化报', '中国文化报', '红色文化;毛泽东;文化活动;“两个务必”;', '西柏坡——红色文化的源泉革命圣地西柏坡，在千里太行的东麓，石家庄所属的平山县中部。如果从嘉兴南湖到井冈、瑞金，再沿长征路线到遵义、延安，然后东到西柏坡和北京，就会大致形成中国地图上的一个半圆。这便是中国革命的轨迹，而西柏坡是它短暂的一个耀眼亮点。它是一', '2004-03-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBptYIKSaGMC4g8qbLOJuJ_6qznRCvRYXdYbBy7-4Ot5INHO5VXMCSuSCLWdQpFpM4WEvJfTVc8xcvktlebfVtS8ypDt7PLM_Xd1OjbL2Ul210P9Z_75kpJlKbwNlnDCFodPxtgyAlHuQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6143, '报纸', '当好考生 答好考题 让考官满意', '江山; 陈国琦; 郭会涛', '新华每日电讯', '新华每日电讯', '县委书记;平山县;', '1949年3月23日，中共中央离开河北 省平山县西柏坡村迁往北京，毛泽东同志 称之为“进京赶考”。2002年12月5日至6 日，中共中央总书记胡锦涛和中央书记处 同志来到西柏坡学习考察。在重温了毛泽 东同志在党的七届二中全会上关于“两个 务必”的', '2003-12-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDkRHyQZIG9QwvbZWQvG1PuetfAELalffJeUJt3404ZuWNtZl9fFRJ3EMfh83SCy0mQYNZ5ENTNgW6OCD2MreFYIJlT1YJtDsMRRVjcJ-tuwH3y0RLYkDVyRfVHxPC523ZSu1vrCZ4D9w==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6144, '报纸', '把第二课堂建在西柏坡', '杨占苍; 赵艳斌', '中国教育报', '中国教育报', '第二课堂;实践教学;学院党委;', '前不久，在石家庄铁道学院召开思想政治工作研讨会期间，院党委书记马树强带领近百名师生到大家熟悉的柏坡岭，在七届二中全会会址前重温入党誓词，学习胡锦涛同志在西柏坡考察学习时的重要讲话，并分别到村民家中吃派饭，实地接受“两个务必”和“三个代表”重要思想教育。', '2003-06-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAfZz4ythy3kESyrKbR1rHHfVRJdy1kQOh115tRYZKG_XMiXiGYjCU0wLFLxqKGST5IOzQJKh6ZnSKq0PIbWUAJdeuKeKzvxvhVm3r8zuhEEWcyEyJTM7kG2povsCh9K6kiw6KT57-w7g==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6145, '报纸', '中南海与好八连', '黄国柱; 贾永; 李大伟', '新华社;', '人民日报', '江泽民同志;中南海;“两个务必”;', '正是浦江两岸春花如云的时节，上海警备区某部八连迎来了一个值得纪念的日子———1963年4月25日，国防部授予这个连队荣誉称号“南京路上好八连”。 风雨征程40年，好八连这面鲜艳的旗帜，一直飘扬在人们的心中———仅仅在改革开放以来，就10次荣立集体二等功、3次荣立', '2003-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDIQQjZ7HbkIottXFcCmfPUkjWkyiHMH9yl6bFcyuSKp9eBZ0VyyeRIwpD4-TQouecOKe4EFrVTGbUIOOdWomH1e_jXE4cdmi4BtRl8A5Zy4DfTZsrPdbtxMJ1ALVEnbYFK5nXRX1xKqg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6146, '报纸', '高级公务员：要强化“赶考”意识', '赵鹏', '新华社;', '新华每日电讯', '“两个务必”;高级公务员;执政为民;', '春天的西柏坡，生机盎然。国家行政学院第9期司级公务 员进修班学员18日专程来到这里，重温毛泽东同志在党的七届 二中全会上的重要讲话，认真领会胡锦涛总书记倡导的在新时 期坚持“两个务必”的重要意义，增强全面贯彻“三个代表” 重要思想、争做勤政为', '2003-04-22 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDFup7BoKReZ6pKcmHHf-mw9LTsCctjIAV81wo8unylrO6VcNZD8jH-yYDq84KlvPJdch0ZSG92XTjWsPMWpxfYqLGT3KqY8SpUc8wV8udZbi2HiGrj4hzpccF9oyXTRkJSJNkjUt0NcA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened');
INSERT INTO `ds_article` VALUES (6147, '报纸', '在新的“赶考”中交优秀答卷', '景抒展; 李绪成; 廖伟文', '解放军报', '解放军报', '“两个务必”;两个务必;全心全意为人民服务;中国特色军事变革;', '草长莺飞、春意盎然的3月，位于河北平山境内的革命圣地西柏坡，迎来了国防大学50多名将官班学员。  54年前，毛泽东在这里向全党同志提出了“两个务必”要求，并把进驻北平执掌全国政权形象地比喻成“赶考”，使中国革命走进了新的征程；54年后的今天，中国最高军事学府', '2003-04-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICARM_A-ImfL8sIjMgRjGePcw5_-8EyUxHYsmLovSk91h6lcNky3GjRUOFmi-YD1Ws7kYRoYowyJc5vKHD-o6SnMTtUXXFqbiUp7Cc0nd7Y8Hl9HbH4UHbT9i1tWwpFyJHGyvIirMZruQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6148, '报纸', '叶子龙同志遗体告别仪式举行', '', '人民公安报', '人民公安报', '叶子龙;告别仪式;北京市;', '本报讯 中国共产党优秀党员，久经考验的忠诚的共产主义战士，北京市的优秀领导者，曾任毛泽东同志秘书、中共中央办公厅机要室主任，原中共北京市顾问委员会副主任，中共北京市委原常委，北京市原副市长，公安部咨询委员会委员叶子龙同志（享受市长级待遇），因病医治无效，', '2003-03-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIA1PMuslKZJoaQHe1Ag4sjYxDrOanSrpDf_GQ7KwN0pRp83kH8oSv39-spt6LTC3EOs4mQyX5hCwsVEtT5n1ATm8mn7Ak9dwWAPNNXKzl2I0d7Brd23P-9arTnnMU-J5J1KeRAmmU71Hw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6149, '报纸', '围绕大目标 实现大团结 促进大发展', '王华清', '中共石家庄市委统战部;', '人民政协报', '“两个务必”;统战工作;统战干部;全面建设小康社会;统战系统;', '（一）  55年前，中共中央和解放军总部移 驻河北省平山县西柏坡，西柏坡成为毛主 席和党中央进入北平，解放全中国的最后 一个农村指挥所，成为我党领导全国人民 和人民解放军与国民党进行战略大决战、 创建新中国的指挥中心。在这里，中', '2003-03-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDWR6QI_GFZE7-KuUkVqqFRKDNX7Qh4S5eMNH4I_VEMdrTIXRMO6MgmV59qsJQMbeLkKyaeSP2VZABRI7eTMQE4qARKizqhmiYK5qHlBsmceFojTSlMO5YvBW3V0xRXihUOr6H-E2W2sg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6150, '报纸', '将军学员赴西柏坡悟“赶考”', '苏银成; 李国利', '人民日报;新华社;', '新华每日电讯', '“两个务必”;共产党人;两个务必;', '新华社石家庄3月23日电（人民日报记者苏银成  新华社记者李国利）经中央军委批准，国防大学研究 系50名将官班学员，22日来到革命圣地西柏坡，重温 54年前毛泽东同志在七届二中全会上向全党提出的 “两个务必”要求，强化高级干部的“赶考”意识，', '2003-03-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICBC1TWLnSpgTVrbPQ6DpcupCwrYYWNLvuVmrttduMRaSwOOjJvVzllh3XAk641fTpyJfS17PUzQJz8cWQbtkyJ87t3Nw7JmKdRVa_Uh19_wQNlsPBE0xdoqlMctPBIy5_JM_u7u5YVDQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6151, '报纸', '“回到人民中间”', '关明; 王四新; 王金海', '工人日报', '工人日报', '温家宝;全面建设小康社会;煤矿工人;', '姚志平代表仍记得那件事情——— 1月31日，正值农历除夕，国家院副总理温家宝来到辽宁阜新矿业集团艾友矿，下到720米深的矿井，和煤矿工人一起围坐在巷道里的铁轨上，一起吃年夜饺子，共度除夕。他一边吃水饺一边说：“我一直想和煤矿工人一起在井下过一个春节，今天这', '2003-03-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICYADhvQg4nQX0FvZFvhqgquqKACmz4CkUr2W0qZslG8b7BnE0TCY1PiHVez--aMKiVwoHwJm6OUfQx-oi-7bw_sZOP9j9088LC2qmYj-2VgBwJwiIoRpIA5FWVTf2GUB_K12nF_Nw6aA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6152, '报纸', '继续发扬光大雷锋精神 深入实践“三个代表”重要思想', '', '人民日报', '人民日报', '雷锋精神;全心全意为人民服务;“三个代表”重要思想;社会主义初级阶段;', 'F雷锋精神的社会基础E 自从我国把建立社会主义市场经济体制确定为经济体制改革的目标以来，关于雷锋精神，有时会听到这样一种观点：雷锋精神不适合社会主义市场经济，已经过时了。这种观点正确吗？ 社会存在决定社会意识。只有弄清楚雷锋精神的社会基础，才', '2003-03-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB89FU0ZevwoFAlL0G9i0-4UQIJ4Yx1h9jTSVYlsiaH9RskDzX1azmuKsRzXTYHF5v6naaryriAjDMk-b0CdHRJO_slJQdL49PiVRKBxdaKUrS9l3O48x_6p9fFd26IV7aJ9H7wsD8Fmg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6153, '报纸', '坚持两个“务必” 永葆共产党人政治本色', '吴珺; 董宏君', '人民日报', '人民日报', '政治本色;共产党人;“两个务必”;', '本报北京3月3日讯 记者吴珺、董宏君报道：中组部党建研究所、《党建研究》编辑部今天在京召开纪念毛泽东同志在七届二中全会上的讲话发表54周年座谈会。会上，大家重温了毛泽东同志的重要讲话，认真学习了胡锦涛同志在西柏坡学习考察时的讲话精神，就新形势下党员领导干部如何', '2003-03-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICH63N19tsBmu3q-C1hLj279GLKIbigFnlZCMR39IoMqGfhgC_KeillSqfqE1KayqcTL8uKg6JcGvignMEoUIad7EFDu_IgiofmEKytLPGf2PVm_kSO73oieKHXzMWBRiNrFtBV9qA1ow==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6154, '报纸', '时刻不忘“两个务必” 认真抓好反腐倡廉', '杨光宗; 黄雁玲; 路志强; 张楠; 姚冰; 郝征; 孔振斌; 陈晓声; 邹小俊; 王荣生', '中国纪检监察报', '中国纪检监察报', '“两个务必”;纪检监察干部;', '本报讯：全国纪检监察机关广大党员干部， 结合正在开展的牢记“两个务必”教育和反腐 倡廉的工作实际，重温毛泽东、邓小平、江泽 民关于艰苦奋斗、居安思危、保持同人民群众 血肉联系的论述，迅速展开学习、讨论活动。  云南省纪委副书记、监', '2003-02-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDkzWsDahMh7n2ieX9dFibwaDlM_Hz47ZJSpvmGhW27XByxP4JZOh_xgR0mCqwgF-6rj3-YYiPCtaSnZcqkNHhcHywhieiw4bOvUHgXoeWGHMsXKZ-pfBMHc3-fkrxCS3OBU7Kg71Eb4Q==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6155, '报纸', '毛泽东邓小平江泽民关于艰苦奋斗、居安思危、保持同人民群众血肉联系的论述', '', '人民日报', '人民日报', '江泽民;中国特色社会主义事业;毛泽东;', '编者按：为了全面建设小康社会，开创中国特色社会主义事业新局面，全党同志一定要发扬党的优良传统和作风，保持同人民群众的血肉联系，始终艰苦奋斗，居安思危，团结和带领群众不断前进。这是江泽民同志在十六大报告中十分强调的一个重要精神。 去年12月，胡锦涛同志在', '2003-02-13 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAeAyeCB1a0QlTCUM8HcplwsRbqhDbGieToQbxulBXLXRruH2G0E1cqlJbO_7j7gEfCQws7LNxgaN1_PHmQBlrlO75NsRsUarJdAyAM7fk_hmKrE_5Ih_7qr8TycuCuIe_jmyfkBUmcGQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6156, '报纸', '权为民所用', '', '光明日报', '光明日报', '权为民所用;胡锦涛;', '党的十六大闭幕不久，胡锦涛总书记和中央书记处的同志便来到革命圣地西柏坡学习考察，回顾我们党带领人民群众进行伟大革命斗争的历史，重温毛泽东同志在党的七届二中全会上的谆谆教诲。胡锦涛总书记发表重要讲话，要求各级领导干部牢记“两个务必”，做到权为民所用，情为', '2003-02-10 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAvPZYgsiRkDO6a5VSM2TjIv5NAiayYArsuVOKNelpo7ZVggGLQFNzY_ynY2-gzGt3QV1LKppGetmvWnSzxAaT95wSI7H7mafw5qH3xaFFiukugmxt76npCLXmWIBsWZNlsrI1EHO7d0A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6157, '报纸', '领导干部要带头做到“两个务必”', '', '光明日报', '光明日报', '“两个务必”;胡锦涛;全面建设小康社会;', '不久前，中共中央总书记胡锦涛和中央书记处的同志，来到革命圣地河北省平山县西柏坡学习考察，回顾我们党带领人民进行伟大革命斗争的历史，重温毛泽东同志在党的七届二中全会上的重要讲话，重温邓小平同志、江泽民同志关于全党和全国人民要长期艰苦奋斗的一系列重要论述，', '2003-01-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDwEaQ8VuwpAL0shAgjDMu8HWuUBRp-TvyXu7nvUe5sN0rSOMsES29Qx5WOmssEmOTKyVhgXlhXjKCNJNoNzRQfg7vVXiv_MdW-Fi7R5CB9_RoKHcz4e-ApWF70n1wfBcyhSUVoWkeU4A==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6158, '报纸', '在新形势下坚持做到“两个务必”', '', '人民日报', '人民日报', '“两个务必”;十六大精神;新形势下;', '在全党全国认真学习贯彻十六大精神，开始全面建设小康社会，开创中国特色社会主义事业新局面的新形势下，中共中央总书记胡锦涛和中央书记处同志来到革命圣地河北省平山县西柏坡学习考察。胡锦涛同志发表重要讲话，强调全党同志要重温毛泽东同志关于“两个务必”的重要论述', '2003-01-24 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC8GA78g7HsMIw02xuMmm94M0xFRSEZ3G2ue-YSR6fcfGyjrt_ywy685eAfF3iHVYrT-V2bD5xHiR6FIxu2flUZ5HbgKWZ__pgx-Q7B6VFTa-Y4wCzlmk-gxZnYTfoCxtORDDFSo-2JXg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6159, '报纸', '坚持发扬艰苦奋斗的优良作风 努力实现全面建设小康社会的宏伟目标', '胡锦涛', '人民日报', '人民日报', '优良作风;奋斗目标;毛泽东;党中央;“两个务必”;全面建设小康社会;七届二中全会;', '这次，我和中央书记处的几位同志一起到西柏坡来，主要目的是回顾我们党带领人民进行伟大革命斗争的历史，重温毛泽东同志在党的七届二中全会上的重要讲话，牢记毛泽东同志当年倡导的“两个务必”，首先从自身做起，并号召全党同志特别是领导干部，大力发扬艰苦奋斗的作风，', '2003-01-03 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIDO20SrqDtfVkKDWl7WyUQU5fYfn4KN8AkZmDtZ0QzSdL8PvstLa3nrL1BieFYkA4VOniFQ93PUV9jFBOpaj0Cj_8ojpnQ7RRRU747NgiG46DfCgjNkabKbMfQ1dfz2la12Z1iONdA1JA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6160, '报纸', '胡锦涛和中央书记处同志到西柏坡学习考察', '刘思扬', '人民日报', '人民日报', '胡锦涛;曾庆红;中共中央;毛泽东;中央书记处;学习考察;', '新华社西柏坡12月7日电（记者刘思扬）　在全党上下认真学习贯彻十六大精神的热潮中，中共中央总书记胡锦涛和曾庆红等中央书记处的同志来到革命圣地河北省平山县西柏坡学习考察，回顾党带领人民进行伟大革命斗争的光辉历史，重温毛泽东同志在党的七届二中全会上的重要讲话，', '2002-12-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBohB3c-VCUwiYgKQjq8wPzs_G-xfPDEUuinqC0JYIceGzfmzJc7QlUb02amzzQ4K9mUhX-nanVJ-LKH1N2egrXNLa_erA_exPFKuzbqCCthSh8aKhS49oX0Noa8hiB9jtyB5orGK6IJA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6161, '报纸', '邮票上党的重要会议', '', '解放军报', '解放军报', '共产党;全国代表大会;发行量;中国共产党成立;', '新中国成立后，我国相继发行了一系列纪念中国共产党走过的辉煌历程的党史邮票，中国共产党的历次全国代表会议，更是重要的选题之一。  1921年7月23日，中国共产党第一次全国代表大会在上海法租界望志路106号举行。因当时会场受到暗探注意和外国巡捕搜查，最后一天的会', '2002-10-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICKOM6tOb6bMfA0kIQpOn5zYLL7hUxmZhdteLiwKkTn1EDtWlQqBG2yybbzoCz1JtSDGoNQGMJBm2_iOdPx4_uLY19kEfx1wHkRrxK6_gqaRO03EgLEtPUIqbgYlMkGXfFyU1_CItc7Aw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened,枣园_screened,中共七大1_screened');
INSERT INTO `ds_article` VALUES (6162, '报纸', '我党历史上的几次重要会议', '', '解放军报', '解放军报', '王稼祥;工作重点转移;', '古田会议 即1929年12月28日至30日在福建上杭古田举行的红军第四军第九次代表大会。会议由陈毅主持并传达了中央《九月来信》，毛泽东作政治报告，朱德作军事报告。会议改选了前委，毛泽东任书记。会议通过毛泽东起草的《中国共产党红军第四军第九次代表大会决议案》，决', '2002-10-09 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICEU5JyLcWdyQT0F085faUkiAG9l_KRRqenQIdrwoCJJihAaqiCTSd9w8C7DpmFaRhRkHDrJSHR7LHeR0ZT8dfYOpdDiW7jIcEoai7SFqTZ1WZIMYi-ZhVo4lLTbQffK6crVwQTq3JeEA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (6163, '报纸', '西柏坡：搞好基础建设 改善参观环境', '胡春婷', '中国旅游报', '中国旅游报', '七届二中全会;', '本报讯(胡春婷)革命圣地西柏坡充分发挥教育和旅游的双重功能，利用当地丰富的人文资源和自然资源，挖掘“红色旅游”的内涵，积极打造平山旅游的特色品牌。  西柏坡位于河北省平山县。20世纪40年代末，毛泽东、周恩来、刘少奇、朱德等老一辈革命家在这里指挥了震惊中外的', '2002-08-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIC_ccOQSF5brcZH2YxIfHZt39vuTlMRwsZKnx3YoceOiipweqvGZ9FPh6Ye0Bvxm7SdnqRxZhyS5sTT3KuFpcKTK-fUhCULbJaQb603In1tiurBjrKpofuUeCMTFpm_jv2t7loaCuHbyg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6164, '报纸', '程默 用镜头聚焦历史', '张晓华', '中国民族报', '中国民族报', '摄影师;', 'T聚声光影画于咫尺 重现无数活剧  集喜怒衰乐至一幕 牵来多少追忆E  5月23日，在中国现代文学馆多功能厅，中国文联老干部 200余人欢聚一堂，用演出、画展、回忆等形式纪念毛泽东同志 《在延安文艺座', '2002-06-04 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iID3hEJWWIJ4M84bA7Dyb8ao_oUNgs8gaCafbSWzEnWIT_UxDzUShHg81WemFt5Jk4PJvNzcBEnIZFGKPnkOvz_26PWSYW4vlCSFZmfkPBs3h3UU2zCoWr91dK9wCumAJ0suSAQi5pWoEQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6165, '报纸', '增强忧患意识 加强和改进作风建设', '', '中国纪检监察报', '中国纪检监察报', '党的作风建设;加强和改进;', '执政党的党风，关系党的形象，关 系人心向背，关系党和国家的生死存 亡。《决定》指出：“历史和现实一再告诉 我们，执政党不注重作风建设，听任不 正之风侵蚀党的肌体，就会损害党群关 系和干群关系，甚至失去民心，丧失政 权。”全党同志要', '2001-11-14 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBat0I7Ky0Ib3mbP4KdM_8u60QBiP6dKqGPEcbU3UXHVIdWVndGOizhbRGXKYI6xHdWYVHM4LSO6e3nt7LCB0yF5x2Vh3L5ZCUXktRf370br7jQ-kgo3Hxw2f6Hw-Bp8my6A27SK5GXIg==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,抗日战争5_screened,中共七大-2_screened');
INSERT INTO `ds_article` VALUES (6166, '报纸', '落实六中全会精神加强作风建设 全党全国上下紧密团结真抓实干', '', '新华每日电讯', '新华每日电讯', '六中全会;江泽民;真抓实干;“两个务必”;', '新华社石家庄11月7日电：中共中央 总书记、国家主席、中央军委主席江泽民 近日在河北考察工作时强调，全党同志 在日益复杂的国内外环境中要始终保持 清醒的头脑，居安思危，增强忧患意识， 扎扎实实地为党和人民工作。各级领导 干部都要深怀爱', '2001-11-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICLMuvjKR2I1BVB4pKFuqPG6_Mv9mz_OFA0H2g6_iW3Na3ui7yVWhN_1Moummw_5ZJHe5oo65qfDow0bmZMX16jnUYtEbcfWpngT16z996_wuOJQbtHXs840hpumncZOWy8JfdGt-y4Og==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6167, '报纸', '第八届精神文明建设“五个一工程”理论、文献电视专题片入选作品简介', '', '光明日报', '光明日报', '电视专题片;毛泽东思想;马列主义;作品简介;“五个一工程”;', '1、《光荣行》  中共党史研究室、中共深圳市委和中共南京市委联合制作的 庆祝中国共产党成立80周年电视专题片《光荣行》，突破了以往按 编年体表现党的历史的手法，以《旗帜飘扬》、《为了人民》、《人民领 袖》、《凝聚力量》', '2001-10-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBNogilDagZ-o0Wc8Xot4-Cy4x_UE6YsAu02IKmuc4vEVY62KQx1oAO9gLFfD4j7QK1Fj_KszE06Ffhrb4wwE6Gm8Xzyjbk6PTiwWPJBz-J8CHFTV2gvz45Exe8rBHd-hUreyrby_nNoQ==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6168, '报纸', '从历史经验看思想建党的重要性', '刘冬冬', '人民日报', '人民日报', '思想建党;优良传统;工人阶级政党;江泽民同志;“七一”重要讲话;邓小平理论;马克思主义理论教育;思想上建党;毛泽东建党思想;党员比例;工人阶级先锋队;历史经验;', '江泽民同志在“七一”重要讲话中指出：“我们党高度重视在思想上建党，坚持用马克思主义理论教育和武装全体党员，不仅要求党员在组织上入党，而且要求党员首先在思想上入党，指导他们为实现党的纲领和任务而奋斗，因而保持了党的工人阶级先锋队性质。”最近他又在军队高级干', '2001-09-18 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2001.006757', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6169, '报纸', '凝聚在党的旗帜下', '王文杰; 张占辉; 祝寿清; 毕永军', '解放军报', '解放军报', '江泽民同志;军队党的建设;党对军队的绝对领导;人民军队;中央军委;', '1989年 11月，德高望重 的邓小平同志在离开军委领导 岗位时，郑重地对全党、全军 作出政治交代：“我确信，我 们的军队能够始终不渝地坚持 自己的性质。这个性质是，党 的军队，人民的军队，社会主', '2001-07-31 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICMrWiS6JflrLshYTlJfKanZav5ORgCAAq7w_KRm0u5LGZuPEudQWmdczvb9ydBDcZNvvp8r-nskdbDO-DCKsei8mOjURnHyMpXuUxhMI8NyGOyYW45kFi79oBtQdVxGhcr3RBwQ12vZA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened,遵义会议_screened');
INSERT INTO `ds_article` VALUES (6170, '报纸', '国家局党组中心组重温领袖教诲', '李玲', '中国旅游报', '中国旅游报', '中心组;', '本报讯 （记者李玲）墙 上悬挂着的一面 鲜红的党旗，为 国家旅游局一间 普通的会议室平 添了几分庄严的 气氛，6月29日 上午，在这间会 议室里，国家旅 游局党组中心学', '2001-07-02 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIB2tLn0nv8uxhA1BXYMjC1aMtfQBdc760_uXxMFg6TNgc8NhjqssWisBHfJCupD1qS9iRb44HftR7WHop-cDohCndgyH_zuF8UMNReJwtRWc8eKo-QJ44jpsIcp8ndiBFhe9ijhr0uJ6Q==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6171, '报纸', '铭记西柏坡的告诫', '王旭东; 蔺玉堂', '中共河北省委;', '光明日报', '王旭东;马克思主义;', '记者：毛泽东同志在党的七届二中全会上 告诫我们，一些共产党人经不起人们用糖衣裹着的 炮弹的袭击，他们在糖弹面前要打败仗。您对这一 伟大历史预言怎样认识，它对我们党今天进行的反 腐败斗争有何现实意义？  王旭', '2001-06-28 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICDe5s4-_3O9di9Jgi1ffKZAWagPd0lqy1rS4dV2eED4OHephDpkTnFdbkKWktpIDxSQDx2jjL_RrvD8u2gXm3KubQPeWxeu2RKSsENtrd9FhcbbJHHUwtyOQRJLt7toClLo7YuEHVbkw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6172, '报纸', '指导工会工作的强大思想武器', '尉健行', '工人日报', '工人日报', '江泽民同志;维护职工合法权益;维护职能;重要讲话精神;全心全意依靠工人阶级;困难职工群体;思想武器;', '同志们：  在中国共产党成立80周年 的前夕，我们召开这次主席团 （扩大）会议，主要任务是，以邓 小平理论和党的基本路线为指 导，按照“三个代表”的要求，深 入学习贯彻', '2001-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBQGduAbofFopso8gkzSa-zzLgaZjP2ytPbFQRytqAD_qn-9erBJrm5PuG0XR3i7pl7pTiHNo-ZTu2Q76egyPOYI-AI7pbenWJfyf77L_47GpRpLq0Wsu_qafUKup2UdY5ESlfDgmrV5g==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6173, '报纸', '荡涤腐恶扬清风', '袁正兵', '检察日报', '检察日报', '反腐败斗争;共产党;反腐倡廉工作;反对腐败;', '腐败，是一个历史问题，也是一个世界性的社会问题。中纪委研究 室纪检监察专员李雪勤说，中国共产党的性质和宗旨，决定了她从一成 立就以反腐倡廉为己任。中国共产党80年的历史，从一个方面讲，也是 一部中国共产党领导中国人', '2001-06-25 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBh2t-UNfeERT1-ecQAyRUKPK3CrIs__C9_vv2nIeLZicU1FbNfmbOuVNZAK_7sBP5vN9ehjmsTh1AQ25TohTtSzLqvf7oAlTpqg2SygfdJ9WL4JwcSwACeOwS143mRbISV6B1AsHKoNA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6174, '报纸', '新中国从这里走来', '罗开富', '经济日报', '经济日报', '华北人民政府;毛泽东思想;政权建设;七届二中全会;党中央;', '沿着党中央转战南北的 路线，我们告别延安。于6月 9日来到了西柏坡，开始了 对又一个革命圣地的激动、兴 奋的采访。  西柏坡的地理位置在太 行山的东麓，东距石家庄90 多公里。  西柏坡在中国共产党80 年历史中的位', '2001-06-18 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iICRtoe8MsotC0NF7kRNByyKc7GhGZ3PUfVY942wF0bbRMOBqodZaO7zu6RXDws-qCqq8uRw4QGqbsePo8wQ-kCWIDbW5EcWJkMdXSgxTVWy1WJUHJSGkzRbGT01gKpSa7Mg29naXDwiow==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,七届二中全会_screened,两个务必_screened,两个务必_screened,西柏坡_screened,西柏坡_screened,抗日战争_screened,中共七大1_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (6175, '报纸', '牢记西柏坡的告诫', '谢茂; 钱晓虎', '解放军报', '解放军报', '“两个务必”;岗南水库;', '西柏坡，在中国共产党发展史上的地位，是不言而喻的。在这里，毛 泽东和他的战友们指挥了震惊中外的辽沈、淮海、平津三大战役；在这里， 中国共产党七届二中全会上“两个务必”的声音，像洪钟大吕，至今还在我 们心头回荡。  我们前往西柏坡采访是5', '2001-06-17 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBLiGj0YkSUw1Yn4qm50SkK0IxoEv5Q5sAouwft7NfO0wXFbrrHJHp1uUnOEi_01eDwEbjwGtWHlRhgTnp8ZmnM6KB8YUhMrDQ3CXRy8tkJ2owVUkolW6wJiToPql63OrFYp_vpVas9iw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6176, '报纸', '让延安精神永放光芒', '尹鸿祝; 李斌', '新华每日电讯', '新华每日电讯', '延安精神;马文瑞;', '1945年4月23日，中国共产党第 七次全国代表大会开幕。出席大会的 547名正式代表和208名候补代表，肩 负着全国121万党员的重托，走进位 于延安杨家岭的中央大礼堂。  时隔56年，作为当年代', '2001-06-12 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBwH6erImWpifO5zFvge80G4cxk385XjSW2C6Qurmc9g5V9W11B2aM4jGEHaRcZvVdfIa44sjvmT2sNJs6JcQ7_3VR4XEOsDa3_nCKDqg_YYSr1hfJuzz9mnlNe011nUIkb8Hp8xOHhiA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (6177, '报纸', '永远的精神财富', '于绍良; 徐金鹏; 吴锦瑜', '新华社;', '新华每日电讯', '延安革命纪念馆;井冈山;精神财富;李自成;毛主席;共产党人;中国共产党;', '建党80周年前夕，从上海兴业路 76号中共一大会址、浙江南湖红船， 到巍巍井冈山、红都瑞金，从贵州遵 义，到革命圣地延安、平山县西柏坡…… 中国共产党历史上一个个革命圣地再 次成为中外人士', '2001-06-08 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIBBg4ZYCXNcQ5P_oCpw6ie2zjsxqYoxwLl6fqxWQkfdhM_StAEomagQ8HruxOgbsq9-KcCdQOStY1FPS71bO5Pu3cmVGgfmysD0z0ebzGblhk1OP7ZCbSZaIvVaaK7LxHaY1C-XKt_hVw==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened,两个务必_screened,西柏坡_screened,农村包围城市、武装夺取政权_screened');
INSERT INTO `ds_article` VALUES (6178, '报纸', '跨过鸭绿江的文化人', '', '解放军报', '解放军报', '常香玉;香玉剧社;志愿军;抗美援朝战争;刘德源;文化人;鸭绿江;', '傅庚辰 歌唱最可爱的人  抗美援朝战争是中国被 迫进行的一场援助朝鲜，保 卫祖国的反击战。在这场战 争中，我们的志愿军战士身 上那种爱国主义、国际主 义、革命英雄主义的伟大精 神，散发出灿', '2000-10-20 08:00:00', 'https://kns.cnki.net/kcms2/article/abstract?v=bnuN6dG7iIAiPLFo8cQ6FGNT6reKPcwfcwX2ixW75NI8ZJat7-nEMp-Y03eRs3LzrpMeDBz2gnUiWG7hhQj2QenwuT4qOq1IebWE2MHgzhvlCM9e2u-YPhDfifTYEFmFX0wt4ABuOZ6r9mDIyRnGSA==&uniplatform=NZKPT&language=CHS', '七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6362, '报纸', '军事文创为国防教育赋能', '张培瑶', '解放军报', '解放军报', '国防教育;文化创意产品;', '“英雄的215号坦克、歼-20战斗机、中国海军055型导弹驱逐舰……每种模型都很精美，拼装模型既锻炼动手能力，又能培养爱国主义情怀。”1月15日，来自辽宁沈阳的陈先生在中国人民革命军事博物馆参观时，被文创商店的武器装备立体纸质模型所吸引。他一次性“集齐”7套不同版本的', '2022-01-19 08:00:00', 'https://link.cnki.net/doi/10.28409/n.cnki.njfjb.2022.000358', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6363, '报纸', '觉醒的中国爱不完', '程新兵', '福建省厦门市湖里区发改局;', '人民法院报', '觉醒的中国;追求真理;', '“沉睡数千年，一醒惊天下。”看完《觉醒年代》后，我仿佛回到了那个激情似火、热血沸腾的年代。彼时，中国还是一头沉睡的狮子。那时的中国没有坚船利炮，没有发达的商业工业，更没有先进的科学与思想。因为整个中国都还在沉睡，还未全民觉醒，还在承受着任人宰割的痛苦。', '2021-11-05 08:00:00', 'https://link.cnki.net/doi/10.28650/n.cnki.nrmfy.2021.004959', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6364, '报纸', '中国共产党人的挚友宋聿修', '宋泳; 李军涛', '团结报', '团结报', '共产党人;冯玉祥;张锋伯;', '宋聿修（1906年-1992年），原名宋秀德，字聿修，后以字行，河北省枣强县人。1925年7月，在察哈尔沽源县小学任教员的宋聿修投笔从戎，考入了冯玉祥将军在张家口开办的西北陆军干部学校，成为一名军人。这个学校的学生中，有一些是共产党员，他们在学校中团结同学，进行革命宣', '2021-11-04 08:00:00', 'https://link.cnki.net/doi/10.28784/n.cnki.ntjbz.2021.002101', '吉鸿昌2,抗日战争1_screened');
INSERT INTO `ds_article` VALUES (6365, '报纸', '丰碑永驻 薪火长传', '钟超; 刘华东; 周洪双', '光明日报', '光明日报', '反法西斯战争;血战到底;英雄气概;东北抗联;滇缅公路;日本帝国主义;卢沟桥事变;抗战到底;中华民族;抗日战争;佟麟阁;全民族抗战;', '七月，卢沟桥畔、宛平城内，中国人民抗日战争纪念馆里，一场“中流砥柱——中国共产党抗战文物专题展”，吸引了络绎不绝的游客前来参观。500余件套精选的历史文物，80余幅珍贵的历史图片，将人们的思绪带回那段热血沸腾的峥嵘岁月。 为庆祝中国共产党成立100周年暨纪念全', '2021-08-05 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.004013', '吉鸿昌2,狼牙山_screened,抗日战争1_screened,九一八事变_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (6366, '报纸', '天津：在革命文物中回望红色历史', '陈建强; 刘茜', '光明日报', '光明日报', '革命文物;红色记忆;红色精神;红色文物;觉悟社;讲解员;', '“这张是‘十五烈士’殉难照片，15位热血青年，虽镣铐加身，却毫无惧色，浩然之气充满天地间。”在天津博物馆“红色记忆——天津革命文物展”上，担当小小讲解员的天津南开区模范小学四年级学生古忻怡绘声绘色地讲解：“这位是江震寰烈士，这是他生前使用过的床单、围巾等物', '2021-06-29 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2021.003305', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6367, '报纸', '革命理想高于天', '', '人民日报', '人民日报', '革命理想;理想信念;共产党人;习近平总书记;历史画卷;奋斗精神;', '正是因为有坚如磐石的理想信念，一代代共产党人勇往奋进以赴之、断头流血以从之、瘅精瘁力以成之，绘就一幅幅激越沉雄的历史画卷，树起一座座不朽的历史丰碑 面对艰巨繁重的任务，面对前所未有的挑战，我们依然需要发扬老一辈革命家“宜将剩勇追穷寇，不可沽名学霸王”的', '2021-05-26 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2021.005427', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6368, '报纸', '崇德向善 见贤思齐', '丁艳', '光明日报', '光明日报', '崇德向善;先进典型宣传;好人现象;公民道德建设;社会主义核心价值观;河南省;模范人物;红旗渠精神;凡人善举;核心价值观建设;', '编者按：由光明日报社与中共河南省委宣传部、河南省文明办、中共南阳市委共同举办的“第六届河南公民道德论坛”近日在河南南阳举行。围绕“崇德向善 见贤思齐”的主题，与会代表深入学习了第十二届中国公民道德论坛精神，总结交流了河南各地、各单位在公民道德建设方面的经验', '2016-10-31 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRqwt51Tl9davOc5n8k7mBucWtFdx-S_yyrndNw7Q3vFGTEB4TBA1RdWDdT4XurrPycslH62FxYDrC-0XrZwmQNLyqf_3eKlVEIr3TsGVteyzU_NJQOD8gNaUbg_FgDnCgPJtPccYdoWKlJ_i39oeeijIuceJwJFHgEg_MVJcnYXfPlnMxflA6xO&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6369, '报纸', '登高一呼,唤起民族自强不息的磅礴力量', '周奔 ; 毛俊 ; 刘建伟', '解放军报', '解放军报', '国民党军队;日本侵略者;共产党人;抗日战争;中国共产党领导;汪德熙;抗日民族统一战线;阳明堡;日本帝国主义;中华民族;八路军;敌后战场;正面战场;军队装备;', '写在前面　　历史进程的答案，总有许许多多的细节可以见证。　　“愿拼热血卫吾华”，这是左权牺牲后朱德含泪题写的悼诗。1942年5月25日，八路军副参谋长左权在太行山十字岭突围时壮烈殉国。公祭那天，“为左权将军报仇”的呼声响彻云霄，当场就有500多名青年报名参加八', '2015-07-27 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRqdsk2oST4Oa5w7BkrpAj5boonz_kOoabBqopQuuXkOmrvjYwVRAJVcWlCLjrXk-wyupyVLN8qxj44YI_k7_47ykYD8Zb19InL2HOrRjdN5lhIAfAJ5ukrESt7pNdCHN7-t3oCCklb2IgQHU_-Pw95LtjVPJ0_-k3vRYl46iRdqKoGn82Zt765u&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2,抗日战争1_screened,九一八事变_screened');
INSERT INTO `ds_article` VALUES (6370, '报纸', '抗日英雄谱', '', '解放军报', '解放军报', '吉鸿昌;孙永勤;抗日救国军;局部抗战;淞沪抗战;抗日救亡运动;长城抗战;义勇军;日本帝国主义;吴淞要塞;抗日英雄;', '七律·长城抗战 丁增义 残阳泣血照燕山，铁骑扬尘剑刃弯。 强虏横行家国痛，烽烟高举故园殷。 胡笳呜咽悲忠勇，鼙鼓铿锵逐悍顽。 饮马长城刀客在，岂容倭寇犯三关。 长城壮歌 若把建筑比作凝固的音乐，那么，旋律通常是由历史所谱写。据', '2015-05-22 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRptyBMgFvvgrnGP76LdJswA46wLmd3ysdBKvtXvPa-7HJI8WmN9XhDnOsyEkQ60CfLt2BCnspZJRoV1DTDs7fnZ1fsmDGBF4PdhBVncqG3Deen75B917bXhD_xg52B2butMn5HymFPdQHwDwsYNIVbvZ28BxLNGeSUXHr20pwFxKVoydjB3wbc-&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2,狼牙山_screened,抗日战争1_screened,抗日战争1_screened,九一八事变_screened,九一八事变_screened,百团大战_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (6371, '报纸', '雷锋精神，跨越时代的价值追求', '高晓杰; 杨春雨; 徐文耀', '解放军报', '解放军报', '雷锋精神;疗养院;社会主义核心价值观;编外雷锋团;价值追求;', '●习近平总书记最近在中共中央政治局集体学习时强调，把培育和弘扬社会主义核心价值观作为凝魂聚气、强基固本的基础工程，不断夯实中国特色社会主义的思想道德基础。 大力弘扬雷锋精神，是培育和践行社会主义核心价值观、激励和引导广大人民群众为实现中国梦而奋斗的现', '2014-03-08 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRq-j9gggdmUnXSfHbp9YE4N2pv27KL-MVICklUnXpE2C2ekjAMlK0tahvB0gXYfZi20IC7Lneoetv7X2ZqvTRLSalvr39MF2kHTDV3bHXUMRFTA8c2c6ZH00pzu-l5A1FPJLR67UvOkQ8dHVFbsyEaojBwm9nLaRBhBUFSxqI3hWrJo2AMOJXI7&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6372, '报纸', '提升软实力 共圆中国梦', '', '光明日报', '光明日报', '马克思主义学院;学院院长;社会主义核心价值体系;中华民族伟大复兴;中国文化软实力;实现中国梦;', '编者按 2013年6月22日，中国文化软实力研究中心、人民日报理论部、光明日报理论部、中国社会科学报、中国社会科学网在北京联合举办了“第四届中国文化软实力研究高层论坛暨《中国文化软实力发展报告2012》新闻发布会”。本届论坛主题是“软实力与中国梦”。来自中央文献', '2013-07-11 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRqtRIiGqmEstEXylZTGuiqZY2-_wC6WDr1Dhb_Yk74kIouhuOA04J5rFqqoKoYQtm6_py-st9Hv8dzumopw-d5FGSjgedMROQYK6vg18yBygKcdByaf1QvnzmfbSfpzxueUI3Ug7bq-dqXbAYmMAl24ycdr828aDJnzterfDrPME_QPXhG_ATlg&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6373, '报纸', '金鸡百花：需要观众多一点耐心', '钱力', '中国文化报', '中国文化报', '电影节;祝希娟;康健民;中国电影文学学会;', '第21届金鸡百花电影节日前在浙江绍兴落下帷幕，与此同时，第31届大众电影百花奖也尘埃落定。与近几年类似，仍然遭遇了观众与不少业内人士的众多非议。组织混乱、票价昂贵、小片扎堆、明星缺席……在一片质疑声中，今年的金鸡百花电影节是否有可圈可点之处？金鸡百花电影节发', '2012-10-11 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRqtRIiGqmEstEXylZTGuiqZY2-_wC6WDr1y7ddC2N5N0OIY5VppjgfTfVSkhEBp2PQcjcVHzKwXtj1mVYU_AVFMwF83MdI9DRC9ZABMUIMIkn9lnRlHBbkJMPlfdkieetgoYJKSR4GjWmhLIyOVphghH06YsvpbJ245wkfVBrNY5aPAu3vY_KsW&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6374, '报纸', '家国情怀,中美相通', '叶小文', '中华文化学院;', '人民日报海外版', '家国情怀;', '如果近期到中国作个民意调查，对美国表示好感的肯定不多，其原因众所周知，且问题主要出在美国而不在中国。但这两天，亲友却纷纷对我说，你看了美国总统夫人的竞选演讲吗？讲得不错呢！　　　　中国人向来对美国如何竞选总统没什么兴趣，那是人家自己的事情；对参选人为争', '2012-09-08 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRoGX4igW8oQBw8zJv4slH63UpCm4brn0XI4dtuKRwuPTu1i_HoYn88hqDGbOroW917n3knsjN91ETYXbD11sGWdPswRmmrVp5HQQCjslFzu2MUIVv6M0aTuuxlUMPLjTS07N_ikPremXSFhuW31rrj8G8hJT7BMc6dP5ufv4FXSOj7X8SIM3tQs&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6375, '报纸', '大战略下的新探索', '陶克 ; 杨祖荣 ; 翟耀 ; 傅开强', '解放军报', '解放军报', '省军区;军民融合式发展;随军家属;', '引 言　　必须站在国家安全和发展战略全局的高度，统筹经济建设和国防建设，在全面建设小康社会进程中实现富国和强军的统一……走出一条中国特色军民融合式发展路子。　　——摘自胡锦涛在中国共产党第十七次全国代表大会上的报告　　风卷大河涌，融合中原兴。　　今', '2011-11-07 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRrR6V_6TwpgGxD1a9SQ8Opg_RdllF50xnLWX_SeI_XCmeFw5q3v9PizvpaeKbRVvCtDlPgmznifz-wHG2RH1sBFWwwTZvNRUIcXyW1yQcfE5eM1Z5qw-HPkaFMcok55lp8hskUrpo1HlA25R74jcCgITi1OUKUQvbjEjCaBLanGwAAmtsONy6Ct&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6376, '报纸', '清华理念:百年传奇生生不息', '', '中国教育报', '中国教育报', '大学理念;清华大学;强迫运动;梅贻琦;周诒春;学术独立;国学研究院;办学实践;钱伟长;张申府;曹云祥;世界一流大学;罗家伦;朱自清;王文显;', '百年来，清华大学广泛吸取国外的先进教育思想和经验，弘扬清华和中国教育的传统。凝聚和形成了清华的大学理念和传统。从办学实践和成就来看，清华的理念是切当的取得了很好的成效。 亦正如此，清华的理念真正融入和浸透了清华人的精神血液，即使近现代中国动荡的政治', '2011-04-18 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRoaDc_5Nd9320p_9QAGzgzU-7hnVjUxLavfHaYKWSZdn5c06_raZ6sI9-1PgqFBPsbySoBamFch5GOZ0tNaRpLitTutb3-_XGu7h9WbEjqE_2KcWUGn4qPvpv8EXXKNMwGXPchwJAxF5IeqlJpsZd_vDSXEiUjtCV4ERfpTZkuppzKX5__oociD&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6377, '报纸', '著名爱国抗日将领 吉鸿昌', '', '人民日报', '人民日报', '吉鸿昌;冯玉祥;察哈尔;', '新华社北京３月３日电 “恨不抗日死，留作今日羞。国破尚如此，我何惜此头！”这是共产党员、著名爱国抗日将领吉鸿昌临刑前写下的一首气吞山河的就义诗。　　　　吉鸿昌，河南省扶沟县人，1895年生。1913年入冯玉祥部。因骁勇善战，屡立战功，从士兵递升至军长。他为人正', '2011-03-04 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRoaDc_5Nd9320p_9QAGzgzU-7hnVjUxLauDsKzcv0gFpHQHsYN05og3cv-v9yaNJPWl6e2u3YM5vDwEAyei178zdqZDM3iCOzHI0P8dxLB2zx60rdyNoZSrXDN-TUnY4XAKCjRXwGFWj58ldigwSx-QpyRIlCFpCiFQir1TSYtJu1VLYGaEEcsu&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2,九一八事变_screened');
INSERT INTO `ds_article` VALUES (6378, '报纸', '影视编剧:一边被忘记,一边是暴利', '李坤晟', '新华每日电讯', '新华每日电讯', '影视编剧;编剧协会;', '在王樵眼中,国内的电视剧编剧分为四等。第一等是海岩、六六、兰晓龙、王宛平这样知名编剧,价码至少10万元1集　　　　一般编剧打官司,要做好3、5年没有活干的准备　　2010年10月16日,当中影集团、八一电影制片厂和华谊兄弟等电影界大佬兴高采烈瓜分本届百花奖的同时,星光', '2010-10-29 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRpAxnRHS2RvT4evBmq6MhzHkx1vf-WlkDnZ9V2QrWl1lRQB7XK0l7hctlg-25UMJfUeTj2ap5_WMBpVbinpeDxkoEmv74MQsxLDBw3wz8NEwsFRNtvCDhTZvwZKpzuCPpDISma8yxFr7JXGnEgh4a2Vgq4Zzfwwy4X4cVutJFSo6w==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6379, '报纸', '民族精神价值的当代整合与传播', '', '中国文化报', '中国文化报', '河南省;唱腔音乐;《道德经》;', '编者按：　　 河南省越调剧团新编历史剧《老子》运用戏剧艺术的手法，把老子形象搬上舞台，塑造了清明高洁的圣哲老子，在第九届中国艺术节上摘得文华大奖。　　 为了精益求精，使《老子》成为舞台上优秀的保留剧目，近日，河南省周口市委、市政府召开了越调《老子', '2010-09-20 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRpuWb1PJqMYje3dm-Of-lRBQ4ew8Harj3mBfXrZXaMhq-27UDFvjsjvJkN-VSl1CDCvVN4_FeCmHza_BNEQfL5RyDohh0nZA70s-jLkmKxFxg2PWJ5X0hSJGdAcTrsxmh5fZqAkeK-y8qQJ82e1QY_Rd1Qpc62OuHNJnV4m2A2fQg==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6380, '报纸', '共和国精神之巅的群像', '贾宇', '光明日报', '光明日报', '毛泽民;共和国;吉鸿昌;彭雪枫;编撰者;新中国成立;', '这是英雄群像,历经岁月淘漉而依然立于精神之巅。 　　　　这是历史长廊,连接着英雄和人民,情牵着媒体和受众。 　　　　作为向新中国成立60周年的献礼,在“100位为新中国成立作出突出贡献的英雄模范人物、100位新中国成立以来感动中国人物”评选的基础上,从2009年7月2日起', '2010-02-01 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRrb-NSzHQduSrzWtDr0pkzyY64PwQnnY2FIGl6Tvk1j9ShX5MkYznUqToZAbpGlY5veyHBV240innmWF7W9sRER98yNxosTrkve9-w7Q3zkuay2ODsMwtslljgqqrqQqmr46YA0kh2TN_wAXbEVrGPeuIXIQACR7LMptePpUMWQew==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6381, '报纸', '弘扬爱国主义精神 推进公民道德建设', '徐光春; 黄晴宜; 徐惟诚; 李卫红; 冯建中; 陆昊 ; 刘永治; 翟卫华; 丹珠昂奔 ; 万俊人', '河南省委;全国妇联;书记处;中国大百科全书出版社;中国伦理学会;教育部;国家体育总局;共青团中央书记处;解放军总政治部;中宣部;国家民委;清华大学;', '人民日报', '公民道德建设;中华民族;爱国主义;当代革命军人核心价值观;', '编者按　　9月22日至23日，第六届全国公民道德论坛在河南郑州举办。本届论坛以“弘扬爱国主义精神、推进公民道德建设”为主题，徐光春、陆昊、黄晴宜、刘永治、徐惟诚等21位同志作了主题发言，就大力弘扬爱国主义精神、加强改进新形势下公民道德建设的思路、措施和办法进行了', '2009-09-25 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRo9HOlxYawvelJAF02NTzwbwEnLaVFYcBmTKnGARyqXGk-pj4Xzm60LrSCUYKQ3-8B9w8qwYG7OfXisgj72KH3scsD17dW-Djv33AMTsf6XrbDBV8UWLa2g5VtRPWkAutGbJvBFxdTKDi0ZRcbYH0gE6mAGUjjt_nqdPATAq-_BYw==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6382, '报纸', '让中华民族爱国主义传统薪火相传', '刘先琴; 赵达', '光明日报', '光明日报', '爱国主义传统;中华民族;民族团结教育;', '秋日的郑州,天高云淡、阳光明媚。在伟大祖国60华诞前夕,弘扬爱国主义精神、推进公民道德建设的鲜艳旗帜,在古老的中原大地上高高擎起。 　　　　9月22日至23日,中宣部主办的第六届中国公民道德论坛在河南郑州举行。中央有关部门和地方负责同志、专家学者与全国道德模范代表', '2009-09-24 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRqgxJaBFNN9aJfGyB0WMbHK2Njf4BnCIA20wJXbNsw_d71oOTf7PlAZCgpxOBWuXPgOgVuZuS7fyU8Xv6lOc_1ycs1_dKKS6Z4neaJOJ2ClSlCll1yW9Y3eW9B2V4PEZuLOtgVxaOHUTpHdtXOuWEATyQnBwl0a13tnlFUG6Y-lAw==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6383, '报纸', '充分发挥文化在经济困难时期的独特作用', '徐光春', '中共河南省委;', '人民日报', '经济困难时期;克服困难;国际金融危机;中原文化;独特作用;保增长;化解矛盾;经济大萧条;应对挑战;旅游业;沟通交流;', '文化是一个国家或地区历史传统、精神情感、风俗习惯等方面的积淀和传承，是人们认同归属的精神家园和沟通交流的桥梁纽带。作为一种凝聚力、生产力、创造力，文化深深熔铸在经济发展、社会进步、民族振兴的每一个历程。以“文”化人，能够提高人的素质与涵养，促进人的全面发', '2009-04-10 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRoPWXXI106HFmDFvL7EdhIzlSAhMFzw5rnqExaxtZ0hAIGVWe4Snz6Rmdp1FK1ukTcU-9cVbyTD8hJBmVlSCxe7ab3jWa3UEzDAk9FG4uqBC3l9tTOzmbbVM9BLPRsBdxj_8olD6aiffLmyBLPOaEcvQCpeVwXjNsb6wzP_2Z-1yw==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6384, '报纸', '王景羲：老兵情结', '孙佰忠', '中国煤炭报', '中国煤炭报', '七七事变;宛平县;抗日战争;日本兵;', '　　T人物点击 王景羲今年94岁， 河北人，20岁当兵，是一 位参加过卢沟桥抗战的 老兵。他的不平凡经历 是一笔精神财富。年纪 大了，他经常给年轻人 讲过去的故事，教育他 们勿忘国耻，牢记历史， 奋发图强，振兴中华。今 年', '2008-07-04 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRo_B2HoOElJEPGRu1auyroZRvOQZ-ehyxeToJynLlCPeVqXew-_nG6oGy1wSbZhfPNfgeXAI02hchXpsQTXCbjXS4YNR2RY7_9F8_BU2cGCpcJ7mosaXmizHqFLwpZlNHUb36Wgd_rEUoEfgaWJboFrsyVpQkKFX5lWeWuAYW6hlA==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2,抗日战争2_screened');
INSERT INTO `ds_article` VALUES (6385, '报纸', '文化做媒,京津旅游亲密联姻', '耿闻', '中国旅游报', '中国旅游报', '京味文化;', '北京虎坊桥湖广会馆旁边有一卖炸糕的小店，每天这里都会排起长队。其中有不少是“老北京”骑车十几里，从搬迁后的地方专程赶来排队。他们说，喜欢吃“这一口儿”的原因很简单，就是为了平复内心对儿时老北京的思念。不过，老北京们也许都知道，这个制作炸糕的技术是从天津“', '2007-06-22 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRo_B2HoOElJEPGRu1auyroZRvOQZ-ehyxfEGUhof_hfInuT_vZrFrcLpZ0aS15xNDBKz1KdwuQ1GR3wqAQTDCY6cxljEc7xtroezJf8pCmc9k0DHmjLXHkFGjcSAgwbRwq1sYtDG60AjKx7in4mDKHlHdUiC81vedfVgdJn7MArfg==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6386, '报纸', '乔淑萍：医生的天平就应向患者倾斜', '耿兴敏; 康毅', '中国妇女报', '中国妇女报', '乔淑萍;先进事迹;构建和谐;卫生部;和谐医患关系;白求恩精神;', '编者按：　　 乔淑萍说自己的前半生是幸运的又是不幸的，痛苦的岁月中相伴的也有幸福。之所以这样说，是因为历经磨难的她出生在一个亲情浓厚的大家庭，工作在一个积极向上的大单位，生活在一个有情有爱的小家里。　　 也许命运总是喜欢折磨原本热爱生命的人，童年', '2006-12-28 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRpzKo6iJcqnuwmAQogWnINaA4wh9zFSokOvP35Y_s6U58KAxDrPxD465apOEIQgVopbKOWQmoEJP04Ky-o--Od1TtiKaDxE7vDaVuoWe06AvLsDk972IYDD0Vt3xRzSBn4HMCD9r3stTPO_p_p77UMOy6macoV7bSple19YNkk11w==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6387, '报纸', '面临退伍干劲不减', '雍长军; 闫瑾; 王小兴; 杨志', '解放军报', '解放军报', '技术勤务;', '北空某团老战士为部队再尽一分力　　本报张家口11月2日电　雍长军、特约通讯员闫瑾报道：连日来，塞外气温骤降。然而，在华北某机场，北空某机务大队今年面临退伍的老战士不畏严寒，各司其职，全神贯注做好战鹰保障。 　　 该团针对退伍老战士人数多、地方就业竞争压', '2006-11-03 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRpzKo6iJcqnuwmAQogWnINaA4wh9zFSokOpgzUz3toAIyE1EtrWteX1GDr2RqKaDeNDA5lo64djjUbeO9y3cURYlFIwOSb2tT7mx-_6jOPXE4Z40K07ljXw6-aOlRq80RRvmHwul94iI-CXEaQsmIuaQhOY-tbZr4n84RnRyG76Xg==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6388, '报纸', '李子纯', '', '人民日报', '人民日报', '李子纯;吉鸿昌;国民党特务;', '李子纯，１９００年４月出生于河南省西华县，先后就读于西华师范学校和开封东岳高中，１９２５年底加入中国共产主义青年团。　　　　１９２７年３月至６月，李子纯受党组织派遣到武昌中央农民运动讲习所学习。在讲习所里，毛泽东、恽代英、彭湃、方志敏、夏明翰等系统讲授的', '2006-04-25 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRr0azNnMPpC-O5oSoqDo7hrOZP44aFooT6yHlNOcXww3V5Eq5KR_c5zwmYdFDFKwUSsCPpdvq5Big7bIHYWrkX-lWL8C9QXPVzTbqv0JMu4FOItbnvLRHLX9EtWEiLJZBqxu2zWiEgjYttsjQZDCJXx0wpc5qcOnKKnJ3a382RRJw==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2,方志敏_screened');
INSERT INTO `ds_article` VALUES (6389, '报纸', '宣侠父', '', '人民日报', '人民日报', '宣侠父;冯玉祥;吉鸿昌;', '宣侠父，1899年12月出生于浙江省诸暨县，1920年获准公费赴日本留学。因为参加留日学生爱国运动，于1922年被迫回国。1923年在杭州加入社会主义青年团，不久转为中国共产党党员。　　　　1924年，宣侠父考入黄埔军校第一期。但因触怒蒋介石，被开除学籍、勒令离校。1925年春', '2005-10-23 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRr0azNnMPpC-O5oSoqDo7hrOZP44aFooT6yHlNOcXww3XXGSU5UcpRH-KPdjz1skuDLXZVtPKyXm6n_MQpBPLa-yctnlkeO5-MSO523xZnB5BwWqho5A2gnkQ_cPbq_D6RGgy3Q47F8vJpvJlQyzOxmxN1iRfgeWPxvPt0uz0ctVQ==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2,九一八事变_screened');
INSERT INTO `ds_article` VALUES (6390, '报纸', '纪念中国人民抗日战争胜利六十周年', '', '人民日报', '人民日报', '日本帝国主义;柳条湖事件;化学武器;抚顺战犯管理所;中国人民抗日战争;侵略者;世界反法西斯战争;局部抗战;侵华战争;抗日民族统一战线;东北军;六十周年;', '以“九一八”事变为起点，中国人民的局部抗战由此揭开了世界反法西斯战争的序幕———　　九一八：勿忘国耻与抗争　　冯春梅　包国俊　　　　提起“九一八”，中国人民就会想起那首歌曲《松花江上》。每到“九一八”，中国人就会产生无比的愤恨和铭心的耻辱。　　　', '2005-09-18 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRrfHJUNqg4dw-OFC8q2Ya3pk8LyyWNA13LrzsVeLft3r8dNlU9SAlzUzjzQ42MDWEOy9o8k-tJ6nzPrMLmqiu5kuOXvTWnGO-tso3EvSLI2z-TZt54k8EewCNyYwVHV3n5jvJKbvStNpuqPTiiSU2Elqs9eZPDdG0Ja07Yg_jVj6Q==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6391, '报纸', '河南省项城市企业军转干部顾全大局自强自立', '欧世金; 费士廷', '解放军报', '解放军报', '军转干部;李炳林;项城市;河南省;', '本报讯　记者欧世金、费士廷报道：全市155名企业军队转业干部各种问题“不出市”，都得到了较好解决。9月9日，该市企业军转干部李炳林对记者说：“我是一个受党培养教育多年的兵，个人再难也不能给党和政府添麻烦。” 　　 李炳林1969年入伍到上海警备区，1982年从副指', '2005-09-16 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRrDskeAxTYLbcQBpoLKwfkKsC2PGtfdImURt2e53XtkWycTVZJe7FPMroVGnzfUBII5CchhoY7Oo2AblUy11H9EsEyemnBMyT7ITXDZ9lU8I5K1Bzkfr9BWrIb2_nPxvsgmQzJ5az287YDORcvqRs6ofo52EDD7MeSWaLTGPl0DoA==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6392, '报纸', '汲取抗战胜利的精神力量', '李煦; 张舵; 万一; 孙彦新; 黄明; 吴谷丰; 王文化; 柳忠义; 谢东光; 张德培; 樊永强; 徐壮志; 李宣良; 梅世雄', '新华社;', '新华每日电讯', '日军暴行;日本兵;万里长城;华北事变;卢沟桥;中国人民抗日战争纪念馆;大刀队;日本军国主义;宛平城;中国共产党;国民党政府;日本侵略者;抗战胜利;精神力量;', '今天，《伟大胜利》大型主题展览在中国人民抗日战争纪念馆 隆重开幕。这是中国人民抗日战争暨世界反法西斯战争胜利60周年 纪念活动的重要组成部分，是我们铭记中国人民抗日战争历史， 深入进行爱国主义教育的生动教材。 展览全面回顾中国人民从1931年', '2005-07-07 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRrDskeAxTYLbcQBpoLKwfkKsC2PGtfdImVamHQg2cIo7yxe9MrYrIduqJeBoHtf309WK_03o3IOYsGJh4bvfm9Gt49fqUWYO8Q0Iab1v40D0_mzArZPefpRY5FHnytga_xGdxEX6J5VJ6c9yKYKWsM8CJetWAuj-bA4gasOgkRtfg==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2,抗日战争3_screened,狼牙山_screened,九一八事变_screened,论持久战_screened');
INSERT INTO `ds_article` VALUES (6393, '报纸', '剑胆琴心铸检魂', '杜辉; 余庆锋; 李磊; 左海霞', '国际商报', '国际商报', '检察系统;剑胆琴心;职业公诉人;周口市;科技强检;检察长;检察业务;检察队伍;扶沟县;', 'T近年来，河南省周口市人民检察机关认真贯彻“三个代表”重要思想，为周口市改革开放和经济建设创造了稳定、和 谐的社会环境。该市检察机关全面正确地履行法律监督职责，依法、独立、公正地行使检察权、为维护国家法律的统一正 确实施尽职尽责，为全市全面建设小', '2003-05-14 08:00:00', 'https://next.cnki.net/middle/abstract?v=r_P-ES8duRoYYiPB6ajofzBvsbC3h-T9gtMt5nqo1E7OP1JEgWxB5PMo7w7tHAknN-VdWIILMQielDiJlOBlETPOeOj0kWFF9DioFJ4LKE0otL9dAUP8vBcv3no8Z10w19yvz3ElZiFn-TNCaSDekHBmZNbG-NPEIzOz6z1JQsEfhUOGtRj-0A==&uniplatform=NZKPT&language=CHS&scence=null', '吉鸿昌2');
INSERT INTO `ds_article` VALUES (6394, '报纸', '重走“进京赶考之路”', '严冰; 叶子', '人民日报海外版', '人民日报海外版', '益寿堂;清华园;颐和园;周恩来;香山公园;毛泽东;革命旧址;中国共产党历史;双清别墅;中国人民解放军总部;', '今年是中华人民共和国成立74周年。 74年前的3月23日，毛泽东率领中共中央机关和中国人民解放军总部离开西柏坡，向北平进发。出发前，毛泽东曾对周恩来说：“今天是进京的日子，进京‘赶考’去！” 1949年3月25日早6点，毛泽东、周恩来等中央领导人到达北平，在清华园车站走', '2023-09-28 08:00:00', 'https://link.cnki.net/doi/10.28656/n.cnki.nrmrh.2023.003366', '赶考_screened,七届二中全会_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6395, '报纸', '激发职业青年为中国式现代化挺膺担当 奋力书写新时代青年文明号的绚丽篇章', '李川', '中青报;中青网;', '中国青年报', '青年文明号;小相岭;西柏坡纪念馆;习近平总书记;中国式现代化;', '“青年是引风气之先的社会力量。一个民族的文明素养很大程度上体现在青年一代的道德水准和精神风貌上。”2013年5月4日，在党的十八大后的首个五四青年节，习近平总书记这样殷切寄语青年一代。青年文明号，作为动员引领广大青年弘扬职业文明、立足岗位建功的品牌项目，自创立', '2023-09-19 08:00:00', 'https://link.cnki.net/doi/10.38302/n.cnki.nzgqn.2023.003351', '赶考_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6396, '报纸', '永葆“赶考”的清醒和坚定', '邢婷婷; 蔡艺芃', '中国纪检监察报', '中国纪检监察报', '全面从严治党;习近平总书记;历史周期率;反腐败斗争;毛泽东;“两个务必”;《甲申三百年祭》;治乱兴衰;制度规范体系;窑洞对;', '党的十八大以来，习近平总书记多次用“赶考”激励全党，强调“我们党是世界上最大的马克思主义执政党，要巩固长期执政地位、始终赢得人民衷心拥护，必须永葆‘赶考’的清醒和坚定。”“赶考”这一比喻是怎么来的？“赶考”考什么？为什么说党面临的“赶考”远未结束？中国纪', '2023-09-18 08:00:00', 'https://link.cnki.net/doi/10.28423/n.cnki.njjjc.2023.002966', '赶考_screened,七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6397, '报纸', '李忠杰：从“两个务必”到“两个答案”', '刘冰雅', '光明网;', '光明日报', '“两个务必”;全面从严治党;李忠杰;历史周期率;中国共产党;习近平总书记;', '中国共产党在百年奋斗中，形成了一系列伟大的精神，这些精神既有共性，又有个性。西柏坡精神是中国共产党人精神谱系中的重要组成部分，是党史上的一个重要亮点。回顾党的历史发展进程，可以发现西柏坡精神是在一个历史大转折时期产生的，由此决定了它具有大转折、大手笔、大', '2023-09-06 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.004365', '赶考_screened,七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6398, '报纸', '中国煤矿文工团：在西柏坡唱响“团结就是力量”', '彭澳丽', '中国文化报', '中国文化报', '中国煤矿文工团;慰问演出;北庄村;西柏坡;', '“团结就是力量，团结就是力量，这力量是铁，这力量是钢，比铁还硬，比钢还强……”80年前，歌曲《团结就是力量》在河北省石家庄市西柏坡镇平山县北庄村唱响，激荡着全国人民奋勇抵抗日寇侵略的决心；80年后，中国煤矿文工团的艺术家在北庄村再次唱响这激昂的旋律，展示着新', '2023-05-15 08:00:00', 'https://link.cnki.net/doi/10.28144/n.cnki.ncwhb.2023.001733', '赶考_screened,七届二中全会_screened');
INSERT INTO `ds_article` VALUES (6399, '报纸', '全面从严治党是党永葆生机活力、走好新的赶考之路的必由之路', '任平', '人民日报', '人民日报', '全面从严治党;反腐败斗争;习近平总书记;永葆生机;', '（一） 治国必先治党，党兴才能国强。 “推进强国建设，必须坚持中国共产党领导和党中央集中统一领导，切实加强党的建设。”全国两会上，习近平总书记的重要讲话让人警醒，“要时刻保持解决大党独有难题的清醒和坚定，勇于自我革命，一刻不停全面从严治党，坚定不移反对腐', '2023-04-03 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.003394', '赶考_screened');
INSERT INTO `ds_article` VALUES (6400, '报纸', '石家庄赶考', '陈发宝; 王胜强; 刘亮; 佘惠敏; 曾诗阳; 宋美倩', '经济日报', '经济日报', '石家庄;省会城市;高新区;生产总值;习近平总书记;京津冀协同发展;', '石家庄市是我们党解放的第一座大城市。2013年7月11日，习近平总书记在西柏坡同党员干部群众座谈时指出：“党面临的‘赶考’远未结束。”习近平总书记对正定古城保护作出重要指示，为在石家庄举办的首届中国国际数字经济博览会发来贺信，2021年初又给石家庄市平山县西柏坡镇北', '2023-03-29 08:00:00', 'https://link.cnki.net/doi/10.28425/n.cnki.njjrb.2023.002056', '赶考_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6401, '报纸', '不负人民的发展答卷', '胡果; 吴秋余; 王浩', '人民日报', '人民日报', '习近平总书记;中国共产党领导;美好生活;共同富裕;中国式现代化;', '发展，党执政兴国的第一要务。 人民，党执政兴国的最大底气。 答卷，新时代赶考路上的厚重书写。 我们续写了经济快速发展和社会长期稳定两大奇迹。 我们打赢了人类历史上规模最大的脱贫攻坚战，创造了彪炳史册的人间奇迹。 我们取得了疫情防控重大决定性胜利，创造了人', '2023-02-26 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.002025', '赶考_screened');
INSERT INTO `ds_article` VALUES (6402, '报纸', '牢记“三个务必” 谱写绚丽华章', '吴毅君; 董伟', '湖南省中国特色社会主义理论体系研究中心湖南科技大学基地;', '光明日报', '习近平总书记;中国特色社会主义;“两个务必”;奋斗目标;共产党人;七届二中全会;党的建设;', '习近平总书记在党的二十大报告中强调：“全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，坚定历史自信，增强历史主动，谱写新时代中国特色社会主义更加绚丽的华章。”这既是对毛泽东同志在党的七届二中全会上对全党提出的“两个务必”的', '2023-02-17 08:00:00', 'https://link.cnki.net/doi/10.28273/n.cnki.ngmrb.2023.001982', '赶考_screened,七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6403, '报纸', '牢记和践行“三个务必” 在新的征程上奋力谱写四川发展新篇章', '王晓晖', '中共四川省委;', '人民日报', '习近平总书记;新篇章;中华民族;党中央;中国式现代化;', '习近平总书记在党的二十大报告中郑重强调：“全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，坚定历史自信，增强历史主动，谱写新时代中国特色社会主义更加绚丽的华章。”这是以习近平同志为核心的党中央向全党发出的伟大号召，充分彰显', '2023-01-04 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2023.000099', '赶考_screened,七届二中全会_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6404, '报纸', '深切缅怀继承遗志 万众一心勇毅前行', '', '新华每日电讯', '新华每日电讯', '江泽民同志;党中央;习近平总书记;', '国旗低垂、汽笛鸣响。6日，全国广大干部群众收听收看江泽民同志追悼大会，认真学习习近平总书记致的悼词。大家一致表示，要化悲痛为力量，继承江泽民同志的遗志，以实际行动更加紧密团结在以习近平同志为核心的党中央周围，贯彻落实党的二十大精神，踔厉奋发、勇毅前行，在中', '2022-12-07 08:00:00', 'https://link.cnki.net/doi/10.28870/n.cnki.nxhmr.2022.008404', '赶考_screened');
INSERT INTO `ds_article` VALUES (6405, '报纸', '踏上新征程，向着新的奋斗目标，出发!', '张毅; 徐隽; 孟祥夫', '人民日报', '人民日报', '习近平总书记;中国共产党人;奋斗目标;', '历史的进程，总有一些时刻烛照未来，总有一些节点彪炳史册—— 10月27日，党的二十大闭幕不到一周，习近平总书记带领中共中央政治局常委专程从北京前往陕西延安，瞻仰延安革命纪念地，重温革命战争时期党中央在延安的峥嵘岁月，缅怀老一辈革命家的丰功伟绩，宣示新一届中央', '2022-11-07 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.011981', '赶考_screened,西柏坡_screened,杨家岭_screened');
INSERT INTO `ds_article` VALUES (6406, '报纸', '“向着新的奋斗目标，出发!”', '杜尚泽; 王乐文; 张晓松; 林晖', '新华社;', '人民日报', '奋斗目标;中共中央政治局常委;中国共产党;习近平总书记;毛泽东思想;延安革命旧址;全面从严治党;党的七大;时代化;马克思主义中国化;走向胜利;', '走得再远、走到再光辉的未来，也不能忘记走过的过去，不能忘记为什么出发。 党的二十大闭幕不过四五天，10月27日上午，习近平总书记带领新当选的二十届中共中央政治局常委来到了延安，瞻仰革命圣地，缅怀老一辈革命家的丰功伟绩，宣示新一届中央领导集体赓续红色血脉、传承', '2022-10-29 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.014135', '赶考_screened,西柏坡_screened,枣园_screened,中共七大1_screened,杨家岭_screened,论持久战_screened,凤凰山_screened');
INSERT INTO `ds_article` VALUES (6407, '报纸', '“三个务必”的深刻内涵和重大意义', '王成国', '浙江省人民政府;公安厅;', '学习时报', '重大意义;深刻内涵;历史方位;马克思主义政党;全面从严治党;社会主义建设规律;人类社会发展规律;', '习近平总书记在党的二十大报告中提出，“全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争”。这“三个务必”是基于对党所处历史方位、面临形势任务、党情国情世情发展变化进行深刻分析作出的重大论断，彰显了百年大党新时代赶考的清醒和坚', '2022-10-24 08:00:00', 'https://link.cnki.net/doi/10.38216/n.cnki.nxxsb.2022.002055', '赶考_screened,两个务必_screened,西柏坡_screened');
INSERT INTO `ds_article` VALUES (6408, '报纸', '为中国人民谋幸福 为中华民族谋复兴', '赵承; 霍小光; 张旭东; 张晓松; 赵超; 邹伟; 刘华; 朱基钗; 韩洁; 林晖', '人民日报', '人民日报', '习近平总书记;国家治理体系;治理能力现代化;中华民族;', '人类的梦想有多么伟大，历史的进程就有多么壮阔。 中国共产党一经诞生，就把为中国人民谋幸福、为中华民族谋复兴确立为自己的初心和使命。在这场百年奋进的接力前行中，以习近平同志为主要代表的新时代中国共产党人领导亿万中华儿女书写下恢宏史诗—— 新时代的10年，中华', '2022-10-15 08:00:00', 'https://link.cnki.net/doi/10.28655/n.cnki.nrmrb.2022.011235', '赶考_screened,西柏坡_screened');
INSERT INTO `ds_film` VALUES (959, '2012-11-21 08:00:00', '温州一家人', 'http://39.106.153.224:8888/profile/upload/2025/02/21/温州一家人_20250221212521A001.jpg', '该剧以一户普通人家的原生态纪实，与中国改革开放30多年社会转型变化的大历史交汇同构，呈现一代创业者的智慧、意志和情怀。20世纪80年代改革开放初期，在温州创业潮兴起之时，温州瑞安古树村的周万顺（李立群 饰）毅然决定将年仅13岁的女儿周阿雨（殷桃 饰）只身送往意大利。自己则把祖屋和全部家当卖掉，带着妻子赵银花（迟蓬 饰）和儿子周麦狗（张译 饰）背井离乡徒步来到温州。到温州后进城的周万顺从拾荒做起，一步一步变身为成功商人。爱面子又叛逆的周麦狗为了摆脱父亲，羞愤之中离家出走大西北，开始了自己的艰辛创业路。而远在意大利的周阿雨排除万难从洗碗工做起，凭借出色的商业头脑在意大利普拉托成功创业。剧中，走在最前沿的温州商人前赴后继走出家门、走出国门，他们的命运紧系时代的脉搏。', '13,19', '孔笙、李雪', '高满堂', '李立群、殷桃、张译、迟蓬', 36, '', '2', '', '1', 1, '2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖、优秀编剧奖（高满堂）、优秀女演员奖（殷桃）；2013年第十九届上海电视节白玉兰奖最佳导演奖（孔笙、李雪）；2014年第十三届精神文明建设“五个一工程”奖优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (966, '2012-03-02 08:00:00', '钱学森', 'http://39.106.153.224:8888/profile/upload/2025/02/21/钱学森_20250221212717A002.jpg', '本片讲述上世纪四十年代，加州理工学院终身教授钱学森（陈坤 饰）因为美国兴起的反共言论而备受打击。他的尖端技术研究被迫中止，并被责令出境。钱学森心系祖国，归心似箭，而意识到钱学森的巨大价值的美方又对其归国设置了重重障碍，甚至以间谍罪逮捕钱学森。最终，宣告无罪的钱学森被长期软禁在家 中。 钱学森写信辗转与祖国取得联系，周恩来授命用11名美国战犯飞行员换回了钱学森。 面对新中国技术、人才、工业等各方面的空白，钱学森带领科研人员从仿制入手，根据现有技术和条件逐步研究、完善，奠定了中国导弹的基础。 ', '18,19', '张建亚', '陈怀国、孙毅安、陶纯', '陈坤、张雨绮', NULL, '', '1', 'https://www.1905.com/vod/play/580704.shtml?__hz=28267ab848bcf807&fr=baidu_aladdin_vod_add&api_source=baidualaddin_vodadd ; https://www.iqiyi.com/v_19rrjtrw7o.html?vfm=2008_aldbd&fc=828fb30b722f3164&fv=p_02_01', '0', 1, '2013年第十五届中国电影华表奖优秀故事影片奖', NULL);
INSERT INTO `ds_film` VALUES (1034, '2012-05-23 08:00:00', '忠诚与背叛', 'http://39.106.153.224:8888/profile/upload/2025/02/21/忠诚与背叛_20250221225854A004.jpeg', '该片主要讲述是一九二七年四月，背叛革命的蒋介石发动“四一二反革命改变\"”，大肆屠杀中国共产党党员。时任中共中央局委员、全国铁路工会总书记的王荷波参与组织上海工人武装起义，由于叛徒出卖，起义修道失败，中共驻国民党党团副书记 杨匏安公开啊吁惩治杀人凶手，罢免蒋介石的职务。当时，在国民党党部、国民政府和军队中任职的共产党员面临诸多诱惑，党内也不断出现投敌叛变等情况，因此 毛泽东、周恩来、陈云等共产党人深感创设一个专门的监督机构势在必行王荷波、杨匏安、何梦兰等人开始为监督机构的创立而四处弃走，积极筹备。同年4月下旬，中国共产党第五次全国代表大会在武汉召开，会议选举产生了由王荷波、杨鲍安等10名同志为委员的中央监察委员会。随后，王荷波杨安相继奔赴新的战场，继续革命。1927年10月，王荷波不幸被捕，壮烈牺牲，杨匏安也于1931年惨遭敌人杀害。中央监察委员会在成立后的一年多时间里，10名委员和候补委员都经受住了艰苦卓绝的土地革命战争血与火的考验，先后有8名成员为革命英勇牺牲，却无一人叛党投敌，他们用自己的鲜血和生命为党旗增添了绚丽的光彩。', '3,19', '张玉中', '赵峻防、沈悦、邵钧林', '刘之冰、徐箭', NULL, '', '0', '', '0', 0, '2013年第二十九届中国电影金鸡奖组委会奖；2013年第十五届中国电影华表奖优秀故事影片奖、优秀男演员奖（刘之冰）。', NULL);
INSERT INTO `ds_film` VALUES (1035, '2012-08-07 08:00:00', '听风者', 'http://39.106.153.224:8888/profile/upload/2025/02/21/听风者_20250221230019A005.jpeg', '该片讲述街头小混混何兵（ 梁朝伟 饰）是一位盲人，他拥有超凡的听觉特能，并以此为生计。1951年10月8日，神秘的701部队突然发现，所有的敌台全部消失了，需要优秀的侦听人员，而何兵的特殊能力对701非常重要，因此701派出张学宁 （ 周迅 饰）将何兵请到701来，希望他能为新中国服务。何兵帮助701找到了敌人的全部电台，也同时找到了自己心爱的女孩，并与她结婚，张学宁还请来了名医为何兵治好了眼睛。可是在一次侦听中，何兵的失误导致了张学宁牺牲。何兵悲痛万分，在一个雨夜又弄瞎了自己的双眼，但同时他的听力再一次变的灵敏，重新为701找回了敌人的电台。', '0,19', '麦兆辉、庄文强', '麦兆辉、庄文强', '梁朝伟、周迅', NULL, '', '1', '', '0', 0, '2014年第十三届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1036, '2013-05-17 08:00:00', '中国合伙人', 'http://39.106.153.224:8888/profile/upload/2025/02/21/中国合伙人_20250221225347A003.jpeg', '该片讲述了20世纪80年代，三个怀有热情和梦想的年轻人在高等学府燕京大学的校园内相遇，从此展开了他们长达三十年的友谊和梦想征途。出生于留学世家的孟晓骏渴望站在美国的土地上改变世界，浪漫自由的王阳尽情享受改革开放初期那蓬勃激昂的青春气息，曾两次高考落榜的农村青年成冬青（黄晓明 饰）以晓骏为目标努力求学，并收获了美好的爱情。然而三个好友最终只有晓骏获得美国签证，现实和梦想的巨大差距让冬青和王阳倍受打击。偶然机缘，被开除公职的冬青在王阳的帮助下办起了英语培训学校，开始品尝到成功的喜悦。在美国发展不顺的晓骏回国，并加入学校，无疑推动三个好友朝着梦想迈进了一大步。只是随着成功的降临，他们的友情也开始承受严峻的考验。', '9,16,19', '陈可辛', '周智勇、张冀、林爱华', '黄晓明、邓超、佟大为', NULL, '', '3', '', '0', 1, '2013年第二十九届中国电影金鸡奖最佳故事片奖、最佳导演奖（陈可辛）、最佳男主角奖（黄晓明）；2014年第三十二届大众电影百花奖优秀故事片奖、最佳男主角奖（黄晓明）、最佳男配角奖（佟大为）；2013年第十五届中国电影华表奖优秀故事片奖。', NULL);
INSERT INTO `ds_film` VALUES (1040, '2013-07-16 08:00:00', '周恩来的四个昼夜', 'http://39.106.153.224:8888/profile/upload/2025/02/21/周恩来的四个昼夜_20250221232103A011.jpeg', '该片讲述了1961年，全党大兴调查研究之风。党中央领导人身体力行，组织调查组或亲自深入实际进行调查研究。1961年5月3日，周恩来 （ 孙维民 饰）总理一行来到伯延时，新中国正面临旱灾和饥荒，伯延沿路的枯树便是无声的证明。然而，从公社主任到老乡们，没有人愿意告诉总理饥饿的实情，大家只有一个朴素的想法，那就是不给国家添麻烦。一次座谈会，社员黑压压挤了一大屋。开始大家不敢说话，周恩来笑着指指身后墙上的画像（当时普遍张贴七位中央常委的画像）：我叫周恩来，就是墙上的那个人。你们看像不像，这次我来是想听大家的心里话，有话只管说，说错了也不要紧。蹲在总理身边闷头吸烟的村民张二廷 （ 储智博 饰）在总理问到他时，头一个跳起身“放炮”：要说食堂好，全是假话。食堂吃不饱。还愣冲冲来了一句：你要是糊弄我们，总理，再过两三年，你也会饿死的。周恩来闻言猛然一震，沉凝片刻，眼里噙满泪水：还是我这个总理没当好，我先道歉，对不起大家。四天四夜里，周总理走访了几十户农民家庭，与乡亲们同吃同住同劳动，在走访调研考察中，了解了真实情况，伯延由此成为全国第一个取消集体食堂的人民公社。', '18,19', '陈力', '田运章、江月', '孙维民、何伟', NULL, '', '1', '', '0', 1, '2013年第二十九届中国电影金鸡奖最佳故事片奖、最佳音乐奖（章绍同）；2014年第三十二届大众电影百花奖优秀故事片奖；2013年第十五届中国电影华表奖优秀故事影片奖、优秀导演奖（陈力）；2014年第十三届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1042, '2014-09-23 08:00:00', '兰辉', 'http://39.106.153.224:8888/profile/upload/2025/02/21/兰辉_20250221232116A012.jpeg', '2008年5月12日的汶川地震引起世界瞩目，在抗震救灾的过程中涌现出许多优秀党员干部，绵阳市北川羌族自治县人民政府副县长兰辉同志，就是其中最优秀的代表。该片主要讲述了2008年5·12汶川地震发生后到2013年5月23日，兰辉因公殉职的五年时间里，兰辉工作与生活的故事。', '18,19', '明振江、温德光、刘之冰', '柳建伟', '刘之冰、李雪健、陶慧敏、洪晓熙、李易祥', NULL, '', '2', '', '0', 0, '2014年第十三届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1043, '2014-05-16 08:00:00', '永远的焦裕禄', 'http://39.106.153.224:8888/profile/upload/2025/02/21/永远的焦裕禄_20250221230401A006.jpeg', '该片讲述焦裕禄在河南省洛阳矿山机器厂工作9年，勤恳认真，积累了丰富的经验。之后被派到无人愿去的河南省兰考县担任县委书记，为改变兰考贫穷落后的面貌，焦裕禄深入基层，访贫问苦，调查研究，制订出治理肆虐兰考百年之久的风沙、内涝、盐碱三害的方案。焦裕禄经常不顾肝脏胀痛，亲自带领群众种植泡桐、翻淤压碱等，始终奋战在整治三害第一线，深得人民爱戴。而在兰考工作475天后，焦裕禄却因肝癌不幸离世。但他留下的“焦裕禄精神”激励着一代又一代的兰考人民和中华儿女 。总导演海涛表示，现在很多年轻人已经不知道焦裕禄是谁了，但一个时代需要有信仰的楷模，该片可以让观众认识到一个真实的人民好干部，这也是该片拍摄的初衷 。同时2014年5月14日是焦裕禄逝世50周年纪念日，拍摄该片也是为了表达对焦裕禄的缅怀，对焦裕禄平凡而伟大精神的弘扬 。在洛阳拍摄期间，主创团队分别到焦裕禄曾经工作过的洛阳矿山机器厂一金工车间、厂资料室、调度室，以及企业建设的焦裕禄大道、焦裕禄铜像等处进行取景，并采访了焦裕禄在洛阳工作期间的工友，回顾了焦裕禄在洛矿工作的事迹 。该片从创意、筹备到拍摄完成，历时近一年时间，由118人组成的摄制组拍摄采访了43人，由48人组成的资料搜索团队观看焦裕禄相关纪录片、科教片、新闻简报共计1100多本，长10200分钟，搜集到大量生动、翔实的历史影像资料。片中近一半篇幅都是运用历史真实镜头，不少镜头是国内仅存，首次与观众见面 。主创团队在兰考拍摄时，条件艰苦。冬天一场大雪后，他们所住地方的太阳能全部被冻住了，没有办法洗热水澡 。在该片的拍摄过程中，焦裕禄干部学院名誉副院长、焦裕禄的二女儿焦守云一直全程跟随，提供故事线索，并担当顾问 。该片是继中央新闻纪录电影制片厂于1966年拍摄的《光辉的榜样——毛主席的好学生焦裕禄》后，第二部关于焦裕禄的纪录片 。', '18', '海涛、侯雅俊', '陈燕民', '焦守云（顾问） 、韩涛（解说） ', NULL, '', '1', '', '0', 0, '2014年第十三届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1044, '2014-05-20 08:00:00', '天上的菊美', 'http://39.106.153.224:8888/profile/upload/2025/02/21/天上的菊美_20250221230634A007.jpeg', '该片讲述了藏族基层干部菊美多吉 （ 阿旺仁青 饰）短暂，但感人的一生。他出身于四川省藏区的基层干部，虽然官职不大，但需要他担心的问题却不少，像牧民家的牛丢了，为当地修桥补路等在他人看来的小事在他心中却是头等大事。而也正是由于过分操劳，使他患上了高血压等疾病，而这也没有能够耽误他为当地百姓服务，直至菊美在一次深入牧区的走访之后，因突发疾病，在睡梦中去世。', '19', '苗月', '卓玛达娃', '阿旺仁青、江疏影', NULL, '', '2', '', '0', 0, '2016年第十六届中国电影华表奖优秀少数民族题材影片奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1046, '2014-11-15 08:00:00', '天河', 'http://39.106.153.224:8888/profile/upload/2025/02/21/天河_20250221231525A008.jpeg', '董望川 （ 李幼斌 饰）是南水北调中线工程的副总指挥，他与妻子周晓丹 （ 俞飞鸿 饰）为工程聚少离多，原本稳固的感情渐渐出现问题。就在技术攻坚之时，董望川最得力的助手兼学生江浩 （ 段奕宏 饰）竟离他而去，跳槽到一家高薪企业，而家乡的亲人也因身处库区而坚决反对搬迁移民。为了确保工程如期保质完成，面对空前压力的董望川选择自己坐镇一线，并推荐妻子周晓丹去接管移民工作。引水中线工程即将全线贯通，花费巨资的外国设备突然出现故障。众人一筹莫展之时，江浩毅然归来，向董望川伸出援手。所有人，都在为工程的顺利竣工做着最后的努力。', '19', '宁海强、沈东', '黄宏、柳建伟', '李幼斌、段奕宏、俞飞鸿', NULL, '', '2', '', '0', 0, '', NULL);
INSERT INTO `ds_film` VALUES (1049, '2014-12-23 08:00:00', '智取威虎山', 'http://39.106.153.224:8888/profile/upload/2025/02/21/智取威虎山_20250221231835A009.jpeg', '该片讲述了1947年冬，为了从土匪手中夺取控制东北九岭上万先遣军的分布图，东北民主联军203小分队队长少剑波 （ 林更新 饰）委派侦查员杨子荣 （ 张涵予 饰）卧底潜入最大的土匪山头“威虎山”。杨子荣凭借自己的机智应变获得了匪首座山雕 （ 梁家辉 饰）和座下八大金刚的赏识，被封为威虎山“老九”。座山雕天生多疑，多次派人试探杨子荣，杨子荣一面与土匪多方周旋，一面涉险为山下战友传出情报。一波未平一波又起，被203小分队生擒的土匪联络副官栾平 （ 杜奕衡 饰）趁乱逃脱，知道杨子荣卧底详情的他竟出现在威虎寨中与杨子荣当面对质，杨子荣腹背受敌陷入全面危机 。', '7,14,19', '徐克', '李杨、吴兵、董哲、林启安、黄建新、徐克', '张涵予、林更新、梁家辉、余男', NULL, '', '0', '', '0', 1, '2015年第三十届中国电影金鸡奖最佳导演奖（徐克）、最佳男配角奖（张涵予）、最佳剪辑奖（于柏杨）；2016年第三十三届大众电影百花奖优秀电影特别表彰；2016年第十六届中国电影华表奖优秀故事片奖、优秀导演奖（徐克）；2017年第十四届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1050, '2015-04-02 08:00:00', '战狼', 'http://39.106.153.224:8888/profile/upload/2025/02/21/战狼_20250221232027A010.jpeg', '该片讲述了痞性十足的 冷锋 （ 吴京 饰）屡屡惹祸，有人说他是流氓，是痞子， 也有人说他是英雄，是传奇，在一次行动中冷锋违抗军令打死了恐怖分子，要被开除出队，却意外得到了神秘部队战狼的接纳，但本想换个地方继续惹祸的他却跳进了另外一个深渊，冷傲的战狼副队长，擦出暧昧火花的性感女队长 龙小云 （ 余男 饰），心计颇深腹黑的毒枭，枉死的队友，雇佣兵跨过边境线入侵中国，一切都使他陷入了麻烦中。一切都在考验这个团队的毒瘤冷锋，他不知该何去何从。', '6,19', '吴京', '刘毅、董群、吴京、高岩', '吴京、余男', NULL, '', '3', '', '0', 0, '2016年第三十三届大众电影百花奖优秀故事片、最佳新人（庄小龙）；2016年第十六届中国电影华表奖优秀故事片奖；2017年第十四届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1051, '2015-08-21 08:00:00', '战火中的芭蕾', 'http://39.106.153.224:8888/profile/upload/2025/02/21/战火中的芭蕾_20250221232228A013.jpeg', '该片讲述了1945年9月12日，潜伏在黑龙江边境小镇丛林中的300多名日本军人拒不投降、负隅顽抗，血洗了当地村民，并袭击了苏联红军。最后东北抗联部队和苏联红军一举剿灭了这股日军。由于战斗发生在日本宣布投降以后的第28天，故称为抗日战争中发生在黑土地上的“最后一战”。', '7,19', '董亚春、尼基塔·米哈尔科夫', '宏恬、黄宏', '曹舒慈、伊戈尔·卡列斯科夫', NULL, '', '0', '', '0', 0, '', NULL);
INSERT INTO `ds_film` VALUES (1052, '2015-05-15 08:00:00', '旋风九日', 'http://39.106.153.224:8888/profile/upload/2025/02/21/旋风九日_20250221232406A014.jpeg', '该片讲述了1979年1月28日，在中美正式建交后的27天，时任中国国务院副总理的邓小平访问美国。在此之前，中美双方大使在谈判桌上较量15年，美国孤立中国二十多年。一个刚刚摆脱危难、冲破束缚的东方大国作出历史性重大抉择，在改革开放前，迈上了中美“融冰之旅”，它如巨人之手推开了封闭的国门，这个抉择不但影响了太平洋两岸的两个大国，更深刻地震撼着整个世界。', '3,18', '傅红星', '傅红星、陈天璇', '陈天璇、吉米·卡特、萨日娜、亨利·基辛格、兹比格涅夫·卡济米尔兹·布热津斯基', NULL, '', '1', '', '0', 0, '', NULL);
INSERT INTO `ds_film` VALUES (1053, '2015-08-28 08:00:00', '百团大战', 'http://39.106.153.224:8888/profile/upload/2025/02/21/百团大战_20250221232543A015.jpeg', '该片讲述了1940年8月20日夜， 晋察冀军区、第129、第120师在八路军总部统一指挥下，发动了以破袭 正太铁路（石家庄至太原）为重点的战役。战役发起第3天，参战部队已达105个团，故称“百团大战”。百团大战是 抗日战争相持阶段八路军在华北地区发动的一次规模最大、持续时间最长的战役。自1939年冬以来，日军以铁路、公路为支柱，对抗日根据地进行频繁扫荡，并企图割断太行、晋察冀等战略区的联系，推行所谓“以铁路为柱，公路为链，碉堡为锁”的“ 囚笼政策”。八路军总部决定发动交通破击战，重点破袭正太铁路和同蒲路北段，给日本华北方面军以有力打击。这次战役经历了两个主动进攻阶段和一个反“扫荡”阶段。第一阶段（8月20日至9月10日）。八路军在 正太、同蒲、平汉、津浦等主要交通线发动总攻击，重点破坏了正太铁路。经过20天的战斗，预定计划全部完成。正太铁路线的路轨、桥梁、隧道、水塔、车站等均被破坏；平汉、同蒲（北段）、石德、北宁铁路以及主要公路也被切断；华北各交通线陷于瘫痪。第二阶段（9月22日至10月上旬）。任务是继续扩大战果，摧毁交通线两侧和深入各抗日根据地的敌伪据点。在这段时间里，我晋察冀军区主要进行了 涞灵战役，第129师主要进行了 榆辽战役，第120师主要破袭了同蒲路。在这些战斗中，八路军给敌人以沉重打击；但是，我军计划要拔除的敌据点未能全部拔除。第三阶段（10月6日至翌年1月24日），主要任务是反击日伪军的报复扫荡。在这段时间里，八路军先后粉碎了日伪军对太行、太岳、平西、北岳、晋西北等抗日根据地的大规模扫荡。百团大战历时5个多月。从8月20日至12月5日的3个半月中，八路军共进行大小战斗1824次，共计毙、伤、俘和投诚日伪军达46480人。其中包括：毙、伤日军20645人，伪军5155人；俘虏日军281人，伪军18407人；日军自动携械投诚者47人，伪军反正者1845人。同时，缴获各种枪5942支（挺），各种炮53门；破坏铁路474公里，公路1502公里，桥梁213座，火车站37个，隧道11个；破坏煤矿5个，仓库11所。此外，还缴获和破坏了其他大量军用物资。百团大战粉碎了日军的“ 囚笼政策”，推迟了日军的南进步伐，增强了全中国军民取得抗战胜利的信心，提高了 中国共产党和 八路军的声望。', '3,7', '宁海强、张玉中', '董哲、刘英学、刘凤玉', '唐国强、王伍福、陶泽如、刘之冰、印小天', NULL, '', '0', '', '0', 0, '2016年第十六届中国电影华表奖优秀故事片奖；2017年第十四届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1055, '2016-07-22 08:00:00', '老阿姨', 'http://39.106.153.224:8888/profile/upload/2025/02/21/老阿姨_20250221232840A016.jpeg', '该片讲述了1950年，龚全珍 （陶慧敏 饰）参军奔赴新疆，担任新疆八一小学教师。经组织介绍和比自己大十八岁的新疆军区后勤部长甘祖昌 （李雪健 饰）结婚。甘祖昌因战争中三次负伤而无法正常工作，要求回乡当农民。龚全珍便随丈夫来到江西，二人相濡以沫、生死与共。甘祖昌去世后，龚全珍传承甘祖昌精神，带领子女勤俭节约、艰苦奋斗，用大爱情怀书写自己传奇的一生。2013年，龚全珍被评为全国道德模范，受到习近平总书记的接见，并被习近平总书记亲切的称为“老阿姨” 。', '19', '雷献禾', '郭中束、史建全', '李雪健、陶慧敏', NULL, '', '1', '', '0', 0, '2018年第十七届中国电影华表奖优秀故事片奖；2017年第十四届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1059, '2016-09-30 08:00:00', '湄公河行动', 'http://39.106.153.224:8888/profile/upload/2025/02/23/湄公河行动_20250223083835A001.jpeg', '该片讲述了2011年10月5日清晨，两艘中国商船在 湄公河 金三角流域遇袭，船上13名中国船员全部遇难，并在船上发现90万粒毒品。这宗枪杀十三名中国船员的血腥冤案，掀起了悲剧的序幕。面对矛头指向中国运毒、颠倒是非的舆论，为了还遇难同胞一个清白，中国决定派出缉毒精英，组成此次案件的特别行动小组，以高刚 （ 张涵予 饰）为队长，潜入金三角查明真相，竭力揪出案件的幕后黑手。然而缉拿真凶的过程并非他们想得那么简单，事件的进展扑朔迷离，通往真相的道路更是险象环生 。', '19', '林超贤', '朱镜祺、刘小群、谭惠贞、林明杰、林超贤、麦天枢', '张涵予、彭于晏、冯文娟', NULL, '', '3', '', '0', 1, '2017年第三十一届中国电影金鸡奖最佳故事片奖；2018年第十七届中国电影华表奖优秀故事片奖；2017年第十四届精神文明建设“五个一工程”优秀作品奖。', 10);
INSERT INTO `ds_film` VALUES (1061, '2022-04-22 08:00:00', '邓小平小道', 'http://39.106.153.224:8888/profile/upload/2025/02/21/邓小平小道_20250221233126A018.jpeg', '文革期间，邓小平受到错误的批判，1969年10月被下放到江西新建县拖拉机修造厂监管劳动，进入生命中的第二段“至暗时刻”。他承受政治、生活等多重高压，一边坚持劳动，一边还要照顾瘫痪在床的大儿子，每天沿着小道从住地“将军楼”步行到工厂上班风雨无阻，沿着这条小道一走就是3年4个月，这条小道被后人称之为“小平小道”。', '18,19', '雷献禾、卢奇', '王兴东', '卢奇、于慧、赵恒煊', NULL, '', '2', '', '0', 0, '2023年第十九届中国电影华表奖优秀故事片奖', NULL);
INSERT INTO `ds_film` VALUES (1063, '2022-09-30 08:00:00', '钢铁意志', 'http://39.106.153.224:8888/profile/upload/2025/02/21/钢铁意志_20250221233222A019.jpeg', '该片讲述了1948年的东北，国民党残部边撤离边计划炸毁鞍钢厂区。危机时刻，“战斗英雄”赵铁池 （ 刘烨 饰）带领共产党部队直冲腹地，摧毁了敌人的阴谋。他与工程师孙雪飞 （ 韩雪 饰）、老工人孟泰 （ 林永健 饰）、总经理程时勋 （ 张国强 饰）一同投身复工复产。然而，高炉已成铁坨，厂区如同废墟，第一炉铁水似乎成了一个不可能完成的任务 。', '3,19', '宁海强', '萧森、孙浩、宁海强', '刘烨、韩雪、林永健', NULL, '', '0', '', '0', 0, '2024年第十七届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1064, '2022-02-01 08:00:00', '狙击手', 'http://39.106.153.224:8888/profile/upload/2025/02/21/狙击手_20250221233345A020.jpeg', '影片根据抗美援朝战争“冷枪冷炮”运动中神枪手群体事迹改编。1952年冬至1953年初，中国人民志愿军与联合国军在朝鲜战场形成僵持，双方发起了低强度的密集狙击战，史称“冷枪冷炮运动”。在连长（张译 饰）带领下的狙击五班战士枪法过人，成为敌军的心头大患，班长刘文武（章宇 饰）更成为重点狙击对象。为重创狙击五班，敌方调配精英狙击小队，配以最先进的武器装备，更迫使狙击五班战士大永（陈永胜 饰）等人为救同伴进入其设好的险境之地。但正当敌军打响自己如意算盘之时，他们未料到，被他们当作诱饵的侦察兵亮亮（刘奕铁 饰）身上其实隐藏着更大的秘密......', '3,7,19', '张艺谋、张末', '陈宇', '陈永胜、章宇', NULL, '', '1', '', '0', 1, '2022年第三十五届中国电影金鸡奖最佳摄影奖（赵小丁）、最佳录音奖（杨江、赵楠）；2022年第十六届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1065, '2022-02-01 08:00:00', '奇迹·笨小孩', 'http://39.106.153.224:8888/profile/upload/2025/02/21/奇迹·笨小孩_20250221233515A021.jpeg', '该片讲述了二十岁的景浩 （ 易烊千玺 饰）独自带着年幼的妹妹景彤（ 陈哈琳 、 陈翊曈 饰）来到深圳生活，兄妹俩生活温馨却拮据。妹妹景彤有遗传妈妈的先天性心脏病，需要尽早做手术。为了给妹妹治病，他必须在一年半的时间里凑齐35万元。景浩决定放手一搏，他创办好景电子元件厂，拆解残次机中的零件卖给手机公司，只要良品率达到85%以上，4个月就可以赚80万元。但公司却既不管人员、厂房、设备，也不支付定金，既没钱又没人 。', '9,16,19', '文牧野', '周楚岑、修梦迪、文牧野、钟伟、韩晓邯', '易烊千玺、田雨、陈哈琳', NULL, '', '3', '', '0', 1, '2022年第三十五届中国电影金鸡奖最佳女配角奖（齐溪）；2023年第十九届中国电影华表奖优秀故事片奖；2022年第十六届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1066, '2022-09-30 08:00:00', '万里归途', 'http://39.106.153.224:8888/profile/upload/2025/02/21/万里归途_20250221233650A022.jpeg', '该片讲述了努米亚共和国爆发战乱，由于使馆人手不够，原本只是协助撤侨工作，当天往返回国的前驻地外交官 宗大伟 （ 张译 饰）与外交部新人成朗 （ 王俊凯 饰）临危受命，主动放弃回家机会，支援撤侨行动。任务顺利结束，却得知还有一批被困同胞，正在白婳 （ 殷桃 饰）的带领下，前往边境撤离点。情急之下，两人放弃了回家机会，逆行进入战区。赤手空拳的外交官，穿越战火和荒漠，面对反叛军的枪口，他们要带领同胞走出一条回家之路 。', '7,19', '饶晓志', '秦海燕、史册、雷志龙、步京委', '张译、王俊凯、殷桃', NULL, '', '3', '', '0', 1, '2023年第三十六届中国电影金鸡奖最佳美术奖（李淼）；2024年第十七届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1067, '2022-02-01 08:00:00', '长津湖之水门桥', 'http://39.106.153.224:8888/profile/upload/2025/02/21/长津湖之水门桥_20250221233800A023.jpeg', '该片以抗美援朝战争第二次战役中的长津湖战役为背景，中国人民志愿军第九兵团七连战士们在伍千里等结束了新兴里和下碣隅里的战斗之后，七连战士们又接到了更艰巨的任务，为阻止美陆战一师撤退，在连长伍千里的带领下，慷慨奔赴咽喉之处，炸毁水门桥阻击敌军 。七连战士们兵分四路在水门桥外围克服敌军重点火力：突击组进攻指挥部，突击穿插，智取目标；火力支援组侦察敌情，协同作战；爆破组攻敌“心脏”，断敌退路；掩护组游击袭扰，灵活配合，最终成功炸毁水门桥，切断了美军退路 。', '3,7,19', '徐克', '兰晓龙、黄建新', '吴京、易烊千玺、朱亚文、李晨', NULL, '', '1', '', '0', 0, '', NULL);
INSERT INTO `ds_film` VALUES (1070, '2023-08-28 08:00:00', '觅渡', 'http://39.106.153.224:8888/profile/upload/2025/02/21/觅渡_20250221233908A024.jpeg', '本片以中国共产党早期三位重要领导人瞿秋白、张太雷、恽代英的革命经历为主线，讲述“常州三杰”坚持共产主义崇高信仰，在中国革命阵地上，展现他们短暂而光辉的人生、非凡而高尚的人格魅力、坚毅而浪漫的革命情怀。', '3,18,19', '宁敬武', '宁敬武', '宋洋、张桐、谷嘉诚', NULL, '', '4', '', '0', 0, '2023年第三十六届中国电影金鸡奖最佳音乐奖（捞仔）', NULL);
INSERT INTO `ds_film` VALUES (1074, '2023-03-24 08:00:00', '望道', 'http://39.106.153.224:8888/profile/upload/2025/02/21/望道_20250221234029A025.jpeg', '该片讲述了从日本留学归来的陈望道接下了翻译《共产党宣言》的任务，从此改变了人生轨迹的故事。片中陈独秀、俞秀松、施存统、经亨颐、戴季陶、蔡慕晖等历史人物一一出场。历经时代动荡变革，友朋或牺牲或离去，陈望道面临生死抉择的考验。', '3,19', '侯咏', '贺子壮、宋晋川、侯咏', '刘烨、胡军、文咏珊', NULL, '', '4', '', '0', 0, '', NULL);
INSERT INTO `ds_film` VALUES (1075, '2023-11-24 08:00:00', '我本是高山', 'http://39.106.153.224:8888/profile/upload/2025/02/21/我本是高山_20250221234158A026.jpeg', '该片根据张桂梅真实事迹改编，海清领衔演绎现实催泪佳作！这是一个坚毅的女人和一群刚刚毕业还很稚嫩的老师，带着一百多个女孩成功逆天改命的故事，是关于爱、青春、热血和命运……', '15,18,19', '郑大圣、杨瑾', '袁媛、陈麒凌', '海清、陈永胜、柴烨', NULL, '', '3', '', '0', 0, '2024年第十七届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1076, '2023-09-28 08:00:00', '志愿军：雄兵出击', 'http://39.106.153.224:8888/profile/upload/2025/02/23/志愿军：雄兵出击_20250223103227A001.jpeg', '该片讲述了1949年建国初期，新中国面临“内忧外患”局面。朝鲜内战爆发以来，美军屡在中朝边境挑衅，平民惨遭轰炸。为了维护来之不易的和平、为了世代长久的安稳，1950年10月，中国人民志愿军入朝，“抗美援朝”战争拉开帷幕。 这是一场“举国之战”—— 朝鲜战场，即使军备实力对比悬殊，我军却用壮烈牺牲换回节节胜利； 外交舞台，中华人民共和国代表团首度亮相联合国，中国新声赢得国际敬畏。 新中国，寸土不让扬国威；新青年，意气风发保家国。', '3,7,19', '陈凯歌', '张珂', '唐国强、王砚辉、刘劲', NULL, '', '1', '', '0', 1, '2024年第三十七届中国电影金鸡奖评委会特别奖、最佳导演奖（陈凯歌）；2024年第三十七届大众电影百花奖最佳影片奖；2024年第十七届精神文明建设“五个一工程”优秀作品奖。', 10);
INSERT INTO `ds_film` VALUES (1077, '2023-01-22 08:00:00', '无名', 'http://39.106.153.224:8888/profile/upload/2025/02/21/无名_20250221234339A028.jpeg', '该片讲述了1941年12月7日，日本偷袭珍珠港。次日，汪伪政府跟随日本对英美宣战，日本象征性占领上海全境。随着太平洋战争全面爆发，中国抗战形势也因此完全改变。中国共产党领导的中共特科在上海周旋于重庆、汪伪、日本间谍机构之间，通过错综复杂的敌后情报系统，策反敌人，获取情报，诛杀汉奸，建立更广泛的统一战线，直至抗战胜利的前夜。', '1,3,19', '程耳', '桂冠、刘晓世', '梁朝伟、王一博、周迅、黄磊', NULL, '', '0', '', '0', 1, '2023年第三十六届中国电影金鸡奖最佳导演奖（程耳）、最佳男主角奖（梁朝伟）、最佳剪辑奖（程耳）。', NULL);
INSERT INTO `ds_film` VALUES (1078, '2023-04-28 08:00:00', '长空之王', 'http://39.106.153.224:8888/profile/upload/2025/02/21/长空之王_20250221234443A029.jpeg', '该片讲述了雷宇（王一博饰）等优秀飞行员经过严苛选拔正式成为试飞员，他们在队长张挺（胡军饰）的带领下，参与到了最新型战机的试飞。高空之上，发动机骤停甚至失火，飞机失去控制。他们一次次与死神过招，只为获取最极限的数据。随着战机交付日期的临近，任务难度逐渐升级，试飞员们面临着更大的挑战。', '6,19', '刘晓世', '桂冠、刘晓世', '王一博、胡军', NULL, '', '3', '', '0', 0, '2023年第三十六届中国电影金鸡奖最佳导演处女作奖（刘晓世）；2024年第十七届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1137, '2012-06-26 08:00:00', '我们的法兰西岁月', 'http://39.106.153.224:8888/profile/upload/2025/02/22/我们的法兰西岁月_20250222002535A030.jpg', '该剧故事发生在二十世纪初叶，为探索救国救民真理，中国的进步青年上下求索，探寻救国救民的道路，在开明人士的倡议下，他们开始把目光转向欧洲。周恩来（朱亚文 饰）、邓希贤（钟秋 饰）等一批进步青年来到法国勤工俭学，开始了异国他乡的工读生活。1921年，周恩来、赵世炎（李梁 饰）等成立巴黎共产主义小组，陈延年兄弟俩在他们感召下开始信奉马克思主义。北洋军阀停止供给留法学生，蔡和森（张念骅 饰）带人到驻法公使馆请愿，遭到警察镇压。在不断斗争中，蔡和森与向警予（吕夏 饰）结为革命伴侣，蔡畅（吴晓丹 饰）和李富春（刘智扬 饰）也喜结连理。由于里昂大学拒收勤工俭学的中国学生，赵世炎、蔡和森等人奋起交涉，遭军警逮捕，后被遣返回国，血的洗礼让广大留法青年自觉地站在了共产主义的旗帜下……本剧讲述了青年时期的周恩来、邓小平、赵世炎、蔡和森等社会主义革命先驱与伟人在法国艰辛寻求救国之道并最终走上共产主义革命道路的故事。', '3,14,19', '康洪雷', '李克威', '朱亚文、钟秋、李泓良、张隽溢、袁文康', 31, '', '0', '', '1', 0, '2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第二十七届中国电视金鹰奖优秀电视剧奖；2012年第十二届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1138, '2012-10-17 08:00:00', '五星红旗迎风飘扬2', 'http://39.106.153.224:8888/profile/upload/2025/02/22/五星红旗迎风飘扬2_20250222002601A031.jpg', '该剧承接“两弹一星”的故事，从1970年4月我国第一颗人造卫星上天写起，着力塑造毛泽东（唐国强 饰）、周恩来（孙维民 饰）、邓小平（卢奇 饰）等老一辈革命家运筹帷幄，在复杂多变和严峻的国际环境中，审时度势，从容应对，始终立于主动地位。为了维护祖国的主权、领土完整和民族尊严，他们进行的坚定而有理有力的斗争，在严重困难面前，他们带领全国人民，迎难而上，以不屈的姿态和昂扬的精神面貌去战胜和克服困难，终于走出了一条中国特色的社会主义道路。', '3,14,19', '王响伟、刘光', '赵锐勇', '唐国强、孙维民、卢奇、马晓伟、黄薇', 45, '', '1', '', '1', 0, '2013年第二十九届中国电视剧飞天奖长篇电视剧二等奖、优秀男演员奖（孙维民）。', NULL);
INSERT INTO `ds_film` VALUES (1139, '2012-10-07 08:00:00', '国家命运', 'http://39.106.153.224:8888/profile/upload/2025/02/22/国家命运_20250222002630A032.jpg', '该剧讲述了朝鲜战争结束后，有感于美国先进武器在战场上对我志愿军造成的巨大伤害，为彻底打破以美国为首的西方敌对势力对中国的核威慑，在毛泽东（韩中 饰）、周恩来（刘劲 饰）、邓小平（史鑫 饰）等国家领导人的带领下，以钱学森（胡亚捷 饰）、钱三强为代表的一大批中青年科学家克服种种难以想象的困难，在贫困经济条件、薄弱的技术基础和艰苦的工作条件下，在党中央的坚定支持下，以惊人的智慧与毅力﹐先后完成发射人造地球卫星、成功试爆原子弹、氢弹等一系列伟大壮举，创造出“两弹一星”的民族奇迹。', '3,14,19', '延艺', '陈怀国、陶纯', '刘劲、谢钢、史鑫、胡亚捷、韩中', 29, '', '1', '', '1', 1, '2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第二十七届中国电视金鹰奖优秀电视剧奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1140, '2012-12-19 08:00:00', '刘伯承元帅', 'http://39.106.153.224:8888/profile/upload/2025/02/22/刘伯承元帅_20250222002701A033.jpg', '该剧以刘伯承元帅（刘之冰 饰）的心路历程为主线，着重塑造他的品格、魅力、才华和胆魄。结构上，采用跳跃式创作手法，撷取最能表现人物性格的华彩段落，进行浓墨重彩的渲染，而不是平分笔墨的编年史式的描述。本剧将解读刘伯承如何从一个贫苦的“川娃子”成长为闻名中外的军事家，通过经典战例和敌我交锋的战争活剧，诠释刘伯承卓越的军事指挥艺术和战争制胜的谋略，生动地再现了他和他的战友们在中国革命历史的舞台上，为中华民族的自由和解放，征战沙场，九死一生的英雄传奇。', '3,14,18', '张玉中', '傅建文、尹东鸿', '刘之冰、王嘉、王晖、梁春书、刘沙', 33, '', '0', '', '1', 0, '2013年第二十九届中国电视剧飞天奖长篇电视剧二等奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1141, '2012-05-29 08:00:00', '知青', 'http://39.106.153.224:8888/profile/upload/2025/02/22/知青_20250222002729A034.jpg', '该剧讲述了1969年北大荒林区的一个雨夜，小火车载来了一批来自全国各大城市的知识青年。白桦林火车站的站长杨秉奎，望着一张张稚嫩而青春洋溢的脸，预感到这批人的到来，将会给北大荒带来翻天覆地的变化。1960年代末期，千百万北京、上海等大城市的红卫兵和老三届响应毛主席“知识青年到农村去，接受贫下中农的再教育，很有必要”的号召，奔赴全国各地农村生产建设兵团，谱写了一曲曲动人的青春之歌。在黑龙江生产建设兵团，涌现出赵天亮（唐曾 饰）、周萍（傅晶 饰）等一大批建设边疆、保卫边疆的有志青年。在陕北、山东屯涌现出赵曙光（程皓枫 饰）、冯晓兰（李欣凌 饰）、许蕾（周娟 饰）等志愿献身农村的知识青年，在城市家中，他（她）们大多是父母眼里的长不大的孩子，可是在边疆、在农村，他们成长为真正的战士，也有部分青年永远长眠在了那片土地上。', '9,10,13,19', '张新建、王滨、高力强', '梁晓声', '唐曾、傅晶、程皓枫', 45, '', '1', '', '1', 0, '2013年第二十九届中国电视剧飞天奖长篇电视剧三等奖。', NULL);
INSERT INTO `ds_film` VALUES (1142, '2012-10-21 08:00:00', '焦裕禄', 'http://39.106.153.224:8888/profile/upload/2025/02/22/焦裕禄_20250222002809A035.jpg', '该剧记述了焦裕禄（王洛勇 饰）一生成长与奋斗的人生轨迹。这位人民公仆的青少年时代，有着鲜为人知的传奇经历，他的故乡是诞生了孔、孟二圣的豫鲁交界之地，中华传统文化的濡染、孔、孟之乡深厚的文化积淀和故乡山水之钟毓灵秀，形成了这位大地之子生身的规定情境。在焦裕禄身上，体现着最典型的中华传统文化精神。命运曾给了焦裕禄令人难以置信的万千磨难，少年丧父、入监坐牢、下煤坑做苦力，背井离乡，受尽了日本侵略者的欺凌和富人的压迫。苦难的洗礼使他成为一个不向人生抵押自己命运的硬汉。投身革命，他又是一个为人敬佩的能文能武的孤胆英雄，当民兵、参加南下武装工作队、领导土改和清匪反霸，他以大智大勇、大爱大恨谱写了一曲羽声慷慨的英雄壮歌。在特殊的历史时期，他同自然灾害和自己的疾病展开了艰苦卓绝的斗争，直到生命最后一刻。他心里装着人民群众，却唯独没有他自己。他似乎是用共产党员的特殊材料造成的，他的眼睛能看到别人看不到的新生事物，他的耳朵能听到别人听不到的声音，他的嘴巴能说出别人不愿出口的话，他的手专做别人不做的事情。他在兰考县这块多灾多难的大地上，像一阵旋风，突然出现，又突然消失，他给兰考人留下的是思念的眼泪和奋斗不息的火焰。', '18,19', '李文岐', '何香久、陈新', '王洛勇、颜丙燕、高志强、李立群、王静', 30, '', '1', '', '1', 1, '2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第二十七届中国电视金鹰奖最佳电视剧奖、观众喜爱的电视剧男演员奖（王洛勇）、金鹰节最佳表演艺术奖（王洛勇）；2014年第十三届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1143, '2012-11-08 08:00:00', '杨善洲', 'http://39.106.153.224:8888/profile/upload/2025/02/22/杨善洲_20250222002833A036.jpg', '该剧讲述了杨善洲（刘佩琦 饰）的故事，生前曾任云南省保山地委书记，2010年10月10日因病逝世。他为官多年，但老母、妻子和三个女儿却一直在乡下艰辛生活。为了兑现自己当初“为当地群众做一点实事不要任何报酬”的承诺，退休后，主动放弃进省城安享晚年的机会，扎根大亮山，义务植树造林，一干就是22年，临终前将5.6万亩、价值3亿元的林场无偿上缴给国家。', '15,18,19', '张绍林', '石零', '刘佩琦、娜仁花、丁柳元、柏青', 23, '', '2', '', '1', 0, '2013年第二十九届中国电视剧飞天奖长篇电视剧二等奖、优秀导演奖（张绍林）。', NULL);
INSERT INTO `ds_film` VALUES (1144, '2012-09-29 08:00:00', '火蓝刀锋', 'http://39.106.153.224:8888/profile/upload/2025/02/22/火蓝刀锋_20250222002917A037.jpg', '该剧讲述蒋小鱼（杨志刚 饰）、鲁炎（郑凯 饰）、张冲（赫子铭 饰）和乌云（刘思言 饰）等新兵被特招进入海军陆战队后，经过几年的磨砺，渐渐树立起“为祖国的大海流尽最后一滴血”的信仰，蜕变成为新一代优秀海军战士的励志大戏。归国后的蒋小鱼组建龙鲨中队，我军的战斗力与日俱增。在与国际海盗殊死搏斗的危险任务中，成功地歼灭了海盗，完成了“把最后一滴血流入祖国的大海”的誓言。草根渔民蒋小鱼从“忽悠王”到“大英雄”的蜕变，成为影片的一大亮点，可圈可点。老兵柳小山、向羽等人对老兵形象的演绎也是真实感人，成为本片的“催泪弹”。', '6,19', '张国庆', '冯骥、徐速、王潇涵', '杨志刚、刘思言、樊昊仑、郑凯', 32, '', '2', '', '1', 0, '2013年第二十九届中国电视剧飞天奖长篇电视剧二等奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1145, '2012-07-14 08:00:00', '先遣连', 'http://39.106.153.224:8888/profile/upload/2025/02/22/先遣连_20250222003009A038.jpg', '该剧讲述了1950年2月，遵照毛泽东主席“解放西藏宜早不宜迟”的伟大号令，新疆军区独立骑兵师抽调汉、蒙、回、藏、维吾尔、哈萨克、锡伯等7个民族136人组成的进藏先遣连，以李狄三（王千源 饰）为代表的领导集体，率领着先遣连的一百三十六人，克服重重困难，跨越昆仑山脉，孤军挺进1000多公里，跋涉冰山雪河，穿越生命禁区，在高寒缺氧的情况下，进入茫无人迹的藏北高原，为西藏和平解放在雪域高原上战胜各种难以想象的困难，付出巨大牺牲，最终将五星红旗插上了阿里高原的故事。', '3,14', '范建会', '王元平（总）、公丕才、王喜民、田耀斌', '王千源、王新军、孙涛、王唯', 24, '', '1', '', '1', 1, '2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1146, '2012-12-25 08:00:00', '我的土地我的家', 'http://39.106.153.224:8888/profile/upload/2025/02/22/我的土地我的家_20250222003043A039.jpg', '该剧以1978年土地下放到户至今天为背景，描述了30年来农村改革开放的历程。以农民张老栓（张洪杰 饰）一家人的恩怨纠葛故事为缩影，讲述了农村和农民在改革开放的历史背景下，由贫穷走向富裕，由保守走向开放，与贫穷落后抗争的命运故事。正面反映改革开放给农村和农民带来的巨大变化和从生活到思想发生的巨大变革。', '12,15,19', '杨晶', '谭文峰、尹江春', '张洪杰、霍桠明、江佳奇、张铮', 24, '', '2', '', '1', 1, '2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第二十七届中国电视金鹰奖优秀电视剧奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1147, '2013-06-18 08:00:00', '寻路', 'http://39.106.153.224:8888/profile/upload/2025/02/22/寻路_20250222003301A040.jpg', '该剧讲述了1927年大革命失败后至1932年间，以毛泽东（由许铂岑 饰）为代表的中国共产党人，在革命根据地和国统区两条战线上坚持革命斗争的历程。在这一时期，中国共产党人在经历重重困难和挑战后，探索并坚持了适合中国国情的革命道路，展现了坚定的革命信仰和不屈不挠的斗争精神。剧中还展现了周恩来（刘劲 饰）等一批革命先驱的英勇事迹，以及他们在革命过程中的智慧和策略。不仅重现了中国共产党早期的重要历史时刻，如秋收起义、三湾改编、井冈山会师等，也深刻描绘了党内不同路线的交锋和斗争，体现了中国共产党在革命实践中不断摸索和前进的过程。通过艺术化的手法，该剧成功塑造了一系列血肉丰满的共产党人形象，为观众提供了丰富的精神滋养和审美享受，成为一部具有深刻历史意义和高度艺术价值的革命史诗。', '3,14,19', '张多福、刘娟', '王朝柱', '许铂岑、刘劲、马晓伟、罗忆楠', 44, '', '0', '', '1', 1, '2014年第十三届精神文明建设“五个一工程”优秀作品奖；2015年第三十届中国电视剧飞天奖优秀重大题材类电视剧奖；2014年第二十七届中国电视金鹰奖最佳电视剧奖。', NULL);
INSERT INTO `ds_film` VALUES (1148, NULL, '陈云', 'http://39.106.153.224:8888/profile/upload/2025/02/22/陈云_20250222003341A041.jpg', '该剧讲述了中国共产党重要领导人陈云（谢刚 饰）的生平故事。陈云出身贫寒，自幼失去双亲，由舅父母抚养成人。他的一生经历了中国革命和建设的多个重要时期，从在商务印书馆当学徒开始，逐步接触先进思想，到后来参加五卅运动和工人罢工运动，加入共产党，成为党内著名的“铁算盘”，以卓越的财经工作能力著称。', '3,14,18', '金韬', '张光荣', '谢钢、丛珊、王霙、李龙君', 30, '', '0', '', '1', 0, '2014年第十三届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1149, '2013-05-07 08:00:00', '阿娜尔罕', 'http://39.106.153.224:8888/profile/upload/2025/02/22/阿娜尔罕_20250222003356A042.jpg', '该剧讲述了在上世纪四十年代末期的南疆，美丽的阿娜尔罕（迪丽热巴饰）与英俊的库尔班（阿卜力克木·阿卜来提 饰）相爱，却因为大地主乌斯曼伯克的贪婪与权谋，使得两人的爱情之路充满坎坷。乌斯曼伯克（吐尔洪·伊明 饰）企图将阿娜尔罕献给专员伊明（尼加提·吐尔逊 饰）以求讨好，但遭到了阿娜尔罕和库尔班的坚决抵抗。乌斯曼伯克在愤怒之下设计陷害阿娜尔罕，导致她家破人亡。随着解放军的到来，阿娜尔罕和村民们看到了希望，而乌斯曼伯克和伊明却不愿接受现实，继续顽抗。在这段艰难的岁月中，阿娜尔罕展现了她的坚韧与不屈，最终迎来了新生活的曙光。', '9,19', '阎清秀、于德安', '程万里、兰小宁、阎清秀', '迪丽热巴、阿卜力克木·阿卜来提、吐尔洪·伊明、尼加提·吐尔逊', 20, '', '1', '', '1', 0, '2014年第十三届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1150, '2013-03-18 08:00:00', '幸福生活万年长', 'http://39.106.153.224:8888/profile/upload/2025/02/22/幸福生活万年长_20250222003449A043.jpg', '该剧以母亲河边的古镇为背景，讲述了万跃进（邵峰 饰）一家在面临环境治理和乡村振兴任务时的故事。万跃进，一位退居二线的老干部，主动承担起县里下达的垃圾清洁工作，致力于改善古镇环境。而他的妻子范跃进（李菁菁 饰）、女儿万改改、儿子万开开（褚栓忠 饰）、儿媳莉莉（王和平 饰）以及亲家曾淑平（尚国 饰）也在这个过程中扮演了不同的角色，共同推动了环保事业的发展。在老万的带领下，古镇的居民们克服了种种困难，实现了“植树造林，清洁垃圾，保护母亲河，建设新农村”的目标，赢得了县里领导的肯定。同时，年轻的书记马彦芳也因为老万的推荐得到了提升。老万一家也在这一年中喜事连连，儿子大婚、女儿出嫁、亲家再婚和孙子出生，象征着幸福生活的延续和传承。通过万家人的努力，古镇的环境得到了显著改善，山更绿、天更蓝、水更清，展现了一种积极向上、和谐共生的乡村振兴新面貌。', '8,15', '牛建荣', '牛建荣', '邵峰、李菁菁、褚栓忠、王和平、尚国伟', 28, '', '3', '', '1', 0, '2014年第十三届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1151, '2013-12-25 08:00:00', '毛泽东', 'http://39.106.153.224:8888/profile/upload/2025/02/22/毛泽东_20250222003608A044.jpg', '该剧讲述毛泽东（唐国强 饰）从韶山出生、读书求学、参加革命、建立国家、治理国家的历史。', '3,13,14', '高希希、嘉娜·沙哈提、赵立军、刘海波、宋海波', '黄晖、叶剑、全影、杨宏', '唐国强、侯京健、刘劲', 50, '', '0', '', '1', 0, '2014年第二十七届中国电视金鹰奖优秀电视剧奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1152, '2013-06-05 08:00:00', '我的故乡晋察冀', 'http://39.106.153.224:8888/profile/upload/2025/02/22/我的故乡晋察冀_20250222003633A045.jpg', '该剧以抗日战争时期的晋察冀边区为背景，讲述了从平型关大捷到开国大典这段历史时期内，保定山货店伙计耿三七（孙涛 饰）在去陕北送货途中遭遇危险，被八路军所救，从而毅然加入抗日队伍的故事。耿三七的成长经历与晋察冀地区的老百姓紧密相连，他们共同经历了十二年的浴血奋战和情感纠葛。剧中通过耿三七的视角，展现了晋察冀军民在中国共产党的领导下，如何团结一心、奋勇抗战，以及在艰苦环境下的不屈不挠和牺牲奉献。同时，剧中也深刻描绘了主人公与晋察冀老百姓之间的深厚情感，以及他们在战争与生活中所展现出的抗战精神和人性光辉。', '7,13,19', '马玉辉', '周振天', '孙涛、齐芳、文江、王强、杜旭东', 40, '', '0', '', '1', 0, '2014年第十三届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1153, '2014-10-06 08:00:00', '北平无战事', 'http://39.106.153.224:8888/profile/upload/2025/02/22/北平无战事_20250222003656A046.jpg', '该剧背景设定在1948年，国共两党决战的关键时刻。在国统区，政经体制混乱失控，物价飞涨，贪官横行，国民政府的统治岌岌可危。故事的主人公方孟敖（刘烨 饰），国民党空军笕桥航校上校教官，因违抗军令接受审判，却因蒋经国的干涉得以免罪，随后被转至国防部预备干部局。方孟敖出身富庶世家，是中央银行北平分行经理方步亭（王庆祥 饰）的公子，同时他也是我党潜伏在国军中的地下党员。方孟敖参与了“孔雀东南飞”行动，调查北平分行的舞弊行为。在这个过程中，他不仅要面对来自国军内部的猜忌和调查，还要应对同僚的暗算和倾轧，同时还要应对战火纷飞的险恶局势。方孟敖和其他地下工作者一起，以他们的智慧和勇气，为新中国的崛起奠定了基石。', '7', '孔笙、李雪', '刘和平', '刘烨、陈宝国、倪大红、王庆祥', 53, '', '0', '', '1', 1, '2015年第三十届中国电视剧飞天奖优秀重大题材类电视剧奖，优秀导演奖（孔笙）、优秀编剧奖（刘和平）、优秀男演员奖（陈宝国）；2015年第二十一届上海电视节白玉兰奖最佳中国电视剧奖、最佳编剧奖（刘和平）。', NULL);
INSERT INTO `ds_film` VALUES (1154, '2014-09-17 08:00:00', '马向阳下乡记', 'http://39.106.153.224:8888/profile/upload/2025/02/22/马向阳下乡记_20250222003725A047.jpg', '在官场摸爬滚打多年的马向阳（吴秀波 饰），虽然只是商务局市场科的一个小科长，却早已熟稔官场避实就虚、虚与委蛇的生存法则和太极推手。谁知突如其来的一纸调令，却将他从优哉游哉的城市达到了作为重点扶贫对象的穷乡僻壤。他从一位科长摇身一变成为大槐树村第一书记，但是这顶乌纱帽可真不那么好戴，从没有过乡村工作经验的他束手无策，不明所以，而当面对学识渊博且实践经验丰富的种植专家周冰（王雅捷 饰）、凭借血缘宗族关系在当地享有极高声望的族长刘世荣（李洪涛 饰） 性格泼辣的留守妇女代表李云芳（梁爱琪 饰）等不同身份之人的时候，许多问题似乎变得更不好解决。肩负着领导殷勤期望的马书记，能否升任这一新的岗位？', '15,19', '张永新', '谷凯', '吴秀波、王雅捷、李洪涛、梁爱琪', 40, '', '2', '', '1', 0, '2015年第三十届中国电视剧飞天奖优秀电视剧奖；2016年第二十八届中国电视金鹰奖优秀电视剧奖；2016年第十四届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1155, '2014-02-02 08:00:00', '父母爱情', 'http://39.106.153.224:8888/profile/upload/2025/02/22/父母爱情_20250222003753A048.jpg', '该剧以青岛某海军军区为背景，海军炮校丛校长（杨立新 饰）和妻子杨涛（娜仁花 饰）为军官举办婚介舞会，两人一心想为大龄军官们解决个人婚配问题。海军军官江德福（郭涛 饰）深受丛校长器重，在丛校长夫妇的引荐下，江德福在舞会上认识了年轻漂亮的安杰（梅婷 饰），并对她心生爱慕。而面对大老粗似的江德福，安杰却一点感觉都没有。由于安杰家庭成分不好，全家人屡次受到江德福的帮助，安杰渐渐发现了貌似粗犷的江德福其实是个机智、可爱的男人，她逐渐接受了江德福的情感，两人结为夫妻。江德福和安杰夫妻共同克服了出身的差异、文化程度的悬殊、生活环境的恶劣以及特殊时期的生存困境，抚养着五个孩子，共同走过了风风雨雨的几十年。孩子们长大成人，步入老年的江德福和安杰回首往事，觉得能携手度此一生是无比幸福的事情。', '12,13', '孔笙', '刘静', '郭涛、梅婷、刘琳、任帅', 44, '', '1', '', '1', 0, '2018年第二十四届上海电视节白玉兰奖国际传播奖', NULL);
INSERT INTO `ds_film` VALUES (1156, '2014-07-15 08:00:00', '湄公河大案', 'http://39.106.153.224:8888/profile/upload/2025/02/22/湄公河大案_20250222004017A049.jpeg', '该剧以湄公河惨案为背景，讲述了中国商船十三名船员在运输途中惨遭杀害后，中国警方迅速组成专案组前往老挝、缅甸、泰国交界的金三角地区进行调查的故事。专案组由江海峰（陈宝国 饰）领导，他们克服重重困难，逐步拨开案情迷雾，最终将嫌疑人锁定在以抢劫、敲诈、贩毒为生的苏沃集团身上。该剧通过紧张的刑侦过程和跨国合作，展现了中国警方的坚定意志和王杰精神，即忠诚、勇敢、智慧和奉献的精神。剧情不仅扣人心弦，也深刻地反映了国家对打击跨国犯罪、保护公民安全的决心和能力。', '1,2', '安战军、游达志（特邀）', '陈育新', '陈宝国、王千源、杜志国、李修贤', 34, '', '2', '', '1', 0, '2015年第三十届中国电视剧飞天奖优秀现实题材类电视剧奖、优秀男演员奖（陈宝国）。', NULL);
INSERT INTO `ds_film` VALUES (1157, '2021-01-12 08:00:00', '山海情', 'http://39.106.153.224:8888/profile/upload/2025/02/22/山海情_20250222005200A051.jpg', '该剧从政府建立吊庄基地，号召西吉的农民们移民、搬迁。但飞沙走石的荒漠条件太艰苦，搬迁来的村民第二天就走了一半的背景讲起。马得福（黄轩 饰）用尽各种办法动员大家去吊庄，并帮助村民们留下来。1996年，党中央作出推进东西部对口协作的战略部署，其中确定福建对口帮扶宁夏，共同推进宁夏扶贫工作。福建专家来到村里教村民们种蘑菇，让大家挣到了第一桶金，又想尽办法为蘑菇寻找销路。福建的干部们鼓励、带动宁夏的劳务输出，为村里人去福建打工积极创造条件。扶贫政策四面开花，闽宁镇初具规模。张树成（胡明 饰）走马上任闽宁镇的党委书记，继续三级扬水工程的同时，加强劳务输出、招商引资，闽宁镇旧貌换新颜，越来越多的村民们主动报名搬迁。时光飞逝，闽宁镇变得越来越好。这片土地焕发了新的生机。', '13,15,19', '孔笙、孙墨龙', '王三毛、未夕、小倔、磊子、邱玉洁、列那', '黄轩、张嘉益、闫妮、黄觉、姚晨', 23, '', '2', '', '1', 1, '2021年第二十七届上海电视节白玉兰奖最佳中国电视剧奖、最佳男配角奖（尤勇智）、最佳女配角奖（黄尧）、最佳摄影奖（杨振宇）；2022年中央宣传部第十六届精神文明建设“五个一工程”优秀作品奖；2022年第三十三届中国电视剧飞天奖优秀电视剧（时代·奋斗）、最佳编剧（王三毛、未夕、小倔、磊子、邱玉洁、列那）、优秀女演员（热依扎）；2022年第三十一届中国电视金鹰奖优秀电视剧奖；2022年第十六届精神文明建设“五个一工程”优秀作品奖；2023年第二十八届上海电视节白玉兰奖国际传播奖。', NULL);
INSERT INTO `ds_film` VALUES (1158, '2021-02-01 08:00:00', '觉醒年代', 'http://39.106.153.224:8888/profile/upload/2025/02/22/觉醒年代_20250222005057A050.jpg', '该剧以1915年《青年杂志》问世到1921年《新青年》成为中国共产党机关刊物为贯穿，展现了从新文化运动到中国共产党建立这段波澜壮阔的历史画卷，讲述觉醒年代的百态人生。该剧以李大钊（张桐 饰）、陈独秀（于和伟 饰）、胡适（朱刚日尧 饰）从相识、相知到分手，走上不同人生道路的传奇故事为基本叙事线，以毛泽东（侯京健 饰）、陈延年（张晚意 饰）、陈乔年（马启越 饰）、邓中夏（查文浩 饰）、赵世炎（林俊毅 饰）等革命青年追求真理的坎坷经历为辅助线，艺术地再现了一批名冠中华的文化大师和一群理想飞扬的热血青年演绎出的一段充满激情、燃烧理想的澎湃岁月，深刻地揭示了马克思主义与中国工人运动相结合和中国共产党建立的历史必然性。', '3,14,19', '张永新', '龙平平', '于和伟、张桐、马少骅、朱刚日尧', 43, '', '4', '', '1', 1, '2021年第二十七届上海电视节白玉兰奖最佳导演奖（张永新）、最佳编剧奖（原创）（龙平平）、最佳男主角奖（于和伟）；2022年第三十一届中国电视金鹰奖最佳电视剧奖、最佳电视剧编剧奖（龙平平）、最佳男配角奖（马少骅）；2022年第三十三届中国电视剧飞天奖优秀电视剧（信仰·使命）、优秀导演奖（张永新）；2022年第十六届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1163, '2020-09-29 08:00:00', '在一起', 'http://39.106.153.224:8888/profile/upload/2025/02/22/在一起_20250222005409A052.jpg', '该剧以“抗疫”期间各行各业真实的人物、故事为基础，由《生命的拐点》《摆渡人》《同行》《救护者》《搜索24小时》《火神山》《方舱》《我叫大连》《口罩》《武汉人》十个单元故事组成，讲述了中国军民在抗击新冠肺炎疫情中的人和事：他们中有义无反顾为人民建起一座白衣长城的医护工作者；有万里赴戎机、八方支援的各地医疗队员；有秉承革命军人优良传统、闻令而动、誓死不退的军医；有平凡又伟大的外卖小哥和专车志愿者；有自救互救、守望相助的普通市民；有积极投身火神山医院的建设者；有在联防联控工作中扎根基层的疾控、社区、公安人员；有误打误撞留在武汉成为志愿者投身抗疫事业的年轻人；有克服种种困难转产口罩、为“复产复工”做出贡献的人们。这些普通人构成了全国上下、各行各业抗击疫情的主力军，为抗击疫情做出不可磨灭的贡献。', '16,19', '张黎、沈严、曹盾、汪俊、韩晓军、刘江、滕华涛、林妍、彭三源、杨阳、杨文军、姚晓峰', '六六、秦雯、高璇、任宝茹、冯骥', '张嘉益、周一围、谭卓、雷佳音、张静初', 20, '', '3', '', '1', 1, '2021年第二十七届上海电视节白玉兰奖评委会大奖、国际传播奖；2022年第三十三届中国电视剧飞天奖优秀电视剧奖。', NULL);
INSERT INTO `ds_film` VALUES (1164, '2019-03-19 08:00:00', '共产党人刘少奇', 'http://39.106.153.224:8888/profile/upload/2025/02/22/共产党人刘少奇_20250222005451A053.jpg', '该剧讲述刘少奇同志一生，闯县城、省城、皇城和国门“四道乡关”，寻“实事求是、每求真是”“八字真经”，矢志找寻救国真理和建设新中国道路的故事！1921年，刘少奇（赵波 饰）在莫斯科东方大学入党。一年后他学成回国，领导了“安源路矿大罢工”。随着大革命形势骤然逆转，刘少奇于险恶情境中亲赴白区主持善后。抗战时期，刘少奇进入中央领导核心，并在建国后当选为中央人民政府副主席，在制定国家政治、经济、文化、教育、外交等方针政策方面发挥了重要作用。六十年代初期，中国经济发生严重困难，刘少奇又进行实地调查研究，参与制定了一系列重要的政策措施，使国民经济得到恢复和发展。1980年5月17日刘少奇追悼大会隆重举行，为中国革命和建设奋斗一生的刘少奇虽早已离开，但他坚定不移的共产主义信仰，将永垂不朽！', '13,14,18,19', '嘉娜·沙哈提', '海波', '赵波、侯京健、宋佳玲、徐百慧、张晚意', 46, '', '1', '', '1', 1, '2019第十五届精神文明建设“五个一工程”优秀作品奖；2020年第三十二届中国电视剧飞天奖优秀电视剧奖；2020年第三十届中国电视金鹰奖优秀电视剧奖。', NULL);
INSERT INTO `ds_film` VALUES (1165, '2018-12-10 08:00:00', '大江大河', 'http://39.106.153.224:8888/profile/upload/2025/02/22/大江大河_20250222005519A054.jpg', '该剧讲述了宋运辉（王凯 饰）天资聪颖却出身不好，一直备受歧视，但是他把握住了1978年恢复高考的机会，考上大学，勤学苦干，当上了国企的技术人员，在一步步晋升中奠定了成功人生的基础，然而，在新时代的变革中，他也经历了苦恼和迷茫的故事。宋运辉的姐夫雷东宝（杨烁 饰）出身贫寒，属于根正苗红的“大老粗”，行动力十足。在乡村改革的浪潮中，他带领村民紧跟政策，一直走在时代的前沿，但由于自身文化水平不高，眼界不够开阔，最终绊倒在新事物脚下。如果说宋运辉和雷东宝的经历是国营经济和集体经济的缩影，个体户杨巡（董子健 饰）无疑就是个体经济的典型代表。在翻滚向前的时代中，他手忙脚乱抓住过商机，也踩踏过陷阱，生意场上几经波折，最终拥有了自己的产业。', '13,15,19', '孔笙、黄伟', '袁克平、唐尧', '王凯、杨烁、董子健、童瑶', 47, '', '2', '', '1', 1, '2019年第二十五届上海电视节白玉兰奖最佳中国电视剧奖、最佳女配角奖（童瑶）、最佳导演奖（孔笙、黄伟）、最佳编剧奖（改编）（袁克平、唐尧）、最佳美术奖（邵昌勇）；2019年第十五届精神文明建设“五个一工程”优秀作品奖；2020年第三十届中国电视金鹰奖优秀中国电视剧奖、最佳导演奖（孔笙）、最佳女演员奖（童瑶）；2020年第三十二届中国电视剧飞天奖优秀电视剧奖。', NULL);
INSERT INTO `ds_film` VALUES (1166, '2021-09-26 08:00:00', '功勋', 'http://39.106.153.224:8888/profile/upload/2025/02/22/功勋_20250222011723A060.jpeg', '该剧用不同的叙事风格讲述八位功勋人物人生中最精彩的故事。《无名英雄于敏》章节从少年、青年和中年三个时期讲述于敏（雷佳音 饰）投身国防安全事业的故事。《申纪兰的提案》章节着重展现申纪兰（蒋欣 饰）首倡“男女同工同酬”并当选第一届全国人大代表的经历。《孙家栋的天路》章节以无数次的试验失败为切入点，展现以孙家栋（佟大为 饰）为代表的中国科学家永不言弃的探索精神。《能文能武李延年》章节讲述李延年（王雷 饰）在抗美援朝战场上的英雄故事。《默默无闻张富清》章节描绘张富清（郭涛 饰）作为战斗英雄转业后扎根基层的故事。《袁隆平的梦》章节从梦境展开，讲袁隆平（黄志忠 饰）如何为祖国和世界人民的温饱问题不懈奋斗。《黄旭华的深潜》章节以黄旭华（黄晓明 饰）研制核潜艇下潜极限为故事压力点和戏剧转折点，再现中国自主研发核潜艇的艰难历程。《屠呦呦的礼物》章节讲述屠呦呦（周迅 饰）研发抗疟新药青蒿素的全过程，并回答人们对屠呦呦获得诺贝尔奖的某些疑惑。', '3,18,19', '郑晓龙（总）、毛卫宁、沈严、康洪雷、林楠、杨文军、阎建钢、杨阳', '刘戈建、李修文、王小枪、陈枰、申捷、巩向东、徐速、王小平、宋方金', '王雷、雷佳音、郭涛、黄晓明、蒋欣', 48, '', '1', '', '1', 1, '2022年第三十三届中国电视剧飞天奖优秀电视剧奖、优秀男演员奖（王雷）；2022年第三十一届中国电视金鹰奖优秀电视剧奖；2022年中央宣传部第十六届精神文明建设“五个一工程”特别奖；2023年第二十八届上海电视节白玉兰奖评委会大奖。', NULL);
INSERT INTO `ds_film` VALUES (1167, '2022-01-09 08:00:00', '超越', 'http://39.106.153.224:8888/profile/upload/2025/02/22/超越_20250222010923A055.jpeg', '该剧以2015年北京申办2022年冬季奥运会成功为历史背景，讲述了“北冰南展”浪潮中，轮滑少女陈冕（李庚希 饰）决定以短道速滑为自己的事业目标，从一个非专业选手，一路过关斩将，最终进入国家队成为主力队员，出征冬奥赛场、为国争光的故事。', '9,16,19', '张晓波', '李嘉、雷博、杨柳伊、孙双润、张嘉运 、林若君', '李庚希、胡军、沙溢', 29, '', '3', '', '1', 1, '2022年第十六届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1168, '2022-12-07 08:00:00', '县委大院', 'http://39.106.153.224:8888/profile/upload/2025/02/22/县委大院_20250222010953A056.jpg', '该剧的故事发生在十九大前夕，梅晓歌（胡歌 饰）走马上任光明县县长，与县委书记吕青山（黄磊 饰）、副书记艾鲜枝（吴越 饰）等成为同事，此时摆在他们面前的是急需修复与发展的光明县，林林总总的难题和麻烦接踵而至。梅晓歌情商高，亲和力佳，逐渐和同事打成一片，平衡施政过程里的矛盾；又有破釜沉舟的勇气，到任后马不停蹄地走遍了光明县上百个村子。当选县委书记后，梅晓歌致力于推动深化改革干部作风，坚持绿色发展理念，在保护环境的基础上保障民生，对县城教育进行优化。在县委班子的努力之下，终于实现了光明县脱贫致富、健康发展的治县理想。年轻干部也在实践锻炼中不断成长，做好传承，推倒干部与群众之间的无形藩篱，干群关系焕然一新。', '19', '孔笙、毛珺琳、王宏', '王小枪', '胡歌、吴越、张新成、黄磊', 24, '', '3', '', '1', 1, '2023年第二十八届上海电视节白玉兰奖最佳中国电视剧奖、最佳编剧（原创）奖（王小枪）、最佳女主角奖（吴越）；2024年第三十二届中国电视金鹰奖优秀电视剧奖；2024年第十七届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1169, '2022-07-12 08:00:00', '大山的女儿', 'http://39.106.153.224:8888/profile/upload/2025/02/22/大山的女儿_20250222011015A057.jpg', '该剧根据真实事迹创作，讲述北师大硕士毕业的黄文秀（杨蓉 饰）主动放弃大城市的工作机会，回到生她养她的家乡，在百色市委宣传部任职，2018年3月，她主动请缨到广西最贫困的一个小山村百坭村任第一书记，白天她走村串户遍访贫困户，分析致贫原因，晚上与“村两委”研究脱贫对策，制定工作方案并全力推进。黄文秀克服困难、不懈努力，在一年多时间内让88户贫困户顺利脱贫。然而一场暴雨，却将黄文秀年轻的生命永远定格在了扶贫路上。虽然黄文秀牺牲了，但是扶贫并没有结束，其他人接过黄文秀的接力棒，努力使百坭村实现了全村脱贫。而之后，黄文秀为百坭村设计的愿景也一一实现，一个幸福的百坭村逐渐呈现在世人眼前。', '15,18,19', '雷献禾、王菁', '郭中束', '杨蓉、刘奕君、杜晓帆、涓子、李君峰', 40, '', '3', '', '1', 1, '2024年第十七届精神文明建设“五个一工程”优秀作品奖', NULL);
INSERT INTO `ds_film` VALUES (1170, '2022-05-28 08:00:00', '警察荣誉', 'http://39.106.153.224:8888/profile/upload/2025/02/22/警察荣誉_20250222011048A058.jpg', '该剧讲述的是见习警员李大为（张若昀 饰）、夏洁（白鹿 饰）、杨树（徐开骋 饰）和赵继伟（曹璐 饰）在派出所的工作与生活。一开始对警察这个职业怀抱各种憧憬，然而当面对巨大的工作压力、尖锐的矛盾冲突以及自媒体时代给派出所工作带来的新挑战时，他们经历了困惑与挫折，也有过迷茫、怀疑甚至放弃的念头，但在人民警察光荣传统的熏陶下，在老一辈的言传身教中，这4个年轻人经受住了考验，迅速成长，他们对自身的使命和荣誉有了新的认识，最终成长为合格的人民警察。', '16,19', '丁黑、鲍成志、符策欣', '赵冬苓、谭嘉言', '张若昀、白鹿、王景春、宁理', 38, '', '3', '', '1', 1, '2024年第三十二届中国电视金鹰奖最佳男配角奖（王景春）', NULL);
INSERT INTO `ds_film` VALUES (1171, '2023-12-12 08:00:00', '问苍茫', 'http://39.106.153.224:8888/profile/upload/2025/02/22/问苍茫_20250222011752A061.jpeg', '该剧讲述了1921年至1927年，从中共一大归来的青年毛泽东（王仁君 饰）带着对中华民族将走向何方的忧国之问，如何在矢志不移地践行马克思主义信仰的过程中，以一个“探路人”“早行者”的姿态，从一名追随者成长为先行者、开拓者，并探索出中国革命正确道路的历史故事。从发展团员、党员到发动工人运动，从国共第一次合作到坚决同国民党右派斗争，直到走进田间地头，用脚步丈量出农民运动对于中国革命的意义，青年毛泽东始终恪守着马克思主义和湖湘文化的精髓，向上成长，向下扎根，敢为人先，知行合一。“问苍茫大地，谁主沉浮？”，正是青年毛泽东及其同道的仰天长问和探寻之路，为中国革命开拓出辽阔新天。', '3,14,19', '王伟', '陈晋、梁振华、翁良平、韩辰辰、胡亚、颜西', '王仁君、宁理、白客、唐曾、嘉泽', 32, '', '4', '', '1', 1, '2024年第二十九届上海电视节白玉兰奖评委会奖；2024年第三十二届中国电视金鹰奖优秀电视剧奖；2024年第十七届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1172, '2024-02-06 08:00:00', '南来北往', 'http://39.106.153.224:8888/profile/upload/2025/02/22/南来北往_20250222011316A059.jpeg', '该剧讲述二十世纪七十年代末，离乡十年归来的老刑警马魁（丁勇岱 饰）与年少气盛优秀的年轻乘警汪新（白敬亭 饰），师徒二人从相互不满，矛盾重重，误解不断到携手作战，默契配合。通过一列火车的人生百态，一群邻里间的人情冷暖，见证伟大祖国的革新与发展，新老两代铁路干警警魂精神薪火传承的故事。', '13,16', '郑晓龙、刘璋牧', '高满堂、李洲', '白敬亭、丁勇岱、金晨、姜妍', 39, '', '2', '', '1', 1, '2024年第二十九届上海电视节白玉兰奖最佳女配角奖（姜妍）；2024年第十七届精神文明建设“五个一工程”优秀作品奖。', NULL);
INSERT INTO `ds_film` VALUES (1173, '2021-07-01 08:00:00', '革命者', 'http://39.106.153.224:8888/profile/upload/2025/02/22/革命者_20250222012818A062.jpeg', '该片聚焦“中国共产主义运动先驱李大钊”的电影，讲述了在1912至1927年间，李大钊引领一众革命志士为救国存亡积极奔走、奋起反抗的壮阔革命历史故事。', '3,14,19', '徐展雄', '管虎、吴兵、张珂、京榆', '张颂文、佟丽娅 、成泰燊、彭昱畅 ', NULL, '', '4', '', '0', 1, '', NULL);
