INSERT INTO `sys_oper_log` VALUES (612, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '127.0.0.1', '内网IP', '{\"id\":[\"1\"],\"annual\":[\"2025-01-09\"],\"tvSeries\":[\"骗骗喜欢你\"],\"img\":[\"http://127.0.0.1:8888/profile/upload/2025/02/01/OIP _2__20250201094000A003.png\"],\"topicContent\":[\"该剧以一户普通人家的原生态纪实，与中国改革开放30多年社会转型变化的大历史交汇同构，呈现一代创业者的智慧、意志和情怀。20世纪80年代改革开放初期，在温州创业潮兴起之时，温州瑞安古树村的周万顺（李立群 饰）毅然决定将年仅13岁的女儿周阿雨（殷桃 饰）只身送往意大利。自己则把祖屋和全部家当卖掉，带着妻子赵银花（迟蓬 饰）和儿子周麦狗（张译 饰）背井离乡徒步来到温州。到温州后进城的周万顺从拾荒做起，一步一步变身为成功商人。爱面子又叛逆的周麦狗为了摆脱父亲，羞愤之中离家出走大西北，开始了自己的艰辛创业路。而远在意大利的周阿雨排除万难从洗碗工做起，凭借出色的商业头脑在意大利普拉托成功创业。剧中，走在最前沿的温州商人前赴后继走出家门、走出国门，他们的命运紧系时代的脉搏。\"],\"type\":[\"0\",\"1\",\"7\",\"17\"],\"director\":[\"张三\"],\"screenwriter\":[\"李四\"],\"actor\":[\"王五、赵六\"],\"episodeNum\":[\"\"],\"reasons\":[\"不知道啊阿达\"],\"chronologicalDivision\":[\"4\"],\"url\":[\"www.baidu.com\"],\"kind\":[\"0\"],\"recommend\":[\"1\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-04 22:14:10', 38);
INSERT INTO `sys_oper_log` VALUES (613, '影视管理', 1, 'com.ds.project.front.film.controller.DsFilmController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/film/add', '127.0.0.1', '内网IP', '{\"annual\":[\"2025-01-08\"],\"tvSeries\":[\"骗骗喜欢你111111111111\"],\"img\":[\"http://127.0.0.1:8888/profile/upload/2025/02/04/OIP _4__20250204221429A001.png\"],\"topicContent\":[\"\"],\"type\":[\"7\",\"14\"],\"director\":[\"张三\"],\"screenwriter\":[\"李四\"],\"actor\":[\"王五、赵六\"],\"episodeNum\":[\"\"],\"reasons\":[\"不知道啊阿达\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"www.baidu.com\"],\"kind\":[\"0\"],\"recommend\":[\"1\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-04 22:14:37', 8);
INSERT INTO `sys_oper_log` VALUES (614, '文章管理', 2, 'com.ds.project.front.article.controller.DsArticleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/article/edit', '127.0.0.1', '内网IP', '{\"id\":[\"1\"],\"srcDatabase\":[\"报纸\"],\"title\":[\"在纪念毛泽东同志诞辰130周年座谈会上的发言\"],\"author\":[\"苗华2\"],\"organ\":[\"中央军委;中央军委政治工作部;\"],\"source\":[\"人民日报\"],\"keyword\":[\"毛泽东;人民军队;毛泽东军事思想;座谈会;\"],\"summary\":[\"毛泽东同志是伟大的马克思主义者，伟大的无产阶级革命家、战略家、理论家，是人民军队的主要缔造者，波澜壮阔的军事实践是他伟大革命生涯中的光辉篇章。回顾缅怀毛泽东同志创建和领导人民军队的丰功伟绩和精神风范，对于我们坚定沿着党指引的方向前进，锚定建军一百年奋斗目\"],\"pubTime\":[\"2024-08-01\"],\"articleText\":[\"https://www.baidu.com/\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-10 10:29:03', 74);
INSERT INTO `sys_oper_log` VALUES (615, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '127.0.0.1', '内网IP', '{\"id\":[\"1\"],\"annual\":[\"2025-01-09\"],\"tvSeries\":[\"骗骗喜欢你2\"],\"img\":[\"http://127.0.0.1:8888/profile/upload/2025/02/01/OIP _2__20250201094000A003.png\"],\"topicContent\":[\"该剧以一户普通人家的原生态纪实，与中国改革开放30多年社会转型变化的大历史交汇同构，呈现一代创业者的智慧、意志和情怀。20世纪80年代改革开放初期，在温州创业潮兴起之时，温州瑞安古树村的周万顺（李立群 饰）毅然决定将年仅13岁的女儿周阿雨（殷桃 饰）只身送往意大利。自己则把祖屋和全部家当卖掉，带着妻子赵银花（迟蓬 饰）和儿子周麦狗（张译 饰）背井离乡徒步来到温州。到温州后进城的周万顺从拾荒做起，一步一步变身为成功商人。爱面子又叛逆的周麦狗为了摆脱父亲，羞愤之中离家出走大西北，开始了自己的艰辛创业路。而远在意大利的周阿雨排除万难从洗碗工做起，凭借出色的商业头脑在意大利普拉托成功创业。剧中，走在最前沿的温州商人前赴后继走出家门、走出国门，他们的命运紧系时代的脉搏。\"],\"type\":[\"0\",\"1\",\"7\",\"17\"],\"director\":[\"张三\"],\"screenwriter\":[\"李四\"],\"actor\":[\"王五、赵六\"],\"episodeNum\":[\"21\"],\"reasons\":[\"不知道啊阿达\"],\"chronologicalDivision\":[\"4\"],\"url\":[\"www.baidu.com\"],\"kind\":[\"0\"],\"recommend\":[\"1\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-10 10:29:14', 7);
