INSERT INTO `sys_oper_log` VALUES (695, '关于我们', 2, 'com.ds.project.front.me.controller.DsAboutMeController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/me/edit', '127.0.0.1', '内网IP', '{\"id\":[\"1\"],\"text\":[\"<b>华为致力于把数字世界带入每个人</b>、<u>每个家庭、每个组织，构建万物</u>互联的智能世界：让无处不在的联接，成为人人平等的权利，成为智能世界的前提和基础；<span style=\\\"background-color: rgb(181, 214, 165);\\\">为世界提供多样性算力，让云无处</span>不在，让智能无所不及；所有的行业和组织，因强大的数字平台而变得敏捷、高效、生机勃勃；通过AI重新定义体验，让消费者在家居、出行、办公、影音娱乐、运动健康等全场景获得极致的个性化智慧体验。华为致力于把数字世界带入每个人、每个家庭、每个组织，构建万物互联的智能世界：让无处不在的联接，成为人人平等的权利，成为智能世界的前提和基础；为世界提供多样性算力，让云无处不在，让智能无所不及；所有的行业和组织，因强大的数字平台而变得敏捷、高效、生机勃勃；通过AI重新定义体验，让消费者在家居、出行、办公、影音娱乐、运动健康等全场景获得极致的个性化智慧体验。华为致力于把数字世界带入每个人、每个家庭、每个组织，构建万物互联的智能世界：让无处不在的联接，成为人人平等的权利，成为智能世界的前提和基础；为世界提供多样性算力，让云无处不在，让智能无所不及；所有的行业和组织，因强大的数字平台而变得敏捷、高效、生机勃勃；通过AI重新定义体验，让消费者在家居、出行、办公、影音娱乐、运动健康等全场景获得极致的个性化智慧体验。\"],\"phone\":[\"1355555132\"],\"address\":[\"广东省 / 北京市 / 台湾县 / 上海村 \"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-15 14:32:59', 49);
