INSERT INTO `sys_oper_log` VALUES (732, '党史标题管理', 3, 'com.ds.project.front.title.controller.DsTitleController.remove()', 'GET', 1, 'admin', '研发部门', '/front/title/remove/107', '223.72.68.45', 'XX XX', '107', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 08:49:41', 11);
INSERT INTO `sys_oper_log` VALUES (733, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"井冈山精神\"],\"briefIntroduction\":[\"井冈山时期留给我们最为宝贵的财富，就是跨越时空的井冈山精神。井冈山精神，最重要的方面就是坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利。\\r\\n\\r\\n——摘自习近平同志《论中国共产党历史》\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 08:56:30', 23);
INSERT INTO `sys_oper_log` VALUES (734, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"160\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"井冈山时期留给我们最为宝贵的财富，就是跨越时空的井冈山精神。井冈山精神，最重要的方面就是坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利。\\r\\n\\r\\n               ——摘自习近平同志《论中国共产党历史》\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 08:56:59', 14);
INSERT INTO `sys_oper_log` VALUES (735, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"苏区精神\"],\"briefIntroduction\":[\"在革命根据地的创建和发展中，在建立红色政权、探索革命道路的实践中，无数革命先辈用鲜血和生命铸就了以坚定信念、求真务实、一心为民、清正廉洁、艰苦奋斗、争创一流、无私奉献等为主要内涵的苏区精神。\\r\\n——摘自习近平同志在纪念中央革命根据地创建暨中华苏维埃共和国成立80周年座谈会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 09:00:36', 20);
INSERT INTO `sys_oper_log` VALUES (736, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"长征精神\"],\"briefIntroduction\":[\"伟大长征精神，就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神；就是为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲的精神；就是坚持独立自主、实事求是，一切从实际出发的精神；就是顾全大局、严守纪律、紧密团结的精神；就是紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的精神。\\r\\n——摘自习近平总书记在纪念红军长征胜利80周年大会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 09:01:24', 21);
INSERT INTO `sys_oper_log` VALUES (737, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"遵义会议精神\"],\"briefIntroduction\":[\"遵义会议作为我们党历史上一次具有伟大转折意义的重要会议，在把马克思主义基本原理同中国具体实际相结合、坚持走独立自主道路、坚定正确的政治路线和政策策略、建设坚强成熟的中央领导集体等方面，留下宝贵经验和重要启示。我们要运用好遵义会议历史经验，让遵义会议精神永放光芒。\\r\\n——摘自习近平总书记2015年6月16日至18日在贵州调研时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 09:01:49', 18);
INSERT INTO `sys_oper_log` VALUES (738, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"延安精神\"],\"briefIntroduction\":[\"延安精神培育了一代代中国共产党人，是我们党的宝贵精神财富。要坚持不懈用延安精神教育广大党员、干部，用以滋养初心、淬炼灵魂，从中汲取信仰的力量、查找党性的差距、校准前进的方向。\\r\\n——摘自2020年4月习近平总书记在陕西考察时的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 09:02:13', 39);
INSERT INTO `sys_oper_log` VALUES (739, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"抗战精神\"],\"briefIntroduction\":[\"中国人民在抗日战争的壮阔进程中孕育出伟大抗战精神，向世界展示了天下兴亡、匹夫有责的爱国情怀，视死如归、宁死不屈的民族气节，不畏强暴、血战到底的英雄气概，百折不挠、坚忍不拔的必胜信念。\\r\\n——摘自习近平总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利75周年座谈会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 09:02:33', 26);
INSERT INTO `sys_oper_log` VALUES (740, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"红岩精神\"],\"briefIntroduction\":[\"重庆要运用这些红色资源，教育引导广大党员、干部坚定理想信仰，养成浩然正气，增强“四个意识”、坚定“四个自信”、做到“两个维护”，始终在政治立场、政治方向、政治原则、政治道路上同党中央保持高度一致。\\r\\n——摘自习近平总书记2019年4月17日在重庆考察时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 09:03:21', 29);
INSERT INTO `sys_oper_log` VALUES (741, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"166\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"红岩精神是中国共产党在国民党统治地区革命实践中形成的革命精神，有着丰富的内涵。在国民党反动派实施的白色恐怖下，一大批共产党人置个人安危于不顾，把天下兴亡的责任担在肩上，为革命奉献自己的全部力量，甚至不惜牺牲生命，展现了坚如磐石的理想信念；以民族大义为重，以人民利益为先，始终坚持党的群众路线，广泛团结国统区抗日民主力量，积极巩固和扩大抗日民族统一战线，展现了和衷共济的爱国情怀；创造性地贯彻执行党的抗日民族统一战线，与国民党的妥协投降势力作坚决斗争，狱中同志经受住酷刑的折磨和高官厚禄的诱惑，坚持斗争到底，在生命即将走向终点时用鲜血和生命总结出“狱中八条”，展现了艰苦卓绝的凛然斗志；众多被关押在渣滓洞、白公馆的中国共产党人，“粉身碎骨浑不怕，要留清白在人间”，坚持操守、宁死不屈，展现了百折不挠的浩然正气。红岩精神是中国共产党人精神谱系的重要组成部分，成为中华民族的宝贵精神财富。——《弘扬红岩精神，赓续红色血脉》原刊于《 人民日报 》（ 2021年10月21日 01 版）\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 09:06:30', 17);
INSERT INTO `sys_oper_log` VALUES (742, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"166\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"红岩精神是中国共产党在国民党统治地区革命实践中形成的革命精神，有着丰富的内涵。在国民党反动派实施的白色恐怖下，一大批共产党人置个人安危于不顾，把天下兴亡的责任担在肩上，为革命奉献自己的全部力量，甚至不惜牺牲生命，展现了坚如磐石的理想信念；以民族大义为重，以人民利益为先，始终坚持党的群众路线，广泛团结国统区抗日民主力量，积极巩固和扩大抗日民族统一战线，展现了和衷共济的爱国情怀；创造性地贯彻执行党的抗日民族统一战线，与国民党的妥协投降势力作坚决斗争，狱中同志经受住酷刑的折磨和高官厚禄的诱惑，坚持斗争到底，在生命即将走向终点时用鲜血和生命总结出“狱中八条”，展现了艰苦卓绝的凛然斗志；众多被关押在渣滓洞、白公馆的中国共产党人，“粉身碎骨浑不怕，要留清白在人间”，坚持操守、宁死不屈，展现了百折不挠的浩然正气。——《弘扬红岩精神，赓续红色血脉》原刊于《 人民日报 》（ 2021年10月21日 01 版）\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 09:08:41', 16);
INSERT INTO `sys_oper_log` VALUES (743, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"166\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"红岩精神是中国共产党在国民党统治地区革命实践中形成的革命精神，有着丰富的内涵。在国民党反动派实施的白色恐怖下，一大批共产党人置个人安危于不顾，把天下兴亡的责任担在肩上，为革命奉献自己的全部力量，甚至不惜牺牲生命，展现了坚如磐石的理想信念，展现了和衷共济的爱国情怀，展现了百折不挠的浩然正气。——《弘扬红岩精神，赓续红色血脉》原刊于《 人民日报 》（ 2021年10月21日 01 版）\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:07:55', 17);
INSERT INTO `sys_oper_log` VALUES (744, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"166\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"红岩精神是中国共产党在国民党统治地区革命实践中形成的革命精神，在国民党反动派实施的白色恐怖下，一大批共产党人置个人安危于不顾，把天下兴亡的责任担在肩上，为革命奉献自己的全部力量，甚至不惜牺牲生命，展现了坚如磐石的理想信念，展现了和衷共济的爱国情怀，展现了百折不挠的浩然正气。——《弘扬红岩精神，赓续红色血脉》原刊于《 人民日报 》（ 2021年10月21日 01 版）\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:08:38', 19);
INSERT INTO `sys_oper_log` VALUES (745, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"西柏坡精神\"],\"briefIntroduction\":[\"全党同志要不断学习领会“两个务必”的深邃思想，始终做到谦虚谨慎、艰苦奋斗、实事求是、一心为民，继续把人民对我们党的“考试”、把我们党正在经受和将要经受各种考验的“考试”考好，使我们的党永远不变质、我们的红色江山永远不变色。\\r\\n——摘自习近平总书记2013年在河北省调研指导党的群众路线教育实践活动时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:22:03', 20);
INSERT INTO `sys_oper_log` VALUES (746, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"照金精神\"],\"briefIntroduction\":[\"以照金为中心的陕甘边革命根据地，在中国革命史上写下了光辉的一页。要加强对革命根据地历史的研究，总结历史经验，更好发扬革命精神和优良作风。\\r\\n——摘自习近平总书记2015年2月14日在陕西考察时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:23:56', 18);
INSERT INTO `sys_oper_log` VALUES (747, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"东北抗联精神\"],\"briefIntroduction\":[\"九一八事变后，中国人民就在白山黑水间奋起抵抗，成为中国人民抗日战争的起点，同时揭开了世界反法西斯战争的序幕。\\r\\n——摘自习近平总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利75周年座谈会上的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:25:00', 17);
INSERT INTO `sys_oper_log` VALUES (748, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"南泥湾精神\"],\"briefIntroduction\":[\"延安是革命圣地。延安时期是我们党领导的中国革命事业从低潮走向高潮、实现历史性转折的时期。老一辈革命家和老一代共产党人在延安时期留下的优良传统和作风，培育形成的以坚定正确的政治方向、解放思想实事求是的思想路线、全心全意为人民服务的根本宗旨、自力更生艰苦奋斗的创业精神为主要内容的延安精神，是我们党的宝贵精神财富。\\r\\n——摘自习近平总书记2015年2月15日在陕西考察工作结束时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:25:23', 17);
INSERT INTO `sys_oper_log` VALUES (749, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"太行精神/吕梁精神\"],\"briefIntroduction\":[\"山西也是具有光荣革命传统的地方，是八路军总部所在地，是抗日战争主战场之一，建立了晋绥、晋察冀、晋冀鲁豫抗日根据地，平型关大捷、百团大战等闻名中外，太行精神、吕梁精神是我们党宝贵的精神财富。这些都要充分挖掘和利用，以丰富多彩的历史文化、红色文化资源为山西发展提供精神力量。\\r\\n——摘自习近平总书记2020年5月在山西考察时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:25:47', 19);
INSERT INTO `sys_oper_log` VALUES (750, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"大别山精神\"],\"briefIntroduction\":[\"鄂豫皖苏区根据地是我们党的重要建党基地，焦裕禄精神、红旗渠精神、大别山精神等都是我们党的宝贵精神财富。\\r\\n——摘自习近平总书记2019年9月在河南考察时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:26:03', 26);
INSERT INTO `sys_oper_log` VALUES (751, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"沂蒙精神\"],\"briefIntroduction\":[\"沂蒙精神与延安精神、井冈山精神、西柏坡精神一样，是党和国家的宝贵精神财富，要不断结合新的时代条件发扬光大。军民水乳交融、生死与共铸就的沂蒙精神，对我们今天抓党的建设仍然具有十分重要的启示作用。\\r\\n——摘自习近平总书记2013年11月在山东考察时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:26:28', 17);
INSERT INTO `sys_oper_log` VALUES (752, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"老区精神\"],\"briefIntroduction\":[\"老区和老区人民，为我们党领导的中国革命作出了重大牺牲和贡献。这些牺牲和贡献永远镌刻在中国共产党、中国人民解放军、中华人民共和国的历史丰碑上。我们要永远珍惜、永远铭记老区和老区人民的这些牺牲和贡献，继承和发扬老区和老区人民的光荣传统，为实现“两个一百年”奋斗目标、实现中华民族伟大复兴的中国梦而不懈奋斗！\\r\\n——摘自习近平总书记2015年在陕甘宁革命老区脱贫致富座谈会上的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:26:51', 23);
INSERT INTO `sys_oper_log` VALUES (753, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"张思德精神\"],\"briefIntroduction\":[\"全心全意为人民服务是党的根本宗旨。延安时期，毛泽东同志在追悼张思德同志时发表的《为人民服务》的演讲，深刻揭示了党群关系、干群关系、军民关系的真谛。\\r\\n——摘自习近平总书记2015年2月15日在陕西考察工作结束时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-18 11:27:07', 17);
INSERT INTO `sys_oper_log` VALUES (754, '影视管理', 1, 'com.ds.project.front.film.controller.DsFilmController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/film/add', '116.22.146.157', 'XX XX', '{\"annual\":[\"\"],\"tvSeries\":[\"天空之城\"],\"img\":[\"\"],\"topicContent\":[\"阿丹哇塞擦大王从阿丹哇塞擦大王从阿丹哇塞擦大王从阿丹哇塞擦大王从阿丹哇塞擦大王从阿丹哇塞擦大王从阿丹哇塞擦大王从阿丹哇塞擦大王从阿丹哇塞擦大王从\"],\"type\":[\"1\",\"8\"],\"director\":[\"小明\"],\"screenwriter\":[\"小明\"],\"actor\":[\"小明\"],\"episodeNum\":[\"\"],\"reasons\":[\"小明阿德哇擦兄弟\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"0\"],\"recommend\":[\"1\"],\"awardInformation\":[\"\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 07:50:48', 204);
INSERT INTO `sys_oper_log` VALUES (755, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '183.6.35.39', 'XX XX', '{\"id\":[\"850\"],\"annual\":[\"\"],\"tvSeries\":[\"领袖\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/19/a_20250219091641A001.png\"],\"topicContent\":[\"该剧剧聚焦遵义会议前后以毛泽东（王霙饰）为核心的第一代领导人的奋斗历程，以纪念毛泽东诞辰120周年。遵义会议之前，历届党的领导人大多听命于共产国际，主张“城市中心论”。六届四中全会，王明、博古等人进入中央委员会。此后，博古请来了李德，把教条主义推向顶峰，不仅丢失了用生命和鲜血换来的中央苏区，而且把党和军队引到了灭亡的边缘。历史的教训，现实的拷问，使得党的领导集体在独立思考中开始了对领路人的认识和选择。周恩来主动检讨自己，张闻天、王稼祥选择自我扬弃，他们共同推举了毛泽东。剧本选取我党我军历史上这一动荡最激烈、斗争最尖锐、变化最深刻的转折阶段，全景式展示了长征前后红军前仆后继的革命历程，形象化地展现了第一代领袖集体形成的时代风云和历史必然性。\"],\"director\":[\"石伟\"],\"screenwriter\":[\"邵钧林\"],\"actor\":[\"王霙、郭广平、洪涛、温峥嵘、曾昂\"],\"episodeNum\":[\"36\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2014第十三届精神文明建设“五个一工程”奖优秀作品奖\"],\"type\":[\"\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 09:16:43', 174);
INSERT INTO `sys_oper_log` VALUES (756, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '183.6.35.39', 'XX XX', '{\"id\":[\"850\"],\"annual\":[\"\"],\"tvSeries\":[\"领袖\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/19/a_20250219095214A001.png\"],\"topicContent\":[\"该剧剧聚焦遵义会议前后以毛泽东（王霙饰）为核心的第一代领导人的奋斗历程，以纪念毛泽东诞辰120周年。遵义会议之前，历届党的领导人大多听命于共产国际，主张“城市中心论”。六届四中全会，王明、博古等人进入中央委员会。此后，博古请来了李德，把教条主义推向顶峰，不仅丢失了用生命和鲜血换来的中央苏区，而且把党和军队引到了灭亡的边缘。历史的教训，现实的拷问，使得党的领导集体在独立思考中开始了对领路人的认识和选择。周恩来主动检讨自己，张闻天、王稼祥选择自我扬弃，他们共同推举了毛泽东。剧本选取我党我军历史上这一动荡最激烈、斗争最尖锐、变化最深刻的转折阶段，全景式展示了长征前后红军前仆后继的革命历程，形象化地展现了第一代领袖集体形成的时代风云和历史必然性。\"],\"director\":[\"石伟\"],\"screenwriter\":[\"邵钧林\"],\"actor\":[\"王霙、郭广平、洪涛、温峥嵘、曾昂\"],\"episodeNum\":[\"36\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2014第十三届精神文明建设“五个一工程”奖优秀作品奖\"],\"type\":[\"\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 09:52:15', 191);
INSERT INTO `sys_oper_log` VALUES (757, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '183.6.35.39', 'XX XX', '{\"id\":[\"845\"],\"annual\":[\"\"],\"tvSeries\":[\"历史转折中\"],\"img\":[\"\"],\"topicContent\":[\"该剧以1976年9月9日伟大的开国领袖毛泽东同志与世长辞为背景。毛泽东同志的离去宣告了一个时代的结束，也开启了新时代的序幕。祸害华夏大地十年之久的四人帮一朝被除，而千疮百孔的新中国其明天依旧迷蒙不清。已经三度被打倒的邓小平（马少骅 饰）接受中央的安排，重新出来主持工作。此时党内对邓的争论两极分化，而“两个凡是”又预示着左倾错误的继续。十一届三中全会上，邓小平批驳反思的建国以来党在治国方针和思想上锁犯下的错误，此后大力推行国防教育，积极推进经济建设。将近十年的改革，让羸弱不堪的新中国获得重生的希望，而他便是那个踏出坚实步伐的重要之人\"],\"director\":[\"吴子牛\"],\"screenwriter\":[\"张强、魏人、龙平平、黄亚洲\"],\"actor\":[\"马少骅、萨日娜、曾红生、张嘉益\"],\"episodeNum\":[\"48\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"2\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2014年第十三届精神文明建设“五个一工程”奖优秀作品奖；2015年第三十届优秀电视剧“飞天奖”；2016年第二十八届中国优秀电视剧“金鹰奖”，最佳表演艺术奖（李雪健）\"],\"type\":[\"\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 09:53:02', 18);
INSERT INTO `sys_oper_log` VALUES (758, '文章搜索词管理', 1, 'com.ds.project.front.terms.controller.DsSearchArticleTermsController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/terms/add', '223.72.68.45', 'XX XX', '{\"titleId\":[\"108\"],\"deptName\":[\"社会主义革命和建设时期\"],\"searchTerms\":[\"塞罕坝精神A\"]}', NULL, 1, '只能在层级3中添加小标题', '2025-02-19 14:35:51', 10);
INSERT INTO `sys_oper_log` VALUES (759, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"塞罕坝精神A\"],\"briefIntroduction\":[\"\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:36:16', 27);
INSERT INTO `sys_oper_log` VALUES (760, '党史标题管理', 3, 'com.ds.project.front.title.controller.DsTitleController.remove()', 'GET', 1, 'admin', '研发部门', '/front/title/remove/176', '223.72.68.45', 'XX XX', '176', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:36:42', 25);
INSERT INTO `sys_oper_log` VALUES (761, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"抗美援朝精神\"],\"briefIntroduction\":[\"在波澜壮阔的抗美援朝战争中，英雄的中国人民志愿军始终发扬祖国和人民利益高于一切、为了祖国和民族的尊严而奋不顾身的爱国主义精神，英勇顽强、舍生忘死的革命英雄主义精神，不畏艰难困苦、始终保持高昂士气的革命乐观主义精神，为完成祖国和人民赋予的使命、慷慨奉献自己一切的革命忠诚精神，为了人类和平与正义事业而奋斗的国际主义精神，锻造了伟大抗美援朝精神。\\r\\n——摘自习近平总书记在纪念中国人民志愿军抗美援朝出国作战70周年大会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:37:36', 30);
INSERT INTO `sys_oper_log` VALUES (762, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"“两弹一星”精神\"],\"briefIntroduction\":[\"希望广大科技工作者不忘初心、牢记使命，秉持国家利益和人民利益至上，继承和发扬老一辈科学家胸怀祖国、服务人民的优秀品质，弘扬“两弹一星”精神，主动肩负起历史重任，把自己的科学追求融入建设社会主义现代化国家的伟大事业中去。\\r\\n——摘自习近平总书记在科学家座谈会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:38:02', 51);
INSERT INTO `sys_oper_log` VALUES (763, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"雷锋精神\"],\"briefIntroduction\":[\"我们既要学习雷锋的精神，也要学习雷锋的做法，把崇高理想信念和道德品质追求转化为具体行动，体现在平凡的工作生活中，作出自己应有的贡献，把雷锋精神代代传承下去。\\r\\n——摘自习近平总书记在参观抚顺市雷锋纪念馆时的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:38:19', 28);
INSERT INTO `sys_oper_log` VALUES (764, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"焦裕禄精神\"],\"briefIntroduction\":[\"要特别学习弘扬焦裕禄同志“心中装着全体人民、唯独没有他自己”的公仆情怀，凡事探求就里、“吃别人嚼过的馍没味道”的求实作风，“敢教日月换新天”、“革命者要在困难面前逞英雄”的奋斗精神，艰苦朴素、廉洁奉公、“任何时候都不搞特殊化”的道德情操。\\r\\n——摘自习近平总书记在调研指导兰考县党的群众路线教育实践活动时的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:38:39', 32);
INSERT INTO `sys_oper_log` VALUES (765, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"红旗渠精神\"],\"briefIntroduction\":[\"红旗渠建设中，孕育形成了“自力更生、艰苦创业、团结协作、无私奉献”的红旗渠精神，引领着勤劳勇敢的林州人民“又踏层峰望眼开”，谱写了“战太行、出太行、富太行、美太行、福太行”的发展五部曲。 ——《精神长河 映照初心》刊载于《光明日报》\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:41:35', 56);
