INSERT INTO `sys_oper_log` VALUES (777, '党史标题管理', 3, 'com.ds.project.front.title.controller.DsTitleController.remove()', 'GET', 1, 'admin', '研发部门', '/front/title/remove/144', '223.72.68.45', 'XX XX', '144', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:42:47', 11);
INSERT INTO `sys_oper_log` VALUES (778, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"北大荒精神\"],\"briefIntroduction\":[\"农垦为保障国家粮食安全、支援国家建设、维护边疆稳定作出了重大贡献。要贯彻新发展理念，加快建设现代农业的大基地、大企业、大产业，深化农垦体制改革，全面增强农垦内生动力、发展活力、整体实力，更好发挥农垦在现代农业建设中的骨干作用。\\r\\n——习近平总书记2018年9月25日在黑龙江农垦建三江管理局考察调研时强调\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:43:32', 26);
INSERT INTO `sys_oper_log` VALUES (779, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"“两路”精神\"],\"briefIntroduction\":[\"当年，10多万军民在极其艰苦的条件下团结奋斗，创造了世界公路史上的奇迹，结束了西藏没有公路的历史。60年来，在建设和养护公路的过程中，形成和发扬了一不怕苦、二不怕死，顽强拼搏、甘当路石，军民一家、民族团结的“两路”精神。\\r\\n——摘自习近平总书记2014年就川藏青藏公路建成通车60周年作出的重要批示\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:43:58', 39);
INSERT INTO `sys_oper_log` VALUES (780, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"老西藏精神（孔繁森精神）\"],\"briefIntroduction\":[\"广大干部特别是西藏干部要发扬“老西藏精神”，缺氧不缺精神、艰苦不怕吃苦、海拔高境界更高，在工作中不断增强责任感、使命感，增强能力、锤炼作风。\\r\\n——摘自习近平总书记2020年8月在中央第七次西藏工作座谈会上的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:44:28', 36);
INSERT INTO `sys_oper_log` VALUES (781, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"大庆精神（铁人精神）\"],\"briefIntroduction\":[\"60年来，几代大庆人艰苦创业、接力奋斗，在亘古荒原上建成我国最大的石油生产基地。大庆油田的卓越贡献已经镌刻在伟大祖国的历史丰碑上，大庆精神、铁人精神已经成为中华民族伟大精神的重要组成部分。\\r\\n——习近平总书记致信祝贺大庆油田发现60周年强调\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:44:52', 30);
INSERT INTO `sys_oper_log` VALUES (782, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"王杰精神\"],\"briefIntroduction\":[\"无论时代怎样变迁，王杰的“三不伸手”精神始终闪闪发光。习近平总书记在王杰生前所在连队视察时指出，王杰“在荣誉上不伸手，在待遇上不伸手，在物质上不伸手”，这“三不伸手”是一面镜子，共产党员都要好好照照这面镜子。——《一种不同寻常的精神境界》刊载于《光明日报》\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:48:01', 32);
INSERT INTO `sys_oper_log` VALUES (783, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"塞罕坝精神\"],\"briefIntroduction\":[\"塞罕坝林场建设史是一部可歌可泣的艰苦奋斗史。你们用实际行动铸就了牢记使命、艰苦创业、绿色发展的塞罕坝精神，这对全国生态文明建设具有重要示范意义。抓生态文明建设，既要靠物质，也要靠精神。要传承好塞罕坝精神，深刻理解和落实生态文明理念，再接再厉、二次创业，在实现第二个百年奋斗目标新征程上再建功立业。\\r\\n——摘自习近平总书记2021年8月23日在河北承德塞罕坝机械林场考察时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:48:24', 28);
INSERT INTO `sys_oper_log` VALUES (784, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"108\"],\"title\":[\"西迁精神\"],\"briefIntroduction\":[\"“西迁精神”的核心是爱国主义，精髓是听党指挥跟党走，与党和国家、与民族和人民同呼吸、共命运，具有深刻现实意义和历史意义。\\r\\n——摘自习近平总书记2020年4月在陕西考察时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:48:43', 26);
