INSERT INTO `sys_oper_log` VALUES (793, '党史标题管理', 3, 'com.ds.project.front.title.controller.DsTitleController.remove()', 'GET', 1, 'admin', '研发部门', '/front/title/remove/153', '223.72.68.45', 'XX XX', '153', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 14:49:50', 14);
INSERT INTO `sys_oper_log` VALUES (794, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"109\"],\"title\":[\"改革开放精神\"],\"briefIntroduction\":[\"40年的实践充分证明，改革开放是党和人民大踏步赶上时代的重要法宝，是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招。——摘自习近平总书记2018年12月18日在庆祝改革开放40周年大会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:48:35', 31);
INSERT INTO `sys_oper_log` VALUES (795, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"189\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"四十年的实践充分证明，改革开放是党和人民大踏步赶上时代的重要法宝，是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招。——摘自习近平总书记2018年12月18日在庆祝改革开放40周年大会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:50:19', 46);
INSERT INTO `sys_oper_log` VALUES (796, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"109\"],\"title\":[\"特区精神\"],\"briefIntroduction\":[\"经济特区要勇于扛起历史责任，适应国内外形势新变化，按照国家发展新要求，顺应人民新期待，发扬敢闯敢试、敢为人先、埋头苦干的特区精神，始终站在改革开放最前沿，在各方面体制机制改革方面先行先试、大胆探索，为全国提供更多可复制可推广的经验。\\r\\n——摘自习近平总书记在庆祝海南建省办经济特区30周年大会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:50:46', 26);
INSERT INTO `sys_oper_log` VALUES (797, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"109\"],\"title\":[\"抗洪精神\"],\"briefIntroduction\":[\"广大干部群众和人民解放军、武警官兵坚决响应党和政府号召，发扬不怕累苦、不怕疲劳、不怕牺牲的精神斗志，坚守在防汛抗洪救灾第一线，涌现了许多先进典型和感人事迹，展现了中国人民众志成城、顽强拼搏、敢于胜利的英雄气概，书写了洪水无情人有情的人间大爱。\\r\\n——习近平总书记2020年8月在安徽考察时强调\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:51:15', 23);
INSERT INTO `sys_oper_log` VALUES (798, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"109\"],\"title\":[\"女排精神\"],\"briefIntroduction\":[\"广大人民群众对中国女排的喜爱，不仅是因为你们夺得了冠军，更重要的是你们在赛场上展现了祖国至上、团结协作、顽强拼搏、永不言败的精神面貌。女排精神代表着一个时代的精神，喊出了为中华崛起而拼搏的时代最强音。\\r\\n——摘自习近平总书记在会见获得2019年女排世界杯冠军的中国女排队员、教练员代表时的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:51:56', 25);
INSERT INTO `sys_oper_log` VALUES (799, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"109\"],\"title\":[\"抗击“非典”精神\"],\"briefIntroduction\":[\"做好非典的预防、治疗和控制工作，直接关系广大人民群众生命安全和身体健康，直接关系改革发展稳定大局，直接关系国家利益和我国国际形象。\\r\\n——摘自2020年6月15日人民日报《把人民生命安全和身体健康放在心里——习近平同志2003年领导浙江省抗击非典斗争纪事》\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:52:17', 30);
INSERT INTO `sys_oper_log` VALUES (800, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"109\"],\"title\":[\"抗震救灾精神\"],\"briefIntroduction\":[\"要坚持抗震救灾工作和经济社会发展两手抓、两不误，大力弘扬伟大抗震救灾精神，大力发挥各级党组织领导核心和战斗堡垒作用、广大党员先锋模范作用，引导灾区群众广泛开展自力更生、生产自救活动，在中央和四川省大力支持下，积极发展生产、建设家园，用自己的双手创造幸福美好的生活。\\r\\n——摘自习近平总书记就芦山地震抗震救灾工作作出的重要指示\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:52:36', 24);
INSERT INTO `sys_oper_log` VALUES (801, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"109\"],\"title\":[\"青藏铁路精神\"],\"briefIntroduction\":[\"国铁集团要落实主体责任，有关单位和川藏两省区要加强协调配合，精心组织实施，广大铁路建设者要发扬“两路”精神和青藏铁路精神，科学施工、安全施工、绿色施工，高质量推进工程建设，为全面建设社会主义现代化国家作出新的贡献。\\r\\n——摘自习近平总书记2020年对川藏铁路开工建设作出的重要指示\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:56:09', 38);
INSERT INTO `sys_oper_log` VALUES (802, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"109\"],\"title\":[\"载人航天精神\"],\"briefIntroduction\":[\"我们注重传承优良传统，发扬特别能吃苦、特别能战斗、特别能攻关、特别能奉献的载人航天精神，彰显了坚定的中国特色社会主义道路自信、理论自信、制度自信、文化自信，为坚持和发展中国特色社会主义增添了强大精神力量。\\r\\n——摘自习近平总书记在会见天宫二号和神舟十一号载人飞行任务航天员及参研参试人员代表时的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:56:39', 26);
INSERT INTO `sys_oper_log` VALUES (803, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"109\"],\"title\":[\"劳模精神（劳动精神、工匠精神）\"],\"briefIntroduction\":[\"“爱岗敬业、争创一流，艰苦奋斗、勇于创新，淡泊名利、甘于奉献”的劳模精神，生动诠释了社会主义核心价值观，是我们的宝贵精神财富和强大精神力量。\\r\\n——摘自2015年习近平总书记在庆祝“五一”国际劳动节暨表彰全国劳动模范和先进工作者大会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 15:57:06', 29);
