INSERT INTO `sys_oper_log` VALUES (811, '党史标题管理', 3, 'com.ds.project.front.title.controller.DsTitleController.remove()', 'GET', 1, 'admin', '研发部门', '/front/title/remove/131', '223.72.68.45', 'XX XX', '131', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 16:15:17', 11);
INSERT INTO `sys_oper_log` VALUES (812, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"110\"],\"title\":[\"脱贫攻坚精神\"],\"briefIntroduction\":[\"脱贫攻坚伟大斗争，锻造形成了“上下同心、尽锐出战、精准务实、开拓创新、攻坚克难、不负人民”的脱贫攻坚精神。脱贫攻坚精神，是中国共产党性质宗旨、中国人民意志品质、中华民族精神的生动写照，是爱国主义、集体主义、社会主义思想的集中体现，是中国精神、中国价值、中国力量的充分彰显，赓续传承了伟大民族精神和时代精神。\\r\\n——摘自习近平总书记2021年2月25日在全国脱贫攻坚总结表彰大会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 16:16:16', 29);
INSERT INTO `sys_oper_log` VALUES (813, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"110\"],\"title\":[\"抗疫精神\"],\"briefIntroduction\":[\"伟大抗疫精神，同中华民族长期形成的特质禀赋和文化基因一脉相承，是爱国主义、集体主义、社会主义精神的传承和发展，是中国精神的生动诠释，丰富了民族精神和时代精神的内涵。我们要在全社会大力弘扬伟大抗疫精神，使之转化为全面建设社会主义现代化国家、实现中华民族伟大复兴的强大力量。\\r\\n——摘自习近平总书记在全国抗击新冠肺炎疫情表彰大会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 16:16:42', 34);
INSERT INTO `sys_oper_log` VALUES (814, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"110\"],\"title\":[\"“三牛”精神\"],\"briefIntroduction\":[\"在中华文化里，牛是勤劳、奉献、奋进、力量的象征。人们把为民服务、无私奉献比喻为孺子牛，把创新发展、攻坚克难比喻为拓荒牛，把艰苦奋斗、吃苦耐劳比喻为老黄牛。前进道路上，我们要大力发扬孺子牛、拓荒牛、老黄牛精神，以不怕苦、能吃苦的牛劲牛力，不用扬鞭自奋蹄，继续为中华民族伟大复兴辛勤耕耘、勇往直前，在新时代创造新的历史辉煌！\\r\\n——摘自习近平总书记在2021年春节团拜会上的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 16:17:03', 34);
INSERT INTO `sys_oper_log` VALUES (815, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"110\"],\"title\":[\"科学家精神\"],\"briefIntroduction\":[\"在中华民族伟大复兴的征程上，一代又一代科学家心系祖国和人民，不畏艰难，无私奉献，为科学技术进步、人民生活改善、中华民族发展作出了重大贡献。新时代更需要继承发扬以国家民族命运为己任的爱国主义精神，更需要继续发扬以爱国主义为底色的科学家精神。\\r\\n——摘自习近平总书记在中国科学院第二十次院士大会、中国工程院第十五次院士大会、中国科协第十次全国代表大会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 16:17:22', 37);
INSERT INTO `sys_oper_log` VALUES (816, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"110\"],\"title\":[\"企业家精神\"],\"briefIntroduction\":[\"企业家要带领企业战胜当前的困难，走向更辉煌的未来，就要在爱国、创新、诚信、社会责任和国际视野等方面不断提升自己，努力成为新时代构建新发展格局、建设现代化经济体系、推动高质量发展的生力军。\\r\\n——摘自习近平总书记2020年7月21日在企业家座谈会上的讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 16:17:51', 23);
INSERT INTO `sys_oper_log` VALUES (817, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"110\"],\"title\":[\"探月精神\"],\"briefIntroduction\":[\"17年来，参与探月工程研制建设的全体人员大力弘扬追逐梦想、勇于探索、协同攻坚、合作共赢的探月精神，不断攀登新的科技高峰，可喜可贺、令人欣慰。\\r\\n——习近平总书记2021年2月22日在会见探月工程嫦娥五号任务参研参试人员代表并参观月球样品和探月工程成果展览时强调\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 16:18:18', 24);
INSERT INTO `sys_oper_log` VALUES (818, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"110\"],\"title\":[\"丝路精神\"],\"briefIntroduction\":[\"古丝绸之路绵亘万里，延续千年，积淀了以和平合作、开放包容、互学互鉴、互利共赢为核心的丝路精神。这是人类文明的宝贵遗产。\\r\\n——摘自习近平主席2017年5月14日在首届“一带一路”国际合作高峰论坛开幕式上的主旨演讲\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 16:18:46', 23);
INSERT INTO `sys_oper_log` VALUES (819, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"110\"],\"title\":[\"新时代北斗精神\"],\"briefIntroduction\":[\"26年来，参与北斗系统研制建设的全体人员迎难而上、敢打硬仗、接续奋斗，发扬“两弹一星”精神，培育了新时代北斗精神，要传承好、弘扬好。要推广北斗系统应用，做好确保系统稳定运行等后续各项工作，为推动我国经济社会发展、推动构建人类命运共同体作出新的更大贡献。\\r\\n——习近平总书记2020年7月31日在参观北斗系统建设发展成果展览展示时强调\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-19 16:19:13', 35);
