INSERT INTO `sys_oper_log` VALUES (872, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"965\"],\"annual\":[\"2012-03-02\"],\"tvSeries\":[\"钱学森\"],\"img\":[\"\"],\"topicContent\":[\"本片讲述上世纪四十年代，加州理工学院终身教授钱学森（陈坤 饰）因为美国兴起的反共言论而备受打击。他的尖端技术研究被迫中止，并被责令出境。钱学森心系祖国，归心似箭，而意识到钱学森的巨大价值的美方又对其归国设置了重重障碍，甚至以间谍罪逮捕钱学森。最终，宣告无罪的钱学森被长期软禁在家 中。 钱学森写信辗转与祖国取得联系，周恩来授命用11名美国战犯飞行员换回了钱学森。 面对新中国技术、人才、工业等各方面的空白，钱学森带领科研人员从仿制入手，根据现有技术和条件逐步研究、完善，奠定了中国导弹的基础。 \"],\"type\":[\"1\",\"8\",\"9\",\"18\",\"19\"],\"director\":[\"张建亚\"],\"screenwriter\":[\"陈怀国、孙毅安、陶纯\"],\"actor\":[\"陈坤、张雨绮\"],\"episodeNum\":[\"\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"https://www.1905.com/vod/play/580704.shtml?__hz=28267ab848bcf807&fr=baidu_aladdin_vod_add&api_source=baidualaddin_vodadd ; https://www.iqiyi.com/v_19rrjtrw7o.html?vfm=2008_aldbd&fc=828fb30b722f3164&fv=p_02_01\"],\"kind\":[\"0\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2013年第十五届中国电影华表奖优秀故事影片奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 12:24:03', 19);
