INSERT INTO `sys_oper_log` VALUES (877, '文章管理', 2, 'com.ds.project.front.article.controller.DsArticleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/article/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"270\"],\"srcDatabase\":[\"报纸\"],\"title\":[\"井冈山第一支部\"],\"author\":[\"文洪英; 肖况\"],\"organ\":[\"农民日报\"],\"source\":[\"农民日报\"],\"keyword\":[\"井冈山;支部书记;毛泽覃;农村党支部;井冈山根据地;\"],\"summary\":[\"这是一个不应该被忘却的名字——乔林。乔林是一个小山村的名字。上了井冈山，由茨坪经黄洋界西行十余公里，一条弯弯曲曲的大山沟，便是乔林的地盘。像它的名字一样，这里漫山遍野都是高大茂密的林木。在大如房屋的石头旮旯里，散落着星星点点的田地。这里\"],\"pubTime\":[\"2001-06-14\"],\"articleText\":[\"https://kns.cnki.net/kcms2/article/abstract?v=6e6DrGrvy4OFJzmolfsPvHMDw25EbEHoLkFQrAizK3vs619NkL4TtCL4Y9o4V3V5euCHpwYP8QNzICpNZrXtryI-oL1QZR890Jyp8TZaebwsDc7LsIfXqAOL6dp35u15ba2nHUSC3WoGN8QmNxcdLw==&uniplatform=NZKPT&language=CHS\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 16:46:51', 24);
