INSERT INTO `sys_oper_log` VALUES (939, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"太行精神（吕梁精神）\"],\"briefIntroduction\":[\"山西也是具有光荣革命传统的地方，是八路军总部所在地，是抗日战争主战场之一，建立了晋绥、晋察冀、晋冀鲁豫抗日根据地，平型关大捷、百团大战等闻名中外，太行精神、吕梁精神是我们党宝贵的精神财富。这些都要充分挖掘和利用，以丰富多彩的历史文化、红色文化资源为山西发展提供精神力量。\\r\\n ——摘自习近平总书记2020年5月在山西考察时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 21:16:35', 20);
INSERT INTO `sys_oper_log` VALUES (940, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"大别山精神\"],\"briefIntroduction\":[\"鄂豫皖苏区根据地是我们党的重要建党基地，焦裕禄精神、红旗渠精神、大别山精神等都是我们党的宝贵精神财富。\\r\\n ——摘自习近平总书记2019年9月在河南考察时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 21:17:14', 24);
INSERT INTO `sys_oper_log` VALUES (941, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"沂蒙精神\"],\"briefIntroduction\":[\"沂蒙精神是红色革命精神之一 ，是临沂人民在长期的革命和建设实践中形成的先进群体意识，是中华民族优秀文化的重要组成部分，是临沂人民乃至全国人民宝贵的精神财富。2022年3月，经党中央批准，沂蒙精神基本内涵正式表述为“党群同心、军民情深、水乳交融、生死与共”。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 21:20:29', 19);
INSERT INTO `sys_oper_log` VALUES (942, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"老区精神\"],\"briefIntroduction\":[\"老区和老区人民，为我们党领导的中国革命作出了重大牺牲和贡献。这些牺牲和贡献永远镌刻在中国共产党、中国人民解放军、中华人民共和国的历史丰碑上。我们要永远珍惜、永远铭记老区和老区人民的这些牺牲和贡献，继承和发扬老区和老区人民的光荣传统，为实现“两个一百年”奋斗目标、实现中华民族伟大复兴的中国梦而不懈奋斗！\\r\\n ——摘自习近平总书记2015年在陕甘宁革命老区脱贫致富座谈会上的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 21:21:08', 25);
INSERT INTO `sys_oper_log` VALUES (943, '党史标题管理', 1, 'com.ds.project.front.title.controller.DsTitleController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/title/add', '223.72.68.45', 'XX XX', '{\"parentId\":[\"105\"],\"title\":[\"张思德精神\"],\"briefIntroduction\":[\"全心全意为人民服务是党的根本宗旨。延安时期，毛泽东同志在追悼张思德同志时发表的《为人民服务》的演讲，深刻揭示了党群关系、干群关系、军民关系的真谛。\\r\\n ——摘自习近平总书记2015年2月15日在陕西考察工作结束时的重要讲话\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 21:21:34', 20);
