INSERT INTO `sys_oper_log` VALUES (1039, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1075\"],\"annual\":[\"2023-11-24\"],\"tvSeries\":[\"我本是高山\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/21/我本是高山_20250221234158A026.jpeg\"],\"topicContent\":[\"该片根据张桂梅真实事迹改编，海清领衔演绎现实催泪佳作！这是一个坚毅的女人和一群刚刚毕业还很稚嫩的老师，带着一百多个女孩成功逆天改命的故事，是关于爱、青春、热血和命运……\"],\"type\":[\"15\",\"18\",\"19\"],\"director\":[\"郑大圣、杨瑾\"],\"screenwriter\":[\"袁媛、陈麒凌\"],\"actor\":[\"海清、陈永胜、柴烨\"],\"episodeNum\":[\"\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"3\"],\"url\":[\"\"],\"kind\":[\"0\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2024年第十七届精神文明建设“五个一工程”优秀作品奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 23:42:00', 10);
INSERT INTO `sys_oper_log` VALUES (1040, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1076\"],\"annual\":[\"2023-09-28\"],\"tvSeries\":[\"志愿军：雄兵出击\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/21/志愿军：雄兵出击_20250221234253A027.jpeg\"],\"topicContent\":[\"该片讲述了1949年建国初期，新中国面临“内忧外患”局面。朝鲜内战爆发以来，美军屡在中朝边境挑衅，平民惨遭轰炸。为了维护来之不易的和平、为了世代长久的安稳，1950年10月，中国人民志愿军入朝，“抗美援朝”战争拉开帷幕。 这是一场“举国之战”—— 朝鲜战场，即使军备实力对比悬殊，我军却用壮烈牺牲换回节节胜利； 外交舞台，中华人民共和国代表团首度亮相联合国，中国新声赢得国际敬畏。 新中国，寸土不让扬国威；新青年，意气风发保家国。\"],\"type\":[\"3\",\"7\",\"19\"],\"director\":[\"陈凯歌\"],\"screenwriter\":[\"张珂\"],\"actor\":[\"唐国强、王砚辉、刘劲\"],\"episodeNum\":[\"\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"0\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2024年第三十七届中国电影金鸡奖评委会特别奖、最佳导演奖（陈凯歌）；2024年第三十七届大众电影百花奖最佳影片奖；2024年第十七届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 23:42:58', 12);
INSERT INTO `sys_oper_log` VALUES (1041, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1077\"],\"annual\":[\"2023-01-22\"],\"tvSeries\":[\"无名\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/21/无名_20250221234339A028.jpeg\"],\"topicContent\":[\"该片讲述了1941年12月7日，日本偷袭珍珠港。次日，汪伪政府跟随日本对英美宣战，日本象征性占领上海全境。随着太平洋战争全面爆发，中国抗战形势也因此完全改变。中国共产党领导的中共特科在上海周旋于重庆、汪伪、日本间谍机构之间，通过错综复杂的敌后情报系统，策反敌人，获取情报，诛杀汉奸，建立更广泛的统一战线，直至抗战胜利的前夜。\"],\"type\":[\"1\",\"3\",\"19\"],\"director\":[\"程耳\"],\"screenwriter\":[\"桂冠、刘晓世\"],\"actor\":[\"梁朝伟、王一博、周迅、黄磊\"],\"episodeNum\":[\"\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"0\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2023年第三十六届中国电影金鸡奖最佳导演奖（程耳）、最佳男主角奖（梁朝伟）、最佳剪辑奖（程耳）。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 23:43:42', 11);
INSERT INTO `sys_oper_log` VALUES (1042, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1078\"],\"annual\":[\"2023-04-28\"],\"tvSeries\":[\"长空之王\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/21/长空之王_20250221234443A029.jpeg\"],\"topicContent\":[\"该片讲述了雷宇（王一博饰）等优秀飞行员经过严苛选拔正式成为试飞员，他们在队长张挺（胡军饰）的带领下，参与到了最新型战机的试飞。高空之上，发动机骤停甚至失火，飞机失去控制。他们一次次与死神过招，只为获取最极限的数据。随着战机交付日期的临近，任务难度逐渐升级，试飞员们面临着更大的挑战。\"],\"type\":[\"6\",\"19\"],\"director\":[\"刘晓世\"],\"screenwriter\":[\"桂冠、刘晓世\"],\"actor\":[\"王一博、胡军\"],\"episodeNum\":[\"\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"3\"],\"url\":[\"\"],\"kind\":[\"0\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2023年第三十六届中国电影金鸡奖最佳导演处女作奖（刘晓世）；2024年第十七届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 23:44:46', 12);
INSERT INTO `sys_oper_log` VALUES (1043, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1077\"],\"annual\":[\"2023-01-22\"],\"tvSeries\":[\"无名\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/21/无名_20250221234339A028.jpeg\"],\"topicContent\":[\"该片讲述了1941年12月7日，日本偷袭珍珠港。次日，汪伪政府跟随日本对英美宣战，日本象征性占领上海全境。随着太平洋战争全面爆发，中国抗战形势也因此完全改变。中国共产党领导的中共特科在上海周旋于重庆、汪伪、日本间谍机构之间，通过错综复杂的敌后情报系统，策反敌人，获取情报，诛杀汉奸，建立更广泛的统一战线，直至抗战胜利的前夜。\"],\"type\":[\"1\",\"3\",\"19\"],\"director\":[\"程耳\"],\"screenwriter\":[\"桂冠、刘晓世\"],\"actor\":[\"梁朝伟、王一博、周迅、黄磊\"],\"episodeNum\":[\"\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"0\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2023年第三十六届中国电影金鸡奖最佳导演奖（程耳）、最佳男主角奖（梁朝伟）、最佳剪辑奖（程耳）。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-21 23:44:53', 10);
