INSERT INTO `sys_oper_log` VALUES (1049, '影视管理', 3, 'com.ds.project.front.film.controller.DsFilmController.remove()', 'POST', 1, 'admin', '研发部门', '/front/film/remove', '223.72.68.45', 'XX XX', '{\"ids\":[\"1136\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:11:56', 9);
INSERT INTO `sys_oper_log` VALUES (1050, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1137\"],\"annual\":[\"2012-06-26\"],\"tvSeries\":[\"我们的法兰西岁月\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/我们的法兰西岁月_20250222002535A030.jpg\"],\"topicContent\":[\"该剧故事发生在二十世纪初叶，为探索救国救民真理，中国的进步青年上下求索，探寻救国救民的道路，在开明人士的倡议下，他们开始把目光转向欧洲。周恩来（朱亚文 饰）、邓希贤（钟秋 饰）等一批进步青年来到法国勤工俭学，开始了异国他乡的工读生活。1921年，周恩来、赵世炎（李梁 饰）等成立巴黎共产主义小组，陈延年兄弟俩在他们感召下开始信奉马克思主义。北洋军阀停止供给留法学生，蔡和森（张念骅 饰）带人到驻法公使馆请愿，遭到警察镇压。在不断斗争中，蔡和森与向警予（吕夏 饰）结为革命伴侣，蔡畅（吴晓丹 饰）和李富春（刘智扬 饰）也喜结连理。由于里昂大学拒收勤工俭学的中国学生，赵世炎、蔡和森等人奋起交涉，遭军警逮捕，后被遣返回国，血的洗礼让广大留法青年自觉地站在了共产主义的旗帜下……本剧讲述了青年时期的周恩来、邓小平、赵世炎、蔡和森等社会主义革命先驱与伟人在法国艰辛寻求救国之道并最终走上共产主义革命道路的故事。\"],\"type\":[\"3\",\"14\",\"19\"],\"director\":[\"康洪雷\"],\"screenwriter\":[\"李克威\"],\"actor\":[\"朱亚文、钟秋、李泓良、张隽溢、袁文康\"],\"episodeNum\":[\"31\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第二十七届中国电视金鹰奖优秀电视剧奖；2012年第十二届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:25:45', 10);
INSERT INTO `sys_oper_log` VALUES (1051, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1138\"],\"annual\":[\"2012-10-17\"],\"tvSeries\":[\"五星红旗迎风飘扬2\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/五星红旗迎风飘扬2_20250222002601A031.jpg\"],\"topicContent\":[\"该剧承接“两弹一星”的故事，从1970年4月我国第一颗人造卫星上天写起，着力塑造毛泽东（唐国强 饰）、周恩来（孙维民 饰）、邓小平（卢奇 饰）等老一辈革命家运筹帷幄，在复杂多变和严峻的国际环境中，审时度势，从容应对，始终立于主动地位。为了维护祖国的主权、领土完整和民族尊严，他们进行的坚定而有理有力的斗争，在严重困难面前，他们带领全国人民，迎难而上，以不屈的姿态和昂扬的精神面貌去战胜和克服困难，终于走出了一条中国特色的社会主义道路。\"],\"type\":[\"3\",\"14\",\"19\"],\"director\":[\"王响伟、刘光\"],\"screenwriter\":[\"赵锐勇\"],\"actor\":[\"唐国强、孙维民、卢奇、马晓伟、黄薇\"],\"episodeNum\":[\"45\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧二等奖、优秀男演员奖（孙维民）。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:26:08', 9);
INSERT INTO `sys_oper_log` VALUES (1052, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1139\"],\"annual\":[\"2012-10-07\"],\"tvSeries\":[\"国家命运\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/国家命运_20250222002630A032.jpg\"],\"topicContent\":[\"该剧讲述了朝鲜战争结束后，有感于美国先进武器在战场上对我志愿军造成的巨大伤害，为彻底打破以美国为首的西方敌对势力对中国的核威慑，在毛泽东（韩中 饰）、周恩来（刘劲 饰）、邓小平（史鑫 饰）等国家领导人的带领下，以钱学森（胡亚捷 饰）、钱三强为代表的一大批中青年科学家克服种种难以想象的困难，在贫困经济条件、薄弱的技术基础和艰苦的工作条件下，在党中央的坚定支持下，以惊人的智慧与毅力﹐先后完成发射人造地球卫星、成功试爆原子弹、氢弹等一系列伟大壮举，创造出“两弹一星”的民族奇迹。\"],\"type\":[\"3\",\"14\",\"19\"],\"director\":[\"延艺\"],\"screenwriter\":[\"陈怀国、陶纯\"],\"actor\":[\"刘劲、谢钢、史鑫、胡亚捷、韩中\"],\"episodeNum\":[\"29\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第二十七届中国电视金鹰奖优秀电视剧奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:26:37', 10);
INSERT INTO `sys_oper_log` VALUES (1053, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1140\"],\"annual\":[\"2012-12-19\"],\"tvSeries\":[\"刘伯承元帅\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/刘伯承元帅_20250222002701A033.jpg\"],\"topicContent\":[\"该剧以刘伯承元帅（刘之冰 饰）的心路历程为主线，着重塑造他的品格、魅力、才华和胆魄。结构上，采用跳跃式创作手法，撷取最能表现人物性格的华彩段落，进行浓墨重彩的渲染，而不是平分笔墨的编年史式的描述。本剧将解读刘伯承如何从一个贫苦的“川娃子”成长为闻名中外的军事家，通过经典战例和敌我交锋的战争活剧，诠释刘伯承卓越的军事指挥艺术和战争制胜的谋略，生动地再现了他和他的战友们在中国革命历史的舞台上，为中华民族的自由和解放，征战沙场，九死一生的英雄传奇。\"],\"type\":[\"3\",\"14\",\"18\"],\"director\":[\"张玉中\"],\"screenwriter\":[\"傅建文、尹东鸿\"],\"actor\":[\"刘之冰、王嘉、王晖、梁春书、刘沙\"],\"episodeNum\":[\"33\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧二等奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:27:05', 11);
INSERT INTO `sys_oper_log` VALUES (1054, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1141\"],\"annual\":[\"2012-05-29\"],\"tvSeries\":[\"知青\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/知青_20250222002729A034.jpg\"],\"topicContent\":[\"该剧讲述了1969年北大荒林区的一个雨夜，小火车载来了一批来自全国各大城市的知识青年。白桦林火车站的站长杨秉奎，望着一张张稚嫩而青春洋溢的脸，预感到这批人的到来，将会给北大荒带来翻天覆地的变化。1960年代末期，千百万北京、上海等大城市的红卫兵和老三届响应毛主席“知识青年到农村去，接受贫下中农的再教育，很有必要”的号召，奔赴全国各地农村生产建设兵团，谱写了一曲曲动人的青春之歌。在黑龙江生产建设兵团，涌现出赵天亮（唐曾 饰）、周萍（傅晶 饰）等一大批建设边疆、保卫边疆的有志青年。在陕北、山东屯涌现出赵曙光（程皓枫 饰）、冯晓兰（李欣凌 饰）、许蕾（周娟 饰）等志愿献身农村的知识青年，在城市家中，他（她）们大多是父母眼里的长不大的孩子，可是在边疆、在农村，他们成长为真正的战士，也有部分青年永远长眠在了那片土地上。\"],\"type\":[\"9\",\"10\",\"13\",\"19\"],\"director\":[\"张新建、王滨、高力强\"],\"screenwriter\":[\"梁晓声\"],\"actor\":[\"唐曾、傅晶、程皓枫\"],\"episodeNum\":[\"45\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧三等奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:27:35', 10);
INSERT INTO `sys_oper_log` VALUES (1055, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1142\"],\"annual\":[\"2012-10-21\"],\"tvSeries\":[\"焦裕禄\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/焦裕禄_20250222002809A035.jpg\"],\"topicContent\":[\"该剧记述了焦裕禄（王洛勇 饰）一生成长与奋斗的人生轨迹。这位人民公仆的青少年时代，有着鲜为人知的传奇经历，他的故乡是诞生了孔、孟二圣的豫鲁交界之地，中华传统文化的濡染、孔、孟之乡深厚的文化积淀和故乡山水之钟毓灵秀，形成了这位大地之子生身的规定情境。在焦裕禄身上，体现着最典型的中华传统文化精神。命运曾给了焦裕禄令人难以置信的万千磨难，少年丧父、入监坐牢、下煤坑做苦力，背井离乡，受尽了日本侵略者的欺凌和富人的压迫。苦难的洗礼使他成为一个不向人生抵押自己命运的硬汉。投身革命，他又是一个为人敬佩的能文能武的孤胆英雄，当民兵、参加南下武装工作队、领导土改和清匪反霸，他以大智大勇、大爱大恨谱写了一曲羽声慷慨的英雄壮歌。在特殊的历史时期，他同自然灾害和自己的疾病展开了艰苦卓绝的斗争，直到生命最后一刻。他心里装着人民群众，却唯独没有他自己。他似乎是用共产党员的特殊材料造成的，他的眼睛能看到别人看不到的新生事物，他的耳朵能听到别人听不到的声音，他的嘴巴能说出别人不愿出口的话，他的手专做别人不做的事情。他在兰考县这块多灾多难的大地上，像一阵旋风，突然出现，又突然消失，他给兰考人留下的是思念的眼泪和奋斗不息的火焰。\"],\"type\":[\"18\",\"19\"],\"director\":[\"李文岐\"],\"screenwriter\":[\"何香久、陈新\"],\"actor\":[\"王洛勇、颜丙燕、高志强、李立群、王静\"],\"episodeNum\":[\"30\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第二十七届中国电视金鹰奖最佳电视剧奖、观众喜爱的电视剧男演员奖（王洛勇）、金鹰节最佳表演艺术奖（王洛勇）；2014年第十三届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:28:13', 12);
INSERT INTO `sys_oper_log` VALUES (1056, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1143\"],\"annual\":[\"2012-11-08\"],\"tvSeries\":[\"杨善洲\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/杨善洲_20250222002833A036.jpg\"],\"topicContent\":[\"该剧讲述了杨善洲（刘佩琦 饰）的故事，生前曾任云南省保山地委书记，2010年10月10日因病逝世。他为官多年，但老母、妻子和三个女儿却一直在乡下艰辛生活。为了兑现自己当初“为当地群众做一点实事不要任何报酬”的承诺，退休后，主动放弃进省城安享晚年的机会，扎根大亮山，义务植树造林，一干就是22年，临终前将5.6万亩、价值3亿元的林场无偿上缴给国家。\"],\"type\":[\"15\",\"18\",\"19\"],\"director\":[\"张绍林\"],\"screenwriter\":[\"石零\"],\"actor\":[\"刘佩琦、娜仁花、丁柳元、柏青\"],\"episodeNum\":[\"23\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"2\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧二等奖、优秀导演奖（张绍林）。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:28:40', 12);
INSERT INTO `sys_oper_log` VALUES (1057, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1144\"],\"annual\":[\"2012-09-29\"],\"tvSeries\":[\"火蓝刀锋\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/火蓝刀锋_20250222002917A037.jpg\"],\"topicContent\":[\"该剧讲述蒋小鱼（杨志刚 饰）、鲁炎（郑凯 饰）、张冲（赫子铭 饰）和乌云（刘思言 饰）等新兵被特招进入海军陆战队后，经过几年的磨砺，渐渐树立起“为祖国的大海流尽最后一滴血”的信仰，蜕变成为新一代优秀海军战士的励志大戏。归国后的蒋小鱼组建龙鲨中队，我军的战斗力与日俱增。在与国际海盗殊死搏斗的危险任务中，成功地歼灭了海盗，完成了“把最后一滴血流入祖国的大海”的誓言。草根渔民蒋小鱼从“忽悠王”到“大英雄”的蜕变，成为影片的一大亮点，可圈可点。老兵柳小山、向羽等人对老兵形象的演绎也是真实感人，成为本片的“催泪弹”。\"],\"type\":[\"6\",\"19\"],\"director\":[\"张国庆\"],\"screenwriter\":[\"冯骥、徐速、王潇涵\"],\"actor\":[\"杨志刚、刘思言、樊昊仑、郑凯\"],\"episodeNum\":[\"32\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"2\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧二等奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:29:21', 18);
INSERT INTO `sys_oper_log` VALUES (1058, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1145\"],\"annual\":[\"2012-07-14\"],\"tvSeries\":[\"先遣连\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/先遣连_20250222003009A038.jpg\"],\"topicContent\":[\"该剧讲述了1950年2月，遵照毛泽东主席“解放西藏宜早不宜迟”的伟大号令，新疆军区独立骑兵师抽调汉、蒙、回、藏、维吾尔、哈萨克、锡伯等7个民族136人组成的进藏先遣连，以李狄三（王千源 饰）为代表的领导集体，率领着先遣连的一百三十六人，克服重重困难，跨越昆仑山脉，孤军挺进1000多公里，跋涉冰山雪河，穿越生命禁区，在高寒缺氧的情况下，进入茫无人迹的藏北高原，为西藏和平解放在雪域高原上战胜各种难以想象的困难，付出巨大牺牲，最终将五星红旗插上了阿里高原的故事。\"],\"type\":[\"3\",\"14\"],\"director\":[\"范建会\"],\"screenwriter\":[\"王元平（总）、公丕才、王喜民、田耀斌\"],\"actor\":[\"王千源、王新军、孙涛、王唯\"],\"episodeNum\":[\"24\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:30:12', 13);
INSERT INTO `sys_oper_log` VALUES (1059, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1146\"],\"annual\":[\"2012-12-25\"],\"tvSeries\":[\"我的土地我的家\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/我的土地我的家_20250222003043A039.jpg\"],\"topicContent\":[\"该剧以1978年土地下放到户至今天为背景，描述了30年来农村改革开放的历程。以农民张老栓（张洪杰 饰）一家人的恩怨纠葛故事为缩影，讲述了农村和农民在改革开放的历史背景下，由贫穷走向富裕，由保守走向开放，与贫穷落后抗争的命运故事。正面反映改革开放给农村和农民带来的巨大变化和从生活到思想发生的巨大变革。\"],\"type\":[\"12\",\"15\",\"19\"],\"director\":[\"杨晶\"],\"screenwriter\":[\"谭文峰、尹江春\"],\"actor\":[\"张洪杰、霍桠明、江佳奇、张铮\"],\"episodeNum\":[\"24\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"2\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2013年第二十九届中国电视剧飞天奖长篇电视剧一等奖；2014年第二十七届中国电视金鹰奖优秀电视剧奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:30:55', 10);
INSERT INTO `sys_oper_log` VALUES (1060, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1147\"],\"annual\":[\"2013-06-18\"],\"tvSeries\":[\"寻路\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/寻路_20250222003301A040.jpg\"],\"topicContent\":[\"该剧讲述了1927年大革命失败后至1932年间，以毛泽东（由许铂岑 饰）为代表的中国共产党人，在革命根据地和国统区两条战线上坚持革命斗争的历程。在这一时期，中国共产党人在经历重重困难和挑战后，探索并坚持了适合中国国情的革命道路，展现了坚定的革命信仰和不屈不挠的斗争精神。剧中还展现了周恩来（刘劲 饰）等一批革命先驱的英勇事迹，以及他们在革命过程中的智慧和策略。不仅重现了中国共产党早期的重要历史时刻，如秋收起义、三湾改编、井冈山会师等，也深刻描绘了党内不同路线的交锋和斗争，体现了中国共产党在革命实践中不断摸索和前进的过程。通过艺术化的手法，该剧成功塑造了一系列血肉丰满的共产党人形象，为观众提供了丰富的精神滋养和审美享受，成为一部具有深刻历史意义和高度艺术价值的革命史诗。\"],\"type\":[\"3\",\"14\",\"19\"],\"director\":[\"张多福、刘娟\"],\"screenwriter\":[\"王朝柱\"],\"actor\":[\"许铂岑、刘劲、马晓伟、罗忆楠\"],\"episodeNum\":[\"44\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2014年第十三届精神文明建设“五个一工程”优秀作品奖；2015年第三十届中国电视剧飞天奖优秀重大题材类电视剧奖；2014年第二十七届中国电视金鹰奖最佳电视剧奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:33:23', 12);
INSERT INTO `sys_oper_log` VALUES (1061, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1148\"],\"annual\":[\"\"],\"tvSeries\":[\"陈云\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/陈云_20250222003341A041.jpg\"],\"topicContent\":[\"该剧讲述了中国共产党重要领导人陈云（谢刚 饰）的生平故事。陈云出身贫寒，自幼失去双亲，由舅父母抚养成人。他的一生经历了中国革命和建设的多个重要时期，从在商务印书馆当学徒开始，逐步接触先进思想，到后来参加五卅运动和工人罢工运动，加入共产党，成为党内著名的“铁算盘”，以卓越的财经工作能力著称。\"],\"type\":[\"3\",\"14\",\"18\"],\"director\":[\"金韬\"],\"screenwriter\":[\"张光荣\"],\"actor\":[\"谢钢、丛珊、王霙、李龙君\"],\"episodeNum\":[\"30\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2014年第十三届精神文明建设“五个一工程”优秀作品奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:33:46', 13);
INSERT INTO `sys_oper_log` VALUES (1062, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1149\"],\"annual\":[\"2013-05-07\"],\"tvSeries\":[\"阿娜尔罕\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/阿娜尔罕_20250222003356A042.jpg\"],\"topicContent\":[\"该剧讲述了在上世纪四十年代末期的南疆，美丽的阿娜尔罕（迪丽热巴饰）与英俊的库尔班（阿卜力克木·阿卜来提 饰）相爱，却因为大地主乌斯曼伯克的贪婪与权谋，使得两人的爱情之路充满坎坷。乌斯曼伯克（吐尔洪·伊明 饰）企图将阿娜尔罕献给专员伊明（尼加提·吐尔逊 饰）以求讨好，但遭到了阿娜尔罕和库尔班的坚决抵抗。乌斯曼伯克在愤怒之下设计陷害阿娜尔罕，导致她家破人亡。随着解放军的到来，阿娜尔罕和村民们看到了希望，而乌斯曼伯克和伊明却不愿接受现实，继续顽抗。在这段艰难的岁月中，阿娜尔罕展现了她的坚韧与不屈，最终迎来了新生活的曙光。\"],\"type\":[\"9\",\"19\"],\"director\":[\"阎清秀、于德安\"],\"screenwriter\":[\"程万里、兰小宁、阎清秀\"],\"actor\":[\"迪丽热巴、阿卜力克木·阿卜来提、吐尔洪·伊明、尼加提·吐尔逊\"],\"episodeNum\":[\"20\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2014年第十三届精神文明建设“五个一工程”优秀作品奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:34:13', 10);
INSERT INTO `sys_oper_log` VALUES (1063, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1150\"],\"annual\":[\"2013-03-18\"],\"tvSeries\":[\"幸福生活万年长\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/幸福生活万年长_20250222003449A043.jpg\"],\"topicContent\":[\"该剧以母亲河边的古镇为背景，讲述了万跃进（邵峰 饰）一家在面临环境治理和乡村振兴任务时的故事。万跃进，一位退居二线的老干部，主动承担起县里下达的垃圾清洁工作，致力于改善古镇环境。而他的妻子范跃进（李菁菁 饰）、女儿万改改、儿子万开开（褚栓忠 饰）、儿媳莉莉（王和平 饰）以及亲家曾淑平（尚国 饰）也在这个过程中扮演了不同的角色，共同推动了环保事业的发展。在老万的带领下，古镇的居民们克服了种种困难，实现了“植树造林，清洁垃圾，保护母亲河，建设新农村”的目标，赢得了县里领导的肯定。同时，年轻的书记马彦芳也因为老万的推荐得到了提升。老万一家也在这一年中喜事连连，儿子大婚、女儿出嫁、亲家再婚和孙子出生，象征着幸福生活的延续和传承。通过万家人的努力，古镇的环境得到了显著改善，山更绿、天更蓝、水更清，展现了一种积极向上、和谐共生的乡村振兴新面貌。\"],\"type\":[\"8\",\"15\"],\"director\":[\"牛建荣\"],\"screenwriter\":[\"牛建荣\"],\"actor\":[\"邵峰、李菁菁、褚栓忠、王和平、尚国伟\"],\"episodeNum\":[\"28\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"3\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2014年第十三届精神文明建设“五个一工程”优秀作品奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:35:33', 12);
INSERT INTO `sys_oper_log` VALUES (1064, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1151\"],\"annual\":[\"2013-12-25\"],\"tvSeries\":[\"毛泽东\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/毛泽东_20250222003608A044.jpg\"],\"topicContent\":[\"该剧讲述毛泽东（唐国强 饰）从韶山出生、读书求学、参加革命、建立国家、治理国家的历史。\"],\"type\":[\"3\",\"13\",\"14\"],\"director\":[\"高希希、嘉娜·沙哈提、赵立军、刘海波、宋海波\"],\"screenwriter\":[\"黄晖、叶剑、全影、杨宏\"],\"actor\":[\"唐国强、侯京健、刘劲\"],\"episodeNum\":[\"50\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2014年第二十七届中国电视金鹰奖优秀电视剧奖；2014年第十三届精神文明建设“五个一工程”优秀作品奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:36:16', 10);
INSERT INTO `sys_oper_log` VALUES (1065, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1152\"],\"annual\":[\"2013-06-05\"],\"tvSeries\":[\"我的故乡晋察冀\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/我的故乡晋察冀_20250222003633A045.jpg\"],\"topicContent\":[\"该剧以抗日战争时期的晋察冀边区为背景，讲述了从平型关大捷到开国大典这段历史时期内，保定山货店伙计耿三七（孙涛 饰）在去陕北送货途中遭遇危险，被八路军所救，从而毅然加入抗日队伍的故事。耿三七的成长经历与晋察冀地区的老百姓紧密相连，他们共同经历了十二年的浴血奋战和情感纠葛。剧中通过耿三七的视角，展现了晋察冀军民在中国共产党的领导下，如何团结一心、奋勇抗战，以及在艰苦环境下的不屈不挠和牺牲奉献。同时，剧中也深刻描绘了主人公与晋察冀老百姓之间的深厚情感，以及他们在战争与生活中所展现出的抗战精神和人性光辉。\"],\"type\":[\"7\",\"13\",\"19\"],\"director\":[\"马玉辉\"],\"screenwriter\":[\"周振天\"],\"actor\":[\"孙涛、齐芳、文江、王强、杜旭东\"],\"episodeNum\":[\"40\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2014年第十三届精神文明建设“五个一工程”优秀作品奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:36:37', 9);
INSERT INTO `sys_oper_log` VALUES (1066, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1153\"],\"annual\":[\"2014-10-06\"],\"tvSeries\":[\"北平无战事\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/北平无战事_20250222003656A046.jpg\"],\"topicContent\":[\"该剧背景设定在1948年，国共两党决战的关键时刻。在国统区，政经体制混乱失控，物价飞涨，贪官横行，国民政府的统治岌岌可危。故事的主人公方孟敖（刘烨 饰），国民党空军笕桥航校上校教官，因违抗军令接受审判，却因蒋经国的干涉得以免罪，随后被转至国防部预备干部局。方孟敖出身富庶世家，是中央银行北平分行经理方步亭（王庆祥 饰）的公子，同时他也是我党潜伏在国军中的地下党员。方孟敖参与了“孔雀东南飞”行动，调查北平分行的舞弊行为。在这个过程中，他不仅要面对来自国军内部的猜忌和调查，还要应对同僚的暗算和倾轧，同时还要应对战火纷飞的险恶局势。方孟敖和其他地下工作者一起，以他们的智慧和勇气，为新中国的崛起奠定了基石。\"],\"type\":[\"7\"],\"director\":[\"孔笙、李雪\"],\"screenwriter\":[\"刘和平\"],\"actor\":[\"刘烨、陈宝国、倪大红、王庆祥\"],\"episodeNum\":[\"53\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"0\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2015年第三十届中国电视剧飞天奖优秀重大题材类电视剧奖，优秀导演奖（孔笙）、优秀编剧奖（刘和平）、优秀男演员奖（陈宝国）；2015年第二十一届上海电视节白玉兰奖最佳中国电视剧奖、最佳编剧奖（刘和平）。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:37:01', 14);
INSERT INTO `sys_oper_log` VALUES (1067, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1154\"],\"annual\":[\"2014-09-17\"],\"tvSeries\":[\"马向阳下乡记\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/马向阳下乡记_20250222003725A047.jpg\"],\"topicContent\":[\"在官场摸爬滚打多年的马向阳（吴秀波 饰），虽然只是商务局市场科的一个小科长，却早已熟稔官场避实就虚、虚与委蛇的生存法则和太极推手。谁知突如其来的一纸调令，却将他从优哉游哉的城市达到了作为重点扶贫对象的穷乡僻壤。他从一位科长摇身一变成为大槐树村第一书记，但是这顶乌纱帽可真不那么好戴，从没有过乡村工作经验的他束手无策，不明所以，而当面对学识渊博且实践经验丰富的种植专家周冰（王雅捷 饰）、凭借血缘宗族关系在当地享有极高声望的族长刘世荣（李洪涛 饰） 性格泼辣的留守妇女代表李云芳（梁爱琪 饰）等不同身份之人的时候，许多问题似乎变得更不好解决。肩负着领导殷勤期望的马书记，能否升任这一新的岗位？\"],\"type\":[\"15\",\"19\"],\"director\":[\"张永新\"],\"screenwriter\":[\"谷凯\"],\"actor\":[\"吴秀波、王雅捷、李洪涛、梁爱琪\"],\"episodeNum\":[\"40\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"2\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2015年第三十届中国电视剧飞天奖优秀电视剧奖；2016年第二十八届中国电视金鹰奖优秀电视剧奖；2016年第十四届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:37:36', 27);
INSERT INTO `sys_oper_log` VALUES (1068, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1155\"],\"annual\":[\"2014-02-02\"],\"tvSeries\":[\"父母爱情\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/父母爱情_20250222003753A048.jpg\"],\"topicContent\":[\"该剧以青岛某海军军区为背景，海军炮校丛校长（杨立新 饰）和妻子杨涛（娜仁花 饰）为军官举办婚介舞会，两人一心想为大龄军官们解决个人婚配问题。海军军官江德福（郭涛 饰）深受丛校长器重，在丛校长夫妇的引荐下，江德福在舞会上认识了年轻漂亮的安杰（梅婷 饰），并对她心生爱慕。而面对大老粗似的江德福，安杰却一点感觉都没有。由于安杰家庭成分不好，全家人屡次受到江德福的帮助，安杰渐渐发现了貌似粗犷的江德福其实是个机智、可爱的男人，她逐渐接受了江德福的情感，两人结为夫妻。江德福和安杰夫妻共同克服了出身的差异、文化程度的悬殊、生活环境的恶劣以及特殊时期的生存困境，抚养着五个孩子，共同走过了风风雨雨的几十年。孩子们长大成人，步入老年的江德福和安杰回首往事，觉得能携手度此一生是无比幸福的事情。\"],\"type\":[\"12\",\"13\"],\"director\":[\"孔笙\"],\"screenwriter\":[\"刘静\"],\"actor\":[\"郭涛、梅婷、刘琳、任帅\"],\"episodeNum\":[\"44\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2018年第二十四届上海电视节白玉兰奖国际传播奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:37:58', 11);
INSERT INTO `sys_oper_log` VALUES (1069, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1156\"],\"annual\":[\"2014-07-15\"],\"tvSeries\":[\"湄公河大案\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/湄公河大案_20250222004017A049.jpeg\"],\"topicContent\":[\"该剧以湄公河惨案为背景，讲述了中国商船十三名船员在运输途中惨遭杀害后，中国警方迅速组成专案组前往老挝、缅甸、泰国交界的金三角地区进行调查的故事。专案组由江海峰（陈宝国 饰）领导，他们克服重重困难，逐步拨开案情迷雾，最终将嫌疑人锁定在以抢劫、敲诈、贩毒为生的苏沃集团身上。该剧通过紧张的刑侦过程和跨国合作，展现了中国警方的坚定意志和王杰精神，即忠诚、勇敢、智慧和奉献的精神。剧情不仅扣人心弦，也深刻地反映了国家对打击跨国犯罪、保护公民安全的决心和能力。\"],\"type\":[\"1\",\"2\"],\"director\":[\"安战军、游达志（特邀）\"],\"screenwriter\":[\"陈育新\"],\"actor\":[\"陈宝国、王千源、杜志国、李修贤\"],\"episodeNum\":[\"34\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"2\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"0\"],\"awardInformation\":[\"2015年第三十届中国电视剧飞天奖优秀现实题材类电视剧奖、优秀男演员奖（陈宝国）。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:40:22', 10);
INSERT INTO `sys_oper_log` VALUES (1070, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1158\"],\"annual\":[\"2021-02-01\"],\"tvSeries\":[\"觉醒年代\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/觉醒年代_20250222005057A050.jpg\"],\"topicContent\":[\"该剧以1915年《青年杂志》问世到1921年《新青年》成为中国共产党机关刊物为贯穿，展现了从新文化运动到中国共产党建立这段波澜壮阔的历史画卷，讲述觉醒年代的百态人生。该剧以李大钊（张桐 饰）、陈独秀（于和伟 饰）、胡适（朱刚日尧 饰）从相识、相知到分手，走上不同人生道路的传奇故事为基本叙事线，以毛泽东（侯京健 饰）、陈延年（张晚意 饰）、陈乔年（马启越 饰）、邓中夏（查文浩 饰）、赵世炎（林俊毅 饰）等革命青年追求真理的坎坷经历为辅助线，艺术地再现了一批名冠中华的文化大师和一群理想飞扬的热血青年演绎出的一段充满激情、燃烧理想的澎湃岁月，深刻地揭示了马克思主义与中国工人运动相结合和中国共产党建立的历史必然性。\"],\"type\":[\"3\",\"14\",\"19\"],\"director\":[\"张永新\"],\"screenwriter\":[\"龙平平\"],\"actor\":[\"于和伟、张桐、马少骅、朱刚日尧\"],\"episodeNum\":[\"43\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"4\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2021年第二十七届上海电视节白玉兰奖最佳导演奖（张永新）、最佳编剧奖（原创）（龙平平）、最佳男主角奖（于和伟）；2022年第三十一届中国电视金鹰奖最佳电视剧奖、最佳电视剧编剧奖（龙平平）、最佳男配角奖（马少骅）；2022年第三十三届中国电视剧飞天奖优秀电视剧（信仰·使命）、优秀导演奖（张永新）；2022年第十六届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:51:18', 11);
INSERT INTO `sys_oper_log` VALUES (1071, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1157\"],\"annual\":[\"2021-01-12\"],\"tvSeries\":[\"山海情\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/山海情_20250222005200A051.jpg\"],\"topicContent\":[\"该剧从政府建立吊庄基地，号召西吉的农民们移民、搬迁。但飞沙走石的荒漠条件太艰苦，搬迁来的村民第二天就走了一半的背景讲起。马得福（黄轩 饰）用尽各种办法动员大家去吊庄，并帮助村民们留下来。1996年，党中央作出推进东西部对口协作的战略部署，其中确定福建对口帮扶宁夏，共同推进宁夏扶贫工作。福建专家来到村里教村民们种蘑菇，让大家挣到了第一桶金，又想尽办法为蘑菇寻找销路。福建的干部们鼓励、带动宁夏的劳务输出，为村里人去福建打工积极创造条件。扶贫政策四面开花，闽宁镇初具规模。张树成（胡明 饰）走马上任闽宁镇的党委书记，继续三级扬水工程的同时，加强劳务输出、招商引资，闽宁镇旧貌换新颜，越来越多的村民们主动报名搬迁。时光飞逝，闽宁镇变得越来越好。这片土地焕发了新的生机。\"],\"type\":[\"13\",\"15\",\"19\"],\"director\":[\"孔笙、孙墨龙\"],\"screenwriter\":[\"王三毛、未夕、小倔、磊子、邱玉洁、列那\"],\"actor\":[\"黄轩、张嘉益、闫妮、黄觉、姚晨\"],\"episodeNum\":[\"23\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"2\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2021年第二十七届上海电视节白玉兰奖最佳中国电视剧奖、最佳男配角奖（尤勇智）、最佳女配角奖（黄尧）、最佳摄影奖（杨振宇）；2022年中央宣传部第十六届精神文明建设“五个一工程”优秀作品奖；2022年第三十三届中国电视剧飞天奖优秀电视剧（时代·奋斗）、最佳编剧（王三毛、未夕、小倔、磊子、邱玉洁、列那）、优秀女演员（热依扎）；2022年第三十一届中国电视金鹰奖优秀电视剧奖；2022年第十六届精神文明建设“五个一工程”优秀作品奖；2023年第二十八届上海电视节白玉兰奖国际传播奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:52:09', 10);
