INSERT INTO `sys_oper_log` VALUES (1075, '影视管理', 3, 'com.ds.project.front.film.controller.DsFilmController.remove()', 'POST', 1, 'admin', '研发部门', '/front/film/remove', '223.72.68.45', 'XX XX', '{\"ids\":[\"1162\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:53:52', 10);
INSERT INTO `sys_oper_log` VALUES (1076, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1163\"],\"annual\":[\"2020-09-29\"],\"tvSeries\":[\"在一起\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/在一起_20250222005409A052.jpg\"],\"topicContent\":[\"该剧以“抗疫”期间各行各业真实的人物、故事为基础，由《生命的拐点》《摆渡人》《同行》《救护者》《搜索24小时》《火神山》《方舱》《我叫大连》《口罩》《武汉人》十个单元故事组成，讲述了中国军民在抗击新冠肺炎疫情中的人和事：他们中有义无反顾为人民建起一座白衣长城的医护工作者；有万里赴戎机、八方支援的各地医疗队员；有秉承革命军人优良传统、闻令而动、誓死不退的军医；有平凡又伟大的外卖小哥和专车志愿者；有自救互救、守望相助的普通市民；有积极投身火神山医院的建设者；有在联防联控工作中扎根基层的疾控、社区、公安人员；有误打误撞留在武汉成为志愿者投身抗疫事业的年轻人；有克服种种困难转产口罩、为“复产复工”做出贡献的人们。这些普通人构成了全国上下、各行各业抗击疫情的主力军，为抗击疫情做出不可磨灭的贡献。\"],\"type\":[\"16\",\"19\"],\"director\":[\"张黎、沈严、曹盾、汪俊、韩晓军、刘江、滕华涛、林妍、彭三源、杨阳、杨文军、姚晓峰\"],\"screenwriter\":[\"六六、秦雯、高璇、任宝茹、冯骥\"],\"actor\":[\"张嘉益、周一围、谭卓、雷佳音、张静初\"],\"episodeNum\":[\"20\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"3\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2021年第二十七届上海电视节白玉兰奖评委会大奖、国际传播奖；2022年第三十三届中国电视剧飞天奖优秀电视剧奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:54:31', 12);
INSERT INTO `sys_oper_log` VALUES (1077, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1164\"],\"annual\":[\"2019-03-19\"],\"tvSeries\":[\"共产党人刘少奇\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/共产党人刘少奇_20250222005451A053.jpg\"],\"topicContent\":[\"该剧讲述刘少奇同志一生，闯县城、省城、皇城和国门“四道乡关”，寻“实事求是、每求真是”“八字真经”，矢志找寻救国真理和建设新中国道路的故事！1921年，刘少奇（赵波 饰）在莫斯科东方大学入党。一年后他学成回国，领导了“安源路矿大罢工”。随着大革命形势骤然逆转，刘少奇于险恶情境中亲赴白区主持善后。抗战时期，刘少奇进入中央领导核心，并在建国后当选为中央人民政府副主席，在制定国家政治、经济、文化、教育、外交等方针政策方面发挥了重要作用。六十年代初期，中国经济发生严重困难，刘少奇又进行实地调查研究，参与制定了一系列重要的政策措施，使国民经济得到恢复和发展。1980年5月17日刘少奇追悼大会隆重举行，为中国革命和建设奋斗一生的刘少奇虽早已离开，但他坚定不移的共产主义信仰，将永垂不朽！\"],\"type\":[\"13\",\"14\",\"18\",\"19\"],\"director\":[\"嘉娜·沙哈提\"],\"screenwriter\":[\"海波\"],\"actor\":[\"赵波、侯京健、宋佳玲、徐百慧、张晚意\"],\"episodeNum\":[\"46\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2019第十五届精神文明建设“五个一工程”优秀作品奖；2020年第三十二届中国电视剧飞天奖优秀电视剧奖；2020年第三十届中国电视金鹰奖优秀电视剧奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:55:00', 17);
INSERT INTO `sys_oper_log` VALUES (1078, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1165\"],\"annual\":[\"2018-12-10\"],\"tvSeries\":[\"大江大河\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/大江大河_20250222005519A054.jpg\"],\"topicContent\":[\"该剧讲述了宋运辉（王凯 饰）天资聪颖却出身不好，一直备受歧视，但是他把握住了1978年恢复高考的机会，考上大学，勤学苦干，当上了国企的技术人员，在一步步晋升中奠定了成功人生的基础，然而，在新时代的变革中，他也经历了苦恼和迷茫的故事。宋运辉的姐夫雷东宝（杨烁 饰）出身贫寒，属于根正苗红的“大老粗”，行动力十足。在乡村改革的浪潮中，他带领村民紧跟政策，一直走在时代的前沿，但由于自身文化水平不高，眼界不够开阔，最终绊倒在新事物脚下。如果说宋运辉和雷东宝的经历是国营经济和集体经济的缩影，个体户杨巡（董子健 饰）无疑就是个体经济的典型代表。在翻滚向前的时代中，他手忙脚乱抓住过商机，也踩踏过陷阱，生意场上几经波折，最终拥有了自己的产业。\"],\"type\":[\"13\",\"15\",\"19\"],\"director\":[\"孔笙、黄伟\"],\"screenwriter\":[\"袁克平、唐尧\"],\"actor\":[\"王凯、杨烁、董子健、童瑶\"],\"episodeNum\":[\"47\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"2\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2019年第二十五届上海电视节白玉兰奖最佳中国电视剧奖、最佳女配角奖（童瑶）、最佳导演奖（孔笙、黄伟）、最佳编剧奖（改编）（袁克平、唐尧）、最佳美术奖（邵昌勇）；2019年第十五届精神文明建设“五个一工程”优秀作品奖；2020年第三十届中国电视金鹰奖优秀中国电视剧奖、最佳导演奖（孔笙）、最佳女演员奖（童瑶）；2020年第三十二届中国电视剧飞天奖优秀电视剧奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 00:55:27', 10);
INSERT INTO `sys_oper_log` VALUES (1079, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1166\"],\"annual\":[\"2021-09-26\"],\"tvSeries\":[\"功勋\"],\"img\":[\"\"],\"topicContent\":[\"该剧用不同的叙事风格讲述八位功勋人物人生中最精彩的故事。《无名英雄于敏》章节从少年、青年和中年三个时期讲述于敏（雷佳音 饰）投身国防安全事业的故事。《申纪兰的提案》章节着重展现申纪兰（蒋欣 饰）首倡“男女同工同酬”并当选第一届全国人大代表的经历。《孙家栋的天路》章节以无数次的试验失败为切入点，展现以孙家栋（佟大为 饰）为代表的中国科学家永不言弃的探索精神。《能文能武李延年》章节讲述李延年（王雷 饰）在抗美援朝战场上的英雄故事。《默默无闻张富清》章节描绘张富清（郭涛 饰）作为战斗英雄转业后扎根基层的故事。《袁隆平的梦》章节从梦境展开，讲袁隆平（黄志忠 饰）如何为祖国和世界人民的温饱问题不懈奋斗。《黄旭华的深潜》章节以黄旭华（黄晓明 饰）研制核潜艇下潜极限为故事压力点和戏剧转折点，再现中国自主研发核潜艇的艰难历程。《屠呦呦的礼物》章节讲述屠呦呦（周迅 饰）研发抗疟新药青蒿素的全过程，并回答人们对屠呦呦获得诺贝尔奖的某些疑惑。\"],\"type\":[\"3\",\"18\",\"19\"],\"director\":[\"郑晓龙（总）、毛卫宁、沈严、康洪雷、林楠、杨文军、阎建钢、杨阳\"],\"screenwriter\":[\"刘戈建、李修文、王小枪、陈枰、申捷、巩向东、徐速、王小平、宋方金\"],\"actor\":[\"王雷、雷佳音、郭涛、黄晓明、蒋欣\"],\"episodeNum\":[\"48\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2022年第三十三届中国电视剧飞天奖优秀电视剧奖、优秀男演员奖（王雷）；2022年第三十一届中国电视金鹰奖优秀电视剧奖；2022年中央宣传部第十六届精神文明建设“五个一工程”特别奖；2023年第二十八届上海电视节白玉兰奖评委会大奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:06:18', 11);
INSERT INTO `sys_oper_log` VALUES (1080, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1167\"],\"annual\":[\"2022-01-09\"],\"tvSeries\":[\"超越\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/超越_20250222010923A055.jpeg\"],\"topicContent\":[\"该剧以2015年北京申办2022年冬季奥运会成功为历史背景，讲述了“北冰南展”浪潮中，轮滑少女陈冕（李庚希 饰）决定以短道速滑为自己的事业目标，从一个非专业选手，一路过关斩将，最终进入国家队成为主力队员，出征冬奥赛场、为国争光的故事。\"],\"type\":[\"9\",\"16\",\"19\"],\"director\":[\"张晓波\"],\"screenwriter\":[\"李嘉、雷博、杨柳伊、孙双润、张嘉运 、林若君\"],\"actor\":[\"李庚希、胡军、沙溢\"],\"episodeNum\":[\"29\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"3\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2022年第十六届精神文明建设“五个一工程”优秀作品奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:09:34', 16);
INSERT INTO `sys_oper_log` VALUES (1081, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1168\"],\"annual\":[\"2022-12-07\"],\"tvSeries\":[\"县委大院\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/县委大院_20250222010953A056.jpg\"],\"topicContent\":[\"该剧的故事发生在十九大前夕，梅晓歌（胡歌 饰）走马上任光明县县长，与县委书记吕青山（黄磊 饰）、副书记艾鲜枝（吴越 饰）等成为同事，此时摆在他们面前的是急需修复与发展的光明县，林林总总的难题和麻烦接踵而至。梅晓歌情商高，亲和力佳，逐渐和同事打成一片，平衡施政过程里的矛盾；又有破釜沉舟的勇气，到任后马不停蹄地走遍了光明县上百个村子。当选县委书记后，梅晓歌致力于推动深化改革干部作风，坚持绿色发展理念，在保护环境的基础上保障民生，对县城教育进行优化。在县委班子的努力之下，终于实现了光明县脱贫致富、健康发展的治县理想。年轻干部也在实践锻炼中不断成长，做好传承，推倒干部与群众之间的无形藩篱，干群关系焕然一新。\"],\"type\":[\"19\"],\"director\":[\"孔笙、毛珺琳、王宏\"],\"screenwriter\":[\"王小枪\"],\"actor\":[\"胡歌、吴越、张新成、黄磊\"],\"episodeNum\":[\"24\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"3\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2023年第二十八届上海电视节白玉兰奖最佳中国电视剧奖、最佳编剧（原创）奖（王小枪）、最佳女主角奖（吴越）；2024年第三十二届中国电视金鹰奖优秀电视剧奖；2024年第十七届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:10:00', 10);
INSERT INTO `sys_oper_log` VALUES (1082, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1169\"],\"annual\":[\"2022-07-12\"],\"tvSeries\":[\"大山的女儿\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/大山的女儿_20250222011015A057.jpg\"],\"topicContent\":[\"该剧根据真实事迹创作，讲述北师大硕士毕业的黄文秀（杨蓉 饰）主动放弃大城市的工作机会，回到生她养她的家乡，在百色市委宣传部任职，2018年3月，她主动请缨到广西最贫困的一个小山村百坭村任第一书记，白天她走村串户遍访贫困户，分析致贫原因，晚上与“村两委”研究脱贫对策，制定工作方案并全力推进。黄文秀克服困难、不懈努力，在一年多时间内让88户贫困户顺利脱贫。然而一场暴雨，却将黄文秀年轻的生命永远定格在了扶贫路上。虽然黄文秀牺牲了，但是扶贫并没有结束，其他人接过黄文秀的接力棒，努力使百坭村实现了全村脱贫。而之后，黄文秀为百坭村设计的愿景也一一实现，一个幸福的百坭村逐渐呈现在世人眼前。\"],\"type\":[\"15\",\"18\",\"19\"],\"director\":[\"雷献禾、王菁\"],\"screenwriter\":[\"郭中束\"],\"actor\":[\"杨蓉、刘奕君、杜晓帆、涓子、李君峰\"],\"episodeNum\":[\"40\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"3\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2024年第十七届精神文明建设“五个一工程”优秀作品奖\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:10:25', 10);
INSERT INTO `sys_oper_log` VALUES (1083, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1170\"],\"annual\":[\"2022-05-28\"],\"tvSeries\":[\"警察荣誉\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/警察荣誉_20250222011048A058.jpg\"],\"topicContent\":[\"该剧讲述的是见习警员李大为（张若昀 饰）、夏洁（白鹿 饰）、杨树（徐开骋 饰）和赵继伟（曹璐 饰）在派出所的工作与生活。一开始对警察这个职业怀抱各种憧憬，然而当面对巨大的工作压力、尖锐的矛盾冲突以及自媒体时代给派出所工作带来的新挑战时，他们经历了困惑与挫折，也有过迷茫、怀疑甚至放弃的念头，但在人民警察光荣传统的熏陶下，在老一辈的言传身教中，这4个年轻人经受住了考验，迅速成长，他们对自身的使命和荣誉有了新的认识，最终成长为合格的人民警察。\"],\"type\":[\"16\",\"19\"],\"director\":[\"丁黑、鲍成志、符策欣\"],\"screenwriter\":[\"赵冬苓、谭嘉言\"],\"actor\":[\"张若昀、白鹿、王景春、宁理\"],\"episodeNum\":[\"38\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"3\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2024年第三十二届中国电视金鹰奖最佳男配角奖（王景春）\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:10:51', 10);
INSERT INTO `sys_oper_log` VALUES (1084, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1171\"],\"annual\":[\"2023-12-12\"],\"tvSeries\":[\"问苍茫\"],\"img\":[\"\"],\"topicContent\":[\"该剧讲述了1921年至1927年，从中共一大归来的青年毛泽东（王仁君 饰）带着对中华民族将走向何方的忧国之问，如何在矢志不移地践行马克思主义信仰的过程中，以一个“探路人”“早行者”的姿态，从一名追随者成长为先行者、开拓者，并探索出中国革命正确道路的历史故事。从发展团员、党员到发动工人运动，从国共第一次合作到坚决同国民党右派斗争，直到走进田间地头，用脚步丈量出农民运动对于中国革命的意义，青年毛泽东始终恪守着马克思主义和湖湘文化的精髓，向上成长，向下扎根，敢为人先，知行合一。“问苍茫大地，谁主沉浮？”，正是青年毛泽东及其同道的仰天长问和探寻之路，为中国革命开拓出辽阔新天。\"],\"type\":[\"3\",\"14\",\"19\"],\"director\":[\"王伟\"],\"screenwriter\":[\"陈晋、梁振华、翁良平、韩辰辰、胡亚、颜西\"],\"actor\":[\"王仁君、宁理、白客、唐曾、嘉泽\"],\"episodeNum\":[\"32\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"4\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2024年第二十九届上海电视节白玉兰奖评委会奖；2024年第三十二届中国电视金鹰奖优秀电视剧奖；2024年第十七届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:11:17', 10);
INSERT INTO `sys_oper_log` VALUES (1085, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1172\"],\"annual\":[\"2024-02-06\"],\"tvSeries\":[\"南来北往\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/南来北往_20250222011316A059.jpeg\"],\"topicContent\":[\"该剧讲述二十世纪七十年代末，离乡十年归来的老刑警马魁（丁勇岱 饰）与年少气盛优秀的年轻乘警汪新（白敬亭 饰），师徒二人从相互不满，矛盾重重，误解不断到携手作战，默契配合。通过一列火车的人生百态，一群邻里间的人情冷暖，见证伟大祖国的革新与发展，新老两代铁路干警警魂精神薪火传承的故事。\"],\"type\":[\"13\",\"16\"],\"director\":[\"郑晓龙、刘璋牧\"],\"screenwriter\":[\"高满堂、李洲\"],\"actor\":[\"白敬亭、丁勇岱、金晨、姜妍\"],\"episodeNum\":[\"39\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"2\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2024年第二十九届上海电视节白玉兰奖最佳女配角奖（姜妍）；2024年第十七届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:13:27', 10);
INSERT INTO `sys_oper_log` VALUES (1086, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1166\"],\"annual\":[\"2021-09-26\"],\"tvSeries\":[\"功勋\"],\"img\":[\"\"],\"topicContent\":[\"该剧用不同的叙事风格讲述八位功勋人物人生中最精彩的故事。《无名英雄于敏》章节从少年、青年和中年三个时期讲述于敏（雷佳音 饰）投身国防安全事业的故事。《申纪兰的提案》章节着重展现申纪兰（蒋欣 饰）首倡“男女同工同酬”并当选第一届全国人大代表的经历。《孙家栋的天路》章节以无数次的试验失败为切入点，展现以孙家栋（佟大为 饰）为代表的中国科学家永不言弃的探索精神。《能文能武李延年》章节讲述李延年（王雷 饰）在抗美援朝战场上的英雄故事。《默默无闻张富清》章节描绘张富清（郭涛 饰）作为战斗英雄转业后扎根基层的故事。《袁隆平的梦》章节从梦境展开，讲袁隆平（黄志忠 饰）如何为祖国和世界人民的温饱问题不懈奋斗。《黄旭华的深潜》章节以黄旭华（黄晓明 饰）研制核潜艇下潜极限为故事压力点和戏剧转折点，再现中国自主研发核潜艇的艰难历程。《屠呦呦的礼物》章节讲述屠呦呦（周迅 饰）研发抗疟新药青蒿素的全过程，并回答人们对屠呦呦获得诺贝尔奖的某些疑惑。\"],\"type\":[\"3\",\"18\",\"19\"],\"director\":[\"郑晓龙（总）、毛卫宁、沈严、康洪雷、林楠、杨文军、阎建钢、杨阳\"],\"screenwriter\":[\"刘戈建、李修文、王小枪、陈枰、申捷、巩向东、徐速、王小平、宋方金\"],\"actor\":[\"王雷、雷佳音、郭涛、黄晓明、蒋欣\"],\"episodeNum\":[\"48\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2022年第三十三届中国电视剧飞天奖优秀电视剧奖、优秀男演员奖（王雷）；2022年第三十一届中国电视金鹰奖优秀电视剧奖；2022年中央宣传部第十六届精神文明建设“五个一工程”特别奖；2023年第二十八届上海电视节白玉兰奖评委会大奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:14:41', 6);
