INSERT INTO `sys_oper_log` VALUES (1088, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1166\"],\"annual\":[\"2021-09-26\"],\"tvSeries\":[\"功勋\"],\"img\":[\"\"],\"topicContent\":[\"该剧用不同的叙事风格讲述八位功勋人物人生中最精彩的故事。《无名英雄于敏》章节从少年、青年和中年三个时期讲述于敏（雷佳音 饰）投身国防安全事业的故事。《申纪兰的提案》章节着重展现申纪兰（蒋欣 饰）首倡“男女同工同酬”并当选第一届全国人大代表的经历。《孙家栋的天路》章节以无数次的试验失败为切入点，展现以孙家栋（佟大为 饰）为代表的中国科学家永不言弃的探索精神。《能文能武李延年》章节讲述李延年（王雷 饰）在抗美援朝战场上的英雄故事。《默默无闻张富清》章节描绘张富清（郭涛 饰）作为战斗英雄转业后扎根基层的故事。《袁隆平的梦》章节从梦境展开，讲袁隆平（黄志忠 饰）如何为祖国和世界人民的温饱问题不懈奋斗。《黄旭华的深潜》章节以黄旭华（黄晓明 饰）研制核潜艇下潜极限为故事压力点和戏剧转折点，再现中国自主研发核潜艇的艰难历程。《屠呦呦的礼物》章节讲述屠呦呦（周迅 饰）研发抗疟新药青蒿素的全过程，并回答人们对屠呦呦获得诺贝尔奖的某些疑惑。\"],\"type\":[\"3\",\"18\",\"19\"],\"director\":[\"郑晓龙（总）、毛卫宁、沈严、康洪雷、林楠、杨文军、阎建钢、杨阳\"],\"screenwriter\":[\"刘戈建、李修文、王小枪、陈枰、申捷、巩向东、徐速、王小平、宋方金\"],\"actor\":[\"王雷、雷佳音、郭涛、黄晓明、蒋欣\"],\"episodeNum\":[\"48\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2022年第三十三届中国电视剧飞天奖优秀电视剧奖、优秀男演员奖（王雷）；2022年第三十一届中国电视金鹰奖优秀电视剧奖；2022年中央宣传部第十六届精神文明建设“五个一工程”特别奖；2023年第二十八届上海电视节白玉兰奖评委会大奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:16:03', 9);
INSERT INTO `sys_oper_log` VALUES (1089, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1166\"],\"annual\":[\"2021-09-26\"],\"tvSeries\":[\"功勋\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/功勋_20250222011723A060.jpeg\"],\"topicContent\":[\"该剧用不同的叙事风格讲述八位功勋人物人生中最精彩的故事。《无名英雄于敏》章节从少年、青年和中年三个时期讲述于敏（雷佳音 饰）投身国防安全事业的故事。《申纪兰的提案》章节着重展现申纪兰（蒋欣 饰）首倡“男女同工同酬”并当选第一届全国人大代表的经历。《孙家栋的天路》章节以无数次的试验失败为切入点，展现以孙家栋（佟大为 饰）为代表的中国科学家永不言弃的探索精神。《能文能武李延年》章节讲述李延年（王雷 饰）在抗美援朝战场上的英雄故事。《默默无闻张富清》章节描绘张富清（郭涛 饰）作为战斗英雄转业后扎根基层的故事。《袁隆平的梦》章节从梦境展开，讲袁隆平（黄志忠 饰）如何为祖国和世界人民的温饱问题不懈奋斗。《黄旭华的深潜》章节以黄旭华（黄晓明 饰）研制核潜艇下潜极限为故事压力点和戏剧转折点，再现中国自主研发核潜艇的艰难历程。《屠呦呦的礼物》章节讲述屠呦呦（周迅 饰）研发抗疟新药青蒿素的全过程，并回答人们对屠呦呦获得诺贝尔奖的某些疑惑。\"],\"type\":[\"3\",\"18\",\"19\"],\"director\":[\"郑晓龙（总）、毛卫宁、沈严、康洪雷、林楠、杨文军、阎建钢、杨阳\"],\"screenwriter\":[\"刘戈建、李修文、王小枪、陈枰、申捷、巩向东、徐速、王小平、宋方金\"],\"actor\":[\"王雷、雷佳音、郭涛、黄晓明、蒋欣\"],\"episodeNum\":[\"48\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2022年第三十三届中国电视剧飞天奖优秀电视剧奖、优秀男演员奖（王雷）；2022年第三十一届中国电视金鹰奖优秀电视剧奖；2022年中央宣传部第十六届精神文明建设“五个一工程”特别奖；2023年第二十八届上海电视节白玉兰奖评委会大奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:17:26', 12);
INSERT INTO `sys_oper_log` VALUES (1090, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1171\"],\"annual\":[\"2023-12-12\"],\"tvSeries\":[\"问苍茫\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/问苍茫_20250222011752A061.jpeg\"],\"topicContent\":[\"该剧讲述了1921年至1927年，从中共一大归来的青年毛泽东（王仁君 饰）带着对中华民族将走向何方的忧国之问，如何在矢志不移地践行马克思主义信仰的过程中，以一个“探路人”“早行者”的姿态，从一名追随者成长为先行者、开拓者，并探索出中国革命正确道路的历史故事。从发展团员、党员到发动工人运动，从国共第一次合作到坚决同国民党右派斗争，直到走进田间地头，用脚步丈量出农民运动对于中国革命的意义，青年毛泽东始终恪守着马克思主义和湖湘文化的精髓，向上成长，向下扎根，敢为人先，知行合一。“问苍茫大地，谁主沉浮？”，正是青年毛泽东及其同道的仰天长问和探寻之路，为中国革命开拓出辽阔新天。\"],\"type\":[\"3\",\"14\",\"19\"],\"director\":[\"王伟\"],\"screenwriter\":[\"陈晋、梁振华、翁良平、韩辰辰、胡亚、颜西\"],\"actor\":[\"王仁君、宁理、白客、唐曾、嘉泽\"],\"episodeNum\":[\"32\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"4\"],\"url\":[\"\"],\"kind\":[\"1\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2024年第二十九届上海电视节白玉兰奖评委会奖；2024年第三十二届中国电视金鹰奖优秀电视剧奖；2024年第十七届精神文明建设“五个一工程”优秀作品奖。\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:17:56', 13);
INSERT INTO `sys_oper_log` VALUES (1091, '影视管理', 1, 'com.ds.project.front.film.controller.DsFilmController.addSave()', 'POST', 1, 'admin', '研发部门', '/front/film/add', '223.72.68.45', 'XX XX', '{\"annual\":[\"2021-07-01\"],\"tvSeries\":[\"革命者\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/22/革命者_20250222012818A062.jpeg\"],\"topicContent\":[\"该片聚焦“中国共产主义运动先驱李大钊”的电影，讲述了在1912至1927年间，李大钊引领一众革命志士为救国存亡积极奔走、奋起反抗的壮阔革命历史故事。\"],\"type\":[\"3\",\"14\",\"19\"],\"director\":[\"徐展雄\"],\"screenwriter\":[\"管虎、吴兵、张珂、京榆\"],\"actor\":[\"张颂文、佟丽娅 、成泰燊、彭昱畅 \"],\"episodeNum\":[\"\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"4\"],\"url\":[\"\"],\"kind\":[\"0\"],\"recommend\":[\"1\"],\"awardInformation\":[\"\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-22 01:29:25', 18);
