INSERT INTO `sys_oper_log` VALUES (1192, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1059\"],\"annual\":[\"2016-09-30\"],\"tvSeries\":[\"湄公河行动\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/23/湄公河行动_20250223083835A001.jpeg\"],\"topicContent\":[\"该片讲述了2011年10月5日清晨，两艘中国商船在 湄公河 金三角流域遇袭，船上13名中国船员全部遇难，并在船上发现90万粒毒品。这宗枪杀十三名中国船员的血腥冤案，掀起了悲剧的序幕。面对矛头指向中国运毒、颠倒是非的舆论，为了还遇难同胞一个清白，中国决定派出缉毒精英，组成此次案件的特别行动小组，以高刚 （ 张涵予 饰）为队长，潜入金三角查明真相，竭力揪出案件的幕后黑手。然而缉拿真凶的过程并非他们想得那么简单，事件的进展扑朔迷离，通往真相的道路更是险象环生 。\"],\"type\":[\"19\"],\"director\":[\"林超贤\"],\"screenwriter\":[\"朱镜祺、刘小群、谭惠贞、林明杰、林超贤、麦天枢\"],\"actor\":[\"张涵予、彭于晏、冯文娟\"],\"episodeNum\":[\"\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"3\"],\"url\":[\"\"],\"kind\":[\"0\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2017年第三十一届中国电影金鸡奖最佳故事片奖；2018年第十七届中国电影华表奖优秀故事片奖；2017年第十四届精神文明建设“五个一工程”优秀作品奖。\"],\"sortNum\":[\"10\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 08:38:40', 189);
INSERT INTO `sys_oper_log` VALUES (1193, '影视管理', 2, 'com.ds.project.front.film.controller.DsFilmController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/film/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"1076\"],\"annual\":[\"2023-09-28\"],\"tvSeries\":[\"志愿军：雄兵出击\"],\"img\":[\"http://39.106.153.224:8888/profile/upload/2025/02/23/志愿军：雄兵出击_20250223103227A001.jpeg\"],\"topicContent\":[\"该片讲述了1949年建国初期，新中国面临“内忧外患”局面。朝鲜内战爆发以来，美军屡在中朝边境挑衅，平民惨遭轰炸。为了维护来之不易的和平、为了世代长久的安稳，1950年10月，中国人民志愿军入朝，“抗美援朝”战争拉开帷幕。 这是一场“举国之战”—— 朝鲜战场，即使军备实力对比悬殊，我军却用壮烈牺牲换回节节胜利； 外交舞台，中华人民共和国代表团首度亮相联合国，中国新声赢得国际敬畏。 新中国，寸土不让扬国威；新青年，意气风发保家国。\"],\"type\":[\"3\",\"7\",\"19\"],\"director\":[\"陈凯歌\"],\"screenwriter\":[\"张珂\"],\"actor\":[\"唐国强、王砚辉、刘劲\"],\"episodeNum\":[\"\"],\"reasons\":[\"\"],\"chronologicalDivision\":[\"1\"],\"url\":[\"\"],\"kind\":[\"0\"],\"recommend\":[\"1\"],\"awardInformation\":[\"2024年第三十七届中国电影金鸡奖评委会特别奖、最佳导演奖（陈凯歌）；2024年第三十七届大众电影百花奖最佳影片奖；2024年第十七届精神文明建设“五个一工程”优秀作品奖。\"],\"sortNum\":[\"10\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 10:32:32', 215);
INSERT INTO `sys_oper_log` VALUES (1194, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"210\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 14px;\\\">全心全意为人民服务是党的根本宗旨。延安时期，毛泽东同志在追悼张思德同志时发表的《为人民服务》的演讲，深刻揭示了党群关系、干群关系、军民关系的真谛。</span></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ——摘自习近平总书记2015年2月15日在陕西考察工作结束时的重要讲话</p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 11:29:42', 192);
