INSERT INTO `sys_oper_log` VALUES (1200, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"160\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 18px;\\\"><b>井冈山时期留给我们最为宝贵的财富，就是跨越时空的井冈山精神。井冈山精神，最重要的方面就是坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利</b>。</span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\"> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ——摘自习近平同志《论中国共产党历史》</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 11:57:30', 22);
