INSERT INTO `sys_oper_log` VALUES (1204, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"210\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px; font-family: Arial;\\\"><b>全心全意为人民服务是党的根本宗旨。延安时期，毛泽东同志在追悼张思德同志时发表的《为人民服务》的演讲，深刻揭示了党群关系、干群关系、军民关系的真谛。</b></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 14px;\\\"><span style=\\\"font-family: &quot;Times New Roman&quot;;\\\"><span style=\\\"font-size: 24px; font-family: Arial;\\\">&nbsp;——摘自习近平总书记2015年2月15日在陕西考察工作结束时的重要讲话</span></span></span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:01:51', 19);
INSERT INTO `sys_oper_log` VALUES (1205, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"210\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px; font-family: Arial;\\\"><b>全心全意为人民服务是党的根本宗旨。延安时期，毛泽东同志在追悼张思德同志时发表的《为人民服务》的演讲，深刻揭示了党群关系、干群关系、军民关系的真谛。</b></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 14px;\\\"><span style=\\\"font-family: &quot;Times New Roman&quot;;\\\"><span style=\\\"font-size: 24px; font-family: Arial;\\\">&nbsp;<span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2015年2月15日在陕西考察工作结束时的重要讲话</span></span></span></span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:02:33', 26);
INSERT INTO `sys_oper_log` VALUES (1206, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"209\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>老区和老区人民，为我们党领导的中国革命作出了重大牺牲和贡献。这些牺牲和贡献永远镌刻在中国共产党、中国人民解放军、中华人民共和国的历史丰碑上。我们要永远珍惜、永远铭记老区和老区人民的这些牺牲和贡献，继承和发扬老区和老区人民的光荣传统，为实现“两个一百年”奋斗目标、实现中华民族伟大复兴的中国梦而不懈奋斗！\\r\\n</b></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px;\\\"> ——摘自习近平总书记2015年在陕甘宁革命老区脱贫致富座谈会上的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:03:21', 36);
INSERT INTO `sys_oper_log` VALUES (1207, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"208\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<span style=\\\"font-size: 24px;\\\"><b>沂蒙精神是红色革命精神之一 ，是临沂人民在长期的革命和建设实践中形成的先进群体意识，是中华民族优秀文化的重要组成部分，是临沂人民乃至全国人民宝贵的精神财富。2022年3月，经党中央批准，沂蒙精神基本内涵正式表述为“党群同心、军民情深、水乳交融、生死与共”。</b></span>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:04:45', 47);
INSERT INTO `sys_oper_log` VALUES (1208, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"207\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>鄂豫皖苏区根据地是我们党的重要建党基地，焦裕禄精神、红旗渠精神、大别山精神等都是我们党的宝贵精神财富。</b>\\r\\n</span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px;\\\"> ——摘自习近平总书记2019年9月在河南考察时的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:05:05', 23);
INSERT INTO `sys_oper_log` VALUES (1209, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"206\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>山西也是具有光荣革命传统的地方，是八路军总部所在地，是抗日战争主战场之一，建立了晋绥、晋察冀、晋冀鲁豫抗日根据地，平型关大捷、百团大战等闻名中外，太行精神、吕梁精神是我们党宝贵的精神财富。这些都要充分挖掘和利用，以丰富多彩的历史文化、红色文化资源为山西发展提供精神力量。\\r\\n</b></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px;\\\"> ——摘自习近平总书记2020年5月在山西考察时的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:06:13', 20);
INSERT INTO `sys_oper_log` VALUES (1210, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"170\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>延安是革命圣地。延安时期是我们党领导的中国革命事业从低潮走向高潮、实现历史性转折的时期。老一辈革命家和老一代共产党人在延安时期留下的优良传统和作风，培育形成的以坚定正确的政治方向、解放思想实事求是的思想路线、全心全意为人民服务的根本宗旨、自力更生艰苦奋斗的创业精神为主要内容的延安精神，是我们党的宝贵精神财富。</b></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px;\\\">\\r\\n——摘自习近平总书记2015年2月15日在陕西考察工作结束时的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:06:31', 23);
INSERT INTO `sys_oper_log` VALUES (1211, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"160\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 18px;\\\"><b><span style=\\\"font-size: 24px; font-family: &quot;Helvetica Neue&quot;;\\\">井冈山时期留给我们最为宝贵的财富，就是跨越时空的井冈山精神。井冈山精神，最重要的方面就是坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利</span></b><span style=\\\"font-size: 24px; font-family: &quot;Helvetica Neue&quot;;\\\">。</span></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px; font-family: &quot;Helvetica Neue&quot;;\\\"> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\\\"font-size: 18px;\\\">——摘自习近平同志《论中国共产党历史》</span></span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:07:40', 19);
