INSERT INTO `sys_oper_log` VALUES (1213, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"207\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>鄂豫皖苏区根据地是我们党的重要建党基地，焦裕禄精神、红旗渠精神、大别山精神等都是我们党的宝贵精神财富。</b>\\r\\n</span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px;\\\"> <span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2019年9月在河南考察时的重要讲话</span></span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:08:08', 37);
INSERT INTO `sys_oper_log` VALUES (1214, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"206\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>山西也是具有光荣革命传统的地方，是八路军总部所在地，是抗日战争主战场之一，建立了晋绥、晋察冀、晋冀鲁豫抗日根据地，平型关大捷、百团大战等闻名中外，太行精神、吕梁精神是我们党宝贵的精神财富。这些都要充分挖掘和利用，以丰富多彩的历史文化、红色文化资源为山西发展提供精神力量。\\r\\n</b></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px;\\\"> <span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2020年5月在山西考察时的重要讲话</span></span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:08:17', 21);
INSERT INTO `sys_oper_log` VALUES (1215, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"170\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>延安是革命圣地。延安时期是我们党领导的中国革命事业从低潮走向高潮、实现历史性转折的时期。老一辈革命家和老一代共产党人在延安时期留下的优良传统和作风，培育形成的以坚定正确的政治方向、解放思想实事求是的思想路线、全心全意为人民服务的根本宗旨、自力更生艰苦奋斗的创业精神为主要内容的延安精神，是我们党的宝贵精神财富。</b></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px;\\\">\\r\\n<span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2015年2月15日在陕西考察工作结束时的重要讲话</span></span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:08:25', 21);
INSERT INTO `sys_oper_log` VALUES (1216, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"169\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">九一八事变后，中国人民就在白山黑水间奋起抵抗，成为中国人民抗日战争的起点，同时揭开了世界反法西斯战争的序幕。</span></b></p><p style=\\\"text-align: right;\\\">\\r\\n<span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利75周年座谈会上的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:08:45', 25);
INSERT INTO `sys_oper_log` VALUES (1217, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"168\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>以照金为中心的陕甘边革命根据地，在中国革命史上写下了光辉的一页。要加强对革命根据地历史的研究，总结历史经验，更好发扬革命精神和优良作风。</b></span></p><p><br></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2015年2月14日在陕西考察时的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:09:24', 21);
INSERT INTO `sys_oper_log` VALUES (1218, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"168\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>以照金为中心的陕甘边革命根据地，在中国革命史上写下了光辉的一页。要加强对革命根据地历史的研究，总结历史经验，更好发扬革命精神和优良作风。</b></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2015年2月14日在陕西考察时的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:09:46', 20);
INSERT INTO `sys_oper_log` VALUES (1219, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"166\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">红岩精神是中国共产党在国民党统治地区革命实践中形成的革命精神，在国民党反动派实施的白色恐怖下，一大批共产党人置个人安危于不顾，把天下兴亡的责任担在肩上，为革命奉献自己的全部力量，甚至不惜牺牲生命，展现了坚如磐石的理想信念，展现了和衷共济的爱国情怀，展现了百折不挠的浩然正气。</span></b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——《弘扬红岩精神，赓续红色血脉》原刊于《 人民日报 》（ 2021年10月21日 01 版）</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:10:09', 16);
INSERT INTO `sys_oper_log` VALUES (1220, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"160\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 18px;\\\"><b><span style=\\\"font-size: 24px; font-family: &quot;Helvetica Neue&quot;;\\\">井冈山时期留给我们最为宝贵的财富，就是跨越时空的井冈山精神。井冈山精神，最重要的方面就是坚定信念、艰苦奋斗，实事求是、敢闯新路，依靠群众、勇于胜利</span></b><span style=\\\"font-size: 24px; font-family: &quot;Helvetica Neue&quot;;\\\">。</span></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px; font-family: &quot;Helvetica Neue&quot;;\\\"> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\\\"font-size: 18px;\\\">——摘自习近平同志《论中国共产党历史》</span></span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:10:23', 21);
INSERT INTO `sys_oper_log` VALUES (1221, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"161\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">在革命根据地的创建和发展中，在建立红色政权、探索革命道路的实践中，无数革命先辈用鲜血和生命铸就了以坚定信念、求真务实、一心为民、清正廉洁、艰苦奋斗、争创一流、无私奉献等为主要内涵的苏区精神。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平同志在纪念中央革命根据地创建暨中华苏维埃共和国成立80周年座谈会上的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:10:45', 20);
INSERT INTO `sys_oper_log` VALUES (1222, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"162\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>伟大长征精神，就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神；就是为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲的精神；就是坚持独立自主、实事求是，一切从实际出发的精神；就是顾全大局、严守纪律、紧密团结的精神；就是紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的精神。</b></span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 24px;\\\">\\r\\n<span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在纪念红军长征胜利80周年大会上的讲话</span></span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:12:17', 18);
INSERT INTO `sys_oper_log` VALUES (1223, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"163\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">遵义会议作为我们党历史上一次具有伟大转折意义的重要会议，在把马克思主义基本原理同中国具体实际相结合、坚持走独立自主道路、坚定正确的政治路线和政策策略、建设坚强成熟的中央领导集体等方面，留下宝贵经验和重要启示。我们要运用好遵义会议历史经验，让遵义会议精神永放光芒。</span>\\r\\n</b></p><p><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2015年6月16日至18日在贵州调研时的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:12:46', 39);
INSERT INTO `sys_oper_log` VALUES (1224, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"164\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>延安精神培育了一代代中国共产党人，是我们党的宝贵精神财富。要坚持不懈用延安精神教育广大党员、干部，用以滋养初心、淬炼灵魂，从中汲取信仰的力量、查找党性的差距、校准前进的方向。</b></span>\\r\\n</p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自2020年4月习近平总书记在陕西考察时的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:13:03', 24);
INSERT INTO `sys_oper_log` VALUES (1225, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"167\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>全党同志要不断学习领会“两个务必”的深邃思想，始终做到谦虚谨慎、艰苦奋斗、实事求是、一心为民，继续把人民对我们党的“考试”、把我们党正在经受和将要经受各种考验的“考试”考好，使我们的党永远不变质、我们的红色江山永远不变色。</b></span>\\r\\n</p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2013年在河北省调研指导党的群众路线教育实践活动时的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:13:26', 29);
INSERT INTO `sys_oper_log` VALUES (1226, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"165\"],\"parentId\":[\"105\"],\"parentName\":[\"新民主主义革命时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">中国人民在抗日战争的壮阔进程中孕育出伟大抗战精神，向世界展示了天下兴亡、匹夫有责的爱国情怀，视死如归、宁死不屈的民族气节，不畏强暴、血战到底的英雄气概，百折不挠、坚忍不拔的必胜信念。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利75周年座谈会上的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:13:44', 19);
INSERT INTO `sys_oper_log` VALUES (1227, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"181\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">红旗渠建设中，孕育形成了“自力更生、艰苦创业、团结协作、无私奉献”的红旗渠精神，引领着勤劳勇敢的林州人民“又踏层峰望眼开”，谱写了“战太行、出太行、富太行、美太行、福太行”的发展五部曲。</span> </b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——《精神长河 映照初心》刊载于《光明日报》</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:14:32', 23);
INSERT INTO `sys_oper_log` VALUES (1228, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"177\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>在波澜壮阔的抗美援朝战争中，英雄的中国人民志愿军始终发扬祖国和人民利益高于一切、为了祖国和民族的尊严而奋不顾身的爱国主义精神，英勇顽强、舍生忘死的革命英雄主义精神，不畏艰难困苦、始终保持高昂士气的革命乐观主义精神，为完成祖国和人民赋予的使命、慷慨奉献自己一切的革命忠诚精神，为了人类和平与正义事业而奋斗的国际主义精神，锻造了伟大抗美援朝精神。</b></span>\\r\\n</p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在纪念中国人民志愿军抗美援朝出国作战70周年大会上的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:19:21', 19);
INSERT INTO `sys_oper_log` VALUES (1229, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"178\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>希望广大科技工作者不忘初心、牢记使命，秉持国家利益和人民利益至上，继承和发扬老一辈科学家胸怀祖国、服务人民的优秀品质，弘扬“两弹一星”精神，主动肩负起历史重任，把自己的科学追求融入建设社会主义现代化国家的伟大事业中去。</b></span>\\r\\n</p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在科学家座谈会上的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:20:10', 33);
INSERT INTO `sys_oper_log` VALUES (1230, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"179\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>我们既要学习雷锋的精神，也要学习雷锋的做法，把崇高理想信念和道德品质追求转化为具体行动，体现在平凡的工作生活中，作出自己应有的贡献，把雷锋精神代代传承下去。</b></span>\\r\\n</p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在参观抚顺市雷锋纪念馆时的讲话</span></p><p><br></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:20:37', 24);
INSERT INTO `sys_oper_log` VALUES (1231, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"188\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">“西迁精神”的核心是爱国主义，精髓是听党指挥跟党走，与党和国家、与民族和人民同呼吸、共命运，具有深刻现实意义和历史意义。</span></b></p><p style=\\\"text-align: right;\\\">\\r\\n<span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2020年4月在陕西考察时的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 12:20:56', 22);
INSERT INTO `sys_oper_log` VALUES (1232, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"186\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">无论时代怎样变迁，王杰的“三不伸手”精神始终闪闪发光。习近平总书记在王杰生前所在连队视察时指出，王杰“在荣誉上不伸手，在待遇上不伸手，在物质上不伸手”，这“三不伸手”是一面镜子，共产党员都要好好照照这面镜子。</span></b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——《一种不同寻常的精神境界》刊载于《光明日报》</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:49:59', 17);
INSERT INTO `sys_oper_log` VALUES (1233, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"180\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">要特别学习弘扬焦裕禄同志“心中装着全体人民、唯独没有他自己”的公仆情怀，凡事探求就里、“吃别人嚼过的馍没味道”的求实作风，“敢教日月换新天”、“革命者要在困难面前逞英雄”的奋斗精神，艰苦朴素、廉洁奉公、“任何时候都不搞特殊化”的道德情操。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在调研指导兰考县党的群众路线教育实践活动时的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:50:22', 25);
INSERT INTO `sys_oper_log` VALUES (1234, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"182\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>农垦为保障国家粮食安全、支援国家建设、维护边疆稳定作出了重大贡献。要贯彻新发展理念，加快建设现代农业的大基地、大企业、大产业，深化农垦体制改革，全面增强农垦内生动力、发展活力、整体实力，更好发挥农垦在现代农业建设中的骨干作用。</b></span>\\r\\n</p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——习近平总书记2018年9月25日在黑龙江农垦建三江管理局考察调研时强调</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:50:44', 28);
INSERT INTO `sys_oper_log` VALUES (1235, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"183\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">当年，10多万军民在极其艰苦的条件下团结奋斗，创造了世界公路史上的奇迹，结束了西藏没有公路的历史。60年来，在建设和养护公路的过程中，形成和发扬了一不怕苦、二不怕死，顽强拼搏、甘当路石，军民一家、民族团结的“两路”精神。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2014年就川藏青藏公路建成通车60周年作出的重要批示</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:51:08', 22);
INSERT INTO `sys_oper_log` VALUES (1236, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"198\"],\"parentId\":[\"110\"],\"parentName\":[\"中国特色社会主义新时代\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">脱贫攻坚伟大斗争，锻造形成了“上下同心、尽锐出战、精准务实、开拓创新、攻坚克难、不负人民”的脱贫攻坚精神。脱贫攻坚精神，是中国共产党性质宗旨、中国人民意志品质、中华民族精神的生动写照，是爱国主义、集体主义、社会主义思想的集中体现，是中国精神、中国价值、中国力量的充分彰显，赓续传承了伟大民族精神和时代精神。</span></b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2021年2月25日在全国脱贫攻坚总结表彰大会上的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:51:36', 23);
INSERT INTO `sys_oper_log` VALUES (1237, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"205\"],\"parentId\":[\"110\"],\"parentName\":[\"中国特色社会主义新时代\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 18px;\\\"><span style=\\\"font-size: 24px;\\\"><b>26年来，参与北斗系统研制建设的全体人员迎难而上、敢打硬仗、接续奋斗，发扬“两弹一星”精神，培育了新时代北斗精神，要传承好、弘扬好。要推广北斗系统应用，做好确保系统稳定运行等后续各项工作，为推动我国经济社会发展、推动构建人类命运共同体作出新的更大贡献。</b></span>\\r\\n</span></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——习近平总书记2020年7月31日在参观北斗系统建设发展成果展览展示时强调</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:51:57', 25);
INSERT INTO `sys_oper_log` VALUES (1238, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"204\"],\"parentId\":[\"110\"],\"parentName\":[\"中国特色社会主义新时代\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>古丝绸之路绵亘万里，延续千年，积淀了以和平合作、开放包容、互学互鉴、互利共赢为核心的丝路精神。这是人类文明的宝贵遗产。</b></span></p><p style=\\\"text-align: right;\\\">\\r\\n<span style=\\\"font-size: 18px;\\\">——摘自习近平主席2017年5月14日在首届“一带一路”国际合作高峰论坛开幕式上的主旨演讲</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:52:22', 19);
INSERT INTO `sys_oper_log` VALUES (1239, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"203\"],\"parentId\":[\"110\"],\"parentName\":[\"中国特色社会主义新时代\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>17年来，参与探月工程研制建设的全体人员大力弘扬追逐梦想、勇于探索、协同攻坚、合作共赢的探月精神，不断攀登新的科技高峰，可喜可贺、令人欣慰。</b></span>\\r\\n</p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——习近平总书记2021年2月22日在会见探月工程嫦娥五号任务参研参试人员代表并参观月球样品和探月工程成果展览时强调</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:52:41', 44);
INSERT INTO `sys_oper_log` VALUES (1240, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"184\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">广大干部特别是西藏干部要发扬“老西藏精神”，缺氧不缺精神、艰苦不怕吃苦、海拔高境界更高，在工作中不断增强责任感、使命感，增强能力、锤炼作风。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2020年8月在中央第七次西藏工作座谈会上的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:53:00', 20);
INSERT INTO `sys_oper_log` VALUES (1241, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"202\"],\"parentId\":[\"110\"],\"parentName\":[\"中国特色社会主义新时代\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">企业家要带领企业战胜当前的困难，走向更辉煌的未来，就要在爱国、创新、诚信、社会责任和国际视野等方面不断提升自己，努力成为新时代构建新发展格局、建设现代化经济体系、推动高质量发展的生力军。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2020年7月21日在企业家座谈会上的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:53:20', 20);
INSERT INTO `sys_oper_log` VALUES (1242, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"201\"],\"parentId\":[\"110\"],\"parentName\":[\"中国特色社会主义新时代\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">在中华民族伟大复兴的征程上，一代又一代科学家心系祖国和人民，不畏艰难，无私奉献，为科学技术进步、人民生活改善、中华民族发展作出了重大贡献。新时代更需要继承发扬以国家民族命运为己任的爱国主义精神，更需要继续发扬以爱国主义为底色的科学家精神。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在中国科学院第二十次院士大会、中国工程院第十五次院士大会、中国科协第十次全国代表大会上的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:53:40', 17);
INSERT INTO `sys_oper_log` VALUES (1243, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"185\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">六十年来，几代大庆人艰苦创业、接力奋斗，在亘古荒原上建成我国最大的石油生产基地。大庆油田的卓越贡献已经镌刻在伟大祖国的历史丰碑上，大庆精神、铁人精神已经成为中华民族伟大精神的重要组成部分。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——习近平总书记致信祝贺大庆油田发现60周年强调</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:54:11', 27);
INSERT INTO `sys_oper_log` VALUES (1244, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"187\"],\"parentId\":[\"108\"],\"parentName\":[\"社会主义革命和建设时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">塞罕坝林场建设史是一部可歌可泣的艰苦奋斗史。你们用实际行动铸就了牢记使命、艰苦创业、绿色发展的塞罕坝精神，这对全国生态文明建设具有重要示范意义。抓生态文明建设，既要靠物质，也要靠精神。要传承好塞罕坝精神，深刻理解和落实生态文明理念，再接再厉、二次创业，在实现第二个百年奋斗目标新征程上再建功立业。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2021年8月23日在河北承德塞罕坝机械林场考察时的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:54:28', 22);
INSERT INTO `sys_oper_log` VALUES (1245, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"200\"],\"parentId\":[\"110\"],\"parentName\":[\"中国特色社会主义新时代\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">在中华文化里，牛是勤劳、奉献、奋进、力量的象征。人们把为民服务、无私奉献比喻为孺子牛，把创新发展、攻坚克难比喻为拓荒牛，把艰苦奋斗、吃苦耐劳比喻为老黄牛。前进道路上，我们要大力发扬孺子牛、拓荒牛、老黄牛精神，以不怕苦、能吃苦的牛劲牛力，不用扬鞭自奋蹄，继续为中华民族伟大复兴辛勤耕耘、勇往直前，在新时代创造新的历史辉煌！</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在2021年春节团拜会上的重要讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:54:46', 17);
INSERT INTO `sys_oper_log` VALUES (1246, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"199\"],\"parentId\":[\"110\"],\"parentName\":[\"中国特色社会主义新时代\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">伟大抗疫精神，同中华民族长期形成的特质禀赋和文化基因一脉相承，是爱国主义、集体主义、社会主义精神的传承和发展，是中国精神的生动诠释，丰富了民族精神和时代精神的内涵。我们要在全社会大力弘扬伟大抗疫精神，使之转化为全面建设社会主义现代化国家、实现中华民族伟大复兴的强大力量。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在全国抗击新冠肺炎疫情表彰大会上的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:55:13', 17);
INSERT INTO `sys_oper_log` VALUES (1247, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"194\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">要坚持抗震救灾工作和经济社会发展两手抓、两不误，大力弘扬伟大抗震救灾精神，大力发挥各级党组织领导核心和战斗堡垒作用、广大党员先锋模范作用，引导灾区群众广泛开展自力更生、生产自救活动，在中央和四川省大力支持下，积极发展生产、建设家园，用自己的双手创造幸福美好的生活。</span></b></p><p style=\\\"text-align: right;\\\">\\r\\n<span style=\\\"font-size: 18px;\\\">——摘自习近平总书记就芦山地震抗震救灾工作作出的重要指示</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 14:58:29', 17);
INSERT INTO `sys_oper_log` VALUES (1248, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"189\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">四十年的实践充分证明，改革开放是党和人民大踏步赶上时代的重要法宝，是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招。</span></b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2018年12月18日在庆祝改革开放40周年大会上的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 15:27:37', 16);
INSERT INTO `sys_oper_log` VALUES (1249, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"190\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">经济特区要勇于扛起历史责任，适应国内外形势新变化，按照国家发展新要求，顺应人民新期待，发扬敢闯敢试、敢为人先、埋头苦干的特区精神，始终站在改革开放最前沿，在各方面体制机制改革方面先行先试、大胆探索，为全国提供更多可复制可推广的经验。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在庆祝海南建省办经济特区30周年大会上的讲话</span><span style=\\\"font-size: 18px;\\\">﻿</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 15:28:14', 18);
INSERT INTO `sys_oper_log` VALUES (1250, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"191\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">广大干部群众和人民解放军、武警官兵坚决响应党和政府号召，发扬不怕累苦、不怕疲劳、不怕牺牲的精神斗志，坚守在防汛抗洪救灾第一线，涌现了许多先进典型和感人事迹，展现了中国人民众志成城、顽强拼搏、敢于胜利的英雄气概，书写了洪水无情人有情的人间大爱。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——习近平总书记2020年8月在安徽考察时强调</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 15:28:34', 17);
INSERT INTO `sys_oper_log` VALUES (1251, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"192\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">广大人民群众对中国女排的喜爱，不仅是因为你们夺得了冠军，更重要的是你们在赛场上展现了祖国至上、团结协作、顽强拼搏、永不言败的精神面貌。女排精神代表着一个时代的精神，喊出了为中华崛起而拼搏的时代最强音。</span></b></p><p>\\r\\n<span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在会见获得2019年女排世界杯冠军的中国女排队员、教练员代表时的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 15:28:59', 25);
INSERT INTO `sys_oper_log` VALUES (1252, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"197\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"<p style=\\\"text-align: left;\\\"><span style=\\\"font-size: 24px;\\\"><b>“爱岗敬业、争创一流，艰苦奋斗、勇于创新，淡泊名利、甘于奉献”的劳模精神，生动诠释了社会主义核心价值观，是我们的宝贵精神财富和强大精神力量。</b></span>\\r\\n</p><p style=\\\"text-align: right;\\\"><span style=\\\"color: inherit; font-size: 18px;\\\">——摘自2015年习近平总书记在庆祝“五一”国际劳动节暨表彰全国劳动模范和先进工作者大会上的讲话</span><br></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 15:29:42', 17);
INSERT INTO `sys_oper_log` VALUES (1253, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"193\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">做好非典的预防、治疗和控制工作，直接关系广大人民群众生命安全和身体健康，直接关系改革发展稳定大局，直接关系国家利益和我国国际形象。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自2020年6月15日人民日报《把人民生命安全和身体健康放在心里——习近平同志2003年领导浙江省抗击非典斗争纪事》</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 15:30:33', 17);
INSERT INTO `sys_oper_log` VALUES (1254, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"195\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"<p><span style=\\\"font-size: 24px;\\\"><b>国铁集团要落实主体责任，有关单位和川藏两省区要加强协调配合，精心组织实施，广大铁路建设者要发扬“两路”精神和青藏铁路精神，科学施工、安全施工、绿色施工，高质量推进工程建设，为全面建设社会主义现代化国家作出新的贡献。</b></span></p><p style=\\\"text-align: right;\\\">\\r\\n<span style=\\\"font-size: 18px;\\\">——摘自习近平总书记2020年对川藏铁路开工建设作出的重要指示</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 15:30:53', 36);
INSERT INTO `sys_oper_log` VALUES (1255, '党史标题管理', 2, 'com.ds.project.front.title.controller.DsTitleController.editSave()', 'POST', 1, 'admin', '研发部门', '/front/title/edit', '223.72.68.45', 'XX XX', '{\"id\":[\"196\"],\"parentId\":[\"109\"],\"parentName\":[\"改革开放和社会主义现代化建设新时期\"],\"briefIntroduction\":[\"<p><b><span style=\\\"font-size: 24px;\\\">我们注重传承优良传统，发扬特别能吃苦、特别能战斗、特别能攻关、特别能奉献的载人航天精神，彰显了坚定的中国特色社会主义道路自信、理论自信、制度自信、文化自信，为坚持和发展中国特色社会主义增添了强大精神力量。</span>\\r\\n</b></p><p style=\\\"text-align: right;\\\"><span style=\\\"font-size: 18px;\\\">——摘自习近平总书记在会见天宫二号和神舟十一号载人飞行任务航天员及参研参试人员代表时的讲话</span></p>\"]}', '{\"msg\":\"操作成功\",\"code\":0}', 0, NULL, '2025-02-23 15:31:13', 18);
